CREATE OR REPLACE FUNCTION "browser_catalog"."bump_instrument_revision_when_sample_paths_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  changed boolean := false;
BEGIN
  IF TG_TABLE_SCHEMA <> 'public' OR TG_TABLE_NAME <> 'sample_s3_path' THEN
    RAISE EXCEPTION
      'Unsupported Instrument sample-path source table: %.%',
      TG_TABLE_SCHEMA,
      TG_TABLE_NAME;
  ELSIF TG_OP = 'TRUNCATE' THEN
    changed := true;
  ELSIF TG_OP = 'INSERT' THEN
    SELECT EXISTS (SELECT 1 FROM new_rows)
    INTO changed;
  ELSIF TG_OP = 'DELETE' THEN
    SELECT EXISTS (SELECT 1 FROM old_rows)
    INTO changed;
  ELSIF TG_OP = 'UPDATE' THEN
    SELECT EXISTS (
      SELECT 1 FROM old_rows
      UNION ALL
      SELECT 1 FROM new_rows
    )
    INTO changed;
  END IF;

  IF changed THEN
    PERFORM browser_catalog.bump_instrument_source_revision();
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "browser_catalog"."bump_instrument_revision_when_sample_paths_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "browser_catalog"."bump_instrument_source_revision"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(2173, 1);

  UPDATE public.catalog_cache_resource_revisions
  SET revision = revision + 1,
      updated_at = pg_catalog.clock_timestamp()
  WHERE resource = 'instruments';

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'Browser-catalog Instrument source revision is unavailable';
  END IF;
END;
$$;


ALTER FUNCTION "browser_catalog"."bump_instrument_source_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "browser_catalog"."bump_instrument_visibility_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  should_bump boolean := false;
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    should_bump := true;
  ELSIF TG_TABLE_NAME = 'sample_path_constructs' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT EXISTS (
        SELECT 1
        FROM new_rows AS current
        INNER JOIN public.instruments_v2 AS instrument
          ON instrument.id = current.instrument_v2_id
        WHERE instrument.published
      )
      INTO should_bump;
    ELSIF TG_OP = 'DELETE' THEN
      SELECT EXISTS (
        SELECT 1
        FROM old_rows AS previous
        INNER JOIN public.instruments_v2 AS instrument
          ON instrument.id = previous.instrument_v2_id
        WHERE instrument.published
      )
      INTO should_bump;
    ELSIF TG_OP = 'UPDATE' THEN
      WITH previous_effect AS (
        SELECT
          previous.instrument_v2_id,
          count(*) AS construct_count,
          count(*) FILTER (
            WHERE previous.filename IS DISTINCT FROM 'pitchless'
          ) AS non_pitchless_count,
          count(*) FILTER (
            WHERE COALESCE(cue.swell_eligible, false)
              OR COALESCE(cue.crash_eligible, false)
          ) AS cue_eligible_count
        FROM old_rows AS previous
        INNER JOIN public.instruments_v2 AS instrument
          ON instrument.id = previous.instrument_v2_id
         AND instrument.published
        LEFT JOIN public.sample_playback_cues AS cue
          ON cue.sample_path_construct_id = previous.id
        GROUP BY previous.instrument_v2_id
      ),
      current_effect AS (
        SELECT
          current.instrument_v2_id,
          count(*) AS construct_count,
          count(*) FILTER (
            WHERE current.filename IS DISTINCT FROM 'pitchless'
          ) AS non_pitchless_count,
          count(*) FILTER (
            WHERE COALESCE(cue.swell_eligible, false)
              OR COALESCE(cue.crash_eligible, false)
          ) AS cue_eligible_count
        FROM new_rows AS current
        INNER JOIN public.instruments_v2 AS instrument
          ON instrument.id = current.instrument_v2_id
         AND instrument.published
        LEFT JOIN public.sample_playback_cues AS cue
          ON cue.sample_path_construct_id = current.id
        GROUP BY current.instrument_v2_id
      ),
      changed_effect AS (
        (
          SELECT * FROM previous_effect
          EXCEPT
          SELECT * FROM current_effect
        )
        UNION ALL
        (
          SELECT * FROM current_effect
          EXCEPT
          SELECT * FROM previous_effect
        )
      )
      SELECT EXISTS (SELECT 1 FROM changed_effect)
      INTO should_bump;
    END IF;
  ELSIF TG_TABLE_NAME = 'sample_playback_cues' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT EXISTS (
        SELECT 1
        FROM new_rows AS current
        INNER JOIN public.sample_path_constructs AS construct
          ON construct.id = current.sample_path_construct_id
        INNER JOIN public.instruments_v2 AS instrument
          ON instrument.id = construct.instrument_v2_id
        WHERE instrument.published
          AND (
            COALESCE(current.swell_eligible, false)
            OR COALESCE(current.crash_eligible, false)
          )
      )
      INTO should_bump;
    ELSIF TG_OP = 'DELETE' THEN
      SELECT EXISTS (
        SELECT 1
        FROM old_rows AS previous
        INNER JOIN public.sample_path_constructs AS construct
          ON construct.id = previous.sample_path_construct_id
        INNER JOIN public.instruments_v2 AS instrument
          ON instrument.id = construct.instrument_v2_id
        WHERE instrument.published
          AND (
            COALESCE(previous.swell_eligible, false)
            OR COALESCE(previous.crash_eligible, false)
          )
      )
      INTO should_bump;
    ELSIF TG_OP = 'UPDATE' THEN
      WITH previous_effect AS (
        SELECT
          construct.instrument_v2_id,
          count(*) AS cue_eligible_count
        FROM old_rows AS previous
        INNER JOIN public.sample_path_constructs AS construct
          ON construct.id = previous.sample_path_construct_id
        INNER JOIN public.instruments_v2 AS instrument
          ON instrument.id = construct.instrument_v2_id
         AND instrument.published
        WHERE COALESCE(previous.swell_eligible, false)
          OR COALESCE(previous.crash_eligible, false)
        GROUP BY construct.instrument_v2_id
      ),
      current_effect AS (
        SELECT
          construct.instrument_v2_id,
          count(*) AS cue_eligible_count
        FROM new_rows AS current
        INNER JOIN public.sample_path_constructs AS construct
          ON construct.id = current.sample_path_construct_id
        INNER JOIN public.instruments_v2 AS instrument
          ON instrument.id = construct.instrument_v2_id
         AND instrument.published
        WHERE COALESCE(current.swell_eligible, false)
          OR COALESCE(current.crash_eligible, false)
        GROUP BY construct.instrument_v2_id
      ),
      changed_effect AS (
        (
          SELECT * FROM previous_effect
          EXCEPT
          SELECT * FROM current_effect
        )
        UNION ALL
        (
          SELECT * FROM current_effect
          EXCEPT
          SELECT * FROM previous_effect
        )
      )
      SELECT EXISTS (SELECT 1 FROM changed_effect)
      INTO should_bump;
    END IF;
  ELSE
    RAISE EXCEPTION
      'Unsupported Instrument visibility source table: %',
      TG_TABLE_NAME;
  END IF;

  IF should_bump THEN
    PERFORM browser_catalog.bump_instrument_source_revision();
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "browser_catalog"."bump_instrument_visibility_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "browser_catalog"."cleanup_instrument_discovery_expired"("p_now" timestamp with time zone, "p_limit" integer DEFAULT 16) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  IF p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'Instrument Discovery cleanup limit is invalid';
  END IF;

  WITH expired AS (
    SELECT candidate.resource_key, candidate.generation
    FROM browser_catalog.instrument_discovery_resource_generations AS candidate
    LEFT JOIN browser_catalog.instrument_discovery_state AS state
      ON state.singleton
     AND (
       (candidate.resource_key = 'instruments'
         AND candidate.generation = state.instrument_generation)
       OR (candidate.resource_key = 'tags'
         AND candidate.generation = state.tag_generation)
       OR (candidate.resource_key = 'cues'
         AND candidate.generation = state.cue_generation)
       OR (candidate.resource_key = 'characteristics'
         AND candidate.generation = state.characteristic_generation)
     )
    WHERE candidate.retained_until <= p_now
      AND state.singleton IS NULL
    ORDER BY candidate.retained_until,
      candidate.resource_key,
      candidate.generation
    LIMIT p_limit
  )
  DELETE FROM browser_catalog.instrument_discovery_resource_pages AS page
  USING expired
  WHERE page.resource_key = expired.resource_key
    AND page.generation = expired.generation;

  WITH expired AS (
    SELECT candidate.resource_key, candidate.generation
    FROM browser_catalog.instrument_discovery_resource_generations AS candidate
    WHERE candidate.retained_until <= p_now
      AND NOT EXISTS (
        SELECT 1
        FROM browser_catalog.instrument_discovery_state AS state
        WHERE state.singleton
          AND candidate.generation = CASE candidate.resource_key
            WHEN 'instruments' THEN state.instrument_generation
            WHEN 'tags' THEN state.tag_generation
            WHEN 'cues' THEN state.cue_generation
            WHEN 'characteristics' THEN state.characteristic_generation
          END
      )
    ORDER BY candidate.retained_until,
      candidate.resource_key,
      candidate.generation
    LIMIT p_limit
  )
  DELETE FROM browser_catalog.instrument_discovery_instrument_rows AS row
  USING expired
  WHERE expired.resource_key = 'instruments'
    AND row.generation = expired.generation;

  WITH expired AS (
    SELECT candidate.resource_key, candidate.generation
    FROM browser_catalog.instrument_discovery_resource_generations AS candidate
    WHERE candidate.retained_until <= p_now
      AND NOT EXISTS (
        SELECT 1
        FROM browser_catalog.instrument_discovery_state AS state
        WHERE state.singleton
          AND candidate.generation = CASE candidate.resource_key
            WHEN 'instruments' THEN state.instrument_generation
            WHEN 'tags' THEN state.tag_generation
            WHEN 'cues' THEN state.cue_generation
            WHEN 'characteristics' THEN state.characteristic_generation
          END
      )
    ORDER BY candidate.retained_until,
      candidate.resource_key,
      candidate.generation
    LIMIT p_limit
  )
  DELETE FROM browser_catalog.instrument_discovery_tag_rows AS row
  USING expired
  WHERE expired.resource_key = 'tags'
    AND row.generation = expired.generation;

  WITH expired AS (
    SELECT candidate.resource_key, candidate.generation
    FROM browser_catalog.instrument_discovery_resource_generations AS candidate
    WHERE candidate.retained_until <= p_now
      AND NOT EXISTS (
        SELECT 1
        FROM browser_catalog.instrument_discovery_state AS state
        WHERE state.singleton
          AND candidate.generation = CASE candidate.resource_key
            WHEN 'instruments' THEN state.instrument_generation
            WHEN 'tags' THEN state.tag_generation
            WHEN 'cues' THEN state.cue_generation
            WHEN 'characteristics' THEN state.characteristic_generation
          END
      )
    ORDER BY candidate.retained_until,
      candidate.resource_key,
      candidate.generation
    LIMIT p_limit
  )
  DELETE FROM browser_catalog.instrument_discovery_cue_rows AS row
  USING expired
  WHERE expired.resource_key = 'cues'
    AND row.generation = expired.generation;

  WITH expired AS (
    SELECT candidate.resource_key, candidate.generation
    FROM browser_catalog.instrument_discovery_resource_generations AS candidate
    WHERE candidate.retained_until <= p_now
      AND NOT EXISTS (
        SELECT 1
        FROM browser_catalog.instrument_discovery_state AS state
        WHERE state.singleton
          AND candidate.generation = CASE candidate.resource_key
            WHEN 'instruments' THEN state.instrument_generation
            WHEN 'tags' THEN state.tag_generation
            WHEN 'cues' THEN state.cue_generation
            WHEN 'characteristics' THEN state.characteristic_generation
          END
      )
    ORDER BY candidate.retained_until,
      candidate.resource_key,
      candidate.generation
    LIMIT p_limit
  )
  DELETE FROM browser_catalog.instrument_discovery_characteristic_rows AS row
  USING expired
  WHERE expired.resource_key = 'characteristics'
    AND row.generation = expired.generation;

  WITH expired AS (
    SELECT candidate.resource_key, candidate.generation
    FROM browser_catalog.instrument_discovery_resource_generations AS candidate
    WHERE candidate.retained_until <= p_now
      AND NOT EXISTS (
        SELECT 1
        FROM browser_catalog.instrument_discovery_state AS state
        WHERE state.singleton
          AND candidate.generation = CASE candidate.resource_key
            WHEN 'instruments' THEN state.instrument_generation
            WHEN 'tags' THEN state.tag_generation
            WHEN 'cues' THEN state.cue_generation
            WHEN 'characteristics' THEN state.characteristic_generation
          END
      )
    ORDER BY candidate.retained_until,
      candidate.resource_key,
      candidate.generation
    LIMIT p_limit
  )
  DELETE FROM browser_catalog.instrument_discovery_resource_generations AS generation
  USING expired
  WHERE generation.resource_key = expired.resource_key
    AND generation.generation = expired.generation;
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "browser_catalog"."cleanup_instrument_discovery_expired"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "browser_catalog"."cleanup_instrument_discovery_expired"("p_now" timestamp with time zone, "p_limit" integer) IS 'Private bounded cleanup shared by core and Characteristic staging/promotion paths.';



CREATE OR REPLACE FUNCTION "browser_catalog"."instrument_discovery_normalize_name"("value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT PARALLEL SAFE
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT pg_catalog.btrim(
    pg_catalog.regexp_replace(
      pg_catalog.lower(
        normalize(value, NFKC) COLLATE "en-US-x-icu"
      ),
      U&'[\0009-\000D\0020\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]+',
      ' ',
      'g'
    )
  );
$$;


ALTER FUNCTION "browser_catalog"."instrument_discovery_normalize_name"("value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "browser_catalog"."instrument_discovery_normalize_name"("value" "text") IS 'Private NFKC, en-US lowercase, ECMAScript-whitespace normalizer matching the shared Instrument Discovery model.';



CREATE OR REPLACE FUNCTION "browser_catalog"."is_valid_song_v2"("value" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  SELECT CASE
    WHEN jsonb_typeof(value) = 'object'
      AND jsonb_typeof(value -> 'name') = 'string'
      AND jsonb_typeof(value -> 'phraseSequence') = 'array'
      AND jsonb_typeof(value -> 'stems') = 'array'
      AND jsonb_typeof(value -> 'sections') = 'array'
      AND jsonb_typeof(value -> 'phraseTimeMarkers') = 'array'
      AND jsonb_typeof(value -> 'masterBus') = 'object'
      AND jsonb_typeof(value -> 'buses') = 'object'
      AND jsonb_typeof(value #> '{buses,drums}') = 'object'
      AND jsonb_typeof(value #> '{buses,swells}') = 'object'
      AND jsonb_typeof(value #> '{buses,loops}') = 'object'
    THEN NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(value -> 'phraseSequence') AS phrase(item)
      WHERE jsonb_typeof(phrase.item) IS DISTINCT FROM 'object'
        OR jsonb_typeof(phrase.item -> 'section')
          IS DISTINCT FROM 'object'
        OR jsonb_typeof(phrase.item -> 'composition')
          IS DISTINCT FROM 'object'
        OR jsonb_typeof(phrase.item -> 'buses')
          IS DISTINCT FROM 'object'
        OR jsonb_typeof(phrase.item #> '{buses,drums}')
          IS DISTINCT FROM 'object'
        OR jsonb_typeof(phrase.item #> '{buses,swells}')
          IS DISTINCT FROM 'object'
        OR jsonb_typeof(phrase.item #> '{buses,loops}')
          IS DISTINCT FROM 'object'
    )
    ELSE false
  END;
$$;


ALTER FUNCTION "browser_catalog"."is_valid_song_v2"("value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "browser_catalog"."preserve_instrument_v2_projection_fidelity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  source_fidelity jsonb;
BEGIN
  -- Song-only generations insert the prior immutable Instrument payload. Once
  -- fidelity fields exist, preserve that payload exactly instead of consulting
  -- independently changing source tables during an unchanged-resource clone.
  IF NEW.instrument ? 'sampled_midi_notes'
    AND NEW.instrument ? 'visibility_role'
  THEN
    NEW.instrument :=
      NEW.instrument
      - 'sample_path_constructs'
      - 'sample_playback_cues';
    RETURN NEW;
  END IF;

  SELECT jsonb_build_object(
    'sampled_midi_notes', source.sampled_midi_notes,
    'visibility_role', source.visibility_role,
    'file_name_references', source.file_name_references,
    'articulations', source.articulations,
    'effects_instruments', source.effects_instruments,
    'original_sample_ids', source.original_sample_ids
  )
  INTO source_fidelity
  FROM public.producer_instrument_catalog_v1 AS source
  WHERE source.id = NEW.resource_id;

  IF source_fidelity IS NULL THEN
    RAISE EXCEPTION
      'Published InstrumentV2 source % is unavailable for projection',
      NEW.resource_id;
  END IF;

  NEW.instrument :=
    (
      NEW.instrument
      - 'sample_path_constructs'
      - 'sample_playback_cues'
    )
    || source_fidelity;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "browser_catalog"."preserve_instrument_v2_projection_fidelity"() OWNER TO "postgres";


COMMENT ON FUNCTION "browser_catalog"."preserve_instrument_v2_projection_fidelity"() IS 'Copies exact InstrumentV2 sampled notes, visibility, and nullable arrays into each immutable projection row without copying constructs or cues.';



CREATE OR REPLACE FUNCTION "browser_catalog"."refresh_instrument_discovery_projection"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
<<projection>>
DECLARE
  current_source_revision bigint;
  prior_source_revision bigint;
  prior_instrument_generation uuid;
  prior_tag_generation uuid;
  prior_cue_generation uuid;
  prior_characteristic_generation uuid;
  prior_manifest_revision text;
  prior_generated_at timestamptz;
  instrument_generation uuid := extensions.gen_random_uuid();
  tag_generation uuid := extensions.gen_random_uuid();
  cue_generation uuid := extensions.gen_random_uuid();
  characteristic_generation uuid;
  generated_at timestamptz := pg_catalog.clock_timestamp();
  instrument_source_revision text;
  tag_source_revision text;
  cue_source_revision text;
  characteristic_source_revision text;
  characteristic_adoption_revision text;
  gc_generation_limit constant integer := 16;
  empty_checksum constant text := pg_catalog.encode(
    extensions.digest(''::text, 'sha256'),
    'hex'
  );
  instrument_count integer;
  tag_count integer;
  cue_count integer;
  instrument_page_count integer;
  tag_page_count integer;
  cue_page_count integer;
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(2173, 1);
  characteristic_source_revision := 'sha256:' || empty_checksum;
  characteristic_adoption_revision := 'sha256:' || empty_checksum;

  SELECT revision
  INTO current_source_revision
  FROM public.catalog_cache_resource_revisions
  WHERE resource = 'instruments'
  FOR UPDATE;

  IF current_source_revision IS NULL THEN
    RAISE EXCEPTION 'Instrument Discovery source revision is unavailable';
  END IF;

  SELECT state.source_revision,
    state.instrument_generation,
    state.tag_generation,
    state.cue_generation,
    state.characteristic_generation,
    state.manifest_revision,
    state.generated_at
  INTO prior_source_revision,
    prior_instrument_generation,
    prior_tag_generation,
    prior_cue_generation,
    prior_characteristic_generation,
    prior_manifest_revision,
    prior_generated_at
  FROM browser_catalog.instrument_discovery_state AS state
  WHERE state.singleton
  FOR UPDATE;

  PERFORM browser_catalog.cleanup_instrument_discovery_expired(
    projection.generated_at,
    gc_generation_limit
  );

  IF prior_source_revision = current_source_revision
    AND prior_characteristic_generation IS NOT NULL
  THEN
    RETURN jsonb_build_object(
      'publicationStatus', 'current',
      'sourceRevision', current_source_revision,
      'instrumentGeneration', prior_instrument_generation,
      'tagGeneration', prior_tag_generation,
      'cueGeneration', prior_cue_generation,
      'characteristicGeneration', prior_characteristic_generation,
      'expectedInstrumentGeneration', prior_instrument_generation,
      'expectedTagGeneration', prior_tag_generation,
      'expectedCueGeneration', prior_cue_generation,
      'expectedCharacteristicGeneration', prior_characteristic_generation,
      'manifestRevision', prior_manifest_revision,
      'generatedAt', prior_generated_at
    );
  END IF;

  instrument_source_revision :=
    'catalog-instruments:' || current_source_revision::text;
  tag_source_revision := 'catalog-tags:' || current_source_revision::text;
  cue_source_revision := 'catalog-cues:' || current_source_revision::text;
  characteristic_generation := COALESCE(
    prior_characteristic_generation,
    extensions.gen_random_uuid()
  );

  SELECT instruments.generation, tags.generation, cues.generation
  INTO instrument_generation, tag_generation, cue_generation
  FROM browser_catalog.instrument_discovery_resource_generations AS instruments
  INNER JOIN browser_catalog.instrument_discovery_resource_generations AS tags
    ON tags.publication_status = 'staging'
   AND tags.generated_at = instruments.generated_at
   AND tags.resource_key = 'tags'
   AND tags.source_revision = tag_source_revision
   AND tags.instrument_revision = instrument_source_revision
  INNER JOIN browser_catalog.instrument_discovery_resource_generations AS cues
    ON cues.publication_status = 'staging'
   AND cues.generated_at = instruments.generated_at
   AND cues.resource_key = 'cues'
   AND cues.source_revision = cue_source_revision
   AND cues.instrument_revision = instrument_source_revision
  WHERE instruments.publication_status = 'staging'
    AND instruments.resource_key = 'instruments'
    AND instruments.source_revision = instrument_source_revision
    AND instruments.retained_until > projection.generated_at
  ORDER BY instruments.generated_at DESC
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'publicationStatus', 'staging',
      'sourceRevision', current_source_revision,
      'instrumentGeneration', instrument_generation,
      'tagGeneration', tag_generation,
      'cueGeneration', cue_generation,
      'characteristicGeneration', characteristic_generation,
      'expectedInstrumentGeneration', prior_instrument_generation,
      'expectedTagGeneration', prior_tag_generation,
      'expectedCueGeneration', prior_cue_generation,
      'expectedCharacteristicGeneration', prior_characteristic_generation,
      'resources', jsonb_build_array(
        jsonb_build_object(
          'resource', 'instruments',
          'generation', instrument_generation,
          'pageCount', (
            SELECT page_count
            FROM browser_catalog.instrument_discovery_resource_generations
            WHERE resource_key = 'instruments'
              AND generation = instrument_generation
          )
        ),
        jsonb_build_object(
          'resource', 'tags',
          'generation', tag_generation,
          'pageCount', (
            SELECT page_count
            FROM browser_catalog.instrument_discovery_resource_generations
            WHERE resource_key = 'tags'
              AND generation = tag_generation
          )
        ),
        jsonb_build_object(
          'resource', 'cues',
          'generation', cue_generation,
          'pageCount', (
            SELECT page_count
            FROM browser_catalog.instrument_discovery_resource_generations
            WHERE resource_key = 'cues'
              AND generation = cue_generation
          )
        )
      )
    );
  END IF;

  instrument_generation := extensions.gen_random_uuid();
  tag_generation := extensions.gen_random_uuid();
  cue_generation := extensions.gen_random_uuid();

  IF EXISTS (
    SELECT 1
    FROM public.producer_instrument_catalog_v1 AS instrument
    LEFT JOIN public.contributors AS contributor
      ON contributor.id = instrument.contributor_id
    WHERE instrument.visibility_role <> 'hidden'
      AND (
        NULLIF(pg_catalog.btrim(instrument.name), '') IS NULL
        OR instrument.name IS DISTINCT FROM pg_catalog.btrim(instrument.name)
        OR NULLIF(pg_catalog.btrim(instrument.instrument_family), '') IS NULL
        OR instrument.instrument_family IS DISTINCT FROM
          pg_catalog.btrim(instrument.instrument_family)
        OR contributor.id IS NULL
        OR NULLIF(pg_catalog.btrim(contributor.slug), '') IS NULL
        OR contributor.slug IS DISTINCT FROM pg_catalog.btrim(contributor.slug)
        OR instrument.range_lower NOT BETWEEN 0 AND 127
        OR instrument.range_upper NOT BETWEEN 0 AND 127
        OR instrument.range_lower > instrument.range_upper
        OR (
          instrument.single_pitch IS NOT NULL
          AND instrument.single_pitch NOT BETWEEN 0 AND 127
        )
        OR instrument.visibility_role NOT IN (
          'normal',
          'cue_only',
          'normal_and_cue',
          'drum',
          'drum_and_cue'
        )
      )
  ) THEN
    RAISE EXCEPTION
      'Instrument Discovery source contains an invalid canonical Instrument';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.instrument_v2_instrument_tags AS link
    INNER JOIN public.producer_instrument_catalog_v1 AS instrument
      ON instrument.id = link.instrument_v2_id
     AND instrument.visibility_role <> 'hidden'
    INNER JOIN public.instrument_tags AS tag ON tag.id = link.tag_id
    CROSS JOIN LATERAL (
      SELECT
        public.sip_normalize_instrument_tag_group(tag.tag_group)
          AS tag_group,
        public.sip_normalize_instrument_tag_name(
          public.sip_normalize_instrument_tag_group(tag.tag_group),
          tag.tag_name
        ) AS tag_name
    ) AS normalized
    CROSS JOIN LATERAL (
      SELECT public.sip_normalize_instrument_tag_name_key(
        normalized.tag_name
      ) AS tag_name_key
    ) AS keyed
    WHERE normalized.tag_group NOT IN ('harmType', 'sampleType')
      AND keyed.tag_name_key NOT IN (
        'legacy',
        'potentiallysustainedsampletype'
      )
      AND (
        NULLIF(pg_catalog.btrim(normalized.tag_group), '') IS NULL
        OR NULLIF(pg_catalog.btrim(normalized.tag_name), '') IS NULL
        OR NULLIF(pg_catalog.btrim(keyed.tag_name_key), '') IS NULL
      )
  ) THEN
    RAISE EXCEPTION
      'Instrument Discovery source contains an invalid linked Tag';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.instrument_v2_legacy_map AS map
    INNER JOIN public.producer_instrument_catalog_v1 AS instrument
      ON instrument.id = map.instrument_v2_id
     AND instrument.visibility_role <> 'hidden'
    WHERE map.legacy_lookup_key IS DISTINCT FROM
        pg_catalog.btrim(map.legacy_lookup_key)
      OR (
        NULLIF(pg_catalog.btrim(map.legacy_file_path_reference), '') IS NOT NULL
        AND map.legacy_file_path_reference IS DISTINCT FROM
          pg_catalog.btrim(map.legacy_file_path_reference)
      )
  ) THEN
    RAISE EXCEPTION
      'Instrument Discovery source contains an invalid compatibility alias';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.sample_playback_cues AS cue
    INNER JOIN public.sample_path_constructs AS construct
      ON construct.id = cue.sample_path_construct_id
    INNER JOIN public.producer_instrument_catalog_v1 AS instrument
      ON instrument.id = construct.instrument_v2_id
     AND instrument.visibility_role <> 'hidden'
    WHERE (
        COALESCE(cue.swell_eligible, false)
        OR COALESCE(cue.crash_eligible, false)
      )
      AND (
        NULLIF(pg_catalog.btrim(construct.filename), '') IS NULL
        OR construct.filename IS DISTINCT FROM
          pg_catalog.btrim(construct.filename)
      )
  ) THEN
    RAISE EXCEPTION
      'Instrument Discovery source contains an invalid Cue filename';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.sample_playback_cues AS cue
    INNER JOIN public.sample_path_constructs AS construct
      ON construct.id = cue.sample_path_construct_id
    INNER JOIN public.producer_instrument_catalog_v1 AS instrument
      ON instrument.id = construct.instrument_v2_id
     AND instrument.visibility_role <> 'hidden'
    INNER JOIN public.analysis_librosa AS analysis
      ON analysis.sample_id = construct.sample_original_path_id
    WHERE (
        COALESCE(cue.swell_eligible, false)
        OR COALESCE(cue.crash_eligible, false)
      )
      AND analysis.duration IS NOT NULL
      AND NOT (
        analysis.duration BETWEEN 0 AND 9007199254740991::double precision
      )
  ) THEN
    RAISE EXCEPTION
      'Instrument Discovery source contains an invalid Cue duration';
  END IF;

  INSERT INTO browser_catalog.instrument_discovery_instrument_rows (
    generation,
    instrument_id,
    item
  )
  SELECT
    instrument_generation,
    instrument.id,
    jsonb_build_object(
      'id', instrument.id,
      'name', instrument.name,
      'normalizedName',
        browser_catalog.instrument_discovery_normalize_name(instrument.name),
      'family', instrument.instrument_family,
      'instrumentType', instrument.instrument_type,
      'providerId', instrument.contributor_id,
      'providerName', contributor.slug,
      'collection', instrument.collection,
      'engineType', CASE
        WHEN instrument.engine_type::text = 'tonal' THEN 'tonal'
        ELSE 'non_tonal'
      END,
      'assetRole', instrument.asset_role,
      'playbackType', instrument.playback_type,
      'polyphonyType', instrument.polyphony_type,
      'visibilityRole', instrument.visibility_role,
      'range', jsonb_build_array(
        instrument.range_lower,
        instrument.range_upper
      ),
      'singlePitch', instrument.single_pitch,
      'sampledMidiNotes', pg_catalog.to_jsonb(instrument.sampled_midi_notes),
      'aliases', COALESCE(aliases.items, '[]'::jsonb)
    )
  FROM public.producer_instrument_catalog_v1 AS instrument
  INNER JOIN public.contributors AS contributor
    ON contributor.id = instrument.contributor_id
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(
      jsonb_build_object('kind', values.kind, 'value', values.value)
      ORDER BY values.kind, values.value
    ) AS items
    FROM (
      SELECT DISTINCT 'legacy_instrument_id'::text AS kind,
        map.legacy_instrument_id::text AS value
      FROM public.instrument_v2_legacy_map AS map
      WHERE map.instrument_v2_id = instrument.id
        AND map.legacy_instrument_id IS NOT NULL
      UNION
      SELECT DISTINCT 'legacy_lookup_key', map.legacy_lookup_key
      FROM public.instrument_v2_legacy_map AS map
      WHERE map.instrument_v2_id = instrument.id
        AND NULLIF(pg_catalog.btrim(map.legacy_lookup_key), '') IS NOT NULL
      UNION
      SELECT DISTINCT
        'legacy_file_path_reference',
        map.legacy_file_path_reference
      FROM public.instrument_v2_legacy_map AS map
      WHERE map.instrument_v2_id = instrument.id
        AND NULLIF(
          pg_catalog.btrim(map.legacy_file_path_reference),
          ''
        ) IS NOT NULL
    ) AS values
  ) AS aliases ON true
  WHERE instrument.visibility_role <> 'hidden'
  ORDER BY instrument.id;

  WITH normalized_tags AS (
    SELECT
      tag.id,
      public.sip_normalize_instrument_tag_group(tag.tag_group) AS tag_group,
      public.sip_normalize_instrument_tag_name(
        public.sip_normalize_instrument_tag_group(tag.tag_group),
        tag.tag_name
      ) AS tag_name
    FROM public.instrument_tags AS tag
  ), public_tags AS (
    SELECT
      normalized.id,
      normalized.tag_group,
      normalized.tag_name,
      public.sip_normalize_instrument_tag_name_key(normalized.tag_name)
        AS tag_name_key
    FROM normalized_tags AS normalized
    WHERE normalized.tag_group NOT IN ('harmType', 'sampleType')
      AND public.sip_normalize_instrument_tag_name_key(normalized.tag_name)
        NOT IN ('legacy', 'potentiallysustainedsampletype')
      AND NULLIF(pg_catalog.btrim(normalized.tag_group), '') IS NOT NULL
      AND NULLIF(pg_catalog.btrim(normalized.tag_name), '') IS NOT NULL
      AND NULLIF(
        pg_catalog.btrim(
          public.sip_normalize_instrument_tag_name_key(normalized.tag_name)
        ),
        ''
      ) IS NOT NULL
  )
  INSERT INTO browser_catalog.instrument_discovery_tag_rows (
    generation,
    sort_key,
    item
  )
  SELECT
    tag_generation,
    '0:' || tag.id::text,
    jsonb_build_object(
      'kind', 'tag',
      'id', tag.id,
      'group', tag.tag_group,
      'name', tag.tag_name,
      'normalizedName',
        browser_catalog.instrument_discovery_normalize_name(tag.tag_name)
    )
  FROM public_tags AS tag
  WHERE EXISTS (
    SELECT 1
    FROM public.instrument_v2_instrument_tags AS link
    INNER JOIN public.producer_instrument_catalog_v1 AS instrument
      ON instrument.id = link.instrument_v2_id
     AND instrument.visibility_role <> 'hidden'
    WHERE link.tag_id = tag.id
  )

  UNION ALL

  SELECT
    tag_generation,
    '1:' || link.instrument_v2_id::text || ':' || link.tag_id::text,
    jsonb_build_object(
      'kind', 'instrument_tag',
      'instrumentId', link.instrument_v2_id,
      'tagId', link.tag_id
    )
  FROM public.instrument_v2_instrument_tags AS link
  INNER JOIN public.producer_instrument_catalog_v1 AS instrument
    ON instrument.id = link.instrument_v2_id
   AND instrument.visibility_role <> 'hidden'
  INNER JOIN public_tags AS tag ON tag.id = link.tag_id;

  INSERT INTO browser_catalog.instrument_discovery_cue_rows (
    generation,
    instrument_id,
    construct_id,
    item
  )
  SELECT
    cue_generation,
    instrument.id,
    construct.id,
    jsonb_build_object(
      'instrumentId', instrument.id,
      'constructId', construct.id,
      'sampleOriginalPathId', construct.sample_original_path_id,
      'filename', construct.filename,
      'midiNote', CASE
        WHEN construct.midi_note ~ '^[0-9]+$'
          AND construct.midi_note::integer BETWEEN 0 AND 127
        THEN construct.midi_note::integer
        ELSE NULL
      END,
      'syncPointMs', CASE
        WHEN cue.sync_point_ms >= 0 THEN cue.sync_point_ms
        ELSE NULL
      END,
      'durationSeconds', CASE
        WHEN analysis.duration >= 0 THEN analysis.duration
        ELSE NULL
      END,
      'swellEligible', COALESCE(cue.swell_eligible, false),
      'crashEligible', COALESCE(cue.crash_eligible, false)
    )
  FROM public.sample_playback_cues AS cue
  INNER JOIN public.sample_path_constructs AS construct
    ON construct.id = cue.sample_path_construct_id
  INNER JOIN public.producer_instrument_catalog_v1 AS instrument
    ON instrument.id = construct.instrument_v2_id
   AND instrument.visibility_role <> 'hidden'
  LEFT JOIN public.analysis_librosa AS analysis
    ON analysis.sample_id = construct.sample_original_path_id
  WHERE COALESCE(cue.swell_eligible, false)
     OR COALESCE(cue.crash_eligible, false)
  ORDER BY instrument.id, construct.id;

  -- Bootstrap a valid empty Characteristic resource once. The independent
  -- canonical-current publisher replaces it atomically and later Instrument
  -- refreshes preserve that immutable generation.
  IF prior_characteristic_generation IS NULL THEN
    INSERT INTO browser_catalog.instrument_discovery_resource_generations (
      resource_key,
      generation,
      source_revision,
      instrument_revision,
      registry_version,
      adoption_revision,
      adopted,
      publication_status,
      etag,
      checksum,
      row_count,
      page_count,
      generated_at,
      retained_until
    ) VALUES (
      'characteristics',
      characteristic_generation,
      characteristic_source_revision,
      instrument_source_revision,
      'perceptual-characteristic-registry-v1',
      characteristic_adoption_revision,
      '[]'::jsonb,
      'sealed',
      '"sha256-' || empty_checksum || '"',
      empty_checksum,
      0,
      0,
      generated_at,
      generated_at + interval '24 hours'
    );
  END IF;

  WITH numbered AS (
    SELECT
      item,
      ((row_number() OVER (ORDER BY instrument_id) - 1) / 250)::integer
        AS page_index,
      instrument_id
    FROM browser_catalog.instrument_discovery_instrument_rows
    WHERE generation = instrument_generation
  ), grouped AS (
    SELECT
      page_index,
      jsonb_agg(item ORDER BY instrument_id) AS items
    FROM numbered
    GROUP BY page_index
  )
  INSERT INTO browser_catalog.instrument_discovery_resource_pages (
    resource_key,
    generation,
    page_index,
    row_count,
    items
  )
  SELECT
    'instruments',
    instrument_generation,
    page_index,
    jsonb_array_length(items),
    items
  FROM grouped;

  WITH numbered AS (
    SELECT
      item,
      ((row_number() OVER (ORDER BY sort_key) - 1) / 500)::integer
        AS page_index,
      sort_key
    FROM browser_catalog.instrument_discovery_tag_rows
    WHERE generation = tag_generation
  ), grouped AS (
    SELECT page_index, jsonb_agg(item ORDER BY sort_key) AS items
    FROM numbered
    GROUP BY page_index
  )
  INSERT INTO browser_catalog.instrument_discovery_resource_pages (
    resource_key,
    generation,
    page_index,
    row_count,
    items
  )
  SELECT
    'tags',
    tag_generation,
    page_index,
    jsonb_array_length(items),
    items
  FROM grouped;

  WITH numbered AS (
    SELECT
      item,
      ((row_number() OVER (ORDER BY instrument_id, construct_id) - 1) / 500)::integer
        AS page_index,
      instrument_id,
      construct_id
    FROM browser_catalog.instrument_discovery_cue_rows
    WHERE generation = cue_generation
  ), grouped AS (
    SELECT
      page_index,
      jsonb_agg(item ORDER BY instrument_id, construct_id) AS items
    FROM numbered
    GROUP BY page_index
  )
  INSERT INTO browser_catalog.instrument_discovery_resource_pages (
    resource_key,
    generation,
    page_index,
    row_count,
    items
  )
  SELECT
    'cues',
    cue_generation,
    page_index,
    jsonb_array_length(items),
    items
  FROM grouped;

  SELECT
    COALESCE(sum(row_count), 0)::integer,
    count(*)::integer
  INTO instrument_count, instrument_page_count
  FROM browser_catalog.instrument_discovery_resource_pages
  WHERE resource_key = 'instruments'
    AND generation = instrument_generation;

  SELECT
    COALESCE(sum(row_count), 0)::integer,
    count(*)::integer
  INTO tag_count, tag_page_count
  FROM browser_catalog.instrument_discovery_resource_pages
  WHERE resource_key = 'tags' AND generation = tag_generation;

  SELECT
    COALESCE(sum(row_count), 0)::integer,
    count(*)::integer
  INTO cue_count, cue_page_count
  FROM browser_catalog.instrument_discovery_resource_pages
  WHERE resource_key = 'cues' AND generation = cue_generation;

  IF instrument_count <> (
    SELECT count(*)::integer
    FROM public.producer_instrument_catalog_v1
    WHERE visibility_role <> 'hidden'
  ) THEN
    RAISE EXCEPTION 'Instrument Discovery Instrument projection parity failed';
  END IF;

  IF cue_count <> (
    SELECT count(*)::integer
    FROM public.sample_playback_cues AS cue
    INNER JOIN public.sample_path_constructs AS construct
      ON construct.id = cue.sample_path_construct_id
    INNER JOIN public.producer_instrument_catalog_v1 AS instrument
      ON instrument.id = construct.instrument_v2_id
     AND instrument.visibility_role <> 'hidden'
    WHERE COALESCE(cue.swell_eligible, false)
       OR COALESCE(cue.crash_eligible, false)
  ) THEN
    RAISE EXCEPTION 'Instrument Discovery Cue projection parity failed';
  END IF;

  INSERT INTO browser_catalog.instrument_discovery_resource_generations (
    resource_key,
    generation,
    source_revision,
    instrument_revision,
    row_count,
    page_count,
    generated_at,
    retained_until
  ) VALUES
    (
      'instruments', instrument_generation, instrument_source_revision, NULL,
      instrument_count, instrument_page_count, generated_at,
      generated_at + interval '24 hours'
    ),
    (
      'tags', tag_generation, tag_source_revision, instrument_source_revision,
      tag_count, tag_page_count, generated_at,
      generated_at + interval '24 hours'
    ),
    (
      'cues', cue_generation, cue_source_revision, instrument_source_revision,
      cue_count, cue_page_count, generated_at,
      generated_at + interval '24 hours'
    );

  RETURN jsonb_build_object(
    'publicationStatus', 'staging',
    'sourceRevision', current_source_revision,
    'instrumentGeneration', instrument_generation,
    'tagGeneration', tag_generation,
    'cueGeneration', cue_generation,
    'characteristicGeneration', characteristic_generation,
    'expectedInstrumentGeneration', prior_instrument_generation,
    'expectedTagGeneration', prior_tag_generation,
    'expectedCueGeneration', prior_cue_generation,
    'expectedCharacteristicGeneration', prior_characteristic_generation,
    'resources', jsonb_build_array(
      jsonb_build_object(
        'resource', 'instruments',
        'generation', instrument_generation,
        'pageCount', instrument_page_count
      ),
      jsonb_build_object(
        'resource', 'tags',
        'generation', tag_generation,
        'pageCount', tag_page_count
      ),
      jsonb_build_object(
        'resource', 'cues',
        'generation', cue_generation,
        'pageCount', cue_page_count
      )
    )
  );
END;
$_$;


ALTER FUNCTION "browser_catalog"."refresh_instrument_discovery_projection"() OWNER TO "postgres";


COMMENT ON FUNCTION "browser_catalog"."refresh_instrument_discovery_projection"() IS 'Stages compact canonical Instrument, Tag, and every eligible Cue page for service-only shared-contract hashing without changing the active manifest.';


SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "browser_catalog"."catalog_state" (
    "singleton" boolean DEFAULT true NOT NULL,
    "schema_version" integer DEFAULT 1 NOT NULL,
    "active_generation" "uuid",
    "retained_prior_generation" "uuid",
    "retained_prior_generated_at" timestamp with time zone,
    "retained_prior_until" timestamp with time zone,
    "retention_window" interval DEFAULT '24:00:00'::interval NOT NULL,
    "songs_source_revision" bigint DEFAULT 0 NOT NULL,
    "instruments_source_revision" bigint DEFAULT 0 NOT NULL,
    "songs_count" integer DEFAULT 0 NOT NULL,
    "instruments_count" integer DEFAULT 0 NOT NULL,
    "songs_checksum" "text" DEFAULT "repeat"('0'::"text", 64) NOT NULL,
    "instruments_checksum" "text" DEFAULT "repeat"('0'::"text", 64) NOT NULL,
    "generated_at" timestamp with time zone,
    CONSTRAINT "catalog_state_check" CHECK (((("retained_prior_generation" IS NULL) AND ("retained_prior_generated_at" IS NULL) AND ("retained_prior_until" IS NULL)) OR (("retained_prior_generation" IS DISTINCT FROM "active_generation") AND ("retained_prior_generated_at" IS NOT NULL) AND ("retained_prior_until" IS NOT NULL) AND ("retained_prior_until" > "retained_prior_generated_at")))),
    CONSTRAINT "catalog_state_check1" CHECK (((("active_generation" IS NULL) AND ("generated_at" IS NULL)) OR (("active_generation" IS NOT NULL) AND ("generated_at" IS NOT NULL)))),
    CONSTRAINT "catalog_state_instruments_checksum_check" CHECK (("instruments_checksum" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "catalog_state_instruments_count_check" CHECK (("instruments_count" >= 0)),
    CONSTRAINT "catalog_state_instruments_source_revision_check" CHECK (("instruments_source_revision" >= 0)),
    CONSTRAINT "catalog_state_retention_window_check" CHECK ((("retention_window" >= '01:00:00'::interval) AND ("retention_window" <= '7 days'::interval))),
    CONSTRAINT "catalog_state_schema_version_check" CHECK (("schema_version" = 1)),
    CONSTRAINT "catalog_state_singleton_check" CHECK ("singleton"),
    CONSTRAINT "catalog_state_songs_checksum_check" CHECK (("songs_checksum" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "catalog_state_songs_count_check" CHECK (("songs_count" >= 0)),
    CONSTRAINT "catalog_state_songs_source_revision_check" CHECK (("songs_source_revision" >= 0))
);

ALTER TABLE ONLY "browser_catalog"."catalog_state" REPLICA IDENTITY FULL;


ALTER TABLE "browser_catalog"."catalog_state" OWNER TO "postgres";


COMMENT ON TABLE "browser_catalog"."catalog_state" IS 'Singleton atomic pointer to one complete active generation and one retained prior generation.';



CREATE OR REPLACE FUNCTION "browser_catalog"."refresh_projection"() RETURNS "browser_catalog"."catalog_state"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  candidate_generation uuid;
  candidate_generated_at timestamptz;
  previous_generation uuid;
  previous_generated_at timestamptz;
  previous_songs_revision bigint;
  previous_instruments_revision bigint;
  configured_retention_window interval;
  current_songs_revision bigint;
  current_instruments_revision bigint;
  rebuild_songs boolean;
  rebuild_instruments boolean;
  projected_songs_count integer;
  projected_instruments_count integer;
  expected_songs_count integer;
  expected_instruments_count integer;
  projected_songs_checksum text;
  projected_instruments_checksum text;
  promoted_state browser_catalog.catalog_state%ROWTYPE;
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(2173, 1);

  SELECT revision
  INTO current_songs_revision
  FROM public.catalog_cache_resource_revisions
  WHERE resource = 'songs'
  FOR UPDATE;

  SELECT revision
  INTO current_instruments_revision
  FROM public.catalog_cache_resource_revisions
  WHERE resource = 'instruments'
  FOR UPDATE;

  IF current_songs_revision IS NULL OR current_instruments_revision IS NULL THEN
    RAISE EXCEPTION 'Browser catalog source revisions are unavailable';
  END IF;

  SELECT
    active_generation,
    generated_at,
    songs_source_revision,
    instruments_source_revision,
    retention_window
  INTO
    previous_generation,
    previous_generated_at,
    previous_songs_revision,
    previous_instruments_revision,
    configured_retention_window
  FROM browser_catalog.catalog_state
  WHERE singleton
  FOR UPDATE;

  IF previous_generation IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM browser_catalog.catalog_state AS state
      WHERE state.singleton
        AND state.songs_source_revision = current_songs_revision
        AND state.instruments_source_revision = current_instruments_revision
    )
  THEN
    SELECT *
    INTO promoted_state
    FROM browser_catalog.catalog_state
    WHERE singleton;
    RETURN promoted_state;
  END IF;

  candidate_generation := extensions.gen_random_uuid();
  candidate_generated_at := pg_catalog.clock_timestamp();
  rebuild_songs := previous_generation IS NULL
    OR previous_songs_revision IS DISTINCT FROM current_songs_revision;
  rebuild_instruments := previous_generation IS NULL
    OR previous_instruments_revision
      IS DISTINCT FROM current_instruments_revision;

  INSERT INTO browser_catalog.generation_retention (
    server_generation,
    generated_at
  )
  VALUES (
    candidate_generation,
    candidate_generated_at
  );

  IF rebuild_songs AND EXISTS (
    SELECT 1
    FROM public.market_songs_public AS songs
    LEFT JOIN public.market_song_configs AS configs
      ON configs.market_song_id = songs.id
    WHERE configs.market_song_id IS NULL
      OR NOT COALESCE(
      browser_catalog.is_valid_song_v2(configs.song_v2)
      AND jsonb_typeof(configs.audio_samples) = 'object',
      false
    )
  ) THEN
    RAISE EXCEPTION
      'Every published adaptive browser-catalog song requires one valid SongIV2 configuration';
  END IF;

  IF rebuild_songs AND EXISTS (
    SELECT 1
    FROM public.market_songs_public AS songs
    LEFT JOIN public.market_song_embeddings AS embeddings
      ON embeddings.market_song_id = songs.id
     AND embeddings.embedding_space =
       'openai:text-embedding-3-large:256:v1'
    WHERE embeddings.market_song_id IS NULL
      OR embeddings.meta IS NULL
      OR embeddings.genre IS NULL
      OR embeddings.instrumentation IS NULL
      OR embeddings.characteristics IS NULL
      OR embeddings.meta::text ~* '(nan|infinity)'
      OR embeddings.genre::text ~* '(nan|infinity)'
      OR embeddings.instrumentation::text ~* '(nan|infinity)'
      OR embeddings.characteristics::text ~* '(nan|infinity)'
  ) THEN
    RAISE EXCEPTION
      'Every published adaptive browser-catalog song requires one finite canonical four-vector bundle';
  END IF;

  IF rebuild_songs THEN
    INSERT INTO browser_catalog.song_projection_rows (
      server_generation,
      product_type,
      resource_id,
      core,
      song_v2,
      audio_samples,
      config_updated_at,
      embedding_space,
      embedding_source_version,
      embedding_source_hash,
      embedding_source_text,
      embedding_generated_at,
      embedding_updated_at,
      meta_embedding,
      genre_embedding,
      instrumentation_embedding,
      characteristics_embedding,
      projection_generated_at,
      source_updated_at
    )
    SELECT
      candidate_generation,
      'adaptive',
      songs.id,
      pg_catalog.to_jsonb(songs),
      configs.song_v2,
      configs.audio_samples,
      configs.updated_at,
      embeddings.embedding_space,
      embeddings.source_version,
      embeddings.source_hash,
      embeddings.source_text,
      embeddings.created_at,
      embeddings.updated_at,
      embeddings.meta,
      embeddings.genre,
      embeddings.instrumentation,
      embeddings.characteristics,
      candidate_generated_at,
      songs.updated_at
    FROM public.market_songs_public AS songs
    INNER JOIN public.market_song_configs AS configs
      ON configs.market_song_id = songs.id
    INNER JOIN public.market_song_embeddings AS embeddings
      ON embeddings.market_song_id = songs.id
     AND embeddings.embedding_space =
       'openai:text-embedding-3-large:256:v1'

    UNION ALL

    SELECT
      candidate_generation,
      'ready-made',
      ready_made.id,
      jsonb_build_object(
        'id', ready_made.id,
        'title', ready_made.title,
        'slug', ready_made.slug,
        'composer', ready_made.composer,
        'description', ready_made.description,
        'usage', ready_made.usage,
        'audio_url', ready_made.audio_url,
        'cover_image', ready_made.cover_image,
        'waveform_bytes', ready_made.waveform_bytes,
        'duration_seconds', ready_made.duration_seconds,
        'tempo_label', ready_made.tempo_label,
        'music_key', ready_made.music_key,
        'tonality', ready_made.tonality,
        'time_signature', ready_made.time_signature,
        'music_type', ready_made.music_type,
        'vocals', ready_made.vocals,
        'genre_tags', ready_made.genre_tags,
        'similar_artists', ready_made.similar_artists,
        'mood', ready_made.mood,
        'instruments', ready_made.instruments,
        'tags', ready_made.tags,
        'seo_title', ready_made.seo_title,
        'seo_description', ready_made.seo_description,
        'seo_keywords', ready_made.seo_keywords,
        'source_catalog_key', ready_made.source_catalog_key,
        'source_catalog_row', ready_made.source_catalog_row,
        'legacy_prerecorded_url', ready_made.legacy_prerecorded_url,
        'external_youtube_video_id', ready_made.external_youtube_video_id,
        'isrc', ready_made.isrc,
        'upc', ready_made.upc,
        'ascap_id', ready_made.ascap_id,
        'license_sku', ready_made.license_sku,
        'purchase_enabled', ready_made.purchase_enabled,
        'variant_parent_title', ready_made.variant_parent_title,
        'variant_parent_slug', ready_made.variant_parent_slug,
        'variant_group_title', ready_made.variant_group_title,
        'variant_group_slug', ready_made.variant_group_slug,
        'variant_kind', ready_made.variant_kind,
        'variant_label', ready_made.variant_label,
        'is_primary_variant', ready_made.is_primary_variant,
        'variant_sort_order', ready_made.variant_sort_order,
        'catalog_sort_date', ready_made.catalog_sort_date,
        'catalog_excluded_reason', ready_made.catalog_excluded_reason,
        'ordering', ready_made.ordering,
        'updated_at', ready_made.updated_at,
        'created_at', ready_made.created_at
      ),
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      candidate_generated_at,
      ready_made.updated_at
    FROM public.market_ready_made_tracks AS ready_made
    WHERE ready_made.is_published
      AND ready_made.purchase_enabled
      AND ready_made.catalog_excluded_reason IS NULL;
  ELSE
    INSERT INTO browser_catalog.song_projection_rows (
      server_generation,
      product_type,
      resource_id,
      core,
      song_v2,
      audio_samples,
      config_updated_at,
      embedding_space,
      embedding_source_version,
      embedding_source_hash,
      embedding_source_text,
      embedding_generated_at,
      embedding_updated_at,
      meta_embedding,
      genre_embedding,
      instrumentation_embedding,
      characteristics_embedding,
      projection_generated_at,
      source_updated_at
    )
    SELECT
      candidate_generation,
      source.product_type,
      source.resource_id,
      source.core,
      source.song_v2,
      source.audio_samples,
      source.config_updated_at,
      source.embedding_space,
      source.embedding_source_version,
      source.embedding_source_hash,
      source.embedding_source_text,
      source.embedding_generated_at,
      source.embedding_updated_at,
      source.meta_embedding,
      source.genre_embedding,
      source.instrumentation_embedding,
      source.characteristics_embedding,
      candidate_generated_at,
      source.source_updated_at
    FROM browser_catalog.song_projection_rows AS source
    WHERE source.server_generation = previous_generation;
  END IF;

  IF rebuild_instruments THEN
    INSERT INTO browser_catalog.instrument_projection_rows (
    server_generation,
    resource_id,
    instrument,
    aliases,
    legacy_instruments,
    tags,
    profile_metadata,
    profile_embedding,
    projection_generated_at,
    source_updated_at
  )
  SELECT
    candidate_generation,
    instrument.id,
    jsonb_build_object(
      'id', instrument.id,
      'name', instrument.name,
      'lookup_key', instrument.lookup_key,
      'engine_type', instrument.engine_type,
      'asset_role', instrument.asset_role,
      'playback_type', instrument.playback_type,
      'polyphony_type', instrument.polyphony_type,
      'instrument_family', instrument.instrument_family,
      'instrument_type', instrument.instrument_type,
      'contributor_id', instrument.contributor_id,
      'collection', instrument.collection,
      'pitch_contents', instrument.pitch_contents,
      'velocity_layers', instrument.velocity_layers,
      'round_robins', instrument.round_robins,
      'pitch_content_config', instrument.pitch_content_config,
      'range_lower', instrument.range_lower,
      'range_upper', instrument.range_upper,
      'single_pitch', instrument.single_pitch,
      'gain', instrument.gain,
      'sustain_crop_time', instrument.sustain_crop_time,
      'file_path_reference', instrument.file_path_reference,
      'file_name_references', instrument.file_name_references,
      'filename_variant_map', instrument.filename_variant_map,
      'articulations', instrument.articulations,
      'effects_instruments', instrument.effects_instruments,
      'mic_positions', instrument.mic_positions,
      'original_sample_ids', instrument.original_sample_ids,
      'articulation', instrument.articulation,
      'effect', instrument.effect,
      'legato_transition', instrument.legato_transition,
      'updated_at', instrument.updated_at,
      'created_at', instrument.created_at
    ),
    COALESCE(aliases.rows, '[]'::jsonb),
    COALESCE(legacy.rows, '[]'::jsonb),
    COALESCE(tags.rows, '[]'::jsonb),
    CASE
      WHEN profile.id IS NULL THEN NULL
      ELSE jsonb_build_object(
        'id', profile.id,
        'audio_profile_version', profile.audio_profile_version,
        'audio_profile_source_signature',
          profile.audio_profile_source_signature,
        'audio_profile_sample_count', profile.audio_profile_sample_count,
        'audio_profile_analyzed_sample_count',
          profile.audio_profile_analyzed_sample_count,
        'audio_profile_flagged_sample_count',
          profile.audio_profile_flagged_sample_count,
        'audio_profile_quality_report', profile.audio_profile_quality_report,
        'audio_profile_warning_payload', profile.audio_profile_warning_payload,
        'audio_profile_temporal_summary',
          profile.audio_profile_temporal_summary,
        'audio_profile_computed_at', profile.audio_profile_computed_at,
        'low_register', profile.low_register,
        'mid_register', profile.mid_register,
        'high_register', profile.high_register,
        'spectral_centroid_median', profile.spectral_centroid_median,
        'spectral_flatness_median', profile.spectral_flatness_median,
        'spectral_contrast_median', profile.spectral_contrast_median,
        'hp_ratio_median', profile.hp_ratio_median,
        'attack_time_ms_median', profile.attack_time_ms_median,
        'decay_time_ms_median', profile.decay_time_ms_median,
        'inharmonicity_median', profile.inharmonicity_median,
        'spectral_rolloff_median', profile.spectral_rolloff_median,
        'spectral_entropy_median', profile.spectral_entropy_median,
        'hnr_db_median', profile.hnr_db_median,
        'onset_sharpness_median', profile.onset_sharpness_median,
        'sustain_stability_median', profile.sustain_stability_median,
        'temporal_centroid_median', profile.temporal_centroid_median,
        'spectral_flux_mean_median', profile.spectral_flux_mean_median,
        'pitch_mean', profile.pitch_mean,
        'pitch_median_median', profile.pitch_median_median,
        'pitch_std_median', profile.pitch_std_median,
        'pitch_range_median', profile.pitch_range_median,
        'pitch_stability_median', profile.pitch_stability_median,
        'pitch_confidence_median', profile.pitch_confidence_median,
        'effective_duration_median', profile.effective_duration_median,
        'vibrato_rate_hz_median', profile.vibrato_rate_hz_median,
        'vibrato_depth_hz_median', profile.vibrato_depth_hz_median,
        'odd_even_ratio_median', profile.odd_even_ratio_median,
        'pitched_sample_ratio', profile.pitched_sample_ratio,
        'long_sample_ratio', profile.long_sample_ratio,
        'short_sample_ratio', profile.short_sample_ratio,
        'sharp_onset_sample_ratio', profile.sharp_onset_sample_ratio,
        'tremolo_candidate_sample_ratio',
          profile.tremolo_candidate_sample_ratio,
        'vibrato_candidate_sample_ratio',
          profile.vibrato_candidate_sample_ratio,
        'noisy_candidate_sample_ratio',
          profile.noisy_candidate_sample_ratio,
        'harmonic_candidate_sample_ratio',
          profile.harmonic_candidate_sample_ratio,
        'percussive_candidate_sample_ratio',
          profile.percussive_candidate_sample_ratio,
        'bright_sample_ratio', profile.bright_sample_ratio,
        'dark_sample_ratio', profile.dark_sample_ratio
      )
    END,
    profile.embedding,
    candidate_generated_at,
    instrument.updated_at
  FROM public.instruments_v2 AS instrument
  LEFT JOIN public.instruments_v2_with_audio_profile_v1 AS profile
    ON profile.id = instrument.id
   AND profile.audio_profile_version = 'audio-profile-v1'
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', map.id,
        'instrument_v2_id', map.instrument_v2_id,
        'legacy_instrument_id', map.legacy_instrument_id,
        'legacy_lookup_key', map.legacy_lookup_key,
        'legacy_file_path_reference', map.legacy_file_path_reference,
        'legacy_velocity', map.legacy_velocity,
        'is_primary_for_legacy', map.is_primary_for_legacy,
        'is_primary_for_v2', map.is_primary_for_v2,
        'updated_at', map.updated_at
      )
      ORDER BY map.id
    ) AS rows
    FROM public.instrument_v2_legacy_map AS map
    WHERE map.instrument_v2_id = instrument.id
  ) AS aliases ON true
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(candidate.row ORDER BY candidate.legacy_id) AS rows
    FROM (
      SELECT DISTINCT ON (legacy_instrument.id)
        legacy_instrument.id AS legacy_id,
        jsonb_build_object(
          'id', legacy_instrument.id,
          'firebase_id', legacy_instrument.firebase_id,
          'file_path_reference', legacy_instrument.file_path_reference,
          'name', legacy_instrument.name,
          'family', legacy_instrument.family,
          'instrument_family', legacy_instrument.instrument_family,
          'type', legacy_instrument.type,
          'instrument_type', legacy_instrument.instrument_type,
          'sample_type', legacy_instrument.sample_type,
          'sample_sub_sets', legacy_instrument.sample_sub_sets,
          'gain', legacy_instrument.gain,
          'range_lower_limit', legacy_instrument.range_lower_limit,
          'range_upper_limit', legacy_instrument.range_upper_limit,
          'single_pitch', legacy_instrument.single_pitch,
          'sample_config', legacy_instrument.sample_config,
          'sample_sets', legacy_instrument.sample_sets,
          'harmony_type', legacy_instrument.harmony_type,
          'file_name_reference', legacy_instrument.file_name_reference,
          'file_name_references', legacy_instrument.file_name_references,
          'contributor_id', legacy_instrument.contributor_id,
          'contributor_name', legacy_instrument.contributor_name,
          'collection', legacy_instrument.collection,
          'pitch_gaps', legacy_instrument.pitch_gaps,
          'articulations', legacy_instrument.articulations,
          'effects_instruments', legacy_instrument.effects_instruments,
          'velocity_layers', legacy_instrument.velocity_layers,
          'mic_positions', legacy_instrument.mic_positions,
          'created_at', legacy_instrument.created_at
        ) AS row
      FROM public.instrument_v2_legacy_map AS map
      INNER JOIN public.instruments AS legacy_instrument
        ON legacy_instrument.id = map.legacy_instrument_id
       AND legacy_instrument.published
      WHERE map.instrument_v2_id = instrument.id
      ORDER BY legacy_instrument.id, map.id
    ) AS candidate
  ) AS legacy ON true
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(
      jsonb_build_object(
        'instrument_v2_id', link.instrument_v2_id,
        'tag_id', tag.id,
        'source', link.source,
        'created_at', link.created_at,
        'id', tag.id,
        'tag_group', tag.tag_group,
        'tag_name', tag.tag_name,
        'notes', tag.notes,
        'contributor_id', tag.contributor_id
      )
      ORDER BY tag.id
    ) AS rows
    FROM public.instrument_v2_instrument_tags AS link
    INNER JOIN public.instrument_tags AS tag ON tag.id = link.tag_id
    WHERE link.instrument_v2_id = instrument.id
  ) AS tags ON true
    WHERE instrument.published;
  ELSE
    INSERT INTO browser_catalog.instrument_projection_rows (
      server_generation,
      resource_id,
      instrument,
      aliases,
      legacy_instruments,
      tags,
      profile_metadata,
      profile_embedding,
      projection_generated_at,
      source_updated_at
    )
    SELECT
      candidate_generation,
      source.resource_id,
      source.instrument,
      source.aliases,
      source.legacy_instruments,
      source.tags,
      source.profile_metadata,
      source.profile_embedding,
      candidate_generated_at,
      source.source_updated_at
    FROM browser_catalog.instrument_projection_rows AS source
    WHERE source.server_generation = previous_generation;
  END IF;

  SELECT count(*)::integer
  INTO projected_songs_count
  FROM browser_catalog.song_projection_rows
  WHERE server_generation = candidate_generation;

  SELECT (
    (SELECT count(*) FROM public.market_songs_public)
    +
    (SELECT count(*)
     FROM public.market_ready_made_tracks
     WHERE is_published
       AND purchase_enabled
       AND catalog_excluded_reason IS NULL)
  )::integer
  INTO expected_songs_count;

  SELECT count(*)::integer
  INTO projected_instruments_count
  FROM browser_catalog.instrument_projection_rows
  WHERE server_generation = candidate_generation;

  SELECT count(*)::integer
  INTO expected_instruments_count
  FROM public.instruments_v2
  WHERE published;

  IF projected_songs_count <> expected_songs_count THEN
    RAISE EXCEPTION
      'Browser song projection parity failed: projected %, expected %',
      projected_songs_count,
      expected_songs_count;
  END IF;

  IF projected_instruments_count <> expected_instruments_count THEN
    RAISE EXCEPTION
      'Browser instrument projection parity failed: projected %, expected %',
      projected_instruments_count,
      expected_instruments_count;
  END IF;

  SELECT pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        COALESCE(
          string_agg(
            jsonb_build_object(
              'productType', product_type,
              'resourceId', resource_id,
              'core', core,
              'songV2', song_v2,
              'audioSamples', audio_samples,
              'configUpdatedAt', config_updated_at,
              'embeddingSpace', embedding_space,
              'embeddingSourceVersion', embedding_source_version,
              'embeddingSourceHash', embedding_source_hash,
              'embeddingSourceText', embedding_source_text,
              'embeddingGeneratedAt', embedding_generated_at,
              'embeddingUpdatedAt', embedding_updated_at,
              'meta', meta_embedding::text,
              'genre', genre_embedding::text,
              'instrumentation', instrumentation_embedding::text,
              'characteristics', characteristics_embedding::text,
              'sourceUpdatedAt', source_updated_at
            )::text,
            E'\n' ORDER BY product_type, resource_id
          ),
          ''
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  )
  INTO projected_songs_checksum
  FROM browser_catalog.song_projection_rows
  WHERE server_generation = candidate_generation;

  SELECT pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        COALESCE(
          string_agg(
            jsonb_build_object(
              'resourceId', resource_id,
              'instrument', instrument,
              'aliases', aliases,
              'legacyInstruments', legacy_instruments,
              'tags', tags,
              'profileMetadata', profile_metadata,
              'profileEmbedding', profile_embedding::text,
              'sourceUpdatedAt', source_updated_at
            )::text,
            E'\n' ORDER BY resource_id
          ),
          ''
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  )
  INTO projected_instruments_checksum
  FROM browser_catalog.instrument_projection_rows
  WHERE server_generation = candidate_generation;

  IF previous_generation IS NOT NULL THEN
    UPDATE browser_catalog.generation_retention
    SET retired_at = candidate_generated_at,
        expires_at =
          candidate_generated_at + configured_retention_window
    WHERE server_generation = previous_generation
      AND retired_at IS NULL
    RETURNING generated_at INTO previous_generated_at;

    IF NOT FOUND THEN
      RAISE EXCEPTION
        'Active browser catalog generation % has no active retention record',
        previous_generation;
    END IF;
  END IF;

  UPDATE browser_catalog.catalog_state
  SET active_generation = candidate_generation,
      retained_prior_generation = previous_generation,
      retained_prior_generated_at = previous_generated_at,
      retained_prior_until = CASE
        WHEN previous_generation IS NULL THEN NULL
        ELSE candidate_generated_at + configured_retention_window
      END,
      songs_source_revision = current_songs_revision,
      instruments_source_revision = current_instruments_revision,
      songs_count = projected_songs_count,
      instruments_count = projected_instruments_count,
      songs_checksum = projected_songs_checksum,
      instruments_checksum = projected_instruments_checksum,
      generated_at = pg_catalog.clock_timestamp()
  WHERE singleton
  RETURNING * INTO promoted_state;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Browser catalog state row is unavailable';
  END IF;

  DELETE FROM browser_catalog.song_projection_rows
  WHERE server_generation <> candidate_generation
    AND EXISTS (
      SELECT 1
      FROM browser_catalog.generation_retention AS retention
      WHERE retention.server_generation =
        song_projection_rows.server_generation
        AND retention.expires_at <= candidate_generated_at
    );

  DELETE FROM browser_catalog.instrument_projection_rows
  WHERE server_generation <> candidate_generation
    AND EXISTS (
      SELECT 1
      FROM browser_catalog.generation_retention AS retention
      WHERE retention.server_generation =
        instrument_projection_rows.server_generation
        AND retention.expires_at <= candidate_generated_at
    );

  DELETE FROM browser_catalog.generation_retention
  WHERE server_generation <> candidate_generation
    AND expires_at <= candidate_generated_at;

  RETURN promoted_state;
END;
$$;


ALTER FUNCTION "browser_catalog"."refresh_projection"() OWNER TO "postgres";


COMMENT ON FUNCTION "browser_catalog"."refresh_projection"() IS 'Transactionally materializes and promotes songs plus instruments under the source-revision advisory lock.';



CREATE OR REPLACE FUNCTION "intelligence_read"."partner_pipeline"("p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 25) RETURNS TABLE("organization_name" "text", "partner_category" "text", "relationship_status" "text", "priority" "text", "milestone" "text", "engagement_state" "text", "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    o.name AS organization_name,
    r.partner_type_key AS partner_category,
    r.status AS relationship_status,
    r.priority,
    r.milestone_key AS milestone,
    CASE
      WHEN r.last_contacted_at IS NULL THEN 'not-contacted'
      WHEN r.follow_up_at IS NOT NULL AND r.follow_up_at <= now() THEN 'follow-up-due'
      ELSE 'engaged'
    END AS engagement_state,
    r.updated_at
  FROM public.crm_relationships AS r
  JOIN public.crm_organizations AS o ON o.id = r.organization_id
  WHERE o.archived_at IS NULL
    AND (p_query IS NULL OR o.name ILIKE '%' || replace(replace(p_query, '%', E'\\%'), '_', E'\\_') || '%' ESCAPE E'\\')
  ORDER BY r.updated_at DESC
  LIMIT LEAST(GREATEST(p_limit, 1), 50)
$$;


ALTER FUNCTION "intelligence_read"."partner_pipeline"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "intelligence_read"."product_membership_summary"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("product" "text", "memberships" bigint, "signed_up" bigint, "active" bigint, "latest_sync" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    m.product,
    count(*)::bigint AS memberships,
    count(*) FILTER (
      WHERE m.signed_up_at >= p_start_date::timestamptz
        AND m.signed_up_at < (p_end_date + 1)::timestamptz
    )::bigint AS signed_up,
    count(*) FILTER (
      WHERE m.last_active_at >= p_start_date::timestamptz
        AND m.last_active_at < (p_end_date + 1)::timestamptz
    )::bigint AS active,
    max(m.last_synced_at) AS latest_sync
  FROM public.crm_product_memberships AS m
  WHERE p_end_date >= p_start_date
    AND p_end_date - p_start_date <= 90
  GROUP BY m.product
  ORDER BY m.product
$$;


ALTER FUNCTION "intelligence_read"."product_membership_summary"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."audit_feature_flag_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_feature_flag_id uuid;
  v_target_user_id uuid;
  v_actor_user_id uuid;
  v_entity_type text;
  v_action text;
  v_before_state jsonb;
  v_after_state jsonb;
  v_mutation_source text;
  v_change_reason text;
  v_audit_event_id bigint;
BEGIN
  IF TG_TABLE_NAME = 'feature_flags' THEN
    v_entity_type := 'feature_flag';
    v_feature_flag_id := COALESCE(NEW.id, OLD.id);
    v_actor_user_id := CASE
      WHEN TG_OP = 'INSERT' THEN NEW.created_by_user_id
      ELSE NEW.updated_by_user_id
    END;
    v_mutation_source := 'migration';

    IF TG_OP = 'UPDATE' THEN
      v_before_state := pg_catalog.jsonb_build_object(
        'key', OLD.key,
        'label', OLD.label,
        'description', OLD.description,
        'category', OLD.category,
        'surfaces', OLD.surfaces,
        'is_active', OLD.is_active,
        'requires_reload', OLD.requires_reload,
        'dev_logging_enabled', OLD.dev_logging_enabled,
        'product_insights_enabled', OLD.product_insights_enabled,
        'self_service_enabled', OLD.self_service_enabled,
        'owner', OLD.owner,
        'review_after', OLD.review_after,
        'archived_at', OLD.archived_at
      );
    END IF;

    v_after_state := pg_catalog.jsonb_build_object(
      'key', NEW.key,
      'label', NEW.label,
      'description', NEW.description,
      'category', NEW.category,
      'surfaces', NEW.surfaces,
      'is_active', NEW.is_active,
      'requires_reload', NEW.requires_reload,
      'dev_logging_enabled', NEW.dev_logging_enabled,
      'product_insights_enabled', NEW.product_insights_enabled,
      'self_service_enabled', NEW.self_service_enabled,
      'owner', NEW.owner,
      'review_after', NEW.review_after,
      'archived_at', NEW.archived_at
    );

    IF TG_OP = 'UPDATE' AND v_before_state IS NOT DISTINCT FROM v_after_state THEN
      RETURN NEW;
    END IF;

    v_action := CASE
      WHEN TG_OP = 'INSERT' THEN 'insert'
      WHEN OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL THEN 'archive'
      ELSE 'update'
    END;
  ELSE
    v_entity_type := 'user_enablement';
    IF TG_OP = 'DELETE' THEN
      v_feature_flag_id := OLD.feature_flag_id;
      v_target_user_id := OLD.user_id;
    ELSE
      v_feature_flag_id := NEW.feature_flag_id;
      v_target_user_id := NEW.user_id;
    END IF;

    IF TG_OP = 'INSERT' THEN
      v_action := 'insert';
      v_actor_user_id := NEW.updated_by_user_id;
      v_after_state := pg_catalog.jsonb_build_object('enabled', NEW.enabled);
      v_mutation_source := NEW.updated_via;
      v_change_reason := NEW.change_reason;
    ELSIF TG_OP = 'UPDATE' THEN
      IF OLD.enabled IS NOT DISTINCT FROM NEW.enabled THEN
        RETURN NEW;
      END IF;
      v_action := 'update';
      v_actor_user_id := NEW.updated_by_user_id;
      v_before_state := pg_catalog.jsonb_build_object('enabled', OLD.enabled);
      v_after_state := pg_catalog.jsonb_build_object('enabled', NEW.enabled);
      v_mutation_source := NEW.updated_via;
      v_change_reason := NEW.change_reason;
    ELSE
      v_action := 'delete';
      v_actor_user_id := OLD.updated_by_user_id;
      v_before_state := pg_catalog.jsonb_build_object('enabled', OLD.enabled);
      v_mutation_source := OLD.updated_via;
      v_change_reason := OLD.change_reason;
    END IF;
  END IF;

  INSERT INTO public.feature_flag_change_events (
    feature_flag_id,
    target_user_id,
    actor_user_id,
    entity_type,
    action,
    before_state,
    after_state,
    mutation_source,
    change_reason
  ) VALUES (
    v_feature_flag_id,
    v_target_user_id,
    v_actor_user_id,
    v_entity_type,
    v_action,
    v_before_state,
    v_after_state,
    v_mutation_source,
    v_change_reason
  )
  RETURNING id INTO v_audit_event_id;

  PERFORM pg_catalog.set_config(
    'feature_flags.last_audit_event_id',
    v_audit_event_id::text,
    true
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."audit_feature_flag_change"() OWNER TO "feature_flag_owner";


CREATE OR REPLACE FUNCTION "private"."crm_apply_duplicate_source_link_repair"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  actor_is_admin boolean;
  api_key_is_active boolean;
  idempotency_id uuid;
  stored_fingerprint text;
  stored_response jsonb;
  source_contact_id uuid;
  target_contact_id uuid;
  expected_contacts integer;
  expected_links integer;
  expected_relationship_removals integer;
  expected_relationship_moves integer;
  expected_activity_removals integer;
  expected_activity_moves integer;
  planned_links integer;
  planned_relationship_removals integer;
  planned_relationship_moves integer;
  planned_activity_removals integer;
  planned_activity_moves integer;
  actual_contacts integer;
  actual_links integer;
  actual_relationship_removals integer;
  actual_relationship_moves integer;
  actual_activity_removals integer;
  actual_activity_moves integer;
  result jsonb;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'crm_api_service_role_required' USING errcode = '42501';
  END IF;

  SELECT role = 'admin' INTO actor_is_admin
  FROM public.crm_team_members
  WHERE user_id = p_actor_user_id AND active;
  IF NOT coalesce(actor_is_admin, false) THEN
    RAISE EXCEPTION 'crm_admin_required' USING errcode = '42501';
  END IF;

  IF p_api_key_id IS NULL THEN
    IF p_actor_scope IS DISTINCT FROM 'user:' || p_actor_user_id::text THEN
      RAISE EXCEPTION 'crm_actor_scope_invalid' USING errcode = '22023';
    END IF;
  ELSE
    IF p_actor_scope IS DISTINCT FROM 'api-key:' || p_api_key_id::text THEN
      RAISE EXCEPTION 'crm_actor_scope_invalid' USING errcode = '22023';
    END IF;
    SELECT EXISTS (
      SELECT 1
      FROM public.crm_api_keys
      WHERE id = p_api_key_id
        AND team_member_user_id = p_actor_user_id
        AND revoked_at IS NULL
        AND (expires_at IS NULL OR expires_at > now())
    ) INTO api_key_is_active;
    IF NOT api_key_is_active THEN
      RAISE EXCEPTION 'crm_api_key_not_active' USING errcode = '42501';
    END IF;
  END IF;

  IF p_operation IS DISTINCT FROM 'duplicate-source-link.repair' THEN
    RAISE EXCEPTION 'crm_duplicate_source_repair_operation_invalid' USING errcode = '22023';
  END IF;
  IF p_idempotency_key IS NULL
    OR p_idempotency_key <> btrim(p_idempotency_key)
    OR char_length(p_idempotency_key) NOT BETWEEN 8 AND 200
  THEN
    RAISE EXCEPTION 'crm_idempotency_key_invalid' USING errcode = '22023';
  END IF;
  IF p_request_fingerprint IS NULL
    OR p_request_fingerprint !~ '^[a-f0-9]{64}$'
  THEN
    RAISE EXCEPTION 'crm_request_fingerprint_invalid' USING errcode = '22023';
  END IF;
  IF p_payload IS NULL
    OR jsonb_typeof(p_payload) <> 'object'
    OR p_payload->>'confirm' IS DISTINCT FROM 'REPAIR'
    OR nullif(btrim(p_payload->>'source_kind'), '') IS NULL
    OR nullif(btrim(p_payload->>'source_record_id'), '') IS NULL
    OR nullif(p_payload->>'source_contact_id', '') IS NULL
    OR nullif(p_payload->>'target_contact_id', '') IS NULL
    OR jsonb_typeof(p_payload->'expected_contacts_to_remove') <> 'number'
    OR jsonb_typeof(p_payload->'expected_links_to_remove') <> 'number'
    OR jsonb_typeof(p_payload->'expected_relationships_to_remove') <> 'number'
    OR jsonb_typeof(p_payload->'expected_relationships_to_move') <> 'number'
    OR jsonb_typeof(p_payload->'expected_activities_to_remove') <> 'number'
    OR jsonb_typeof(p_payload->'expected_activities_to_move') <> 'number'
  THEN
    RAISE EXCEPTION 'crm_duplicate_source_repair_payload_invalid' USING errcode = '22023';
  END IF;

  source_contact_id := (p_payload->>'source_contact_id')::uuid;
  target_contact_id := (p_payload->>'target_contact_id')::uuid;
  expected_contacts := (p_payload->>'expected_contacts_to_remove')::integer;
  expected_links := (p_payload->>'expected_links_to_remove')::integer;
  expected_relationship_removals := (p_payload->>'expected_relationships_to_remove')::integer;
  expected_relationship_moves := (p_payload->>'expected_relationships_to_move')::integer;
  expected_activity_removals := (p_payload->>'expected_activities_to_remove')::integer;
  expected_activity_moves := (p_payload->>'expected_activities_to_move')::integer;
  IF source_contact_id = target_contact_id
    OR expected_contacts <> 1
    OR expected_links < 1
    OR expected_relationship_removals < 0
    OR expected_relationship_moves < 0
    OR expected_activity_removals < 0
    OR expected_activity_moves < 0
  THEN
    RAISE EXCEPTION 'crm_duplicate_source_repair_expected_counts_invalid' USING errcode = '22023';
  END IF;

  INSERT INTO public.crm_idempotency_records (
    actor_scope, actor_user_id, api_key_id, operation, idempotency_key,
    request_fingerprint
  ) VALUES (
    p_actor_scope, p_actor_user_id, p_api_key_id, p_operation,
    p_idempotency_key, p_request_fingerprint
  )
  ON CONFLICT (actor_scope, operation, idempotency_key) DO NOTHING
  RETURNING id INTO idempotency_id;

  IF idempotency_id IS NULL THEN
    SELECT request_fingerprint, response_body
      INTO stored_fingerprint, stored_response
    FROM public.crm_idempotency_records
    WHERE actor_scope = p_actor_scope
      AND operation = p_operation
      AND idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF stored_fingerprint <> p_request_fingerprint THEN
      RAISE EXCEPTION 'crm_idempotency_conflict' USING errcode = '23505';
    END IF;
    RETURN stored_response || jsonb_build_object('replayed', true);
  END IF;

  PERFORM id
  FROM public.crm_contacts
  WHERE id IN (source_contact_id, target_contact_id)
  ORDER BY id
  FOR UPDATE;
  SELECT count(*)::integer INTO actual_contacts
  FROM public.crm_contacts
  WHERE id IN (source_contact_id, target_contact_id)
    AND archived_at IS NULL;
  IF actual_contacts <> 2 THEN
    RAISE EXCEPTION 'crm_duplicate_source_repair_contacts_changed' USING errcode = '40001';
  END IF;

  PERFORM source_link.id
  FROM public.crm_contact_sources source_link
  WHERE source_link.contact_id IN (source_contact_id, target_contact_id)
  ORDER BY source_link.id
  FOR UPDATE;
  IF NOT EXISTS (
    SELECT 1
    FROM public.crm_contact_sources source_link
    JOIN public.crm_contact_sources target_link
      ON target_link.source_id = source_link.source_id
     AND target_link.contact_id = target_contact_id
    JOIN public.crm_sources source_row ON source_row.id = source_link.source_id
    WHERE source_link.contact_id = source_contact_id
      AND source_row.source_kind = btrim(p_payload->>'source_kind')
      AND source_row.external_record_id = btrim(p_payload->>'source_record_id')
  ) THEN
    RAISE EXCEPTION 'crm_duplicate_source_repair_identity_changed' USING errcode = '40001';
  END IF;

  PERFORM relationship.id
  FROM public.crm_relationships relationship
  WHERE relationship.contact_id IN (source_contact_id, target_contact_id)
  ORDER BY relationship.id
  FOR UPDATE;
  PERFORM activity.id
  FROM public.crm_activities activity
  WHERE activity.contact_id IN (source_contact_id, target_contact_id)
  ORDER BY activity.id
  FOR UPDATE;

  SELECT count(*)::integer INTO planned_links
  FROM public.crm_contact_sources
  WHERE contact_id = source_contact_id;

  WITH classified AS (
    SELECT
      source_row.id,
      row_number() OVER (
        PARTITION BY source_row.partner_type_key ORDER BY source_row.id
      ) AS duplicate_ordinal,
      EXISTS (
        SELECT 1
        FROM public.crm_relationships target_row
        WHERE target_row.contact_id = target_contact_id
          AND target_row.partner_type_key = source_row.partner_type_key
      ) AS target_has_key
    FROM public.crm_relationships source_row
    WHERE source_row.contact_id = source_contact_id
  )
  SELECT
    count(*) FILTER (WHERE target_has_key OR duplicate_ordinal > 1)::integer,
    count(*) FILTER (WHERE NOT target_has_key AND duplicate_ordinal = 1)::integer
  INTO planned_relationship_removals, planned_relationship_moves
  FROM classified;

  WITH classified AS (
    SELECT
      source_row.id,
      row_number() OVER (
        PARTITION BY source_row.channel, source_row.source_reference
        ORDER BY source_row.id
      ) AS duplicate_ordinal,
      EXISTS (
        SELECT 1
        FROM public.crm_activities target_row
        WHERE target_row.contact_id = target_contact_id
          AND target_row.channel = source_row.channel
          AND target_row.source_reference IS NOT DISTINCT FROM source_row.source_reference
      ) AS target_has_key
    FROM public.crm_activities source_row
    WHERE source_row.contact_id = source_contact_id
  )
  SELECT
    count(*) FILTER (WHERE target_has_key OR duplicate_ordinal > 1)::integer,
    count(*) FILTER (WHERE NOT target_has_key AND duplicate_ordinal = 1)::integer
  INTO planned_activity_removals, planned_activity_moves
  FROM classified;

  IF planned_links <> expected_links
    OR planned_relationship_removals <> expected_relationship_removals
    OR planned_relationship_moves <> expected_relationship_moves
    OR planned_activity_removals <> expected_activity_removals
    OR planned_activity_moves <> expected_activity_moves
  THEN
    RAISE EXCEPTION 'crm_duplicate_source_repair_plan_changed' USING errcode = '40001';
  END IF;

  WITH classified AS (
    SELECT
      source_row.id,
      row_number() OVER (
        PARTITION BY source_row.partner_type_key ORDER BY source_row.id
      ) AS duplicate_ordinal,
      EXISTS (
        SELECT 1 FROM public.crm_relationships target_row
        WHERE target_row.contact_id = target_contact_id
          AND target_row.partner_type_key = source_row.partner_type_key
      ) AS target_has_key
    FROM public.crm_relationships source_row
    WHERE source_row.contact_id = source_contact_id
  )
  DELETE FROM public.crm_relationships relationship
  USING classified
  WHERE relationship.id = classified.id
    AND (classified.target_has_key OR classified.duplicate_ordinal > 1);
  GET DIAGNOSTICS actual_relationship_removals = ROW_COUNT;

  UPDATE public.crm_relationships
  SET contact_id = target_contact_id, updated_at = now()
  WHERE contact_id = source_contact_id;
  GET DIAGNOSTICS actual_relationship_moves = ROW_COUNT;

  WITH classified AS (
    SELECT
      source_row.id,
      row_number() OVER (
        PARTITION BY source_row.channel, source_row.source_reference
        ORDER BY source_row.id
      ) AS duplicate_ordinal,
      EXISTS (
        SELECT 1 FROM public.crm_activities target_row
        WHERE target_row.contact_id = target_contact_id
          AND target_row.channel = source_row.channel
          AND target_row.source_reference IS NOT DISTINCT FROM source_row.source_reference
      ) AS target_has_key
    FROM public.crm_activities source_row
    WHERE source_row.contact_id = source_contact_id
  )
  DELETE FROM public.crm_activities activity
  USING classified
  WHERE activity.id = classified.id
    AND (classified.target_has_key OR classified.duplicate_ordinal > 1);
  GET DIAGNOSTICS actual_activity_removals = ROW_COUNT;

  UPDATE public.crm_activities
  SET contact_id = target_contact_id
  WHERE contact_id = source_contact_id;
  GET DIAGNOSTICS actual_activity_moves = ROW_COUNT;

  DELETE FROM public.crm_contact_sources
  WHERE contact_id = source_contact_id;
  GET DIAGNOSTICS actual_links = ROW_COUNT;

  DELETE FROM public.crm_contacts
  WHERE id = source_contact_id;
  GET DIAGNOSTICS actual_contacts = ROW_COUNT;

  IF actual_contacts <> expected_contacts
    OR actual_links <> expected_links
    OR actual_relationship_removals <> expected_relationship_removals
    OR actual_relationship_moves <> expected_relationship_moves
    OR actual_activity_removals <> expected_activity_removals
    OR actual_activity_moves <> expected_activity_moves
  THEN
    RAISE EXCEPTION 'crm_duplicate_source_repair_result_mismatch' USING errcode = '40001';
  END IF;

  result := jsonb_build_object(
    'operation', p_operation,
    'sourceContactId', source_contact_id,
    'targetContactId', target_contact_id,
    'cleanup', jsonb_build_object(
      'contactsRemoved', actual_contacts,
      'linksRemoved', actual_links,
      'relationshipsRemoved', actual_relationship_removals,
      'relationshipsMoved', actual_relationship_moves,
      'activitiesRemoved', actual_activity_removals,
      'activitiesMoved', actual_activity_moves
    ),
    'replayed', false
  );

  INSERT INTO public.crm_change_events (
    actor_user_id, entity_type, entity_id, action, after_summary
  ) VALUES (
    p_actor_user_id, 'contact', target_contact_id,
    'duplicate-source-repaired',
    jsonb_build_object(
      'source_contact_id', source_contact_id,
      'source_kind', btrim(p_payload->>'source_kind'),
      'source_record_id', btrim(p_payload->>'source_record_id'),
      'cleanup', result->'cleanup',
      'summary', nullif(btrim(p_payload->>'summary'), '')
    )
  );

  UPDATE public.crm_idempotency_records
  SET response_body = result, completed_at = now()
  WHERE id = idempotency_id;

  RETURN result;
END;
$_$;


ALTER FUNCTION "private"."crm_apply_duplicate_source_link_repair"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."crm_apply_duplicate_source_link_repair"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") IS 'Atomically applies one reviewed duplicate-source cleanup with exact-count validation, idempotency, and an audit event.';



CREATE OR REPLACE FUNCTION "private"."crm_apply_evidence_mutation"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  actor_role text;
  idempotency_id uuid;
  stored_fingerprint text;
  stored_response jsonb;
  result jsonb;
  entity_type_value text;
  entity_id_value uuid;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'crm_api_service_role_required' USING errcode = '42501';
  END IF;
  SELECT role INTO actor_role FROM public.crm_team_members WHERE user_id = p_actor_user_id AND active;
  IF actor_role IS NULL THEN RAISE EXCEPTION 'crm_actor_not_active' USING errcode = '42501'; END IF;

  INSERT INTO public.crm_idempotency_records (
    actor_scope, actor_user_id, api_key_id, operation, idempotency_key, request_fingerprint
  ) VALUES (
    p_actor_scope, p_actor_user_id, p_api_key_id, p_operation, p_idempotency_key, p_request_fingerprint
  )
  ON CONFLICT (actor_scope, operation, idempotency_key) DO NOTHING
  RETURNING id INTO idempotency_id;

  IF idempotency_id IS NULL THEN
    SELECT request_fingerprint, response_body INTO stored_fingerprint, stored_response
    FROM public.crm_idempotency_records
    WHERE actor_scope = p_actor_scope AND operation = p_operation AND idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF stored_fingerprint <> p_request_fingerprint THEN
      RAISE EXCEPTION 'crm_idempotency_conflict' USING errcode = '23505';
    END IF;
    RETURN stored_response || jsonb_build_object('replayed', true);
  END IF;

  CASE p_operation
    WHEN 'contact-method.upsert' THEN
      INSERT INTO public.crm_contact_methods AS target (
        contact_id, kind, value, normalized_value, label, is_primary,
        external_id, verification_state, verification_source_id,
        first_seen_at, last_seen_at
      ) VALUES (
        (p_payload->>'contact_id')::uuid, p_payload->>'kind', p_payload->>'value',
        nullif(p_payload->>'normalized_value', ''), nullif(p_payload->>'label', ''),
        coalesce((p_payload->>'is_primary')::boolean, false), nullif(p_payload->>'external_id', ''),
        coalesce(nullif(p_payload->>'verification_state', ''), 'unverified'),
        nullif(p_payload->>'verification_source_id', '')::uuid,
        coalesce(nullif(p_payload->>'first_seen_at', '')::timestamptz, now()),
        coalesce(nullif(p_payload->>'last_seen_at', '')::timestamptz, now())
      )
      ON CONFLICT (kind, external_id) WHERE external_id IS NOT NULL DO UPDATE SET
        contact_id = EXCLUDED.contact_id, value = EXCLUDED.value,
        normalized_value = EXCLUDED.normalized_value, label = EXCLUDED.label,
        verification_state = EXCLUDED.verification_state,
        verification_source_id = EXCLUDED.verification_source_id,
        first_seen_at = least(target.first_seen_at, EXCLUDED.first_seen_at),
        last_seen_at = greatest(target.last_seen_at, EXCLUDED.last_seen_at), updated_at = now()
      RETURNING id INTO entity_id_value;
      entity_type_value := 'contact';

    WHEN 'organization-affiliation.upsert' THEN
      INSERT INTO public.crm_organization_contacts AS target (
        organization_id, contact_id, title, is_primary_contact,
        affiliation_kind, started_at, ended_at, is_current
      ) VALUES (
        (p_payload->>'organization_id')::uuid, (p_payload->>'contact_id')::uuid,
        nullif(p_payload->>'title', ''), coalesce((p_payload->>'is_primary_contact')::boolean, false),
        coalesce(nullif(p_payload->>'affiliation_kind', ''), 'member'),
        nullif(p_payload->>'started_at', '')::date, nullif(p_payload->>'ended_at', '')::date,
        coalesce((p_payload->>'is_current')::boolean, true)
      )
      ON CONFLICT (organization_id, contact_id) DO UPDATE SET
        title = EXCLUDED.title, affiliation_kind = EXCLUDED.affiliation_kind,
        started_at = EXCLUDED.started_at, ended_at = EXCLUDED.ended_at,
        is_current = EXCLUDED.is_current, updated_at = now()
      RETURNING id INTO entity_id_value;
      entity_type_value := 'organization';

    WHEN 'relationship-evidence.upsert' THEN
      UPDATE public.crm_relationships SET
        origin_mode = coalesce(nullif(p_payload->>'origin_mode', ''), origin_mode),
        origin_detail = coalesce(nullif(p_payload->>'origin_detail', ''), origin_detail),
        derived_engagement = coalesce(nullif(p_payload->>'derived_engagement', ''), derived_engagement),
        derived_engagement_at = coalesce(nullif(p_payload->>'derived_engagement_at', '')::timestamptz, derived_engagement_at),
        derived_engagement_source_id = coalesce(nullif(p_payload->>'derived_engagement_source_id', '')::uuid, derived_engagement_source_id),
        engagement_override = CASE WHEN p_payload ? 'clear_override' AND (p_payload->>'clear_override')::boolean THEN NULL ELSE coalesce(nullif(p_payload->>'engagement_override', ''), engagement_override) END,
        engagement_override_reason = CASE WHEN p_payload ? 'clear_override' AND (p_payload->>'clear_override')::boolean THEN NULL ELSE coalesce(nullif(p_payload->>'engagement_override_reason', ''), engagement_override_reason) END,
        engagement_override_actor_user_id = CASE WHEN p_payload ? 'clear_override' AND (p_payload->>'clear_override')::boolean THEN NULL WHEN p_payload ? 'engagement_override' THEN p_actor_user_id ELSE engagement_override_actor_user_id END,
        engagement_override_at = CASE WHEN p_payload ? 'clear_override' AND (p_payload->>'clear_override')::boolean THEN NULL WHEN p_payload ? 'engagement_override' THEN now() ELSE engagement_override_at END,
        interest_score = coalesce((p_payload->>'interest_score')::smallint, interest_score),
        relationship_quality_score = coalesce((p_payload->>'relationship_quality_score')::smallint, relationship_quality_score),
        updated_at = now()
      WHERE id = (p_payload->>'id')::uuid RETURNING id INTO entity_id_value;
      IF NOT FOUND THEN RAISE EXCEPTION 'crm_relationship_not_found' USING errcode = 'P0002'; END IF;
      entity_type_value := 'relationship';

    WHEN 'activity-evidence.add' THEN
      INSERT INTO public.crm_activities (
        relationship_id, contact_id, organization_id, channel, activity_kind,
        occurred_at, summary, source_reference, actor_user_id, event_type,
        direction, product_scope, confidence, source_id, external_event_id, import_run_id
      ) VALUES (
        nullif(p_payload->>'relationship_id', '')::uuid, nullif(p_payload->>'contact_id', '')::uuid,
        nullif(p_payload->>'organization_id', '')::uuid, p_payload->>'channel',
        coalesce(nullif(p_payload->>'activity_kind', ''), p_payload->>'event_type'),
        coalesce(nullif(p_payload->>'occurred_at', '')::timestamptz, now()), p_payload->>'summary',
        nullif(p_payload->>'source_reference', ''), p_actor_user_id, p_payload->>'event_type',
        coalesce(nullif(p_payload->>'direction', ''), 'unknown'), nullif(p_payload->>'product_scope', ''),
        coalesce(nullif(p_payload->>'confidence', ''), 'observed'), nullif(p_payload->>'source_id', '')::uuid,
        nullif(p_payload->>'external_event_id', ''), nullif(p_payload->>'import_run_id', '')::uuid
      )
      ON CONFLICT (source_id, external_event_id) WHERE source_id IS NOT NULL AND external_event_id IS NOT NULL
      DO UPDATE SET occurred_at = EXCLUDED.occurred_at, summary = EXCLUDED.summary,
        confidence = EXCLUDED.confidence, import_run_id = EXCLUDED.import_run_id
      RETURNING id INTO entity_id_value;
      entity_type_value := 'activity';

    WHEN 'membership-evidence.upsert' THEN
      INSERT INTO public.crm_product_memberships AS target (
        contact_id, product, signup_source, signed_up_at, last_active_at,
        account_created_at, first_active_at, last_created_at, last_published_at,
        last_exported_at, last_purchased_at, last_feedback_at, created_count,
        published_count, export_count, purchase_count, feedback_count,
        freshness, source_id, last_synced_at
      ) VALUES (
        (p_payload->>'contact_id')::uuid, p_payload->>'product', nullif(p_payload->>'signup_source', ''),
        nullif(p_payload->>'signed_up_at', '')::timestamptz, nullif(p_payload->>'last_active_at', '')::timestamptz,
        nullif(p_payload->>'account_created_at', '')::timestamptz, nullif(p_payload->>'first_active_at', '')::timestamptz,
        nullif(p_payload->>'last_created_at', '')::timestamptz, nullif(p_payload->>'last_published_at', '')::timestamptz,
        nullif(p_payload->>'last_exported_at', '')::timestamptz, nullif(p_payload->>'last_purchased_at', '')::timestamptz,
        nullif(p_payload->>'last_feedback_at', '')::timestamptz, coalesce((p_payload->>'created_count')::integer, 0),
        coalesce((p_payload->>'published_count')::integer, 0), coalesce((p_payload->>'export_count')::integer, 0),
        coalesce((p_payload->>'purchase_count')::integer, 0), coalesce((p_payload->>'feedback_count')::integer, 0),
        coalesce(nullif(p_payload->>'freshness', ''), 'unknown'), nullif(p_payload->>'source_id', '')::uuid, now()
      )
      ON CONFLICT (contact_id, product) DO UPDATE SET
        signup_source = EXCLUDED.signup_source, signed_up_at = EXCLUDED.signed_up_at,
        last_active_at = EXCLUDED.last_active_at, account_created_at = EXCLUDED.account_created_at,
        first_active_at = EXCLUDED.first_active_at, last_created_at = EXCLUDED.last_created_at,
        last_published_at = EXCLUDED.last_published_at, last_exported_at = EXCLUDED.last_exported_at,
        last_purchased_at = EXCLUDED.last_purchased_at, last_feedback_at = EXCLUDED.last_feedback_at,
        created_count = EXCLUDED.created_count, published_count = EXCLUDED.published_count,
        export_count = EXCLUDED.export_count, purchase_count = EXCLUDED.purchase_count,
        feedback_count = EXCLUDED.feedback_count, freshness = EXCLUDED.freshness,
        source_id = EXCLUDED.source_id, last_synced_at = now(), updated_at = now()
      RETURNING id INTO entity_id_value;
      entity_type_value := 'membership';

    WHEN 'source-definition.upsert' THEN
      INSERT INTO public.crm_source_definitions AS target (
        source_key, source_kind, title, owner_user_id, refresh_class,
        mapping_version, active, configuration
      ) VALUES (
        p_payload->>'source_key', p_payload->>'source_kind', p_payload->>'title',
        nullif(p_payload->>'owner_user_id', '')::uuid,
        p_payload->>'refresh_class', coalesce((p_payload->>'mapping_version')::integer, 1),
        coalesce((p_payload->>'active')::boolean, true), coalesce(p_payload->'configuration', '{}'::jsonb)
      )
      ON CONFLICT (source_key) DO UPDATE SET
        source_kind = EXCLUDED.source_kind, title = EXCLUDED.title,
        owner_user_id = EXCLUDED.owner_user_id, refresh_class = EXCLUDED.refresh_class,
        mapping_version = EXCLUDED.mapping_version, active = EXCLUDED.active,
        configuration = EXCLUDED.configuration, updated_at = now()
      RETURNING id INTO entity_id_value;
      entity_type_value := 'source-definition';

    WHEN 'sync-run.start' THEN
      INSERT INTO public.crm_sync_runs (
        source_definition_id, cursor_start, window_start, window_end, mapping_version
      ) VALUES (
        (p_payload->>'source_definition_id')::uuid, nullif(p_payload->>'cursor_start', ''),
        nullif(p_payload->>'window_start', '')::timestamptz,
        nullif(p_payload->>'window_end', '')::timestamptz,
        (p_payload->>'mapping_version')::integer
      ) RETURNING id INTO entity_id_value;
      entity_type_value := 'sync-run';

    WHEN 'sync-run.finish' THEN
      UPDATE public.crm_sync_runs SET
        status = p_payload->>'status', finished_at = now(),
        cursor_end = nullif(p_payload->>'cursor_end', ''),
        counts = coalesce(p_payload->'counts', '{}'::jsonb),
        error_category = nullif(p_payload->>'error_category', '')
      WHERE id = (p_payload->>'id')::uuid AND status = 'running'
      RETURNING id INTO entity_id_value;
      IF NOT FOUND THEN RAISE EXCEPTION 'crm_sync_run_not_running' USING errcode = 'P0002'; END IF;
      entity_type_value := 'sync-run';

    WHEN 'attribution.upsert' THEN
      IF p_payload ? 'id' THEN
        UPDATE public.crm_contact_attributions SET
          product = nullif(p_payload->>'product', ''), touch_kind = p_payload->>'touch_kind',
          source = nullif(p_payload->>'source', ''), medium = nullif(p_payload->>'medium', ''),
          campaign = nullif(p_payload->>'campaign', ''), content = nullif(p_payload->>'content', ''),
          referrer = nullif(p_payload->>'referrer', ''), observed_at = (p_payload->>'observed_at')::timestamptz,
          confidence = coalesce(nullif(p_payload->>'confidence', ''), 'observed'),
          source_id = nullif(p_payload->>'source_id', '')::uuid, updated_at = now()
        WHERE id = (p_payload->>'id')::uuid RETURNING id INTO entity_id_value;
      ELSE
        INSERT INTO public.crm_contact_attributions (
          contact_id, product, touch_kind, source, medium, campaign, content,
          referrer, observed_at, confidence, source_id
        ) VALUES (
          (p_payload->>'contact_id')::uuid, nullif(p_payload->>'product', ''), p_payload->>'touch_kind',
          nullif(p_payload->>'source', ''), nullif(p_payload->>'medium', ''),
          nullif(p_payload->>'campaign', ''), nullif(p_payload->>'content', ''),
          nullif(p_payload->>'referrer', ''), (p_payload->>'observed_at')::timestamptz,
          coalesce(nullif(p_payload->>'confidence', ''), 'observed'), nullif(p_payload->>'source_id', '')::uuid
        ) RETURNING id INTO entity_id_value;
      END IF;
      IF NOT FOUND THEN RAISE EXCEPTION 'crm_attribution_not_found' USING errcode = 'P0002'; END IF;
      entity_type_value := 'attribution';

    WHEN 'import-conflict.upsert' THEN
      INSERT INTO public.crm_import_conflicts AS target (
        source_definition_id, sync_run_id, external_record_id, conflict_kind,
        candidate_contact_ids, explanation
      ) VALUES (
        (p_payload->>'source_definition_id')::uuid, nullif(p_payload->>'sync_run_id', '')::uuid,
        p_payload->>'external_record_id', p_payload->>'conflict_kind',
        coalesce(ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'candidate_contact_ids', '[]'::jsonb)))::uuid[], '{}'),
        p_payload->>'explanation'
      )
      ON CONFLICT (source_definition_id, external_record_id, conflict_kind) DO UPDATE SET
        sync_run_id = EXCLUDED.sync_run_id, candidate_contact_ids = EXCLUDED.candidate_contact_ids,
        explanation = EXCLUDED.explanation, updated_at = now()
      RETURNING id INTO entity_id_value;
      entity_type_value := 'import-conflict';

    WHEN 'import-conflict.resolve' THEN
      UPDATE public.crm_import_conflicts SET
        status = p_payload->>'status', resolution = p_payload->>'resolution',
        resolved_by_user_id = p_actor_user_id, resolved_at = now(), updated_at = now()
      WHERE id = (p_payload->>'id')::uuid AND status = 'open'
      RETURNING id INTO entity_id_value;
      IF NOT FOUND THEN RAISE EXCEPTION 'crm_import_conflict_not_open' USING errcode = 'P0002'; END IF;
      entity_type_value := 'import-conflict';

    WHEN 'update.upsert' THEN
      IF p_payload ? 'id' THEN
        UPDATE public.crm_updates SET
          title = p_payload->>'title', product_scope = p_payload->>'product_scope',
          purpose = p_payload->>'purpose', topic = p_payload->>'topic',
          milestone_key = nullif(p_payload->>'milestone_key', ''),
          rule_version = coalesce((p_payload->>'rule_version')::integer, rule_version),
          status = coalesce(nullif(p_payload->>'status', ''), status), updated_at = now()
        WHERE id = (p_payload->>'id')::uuid RETURNING id INTO entity_id_value;
      ELSE
        INSERT INTO public.crm_updates (
          title, product_scope, purpose, topic, milestone_key, rule_version, status, created_by_user_id
        ) VALUES (
          p_payload->>'title', p_payload->>'product_scope', p_payload->>'purpose', p_payload->>'topic',
          nullif(p_payload->>'milestone_key', ''), coalesce((p_payload->>'rule_version')::integer, 1),
          coalesce(nullif(p_payload->>'status', ''), 'draft'), p_actor_user_id
        ) RETURNING id INTO entity_id_value;
      END IF;
      IF NOT FOUND THEN RAISE EXCEPTION 'crm_update_not_found' USING errcode = 'P0002'; END IF;
      entity_type_value := 'update';

    WHEN 'update-recipient.upsert' THEN
      INSERT INTO public.crm_update_recipients AS target (
        update_id, contact_id, decision, reason_codes, eligibility_snapshot, freshness_snapshot
      ) VALUES (
        (p_payload->>'update_id')::uuid, (p_payload->>'contact_id')::uuid,
        p_payload->>'decision',
        coalesce(ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'reason_codes', '[]'::jsonb))), '{}'),
        coalesce(p_payload->'eligibility_snapshot', '{}'::jsonb),
        coalesce(p_payload->'freshness_snapshot', '{}'::jsonb)
      )
      ON CONFLICT (update_id, contact_id) DO UPDATE SET
        decision = EXCLUDED.decision, reason_codes = EXCLUDED.reason_codes,
        eligibility_snapshot = EXCLUDED.eligibility_snapshot,
        freshness_snapshot = EXCLUDED.freshness_snapshot, updated_at = now()
      RETURNING id INTO entity_id_value;
      entity_type_value := 'update-recipient';

    ELSE
      RAISE EXCEPTION 'crm_evidence_operation_not_supported' USING errcode = '22023';
  END CASE;

  result := jsonb_build_object('operation', p_operation, 'id', entity_id_value, 'replayed', false);
  INSERT INTO public.crm_change_events (actor_user_id, entity_type, entity_id, action, after_summary)
  VALUES (p_actor_user_id, entity_type_value, entity_id_value, 'upserted', jsonb_build_object('operation', p_operation));
  UPDATE public.crm_idempotency_records SET response_body = result, completed_at = now() WHERE id = idempotency_id;
  RETURN result;
END;
$$;


ALTER FUNCTION "private"."crm_apply_evidence_mutation"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."crm_apply_import_provenance_mutation"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  actor_is_active boolean;
  api_key_is_active boolean;
  idempotency_id uuid;
  stored_fingerprint text;
  stored_response jsonb;
  contact_row public.crm_contacts%ROWTYPE;
  contact_method_row public.crm_contact_methods%ROWTYPE;
  contact_method_match public.crm_contact_methods%ROWTYPE;
  contact_method_id uuid;
  source_row public.crm_sources%ROWTYPE;
  contact_source_row public.crm_contact_sources%ROWTYPE;
  membership_row public.crm_product_memberships%ROWTYPE;
  permission_row public.crm_communication_permissions%ROWTYPE;
  relationship_rows jsonb := '[]'::jsonb;
  relationship_activity_links jsonb := '[]'::jsonb;
  expected_relationship_ids uuid[];
  current_relationship_ids uuid[];
  deleted_relationship_count integer;
  permission_preserved boolean := false;
  observed_at_value timestamptz;
  result jsonb;
  entity_type_value text;
  entity_id_value uuid;
  change_action text := 'upserted';
  before_summary_value jsonb;
  after_summary_value jsonb;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'crm_api_service_role_required' USING errcode = '42501';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'crm_actor_required' USING errcode = '22023';
  END IF;
  SELECT EXISTS (
    SELECT 1
    FROM public.crm_team_members
    WHERE user_id = p_actor_user_id AND active
  ) INTO actor_is_active;
  IF NOT actor_is_active THEN
    RAISE EXCEPTION 'crm_actor_not_active' USING errcode = '42501';
  END IF;

  IF p_api_key_id IS NULL THEN
    IF p_actor_scope IS DISTINCT FROM 'user:' || p_actor_user_id::text THEN
      RAISE EXCEPTION 'crm_actor_scope_invalid' USING errcode = '22023';
    END IF;
  ELSE
    IF p_actor_scope IS DISTINCT FROM 'api-key:' || p_api_key_id::text THEN
      RAISE EXCEPTION 'crm_actor_scope_invalid' USING errcode = '22023';
    END IF;
    SELECT EXISTS (
      SELECT 1
      FROM public.crm_api_keys
      WHERE id = p_api_key_id
        AND team_member_user_id = p_actor_user_id
        AND revoked_at IS NULL
        AND (expires_at IS NULL OR expires_at > now())
    ) INTO api_key_is_active;
    IF NOT api_key_is_active THEN
      RAISE EXCEPTION 'crm_api_key_not_active' USING errcode = '42501';
    END IF;
  END IF;

  IF p_operation IS NULL
    OR p_operation NOT IN (
      'contact.upsert', 'contact-method.upsert', 'membership-evidence.upsert',
      'permission.upsert', 'source-record.upsert', 'contact-source.upsert',
      'relationship.delete'
    )
  THEN
    RAISE EXCEPTION 'crm_import_provenance_operation_not_supported' USING errcode = '22023';
  END IF;
  IF p_idempotency_key IS NULL
    OR p_idempotency_key <> btrim(p_idempotency_key)
    OR char_length(p_idempotency_key) NOT BETWEEN 8 AND 200
  THEN
    RAISE EXCEPTION 'crm_idempotency_key_invalid' USING errcode = '22023';
  END IF;
  IF p_request_fingerprint IS NULL
    OR p_request_fingerprint !~ '^[a-f0-9]{64}$'
  THEN
    RAISE EXCEPTION 'crm_request_fingerprint_invalid' USING errcode = '22023';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'crm_import_provenance_payload_invalid' USING errcode = '22023';
  END IF;
  IF nullif(p_payload->>'observed_at', '') IS NULL THEN
    RAISE EXCEPTION 'crm_import_provenance_observed_at_required' USING errcode = '22023';
  END IF;
  observed_at_value := (p_payload->>'observed_at')::timestamptz;
  after_summary_value := jsonb_build_object('operation', p_operation);

  INSERT INTO public.crm_idempotency_records (
    actor_scope, actor_user_id, api_key_id, operation, idempotency_key,
    request_fingerprint
  ) VALUES (
    p_actor_scope, p_actor_user_id, p_api_key_id, p_operation,
    p_idempotency_key, p_request_fingerprint
  )
  ON CONFLICT (actor_scope, operation, idempotency_key) DO NOTHING
  RETURNING id INTO idempotency_id;

  IF idempotency_id IS NULL THEN
    SELECT request_fingerprint, response_body
      INTO stored_fingerprint, stored_response
    FROM public.crm_idempotency_records
    WHERE actor_scope = p_actor_scope
      AND operation = p_operation
      AND idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF stored_fingerprint <> p_request_fingerprint THEN
      RAISE EXCEPTION 'crm_idempotency_conflict' USING errcode = '23505';
    END IF;
    IF p_operation = 'relationship.delete' AND EXISTS (
      SELECT 1 FROM public.crm_relationships
      WHERE contact_id = (p_payload->>'contact_id')::uuid
        AND partner_type_key = 'strategic-partner'
    ) THEN
      RAISE EXCEPTION 'crm_import_relationship_delete_replay_drift' USING errcode = '23514';
    END IF;
    RETURN stored_response || jsonb_build_object('replayed', true);
  END IF;

  CASE p_operation
    WHEN 'contact.upsert' THEN
      IF p_payload ? 'id' THEN
        SELECT * INTO contact_row
        FROM public.crm_contacts
        WHERE id = (p_payload->>'id')::uuid
        FOR UPDATE;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'crm_contact_not_found' USING errcode = 'P0002';
        END IF;
        IF nullif(p_payload->>'auth_user_id', '') IS NOT NULL
          AND contact_row.auth_user_id IS NOT NULL
          AND contact_row.auth_user_id IS DISTINCT FROM (p_payload->>'auth_user_id')::uuid
        THEN
          RAISE EXCEPTION 'crm_import_contact_authority_conflict' USING errcode = '23514';
        END IF;
        UPDATE public.crm_contacts AS target SET
          auth_user_id = coalesce(target.auth_user_id, nullif(p_payload->>'auth_user_id', '')::uuid),
          display_name = CASE
            WHEN nullif(btrim(target.display_name), '') IS NULL
              THEN nullif(btrim(p_payload->>'display_name'), '')
            ELSE target.display_name
          END,
          given_name = CASE
            WHEN nullif(btrim(target.given_name), '') IS NULL
              THEN nullif(btrim(p_payload->>'given_name'), '')
            ELSE target.given_name
          END,
          family_name = CASE
            WHEN nullif(btrim(target.family_name), '') IS NULL
              THEN nullif(btrim(p_payload->>'family_name'), '')
            ELSE target.family_name
          END,
          updated_at = now()
        WHERE id = contact_row.id
        RETURNING * INTO contact_row;
      ELSE
        INSERT INTO public.crm_contacts (
          auth_user_id, display_name, given_name, family_name, owner_user_id
        ) VALUES (
          nullif(p_payload->>'auth_user_id', '')::uuid,
          nullif(btrim(p_payload->>'display_name'), ''),
          nullif(btrim(p_payload->>'given_name'), ''),
          nullif(btrim(p_payload->>'family_name'), ''),
          p_actor_user_id
        )
        RETURNING * INTO contact_row;
      END IF;

      entity_type_value := 'contact';
      entity_id_value := contact_row.id;
      result := jsonb_build_object(
        'operation', p_operation,
        'contact', to_jsonb(contact_row),
        'replayed', false
      );

    WHEN 'contact-method.upsert' THEN
      IF nullif(p_payload->>'contact_id', '') IS NULL
        OR nullif(btrim(p_payload->>'kind'), '') IS NULL
        OR nullif(btrim(p_payload->>'value'), '') IS NULL
      THEN
        RAISE EXCEPTION 'crm_import_contact_method_payload_invalid' USING errcode = '22023';
      END IF;

      contact_method_id := NULL;
      FOR contact_method_match IN
        SELECT *
        FROM public.crm_contact_methods
        WHERE kind = p_payload->>'kind'
          AND (
            (
              nullif(p_payload->>'external_id', '') IS NOT NULL
              AND external_id = p_payload->>'external_id'
            )
            OR (
              p_payload->>'kind' IN ('email', 'phone', 'linkedin', 'website')
              AND nullif(p_payload->>'normalized_value', '') IS NOT NULL
              AND normalized_value = p_payload->>'normalized_value'
            )
          )
        ORDER BY id
        FOR UPDATE
      LOOP
        IF contact_method_match.contact_id IS DISTINCT FROM (p_payload->>'contact_id')::uuid
        THEN
          RAISE EXCEPTION 'crm_import_contact_method_authority_conflict' USING errcode = '23514';
        END IF;
        IF contact_method_id IS NOT NULL
          AND contact_method_id IS DISTINCT FROM contact_method_match.id
        THEN
          RAISE EXCEPTION 'crm_import_contact_method_identity_conflict' USING errcode = '23514';
        END IF;
        contact_method_id := contact_method_match.id;
      END LOOP;

      IF contact_method_id IS NULL THEN
        INSERT INTO public.crm_contact_methods (
          contact_id, kind, value, normalized_value, label, is_primary,
          external_id, verification_state, first_seen_at, last_seen_at
        ) VALUES (
          (p_payload->>'contact_id')::uuid,
          p_payload->>'kind',
          p_payload->>'value',
          nullif(p_payload->>'normalized_value', ''),
          nullif(p_payload->>'label', ''),
          false,
          nullif(p_payload->>'external_id', ''),
          coalesce(nullif(p_payload->>'verification_state', ''), 'source-observed'),
          coalesce(nullif(p_payload->>'first_seen_at', '')::timestamptz, observed_at_value),
          coalesce(nullif(p_payload->>'last_seen_at', '')::timestamptz, observed_at_value)
        )
        RETURNING * INTO contact_method_row;
      ELSE
        UPDATE public.crm_contact_methods AS target SET
          first_seen_at = least(
            target.first_seen_at,
            coalesce(nullif(p_payload->>'first_seen_at', '')::timestamptz, observed_at_value)
          ),
          last_seen_at = greatest(
            target.last_seen_at,
            coalesce(nullif(p_payload->>'last_seen_at', '')::timestamptz, observed_at_value)
          ),
          updated_at = now()
        WHERE id = contact_method_id
        RETURNING * INTO contact_method_row;
      END IF;

      entity_type_value := 'contact';
      entity_id_value := contact_method_row.contact_id;
      result := jsonb_build_object(
        'operation', p_operation,
        'contact_method', to_jsonb(contact_method_row),
        'replayed', false
      );

    WHEN 'membership-evidence.upsert' THEN
      IF nullif(p_payload->>'contact_id', '') IS NULL
        OR nullif(btrim(p_payload->>'product'), '') IS NULL
      THEN
        RAISE EXCEPTION 'crm_import_membership_payload_invalid' USING errcode = '22023';
      END IF;

      INSERT INTO public.crm_product_memberships AS target (
        contact_id, product, signup_source, signed_up_at, last_active_at,
        account_created_at, first_active_at, last_created_at, last_published_at,
        last_exported_at, last_purchased_at, last_feedback_at, created_count,
        published_count, export_count, purchase_count, feedback_count,
        freshness, source_id, last_synced_at
      ) VALUES (
        (p_payload->>'contact_id')::uuid, p_payload->>'product',
        nullif(p_payload->>'signup_source', ''),
        nullif(p_payload->>'signed_up_at', '')::timestamptz,
        nullif(p_payload->>'last_active_at', '')::timestamptz,
        nullif(p_payload->>'account_created_at', '')::timestamptz,
        nullif(p_payload->>'first_active_at', '')::timestamptz,
        nullif(p_payload->>'last_created_at', '')::timestamptz,
        nullif(p_payload->>'last_published_at', '')::timestamptz,
        nullif(p_payload->>'last_exported_at', '')::timestamptz,
        nullif(p_payload->>'last_purchased_at', '')::timestamptz,
        nullif(p_payload->>'last_feedback_at', '')::timestamptz,
        coalesce((p_payload->>'created_count')::integer, 0),
        coalesce((p_payload->>'published_count')::integer, 0),
        coalesce((p_payload->>'export_count')::integer, 0),
        coalesce((p_payload->>'purchase_count')::integer, 0),
        coalesce((p_payload->>'feedback_count')::integer, 0),
        coalesce(nullif(p_payload->>'freshness', ''), 'unknown'),
        nullif(p_payload->>'source_id', '')::uuid,
        now()
      )
      ON CONFLICT (contact_id, product) DO UPDATE SET
        signup_source = CASE WHEN p_payload ? 'signup_source' THEN EXCLUDED.signup_source ELSE target.signup_source END,
        signed_up_at = CASE WHEN p_payload ? 'signed_up_at' THEN EXCLUDED.signed_up_at ELSE target.signed_up_at END,
        last_active_at = CASE WHEN p_payload ? 'last_active_at' THEN EXCLUDED.last_active_at ELSE target.last_active_at END,
        account_created_at = CASE WHEN p_payload ? 'account_created_at' THEN EXCLUDED.account_created_at ELSE target.account_created_at END,
        first_active_at = CASE WHEN p_payload ? 'first_active_at' THEN EXCLUDED.first_active_at ELSE target.first_active_at END,
        last_created_at = CASE WHEN p_payload ? 'last_created_at' THEN EXCLUDED.last_created_at ELSE target.last_created_at END,
        last_published_at = CASE WHEN p_payload ? 'last_published_at' THEN EXCLUDED.last_published_at ELSE target.last_published_at END,
        last_exported_at = CASE WHEN p_payload ? 'last_exported_at' THEN EXCLUDED.last_exported_at ELSE target.last_exported_at END,
        last_purchased_at = CASE WHEN p_payload ? 'last_purchased_at' THEN EXCLUDED.last_purchased_at ELSE target.last_purchased_at END,
        last_feedback_at = CASE WHEN p_payload ? 'last_feedback_at' THEN EXCLUDED.last_feedback_at ELSE target.last_feedback_at END,
        created_count = CASE WHEN p_payload ? 'created_count' THEN EXCLUDED.created_count ELSE target.created_count END,
        published_count = CASE WHEN p_payload ? 'published_count' THEN EXCLUDED.published_count ELSE target.published_count END,
        export_count = CASE WHEN p_payload ? 'export_count' THEN EXCLUDED.export_count ELSE target.export_count END,
        purchase_count = CASE WHEN p_payload ? 'purchase_count' THEN EXCLUDED.purchase_count ELSE target.purchase_count END,
        feedback_count = CASE WHEN p_payload ? 'feedback_count' THEN EXCLUDED.feedback_count ELSE target.feedback_count END,
        freshness = CASE WHEN p_payload ? 'freshness' THEN EXCLUDED.freshness ELSE target.freshness END,
        source_id = CASE WHEN p_payload ? 'source_id' THEN EXCLUDED.source_id ELSE target.source_id END,
        last_synced_at = now(),
        updated_at = now()
      RETURNING * INTO membership_row;

      entity_type_value := 'membership';
      entity_id_value := membership_row.id;
      result := jsonb_build_object(
        'operation', p_operation,
        'membership', to_jsonb(membership_row),
        'replayed', false
      );

    WHEN 'relationship.delete' THEN
      IF nullif(p_payload->>'contact_id', '') IS NULL
        OR p_payload->>'partner_type_key' IS DISTINCT FROM 'strategic-partner'
        OR jsonb_typeof(p_payload->'expected_relationship_ids') IS DISTINCT FROM 'array'
        OR jsonb_typeof(p_payload->'expected_relationships') IS DISTINCT FROM 'array'
        OR jsonb_typeof(p_payload->'expected_count') IS DISTINCT FROM 'number'
        OR p_payload->>'expected_count' !~ '^(0|[1-9][0-9]*)$'
        OR jsonb_typeof(p_payload->'expected_activity_links') IS DISTINCT FROM 'array'
        OR jsonb_typeof(p_payload->'expected_activity_link_count') IS DISTINCT FROM 'number'
        OR p_payload->>'expected_activity_link_count' !~ '^(0|[1-9][0-9]*)$'
      THEN
        RAISE EXCEPTION 'crm_import_relationship_delete_payload_invalid' USING errcode = '22023';
      END IF;

      SELECT coalesce(array_agg(value::uuid ORDER BY value::uuid), '{}'::uuid[])
      INTO expected_relationship_ids
      FROM jsonb_array_elements_text(p_payload->'expected_relationship_ids');
      IF cardinality(expected_relationship_ids) <> (p_payload->>'expected_count')::integer
        OR cardinality(expected_relationship_ids) <> jsonb_array_length(p_payload->'expected_relationship_ids')
        OR cardinality(expected_relationship_ids) <> jsonb_array_length(p_payload->'expected_relationships')
        OR to_jsonb(expected_relationship_ids::text[]) IS DISTINCT FROM p_payload->'expected_relationship_ids'
        OR jsonb_array_length(p_payload->'expected_activity_links') <>
          (p_payload->>'expected_activity_link_count')::integer
      THEN
        RAISE EXCEPTION 'crm_import_relationship_delete_expected_count_invalid' USING errcode = '22023';
      END IF;

      WITH locked_relationships AS MATERIALIZED (
        SELECT relationship.*
        FROM public.crm_relationships relationship
        WHERE contact_id = (p_payload->>'contact_id')::uuid
          AND partner_type_key = 'strategic-partner'
        ORDER BY relationship.id
        FOR UPDATE
      )
      SELECT
        coalesce(array_agg(relationship.id ORDER BY relationship.id), '{}'::uuid[]),
        coalesce(jsonb_agg(to_jsonb(relationship) ORDER BY relationship.id), '[]'::jsonb)
      INTO current_relationship_ids, relationship_rows
      FROM locked_relationships relationship;
      WITH locked_activity_links AS MATERIALIZED (
        SELECT activity.id, activity.relationship_id
        FROM public.crm_activities activity
        WHERE activity.relationship_id = ANY(expected_relationship_ids)
        ORDER BY activity.id, activity.relationship_id
        FOR UPDATE
      )
      SELECT coalesce(
        jsonb_agg(
          jsonb_build_object(
            'activity_id', activity.id,
            'relationship_id', activity.relationship_id
          ) ORDER BY activity.id, activity.relationship_id
        ),
        '[]'::jsonb
      )
      INTO relationship_activity_links
      FROM locked_activity_links activity;
      IF current_relationship_ids IS DISTINCT FROM expected_relationship_ids
        OR relationship_rows IS DISTINCT FROM p_payload->'expected_relationships'
        OR relationship_activity_links IS DISTINCT FROM p_payload->'expected_activity_links'
      THEN
        RAISE EXCEPTION 'crm_import_relationship_delete_authority_conflict' USING errcode = '23514';
      END IF;

      DELETE FROM public.crm_relationships
      WHERE contact_id = (p_payload->>'contact_id')::uuid
        AND partner_type_key = 'strategic-partner';
      GET DIAGNOSTICS deleted_relationship_count = ROW_COUNT;
      IF deleted_relationship_count IS DISTINCT FROM
        cardinality(expected_relationship_ids)
      THEN
        RAISE EXCEPTION 'crm_import_relationship_delete_authority_conflict' USING errcode = '23514';
      END IF;

      IF jsonb_array_length(relationship_rows) > 0 THEN
        entity_type_value := 'relationship';
        entity_id_value := (relationship_rows->0->>'id')::uuid;
        change_action := 'deleted';
        result := jsonb_build_object(
          'operation', p_operation,
          'relationship_id', relationship_rows->0->>'id',
          'relationship_ids', p_payload->'expected_relationship_ids',
          'relationships', relationship_rows,
          'activity_links', relationship_activity_links,
          'deleted_count', deleted_relationship_count,
          'activity_link_count', jsonb_array_length(relationship_activity_links),
          'deleted', true,
          'replayed', false
        );
      ELSE
        entity_type_value := 'contact';
        entity_id_value := (p_payload->>'contact_id')::uuid;
        change_action := 'preserved';
        result := jsonb_build_object(
          'operation', p_operation,
          'relationship_ids', '[]'::jsonb,
          'relationships', '[]'::jsonb,
          'activity_links', '[]'::jsonb,
          'deleted_count', 0,
          'activity_link_count', 0,
          'deleted', false,
          'replayed', false
        );
      END IF;
      before_summary_value := jsonb_build_object(
        'relationships', relationship_rows,
        'activity_links', relationship_activity_links
      );
      after_summary_value := jsonb_build_object(
        'operation', p_operation,
        'relationship_ids', p_payload->'expected_relationship_ids',
        'deleted_count', deleted_relationship_count,
        'activity_link_count', jsonb_array_length(relationship_activity_links)
      );

    WHEN 'permission.upsert' THEN
      IF nullif(p_payload->>'contact_id', '') IS NULL
        OR nullif(btrim(p_payload->>'topic'), '') IS NULL
      THEN
        RAISE EXCEPTION 'crm_import_permission_payload_invalid' USING errcode = '22023';
      END IF;

      SELECT EXISTS (
        SELECT 1
        FROM public.crm_communication_permissions
        WHERE contact_id = (p_payload->>'contact_id')::uuid
          AND topic = p_payload->>'topic'
          AND (
            actor_user_id IS NOT NULL
            OR (
              state IN ('denied', 'unsubscribed')
              AND coalesce(nullif(p_payload->>'state', ''), 'unknown') NOT IN ('denied', 'unsubscribed')
            )
          )
      ) INTO permission_preserved;

      INSERT INTO public.crm_communication_permissions AS target (
        contact_id, topic, state, basis, captured_at, source_id, actor_user_id
      ) VALUES (
        (p_payload->>'contact_id')::uuid,
        p_payload->>'topic',
        coalesce(nullif(p_payload->>'state', ''), 'unknown'),
        nullif(p_payload->>'basis', ''),
        coalesce(nullif(p_payload->>'captured_at', '')::timestamptz, observed_at_value),
        nullif(p_payload->>'source_id', '')::uuid,
        NULL
      )
      ON CONFLICT (contact_id, topic) DO UPDATE SET
        state = CASE
          WHEN target.actor_user_id IS NOT NULL
            OR (
              target.state IN ('denied', 'unsubscribed')
              AND EXCLUDED.state NOT IN ('denied', 'unsubscribed')
            )
            THEN target.state
          ELSE EXCLUDED.state
        END,
        basis = CASE WHEN permission_preserved THEN target.basis ELSE EXCLUDED.basis END,
        captured_at = CASE WHEN permission_preserved THEN target.captured_at ELSE EXCLUDED.captured_at END,
        source_id = CASE WHEN permission_preserved THEN target.source_id ELSE EXCLUDED.source_id END,
        actor_user_id = target.actor_user_id,
        updated_at = CASE WHEN permission_preserved THEN target.updated_at ELSE now() END
      RETURNING * INTO permission_row;

      entity_type_value := 'permission';
      entity_id_value := permission_row.id;
      result := jsonb_build_object(
        'operation', p_operation,
        'permission', to_jsonb(permission_row),
        'preserved_authority', permission_preserved,
        'replayed', false
      );

    WHEN 'source-record.upsert' THEN
      IF nullif(btrim(p_payload->>'source_kind'), '') IS NULL
        OR nullif(btrim(p_payload->>'title'), '') IS NULL
        OR nullif(btrim(p_payload->>'external_record_id'), '') IS NULL
        OR (p_payload ? 'metadata' AND jsonb_typeof(p_payload->'metadata') <> 'object')
        OR (
          nullif(p_payload->>'payload_hash', '') IS NOT NULL
          AND p_payload->>'payload_hash' !~ '^[a-f0-9]{64}$'
        )
      THEN
        RAISE EXCEPTION 'crm_source_record_payload_invalid' USING errcode = '22023';
      END IF;

      INSERT INTO public.crm_sources AS target (
        source_kind, title, source_url, external_record_id, payload_hash,
        metadata, first_seen_at, last_seen_at
      ) VALUES (
        btrim(p_payload->>'source_kind'), btrim(p_payload->>'title'),
        nullif(btrim(p_payload->>'source_url'), ''),
        btrim(p_payload->>'external_record_id'),
        nullif(p_payload->>'payload_hash', ''),
        coalesce(p_payload->'metadata', '{}'::jsonb),
        observed_at_value, observed_at_value
      )
      ON CONFLICT (source_kind, external_record_id)
        WHERE external_record_id IS NOT NULL
      DO UPDATE SET
        title = EXCLUDED.title,
        source_url = CASE
          WHEN p_payload ? 'source_url' THEN EXCLUDED.source_url
          ELSE target.source_url
        END,
        payload_hash = CASE
          WHEN p_payload ? 'payload_hash' THEN EXCLUDED.payload_hash
          ELSE target.payload_hash
        END,
        metadata = CASE
          WHEN p_payload ? 'metadata' THEN EXCLUDED.metadata
          ELSE target.metadata
        END,
        first_seen_at = least(target.first_seen_at, EXCLUDED.first_seen_at),
        last_seen_at = greatest(target.last_seen_at, EXCLUDED.last_seen_at),
        updated_at = now()
      RETURNING * INTO source_row;

      entity_type_value := 'source-record';
      entity_id_value := source_row.id;
      result := jsonb_build_object(
        'operation', p_operation,
        'source_record', jsonb_build_object(
          'id', source_row.id,
          'first_seen_at', source_row.first_seen_at,
          'last_seen_at', source_row.last_seen_at
        ),
        'replayed', false
      );

    WHEN 'contact-source.upsert' THEN
      IF nullif(p_payload->>'contact_id', '') IS NULL
        OR nullif(p_payload->>'source_id', '') IS NULL
      THEN
        RAISE EXCEPTION 'crm_contact_source_payload_invalid' USING errcode = '22023';
      END IF;

      INSERT INTO public.crm_contact_sources AS target (
        contact_id, source_id, first_seen_at, last_seen_at
      ) VALUES (
        (p_payload->>'contact_id')::uuid,
        (p_payload->>'source_id')::uuid,
        observed_at_value,
        observed_at_value
      )
      ON CONFLICT (contact_id, source_id) DO UPDATE SET
        first_seen_at = least(target.first_seen_at, EXCLUDED.first_seen_at),
        last_seen_at = greatest(target.last_seen_at, EXCLUDED.last_seen_at),
        updated_at = now()
      RETURNING * INTO contact_source_row;

      entity_type_value := 'contact-source';
      entity_id_value := contact_source_row.id;
      result := jsonb_build_object(
        'operation', p_operation,
        'contact_source', jsonb_build_object(
          'id', contact_source_row.id,
          'contact_id', contact_source_row.contact_id,
          'source_id', contact_source_row.source_id,
          'first_seen_at', contact_source_row.first_seen_at,
          'last_seen_at', contact_source_row.last_seen_at
        ),
        'replayed', false
      );
  END CASE;

  INSERT INTO public.crm_change_events (
    actor_user_id, entity_type, entity_id, action, before_summary, after_summary
  ) VALUES (
    p_actor_user_id, entity_type_value, entity_id_value, change_action,
    before_summary_value, after_summary_value
  );

  UPDATE public.crm_idempotency_records
  SET response_body = result, completed_at = now()
  WHERE id = idempotency_id;

  RETURN result;
END;
$_$;


ALTER FUNCTION "private"."crm_apply_import_provenance_mutation"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."crm_apply_mutation"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  actor_role text;
  is_admin boolean;
  idempotency_id uuid;
  stored_fingerprint text;
  stored_response jsonb;
  contact_row public.crm_contacts%ROWTYPE;
  organization_row public.crm_organizations%ROWTYPE;
  relationship_row public.crm_relationships%ROWTYPE;
  permission_row public.crm_communication_permissions%ROWTYPE;
  api_key_row public.crm_api_keys%ROWTYPE;
  result jsonb;
  entity_type_value text;
  entity_id_value uuid;
  action_value text;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'crm_api_service_role_required' USING errcode = '42501';
  END IF;

  SELECT role INTO actor_role
  FROM public.crm_team_members
  WHERE user_id = p_actor_user_id AND active;

  IF actor_role IS NULL THEN
    RAISE EXCEPTION 'crm_actor_not_active' USING errcode = '42501';
  END IF;
  is_admin := actor_role = 'admin';

  INSERT INTO public.crm_idempotency_records (
    actor_scope, actor_user_id, api_key_id, operation, idempotency_key,
    request_fingerprint
  ) VALUES (
    p_actor_scope, p_actor_user_id, p_api_key_id, p_operation,
    p_idempotency_key, p_request_fingerprint
  )
  ON CONFLICT (actor_scope, operation, idempotency_key) DO NOTHING
  RETURNING id INTO idempotency_id;

  IF idempotency_id IS NULL THEN
    SELECT id, request_fingerprint, response_body
      INTO idempotency_id, stored_fingerprint, stored_response
    FROM public.crm_idempotency_records
    WHERE actor_scope = p_actor_scope
      AND operation = p_operation
      AND idempotency_key = p_idempotency_key
    FOR UPDATE;

    IF stored_fingerprint <> p_request_fingerprint THEN
      RAISE EXCEPTION 'crm_idempotency_conflict' USING errcode = '23505';
    END IF;
    RETURN stored_response || jsonb_build_object('replayed', true);
  END IF;

  CASE p_operation
    WHEN 'contact.upsert' THEN
      IF p_payload ? 'id' THEN
        UPDATE public.crm_contacts AS target
        SET auth_user_id = coalesce(nullif(p_payload->>'auth_user_id', '')::uuid, target.auth_user_id),
            display_name = coalesce(nullif(p_payload->>'display_name', ''), target.display_name),
            given_name = coalesce(nullif(p_payload->>'given_name', ''), target.given_name),
            family_name = coalesce(nullif(p_payload->>'family_name', ''), target.family_name),
            private_notes = coalesce(nullif(p_payload->>'private_notes', ''), target.private_notes),
            owner_user_id = coalesce(nullif(p_payload->>'owner_user_id', '')::uuid, target.owner_user_id),
            updated_at = now()
        WHERE id = (p_payload->>'id')::uuid
        RETURNING * INTO contact_row;
        IF NOT FOUND THEN RAISE EXCEPTION 'crm_contact_not_found' USING errcode = 'P0002'; END IF;
      ELSE
        INSERT INTO public.crm_contacts (
        id, auth_user_id, display_name, given_name, family_name, private_notes,
        owner_user_id
      ) VALUES (
        gen_random_uuid(),
        nullif(p_payload->>'auth_user_id', '')::uuid,
        nullif(p_payload->>'display_name', ''),
        nullif(p_payload->>'given_name', ''),
        nullif(p_payload->>'family_name', ''),
        nullif(p_payload->>'private_notes', ''),
        coalesce(nullif(p_payload->>'owner_user_id', '')::uuid, p_actor_user_id)
        ) RETURNING * INTO contact_row;
      END IF;
      result := jsonb_build_object('operation', p_operation, 'contact', to_jsonb(contact_row));
      entity_type_value := 'contact';
      entity_id_value := contact_row.id;
      action_value := 'upserted';

    WHEN 'contact.archive' THEN
      IF NOT is_admin THEN RAISE EXCEPTION 'crm_admin_required' USING errcode = '42501'; END IF;
      UPDATE public.crm_contacts
      SET archived_at = now(), updated_at = now()
      WHERE id = (p_payload->>'contact_id')::uuid
      RETURNING * INTO contact_row;
      IF NOT FOUND THEN RAISE EXCEPTION 'crm_contact_not_found' USING errcode = 'P0002'; END IF;
      result := jsonb_build_object('operation', p_operation, 'contact', to_jsonb(contact_row));
      entity_type_value := 'contact'; entity_id_value := contact_row.id; action_value := 'archived';

    WHEN 'contact.delete' THEN
      IF NOT is_admin THEN RAISE EXCEPTION 'crm_admin_required' USING errcode = '42501'; END IF;
      SELECT * INTO contact_row FROM public.crm_contacts WHERE id = (p_payload->>'contact_id')::uuid FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'crm_contact_not_found' USING errcode = 'P0002'; END IF;
      DELETE FROM public.crm_contacts WHERE id = contact_row.id;
      result := jsonb_build_object('operation', p_operation, 'contact_id', contact_row.id);
      entity_type_value := 'contact'; entity_id_value := contact_row.id; action_value := 'deleted';

    WHEN 'contact.merge' THEN
      IF NOT is_admin THEN RAISE EXCEPTION 'crm_admin_required' USING errcode = '42501'; END IF;
      SELECT * INTO contact_row
      FROM public.crm_merge_contacts(
        (p_payload->>'source_contact_id')::uuid,
        (p_payload->>'target_contact_id')::uuid,
        nullif(p_payload->>'summary', '')
      );
      UPDATE public.crm_change_events
      SET actor_user_id = p_actor_user_id
      WHERE id = (
        SELECT id FROM public.crm_change_events
        WHERE entity_type = 'contact' AND entity_id = contact_row.id
          AND action = 'merged' AND actor_user_id IS NULL
        ORDER BY created_at DESC, id DESC LIMIT 1
      );
      result := jsonb_build_object('operation', p_operation, 'contact', to_jsonb(contact_row));
      entity_type_value := 'contact'; entity_id_value := contact_row.id; action_value := 'merge-requested';

    WHEN 'organization.upsert' THEN
      IF p_payload ? 'id' THEN
        UPDATE public.crm_organizations AS target
        SET name = coalesce(nullif(p_payload->>'name', ''), target.name),
            normalized_name = coalesce(nullif(lower(p_payload->>'normalized_name'), ''), target.normalized_name),
            domain = coalesce(nullif(lower(p_payload->>'domain'), ''), target.domain),
            website = coalesce(nullif(p_payload->>'website', ''), target.website),
            private_notes = coalesce(nullif(p_payload->>'private_notes', ''), target.private_notes),
            owner_user_id = coalesce(nullif(p_payload->>'owner_user_id', '')::uuid, target.owner_user_id),
            updated_at = now()
        WHERE id = (p_payload->>'id')::uuid
        RETURNING * INTO organization_row;
        IF NOT FOUND THEN RAISE EXCEPTION 'crm_organization_not_found' USING errcode = 'P0002'; END IF;
      ELSE
        INSERT INTO public.crm_organizations (
        id, name, normalized_name, domain, website, private_notes, owner_user_id
      ) VALUES (
        gen_random_uuid(),
        nullif(p_payload->>'name', ''),
        nullif(lower(p_payload->>'normalized_name'), ''),
        nullif(lower(p_payload->>'domain'), ''),
        nullif(p_payload->>'website', ''),
        nullif(p_payload->>'private_notes', ''),
        coalesce(nullif(p_payload->>'owner_user_id', '')::uuid, p_actor_user_id)
        ) RETURNING * INTO organization_row;
      END IF;
      result := jsonb_build_object('operation', p_operation, 'organization', to_jsonb(organization_row));
      entity_type_value := 'organization'; entity_id_value := organization_row.id; action_value := 'upserted';

    WHEN 'relationship.upsert' THEN
      IF p_payload ? 'id' THEN
        UPDATE public.crm_relationships AS target
        SET partner_type_key = coalesce(nullif(p_payload->>'partner_type_key', ''), target.partner_type_key),
            status = coalesce(nullif(p_payload->>'status', ''), target.status),
            priority = coalesce(nullif(p_payload->>'priority', ''), target.priority),
            owner_user_id = coalesce(nullif(p_payload->>'owner_user_id', '')::uuid, target.owner_user_id),
            next_action = CASE WHEN coalesce((p_payload->>'clear_next_action')::boolean, false) THEN NULL ELSE coalesce(nullif(p_payload->>'next_action', ''), target.next_action) END,
            follow_up_at = CASE WHEN coalesce((p_payload->>'clear_follow_up_at')::boolean, false) THEN NULL ELSE coalesce(nullif(p_payload->>'follow_up_at', '')::timestamptz, target.follow_up_at) END,
            milestone_key = coalesce(nullif(p_payload->>'milestone_key', ''), target.milestone_key),
            last_contacted_at = coalesce(nullif(p_payload->>'last_contacted_at', '')::timestamptz, target.last_contacted_at),
            updated_at = now()
        WHERE id = (p_payload->>'id')::uuid
        RETURNING * INTO relationship_row;
        IF NOT FOUND THEN RAISE EXCEPTION 'crm_relationship_not_found' USING errcode = 'P0002'; END IF;
      ELSE
        INSERT INTO public.crm_relationships (
        id, contact_id, organization_id, partner_type_key, status, priority,
        owner_user_id, next_action, follow_up_at, milestone_key, last_contacted_at
      ) VALUES (
        coalesce(nullif(p_payload->>'id', '')::uuid, gen_random_uuid()),
        nullif(p_payload->>'contact_id', '')::uuid,
        nullif(p_payload->>'organization_id', '')::uuid,
        nullif(p_payload->>'partner_type_key', ''),
        coalesce(nullif(p_payload->>'status', ''), 'new'),
        coalesce(nullif(p_payload->>'priority', ''), 'normal'),
        coalesce(nullif(p_payload->>'owner_user_id', '')::uuid, p_actor_user_id),
        nullif(p_payload->>'next_action', ''),
        nullif(p_payload->>'follow_up_at', '')::timestamptz,
        nullif(p_payload->>'milestone_key', ''),
        nullif(p_payload->>'last_contacted_at', '')::timestamptz
      )
        RETURNING * INTO relationship_row;
      END IF;
      result := jsonb_build_object('operation', p_operation, 'relationship', to_jsonb(relationship_row));
      entity_type_value := 'relationship'; entity_id_value := relationship_row.id; action_value := 'upserted';

    WHEN 'activity.add' THEN
      INSERT INTO public.crm_activities (
        relationship_id, contact_id, organization_id, channel, activity_kind,
        occurred_at, summary, source_reference, actor_user_id
      ) VALUES (
        nullif(p_payload->>'relationship_id', '')::uuid,
        nullif(p_payload->>'contact_id', '')::uuid,
        nullif(p_payload->>'organization_id', '')::uuid,
        nullif(p_payload->>'channel', ''),
        nullif(p_payload->>'activity_kind', ''),
        coalesce(nullif(p_payload->>'occurred_at', '')::timestamptz, now()),
        nullif(p_payload->>'summary', ''),
        nullif(p_payload->>'source_reference', ''),
        p_actor_user_id
      ) RETURNING id INTO entity_id_value;
      result := jsonb_build_object('operation', p_operation, 'activity_id', entity_id_value);
      entity_type_value := 'activity'; action_value := 'added';

    WHEN 'permission.upsert' THEN
      INSERT INTO public.crm_communication_permissions AS target (
        contact_id, topic, state, basis, captured_at, source_id, actor_user_id
      ) VALUES (
        (p_payload->>'contact_id')::uuid,
        nullif(p_payload->>'topic', ''),
        coalesce(nullif(p_payload->>'state', ''), 'unknown'),
        nullif(p_payload->>'basis', ''),
        coalesce(nullif(p_payload->>'captured_at', '')::timestamptz, now()),
        nullif(p_payload->>'source_id', '')::uuid,
        p_actor_user_id
      )
      ON CONFLICT (contact_id, topic) DO UPDATE SET
        state = EXCLUDED.state,
        basis = EXCLUDED.basis,
        captured_at = EXCLUDED.captured_at,
        source_id = EXCLUDED.source_id,
        actor_user_id = EXCLUDED.actor_user_id,
        updated_at = now()
      RETURNING * INTO permission_row;
      result := jsonb_build_object('operation', p_operation, 'permission', to_jsonb(permission_row));
      entity_type_value := 'permission'; entity_id_value := permission_row.id; action_value := 'upserted';

    WHEN 'partner-type.upsert' THEN
      IF NOT is_admin THEN RAISE EXCEPTION 'crm_admin_required' USING errcode = '42501'; END IF;
      INSERT INTO public.crm_partner_types AS target (key, label, product_scope, active)
      VALUES (
        nullif(p_payload->>'key', ''),
        nullif(p_payload->>'label', ''),
        nullif(p_payload->>'product_scope', ''),
        coalesce((p_payload->>'active')::boolean, true)
      )
      ON CONFLICT (key) DO UPDATE SET
        label = EXCLUDED.label,
        product_scope = EXCLUDED.product_scope,
        active = EXCLUDED.active,
        updated_at = now();
      result := jsonb_build_object('operation', p_operation, 'partner_type_key', p_payload->>'key');
      entity_type_value := 'partner-type'; entity_id_value := NULL; action_value := 'upserted';

    WHEN 'api-key.create', 'api-key.rotate' THEN
      IF NOT is_admin THEN RAISE EXCEPTION 'crm_admin_required' USING errcode = '42501'; END IF;
      IF p_operation = 'api-key.rotate' THEN
        UPDATE public.crm_api_keys SET revoked_at = now()
        WHERE id = (p_payload->>'previous_key_id')::uuid AND revoked_at IS NULL;
        IF NOT FOUND THEN RAISE EXCEPTION 'crm_api_key_not_found' USING errcode = 'P0002'; END IF;
      END IF;
      INSERT INTO public.crm_api_keys (team_member_user_id, token_hash, label, scopes, expires_at)
      VALUES (
        coalesce(nullif(p_payload->>'team_member_user_id', '')::uuid, p_actor_user_id),
        nullif(p_payload->>'token_hash', ''),
        nullif(p_payload->>'label', ''),
        coalesce(ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'scopes', '[]'::jsonb))), '{}'::text[]),
        nullif(p_payload->>'expires_at', '')::timestamptz
      ) RETURNING * INTO api_key_row;
      result := jsonb_build_object('operation', p_operation, 'api_key', jsonb_build_object(
        'id', api_key_row.id, 'label', api_key_row.label, 'scopes', api_key_row.scopes,
        'expires_at', api_key_row.expires_at
      ));
      entity_type_value := 'api-key'; entity_id_value := api_key_row.id; action_value := 'issued';

    WHEN 'api-key.revoke' THEN
      IF NOT is_admin THEN RAISE EXCEPTION 'crm_admin_required' USING errcode = '42501'; END IF;
      UPDATE public.crm_api_keys SET revoked_at = now()
      WHERE id = (p_payload->>'api_key_id')::uuid AND revoked_at IS NULL
      RETURNING * INTO api_key_row;
      IF NOT FOUND THEN RAISE EXCEPTION 'crm_api_key_not_found' USING errcode = 'P0002'; END IF;
      result := jsonb_build_object('operation', p_operation, 'api_key_id', api_key_row.id);
      entity_type_value := 'api-key'; entity_id_value := api_key_row.id; action_value := 'revoked';

    ELSE
      RAISE EXCEPTION 'crm_operation_not_supported' USING errcode = '22023';
  END CASE;

  INSERT INTO public.crm_change_events (
    actor_user_id, entity_type, entity_id, action, after_summary
  ) VALUES (
    p_actor_user_id, entity_type_value, entity_id_value, action_value,
    jsonb_build_object('operation', p_operation)
  );

  result := result || jsonb_build_object('replayed', false);
  UPDATE public.crm_idempotency_records
  SET response_body = result, completed_at = now()
  WHERE id = idempotency_id;

  RETURN result;
END;
$$;


ALTER FUNCTION "private"."crm_apply_mutation"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."crm_assert_mutation_lease"("p_lease_token" "uuid", "p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  actor_is_active boolean;
  api_key_is_active boolean;
  lease_row public.crm_mutation_leases%ROWTYPE;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'crm_api_service_role_required' USING errcode = '42501';
  END IF;
  SELECT * INTO lease_row
  FROM public.crm_mutation_leases
  WHERE lease_key = 'global'
    AND lease_token = p_lease_token
    AND lease_expires_at > now()
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'crm_mutation_lease_stale' USING errcode = '55P03';
  END IF;
  IF lease_row.actor_user_id IS DISTINCT FROM p_actor_user_id
    OR lease_row.actor_scope IS DISTINCT FROM p_actor_scope
  THEN
    RAISE EXCEPTION 'crm_mutation_lease_actor_mismatch' USING errcode = '22023';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.crm_team_members
    WHERE user_id = p_actor_user_id AND active
  ) INTO actor_is_active;
  IF NOT actor_is_active THEN
    RAISE EXCEPTION 'crm_actor_not_active' USING errcode = '42501';
  END IF;

  IF p_api_key_id IS NULL THEN
    IF p_actor_scope IS DISTINCT FROM 'user:' || p_actor_user_id::text THEN
      RAISE EXCEPTION 'crm_actor_scope_invalid' USING errcode = '22023';
    END IF;
  ELSE
    IF p_actor_scope IS DISTINCT FROM 'api-key:' || p_api_key_id::text THEN
      RAISE EXCEPTION 'crm_actor_scope_invalid' USING errcode = '22023';
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM public.crm_api_keys
      WHERE id = p_api_key_id
        AND team_member_user_id = p_actor_user_id
        AND revoked_at IS NULL
        AND (expires_at IS NULL OR expires_at > now())
    ) INTO api_key_is_active;
    IF NOT api_key_is_active THEN
      RAISE EXCEPTION 'crm_api_key_not_active' USING errcode = '42501';
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION "private"."crm_assert_mutation_lease"("p_lease_token" "uuid", "p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."crm_record_import_authority_preservation"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  authority_kind text := p_payload->>'authority_kind';
  contact_id_value uuid := nullif(p_payload->>'contact_id', '')::uuid;
  entity_id_value uuid := nullif(p_payload->>'entity_id', '')::uuid;
  entity_type_value text := p_payload->>'entity_type';
  idempotency_id uuid;
  partner_type_value text := nullif(p_payload->>'partner_type_key', '');
  result jsonb;
  stored_fingerprint text;
  stored_response jsonb;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'crm_api_service_role_required' USING errcode = '42501';
  END IF;
  IF p_operation IS DISTINCT FROM 'import-authority.preserve' THEN
    RAISE EXCEPTION 'crm_evidence_operation_not_supported' USING errcode = '22023';
  END IF;
  -- Validate and lock the exact preserved authority before both first apply and
  -- idempotent replay so a concurrent direct deletion cannot race the receipt.
  IF authority_kind = 'organization' THEN
    IF entity_type_value IS DISTINCT FROM 'organization' THEN
      RAISE EXCEPTION 'crm_import_preserved_authority_changed' USING errcode = '23514';
    END IF;
    PERFORM 1 FROM public.crm_organizations
    WHERE id = entity_id_value
    FOR KEY SHARE;
  ELSIF authority_kind = 'organization-affiliation' THEN
    IF entity_type_value IS DISTINCT FROM 'organization' THEN
      RAISE EXCEPTION 'crm_import_preserved_authority_changed' USING errcode = '23514';
    END IF;
    PERFORM 1 FROM public.crm_organization_contacts
    WHERE organization_id = entity_id_value AND contact_id = contact_id_value
    FOR KEY SHARE;
  ELSIF authority_kind IN ('relationship', 'relationship-evidence') THEN
    IF entity_type_value IS DISTINCT FROM 'relationship' THEN
      RAISE EXCEPTION 'crm_import_preserved_authority_changed' USING errcode = '23514';
    END IF;
    PERFORM 1 FROM public.crm_relationships
    WHERE id = entity_id_value
      AND contact_id = contact_id_value
      AND partner_type_key = partner_type_value
    FOR KEY SHARE;
  ELSE
    RAISE EXCEPTION 'crm_import_preserved_authority_kind_invalid' USING errcode = '22023';
  END IF;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'crm_import_preserved_authority_changed' USING errcode = '23514';
  END IF;

  INSERT INTO public.crm_idempotency_records (
    actor_scope, actor_user_id, api_key_id, operation, idempotency_key,
    request_fingerprint
  ) VALUES (
    p_actor_scope, p_actor_user_id, p_api_key_id, p_operation,
    p_idempotency_key, p_request_fingerprint
  )
  ON CONFLICT (actor_scope, operation, idempotency_key) DO NOTHING
  RETURNING id INTO idempotency_id;

  IF idempotency_id IS NULL THEN
    SELECT request_fingerprint, response_body
      INTO stored_fingerprint, stored_response
    FROM public.crm_idempotency_records
    WHERE actor_scope = p_actor_scope
      AND operation = p_operation
      AND idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF stored_fingerprint <> p_request_fingerprint THEN
      RAISE EXCEPTION 'crm_idempotency_conflict' USING errcode = '23505';
    END IF;
    RETURN stored_response || jsonb_build_object('replayed', true);
  END IF;

  result := jsonb_build_object(
    'operation', p_operation,
    'preserved', jsonb_build_object(
      'authority_kind', authority_kind,
      'entity_id', entity_id_value,
      'entity_type', entity_type_value
    ),
    'replayed', false
  );
  INSERT INTO public.crm_change_events (
    actor_user_id, entity_type, entity_id, action, after_summary
  ) VALUES (
    p_actor_user_id, entity_type_value, entity_id_value,
    'preserved-import-authority',
    jsonb_build_object(
      'operation', p_operation,
      'authority_kind', authority_kind,
      'contact_id', contact_id_value,
      'partner_type_key', partner_type_value
    )
  );
  UPDATE public.crm_idempotency_records
  SET response_body = result, completed_at = now()
  WHERE id = idempotency_id;
  RETURN result;
END;
$$;


ALTER FUNCTION "private"."crm_record_import_authority_preservation"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."feature_flag_request_user_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT auth.uid();
$$;


ALTER FUNCTION "private"."feature_flag_request_user_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_feature_flag_catalog"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'feature flags must be archived, not deleted'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.key IS DISTINCT FROM NEW.key THEN
    RAISE EXCEPTION 'feature flag keys are immutable'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.created_at IS DISTINCT FROM NEW.created_at
    OR (
      OLD.created_by_user_id IS DISTINCT FROM NEW.created_by_user_id
      AND NEW.created_by_user_id IS NOT NULL
    )
  THEN
    RAISE EXCEPTION 'feature flag creation metadata is immutable'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."guard_feature_flag_catalog"() OWNER TO "feature_flag_owner";


CREATE OR REPLACE FUNCTION "private"."guard_feature_user_enablement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_user_id uuid := (SELECT private.feature_flag_request_user_id());
BEGIN
  -- ON DELETE SET NULL actor-FK maintenance may update this row immediately
  -- before the target user's ON DELETE CASCADE removes the assignment. It is
  -- trusted database maintenance, not an assignment state transition.
  IF TG_OP = 'UPDATE'
    AND OLD.enabled IS NOT DISTINCT FROM NEW.enabled
    AND OLD.user_id IS NOT DISTINCT FROM NEW.user_id
    AND OLD.feature_flag_id IS NOT DISTINCT FROM NEW.feature_flag_id
    AND OLD.change_reason IS NOT DISTINCT FROM NEW.change_reason
    AND OLD.updated_via IS NOT DISTINCT FROM NEW.updated_via
    AND (
      OLD.created_by_user_id IS DISTINCT FROM NEW.created_by_user_id
      OR OLD.updated_by_user_id IS DISTINCT FROM NEW.updated_by_user_id
    )
    AND (
      OLD.created_by_user_id IS NOT DISTINCT FROM NEW.created_by_user_id
      OR NEW.created_by_user_id IS NULL
    )
    AND (
      OLD.updated_by_user_id IS NOT DISTINCT FROM NEW.updated_by_user_id
      OR NEW.updated_by_user_id IS NULL
    )
  THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND (
    OLD.user_id IS DISTINCT FROM NEW.user_id
    OR OLD.feature_flag_id IS DISTINCT FROM NEW.feature_flag_id
    OR OLD.created_at IS DISTINCT FROM NEW.created_at
    OR OLD.created_by_user_id IS DISTINCT FROM NEW.created_by_user_id
  ) THEN
    RAISE EXCEPTION 'feature assignment identity and creation metadata are immutable'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.updated_via = 'self_service' THEN
    IF v_actor_user_id IS NULL
      OR NEW.user_id IS DISTINCT FROM v_actor_user_id
      OR NEW.updated_by_user_id IS DISTINCT FROM v_actor_user_id
      OR NOT private.is_current_soundsculpt_staff()
      OR NOT EXISTS (
        SELECT 1
        FROM public.feature_flags AS flags
        WHERE flags.id = NEW.feature_flag_id
          AND flags.self_service_enabled
          AND flags.archived_at IS NULL
      )
    THEN
      RAISE EXCEPTION 'self-service feature assignment is not permitted'
        USING ERRCODE = '42501';
    END IF;

    IF TG_OP = 'INSERT'
      AND NEW.created_by_user_id IS DISTINCT FROM v_actor_user_id
    THEN
      RAISE EXCEPTION 'self-service assignment creator must be the current user'
        USING ERRCODE = '42501';
    END IF;

    IF NEW.change_reason IS DISTINCT FROM 'Internal self-service toggle' THEN
      RAISE EXCEPTION 'self-service change reason is server controlled'
        USING ERRCODE = '42501';
    END IF;
  ELSIF NEW.updated_via = 'admin' THEN
    IF NEW.updated_by_user_id IS NULL
      OR NEW.change_reason IS NULL
      OR btrim(NEW.change_reason) = ''
      OR (TG_OP = 'INSERT' AND NEW.created_by_user_id IS NULL)
    THEN
      RAISE EXCEPTION 'admin feature changes require a validated actor and reason'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."guard_feature_user_enablement"() OWNER TO "feature_flag_owner";


CREATE OR REPLACE FUNCTION "private"."is_current_soundsculpt_staff"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  SELECT EXISTS (
    SELECT 1
    FROM private.feature_flag_auth_users AS users
    WHERE users.id = (SELECT private.feature_flag_request_user_id())
      AND users.email_confirmed_at IS NOT NULL
      AND users.deleted_at IS NULL
      AND users.email ~* '^[^@]+@soundsculpt[.]app$'
  );
$_$;


ALTER FUNCTION "private"."is_current_soundsculpt_staff"() OWNER TO "feature_flag_owner";


CREATE OR REPLACE FUNCTION "private"."promote_sip_instruments_v2_without_runtime_manifest_v1"("p_instrument_rows" "jsonb", "p_promotion_links" "jsonb", "p_sample_path_construct_rows" "jsonb", "p_legacy_alias_rows" "jsonb", "p_sip_tag_rows" "jsonb", "p_v2_tag_rows" "jsonb", "p_upload_status_rows" "jsonb", "p_metadata_rows" "jsonb", "p_sample_playback_cue_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  base_result jsonb := '{}'::jsonb;
  cue_upsert_count integer := 0;
  cue_delete_count integer := 0;
BEGIN
  p_sample_playback_cue_rows :=
    COALESCE(p_sample_playback_cue_rows, '[]'::jsonb);

  IF jsonb_typeof(p_sample_playback_cue_rows) <> 'array' THEN
    RAISE EXCEPTION 'sample_playback_cue_rows must be a JSON array'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_sample_playback_cue_rows) AS item(row_json)
    WHERE NOT (
      item.row_json ? 'sample_original_path_id'
      OR item.row_json ? 'original_sample_id'
    )
  ) THEN
    RAISE EXCEPTION
      'sample_playback_cue_rows require sample_original_path_id or original_sample_id'
      USING ERRCODE = '22023';
  END IF;

  base_result := public.promote_sip_instruments_v2(
    p_instrument_rows,
    p_promotion_links,
    p_sample_path_construct_rows,
    p_legacy_alias_rows,
    p_sip_tag_rows,
    p_v2_tag_rows,
    p_upload_status_rows,
    p_metadata_rows
  );

  IF jsonb_array_length(p_sample_playback_cue_rows) > 0 THEN
    WITH raw_rows AS (
      SELECT
        COALESCE(row_data.sample_original_path_id, row_data.original_sample_id)
          AS sample_original_path_id,
        row_data.sync_point_ms,
        row_data.loop_start_offset_ms,
        row_data.loop_end_offset_ms,
        row_data.sync_point_status,
        row_data.loop_start_status,
        row_data.loop_end_status,
        row_data.swell_eligible,
        row_data.crash_eligible,
        item.row_ordinal
      FROM jsonb_array_elements(p_sample_playback_cue_rows) WITH ORDINALITY
        AS item(row_json, row_ordinal)
      CROSS JOIN LATERAL jsonb_to_record(item.row_json) AS row_data(
        sample_original_path_id uuid,
        original_sample_id uuid,
        sync_point_ms integer,
        loop_start_offset_ms integer,
        loop_end_offset_ms integer,
        sync_point_status text,
        loop_start_status text,
        loop_end_status text,
        swell_eligible boolean,
        crash_eligible boolean
      )
      WHERE COALESCE(row_data.sample_original_path_id, row_data.original_sample_id)
        IS NOT NULL
    ),
    deduped AS (
      SELECT DISTINCT ON (sample_original_path_id)
        sample_original_path_id,
        CASE
          WHEN sync_point_status = 'found' AND sync_point_ms >= 0
            THEN sync_point_ms
          ELSE NULL
        END AS raw_sync_point_ms,
        CASE
          WHEN loop_start_status = 'found' AND loop_start_offset_ms >= 0
            THEN loop_start_offset_ms
          ELSE NULL
        END AS raw_loop_start_offset_ms,
        CASE
          WHEN loop_end_status = 'found' AND loop_end_offset_ms >= 0
            THEN loop_end_offset_ms
          ELSE NULL
        END AS raw_loop_end_offset_ms,
        swell_eligible,
        crash_eligible
      FROM raw_rows
      ORDER BY sample_original_path_id, row_ordinal DESC
    ),
    prepared AS (
      SELECT
        sample_original_path_id,
        raw_sync_point_ms AS sync_point_ms,
        CASE
          WHEN raw_loop_start_offset_ms IS NOT NULL
           AND raw_loop_end_offset_ms IS NOT NULL
           AND raw_loop_end_offset_ms <= raw_loop_start_offset_ms
            THEN NULL
          ELSE raw_loop_start_offset_ms
        END AS loop_start_offset_ms,
        CASE
          WHEN raw_loop_start_offset_ms IS NOT NULL
           AND raw_loop_end_offset_ms IS NOT NULL
           AND raw_loop_end_offset_ms <= raw_loop_start_offset_ms
            THEN NULL
          ELSE raw_loop_end_offset_ms
        END AS loop_end_offset_ms,
        swell_eligible,
        crash_eligible
      FROM deduped
    ),
    mapped AS (
      SELECT
        spc.id AS sample_path_construct_id,
        prepared.sync_point_ms,
        prepared.loop_start_offset_ms,
        prepared.loop_end_offset_ms,
        prepared.swell_eligible,
        prepared.crash_eligible
      FROM prepared
      JOIN public.sample_path_constructs spc
        ON spc.sample_original_path_id = prepared.sample_original_path_id
    ),
    upserted AS (
      INSERT INTO public.sample_playback_cues (
        sample_path_construct_id,
        sync_point_ms,
        loop_start_offset_ms,
        loop_end_offset_ms,
        swell_eligible,
        crash_eligible
      )
      SELECT
        sample_path_construct_id,
        sync_point_ms,
        loop_start_offset_ms,
        loop_end_offset_ms,
        swell_eligible,
        crash_eligible
      FROM mapped
      WHERE sync_point_ms IS NOT NULL
        OR loop_start_offset_ms IS NOT NULL
        OR loop_end_offset_ms IS NOT NULL
      ON CONFLICT (sample_path_construct_id) DO UPDATE SET
        sync_point_ms = EXCLUDED.sync_point_ms,
        loop_start_offset_ms = EXCLUDED.loop_start_offset_ms,
        loop_end_offset_ms = EXCLUDED.loop_end_offset_ms,
        swell_eligible = EXCLUDED.swell_eligible,
        crash_eligible = EXCLUDED.crash_eligible,
        updated_at = now()
      RETURNING 1
    )
    SELECT count(*) INTO cue_upsert_count
    FROM upserted;

    WITH raw_rows AS (
      SELECT
        COALESCE(row_data.sample_original_path_id, row_data.original_sample_id)
          AS sample_original_path_id,
        row_data.sync_point_ms,
        row_data.loop_start_offset_ms,
        row_data.loop_end_offset_ms,
        row_data.sync_point_status,
        row_data.loop_start_status,
        row_data.loop_end_status,
        item.row_ordinal
      FROM jsonb_array_elements(p_sample_playback_cue_rows) WITH ORDINALITY
        AS item(row_json, row_ordinal)
      CROSS JOIN LATERAL jsonb_to_record(item.row_json) AS row_data(
        sample_original_path_id uuid,
        original_sample_id uuid,
        sync_point_ms integer,
        loop_start_offset_ms integer,
        loop_end_offset_ms integer,
        sync_point_status text,
        loop_start_status text,
        loop_end_status text
      )
      WHERE COALESCE(row_data.sample_original_path_id, row_data.original_sample_id)
        IS NOT NULL
    ),
    deduped AS (
      SELECT DISTINCT ON (sample_original_path_id)
        sample_original_path_id,
        CASE
          WHEN sync_point_status = 'found' AND sync_point_ms >= 0
            THEN sync_point_ms
          ELSE NULL
        END AS raw_sync_point_ms,
        CASE
          WHEN loop_start_status = 'found' AND loop_start_offset_ms >= 0
            THEN loop_start_offset_ms
          ELSE NULL
        END AS raw_loop_start_offset_ms,
        CASE
          WHEN loop_end_status = 'found' AND loop_end_offset_ms >= 0
            THEN loop_end_offset_ms
          ELSE NULL
        END AS raw_loop_end_offset_ms
      FROM raw_rows
      ORDER BY sample_original_path_id, row_ordinal DESC
    ),
    prepared AS (
      SELECT
        sample_original_path_id,
        raw_sync_point_ms AS sync_point_ms,
        CASE
          WHEN raw_loop_start_offset_ms IS NOT NULL
           AND raw_loop_end_offset_ms IS NOT NULL
           AND raw_loop_end_offset_ms <= raw_loop_start_offset_ms
            THEN NULL
          ELSE raw_loop_start_offset_ms
        END AS loop_start_offset_ms,
        CASE
          WHEN raw_loop_start_offset_ms IS NOT NULL
           AND raw_loop_end_offset_ms IS NOT NULL
           AND raw_loop_end_offset_ms <= raw_loop_start_offset_ms
            THEN NULL
          ELSE raw_loop_end_offset_ms
        END AS loop_end_offset_ms
      FROM deduped
    ),
    mapped AS (
      SELECT
        spc.id AS sample_path_construct_id,
        prepared.sync_point_ms,
        prepared.loop_start_offset_ms,
        prepared.loop_end_offset_ms
      FROM prepared
      JOIN public.sample_path_constructs spc
        ON spc.sample_original_path_id = prepared.sample_original_path_id
      WHERE prepared.sync_point_ms IS NULL
        AND prepared.loop_start_offset_ms IS NULL
        AND prepared.loop_end_offset_ms IS NULL
    ),
    deleted AS (
      DELETE FROM public.sample_playback_cues existing
      USING mapped
      WHERE existing.sample_path_construct_id = mapped.sample_path_construct_id
      RETURNING 1
    )
    SELECT count(*) INTO cue_delete_count
    FROM deleted;
  END IF;

  RETURN base_result || jsonb_build_object(
    'samplePlaybackCuesUpserted', cue_upsert_count,
    'samplePlaybackCuesDeleted', cue_delete_count
  );
END;
$$;


ALTER FUNCTION "private"."promote_sip_instruments_v2_without_runtime_manifest_v1"("p_instrument_rows" "jsonb", "p_promotion_links" "jsonb", "p_sample_path_construct_rows" "jsonb", "p_legacy_alias_rows" "jsonb", "p_sip_tag_rows" "jsonb", "p_v2_tag_rows" "jsonb", "p_upload_status_rows" "jsonb", "p_metadata_rows" "jsonb", "p_sample_playback_cue_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."promote_sip_instruments_v2_without_runtime_manifest_v1"("p_instrument_rows" "jsonb", "p_promotion_links" "jsonb", "p_sample_path_construct_rows" "jsonb", "p_legacy_alias_rows" "jsonb", "p_sip_tag_rows" "jsonb", "p_v2_tag_rows" "jsonb", "p_upload_status_rows" "jsonb", "p_metadata_rows" "jsonb", "p_sample_playback_cue_rows" "jsonb") IS 'Promotes SIP review rows and reviewed playback cues, preserving source sync/loop values plus swell/crash eligibility.';



CREATE OR REPLACE FUNCTION "private"."reject_feature_flag_audit_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'feature flag audit events are immutable'
    USING ERRCODE = '55000';
END;
$$;


ALTER FUNCTION "private"."reject_feature_flag_audit_mutation"() OWNER TO "feature_flag_owner";


CREATE OR REPLACE FUNCTION "private"."sip_apply_semantic_regroup_pre_alias_detach_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_expected_snapshot" "jsonb", "p_expected_parent_source_snapshot" "jsonb", "p_expected_target_snapshot" "jsonb", "p_expected_target_metadata_snapshot" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_child jsonb;
  v_child_v2 public.instruments_v2%ROWTYPE;
  v_parent_staging public.sip_review_instrument%ROWTYPE;
  v_child_staging_id uuid;
  v_child_v2_id uuid;
  v_source_group_key text;
  v_locked_lease_id uuid;
BEGIN
  -- Completed receipts replay through the unchanged primitive without
  -- reconstructing transient adoption state.
  IF EXISTS (
    SELECT 1
    FROM public.sip_semantic_regroup_receipts receipt
    WHERE receipt.provider_slug = btrim(p_contributor_slug)
      AND receipt.manifest_hash = p_manifest_hash
  ) THEN
    RETURN private.sip_apply_semantic_regroup_pre_orphan_v1(
      p_contributor_slug,
      p_lease_id,
      p_lease_token,
      p_manifest_hash,
      p_manifest,
      p_expected_snapshot,
      p_expected_parent_source_snapshot,
      p_expected_target_snapshot,
      p_expected_target_metadata_snapshot,
      p_applied_by
    );
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  SELECT lease.id INTO v_locked_lease_id
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
    FOR UPDATE;
  IF v_locked_lease_id IS NULL THEN
    RAISE EXCEPTION 'semantic regroup requires an active provider lease'
      USING ERRCODE = '42501';
  END IF;

  -- Match the existing primitive's global lock order before creating any
  -- adoption lineage. The wrapped primitive reacquires these compatible locks
  -- and performs its normal snapshot validation before the transaction commits.
  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_promotion_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_playback_cues IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_instrument_tags IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_tag IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_upload_status IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_disposition IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_semantic_regroup_receipts IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE MODE;
  LOCK TABLE public.sip_review_legacy_map IN SHARE MODE;

  SELECT staging.* INTO v_parent_staging
  FROM public.sip_review_instrument staging
  WHERE staging.id = (p_manifest#>>'{parent,stagingInstrumentId}')::uuid
    AND staging.source_contributor_slug = btrim(p_contributor_slug)
  FOR UPDATE;
  IF v_parent_staging.id IS NULL OR v_parent_staging.source_sip_instrument_id IS NULL THEN
    RAISE EXCEPTION 'semantic regroup orphan adoption parent changed'
      USING ERRCODE = '55000';
  END IF;

  FOR v_child IN
    SELECT value
    FROM jsonb_array_elements(p_manifest->'children') value
    WHERE COALESCE(value->>'targetMode', 'create') = 'existing'
  LOOP
    v_child_staging_id := (v_child->>'stagingInstrumentId')::uuid;
    v_child_v2_id := (v_child->>'instrumentV2Id')::uuid;

    SELECT instrument.* INTO v_child_v2
    FROM public.instruments_v2 instrument
    WHERE instrument.id = v_child_v2_id
    FOR UPDATE;

    -- Normal published/staged existing targets continue unchanged.
    IF v_child_v2.id IS NOT NULL AND v_child_v2.published THEN
      CONTINUE;
    END IF;

    IF v_child_v2.id IS NULL
       OR v_child_v2.published
       OR v_child_v2.name IS DISTINCT FROM v_child->>'name'
       OR v_child_v2.contributor_id IS DISTINCT FROM v_parent_staging.contributor_id
       OR v_child_v2.asset_role::text IS DISTINCT FROM 'playable_sample'
       OR v_child_v2.engine_type IS DISTINCT FROM (CASE
            WHEN v_child->>'addressMode' = 'pitchless'
              THEN 'non_tonal'::public.instrument_engine_type
            ELSE 'tonal'::public.instrument_engine_type
          END)
       OR v_child_v2.playback_type IS DISTINCT FROM
            (v_child->>'playbackType')::public.instrument_playback_type
       OR v_child_v2.polyphony_type IS DISTINCT FROM
            (v_child#>>'{metadataPolicy,polyphonyType}')::public.instrument_polyphony_type
       OR v_child_v2.instrument_family IS DISTINCT FROM
            v_child#>>'{metadataPolicy,instrumentFamily}'
       OR v_child_v2.instrument_type IS DISTINCT FROM
            v_child#>>'{metadataPolicy,instrumentType}'
       OR v_child_v2.collection IS DISTINCT FROM
            NULLIF(v_child#>>'{metadataPolicy,collection}', '')
       OR v_child_v2.articulation IS DISTINCT FROM
            NULLIF(v_child#>>'{metadataPolicy,articulation}', '')
       OR v_child_v2.effect IS DISTINCT FROM
            NULLIF(v_child#>>'{metadataPolicy,effect}', '')
       OR v_child_v2.range_lower IS DISTINCT FROM (v_child->>'rangeLower')::integer
       OR v_child_v2.range_upper IS DISTINCT FROM (v_child->>'rangeUpper')::integer
       OR v_child_v2.single_pitch IS DISTINCT FROM NULLIF(v_child->>'singlePitch', '')::integer
       OR v_child_v2.file_path_reference IS DISTINCT FROM v_child->>'filePathReference'
       OR cardinality(COALESCE(v_child_v2.articulations, ARRAY[]::uuid[])) <> 0
       OR cardinality(COALESCE(v_child_v2.effects_instruments, ARRAY[]::uuid[])) <> 0
       OR v_child_v2.legato_transition IS NOT NULL
       OR ARRAY(
         SELECT source_id
         FROM unnest(COALESCE(v_child_v2.original_sample_ids, ARRAY[]::uuid[])) source_id
         ORDER BY source_id
       ) IS DISTINCT FROM ARRAY(
         SELECT (source->>'sampleOriginalPathId')::uuid
         FROM jsonb_array_elements(v_child->'sources') source
         ORDER BY (source->>'sampleOriginalPathId')::uuid
       )
       OR v_child#>>'{metadataPolicy,mode}' IS DISTINCT FROM 'preserve_existing'
       OR v_child#>>'{metadataPolicy,reviewStatus}' IS DISTINCT FROM 'reviewed'
       OR EXISTS (
         SELECT 1 FROM public.sample_path_constructs construct
         WHERE construct.instrument_v2_id = v_child_v2_id
       )
       OR EXISTS (
         SELECT 1 FROM public.sip_review_instrument staging
         WHERE staging.id = v_child_staging_id
            OR staging.original_file_path_reference = v_child->>'filePathReference'
       )
       OR EXISTS (
         SELECT 1 FROM public.sip_review_promotion_map promotion
         WHERE promotion.instrument_v2_id = v_child_v2_id
            OR promotion.sip_review_instrument_id = v_child_staging_id
       )
       OR EXISTS (
         SELECT 1 FROM public.instrument_v2_legacy_map legacy
         WHERE legacy.instrument_v2_id = v_child_v2_id
       )
       OR EXISTS (
         SELECT 1 FROM public.instruments_v2 owner
         WHERE owner.id <> v_child_v2_id
           AND (
             v_child_v2_id = ANY(COALESCE(owner.articulations, ARRAY[]::uuid[]))
             OR v_child_v2_id = ANY(COALESCE(owner.effects_instruments, ARRAY[]::uuid[]))
             OR owner.legato_transition = v_child_v2_id
           )
       )
       OR ARRAY(
         SELECT tag.tag_id
         FROM public.instrument_v2_instrument_tags tag
         WHERE tag.instrument_v2_id = v_child_v2_id
         ORDER BY tag.tag_id
       ) IS DISTINCT FROM ARRAY(
         SELECT tag_id::uuid
         FROM jsonb_array_elements_text(v_child#>'{metadataPolicy,tagIds}') tag_id
         ORDER BY tag_id::uuid
       ) THEN
      RAISE EXCEPTION 'semantic regroup unpublished target is not an exact adoptable orphan'
        USING ERRCODE = '55000';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.sip_fleet_provider_leases lease
      WHERE lease.id = v_locked_lease_id
        AND lease.provider_slug = btrim(p_contributor_slug)
        AND lease.lease_token = p_lease_token
        AND lease.released_at IS NULL
        AND lease.lease_expires_at > clock_timestamp()
    ) THEN
      RAISE EXCEPTION 'semantic regroup provider lease expired before cutover'
        USING ERRCODE = '42501';
    END IF;

    v_source_group_key :=
      COALESCE(v_parent_staging.source_group_key, v_parent_staging.id::text)
      || '::semantic-regroup-adopt::' || v_child_staging_id::text;

    INSERT INTO public.sip_review_instrument (
      id, source_sip_instrument_id, source_contributor_slug, source_group_key,
      name, engine_type, playback_type, polyphony_type, instrument_family,
      instrument_type, contributor_id, collection, pitch_contents,
      velocity_layers, pitch_content_config, range_lower, range_upper,
      single_pitch, gain, sustain_crop_time, original_file_path_reference,
      original_file_name_references, articulations, effects_instruments,
      mic_positions, original_sample_ids, published, is_retired,
      split_parent_sip_review_instrument_id, staged_by, round_robins,
      velocity_layer_map, articulation, effect, asset_role
    ) VALUES (
      v_child_staging_id,
      v_parent_staging.source_sip_instrument_id,
      v_parent_staging.source_contributor_slug,
      v_source_group_key,
      v_child_v2.name,
      v_child_v2.engine_type,
      v_child_v2.playback_type,
      v_child_v2.polyphony_type,
      v_child_v2.instrument_family,
      v_child_v2.instrument_type,
      v_child_v2.contributor_id,
      v_child_v2.collection,
      v_child_v2.pitch_contents,
      v_child_v2.velocity_layers,
      v_child_v2.pitch_content_config,
      v_child_v2.range_lower,
      v_child_v2.range_upper,
      v_child_v2.single_pitch,
      v_child_v2.gain,
      v_child_v2.sustain_crop_time,
      v_child_v2.file_path_reference,
      v_child_v2.file_name_references,
      ARRAY[]::uuid[],
      ARRAY[]::uuid[],
      v_child_v2.mic_positions,
      ARRAY(
        SELECT (source->>'sampleOriginalPathId')::uuid
        FROM jsonb_array_elements(v_child->'sources') source
      ),
      false,
      false,
      v_parent_staging.id,
      p_applied_by,
      v_child_v2.round_robins,
      '{}'::jsonb,
      v_child_v2.articulation,
      v_child_v2.effect,
      v_child_v2.asset_role
    );

    INSERT INTO public.sip_review_promotion_map (
      sip_review_instrument_id, instrument_v2_id, promoted_by, notes
    ) VALUES (
      v_child_staging_id,
      v_child_v2_id,
      p_applied_by,
      'semantic-regroup-orphan-adoption:' || p_manifest_hash
    );

    INSERT INTO public.sip_review_instrument_tag (
      sip_review_instrument_id, tag_id, source
    )
    SELECT
      v_child_staging_id,
      tag.tag_id,
      'semantic-regroup-orphan-adoption:' || p_manifest_hash
    FROM public.instrument_v2_instrument_tags tag
    WHERE tag.instrument_v2_id = v_child_v2_id;

    -- The existing primitive validates only published existing targets. Hold
    -- ACCESS EXCLUSIVE through the already-fenced transaction while disabling
    -- only the deterministic-publication guard for this exact validated state
    -- flip. Trigger DDL and the row update are transactional: any error restores
    -- both the trigger and the unpublished row automatically.
    EXECUTE 'ALTER TABLE public.instruments_v2 DISABLE TRIGGER guard_sip_publish_state_transition_v1';
    UPDATE public.instruments_v2
    SET published = true, updated_at = now()
    WHERE id = v_child_v2_id AND NOT published;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'semantic regroup unpublished target changed during adoption'
        USING ERRCODE = '55000';
    END IF;
    EXECUTE 'ALTER TABLE public.instruments_v2 ENABLE TRIGGER guard_sip_publish_state_transition_v1';
  END LOOP;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = v_locked_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'semantic regroup provider lease expired before cutover'
      USING ERRCODE = '42501';
  END IF;

  RETURN private.sip_apply_semantic_regroup_pre_orphan_v1(
    p_contributor_slug,
    p_lease_id,
    p_lease_token,
    p_manifest_hash,
    p_manifest,
    p_expected_snapshot,
    p_expected_parent_source_snapshot,
    p_expected_target_snapshot,
    p_expected_target_metadata_snapshot,
    p_applied_by
  );
END;
$$;


ALTER FUNCTION "private"."sip_apply_semantic_regroup_pre_alias_detach_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_expected_snapshot" "jsonb", "p_expected_parent_source_snapshot" "jsonb", "p_expected_target_snapshot" "jsonb", "p_expected_target_metadata_snapshot" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."sip_apply_semantic_regroup_pre_orphan_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_expected_snapshot" "jsonb", "p_expected_parent_source_snapshot" "jsonb", "p_expected_target_snapshot" "jsonb", "p_expected_target_metadata_snapshot" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_policy jsonb := p_manifest->'relationshipRemapPolicy';
  v_relationships jsonb := p_expected_parent_source_snapshot->'relationships';
  v_parent_v2_id uuid;
  v_parent_staging_id uuid;
  v_parent_source_sip_id uuid;
  v_target_v2_id uuid;
  v_target_staging_id uuid;
  v_target_source_sip_id uuid;
  v_target_mode text;
  v_expected_production jsonb;
  v_expected_staging jsonb;
  v_live_production jsonb;
  v_live_staging jsonb;
  v_parent_articulations uuid[];
  v_parent_staging_articulations uuid[];
  v_result jsonb;
  v_relationship_rows integer := 0;
  v_changed integer := 0;
BEGIN
  -- Omitted policy is the exact historical behavior and receipt format.
  IF v_policy IS NULL THEN
    RETURN public.sip_publish_coordinator_apply_semantic_regroup_plain_v1(
      p_contributor_slug,
      p_lease_id,
      p_lease_token,
      p_manifest_hash,
      p_manifest,
      p_expected_snapshot,
      p_expected_parent_source_snapshot,
      p_expected_target_snapshot,
      p_expected_target_metadata_snapshot,
      p_applied_by
    );
  END IF;

  IF jsonb_typeof(v_policy) IS DISTINCT FROM 'object'
     OR v_policy->>'mode' IS DISTINCT FROM 'replace_parent_articulation_with_child'
     OR COALESCE(v_policy->>'targetInstrumentV2Id', '') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     OR COALESCE(v_policy->>'targetStagingInstrumentId', '') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     OR jsonb_typeof(v_relationships) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_manifest->'children') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest->'children') IS DISTINCT FROM 1
     OR jsonb_typeof(v_relationships->'production') IS DISTINCT FROM 'array'
     OR jsonb_typeof(v_relationships->'staging') IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_relationships->'production') > 250
     OR jsonb_array_length(v_relationships->'staging') > 250 THEN
    RAISE EXCEPTION 'semantic regroup relationship policy or snapshot is invalid'
      USING ERRCODE = '22023';
  END IF;

  v_parent_v2_id := (p_manifest#>>'{parent,instrumentV2Id}')::uuid;
  v_parent_staging_id := (p_manifest#>>'{parent,stagingInstrumentId}')::uuid;
  v_target_v2_id := (v_policy->>'targetInstrumentV2Id')::uuid;
  v_target_staging_id := (v_policy->>'targetStagingInstrumentId')::uuid;

  SELECT COALESCE(child->>'targetMode', 'create')
  INTO v_target_mode
  FROM jsonb_array_elements(p_manifest->'children') child
  WHERE (child->>'instrumentV2Id')::uuid = v_target_v2_id
    AND (child->>'stagingInstrumentId')::uuid = v_target_staging_id;

  IF v_target_v2_id = v_parent_v2_id
     OR v_target_staging_id = v_parent_staging_id
     OR v_target_mode IS NULL
     OR v_target_mode NOT IN ('create', 'existing')
     OR 1 IS DISTINCT FROM (
       SELECT count(*)
       FROM jsonb_array_elements(p_manifest->'children') child
       WHERE (child->>'instrumentV2Id')::uuid = v_target_v2_id
         AND (child->>'stagingInstrumentId')::uuid = v_target_staging_id
     ) THEN
    RAISE EXCEPTION 'semantic regroup relationship target is not one exact manifest child'
      USING ERRCODE = '22023';
  END IF;

  -- Preserve the original provider admission order before acquiring the broad
  -- relationship fences. The nested implementation revalidates the lease and
  -- active-run state immediately before its first durable mutation.
  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug), 0));
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'semantic regroup requires an active provider lease'
      USING ERRCODE = '42501';
  END IF;

  -- An exact replay must not compare the pre-cutover relationship snapshot to
  -- post-cutover state. The original implementation owns the immutable receipt
  -- comparison and idempotent result.
  IF EXISTS (
    SELECT 1
    FROM public.sip_semantic_regroup_receipts receipt
    WHERE receipt.provider_slug = p_contributor_slug
      AND receipt.manifest_hash = p_manifest_hash
  ) THEN
    RETURN public.sip_publish_coordinator_apply_semantic_regroup_plain_v1(
      p_contributor_slug,
      p_lease_id,
      p_lease_token,
      p_manifest_hash,
      p_manifest,
      p_expected_snapshot,
      p_expected_parent_source_snapshot,
      p_expected_target_snapshot,
      p_expected_target_metadata_snapshot,
      p_applied_by
    );
  END IF;

  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;

  -- Close the race where an exact concurrent invocation committed while this
  -- transaction waited for the relationship table fences.
  IF EXISTS (
    SELECT 1
    FROM public.sip_semantic_regroup_receipts receipt
    WHERE receipt.provider_slug = p_contributor_slug
      AND receipt.manifest_hash = p_manifest_hash
  ) THEN
    RETURN public.sip_publish_coordinator_apply_semantic_regroup_plain_v1(
      p_contributor_slug,
      p_lease_id,
      p_lease_token,
      p_manifest_hash,
      p_manifest,
      p_expected_snapshot,
      p_expected_parent_source_snapshot,
      p_expected_target_snapshot,
      p_expected_target_metadata_snapshot,
      p_applied_by
    );
  END IF;

  SELECT staging.source_sip_instrument_id
  INTO v_parent_source_sip_id
  FROM public.sip_review_instrument staging
  WHERE staging.id = v_parent_staging_id
    AND staging.source_contributor_slug = p_contributor_slug
  FOR UPDATE;
  IF v_parent_source_sip_id IS NULL THEN
    RAISE EXCEPTION 'semantic regroup relationship parent identity changed'
      USING ERRCODE = '55000';
  END IF;

  IF COALESCE(v_target_mode, 'create') = 'create' THEN
    -- Create-target staging rows intentionally preserve the provider source
    -- identity. The staging articulation replacement is therefore an identity
    -- transform, while the production UUID changes.
    v_target_source_sip_id := v_parent_source_sip_id;
  ELSE
    SELECT staging.source_sip_instrument_id
    INTO v_target_source_sip_id
    FROM public.sip_review_instrument staging
    WHERE staging.id = v_target_staging_id
      AND staging.source_contributor_slug = p_contributor_slug
    FOR UPDATE;
    IF v_target_source_sip_id IS NULL THEN
      RAISE EXCEPTION 'semantic regroup relationship target identity changed'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  v_expected_production := v_relationships->'production';
  v_expected_staging := v_relationships->'staging';

  IF EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_expected_production) expected
       WHERE jsonb_typeof(expected) IS DISTINCT FROM 'object'
          OR COALESCE(expected->>'instrumentV2Id', '') !~
             '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
          OR jsonb_typeof(expected->'articulations') IS DISTINCT FROM 'array'
          OR jsonb_typeof(expected->'effectsInstruments') IS DISTINCT FROM 'array'
          OR COALESCE(jsonb_typeof(expected->'legatoTransition'), 'missing')
               NOT IN ('null', 'string')
     ) OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_expected_staging) expected
       WHERE jsonb_typeof(expected) IS DISTINCT FROM 'object'
          OR COALESCE(expected->>'stagingInstrumentId', '') !~
             '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
          OR COALESCE(expected->>'sourceSipInstrumentId', '') !~
             '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
          OR jsonb_typeof(expected->'articulations') IS DISTINCT FROM 'array'
          OR jsonb_typeof(expected->'effectsInstruments') IS DISTINCT FROM 'array'
          OR COALESCE(jsonb_typeof(expected->'legatoTransition'), 'missing')
               NOT IN ('null', 'string')
     ) OR jsonb_array_length(v_expected_production) IS DISTINCT FROM (
       SELECT count(DISTINCT expected->>'instrumentV2Id')
       FROM jsonb_array_elements(v_expected_production) expected
     ) OR jsonb_array_length(v_expected_staging) IS DISTINCT FROM (
       SELECT count(DISTINCT expected->>'stagingInstrumentId')
       FROM jsonb_array_elements(v_expected_staging) expected
     ) THEN
    RAISE EXCEPTION 'semantic regroup relationship snapshot identity is invalid or duplicated'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'instrumentV2Id', relation.id,
    'articulations', COALESCE(to_jsonb(relation.articulations), '[]'::jsonb),
    'effectsInstruments', COALESCE(to_jsonb(relation.effects_instruments), '[]'::jsonb),
    'legatoTransition', to_jsonb(relation.legato_transition)
  ) ORDER BY relation.id::text), '[]'::jsonb)
  INTO v_live_production
  FROM public.instruments_v2 relation
  WHERE relation.id IN (v_parent_v2_id, v_target_v2_id)
     OR COALESCE(relation.articulations, ARRAY[]::uuid[]) && ARRAY[v_parent_v2_id, v_target_v2_id];

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'stagingInstrumentId', relation.id,
    'sourceSipInstrumentId', relation.source_sip_instrument_id,
    'articulations', COALESCE(to_jsonb(relation.articulations), '[]'::jsonb),
    'effectsInstruments', COALESCE(to_jsonb(relation.effects_instruments), '[]'::jsonb),
    'legatoTransition', to_jsonb(relation.legato_transition)
  ) ORDER BY relation.id::text), '[]'::jsonb)
  INTO v_live_staging
  FROM public.sip_review_instrument relation
  WHERE relation.id IN (v_parent_staging_id, v_target_staging_id)
     OR COALESCE(relation.articulations, ARRAY[]::uuid[]) &&
          ARRAY[v_parent_source_sip_id, v_target_source_sip_id];

  IF v_expected_production IS DISTINCT FROM v_live_production
     OR v_expected_staging IS DISTINCT FROM v_live_staging THEN
    RAISE EXCEPTION 'semantic regroup relationship snapshot changed under lock'
      USING ERRCODE = '55000';
  END IF;

  -- This extension is intentionally articulation-only. Effects and legato
  -- involving either endpoint, or owned by either endpoint, remain blockers.
  IF EXISTS (
       SELECT 1 FROM public.instruments_v2 relation
       WHERE (relation.id IN (v_parent_v2_id, v_target_v2_id) AND (
                cardinality(COALESCE(relation.effects_instruments, ARRAY[]::uuid[])) > 0
                OR relation.legato_transition IS NOT NULL
             ))
          OR COALESCE(relation.effects_instruments, ARRAY[]::uuid[]) &&
               ARRAY[v_parent_v2_id, v_target_v2_id]
          OR relation.legato_transition IN (v_parent_v2_id, v_target_v2_id)
     ) OR EXISTS (
       SELECT 1 FROM public.sip_review_instrument relation
       WHERE (relation.id IN (v_parent_staging_id, v_target_staging_id) AND (
                cardinality(COALESCE(relation.effects_instruments, ARRAY[]::uuid[])) > 0
                OR relation.legato_transition IS NOT NULL
             ))
          OR COALESCE(relation.effects_instruments, ARRAY[]::uuid[]) &&
               ARRAY[v_parent_source_sip_id, v_target_source_sip_id]
          OR relation.legato_transition IN (v_parent_staging_id, v_target_staging_id)
     ) THEN
    RAISE EXCEPTION 'semantic regroup articulation remap rejects effects or legato relationships'
      USING ERRCODE = '55000';
  END IF;

  SELECT ARRAY(
    SELECT (member#>>'{}')::uuid
    FROM jsonb_array_elements(parent->'articulations') member
  ) INTO v_parent_articulations
  FROM jsonb_array_elements(v_expected_production) parent
  WHERE parent->>'instrumentV2Id' = v_parent_v2_id::text;
  SELECT ARRAY(
    SELECT (member#>>'{}')::uuid
    FROM jsonb_array_elements(parent->'articulations') member
  ) INTO v_parent_staging_articulations
  FROM jsonb_array_elements(v_expected_staging) parent
  WHERE parent->>'stagingInstrumentId' = v_parent_staging_id::text;
  IF v_parent_articulations IS NULL OR v_parent_staging_articulations IS NULL THEN
    RAISE EXCEPTION 'semantic regroup relationship snapshot omits the parent endpoints'
      USING ERRCODE = '22023';
  END IF;

  -- Neutralize both endpoint identities so the unchanged legacy cutover can
  -- enforce all of its existing non-relationship invariants.
  UPDATE public.instruments_v2 relation
  SET articulations = CASE
        WHEN relation.id IN (v_parent_v2_id, v_target_v2_id) THEN ARRAY[]::uuid[]
        ELSE ARRAY(
          SELECT member
          FROM unnest(COALESCE(relation.articulations, ARRAY[]::uuid[])) member
          WHERE member NOT IN (v_parent_v2_id, v_target_v2_id)
          ORDER BY member
        )
      END,
      updated_at = now()
  WHERE relation.id IN (v_parent_v2_id, v_target_v2_id)
     OR COALESCE(relation.articulations, ARRAY[]::uuid[]) && ARRAY[v_parent_v2_id, v_target_v2_id];

  UPDATE public.sip_review_instrument relation
  SET articulations = CASE
        WHEN relation.id IN (v_parent_staging_id, v_target_staging_id) THEN ARRAY[]::uuid[]
        ELSE ARRAY(
          SELECT member
          FROM unnest(COALESCE(relation.articulations, ARRAY[]::uuid[])) member
          WHERE member NOT IN (v_parent_source_sip_id, v_target_source_sip_id)
          ORDER BY member
        )
      END,
      updated_at = now()
  WHERE relation.id IN (v_parent_staging_id, v_target_staging_id)
     OR COALESCE(relation.articulations, ARRAY[]::uuid[]) &&
          ARRAY[v_parent_source_sip_id, v_target_source_sip_id];

  v_result := public.sip_publish_coordinator_apply_semantic_regroup_plain_v1(
    p_contributor_slug,
    p_lease_id,
    p_lease_token,
    p_manifest_hash,
    p_manifest,
    p_expected_snapshot,
    p_expected_parent_source_snapshot,
    p_expected_target_snapshot,
    p_expected_target_metadata_snapshot,
    p_applied_by
  );

  -- Reconstruct every preflight row exactly, replacing the parent endpoint and
  -- sorting/deduplicating the result. This exact update is also the assertion
  -- that every non-parent member survives unchanged.
  UPDATE public.instruments_v2 relation
  SET articulations = replacement.articulations,
      updated_at = now()
  FROM (
    SELECT (expected->>'instrumentV2Id')::uuid AS id,
      ARRAY(
        SELECT DISTINCT CASE WHEN member = v_parent_v2_id THEN v_target_v2_id ELSE member END
        FROM jsonb_array_elements_text(expected->'articulations') value
        CROSS JOIN LATERAL (SELECT value::uuid AS member) parsed
        ORDER BY 1
      ) AS articulations
    FROM jsonb_array_elements(v_expected_production) expected
  ) replacement
  WHERE relation.id = replacement.id;
  GET DIAGNOSTICS v_relationship_rows = ROW_COUNT;

  UPDATE public.sip_review_instrument relation
  SET articulations = replacement.articulations,
      updated_at = now()
  FROM (
    SELECT (expected->>'stagingInstrumentId')::uuid AS id,
      ARRAY(
        SELECT DISTINCT CASE
          WHEN member = v_parent_source_sip_id THEN v_target_source_sip_id ELSE member
        END
        FROM jsonb_array_elements_text(expected->'articulations') value
        CROSS JOIN LATERAL (SELECT value::uuid AS member) parsed
        ORDER BY 1
      ) AS articulations
    FROM jsonb_array_elements(v_expected_staging) expected
  ) replacement
  WHERE relation.id = replacement.id;
  GET DIAGNOSTICS v_changed = ROW_COUNT;
  v_relationship_rows := v_relationship_rows + v_changed;

  -- A create target did not exist in the preflight snapshot. Carry the
  -- parent's outgoing graph to it; for an existing target this unions both
  -- exact preflight graphs so neither side's non-parent members are lost.
  UPDATE public.instruments_v2 target
  SET articulations = ARRAY(
        SELECT DISTINCT member
        FROM unnest(
          COALESCE(target.articulations, ARRAY[]::uuid[]) ||
          ARRAY(
            SELECT CASE WHEN member = v_parent_v2_id THEN v_target_v2_id ELSE member END
            FROM unnest(v_parent_articulations) member
          )
        ) member
        ORDER BY member
      ),
      updated_at = now()
  WHERE target.id = v_target_v2_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'semantic regroup relationship production target disappeared'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.sip_review_instrument target
  SET articulations = ARRAY(
        SELECT DISTINCT member
        FROM unnest(
          COALESCE(target.articulations, ARRAY[]::uuid[]) ||
          ARRAY(
            SELECT CASE
              WHEN member = v_parent_source_sip_id THEN v_target_source_sip_id ELSE member
            END
            FROM unnest(v_parent_staging_articulations) member
          )
        ) member
        ORDER BY member
      ),
      updated_at = now()
  WHERE target.id = v_target_staging_id
    AND target.source_sip_instrument_id = v_target_source_sip_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'semantic regroup relationship staging target disappeared'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
       SELECT 1 FROM public.instruments_v2 relation
       WHERE v_parent_v2_id = ANY(COALESCE(relation.articulations, ARRAY[]::uuid[]))
     ) OR (
       v_parent_source_sip_id <> v_target_source_sip_id
       AND EXISTS (
         SELECT 1 FROM public.sip_review_instrument relation
         WHERE v_parent_source_sip_id = ANY(COALESCE(relation.articulations, ARRAY[]::uuid[]))
       )
     ) THEN
    RAISE EXCEPTION 'semantic regroup relationship remap left an old articulation reference'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
       SELECT 1
       FROM jsonb_array_elements(v_expected_production) expected
       JOIN public.instruments_v2 relation
         ON relation.id = (expected->>'instrumentV2Id')::uuid
       WHERE relation.id <> v_target_v2_id
         AND relation.articulations IS DISTINCT FROM ARRAY(
           SELECT DISTINCT CASE
             WHEN value::uuid = v_parent_v2_id THEN v_target_v2_id ELSE value::uuid
           END
           FROM jsonb_array_elements_text(expected->'articulations') value
           ORDER BY 1
         )
     ) OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(v_expected_staging) expected
       JOIN public.sip_review_instrument relation
         ON relation.id = (expected->>'stagingInstrumentId')::uuid
       WHERE relation.id <> v_target_staging_id
         AND relation.articulations IS DISTINCT FROM ARRAY(
           SELECT DISTINCT CASE
             WHEN value::uuid = v_parent_source_sip_id THEN v_target_source_sip_id ELSE value::uuid
           END
           FROM jsonb_array_elements_text(expected->'articulations') value
           ORDER BY 1
         )
     ) OR NOT (
       ARRAY(
         SELECT DISTINCT CASE
           WHEN member = v_parent_v2_id THEN v_target_v2_id ELSE member
         END
         FROM unnest(v_parent_articulations) member
       ) <@ (SELECT articulations FROM public.instruments_v2 WHERE id = v_target_v2_id)
     ) OR NOT (
       ARRAY(
         SELECT DISTINCT CASE
           WHEN member = v_parent_source_sip_id THEN v_target_source_sip_id ELSE member
         END
         FROM unnest(v_parent_staging_articulations) member
       ) <@ (SELECT articulations FROM public.sip_review_instrument WHERE id = v_target_staging_id)
     ) THEN
    RAISE EXCEPTION 'semantic regroup relationship remap changed a non-parent articulation member'
      USING ERRCODE = '55000';
  END IF;

  v_result := v_result || jsonb_build_object(
    'relationship_remap_applied', true,
    'relationship_target_instrument_v2_id', v_target_v2_id,
    'relationship_target_staging_instrument_id', v_target_staging_id,
    'relationship_rows_remapped', v_relationship_rows
  );
  UPDATE public.sip_semantic_regroup_receipts receipt
  SET result = v_result
  WHERE receipt.provider_slug = p_contributor_slug
    AND receipt.manifest_hash = p_manifest_hash;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'semantic regroup relationship receipt disappeared'
      USING ERRCODE = '55000';
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "private"."sip_apply_semantic_regroup_pre_orphan_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_expected_snapshot" "jsonb", "p_expected_parent_source_snapshot" "jsonb", "p_expected_target_snapshot" "jsonb", "p_expected_target_metadata_snapshot" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_fleet_executor_leases" (
    "executor_id" "text" NOT NULL,
    "lease_token" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lease_expires_at" timestamp with time zone NOT NULL,
    "heartbeat_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "capabilities" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sip_fleet_executor_leases_executor_id_check" CHECK (("btrim"("executor_id") <> ''::"text")),
    CONSTRAINT "sip_fleet_executor_leases_metadata_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text"))
);


ALTER TABLE "public"."sip_fleet_executor_leases" OWNER TO "postgres";


COMMENT ON TABLE "public"."sip_fleet_executor_leases" IS 'Short-lived executor identities used to fence item claims.';



CREATE OR REPLACE FUNCTION "public"."acquire_sip_fleet_executor_lease"("p_executor_id" "text", "p_lease_seconds" integer DEFAULT 300, "p_capabilities" "text"[] DEFAULT '{}'::"text"[], "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."sip_fleet_executor_leases"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_lease public.sip_fleet_executor_leases%ROWTYPE;
BEGIN
  IF nullif(btrim(p_executor_id),'') IS NULL THEN RAISE EXCEPTION 'executor_id_required'; END IF;
  IF p_lease_seconds < 30 OR p_lease_seconds > 3600 THEN RAISE EXCEPTION 'invalid_lease_seconds'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-fleet-executor-admission',0));
  IF EXISTS (
    SELECT 1 FROM public.sip_versioned_output_prefix_staging_operations operation
    WHERE operation.status='running' OR (operation.status='ambiguous' AND NOT EXISTS (
      SELECT 1 FROM public.sip_versioned_output_prefix_premutation_reconciliation_receipts clearance
      WHERE clearance.staging_operation_id=operation.id
    ))
  ) THEN RAISE EXCEPTION 'versioned_output_prefix_staging_active'; END IF;
  INSERT INTO public.sip_fleet_executor_leases(
    executor_id,lease_token,lease_expires_at,heartbeat_at,capabilities,metadata
  ) VALUES (btrim(p_executor_id),gen_random_uuid(),now()+make_interval(secs=>p_lease_seconds),
    now(),coalesce(p_capabilities,'{}'),coalesce(p_metadata,'{}'::jsonb))
  ON CONFLICT (executor_id) DO UPDATE SET lease_token=EXCLUDED.lease_token,
    lease_expires_at=EXCLUDED.lease_expires_at,heartbeat_at=now(),
    capabilities=EXCLUDED.capabilities,metadata=EXCLUDED.metadata
  RETURNING * INTO v_lease;
  IF NOT FOUND THEN RAISE EXCEPTION 'executor_lease_held'; END IF;
  RETURN v_lease;
END $$;


ALTER FUNCTION "public"."acquire_sip_fleet_executor_lease"("p_executor_id" "text", "p_lease_seconds" integer, "p_capabilities" "text"[], "p_metadata" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_fleet_provider_leases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_slug" "text" NOT NULL,
    "lease_owner" "text" NOT NULL,
    "lease_token" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lease_expires_at" timestamp with time zone NOT NULL,
    "released_at" timestamp with time zone,
    "heartbeat_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sip_fleet_provider_leases_lease_owner_check" CHECK (("btrim"("lease_owner") <> ''::"text")),
    CONSTRAINT "sip_fleet_provider_leases_metadata_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "sip_fleet_provider_leases_provider_slug_check" CHECK (("btrim"("provider_slug") <> ''::"text"))
);


ALTER TABLE "public"."sip_fleet_provider_leases" OWNER TO "postgres";


COMMENT ON TABLE "public"."sip_fleet_provider_leases" IS 'Fencing leases that ensure one publish coordinator owns a provider.';



CREATE OR REPLACE FUNCTION "public"."acquire_sip_fleet_provider_lease"("p_provider_slug" "text", "p_lease_owner" "text", "p_lease_seconds" integer DEFAULT 900, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."sip_fleet_provider_leases"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_lease public.sip_fleet_provider_leases%ROWTYPE;
BEGIN
  IF nullif(btrim(p_provider_slug),'') IS NULL OR nullif(btrim(p_lease_owner),'') IS NULL THEN
    RAISE EXCEPTION 'provider_slug_and_lease_owner_required';
  END IF;
  IF p_lease_seconds < 30 OR p_lease_seconds > 86400 THEN RAISE EXCEPTION 'invalid_lease_seconds'; END IF;
  INSERT INTO public.sip_fleet_provider_leases(
    provider_slug, lease_owner, lease_token, lease_expires_at, heartbeat_at, metadata
  ) VALUES (btrim(p_provider_slug), btrim(p_lease_owner), gen_random_uuid(),
    now() + make_interval(secs => p_lease_seconds), now(), coalesce(p_metadata,'{}'::jsonb))
  ON CONFLICT (provider_slug) DO UPDATE SET
    lease_owner = EXCLUDED.lease_owner,
    lease_token = CASE
      WHEN public.sip_fleet_provider_leases.lease_owner = EXCLUDED.lease_owner
        AND public.sip_fleet_provider_leases.lease_expires_at > now()
        AND public.sip_fleet_provider_leases.released_at IS NULL
        THEN public.sip_fleet_provider_leases.lease_token
      ELSE EXCLUDED.lease_token
    END,
    lease_expires_at = EXCLUDED.lease_expires_at, released_at = NULL,
    heartbeat_at = now(), metadata = EXCLUDED.metadata
  WHERE public.sip_fleet_provider_leases.lease_owner = EXCLUDED.lease_owner
     OR public.sip_fleet_provider_leases.lease_expires_at <= now()
  RETURNING * INTO v_lease;
  IF NOT FOUND THEN RAISE EXCEPTION 'provider_lease_held'; END IF;
  UPDATE public.sip_fleet_runs SET provider_lease_id=v_lease.id,
    provider_lease_token=v_lease.lease_token
  WHERE provider_slug=v_lease.provider_slug AND status IN ('queued','running')
    AND provider_lease_token IS DISTINCT FROM v_lease.lease_token;
  RETURN v_lease;
END $$;


ALTER FUNCTION "public"."acquire_sip_fleet_provider_lease"("p_provider_slug" "text", "p_lease_owner" "text", "p_lease_seconds" integer, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_user_feature_flag"("p_target_user_id" "uuid", "p_flag_key" "text", "p_enabled" boolean, "p_reason" "text", "p_actor_user_id" "uuid") RETURNS TABLE("feature_flag_id" "uuid", "key" "text", "enabled" boolean, "assigned_enabled" boolean, "evaluation_reason" "text", "is_active" boolean, "requires_reload" boolean, "dev_logging_enabled" boolean, "product_insights_enabled" boolean, "assignment_updated_at" timestamp with time zone, "assignment_change_reason" "text", "assignment_updated_via" "text", "assignment_updated_by_user_id" "uuid", "audit_event_id" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_feature_flag_id uuid;
  v_audit_event_id bigint;
BEGIN
  IF p_target_user_id IS NULL
    OR p_actor_user_id IS NULL
    OR p_flag_key IS NULL
    OR p_flag_key = ''
    OR p_enabled IS NULL
  THEN
    RAISE EXCEPTION 'target, actor, flag key, and enabled state are required'
      USING ERRCODE = '22004';
  END IF;

  IF p_reason IS NULL
    OR char_length(btrim(p_reason)) < 1
    OR char_length(p_reason) > 500
  THEN
    RAISE EXCEPTION 'admin feature changes require a reason of 1 to 500 characters'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM private.feature_flag_auth_users AS users
    WHERE users.id = p_actor_user_id
      AND users.email_confirmed_at IS NOT NULL
      AND users.deleted_at IS NULL
      AND users.email ~* '^[^@]+@soundsculpt[.]app$'
  ) THEN
    RAISE EXCEPTION 'feature flag actor must be a current confirmed internal user'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM private.feature_flag_auth_users AS users
    WHERE users.id = p_target_user_id
      AND users.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'feature flag target user does not exist'
      USING ERRCODE = '22023';
  END IF;

  SELECT flags.id
  INTO v_feature_flag_id
  FROM public.feature_flags AS flags
  WHERE flags.key = p_flag_key
    AND flags.archived_at IS NULL;

  IF v_feature_flag_id IS NULL THEN
    RAISE EXCEPTION 'feature flag does not exist or is archived'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_target_user_id::text || ':' || v_feature_flag_id::text,
      0
    )
  );
  PERFORM pg_catalog.set_config(
    'feature_flags.last_audit_event_id',
    '',
    true
  );

  INSERT INTO public.feature_user_enablements (
    user_id,
    feature_flag_id,
    enabled,
    change_reason,
    updated_via,
    created_by_user_id,
    updated_by_user_id
  ) VALUES (
    p_target_user_id,
    v_feature_flag_id,
    p_enabled,
    btrim(p_reason),
    'admin',
    p_actor_user_id,
    p_actor_user_id
  )
  ON CONFLICT ON CONSTRAINT feature_user_enablements_pkey DO UPDATE
    SET enabled = EXCLUDED.enabled,
        change_reason = EXCLUDED.change_reason,
        updated_via = 'admin',
        updated_by_user_id = EXCLUDED.updated_by_user_id
  WHERE public.feature_user_enablements.enabled IS DISTINCT FROM EXCLUDED.enabled;

  v_audit_event_id := NULLIF(
    pg_catalog.current_setting('feature_flags.last_audit_event_id', true),
    ''
  )::bigint;

  RETURN QUERY
  SELECT
    flags.id,
    flags.key,
    flags.is_active AND assignments.enabled,
    assignments.enabled,
    CASE
      WHEN NOT flags.is_active THEN 'inactive'
      WHEN assignments.enabled THEN 'targeted'
      ELSE 'explicitly_disabled'
    END,
    flags.is_active,
    flags.requires_reload,
    flags.dev_logging_enabled,
    flags.product_insights_enabled,
    assignments.updated_at,
    assignments.change_reason,
    assignments.updated_via,
    assignments.updated_by_user_id,
    v_audit_event_id
  FROM public.feature_flags AS flags
  JOIN public.feature_user_enablements AS assignments
    ON assignments.feature_flag_id = flags.id
   AND assignments.user_id = p_target_user_id
  WHERE flags.id = v_feature_flag_id;
END;
$_$;


ALTER FUNCTION "public"."admin_set_user_feature_flag"("p_target_user_id" "uuid", "p_flag_key" "text", "p_enabled" boolean, "p_reason" "text", "p_actor_user_id" "uuid") OWNER TO "feature_flag_owner";


CREATE OR REPLACE FUNCTION "public"."append_sample_psychoacoustic_result_v1"("p_published_asset_id" "uuid", "p_asset_source_signature" "text", "p_result" "jsonb", "p_canonical_result_body" "text", "p_projection_version" "text", "p_run_id" "uuid", "p_run_kind" "text", "p_created_by" "text") RETURNS TABLE("record_id" "uuid", "result_id" "text", "result_digest" "text", "idempotent" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_existing public.sample_psychoacoustic_characteristic_results%ROWTYPE;
  v_job public.sample_psychoacoustic_characteristic_jobs%ROWTYPE;
  v_inserted public.sample_psychoacoustic_characteristic_results%ROWTYPE;
  v_result_id text := p_result #>> '{identity,resultId}';
  v_result_digest text := p_result #>> '{identity,resultDigest}';
BEGIN
  IF p_result IS NULL OR jsonb_typeof(p_result) <> 'object'
     OR p_canonical_result_body IS NULL
     OR p_run_id IS NULL
     OR p_run_kind NOT IN ('validation', 'recompute', 'manual')
     OR btrim(coalesce(p_created_by, '')) = ''
     OR length(p_created_by) > 256
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'psychoacoustic_result_invalid_input';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'sample-psychoacoustic-result-run:' || p_run_id::text,
    0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    concat_ws(
      ':',
      'sample-psychoacoustic-result-identity',
      p_published_asset_id::text,
      p_asset_source_signature,
      p_result->>'characteristicKey',
      p_result->>'evidenceContractVersion',
      p_result->>'algorithmVersion',
      coalesce(p_projection_version, '<null>')
    ),
    0
  ));

  SELECT * INTO v_existing
  FROM public.sample_psychoacoustic_characteristic_results AS result
  WHERE result.created_run_id = p_run_id
  FOR SHARE;
  IF FOUND THEN
    IF v_existing.result_id <> v_result_id
       OR v_existing.result_digest <> v_result_digest
       OR v_existing.result_payload <> p_result
       OR v_existing.canonical_result_body <> p_canonical_result_body
       OR v_existing.published_asset_id <> p_published_asset_id
       OR v_existing.asset_source_signature <> p_asset_source_signature
       OR v_existing.projection_version IS DISTINCT FROM p_projection_version
       OR v_existing.run_kind <> p_run_kind
       OR v_existing.created_by <> p_created_by
    THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'psychoacoustic_run_identity_conflict';
    END IF;
  ELSE
    SELECT * INTO v_existing
    FROM public.sample_psychoacoustic_characteristic_results AS result
    WHERE result.published_asset_id = p_published_asset_id
      AND result.asset_source_signature = p_asset_source_signature
      AND result.characteristic_key = p_result->>'characteristicKey'
      AND result.evidence_contract_version = p_result->>'evidenceContractVersion'
      AND result.algorithm_version = p_result->>'algorithmVersion'
      AND result.projection_version IS NOT DISTINCT FROM p_projection_version
    FOR SHARE;
    IF FOUND AND (
      v_existing.result_id <> v_result_id
      OR v_existing.result_digest <> v_result_digest
      OR v_existing.result_payload <> p_result
      OR v_existing.canonical_result_body <> p_canonical_result_body
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'psychoacoustic_result_identity_conflict';
    END IF;
  END IF;

  IF v_existing.id IS NOT NULL THEN
    SELECT * INTO v_job
    FROM public.sample_psychoacoustic_characteristic_jobs AS job
    WHERE job.id = p_run_id
    FOR UPDATE;
    IF FOUND AND (
      v_job.published_asset_id <> p_published_asset_id
      OR v_job.asset_source_signature <> p_asset_source_signature
      OR v_job.characteristic_key <> p_result->>'characteristicKey'
      OR v_job.evidence_contract_version <> p_result->>'evidenceContractVersion'
      OR v_job.algorithm_version <> p_result->>'algorithmVersion'
      OR v_job.projection_version IS DISTINCT FROM p_projection_version
      OR v_job.run_kind <> p_run_kind
      OR v_job.requested_by <> p_created_by
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'psychoacoustic_run_identity_conflict';
    END IF;
    IF v_job.id IS NOT NULL THEN
      UPDATE public.sample_psychoacoustic_characteristic_jobs
      SET status = 'completed',
          result_record_id = v_existing.id,
          updated_at = now()
      WHERE id = v_job.id;
    END IF;
    RETURN QUERY SELECT
      v_existing.id,
      v_existing.result_id,
      v_existing.result_digest,
      true;
    RETURN;
  END IF;

  PERFORM 1
  FROM public.sample_s3_path AS asset
  WHERE asset.id = p_published_asset_id
    AND asset.source_signature = p_asset_source_signature
    AND asset.is_current
    AND asset.excluded_at IS NULL
    AND asset.quality = 1
    AND asset.format = 'mp3'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'psychoacoustic_asset_identity_conflict';
  END IF;

  SELECT * INTO v_job
  FROM public.sample_psychoacoustic_characteristic_jobs AS job
  WHERE job.id = p_run_id
  FOR UPDATE;
  IF FOUND AND (
    v_job.published_asset_id <> p_published_asset_id
    OR v_job.asset_source_signature <> p_asset_source_signature
    OR v_job.characteristic_key <> p_result->>'characteristicKey'
    OR v_job.evidence_contract_version <> p_result->>'evidenceContractVersion'
    OR v_job.algorithm_version <> p_result->>'algorithmVersion'
    OR v_job.projection_version IS DISTINCT FROM p_projection_version
    OR v_job.run_kind <> p_run_kind
    OR v_job.requested_by <> p_created_by
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'psychoacoustic_run_identity_conflict';
  END IF;

  INSERT INTO public.sample_psychoacoustic_characteristic_results(
    published_asset_id,
    asset_source_signature,
    source_digest,
    characteristic_key,
    evidence_contract_version,
    algorithm_version,
    projection_version,
    state,
    policy,
    native_measurements,
    projection,
    applicability,
    unavailable_reason,
    explanation,
    result_id,
    result_digest,
    result_payload,
    canonical_result_body,
    created_run_id,
    run_kind,
    created_by
  ) VALUES (
    p_published_asset_id,
    p_asset_source_signature,
    p_result->>'sourceSignature',
    p_result->>'characteristicKey',
    p_result->>'evidenceContractVersion',
    p_result->>'algorithmVersion',
    p_projection_version,
    p_result->>'state',
    p_result->'policy',
    p_result->'nativeMeasurements',
    p_result->'projection',
    p_result->'applicability',
    p_result->>'unavailableReason',
    p_result->'explanation',
    v_result_id,
    v_result_digest,
    p_result,
    p_canonical_result_body,
    p_run_id,
    p_run_kind,
    p_created_by
  ) RETURNING * INTO v_inserted;

  IF v_job.id IS NOT NULL THEN
    UPDATE public.sample_psychoacoustic_characteristic_jobs
    SET status = 'completed',
        result_record_id = v_inserted.id,
        updated_at = now()
    WHERE id = v_job.id;
  END IF;

  RETURN QUERY SELECT
    v_inserted.id,
    v_inserted.result_id,
    v_inserted.result_digest,
    false;
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION USING
    ERRCODE = 'P0001',
    MESSAGE = 'psychoacoustic_result_identity_conflict';
END;
$$;


ALTER FUNCTION "public"."append_sample_psychoacoustic_result_v1"("p_published_asset_id" "uuid", "p_asset_source_signature" "text", "p_result" "jsonb", "p_canonical_result_body" "text", "p_projection_version" "text", "p_run_id" "uuid", "p_run_kind" "text", "p_created_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_pitchless_round_robin_cap_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_instrument_v2_id" "uuid", "p_keeper_sample_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  keeper_count integer;
  detached_count integer;
  renumbered_count integer;
  keeper_round_robins jsonb;
  keeper_mic_positions jsonb;
BEGIN
  IF NOT public.validate_sip_publish_operator_lease_v1(p_contributor_slug, p_lease_id, p_lease_token) THEN
    RAISE EXCEPTION 'invalid_coordinator_publish_authorization';
  END IF;
  keeper_count := COALESCE(array_length(p_keeper_sample_ids, 1), 0);
  IF keeper_count <> 8 THEN RAISE EXCEPTION 'pitchless round-robin cap requires exactly 8 keeper samples'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.instruments_v2 WHERE id = p_instrument_v2_id) THEN RAISE EXCEPTION 'instrument not found'; END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(p_keeper_sample_ids) AS requested(sample_id)
    LEFT JOIN public.sample_path_constructs spc ON spc.sample_original_path_id = requested.sample_id AND spc.instrument_v2_id = p_instrument_v2_id
    WHERE spc.id IS NULL
  ) THEN RAISE EXCEPTION 'keeper sample is not an active construct for this instrument'; END IF;
  PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);
  UPDATE public.sample_path_constructs SET instrument_v2_id = NULL
  WHERE instrument_v2_id = p_instrument_v2_id AND NOT (sample_original_path_id = ANY(p_keeper_sample_ids));
  GET DIAGNOSTICS detached_count = ROW_COUNT;
  WITH keepers AS (
    SELECT sample_id, (ordinality - 1)::integer AS next_round_robin
    FROM unnest(p_keeper_sample_ids) WITH ORDINALITY AS requested(sample_id, ordinality)
  )
  UPDATE public.sample_path_constructs spc
  SET pitch_content = '0', velocity = 0, round_robin = keepers.next_round_robin,
      midi_note = 'pitchless', mic_position = 'main', filename = 'pitchless'
  FROM keepers
  WHERE spc.instrument_v2_id = p_instrument_v2_id AND spc.sample_original_path_id = keepers.sample_id;
  GET DIAGNOSTICS renumbered_count = ROW_COUNT;
  SELECT jsonb_build_object('0/0', jsonb_agg(round_robin ORDER BY round_robin)),
         jsonb_object_agg(format('0/0/%s', round_robin), jsonb_build_array('main'))
  INTO keeper_round_robins, keeper_mic_positions
  FROM public.sample_path_constructs WHERE instrument_v2_id = p_instrument_v2_id;
  UPDATE public.instruments_v2
  SET engine_type = 'fx', playback_type = 'oneShot', pitch_contents = to_jsonb(ARRAY['0']::text[]),
      velocity_layers = '{"0":[0]}'::jsonb, round_robins = keeper_round_robins,
      mic_positions = keeper_mic_positions, range_lower = 21, range_upper = 108,
      single_pitch = NULL, file_name_references = ARRAY['pitchless'], updated_at = now()
  WHERE id = p_instrument_v2_id;
  RETURN jsonb_build_object('instrument_v2_id', p_instrument_v2_id, 'keeper_count', keeper_count,
    'renumbered_count', renumbered_count, 'detached_count', detached_count,
    'active_round_robins', keeper_round_robins, 'file_name_references', ARRAY['pitchless']);
END $$;


ALTER FUNCTION "public"."apply_pitchless_round_robin_cap_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_instrument_v2_id" "uuid", "p_keeper_sample_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_sip_review_sample_override_bulk"("p_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_target_column" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  normalized_target text := lower(btrim(coalesce(p_target_column, '')));
  upsert_count integer := 0;
BEGIN
  p_rows := COALESCE(p_rows, '[]'::jsonb);

  IF jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'apply_sip_review_sample_override_bulk p_rows must be a JSON array' USING ERRCODE = '22023';
  END IF;

  IF normalized_target NOT IN (
    'collection',
    'instrument_name',
    'articulation',
    'effect',
    'mic_position',
    'velocity',
    'round_robin',
    'midi_note',
    'playback_type',
    'pitch_content',
    'filename'
  ) THEN
    RAISE EXCEPTION 'unsupported sample override target column: %', p_target_column USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_rows) AS item(row_json)
    WHERE NOT (item.row_json ? 'sip_review_instrument_id')
      OR NOT (item.row_json ? 'contributor_slug')
      OR NOT (item.row_json ? 'original_sample_id')
      OR NOT (item.row_json ? 'value')
  ) THEN
    RAISE EXCEPTION 'sample override rows require sip_review_instrument_id, contributor_slug, original_sample_id, and value' USING ERRCODE = '22023';
  END IF;

  WITH rows AS (
    SELECT
      (row_json->>'sip_review_instrument_id')::uuid AS sip_review_instrument_id,
      NULLIF(btrim(row_json->>'contributor_slug'), '') AS contributor_slug,
      (row_json->>'original_sample_id')::uuid AS original_sample_id,
      NULLIF(btrim(row_json->>'file_path'), '') AS file_path,
      row_json->>'value' AS value
    FROM jsonb_array_elements(p_rows) AS item(row_json)
  ),
  prepared AS (
    SELECT
      rows.sip_review_instrument_id,
      rows.contributor_slug,
      rows.original_sample_id,
      COALESCE(rows.file_path, samples_original_paths.s3_path) AS file_path,
      rows.value
    FROM rows
    LEFT JOIN samples_original_paths
      ON samples_original_paths.id = rows.original_sample_id
  )
  INSERT INTO public.sip_review_sample_override (
    sip_review_instrument_id,
    contributor_slug,
    original_sample_id,
    file_path,
    collection,
    instrument_name,
    articulation,
    effect,
    mic_position,
    velocity,
    round_robin,
    midi_note,
    playback_type,
    pitch_content,
    filename
  )
  SELECT
    sip_review_instrument_id,
    contributor_slug,
    original_sample_id,
    file_path,
    CASE WHEN normalized_target = 'collection' THEN value END,
    CASE WHEN normalized_target = 'instrument_name' THEN value END,
    CASE WHEN normalized_target = 'articulation' THEN value END,
    CASE WHEN normalized_target = 'effect' THEN value END,
    CASE WHEN normalized_target = 'mic_position' THEN value END,
    CASE WHEN normalized_target = 'velocity' THEN value END,
    CASE WHEN normalized_target = 'round_robin' THEN value END,
    CASE WHEN normalized_target = 'midi_note' THEN value END,
    CASE
      WHEN normalized_target = 'playback_type'
        THEN NULLIF(btrim(value), '')::public.instrument_playback_type
    END,
    CASE WHEN normalized_target = 'pitch_content' THEN value END,
    CASE WHEN normalized_target = 'filename' THEN value END
  FROM prepared
  ON CONFLICT (sip_review_instrument_id, original_sample_id) DO UPDATE SET
    contributor_slug = EXCLUDED.contributor_slug,
    file_path = EXCLUDED.file_path,
    collection = CASE
      WHEN normalized_target = 'collection' THEN EXCLUDED.collection
      ELSE public.sip_review_sample_override.collection
    END,
    instrument_name = CASE
      WHEN normalized_target = 'instrument_name' THEN EXCLUDED.instrument_name
      ELSE public.sip_review_sample_override.instrument_name
    END,
    articulation = CASE
      WHEN normalized_target = 'articulation' THEN EXCLUDED.articulation
      ELSE public.sip_review_sample_override.articulation
    END,
    effect = CASE
      WHEN normalized_target = 'effect' THEN EXCLUDED.effect
      ELSE public.sip_review_sample_override.effect
    END,
    mic_position = CASE
      WHEN normalized_target = 'mic_position' THEN EXCLUDED.mic_position
      ELSE public.sip_review_sample_override.mic_position
    END,
    velocity = CASE
      WHEN normalized_target = 'velocity' THEN EXCLUDED.velocity
      ELSE public.sip_review_sample_override.velocity
    END,
    round_robin = CASE
      WHEN normalized_target = 'round_robin' THEN EXCLUDED.round_robin
      ELSE public.sip_review_sample_override.round_robin
    END,
    midi_note = CASE
      WHEN normalized_target = 'midi_note' THEN EXCLUDED.midi_note
      ELSE public.sip_review_sample_override.midi_note
    END,
    playback_type = CASE
      WHEN normalized_target = 'playback_type' THEN EXCLUDED.playback_type
      ELSE public.sip_review_sample_override.playback_type
    END,
    pitch_content = CASE
      WHEN normalized_target = 'pitch_content' THEN EXCLUDED.pitch_content
      ELSE public.sip_review_sample_override.pitch_content
    END,
    filename = CASE
      WHEN normalized_target = 'filename' THEN EXCLUDED.filename
      ELSE public.sip_review_sample_override.filename
    END,
    updated_at = now();
  GET DIAGNOSTICS upsert_count = ROW_COUNT;

  RETURN jsonb_build_object('upserted', upsert_count);
END;
$$;


ALTER FUNCTION "public"."apply_sip_review_sample_override_bulk"("p_rows" "jsonb", "p_target_column" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arrays_equal_unordered"("a" "text"[], "b" "text"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN a IS NULL AND b IS NULL THEN true
    WHEN a IS NULL OR b IS NULL THEN false
    WHEN cardinality(a) IS DISTINCT FROM cardinality(b) THEN false
    ELSE COALESCE(
      (SELECT array_agg(v ORDER BY v NULLS FIRST) FROM unnest(a) AS u(v)),
      ARRAY[]::text[]
    ) = COALESCE(
      (SELECT array_agg(v ORDER BY v NULLS FIRST) FROM unnest(b) AS u(v)),
      ARRAY[]::text[]
    )
  END
$$;


ALTER FUNCTION "public"."arrays_equal_unordered"("a" "text"[], "b" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_round_robin_cue_eligibility_slot_identity_v1"("p_instrument_v2_id" "uuid", "p_pitch_content" "text", "p_velocity" integer, "p_mic_position" "text", "p_filename" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_swell_mixed boolean;
  v_crash_mixed boolean;
BEGIN
  IF p_instrument_v2_id IS NULL THEN
    RETURN;
  END IF;

  SELECT
    bool_or(COALESCE(cue.swell_eligible, false))
      <> bool_and(COALESCE(cue.swell_eligible, false)),
    bool_or(COALESCE(cue.crash_eligible, false))
      <> bool_and(COALESCE(cue.crash_eligible, false))
    INTO v_swell_mixed, v_crash_mixed
    FROM public.sample_path_constructs sibling
    LEFT JOIN public.sample_playback_cues cue
      ON cue.sample_path_construct_id = sibling.id
   WHERE sibling.instrument_v2_id = p_instrument_v2_id
     AND sibling.pitch_content = p_pitch_content
     AND sibling.velocity = p_velocity
     AND sibling.mic_position IS NOT DISTINCT FROM p_mic_position
     AND sibling.filename = p_filename
   HAVING count(DISTINCT sibling.round_robin) > 1;

  IF COALESCE(v_swell_mixed, false)
     OR COALESCE(v_crash_mixed, false) THEN
    RAISE EXCEPTION
      'round-robin cue eligibility must be uniform for slot instrument_v2_id=%, pitch_content=%, velocity=%, mic_position=%, filename=% (swell_mixed=%, crash_mixed=%)',
      p_instrument_v2_id,
      p_pitch_content,
      p_velocity,
      p_mic_position,
      p_filename,
      COALESCE(v_swell_mixed, false),
      COALESCE(v_crash_mixed, false)
      USING ERRCODE = '23514';
  END IF;
END;
$$;


ALTER FUNCTION "public"."assert_round_robin_cue_eligibility_slot_identity_v1"("p_instrument_v2_id" "uuid", "p_pitch_content" "text", "p_velocity" integer, "p_mic_position" "text", "p_filename" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_round_robin_cue_eligibility_slot_v1"("p_sample_path_construct_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_construct public.sample_path_constructs%ROWTYPE;
BEGIN
  SELECT *
    INTO v_construct
    FROM public.sample_path_constructs
   WHERE id = p_sample_path_construct_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  PERFORM public.assert_round_robin_cue_eligibility_slot_identity_v1(
    v_construct.instrument_v2_id,
    v_construct.pitch_content,
    v_construct.velocity,
    v_construct.mic_position,
    v_construct.filename
  );
END;
$$;


