CREATE OR REPLACE FUNCTION "public"."audio_profile_v1_hash"("payload" "jsonb") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT 'apv1:sha256-v1:' || encode(
    extensions.digest(convert_to(COALESCE(payload, '{}'::jsonb)::text, 'UTF8'), 'sha256'),
    'hex'
  );
$$;


ALTER FUNCTION "public"."audio_profile_v1_hash"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_instrument_runtime_sample_manifests_v1"("p_instrument_v2_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_contributor_slug" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 1000) RETURNS TABLE("contributor_slug" "text", "instrument_v2_id" "uuid", "instrument_name" "text", "candidate" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 10001 THEN
    RAISE EXCEPTION 'p_limit must be between 1 and 10001'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    contributor.slug,
    instrument.id,
    instrument.name,
    manifest.candidate || jsonb_build_object(
      'runtimeReadiness',
      public.build_instrument_v2_runtime_readiness_v1(
        instrument.id,
        manifest.candidate,
        false
      )
    )
  FROM public.instruments_v2 instrument
  LEFT JOIN public.contributors contributor
    ON contributor.id = instrument.contributor_id
  CROSS JOIN LATERAL (
    SELECT public.build_instrument_runtime_sample_manifest_v1(instrument.id)
      AS candidate
  ) manifest
  WHERE instrument.published = true
    AND (
      p_instrument_v2_ids IS NULL
      OR instrument.id = ANY(p_instrument_v2_ids)
    )
    AND (
      p_contributor_slug IS NULL
      OR contributor.slug = p_contributor_slug
    )
  ORDER BY contributor.slug NULLS LAST, instrument.name, instrument.id
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."audit_instrument_runtime_sample_manifests_v1"("p_instrument_v2_ids" "uuid"[], "p_contributor_slug" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_instrument_runtime_sample_manifests_v1"("p_instrument_v2_ids" "uuid"[], "p_contributor_slug" "text", "p_limit" integer) IS 'Read-only deterministic manifest audit for bounded published Instrument V2 scope.';



CREATE OR REPLACE FUNCTION "public"."build_instrument_runtime_sample_manifest_v1"("p_instrument_v2_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_instrument_exists boolean;
  v_variants jsonb;
  v_hash_variants jsonb;
  v_blocking_reasons jsonb;
  v_variant_count integer;
  v_manifest_sha256 text;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM public.instruments_v2 WHERE id = p_instrument_v2_id
  ) INTO v_instrument_exists;

  IF NOT v_instrument_exists THEN
    RAISE EXCEPTION 'Instrument V2 % does not exist', p_instrument_v2_id
      USING ERRCODE = '22023';
  END IF;

  WITH variant_rows AS MATERIALIZED (
    SELECT
      construct.id AS sample_path_construct_id,
      construct.sample_original_path_id,
      COALESCE(NULLIF(btrim(construct.pitch_content), ''), '0')
        AS pitch_content,
      GREATEST(construct.velocity, 0) AS velocity,
      GREATEST(construct.round_robin, 0) AS round_robin,
      COALESCE(NULLIF(btrim(construct.mic_position), ''), 'main')
        AS mic_position,
      COALESCE(
        NULLIF(
          regexp_replace(
            btrim(construct.filename),
            '\.(mp3|ogg|wav|aif|aiff|flac|ncw)$',
            '',
            'i'
          ),
          ''
        ),
        '0'
      ) AS filename,
      CASE
        WHEN lower(btrim(construct.midi_note)) = 'pitchless' THEN NULL
        WHEN btrim(construct.midi_note) ~ '^[0-9]{1,3}$'
          AND btrim(construct.midi_note)::integer BETWEEN 0 AND 127
          THEN btrim(construct.midi_note)::integer
        ELSE NULL
      END AS midi_note,
      (
        lower(btrim(construct.midi_note)) = 'pitchless'
        OR (
          btrim(construct.midi_note) ~ '^[0-9]{1,3}$'
          AND btrim(construct.midi_note)::integer BETWEEN 0 AND 127
        )
      ) AS midi_note_valid,
      construct.playback_type::text AS playback_type,
      CASE
        WHEN librosa.duration IS NULL THEN NULL
        WHEN librosa.duration::text IN ('NaN', 'Infinity', '-Infinity') THEN NULL
        WHEN librosa.duration <= 0 OR librosa.duration > 2147483.647 THEN NULL
        ELSE round(librosa.duration * 1000.0)::integer
      END AS duration_ms,
      CASE
        WHEN librosa.duration IS NULL THEN false
        WHEN librosa.duration::text IN ('NaN', 'Infinity', '-Infinity') THEN true
        ELSE librosa.duration <= 0 OR librosa.duration > 2147483.647
      END AS duration_invalid,
      cue.sync_point_ms,
      cue.loop_start_offset_ms,
      cue.loop_end_offset_ms,
      COALESCE(cue.swell_eligible, false) AS swell_eligible,
      COALESCE(cue.crash_eligible, false) AS crash_eligible,
      construct.filename IS NULL OR btrim(construct.filename) = ''
        OR construct.sample_original_path_id IS NULL AS metadata_incomplete
    FROM public.sample_path_constructs construct
    LEFT JOIN public.sample_playback_cues cue
      ON cue.sample_path_construct_id = construct.id
    LEFT JOIN public.analysis_librosa librosa
      ON librosa.sample_id = construct.sample_original_path_id
    WHERE construct.instrument_v2_id = p_instrument_v2_id
  )
  SELECT
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'pitchContent', pitch_content,
          'velocity', velocity,
          'roundRobin', round_robin,
          'micPosition', mic_position,
          'filename', filename,
          'midiNote', midi_note,
          'playbackType', playback_type,
          'durationMs', duration_ms,
          'syncPointMs', sync_point_ms,
          'loopStartOffsetMs', loop_start_offset_ms,
          'loopEndOffsetMs', loop_end_offset_ms,
          'swellEligible', swell_eligible,
          'crashEligible', crash_eligible,
          'sampleOriginalPathId', sample_original_path_id
        )
        ORDER BY
          pitch_content,
          velocity,
          round_robin,
          mic_position,
          filename,
          midi_note NULLS FIRST,
          sample_original_path_id NULLS FIRST,
          sample_path_construct_id
      ),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'pitchContent', pitch_content,
          'velocity', velocity,
          'roundRobin', round_robin,
          'micPosition', mic_position,
          'filename', filename,
          'midiNote', midi_note,
          'playbackType', playback_type,
          'durationMs', duration_ms,
          'syncPointMs', sync_point_ms,
          'loopStartOffsetMs', loop_start_offset_ms,
          'loopEndOffsetMs', loop_end_offset_ms,
          'swellEligible', swell_eligible,
          'crashEligible', crash_eligible
        )
        ORDER BY
          pitch_content,
          velocity,
          round_robin,
          mic_position,
          filename,
          midi_note NULLS FIRST,
          sample_original_path_id NULLS FIRST,
          sample_path_construct_id
      ),
      '[]'::jsonb
    ),
    count(*)::integer
  INTO v_variants, v_hash_variants, v_variant_count
  FROM variant_rows;

  WITH variant_rows AS MATERIALIZED (
    SELECT
      construct.id AS sample_path_construct_id,
      construct.sample_original_path_id,
      COALESCE(NULLIF(btrim(construct.pitch_content), ''), '0')
        AS pitch_content,
      GREATEST(construct.velocity, 0) AS velocity,
      GREATEST(construct.round_robin, 0) AS round_robin,
      COALESCE(NULLIF(btrim(construct.mic_position), ''), 'main')
        AS mic_position,
      COALESCE(
        NULLIF(
          regexp_replace(
            btrim(construct.filename),
            '\.(mp3|ogg|wav|aif|aiff|flac|ncw)$',
            '',
            'i'
          ),
          ''
        ),
        '0'
      ) AS filename,
      CASE
        WHEN lower(btrim(construct.midi_note)) = 'pitchless' THEN NULL
        WHEN btrim(construct.midi_note) ~ '^[0-9]{1,3}$'
          AND btrim(construct.midi_note)::integer BETWEEN 0 AND 127
          THEN btrim(construct.midi_note)::integer
        ELSE NULL
      END AS midi_note,
      (
        lower(btrim(construct.midi_note)) = 'pitchless'
        OR (
          btrim(construct.midi_note) ~ '^[0-9]{1,3}$'
          AND btrim(construct.midi_note)::integer BETWEEN 0 AND 127
        )
      ) AS midi_note_valid,
      construct.playback_type::text AS playback_type,
      CASE
        WHEN librosa.duration IS NULL THEN NULL
        WHEN librosa.duration::text IN ('NaN', 'Infinity', '-Infinity') THEN NULL
        WHEN librosa.duration <= 0 OR librosa.duration > 2147483.647 THEN NULL
        ELSE round(librosa.duration * 1000.0)::integer
      END AS duration_ms,
      CASE
        WHEN librosa.duration IS NULL THEN false
        WHEN librosa.duration::text IN ('NaN', 'Infinity', '-Infinity') THEN true
        ELSE librosa.duration <= 0 OR librosa.duration > 2147483.647
      END AS duration_invalid,
      cue.sync_point_ms,
      cue.loop_start_offset_ms,
      cue.loop_end_offset_ms,
      COALESCE(cue.swell_eligible, false) AS swell_eligible,
      COALESCE(cue.crash_eligible, false) AS crash_eligible,
      construct.filename IS NULL OR btrim(construct.filename) = ''
        OR construct.sample_original_path_id IS NULL AS metadata_incomplete
    FROM public.sample_path_constructs construct
    LEFT JOIN public.sample_playback_cues cue
      ON cue.sample_path_construct_id = construct.id
    LEFT JOIN public.analysis_librosa librosa
      ON librosa.sample_id = construct.sample_original_path_id
    WHERE construct.instrument_v2_id = p_instrument_v2_id
  ),
  duplicate_groups AS (
    SELECT
      pitch_content,
      velocity,
      round_robin,
      mic_position,
      filename,
      midi_note,
      count(*)::integer AS duplicate_count,
      jsonb_agg(sample_path_construct_id ORDER BY sample_path_construct_id)
        AS sample_path_construct_ids
    FROM variant_rows
    GROUP BY
      pitch_content,
      velocity,
      round_robin,
      mic_position,
      filename,
      midi_note
    HAVING count(*) > 1
  ),
  reason_rows AS (
    SELECT
      'duplicate_runtime_variant_identity'::text AS code,
      jsonb_build_object(
        'duplicates',
        jsonb_agg(
          jsonb_build_object(
            'pitchContent', pitch_content,
            'velocity', velocity,
            'roundRobin', round_robin,
            'micPosition', mic_position,
            'filename', filename,
            'midiNote', midi_note,
            'count', duplicate_count,
            'samplePathConstructIds', sample_path_construct_ids
          )
          ORDER BY
            pitch_content,
            velocity,
            round_robin,
            mic_position,
            filename,
            midi_note NULLS FIRST
        )
      ) AS details
    FROM duplicate_groups
    HAVING count(*) > 0

    UNION ALL

    SELECT
      'invalid_midi_note',
      jsonb_build_object(
        'count', count(*),
        'samplePathConstructIds',
        jsonb_agg(sample_path_construct_id ORDER BY sample_path_construct_id)
      )
    FROM variant_rows
    WHERE NOT midi_note_valid
    HAVING count(*) > 0

    UNION ALL

    SELECT
      'incomplete_metadata',
      jsonb_build_object(
        'count', count(*),
        'samplePathConstructIds',
        jsonb_agg(sample_path_construct_id ORDER BY sample_path_construct_id)
      )
    FROM variant_rows
    WHERE metadata_incomplete
    HAVING count(*) > 0

    UNION ALL

    SELECT
      'invalid_duration',
      jsonb_build_object(
        'count', count(*),
        'samplePathConstructIds',
        jsonb_agg(sample_path_construct_id ORDER BY sample_path_construct_id)
      )
    FROM variant_rows
    WHERE duration_invalid
    HAVING count(*) > 0

    UNION ALL

    SELECT
      'missing_duration',
      jsonb_build_object(
        'count', count(*),
        'samplePathConstructIds',
        jsonb_agg(sample_path_construct_id ORDER BY sample_path_construct_id)
      )
    FROM variant_rows
    WHERE duration_ms IS NULL
      AND NOT duration_invalid
      AND (
        playback_type IN ('looped', 'legato_transition')
        OR sync_point_ms IS NOT NULL
        OR loop_start_offset_ms IS NOT NULL
        OR loop_end_offset_ms IS NOT NULL
        OR swell_eligible
        OR crash_eligible
      )
    HAVING count(*) > 0

    UNION ALL

    SELECT
      'missing_sync_point',
      jsonb_build_object(
        'count', count(*),
        'samplePathConstructIds',
        jsonb_agg(sample_path_construct_id ORDER BY sample_path_construct_id)
      )
    FROM variant_rows
    WHERE sync_point_ms IS NULL AND (swell_eligible OR crash_eligible)
    HAVING count(*) > 0

    UNION ALL

    SELECT
      'invalid_timing_bounds',
      jsonb_build_object(
        'count', count(*),
        'toleranceMs', 1,
        'samplePathConstructIds',
        jsonb_agg(sample_path_construct_id ORDER BY sample_path_construct_id)
      )
    FROM variant_rows
    WHERE
      sync_point_ms < 0
      OR loop_start_offset_ms < 0
      OR loop_end_offset_ms < 0
      OR (loop_start_offset_ms IS NULL) <> (loop_end_offset_ms IS NULL)
      OR (
        loop_start_offset_ms IS NOT NULL
        AND loop_end_offset_ms <= loop_start_offset_ms
      )
      OR (
        duration_ms IS NOT NULL
        AND (
          sync_point_ms > duration_ms + 1
          OR loop_start_offset_ms > duration_ms + 1
          OR loop_end_offset_ms > duration_ms + 1
        )
      )
    HAVING count(*) > 0

    UNION ALL

    SELECT
      'round_robin_eligibility_violation',
      jsonb_build_object(
        'count', count(*),
        'slots', jsonb_agg(
          jsonb_build_object(
            'pitchContent', violation.pitch_content,
            'velocity', violation.velocity,
            'micPosition', violation.mic_position,
            'filename', violation.filename
          )
          ORDER BY
            violation.pitch_content,
            violation.velocity,
            violation.mic_position,
            violation.filename
        )
      )
    FROM public.round_robin_cue_eligibility_violations_v1 violation
    WHERE violation.instrument_v2_id = p_instrument_v2_id
    HAVING count(*) > 0

    UNION ALL

    SELECT
      'missing_variants',
      jsonb_build_object('count', 0)
    WHERE v_variant_count = 0
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object('code', code) || details
      ORDER BY code, details::text
    ),
    '[]'::jsonb
  )
  INTO v_blocking_reasons
  FROM reason_rows;

  v_manifest_sha256 := encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'version', 1,
          'variants', v_hash_variants
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  RETURN jsonb_build_object(
    'instrumentV2Id', p_instrument_v2_id,
    'schemaVersion', 1,
    'variants', v_variants,
    'variantCount', v_variant_count,
    'manifestSha256', v_manifest_sha256,
    'isComplete', jsonb_array_length(v_blocking_reasons) = 0,
    'blockingReasons', v_blocking_reasons
  );
END;
$_$;


ALTER FUNCTION "public"."build_instrument_runtime_sample_manifest_v1"("p_instrument_v2_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."build_instrument_runtime_sample_manifest_v1"("p_instrument_v2_id" "uuid") IS 'Builds one deterministic runtime manifest candidate without persisting it. Safe for read-only SIP audits.';



CREATE OR REPLACE FUNCTION "public"."build_instrument_v2_runtime_readiness_v1"("p_instrument_v2_id" "uuid", "p_candidate" "jsonb", "p_address_pending" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_address_ready boolean;
  v_address_status text;
  v_behavior_ready boolean;
  v_blockers jsonb;
  v_behavior_blockers jsonb;
  v_address_blocker jsonb;
  v_fallback_state text;
BEGIN
  IF jsonb_typeof(p_candidate) IS DISTINCT FROM 'object'
    OR COALESCE(p_candidate->>'manifestSha256', '') !~ '^[0-9a-f]{64}$'
    OR jsonb_typeof(p_candidate->'blockingReasons') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_candidate->'variants') IS DISTINCT FROM 'array'
    OR p_candidate->>'schemaVersion' IS DISTINCT FROM '1'
    OR jsonb_typeof(p_candidate->'isComplete') IS DISTINCT FROM 'boolean'
    OR COALESCE(p_candidate->>'variantCount', '') !~ '^[0-9]+$'
    OR (p_candidate->>'variantCount')::integer
      IS DISTINCT FROM jsonb_array_length(p_candidate->'variants')
  THEN
    RAISE EXCEPTION 'runtime_manifest_candidate_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF p_candidate->>'instrumentV2Id' IS DISTINCT FROM p_instrument_v2_id::text THEN
    RAISE EXCEPTION 'runtime_manifest_candidate_instrument_mismatch'
      USING ERRCODE = '22023';
  END IF;

  -- Address readiness is independent, current public-output evidence. It is
  -- never inferred from manifest metadata or behavior completeness.
  SELECT
    NULLIF(btrim(instrument.file_path_reference), '') IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.sample_path_constructs construct
        JOIN public.samples_original_paths source
          ON source.id = construct.sample_original_path_id
        WHERE construct.instrument_v2_id = p_instrument_v2_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.sample_path_constructs construct
        JOIN public.samples_original_paths source
          ON source.id = construct.sample_original_path_id
        WHERE construct.instrument_v2_id = p_instrument_v2_id
          AND NOT EXISTS (
            SELECT 1
            FROM public.instrument_v2_publish_output_manifest output
            WHERE output.instrument_v2_id = p_instrument_v2_id
              AND output.sample_path_construct_id = construct.id
              AND output.original_sample_id = construct.sample_original_path_id
              AND output.fingerprint_schema = 'sip-v2-output-v2'
              AND output.status = 'completed'
              AND jsonb_typeof(output.output_object_identity) = 'object'
              AND NULLIF(
                btrim(output.output_object_identity->>'eTag'),
                ''
              ) IS NOT NULL
              AND jsonb_typeof(
                output.output_object_identity->'contentLength'
              ) = 'number'
              AND (
                output.output_object_identity->>'contentLength'
              )::numeric >= 0
              AND output.processed_at >= construct.updated_at
              AND output.processing_input->>'fingerprintSchema' =
                'sip-v2-output-v2'
              AND output.processing_input->>'instrumentV2Id' =
                p_instrument_v2_id::text
              AND output.processing_input->>'filePathReference' =
                instrument.file_path_reference
              AND output.processing_input->>'samplePathConstructId' =
                construct.id::text
              AND output.processing_input->>'originalSampleId' =
                construct.sample_original_path_id::text
              AND jsonb_typeof(
                output.processing_input->'sourceObjectIdentity'
              ) = 'object'
              AND NULLIF(btrim(
                output.processing_input->'sourceObjectIdentity'->>'eTag'
              ), '') IS NOT NULL
              AND output.processing_input->>'sourceS3Key' = source.s3_path
              AND output.processing_input->>'pitchContent' =
                COALESCE(NULLIF(btrim(construct.pitch_content), ''), '0')
              AND output.processing_input->>'midiNote' = CASE
                WHEN construct.midi_note = 'pitchless'
                  AND construct.filename = 'pitchless'
                  AND construct.pitch_content = '0'
                THEN '0'
                ELSE btrim(construct.midi_note)
              END
              AND output.processing_input->>'velocity' =
                GREATEST(COALESCE(construct.velocity, 0), 0)::text
              AND output.processing_input->>'roundRobin' =
                GREATEST(COALESCE(construct.round_robin, 0), 0)::text
              AND output.processing_input->>'micPosition' =
                COALESCE(NULLIF(btrim(construct.mic_position), ''), 'main')
              AND output.processing_input->>'filename' =
                btrim(construct.filename)
              AND output.processing_input->'target'->>'s3Key' =
                output.destination_s3_key
              AND output.processing_input->'target'->>'format' = output.format
              AND output.processing_input->'target'->>'quality' =
                output.quality::text
            GROUP BY output.sample_path_construct_id
            HAVING count(DISTINCT (output.format, output.quality)) = 9
              AND count(*) FILTER (
                WHERE output.format = 'mp3' AND output.quality BETWEEN 1 AND 5
              ) = 5
              AND count(*) FILTER (
                WHERE output.format = 'ogg' AND output.quality BETWEEN 2 AND 5
              ) = 4
          )
      )
  INTO v_address_ready
  FROM public.instruments_v2 instrument
  WHERE instrument.id = p_instrument_v2_id;

  v_address_ready := COALESCE(v_address_ready, false);
  v_address_status := CASE
    WHEN v_address_ready THEN 'ready'
    WHEN p_address_pending THEN 'pending'
    ELSE 'blocked'
  END;
  v_behavior_ready := COALESCE((p_candidate->>'isComplete')::boolean, false);

  v_fallback_state := CASE
    WHEN NOT v_address_ready THEN 'blocked'
    WHEN v_behavior_ready THEN 'runtime_manifest'
    WHEN v_address_ready THEN 'construct_hydration'
  END;

  SELECT COALESCE(
    jsonb_agg(
      reason || jsonb_build_object(
        'readinessClass', 'behavior',
        'remediationClass', CASE
          WHEN reason->>'code' IN (
            'duplicate_runtime_variant_identity', 'invalid_midi_note',
            'incomplete_metadata', 'missing_variants'
          ) THEN 'construct_review'
          WHEN reason->>'code' IN ('invalid_duration', 'missing_duration')
            THEN 'source_analysis'
          WHEN reason->>'code' IN (
            'missing_sync_point',
            'invalid_timing_bounds'
          ) THEN 'cue_review'
          WHEN reason->>'code' = 'round_robin_eligibility_violation'
            THEN 'rr_eligibility'
          ELSE 'runtime_manifest_review'
        END
      )
      ORDER BY reason->>'code', reason::text
    ),
    '[]'::jsonb
  ) INTO v_behavior_blockers
  FROM jsonb_array_elements(p_candidate->'blockingReasons') reason;

  v_address_blocker := CASE
    WHEN v_address_ready THEN '[]'::jsonb
    WHEN p_address_pending THEN jsonb_build_array(jsonb_build_object(
      'code', 'address_evidence_pending',
      'readinessClass', 'address',
      'remediationClass', 'publish_outputs'
    ))
    ELSE jsonb_build_array(jsonb_build_object(
      'code', 'address_output_receipts_incomplete',
      'readinessClass', 'address',
      'remediationClass', 'publish_outputs'
    ))
  END;
  v_blockers := v_address_blocker || v_behavior_blockers;

  RETURN jsonb_build_object(
    'instrumentV2Id', p_candidate->>'instrumentV2Id',
    'manifestSha256', p_candidate->>'manifestSha256',
    'variantCount', (p_candidate->>'variantCount')::integer,
    'addressReady', v_address_ready,
    'addressStatus', v_address_status,
    'behaviorReady', v_behavior_ready,
    'fallbackEligibility', CASE
      WHEN v_behavior_ready THEN 'runtime_manifest'
      ELSE 'construct_hydration'
    END,
    'fallbackState', v_fallback_state,
    'blockers', v_blockers
  );
END;
$_$;


ALTER FUNCTION "public"."build_instrument_v2_runtime_readiness_v1"("p_instrument_v2_id" "uuid", "p_candidate" "jsonb", "p_address_pending" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."build_instrument_v2_runtime_readiness_v1"("p_instrument_v2_id" "uuid", "p_candidate" "jsonb", "p_address_pending" boolean) IS 'Builds deterministic runtime address and behavior readiness; canonical pitchless storage tokens map to runtime MIDI 0 only when pitch, filename, and pitch-content identity agree.';



CREATE OR REPLACE FUNCTION "public"."build_sip_staging_instruments_payload"("p_contributor_slug" "text", "p_search" "text" DEFAULT ''::"text", "p_path_search" "text" DEFAULT ''::"text", "p_status_filter" "text" DEFAULT 'all'::"text", "p_warning_filter" "text" DEFAULT 'all'::"text", "p_sort_by" "text" DEFAULT 'sampleCount'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_round_robin_filter" "text" DEFAULT 'all'::"text", "p_instrument_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
WITH args AS (
  SELECT
    regexp_replace(
      regexp_replace(lower(btrim(coalesce(p_contributor_slug, ''))), '[_\s]+', '-', 'g'),
      '-+',
      '-',
      'g'
    ) AS contributor_slug,
    btrim(coalesce(p_search, '')) AS search,
    btrim(coalesce(p_path_search, '')) AS path_search,
    lower(btrim(coalesce(p_status_filter, 'all'))) AS status_filter,
    lower(btrim(coalesce(p_warning_filter, 'all'))) AS warning_filter,
    lower(btrim(coalesce(p_round_robin_filter, 'all'))) AS round_robin_filter,
    coalesce(p_instrument_ids, ARRAY[]::uuid[]) AS instrument_ids,
    coalesce(nullif(btrim(p_sort_by), ''), 'sampleCount') AS sort_by,
    CASE WHEN lower(btrim(coalesce(p_sort_dir, 'desc'))) = 'asc' THEN 'asc' ELSE 'desc' END AS sort_dir,
    CASE
      WHEN p_limit IS NULL THEN NULL::integer
      ELSE least(greatest(coalesce(p_limit, 50), 1), 500)
    END AS limit_value,
    greatest(coalesce(p_offset, 0), 0) AS offset_value
),
scope_counts AS (
  SELECT
    scope.sip_review_instrument_id,
    count(*)::integer AS scope_count
  FROM public.sip_review_instrument_sample_scope scope
  JOIN args ON scope.contributor_slug = args.contributor_slug
  GROUP BY scope.sip_review_instrument_id
),
candidate_base AS (
  SELECT
    sri.id,
    sri.source_sip_instrument_id,
    sri.source_contributor_slug,
    sri.source_group_key,
    coalesce(nullif(btrim(sri.name), ''), 'Unnamed') AS name,
    nullif(btrim(sri.collection), '') AS collection,
    sri.engine_type::text AS engine_type,
    sri.playback_type::text AS playback_type,
    nullif(btrim(sri.polyphony_type::text), '') AS polyphony_type,
    btrim(sri.instrument_family) AS instrument_family,
    nullif(btrim(sri.instrument_type), '') AS instrument_type,
    sri.contributor_id,
    sri.pitch_contents,
    sri.pitch_content_config,
    sri.velocity_layers,
    sri.range_lower,
    sri.range_upper,
    sri.single_pitch,
    sri.gain,
    sri.sustain_crop_time,
    sri.articulations,
    sri.effects_instruments,
    sri.mic_positions,
    sri.round_robins,
    nullif(btrim(sri.articulation), '') AS articulation,
    nullif(btrim(sri.effect), '') AS effect,
    sri.legato_transition,
    sri.original_sample_ids,
    cardinality(coalesce(sri.original_sample_ids, ARRAY[]::uuid[]))::integer AS original_sample_count,
    coalesce(scope_counts.scope_count, 0)::integer AS scope_count,
    CASE
      WHEN coalesce(scope_counts.scope_count, 0) > 0 THEN scope_counts.scope_count
      ELSE cardinality(coalesce(sri.original_sample_ids, ARRAY[]::uuid[]))
    END::integer AS sample_count,
    sri.original_file_path_reference,
    sri.original_file_name_references,
    sri.published,
    sri.updated_at,
    sri.is_retired,
    sri.split_parent_sip_review_instrument_id,
    rpm.instrument_v2_id,
    CASE
      WHEN sri.is_retired THEN 'retired'
      WHEN rpm.instrument_v2_id IS NOT NULL THEN 'promoted'
      ELSE 'staged'
    END AS staging_status,
    lower(coalesce(nullif(btrim(source.name), ''), nullif(btrim(sri.name), ''), 'Unnamed')) AS warning_key
  FROM public.sip_review_instrument sri
  JOIN args ON true
  LEFT JOIN public.sip_instrument source
    ON source.id = sri.source_sip_instrument_id
  LEFT JOIN public.sip_review_promotion_map rpm
    ON rpm.sip_review_instrument_id = sri.id
  LEFT JOIN scope_counts
    ON scope_counts.sip_review_instrument_id = sri.id
  WHERE sri.source_contributor_slug = args.contributor_slug
    AND (
      cardinality(args.instrument_ids) = 0
      OR sri.id = ANY(args.instrument_ids)
    )
    AND (
      args.search = ''
      OR sri.name ILIKE ('%' || args.search || '%')
    )
    AND (
      args.path_search = ''
      OR sri.original_file_path_reference ILIKE ('%' || args.path_search || '%')
      OR EXISTS (
        SELECT 1
        FROM unnest(coalesce(sri.original_file_name_references, ARRAY[]::text[])) AS file_name(value)
        WHERE file_name.value ILIKE ('%' || args.path_search || '%')
      )
    )
),
status_filtered AS (
  SELECT candidate_base.*
  FROM candidate_base
  CROSS JOIN args
  WHERE CASE
    WHEN args.status_filter = 'all'
      THEN candidate_base.staging_status NOT IN ('retired', 'promoted')
    WHEN args.status_filter IN ('staged', 'promoted', 'retired')
      THEN candidate_base.staging_status = args.status_filter
    ELSE false
  END
),
warning_names AS (
  SELECT DISTINCT warning_key
  FROM status_filtered
  WHERE warning_key IS NOT NULL AND warning_key <> ''
),
construct_field_presence AS (
  SELECT
    sc.contributor_slug,
    sc.original_sample_id,
    bool_or(nullif(btrim(sc.articulation), '') IS NOT NULL) AS has_articulation,
    bool_or(nullif(btrim(sc.effect), '') IS NOT NULL) AS has_effect,
    bool_or(nullif(btrim(sc.mic_position), '') IS NOT NULL) AS has_mic_position
  FROM public.sip_sample_construct sc
  JOIN args
    ON sc.contributor_slug = args.contributor_slug
  JOIN warning_names
    ON warning_names.warning_key = lower(sc.instrument_name)
  WHERE sc.original_sample_id IS NOT NULL
  GROUP BY sc.contributor_slug, sc.original_sample_id
),
warning_by_name AS (
  SELECT
    lower(sc.instrument_name) AS warning_key,
    count(*) FILTER (
      WHERE sc.confidence IS NOT NULL
        AND sc.confidence ~ '^[+-]?[0-9]+(\.[0-9]+)?$'
        AND sc.confidence::numeric < 0.5
    )::integer AS warning_count,
    coalesce(sum(
      (CASE WHEN coalesce(cfp.has_articulation, false) AND lower(sa.articulation_cosine_threshold_band) IN ('mismatch', 'ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN coalesce(cfp.has_effect, false) AND lower(sa.effect_cosine_threshold_band) IN ('mismatch', 'ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN coalesce(cfp.has_mic_position, false) AND lower(sa.mic_position_cosine_threshold_band) IN ('mismatch', 'ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN lower(sa.collision_cosine_threshold_band) IN ('mismatch', 'ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN lower(sa.velocity_cosine_threshold_band) IN ('mismatch', 'ambiguous') THEN 1 ELSE 0 END)
    ), 0)::integer AS anomaly_count
  FROM public.sip_sample_construct sc
  JOIN args
    ON sc.contributor_slug = args.contributor_slug
  JOIN warning_names
    ON warning_names.warning_key = lower(sc.instrument_name)
  LEFT JOIN public.sip_sample_analysis sa
    ON sa.original_sample_id = sc.original_sample_id
   AND sa.contributor_slug = sc.contributor_slug
  LEFT JOIN construct_field_presence cfp
    ON cfp.contributor_slug = sc.contributor_slug
   AND cfp.original_sample_id = sc.original_sample_id
  GROUP BY lower(sc.instrument_name)
),
filtered AS (
  SELECT
    status_filtered.*,
    coalesce(warning_by_name.warning_count, 0)::integer AS warning_count,
    coalesce(warning_by_name.anomaly_count, 0)::integer AS anomaly_count
  FROM status_filtered
  CROSS JOIN args
  LEFT JOIN warning_by_name
    ON warning_by_name.warning_key = status_filtered.warning_key
  WHERE CASE
    WHEN args.warning_filter = 'warnings'
      THEN coalesce(warning_by_name.warning_count, 0) > 0
    WHEN args.warning_filter = 'anomalies'
      THEN coalesce(warning_by_name.anomaly_count, 0) > 0
    ELSE true
  END
),
sort_metrics AS (
  SELECT
    filtered.*,
    CASE
      WHEN filtered.pitch_contents IS NULL OR jsonb_typeof(filtered.pitch_contents) = 'null'
        THEN 0::double precision
      WHEN jsonb_typeof(filtered.pitch_contents) = 'array'
        THEN jsonb_array_length(filtered.pitch_contents)::double precision
      WHEN jsonb_typeof(filtered.pitch_contents) = 'object'
        THEN (
          SELECT count(*)::double precision
          FROM jsonb_object_keys(filtered.pitch_contents) AS key
        )
      WHEN jsonb_typeof(filtered.pitch_contents) IN ('number', 'string')
       AND filtered.pitch_contents #>> '{}' ~ '^[+-]?[0-9]+(\.[0-9]+)?$'
        THEN (filtered.pitch_contents #>> '{}')::double precision
      ELSE 0::double precision
    END AS pitch_content_count,
    CASE
      WHEN filtered.velocity_layers IS NULL OR jsonb_typeof(filtered.velocity_layers) = 'null'
        THEN 1::double precision
      WHEN jsonb_typeof(filtered.velocity_layers) = 'array'
        THEN jsonb_array_length(filtered.velocity_layers)::double precision
      WHEN jsonb_typeof(filtered.velocity_layers) = 'object'
        THEN coalesce((
          SELECT max(trunc((layer.value #>> '{}')::double precision)) + 1
          FROM jsonb_each(filtered.velocity_layers) AS entry(key, value)
          CROSS JOIN LATERAL jsonb_array_elements(
            CASE
              WHEN jsonb_typeof(entry.value) = 'array' THEN entry.value
              ELSE '[]'::jsonb
            END
          ) AS layer(value)
          WHERE layer.value #>> '{}' ~ '^[+-]?[0-9]+(\.[0-9]+)?$'
            AND trunc((layer.value #>> '{}')::double precision) >= 0
        ), 1::double precision)
      WHEN jsonb_typeof(filtered.velocity_layers) IN ('number', 'string')
       AND filtered.velocity_layers #>> '{}' ~ '^[+-]?[0-9]+(\.[0-9]+)?$'
        THEN greatest(1, trunc((filtered.velocity_layers #>> '{}')::double precision))::double precision
      ELSE 1::double precision
    END AS velocity_layer_count
  FROM filtered
),
sort_values AS (
  SELECT
    sort_metrics.*,
    args.sort_dir,
    CASE
      WHEN args.sort_by = 'sampleCount' THEN sort_metrics.sample_count::double precision
      WHEN args.sort_by = 'originalSampleCount' THEN sort_metrics.original_sample_count::double precision
      WHEN args.sort_by IN ('polyphonySets', 'pitchContents') THEN sort_metrics.pitch_content_count
      WHEN args.sort_by = 'velocityLayers' THEN sort_metrics.velocity_layer_count
      WHEN args.sort_by = 'range' THEN coalesce(sort_metrics.range_lower, sort_metrics.single_pitch, 0)::double precision
      WHEN args.sort_by = 'singlePitch' THEN coalesce(sort_metrics.single_pitch, -1)::double precision
      WHEN args.sort_by = 'gain' THEN coalesce(sort_metrics.gain, 0)::double precision
      WHEN args.sort_by = 'sustainCropTime' THEN coalesce(sort_metrics.sustain_crop_time, 0)::double precision
      WHEN args.sort_by = 'published' THEN CASE WHEN sort_metrics.published THEN 1 ELSE 0 END::double precision
      WHEN args.sort_by = 'warningCount' THEN sort_metrics.warning_count::double precision
      WHEN args.sort_by = 'anomalyCount' THEN sort_metrics.anomaly_count::double precision
      WHEN args.sort_by = 'fileNameReferences' THEN coalesce(array_length(sort_metrics.original_file_name_references, 1), 0)::double precision
      WHEN args.sort_by NOT IN (
        'instrumentName', 'name', 'collection', 'collections', 'type',
        'engineType', 'playbackType', 'polyphonyType', 'instrumentFamily',
        'instrumentType', 'contributorId', 'polyphonyConfig', 'pitchContentConfig',
        'filePathReference', 'originalSampleIds',
        'articulations', 'effectsInstruments', 'micPositions', 'velocities',
        'legatoTransition',
        'promotedInstrumentV2Id', 'status', 'stagingStatus', 'updatedAt',
        'articulation', 'effect', 'roundRobins'
      ) THEN sort_metrics.sample_count::double precision
      ELSE NULL::double precision
    END AS numeric_sort,
    CASE
      WHEN args.sort_by IN ('instrumentName', 'name') THEN sort_metrics.name
      WHEN args.sort_by IN ('collection', 'collections') THEN coalesce(sort_metrics.collection, '')
      WHEN args.sort_by IN ('type', 'engineType') THEN sort_metrics.engine_type
      WHEN args.sort_by = 'playbackType' THEN sort_metrics.playback_type
      WHEN args.sort_by = 'polyphonyType' THEN coalesce(sort_metrics.polyphony_type, '')
      WHEN args.sort_by = 'instrumentFamily' THEN coalesce(sort_metrics.instrument_family, '')
      WHEN args.sort_by = 'instrumentType' THEN coalesce(sort_metrics.instrument_type, '')
      WHEN args.sort_by = 'contributorId' THEN coalesce(sort_metrics.contributor_id::text, '')
      WHEN args.sort_by IN ('polyphonyConfig', 'pitchContentConfig') THEN coalesce(sort_metrics.pitch_content_config::text, '')
      WHEN args.sort_by = 'filePathReference' THEN coalesce(sort_metrics.original_file_path_reference, '')
      WHEN args.sort_by = 'originalSampleIds' THEN array_to_string(coalesce(sort_metrics.original_sample_ids, ARRAY[]::uuid[]), ',')
      WHEN args.sort_by = 'articulations' THEN array_to_string(coalesce(sort_metrics.articulations, ARRAY[]::uuid[])::text[], ',')
      WHEN args.sort_by = 'effectsInstruments' THEN array_to_string(coalesce(sort_metrics.effects_instruments, ARRAY[]::uuid[])::text[], ',')
      WHEN args.sort_by = 'micPositions' THEN coalesce(sort_metrics.mic_positions::text, '')
      WHEN args.sort_by = 'velocities' THEN sort_metrics.velocity_layers::text
      WHEN args.sort_by = 'legatoTransition' THEN coalesce(sort_metrics.legato_transition::text, '')
      WHEN args.sort_by = 'promotedInstrumentV2Id' THEN coalesce(sort_metrics.instrument_v2_id::text, '')
      WHEN args.sort_by IN ('status', 'stagingStatus') THEN sort_metrics.staging_status
      WHEN args.sort_by = 'updatedAt' THEN coalesce(sort_metrics.updated_at::text, '')
      WHEN args.sort_by = 'articulation' THEN coalesce(sort_metrics.articulation, '')
      WHEN args.sort_by = 'effect' THEN coalesce(sort_metrics.effect, '')
      WHEN args.sort_by = 'roundRobins' THEN coalesce(sort_metrics.round_robins::text, '')
      ELSE NULL::text
    END AS text_sort
  FROM sort_metrics
  CROSS JOIN args
),
ordered AS (
  SELECT
    sort_values.*,
    row_number() OVER (
      ORDER BY
        CASE WHEN sort_values.sort_dir = 'asc' THEN sort_values.numeric_sort END ASC NULLS LAST,
        CASE WHEN sort_values.sort_dir = 'desc' THEN sort_values.numeric_sort END DESC NULLS LAST,
        CASE WHEN sort_values.sort_dir = 'asc' THEN sort_values.text_sort END ASC NULLS LAST,
        CASE WHEN sort_values.sort_dir = 'desc' THEN sort_values.text_sort END DESC NULLS LAST,
        sort_values.id ASC
    ) AS row_order,
    count(*) OVER () AS total_count
  FROM sort_values
),
limited AS (
  SELECT ordered.*
  FROM ordered
  CROSS JOIN args
  WHERE args.limit_value IS NULL
    OR (
      ordered.row_order > args.offset_value
      AND ordered.row_order <= args.offset_value + args.limit_value
    )
)
SELECT jsonb_build_object(
  'rows',
  coalesce(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'rowOrder', ordered.row_order,
          'id', ordered.id::text,
          'sourceTmpInstrumentV2Id', ordered.source_sip_instrument_id::text,
          'sourceContributorSlug', ordered.source_contributor_slug,
          'sourceGroupKey', coalesce(ordered.source_group_key, ''),
          'name', ordered.name,
          'collection', ordered.collection,
          'engineType', ordered.engine_type,
          'playbackType', ordered.playback_type,
          'polyphonyType', ordered.polyphony_type,
          'instrumentFamily', ordered.instrument_family,
          'instrumentType', ordered.instrument_type,
          'contributorId', ordered.contributor_id::text,
          'polyphonySets', ordered.pitch_contents,
          'polyphonyConfig', ordered.pitch_content_config,
          'velocityLayers', ordered.velocity_layers,
          'rangeLower', ordered.range_lower,
          'rangeUpper', ordered.range_upper,
          'singlePitch', ordered.single_pitch,
          'gain', ordered.gain,
          'sustainCropTime', ordered.sustain_crop_time,
          'velocities', jsonb_build_array(ordered.velocity_layers::text),
          'articulations', to_jsonb(coalesce(ordered.articulations, ARRAY[]::uuid[])),
          'effectsInstruments', to_jsonb(coalesce(ordered.effects_instruments, ARRAY[]::uuid[])),
          'legatoTransition', ordered.legato_transition::text,
          'legatoTransitionInstrumentId', ordered.legato_transition::text,
          'micPositions', coalesce(ordered.mic_positions, '[]'::jsonb),
          'roundRobins', coalesce(to_jsonb(ordered.round_robins), 'null'::jsonb),
          'articulation', ordered.articulation,
          'effect', ordered.effect,
          'originalSampleIds', to_jsonb(coalesce(ordered.original_sample_ids, ARRAY[]::uuid[])),
          'originalSampleCount', ordered.original_sample_count,
          'sampleCount', ordered.sample_count,
          'originalFilePathReference', ordered.original_file_path_reference,
          'originalFileNameReferences', to_jsonb(coalesce(ordered.original_file_name_references, ARRAY[]::text[])),
          'filePathReference', ordered.original_file_path_reference,
          'fileNameReferences', to_jsonb(coalesce(ordered.original_file_name_references, ARRAY[]::text[])),
          'warningCount', ordered.warning_count,
          'anomalyCount', ordered.anomaly_count,
          'stagingStatus', ordered.staging_status,
          'promotedInstrumentV2Id', ordered.instrument_v2_id::text,
          'published', ordered.published,
          'updatedAt', ordered.updated_at,
          'isRetired', ordered.is_retired,
          'splitParentStagingInstrumentV2Id', ordered.split_parent_sip_review_instrument_id::text
        )
        ORDER BY ordered.row_order
      )
      FROM limited AS ordered
    ),
    '[]'::jsonb
  ),
  'totalCount', coalesce((SELECT max(ordered.total_count)::integer FROM ordered), 0)
);
$_$;


ALTER FUNCTION "public"."build_sip_staging_instruments_payload"("p_contributor_slug" "text", "p_search" "text", "p_path_search" "text", "p_status_filter" "text", "p_warning_filter" "text", "p_sort_by" "text", "p_sort_dir" "text", "p_round_robin_filter" "text", "p_instrument_ids" "uuid"[], "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bump_catalog_cache_resource_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(2173, 1);

  UPDATE public.catalog_cache_resource_revisions
  SET revision = revision + 1,
      updated_at = pg_catalog.clock_timestamp()
  WHERE resource = TG_ARGV[0];

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unknown catalog-cache resource: %', TG_ARGV[0];
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."bump_catalog_cache_resource_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_composer_profile"("target_composer_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  select
    auth.role() = 'authenticated'
    and (
      public.is_soundsculpt_staff()
      or (
        target_composer_id is not null
        and exists (
          select 1
          from public.composers c
          where c.id = target_composer_id
            and lower(coalesce(c.email, '')) = lower(coalesce(auth.jwt() ->> 'email', ''))
        )
      )
    );
$$;


ALTER FUNCTION "public"."can_manage_composer_profile"("target_composer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_sip_fleet_run"("p_run_id" "uuid", "p_provider_lease_token" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_changed boolean;
BEGIN
  UPDATE public.sip_fleet_runs run SET cancel_requested=true,cancel_reason=p_reason
  WHERE run.id=p_run_id AND run.status IN ('queued','running') AND EXISTS(
    SELECT 1 FROM public.sip_fleet_provider_leases lease WHERE lease.provider_slug=run.provider_slug
      AND lease.lease_token=p_provider_lease_token AND lease.lease_expires_at>now())
  RETURNING true INTO v_changed;
  IF coalesce(v_changed,false) THEN
    UPDATE public.sip_fleet_run_items SET status='canceled',finished_at=now()
    WHERE run_id=p_run_id AND status='queued';
    UPDATE public.sip_fleet_runs SET status='canceled',finished_at=now()
    WHERE id=p_run_id AND NOT EXISTS(SELECT 1 FROM public.sip_fleet_run_items WHERE run_id=p_run_id AND status='running');
  END IF;
  RETURN coalesce(v_changed,false);
END $$;


ALTER FUNCTION "public"."cancel_sip_fleet_run"("p_run_id" "uuid", "p_provider_lease_token" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_pipeline_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "contributor_slug" "text" NOT NULL,
    "mode" "text" DEFAULT 'run_all_contributor'::"text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "requested_by" "text",
    "worker_id" "text",
    "scope" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "batch_settings" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "selected_count" integer DEFAULT 0 NOT NULL,
    "queued_count" integer DEFAULT 0 NOT NULL,
    "running_count" integer DEFAULT 0 NOT NULL,
    "published_count" integer DEFAULT 0 NOT NULL,
    "blocked_count" integer DEFAULT 0 NOT NULL,
    "stalled_count" integer DEFAULT 0 NOT NULL,
    "failed_count" integer DEFAULT 0 NOT NULL,
    "cancelled_count" integer DEFAULT 0 NOT NULL,
    "current_stage" "text",
    "last_error" "text",
    "last_event_at" timestamp with time zone,
    "heartbeat_at" timestamp with time zone,
    "cancel_requested" boolean DEFAULT false NOT NULL,
    "cancel_reason" "text",
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sip_pipeline_runs_batch_settings_object" CHECK (("jsonb_typeof"("batch_settings") = 'object'::"text")),
    CONSTRAINT "sip_pipeline_runs_non_negative_counts" CHECK ((("selected_count" >= 0) AND ("queued_count" >= 0) AND ("running_count" >= 0) AND ("published_count" >= 0) AND ("blocked_count" >= 0) AND ("stalled_count" >= 0) AND ("failed_count" >= 0) AND ("cancelled_count" >= 0))),
    CONSTRAINT "sip_pipeline_runs_scope_object" CHECK (("jsonb_typeof"("scope") = 'object'::"text")),
    CONSTRAINT "sip_pipeline_runs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'paused'::"text", 'complete'::"text", 'blocked'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."sip_pipeline_runs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_sip_pipeline_run"("p_run_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."sip_pipeline_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run public.sip_pipeline_runs%ROWTYPE;
BEGIN
  UPDATE public.sip_pipeline_runs
  SET
    cancel_requested = true,
    cancel_reason = p_reason,
    status = 'cancelled',
    finished_at = COALESCE(finished_at, now()),
    updated_at = now()
  WHERE id = p_run_id
  RETURNING * INTO v_run;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sip_pipeline_run_not_found: %', p_run_id;
  END IF;

  UPDATE public.sip_pipeline_run_items
  SET
    status = 'cancelled',
    lease_owner = NULL,
    lease_expires_at = NULL,
    last_error = COALESCE(p_reason, last_error),
    finished_at = COALESCE(finished_at, now()),
    updated_at = now()
  WHERE run_id = p_run_id
    AND status IN ('queued', 'running');

  PERFORM public.record_sip_pipeline_run_event(
    p_run_id,
    NULL,
    NULL,
    NULL,
    'run_cancelled',
    p_reason,
    '{}'::jsonb
  );

  RETURN public.sip_pipeline_refresh_run_counts(p_run_id);
END;
$$;


