CREATE OR REPLACE FUNCTION "public"."cascade_sample_path_constructs_playback_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.playback_type IS DISTINCT FROM OLD.playback_type THEN
    UPDATE public.sample_path_constructs spc
    SET playback_type = NEW.playback_type,
        updated_at = now()
    WHERE spc.instrument_v2_id = NEW.id
      AND spc.playback_type IS DISTINCT FROM NEW.playback_type;
  END IF;

  RETURN NEW;
END;
$$;


