CREATE OR REPLACE FUNCTION "public"."claim_analysis_jobs"("p_worker_id" "text", "p_batch_size" integer DEFAULT 100, "p_stale_minutes" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "s3_path" "text", "file_name" "text", "meyda_512_analyzed" boolean, "meyda_1024_analyzed" boolean, "meyda_4096_analyzed" boolean, "aubio_analyzed" boolean)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_stale_threshold TIMESTAMPTZ;
BEGIN
  v_stale_threshold := now() - (p_stale_minutes || ' minutes')::INTERVAL;

  UPDATE public.samples_original_paths osp
  SET
    retry_count = osp.retry_count + 1,
    claimed_by = NULL,
    claimed_at = NULL,
    updated_at = now()
  WHERE osp.claimed_by IS NOT NULL
    AND osp.claimed_at < v_stale_threshold
    AND osp.retry_count < 3;

  RETURN QUERY
  WITH claimed AS (
    SELECT osp.id
    FROM public.samples_original_paths osp
    WHERE (
      osp.meyda_512_analyzed = false
      OR osp.meyda_1024_analyzed = false
      OR osp.meyda_4096_analyzed = false
      OR osp.aubio_analyzed = false
    )
      AND osp.licensing_secured = true
      AND osp.claimed_by IS NULL
      AND osp.retry_count < 3
    ORDER BY osp.created_at
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.samples_original_paths osp
  SET claimed_by = p_worker_id,
      claimed_at = now(),
      updated_at = now()
  FROM claimed c
  WHERE osp.id = c.id
  RETURNING
    osp.id,
    osp.s3_path,
    osp.file_name,
    osp.meyda_512_analyzed,
    osp.meyda_1024_analyzed,
    osp.meyda_4096_analyzed,
    osp.aubio_analyzed;
END;
$$;


ALTER FUNCTION "public"."claim_analysis_jobs"("p_worker_id" "text", "p_batch_size" integer, "p_stale_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_analysis_jobs"("p_worker_id" "text", "p_batch_size" integer, "p_stale_minutes" integer) IS 'Atomically claims a batch of analysis jobs for a worker.
Uses FOR UPDATE SKIP LOCKED to enable parallel workers without conflicts.
Parameters:
  - p_worker_id: Unique identifier for the worker claiming jobs
  - p_batch_size: Maximum number of jobs to claim (default: 100)
  - p_stale_minutes: Minutes after which claimed jobs are considered stale (default: 30)
Returns: Table of claimed jobs with id, s3_path, file_name, and analysis status flags';



CREATE OR REPLACE FUNCTION "public"."claim_deep_derived_analysis_jobs"("p_worker_id" "text", "p_batch_size" integer DEFAULT 100, "p_stale_minutes" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "sample_id" "uuid")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_stale_threshold TIMESTAMPTZ;
BEGIN
  v_stale_threshold := now() - (p_stale_minutes || ' minutes')::INTERVAL;

  UPDATE public.samples_original_paths osp
  SET retry_count = osp.retry_count + 1,
      claimed_by = NULL,
      claimed_at = NULL,
      updated_at = now()
  WHERE osp.claimed_by IS NOT NULL
    AND osp.claimed_at < v_stale_threshold
    AND osp.retry_count < 3
    AND (osp.librosa_analyzed = true OR osp.essentia_analyzed = true)
    AND osp.deep_derived_analyzed = false
    AND osp.licensing_secured = true;

  RETURN QUERY
  WITH claimed AS (
    SELECT osp.id
    FROM public.samples_original_paths osp
    WHERE (osp.librosa_analyzed = true OR osp.essentia_analyzed = true)
      AND osp.deep_derived_analyzed = false
      AND osp.licensing_secured = true
      AND osp.claimed_by IS NULL
      AND osp.retry_count < 3
    ORDER BY osp.created_at ASC
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.samples_original_paths osp
  SET claimed_by = p_worker_id,
      claimed_at = now(),
      updated_at = now()
  FROM claimed c
  WHERE osp.id = c.id
  RETURNING osp.id, osp.id AS sample_id;
END;
$$;


