    "reason" "text" DEFAULT 'manual'::"text" NOT NULL,
    "priority" integer DEFAULT 0 NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "lease_owner" "text",
    "lease_expires_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "last_error" "text",
    "sample_count" integer DEFAULT 0 NOT NULL,
    "analyzed_sample_count" integer DEFAULT 0 NOT NULL,
    "flagged_sample_count" integer DEFAULT 0 NOT NULL,
    "counts" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "warning_payload" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "result_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "instrument_audio_profile_jobs_v1_counts_nonnegative" CHECK ((("attempts" >= 0) AND ("max_attempts" > 0) AND ("sample_count" >= 0) AND ("analyzed_sample_count" >= 0) AND ("flagged_sample_count" >= 0))),
    CONSTRAINT "instrument_audio_profile_jobs_v1_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'completed'::"text", 'completed_with_warnings'::"text", 'failed'::"text", 'skipped_fresh'::"text"])))
);


ALTER TABLE "public"."instrument_audio_profile_jobs_v1" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_instrument_audio_profile_jobs_v1"("p_worker_id" "text", "p_limit" integer DEFAULT 1, "p_lease_seconds" integer DEFAULT 600) RETURNS SETOF "public"."instrument_audio_profile_jobs_v1"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH claimable AS (
    SELECT id
    FROM public.instrument_audio_profile_jobs_v1
    WHERE
      status = 'queued'
      OR (
        status = 'running'
        AND lease_expires_at IS NOT NULL
        AND lease_expires_at < now()
        AND attempts < max_attempts
      )
    ORDER BY priority DESC, created_at ASC, id ASC
    LIMIT GREATEST(COALESCE(p_limit, 1), 1)
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.instrument_audio_profile_jobs_v1 jobs
  SET
    status = 'running',
    lease_owner = COALESCE(NULLIF(p_worker_id, ''), 'anonymous-worker'),
    lease_expires_at = now() + make_interval(secs => GREATEST(COALESCE(p_lease_seconds, 600), 60)),
    started_at = COALESCE(jobs.started_at, now()),
    attempts = jobs.attempts + 1,
    updated_at = now()
  FROM claimable
  WHERE jobs.id = claimable.id
  RETURNING jobs.*;
END;
$$;


ALTER FUNCTION "public"."claim_instrument_audio_profile_jobs_v1"("p_worker_id" "text", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


