CREATE OR REPLACE FUNCTION "public"."claim_librosa_jobs"("p_worker_id" "text", "p_batch_size" integer DEFAULT 100, "p_stale_minutes" integer DEFAULT 30, "p_prioritize_path" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "s3_path" "text", "file_name" "text", "librosa_analyzed" boolean)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_stale_threshold TIMESTAMPTZ;
BEGIN
  v_stale_threshold := now() - (p_stale_minutes || ' minutes')::INTERVAL;

  UPDATE public.samples_original_paths osp
  SET retry_count = osp.retry_count + 1,
      claimed_by = NULL,
      claimed_at = NULL,
      updated_at = now()
  WHERE osp.claimed_by IS NOT NULL
    AND osp.claimed_at < v_stale_threshold
    AND osp.retry_count < 3;

  RETURN QUERY
  WITH claimed AS (
    SELECT osp.id
    FROM public.samples_original_paths osp
    WHERE osp.librosa_analyzed = false
      AND osp.licensing_secured = true
      AND osp.claimed_by IS NULL
      AND osp.retry_count < 3
    ORDER BY
      CASE
        WHEN p_prioritize_path IS NOT NULL AND trim(p_prioritize_path) != ''
          AND osp.s3_path ILIKE '%' || trim(p_prioritize_path) || '%'
        THEN 0
        ELSE 1
      END,
      osp.created_at
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.samples_original_paths osp
  SET claimed_by = p_worker_id,
      claimed_at = now(),
      updated_at = now()
  FROM claimed c
  WHERE osp.id = c.id
  RETURNING osp.id, osp.s3_path, osp.file_name, osp.librosa_analyzed;
END;
$$;


