COMMENT ON FUNCTION "public"."claim_librosa_jobs"("p_worker_id" "text", "p_batch_size" integer, "p_stale_minutes" integer, "p_prioritize_path" "text") IS 'Atomically claims a batch of librosa analysis jobs. When p_prioritize_path is set, jobs whose s3_path contains that string (case-insensitive) are claimed first.';



CREATE OR REPLACE FUNCTION "public"."claim_market_pattern_embedding_jobs"("p_worker_id" "text", "p_embedding_space" "text", "p_batch_size" integer DEFAULT 1, "p_lease_seconds" integer DEFAULT 300) RETURNS TABLE("job_id" "uuid", "market_pattern_id" "uuid", "embedding_space" "text", "requested_source_hash" "text", "force" boolean, "attempt_count" integer, "max_attempts" integer, "lease_token" "uuid")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NULLIF(btrim(p_worker_id), '') IS NULL THEN
    RAISE EXCEPTION 'p_worker_id is required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(p_embedding_space), '') IS NULL THEN
    RAISE EXCEPTION 'p_embedding_space is required' USING ERRCODE = '22023';
  END IF;
  IF p_batch_size NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'p_batch_size must be between 1 and 100'
      USING ERRCODE = '22023';
  END IF;
  IF p_lease_seconds NOT BETWEEN 15 AND 3600 THEN
    RAISE EXCEPTION 'p_lease_seconds must be between 15 and 3600'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.market_pattern_embedding_jobs AS expired
  SET
    status = CASE
      WHEN expired.attempt_count >= expired.max_attempts THEN 'failed'
      ELSE 'queued'
    END,
    available_at = CASE
      WHEN expired.attempt_count >= expired.max_attempts THEN expired.available_at
      ELSE now()
    END,
    lease_token = NULL,
    leased_by = NULL,
    lease_expires_at = NULL,
    last_heartbeat_at = NULL,
    last_error = concat_ws(E'\n', NULLIF(expired.last_error, ''), 'Lease expired'),
    completed_at = NULL
  WHERE expired.status = 'running'
    AND expired.embedding_space = p_embedding_space
    AND expired.lease_expires_at <= now();

  RETURN QUERY
  WITH claimable AS (
    SELECT jobs.id
    FROM public.market_pattern_embedding_jobs AS jobs
    WHERE jobs.status = 'queued'
      AND jobs.embedding_space = p_embedding_space
      AND jobs.available_at <= now()
      AND jobs.attempt_count < jobs.max_attempts
    ORDER BY jobs.priority DESC, jobs.available_at, jobs.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT p_batch_size
  ), claimed AS (
    UPDATE public.market_pattern_embedding_jobs AS jobs
    SET
      status = 'running',
      attempt_count = jobs.attempt_count + 1,
      lease_token = gen_random_uuid(),
      leased_by = p_worker_id,
      lease_expires_at = now() + make_interval(secs => p_lease_seconds),
      last_heartbeat_at = now(),
      started_at = COALESCE(jobs.started_at, now()),
      completed_at = NULL
    FROM claimable
    WHERE jobs.id = claimable.id
    RETURNING jobs.*
  )
  SELECT
    claimed.id,
    claimed.market_pattern_id,
    claimed.embedding_space,
    claimed.requested_source_hash,
    claimed.force,
    claimed.attempt_count,
    claimed.max_attempts,
    claimed.lease_token
  FROM claimed
  ORDER BY claimed.priority DESC, claimed.created_at;
END;
$$;


ALTER FUNCTION "public"."claim_market_pattern_embedding_jobs"("p_worker_id" "text", "p_embedding_space" "text", "p_batch_size" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_monthly_allowance"("p_user_id" "uuid", "p_policy_key" "text", "p_resource_kind" "text", "p_resource_id" "text", "p_idempotency_key" "text") RETURNS TABLE("allowed" boolean, "claim_id" "uuid", "idempotent" boolean, "policy_key" "text", "allowance_bucket" "text", "used" integer, "limit" integer, "remaining" integer, "resets_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_month date := date_trunc('month', timezone('UTC', clock_timestamp()))::date;
  v_next_month timestamptz := (date_trunc('month', timezone('UTC', clock_timestamp())) + interval '1 month') AT TIME ZONE 'UTC';
  v_policy public.monthly_allowance_policies%ROWTYPE;
  v_claim public.monthly_allowance_claims%ROWTYPE;
  v_existing boolean := false;
  v_used integer;
BEGIN
  IF p_user_id IS NULL OR p_policy_key IS NULL
     OR p_resource_kind IS NULL OR p_resource_kind !~ '^[a-z][a-z0-9_]{2,127}$'
     OR p_resource_id IS NULL OR char_length(p_resource_id) NOT BETWEEN 1 AND 512
     OR p_idempotency_key IS NULL OR char_length(p_idempotency_key) NOT BETWEEN 1 AND 256 THEN
    RAISE EXCEPTION 'invalid monthly allowance claim input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_policy FROM public.monthly_allowance_policies AS policies
  WHERE policies.policy_key = p_policy_key AND policies.is_active;
  IF NOT FOUND OR v_policy.resource_kind <> p_resource_kind THEN
    RAISE EXCEPTION 'unknown or incompatible monthly allowance policy' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text || ':' || p_policy_key || ':' || v_month::text, 0));

  SELECT * INTO v_claim FROM public.monthly_allowance_claims AS claims
  WHERE claims.user_id = p_user_id AND claims.policy_key = p_policy_key
    AND claims.usage_period_start = v_month AND claims.idempotency_key = p_idempotency_key;
  v_existing := FOUND;

  IF NOT v_existing THEN
    SELECT * INTO v_claim FROM public.monthly_allowance_claims AS claims
    WHERE claims.user_id = p_user_id AND claims.policy_key = p_policy_key
      AND claims.usage_period_start = v_month AND claims.resource_kind = p_resource_kind
      AND claims.resource_id = p_resource_id AND claims.consumption_status = 'consumed';
    v_existing := FOUND;
  END IF;

  SELECT count(*)::integer INTO v_used FROM public.monthly_allowance_claims AS claims
  WHERE claims.user_id = p_user_id AND claims.policy_key = p_policy_key
    AND claims.usage_period_start = v_month AND claims.consumption_status = 'consumed';

  IF v_existing THEN
    RETURN QUERY SELECT v_claim.consumption_status = 'consumed', v_claim.id, true,
      v_policy.policy_key, v_policy.allowance_bucket, v_used, v_policy.monthly_limit,
      greatest(v_policy.monthly_limit - v_used, 0), v_next_month;
    RETURN;
  END IF;

  IF v_used >= v_policy.monthly_limit THEN
    RETURN QUERY SELECT false, NULL::uuid, false, v_policy.policy_key,
      v_policy.allowance_bucket, v_used, v_policy.monthly_limit, 0, v_next_month;
    RETURN;
  END IF;

  INSERT INTO public.monthly_allowance_claims (
    user_id, policy_key, usage_period_start, resource_kind, resource_id, idempotency_key
  ) VALUES (
    p_user_id, p_policy_key, v_month, p_resource_kind, p_resource_id, p_idempotency_key
  ) RETURNING * INTO v_claim;

  RETURN QUERY SELECT true, v_claim.id, false, v_policy.policy_key,
    v_policy.allowance_bucket, v_used + 1, v_policy.monthly_limit,
    v_policy.monthly_limit - v_used - 1, v_next_month;
END;
$_$;


ALTER FUNCTION "public"."claim_monthly_allowance"("p_user_id" "uuid", "p_policy_key" "text", "p_resource_kind" "text", "p_resource_id" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_sample_analysis_jobs"("p_worker_id" "text", "p_batch_size" integer DEFAULT 25, "p_lease_seconds" integer DEFAULT 900, "p_stages" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("id" "uuid", "published_asset_id" "uuid", "stage" "text", "analysis_version" "text", "source_signature" "text", "lease_token" "uuid", "s3_bucket" "text", "s3_key" "text", "file_name" "text", "sample_path_construct_id" "uuid", "sample_original_path_id" "uuid", "instrument_v2_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF btrim(coalesce(p_worker_id,'')) = '' THEN RAISE EXCEPTION 'p_worker_id is required'; END IF;
  RETURN QUERY WITH candidates AS (
    SELECT job.id FROM public.sample_analysis_jobs job
    JOIN public.sample_s3_path asset ON asset.id = job.published_asset_id
    JOIN public.instruments_v2 instrument ON instrument.id = asset.instrument_v2_id
    LEFT JOIN public.contributors contributor ON contributor.id = instrument.contributor_id
    WHERE asset.is_current AND asset.excluded_at IS NULL
      AND (job.stage <> 'temporal' OR contributor.slug IS NULL OR contributor.slug NOT IN ('gotchanoddin', 'sound-dust'))
      AND (p_stages IS NULL OR job.stage = ANY(p_stages))
      AND (job.stage <> 'deep_derived' OR EXISTS (
        SELECT 1 FROM public.sample_analysis_librosa librosa
        WHERE librosa.published_asset_id = job.published_asset_id
          AND jsonb_typeof(librosa.analysis_payload->'librosa') = 'object'
          AND librosa.analysis_payload->'librosa' <> '{}'::jsonb
      ))
      AND job.attempts < job.max_attempts AND job.available_at <= now()
      AND (job.status = 'queued' OR (job.status = 'running' AND job.lease_expires_at <= now()))
    ORDER BY job.priority DESC, job.available_at, job.created_at
    FOR UPDATE OF job SKIP LOCKED LIMIT greatest(1, least(p_batch_size, 100))
  ), claimed AS (
    UPDATE public.sample_analysis_jobs job SET status='running', attempts=job.attempts+1,
      lease_owner=p_worker_id, lease_token=gen_random_uuid(),
      lease_expires_at=now()+make_interval(secs => greatest(30,p_lease_seconds)),
      started_at=coalesce(job.started_at,now()), last_error=NULL
    FROM candidates WHERE job.id=candidates.id RETURNING job.*
  ) SELECT claimed.id, asset.id, claimed.stage, claimed.analysis_version,
      claimed.source_signature, claimed.lease_token, asset.s3_bucket, asset.s3_key,
      regexp_replace(asset.s3_key, '^.*/', ''), asset.sample_path_construct_id,
      asset.sample_original_path_id, asset.instrument_v2_id
    FROM claimed JOIN public.sample_s3_path asset ON asset.id=claimed.published_asset_id;
END $$;


ALTER FUNCTION "public"."claim_sample_analysis_jobs"("p_worker_id" "text", "p_batch_size" integer, "p_lease_seconds" integer, "p_stages" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_sample_analysis_jobs"("p_worker_id" "text", "p_batch_size" integer, "p_lease_seconds" integer, "p_stages" "text"[], "p_contributor_slugs" "text"[]) RETURNS TABLE("id" "uuid", "published_asset_id" "uuid", "stage" "text", "analysis_version" "text", "source_signature" "text", "lease_token" "uuid", "s3_bucket" "text", "s3_key" "text", "file_name" "text", "sample_path_construct_id" "uuid", "sample_original_path_id" "uuid", "instrument_v2_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF btrim(coalesce(p_worker_id,'')) = '' THEN RAISE EXCEPTION 'p_worker_id is required'; END IF;
  IF p_contributor_slugs IS NULL OR cardinality(p_contributor_slugs) = 0 THEN
    RAISE EXCEPTION 'p_contributor_slugs is required for the scoped claim';
  END IF;
  RETURN QUERY WITH candidates AS (
    SELECT job.id
    FROM public.sample_analysis_jobs job
    JOIN public.sample_s3_path asset ON asset.id = job.published_asset_id
    JOIN public.instruments_v2 instrument ON instrument.id = asset.instrument_v2_id
    JOIN public.contributors contributor ON contributor.id = instrument.contributor_id
    WHERE asset.is_current AND asset.excluded_at IS NULL
      AND contributor.slug = ANY(p_contributor_slugs)
      AND (job.stage <> 'temporal' OR contributor.slug NOT IN ('gotchanoddin', 'sound-dust'))
      AND (p_stages IS NULL OR job.stage = ANY(p_stages))
      AND (job.stage <> 'deep_derived' OR EXISTS (
        SELECT 1 FROM public.sample_analysis_librosa librosa
        WHERE librosa.published_asset_id = job.published_asset_id
          AND jsonb_typeof(librosa.analysis_payload->'librosa') = 'object'
          AND librosa.analysis_payload->'librosa' <> '{}'::jsonb
      ))
      AND job.attempts < job.max_attempts AND job.available_at <= now()
      AND (job.status = 'queued' OR (job.status = 'running' AND job.lease_expires_at <= now()))
    ORDER BY job.priority DESC, job.available_at, job.created_at
    FOR UPDATE OF job SKIP LOCKED LIMIT greatest(1, least(p_batch_size, 100))
  ), claimed AS (
    UPDATE public.sample_analysis_jobs job SET status='running', attempts=job.attempts+1,
      lease_owner=p_worker_id, lease_token=gen_random_uuid(),
      lease_expires_at=now()+make_interval(secs => greatest(30,p_lease_seconds)),
      started_at=coalesce(job.started_at,now()), last_error=NULL
    FROM candidates WHERE job.id=candidates.id RETURNING job.*
  ) SELECT claimed.id, asset.id, claimed.stage, claimed.analysis_version,
      claimed.source_signature, claimed.lease_token, asset.s3_bucket, asset.s3_key,
      regexp_replace(asset.s3_key, '^.*/', ''), asset.sample_path_construct_id,
      asset.sample_original_path_id, asset.instrument_v2_id
    FROM claimed JOIN public.sample_s3_path asset ON asset.id=claimed.published_asset_id;
END $$;


ALTER FUNCTION "public"."claim_sample_analysis_jobs"("p_worker_id" "text", "p_batch_size" integer, "p_lease_seconds" integer, "p_stages" "text"[], "p_contributor_slugs" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_sample_analysis_jobs"("p_worker_id" "text", "p_batch_size" integer, "p_lease_seconds" integer, "p_stages" "text"[], "p_contributor_slugs" "text"[], "p_instrument_v2_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "published_asset_id" "uuid", "stage" "text", "analysis_version" "text", "source_signature" "text", "lease_token" "uuid", "s3_bucket" "text", "s3_key" "text", "file_name" "text", "sample_path_construct_id" "uuid", "sample_original_path_id" "uuid", "instrument_v2_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF btrim(coalesce(p_worker_id,'')) = '' THEN RAISE EXCEPTION 'p_worker_id is required'; END IF;
  IF p_contributor_slugs IS NULL OR cardinality(p_contributor_slugs) = 0 THEN
    RAISE EXCEPTION 'p_contributor_slugs is required for the scoped claim';
  END IF;
  IF p_instrument_v2_ids IS NULL OR cardinality(p_instrument_v2_ids) = 0 THEN
    RAISE EXCEPTION 'p_instrument_v2_ids is required for the instrument-scoped claim';
  END IF;
  RETURN QUERY WITH candidates AS (
    SELECT job.id
    FROM public.sample_analysis_jobs job
    JOIN public.sample_s3_path asset ON asset.id = job.published_asset_id
    JOIN public.instruments_v2 instrument ON instrument.id = asset.instrument_v2_id
    JOIN public.contributors contributor ON contributor.id = instrument.contributor_id
    WHERE asset.is_current AND asset.excluded_at IS NULL
      AND contributor.slug = ANY(p_contributor_slugs)
      AND asset.instrument_v2_id = ANY(p_instrument_v2_ids)
      AND (job.stage <> 'temporal' OR contributor.slug NOT IN ('gotchanoddin', 'sound-dust'))
      AND (p_stages IS NULL OR job.stage = ANY(p_stages))
      AND (job.stage <> 'deep_derived' OR EXISTS (
        SELECT 1 FROM public.sample_analysis_librosa librosa
        WHERE librosa.published_asset_id = job.published_asset_id
          AND jsonb_typeof(librosa.analysis_payload->'librosa') = 'object'
          AND librosa.analysis_payload->'librosa' <> '{}'::jsonb
      ))
      AND job.attempts < job.max_attempts AND job.available_at <= now()
      AND (job.status = 'queued' OR (job.status = 'running' AND job.lease_expires_at <= now()))
    ORDER BY job.priority DESC, job.available_at, job.created_at
    FOR UPDATE OF job SKIP LOCKED LIMIT greatest(1, least(p_batch_size, 100))
  ), claimed AS (
    UPDATE public.sample_analysis_jobs job SET status='running', attempts=job.attempts+1,
      lease_owner=p_worker_id, lease_token=gen_random_uuid(),
      lease_expires_at=now()+make_interval(secs => greatest(30,p_lease_seconds)),
      started_at=coalesce(job.started_at,now()), last_error=NULL
    FROM candidates WHERE job.id=candidates.id RETURNING job.*
  ) SELECT claimed.id, asset.id, claimed.stage, claimed.analysis_version,
      claimed.source_signature, claimed.lease_token, asset.s3_bucket, asset.s3_key,
      regexp_replace(asset.s3_key, '^.*/', ''), asset.sample_path_construct_id,
      asset.sample_original_path_id, asset.instrument_v2_id
    FROM claimed JOIN public.sample_s3_path asset ON asset.id=claimed.published_asset_id;
END $$;


ALTER FUNCTION "public"."claim_sample_analysis_jobs"("p_worker_id" "text", "p_batch_size" integer, "p_lease_seconds" integer, "p_stages" "text"[], "p_contributor_slugs" "text"[], "p_instrument_v2_ids" "uuid"[]) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sample_audio_profile_jobs_v1" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "sample_original_path_id" "uuid" NOT NULL,
    "profile_version" "text" DEFAULT 'audio-profile-v1'::"text" NOT NULL,
    "source_analysis_signature" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "reason" "text" DEFAULT 'manual'::"text" NOT NULL,
    "priority" integer DEFAULT 0 NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "lease_owner" "text",
    "lease_expires_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "last_error" "text",
    "counts" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "warning_payload" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "result_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sample_audio_profile_jobs_v1_attempts_nonnegative" CHECK ((("attempts" >= 0) AND ("max_attempts" > 0))),
    CONSTRAINT "sample_audio_profile_jobs_v1_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'completed'::"text", 'completed_with_warnings'::"text", 'failed'::"text", 'skipped_fresh'::"text"])))
);


ALTER TABLE "public"."sample_audio_profile_jobs_v1" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_sample_audio_profile_jobs_v1"("p_worker_id" "text", "p_limit" integer DEFAULT 1, "p_lease_seconds" integer DEFAULT 600) RETURNS SETOF "public"."sample_audio_profile_jobs_v1"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH claimable AS (
    SELECT id
    FROM public.sample_audio_profile_jobs_v1
    WHERE
      status = 'queued'
      OR (
        status = 'running'
        AND lease_expires_at IS NOT NULL
        AND lease_expires_at < now()
        AND attempts < max_attempts
      )
    ORDER BY priority DESC, created_at ASC, id ASC
    LIMIT GREATEST(COALESCE(p_limit, 1), 1)
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.sample_audio_profile_jobs_v1 jobs
  SET
    status = 'running',
    lease_owner = COALESCE(NULLIF(p_worker_id, ''), 'anonymous-worker'),
    lease_expires_at = now() + make_interval(secs => GREATEST(COALESCE(p_lease_seconds, 600), 60)),
    started_at = COALESCE(jobs.started_at, now()),
    attempts = jobs.attempts + 1,
    updated_at = now()
  FROM claimable
  WHERE jobs.id = claimable.id
  RETURNING jobs.*;
END;
$$;


ALTER FUNCTION "public"."claim_sample_audio_profile_jobs_v1"("p_worker_id" "text", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


