    "run_id" "uuid" NOT NULL,
    "item_key" "text" NOT NULL,
    "instrument_v2_id" "uuid",
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "priority" integer DEFAULT 0 NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 3 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "executor_id" "text",
    "lease_token" "uuid",
    "lease_expires_at" timestamp with time zone,
    "heartbeat_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "result_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "progress_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "last_progress_at" timestamp with time zone,
    CONSTRAINT "sip_fleet_run_items_attempts_check" CHECK (("attempts" >= 0)),
    CONSTRAINT "sip_fleet_run_items_item_key_check" CHECK (("btrim"("item_key") <> ''::"text")),
    CONSTRAINT "sip_fleet_run_items_max_attempts_check" CHECK (("max_attempts" > 0)),
    CONSTRAINT "sip_fleet_run_items_payload_check" CHECK (("jsonb_typeof"("payload") = 'object'::"text")),
    CONSTRAINT "sip_fleet_run_items_result_payload_check" CHECK (("jsonb_typeof"("result_payload") = 'object'::"text")),
    CONSTRAINT "sip_fleet_run_items_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'waiting_for_audio_profile'::"text", 'completed'::"text", 'failed'::"text", 'canceled'::"text"])))
);


ALTER TABLE "public"."sip_fleet_run_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."sip_fleet_run_items" IS 'Executor-claimable units within a durable fleet run.';



CREATE OR REPLACE FUNCTION "public"."claim_sip_fleet_run_item"("p_run_id" "uuid", "p_instrument_v2_id" "uuid", "p_executor_id" "text", "p_lane_id" "text", "p_lease_seconds" integer DEFAULT 900) RETURNS "public"."sip_fleet_run_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_item public.sip_fleet_run_items%ROWTYPE;
BEGIN
  IF nullif(btrim(p_executor_id),'') IS NULL OR nullif(btrim(p_lane_id),'') IS NULL
    THEN RAISE EXCEPTION 'executor_and_lane_required'; END IF;
  IF p_lease_seconds<30 OR p_lease_seconds>3600 THEN RAISE EXCEPTION 'invalid_lease_seconds'; END IF;
  UPDATE public.sip_fleet_run_items item SET status='canceled',finished_at=now(),
    last_error=coalesce(item.last_error,'coordinator_cancel_lease_expired'),
    executor_id=NULL,lease_token=NULL,lease_expires_at=NULL
  FROM public.sip_fleet_runs run
  WHERE item.run_id=p_run_id AND item.instrument_v2_id=p_instrument_v2_id
    AND run.id=item.run_id AND run.cancel_requested AND item.status='running'
    AND item.lease_expires_at<=now();
  UPDATE public.sip_fleet_runs SET status='canceled',finished_at=now()
  WHERE id=p_run_id AND cancel_requested
    AND NOT EXISTS(SELECT 1 FROM public.sip_fleet_run_items
      WHERE run_id=p_run_id AND status='running');
  UPDATE public.sip_fleet_run_items SET status='failed',finished_at=now(),
    last_error='coordinator_max_attempts_exhausted',executor_id=NULL,lease_token=NULL,lease_expires_at=NULL
  WHERE run_id=p_run_id AND instrument_v2_id=p_instrument_v2_id AND status='running'
    AND lease_expires_at<=now() AND attempts>=max_attempts;
  UPDATE public.sip_fleet_runs SET
    status=CASE WHEN cancel_requested THEN 'canceled' ELSE 'failed' END,
    finished_at=now()
  WHERE id=p_run_id AND NOT EXISTS(
    SELECT 1 FROM public.sip_fleet_run_items WHERE run_id=p_run_id AND status IN ('queued','running'))
    AND EXISTS(SELECT 1 FROM public.sip_fleet_run_items WHERE run_id=p_run_id AND status='failed');
  UPDATE public.sip_fleet_run_items item SET status='running',executor_id=btrim(p_executor_id),
    lease_token=gen_random_uuid(),lease_expires_at=now()+make_interval(secs=>p_lease_seconds),
    heartbeat_at=now(),started_at=coalesce(item.started_at,now()),attempts=item.attempts+1,
    result_payload=coalesce(item.result_payload,'{}'::jsonb)||jsonb_build_object('laneId',btrim(p_lane_id))
  FROM public.sip_fleet_runs run
  WHERE item.run_id=p_run_id AND item.instrument_v2_id=p_instrument_v2_id
    AND run.id=item.run_id AND run.status IN ('queued','running') AND NOT run.cancel_requested
    AND item.attempts<item.max_attempts AND item.available_at<=now()
    AND (item.status='queued' OR (item.status='running' AND item.lease_expires_at<=now()))
  RETURNING item.* INTO v_item;
  IF v_item.id IS NULL THEN RETURN NULL; END IF;
  UPDATE public.sip_fleet_runs SET status='running',started_at=coalesce(started_at,now())
    WHERE id=p_run_id AND status='queued';
  RETURN v_item;
END $$;


ALTER FUNCTION "public"."claim_sip_fleet_run_item"("p_run_id" "uuid", "p_instrument_v2_id" "uuid", "p_executor_id" "text", "p_lane_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_sip_fleet_run_items"("p_executor_id" "text", "p_executor_lease_token" "uuid", "p_limit" integer DEFAULT 1, "p_item_lease_seconds" integer DEFAULT 900) RETURNS SETOF "public"."sip_fleet_run_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_limit<1 OR p_limit>100 THEN RAISE EXCEPTION 'invalid_claim_limit'; END IF;
  IF p_item_lease_seconds<30 OR p_item_lease_seconds>3600 THEN RAISE EXCEPTION 'invalid_lease_seconds'; END IF;
  UPDATE public.sip_fleet_run_items item SET status='canceled',finished_at=now(),
    last_error=coalesce(item.last_error,'coordinator_cancel_lease_expired'),
    executor_id=NULL,lease_token=NULL,lease_expires_at=NULL
  FROM public.sip_fleet_runs run
  WHERE item.run_id=run.id AND run.cancel_requested AND item.status='running'
    AND item.lease_expires_at<=now();
  UPDATE public.sip_fleet_runs run SET status='canceled',finished_at=now()
  WHERE run.status IN ('queued','running') AND run.cancel_requested
    AND NOT EXISTS(SELECT 1 FROM public.sip_fleet_run_items item
      WHERE item.run_id=run.id AND item.status='running');
  UPDATE public.sip_fleet_run_items SET status='failed',finished_at=now(),
    last_error='coordinator_max_attempts_exhausted',executor_id=NULL,lease_token=NULL,lease_expires_at=NULL
  WHERE status='running' AND lease_expires_at<=now() AND attempts>=max_attempts;
  UPDATE public.sip_fleet_runs run SET
    status=CASE WHEN run.cancel_requested THEN 'canceled' ELSE 'failed' END,
    finished_at=now()
  WHERE run.status IN ('queued','running')
    AND NOT EXISTS(SELECT 1 FROM public.sip_fleet_run_items item
      WHERE item.run_id=run.id AND item.status IN ('queued','running'))
    AND EXISTS(SELECT 1 FROM public.sip_fleet_run_items item
      WHERE item.run_id=run.id AND item.status='failed');
  IF NOT EXISTS (SELECT 1 FROM public.sip_fleet_executor_leases WHERE executor_id=p_executor_id
    AND lease_token=p_executor_lease_token AND lease_expires_at>now())
    THEN RAISE EXCEPTION 'invalid_executor_lease'; END IF;
  RETURN QUERY WITH candidates AS (
    SELECT item.id FROM public.sip_fleet_run_items item JOIN public.sip_fleet_runs run ON run.id=item.run_id
    WHERE run.status IN ('queued','running') AND NOT run.cancel_requested
      AND item.attempts<item.max_attempts AND item.available_at<=now()
      AND (item.status='queued' OR (item.status='running' AND item.lease_expires_at<=now()))
    ORDER BY item.priority DESC,item.available_at,item.created_at FOR UPDATE OF item SKIP LOCKED LIMIT p_limit
  ), claimed AS (
    UPDATE public.sip_fleet_run_items item SET status='running',executor_id=p_executor_id,
      lease_token=gen_random_uuid(),lease_expires_at=now()+make_interval(secs=>p_item_lease_seconds),
      heartbeat_at=now(),started_at=coalesce(item.started_at,now()),attempts=item.attempts+1
    FROM candidates WHERE item.id=candidates.id RETURNING item.*
  ), started AS (
    UPDATE public.sip_fleet_runs run SET status='running',started_at=coalesce(started_at,now())
    WHERE id IN (SELECT run_id FROM claimed) AND status='queued' RETURNING id
  ) SELECT claimed.* FROM claimed;
END $$;


ALTER FUNCTION "public"."claim_sip_fleet_run_items"("p_executor_id" "text", "p_executor_lease_token" "uuid", "p_limit" integer, "p_item_lease_seconds" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_pipeline_run_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "run_id" "uuid" NOT NULL,
    "staging_instrument_id" "uuid" NOT NULL,
    "source_sip_instrument_id" "uuid",
    "instrument_v2_id" "uuid",
    "contributor_slug" "text" NOT NULL,
    "instrument_name" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "current_stage" "text" DEFAULT 'publish-actions'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 3 NOT NULL,
    "lease_owner" "text",
    "lease_expires_at" timestamp with time zone,
    "last_error" "text",
    "blocker_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "result_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_token" "uuid",
    CONSTRAINT "sip_pipeline_run_items_attempts_check" CHECK ((("attempt_count" >= 0) AND ("max_attempts" > 0))),
    CONSTRAINT "sip_pipeline_run_items_blocker_object" CHECK (("jsonb_typeof"("blocker_payload") = 'object'::"text")),
    CONSTRAINT "sip_pipeline_run_items_result_object" CHECK (("jsonb_typeof"("result_payload") = 'object'::"text")),
    CONSTRAINT "sip_pipeline_run_items_stage_check" CHECK (("current_stage" = ANY (ARRAY['publish-actions'::"text", 'normalize'::"text", 'compress'::"text", 'upload-s3'::"text", 'publish'::"text"]))),
    CONSTRAINT "sip_pipeline_run_items_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'published'::"text", 'blocked'::"text", 'stalled'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."sip_pipeline_run_items" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_sip_pipeline_run_items"("p_worker_id" "text", "p_limit" integer DEFAULT 1, "p_lease_seconds" integer DEFAULT 900) RETURNS SETOF "public"."sip_pipeline_run_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_expired record;
  v_item record;
BEGIN
  IF NULLIF(btrim(p_worker_id), '') IS NULL THEN
    RAISE EXCEPTION 'worker_id_required';
  END IF;

  FOR v_expired IN
    UPDATE public.sip_pipeline_run_items item
    SET
      status = 'stalled',
      lease_owner = NULL,
      lease_expires_at = NULL,
      last_error = COALESCE(
        item.last_error,
        'Worker lease expired after max attempts'
      ),
      blocker_payload = COALESCE(item.blocker_payload, '{}'::jsonb)
        || jsonb_build_object(
          'failureKind', 'lease_expired',
          'retryable', true
        ),
      finished_at = COALESCE(item.finished_at, now()),
      updated_at = now()
    FROM public.sip_pipeline_runs run
    WHERE run.id = item.run_id
      AND run.status IN ('queued', 'running')
      AND run.cancel_requested = false
      AND item.status = 'running'
      AND item.lease_expires_at IS NOT NULL
      AND item.lease_expires_at < now()
      AND item.attempt_count >= item.max_attempts
    RETURNING
      item.run_id,
      item.id,
      item.staging_instrument_id,
      item.current_stage,
      item.attempt_count,
      item.max_attempts
  LOOP
    PERFORM public.record_sip_pipeline_run_event(
      v_expired.run_id,
      v_expired.id,
      v_expired.staging_instrument_id,
      v_expired.current_stage,
      'item_lease_expired_stalled',
      'Worker lease expired after max attempts',
      jsonb_build_object(
        'attemptCount', v_expired.attempt_count,
        'maxAttempts', v_expired.max_attempts
      )
    );
    PERFORM public.sip_pipeline_refresh_run_counts(v_expired.run_id);
  END LOOP;

  FOR v_item IN
    WITH candidates AS (
      SELECT
        item.id,
        item.status AS item_status,
        item.lease_expires_at
      FROM public.sip_pipeline_run_items item
      JOIN public.sip_pipeline_runs run
        ON run.id = item.run_id
      WHERE run.status IN ('queued', 'running')
        AND run.cancel_requested = false
        AND (
          (
            item.status = 'running'
            AND item.lease_expires_at IS NOT NULL
            AND item.lease_expires_at < now()
            AND item.attempt_count < item.max_attempts
          )
          OR (
            item.status = 'queued'
            AND item.attempt_count < item.max_attempts
          )
        )
      ORDER BY
        run.created_at,
        CASE
          WHEN item.status = 'running'
            AND item.lease_expires_at IS NOT NULL
            AND item.lease_expires_at < now()
          THEN 0
          ELSE 1
        END,
        item.lease_expires_at NULLS LAST,
        item.created_at,
        item.id
      LIMIT GREATEST(COALESCE(p_limit, 1), 1)
      FOR UPDATE OF item SKIP LOCKED
    )
    UPDATE public.sip_pipeline_run_items item
    SET
      status = 'running',
      lease_owner = p_worker_id,
      lease_token = gen_random_uuid(),
      lease_expires_at = now() + make_interval(secs => GREATEST(COALESCE(p_lease_seconds, 900), 60)),
      attempt_count = item.attempt_count + 1,
      started_at = COALESCE(item.started_at, now()),
      finished_at = NULL,
      updated_at = now()
    FROM candidates
    WHERE item.id = candidates.id
    RETURNING item.*
  LOOP
    UPDATE public.sip_pipeline_runs
    SET
      status = 'running',
      worker_id = p_worker_id,
      heartbeat_at = now(),
      started_at = COALESCE(started_at, now()),
      current_stage = v_item.current_stage,
      updated_at = now()
    WHERE id = v_item.run_id
      AND status IN ('queued', 'running');

    INSERT INTO public.sip_pipeline_run_events (
      run_id,
      run_item_id,
      staging_instrument_id,
      stage,
      event_type,
      message,
      payload
    )
    VALUES (
      v_item.run_id,
      v_item.id,
      v_item.staging_instrument_id,
      v_item.current_stage,
      'item_claimed',
      'Worker claimed pipeline item',
      jsonb_build_object(
        'workerId', p_worker_id,
        'attemptCount', v_item.attempt_count,
        'leaseToken', v_item.lease_token
      )
    );

    PERFORM public.sip_pipeline_refresh_run_counts(v_item.run_id);
    RETURN NEXT v_item;
  END LOOP;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."claim_sip_pipeline_run_items"("p_worker_id" "text", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_sip_review_warning_refresh_batch"("p_contributor" "text", "p_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_limit" integer DEFAULT 25, "p_lease_ttl" interval DEFAULT '00:05:00'::interval, "p_force" boolean DEFAULT false) RETURNS TABLE("claimed_ids" "uuid"[], "lease_token" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_token uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(lower(btrim(p_contributor)),0));
  v_token:=gen_random_uuid();
  WITH candidates AS (
    SELECT i.id,i.source_contributor_slug
    FROM public.sip_review_instrument i
    LEFT JOIN public.sip_review_warning_index_state s ON s.sip_review_instrument_id=i.id
    LEFT JOIN public.sip_review_promotion_map pm ON pm.sip_review_instrument_id=i.id
    WHERE i.source_contributor_slug=p_contributor AND NOT i.is_retired AND pm.id IS NULL
      AND (p_ids IS NULL OR i.id=ANY(p_ids))
      AND (s.sip_review_instrument_id IS NULL OR ((s.is_stale OR p_force)
        AND (s.refresh_lease_token IS NULL OR s.last_attempted_at<now()-p_lease_ttl)
        AND (p_force OR s.failure_count=0 OR s.last_attempted_at<now()-(p_lease_ttl*power(2,least(s.failure_count,5))))))
    ORDER BY coalesce(s.stale_at,i.created_at),i.id
    FOR UPDATE OF i SKIP LOCKED LIMIT p_limit
  ), claimed AS (
    INSERT INTO public.sip_review_warning_index_state(sip_review_instrument_id,contributor_slug,last_attempted_at,refresh_lease_token,updated_at)
    SELECT id,source_contributor_slug,now(),v_token,now() FROM candidates
    ON CONFLICT(sip_review_instrument_id) DO UPDATE SET last_attempted_at=EXCLUDED.last_attempted_at,
      refresh_lease_token=EXCLUDED.refresh_lease_token,contributor_slug=EXCLUDED.contributor_slug,updated_at=EXCLUDED.updated_at
    RETURNING sip_review_instrument_id
  ) SELECT array_agg(sip_review_instrument_id),v_token INTO claimed_ids,lease_token FROM claimed;
  claimed_ids:=coalesce(claimed_ids,ARRAY[]::uuid[]);
  RETURN NEXT;
END $$;


ALTER FUNCTION "public"."claim_sip_review_warning_refresh_batch"("p_contributor" "text", "p_ids" "uuid"[], "p_limit" integer, "p_lease_ttl" interval, "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_instrument_audio_profile_job_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_status" "text", "p_counts" "jsonb" DEFAULT '{}'::"jsonb", "p_warning_payload" "jsonb" DEFAULT '[]'::"jsonb", "p_result_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS "public"."instrument_audio_profile_jobs_v1"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  updated_row public.instrument_audio_profile_jobs_v1;
BEGIN
  IF p_status NOT IN ('completed', 'completed_with_warnings', 'failed', 'skipped_fresh') THEN
    RAISE EXCEPTION 'Invalid instrument audio-profile job completion status: %', p_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.instrument_audio_profile_jobs_v1 jobs
  SET
    status = p_status,
    lease_owner = NULL,
    lease_expires_at = NULL,
    completed_at = now(),
    sample_count = COALESCE((p_counts->>'sampleCount')::integer, jobs.sample_count),
    analyzed_sample_count = COALESCE((p_counts->>'analyzedSampleCount')::integer, jobs.analyzed_sample_count),
    flagged_sample_count = COALESCE((p_counts->>'flaggedSampleCount')::integer, jobs.flagged_sample_count),
    counts = COALESCE(p_counts, '{}'::jsonb),
    warning_payload = COALESCE(p_warning_payload, '[]'::jsonb),
    result_payload = COALESCE(p_result_payload, '{}'::jsonb),
    last_error = CASE WHEN p_status = 'failed' THEN p_error ELSE NULL END,
    updated_at = now()
  WHERE jobs.id = p_job_id
    AND (
      jobs.lease_owner IS NULL
      OR p_worker_id IS NULL
      OR jobs.lease_owner = p_worker_id
    )
  RETURNING jobs.* INTO updated_row;

  IF updated_row.id IS NULL THEN
    RAISE EXCEPTION 'Instrument audio-profile job % is not claimed by worker %', p_job_id, p_worker_id
      USING ERRCODE = '55000';
  END IF;

  RETURN updated_row;
END;
$$;


ALTER FUNCTION "public"."complete_instrument_audio_profile_job_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_status" "text", "p_counts" "jsonb", "p_warning_payload" "jsonb", "p_result_payload" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_market_pattern_embedding_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_source_hash" "text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  job public.market_pattern_embedding_jobs%ROWTYPE;
BEGIN
  SELECT * INTO job
  FROM public.market_pattern_embedding_jobs
  WHERE id = p_job_id
  FOR UPDATE;
  IF job.id IS NULL
    OR job.status <> 'running'
    OR job.lease_token IS DISTINCT FROM p_lease_token
    OR job.lease_expires_at <= now()
  THEN
    RAISE EXCEPTION 'Stale or expired lease token for job %', p_job_id
      USING ERRCODE = '55000';
  END IF;

  IF job.requested_source_hash IS NOT NULL
    AND job.requested_source_hash <> p_source_hash
  THEN
    UPDATE public.market_pattern_embedding_jobs
    SET
      status = 'superseded',
      lease_token = NULL,
      leased_by = NULL,
      lease_expires_at = NULL,
      last_heartbeat_at = NULL,
      last_error = 'Pattern source changed before completion'
    WHERE id = p_job_id;
    RETURN false;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.market_pattern_embeddings
    WHERE market_pattern_id = job.market_pattern_id
      AND embedding_space = job.embedding_space
      AND source_hash = p_source_hash
  ) THEN
    RAISE EXCEPTION 'Embedding upsert must precede completion for job %', p_job_id
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.market_pattern_embedding_jobs
  SET
    status = 'completed',
    requested_source_hash = p_source_hash,
    lease_token = NULL,
    leased_by = NULL,
    lease_expires_at = NULL,
    last_heartbeat_at = NULL,
    last_error = NULL,
    completed_at = now()
  WHERE id = p_job_id;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."complete_market_pattern_embedding_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_source_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_published_sample_analysis_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_result_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_job public.sample_analysis_jobs%ROWTYPE;
BEGIN
  IF p_result_payload IS NULL OR jsonb_typeof(p_result_payload) <> 'object' OR p_result_payload = '{}'::jsonb THEN
    RAISE EXCEPTION 'Analysis job % requires a non-empty JSON object payload', p_job_id;
  END IF;
  UPDATE public.sample_analysis_jobs SET status='completed', completed_at=now(),
    result_payload=coalesce(p_result_payload,'{}'::jsonb), lease_owner=NULL, lease_token=NULL, lease_expires_at=NULL
    WHERE id=p_job_id AND status='running' AND lease_token=p_lease_token AND lease_expires_at>now()
    RETURNING * INTO v_job;
  IF NOT FOUND THEN RETURN false; END IF;
  PERFORM 1 FROM public.sample_s3_path WHERE id=v_job.published_asset_id FOR UPDATE;
  IF v_job.stage = ANY(ARRAY['derived','deep_derived']) THEN
    PERFORM 1 FROM public.instruments_v2 WHERE id=(SELECT instrument_v2_id FROM public.sample_s3_path WHERE id=v_job.published_asset_id) FOR UPDATE;
  END IF;
  IF v_job.stage='analysis' THEN
    IF jsonb_typeof(p_result_payload #> '{meyda,512}') <> 'object' OR p_result_payload #> '{meyda,512}' = '{}'::jsonb
       OR jsonb_typeof(p_result_payload #> '{meyda,1024}') <> 'object' OR p_result_payload #> '{meyda,1024}' = '{}'::jsonb
       OR jsonb_typeof(p_result_payload #> '{meyda,4096}') <> 'object' OR p_result_payload #> '{meyda,4096}' = '{}'::jsonb
       OR jsonb_typeof(p_result_payload->'aubio') <> 'object' OR p_result_payload->'aubio' = '{}'::jsonb THEN
      RAISE EXCEPTION 'Raw analysis payload is missing Meyda or Aubio output';
    END IF;
    INSERT INTO public.sample_analysis_aubio(published_asset_id,analysis_payload,raw_result) VALUES(v_job.published_asset_id,jsonb_build_object('meta',p_result_payload->'meta','aubio',p_result_payload->'aubio'),p_result_payload->'aubio') ON CONFLICT(published_asset_id) DO UPDATE SET analysis_payload=excluded.analysis_payload,raw_result=excluded.raw_result,analyzed_at=now();
    INSERT INTO public.sample_analysis_meyda_512(published_asset_id,frame_index,hop_size,analysis_payload) VALUES(v_job.published_asset_id,0,256,jsonb_build_object('meta',p_result_payload->'meta','meyda',p_result_payload #> '{meyda,512}')) ON CONFLICT(published_asset_id,frame_index) DO UPDATE SET analysis_payload=excluded.analysis_payload,analyzed_at=now();
    INSERT INTO public.sample_analysis_meyda_1024(published_asset_id,frame_index,hop_size,analysis_payload) VALUES(v_job.published_asset_id,0,512,jsonb_build_object('meta',p_result_payload->'meta','meyda',p_result_payload #> '{meyda,1024}')) ON CONFLICT(published_asset_id,frame_index) DO UPDATE SET analysis_payload=excluded.analysis_payload,analyzed_at=now();
    INSERT INTO public.sample_analysis_meyda_4096(published_asset_id,frame_index,hop_size,analysis_payload) VALUES(v_job.published_asset_id,0,2048,jsonb_build_object('meta',p_result_payload->'meta','meyda',p_result_payload #> '{meyda,4096}')) ON CONFLICT(published_asset_id) DO UPDATE SET analysis_payload=excluded.analysis_payload,analyzed_at=now();
  ELSIF v_job.stage='librosa' THEN
    IF jsonb_typeof(p_result_payload->'librosa') <> 'object' OR p_result_payload->'librosa' = '{}'::jsonb THEN RAISE EXCEPTION 'Librosa analysis payload is missing analyzer output'; END IF;
    INSERT INTO public.sample_analysis_librosa(published_asset_id,sample_rate,analysis_payload,raw_result) VALUES(v_job.published_asset_id,coalesce((p_result_payload #>> '{meta,sampleRate}')::integer,0),p_result_payload,p_result_payload) ON CONFLICT(published_asset_id) DO UPDATE SET sample_rate=excluded.sample_rate,analysis_payload=excluded.analysis_payload,raw_result=excluded.raw_result,updated_at=now();
  ELSIF v_job.stage='derived' THEN
    IF NOT EXISTS (SELECT 1 FROM jsonb_each(p_result_payload) field WHERE field.value <> 'null'::jsonb) THEN RAISE EXCEPTION 'Derived analysis payload contains no material values'; END IF;
    INSERT INTO public.sample_derived_sample_analysis(published_asset_id,analysis_payload) VALUES(v_job.published_asset_id,p_result_payload) ON CONFLICT(published_asset_id) DO UPDATE SET analysis_payload=excluded.analysis_payload,derived_at=now();
  ELSIF v_job.stage='deep_derived' THEN
    IF NOT EXISTS (SELECT 1 FROM jsonb_each(p_result_payload) field WHERE field.value <> 'null'::jsonb) THEN RAISE EXCEPTION 'Deep-derived analysis payload contains no material values'; END IF;
    INSERT INTO public.sample_deep_derived_sample_analysis(published_asset_id,analysis_payload) VALUES(v_job.published_asset_id,p_result_payload) ON CONFLICT(published_asset_id) DO UPDATE SET analysis_payload=excluded.analysis_payload,derived_at=now();
  END IF;
  IF v_job.stage = 'analysis' THEN
    PERFORM public.enqueue_published_sample_analysis(v_job.published_asset_id, ARRAY['derived']);
  ELSIF v_job.stage='librosa' THEN
    PERFORM public.enqueue_published_sample_analysis(v_job.published_asset_id, ARRAY['deep_derived'], 0, true);
  ELSIF v_job.stage = ANY(ARRAY['derived','deep_derived']) THEN
    IF (SELECT ready FROM public.published_sample_analysis_ready_for_profile_v1((SELECT instrument_v2_id FROM public.sample_s3_path WHERE id=v_job.published_asset_id))) THEN
      PERFORM public.enqueue_instrument_audio_profile_jobs_v1(ARRAY[(SELECT instrument_v2_id FROM public.sample_s3_path WHERE id=v_job.published_asset_id)], 'post_publish_mp3_analysis', 'audio-profile-v1', true, 1000);
    END IF;
  END IF;
  RETURN true;
END $$;


ALTER FUNCTION "public"."complete_published_sample_analysis_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_result_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_published_sample_temporal_analysis_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_result_payload" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_job public.sample_analysis_jobs%ROWTYPE; v_sample_rate integer;
  v_duration_ms integer; v_features jsonb; v_metadata jsonb; v_instrument_id uuid;
BEGIN
  IF p_result_payload IS NULL OR jsonb_typeof(p_result_payload) <> 'object'
     OR jsonb_typeof(p_result_payload->'temporal') <> 'object'
     OR p_result_payload->'temporal' = '{}'::jsonb THEN
    RAISE EXCEPTION 'Temporal analysis job % requires a non-empty temporal payload', p_job_id;
  END IF;
  v_sample_rate := NULLIF(p_result_payload #>> '{meta,sampleRate}', '')::integer;
  v_duration_ms := round(coalesce(NULLIF(p_result_payload #>> '{meta,duration}', '')::numeric, -1) * 1000)::integer;
  IF v_sample_rate IS NULL OR v_sample_rate <= 0 OR v_duration_ms < 0 THEN
    RAISE EXCEPTION 'Temporal analysis job % returned invalid audio metadata', p_job_id;
  END IF;
  SELECT job.* INTO v_job
  FROM public.sample_analysis_jobs job
  JOIN public.sample_s3_path asset ON asset.id = job.published_asset_id
  WHERE job.id=p_job_id AND job.stage='temporal' AND job.status='running'
    AND job.lease_token=p_lease_token AND job.lease_expires_at>now()
    AND asset.is_current AND asset.source_signature=job.source_signature
  FOR UPDATE OF job, asset;
  IF NOT FOUND THEN RETURN false; END IF;
  v_features := p_result_payload->'temporal'; v_metadata := p_result_payload->'meta';
  INSERT INTO public.sample_analysis_temporal(
    published_asset_id, analysis_version, algorithm_version, source_signature,
    sample_rate_hz, duration_ms, feature_payload, analyzer_metadata
  ) VALUES (
    v_job.published_asset_id, v_job.analysis_version, v_job.algorithm_version,
    v_job.source_signature, v_sample_rate, v_duration_ms, v_features,
    coalesce(v_metadata, '{}'::jsonb)
  ) ON CONFLICT (published_asset_id, analysis_version, algorithm_version, source_signature) DO NOTHING;
  UPDATE public.sample_analysis_jobs SET status='completed', completed_at=now(),
    result_payload=p_result_payload, lease_owner=NULL, lease_token=NULL, lease_expires_at=NULL
  WHERE id=v_job.id;
  SELECT instrument_v2_id INTO v_instrument_id FROM public.sample_s3_path WHERE id=v_job.published_asset_id;
  IF v_instrument_id IS NOT NULL
     AND public.published_sample_temporal_ready_for_profile_v1(v_instrument_id) THEN
    PERFORM public.enqueue_instrument_audio_profile_jobs_v1(
      ARRAY[v_instrument_id], 'post_publish_temporal_analysis', 'audio-profile-v1', true, 1000
    );
  END IF;
  RETURN true;
END $$;


ALTER FUNCTION "public"."complete_published_sample_temporal_analysis_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_result_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_sample_audio_profile_job_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_status" "text", "p_counts" "jsonb" DEFAULT '{}'::"jsonb", "p_warning_payload" "jsonb" DEFAULT '[]'::"jsonb", "p_result_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS "public"."sample_audio_profile_jobs_v1"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  updated_row public.sample_audio_profile_jobs_v1;
BEGIN
  IF p_status NOT IN ('completed', 'completed_with_warnings', 'failed', 'skipped_fresh') THEN
    RAISE EXCEPTION 'Invalid sample audio-profile job completion status: %', p_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.sample_audio_profile_jobs_v1 jobs
  SET
    status = p_status,
    lease_owner = NULL,
    lease_expires_at = NULL,
    completed_at = now(),
    counts = COALESCE(p_counts, '{}'::jsonb),
    warning_payload = COALESCE(p_warning_payload, '[]'::jsonb),
    result_payload = COALESCE(p_result_payload, '{}'::jsonb),
    last_error = CASE WHEN p_status = 'failed' THEN p_error ELSE NULL END,
    updated_at = now()
  WHERE jobs.id = p_job_id
    AND (
      jobs.lease_owner IS NULL
      OR p_worker_id IS NULL
      OR jobs.lease_owner = p_worker_id
    )
  RETURNING jobs.* INTO updated_row;

  IF updated_row.id IS NULL THEN
    RAISE EXCEPTION 'Sample audio-profile job % is not claimed by worker %', p_job_id, p_worker_id
      USING ERRCODE = '55000';
  END IF;

  RETURN updated_row;
END;
$$;


ALTER FUNCTION "public"."complete_sample_audio_profile_job_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_status" "text", "p_counts" "jsonb", "p_warning_payload" "jsonb", "p_result_payload" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_sip_fleet_run_item"("p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_succeeded" boolean, "p_result_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_run_id uuid;
BEGIN
  UPDATE public.sip_fleet_run_items SET status=CASE WHEN p_succeeded THEN 'completed' ELSE 'failed' END,
    result_payload=coalesce(p_result_payload,'{}'::jsonb),last_error=CASE WHEN p_succeeded THEN NULL ELSE p_error END,
    finished_at=now(),executor_id=NULL,lease_token=NULL,lease_expires_at=NULL
  WHERE id=p_item_id AND status='running' AND executor_id=p_executor_id AND lease_token=p_lease_token
    AND lease_expires_at>now()
  RETURNING run_id INTO v_run_id;
  IF NOT FOUND THEN RETURN false; END IF;
  UPDATE public.sip_fleet_runs run SET
    status=CASE
      WHEN run.cancel_requested
        AND NOT EXISTS(SELECT 1 FROM public.sip_fleet_run_items i WHERE i.run_id=run.id AND i.status IN ('queued','running')) THEN 'canceled'
      WHEN NOT EXISTS(SELECT 1 FROM public.sip_fleet_run_items i WHERE i.run_id=run.id AND i.status IN ('queued','running'))
        AND EXISTS(SELECT 1 FROM public.sip_fleet_run_items i WHERE i.run_id=run.id AND i.status='failed') THEN 'failed'
      WHEN NOT EXISTS(SELECT 1 FROM public.sip_fleet_run_items i WHERE i.run_id=run.id AND i.status IN ('queued','running')) THEN 'completed'
      ELSE run.status END,
    finished_at=CASE WHEN NOT EXISTS(SELECT 1 FROM public.sip_fleet_run_items i WHERE i.run_id=run.id AND i.status IN ('queued','running')) THEN now() ELSE NULL END
  WHERE run.id=v_run_id;
  RETURN true;
END $$;


ALTER FUNCTION "public"."complete_sip_fleet_run_item"("p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_succeeded" boolean, "p_result_payload" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_sip_pipeline_run_item"("p_item_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_status" "text", "p_next_stage" "text" DEFAULT NULL::"text", "p_blocker_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_result_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS "public"."sip_pipeline_run_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item public.sip_pipeline_run_items%ROWTYPE;
  v_run public.sip_pipeline_runs%ROWTYPE;
  v_next_status text;
  v_next_stage text;
  v_event_type text;
  v_error text;
  v_blocker_payload jsonb := COALESCE(p_blocker_payload, '{}'::jsonb);
  v_result_payload jsonb := COALESCE(p_result_payload, '{}'::jsonb);
  v_floor_stage text;
  v_target_started boolean := false;
  v_backward boolean := false;
  v_expected_previous text;
BEGIN
  SELECT * INTO v_item
  FROM public.sip_pipeline_run_items
  WHERE id = p_item_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sip_pipeline_run_item_not_found: %', p_item_id;
  END IF;

  SELECT * INTO v_run
  FROM public.sip_pipeline_runs
  WHERE id = v_item.run_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sip_pipeline_run_not_found: %', v_item.run_id;
  END IF;

  IF v_item.status <> 'running' THEN
    IF p_lease_token IS NOT NULL
      AND v_item.lease_token IS NOT DISTINCT FROM p_lease_token
    THEN
      RETURN v_item;
    END IF;
    RAISE EXCEPTION 'sip_pipeline_run_item_not_running: %', p_item_id;
  END IF;

  IF p_lease_token IS NULL
    OR v_item.lease_token IS DISTINCT FROM p_lease_token
    OR v_item.lease_owner IS DISTINCT FROM p_worker_id
  THEN
    RAISE EXCEPTION 'sip_pipeline_run_item_lease_mismatch: %', p_item_id;
  END IF;

  IF (v_run.cancel_requested OR v_run.status = 'cancelled')
    AND p_status <> 'published'
  THEN
    v_next_status := 'cancelled';
    v_next_stage := v_item.current_stage;
    v_event_type := 'item_cancelled';
    v_error := COALESCE(p_error, v_run.cancel_reason, 'Run cancelled');
  ELSIF p_status = 'stage_complete' THEN
    IF p_next_stage IS NULL THEN
      RAISE EXCEPTION 'next_stage_required';
    END IF;
    IF p_next_stage NOT IN ('publish-actions', 'normalize', 'compress', 'upload-s3', 'publish') THEN
      RAISE EXCEPTION 'invalid_sip_pipeline_next_stage: %', p_next_stage;
    END IF;

    v_floor_stage := public.sip_pipeline_upload_status_floor(
      v_item.source_sip_instrument_id,
      'publish-actions'
    );
    v_backward :=
      public.sip_pipeline_stage_rank(p_next_stage)
      < public.sip_pipeline_stage_rank(v_item.current_stage);
    v_expected_previous := public.sip_pipeline_previous_stage(v_item.current_stage);

    IF v_backward THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.sip_pipeline_run_events event
        WHERE event.run_id = v_item.run_id
          AND event.run_item_id = v_item.id
          AND event.stage = p_next_stage
          AND event.event_type = 'stage_started'
      ) INTO v_target_started;
    END IF;

    IF v_backward AND (
      p_next_stage IS DISTINCT FROM v_expected_previous
      OR v_target_started
      OR public.sip_pipeline_stage_rank(p_next_stage) < public.sip_pipeline_stage_rank(v_floor_stage)
    ) THEN
      v_next_status := 'blocked';
      v_next_stage := v_item.current_stage;
      v_event_type := 'item_blocked';
      v_error := COALESCE(
        p_error,
        format(
          'Stage regression guard blocked %s -> %s; upload-status floor is %s',
          v_item.current_stage,
          p_next_stage,
          v_floor_stage
        )
      );
      v_blocker_payload := v_blocker_payload || jsonb_build_object(
        'failureKind', 'stage_regression_guard',
        'requestedStage', p_next_stage,
        'uploadStatusFloor', v_floor_stage,
        'targetAlreadyStarted', v_target_started,
        'retryable', false
      );
    ELSE
      v_next_status := 'queued';
      v_next_stage := CASE
        WHEN public.sip_pipeline_stage_rank(p_next_stage) < public.sip_pipeline_stage_rank(v_floor_stage)
          THEN v_floor_stage
        ELSE p_next_stage
      END;
      v_event_type := 'stage_complete';
      v_error := p_error;
    END IF;
  ELSIF p_status = 'retry' THEN
    IF v_item.attempt_count >= v_item.max_attempts THEN
      v_next_status := 'stalled';
      v_next_stage := v_item.current_stage;
      v_event_type := 'item_stalled';
    ELSE
      v_next_status := 'queued';
      v_next_stage := v_item.current_stage;
      v_event_type := 'item_retry_queued';
    END IF;
    v_error := p_error;
  ELSIF p_status IN ('published', 'blocked', 'stalled', 'failed', 'cancelled') THEN
    v_next_status := p_status;
    v_next_stage := v_item.current_stage;
    v_event_type := 'item_' || p_status;
    v_error := p_error;
  ELSE
    RAISE EXCEPTION 'invalid_sip_pipeline_item_status: %', p_status;
  END IF;

  UPDATE public.sip_pipeline_run_items
  SET
    status = v_next_status,
    current_stage = v_next_stage,
    attempt_count = CASE
      WHEN p_status = 'stage_complete' AND v_next_status = 'queued' THEN 0
      ELSE attempt_count
    END,
    lease_owner = NULL,
    lease_expires_at = NULL,
    blocker_payload = v_blocker_payload,
    result_payload = v_result_payload,
    last_error = v_error,
    finished_at = CASE WHEN v_next_status IN ('published', 'blocked', 'stalled', 'failed', 'cancelled') THEN now() ELSE NULL END,
    updated_at = now()
  WHERE id = p_item_id
  RETURNING * INTO v_item;

  PERFORM public.record_sip_pipeline_run_event(
    v_item.run_id,
    v_item.id,
    v_item.staging_instrument_id,
    v_item.current_stage,
    v_event_type,
    v_error,
    jsonb_build_object(
      'status', v_next_status,
      'nextStage', v_next_stage,
      'blocker', v_blocker_payload,
      'result', v_result_payload,
      'cancelRequested', v_run.cancel_requested,
      'leaseToken', p_lease_token
    )
  );

  PERFORM public.sip_pipeline_refresh_run_counts(v_item.run_id);

  RETURN v_item;
END;
$$;


ALTER FUNCTION "public"."complete_sip_pipeline_run_item"("p_item_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_status" "text", "p_next_stage" "text", "p_blocker_payload" "jsonb", "p_result_payload" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_sip_review_warning_refresh"("p_lease_token" "uuid", "p_payload" "jsonb") RETURNS TABLE("completed_ids" "uuid"[], "skipped_ids" "uuid"[], "failures" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_item jsonb; v_staging_id uuid; v_status text; v_warnings jsonb; v_diagnostics jsonb;
  v_error text; v_state_token uuid; v_provider text; v_completed uuid[]:=ARRAY[]::uuid[];
  v_skipped uuid[]:=ARRAY[]::uuid[]; v_failures jsonb:='{}'::jsonb;
BEGIN
  FOR v_provider IN
    SELECT DISTINCT lower(btrim(s.contributor_slug))
    FROM public.sip_review_warning_index_state s
    JOIN jsonb_array_elements(p_payload) e ON s.sip_review_instrument_id=(e->>'staging_id')::uuid
    WHERE s.refresh_lease_token=p_lease_token AND btrim(coalesce(s.contributor_slug,''))<>''
    ORDER BY lower(btrim(s.contributor_slug))
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(v_provider,0));
  END LOOP;
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_payload)
  LOOP
    v_staging_id:=(v_item->>'staging_id')::uuid; v_status:=v_item->>'status';
    v_warnings:=v_item->'warnings'; v_diagnostics:=v_item->'diagnostics'; v_error:=v_item->>'error';
    SELECT refresh_lease_token INTO v_state_token FROM public.sip_review_warning_index_state
      WHERE sip_review_instrument_id=v_staging_id;
    IF NOT FOUND THEN v_failures:=v_failures||jsonb_build_object(v_staging_id::text,'instrument_deleted'); CONTINUE; END IF;
    IF v_state_token IS DISTINCT FROM p_lease_token THEN v_skipped:=array_append(v_skipped,v_staging_id); CONTINUE; END IF;
    IF v_status='ok' THEN
      BEGIN
        PERFORM pg_advisory_xact_lock(hashtext(v_staging_id::text));
        DELETE FROM public.sip_review_warning_index WHERE sip_review_instrument_id=v_staging_id;
        IF v_warnings IS NOT NULL AND jsonb_array_length(v_warnings)>0 THEN
          INSERT INTO public.sip_review_warning_index(sip_review_instrument_id,contributor_slug,category,warning_key,type,severity,field,file_path,original_sample_id,message)
          SELECT v_staging_id,w->>'contributor_slug',w->>'category',w->>'warning_key',w->>'type',w->>'severity',w->>'field',w->>'file_path',(w->>'original_sample_id')::uuid,w->>'message'
          FROM jsonb_array_elements(v_warnings) w
          ON CONFLICT(sip_review_instrument_id,category,warning_key) DO UPDATE SET type=EXCLUDED.type,severity=EXCLUDED.severity,
            field=EXCLUDED.field,file_path=EXCLUDED.file_path,original_sample_id=EXCLUDED.original_sample_id,message=EXCLUDED.message,
            contributor_slug=EXCLUDED.contributor_slug,updated_at=now();
        END IF;
        UPDATE public.sip_review_warning_index_state SET is_stale=false,refreshed_at=now(),refresh_error=NULL,
          refresh_lease_token=NULL,failure_count=0,diagnostics_json=v_diagnostics,updated_at=now()
        WHERE sip_review_instrument_id=v_staging_id AND refresh_lease_token=p_lease_token;
        v_completed:=array_append(v_completed,v_staging_id);
      EXCEPTION WHEN OTHERS THEN
        UPDATE public.sip_review_warning_index_state SET refresh_error=SQLERRM,refresh_lease_token=NULL,
          failure_count=least(failure_count+1,10),updated_at=now()
        WHERE sip_review_instrument_id=v_staging_id AND refresh_lease_token=p_lease_token;
        v_failures:=v_failures||jsonb_build_object(v_staging_id::text,SQLERRM);
      END;
    ELSIF v_status='failed' THEN
      UPDATE public.sip_review_warning_index_state SET refresh_error=v_error,refresh_lease_token=NULL,
        failure_count=least(failure_count+1,10),updated_at=now()
      WHERE sip_review_instrument_id=v_staging_id AND refresh_lease_token=p_lease_token;
      v_completed:=array_append(v_completed,v_staging_id);
    END IF;
  END LOOP;
  completed_ids:=v_completed; skipped_ids:=v_skipped; failures:=v_failures; RETURN NEXT;
END $$;


ALTER FUNCTION "public"."complete_sip_review_warning_refresh"("p_lease_token" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_instrument_audio_profile_signature_v1"("p_instrument_v2_id" "uuid", "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_ready boolean;
  v_temporal_ready boolean;
  v_published_signature text;
BEGIN
  SELECT ready, source_signature INTO v_ready, v_published_signature
  FROM public.published_sample_analysis_ready_for_profile_v1(
    p_instrument_v2_id
  );
  v_temporal_ready :=
    public.published_sample_temporal_ready_for_profile_v1(
      p_instrument_v2_id
    );
  IF coalesce(v_ready, false)
     AND v_temporal_ready
     AND nullif(v_published_signature, '') IS NOT NULL THEN
    RETURN public.audio_profile_v1_hash(jsonb_build_object(
      'profileVersion', p_profile_version,
      'instrumentV2Id', p_instrument_v2_id,
      'postPublishMp3Signature', v_published_signature,
      'temporalEvidence', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'assetId', asset.id,
          'sourceSignature', temporal.source_signature,
          'analysisVersion', temporal.analysis_version,
          'algorithmVersion', temporal.algorithm_version
        ) ORDER BY asset.id)
        FROM public.sample_s3_path asset
        JOIN public.sample_path_constructs construct
          ON construct.id = asset.sample_path_construct_id
         AND construct.instrument_v2_id = p_instrument_v2_id
        LEFT JOIN public.sample_analysis_temporal temporal
          ON temporal.published_asset_id = asset.id
         AND temporal.source_signature = asset.source_signature
         AND temporal.analysis_version = 'temporal-v1'
         AND temporal.algorithm_version = 'global-temporal-pcm-v1'
        WHERE asset.instrument_v2_id = p_instrument_v2_id
          AND asset.is_current
          AND asset.excluded_at IS NULL
      ), '[]'::jsonb)
    ));
  END IF;
  IF coalesce(v_ready, false)
     AND nullif(v_published_signature, '') IS NOT NULL THEN
    RETURN public.audio_profile_v1_hash(jsonb_build_object(
      'profileVersion', p_profile_version,
      'instrumentV2Id', p_instrument_v2_id,
      'postPublishMp3Signature', v_published_signature
    ));
  END IF;
  RETURN public.audio_profile_v1_hash(jsonb_build_object(
    'profileVersion', p_profile_version,
    'instrumentV2Id', p_instrument_v2_id,
    'samples', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'sampleOriginalPathId', construct.sample_original_path_id,
        'pitchContent', construct.pitch_content,
        'velocity', construct.velocity,
        'roundRobin', construct.round_robin,
        'micPosition', coalesce(
          nullif(btrim(construct.mic_position), ''),
          'main'
        ),
        'midiNote', construct.midi_note,
        'filename', construct.filename,
        'sampleAnalysisSignature',
          public.compute_sample_audio_profile_signature_v1(
            construct.sample_original_path_id,
            p_profile_version
          )
      ) ORDER BY
        construct.sample_original_path_id,
        construct.pitch_content,
        construct.velocity,
        construct.round_robin,
        coalesce(nullif(btrim(construct.mic_position), ''), 'main'),
        construct.filename)
      FROM public.sample_path_constructs construct
      WHERE construct.instrument_v2_id = p_instrument_v2_id
    ), '[]'::jsonb)
  ));
END $$;


ALTER FUNCTION "public"."compute_instrument_audio_profile_signature_v1"("p_instrument_v2_id" "uuid", "p_profile_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_sample_audio_profile_signature_v1"("p_sample_original_path_id" "uuid", "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT public.audio_profile_v1_hash(
    jsonb_build_object(
      'profileVersion', p_profile_version,
      'sampleOriginalPathId', osp.id,
      'sampleUpdatedAt', osp.updated_at,
      'meyda4096AnalyzedAt', m4.analyzed_at,
      'meyda4096Id', m4.id,
      'derivedAt', der.derived_at,
      'derivedId', der.id,
      'librosaUpdatedAt', lib.updated_at,
      'librosaId', lib.id
    )
  )
  FROM public.samples_original_paths osp
  LEFT JOIN public.analysis_meyda_4096 m4
    ON m4.sample_id = osp.id
  LEFT JOIN public.derived_sample_analysis der
    ON der.sample_id = osp.id
  LEFT JOIN public.analysis_librosa lib
    ON lib.sample_id = osp.id
  WHERE osp.id = p_sample_original_path_id;
$$;


ALTER FUNCTION "public"."compute_sample_audio_profile_signature_v1"("p_sample_original_path_id" "uuid", "p_profile_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_catalog_cache_rate_limit"("p_quota_key" "text", "p_limit" integer, "p_window_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_request_count integer;
BEGIN
  IF p_quota_key IS NULL
     OR pg_catalog.length(p_quota_key) < 1
     OR pg_catalog.length(p_quota_key) > 512
     OR p_limit < 1
     OR p_limit > 10000
     OR p_window_seconds < 1
     OR p_window_seconds > 3600 THEN
    RETURN false;
  END IF;

  DELETE FROM public.catalog_cache_rate_limits
  WHERE quota_key IN (
    SELECT quota_key
    FROM public.catalog_cache_rate_limits
    WHERE expires_at <= v_now
    ORDER BY expires_at
    LIMIT 100
  );

  INSERT INTO public.catalog_cache_rate_limits (
    quota_key,
    request_count,
    expires_at,
    updated_at
  )
  VALUES (
    p_quota_key,
    1,
    v_now + pg_catalog.make_interval(secs => p_window_seconds),
    v_now
  )
  ON CONFLICT (quota_key) DO UPDATE
  SET request_count = CASE
        WHEN public.catalog_cache_rate_limits.expires_at <= v_now THEN 1
        ELSE public.catalog_cache_rate_limits.request_count + 1
      END,
      expires_at = CASE
        WHEN public.catalog_cache_rate_limits.expires_at <= v_now
          THEN EXCLUDED.expires_at
        ELSE public.catalog_cache_rate_limits.expires_at
      END,
      updated_at = v_now
  RETURNING request_count INTO v_request_count;

  RETURN v_request_count <= p_limit;
END;
$$;


ALTER FUNCTION "public"."consume_catalog_cache_rate_limit"("p_quota_key" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."consume_catalog_cache_rate_limit"("p_quota_key" "text", "p_limit" integer, "p_window_seconds" integer) IS 'Atomically consumes one service-role-only catalog-cache quota unit in a shared TTL window.';



CREATE TABLE IF NOT EXISTS "public"."creator_profiles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "platform" "public"."creator_platform" NOT NULL,
    "handle" "text" NOT NULL,
    "display_name" "text",
    "bio" "text",
    "follower_count" integer,
    "avg_views" integer,
    "engagement_rate" numeric(8,3),
    "external_links" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "recent_content" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "status" "public"."creator_status" DEFAULT 'discovered'::"public"."creator_status" NOT NULL,
    "discovery_source" "text",
    "discovered_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "creator_profiles_avg_views_non_negative" CHECK ((("avg_views" IS NULL) OR ("avg_views" >= 0))),
    CONSTRAINT "creator_profiles_engagement_rate_non_negative" CHECK ((("engagement_rate" IS NULL) OR ("engagement_rate" >= (0)::numeric))),
    CONSTRAINT "creator_profiles_follower_count_non_negative" CHECK ((("follower_count" IS NULL) OR ("follower_count" >= 0))),
    CONSTRAINT "creator_profiles_handle_not_empty" CHECK (("length"(TRIM(BOTH FROM "handle")) > 0))
);


ALTER TABLE "public"."creator_profiles" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."creator_update_status_with_event"("p_creator_id" "uuid", "p_next_status" "public"."creator_status", "p_actor" "text", "p_notes" "text") RETURNS "public"."creator_profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  current_profile creator_profiles%rowtype;
  updated_profile creator_profiles%rowtype;
BEGIN
  IF coalesce(auth.role(), '') NOT IN ('', 'service_role')
    AND NOT public.is_soundsculpt_staff()
  THEN
    RAISE EXCEPTION 'insufficient_privilege' USING errcode = '42501';
  END IF;

  SELECT *
  INTO current_profile
  FROM creator_profiles
  WHERE id = p_creator_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'creator_not_found' USING errcode = 'P0002';
  END IF;

  IF current_profile.status = p_next_status THEN
    RAISE EXCEPTION 'status_unchanged' USING errcode = '22023';
  END IF;

  UPDATE creator_profiles
  SET
    status = p_next_status,
    updated_at = now()
  WHERE id = p_creator_id
  RETURNING * INTO updated_profile;

  INSERT INTO creator_review_events (
    creator_id,
    actor,
    previous_status,
    next_status,
    notes
  ) VALUES (
    p_creator_id,
    coalesce(nullif(trim(p_actor), ''), 'internal'),
    current_profile.status,
    p_next_status,
    trim(coalesce(p_notes, ''))
  );

  RETURN updated_profile;
END;
$$;


ALTER FUNCTION "public"."creator_update_status_with_event"("p_creator_id" "uuid", "p_next_status" "public"."creator_status", "p_actor" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_acquire_mutation_lease"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_lease_owner" "text", "p_lease_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  actor_is_active boolean;
  api_key_is_active boolean;
  lease_row public.crm_mutation_leases%ROWTYPE;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'crm_api_service_role_required' USING errcode = '42501';
  END IF;
  IF p_actor_user_id IS NULL OR nullif(btrim(p_lease_owner), '') IS NULL THEN
    RAISE EXCEPTION 'crm_mutation_lease_actor_and_owner_required' USING errcode = '22023';
  END IF;
  IF p_lease_seconds NOT BETWEEN 30 AND 900 THEN
    RAISE EXCEPTION 'crm_mutation_lease_seconds_invalid' USING errcode = '22023';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.crm_team_members
    WHERE user_id = p_actor_user_id AND active
  ) INTO actor_is_active;
  IF NOT actor_is_active THEN
    RAISE EXCEPTION 'crm_actor_not_active' USING errcode = '42501';
  END IF;

  IF p_api_key_id IS NULL THEN
    IF p_actor_scope IS DISTINCT FROM 'user:' || p_actor_user_id::text THEN
      RAISE EXCEPTION 'crm_actor_scope_invalid' USING errcode = '22023';
    END IF;
  ELSE
    IF p_actor_scope IS DISTINCT FROM 'api-key:' || p_api_key_id::text THEN
      RAISE EXCEPTION 'crm_actor_scope_invalid' USING errcode = '22023';
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM public.crm_api_keys
      WHERE id = p_api_key_id
        AND team_member_user_id = p_actor_user_id
        AND revoked_at IS NULL
        AND (expires_at IS NULL OR expires_at > now())
    ) INTO api_key_is_active;
    IF NOT api_key_is_active THEN
      RAISE EXCEPTION 'crm_api_key_not_active' USING errcode = '42501';
    END IF;
  END IF;

  INSERT INTO public.crm_mutation_leases AS target (
    lease_key, lease_token, lease_owner, actor_user_id, actor_scope,
    lease_expires_at
  ) VALUES (
    'global', gen_random_uuid(), btrim(p_lease_owner), p_actor_user_id,
    p_actor_scope, now() + make_interval(secs => p_lease_seconds)
  )
  ON CONFLICT (lease_key) DO UPDATE SET
    lease_token = EXCLUDED.lease_token,
    lease_owner = EXCLUDED.lease_owner,
    actor_user_id = EXCLUDED.actor_user_id,
    actor_scope = EXCLUDED.actor_scope,
    lease_expires_at = EXCLUDED.lease_expires_at,
    updated_at = now()
  WHERE target.lease_expires_at <= now()
  RETURNING * INTO lease_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'crm_mutation_lease_held' USING errcode = '55P03';
  END IF;
  RETURN jsonb_build_object(
    'lease_token', lease_row.lease_token,
    'lease_expires_at', lease_row.lease_expires_at
  );
END;
$$;


ALTER FUNCTION "public"."crm_acquire_mutation_lease"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_lease_owner" "text", "p_lease_seconds" integer) OWNER TO "postgres";


