    RETURN private.crm_record_import_authority_preservation(
      p_actor_user_id, p_actor_scope, p_api_key_id, p_operation,
      p_idempotency_key, p_request_fingerprint, p_payload
    );
  END IF;
  RETURN private.crm_apply_evidence_mutation(
    p_actor_user_id, p_actor_scope, p_api_key_id, p_operation,
    p_idempotency_key, p_request_fingerprint, p_payload
  );
END;
