ALTER FUNCTION "public"."crm_apply_mutation"("p_actor_user_id" "uuid", "p_actor_scope" "text", "p_api_key_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_request_fingerprint" "text", "p_payload" "jsonb", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_heartbeat_mutation_lease"("p_lease_token" "uuid", "p_lease_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  lease_row public.crm_mutation_leases%ROWTYPE;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'crm_api_service_role_required' USING errcode = '42501';
  END IF;
  IF p_lease_token IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 900 THEN
    RAISE EXCEPTION 'crm_mutation_lease_heartbeat_invalid' USING errcode = '22023';
  END IF;
  UPDATE public.crm_mutation_leases SET
    lease_expires_at = now() + make_interval(secs => p_lease_seconds),
    updated_at = now()
  WHERE lease_key = 'global'
    AND lease_token = p_lease_token
    AND lease_expires_at > now()
  RETURNING * INTO lease_row;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'crm_mutation_lease_stale' USING errcode = '55P03';
  END IF;
  RETURN jsonb_build_object('lease_expires_at', lease_row.lease_expires_at);
END;
$$;


