    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "auth_user_id" "uuid",
    "display_name" "text",
    "given_name" "text",
    "family_name" "text",
    "private_notes" "text",
    "owner_user_id" "uuid",
    "archived_at" timestamp with time zone,
    "merged_into_contact_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "crm_contacts_not_merged_into_self" CHECK ((("merged_into_contact_id" IS NULL) OR ("merged_into_contact_id" <> "id")))
);


ALTER TABLE "public"."crm_contacts" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_merge_contacts"("p_source_contact_id" "uuid", "p_target_contact_id" "uuid", "p_summary" "text" DEFAULT NULL::"text") RETURNS "public"."crm_contacts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE target_contact public.crm_contacts%ROWTYPE;
BEGIN
  SELECT * INTO target_contact
  FROM public.crm_merge_contacts_legacy_evidence_v1(p_source_contact_id, p_target_contact_id, p_summary);

  DELETE FROM public.crm_contact_attributions source_row
  USING public.crm_contact_attributions target_row
  WHERE source_row.contact_id = p_source_contact_id
    AND target_row.contact_id = p_target_contact_id
    AND source_row.product IS NOT DISTINCT FROM target_row.product
    AND source_row.touch_kind = target_row.touch_kind
    AND source_row.source_id IS NOT DISTINCT FROM target_row.source_id
    AND source_row.observed_at = target_row.observed_at;
  UPDATE public.crm_contact_attributions SET contact_id = p_target_contact_id WHERE contact_id = p_source_contact_id;

  DELETE FROM public.crm_update_recipients source_row
  USING public.crm_update_recipients target_row
  WHERE source_row.contact_id = p_source_contact_id
    AND target_row.contact_id = p_target_contact_id
    AND source_row.update_id = target_row.update_id;
  UPDATE public.crm_update_recipients SET contact_id = p_target_contact_id WHERE contact_id = p_source_contact_id;

  UPDATE public.crm_import_conflicts
  SET candidate_contact_ids = array_replace(candidate_contact_ids, p_source_contact_id, p_target_contact_id)
  WHERE p_source_contact_id = ANY(candidate_contact_ids);

  RETURN target_contact;
END;
$$;


ALTER FUNCTION "public"."crm_merge_contacts"("p_source_contact_id" "uuid", "p_target_contact_id" "uuid", "p_summary" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_merge_contacts_legacy_evidence_v1"("p_source_contact_id" "uuid", "p_target_contact_id" "uuid", "p_summary" "text" DEFAULT NULL::"text") RETURNS "public"."crm_contacts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  source_contact public.crm_contacts%ROWTYPE;
  target_contact public.crm_contacts%ROWTYPE;
BEGIN
  IF NOT public.crm_is_admin() THEN
    RAISE EXCEPTION 'insufficient_privilege' USING errcode = '42501';
  END IF;

  IF p_source_contact_id = p_target_contact_id THEN
    RAISE EXCEPTION 'crm_contacts_must_be_distinct' USING errcode = '22023';
  END IF;

  SELECT * INTO source_contact FROM public.crm_contacts WHERE id = p_source_contact_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'crm_source_contact_not_found' USING errcode = 'P0002';
  END IF;

  SELECT * INTO target_contact FROM public.crm_contacts WHERE id = p_target_contact_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'crm_target_contact_not_found' USING errcode = 'P0002';
  END IF;

  IF source_contact.archived_at IS NOT NULL OR target_contact.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'crm_cannot_merge_archived_contact' USING errcode = '22023';
  END IF;

  IF source_contact.auth_user_id IS NOT NULL
    AND target_contact.auth_user_id IS NOT NULL
    AND source_contact.auth_user_id <> target_contact.auth_user_id
  THEN
    RAISE EXCEPTION 'crm_conflicting_auth_users' USING errcode = '22023';
  END IF;

  DELETE FROM public.crm_contact_methods source_method
  USING public.crm_contact_methods target_method
  WHERE source_method.contact_id = p_source_contact_id
    AND target_method.contact_id = p_target_contact_id
    AND source_method.kind = target_method.kind
    AND source_method.normalized_value IS NOT NULL
    AND source_method.normalized_value = target_method.normalized_value;
  UPDATE public.crm_contact_methods source_method
  SET is_primary = false
  WHERE source_method.contact_id = p_source_contact_id
    AND source_method.is_primary
    AND EXISTS (
      SELECT 1
      FROM public.crm_contact_methods target_method
      WHERE target_method.contact_id = p_target_contact_id
        AND target_method.kind = source_method.kind
        AND target_method.is_primary
    );
  UPDATE public.crm_contact_methods SET contact_id = p_target_contact_id WHERE contact_id = p_source_contact_id;

  DELETE FROM public.crm_organization_contacts source_link
  USING public.crm_organization_contacts target_link
  WHERE source_link.contact_id = p_source_contact_id
    AND target_link.contact_id = p_target_contact_id
    AND source_link.organization_id = target_link.organization_id;
  UPDATE public.crm_organization_contacts source_link
  SET is_primary_contact = false
  WHERE source_link.contact_id = p_source_contact_id
    AND source_link.is_primary_contact
    AND EXISTS (
      SELECT 1
      FROM public.crm_organization_contacts target_link
      WHERE target_link.contact_id = p_target_contact_id
        AND target_link.organization_id = source_link.organization_id
        AND target_link.is_primary_contact
    );
  UPDATE public.crm_organization_contacts SET contact_id = p_target_contact_id WHERE contact_id = p_source_contact_id;

  DELETE FROM public.crm_contact_sources source_link
  USING public.crm_contact_sources target_link
  WHERE source_link.contact_id = p_source_contact_id
    AND target_link.contact_id = p_target_contact_id
    AND source_link.source_id = target_link.source_id;
  UPDATE public.crm_contact_sources SET contact_id = p_target_contact_id WHERE contact_id = p_source_contact_id;

  DELETE FROM public.crm_communication_permissions source_permission
  USING public.crm_communication_permissions target_permission
  WHERE source_permission.contact_id = p_source_contact_id
    AND target_permission.contact_id = p_target_contact_id
    AND source_permission.topic = target_permission.topic;
  UPDATE public.crm_communication_permissions SET contact_id = p_target_contact_id WHERE contact_id = p_source_contact_id;

  DELETE FROM public.crm_product_memberships source_membership
  USING public.crm_product_memberships target_membership
  WHERE source_membership.contact_id = p_source_contact_id
    AND target_membership.contact_id = p_target_contact_id
    AND source_membership.product = target_membership.product;
  UPDATE public.crm_product_memberships SET contact_id = p_target_contact_id WHERE contact_id = p_source_contact_id;

  UPDATE public.crm_relationships SET contact_id = p_target_contact_id WHERE contact_id = p_source_contact_id;
  UPDATE public.crm_activities SET contact_id = p_target_contact_id WHERE contact_id = p_source_contact_id;

  -- Clear the source binding before copying it so the unique auth-user index
  -- remains valid throughout this transaction.
  UPDATE public.crm_contacts
  SET auth_user_id = NULL,
      updated_at = now()
  WHERE id = p_source_contact_id;
  UPDATE public.crm_contacts
  SET auth_user_id = coalesce(auth_user_id, source_contact.auth_user_id),
      updated_at = now()
  WHERE id = p_target_contact_id;
  UPDATE public.crm_contacts
  SET archived_at = now(),
      merged_into_contact_id = p_target_contact_id,
      updated_at = now()
  WHERE id = p_source_contact_id;

  INSERT INTO public.crm_change_events (
    actor_user_id, entity_type, entity_id, action, before_summary, after_summary
  ) VALUES (
    auth.uid(),
    'contact',
    p_target_contact_id,
    'merged',
    jsonb_build_object('source_contact_id', p_source_contact_id),
    jsonb_build_object('source_contact_id', p_source_contact_id, 'summary', nullif(btrim(p_summary), ''))
  );

  SELECT * INTO target_contact
  FROM public.crm_contacts
  WHERE id = p_target_contact_id;

  RETURN target_contact;
END;
$$;


ALTER FUNCTION "public"."crm_merge_contacts_legacy_evidence_v1"("p_source_contact_id" "uuid", "p_target_contact_id" "uuid", "p_summary" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_preserve_restrictive_permission"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.state IN ('denied', 'unsubscribed')
    AND NEW.state NOT IN ('denied', 'unsubscribed')
    AND NEW.actor_user_id IS NULL
  THEN
    RAISE EXCEPTION 'crm_permission_requires_human_override' USING errcode = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."crm_preserve_restrictive_permission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_release_mutation_lease"("p_lease_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  released_count bigint;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'crm_api_service_role_required' USING errcode = '42501';
  END IF;
  DELETE FROM public.crm_mutation_leases
  WHERE lease_key = 'global' AND lease_token = p_lease_token;
  GET DIAGNOSTICS released_count = ROW_COUNT;
  RETURN jsonb_build_object('released', released_count = 1);
END;
$$;


ALTER FUNCTION "public"."crm_release_mutation_lease"("p_lease_token" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."crm_relationships" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "contact_id" "uuid",
    "organization_id" "uuid",
    "partner_type_key" "text" NOT NULL,
    "status" "text" DEFAULT 'new'::"text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "owner_user_id" "uuid",
    "next_action" "text",
    "follow_up_at" timestamp with time zone,
    "milestone_key" "text",
    "last_contacted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "origin_mode" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "origin_detail" "text",
    "derived_engagement" "text" DEFAULT 'prospect'::"text" NOT NULL,
    "derived_engagement_at" timestamp with time zone,
    "derived_engagement_source_id" "uuid",
    "engagement_override" "text",
    "engagement_override_reason" "text",
    "engagement_override_actor_user_id" "uuid",
    "engagement_override_at" timestamp with time zone,
    "interest_score" smallint,
    "relationship_quality_score" smallint,
    CONSTRAINT "crm_relationships_derived_engagement_check" CHECK (("derived_engagement" = ANY (ARRAY['prospect'::"text", 'outreach-attempted'::"text", 'connected'::"text", 'responded'::"text", 'conversation'::"text", 'interested'::"text", 'active'::"text", 'dormant'::"text", 'declined'::"text", 'closed'::"text"]))),
    CONSTRAINT "crm_relationships_engagement_override_check" CHECK ((("engagement_override" IS NULL) OR ("engagement_override" = ANY (ARRAY['prospect'::"text", 'outreach-attempted'::"text", 'connected'::"text", 'responded'::"text", 'conversation'::"text", 'interested'::"text", 'active'::"text", 'dormant'::"text", 'declined'::"text", 'closed'::"text"])))),
    CONSTRAINT "crm_relationships_engagement_override_complete_check" CHECK (((("engagement_override" IS NULL) AND ("engagement_override_reason" IS NULL) AND ("engagement_override_actor_user_id" IS NULL) AND ("engagement_override_at" IS NULL)) OR (("engagement_override" IS NOT NULL) AND (NULLIF("btrim"("engagement_override_reason"), ''::"text") IS NOT NULL) AND ("engagement_override_actor_user_id" IS NOT NULL) AND ("engagement_override_at" IS NOT NULL)))),
    CONSTRAINT "crm_relationships_interest_score_check" CHECK ((("interest_score" IS NULL) OR (("interest_score" >= 1) AND ("interest_score" <= 3)))),
    CONSTRAINT "crm_relationships_origin_mode_check" CHECK (("origin_mode" = ANY (ARRAY['unknown'::"text", 'inbound'::"text", 'outbound-cold'::"text", 'outbound-warm'::"text", 'referral'::"text", 'organic'::"text", 'paid'::"text", 'event'::"text", 'community'::"text", 'existing-network'::"text"]))),
    CONSTRAINT "crm_relationships_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "crm_relationships_quality_score_check" CHECK ((("relationship_quality_score" IS NULL) OR (("relationship_quality_score" >= 1) AND ("relationship_quality_score" <= 3)))),
    CONSTRAINT "crm_relationships_require_subject" CHECK ((("contact_id" IS NOT NULL) OR ("organization_id" IS NOT NULL))),
    CONSTRAINT "crm_relationships_status_check" CHECK (("status" = ANY (ARRAY['new'::"text", 'contacted'::"text", 'awaiting-reply'::"text", 'interested'::"text", 'active'::"text", 'nurture'::"text", 'paused'::"text", 'closed'::"text", 'declined'::"text"])))
);


ALTER TABLE "public"."crm_relationships" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_set_relationship_status"("p_relationship_id" "uuid", "p_status" "text", "p_next_action" "text" DEFAULT NULL::"text", "p_follow_up_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_clear_next_action" boolean DEFAULT false, "p_clear_follow_up_at" boolean DEFAULT false) RETURNS "public"."crm_relationships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  previous_relationship public.crm_relationships%ROWTYPE;
  updated_relationship public.crm_relationships%ROWTYPE;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role'
    AND NOT public.is_soundsculpt_staff()
  THEN
    RAISE EXCEPTION 'insufficient_privilege' USING errcode = '42501';
  END IF;

  SELECT * INTO previous_relationship
  FROM public.crm_relationships
  WHERE id = p_relationship_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'crm_relationship_not_found' USING errcode = 'P0002';
  END IF;

  UPDATE public.crm_relationships
  SET status = p_status,
      next_action = CASE WHEN p_clear_next_action THEN NULL ELSE coalesce(p_next_action, next_action) END,
      follow_up_at = CASE WHEN p_clear_follow_up_at THEN NULL ELSE coalesce(p_follow_up_at, follow_up_at) END,
      updated_at = now()
  WHERE id = p_relationship_id
  RETURNING * INTO updated_relationship;

  INSERT INTO public.crm_change_events (
    actor_user_id, entity_type, entity_id, action, before_summary, after_summary
  ) VALUES (
    auth.uid(),
    'relationship',
    p_relationship_id,
    'status-updated',
    jsonb_build_object('status', previous_relationship.status, 'next_action', previous_relationship.next_action, 'follow_up_at', previous_relationship.follow_up_at),
    jsonb_build_object('status', updated_relationship.status, 'next_action', updated_relationship.next_action, 'follow_up_at', updated_relationship.follow_up_at)
  );

  RETURN updated_relationship;
END;
$$;


ALTER FUNCTION "public"."crm_set_relationship_status"("p_relationship_id" "uuid", "p_status" "text", "p_next_action" "text", "p_follow_up_at" timestamp with time zone, "p_clear_next_action" boolean, "p_clear_follow_up_at" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_round_robin_cue_construct_slot_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    PERFORM public.assert_round_robin_cue_eligibility_slot_identity_v1(
      OLD.instrument_v2_id,
      OLD.pitch_content,
      OLD.velocity,
      OLD.mic_position,
      OLD.filename
    );
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    PERFORM public.assert_round_robin_cue_eligibility_slot_identity_v1(
      NEW.instrument_v2_id,
      NEW.pitch_content,
      NEW.velocity,
      NEW.mic_position,
      NEW.filename
    );
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."enforce_round_robin_cue_construct_slot_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_round_robin_cue_eligibility_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.assert_round_robin_cue_eligibility_slot_v1(
      NEW.sample_path_construct_id
    );
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM public.assert_round_robin_cue_eligibility_slot_v1(
      OLD.sample_path_construct_id
    );
  ELSE
    PERFORM public.assert_round_robin_cue_eligibility_slot_v1(
      OLD.sample_path_construct_id
    );
    IF NEW.sample_path_construct_id IS DISTINCT FROM
       OLD.sample_path_construct_id THEN
      PERFORM public.assert_round_robin_cue_eligibility_slot_v1(
        NEW.sample_path_construct_id
      );
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."enforce_round_robin_cue_eligibility_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_sample_path_constructs_playback_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  parent_playback_type public.instrument_playback_type;
BEGIN
  IF NEW.playback_type IS NULL THEN
    NEW.playback_type := 'oneShot'::public.instrument_playback_type;
  END IF;

  IF NEW.instrument_v2_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT parent.playback_type
  INTO parent_playback_type
  FROM public.instruments_v2 parent
  WHERE parent.id = NEW.instrument_v2_id;

  IF parent_playback_type IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.playback_type IS DISTINCT FROM parent_playback_type THEN
    RAISE EXCEPTION 'sample_path_constructs.playback_type must match parent instruments_v2.playback_type'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_sample_path_constructs_playback_type"() OWNER TO "postgres";


