CREATE OR REPLACE FUNCTION "public"."enqueue_instrument_audio_profile_backfill_v1"("p_contributor_slug" "text" DEFAULT NULL::"text", "p_instrument_v2_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_only_missing" boolean DEFAULT false, "p_limit" integer DEFAULT 100, "p_reason" "text" DEFAULT 'backfill'::"text", "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text", "p_force" boolean DEFAULT false, "p_priority" integer DEFAULT 0, "p_published_only" boolean DEFAULT true) RETURNS TABLE("instrument_v2_id" "uuid", "job_id" "uuid", "status" "text", "source_signature" "text", "enqueued" boolean, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  candidate_ids uuid[];
BEGIN
  SELECT COALESCE(array_agg(candidate.id), ARRAY[]::uuid[])
  INTO candidate_ids
  FROM (
    SELECT i.id
    FROM public.instruments_v2 i
    LEFT JOIN public.contributors c
      ON c.id = i.contributor_id
    LEFT JOIN public.instrument_audio_profile_v1 p
      ON p.instrument_v2_id = i.id
     AND p.profile_version = p_profile_version
    CROSS JOIN LATERAL (
      SELECT public.compute_instrument_audio_profile_signature_v1(i.id, p_profile_version) AS current_signature
    ) sig
    WHERE
      (p_instrument_v2_ids IS NULL OR i.id = ANY(p_instrument_v2_ids))
      AND (p_contributor_slug IS NULL OR c.slug = p_contributor_slug)
      AND (NOT p_published_only OR i.published = true)
      AND (
        p_force
        OR p.instrument_v2_id IS NULL
        OR (NOT p_only_missing AND p.source_signature IS DISTINCT FROM sig.current_signature)
      )
    ORDER BY i.updated_at DESC, i.id ASC
    LIMIT GREATEST(COALESCE(p_limit, 100), 1)
  ) candidate;

  RETURN QUERY
  SELECT *
  FROM public.enqueue_instrument_audio_profile_jobs_v1(
    candidate_ids,
    COALESCE(NULLIF(p_reason, ''), 'backfill'),
    p_profile_version,
    p_force,
    p_priority
  );
END;
$$;


ALTER FUNCTION "public"."enqueue_instrument_audio_profile_backfill_v1"("p_contributor_slug" "text", "p_instrument_v2_ids" "uuid"[], "p_only_missing" boolean, "p_limit" integer, "p_reason" "text", "p_profile_version" "text", "p_force" boolean, "p_priority" integer, "p_published_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_instrument_audio_profile_backfill_v2"("p_contributor_slug" "text" DEFAULT NULL::"text", "p_instrument_v2_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_only_missing" boolean DEFAULT false, "p_candidate_limit" integer DEFAULT 25, "p_repair_limit" integer DEFAULT 25, "p_reason" "text" DEFAULT 'backfill'::"text", "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text", "p_force" boolean DEFAULT false, "p_priority" integer DEFAULT 0, "p_published_only" boolean DEFAULT true, "p_cursor_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("instrument_v2_id" "uuid", "job_id" "uuid", "status" "text", "source_signature" "text", "enqueued" boolean, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_candidate_ids uuid[];
  v_repair_ids uuid[];
BEGIN
  IF p_candidate_limit IS NULL OR p_candidate_limit < 1 OR p_candidate_limit > 100 THEN
    RAISE EXCEPTION 'candidate limit must be between 1 and 100' USING ERRCODE = '22023';
  END IF;
  IF p_repair_limit IS NULL OR p_repair_limit < 1 OR p_repair_limit > 100 THEN
    RAISE EXCEPTION 'repair limit must be between 1 and 100' USING ERRCODE = '22023';
  END IF;
  IF p_repair_limit < p_candidate_limit THEN
    RAISE EXCEPTION 'repair limit must be at least the candidate limit' USING ERRCODE = '22023';
  END IF;
  IF (p_cursor_updated_at IS NULL) <> (p_cursor_id IS NULL) THEN
    RAISE EXCEPTION 'cursor updated_at and id must be provided together' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(array_agg(page.id ORDER BY page.updated_at DESC, page.id ASC), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT i.id, i.updated_at FROM public.instruments_v2 i
    LEFT JOIN public.contributors c ON c.id = i.contributor_id
    WHERE (p_instrument_v2_ids IS NULL OR i.id = ANY(p_instrument_v2_ids))
      AND (p_contributor_slug IS NULL OR c.slug = p_contributor_slug)
      AND (NOT p_published_only OR i.published)
      AND (p_cursor_updated_at IS NULL OR i.updated_at < p_cursor_updated_at
        OR (i.updated_at = p_cursor_updated_at AND i.id > p_cursor_id))
    ORDER BY i.updated_at DESC, i.id ASC LIMIT p_candidate_limit
  ) page;

  WITH candidates AS MATERIALIZED (
    SELECT i.*, selected.ordinality FROM unnest(v_candidate_ids) WITH ORDINALITY AS selected(id, ordinality)
    JOIN public.instruments_v2 i ON i.id = selected.id
  ), missing AS MATERIALIZED (
    SELECT candidate.id, candidate.updated_at, 0 AS repair_priority
    FROM candidates candidate LEFT JOIN public.instrument_audio_profile_v1 p
      ON p.instrument_v2_id = candidate.id AND p.profile_version = p_profile_version
    WHERE p.instrument_v2_id IS NULL
  ), existing AS MATERIALIZED (
    SELECT candidate.id, candidate.updated_at, p.source_signature,
      public.compute_instrument_audio_profile_signature_v1(candidate.id, p_profile_version) AS current_signature
    FROM candidates candidate JOIN public.instrument_audio_profile_v1 p
      ON p.instrument_v2_id = candidate.id AND p.profile_version = p_profile_version
  ), repairs AS MATERIALIZED (
    SELECT id, updated_at, repair_priority FROM missing
    UNION ALL
    SELECT id, updated_at, 1 FROM existing
    WHERE p_force OR (NOT p_only_missing AND source_signature IS DISTINCT FROM current_signature)
  )
  SELECT coalesce(array_agg(repair.id ORDER BY repair.repair_priority, repair.updated_at DESC, repair.id ASC), ARRAY[]::uuid[])
  INTO v_repair_ids
  FROM (SELECT * FROM repairs ORDER BY repair_priority, updated_at DESC, id ASC LIMIT p_repair_limit) repair;

  RETURN QUERY SELECT * FROM public.enqueue_instrument_audio_profile_jobs_v1(
    v_repair_ids, coalesce(nullif(p_reason, ''), 'backfill'), p_profile_version, p_force, p_priority
  );
END;
$$;


ALTER FUNCTION "public"."enqueue_instrument_audio_profile_backfill_v2"("p_contributor_slug" "text", "p_instrument_v2_ids" "uuid"[], "p_only_missing" boolean, "p_candidate_limit" integer, "p_repair_limit" integer, "p_reason" "text", "p_profile_version" "text", "p_force" boolean, "p_priority" integer, "p_published_only" boolean, "p_cursor_updated_at" timestamp with time zone, "p_cursor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_instrument_audio_profile_jobs_v1"("p_instrument_v2_ids" "uuid"[], "p_reason" "text" DEFAULT 'manual'::"text", "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text", "p_force" boolean DEFAULT false, "p_priority" integer DEFAULT 0) RETURNS TABLE("instrument_v2_id" "uuid", "job_id" "uuid", "status" "text", "source_signature" "text", "enqueued" boolean, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH target AS (
    SELECT DISTINCT
      i.id AS instrument_v2_id,
      public.compute_instrument_audio_profile_signature_v1(i.id, p_profile_version) AS source_signature
    FROM public.instruments_v2 i
    WHERE i.id = ANY(COALESCE(p_instrument_v2_ids, ARRAY[]::uuid[]))
  ),
  upserted AS (
    INSERT INTO public.instrument_audio_profile_jobs_v1 (
      instrument_v2_id,
      profile_version,
      source_signature,
      status,
      reason,
      priority
    )
    SELECT
      target.instrument_v2_id,
      p_profile_version,
      target.source_signature,
      'queued',
      COALESCE(NULLIF(p_reason, ''), 'manual'),
      COALESCE(p_priority, 0)
    FROM target
    WHERE target.source_signature IS NOT NULL
    ON CONFLICT ON CONSTRAINT "instrument_audio_profile_jobs_v1_dedupe"
    DO UPDATE SET
      reason = EXCLUDED.reason,
      priority = GREATEST(public.instrument_audio_profile_jobs_v1.priority, EXCLUDED.priority),
      status = CASE
        WHEN p_force
          OR public.instrument_audio_profile_jobs_v1.status = 'failed'
          OR (
            public.instrument_audio_profile_jobs_v1.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
            AND NOT EXISTS (
              SELECT 1
              FROM public.instrument_audio_profile_v1 profile
              WHERE profile.instrument_v2_id = public.instrument_audio_profile_jobs_v1.instrument_v2_id
                AND profile.profile_version = public.instrument_audio_profile_jobs_v1.profile_version
                AND profile.source_signature IS NOT DISTINCT FROM public.instrument_audio_profile_jobs_v1.source_signature
            )
          ) THEN 'queued'
        ELSE public.instrument_audio_profile_jobs_v1.status
      END,
      lease_owner = CASE
        WHEN p_force
          OR public.instrument_audio_profile_jobs_v1.status = 'failed'
          OR (
            public.instrument_audio_profile_jobs_v1.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
            AND NOT EXISTS (
              SELECT 1
              FROM public.instrument_audio_profile_v1 profile
              WHERE profile.instrument_v2_id = public.instrument_audio_profile_jobs_v1.instrument_v2_id
                AND profile.profile_version = public.instrument_audio_profile_jobs_v1.profile_version
                AND profile.source_signature IS NOT DISTINCT FROM public.instrument_audio_profile_jobs_v1.source_signature
            )
          ) THEN NULL
        ELSE public.instrument_audio_profile_jobs_v1.lease_owner
      END,
      lease_expires_at = CASE
        WHEN p_force
          OR public.instrument_audio_profile_jobs_v1.status = 'failed'
          OR (
            public.instrument_audio_profile_jobs_v1.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
            AND NOT EXISTS (
              SELECT 1
              FROM public.instrument_audio_profile_v1 profile
              WHERE profile.instrument_v2_id = public.instrument_audio_profile_jobs_v1.instrument_v2_id
                AND profile.profile_version = public.instrument_audio_profile_jobs_v1.profile_version
                AND profile.source_signature IS NOT DISTINCT FROM public.instrument_audio_profile_jobs_v1.source_signature
            )
          ) THEN NULL
        ELSE public.instrument_audio_profile_jobs_v1.lease_expires_at
      END,
      completed_at = CASE
        WHEN p_force
          OR public.instrument_audio_profile_jobs_v1.status = 'failed'
          OR (
            public.instrument_audio_profile_jobs_v1.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
            AND NOT EXISTS (
              SELECT 1
              FROM public.instrument_audio_profile_v1 profile
              WHERE profile.instrument_v2_id = public.instrument_audio_profile_jobs_v1.instrument_v2_id
                AND profile.profile_version = public.instrument_audio_profile_jobs_v1.profile_version
                AND profile.source_signature IS NOT DISTINCT FROM public.instrument_audio_profile_jobs_v1.source_signature
            )
          ) THEN NULL
        ELSE public.instrument_audio_profile_jobs_v1.completed_at
      END,
      last_error = CASE
        WHEN p_force
          OR public.instrument_audio_profile_jobs_v1.status = 'failed'
          OR (
            public.instrument_audio_profile_jobs_v1.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
            AND NOT EXISTS (
              SELECT 1
              FROM public.instrument_audio_profile_v1 profile
              WHERE profile.instrument_v2_id = public.instrument_audio_profile_jobs_v1.instrument_v2_id
                AND profile.profile_version = public.instrument_audio_profile_jobs_v1.profile_version
                AND profile.source_signature IS NOT DISTINCT FROM public.instrument_audio_profile_jobs_v1.source_signature
            )
          ) THEN NULL
        ELSE public.instrument_audio_profile_jobs_v1.last_error
      END,
      updated_at = now()
    RETURNING
      public.instrument_audio_profile_jobs_v1.instrument_v2_id,
      public.instrument_audio_profile_jobs_v1.id,
      public.instrument_audio_profile_jobs_v1.status,
      public.instrument_audio_profile_jobs_v1.source_signature,
      public.instrument_audio_profile_jobs_v1.reason
  )
  SELECT
    upserted.instrument_v2_id,
    upserted.id,
    upserted.status,
    upserted.source_signature,
    upserted.status = 'queued',
    upserted.reason
  FROM upserted
  ORDER BY upserted.instrument_v2_id;
END;
$$;


ALTER FUNCTION "public"."enqueue_instrument_audio_profile_jobs_v1"("p_instrument_v2_ids" "uuid"[], "p_reason" "text", "p_profile_version" "text", "p_force" boolean, "p_priority" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_market_pattern_embedding_job"("p_market_pattern_id" "uuid", "p_embedding_space" "text", "p_source_hash" "text" DEFAULT NULL::"text", "p_force" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  active_job_id uuid;
  new_job_id uuid;
BEGIN
  IF p_market_pattern_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.market_patterns WHERE id = p_market_pattern_id
  ) THEN
    RAISE EXCEPTION 'Unknown market pattern: %', p_market_pattern_id
      USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(p_embedding_space), '') IS NULL THEN
    RAISE EXCEPTION 'p_embedding_space is required' USING ERRCODE = '22023';
  END IF;
  IF p_source_hash IS NOT NULL AND p_source_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'p_source_hash must be a lowercase SHA-256 value'
      USING ERRCODE = '22023';
  END IF;

  SELECT id INTO active_job_id
  FROM public.market_pattern_embedding_jobs
  WHERE market_pattern_id = p_market_pattern_id
    AND embedding_space = p_embedding_space
    AND status IN ('queued', 'running')
  ORDER BY created_at DESC
  LIMIT 1;
  IF active_job_id IS NOT NULL THEN
    -- Admin calls omit p_source_hash and need the active job id for truthful
    -- UI state. Reconciliation calls always provide a hash; returning NULL
    -- tells the backfill report that no new row was enqueued.
    RETURN CASE WHEN p_source_hash IS NULL THEN active_job_id ELSE NULL END;
  END IF;

  IF NOT p_force AND EXISTS (
    SELECT 1
    FROM public.market_pattern_embeddings
    WHERE market_pattern_id = p_market_pattern_id
      AND embedding_space = p_embedding_space
      AND (p_source_hash IS NULL OR source_hash = p_source_hash)
  ) THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.market_pattern_embedding_jobs (
    market_pattern_id,
    embedding_space,
    requested_source_hash,
    force
  ) VALUES (
    p_market_pattern_id,
    p_embedding_space,
    p_source_hash,
    p_force
  )
  RETURNING id INTO new_job_id;

  RETURN new_job_id;
EXCEPTION WHEN unique_violation THEN
  SELECT id INTO active_job_id
  FROM public.market_pattern_embedding_jobs
  WHERE market_pattern_id = p_market_pattern_id
    AND embedding_space = p_embedding_space
    AND status IN ('queued', 'running')
  ORDER BY created_at DESC
  LIMIT 1;
  RETURN CASE WHEN p_source_hash IS NULL THEN active_job_id ELSE NULL END;
END;
$_$;


ALTER FUNCTION "public"."enqueue_market_pattern_embedding_job"("p_market_pattern_id" "uuid", "p_embedding_space" "text", "p_source_hash" "text", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_published_sample_analysis"("p_published_asset_id" "uuid", "p_stages" "text"[] DEFAULT ARRAY['analysis'::"text", 'librosa'::"text"], "p_priority" integer DEFAULT 0, "p_force" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_asset public.sample_s3_path%ROWTYPE; v_stage text; v_count integer := 0;
BEGIN
  SELECT * INTO v_asset FROM public.sample_s3_path
    WHERE id = p_published_asset_id AND is_current FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Current published asset % not found', p_published_asset_id; END IF;
  IF v_asset.excluded_at IS NOT NULL THEN RETURN 0; END IF;
  FOREACH v_stage IN ARRAY p_stages LOOP
    IF v_stage <> ALL (ARRAY['analysis','derived','librosa','deep_derived']) THEN
      RAISE EXCEPTION 'Unsupported published analysis stage: %', v_stage;
    END IF;
    INSERT INTO public.sample_analysis_jobs(
      published_asset_id, stage, analysis_version, source_signature, priority
    ) VALUES (v_asset.id, v_stage, v_asset.analysis_version, v_asset.source_signature, p_priority)
    ON CONFLICT ON CONSTRAINT sample_analysis_jobs_dedupe DO UPDATE SET
      status = CASE WHEN p_force THEN 'queued' ELSE public.sample_analysis_jobs.status END,
      priority = greatest(public.sample_analysis_jobs.priority, EXCLUDED.priority),
      attempts = CASE WHEN p_force THEN 0 ELSE public.sample_analysis_jobs.attempts END,
      available_at = CASE WHEN p_force THEN now() ELSE public.sample_analysis_jobs.available_at END,
      lease_owner = CASE WHEN p_force THEN NULL ELSE public.sample_analysis_jobs.lease_owner END,
      lease_token = CASE WHEN p_force THEN NULL ELSE public.sample_analysis_jobs.lease_token END,
      lease_expires_at = CASE WHEN p_force THEN NULL ELSE public.sample_analysis_jobs.lease_expires_at END,
      completed_at = CASE WHEN p_force THEN NULL ELSE public.sample_analysis_jobs.completed_at END,
      last_error = CASE WHEN p_force THEN NULL ELSE public.sample_analysis_jobs.last_error END;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END $$;


ALTER FUNCTION "public"."enqueue_published_sample_analysis"("p_published_asset_id" "uuid", "p_stages" "text"[], "p_priority" integer, "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_published_sample_temporal_analysis"("p_published_asset_id" "uuid", "p_priority" integer DEFAULT 0, "p_force" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_asset public.sample_s3_path%ROWTYPE;
BEGIN
  SELECT * INTO v_asset
  FROM public.sample_s3_path
  WHERE id = p_published_asset_id AND is_current
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Current published asset % not found', p_published_asset_id;
  END IF;
  IF v_asset.excluded_at IS NOT NULL THEN RETURN 0; END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.instruments_v2 instrument
    WHERE instrument.id = v_asset.instrument_v2_id
      AND (
        instrument.published = true
        OR EXISTS (
          SELECT 1
          FROM public.sip_sibling_consolidation_receipts_v2 receipt
          WHERE receipt.canonical_instrument_v2_id = instrument.id
            AND receipt.status = 'cutover'
            AND receipt.closeout_status = 'pending'
        )
      )
  ) THEN
    RETURN 0;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.instruments_v2 instrument
    JOIN public.contributors contributor ON contributor.id = instrument.contributor_id
    WHERE instrument.id = v_asset.instrument_v2_id
      AND contributor.slug IN ('gotchanoddin', 'sound-dust')
  ) THEN
    RETURN 0;
  END IF;

  INSERT INTO public.sample_analysis_jobs(
    published_asset_id, stage, analysis_version, algorithm_version,
    source_signature, priority
  ) VALUES (
    v_asset.id, 'temporal', 'temporal-v1', 'global-temporal-pcm-v1',
    v_asset.source_signature, p_priority
  ) ON CONFLICT ON CONSTRAINT sample_analysis_jobs_dedupe DO UPDATE SET
    algorithm_version = EXCLUDED.algorithm_version,
    status = CASE
      WHEN p_force
        OR public.sample_analysis_jobs.algorithm_version
          IS DISTINCT FROM EXCLUDED.algorithm_version
      THEN 'queued'
      ELSE public.sample_analysis_jobs.status
    END,
    priority = greatest(public.sample_analysis_jobs.priority, EXCLUDED.priority),
    attempts = CASE
      WHEN p_force
        OR public.sample_analysis_jobs.algorithm_version
          IS DISTINCT FROM EXCLUDED.algorithm_version
      THEN 0
      ELSE public.sample_analysis_jobs.attempts
    END,
    available_at = CASE
      WHEN p_force
        OR public.sample_analysis_jobs.algorithm_version
          IS DISTINCT FROM EXCLUDED.algorithm_version
      THEN now()
      ELSE public.sample_analysis_jobs.available_at
    END,
    lease_owner = CASE
      WHEN p_force
        OR public.sample_analysis_jobs.algorithm_version
          IS DISTINCT FROM EXCLUDED.algorithm_version
      THEN NULL
      ELSE public.sample_analysis_jobs.lease_owner
    END,
    lease_token = CASE
      WHEN p_force
        OR public.sample_analysis_jobs.algorithm_version
          IS DISTINCT FROM EXCLUDED.algorithm_version
      THEN NULL
      ELSE public.sample_analysis_jobs.lease_token
    END,
    lease_expires_at = CASE
      WHEN p_force
        OR public.sample_analysis_jobs.algorithm_version
          IS DISTINCT FROM EXCLUDED.algorithm_version
      THEN NULL
      ELSE public.sample_analysis_jobs.lease_expires_at
    END,
    completed_at = CASE
      WHEN p_force
        OR public.sample_analysis_jobs.algorithm_version
          IS DISTINCT FROM EXCLUDED.algorithm_version
      THEN NULL
      ELSE public.sample_analysis_jobs.completed_at
    END,
    result_payload = CASE
      WHEN p_force
        OR public.sample_analysis_jobs.algorithm_version
          IS DISTINCT FROM EXCLUDED.algorithm_version
      THEN '{}'::jsonb
      ELSE public.sample_analysis_jobs.result_payload
    END,
    last_error = CASE
      WHEN p_force
        OR public.sample_analysis_jobs.algorithm_version
          IS DISTINCT FROM EXCLUDED.algorithm_version
      THEN NULL
      ELSE public.sample_analysis_jobs.last_error
    END;
  RETURN 1;
END $$;


ALTER FUNCTION "public"."enqueue_published_sample_temporal_analysis"("p_published_asset_id" "uuid", "p_priority" integer, "p_force" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_published_sample_temporal_analysis"("p_published_asset_id" "uuid", "p_priority" integer, "p_force" boolean) IS 'Queues one versioned, published-MP3 temporal analysis job without modifying SIP provider state.';



CREATE OR REPLACE FUNCTION "public"."enqueue_sample_audio_profile_jobs_v1"("p_sample_original_path_ids" "uuid"[], "p_reason" "text" DEFAULT 'manual'::"text", "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text", "p_force" boolean DEFAULT false, "p_priority" integer DEFAULT 0) RETURNS TABLE("sample_original_path_id" "uuid", "job_id" "uuid", "status" "text", "source_analysis_signature" "text", "enqueued" boolean, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH target AS (
    SELECT DISTINCT
      osp.id AS sample_original_path_id,
      public.compute_sample_audio_profile_signature_v1(osp.id, p_profile_version) AS source_analysis_signature
    FROM public.samples_original_paths osp
    WHERE osp.id = ANY(COALESCE(p_sample_original_path_ids, ARRAY[]::uuid[]))
  ),
  upserted AS (
    INSERT INTO public.sample_audio_profile_jobs_v1 (
      sample_original_path_id,
      profile_version,
      source_analysis_signature,
      status,
      reason,
      priority
    )
    SELECT
      target.sample_original_path_id,
      p_profile_version,
      target.source_analysis_signature,
      'queued',
      COALESCE(NULLIF(p_reason, ''), 'manual'),
      COALESCE(p_priority, 0)
    FROM target
    WHERE target.source_analysis_signature IS NOT NULL
    ON CONFLICT ON CONSTRAINT "sample_audio_profile_jobs_v1_dedupe"
    DO UPDATE SET
      reason = EXCLUDED.reason,
      priority = GREATEST(public.sample_audio_profile_jobs_v1.priority, EXCLUDED.priority),
      status = CASE
        WHEN p_force
          OR public.sample_audio_profile_jobs_v1.status = 'failed'
          OR (
            public.sample_audio_profile_jobs_v1.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
            AND NOT EXISTS (
              SELECT 1
              FROM public.sample_audio_profile_v1 profile
              WHERE profile.sample_original_path_id = public.sample_audio_profile_jobs_v1.sample_original_path_id
                AND profile.profile_version = public.sample_audio_profile_jobs_v1.profile_version
                AND profile.source_analysis_signature IS NOT DISTINCT FROM public.sample_audio_profile_jobs_v1.source_analysis_signature
            )
          ) THEN 'queued'
        ELSE public.sample_audio_profile_jobs_v1.status
      END,
      lease_owner = CASE
        WHEN p_force
          OR public.sample_audio_profile_jobs_v1.status = 'failed'
          OR (
            public.sample_audio_profile_jobs_v1.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
            AND NOT EXISTS (
              SELECT 1
              FROM public.sample_audio_profile_v1 profile
              WHERE profile.sample_original_path_id = public.sample_audio_profile_jobs_v1.sample_original_path_id
                AND profile.profile_version = public.sample_audio_profile_jobs_v1.profile_version
                AND profile.source_analysis_signature IS NOT DISTINCT FROM public.sample_audio_profile_jobs_v1.source_analysis_signature
            )
          ) THEN NULL
        ELSE public.sample_audio_profile_jobs_v1.lease_owner
      END,
      lease_expires_at = CASE
        WHEN p_force
          OR public.sample_audio_profile_jobs_v1.status = 'failed'
          OR (
            public.sample_audio_profile_jobs_v1.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
            AND NOT EXISTS (
              SELECT 1
              FROM public.sample_audio_profile_v1 profile
              WHERE profile.sample_original_path_id = public.sample_audio_profile_jobs_v1.sample_original_path_id
                AND profile.profile_version = public.sample_audio_profile_jobs_v1.profile_version
                AND profile.source_analysis_signature IS NOT DISTINCT FROM public.sample_audio_profile_jobs_v1.source_analysis_signature
            )
          ) THEN NULL
        ELSE public.sample_audio_profile_jobs_v1.lease_expires_at
      END,
      completed_at = CASE
        WHEN p_force
          OR public.sample_audio_profile_jobs_v1.status = 'failed'
          OR (
            public.sample_audio_profile_jobs_v1.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
            AND NOT EXISTS (
              SELECT 1
              FROM public.sample_audio_profile_v1 profile
              WHERE profile.sample_original_path_id = public.sample_audio_profile_jobs_v1.sample_original_path_id
                AND profile.profile_version = public.sample_audio_profile_jobs_v1.profile_version
                AND profile.source_analysis_signature IS NOT DISTINCT FROM public.sample_audio_profile_jobs_v1.source_analysis_signature
            )
          ) THEN NULL
        ELSE public.sample_audio_profile_jobs_v1.completed_at
      END,
      last_error = CASE
        WHEN p_force
          OR public.sample_audio_profile_jobs_v1.status = 'failed'
          OR (
            public.sample_audio_profile_jobs_v1.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
            AND NOT EXISTS (
              SELECT 1
              FROM public.sample_audio_profile_v1 profile
              WHERE profile.sample_original_path_id = public.sample_audio_profile_jobs_v1.sample_original_path_id
                AND profile.profile_version = public.sample_audio_profile_jobs_v1.profile_version
                AND profile.source_analysis_signature IS NOT DISTINCT FROM public.sample_audio_profile_jobs_v1.source_analysis_signature
            )
          ) THEN NULL
        ELSE public.sample_audio_profile_jobs_v1.last_error
      END,
      updated_at = now()
    RETURNING
      public.sample_audio_profile_jobs_v1.sample_original_path_id,
      public.sample_audio_profile_jobs_v1.id,
      public.sample_audio_profile_jobs_v1.status,
      public.sample_audio_profile_jobs_v1.source_analysis_signature,
      public.sample_audio_profile_jobs_v1.reason
  )
  SELECT
    upserted.sample_original_path_id,
    upserted.id,
    upserted.status,
    upserted.source_analysis_signature,
    upserted.status = 'queued',
    upserted.reason
  FROM upserted
  ORDER BY upserted.sample_original_path_id;
END;
$$;


ALTER FUNCTION "public"."enqueue_sample_audio_profile_jobs_v1"("p_sample_original_path_ids" "uuid"[], "p_reason" "text", "p_profile_version" "text", "p_force" boolean, "p_priority" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_sample_psychoacoustic_characteristic_jobs_v1"("p_requests" "jsonb", "p_run_kind" "text", "p_requested_by" "text", "p_force" boolean DEFAULT false) RETURNS TABLE("ordinal" integer, "job_id" "uuid", "status" "text", "idempotent" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_item record;
  v_existing public.sample_psychoacoustic_characteristic_jobs%ROWTYPE;
  v_inserted public.sample_psychoacoustic_characteristic_jobs%ROWTYPE;
  v_count integer;
BEGIN
  IF jsonb_typeof(p_requests) <> 'array'
     OR p_run_kind NOT IN ('validation', 'recompute', 'manual')
     OR btrim(coalesce(p_requested_by, '')) = ''
     OR length(p_requested_by) > 256
  THEN
    RAISE EXCEPTION 'invalid psychoacoustic job request' USING ERRCODE = '22023';
  END IF;
  v_count := jsonb_array_length(p_requests);
  IF v_count < 1 OR v_count > 100 THEN
    RAISE EXCEPTION 'p_requests must contain 1 to 100 identities'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_requests) AS item
    GROUP BY item
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'p_requests contains duplicate identities'
      USING ERRCODE = '22023';
  END IF;

  FOR v_item IN
    SELECT
      item.ordinality::integer AS ordinal,
      (item.value->>'publishedAssetId')::uuid AS published_asset_id,
      item.value->>'assetSourceSignature' AS asset_source_signature,
      item.value->>'characteristicKey' AS characteristic_key,
      item.value->>'evidenceContractVersion' AS evidence_contract_version,
      item.value->>'algorithmVersion' AS algorithm_version,
      item.value->>'projectionVersion' AS projection_version
    FROM jsonb_array_elements(p_requests) WITH ORDINALITY AS item(value, ordinality)
    ORDER BY
      published_asset_id,
      asset_source_signature,
      characteristic_key,
      evidence_contract_version,
      algorithm_version,
      projection_version NULLS FIRST,
      ordinal
  LOOP
    IF v_item.asset_source_signature !~ '^apv1:sha256-v1:[0-9a-f]{64}$'
       OR public.sample_psychoacoustic_token_is_valid_v1(
         v_item.characteristic_key
       ) IS NOT TRUE
       OR public.sample_psychoacoustic_token_is_valid_v1(
         v_item.evidence_contract_version
       ) IS NOT TRUE
       OR public.sample_psychoacoustic_token_is_valid_v1(
         v_item.algorithm_version
       ) IS NOT TRUE
       OR (v_item.projection_version IS NOT NULL
           AND public.sample_psychoacoustic_token_is_valid_v1(
             v_item.projection_version
           ) IS NOT TRUE)
    THEN
      RAISE EXCEPTION 'invalid psychoacoustic job identity'
        USING ERRCODE = '22023';
    END IF;

    PERFORM 1
    FROM public.sample_s3_path AS asset
    WHERE asset.id = v_item.published_asset_id
      AND asset.source_signature = v_item.asset_source_signature
      AND asset.is_current
      AND asset.excluded_at IS NULL
      AND asset.quality = 1
      AND asset.format = 'mp3'
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'psychoacoustic_asset_identity_conflict';
    END IF;

    IF p_force THEN
      INSERT INTO public.sample_psychoacoustic_characteristic_jobs(
        published_asset_id,
        asset_source_signature,
        characteristic_key,
        evidence_contract_version,
        algorithm_version,
        projection_version,
        run_kind,
        requested_by
      ) VALUES (
        v_item.published_asset_id,
        v_item.asset_source_signature,
        v_item.characteristic_key,
        v_item.evidence_contract_version,
        v_item.algorithm_version,
        v_item.projection_version,
        p_run_kind,
        p_requested_by
      )
      ON CONFLICT ON CONSTRAINT sample_psychoacoustic_jobs_identity_key
      DO UPDATE SET
        status = 'queued',
        result_record_id = NULL,
        updated_at = now()
      WHERE sample_psychoacoustic_characteristic_jobs.run_kind = EXCLUDED.run_kind
        AND sample_psychoacoustic_characteristic_jobs.requested_by = EXCLUDED.requested_by
      RETURNING * INTO v_existing;
      IF v_existing.id IS NULL THEN
        RAISE EXCEPTION USING
          ERRCODE = 'P0001',
          MESSAGE = 'psychoacoustic_job_identity_conflict';
      END IF;
      RETURN QUERY SELECT
        v_item.ordinal,
        v_existing.id,
        v_existing.status,
        false;
    ELSE
      v_inserted := NULL;
      INSERT INTO public.sample_psychoacoustic_characteristic_jobs(
        published_asset_id,
        asset_source_signature,
        characteristic_key,
        evidence_contract_version,
        algorithm_version,
        projection_version,
        run_kind,
        requested_by
      ) VALUES (
        v_item.published_asset_id,
        v_item.asset_source_signature,
        v_item.characteristic_key,
        v_item.evidence_contract_version,
        v_item.algorithm_version,
        v_item.projection_version,
        p_run_kind,
        p_requested_by
      )
      ON CONFLICT ON CONSTRAINT sample_psychoacoustic_jobs_identity_key
      DO NOTHING
      RETURNING * INTO v_inserted;
      IF v_inserted.id IS NOT NULL THEN
        RETURN QUERY SELECT
          v_item.ordinal,
          v_inserted.id,
          v_inserted.status,
          false;
        CONTINUE;
      END IF;

      SELECT * INTO v_existing
      FROM public.sample_psychoacoustic_characteristic_jobs AS job
      WHERE job.published_asset_id = v_item.published_asset_id
        AND job.asset_source_signature = v_item.asset_source_signature
        AND job.characteristic_key = v_item.characteristic_key
        AND job.evidence_contract_version = v_item.evidence_contract_version
        AND job.algorithm_version = v_item.algorithm_version
        AND job.projection_version IS NOT DISTINCT FROM v_item.projection_version
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING
          ERRCODE = '40001',
          MESSAGE = 'psychoacoustic_job_concurrent_resolution_failed';
      END IF;
      IF v_existing.run_kind <> p_run_kind
         OR v_existing.requested_by <> p_requested_by
      THEN
        RAISE EXCEPTION USING
          ERRCODE = 'P0001',
          MESSAGE = 'psychoacoustic_job_identity_conflict';
      END IF;
      RETURN QUERY SELECT
        v_item.ordinal,
        v_existing.id,
        v_existing.status,
        true;
    END IF;
  END LOOP;
END;
$_$;


ALTER FUNCTION "public"."enqueue_sample_psychoacoustic_characteristic_jobs_v1"("p_requests" "jsonb", "p_run_kind" "text", "p_requested_by" "text", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_sip_pipeline_run"("p_contributor_slug" "text", "p_mode" "text" DEFAULT 'run_all_contributor'::"text", "p_requested_by" "text" DEFAULT NULL::"text", "p_batch_settings" "jsonb" DEFAULT '{}'::"jsonb", "p_scope" "jsonb" DEFAULT '{}'::"jsonb", "p_max_attempts" integer DEFAULT 3) RETURNS SETOF "public"."sip_pipeline_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run_id uuid;
BEGIN
  IF NULLIF(btrim(p_contributor_slug), '') IS NULL THEN
    RAISE EXCEPTION 'contributor_slug_required';
  END IF;

  IF COALESCE(jsonb_typeof(p_batch_settings), 'object') <> 'object' THEN
    RAISE EXCEPTION 'batch_settings_must_be_object';
  END IF;

  IF COALESCE(jsonb_typeof(p_scope), 'object') <> 'object' THEN
    RAISE EXCEPTION 'scope_must_be_object';
  END IF;

  SELECT id INTO v_run_id
  FROM public.sip_pipeline_runs
  WHERE contributor_slug = p_contributor_slug
    AND mode = COALESCE(NULLIF(p_mode, ''), 'run_all_contributor')
    AND status IN ('queued', 'running', 'paused')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_run_id IS NOT NULL THEN
    RETURN QUERY SELECT * FROM public.sip_pipeline_runs WHERE id = v_run_id;
    RETURN;
  END IF;

  INSERT INTO public.sip_pipeline_runs (
    contributor_slug,
    mode,
    requested_by,
    batch_settings,
    scope,
    last_event_at,
    heartbeat_at
  )
  VALUES (
    p_contributor_slug,
    COALESCE(NULLIF(p_mode, ''), 'run_all_contributor'),
    p_requested_by,
    COALESCE(p_batch_settings, '{}'::jsonb),
    COALESCE(p_scope, '{}'::jsonb),
    now(),
    now()
  )
  RETURNING id INTO v_run_id;

  INSERT INTO public.sip_pipeline_run_items (
    run_id,
    staging_instrument_id,
    source_sip_instrument_id,
    instrument_v2_id,
    contributor_slug,
    instrument_name,
    current_stage,
    max_attempts
  )
  SELECT
    v_run_id,
    sri.id,
    sri.source_sip_instrument_id,
    spm.instrument_v2_id,
    sri.source_contributor_slug,
    sri.name,
    public.sip_pipeline_stage_from_upload_status(
      sri.source_sip_instrument_id,
      'publish-actions'
    ),
    GREATEST(COALESCE(p_max_attempts, 3), 1)
  FROM public.sip_review_instrument sri
  LEFT JOIN public.sip_review_promotion_map spm
    ON spm.sip_review_instrument_id = sri.id
  LEFT JOIN public.instruments_v2 iv2
    ON iv2.id = spm.instrument_v2_id
  WHERE sri.source_contributor_slug = p_contributor_slug
    AND sri.is_retired = false
    AND sri.split_parent_sip_review_instrument_id IS NULL
    AND COALESCE(iv2.published, false) = false
  ORDER BY lower(sri.name), sri.id;

  INSERT INTO public.sip_pipeline_run_events (
    run_id,
    event_type,
    message,
    payload
  )
  VALUES (
    v_run_id,
    'run_enqueued',
    'Queued SIP contributor publish run',
    jsonb_build_object(
      'contributorSlug', p_contributor_slug,
      'mode', COALESCE(NULLIF(p_mode, ''), 'run_all_contributor')
    )
  );

  PERFORM public.sip_pipeline_refresh_run_counts(v_run_id);

  RETURN QUERY SELECT * FROM public.sip_pipeline_runs WHERE id = v_run_id;
END;
$$;


ALTER FUNCTION "public"."enqueue_sip_pipeline_run"("p_contributor_slug" "text", "p_mode" "text", "p_requested_by" "text", "p_batch_settings" "jsonb", "p_scope" "jsonb", "p_max_attempts" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_market_pattern_embedding_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_error" "text", "p_retryable" boolean DEFAULT true, "p_retry_after_seconds" integer DEFAULT 30) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  job public.market_pattern_embedding_jobs%ROWTYPE;
  next_status text;
BEGIN
  IF NULLIF(btrim(p_error), '') IS NULL THEN
    RAISE EXCEPTION 'p_error is required' USING ERRCODE = '22023';
  END IF;
  IF p_retry_after_seconds NOT BETWEEN 0 AND 86400 THEN
    RAISE EXCEPTION 'p_retry_after_seconds must be between 0 and 86400'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO job
  FROM public.market_pattern_embedding_jobs
  WHERE id = p_job_id
  FOR UPDATE;
  IF job.id IS NULL
    OR job.status <> 'running'
    OR job.lease_token IS DISTINCT FROM p_lease_token
    OR job.lease_expires_at <= now()
  THEN
    RAISE EXCEPTION 'Stale or expired lease token for job %', p_job_id
      USING ERRCODE = '55000';
  END IF;

  next_status := CASE
    WHEN p_retryable AND job.attempt_count < job.max_attempts THEN 'queued'
    ELSE 'failed'
  END;

  UPDATE public.market_pattern_embedding_jobs
  SET
    status = next_status,
    available_at = CASE
      WHEN next_status = 'queued'
        THEN now() + make_interval(secs => p_retry_after_seconds)
      ELSE available_at
    END,
    lease_token = NULL,
    leased_by = NULL,
    lease_expires_at = NULL,
    last_heartbeat_at = NULL,
    last_error = left(p_error, 8000),
    completed_at = NULL
  WHERE id = p_job_id;

  RETURN next_status;
END;
$$;


ALTER FUNCTION "public"."fail_market_pattern_embedding_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_error" "text", "p_retryable" boolean, "p_retry_after_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_published_sample_analysis_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_error" "text", "p_retryable" boolean DEFAULT true) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_changed integer;
BEGIN
  UPDATE public.sample_analysis_jobs job SET
    status=CASE WHEN p_retryable AND job.attempts < job.max_attempts THEN 'queued' ELSE 'failed' END,
    available_at=CASE WHEN p_retryable THEN now() + make_interval(secs => least(3600, power(2,job.attempts)::integer * 15)) ELSE job.available_at END,
    last_error=left(p_error,8000), lease_owner=NULL, lease_token=NULL, lease_expires_at=NULL
  WHERE id=p_job_id AND status='running' AND lease_token=p_lease_token;
  GET DIAGNOSTICS v_changed = ROW_COUNT; RETURN v_changed=1;
END $$;


ALTER FUNCTION "public"."fail_published_sample_analysis_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_error" "text", "p_retryable" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."filter_sip_staging_instrument_payload_rows"("p_payload" "jsonb", "p_search" "text" DEFAULT ''::"text", "p_path_search" "text" DEFAULT ''::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
WITH args AS (
  SELECT
    lower(btrim(coalesce(p_search, ''))) AS search,
    lower(btrim(coalesce(p_path_search, ''))) AS path_search,
    replace(
      replace(
        replace(lower(btrim(coalesce(p_path_search, ''))), E'\\', E'\\\\'),
        '%',
        E'\\%'
      ),
      '_',
      E'\\_'
    ) AS path_search_like
),
raw_rows AS (
  SELECT
    row_value.value,
    row_value.ordinality,
    lower(concat_ws(
      ' ',
      row_value.value->>'name',
      row_value.value->>'instrumentFamily',
      row_value.value->>'instrument_family',
      row_value.value->>'instrumentType',
      row_value.value->>'instrument_type',
      row_value.value->>'originalFilePathReference',
      row_value.value->>'original_file_path_reference',
      row_value.value->>'filePathReference',
      row_value.value->>'file_path_reference',
      file_names.value
    )) AS global_haystack,
    lower(concat_ws(
      ' ',
      row_value.value->>'originalFilePathReference',
      row_value.value->>'original_file_path_reference',
      row_value.value->>'filePathReference',
      row_value.value->>'file_path_reference',
      file_names.value
    )) AS path_haystack
  FROM jsonb_array_elements(coalesce(p_payload->'rows', '[]'::jsonb))
    WITH ORDINALITY AS row_value(value, ordinality)
  CROSS JOIN LATERAL (
    SELECT coalesce(string_agg(file_name.value, ' '), '') AS value
    FROM (
      SELECT value
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(row_value.value->'originalFileNameReferences') = 'array'
            THEN row_value.value->'originalFileNameReferences'
          ELSE '[]'::jsonb
        END
      )
      UNION ALL
      SELECT value
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(row_value.value->'fileNameReferences') = 'array'
            THEN row_value.value->'fileNameReferences'
          ELSE '[]'::jsonb
        END
      )
    ) AS file_name(value)
  ) AS file_names
),
filtered AS (
  SELECT raw_rows.value, raw_rows.ordinality
  FROM raw_rows
  CROSS JOIN args
  WHERE (
    args.search = ''
    OR NOT EXISTS (
      SELECT 1
      FROM regexp_split_to_table(args.search, '[[:space:]]+') AS token(value)
      WHERE btrim(token.value) <> ''
        AND raw_rows.global_haystack NOT LIKE (
          '%' ||
          replace(
            replace(replace(token.value, E'\\', E'\\\\'), '%', E'\\%'),
            '_',
            E'\\_'
          ) ||
          '%'
        ) ESCAPE E'\\'
    )
  )
  AND (
    args.path_search = ''
    OR raw_rows.path_haystack LIKE ('%' || args.path_search_like || '%') ESCAPE E'\\'
  )
)
SELECT jsonb_build_object(
  'rows',
  coalesce(
    (
      SELECT jsonb_agg(filtered.value ORDER BY filtered.ordinality)
      FROM filtered
    ),
    '[]'::jsonb
  ),
  'totalCount',
  (SELECT count(*)::integer FROM filtered)
);
$$;


ALTER FUNCTION "public"."filter_sip_staging_instrument_payload_rows"("p_payload" "jsonb", "p_search" "text", "p_path_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_community_loop_picks"("p_limit" integer) RETURNS TABLE("saved_loop_id" "uuid", "like_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 8 THEN
    RAISE EXCEPTION 'p_limit must be an integer between 1 and 8'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.saved_loop_likes AS saved_loop_like
    INNER JOIN public.saved_loops AS saved_loop
      ON saved_loop.id = saved_loop_like.saved_loop_id
    WHERE saved_loop.is_archived = false
      AND saved_loop.show_in_loops_library = true
      AND saved_loop.share_visibility = 'public'
    LIMIT 1
  ) THEN
    RETURN QUERY
    SELECT
      saved_loop.id AS saved_loop_id,
      count(saved_loop_like.id)::bigint AS like_count
    FROM public.saved_loops AS saved_loop
    LEFT JOIN public.saved_loop_likes AS saved_loop_like
      ON saved_loop_like.saved_loop_id = saved_loop.id
    WHERE saved_loop.is_archived = false
      AND saved_loop.show_in_loops_library = true
      AND saved_loop.share_visibility = 'public'
    GROUP BY saved_loop.id, saved_loop.published_at
    ORDER BY
      count(saved_loop_like.id) DESC,
      saved_loop.published_at DESC NULLS LAST,
      saved_loop.id DESC
    LIMIT p_limit;
  ELSE
    RETURN QUERY
    SELECT
      saved_loop.id AS saved_loop_id,
      0::bigint AS like_count
    FROM public.saved_loops AS saved_loop
    WHERE saved_loop.is_archived = false
      AND saved_loop.show_in_loops_library = true
      AND saved_loop.share_visibility = 'public'
    ORDER BY pg_catalog.random()
    LIMIT p_limit;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_community_loop_picks"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_featured_blog_posts_by_content"("post_slug" "text", "query_embedding" "extensions"."vector") RETURNS TABLE("created_at" timestamp with time zone, "img_url" "text", "author" "text", "title" "text", "similarity" double precision, "slug" "text")
    LANGUAGE "plpgsql"
    AS $$BEGIN RETURN QUERY SELECT bp.created_at, bp.img_url, bp.author, bp.title, 1 - (bp.content_embedding <=> query_embedding) AS similarity, bp.slug FROM blog_posts bp WHERE bp.slug != post_slug ORDER BY similarity DESC, bp.slug LIMIT 3; END;$$;


ALTER FUNCTION "public"."get_featured_blog_posts_by_content"("post_slug" "text", "query_embedding" "extensions"."vector") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_market_loop_favorite_counts"("p_pairs" "jsonb") RETURNS TABLE("market_pattern_id" "uuid", "sample_id" "uuid", "like_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_pairs IS NULL OR pg_catalog.jsonb_typeof(p_pairs) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'p_pairs must be a JSON array of at most 100 pairs'
      USING ERRCODE = '22023';
  END IF;

  IF pg_catalog.jsonb_array_length(p_pairs) > 100 THEN
    RAISE EXCEPTION 'p_pairs must contain at most 100 pairs'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_array_elements(p_pairs) AS input_pair(value)
    WHERE pg_catalog.jsonb_typeof(input_pair.value) IS DISTINCT FROM 'object'
      OR pg_catalog.jsonb_typeof(input_pair.value -> 'market_pattern_id') IS DISTINCT FROM 'string'
      OR pg_catalog.jsonb_typeof(input_pair.value -> 'sample_id') IS DISTINCT FROM 'string'
  ) THEN
    RAISE EXCEPTION 'each p_pairs entry must contain string market_pattern_id and sample_id fields'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH requested AS (
    SELECT DISTINCT
      pair.market_pattern_id,
      pair.sample_id
    FROM pg_catalog.jsonb_to_recordset(p_pairs) AS pair(
      market_pattern_id uuid,
      sample_id uuid
    )
  )
  SELECT
    requested.market_pattern_id,
    requested.sample_id,
    count(favorite.id)::bigint AS like_count
  FROM requested
  LEFT JOIN public.market_loop_favorites AS favorite
    ON favorite.market_pattern_id = requested.market_pattern_id
   AND favorite.sample_id = requested.sample_id
  GROUP BY requested.market_pattern_id, requested.sample_id;
END;
$$;


ALTER FUNCTION "public"."get_market_loop_favorite_counts"("p_pairs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_market_loop_most_liked"("p_limit" integer DEFAULT 8) RETURNS TABLE("market_pattern_id" "uuid", "sample_id" "uuid", "like_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 24 THEN
    RAISE EXCEPTION 'p_limit must be between 1 and 24'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    favorite.market_pattern_id,
    favorite.sample_id,
    count(favorite.id)::bigint AS like_count
  FROM public.market_loop_favorites AS favorite
  GROUP BY favorite.market_pattern_id, favorite.sample_id
  ORDER BY
    count(favorite.id) DESC,
    favorite.market_pattern_id ASC,
    favorite.sample_id ASC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_market_loop_most_liked"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_monthly_allowance_usage"("p_user_id" "uuid") RETURNS TABLE("policy_key" "text", "allowance_bucket" "text", "used" integer, "limit" integer, "remaining" integer, "resets_at" timestamp with time zone)
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  WITH current_month AS (
    SELECT date_trunc('month', timezone('UTC', clock_timestamp()))::date AS usage_period_start,
      (date_trunc('month', timezone('UTC', clock_timestamp())) + interval '1 month') AT TIME ZONE 'UTC' AS resets_at
  )
  SELECT policies.policy_key, policies.allowance_bucket,
    count(claims.id)::integer AS used, policies.monthly_limit AS "limit",
    greatest(policies.monthly_limit - count(claims.id)::integer, 0) AS remaining,
    current_month.resets_at
  FROM public.monthly_allowance_policies policies CROSS JOIN current_month
  LEFT JOIN public.monthly_allowance_claims claims
    ON claims.user_id = p_user_id AND claims.policy_key = policies.policy_key
    AND claims.usage_period_start = current_month.usage_period_start
    AND claims.consumption_status = 'consumed'
  WHERE policies.is_active AND policies.is_default_free
  GROUP BY policies.policy_key, policies.allowance_bucket, policies.monthly_limit, current_month.resets_at;
$$;


ALTER FUNCTION "public"."get_monthly_allowance_usage"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_feature_flags"() RETURNS TABLE("key" "text", "enabled" boolean, "assigned_enabled" boolean, "evaluation_reason" "text", "is_active" boolean, "requires_reload" boolean, "dev_logging_enabled" boolean, "product_insights_enabled" boolean, "assignment_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := (SELECT private.feature_flag_request_user_id());
BEGIN
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    flags.key,
    flags.is_active AND COALESCE(assignments.enabled, false) AS enabled,
    COALESCE(assignments.enabled, false) AS assigned_enabled,
    CASE
      WHEN NOT flags.is_active THEN 'inactive'
      WHEN assignments.enabled IS TRUE THEN 'targeted'
      WHEN assignments.user_id IS NOT NULL THEN 'explicitly_disabled'
      ELSE 'not_assigned'
    END AS evaluation_reason,
    flags.is_active,
    flags.requires_reload,
    flags.dev_logging_enabled,
    flags.product_insights_enabled,
    assignments.updated_at AS assignment_updated_at
  FROM public.feature_flags AS flags
  LEFT JOIN public.feature_user_enablements AS assignments
    ON assignments.feature_flag_id = flags.id
   AND assignments.user_id = v_user_id
  WHERE flags.archived_at IS NULL
  ORDER BY flags.key;
END;
$$;


ALTER FUNCTION "public"."get_my_feature_flags"() OWNER TO "feature_flag_owner";


CREATE OR REPLACE FUNCTION "public"."get_sample_like_stats"("p_sample_ids" "jsonb") RETURNS TABLE("sample_id" "uuid", "all_time_like_count" bigint, "trending_like_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  trending_since timestamptz := pg_catalog.now() - interval '30 days';
BEGIN
  IF p_sample_ids IS NULL
    OR pg_catalog.jsonb_typeof(p_sample_ids) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'p_sample_ids must be a JSON array of at most 100 UUIDs';
  END IF;

  IF pg_catalog.jsonb_array_length(p_sample_ids) > 100 THEN
    RAISE EXCEPTION 'p_sample_ids must contain at most 100 UUIDs';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_array_elements(p_sample_ids) AS input_sample(value)
    WHERE pg_catalog.jsonb_typeof(input_sample.value) IS DISTINCT FROM 'string'
      OR NOT (
        input_sample.value #>> '{}'::text[]
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
  ) THEN
    RAISE EXCEPTION 'each p_sample_ids entry must be a UUID string';
  END IF;

  RETURN QUERY
  WITH requested_sample_ids AS (
    SELECT DISTINCT (input_sample.value #>> '{}'::text[])::uuid AS sample_id
    FROM pg_catalog.jsonb_array_elements(p_sample_ids) AS input_sample(value)
  )
  SELECT
    requested_sample_ids.sample_id,
    count(sample_like.id)::bigint AS all_time_like_count,
    count(sample_like.id) FILTER (
      WHERE sample_like.created_at >= trending_since
    )::bigint AS trending_like_count
  FROM requested_sample_ids
  LEFT JOIN public.sample_likes AS sample_like
    ON sample_like.sample_id = requested_sample_ids.sample_id
  GROUP BY requested_sample_ids.sample_id;
END;
$_$;


ALTER FUNCTION "public"."get_sample_like_stats"("p_sample_ids" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_saved_loop_like_counts"("p_saved_loop_ids" "jsonb") RETURNS TABLE("saved_loop_id" "uuid", "like_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_saved_loop_ids IS NULL
    OR pg_catalog.jsonb_typeof(p_saved_loop_ids) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'p_saved_loop_ids must be a JSON array of at most 100 UUIDs'
      USING ERRCODE = '22023';
  END IF;

  IF pg_catalog.jsonb_array_length(p_saved_loop_ids) > 100 THEN
    RAISE EXCEPTION 'p_saved_loop_ids must contain at most 100 UUIDs'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH requested_saved_loops AS (
    SELECT DISTINCT (input_loop.value #>> '{}'::text[])::uuid AS saved_loop_id
    FROM pg_catalog.jsonb_array_elements(p_saved_loop_ids) AS input_loop(value)
  ), readable_saved_loops AS (
    SELECT
      requested_saved_loops.saved_loop_id,
      EXISTS (
        SELECT 1
        FROM public.saved_loops AS saved_loop
        WHERE saved_loop.id = requested_saved_loops.saved_loop_id
          AND (
            saved_loop.user_id = auth.uid()
            OR (
              saved_loop.is_archived = false
              AND saved_loop.show_in_loops_library = true
              AND saved_loop.share_visibility = 'public'
            )
          )
      ) AS can_read_like_count
    FROM requested_saved_loops
  )
  SELECT
    readable_saved_loops.saved_loop_id,
    CASE
      WHEN readable_saved_loops.can_read_like_count
        THEN count(saved_loop_like.id)::bigint
      ELSE 0::bigint
    END AS like_count
  FROM readable_saved_loops
  LEFT JOIN public.saved_loop_likes AS saved_loop_like
    ON saved_loop_like.saved_loop_id = readable_saved_loops.saved_loop_id
   AND readable_saved_loops.can_read_like_count
  GROUP BY
    readable_saved_loops.saved_loop_id,
    readable_saved_loops.can_read_like_count;
END;
$$;


ALTER FUNCTION "public"."get_saved_loop_like_counts"("p_saved_loop_ids" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sip_contributors"() RETURNS TABLE("contributor_slug" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT DISTINCT slug
  FROM (
    SELECT contributor_slug AS slug
    FROM sip_pipeline_state
    WHERE contributor_slug IS NOT NULL AND contributor_slug <> ''

    UNION

    SELECT source_contributor_slug AS slug
    FROM sip_review_instrument
    WHERE source_contributor_slug IS NOT NULL AND source_contributor_slug <> ''

    UNION

    SELECT source_contributor_slug AS slug
    FROM sip_instrument_meta
    WHERE source_contributor_slug IS NOT NULL AND source_contributor_slug <> ''

    UNION

    SELECT contributor_slug AS slug
    FROM sip_sample_instrument_source
    WHERE contributor_slug IS NOT NULL AND contributor_slug <> ''

    UNION

    SELECT contributor_slug AS slug
    FROM sip_sample_construct
    WHERE contributor_slug IS NOT NULL AND contributor_slug <> ''
  ) combined
  ORDER BY slug;
$$;


ALTER FUNCTION "public"."get_sip_contributors"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sip_instrument_warning_summary"("p_contributor_slug" "text", "p_instrument_names" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("instrument_name" "text", "warning_count" bigint, "anomaly_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  WITH construct_field_presence AS (
    SELECT
      sc.contributor_slug,
      sc.original_sample_id,
      bool_or(nullif(btrim(sc.articulation), '') IS NOT NULL) AS has_articulation,
      bool_or(nullif(btrim(sc.effect), '') IS NOT NULL) AS has_effect,
      bool_or(nullif(btrim(sc.mic_position), '') IS NOT NULL) AS has_mic_position
    FROM public.sip_sample_construct sc
    WHERE sc.contributor_slug = p_contributor_slug
      AND sc.original_sample_id IS NOT NULL
      AND (
        p_instrument_names IS NULL
        OR lower(sc.instrument_name) = ANY(
             SELECT lower(n) FROM unnest(p_instrument_names) AS n
           )
      )
    GROUP BY sc.contributor_slug, sc.original_sample_id
  )
  SELECT
    lower(sc.instrument_name) AS instrument_name,
    count(*) FILTER (
      WHERE sc.confidence IS NOT NULL
        AND sc.confidence ~ '^[+-]?[0-9]+(\.[0-9]+)?$'
        AND sc.confidence::numeric < 0.5
    ) AS warning_count,
    coalesce(sum(
      (CASE WHEN coalesce(cfp.has_articulation, false) AND lower(sa.articulation_cosine_threshold_band) IN ('mismatch','ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN coalesce(cfp.has_effect, false) AND lower(sa.effect_cosine_threshold_band) IN ('mismatch','ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN coalesce(cfp.has_mic_position, false) AND lower(sa.mic_position_cosine_threshold_band) IN ('mismatch','ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN lower(sa.collision_cosine_threshold_band) IN ('mismatch','ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN lower(sa.velocity_cosine_threshold_band) IN ('mismatch','ambiguous') THEN 1 ELSE 0 END)
    ), 0) AS anomaly_count
  FROM public.sip_sample_construct sc
  LEFT JOIN public.sip_sample_analysis sa
    ON sa.original_sample_id = sc.original_sample_id
   AND sa.contributor_slug = sc.contributor_slug
  LEFT JOIN construct_field_presence cfp
    ON cfp.contributor_slug = sc.contributor_slug
   AND cfp.original_sample_id = sc.original_sample_id
  WHERE sc.contributor_slug = p_contributor_slug
    AND (
      p_instrument_names IS NULL
      OR lower(sc.instrument_name) = ANY(
           SELECT lower(n) FROM unnest(p_instrument_names) AS n
         )
    )
  GROUP BY lower(sc.instrument_name)
  ORDER BY lower(sc.instrument_name);
$_$;


ALTER FUNCTION "public"."get_sip_instrument_warning_summary"("p_contributor_slug" "text", "p_instrument_names" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sip_staging_instrument_sample_page"("p_contributor_slug" "text", "p_staging_instrument_id" "uuid", "p_sort_by" "text" DEFAULT 'midi_note'::"text", "p_sort_dir" "text" DEFAULT 'asc'::"text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_contributor_slug text := regexp_replace(
    regexp_replace(lower(btrim(coalesce(p_contributor_slug, ''))), '[_\s]+', '-', 'g'),
    '-+',
    '-',
    'g'
  );
  v_sort_by text := lower(btrim(coalesce(p_sort_by, 'midi_note')));
  v_sort_dir text := CASE WHEN lower(btrim(coalesce(p_sort_dir, 'asc'))) = 'desc' THEN 'desc' ELSE 'asc' END;
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 500);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_staging public.sip_review_instrument%ROWTYPE;
  v_source_name text := NULL;
  v_source_original_sample_ids uuid[] := '{}'::uuid[];
  v_source_tmp_name text := NULL;
  v_source_tmp_original_sample_ids uuid[] := '{}'::uuid[];
  v_source_tmp_construct_ids integer[] := '{}'::integer[];
  v_instrument_name text := NULL;
  v_source_tmp_id integer := NULL;
  v_scope_row_count integer := 0;
  v_scope_sample_match_count integer := 0;
  v_scope_path_match_count integer := 0;
  v_staging_match_count integer := 0;
  v_source_sample_match_count integer := 0;
  v_source_construct_match_count integer := 0;
  v_instrument_name_match_count integer := 0;
  v_fetch_path text := 'none';
  v_total_count integer := 0;
  v_rows jsonb := '[]'::jsonb;
  v_context_sample_ids uuid[] := '{}'::uuid[];
BEGIN
  IF v_sort_by NOT IN ('file_path', 'instrument_name', 'confidence', 'collection', 'midi_note', 'velocity', 'name', 'id') THEN
    v_sort_by := 'midi_note';
  END IF;

  SELECT sri.*
  INTO v_staging
  FROM public.sip_review_instrument sri
  WHERE sri.id = p_staging_instrument_id
    AND sri.source_contributor_slug = v_contributor_slug
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'instrumentName', NULL,
      'rows', '[]'::jsonb,
      'contextSampleIds', '[]'::jsonb,
      'totalCount', 0,
      'hasMore', false,
      'fetchPath', 'none',
      'diagnostics', jsonb_build_object('reason', 'staging_not_found')
    );
  END IF;

  IF v_staging.source_sip_instrument_id IS NOT NULL THEN
    SELECT si.name, coalesce(si.original_sample_ids, '{}'::uuid[])
    INTO v_source_name, v_source_original_sample_ids
    FROM public.sip_instrument si
    WHERE si.id = v_staging.source_sip_instrument_id
    LIMIT 1;

    SELECT meta.source_sip_sample_instrument_id
    INTO v_source_tmp_id
    FROM public.sip_instrument_meta meta
    WHERE meta.source_contributor_slug = v_contributor_slug
      AND meta.sip_instrument_id = v_staging.source_sip_instrument_id
    LIMIT 1;
  END IF;

  IF v_source_tmp_id IS NOT NULL THEN
    SELECT source.name,
      coalesce(source.original_sample_ids, '{}'::uuid[]),
      coalesce(source.sample_construct_ids, '{}'::integer[])
    INTO v_source_tmp_name, v_source_tmp_original_sample_ids, v_source_tmp_construct_ids
    FROM public.sip_sample_instrument_source source
    WHERE source.id = v_source_tmp_id
      AND source.contributor_slug = v_contributor_slug
    LIMIT 1;
  END IF;

  v_instrument_name := coalesce(
    nullif(btrim(v_source_tmp_name), ''),
    nullif(btrim(v_source_name), ''),
    nullif(btrim(v_staging.name), '')
  );

  SELECT count(*)::integer
  INTO v_scope_row_count
  FROM public.sip_review_instrument_sample_scope scope
  WHERE scope.sip_review_instrument_id = p_staging_instrument_id;

  IF v_scope_row_count > 0 THEN
    SELECT count(*)::integer
    INTO v_scope_sample_match_count
    FROM public.sip_sample_construct sc
    WHERE sc.contributor_slug = v_contributor_slug
      AND EXISTS (
        SELECT 1
        FROM public.sip_review_instrument_sample_scope scope
        WHERE scope.sip_review_instrument_id = p_staging_instrument_id
          AND scope.original_sample_id IS NOT NULL
          AND scope.original_sample_id = sc.original_sample_id
      );

    IF v_scope_sample_match_count > 0 THEN
      v_fetch_path := 'scope_sample_ids';
      v_total_count := v_scope_sample_match_count;
    ELSE
      SELECT count(*)::integer
      INTO v_scope_path_match_count
      FROM public.sip_sample_construct sc
      WHERE sc.contributor_slug = v_contributor_slug
        AND EXISTS (
          SELECT 1
          FROM public.sip_review_instrument_sample_scope scope
          WHERE scope.sip_review_instrument_id = p_staging_instrument_id
            AND scope.file_path = sc.file_path
        );

      IF v_scope_path_match_count > 0 THEN
        v_fetch_path := 'scope_paths';
        v_total_count := v_scope_path_match_count;
      ELSE
        v_fetch_path := 'scope_empty';
        v_total_count := 0;
      END IF;
    END IF;
  END IF;

  IF v_fetch_path = 'none' AND cardinality(coalesce(v_staging.original_sample_ids, '{}'::uuid[])) > 0 THEN
    SELECT count(*)::integer
    INTO v_staging_match_count
    FROM public.sip_sample_construct sc
    WHERE sc.contributor_slug = v_contributor_slug
      AND sc.original_sample_id = ANY(coalesce(v_staging.original_sample_ids, '{}'::uuid[]));

    IF v_staging_match_count > 0 THEN
      v_fetch_path := 'sample_ids';
      v_total_count := v_staging_match_count;
    END IF;
  END IF;

  IF v_fetch_path = 'none' THEN
    v_source_original_sample_ids := ARRAY(
      SELECT DISTINCT sid
      FROM unnest(
        coalesce(v_source_tmp_original_sample_ids, '{}'::uuid[]) ||
        coalesce(v_source_original_sample_ids, '{}'::uuid[])
      ) AS source_ids(sid)
      WHERE sid IS NOT NULL
    );

    IF cardinality(v_source_original_sample_ids) > 0 THEN
      SELECT count(*)::integer
      INTO v_source_sample_match_count
      FROM public.sip_sample_construct sc
      WHERE sc.contributor_slug = v_contributor_slug
        AND sc.original_sample_id = ANY(v_source_original_sample_ids);

      IF v_source_sample_match_count > 0 THEN
        v_fetch_path := 'source_sample_ids';
        v_total_count := v_source_sample_match_count;
      END IF;
    END IF;
  END IF;

  IF v_fetch_path = 'none' AND cardinality(coalesce(v_source_tmp_construct_ids, '{}'::integer[])) > 0 THEN
    SELECT count(*)::integer
    INTO v_source_construct_match_count
    FROM public.sip_sample_construct sc
    WHERE sc.contributor_slug = v_contributor_slug
      AND sc.id = ANY(v_source_tmp_construct_ids);

    IF v_source_construct_match_count > 0 THEN
      v_fetch_path := 'construct_ids';
      v_total_count := v_source_construct_match_count;
    END IF;
  END IF;

  IF v_fetch_path = 'none' AND v_instrument_name IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_instrument_name_match_count
    FROM public.sip_sample_construct sc
    WHERE sc.contributor_slug = v_contributor_slug
      AND sc.instrument_name = v_instrument_name;

    IF v_instrument_name_match_count > 0 THEN
      v_fetch_path := 'instrument_name';
      v_total_count := v_instrument_name_match_count;
    END IF;
  END IF;

  IF v_total_count > 0 THEN
    WITH matched AS (
      SELECT sc.*
      FROM public.sip_sample_construct sc
      WHERE sc.contributor_slug = v_contributor_slug
        AND v_fetch_path = 'scope_sample_ids'
        AND EXISTS (
          SELECT 1
          FROM public.sip_review_instrument_sample_scope scope
          WHERE scope.sip_review_instrument_id = p_staging_instrument_id
            AND scope.original_sample_id IS NOT NULL
            AND scope.original_sample_id = sc.original_sample_id
        )
      UNION ALL
      SELECT sc.*
      FROM public.sip_sample_construct sc
      WHERE sc.contributor_slug = v_contributor_slug
        AND v_fetch_path = 'scope_paths'
        AND EXISTS (
          SELECT 1
          FROM public.sip_review_instrument_sample_scope scope
          WHERE scope.sip_review_instrument_id = p_staging_instrument_id
            AND scope.file_path = sc.file_path
        )
      UNION ALL
      SELECT sc.*
      FROM public.sip_sample_construct sc
      WHERE sc.contributor_slug = v_contributor_slug
        AND v_fetch_path = 'sample_ids'
        AND sc.original_sample_id = ANY(coalesce(v_staging.original_sample_ids, '{}'::uuid[]))
      UNION ALL
      SELECT sc.*
      FROM public.sip_sample_construct sc
      WHERE sc.contributor_slug = v_contributor_slug
        AND v_fetch_path = 'source_sample_ids'
        AND sc.original_sample_id = ANY(v_source_original_sample_ids)
      UNION ALL
      SELECT sc.*
      FROM public.sip_sample_construct sc
      WHERE sc.contributor_slug = v_contributor_slug
        AND v_fetch_path = 'construct_ids'
        AND sc.id = ANY(v_source_tmp_construct_ids)
      UNION ALL
      SELECT sc.*
      FROM public.sip_sample_construct sc
      WHERE sc.contributor_slug = v_contributor_slug
        AND v_fetch_path = 'instrument_name'
        AND sc.instrument_name = v_instrument_name
    ),
    base AS (
      SELECT
        matched.*,
        CASE WHEN matched.midi_note ~ '^-?[0-9]+$' THEN matched.midi_note::integer ELSE NULL END AS midi_sort,
        CASE WHEN matched.confidence ~ '^-?[0-9]+(\.[0-9]+)?$' THEN matched.confidence::double precision ELSE NULL END AS confidence_sort,
        CASE WHEN matched.velocity ~ '^-?[0-9]+$' THEN matched.velocity::integer ELSE NULL END AS velocity_sort
      FROM matched
    ),
    ordered AS (
      SELECT
        base.*,
        row_number() OVER (
          ORDER BY
            CASE WHEN v_sort_by = 'midi_note' AND v_sort_dir = 'asc' THEN midi_sort END ASC NULLS LAST,
            CASE WHEN v_sort_by = 'midi_note' AND v_sort_dir = 'desc' THEN midi_sort END DESC NULLS LAST,
            CASE WHEN v_sort_by = 'confidence' AND v_sort_dir = 'asc' THEN confidence_sort END ASC NULLS LAST,
            CASE WHEN v_sort_by = 'confidence' AND v_sort_dir = 'desc' THEN confidence_sort END DESC NULLS LAST,
            CASE WHEN v_sort_by = 'velocity' AND v_sort_dir = 'asc' THEN velocity_sort END ASC NULLS LAST,
            CASE WHEN v_sort_by = 'velocity' AND v_sort_dir = 'desc' THEN velocity_sort END DESC NULLS LAST,
            CASE WHEN v_sort_by = 'file_path' AND v_sort_dir = 'asc' THEN file_path END ASC NULLS LAST,
            CASE WHEN v_sort_by = 'file_path' AND v_sort_dir = 'desc' THEN file_path END DESC NULLS LAST,
            CASE WHEN v_sort_by = 'instrument_name' AND v_sort_dir = 'asc' THEN instrument_name END ASC NULLS LAST,
            CASE WHEN v_sort_by = 'instrument_name' AND v_sort_dir = 'desc' THEN instrument_name END DESC NULLS LAST,
            CASE WHEN v_sort_by = 'collection' AND v_sort_dir = 'asc' THEN collection END ASC NULLS LAST,
            CASE WHEN v_sort_by = 'collection' AND v_sort_dir = 'desc' THEN collection END DESC NULLS LAST,
            CASE WHEN v_sort_by = 'name' AND v_sort_dir = 'asc' THEN name END ASC NULLS LAST,
            CASE WHEN v_sort_by = 'name' AND v_sort_dir = 'desc' THEN name END DESC NULLS LAST,
            CASE WHEN v_sort_by = 'id' AND v_sort_dir = 'asc' THEN id END ASC,
            CASE WHEN v_sort_by = 'id' AND v_sort_dir = 'desc' THEN id END DESC,
            midi_sort ASC NULLS LAST,
            file_path ASC,
            id ASC
        ) AS row_order
      FROM base
    ),
    paged AS (
      SELECT *
      FROM ordered
      ORDER BY row_order
      LIMIT v_limit
      OFFSET v_offset
    )
    SELECT
      (
        SELECT coalesce(
          jsonb_agg(
            to_jsonb(paged) - 'midi_sort' - 'confidence_sort' - 'velocity_sort' - 'row_order'
            ORDER BY row_order
          ),
          '[]'::jsonb
        )
        FROM paged
      ),
      (
        SELECT coalesce(
          array_agg(original_sample_id ORDER BY row_order),
          '{}'::uuid[]
        )
        FROM ordered
      )
    INTO v_rows, v_context_sample_ids;
  END IF;

  RETURN jsonb_build_object(
    'instrumentName', v_instrument_name,
    'rows', coalesce(v_rows, '[]'::jsonb),
    'contextSampleIds', to_jsonb(coalesce(v_context_sample_ids, '{}'::uuid[])),
    'totalCount', coalesce(v_total_count, 0),
    'hasMore', (v_offset + jsonb_array_length(coalesce(v_rows, '[]'::jsonb))) < coalesce(v_total_count, 0),
    'fetchPath', v_fetch_path,
    'diagnostics', jsonb_build_object(
      'scopeRowCount', v_scope_row_count,
      'scopeSampleMatchCount', v_scope_sample_match_count,
      'scopePathMatchCount', v_scope_path_match_count,
      'stagingSampleMatchCount', v_staging_match_count,
      'sourceSampleMatchCount', v_source_sample_match_count,
      'sourceConstructMatchCount', v_source_construct_match_count,
      'instrumentNameMatchCount', v_instrument_name_match_count
    )
  );
END;
$_$;


ALTER FUNCTION "public"."get_sip_staging_instrument_sample_page"("p_contributor_slug" "text", "p_staging_instrument_id" "uuid", "p_sort_by" "text", "p_sort_dir" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sip_warning_contributor_category"("p_contributor_slug" "text", "p_category" "text", "p_status_filter" "text" DEFAULT 'active'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_contributor_slug text := lower(trim(coalesce(p_contributor_slug, '')));
    v_category text := lower(trim(coalesce(p_category, '')));
    v_status_filter text := lower(trim(coalesce(p_status_filter, 'active')));
    v_limit integer := greatest(1, least(coalesce(p_limit, 50), 250));
    v_offset integer := greatest(0, coalesce(p_offset, 0));
    v_payload jsonb;
BEGIN
    IF v_status_filter NOT IN ('active', 'open', 'confirmed', 'accepted', 'addressed', 'closed', 'all') THEN
        v_status_filter := 'active';
    END IF;

    IF v_category NOT IN ('midi', 'velocity', 'articulation', 'effects', 'mic_position', 'confidence', 'taxonomy', 'playback_type') THEN
        RETURN jsonb_build_object(
            'category', v_category,
            'total', 0,
            'bySeverity', jsonb_build_object('high', 0, 'med', 0, 'low', 0),
            'types', '[]'::jsonb,
            'instrumentIds', '[]'::jsonb,
            'instruments', '[]'::jsonb,
            'totalCount', 0,
            'hasMore', false
        );
    END IF;

    WITH active_instruments AS (
        SELECT
            ri.id,
            ri.name,
            ri.source_sip_instrument_id,
            ri.instrument_family,
            ri.instrument_type
        FROM public.sip_review_instrument ri
        WHERE ri.source_contributor_slug = v_contributor_slug
          AND coalesce(ri.is_retired, false) = false
          AND NOT EXISTS (
              SELECT 1
              FROM public.sip_review_promotion_map pm
              WHERE pm.sip_review_instrument_id = ri.id
          )
    ),
    visible_all AS (
        SELECT
            wi.sip_review_instrument_id,
            wi.type,
            coalesce(wi.review_status, 'open') AS review_status
        FROM public.sip_review_warning_index_with_review_state wi
        JOIN active_instruments ai
          ON ai.id = wi.sip_review_instrument_id
        WHERE wi.type NOT IN (
            'missing_playback_type',
            'unknown_mic_position',
            'unkown_mic_position',
            'mixed_known_unknown_mic_positions',
            'non_canonical_articulation'
        )
          AND CASE v_status_filter
            WHEN 'active' THEN coalesce(wi.review_status, 'open') IN ('open', 'confirmed')
            WHEN 'closed' THEN coalesce(wi.review_status, 'open') = 'accepted'
            WHEN 'all' THEN true
            ELSE coalesce(wi.review_status, 'open') = v_status_filter
          END
    ),
    visible_category AS (
        SELECT
            wi.sip_review_instrument_id,
            wi.type,
            wi.severity,
            coalesce(wi.review_status, 'open') AS review_status
        FROM public.sip_review_warning_index_with_review_state wi
        JOIN active_instruments ai
          ON ai.id = wi.sip_review_instrument_id
        WHERE wi.category = v_category
          AND wi.type NOT IN (
            'missing_playback_type',
            'unknown_mic_position',
            'unkown_mic_position',
            'mixed_known_unknown_mic_positions',
            'non_canonical_articulation'
          )
          AND CASE v_status_filter
            WHEN 'active' THEN coalesce(wi.review_status, 'open') IN ('open', 'confirmed')
            WHEN 'closed' THEN coalesce(wi.review_status, 'open') = 'accepted'
            WHEN 'all' THEN true
            ELSE coalesce(wi.review_status, 'open') = v_status_filter
          END
    ),
    instrument_totals AS (
        SELECT
            sip_review_instrument_id,
            count(*)::integer AS total,
            count(*) FILTER (
                WHERE type IN ('articulation_cosine_band', 'effect_cosine_band', 'mic_position_cosine_band')
            )::integer AS anomalies
        FROM visible_all
        GROUP BY sip_review_instrument_id
    ),
    category_totals AS (
        SELECT
            count(*)::integer AS total,
            count(*) FILTER (WHERE severity = 'high')::integer AS high,
            count(*) FILTER (WHERE severity = 'med')::integer AS med,
            count(*) FILTER (WHERE severity = 'low')::integer AS low
        FROM visible_category
    ),
    grouped AS (
        SELECT
            ai.id AS staging_instrument_id,
            ai.name AS staging_instrument_name,
            si.name AS source_instrument_name,
            ai.instrument_family,
            ai.instrument_type,
            count(*)::integer AS category_warning_count,
            count(*) FILTER (
                WHERE vc.type IN ('articulation_cosine_band', 'effect_cosine_band', 'mic_position_cosine_band')
            )::integer AS category_anomaly_count,
            coalesce(it.total, 0)::integer AS generated_warning_count_total,
            coalesce(it.anomalies, 0)::integer AS generated_anomaly_count_total
        FROM visible_category vc
        JOIN active_instruments ai
          ON ai.id = vc.sip_review_instrument_id
        LEFT JOIN public.sip_instrument si
          ON si.id = ai.source_sip_instrument_id
        LEFT JOIN instrument_totals it
          ON it.sip_review_instrument_id = ai.id
        GROUP BY
            ai.id,
            ai.name,
            si.name,
            ai.instrument_family,
            ai.instrument_type,
            it.total,
            it.anomalies
    ),
    numbered AS (
        SELECT
            grouped.*,
            row_number() OVER (
                ORDER BY category_warning_count DESC, staging_instrument_name ASC
            ) AS row_number,
            count(*) OVER ()::integer AS total_count
        FROM grouped
    ),
    paged AS (
        SELECT *
        FROM numbered
        WHERE row_number > v_offset
          AND row_number <= v_offset + v_limit
        ORDER BY row_number
    ),
    category_instrument_ids AS (
        SELECT coalesce(
            jsonb_agg(staging_instrument_id::text ORDER BY category_warning_count DESC, staging_instrument_name ASC),
            '[]'::jsonb
        ) AS instrument_ids
        FROM grouped
    ),
    type_rows AS (
        SELECT
            type,
            count(*)::integer AS total,
            count(*) FILTER (WHERE severity = 'high')::integer AS high,
            count(*) FILTER (WHERE severity = 'med')::integer AS med,
            count(*) FILTER (WHERE severity = 'low')::integer AS low,
            coalesce(
                jsonb_agg(DISTINCT sip_review_instrument_id::text),
                '[]'::jsonb
            ) AS instrument_ids
        FROM visible_category
        GROUP BY type
    )
    SELECT jsonb_build_object(
        'category', v_category,
        'total', coalesce(ct.total, 0),
        'bySeverity', jsonb_build_object(
            'high', coalesce(ct.high, 0),
            'med', coalesce(ct.med, 0),
            'low', coalesce(ct.low, 0)
        ),
        'types', coalesce(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'type', tr.type,
                        'total', tr.total,
                        'bySeverity', jsonb_build_object(
                            'high', tr.high,
                            'med', tr.med,
                            'low', tr.low
                        ),
                        'instrumentIds', tr.instrument_ids
                    )
                    ORDER BY tr.total DESC, tr.type ASC
                )
                FROM type_rows tr
            ),
            '[]'::jsonb
        ),
        'instrumentIds', coalesce((SELECT instrument_ids FROM category_instrument_ids), '[]'::jsonb),
        'instruments', coalesce(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'staging_instrument_id', p.staging_instrument_id,
                        'staging_instrument_name', p.staging_instrument_name,
                        'source_instrument_name', p.source_instrument_name,
                        'instrument_family', p.instrument_family,
                        'instrument_type', p.instrument_type,
                        'category_warning_count', p.category_warning_count,
                        'category_anomaly_count', p.category_anomaly_count,
                        'generated_warning_count_total', p.generated_warning_count_total,
                        'generated_anomaly_count_total', p.generated_anomaly_count_total,
                        'table_warning_count_total', p.generated_warning_count_total,
                        'table_anomaly_count_total', p.generated_anomaly_count_total
                    )
                    ORDER BY p.row_number
                )
                FROM paged p
            ),
            '[]'::jsonb
        ),
        'totalCount', coalesce((SELECT max(total_count) FROM numbered), 0),
        'hasMore', v_offset + coalesce((SELECT count(*) FROM paged), 0) < coalesce((SELECT max(total_count) FROM numbered), 0)
    )
    INTO v_payload
    FROM category_totals ct;

    RETURN coalesce(v_payload, jsonb_build_object(
        'category', v_category,
        'total', 0,
        'bySeverity', jsonb_build_object('high', 0, 'med', 0, 'low', 0),
        'types', '[]'::jsonb,
        'instrumentIds', '[]'::jsonb,
        'instruments', '[]'::jsonb,
        'totalCount', 0,
        'hasMore', false
    ));
END;
$$;


ALTER FUNCTION "public"."get_sip_warning_contributor_category"("p_contributor_slug" "text", "p_category" "text", "p_status_filter" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sip_warning_contributor_summary"("p_contributor_slug" "text", "p_status_filter" "text" DEFAULT 'active'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_contributor_slug text := lower(trim(coalesce(p_contributor_slug, '')));
    v_status_filter text := lower(trim(coalesce(p_status_filter, 'active')));
    v_payload jsonb;
BEGIN
    IF v_status_filter NOT IN ('active', 'open', 'confirmed', 'accepted', 'addressed', 'closed', 'all') THEN
        v_status_filter := 'active';
    END IF;

    WITH active_instruments AS (
        SELECT ri.id
        FROM public.sip_review_instrument ri
        WHERE ri.source_contributor_slug = v_contributor_slug
          AND coalesce(ri.is_retired, false) = false
          AND NOT EXISTS (
              SELECT 1
              FROM public.sip_review_promotion_map pm
              WHERE pm.sip_review_instrument_id = ri.id
          )
    ),
    base_warnings AS (
        SELECT
            wi.sip_review_instrument_id,
            wi.category,
            wi.type,
            wi.severity,
            coalesce(wi.review_status, 'open') AS review_status
        FROM public.sip_review_warning_index_with_review_state wi
        JOIN active_instruments ai
          ON ai.id = wi.sip_review_instrument_id
        WHERE wi.type NOT IN (
            'missing_playback_type',
            'unknown_mic_position',
            'unkown_mic_position',
            'mixed_known_unknown_mic_positions',
            'non_canonical_articulation'
        )
    ),
    visible_warnings AS (
        SELECT *
        FROM base_warnings
        WHERE CASE v_status_filter
            WHEN 'active' THEN review_status IN ('open', 'confirmed')
            WHEN 'closed' THEN review_status = 'accepted'
            WHEN 'all' THEN true
            ELSE review_status = v_status_filter
        END
    ),
    totals AS (
        SELECT
            count(*) FILTER (WHERE severity = 'high')::integer AS high,
            count(*) FILTER (WHERE severity = 'med')::integer AS med,
            count(*) FILTER (WHERE severity = 'low')::integer AS low,
            count(*)::integer AS total
        FROM visible_warnings
    ),
    status_counts AS (
        SELECT
            count(*) FILTER (WHERE review_status = 'open')::integer AS open,
            count(*) FILTER (WHERE review_status = 'confirmed')::integer AS confirmed,
            count(*) FILTER (WHERE review_status = 'accepted')::integer AS accepted,
            count(*) FILTER (WHERE review_status = 'addressed')::integer AS addressed,
            count(*) FILTER (WHERE review_status IN ('open', 'confirmed'))::integer AS active,
            count(*) FILTER (WHERE review_status = 'accepted')::integer AS closed,
            count(*)::integer AS all_count
        FROM base_warnings
    ),
    category_rows AS (
        SELECT
            category,
            count(*)::integer AS total,
            count(*) FILTER (WHERE severity = 'high')::integer AS high,
            count(*) FILTER (WHERE severity = 'med')::integer AS med,
            count(*) FILTER (WHERE severity = 'low')::integer AS low
        FROM visible_warnings
        GROUP BY category
    ),
    state_rows AS (
        SELECT
            ai.id,
            ws.sip_review_instrument_id,
            ws.is_stale,
            ws.failure_count,
            ws.last_attempted_at,
            ws.refresh_lease_token,
            ws.diagnostics_json
        FROM active_instruments ai
        LEFT JOIN public.sip_review_warning_index_state ws
          ON ws.sip_review_instrument_id = ai.id
    ),
    coverage AS (
        SELECT
            count(*)::integer AS total,
            count(*) FILTER (WHERE coalesce(is_stale, true) = false)::integer AS fresh,
            (count(*) - count(*) FILTER (WHERE coalesce(is_stale, true) = false))::integer AS stale,
            count(*) FILTER (
                WHERE coalesce(is_stale, true) = true
                  AND refresh_lease_token IS NOT NULL
                  AND last_attempted_at > now() - interval '5 minutes'
            )::integer AS in_flight,
            count(*) FILTER (
                WHERE coalesce(is_stale, true) = true
                  AND NOT (
                      refresh_lease_token IS NOT NULL
                      AND last_attempted_at > now() - interval '5 minutes'
                  )
                  AND coalesce(failure_count, 0) > 0
                  AND last_attempted_at IS NOT NULL
                  AND now() - last_attempted_at < interval '5 minutes' * power(2, least(coalesce(failure_count, 0), 5))
            )::integer AS in_cooldown,
            count(*) FILTER (
                WHERE sip_review_instrument_id IS NULL
                   OR (
                      coalesce(is_stale, true) = true
                      AND NOT (
                          refresh_lease_token IS NOT NULL
                          AND last_attempted_at > now() - interval '5 minutes'
                      )
                      AND (
                          coalesce(failure_count, 0) = 0
                          OR last_attempted_at IS NULL
                          OR now() - last_attempted_at >= interval '5 minutes' * power(2, least(coalesce(failure_count, 0), 5))
                      )
                   )
            )::integer AS remaining_claimable
        FROM state_rows
    ),
    missing AS (
        SELECT coalesce(
            jsonb_object_agg(id::text, diagnostics_json->'missingRequestedSampleIds'),
            '{}'::jsonb
        ) AS missing_by_instrument
        FROM state_rows
        WHERE jsonb_typeof(diagnostics_json->'missingRequestedSampleIds') = 'array'
          AND jsonb_array_length(diagnostics_json->'missingRequestedSampleIds') > 0
    )
    SELECT jsonb_build_object(
        'contributor', v_contributor_slug,
        'totals', jsonb_build_object(
            'high', coalesce(t.high, 0),
            'med', coalesce(t.med, 0),
            'low', coalesce(t.low, 0),
            'total', coalesce(t.total, 0)
        ),
        'reviewStatusCounts', jsonb_build_object(
            'open', coalesce(sc.open, 0),
            'confirmed', coalesce(sc.confirmed, 0),
            'accepted', coalesce(sc.accepted, 0),
            'addressed', coalesce(sc.addressed, 0),
            'active', coalesce(sc.active, 0),
            'closed', coalesce(sc.closed, 0),
            'all', coalesce(sc.all_count, 0)
        ),
        'categories', coalesce(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'category', cr.category,
                        'total', cr.total,
                        'bySeverity', jsonb_build_object(
                            'high', cr.high,
                            'med', cr.med,
                            'low', cr.low
                        ),
                        'instruments', '[]'::jsonb
                    )
                    ORDER BY cr.total DESC, cr.category ASC
                )
                FROM category_rows cr
                WHERE cr.total > 0
            ),
            '[]'::jsonb
        ),
        'coverage', jsonb_build_object(
            'total', coalesce(c.total, 0),
            'fresh', coalesce(c.fresh, 0),
            'stale', coalesce(c.stale, 0),
            'inCooldown', coalesce(c.in_cooldown, 0),
            'inFlight', coalesce(c.in_flight, 0),
            'remainingClaimable', coalesce(c.remaining_claimable, 0)
        ),
        'diagnostics', jsonb_build_object(
            'missingRequestedSampleIdsByInstrument', coalesce(m.missing_by_instrument, '{}'::jsonb)
        )
    )
    INTO v_payload
    FROM totals t
    CROSS JOIN status_counts sc
    CROSS JOIN coverage c
    CROSS JOIN missing m;

    RETURN coalesce(v_payload, jsonb_build_object(
        'contributor', v_contributor_slug,
        'totals', jsonb_build_object('high', 0, 'med', 0, 'low', 0, 'total', 0),
        'reviewStatusCounts', jsonb_build_object(
            'open', 0, 'confirmed', 0, 'accepted', 0, 'addressed', 0,
            'active', 0, 'closed', 0, 'all', 0
        ),
        'categories', '[]'::jsonb,
        'coverage', jsonb_build_object(
            'total', 0, 'fresh', 0, 'stale', 0, 'inCooldown', 0,
            'inFlight', 0, 'remainingClaimable', 0
        ),
        'diagnostics', jsonb_build_object(
            'missingRequestedSampleIdsByInstrument', '{}'::jsonb
        )
    ));
END;
$$;


ALTER FUNCTION "public"."get_sip_warning_contributor_summary"("p_contributor_slug" "text", "p_status_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_top_tags"() RETURNS TABLE("name" "text", "tag_id" "uuid", "tag_count" bigint)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
    SELECT
      bt.name,
      bt.id AS tag_id,
      COUNT(bpt.tag_id) AS tag_count
    FROM
      blog_tags bt
    LEFT JOIN
      blog_post_tags bpt ON bt.id = bpt.tag_id
    GROUP BY
      bt.name, bt.id
    ORDER BY
      tag_count DESC
    LIMIT
      8;
END;
$$;


ALTER FUNCTION "public"."get_top_tags"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_saved_loop_direct_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  IF current_user = 'service_role'
    OR pg_catalog.current_setting(
      'app.saved_loop_discoverability_write',
      true
    ) = 'on'
    OR pg_catalog.current_setting(
      'app.saved_loop_rename_write',
      true
    ) = 'on' THEN
    RETURN NEW;
  END IF;

  IF (pg_catalog.to_jsonb(NEW) - ARRAY['is_archived', 'updated_at'])
      IS DISTINCT FROM
     (pg_catalog.to_jsonb(OLD) - ARRAY['is_archived', 'updated_at']) THEN
    RAISE EXCEPTION
      'Saved loops can only be archived directly; use a saved-loop RPC to rename or change discoverability'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_saved_loop_direct_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_sip_publish_state_transition_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_requires_publication boolean;
  v_candidate jsonb;
  v_manifest public.instrument_runtime_sample_manifests%ROWTYPE;
  v_readiness public.instrument_v2_runtime_readiness%ROWTYPE;
BEGIN
  v_requires_publication := CASE
    WHEN TG_OP = 'INSERT' THEN NEW.published
    ELSE NEW.published AND NOT OLD.published
  END;

  IF NOT v_requires_publication THEN
    RETURN NEW;
  END IF;

  IF COALESCE(
    (
      SELECT enforcement_enabled
      FROM public.sip_fleet_coordinator_settings
      WHERE singleton
    ),
    false
  )
  AND COALESCE(
    current_setting('app.sip_publish_coordinator_authorized', true),
    ''
  ) <> 'on' THEN
    RAISE EXCEPTION 'sip_publish_coordinator_required'
      USING ERRCODE = '42501';
  END IF;

  IF COALESCE(
    current_setting('app.sip_deterministic_publication_authorized', true),
    ''
  ) <> 'on' THEN
    RAISE EXCEPTION 'deterministic_runtime_required'
      USING ERRCODE = '55000';
  END IF;

  -- INSERT ... published=true can never have a persisted manifest because the
  -- manifest owns a foreign key to this row. It is therefore rejected here.
  SELECT * INTO v_manifest
  FROM public.instrument_runtime_sample_manifests manifest
  WHERE manifest.instrument_v2_id = NEW.id;

  SELECT * INTO v_readiness
  FROM public.instrument_v2_runtime_readiness readiness
  WHERE readiness.instrument_v2_id = NEW.id;

  v_candidate := public.build_instrument_runtime_sample_manifest_v1(NEW.id);

  IF v_manifest.instrument_v2_id IS NULL
    OR v_readiness.instrument_v2_id IS NULL
    OR v_manifest.schema_version <> 1
    OR NOT v_manifest.is_complete
    OR jsonb_array_length(v_manifest.blocking_reasons) <> 0
    OR NOT v_readiness.address_ready
    OR NOT v_readiness.behavior_ready
    OR v_readiness.fallback_state <> 'runtime_manifest'
    OR jsonb_array_length(v_readiness.blockers) <> 0
    OR v_manifest.manifest_sha256
      IS DISTINCT FROM v_readiness.manifest_sha256
    OR v_manifest.manifest_sha256
      IS DISTINCT FROM v_candidate->>'manifestSha256'
    OR v_manifest.variant_count
      IS DISTINCT FROM (v_candidate->>'variantCount')::integer
    OR v_manifest.variants IS DISTINCT FROM v_candidate->'variants'
    OR v_manifest.blocking_reasons
      IS DISTINCT FROM v_candidate->'blockingReasons'
    OR COALESCE((v_candidate->>'isComplete')::boolean, false) IS NOT TRUE
  THEN
    RAISE EXCEPTION 'deterministic_runtime_required'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.instrument_v2_deterministic_publication_admissions (
    instrument_v2_id,
    manifest_sha256,
    admitted_at
  ) VALUES (
    NEW.id,
    v_candidate->>'manifestSha256',
    now()
  )
  ON CONFLICT (instrument_v2_id) DO UPDATE SET
    manifest_sha256 = EXCLUDED.manifest_sha256,
    admitted_at = EXCLUDED.admitted_at;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_sip_publish_state_transition_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_sip_publish_state_transition_v1"() IS 'Rejects every new Instrument V2 publication unless persisted complete runtime evidence agrees with a fresh candidate. Historical true rows are not silently unpublished.';



CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.email IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.profiles (id, email)
  VALUES (NEW.id, NEW.email)
  ON CONFLICT (id) DO UPDATE
    SET email = EXCLUDED.email
  WHERE public.profiles.email IS DISTINCT FROM EXCLUDED.email;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."heartbeat_market_pattern_embedding_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_lease_seconds" integer DEFAULT 300) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_lease_seconds NOT BETWEEN 15 AND 3600 THEN
    RAISE EXCEPTION 'p_lease_seconds must be between 15 and 3600'
      USING ERRCODE = '22023';
  END IF;
  UPDATE public.market_pattern_embedding_jobs
  SET
    lease_expires_at = now() + make_interval(secs => p_lease_seconds),
    last_heartbeat_at = now()
  WHERE id = p_job_id
    AND status = 'running'
    AND lease_token = p_lease_token
    AND lease_expires_at > now();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Stale or expired lease token for job %', p_job_id
      USING ERRCODE = '55000';
  END IF;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."heartbeat_market_pattern_embedding_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."heartbeat_sip_fleet_executor_lease"("p_executor_id" "text", "p_lease_token" "uuid", "p_lease_seconds" integer DEFAULT 300) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_lease_seconds < 30 OR p_lease_seconds > 3600 THEN RAISE EXCEPTION 'invalid_lease_seconds'; END IF;
  UPDATE public.sip_fleet_executor_leases SET heartbeat_at=now(),
    lease_expires_at=now()+make_interval(secs=>p_lease_seconds)
  WHERE executor_id=p_executor_id AND lease_token=p_lease_token AND lease_expires_at>now();
  RETURN FOUND;
END $$;


