    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_lease_seconds < 30 OR p_lease_seconds > 86400 THEN RAISE EXCEPTION 'invalid_lease_seconds'; END IF;
  UPDATE public.sip_fleet_provider_leases SET heartbeat_at=now(),
    lease_expires_at=now()+make_interval(secs=>p_lease_seconds)
  WHERE provider_slug=p_provider_slug AND lease_token=p_lease_token AND lease_expires_at>now();
  RETURN FOUND;
END $$;


