CREATE OR REPLACE FUNCTION "public"."heartbeat_sip_fleet_run_item"("p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_lease_seconds" integer DEFAULT 900) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_lease_seconds<30 OR p_lease_seconds>3600 THEN RAISE EXCEPTION 'invalid_lease_seconds'; END IF;
  UPDATE public.sip_fleet_run_items SET heartbeat_at=now(),lease_expires_at=now()+make_interval(secs=>p_lease_seconds)
  WHERE id=p_item_id AND status='running' AND executor_id=p_executor_id
    AND lease_token=p_lease_token AND lease_expires_at>now(); RETURN FOUND;
