CREATE OR REPLACE FUNCTION "public"."heartbeat_sip_pipeline_run"("p_run_id" "uuid", "p_worker_id" "text") RETURNS "public"."sip_pipeline_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run public.sip_pipeline_runs%ROWTYPE;
BEGIN
  UPDATE public.sip_pipeline_runs
  SET
    worker_id = COALESCE(NULLIF(p_worker_id, ''), worker_id),
    heartbeat_at = now(),
    updated_at = now()
  WHERE id = p_run_id
  RETURNING * INTO v_run;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sip_pipeline_run_not_found: %', p_run_id;
  END IF;

  RETURN v_run;
END;
$$;


ALTER FUNCTION "public"."heartbeat_sip_pipeline_run"("p_run_id" "uuid", "p_worker_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."heartbeat_sip_pipeline_run_item"("p_run_id" "uuid", "p_item_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_lease_seconds" integer DEFAULT 900) RETURNS "public"."sip_pipeline_run_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item public.sip_pipeline_run_items%ROWTYPE;
BEGIN
  SELECT item.* INTO v_item
  FROM public.sip_pipeline_run_items item
  JOIN public.sip_pipeline_runs run
    ON run.id = item.run_id
  WHERE item.id = p_item_id
    AND item.run_id = p_run_id
    AND item.status = 'running'
    AND item.lease_owner = p_worker_id
    AND item.lease_token IS NOT DISTINCT FROM p_lease_token
    AND run.status IN ('queued', 'running')
    AND run.cancel_requested = false
  FOR UPDATE OF item;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sip_pipeline_run_item_lease_mismatch: %', p_item_id;
  END IF;

  UPDATE public.sip_pipeline_run_items
  SET
    lease_expires_at = now() + make_interval(secs => GREATEST(COALESCE(p_lease_seconds, 900), 60)),
    updated_at = now()
  WHERE id = p_item_id
  RETURNING * INTO v_item;

  UPDATE public.sip_pipeline_runs
  SET
    worker_id = p_worker_id,
    heartbeat_at = now(),
    current_stage = v_item.current_stage,
    updated_at = now()
  WHERE id = p_run_id;

  RETURN v_item;
END;
$$;


ALTER FUNCTION "public"."heartbeat_sip_pipeline_run_item"("p_run_id" "uuid", "p_item_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."instrument_audio_profile_membership_v1"("p_instrument_v2_id" "uuid") RETURNS TABLE("sample_original_path_id" "uuid", "pitch_content" "text", "velocity" integer, "round_robin" integer, "mic_position" "text", "midi_note" "text", "filename" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
  WITH direct_constructs AS (
    SELECT
      spc.sample_original_path_id,
      spc.pitch_content,
      spc.velocity,
      spc.round_robin,
      COALESCE(NULLIF(btrim(spc.mic_position), ''), 'main') AS mic_position,
      spc.midi_note,
      spc.filename,
      spc.sample_original_path_id::text AS order_key
    FROM public.sample_path_constructs spc
    WHERE spc.instrument_v2_id = p_instrument_v2_id
  ),
  instrument_row AS (
    SELECT
      i.id,
      i.original_sample_ids,
      i.pitch_contents,
      i.file_name_references,
      i.filename_variant_map,
      i.single_pitch
    FROM public.instruments_v2 i
    WHERE i.id = p_instrument_v2_id
  ),
  fallback_constructs AS (
    SELECT
      sample_ids.sample_original_path_id,
      COALESCE(NULLIF(instrument_row.pitch_contents ->> 0, ''), '0') AS pitch_content,
      0::integer AS velocity,
      (sample_ids.ordinality - 1)::integer AS round_robin,
      'main'::text AS mic_position,
      COALESCE(instrument_row.single_pitch::text, '0') AS midi_note,
      COALESCE(
        NULLIF(
          instrument_row.filename_variant_map ->> (
            '0/0/' || (sample_ids.ordinality - 1)::text || '/main'
          ),
          ''
        ),
        NULLIF(
          regexp_replace(
            COALESCE(
              instrument_row.file_name_references[sample_ids.ordinality::integer],
              ''
            ),
            '\.[^.]+$',
            ''
          ),
          ''
        ),
        'pitchless'
      ) AS filename,
      lpad(sample_ids.ordinality::text, 12, '0') AS order_key
    FROM instrument_row
    CROSS JOIN LATERAL unnest(
      COALESCE(instrument_row.original_sample_ids, ARRAY[]::uuid[])
    ) WITH ORDINALITY AS sample_ids(sample_original_path_id, ordinality)
    WHERE NOT EXISTS (SELECT 1 FROM direct_constructs)
  ),
  membership AS (
    SELECT * FROM direct_constructs
    UNION ALL
    SELECT * FROM fallback_constructs
  )
  SELECT
    membership.sample_original_path_id,
    membership.pitch_content,
    membership.velocity,
    membership.round_robin,
    membership.mic_position,
    membership.midi_note,
    membership.filename
  FROM membership
  ORDER BY
    membership.sample_original_path_id,
    membership.pitch_content,
    membership.velocity,
    membership.round_robin,
    membership.mic_position,
    membership.filename,
    membership.order_key;
$_$;


ALTER FUNCTION "public"."instrument_audio_profile_membership_v1"("p_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."instrument_audio_profile_status_page_v2"("p_instrument_v2_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_contributor_slug" "text" DEFAULT NULL::"text", "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text", "p_candidate_limit" integer DEFAULT 25, "p_repair_limit" integer DEFAULT 25, "p_published_only" boolean DEFAULT false, "p_cursor_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("instrument_v2_id" "uuid", "published" boolean, "contributor_slug" "text", "profile_version" "text", "current_source_signature" "text", "profile_source_signature" "text", "profile_state" "text", "has_current_profile" boolean, "sample_count" integer, "analyzed_sample_count" integer, "flagged_sample_count" integer, "warning_payload" "jsonb", "latest_job_id" "uuid", "latest_job_status" "text", "latest_job_reason" "text", "latest_job_attempts" integer, "latest_job_error" "text", "latest_job_created_at" timestamp with time zone, "latest_job_updated_at" timestamp with time zone, "latest_job_completed_at" timestamp with time zone, "candidate_updated_at" timestamp with time zone, "next_cursor_updated_at" timestamp with time zone, "next_cursor_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_candidate_ids uuid[];
  v_next_cursor_updated_at timestamptz;
  v_next_cursor_id uuid;
BEGIN
  IF p_candidate_limit IS NULL OR p_candidate_limit < 1 OR p_candidate_limit > 100 THEN
    RAISE EXCEPTION 'candidate limit must be between 1 and 100' USING ERRCODE = '22023';
  END IF;
  IF p_repair_limit IS NULL OR p_repair_limit < 1 OR p_repair_limit > 100 THEN
    RAISE EXCEPTION 'repair limit must be between 1 and 100' USING ERRCODE = '22023';
  END IF;
  IF p_repair_limit < p_candidate_limit THEN
    RAISE EXCEPTION 'repair limit must be at least the candidate limit' USING ERRCODE = '22023';
  END IF;
  IF (p_cursor_updated_at IS NULL) <> (p_cursor_id IS NULL) THEN
    RAISE EXCEPTION 'cursor updated_at and id must be provided together' USING ERRCODE = '22023';
  END IF;

  -- This subquery is deliberately materialized into an array before any
  -- signature work. Its ordering is the public keyset contract.
  SELECT coalesce(array_agg(page.id ORDER BY page.updated_at DESC, page.id ASC), ARRAY[]::uuid[]),
         (array_agg(page.updated_at ORDER BY page.updated_at DESC, page.id ASC))[cardinality(array_agg(page.id ORDER BY page.updated_at DESC, page.id ASC))],
         (array_agg(page.id ORDER BY page.updated_at DESC, page.id ASC))[cardinality(array_agg(page.id ORDER BY page.updated_at DESC, page.id ASC))]
  INTO v_candidate_ids, v_next_cursor_updated_at, v_next_cursor_id
  FROM (
    SELECT i.id, i.updated_at
    FROM public.instruments_v2 i
    LEFT JOIN public.contributors c ON c.id = i.contributor_id
    WHERE (p_instrument_v2_ids IS NULL OR i.id = ANY(p_instrument_v2_ids))
      AND (p_contributor_slug IS NULL OR c.slug = p_contributor_slug)
      AND (NOT p_published_only OR i.published = true)
      AND (
        p_cursor_updated_at IS NULL
        OR i.updated_at < p_cursor_updated_at
        OR (i.updated_at = p_cursor_updated_at AND i.id > p_cursor_id)
      )
    ORDER BY i.updated_at DESC, i.id ASC
    LIMIT p_candidate_limit
  ) page;

  IF coalesce(cardinality(v_candidate_ids), 0) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH candidates AS MATERIALIZED (
    SELECT i.*, c.slug AS candidate_contributor_slug, selected.ordinality
    FROM unnest(v_candidate_ids) WITH ORDINALITY AS selected(id, ordinality)
    JOIN public.instruments_v2 i ON i.id = selected.id
    LEFT JOIN public.contributors c ON c.id = i.contributor_id
  ),
  -- Missing profiles require no signature calculation and are always emitted
  -- before stale rows. Existing profiles are the only rows that reach the
  -- expensive function below.
  missing AS MATERIALIZED (
    SELECT candidate.*, p.profile_version AS stored_profile_version,
      p.source_signature AS stored_source_signature, p.sample_count AS stored_sample_count,
      p.analyzed_sample_count AS stored_analyzed_sample_count,
      p.flagged_sample_count AS stored_flagged_sample_count,
      p.warning_payload AS stored_warning_payload
    FROM candidates candidate
    LEFT JOIN public.instrument_audio_profile_v1 p
      ON p.instrument_v2_id = candidate.id AND p.profile_version = p_profile_version
    WHERE p.instrument_v2_id IS NULL
  ),
  existing AS MATERIALIZED (
    SELECT candidate.*, p.profile_version AS stored_profile_version,
      p.source_signature AS stored_source_signature, p.sample_count AS stored_sample_count,
      p.analyzed_sample_count AS stored_analyzed_sample_count,
      p.flagged_sample_count AS stored_flagged_sample_count,
      p.warning_payload AS stored_warning_payload,
      p.embedding, p.spectral_centroid_median, p.spectral_contrast_median,
      public.compute_instrument_audio_profile_signature_v1(candidate.id, p_profile_version) AS current_signature
    FROM candidates candidate
    JOIN public.instrument_audio_profile_v1 p
      ON p.instrument_v2_id = candidate.id AND p.profile_version = p_profile_version
  ),
  repairs AS MATERIALIZED (
    SELECT missing.*, NULL::text AS current_signature, 'missing'::text AS state, 0 AS repair_priority
    FROM missing
    UNION ALL
    SELECT existing.*, existing.current_signature,
      CASE
        WHEN existing.stored_source_signature IS DISTINCT FROM existing.current_signature THEN 'stale'
        WHEN existing.embedding IS NULL OR existing.spectral_centroid_median IS NULL OR existing.spectral_contrast_median IS NULL THEN 'incomplete'
        WHEN existing.stored_flagged_sample_count > 0
          OR CASE WHEN jsonb_typeof(coalesce(existing.stored_warning_payload, '[]'::jsonb)) = 'array'
            THEN jsonb_array_length(coalesce(existing.stored_warning_payload, '[]'::jsonb)) ELSE 0 END > 0 THEN 'current_with_warnings'
        ELSE 'current'
      END,
      CASE WHEN existing.stored_source_signature IS DISTINCT FROM existing.current_signature THEN 1 ELSE 2 END
    FROM existing
  ),
  limited_repairs AS MATERIALIZED (
    SELECT repair.id
    FROM repairs repair
    WHERE repair.state IN ('missing', 'stale')
    ORDER BY repair.repair_priority, repair.updated_at DESC, repair.id ASC
    LIMIT p_repair_limit
  ),
  latest_jobs AS MATERIALIZED (
    SELECT candidate.id, job.id AS job_id, job.status AS job_status, job.reason AS job_reason,
      job.attempts AS job_attempts, job.last_error AS job_error, job.created_at AS job_created_at,
      job.updated_at AS job_updated_at, job.completed_at AS job_completed_at
    FROM candidates candidate
    LEFT JOIN LATERAL (
      SELECT j.* FROM public.instrument_audio_profile_jobs_v1 j
      WHERE j.instrument_v2_id = candidate.id AND j.profile_version = p_profile_version
      ORDER BY j.created_at DESC, j.id DESC LIMIT 1
    ) job ON true
  )
  SELECT repair.id, repair.published, repair.candidate_contributor_slug,
    coalesce(repair.stored_profile_version, p_profile_version), repair.current_signature,
    repair.stored_source_signature, repair.state,
    repair.state IN ('current', 'current_with_warnings'), repair.stored_sample_count,
    repair.stored_analyzed_sample_count, repair.stored_flagged_sample_count,
    coalesce(repair.stored_warning_payload, '[]'::jsonb), latest.job_id, latest.job_status,
    latest.job_reason, latest.job_attempts, latest.job_error, latest.job_created_at,
    latest.job_updated_at, latest.job_completed_at, repair.updated_at,
    v_next_cursor_updated_at, v_next_cursor_id
  FROM repairs repair
  JOIN limited_repairs limited ON limited.id = repair.id
  LEFT JOIN latest_jobs latest ON latest.id = repair.id
  ORDER BY repair.repair_priority, repair.updated_at DESC, repair.id ASC;
END;
$$;


ALTER FUNCTION "public"."instrument_audio_profile_status_page_v2"("p_instrument_v2_ids" "uuid"[], "p_contributor_slug" "text", "p_profile_version" "text", "p_candidate_limit" integer, "p_repair_limit" integer, "p_published_only" boolean, "p_cursor_updated_at" timestamp with time zone, "p_cursor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."instrument_audio_profile_status_v1"("p_instrument_v2_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_contributor_slug" "text" DEFAULT NULL::"text", "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text", "p_limit" integer DEFAULT 500, "p_published_only" boolean DEFAULT false) RETURNS TABLE("instrument_v2_id" "uuid", "published" boolean, "contributor_slug" "text", "profile_version" "text", "current_source_signature" "text", "profile_source_signature" "text", "profile_state" "text", "has_current_profile" boolean, "sample_count" integer, "analyzed_sample_count" integer, "flagged_sample_count" integer, "warning_payload" "jsonb", "latest_job_id" "uuid", "latest_job_status" "text", "latest_job_reason" "text", "latest_job_attempts" integer, "latest_job_error" "text", "latest_job_created_at" timestamp with time zone, "latest_job_updated_at" timestamp with time zone, "latest_job_completed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT
    i.id,
    i.published,
    c.slug,
    COALESCE(p.profile_version, p_profile_version),
    sig.current_source_signature,
    p.source_signature,
    CASE
      WHEN p.instrument_v2_id IS NULL THEN 'missing'
      WHEN p.source_signature IS DISTINCT FROM sig.current_source_signature THEN 'stale'
      WHEN p.embedding IS NULL
        OR p.spectral_centroid_median IS NULL
        OR p.spectral_contrast_median IS NULL THEN 'incomplete'
      WHEN p.flagged_sample_count > 0
        OR CASE
          WHEN jsonb_typeof(COALESCE(p.warning_payload, '[]'::jsonb)) = 'array'
            THEN jsonb_array_length(COALESCE(p.warning_payload, '[]'::jsonb))
          ELSE 0
        END > 0 THEN 'current_with_warnings'
      ELSE 'current'
    END AS profile_state,
    p.instrument_v2_id IS NOT NULL
      AND p.source_signature IS NOT DISTINCT FROM sig.current_source_signature AS has_current_profile,
    p.sample_count,
    p.analyzed_sample_count,
    p.flagged_sample_count,
    COALESCE(p.warning_payload, '[]'::jsonb),
    latest.id,
    latest.status,
    latest.reason,
    latest.attempts,
    latest.last_error,
    latest.created_at,
    latest.updated_at,
    latest.completed_at
  FROM public.instruments_v2 i
  LEFT JOIN public.contributors c
    ON c.id = i.contributor_id
  CROSS JOIN LATERAL (
    SELECT public.compute_instrument_audio_profile_signature_v1(i.id, p_profile_version) AS current_source_signature
  ) sig
  LEFT JOIN public.instrument_audio_profile_v1 p
    ON p.instrument_v2_id = i.id
   AND p.profile_version = p_profile_version
  LEFT JOIN LATERAL (
    SELECT job.*
    FROM public.instrument_audio_profile_jobs_v1 job
    WHERE job.instrument_v2_id = i.id
      AND job.profile_version = p_profile_version
    ORDER BY job.created_at DESC, job.id DESC
    LIMIT 1
  ) latest ON true
  WHERE
    (p_instrument_v2_ids IS NULL OR i.id = ANY(p_instrument_v2_ids))
    AND (p_contributor_slug IS NULL OR c.slug = p_contributor_slug)
    AND (NOT p_published_only OR i.published = true)
  ORDER BY i.updated_at DESC, i.id ASC
  LIMIT GREATEST(COALESCE(p_limit, 500), 1);
$$;


ALTER FUNCTION "public"."instrument_audio_profile_status_v1"("p_instrument_v2_ids" "uuid"[], "p_contributor_slug" "text", "p_profile_version" "text", "p_limit" integer, "p_published_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invalidate_instrument_runtime_sample_manifest_v1"("p_instrument_v2_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_instrument_v2_id IS NULL THEN
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'instrument-runtime-sample-manifest:' || p_instrument_v2_id::text,
      0
    )
  );
  PERFORM public.unpublish_invalidated_deterministic_instrument_v2_v1(
    p_instrument_v2_id
  );

  DELETE FROM public.instrument_v2_runtime_readiness
  WHERE instrument_v2_id = p_instrument_v2_id;

  DELETE FROM public.instrument_runtime_sample_manifests
  WHERE instrument_v2_id = p_instrument_v2_id;
END;
$$;


ALTER FUNCTION "public"."invalidate_instrument_runtime_sample_manifest_v1"("p_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invalidate_instrument_v2_runtime_readiness_from_address_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'instrument-runtime-sample-manifest:' || NEW.id::text,
      0
    )
  );
  PERFORM public.unpublish_invalidated_deterministic_instrument_v2_v1(NEW.id);

  DELETE FROM public.instrument_v2_runtime_readiness readiness
  WHERE readiness.instrument_v2_id = NEW.id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."invalidate_instrument_v2_runtime_readiness_from_address_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invalidate_instrument_v2_runtime_readiness_from_output_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_instrument_v2_id uuid;
BEGIN
  FOR v_instrument_v2_id IN
    SELECT id
    FROM (
      VALUES
        (COALESCE(NEW.instrument_v2_id, OLD.instrument_v2_id)),
        (COALESCE(OLD.instrument_v2_id, NEW.instrument_v2_id))
    ) instrument(id)
    WHERE id IS NOT NULL
    GROUP BY id
    ORDER BY id
  LOOP
    PERFORM pg_advisory_xact_lock(
      hashtextextended(
        'instrument-runtime-sample-manifest:' ||
          v_instrument_v2_id::text,
        0
      )
    );
    PERFORM public.unpublish_invalidated_deterministic_instrument_v2_v1(
      v_instrument_v2_id
    );
  END LOOP;

  DELETE FROM public.instrument_v2_runtime_readiness readiness
  WHERE readiness.instrument_v2_id IN (
    COALESCE(NEW.instrument_v2_id, OLD.instrument_v2_id),
    COALESCE(OLD.instrument_v2_id, NEW.instrument_v2_id)
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."invalidate_instrument_v2_runtime_readiness_from_output_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invalidate_instrument_v2_sampled_midi_notes_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.instrument_v2_id IS NOT NULL THEN
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'instrument-summary:' || NEW.instrument_v2_id::text,
          0
        )
      );
      UPDATE public.instruments_v2
      SET sampled_midi_notes = NULL
      WHERE id = NEW.instrument_v2_id
        AND sampled_midi_notes IS NOT NULL;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.instrument_v2_id IS NOT NULL THEN
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'instrument-summary:' || OLD.instrument_v2_id::text,
          0
        )
      );
      UPDATE public.instruments_v2
      SET sampled_midi_notes = NULL
      WHERE id = OLD.instrument_v2_id
        AND sampled_midi_notes IS NOT NULL;
    END IF;
  ELSIF OLD.instrument_v2_id IS NOT NULL
    OR NEW.instrument_v2_id IS NOT NULL
  THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'instrument-summary:' || scoped.instrument_id::text,
        0
      )
    )
    FROM (
      SELECT DISTINCT instrument_id
      FROM (
        VALUES (OLD.instrument_v2_id), (NEW.instrument_v2_id)
      ) AS ids(instrument_id)
      WHERE instrument_id IS NOT NULL
      ORDER BY instrument_id
    ) AS scoped;

    UPDATE public.instruments_v2
    SET sampled_midi_notes = NULL
    WHERE id IN (OLD.instrument_v2_id, NEW.instrument_v2_id)
      AND sampled_midi_notes IS NOT NULL;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."invalidate_instrument_v2_sampled_midi_notes_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invalidate_runtime_manifest_from_construct_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_instrument_v2_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.invalidate_instrument_runtime_sample_manifest_v1(
      NEW.instrument_v2_id
    );
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM public.invalidate_instrument_runtime_sample_manifest_v1(
      OLD.instrument_v2_id
    );
  ELSE
    FOR v_instrument_v2_id IN
      SELECT DISTINCT candidate.instrument_v2_id
      FROM unnest(ARRAY[
        OLD.instrument_v2_id,
        NEW.instrument_v2_id
      ]) AS candidate(instrument_v2_id)
      WHERE candidate.instrument_v2_id IS NOT NULL
      ORDER BY candidate.instrument_v2_id
    LOOP
      PERFORM public.invalidate_instrument_runtime_sample_manifest_v1(
        v_instrument_v2_id
      );
    END LOOP;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."invalidate_runtime_manifest_from_construct_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invalidate_runtime_manifest_from_cue_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_instrument_v2_id uuid;
BEGIN
  FOR v_instrument_v2_id IN
    SELECT DISTINCT construct.instrument_v2_id
    FROM public.sample_path_constructs construct
    WHERE construct.instrument_v2_id IS NOT NULL
      AND construct.id = ANY(
        CASE
          WHEN TG_OP = 'INSERT' THEN ARRAY[NEW.sample_path_construct_id]
          WHEN TG_OP = 'DELETE' THEN ARRAY[OLD.sample_path_construct_id]
          ELSE ARRAY[
            OLD.sample_path_construct_id,
            NEW.sample_path_construct_id
          ]
        END
      )
    ORDER BY construct.instrument_v2_id
  LOOP
    PERFORM public.invalidate_instrument_runtime_sample_manifest_v1(
      v_instrument_v2_id
    );
  END LOOP;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."invalidate_runtime_manifest_from_cue_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invalidate_runtime_manifest_from_duration_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_instrument_v2_id uuid;
BEGIN
  FOR v_instrument_v2_id IN
    SELECT DISTINCT construct.instrument_v2_id
    FROM public.sample_path_constructs construct
    WHERE construct.instrument_v2_id IS NOT NULL
      AND construct.sample_original_path_id IN (
