        CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.sample_id ELSE NULL END
      )
    ORDER BY construct.instrument_v2_id
  LOOP
    PERFORM public.invalidate_instrument_runtime_sample_manifest_v1(
      v_instrument_v2_id
    );
  END LOOP;
  RETURN NULL;
END;
$$;


