CREATE OR REPLACE FUNCTION "public"."is_canonical_sampled_midi_notes_v1"("p_notes" smallint[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT p_notes IS NOT NULL
    AND cardinality(p_notes) > 0
    AND NOT EXISTS (
      SELECT 1
      FROM unnest(p_notes) AS note(value)
      WHERE note.value IS NULL OR note.value < 0 OR note.value > 127
    )
    AND cardinality(p_notes) = (
      SELECT count(DISTINCT note.value)
      FROM unnest(p_notes) AS note(value)
    )
    AND p_notes = ARRAY(
      SELECT note.value
      FROM unnest(p_notes) AS note(value)
      ORDER BY note.value
    )::smallint[];
$$;


ALTER FUNCTION "public"."is_canonical_sampled_midi_notes_v1"("p_notes" smallint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_current_instrument_v2_readiness_snapshot_v2"("p_instrument_v2_id" "uuid", "p_snapshot_sha256" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.instruments_v2 instrument
    JOIN public.instrument_v2_deterministic_readiness readiness
      ON readiness.instrument_v2_id = instrument.id
     AND readiness.snapshot_sha256 = p_snapshot_sha256
    WHERE instrument.id = p_instrument_v2_id
      AND readiness.status IN (
        'full_grid_deterministic',
        'exception_approved'
      )
      AND readiness.snapshot->>'schemaVersion' = '2'
      AND readiness.snapshot->>'instrumentV2Id' = instrument.id::text
      AND readiness.snapshot->>'engineType' =
        coalesce(nullif(btrim(instrument.engine_type::text), ''), 'tonal')
      AND readiness.snapshot->'filePathReference' IS NOT DISTINCT FROM
        coalesce(
          to_jsonb(nullif(btrim(instrument.file_path_reference), '')),
          'null'::jsonb
        )
      AND readiness.snapshot->'rangeLower' IS NOT DISTINCT FROM
        coalesce(to_jsonb(instrument.range_lower), 'null'::jsonb)
      AND readiness.snapshot->'rangeUpper' IS NOT DISTINCT FROM
        coalesce(to_jsonb(instrument.range_upper), 'null'::jsonb)
      AND readiness.snapshot->'singlePitch' IS NOT DISTINCT FROM
        coalesce(
          to_jsonb(
            CASE
              WHEN instrument.single_pitch IS NULL THEN NULL
              WHEN instrument.range_lower IS NOT NULL
                AND instrument.range_upper IS NOT NULL
                AND instrument.single_pitch NOT BETWEEN
                  least(instrument.range_lower, instrument.range_upper)
                  AND greatest(instrument.range_lower, instrument.range_upper)
              THEN NULL
              ELSE instrument.single_pitch
            END
          ),
          'null'::jsonb
        )
      AND readiness.snapshot->'sampledMidiNotes' IS NOT DISTINCT FROM
        coalesce(to_jsonb(instrument.sampled_midi_notes), 'null'::jsonb)
      AND jsonb_typeof(readiness.snapshot->'constructs') = 'array'
      AND NOT EXISTS (
        WITH live_constructs AS MATERIALIZED (
          SELECT
            btrim(construct.id::text) AS id,
            btrim(construct.sample_original_path_id::text)
              AS sample_original_path_id,
            nullif(btrim(source.s3_path), '') AS source_s3_path,
            btrim(construct.pitch_content) AS pitch_content,
            btrim(construct.midi_note) AS midi_note,
            btrim(construct.velocity::text) AS velocity,
            btrim(construct.round_robin::text) AS round_robin,
            btrim(coalesce(construct.mic_position, '')) AS mic_position,
            btrim(construct.filename) AS filename
          FROM public.sample_path_constructs construct
          JOIN public.samples_original_paths source
            ON source.id = construct.sample_original_path_id
          WHERE construct.instrument_v2_id = instrument.id
        ),
        snapshot_constructs AS MATERIALIZED (
          SELECT
            snapshot_construct.id,
            snapshot_construct."sampleOriginalPathId"
              AS sample_original_path_id,
            snapshot_construct."sourceS3Path" AS source_s3_path,
            snapshot_construct."pitchContent" AS pitch_content,
            snapshot_construct."midiNote" AS midi_note,
            snapshot_construct.velocity,
            snapshot_construct."roundRobin" AS round_robin,
            snapshot_construct."micPosition" AS mic_position,
            snapshot_construct.filename
          FROM jsonb_to_recordset(
            readiness.snapshot->'constructs'
          ) AS snapshot_construct(
            id text,
            "sampleOriginalPathId" text,
            "sourceS3Path" text,
            "pitchContent" text,
            "midiNote" text,
            velocity text,
            "roundRobin" text,
            "micPosition" text,
            filename text
          )
        )
        SELECT 1
        FROM (
          (
            SELECT * FROM live_constructs
            EXCEPT ALL
            SELECT * FROM snapshot_constructs
          )
          UNION ALL
          (
            SELECT * FROM snapshot_constructs
            EXCEPT ALL
            SELECT * FROM live_constructs
          )
        ) drift
      )
  );
$$;


ALTER FUNCTION "public"."is_current_instrument_v2_readiness_snapshot_v2"("p_instrument_v2_id" "uuid", "p_snapshot_sha256" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_current_instrument_v2_readiness_snapshot_v2"("p_instrument_v2_id" "uuid", "p_snapshot_sha256" "text") IS 'Revalidates schema-v2 deterministic readiness snapshots with an exact set-based construct comparison.';



