CREATE OR REPLACE FUNCTION "public"."list_market_pattern_embedding_admin_rows"("p_embedding_space" "text" DEFAULT NULL::"text") RETURNS TABLE("market_pattern_id" "uuid", "market_song_id" "uuid", "display_name" "text", "song_title" "text", "audio_url" "text", "is_published" boolean, "is_unique" boolean, "bus_type" "text", "parent_song_published" boolean, "auto_backfill_eligible" boolean, "public_rank_eligible" boolean, "source_fields" "jsonb", "current_source_hash" "text", "embedding_source_hash" "text", "is_current" boolean, "embedding_description" "jsonb", "current_documents" "jsonb", "vector_presence" "jsonb", "latest_job_id" "uuid", "latest_job_status" "text", "latest_job_attempt_count" integer, "latest_job_max_attempts" integer, "latest_job_lease_expires_at" timestamp with time zone, "latest_job_last_error" "text", "latest_job_created_at" timestamp with time zone, "latest_job_updated_at" timestamp with time zone, "latest_job_completed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "statement_timeout" TO '30s'
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT
    patterns.id, patterns.market_song_id, patterns.display_name, patterns.song_title,
    patterns.audio_url, patterns.is_published, patterns.is_unique, patterns.bus_type,
    COALESCE(songs.is_published, false), patterns.is_published,
    EXISTS (SELECT 1 FROM public.market_patterns_loops_unique_feed_v1 AS feed WHERE feed.id = patterns.id),
    current_source.description->'fields', current_source.source_hash, embeddings.source_hash,
    embeddings.source_hash = current_source.source_hash, embeddings.description,
    current_source.description->'documents',
    jsonb_build_object(
      'meta', embeddings.meta IS NOT NULL, 'instrument_name', embeddings.instrument_name IS NOT NULL,
      'instrument_family', embeddings.instrument_family IS NOT NULL, 'pattern_type', embeddings.pattern_type IS NOT NULL,
      'bpm', embeddings.bpm IS NOT NULL, 'key', embeddings.key IS NOT NULL,
      'scale_quality', embeddings.scale_quality IS NOT NULL, 'mood', embeddings.mood IS NOT NULL,
      'time_signature_numerator', embeddings.time_signature_numerator IS NOT NULL,
      'time_signature_denominator', embeddings.time_signature_denominator IS NOT NULL,
      'duration_seconds', embeddings.duration_seconds IS NOT NULL, 'search_tokens', embeddings.search_tokens IS NOT NULL,
      'sample_id', embeddings.sample_id IS NOT NULL, 'pitch_shift', embeddings.pitch_shift IS NOT NULL,
      'is_reverse', embeddings.is_reverse IS NOT NULL, 'pattern', embeddings.pattern IS NOT NULL,
      'envelope', embeddings.envelope IS NOT NULL, 'swell', embeddings.swell IS NOT NULL,
      'humanize', embeddings.humanize IS NOT NULL, 'delay', embeddings.delay IS NOT NULL,
      'chords', embeddings.chords IS NOT NULL
    ),
    latest_job.id, latest_job.status, latest_job.attempt_count, latest_job.max_attempts,
    latest_job.lease_expires_at, latest_job.last_error, latest_job.created_at,
    latest_job.updated_at, latest_job.completed_at
  FROM public.market_patterns AS patterns
  LEFT JOIN public.market_songs AS songs ON songs.id = patterns.market_song_id
  CROSS JOIN LATERAL (
    SELECT public.market_pattern_embedding_description(patterns) AS description
  ) AS current_description
  CROSS JOIN LATERAL (
    SELECT
      current_description.description,
      encode(
        extensions.digest(
          convert_to(public.market_pattern_stable_json(current_description.description), 'UTF8'),
          'sha256'
        ),
        'hex'
      ) AS source_hash
  ) AS current_source
  LEFT JOIN public.market_pattern_embeddings AS embeddings
    ON embeddings.market_pattern_id = patterns.id
    AND embeddings.embedding_space = COALESCE(p_embedding_space, 'openai:text-embedding-3-large:256:market-pattern-v1')
  LEFT JOIN LATERAL (
    SELECT jobs.* FROM public.market_pattern_embedding_jobs AS jobs
    WHERE jobs.market_pattern_id = patterns.id
      AND jobs.embedding_space = COALESCE(p_embedding_space, 'openai:text-embedding-3-large:256:market-pattern-v1')
    ORDER BY jobs.created_at DESC LIMIT 1
  ) AS latest_job ON true
  ORDER BY patterns.created_at DESC, patterns.id;
$$;


ALTER FUNCTION "public"."list_market_pattern_embedding_admin_rows"("p_embedding_space" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_sip_instruments_v2_upload_status_staging_page"("p_contributor_slug" "text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
WITH args AS (
  SELECT
    nullif(btrim(coalesce(p_contributor_slug, '')), '') AS contributor_slug,
    least(greatest(coalesce(p_limit, 50), 1), 2500) AS limit_value,
    greatest(coalesce(p_offset, 0), 0) AS offset_value
),
filtered AS (
  SELECT sri.*
  FROM public.sip_review_instrument sri
  JOIN args ON args.contributor_slug IS NOT NULL
  WHERE sri.source_contributor_slug = args.contributor_slug
    AND coalesce(sri.is_retired, false) = false
),
total AS (
  SELECT count(*)::integer AS count_value
  FROM filtered
),
paged AS (
  SELECT filtered.*
  FROM filtered, args
  ORDER BY filtered.updated_at DESC NULLS LAST, filtered.id DESC
  LIMIT (SELECT limit_value FROM args)
  OFFSET (SELECT offset_value FROM args)
)
SELECT jsonb_build_object(
  'rows',
  coalesce(
    (
      SELECT jsonb_agg(to_jsonb(paged) ORDER BY paged.updated_at DESC NULLS LAST, paged.id DESC)
      FROM paged
    ),
    '[]'::jsonb
  ),
  'totalCount',
  (SELECT count_value FROM total),
  'hasMore',
  (
    SELECT args.offset_value + (SELECT count(*) FROM paged) < total.count_value
    FROM args, total
  )
);
$$;


ALTER FUNCTION "public"."list_sip_instruments_v2_upload_status_staging_page"("p_contributor_slug" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_sip_staging_collection_summary"("p_contributor_slug" "text", "p_search" "text" DEFAULT ''::"text", "p_path_search" "text" DEFAULT ''::"text", "p_status_filter" "text" DEFAULT 'all'::"text", "p_warning_filter" "text" DEFAULT 'all'::"text", "p_sort_by" "text" DEFAULT 'sampleCount'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_round_robin_filter" "text" DEFAULT 'all'::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
WITH raw_payload AS (
  SELECT public.build_sip_staging_instruments_payload(
    p_contributor_slug,
    '',
    '',
    p_status_filter,
    p_warning_filter,
    p_sort_by,
    p_sort_dir,
    p_round_robin_filter,
    NULL::uuid[],
    NULL::integer,
    0
  ) AS data
),
filtered_payload AS (
  SELECT public.filter_sip_staging_instrument_payload_rows(
    raw_payload.data,
    p_search,
    p_path_search
  ) AS data
  FROM raw_payload
),
rows AS (
  SELECT
    row_value.value,
    row_value.ordinality,
    nullif(btrim(row_value.value->>'collection'), '') AS collection
  FROM filtered_payload
  CROSS JOIN LATERAL jsonb_array_elements(filtered_payload.data->'rows')
    WITH ORDINALITY AS row_value(value, ordinality)
),
grouped AS (
  SELECT
    coalesce(collection, '__empty_collection__') AS key,
    collection,
    count(*)::integer AS count,
    jsonb_agg(value->>'id' ORDER BY ordinality) AS instrument_ids
  FROM rows
  GROUP BY collection
)
SELECT jsonb_build_object(
  'totalCount',
  coalesce((filtered_payload.data->>'totalCount')::integer, 0),
  'collections',
  coalesce(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'key', grouped.key,
          'collection', grouped.collection,
          'count', grouped.count,
          'instrumentIds', grouped.instrument_ids,
          'instrument_ids', grouped.instrument_ids
        )
        ORDER BY
          grouped.count DESC,
          coalesce(grouped.collection, 'No collection') ASC
      )
      FROM grouped
    ),
    '[]'::jsonb
  )
)
FROM filtered_payload;
$$;


ALTER FUNCTION "public"."list_sip_staging_collection_summary"("p_contributor_slug" "text", "p_search" "text", "p_path_search" "text", "p_status_filter" "text", "p_warning_filter" "text", "p_sort_by" "text", "p_sort_dir" "text", "p_round_robin_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_sip_staging_instruments"("p_contributor_slug" "text", "p_search" "text" DEFAULT ''::"text", "p_path_search" "text" DEFAULT ''::"text", "p_status_filter" "text" DEFAULT 'all'::"text", "p_warning_filter" "text" DEFAULT 'all'::"text", "p_sort_by" "text" DEFAULT 'sampleCount'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
WITH args AS (
  SELECT
    regexp_replace(
      regexp_replace(lower(btrim(coalesce(p_contributor_slug, ''))), '[_\s]+', '-', 'g'),
      '-+',
      '-',
      'g'
    ) AS contributor_slug,
    btrim(coalesce(p_search, '')) AS search,
    btrim(coalesce(p_path_search, '')) AS path_search,
    lower(btrim(coalesce(p_status_filter, 'all'))) AS status_filter,
    lower(btrim(coalesce(p_warning_filter, 'all'))) AS warning_filter,
    coalesce(nullif(btrim(p_sort_by), ''), 'sampleCount') AS sort_by,
    CASE WHEN lower(btrim(coalesce(p_sort_dir, 'desc'))) = 'asc' THEN 'asc' ELSE 'desc' END AS sort_dir,
    least(greatest(coalesce(p_limit, 50), 1), 500) AS limit_value,
    greatest(coalesce(p_offset, 0), 0) AS offset_value
),
scope_counts AS (
  SELECT
    scope.sip_review_instrument_id,
    count(*)::integer AS scope_count
  FROM public.sip_review_instrument_sample_scope scope
  JOIN args ON scope.contributor_slug = args.contributor_slug
  GROUP BY scope.sip_review_instrument_id
),
candidate_base AS (
  SELECT
    sri.id,
    sri.source_sip_instrument_id,
    sri.source_contributor_slug,
    sri.source_group_key,
    coalesce(nullif(btrim(sri.name), ''), 'Unnamed') AS name,
    nullif(btrim(sri.collection), '') AS collection,
    sri.engine_type::text AS engine_type,
    sri.playback_type::text AS playback_type,
    nullif(btrim(sri.polyphony_type::text), '') AS polyphony_type,
    btrim(sri.instrument_family) AS instrument_family,
    nullif(btrim(sri.instrument_type), '') AS instrument_type,
    sri.contributor_id,
    sri.pitch_contents,
    sri.pitch_content_config,
    sri.velocity_layers,
    sri.range_lower,
    sri.range_upper,
    sri.single_pitch,
    sri.gain,
    sri.sustain_crop_time,
    sri.articulations,
    sri.effects_instruments,
    sri.mic_positions,
    sri.round_robins,
    nullif(btrim(sri.articulation), '') AS articulation,
    nullif(btrim(sri.effect), '') AS effect,
    sri.original_sample_ids,
    cardinality(coalesce(sri.original_sample_ids, ARRAY[]::uuid[]))::integer AS original_sample_count,
    coalesce(scope_counts.scope_count, 0)::integer AS scope_count,
    CASE
      WHEN coalesce(scope_counts.scope_count, 0) > 0 THEN scope_counts.scope_count
      ELSE cardinality(coalesce(sri.original_sample_ids, ARRAY[]::uuid[]))
    END::integer AS sample_count,
    sri.original_file_path_reference,
    sri.original_file_name_references,
    sri.published,
    sri.updated_at,
    sri.is_retired,
    sri.split_parent_sip_review_instrument_id,
    rpm.instrument_v2_id,
    CASE
      WHEN sri.is_retired THEN 'retired'
      WHEN rpm.instrument_v2_id IS NOT NULL THEN 'promoted'
      ELSE 'staged'
    END AS staging_status,
    lower(coalesce(nullif(btrim(source.name), ''), nullif(btrim(sri.name), ''), 'Unnamed')) AS warning_key
  FROM public.sip_review_instrument sri
  JOIN args ON true
  LEFT JOIN public.sip_instrument source
    ON source.id = sri.source_sip_instrument_id
  LEFT JOIN public.sip_review_promotion_map rpm
    ON rpm.sip_review_instrument_id = sri.id
  LEFT JOIN scope_counts
    ON scope_counts.sip_review_instrument_id = sri.id
  WHERE sri.source_contributor_slug = args.contributor_slug
    AND (
      args.search = ''
      OR sri.name ILIKE ('%' || args.search || '%')
    )
    AND (
      args.path_search = ''
      OR sri.original_file_path_reference ILIKE ('%' || args.path_search || '%')
      OR EXISTS (
        SELECT 1
        FROM unnest(coalesce(sri.original_file_name_references, ARRAY[]::text[])) AS file_name(value)
        WHERE file_name.value ILIKE ('%' || args.path_search || '%')
      )
    )
),
status_filtered AS (
  SELECT candidate_base.*
  FROM candidate_base
  CROSS JOIN args
  WHERE CASE
    WHEN args.status_filter = 'all'
      THEN candidate_base.staging_status NOT IN ('retired', 'promoted')
    WHEN args.status_filter IN ('staged', 'promoted', 'retired')
      THEN candidate_base.staging_status = args.status_filter
    ELSE false
  END
),
warning_names AS (
  SELECT DISTINCT warning_key
  FROM status_filtered
  WHERE warning_key IS NOT NULL AND warning_key <> ''
),
warning_by_name AS (
  SELECT
    lower(sc.instrument_name) AS warning_key,
    count(*) FILTER (
      WHERE sc.confidence IS NOT NULL
        AND sc.confidence ~ '^[+-]?[0-9]+(\.[0-9]+)?$'
        AND sc.confidence::numeric < 0.5
    )::integer AS warning_count,
    coalesce(sum(
      (CASE WHEN lower(sa.articulation_cosine_threshold_band) IN ('mismatch', 'ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN lower(sa.effect_cosine_threshold_band) IN ('mismatch', 'ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN lower(sa.mic_position_cosine_threshold_band) IN ('mismatch', 'ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN lower(sa.collision_cosine_threshold_band) IN ('mismatch', 'ambiguous') THEN 1 ELSE 0 END) +
      (CASE WHEN lower(sa.velocity_cosine_threshold_band) IN ('mismatch', 'ambiguous') THEN 1 ELSE 0 END)
    ), 0)::integer AS anomaly_count
  FROM public.sip_sample_construct sc
  JOIN args
    ON sc.contributor_slug = args.contributor_slug
  JOIN warning_names
    ON warning_names.warning_key = lower(sc.instrument_name)
  LEFT JOIN public.sip_sample_analysis sa
    ON sa.original_sample_id = sc.original_sample_id
   AND sa.contributor_slug = sc.contributor_slug
  GROUP BY lower(sc.instrument_name)
),
filtered AS (
  SELECT
    status_filtered.*,
    coalesce(warning_by_name.warning_count, 0)::integer AS warning_count,
    coalesce(warning_by_name.anomaly_count, 0)::integer AS anomaly_count
  FROM status_filtered
  CROSS JOIN args
  LEFT JOIN warning_by_name
    ON warning_by_name.warning_key = status_filtered.warning_key
  WHERE CASE
    WHEN args.warning_filter = 'warnings'
      THEN coalesce(warning_by_name.warning_count, 0) > 0
    WHEN args.warning_filter = 'anomalies'
      THEN coalesce(warning_by_name.anomaly_count, 0) > 0
    ELSE true
  END
),
sort_values AS (
  SELECT
    filtered.*,
    args.sort_dir,
    CASE
      WHEN args.sort_by = 'sampleCount' THEN filtered.sample_count::double precision
      WHEN args.sort_by = 'originalSampleCount' THEN filtered.original_sample_count::double precision
      WHEN args.sort_by = 'polyphonySets' THEN filtered.pitch_contents::double precision
      WHEN args.sort_by = 'velocityLayers' THEN filtered.velocity_layers::double precision
      WHEN args.sort_by = 'range' THEN coalesce(filtered.range_lower, filtered.single_pitch, 0)::double precision
      WHEN args.sort_by = 'singlePitch' THEN coalesce(filtered.single_pitch, -1)::double precision
      WHEN args.sort_by = 'gain' THEN coalesce(filtered.gain, 0)::double precision
      WHEN args.sort_by = 'sustainCropTime' THEN coalesce(filtered.sustain_crop_time, 0)::double precision
      WHEN args.sort_by = 'published' THEN CASE WHEN filtered.published THEN 1 ELSE 0 END::double precision
      WHEN args.sort_by = 'warningCount' THEN filtered.warning_count::double precision
      WHEN args.sort_by = 'anomalyCount' THEN filtered.anomaly_count::double precision
      WHEN args.sort_by NOT IN (
        'instrumentName', 'name', 'collection', 'collections', 'type',
        'engineType', 'playbackType', 'polyphonyType', 'instrumentFamily',
        'instrumentType', 'contributorId', 'polyphonyConfig',
        'filePathReference', 'fileNameReferences', 'originalSampleIds',
        'articulations', 'effectsInstruments', 'micPositions', 'velocities',
        'promotedInstrumentV2Id', 'status', 'stagingStatus', 'updatedAt',
        'articulation', 'effect', 'roundRobins'
      ) THEN filtered.sample_count::double precision
      ELSE NULL::double precision
    END AS numeric_sort,
    CASE
      WHEN args.sort_by IN ('instrumentName', 'name') THEN filtered.name
      WHEN args.sort_by IN ('collection', 'collections') THEN coalesce(filtered.collection, '')
      WHEN args.sort_by IN ('type', 'engineType') THEN filtered.engine_type
      WHEN args.sort_by = 'playbackType' THEN filtered.playback_type
      WHEN args.sort_by = 'polyphonyType' THEN coalesce(filtered.polyphony_type, '')
      WHEN args.sort_by = 'instrumentFamily' THEN coalesce(filtered.instrument_family, '')
      WHEN args.sort_by = 'instrumentType' THEN coalesce(filtered.instrument_type, '')
      WHEN args.sort_by = 'contributorId' THEN coalesce(filtered.contributor_id::text, '')
      WHEN args.sort_by = 'polyphonyConfig' THEN coalesce(filtered.pitch_content_config::text, '')
      WHEN args.sort_by = 'filePathReference' THEN coalesce(filtered.original_file_path_reference, '')
      WHEN args.sort_by = 'fileNameReferences' THEN array_to_string(coalesce(filtered.original_file_name_references, ARRAY[]::text[]), ',')
      WHEN args.sort_by = 'originalSampleIds' THEN array_to_string(coalesce(filtered.original_sample_ids, ARRAY[]::uuid[]), ',')
      WHEN args.sort_by = 'articulations' THEN array_to_string(coalesce(filtered.articulations, ARRAY[]::uuid[])::text[], ',')
      WHEN args.sort_by = 'effectsInstruments' THEN array_to_string(coalesce(filtered.effects_instruments, ARRAY[]::uuid[])::text[], ',')
      WHEN args.sort_by = 'micPositions' THEN coalesce(filtered.mic_positions::text, '')
      WHEN args.sort_by = 'velocities' THEN filtered.velocity_layers::text
      WHEN args.sort_by = 'promotedInstrumentV2Id' THEN coalesce(filtered.instrument_v2_id::text, '')
      WHEN args.sort_by IN ('status', 'stagingStatus') THEN filtered.staging_status
      WHEN args.sort_by = 'updatedAt' THEN coalesce(filtered.updated_at::text, '')
      WHEN args.sort_by = 'articulation' THEN coalesce(filtered.articulation, '')
      WHEN args.sort_by = 'effect' THEN coalesce(filtered.effect, '')
      WHEN args.sort_by = 'roundRobins' THEN coalesce(filtered.round_robins::text, '')
      ELSE NULL::text
    END AS text_sort
  FROM filtered
  CROSS JOIN args
),
ordered AS (
  SELECT
    sort_values.*,
    row_number() OVER (
      ORDER BY
        CASE WHEN sort_values.sort_dir = 'asc' THEN sort_values.numeric_sort END ASC NULLS LAST,
        CASE WHEN sort_values.sort_dir = 'desc' THEN sort_values.numeric_sort END DESC NULLS LAST,
        CASE WHEN sort_values.sort_dir = 'asc' THEN sort_values.text_sort END ASC NULLS LAST,
        CASE WHEN sort_values.sort_dir = 'desc' THEN sort_values.text_sort END DESC NULLS LAST,
        sort_values.id ASC
    ) AS row_order,
    count(*) OVER () AS total_count
  FROM sort_values
),
paged AS (
  SELECT ordered.*
  FROM ordered
  CROSS JOIN args
  WHERE ordered.row_order > args.offset_value
    AND ordered.row_order <= args.offset_value + args.limit_value
)
SELECT jsonb_build_object(
  'rows',
  coalesce(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', paged.id::text,
          'sourceTmpInstrumentV2Id', paged.source_sip_instrument_id::text,
          'sourceContributorSlug', paged.source_contributor_slug,
          'sourceGroupKey', coalesce(paged.source_group_key, ''),
          'name', paged.name,
          'collection', paged.collection,
          'engineType', paged.engine_type,
          'playbackType', paged.playback_type,
          'polyphonyType', paged.polyphony_type,
          'instrumentFamily', paged.instrument_family,
          'instrumentType', paged.instrument_type,
          'contributorId', paged.contributor_id::text,
          'polyphonySets', paged.pitch_contents,
          'polyphonyConfig', paged.pitch_content_config,
          'velocityLayers', paged.velocity_layers,
          'rangeLower', paged.range_lower,
          'rangeUpper', paged.range_upper,
          'singlePitch', paged.single_pitch,
          'gain', paged.gain,
          'sustainCropTime', paged.sustain_crop_time,
          'velocities', jsonb_build_array(paged.velocity_layers::text),
          'articulations', to_jsonb(coalesce(paged.articulations, ARRAY[]::uuid[])),
          'effectsInstruments', to_jsonb(coalesce(paged.effects_instruments, ARRAY[]::uuid[])),
          'micPositions', coalesce(paged.mic_positions, '[]'::jsonb),
          'roundRobins', coalesce(to_jsonb(paged.round_robins), 'null'::jsonb),
          'articulation', paged.articulation,
          'effect', paged.effect,
          'originalSampleIds', to_jsonb(coalesce(paged.original_sample_ids, ARRAY[]::uuid[])),
          'originalSampleCount', paged.original_sample_count,
          'sampleCount', paged.sample_count,
          'originalFilePathReference', paged.original_file_path_reference,
          'originalFileNameReferences', to_jsonb(coalesce(paged.original_file_name_references, ARRAY[]::text[])),
          'filePathReference', paged.original_file_path_reference,
          'fileNameReferences', to_jsonb(coalesce(paged.original_file_name_references, ARRAY[]::text[])),
          'warningCount', paged.warning_count,
          'anomalyCount', paged.anomaly_count,
          'stagingStatus', paged.staging_status,
          'promotedInstrumentV2Id', paged.instrument_v2_id::text,
          'published', paged.published,
          'updatedAt', paged.updated_at,
          'isRetired', paged.is_retired,
          'splitParentStagingInstrumentV2Id', paged.split_parent_sip_review_instrument_id::text
        )
        ORDER BY paged.row_order
      )
      FROM paged
    ),
    '[]'::jsonb
  ),
  'totalCount', coalesce((SELECT max(ordered.total_count)::integer FROM ordered), 0),
  'hasMore',
  (
    SELECT
      args.offset_value + (SELECT count(*) FROM paged)
        < coalesce((SELECT max(ordered.total_count)::integer FROM ordered), 0)
    FROM args
  )
);
$_$;


ALTER FUNCTION "public"."list_sip_staging_instruments"("p_contributor_slug" "text", "p_search" "text", "p_path_search" "text", "p_status_filter" "text", "p_warning_filter" "text", "p_sort_by" "text", "p_sort_dir" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_sip_staging_instruments"("p_contributor_slug" "text", "p_search" "text" DEFAULT ''::"text", "p_path_search" "text" DEFAULT ''::"text", "p_status_filter" "text" DEFAULT 'all'::"text", "p_warning_filter" "text" DEFAULT 'all'::"text", "p_sort_by" "text" DEFAULT 'sampleCount'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_round_robin_filter" "text" DEFAULT 'all'::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
WITH args AS (
  SELECT
    lower(btrim(coalesce(p_search, ''))) AS search,
    lower(btrim(coalesce(p_path_search, ''))) AS path_search,
    least(greatest(coalesce(p_limit, 50), 1), 500) AS limit_value,
    greatest(coalesce(p_offset, 0), 0) AS offset_value,
    coalesce(nullif(btrim(p_sort_by), ''), 'sampleCount') AS sort_by,
    CASE WHEN lower(btrim(coalesce(p_sort_dir, 'desc'))) = 'asc' THEN 'asc' ELSE 'desc' END AS sort_dir
),
unfiltered_payload AS (
  SELECT public.build_sip_staging_instruments_payload(
    p_contributor_slug,
    '',
    '',
    p_status_filter,
    p_warning_filter,
    p_sort_by,
    p_sort_dir,
    p_round_robin_filter,
    NULL::uuid[],
    p_limit,
    p_offset
  ) AS data
  FROM args
  WHERE args.search = ''
    AND args.path_search = ''
    AND args.sort_by <> 'fileNameReferences'
),
filtered_raw_payload AS (
  SELECT public.build_sip_staging_instruments_payload(
    p_contributor_slug,
    '',
    '',
    p_status_filter,
    p_warning_filter,
    p_sort_by,
    p_sort_dir,
    p_round_robin_filter,
    NULL::uuid[],
    NULL::integer,
    0
  ) AS data
  FROM args
  WHERE args.search <> ''
     OR args.path_search <> ''
     OR args.sort_by = 'fileNameReferences'
),
filtered_payload AS (
  SELECT public.filter_sip_staging_instrument_payload_rows(
    filtered_raw_payload.data,
    p_search,
    p_path_search
  ) AS data
  FROM filtered_raw_payload
),
ordered_rows AS (
  SELECT
    row_value.value,
    row_value.ordinality,
    jsonb_array_length(
      CASE
        WHEN jsonb_typeof(row_value.value->'originalFileNameReferences') = 'array'
          THEN row_value.value->'originalFileNameReferences'
        WHEN jsonb_typeof(row_value.value->'fileNameReferences') = 'array'
          THEN row_value.value->'fileNameReferences'
        ELSE '[]'::jsonb
      END
    ) AS filename_count
  FROM filtered_payload
  CROSS JOIN LATERAL jsonb_array_elements(coalesce(filtered_payload.data->'rows', '[]'::jsonb))
    WITH ORDINALITY AS row_value(value, ordinality)
),
ranked_rows AS (
  SELECT
    ordered_rows.*,
    row_number() OVER (
      ORDER BY
        CASE WHEN args.sort_by = 'fileNameReferences' AND args.sort_dir = 'asc'
          THEN ordered_rows.filename_count END ASC NULLS LAST,
        CASE WHEN args.sort_by = 'fileNameReferences' AND args.sort_dir = 'desc'
          THEN ordered_rows.filename_count END DESC NULLS LAST,
        CASE WHEN args.sort_by = 'fileNameReferences'
          THEN ordered_rows.value->>'id' END ASC NULLS LAST,
        ordered_rows.ordinality ASC
    ) AS row_order
  FROM ordered_rows
  CROSS JOIN args
),
paged AS (
  SELECT ranked_rows.*
  FROM ranked_rows
  CROSS JOIN args
  WHERE ranked_rows.row_order > args.offset_value
    AND ranked_rows.row_order <= args.offset_value + args.limit_value
)
SELECT jsonb_build_object(
  'rows',
  coalesce(
    (
      SELECT jsonb_agg(row_value.value - 'rowOrder' ORDER BY row_value.ordinality)
      FROM unfiltered_payload
      CROSS JOIN LATERAL jsonb_array_elements(coalesce(unfiltered_payload.data->'rows', '[]'::jsonb))
        WITH ORDINALITY AS row_value(value, ordinality)
    ),
    '[]'::jsonb
  ),
  'totalCount',
  coalesce((unfiltered_payload.data->>'totalCount')::integer, 0),
  'hasMore',
  args.offset_value + jsonb_array_length(coalesce(unfiltered_payload.data->'rows', '[]'::jsonb))
    < coalesce((unfiltered_payload.data->>'totalCount')::integer, 0)
)
FROM unfiltered_payload
CROSS JOIN args
UNION ALL
SELECT jsonb_build_object(
  'rows',
  coalesce(
    (
      SELECT jsonb_agg(paged.value - 'rowOrder' ORDER BY paged.row_order)
      FROM paged
    ),
    '[]'::jsonb
  ),
  'totalCount',
  coalesce((filtered_payload.data->>'totalCount')::integer, 0),
  'hasMore',
  args.offset_value + (SELECT count(*) FROM paged)
    < coalesce((filtered_payload.data->>'totalCount')::integer, 0)
)
FROM filtered_payload
CROSS JOIN args;
$$;


ALTER FUNCTION "public"."list_sip_staging_instruments"("p_contributor_slug" "text", "p_search" "text", "p_path_search" "text", "p_status_filter" "text", "p_warning_filter" "text", "p_sort_by" "text", "p_sort_dir" "text", "p_limit" integer, "p_offset" integer, "p_round_robin_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_sip_staging_instruments_by_ids"("p_contributor_slug" "text", "p_search" "text" DEFAULT ''::"text", "p_path_search" "text" DEFAULT ''::"text", "p_status_filter" "text" DEFAULT 'all'::"text", "p_warning_filter" "text" DEFAULT 'all'::"text", "p_sort_by" "text" DEFAULT 'sampleCount'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_round_robin_filter" "text" DEFAULT 'all'::"text", "p_instrument_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
WITH normalized_ids AS (
  SELECT coalesce(p_instrument_ids, ARRAY[]::uuid[]) AS instrument_ids
),
raw_payload AS (
  SELECT public.build_sip_staging_instruments_payload(
    p_contributor_slug,
    '',
    '',
    p_status_filter,
    p_warning_filter,
    p_sort_by,
    p_sort_dir,
    p_round_robin_filter,
    normalized_ids.instrument_ids,
    NULL::integer,
    0
  ) AS data
  FROM normalized_ids
  WHERE cardinality(normalized_ids.instrument_ids) > 0
),
filtered_payload AS (
  SELECT public.filter_sip_staging_instrument_payload_rows(
    raw_payload.data,
    p_search,
    p_path_search
  ) AS data
  FROM raw_payload
)
SELECT jsonb_build_object(
  'rows',
  coalesce(
    (
      SELECT jsonb_agg(row_value.value - 'rowOrder' ORDER BY row_value.ordinality)
      FROM filtered_payload
      CROSS JOIN LATERAL jsonb_array_elements(filtered_payload.data->'rows')
        WITH ORDINALITY AS row_value(value, ordinality)
    ),
    '[]'::jsonb
  ),
  'totalCount',
  coalesce((SELECT (filtered_payload.data->>'totalCount')::integer FROM filtered_payload), 0),
  'hasMore',
  false
)
FROM filtered_payload
UNION ALL
SELECT jsonb_build_object(
  'rows', '[]'::jsonb,
  'totalCount', 0,
  'hasMore', false
)
WHERE NOT EXISTS (SELECT 1 FROM filtered_payload);
$$;


ALTER FUNCTION "public"."list_sip_staging_instruments_by_ids"("p_contributor_slug" "text", "p_search" "text", "p_path_search" "text", "p_status_filter" "text", "p_warning_filter" "text", "p_sort_by" "text", "p_sort_dir" "text", "p_round_robin_filter" "text", "p_instrument_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_sip_review_warning_stale"("p_instrument_ids" "uuid"[], "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    INSERT INTO public.sip_review_warning_index_state (
        sip_review_instrument_id,
        contributor_slug,
        is_stale,
        stale_at,
        stale_reason
    )
    SELECT
        i.id,
        i.source_contributor_slug,
        true,
        now(),
        p_reason
    FROM public.sip_review_instrument i
    WHERE i.id = ANY(p_instrument_ids)
    ON CONFLICT (sip_review_instrument_id) DO UPDATE SET
        is_stale = true,
        updated_at = now(),
        refresh_lease_token = NULL,
        failure_count = 0,
        refresh_error = NULL,
        contributor_slug = EXCLUDED.contributor_slug,
        stale_at = CASE
            WHEN sip_review_warning_index_state.is_stale = false THEN now()
            ELSE sip_review_warning_index_state.stale_at
        END,
        stale_reason = CASE
            WHEN sip_review_warning_index_state.is_stale = false THEN p_reason
            ELSE sip_review_warning_index_state.stale_reason
        END;
END;
$$;


ALTER FUNCTION "public"."mark_sip_review_warning_stale"("p_instrument_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_skipped_fresh_instrument_profile_revalidated_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status='skipped_fresh'
    AND NEW.completed_at IS NOT NULL
    AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status)
  THEN
    UPDATE public.instrument_audio_profile_v1 profile
    SET updated_at=NEW.completed_at
    WHERE profile.instrument_v2_id=NEW.instrument_v2_id
      AND profile.profile_version=NEW.profile_version
      AND profile.source_signature=NEW.source_signature
      AND profile.source_signature IS NOT DISTINCT FROM
        public.compute_instrument_audio_profile_signature_v1(
          NEW.instrument_v2_id,NEW.profile_version
        );
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."mark_skipped_fresh_instrument_profile_revalidated_v1"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."market_patterns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "canonical_hash" "text" NOT NULL,
    "hash_version" smallint DEFAULT 1 NOT NULL,
    "loop_identity_config" "jsonb" NOT NULL,
    "market_song_id" "uuid" NOT NULL,
    "artist_id" "uuid",
    "artist_name" "text",
    "song_title" "text",
    "song_slug" "text",
    "contributor_id" "uuid",
    "contributor_name" "text",
    "song_config_coordinates" "jsonb" NOT NULL,
    "audio_url" "text" NOT NULL,
    "waveform" "bytea",
    "is_published" boolean DEFAULT true NOT NULL,
    "usage_count" integer DEFAULT 1 NOT NULL,
    "display_name" "text",
    "bus_type" "text" DEFAULT 'loops'::"text" NOT NULL,
    "bus_index" "text",
    "track_index" "text",
    "instrument_name" "text",
    "instrument_family" "text",
    "pattern_type" "text",
    "bpm" smallint,
    "key" smallint,
    "scale_quality" "text",
    "mood" "text",
    "time_signature_numerator" smallint,
    "time_signature_denominator" smallint,
    "duration_seconds" real,
    "search_tokens" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "sample_id" "text",
    "pitch_shift" smallint,
    "is_reverse" boolean DEFAULT false NOT NULL,
    "pattern" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "envelope" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "swell" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "humanize" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "delay" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "source_stem_id" "uuid",
    "source_bus_id" "uuid",
    "source_track_id" "uuid",
    "phrase_index" integer,
    "section" "text",
    "attributes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "phrase_config_jsonb" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "chords" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_unique" boolean DEFAULT true NOT NULL,
    "identity_hash" "text",
    "stem_type" "text" NOT NULL,
    CONSTRAINT "market_patterns_audio_url_not_blank" CHECK (("length"(TRIM(BOTH FROM "audio_url")) > 0)),
    CONSTRAINT "market_patterns_coordinates_is_object" CHECK (("jsonb_typeof"("song_config_coordinates") = 'object'::"text")),
    CONSTRAINT "market_patterns_delay_is_object" CHECK (("jsonb_typeof"("delay") = 'object'::"text")),
    CONSTRAINT "market_patterns_envelope_is_object" CHECK (("jsonb_typeof"("envelope") = 'object'::"text")),
    CONSTRAINT "market_patterns_hash_version_check" CHECK (("hash_version" > 0)),
    CONSTRAINT "market_patterns_humanize_is_object" CHECK (("jsonb_typeof"("humanize") = 'object'::"text")),
    CONSTRAINT "market_patterns_identity_is_object" CHECK (("jsonb_typeof"("loop_identity_config") = 'object'::"text")),
    CONSTRAINT "market_patterns_meta_is_object" CHECK (("jsonb_typeof"("meta") = 'object'::"text")),
    CONSTRAINT "market_patterns_pattern_is_object" CHECK (("jsonb_typeof"("pattern") = 'object'::"text")),
    CONSTRAINT "market_patterns_phrase_config_is_object" CHECK (("jsonb_typeof"("phrase_config_jsonb") = 'object'::"text")),
    CONSTRAINT "market_patterns_stem_type_check" CHECK (("stem_type" = ANY (ARRAY['harmony'::"text", 'melody'::"text", 'bass'::"text", 'auxiliary'::"text", 'drums'::"text", 'swells'::"text"]))),
    CONSTRAINT "market_patterns_swell_is_object" CHECK (("jsonb_typeof"("swell") = 'object'::"text")),
    CONSTRAINT "market_patterns_usage_count_check" CHECK (("usage_count" >= 1))
);


