COMMENT ON COLUMN "public"."market_patterns"."stem_type" IS 'Actual SongV2 stem type derived from song_config_coordinates.';



CREATE OR REPLACE FUNCTION "public"."market_pattern_embedding_description"("source" "public"."market_patterns") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE STRICT PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  normalized_tokens jsonb;
  fields jsonb;
  documents jsonb;
  meta_document text;
  field_order constant text[] := ARRAY[
    'instrument_name', 'instrument_family', 'pattern_type', 'bpm', 'key',
    'scale_quality', 'mood', 'time_signature_numerator',
    'time_signature_denominator', 'duration_seconds', 'search_tokens',
    'sample_id', 'pitch_shift', 'is_reverse', 'pattern', 'envelope',
    'swell', 'humanize', 'delay', 'chords'
  ];
BEGIN
  SELECT COALESCE(jsonb_agg(token ORDER BY token COLLATE "C"), '[]'::jsonb)
  INTO normalized_tokens
  FROM (
    SELECT DISTINCT lower(btrim(regexp_replace(raw_token, '[[:space:]]+', ' ', 'g'))) AS token
    FROM unnest(source.search_tokens) AS raw(raw_token)
    WHERE btrim(regexp_replace(raw_token, '[[:space:]]+', ' ', 'g')) <> ''
  ) AS normalized;

  fields := jsonb_build_object(
    'instrument_name', CASE WHEN source.instrument_name IS NULL THEN NULL ELSE btrim(regexp_replace(source.instrument_name, '[[:space:]]+', ' ', 'g')) END,
    'instrument_family', CASE WHEN source.instrument_family IS NULL THEN NULL ELSE btrim(regexp_replace(source.instrument_family, '[[:space:]]+', ' ', 'g')) END,
    'pattern_type', CASE WHEN source.pattern_type IS NULL THEN NULL ELSE btrim(regexp_replace(source.pattern_type, '[[:space:]]+', ' ', 'g')) END,
    'bpm', source.bpm, 'key', source.key,
    'scale_quality', CASE WHEN source.scale_quality IS NULL THEN NULL ELSE btrim(regexp_replace(source.scale_quality, '[[:space:]]+', ' ', 'g')) END,
    'mood', CASE WHEN source.mood IS NULL THEN NULL ELSE btrim(regexp_replace(source.mood, '[[:space:]]+', ' ', 'g')) END,
    'time_signature_numerator', source.time_signature_numerator,
    'time_signature_denominator', source.time_signature_denominator,
    'duration_seconds', source.duration_seconds, 'search_tokens', normalized_tokens,
    'sample_id', CASE WHEN source.sample_id IS NULL THEN NULL ELSE btrim(regexp_replace(source.sample_id, '[[:space:]]+', ' ', 'g')) END,
    'pitch_shift', source.pitch_shift, 'is_reverse', source.is_reverse,
    'pattern', source.pattern, 'envelope', source.envelope, 'swell', source.swell,
    'humanize', source.humanize, 'delay', source.delay, 'chords', source.chords
  );

  documents := jsonb_build_object(
    'instrument_name', CASE WHEN NULLIF(fields->>'instrument_name', '') IS NULL THEN NULL ELSE 'instrument_name: ' || (fields->>'instrument_name') END,
    'instrument_family', CASE WHEN NULLIF(fields->>'instrument_family', '') IS NULL THEN NULL ELSE 'instrument_family: ' || (fields->>'instrument_family') END,
    'pattern_type', CASE WHEN NULLIF(fields->>'pattern_type', '') IS NULL THEN NULL ELSE 'pattern_type: ' || (fields->>'pattern_type') END,
    'bpm', CASE WHEN source.bpm IS NULL THEN NULL ELSE 'bpm: ' || source.bpm::text END,
    'key', CASE WHEN source.key IS NULL THEN NULL ELSE 'key: ' || source.key::text END,
    'scale_quality', CASE WHEN NULLIF(fields->>'scale_quality', '') IS NULL THEN NULL ELSE 'scale_quality: ' || (fields->>'scale_quality') END,
    'mood', CASE WHEN NULLIF(fields->>'mood', '') IS NULL THEN NULL ELSE 'mood: ' || (fields->>'mood') END,
    'time_signature_numerator', CASE WHEN source.time_signature_numerator IS NULL THEN NULL ELSE 'time_signature_numerator: ' || source.time_signature_numerator::text END,
    'time_signature_denominator', CASE WHEN source.time_signature_denominator IS NULL THEN NULL ELSE 'time_signature_denominator: ' || source.time_signature_denominator::text END,
    'duration_seconds', CASE WHEN source.duration_seconds IS NULL THEN NULL ELSE 'duration_seconds: ' || source.duration_seconds::text END,
    'search_tokens', CASE WHEN jsonb_array_length(normalized_tokens) = 0 THEN NULL ELSE 'search_tokens: ' || (SELECT string_agg(token, ', ' ORDER BY token COLLATE "C") FROM jsonb_array_elements_text(normalized_tokens) AS token) END,
    'sample_id', CASE WHEN NULLIF(fields->>'sample_id', '') IS NULL THEN NULL ELSE 'sample_id: ' || (fields->>'sample_id') END,
    'pitch_shift', CASE WHEN source.pitch_shift IS NULL THEN NULL ELSE 'pitch_shift: ' || source.pitch_shift::text END,
    'is_reverse', 'is_reverse: ' || source.is_reverse::text,
    'pattern', CASE WHEN source.pattern IN ('{}'::jsonb, '[]'::jsonb, 'null'::jsonb) THEN NULL ELSE 'pattern: ' || public.market_pattern_stable_json(source.pattern) END,
    'envelope', CASE WHEN source.envelope IN ('{}'::jsonb, '[]'::jsonb, 'null'::jsonb) THEN NULL ELSE 'envelope: ' || public.market_pattern_stable_json(source.envelope) END,
    'swell', CASE WHEN source.swell IN ('{}'::jsonb, '[]'::jsonb, 'null'::jsonb) THEN NULL ELSE 'swell: ' || public.market_pattern_stable_json(source.swell) END,
    'humanize', CASE WHEN source.humanize IN ('{}'::jsonb, '[]'::jsonb, 'null'::jsonb) THEN NULL ELSE 'humanize: ' || public.market_pattern_stable_json(source.humanize) END,
    'delay', CASE WHEN source.delay IN ('{}'::jsonb, '[]'::jsonb, 'null'::jsonb) THEN NULL ELSE 'delay: ' || public.market_pattern_stable_json(source.delay) END,
    'chords', CASE WHEN source.chords IN ('{}'::jsonb, '[]'::jsonb, 'null'::jsonb) THEN NULL ELSE 'chords: ' || public.market_pattern_stable_json(source.chords) END
  );

  SELECT string_agg(doc, E'\n' ORDER BY ordinality)
  INTO meta_document
  FROM unnest(field_order) WITH ORDINALITY AS ordered(field_name, ordinality)
  CROSS JOIN LATERAL (SELECT documents->>ordered.field_name AS doc) AS selected
  WHERE doc IS NOT NULL;

  RETURN jsonb_build_object(
    'sourceVersion', 'market-pattern-embedding-source-v1',
    'fields', fields,
    'documents', jsonb_build_object('meta', meta_document) || documents
  );
END;
$$;


ALTER FUNCTION "public"."market_pattern_embedding_description"("source" "public"."market_patterns") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."market_pattern_embedding_source_hash"("source" "public"."market_patterns") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
  SELECT encode(
    extensions.digest(
      convert_to(
        public.market_pattern_stable_json(
          public.market_pattern_embedding_description(source)
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;


ALTER FUNCTION "public"."market_pattern_embedding_source_hash"("source" "public"."market_patterns") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."market_pattern_stable_json"("value" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'public'
    SET "extra_float_digits" TO '1'
    AS $$
  SELECT CASE jsonb_typeof(value)
    WHEN 'object' THEN
      '{' || COALESCE((
        SELECT string_agg(
          to_jsonb(entry.key)::text || ':' || public.market_pattern_stable_json(entry.value),
          ',' ORDER BY entry.key COLLATE "C"
        )
        FROM jsonb_each(value) AS entry
      ), '') || '}'
    WHEN 'array' THEN
      '[' || COALESCE((
        SELECT string_agg(
          public.market_pattern_stable_json(item.value),
          ',' ORDER BY item.ordinality
        )
        FROM jsonb_array_elements(value) WITH ORDINALITY AS item(value, ordinality)
      ), '') || ']'
    WHEN 'number' THEN
      CASE
        WHEN (value #>> '{}')::double precision = 0 THEN '0'
        ELSE trim_scale(
          ((value #>> '{}')::double precision)::text::numeric
        )::text
      END
    ELSE value::text
  END;
$$;


ALTER FUNCTION "public"."market_pattern_stable_json"("value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."market_pattern_stem_type_from_coordinates"("p_market_song_id" "uuid", "p_coordinates" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_stem_type text;
  v_match_count integer;
BEGIN
  SELECT
    count(*)::integer,
    min(stem.value ->> 'type')
  INTO
    v_match_count,
    v_stem_type
  FROM public.market_song_configs AS config
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(config.song_v2 -> 'stems') = 'array'
        THEN config.song_v2 -> 'stems'
      ELSE '[]'::jsonb
    END
  ) AS stem(value)
  WHERE config.market_song_id = p_market_song_id
    AND stem.value ->> 'busType' = p_coordinates ->> 'bus_type'
    AND EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(stem.value -> 'busIndices') = 'array'
            THEN stem.value -> 'busIndices'
          ELSE '[]'::jsonb
        END
      ) AS bus_index(value)
      WHERE bus_index.value = p_coordinates ->> 'bus_index'
    );

  IF v_match_count <> 1 THEN
    RAISE EXCEPTION
      'Expected exactly one stem for market song % and coordinates %, found %',
      p_market_song_id,
      p_coordinates,
      v_match_count
      USING ERRCODE = '23514';
  END IF;

  IF v_stem_type NOT IN (
    'harmony',
    'melody',
    'bass',
    'auxiliary',
    'drums',
    'swells'
  ) THEN
    RAISE EXCEPTION
      'Unsupported stem type "%" for market song % and coordinates %',
      v_stem_type,
      p_market_song_id,
      p_coordinates
      USING ERRCODE = '23514';
  END IF;

  RETURN v_stem_type;
END;
$$;


ALTER FUNCTION "public"."market_pattern_stem_type_from_coordinates"("p_market_song_id" "uuid", "p_coordinates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_instrument_audio_profiles_v1"("anchor_instrument_id" "uuid", "p_match_count" integer DEFAULT 10, "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text") RETURNS TABLE("instrument_v2_id" "uuid", "name" "text", "instrument_family" "text", "instrument_type" "text", "collection" "text", "contributor_slug" "text", "distance" double precision, "similarity" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH anchor AS (
    SELECT profile.embedding
    FROM public.instrument_audio_profile_v1 AS profile
    INNER JOIN public.instruments_v2 AS instrument
      ON instrument.id = profile.instrument_v2_id
    WHERE profile.instrument_v2_id = anchor_instrument_id
      AND profile.profile_version = p_profile_version
      AND instrument.published
      AND profile.embedding IS NOT NULL
      AND profile.source_signature IS NOT DISTINCT FROM
        public.compute_instrument_audio_profile_signature_v1(
          instrument.id,
          profile.profile_version
        )
    LIMIT 1
  )
  SELECT
    instrument.id AS instrument_v2_id,
    instrument.name,
    instrument.instrument_family,
    instrument.instrument_type,
    instrument.collection,
    contributor.slug AS contributor_slug,
    (
      profile.embedding OPERATOR(extensions.<=>) anchor.embedding
    )::double precision AS distance,
    (
      1 - (profile.embedding OPERATOR(extensions.<=>) anchor.embedding)
    )::double precision AS similarity
  FROM anchor
  INNER JOIN public.instrument_audio_profile_v1 AS profile
    ON profile.embedding IS NOT NULL
  INNER JOIN public.instruments_v2 AS instrument
    ON instrument.id = profile.instrument_v2_id
  LEFT JOIN public.contributors AS contributor
    ON contributor.id = instrument.contributor_id
  WHERE instrument.published
    AND profile.profile_version = p_profile_version
    AND profile.instrument_v2_id <> anchor_instrument_id
    AND profile.source_signature IS NOT DISTINCT FROM
      public.compute_instrument_audio_profile_signature_v1(
        instrument.id,
        profile.profile_version
      )
    AND profile.spectral_centroid_median IS NOT NULL
    AND profile.spectral_contrast_median IS NOT NULL
  ORDER BY
    profile.embedding OPERATOR(extensions.<=>) anchor.embedding,
    instrument.id
  LIMIT LEAST(GREATEST(COALESCE(p_match_count, 10), 1), 100);
$$;


ALTER FUNCTION "public"."match_instrument_audio_profiles_v1"("anchor_instrument_id" "uuid", "p_match_count" integer, "p_profile_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_market_loop_sample_neighbors_v1"("anchor_instrument_ids" "uuid"[], "candidate_instrument_ids" "uuid"[], "p_match_count" integer DEFAULT 10, "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text") RETURNS TABLE("anchor_instrument_v2_id" "uuid", "candidate_instrument_v2_id" "uuid", "rank" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  WITH requested_anchors AS (
    SELECT DISTINCT anchor_id
    FROM unnest(COALESCE(anchor_instrument_ids, '{}'::uuid[])) AS anchor_id
  ),
  anchors AS (
    SELECT
      p.instrument_v2_id,
      p.embedding,
      i.engine_type,
      i.playback_type,
      lower(btrim(i.instrument_family)) AS instrument_family
    FROM requested_anchors requested
    JOIN public.instrument_audio_profile_v1 p
      ON p.instrument_v2_id = requested.anchor_id
    JOIN public.instruments_v2 i
      ON i.id = p.instrument_v2_id
    WHERE i.published = true
      AND NULLIF(btrim(i.instrument_family), '') IS NOT NULL
      AND p.profile_version = p_profile_version
      AND p.embedding IS NOT NULL
      AND p.spectral_centroid_median IS NOT NULL
      AND p.spectral_contrast_median IS NOT NULL
      AND p.sample_count > 0
      AND p.analyzed_sample_count * 5 >= p.sample_count * 4
      AND COALESCE(
        p.quality_report ->> 'qualityState',
        p.quality_report ->> 'state',
        'complete'
      ) NOT IN ('failed', 'skipped')
  ),
  candidates AS (
    SELECT
      p.instrument_v2_id,
      p.embedding,
      i.engine_type,
      i.playback_type,
      lower(btrim(i.instrument_family)) AS instrument_family
    FROM public.instrument_audio_profile_v1 p
    JOIN public.instruments_v2 i
      ON i.id = p.instrument_v2_id
    WHERE i.published = true
      AND NULLIF(btrim(i.instrument_family), '') IS NOT NULL
      AND p.profile_version = p_profile_version
      AND p.embedding IS NOT NULL
      AND p.spectral_centroid_median IS NOT NULL
      AND p.spectral_contrast_median IS NOT NULL
      AND p.sample_count > 0
      AND p.analyzed_sample_count * 5 >= p.sample_count * 4
      AND COALESCE(
        p.quality_report ->> 'qualityState',
        p.quality_report ->> 'state',
        'complete'
      ) NOT IN ('failed', 'skipped')
      AND (
        COALESCE(cardinality(candidate_instrument_ids), 0) = 0
        OR p.instrument_v2_id = ANY(candidate_instrument_ids)
      )
  ),
  ranked AS (
    SELECT
      anchors.instrument_v2_id AS anchor_instrument_v2_id,
      candidates.instrument_v2_id AS candidate_instrument_v2_id,
      row_number() OVER (
        PARTITION BY anchors.instrument_v2_id
        ORDER BY
          anchors.embedding <=> candidates.embedding,
          candidates.instrument_v2_id
      )::integer AS rank
    FROM anchors
    JOIN candidates
      ON candidates.engine_type = anchors.engine_type
      AND candidates.playback_type = anchors.playback_type
      AND candidates.instrument_family = anchors.instrument_family
      AND candidates.instrument_v2_id <> anchors.instrument_v2_id
  )
  SELECT
    anchor_instrument_v2_id,
    candidate_instrument_v2_id,
    rank
  FROM ranked
  WHERE rank <= LEAST(GREATEST(COALESCE(p_match_count, 10), 1), 50)
  ORDER BY anchor_instrument_v2_id, rank, candidate_instrument_v2_id;
$$;


ALTER FUNCTION "public"."match_market_loop_sample_neighbors_v1"("anchor_instrument_ids" "uuid"[], "candidate_instrument_ids" "uuid"[], "p_match_count" integer, "p_profile_version" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."match_market_loop_sample_neighbors_v1"("anchor_instrument_ids" "uuid"[], "candidate_instrument_ids" "uuid"[], "p_match_count" integer, "p_profile_version" "text") IS 'Returns conservative Market Loop source/sample neighbors. Empty candidates search the verified published corpus with matching instrument family, engine, and playback behavior.';



CREATE OR REPLACE FUNCTION "public"."match_market_loop_sample_neighbors_v2"("anchor_instrument_ids" "uuid"[], "candidate_instrument_ids" "uuid"[], "p_match_count" integer DEFAULT 10, "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text") RETURNS TABLE("anchor_instrument_v2_id" "uuid", "candidate_instrument_v2_id" "uuid", "rank" integer, "candidate_name" "text", "candidate_instrument_family" "text", "candidate_instrument_type" "text", "candidate_engine_type" "text", "candidate_playback_type" "text", "candidate_collection" "text", "candidate_contributor_slug" "text", "candidate_range_lower" integer, "candidate_range_upper" integer, "candidate_single_pitch" integer, "candidate_available_pitches" integer[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  WITH requested_anchors AS (
    SELECT DISTINCT anchor_id FROM unnest(COALESCE(anchor_instrument_ids, '{}'::uuid[])) AS anchor_id
  ),
  eligible AS (
    SELECT p.instrument_v2_id, p.embedding, i.engine_type, i.playback_type,
      lower(btrim(i.instrument_family)) AS instrument_family, i.name, i.instrument_type,
      i.collection, NULL::text AS contributor_slug, i.range_lower, i.range_upper, i.single_pitch
    FROM public.instrument_audio_profile_v1 p
    JOIN public.instruments_v2 i ON i.id = p.instrument_v2_id
    WHERE i.published = true
      AND NULLIF(btrim(i.instrument_family), '') IS NOT NULL
      AND p.profile_version = p_profile_version AND p.embedding IS NOT NULL
      AND p.spectral_centroid_median IS NOT NULL AND p.spectral_contrast_median IS NOT NULL
      AND p.sample_count > 0 AND p.analyzed_sample_count * 5 >= p.sample_count * 4
      AND COALESCE(p.quality_report ->> 'qualityState', p.quality_report ->> 'state', 'complete') NOT IN ('failed', 'skipped')
  ),
  anchors AS (SELECT e.* FROM requested_anchors r JOIN eligible e ON e.instrument_v2_id = r.anchor_id),
  candidates AS (
    SELECT e.* FROM eligible e
    WHERE COALESCE(cardinality(candidate_instrument_ids), 0) = 0
       OR e.instrument_v2_id = ANY(candidate_instrument_ids)
  ),
  ranked AS (
    SELECT a.instrument_v2_id AS anchor_instrument_v2_id, c.instrument_v2_id AS candidate_instrument_v2_id,
      row_number() OVER (PARTITION BY a.instrument_v2_id ORDER BY a.embedding <=> c.embedding, c.instrument_v2_id)::integer AS rank,
      c.name, c.instrument_family, c.instrument_type, c.engine_type, c.playback_type,
      c.collection, c.contributor_slug, c.range_lower, c.range_upper, c.single_pitch
    FROM anchors a JOIN candidates c
      ON c.engine_type = a.engine_type AND c.playback_type = a.playback_type
      AND c.instrument_family = a.instrument_family AND c.instrument_v2_id <> a.instrument_v2_id
  )
  SELECT r.anchor_instrument_v2_id, r.candidate_instrument_v2_id, r.rank,
    r.name, r.instrument_family, r.instrument_type, r.engine_type, r.playback_type,
    r.collection, r.contributor_slug, r.range_lower, r.range_upper, r.single_pitch,
    COALESCE((SELECT array_agg(DISTINCT spc.midi_note::integer ORDER BY spc.midi_note::integer)
      FROM public.sample_path_constructs spc
      WHERE spc.instrument_v2_id = r.candidate_instrument_v2_id AND spc.midi_note IS NOT NULL), ARRAY[]::integer[])
  FROM ranked r
  WHERE r.rank <= LEAST(GREATEST(COALESCE(p_match_count, 10), 1), 50)
  ORDER BY r.anchor_instrument_v2_id, r.rank, r.candidate_instrument_v2_id;
$$;


ALTER FUNCTION "public"."match_market_loop_sample_neighbors_v2"("anchor_instrument_ids" "uuid"[], "candidate_instrument_ids" "uuid"[], "p_match_count" integer, "p_profile_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_market_loop_sample_neighbors_v3"("anchor_instrument_ids" "uuid"[], "candidate_instrument_ids" "uuid"[], "p_match_count" integer DEFAULT 10, "p_profile_version" "text" DEFAULT 'audio-profile-v1'::"text", "p_min_compatibility_score" double precision DEFAULT 0.7) RETURNS TABLE("anchor_instrument_v2_id" "uuid", "candidate_instrument_v2_id" "uuid", "rank" integer, "candidate_name" "text", "candidate_instrument_family" "text", "candidate_instrument_type" "text", "candidate_engine_type" "text", "candidate_playback_type" "text", "candidate_collection" "text", "candidate_contributor_slug" "text", "candidate_range_lower" integer, "candidate_range_upper" integer, "candidate_single_pitch" integer, "candidate_available_pitches" integer[], "compatibility_score" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  WITH params AS (
    SELECT
      LEAST(GREATEST(COALESCE(p_match_count, 10), 1), 50)::integer AS match_count,
      LEAST(GREATEST(COALESCE(p_min_compatibility_score, 0.7), 0), 1)::double precision
        AS min_compatibility_score
  ),
  requested_anchors AS (
    SELECT DISTINCT anchor_id
    FROM unnest(COALESCE(anchor_instrument_ids, '{}'::uuid[])) AS anchor_id
  ),
  eligible AS (
    SELECT
      p.instrument_v2_id,
      p.embedding,
      i.engine_type,
      i.playback_type,
      lower(btrim(i.instrument_family)) AS instrument_family,
      i.name,
      i.instrument_type,
      i.collection,
      NULL::text AS contributor_slug,
      i.range_lower,
      i.range_upper,
      i.single_pitch,
      ARRAY[
        p.attack_time_ms_median,
        p.decay_time_ms_median,
        p.effective_duration_median,
        p.spectral_flux_mean_median
      ]::double precision[] AS temporal_values,
      ARRAY[
        p.spectral_centroid_median,
        p.spectral_contrast_median,
        p.spectral_flatness_median
      ]::double precision[] AS spectral_values,
      ARRAY[
        p.hp_ratio_median,
        p.inharmonicity_median,
        p.pitch_stability_median,
        p.vibrato_depth_hz_median
      ]::double precision[] AS character_values
    FROM public.instrument_audio_profile_v1 p
    JOIN public.instruments_v2 i ON i.id = p.instrument_v2_id
    WHERE i.published = true
      AND NULLIF(btrim(i.instrument_family), '') IS NOT NULL
      AND p.profile_version = p_profile_version
      AND p.embedding IS NOT NULL
      AND p.spectral_centroid_median IS NOT NULL
      AND p.spectral_contrast_median IS NOT NULL
      AND p.sample_count > 0
      AND p.analyzed_sample_count * 5 >= p.sample_count * 4
      AND COALESCE(
        p.quality_report ->> 'qualityState',
        p.quality_report ->> 'state',
        'complete'
      ) NOT IN ('failed', 'skipped')
  ),
  anchors AS (
    SELECT e.*
    FROM requested_anchors r
    JOIN eligible e ON e.instrument_v2_id = r.anchor_id
  ),
  candidates AS (
    SELECT e.*
    FROM eligible e
    WHERE COALESCE(cardinality(candidate_instrument_ids), 0) = 0
       OR e.instrument_v2_id = ANY(candidate_instrument_ids)
  ),
  ranked AS (
    SELECT
      a.instrument_v2_id AS anchor_instrument_v2_id,
      c.instrument_v2_id AS candidate_instrument_v2_id,
      row_number() OVER (
        PARTITION BY a.instrument_v2_id
        ORDER BY a.embedding <=> c.embedding, c.instrument_v2_id
      )::integer AS rank,
      c.name,
      c.instrument_family,
      c.instrument_type,
      c.engine_type,
      c.playback_type,
      c.collection,
      c.contributor_slug,
      c.range_lower,
      c.range_upper,
      c.single_pitch,
      a.temporal_values AS anchor_temporal_values,
      c.temporal_values AS candidate_temporal_values,
      a.spectral_values AS anchor_spectral_values,
      c.spectral_values AS candidate_spectral_values,
      a.character_values AS anchor_character_values,
      c.character_values AS candidate_character_values,
      params.match_count,
      params.min_compatibility_score
    FROM anchors a
    JOIN candidates c
      ON c.engine_type = a.engine_type
      AND c.playback_type = a.playback_type
      AND c.instrument_family = a.instrument_family
      AND c.instrument_v2_id <> a.instrument_v2_id
    CROSS JOIN params
  ),
  scored AS (
    SELECT
      r.*,
      public.score_market_loop_profile_compatibility_v1(
        r.anchor_temporal_values,
        r.candidate_temporal_values,
        r.anchor_spectral_values,
        r.candidate_spectral_values,
        r.anchor_character_values,
        r.candidate_character_values,
        r.rank,
        r.match_count
      ) AS compatibility_score
    FROM ranked r
  )
  SELECT
    s.anchor_instrument_v2_id,
    s.candidate_instrument_v2_id,
    s.rank,
    s.name,
    s.instrument_family,
    s.instrument_type,
    s.engine_type,
    s.playback_type,
    s.collection,
    s.contributor_slug,
    s.range_lower,
    s.range_upper,
    s.single_pitch,
    COALESCE(
      (
        SELECT array_agg(DISTINCT spc.midi_note::integer ORDER BY spc.midi_note::integer)
        FROM public.sample_path_constructs spc
        WHERE spc.instrument_v2_id = s.candidate_instrument_v2_id
          AND spc.midi_note IS NOT NULL
      ),
      ARRAY[]::integer[]
    ),
    s.compatibility_score
  FROM scored s
  WHERE s.rank <= s.match_count
    AND s.compatibility_score >= s.min_compatibility_score
  ORDER BY s.anchor_instrument_v2_id, s.rank, s.candidate_instrument_v2_id;
$$;


ALTER FUNCTION "public"."match_market_loop_sample_neighbors_v3"("anchor_instrument_ids" "uuid"[], "candidate_instrument_ids" "uuid"[], "p_match_count" integer, "p_profile_version" "text", "p_min_compatibility_score" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_song_by_characteristics"("query_embedding" "extensions"."vector", "match_count" integer DEFAULT NULL::integer) RETURNS TABLE("song_id" bigint, "similarity" double precision)
    LANGUAGE "plpgsql"
    AS $$
#variable_conflict use_column
begin
  return query
  select
    song_characteristics.song_id,
    1 - (song_characteristics.formatted_embedding <=> query_embedding) as similarity
  from song_characteristics
  order by song_characteristics.formatted_embedding <=> query_embedding
  limit match_count;
end;
$$;


ALTER FUNCTION "public"."match_song_by_characteristics"("query_embedding" "extensions"."vector", "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pack_waveform_jsonb_to_bytea"("wave" "jsonb") RETURNS "bytea"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  with pts as (
    select
      ord,
      greatest(
        0,
        least(
          100,
          case
            when value ~ '^-?[0-9]+$' then value::int
            else 0
          end
        )
      ) as v
    from jsonb_array_elements_text(
      case
        when jsonb_typeof(coalesce(wave, '[]'::jsonb)) = 'array'
          then coalesce(wave, '[]'::jsonb)
        else '[]'::jsonb
      end
    ) with ordinality t(value, ord)
  )
  select decode(
    coalesce(string_agg(lpad(to_hex(v), 2, '0'), '' order by ord), ''),
    'hex'
  )
  from pts;
$_$;


ALTER FUNCTION "public"."pack_waveform_jsonb_to_bytea"("wave" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."progression_signature_from_json"("prog" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select string_agg(
    concat_ws(
      ':',
      coalesce(elem->>'root', '0'),
      coalesce(elem->>'inversion', '0'),
      coalesce(elem->>'rootModification', '0'),
      coalesce(elem->>'quality', 'default')
    ),
    '|' order by ord
  )
  from jsonb_array_elements(
    case
      when jsonb_typeof(coalesce(prog, '[]'::jsonb)) = 'array'
        then coalesce(prog, '[]'::jsonb)
      else '[]'::jsonb
    end
  ) with ordinality t(elem, ord);
$$;


ALTER FUNCTION "public"."progression_signature_from_json"("prog" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_instrument_discovery_candidate"("p_instrument_generation" "uuid", "p_tag_generation" "uuid", "p_cue_generation" "uuid", "p_characteristic_generation" "uuid", "p_expected_instrument_generation" "uuid", "p_expected_tag_generation" "uuid", "p_expected_cue_generation" "uuid", "p_expected_characteristic_generation" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
<<promotion>>
DECLARE
  promoted_at timestamptz := pg_catalog.clock_timestamp();
  current_source_revision bigint;
  current_instrument_generation uuid;
  current_tag_generation uuid;
  current_cue_generation uuid;
  current_characteristic_generation uuid;
  current_manifest_revision text;
  current_generated_at timestamptz;
  candidate_instrument_revision text;
  instrument_checksum text;
  tag_checksum text;
  cue_checksum text;
  characteristic_checksum text;
  resource_checksum text;
  manifest_revision text;
  descriptor record;
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(2173, 1);

  SELECT state.source_revision,
    state.instrument_generation,
    state.tag_generation,
    state.cue_generation,
    state.characteristic_generation,
    state.manifest_revision,
    state.generated_at
  INTO current_source_revision,
    current_instrument_generation,
    current_tag_generation,
    current_cue_generation,
    current_characteristic_generation,
    current_manifest_revision,
    current_generated_at
  FROM browser_catalog.instrument_discovery_state AS state
  WHERE state.singleton
  FOR UPDATE;

  IF current_instrument_generation IS NOT DISTINCT FROM p_instrument_generation
    AND current_tag_generation IS NOT DISTINCT FROM p_tag_generation
    AND current_cue_generation IS NOT DISTINCT FROM p_cue_generation
    AND current_characteristic_generation IS NOT DISTINCT FROM
      p_characteristic_generation
  THEN
    RETURN jsonb_build_object(
      'publicationStatus', 'current',
      'sourceRevision', current_source_revision,
      'instrumentGeneration', current_instrument_generation,
      'tagGeneration', current_tag_generation,
      'cueGeneration', current_cue_generation,
      'characteristicGeneration', current_characteristic_generation,
      'expectedInstrumentGeneration', current_instrument_generation,
      'expectedTagGeneration', current_tag_generation,
      'expectedCueGeneration', current_cue_generation,
      'expectedCharacteristicGeneration', current_characteristic_generation,
      'manifestRevision', current_manifest_revision,
      'generatedAt', current_generated_at
    );
  END IF;

  IF current_instrument_generation IS DISTINCT FROM
      p_expected_instrument_generation
    OR current_tag_generation IS DISTINCT FROM p_expected_tag_generation
    OR current_cue_generation IS DISTINCT FROM p_expected_cue_generation
    OR current_characteristic_generation IS DISTINCT FROM
      p_expected_characteristic_generation
  THEN
    RAISE EXCEPTION 'Instrument Discovery active tuple changed before promotion';
  END IF;

  PERFORM browser_catalog.cleanup_instrument_discovery_expired(promoted_at, 16);

  SELECT revision
  INTO current_source_revision
  FROM public.catalog_cache_resource_revisions
  WHERE resource = 'instruments'
  FOR UPDATE;

  SELECT source_revision
  INTO candidate_instrument_revision
  FROM browser_catalog.instrument_discovery_resource_generations
  WHERE resource_key = 'instruments'
    AND generation = p_instrument_generation
    AND (
      publication_status = 'staging'
      OR EXISTS (
        SELECT 1
        FROM browser_catalog.instrument_discovery_state
        WHERE singleton
          AND instrument_generation = p_instrument_generation
      )
    );

  IF candidate_instrument_revision IS NULL
    OR candidate_instrument_revision IS DISTINCT FROM
      'catalog-instruments:' || current_source_revision::text
    OR NOT EXISTS (
      SELECT 1
      FROM browser_catalog.instrument_discovery_resource_generations
      WHERE resource_key = 'tags'
        AND generation = p_tag_generation
        AND source_revision =
          'catalog-tags:' || current_source_revision::text
        AND instrument_revision = promotion.candidate_instrument_revision
    )
    OR NOT EXISTS (
      SELECT 1
      FROM browser_catalog.instrument_discovery_resource_generations
      WHERE resource_key = 'cues'
        AND generation = p_cue_generation
        AND source_revision =
          'catalog-cues:' || current_source_revision::text
        AND instrument_revision = promotion.candidate_instrument_revision
    )
    OR NOT EXISTS (
      SELECT 1
      FROM browser_catalog.instrument_discovery_resource_generations
      WHERE resource_key = 'characteristics'
        AND generation = p_characteristic_generation
        AND (
          publication_status = 'sealed'
          OR instrument_revision = promotion.candidate_instrument_revision
        )
    )
    OR (
      SELECT count(*)
      FROM browser_catalog.instrument_discovery_resource_generations
      WHERE (resource_key, generation) IN (
        ('instruments', p_instrument_generation),
        ('tags', p_tag_generation),
        ('cues', p_cue_generation),
        ('characteristics', p_characteristic_generation)
      )
    ) <> 4
    OR EXISTS (
      SELECT 1
      FROM browser_catalog.instrument_discovery_resource_generations AS generation
      CROSS JOIN browser_catalog.instrument_discovery_state AS state
      WHERE state.singleton
        AND (generation.resource_key, generation.generation) IN (
          ('instruments', p_instrument_generation),
          ('tags', p_tag_generation),
          ('cues', p_cue_generation),
          ('characteristics', p_characteristic_generation)
        )
        AND generation.publication_status = 'sealed'
        AND NOT (
          (generation.resource_key = 'instruments'
            AND generation.generation = state.instrument_generation)
          OR (generation.resource_key = 'tags'
            AND generation.generation = state.tag_generation)
          OR (generation.resource_key = 'cues'
            AND generation.generation = state.cue_generation)
          OR (generation.resource_key = 'characteristics'
            AND generation.generation = state.characteristic_generation)
          OR state.instrument_generation IS NULL
        )
    )
  THEN
    RAISE EXCEPTION 'Instrument Discovery candidate dependency identity changed before promotion';
  END IF;

  FOR descriptor IN
    SELECT generation.*
    FROM browser_catalog.instrument_discovery_resource_generations AS generation
    WHERE (generation.resource_key, generation.generation) IN (
      ('instruments', p_instrument_generation),
      ('tags', p_tag_generation),
      ('cues', p_cue_generation),
      ('characteristics', p_characteristic_generation)
    )
  LOOP
    IF descriptor.publication_status = 'staging' AND (
      descriptor.retained_until <= promoted_at
      OR descriptor.page_count <> (
        SELECT count(*)::integer
        FROM browser_catalog.instrument_discovery_resource_pages AS page
        WHERE page.resource_key = descriptor.resource_key
          AND page.generation = descriptor.generation
          AND page.checksum IS NOT NULL
          AND page.decoded_bytes IS NOT NULL
      )
      OR descriptor.row_count <> COALESCE((
        SELECT sum(page.row_count)::integer
        FROM browser_catalog.instrument_discovery_resource_pages AS page
        WHERE page.resource_key = descriptor.resource_key
          AND page.generation = descriptor.generation
      ), 0)
    ) THEN
      RAISE EXCEPTION 'Instrument Discovery candidate is not completely sealed';
    END IF;

    IF descriptor.resource_key = 'characteristics'
      AND descriptor.publication_status = 'staging'
      AND (
        EXISTS (
          SELECT 1
          FROM browser_catalog.instrument_discovery_characteristic_rows AS row
          WHERE row.generation = descriptor.generation
            AND row.row_checksum IS NULL
        )
        OR EXISTS (
          SELECT 1
          FROM jsonb_array_elements(descriptor.adopted) AS adoption(item)
          CROSS JOIN LATERAL (
            SELECT count(*)::integer AS row_count,
              pg_catalog.encode(
                extensions.digest(
                  COALESCE(
                    string_agg(row.row_checksum, E'\n' ORDER BY row.instrument_id),
                    ''
                  ),
                  'sha256'
                ),
                'hex'
              ) AS checksum
            FROM browser_catalog.instrument_discovery_characteristic_rows AS row
            WHERE row.generation = descriptor.generation
              AND row.characteristic_key = adoption.item ->> 'key'
          ) AS actual
          WHERE actual.row_count IS DISTINCT FROM
              (adoption.item ->> 'rowCount')::integer
            OR actual.checksum IS DISTINCT FROM adoption.item ->> 'checksum'
        )
      )
    THEN
      RAISE EXCEPTION 'Instrument Discovery Characteristic row seals do not match adoption';
    END IF;

    IF descriptor.publication_status = 'staging' THEN
      SELECT pg_catalog.encode(
        extensions.digest(
          COALESCE((
            SELECT string_agg(page.checksum, E'\n' ORDER BY page.page_index)
            FROM browser_catalog.instrument_discovery_resource_pages AS page
            WHERE page.resource_key = descriptor.resource_key
              AND page.generation = descriptor.generation
          ), ''),
          'sha256'
        ),
        'hex'
      ) INTO resource_checksum;
      UPDATE browser_catalog.instrument_discovery_resource_generations AS generation
      SET checksum = resource_checksum,
          etag = '"sha256-' || resource_checksum || '"',
          publication_status = 'sealed',
          retained_until = NULL
      WHERE generation.resource_key = descriptor.resource_key
        AND generation.generation = descriptor.generation;
    END IF;
  END LOOP;

  UPDATE browser_catalog.instrument_discovery_resource_generations
  SET retained_until = NULL
  WHERE (resource_key, generation) IN (
    ('instruments', p_instrument_generation),
    ('tags', p_tag_generation),
    ('cues', p_cue_generation),
    ('characteristics', p_characteristic_generation)
  );

  SELECT checksum INTO instrument_checksum
  FROM browser_catalog.instrument_discovery_resource_generations
  WHERE resource_key = 'instruments' AND generation = p_instrument_generation;
  SELECT checksum INTO tag_checksum
  FROM browser_catalog.instrument_discovery_resource_generations
  WHERE resource_key = 'tags' AND generation = p_tag_generation;
  SELECT checksum INTO cue_checksum
  FROM browser_catalog.instrument_discovery_resource_generations
  WHERE resource_key = 'cues' AND generation = p_cue_generation;
  SELECT checksum INTO characteristic_checksum
  FROM browser_catalog.instrument_discovery_resource_generations
  WHERE resource_key = 'characteristics'
    AND generation = p_characteristic_generation;

  manifest_revision := 'sha256:' || pg_catalog.encode(
    extensions.digest(
      pg_catalog.concat_ws(
        E'\n',
        p_instrument_generation::text,
        instrument_checksum,
        p_tag_generation::text,
        tag_checksum,
        p_cue_generation::text,
        cue_checksum,
        p_characteristic_generation::text,
        characteristic_checksum
      ),
      'sha256'
    ),
    'hex'
  );

  UPDATE browser_catalog.instrument_discovery_resource_generations AS generation
  SET retained_until = promoted_at + interval '24 hours'
  FROM browser_catalog.instrument_discovery_state AS state
  WHERE state.singleton
    AND generation.publication_status = 'sealed'
    AND generation.retained_until IS NULL
    AND (
      (generation.resource_key = 'instruments'
        AND generation.generation = state.instrument_generation
        AND generation.generation <> p_instrument_generation)
      OR (generation.resource_key = 'tags'
        AND generation.generation = state.tag_generation
        AND generation.generation <> p_tag_generation)
      OR (generation.resource_key = 'cues'
        AND generation.generation = state.cue_generation
        AND generation.generation <> p_cue_generation)
      OR (generation.resource_key = 'characteristics'
        AND generation.generation = state.characteristic_generation
        AND generation.generation <> p_characteristic_generation)
    );

  UPDATE browser_catalog.instrument_discovery_state
  SET source_revision = current_source_revision,
      instrument_generation = p_instrument_generation,
      tag_generation = p_tag_generation,
      cue_generation = p_cue_generation,
      characteristic_generation = p_characteristic_generation,
      manifest_revision = promotion.manifest_revision,
      generated_at = promoted_at
  WHERE singleton;

  RETURN jsonb_build_object(
    'publicationStatus', 'current',
    'sourceRevision', current_source_revision,
    'instrumentGeneration', p_instrument_generation,
    'tagGeneration', p_tag_generation,
    'cueGeneration', p_cue_generation,
    'characteristicGeneration', p_characteristic_generation,
    'expectedInstrumentGeneration', p_instrument_generation,
    'expectedTagGeneration', p_tag_generation,
    'expectedCueGeneration', p_cue_generation,
    'expectedCharacteristicGeneration', p_characteristic_generation,
    'manifestRevision', manifest_revision,
    'generatedAt', promoted_at
  );
END;
$$;


ALTER FUNCTION "public"."promote_instrument_discovery_candidate"("p_instrument_generation" "uuid", "p_tag_generation" "uuid", "p_cue_generation" "uuid", "p_characteristic_generation" "uuid", "p_expected_instrument_generation" "uuid", "p_expected_tag_generation" "uuid", "p_expected_cue_generation" "uuid", "p_expected_characteristic_generation" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."promote_instrument_discovery_candidate"("p_instrument_generation" "uuid", "p_tag_generation" "uuid", "p_cue_generation" "uuid", "p_characteristic_generation" "uuid", "p_expected_instrument_generation" "uuid", "p_expected_tag_generation" "uuid", "p_expected_cue_generation" "uuid", "p_expected_characteristic_generation" "uuid") IS 'Idempotently promotes a completely sealed four-resource candidate after expected-pointer CAS, source, count, dependency, and adoption parity checks.';



CREATE OR REPLACE FUNCTION "public"."promote_sip_instruments_v2"("p_instrument_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_promotion_links" "jsonb" DEFAULT '[]'::"jsonb", "p_sample_path_construct_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_legacy_alias_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_sip_tag_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_v2_tag_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_upload_status_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_metadata_rows" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  instrument_count integer := 0;
  promotion_count integer := 0;
  sample_path_construct_count integer := 0;
  legacy_alias_count integer := 0;
  sip_tag_count integer := 0;
  v2_tag_count integer := 0;
  upload_status_count integer := 0;
  metadata_count integer := 0;
BEGIN
  p_instrument_rows := COALESCE(p_instrument_rows, '[]'::jsonb);
  p_promotion_links := COALESCE(p_promotion_links, '[]'::jsonb);
  p_sample_path_construct_rows := COALESCE(p_sample_path_construct_rows, '[]'::jsonb);
  p_legacy_alias_rows := COALESCE(p_legacy_alias_rows, '[]'::jsonb);
  p_sip_tag_rows := COALESCE(p_sip_tag_rows, '[]'::jsonb);
  p_v2_tag_rows := COALESCE(p_v2_tag_rows, '[]'::jsonb);
  p_upload_status_rows := COALESCE(p_upload_status_rows, '[]'::jsonb);
  p_metadata_rows := COALESCE(p_metadata_rows, '[]'::jsonb);

  IF jsonb_typeof(p_instrument_rows) <> 'array'
     OR jsonb_typeof(p_promotion_links) <> 'array'
     OR jsonb_typeof(p_sample_path_construct_rows) <> 'array'
     OR jsonb_typeof(p_legacy_alias_rows) <> 'array'
     OR jsonb_typeof(p_sip_tag_rows) <> 'array'
     OR jsonb_typeof(p_v2_tag_rows) <> 'array'
     OR jsonb_typeof(p_upload_status_rows) <> 'array'
     OR jsonb_typeof(p_metadata_rows) <> 'array' THEN
    RAISE EXCEPTION 'promote_sip_instruments_v2 arguments must be JSON arrays' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_instrument_rows) AS item(row_json)
    WHERE NOT (item.row_json ? 'id')
      OR NOT (item.row_json ? 'name')
      OR NOT (item.row_json ? 'contributor_id')
  ) THEN
    RAISE EXCEPTION 'instrument_rows require id, name, and contributor_id' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_promotion_links) AS item(row_json)
    WHERE NOT (item.row_json ? 'sip_review_instrument_id')
      OR NOT (item.row_json ? 'instrument_v2_id')
  ) THEN
    RAISE EXCEPTION 'promotion_links require sip_review_instrument_id and instrument_v2_id' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_sample_path_construct_rows) AS item(row_json)
    WHERE NOT (item.row_json ? 'sample_original_path_id')
      OR NOT (item.row_json ? 'instrument_v2_id')
      OR NOT (item.row_json ? 'playback_type')
      OR NULLIF(btrim(item.row_json->>'playback_type'), '') IS NULL
  ) THEN
    RAISE EXCEPTION 'sample_path_construct_rows require sample_original_path_id, instrument_v2_id, and playback_type' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_legacy_alias_rows) AS item(row_json)
    WHERE NOT (item.row_json ? 'instrument_v2_id')
      OR NOT (item.row_json ? 'legacy_instrument_id')
      OR NOT (item.row_json ? 'legacy_lookup_key')
  ) THEN
    RAISE EXCEPTION 'legacy_alias_rows require instrument_v2_id, legacy_instrument_id, and legacy_lookup_key' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_sip_tag_rows) AS item(row_json)
    WHERE NOT (item.row_json ? 'sip_instrument_id')
      OR NOT (item.row_json ? 'tag_group')
      OR NOT (item.row_json ? 'tag')
  ) THEN
    RAISE EXCEPTION 'sip_tag_rows require sip_instrument_id, tag_group, and tag' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_v2_tag_rows) AS item(row_json)
    WHERE NOT (item.row_json ? 'instrument_v2_id')
      OR NOT (item.row_json ? 'tag_id')
  ) THEN
    RAISE EXCEPTION 'v2_tag_rows require instrument_v2_id and tag_id' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_upload_status_rows) AS item(row_json)
    WHERE NOT (item.row_json ? 'sip_instrument_id')
  ) THEN
    RAISE EXCEPTION 'upload_status_rows require sip_instrument_id' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_metadata_rows) AS item(row_json)
    WHERE NOT (item.row_json ? 'sip_instrument_id')
  ) THEN
    RAISE EXCEPTION 'metadata_rows require sip_instrument_id' USING ERRCODE = '22023';
  END IF;

  WITH rows AS (
    SELECT *
    FROM jsonb_to_recordset(p_instrument_rows) AS row_data(
      id uuid,
      lookup_key text,
      name text,
      engine_type public.instrument_engine_type,
      playback_type public.instrument_playback_type,
      polyphony_type public.instrument_polyphony_type,
      instrument_family text,
      instrument_type text,
      contributor_id uuid,
      collection text,
      pitch_contents jsonb,
      velocity_layers jsonb,
      pitch_content_config jsonb,
      round_robins jsonb,
      mic_positions jsonb,
      articulation text,
      effect text,
      legato_transition uuid,
      range_lower integer,
      range_upper integer,
      single_pitch integer,
      gain real,
      sustain_crop_time real,
      file_path_reference text,
      file_name_references text[],
      articulations uuid[],
      effects_instruments uuid[],
      published boolean
    )
  )
  INSERT INTO public.instruments_v2 (
    id,
    lookup_key,
    name,
    engine_type,
    playback_type,
    polyphony_type,
    instrument_family,
    instrument_type,
    contributor_id,
    collection,
    pitch_contents,
    velocity_layers,
    pitch_content_config,
    round_robins,
    mic_positions,
    articulation,
    effect,
    legato_transition,
    range_lower,
    range_upper,
    single_pitch,
    gain,
    sustain_crop_time,
    file_path_reference,
    file_name_references,
    articulations,
    effects_instruments,
    published
  )
  SELECT
    id,
    COALESCE(NULLIF(lookup_key, ''), id::text),
    COALESCE(NULLIF(btrim(name), ''), 'Unnamed'),
    COALESCE(engine_type, 'tonal'::public.instrument_engine_type),
    COALESCE(playback_type, 'oneShot'::public.instrument_playback_type),
    COALESCE(polyphony_type, 'Single'::public.instrument_polyphony_type),
    COALESCE(instrument_family, ''),
    instrument_type,
    contributor_id,
    collection,
    COALESCE(pitch_contents, '["0"]'::jsonb),
    COALESCE(velocity_layers, '{"0":[0]}'::jsonb),
    pitch_content_config,
    COALESCE(round_robins, '{"0/0":[0]}'::jsonb),
    COALESCE(mic_positions, '{"0/0/0":["main"]}'::jsonb),
    articulation,
    effect,
    legato_transition,
    COALESCE(range_lower, 21),
    COALESCE(range_upper, 108),
    single_pitch,
    COALESCE(gain, 0.1),
    COALESCE(sustain_crop_time, 0.1),
    file_path_reference,
    file_name_references,
    articulations,
    effects_instruments,
    COALESCE(published, false)
  FROM rows
  ON CONFLICT (id) DO UPDATE SET
    lookup_key = EXCLUDED.lookup_key,
    name = EXCLUDED.name,
    engine_type = EXCLUDED.engine_type,
    playback_type = EXCLUDED.playback_type,
    polyphony_type = EXCLUDED.polyphony_type,
    instrument_family = EXCLUDED.instrument_family,
    instrument_type = EXCLUDED.instrument_type,
    contributor_id = EXCLUDED.contributor_id,
    collection = EXCLUDED.collection,
    pitch_contents = EXCLUDED.pitch_contents,
    velocity_layers = EXCLUDED.velocity_layers,
    pitch_content_config = EXCLUDED.pitch_content_config,
    round_robins = EXCLUDED.round_robins,
    mic_positions = EXCLUDED.mic_positions,
    articulation = EXCLUDED.articulation,
    effect = EXCLUDED.effect,
    legato_transition = EXCLUDED.legato_transition,
    range_lower = EXCLUDED.range_lower,
    range_upper = EXCLUDED.range_upper,
    single_pitch = EXCLUDED.single_pitch,
    gain = EXCLUDED.gain,
    sustain_crop_time = EXCLUDED.sustain_crop_time,
    file_path_reference = EXCLUDED.file_path_reference,
    file_name_references = EXCLUDED.file_name_references,
    articulations = EXCLUDED.articulations,
    effects_instruments = EXCLUDED.effects_instruments,
    published = EXCLUDED.published;
  GET DIAGNOSTICS instrument_count = ROW_COUNT;

  WITH rows AS (
    SELECT *
    FROM jsonb_to_recordset(p_promotion_links) AS row_data(
      sip_review_instrument_id uuid,
      instrument_v2_id uuid,
      promoted_at timestamp with time zone,
      promoted_by text,
      notes text
    )
  )
  INSERT INTO public.sip_review_promotion_map (
    sip_review_instrument_id,
    instrument_v2_id,
    promoted_at,
    promoted_by,
    notes
  )
  SELECT
    sip_review_instrument_id,
    instrument_v2_id,
    COALESCE(promoted_at, now()),
    promoted_by,
    notes
  FROM rows
  ON CONFLICT (sip_review_instrument_id) DO UPDATE SET
    instrument_v2_id = EXCLUDED.instrument_v2_id,
    promoted_at = EXCLUDED.promoted_at,
    promoted_by = EXCLUDED.promoted_by,
    notes = EXCLUDED.notes;
  GET DIAGNOSTICS promotion_count = ROW_COUNT;

  WITH rows AS (
    SELECT *
    FROM jsonb_to_recordset(p_legacy_alias_rows) AS row_data(
      instrument_v2_id uuid,
      legacy_instrument_id uuid,
      sip_review_instrument_id uuid,
      contributor_slug text,
      legacy_lookup_key text,
      legacy_file_path_reference text,
      legacy_velocity smallint,
      is_primary_for_legacy boolean,
      is_primary_for_v2 boolean,
      notes text,
      created_by text,
      updated_by text,
      primary_for_legacy_set_by text,
      primary_for_legacy_set_at timestamp with time zone,
      primary_for_v2_set_by text,
      primary_for_v2_set_at timestamp with time zone
    )
  )
  INSERT INTO public.instrument_v2_legacy_map (
    instrument_v2_id,
    legacy_instrument_id,
    sip_review_instrument_id,
    contributor_slug,
    legacy_lookup_key,
    legacy_file_path_reference,
    legacy_velocity,
    is_primary_for_legacy,
    is_primary_for_v2,
    notes,
    created_by,
    updated_by,
    primary_for_legacy_set_by,
    primary_for_legacy_set_at,
    primary_for_v2_set_by,
    primary_for_v2_set_at
  )
  SELECT
    instrument_v2_id,
    legacy_instrument_id,
    sip_review_instrument_id,
    contributor_slug,
    legacy_lookup_key,
    legacy_file_path_reference,
    COALESCE(legacy_velocity, 1),
    COALESCE(is_primary_for_legacy, false),
    COALESCE(is_primary_for_v2, false),
    notes,
    created_by,
    updated_by,
    primary_for_legacy_set_by,
    primary_for_legacy_set_at,
    primary_for_v2_set_by,
    primary_for_v2_set_at
  FROM rows
  ON CONFLICT (legacy_instrument_id, instrument_v2_id) DO UPDATE SET
    sip_review_instrument_id = COALESCE(EXCLUDED.sip_review_instrument_id, public.instrument_v2_legacy_map.sip_review_instrument_id),
    contributor_slug = COALESCE(EXCLUDED.contributor_slug, public.instrument_v2_legacy_map.contributor_slug),
    legacy_lookup_key = EXCLUDED.legacy_lookup_key,
    legacy_file_path_reference = EXCLUDED.legacy_file_path_reference,
    legacy_velocity = EXCLUDED.legacy_velocity,
    is_primary_for_legacy = public.instrument_v2_legacy_map.is_primary_for_legacy OR EXCLUDED.is_primary_for_legacy,
    is_primary_for_v2 = public.instrument_v2_legacy_map.is_primary_for_v2 OR EXCLUDED.is_primary_for_v2,
    notes = COALESCE(EXCLUDED.notes, public.instrument_v2_legacy_map.notes),
    updated_by = EXCLUDED.updated_by,
    primary_for_legacy_set_by = COALESCE(EXCLUDED.primary_for_legacy_set_by, public.instrument_v2_legacy_map.primary_for_legacy_set_by),
    primary_for_legacy_set_at = COALESCE(EXCLUDED.primary_for_legacy_set_at, public.instrument_v2_legacy_map.primary_for_legacy_set_at),
    primary_for_v2_set_by = COALESCE(EXCLUDED.primary_for_v2_set_by, public.instrument_v2_legacy_map.primary_for_v2_set_by),
    primary_for_v2_set_at = COALESCE(EXCLUDED.primary_for_v2_set_at, public.instrument_v2_legacy_map.primary_for_v2_set_at);
  GET DIAGNOSTICS legacy_alias_count = ROW_COUNT;

  WITH rows AS (
    SELECT *
    FROM jsonb_to_recordset(p_sample_path_construct_rows) AS row_data(
      sample_original_path_id uuid,
      collection text,
      instrument_name text,
      articulation text,
      effect text,
      mic_position text,
      velocity integer,
      round_robin integer,
      midi_note text,
      filename text,
      pitch_content text,
      playback_type public.instrument_playback_type,
      instrument_v2_id uuid,
      contributor_id uuid
    )
  ),
  prepared AS (
    SELECT
      rows.*,
      rows.playback_type AS resolved_playback_type
    FROM rows
  )
  INSERT INTO public.sample_path_constructs (
    sample_original_path_id,
    collection,
    instrument_name,
    articulation,
    effect,
    mic_position,
    velocity,
    round_robin,
    midi_note,
    filename,
    pitch_content,
    playback_type,
    instrument_v2_id,
    contributor_id
  )
  SELECT
    sample_original_path_id,
    collection,
    COALESCE(NULLIF(btrim(instrument_name), ''), 'Unnamed'),
    articulation,
    effect,
    COALESCE(NULLIF(btrim(mic_position), ''), 'main'),
    COALESCE(velocity, 0),
    COALESCE(round_robin, 0),
    COALESCE(NULLIF(btrim(midi_note), ''), '0'),
    COALESCE(NULLIF(btrim(filename), ''), '0'),
    COALESCE(NULLIF(btrim(pitch_content), ''), '0'),
    resolved_playback_type,
    instrument_v2_id,
    contributor_id
  FROM prepared
  ON CONFLICT (sample_original_path_id) DO UPDATE SET
    collection = EXCLUDED.collection,
    instrument_name = EXCLUDED.instrument_name,
    articulation = EXCLUDED.articulation,
    effect = EXCLUDED.effect,
    mic_position = EXCLUDED.mic_position,
    velocity = EXCLUDED.velocity,
    round_robin = EXCLUDED.round_robin,
    midi_note = EXCLUDED.midi_note,
    filename = EXCLUDED.filename,
    pitch_content = EXCLUDED.pitch_content,
    playback_type = EXCLUDED.playback_type,
    instrument_v2_id = EXCLUDED.instrument_v2_id,
    contributor_id = EXCLUDED.contributor_id;
  GET DIAGNOSTICS sample_path_construct_count = ROW_COUNT;

  WITH rows AS (
    SELECT *
    FROM jsonb_to_recordset(p_sip_tag_rows) AS row_data(
      sip_instrument_id uuid,
      tag_group text,
      tag text,
      source text
    )
  )
  INSERT INTO public.sip_instrument_tag (
    sip_instrument_id,
    tag_group,
    tag,
    source
  )
  SELECT
    sip_instrument_id,
    COALESCE(NULLIF(btrim(tag_group), ''), 'general'),
    tag,
    COALESCE(NULLIF(btrim(source), ''), 'admin')
  FROM rows
  ON CONFLICT (sip_instrument_id, tag_group, tag) DO UPDATE SET
    source = EXCLUDED.source;
  GET DIAGNOSTICS sip_tag_count = ROW_COUNT;

  -- Sentinel-row contract with the API caller:
  -- `{ instrument_v2_id, tag_id: null }` rows mark affected instruments whose
  -- stale tag links should be deleted without inserting a new tag.
  IF jsonb_array_length(p_v2_tag_rows) > 0 THEN
    WITH raw_rows AS (
      SELECT
        row_data.instrument_v2_id,
        row_data.tag_id,
        row_data.source,
        item.row_ordinal
      FROM jsonb_array_elements(p_v2_tag_rows) WITH ORDINALITY AS item(row_json, row_ordinal)
      CROSS JOIN LATERAL jsonb_to_record(item.row_json) AS row_data(
        instrument_v2_id uuid,
        tag_id uuid,
        source text
      )
    ),
    desired AS (
      SELECT DISTINCT ON (instrument_v2_id, tag_id)
        instrument_v2_id,
        tag_id,
        COALESCE(NULLIF(btrim(source), ''), 'admin') AS source
      FROM raw_rows
      WHERE instrument_v2_id IS NOT NULL
        AND tag_id IS NOT NULL
      ORDER BY instrument_v2_id, tag_id, row_ordinal DESC
    ),
    affected_instruments AS (
      SELECT DISTINCT instrument_v2_id
      FROM raw_rows
      WHERE instrument_v2_id IS NOT NULL
    ),
    deleted_stale AS (
      DELETE FROM public.instrument_v2_instrument_tags existing
      USING affected_instruments affected
      WHERE existing.instrument_v2_id = affected.instrument_v2_id
        AND NOT EXISTS (
          SELECT 1
          FROM desired
          WHERE desired.instrument_v2_id = existing.instrument_v2_id
            AND desired.tag_id = existing.tag_id
        )
      RETURNING 1
    ),
    upserted AS (
      INSERT INTO public.instrument_v2_instrument_tags (
        instrument_v2_id,
        tag_id,
        source
      )
      SELECT
        instrument_v2_id,
        tag_id,
        source
      FROM desired
      ON CONFLICT (instrument_v2_id, tag_id) DO UPDATE SET
        source = EXCLUDED.source
      RETURNING 1
    )
    SELECT count(*) INTO v2_tag_count
    FROM upserted;
  END IF;

  WITH rows AS (
    SELECT *
    FROM jsonb_to_recordset(p_upload_status_rows) AS row_data(
      sip_instrument_id uuid
    )
  )
  INSERT INTO public.sip_instrument_upload_status (sip_instrument_id)
  SELECT sip_instrument_id
  FROM rows
  ON CONFLICT (sip_instrument_id) DO UPDATE SET
    updated_at = now();
  GET DIAGNOSTICS upload_status_count = ROW_COUNT;

  WITH rows AS (
    SELECT *
    FROM jsonb_to_recordset(p_metadata_rows) AS row_data(
      sip_instrument_id uuid,
      source_contributor_slug text,
      approved boolean,
      approved_at timestamp with time zone,
      approved_by text,
      last_promoted_at timestamp with time zone
    )
  )
  UPDATE public.sip_instrument_meta meta
  SET
    approved = COALESCE(rows.approved, true),
    approved_at = COALESCE(rows.approved_at, now()),
    approved_by = rows.approved_by,
    last_promoted_at = COALESCE(rows.last_promoted_at, now())
  FROM rows
  WHERE meta.sip_instrument_id = rows.sip_instrument_id
    AND (
      rows.source_contributor_slug IS NULL
      OR meta.source_contributor_slug = rows.source_contributor_slug
    );
  GET DIAGNOSTICS metadata_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'instrumentsUpserted', instrument_count,
    'promotionLinksUpserted', promotion_count,
    'samplePathConstructsUpserted', sample_path_construct_count,
    'legacyAliasesUpserted', legacy_alias_count,
    'sipTagsUpserted', sip_tag_count,
    'v2TagsUpserted', v2_tag_count,
    'uploadStatusesUpserted', upload_status_count,
    'metadataRowsUpdated', metadata_count
  );
END;
$$;


ALTER FUNCTION "public"."promote_sip_instruments_v2"("p_instrument_rows" "jsonb", "p_promotion_links" "jsonb", "p_sample_path_construct_rows" "jsonb", "p_legacy_alias_rows" "jsonb", "p_sip_tag_rows" "jsonb", "p_v2_tag_rows" "jsonb", "p_upload_status_rows" "jsonb", "p_metadata_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_sip_instruments_v2"("p_instrument_rows" "jsonb", "p_promotion_links" "jsonb", "p_sample_path_construct_rows" "jsonb", "p_legacy_alias_rows" "jsonb", "p_sip_tag_rows" "jsonb", "p_v2_tag_rows" "jsonb", "p_upload_status_rows" "jsonb", "p_metadata_rows" "jsonb", "p_sample_playback_cue_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_base_result jsonb;
  v_instrument_v2_id uuid;
  v_readiness jsonb;
  v_readiness_rows jsonb := '[]'::jsonb;
BEGIN
  v_base_result := private.promote_sip_instruments_v2_without_runtime_manifest_v1(
    p_instrument_rows,
    p_promotion_links,
    p_sample_path_construct_rows,
    p_legacy_alias_rows,
    p_sip_tag_rows,
    p_v2_tag_rows,
    p_upload_status_rows,
    p_metadata_rows,
    p_sample_playback_cue_rows
  );

  FOR v_instrument_v2_id IN
    SELECT DISTINCT row_data.id
    FROM jsonb_to_recordset(COALESCE(p_instrument_rows, '[]'::jsonb))
      AS row_data(id uuid)
    WHERE row_data.id IS NOT NULL
    ORDER BY row_data.id
  LOOP
    v_readiness := public.refresh_instrument_v2_runtime_readiness_v1(
      v_instrument_v2_id,
      true
    );
    v_readiness_rows := v_readiness_rows || jsonb_build_array(v_readiness);
  END LOOP;

  RETURN v_base_result || jsonb_build_object(
    'runtimeManifestReadiness', v_readiness_rows,
    'runtimeManifestBehaviorReadyCount', (
      SELECT count(*)
      FROM jsonb_array_elements(v_readiness_rows) row_data
      WHERE (row_data->>'behaviorReady')::boolean
    ),
    'runtimeManifestAddressReadyCount', (
      SELECT count(*)
      FROM jsonb_array_elements(v_readiness_rows) row_data
      WHERE (row_data->>'addressReady')::boolean
    ),
    'runtimeManifestDeterministicReadyCount', (
      SELECT count(*)
      FROM jsonb_array_elements(v_readiness_rows) row_data
      WHERE row_data->>'fallbackState' = 'runtime_manifest'
    ),
    'runtimeManifestFallbackCount', (
      SELECT count(*)
      FROM jsonb_array_elements(v_readiness_rows) row_data
      WHERE row_data->>'fallbackEligibility' = 'construct_hydration'
    ),
    'runtimeManifestBlockedCount', (
      SELECT count(*)
      FROM jsonb_array_elements(v_readiness_rows) row_data
      WHERE row_data->>'fallbackState' = 'blocked'
    )
  );
END;
$$;


ALTER FUNCTION "public"."promote_sip_instruments_v2"("p_instrument_rows" "jsonb", "p_promotion_links" "jsonb", "p_sample_path_construct_rows" "jsonb", "p_legacy_alias_rows" "jsonb", "p_sip_tag_rows" "jsonb", "p_v2_tag_rows" "jsonb", "p_upload_status_rows" "jsonb", "p_metadata_rows" "jsonb", "p_sample_playback_cue_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."promote_sip_instruments_v2"("p_instrument_rows" "jsonb", "p_promotion_links" "jsonb", "p_sample_path_construct_rows" "jsonb", "p_legacy_alias_rows" "jsonb", "p_sip_tag_rows" "jsonb", "p_v2_tag_rows" "jsonb", "p_upload_status_rows" "jsonb", "p_metadata_rows" "jsonb", "p_sample_playback_cue_rows" "jsonb") IS 'Promotes SIP review rows and cues, then atomically materializes and classifies each exact Instrument V2 runtime manifest.';



CREATE OR REPLACE FUNCTION "public"."promote_sip_instruments_v2_coordinated"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_instrument_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_promotion_links" "jsonb" DEFAULT '[]'::"jsonb", "p_sample_path_construct_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_legacy_alias_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_sip_tag_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_v2_tag_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_upload_status_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_metadata_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_sample_playback_cue_rows" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.validate_sip_publish_operator_lease_v1(
    p_contributor_slug,
    p_lease_id,
    p_lease_token
  ) THEN
    RAISE EXCEPTION 'invalid_coordinator_publish_authorization';
  END IF;

  PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);

  RETURN public.promote_sip_instruments_v2(
    p_instrument_rows,
    p_promotion_links,
    p_sample_path_construct_rows,
    p_legacy_alias_rows,
    p_sip_tag_rows,
    p_v2_tag_rows,
    p_upload_status_rows,
    p_metadata_rows,
    p_sample_playback_cue_rows
  );
END
$$;


ALTER FUNCTION "public"."promote_sip_instruments_v2_coordinated"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_instrument_rows" "jsonb", "p_promotion_links" "jsonb", "p_sample_path_construct_rows" "jsonb", "p_legacy_alias_rows" "jsonb", "p_sip_tag_rows" "jsonb", "p_v2_tag_rows" "jsonb", "p_upload_status_rows" "jsonb", "p_metadata_rows" "jsonb", "p_sample_playback_cue_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_sip_instruments_v2_coordinated"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_instrument_rows" "jsonb", "p_promotion_links" "jsonb", "p_sample_path_construct_rows" "jsonb", "p_legacy_alias_rows" "jsonb", "p_sip_tag_rows" "jsonb", "p_v2_tag_rows" "jsonb", "p_upload_status_rows" "jsonb", "p_metadata_rows" "jsonb", "p_sample_playback_cue_rows" "jsonb", "p_replace_instrument_v2_ids" "jsonb", "p_replace_in_place_rows" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  base_result jsonb; detached_construct_count integer := 0;
  relationship_rewrite_count integer := 0; retired_instrument_count integer := 0;
  expected_retiring_count integer := 0; replacement_candidate jsonb;
  retiring_target public.instruments_v2%ROWTYPE; canonical_row jsonb;
BEGIN
  IF NOT public.validate_sip_publish_operator_lease_v1(
    p_contributor_slug, p_lease_id, p_lease_token
  ) THEN
    RAISE EXCEPTION 'invalid_coordinator_publish_authorization';
  END IF;
  IF jsonb_typeof(COALESCE(p_replace_instrument_v2_ids, '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(COALESCE(p_replace_in_place_rows, '[]'::jsonb)) <> 'array'
  THEN
    RAISE EXCEPTION 'replacement arguments must be JSON arrays'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(
      COALESCE(p_replace_instrument_v2_ids, '[]'::jsonb)
    ) AS item(value)
    WHERE value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-58][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      COALESCE(p_replace_in_place_rows, '[]'::jsonb)
    ) AS item(row_json)
    WHERE COALESCE(item.row_json->>'retiring_instrument_v2_id', '')
      !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      OR COALESCE(item.row_json->>'canonical_instrument_v2_id', '')
      !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-58][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ) THEN
    RAISE EXCEPTION 'replacement IDs must be UUID strings'
      USING ERRCODE = '22023';
  END IF;
  SELECT count(*) INTO expected_retiring_count
  FROM (
    SELECT DISTINCT row_json->>'retiring_instrument_v2_id' AS retiring_id
    FROM jsonb_array_elements(
      COALESCE(p_replace_in_place_rows, '[]'::jsonb)
    ) AS item(row_json)
  ) replacements;
  FOR replacement_candidate IN
    SELECT row_json
    FROM jsonb_array_elements(
      COALESCE(p_replace_in_place_rows, '[]'::jsonb)
    ) AS item(row_json)
  LOOP
    SELECT * INTO retiring_target
    FROM public.instruments_v2
    WHERE id = (replacement_candidate->>'retiring_instrument_v2_id')::uuid
    FOR UPDATE;
    IF NOT FOUND OR retiring_target.published
      OR retiring_target.id::text =
        replacement_candidate->>'canonical_instrument_v2_id'
    THEN
      RAISE EXCEPTION
        'replace-in-place requires distinct existing unpublished V2 rows'
        USING ERRCODE = '23514';
    END IF;
    SELECT row_json INTO canonical_row
    FROM jsonb_array_elements(
      COALESCE(p_instrument_rows, '[]'::jsonb)
    ) AS item(row_json)
    WHERE row_json->>'id' =
      replacement_candidate->>'canonical_instrument_v2_id';
    IF canonical_row IS NULL
      OR canonical_row->>'contributor_id' IS DISTINCT FROM
        retiring_target.contributor_id::text
      OR COALESCE(canonical_row->>'collection', '') IS DISTINCT FROM
        COALESCE(retiring_target.collection, '')
      OR canonical_row->>'name' IS DISTINCT FROM retiring_target.name
      OR COALESCE(canonical_row->>'articulation', '') IS DISTINCT FROM
        COALESCE(retiring_target.articulation, '')
      OR COALESCE(canonical_row->>'effect', '') IS DISTINCT FROM
        COALESCE(retiring_target.effect, '')
    THEN
      RAISE EXCEPTION
        'replace-in-place canonical row must share the retiring provider path identity'
        USING ERRCODE = '23514';
    END IF;
  END LOOP;
  PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);
  WITH replacements AS (
    SELECT DISTINCT
      (row_json->>'retiring_instrument_v2_id')::uuid AS retiring_id
    FROM jsonb_array_elements(
      COALESCE(p_replace_in_place_rows, '[]'::jsonb)
    ) AS item(row_json)
  )
  UPDATE public.sample_path_constructs existing
  SET instrument_v2_id = NULL
  WHERE existing.instrument_v2_id IN (
    SELECT retiring_id FROM replacements
  );
  GET DIAGNOSTICS detached_construct_count = ROW_COUNT;
  UPDATE public.instruments_v2 consumer SET
    articulations = (
      SELECT array_agg(
        COALESCE((mapping.row_json->>'canonical_instrument_v2_id')::uuid, value)
        ORDER BY ordinality
      )
      FROM unnest(COALESCE(consumer.articulations, ARRAY[]::uuid[]))
        WITH ORDINALITY AS values(value, ordinality)
      LEFT JOIN jsonb_array_elements(
        COALESCE(p_replace_in_place_rows, '[]'::jsonb)
      ) AS mapping(row_json)
        ON mapping.row_json->>'retiring_instrument_v2_id' = value::text
    ),
    effects_instruments = (
      SELECT array_agg(
        COALESCE((mapping.row_json->>'canonical_instrument_v2_id')::uuid, value)
        ORDER BY ordinality
      )
      FROM unnest(COALESCE(consumer.effects_instruments, ARRAY[]::uuid[]))
        WITH ORDINALITY AS values(value, ordinality)
      LEFT JOIN jsonb_array_elements(
        COALESCE(p_replace_in_place_rows, '[]'::jsonb)
      ) AS mapping(row_json)
        ON mapping.row_json->>'retiring_instrument_v2_id' = value::text
    ),
    legato_transition = COALESCE((
      SELECT (mapping.row_json->>'canonical_instrument_v2_id')::uuid
      FROM jsonb_array_elements(
        COALESCE(p_replace_in_place_rows, '[]'::jsonb)
      ) AS mapping(row_json)
      WHERE mapping.row_json->>'retiring_instrument_v2_id' =
        consumer.legato_transition::text
    ), consumer.legato_transition)
  WHERE EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      COALESCE(p_replace_in_place_rows, '[]'::jsonb)
    ) AS mapping(row_json)
    WHERE mapping.row_json->>'retiring_instrument_v2_id' =
      ANY(COALESCE(consumer.articulations::text[], ARRAY[]::text[]))
      OR mapping.row_json->>'retiring_instrument_v2_id' =
        ANY(COALESCE(consumer.effects_instruments::text[], ARRAY[]::text[]))
      OR mapping.row_json->>'retiring_instrument_v2_id' =
        consumer.legato_transition::text
  );
  GET DIAGNOSTICS relationship_rewrite_count = ROW_COUNT;
  WITH replacements AS (
    SELECT DISTINCT
      (row_json->>'retiring_instrument_v2_id')::uuid AS retiring_id
    FROM jsonb_array_elements(
      COALESCE(p_replace_in_place_rows, '[]'::jsonb)
    ) AS item(row_json)
  )
  DELETE FROM public.instruments_v2 retiring
  WHERE retiring.id IN (SELECT retiring_id FROM replacements);
  GET DIAGNOSTICS retired_instrument_count = ROW_COUNT;
  IF retired_instrument_count <> expected_retiring_count THEN
    RAISE EXCEPTION
      'replace-in-place retiring row count changed during promotion'
      USING ERRCODE = '40001';
  END IF;
  WITH requested AS (
    SELECT DISTINCT value::uuid AS instrument_v2_id
    FROM jsonb_array_elements_text(
      COALESCE(p_replace_instrument_v2_ids, '[]'::jsonb)
    ) AS item(value)
  ), promoted AS (
    SELECT DISTINCT row_data.id AS instrument_v2_id
    FROM jsonb_to_recordset(COALESCE(p_instrument_rows, '[]'::jsonb))
      AS row_data(id uuid)
  ), replacement_targets AS (
    SELECT requested.instrument_v2_id
    FROM requested JOIN promoted USING (instrument_v2_id)
  )
  UPDATE public.sample_path_constructs existing
  SET instrument_v2_id = NULL
  WHERE existing.instrument_v2_id IN (
    SELECT instrument_v2_id FROM replacement_targets
  );
  base_result := public.promote_sip_instruments_v2(
    p_instrument_rows, p_promotion_links, p_sample_path_construct_rows,
    p_legacy_alias_rows, p_sip_tag_rows, p_v2_tag_rows,
    p_upload_status_rows, p_metadata_rows, p_sample_playback_cue_rows
  );
  RETURN base_result || jsonb_build_object(
    'replacementConstructsDetached', detached_construct_count,
    'replacementRelationshipsRewritten', relationship_rewrite_count,
    'replacementRowsRetired', retired_instrument_count
  );
END $_$;


ALTER FUNCTION "public"."promote_sip_instruments_v2_coordinated"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_instrument_rows" "jsonb", "p_promotion_links" "jsonb", "p_sample_path_construct_rows" "jsonb", "p_legacy_alias_rows" "jsonb", "p_sip_tag_rows" "jsonb", "p_v2_tag_rows" "jsonb", "p_upload_status_rows" "jsonb", "p_metadata_rows" "jsonb", "p_sample_playback_cue_rows" "jsonb", "p_replace_instrument_v2_ids" "jsonb", "p_replace_in_place_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_instrument_discovery_characteristics"("p_source_revision" "text", "p_adoption_revision" "text", "p_registry_version" "text", "p_rows" "jsonb", "p_adopted" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
<<publication>>
DECLARE
  generated_at timestamptz := pg_catalog.clock_timestamp();
  characteristic_generation uuid := extensions.gen_random_uuid();
  prior_characteristic_generation uuid;
  instrument_generation uuid;
  tag_generation uuid;
  cue_generation uuid;
  instrument_revision text;
  current_manifest_revision text;
  current_generated_at timestamptz;
  characteristic_count integer;
  characteristic_page_count integer;
  rows jsonb;
  adopted jsonb;
BEGIN
  IF NULLIF(pg_catalog.btrim(p_source_revision), '') IS NULL
    OR NULLIF(pg_catalog.btrim(p_adoption_revision), '') IS NULL
    OR NULLIF(pg_catalog.btrim(p_registry_version), '') IS NULL
    OR p_source_revision IS DISTINCT FROM pg_catalog.btrim(p_source_revision)
    OR p_adoption_revision IS DISTINCT FROM pg_catalog.btrim(p_adoption_revision)
    OR p_registry_version IS DISTINCT FROM pg_catalog.btrim(p_registry_version)
  THEN
    RAISE EXCEPTION 'Instrument Discovery Characteristic publication identity is invalid';
  END IF;

  IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_adopted) IS DISTINCT FROM 'array'
  THEN
    RAISE EXCEPTION 'Instrument Discovery Characteristic rows and adoptions must be arrays';
  END IF;

  SELECT COALESCE(
    jsonb_agg(value ORDER BY value ->> 'characteristicKey', value ->> 'instrumentId'),
    '[]'::jsonb
  )
  INTO rows
  FROM jsonb_array_elements(p_rows) AS input(value);

  SELECT COALESCE(
    jsonb_agg(value ORDER BY value ->> 'key'),
    '[]'::jsonb
  )
  INTO adopted
  FROM jsonb_array_elements(p_adopted) AS input(value);

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(rows) AS input(item)
    WHERE jsonb_typeof(item) IS DISTINCT FROM 'object'
      OR NOT item ?& ARRAY[
        'instrumentId',
        'characteristicKey',
        'registryVersion',
        'mappingVersion',
        'scoring',
        'result',
        'evidence',
        'state',
        'normalizedValue',
        'typicalRange',
        'reasonCode'
      ]
      OR item - ARRAY[
        'instrumentId',
        'characteristicKey',
        'registryVersion',
        'mappingVersion',
        'scoring',
        'result',
        'evidence',
        'state',
        'normalizedValue',
        'typicalRange',
        'reasonCode'
      ] <> '{}'::jsonb
      OR jsonb_typeof(item -> 'instrumentId') IS DISTINCT FROM 'string'
      OR item ->> 'instrumentId' !~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      OR NULLIF(pg_catalog.btrim(item ->> 'characteristicKey'), '') IS NULL
      OR jsonb_typeof(item -> 'characteristicKey') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item -> 'registryVersion') IS DISTINCT FROM 'string'
      OR item ->> 'registryVersion' IS DISTINCT FROM p_registry_version
      OR jsonb_typeof(item -> 'mappingVersion') IS DISTINCT FROM 'string'
      OR NULLIF(pg_catalog.btrim(item ->> 'mappingVersion'), '') IS NULL
      OR jsonb_typeof(item -> 'state') IS DISTINCT FROM 'string'
      OR NOT (item ->> 'state' = ANY(
        ARRAY['available', 'not_applicable', 'unavailable']
      ))
      OR jsonb_typeof(item -> 'result') IS DISTINCT FROM 'object'
      OR NOT (item -> 'result') ?& ARRAY['resultId', 'resultDigest']
      OR (item -> 'result') - ARRAY['resultId', 'resultDigest'] <> '{}'::jsonb
      OR jsonb_typeof(item #> '{result,resultId}') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item #> '{result,resultDigest}') IS DISTINCT FROM 'string'
      OR NULLIF(pg_catalog.btrim(item #>> '{result,resultId}'), '') IS NULL
      OR item #>> '{result,resultDigest}' !~ '^sha256:[0-9a-f]{64}$'
      OR jsonb_typeof(item -> 'evidence') IS DISTINCT FROM 'object'
      OR NOT (item -> 'evidence') ?& ARRAY[
        'evidenceRunId',
        'evidenceRunDigest',
        'evidenceContractVersion'
      ]
      OR (item -> 'evidence') - ARRAY[
        'evidenceRunId',
        'evidenceRunDigest',
        'evidenceContractVersion'
      ] <> '{}'::jsonb
      OR jsonb_typeof(item #> '{evidence,evidenceRunId}') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item #> '{evidence,evidenceRunDigest}') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item #> '{evidence,evidenceContractVersion}') IS DISTINCT FROM 'string'
      OR NULLIF(pg_catalog.btrim(item #>> '{evidence,evidenceRunId}'), '') IS NULL
      OR item #>> '{evidence,evidenceRunDigest}' !~ '^sha256:[0-9a-f]{64}$'
      OR NULLIF(
        pg_catalog.btrim(item #>> '{evidence,evidenceContractVersion}'),
        ''
      ) IS NULL
      OR jsonb_typeof(item -> 'scoring') IS DISTINCT FROM 'object'
      OR jsonb_typeof(item #> '{scoring,kind}') IS DISTINCT FROM 'string'
      OR (
        item #>> '{scoring,kind}' = 'catalog-relative'
        AND (
          NOT (item -> 'scoring') ?& ARRAY['kind', 'reference']
          OR (item -> 'scoring') - ARRAY['kind', 'reference'] <> '{}'::jsonb
          OR jsonb_typeof(item #> '{scoring,reference}') IS DISTINCT FROM 'object'
          OR NOT (item #> '{scoring,reference}') ?& ARRAY[
            'referenceSnapshotId',
            'referenceSnapshotDigest',
            'referenceContractVersion'
          ]
          OR (item #> '{scoring,reference}') - ARRAY[
            'referenceSnapshotId',
            'referenceSnapshotDigest',
            'referenceContractVersion'
          ] <> '{}'::jsonb
          OR jsonb_typeof(
            item #> '{scoring,reference,referenceSnapshotId}'
          ) IS DISTINCT FROM 'string'
          OR jsonb_typeof(
            item #> '{scoring,reference,referenceSnapshotDigest}'
          ) IS DISTINCT FROM 'string'
          OR jsonb_typeof(
            item #> '{scoring,reference,referenceContractVersion}'
          ) IS DISTINCT FROM 'string'
          OR NULLIF(
            pg_catalog.btrim(
              item #>> '{scoring,reference,referenceSnapshotId}'
            ),
            ''
          ) IS NULL
          OR item #>> '{scoring,reference,referenceSnapshotDigest}' !~
            '^sha256:[0-9a-f]{64}$'
          OR NULLIF(
            pg_catalog.btrim(
              item #>> '{scoring,reference,referenceContractVersion}'
            ),
            ''
          ) IS NULL
        )
      )
      OR (
        item #>> '{scoring,kind}' = 'direct-bounded'
        AND (
          NOT (item -> 'scoring') ? 'kind'
          OR (item -> 'scoring') - 'kind' <> '{}'::jsonb
        )
      )
      OR NOT (item #>> '{scoring,kind}' = ANY(
        ARRAY['catalog-relative', 'direct-bounded']
      ))
      OR (
        item ->> 'state' = 'available'
        AND (
          jsonb_typeof(item -> 'normalizedValue') IS DISTINCT FROM 'number'
          OR (item ->> 'normalizedValue')::double precision NOT BETWEEN 0 AND 100
          OR jsonb_typeof(item -> 'typicalRange') IS DISTINCT FROM 'object'
          OR NOT (item -> 'typicalRange') ?& ARRAY['low', 'high', 'method']
          OR (item -> 'typicalRange') - ARRAY['low', 'high', 'method'] <> '{}'::jsonb
          OR jsonb_typeof(item #> '{typicalRange,low}') IS DISTINCT FROM 'number'
          OR jsonb_typeof(item #> '{typicalRange,high}') IS DISTINCT FROM 'number'
          OR (item #>> '{typicalRange,low}')::double precision NOT BETWEEN 0 AND 100
          OR (item #>> '{typicalRange,high}')::double precision NOT BETWEEN 0 AND 100
          OR (item #>> '{typicalRange,low}')::double precision >
            (item ->> 'normalizedValue')::double precision
          OR (item ->> 'normalizedValue')::double precision >
            (item #>> '{typicalRange,high}')::double precision
          OR item #>> '{typicalRange,method}' IS DISTINCT FROM
            'equal-primary-cell-p10-p90'
          OR item -> 'reasonCode' <> 'null'::jsonb
        )
      )
      OR (
        item ->> 'state' IN ('not_applicable', 'unavailable')
        AND (
          item -> 'normalizedValue' <> 'null'::jsonb
          OR item -> 'typicalRange' <> 'null'::jsonb
          OR jsonb_typeof(item -> 'reasonCode') IS DISTINCT FROM 'string'
          OR NULLIF(pg_catalog.btrim(item ->> 'reasonCode'), '') IS NULL
        )
      )
  ) THEN
    RAISE EXCEPTION 'Instrument Discovery Characteristic row is not compact and canonical';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(adopted) AS input(item)
    WHERE jsonb_typeof(item) IS DISTINCT FROM 'object'
      OR NOT item ?& ARRAY[
        'key',
        'mappingVersion',
        'scoring',
        'evidenceContractVersion',
        'rowCount',
        'checksum'
      ]
      OR item - ARRAY[
        'key',
        'mappingVersion',
        'scoring',
        'evidenceContractVersion',
        'rowCount',
        'checksum'
      ] <> '{}'::jsonb
      OR jsonb_typeof(item -> 'key') IS DISTINCT FROM 'string'
      OR NULLIF(pg_catalog.btrim(item ->> 'key'), '') IS NULL
      OR jsonb_typeof(item -> 'mappingVersion') IS DISTINCT FROM 'string'
      OR NULLIF(pg_catalog.btrim(item ->> 'mappingVersion'), '') IS NULL
      OR jsonb_typeof(item -> 'evidenceContractVersion') IS DISTINCT FROM 'string'
      OR NULLIF(pg_catalog.btrim(item ->> 'evidenceContractVersion'), '') IS NULL
      OR jsonb_typeof(item -> 'scoring') IS DISTINCT FROM 'object'
      OR jsonb_typeof(item -> 'rowCount') IS DISTINCT FROM 'number'
      OR (item ->> 'rowCount')::integer < 1
      OR jsonb_typeof(item -> 'checksum') IS DISTINCT FROM 'string'
      OR item ->> 'checksum' !~ '^[0-9a-f]{64}$'
  ) THEN
    RAISE EXCEPTION 'Instrument Discovery Characteristic adoption is invalid';
  END IF;

  IF (jsonb_array_length(rows) = 0) IS DISTINCT FROM
      (jsonb_array_length(adopted) = 0)
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(rows) AS row_item(item)
      LEFT JOIN jsonb_array_elements(adopted) AS adoption_item(item)
        ON adoption_item.item ->> 'key' = row_item.item ->> 'characteristicKey'
      WHERE adoption_item.item IS NULL
        OR adoption_item.item ->> 'mappingVersion' IS DISTINCT FROM
          row_item.item ->> 'mappingVersion'
        OR adoption_item.item -> 'scoring' IS DISTINCT FROM
          row_item.item -> 'scoring'
        OR adoption_item.item ->> 'evidenceContractVersion' IS DISTINCT FROM
          row_item.item #>> '{evidence,evidenceContractVersion}'
    )
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(adopted) AS adoption_item(item)
      CROSS JOIN LATERAL (
        SELECT count(*)::integer AS row_count
        FROM jsonb_array_elements(rows) AS row_item(item)
        WHERE row_item.item ->> 'characteristicKey' =
          adoption_item.item ->> 'key'
      ) AS actual
      WHERE actual.row_count IS DISTINCT FROM
          (adoption_item.item ->> 'rowCount')::integer
    )
    OR EXISTS (
      SELECT 1
      FROM (
        SELECT item ->> 'instrumentId' AS instrument_id,
          item ->> 'characteristicKey' AS characteristic_key,
          count(*)
        FROM jsonb_array_elements(rows) AS input(item)
        GROUP BY item ->> 'instrumentId', item ->> 'characteristicKey'
        HAVING count(*) > 1
      ) AS duplicate
    )
    OR EXISTS (
      SELECT 1
      FROM (
        SELECT item ->> 'key' AS key, count(*)
        FROM jsonb_array_elements(adopted) AS input(item)
        GROUP BY item ->> 'key'
        HAVING count(*) > 1
      ) AS duplicate
    )
  THEN
    RAISE EXCEPTION 'Instrument Discovery Characteristic adoption does not match its rows';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(2173, 1);
  PERFORM browser_catalog.cleanup_instrument_discovery_expired(
    publication.generated_at,
    16
  );

  SELECT
    state.instrument_generation,
    state.tag_generation,
    state.cue_generation,
    state.characteristic_generation,
    state.manifest_revision,
    state.generated_at,
    instrument.source_revision
  INTO
    instrument_generation,
    tag_generation,
    cue_generation,
    prior_characteristic_generation,
    current_manifest_revision,
    current_generated_at,
    instrument_revision
  FROM browser_catalog.instrument_discovery_state AS state
  INNER JOIN browser_catalog.instrument_discovery_resource_generations
    AS instrument
    ON instrument.resource_key = 'instruments'
   AND instrument.generation = state.instrument_generation
  INNER JOIN browser_catalog.instrument_discovery_resource_generations AS tags
    ON tags.resource_key = 'tags'
   AND tags.generation = state.tag_generation
  INNER JOIN browser_catalog.instrument_discovery_resource_generations AS cues
    ON cues.resource_key = 'cues'
   AND cues.generation = state.cue_generation
  WHERE state.singleton
  FOR UPDATE OF state;

  IF instrument_generation IS NULL THEN
    RAISE EXCEPTION 'Instrument Discovery Instrument publication is unavailable';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(rows) AS input(item)
    LEFT JOIN browser_catalog.instrument_discovery_instrument_rows AS instrument
      ON instrument.generation = instrument_generation
     AND instrument.instrument_id = (input.item ->> 'instrumentId')::uuid
    WHERE instrument.instrument_id IS NULL
  ) THEN
    RAISE EXCEPTION 'Instrument Discovery Characteristic row references an unpublished Instrument';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM browser_catalog.instrument_discovery_resource_generations AS generation
    WHERE generation.resource_key = 'characteristics'
      AND generation.generation = prior_characteristic_generation
      AND generation.source_revision = p_source_revision
      AND generation.adoption_revision = p_adoption_revision
      AND generation.registry_version = p_registry_version
      AND generation.adopted = publication.adopted
      AND COALESCE(
        (
          SELECT jsonb_agg(row.item ORDER BY row.characteristic_key, row.instrument_id)
          FROM browser_catalog.instrument_discovery_characteristic_rows AS row
          WHERE row.generation = prior_characteristic_generation
        ),
        '[]'::jsonb
      ) = publication.rows
  ) THEN
    RETURN jsonb_build_object(
      'publicationStatus', 'current',
      'sourceRevision', p_source_revision,
      'instrumentGeneration', instrument_generation,
      'tagGeneration', tag_generation,
      'cueGeneration', cue_generation,
      'characteristicGeneration', prior_characteristic_generation,
      'expectedInstrumentGeneration', instrument_generation,
      'expectedTagGeneration', tag_generation,
      'expectedCueGeneration', cue_generation,
      'expectedCharacteristicGeneration', prior_characteristic_generation,
      'manifestRevision', current_manifest_revision,
      'generatedAt', current_generated_at
    );
  END IF;

  SELECT generation.generation
  INTO characteristic_generation
  FROM browser_catalog.instrument_discovery_resource_generations AS generation
  WHERE generation.resource_key = 'characteristics'
    AND generation.publication_status = 'staging'
    AND generation.retained_until > publication.generated_at
    AND generation.source_revision = p_source_revision
    AND generation.instrument_revision = publication.instrument_revision
    AND generation.adoption_revision = p_adoption_revision
    AND generation.registry_version = p_registry_version
    AND generation.adopted = publication.adopted
    AND COALESCE(
      (
        SELECT jsonb_agg(row.item ORDER BY row.characteristic_key, row.instrument_id)
        FROM browser_catalog.instrument_discovery_characteristic_rows AS row
        WHERE row.generation = generation.generation
      ),
      '[]'::jsonb
    ) = publication.rows
  ORDER BY generation.generated_at DESC
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'publicationStatus', 'staging',
      'sourceRevision', p_source_revision,
      'instrumentGeneration', instrument_generation,
      'tagGeneration', tag_generation,
      'cueGeneration', cue_generation,
      'characteristicGeneration', characteristic_generation,
      'expectedInstrumentGeneration', instrument_generation,
      'expectedTagGeneration', tag_generation,
      'expectedCueGeneration', cue_generation,
      'expectedCharacteristicGeneration', prior_characteristic_generation,
      'resources', jsonb_build_array(
        jsonb_build_object(
          'resource', 'characteristics',
          'generation', characteristic_generation,
          'pageCount', (
            SELECT page_count
            FROM browser_catalog.instrument_discovery_resource_generations
            WHERE resource_key = 'characteristics'
              AND generation = characteristic_generation
          )
        )
      )
    );
  END IF;

  characteristic_generation := extensions.gen_random_uuid();

  INSERT INTO browser_catalog.instrument_discovery_characteristic_rows (
    generation,
    instrument_id,
    characteristic_key,
    item
  )
  SELECT
    characteristic_generation,
    (item ->> 'instrumentId')::uuid,
    item ->> 'characteristicKey',
    item
  FROM jsonb_array_elements(rows) AS input(item)
  ORDER BY item ->> 'characteristicKey', item ->> 'instrumentId';

  WITH numbered AS (
    SELECT
      item,
      characteristic_key,
      instrument_id,
      ((row_number() OVER (
        ORDER BY characteristic_key, instrument_id
      ) - 1) / 250)::integer AS page_index
    FROM browser_catalog.instrument_discovery_characteristic_rows
    WHERE generation = characteristic_generation
  ), grouped AS (
    SELECT
      page_index,
      jsonb_agg(item ORDER BY characteristic_key, instrument_id) AS items
    FROM numbered
    GROUP BY page_index
  )
  INSERT INTO browser_catalog.instrument_discovery_resource_pages (
    resource_key,
    generation,
    page_index,
    row_count,
    items
  )
  SELECT
    'characteristics',
    characteristic_generation,
    page_index,
    jsonb_array_length(items),
    items
  FROM grouped;

  SELECT
    COALESCE(sum(row_count), 0)::integer,
    count(*)::integer
  INTO characteristic_count, characteristic_page_count
  FROM browser_catalog.instrument_discovery_resource_pages
  WHERE resource_key = 'characteristics'
    AND generation = characteristic_generation;

  IF characteristic_count <> jsonb_array_length(rows)
    OR characteristic_count <> (
      SELECT COALESCE(sum((item ->> 'rowCount')::integer), 0)::integer
      FROM jsonb_array_elements(adopted) AS input(item)
    )
  THEN
    RAISE EXCEPTION 'Instrument Discovery Characteristic publication parity failed';
  END IF;

  INSERT INTO browser_catalog.instrument_discovery_resource_generations (
    resource_key,
    generation,
    source_revision,
    instrument_revision,
    registry_version,
    adoption_revision,
    adopted,
    row_count,
    page_count,
    generated_at,
    retained_until
  ) VALUES (
    'characteristics',
    characteristic_generation,
    p_source_revision,
    instrument_revision,
    p_registry_version,
    p_adoption_revision,
    adopted,
    characteristic_count,
    characteristic_page_count,
    generated_at,
    generated_at + interval '24 hours'
  );

  RETURN jsonb_build_object(
    'publicationStatus', 'staging',
    'sourceRevision', p_source_revision,
    'instrumentGeneration', instrument_generation,
    'tagGeneration', tag_generation,
    'cueGeneration', cue_generation,
    'characteristicGeneration', characteristic_generation,
    'expectedInstrumentGeneration', instrument_generation,
    'expectedTagGeneration', tag_generation,
    'expectedCueGeneration', cue_generation,
    'expectedCharacteristicGeneration', prior_characteristic_generation,
    'resources', jsonb_build_array(
      jsonb_build_object(
        'resource', 'characteristics',
        'generation', characteristic_generation,
        'pageCount', characteristic_page_count
      )
    )
  );
END;
$_$;


ALTER FUNCTION "public"."publish_instrument_discovery_characteristics"("p_source_revision" "text", "p_adoption_revision" "text", "p_registry_version" "text", "p_rows" "jsonb", "p_adopted" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."publish_instrument_discovery_characteristics"("p_source_revision" "text", "p_adoption_revision" "text", "p_registry_version" "text", "p_rows" "jsonb", "p_adopted" "jsonb") IS 'Service-role-only staging of compact current Characteristic summaries and exact canonical adoption identities; evidence artifacts and explanations are rejected.';



CREATE OR REPLACE FUNCTION "public"."published_sample_analysis_ready_for_profile_v1"("p_instrument_v2_id" "uuid") RETURNS TABLE("ready" boolean, "source_signature" "text", "asset_count" integer, "completed_asset_count" integer, "failed_asset_count" integer, "pending_asset_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH expected AS (
    SELECT count(*)::integer n
    FROM public.sample_path_constructs
    WHERE instrument_v2_id = p_instrument_v2_id
  ), status AS (
    SELECT status.*
    FROM public.published_sample_analysis_status_v1 status
    JOIN public.sample_path_constructs construct
      ON construct.id = status.sample_path_construct_id
     AND construct.instrument_v2_id = p_instrument_v2_id
    WHERE status.instrument_v2_id = p_instrument_v2_id
      AND status.is_current
  ), summary AS (
    SELECT
      count(*)::integer assets,
      count(*) FILTER (
        WHERE analysis_status IN ('complete', 'excluded')
      )::integer completed,
      count(*) FILTER (WHERE analysis_status = 'failed')::integer failed,
      count(*) FILTER (
        WHERE analysis_status IN ('pending', 'running')
      )::integer pending,
      public.audio_profile_v1_hash(jsonb_agg(jsonb_build_object(
        'constructId', sample_path_construct_id,
        'signature', source_signature,
        'status', analysis_status
      ) ORDER BY sample_path_construct_id)) signature
    FROM status
  )
  SELECT
    expected.n > 0
      AND summary.assets = expected.n
      AND summary.completed = expected.n,
    summary.signature,
    summary.assets,
    summary.completed,
    summary.failed,
    summary.pending
  FROM expected CROSS JOIN summary;
$$;


ALTER FUNCTION "public"."published_sample_analysis_ready_for_profile_v1"("p_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."published_sample_analysis_status_v1" AS
SELECT
    NULL::"uuid" AS "instrument_v2_id",
    NULL::"uuid" AS "published_asset_id",
    NULL::"uuid" AS "sample_path_construct_id",
    NULL::"uuid" AS "sample_original_path_id",
    NULL::"text" AS "source_signature",
    NULL::"text" AS "analysis_version",
    NULL::boolean AS "is_current",
    NULL::"text" AS "exclusion_reason",
    NULL::integer AS "job_count",
    NULL::integer AS "completed_job_count",
    NULL::integer AS "pending_job_count",
    NULL::integer AS "failed_job_count",
    NULL::"text" AS "analysis_status";


ALTER TABLE "public"."published_sample_analysis_status_v1" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."published_sample_analysis_status_v1"("p_instrument_v2_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."published_sample_analysis_status_v1"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT * FROM public.published_sample_analysis_status_v1 status
  WHERE p_instrument_v2_id IS NULL OR status.instrument_v2_id=p_instrument_v2_id
  ORDER BY status.instrument_v2_id,status.sample_path_construct_id;
$$;


ALTER FUNCTION "public"."published_sample_analysis_status_v1"("p_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."published_sample_temporal_ready_for_profile_v1"("p_instrument_v2_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH base AS (
    SELECT ready
    FROM public.published_sample_analysis_ready_for_profile_v1(
      p_instrument_v2_id
    )
  ), expected AS (
    SELECT asset.id, asset.source_signature
    FROM public.sample_s3_path asset
    JOIN public.sample_path_constructs construct
      ON construct.id = asset.sample_path_construct_id
     AND construct.instrument_v2_id = p_instrument_v2_id
    WHERE asset.instrument_v2_id = p_instrument_v2_id
      AND asset.is_current
      AND asset.excluded_at IS NULL
  ), matched AS (
    SELECT count(*)::integer AS count
    FROM expected asset
    JOIN public.sample_analysis_temporal temporal
      ON temporal.published_asset_id = asset.id
     AND temporal.source_signature = asset.source_signature
     AND temporal.analysis_version = 'temporal-v1'
     AND temporal.algorithm_version = 'global-temporal-pcm-v1'
  )
  SELECT coalesce((SELECT ready FROM base), false)
    AND (SELECT count(*) FROM expected) = (SELECT count FROM matched);
$$;


ALTER FUNCTION "public"."published_sample_temporal_ready_for_profile_v1"("p_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rank_blog_posts_by_content"("query_embedding" "extensions"."vector", "match_count" integer) RETURNS TABLE("id" "uuid", "created_at" timestamp without time zone, "img_url" "text", "description" "text", "author" "text", "slug" "text", "title" "text", "similarity" double precision, "blog_post_tags" "json")
    LANGUAGE "plpgsql"
    AS $$BEGIN
  RETURN QUERY
  SELECT
    bp.id,
    bp.created_at::timestamp,
    bp.img_url,
    bp.description,
    bp.author,
    bp.slug,
    bp.title,
    1 - (bp.content_embedding <=> query_embedding) as similarity,
    JSON_AGG(
      JSON_BUILD_OBJECT(
        'tag_id', JSON_BUILD_OBJECT(
          'id', bt.id,
          'name', bt.name
        )
      )
    ) AS blog_post_tags
  FROM
    blog_posts bp
  LEFT JOIN
    blog_post_tags bpt ON bp.id = bpt.post_id
  LEFT JOIN
    blog_tags bt ON bpt.tag_id = bt.id
  GROUP BY
    bp.id, bp.created_at, bp.img_url, bp.description, bp.author, bp.title
  ORDER BY
    similarity DESC
  LIMIT
    match_count;
END;$$;


ALTER FUNCTION "public"."rank_blog_posts_by_content"("query_embedding" "extensions"."vector", "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rank_blog_posts_by_tags"("query_embedding" "extensions"."vector", "match_count" integer) RETURNS TABLE("id" "uuid", "created_at" timestamp without time zone, "img_url" "text", "description" "text", "author" "text", "slug" "text", "title" "text", "similarity" double precision, "blog_post_tags" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    bp.id,
    bp.created_at::timestamp,
    bp.img_url,
    bp.description,
    bp.author,
    bp.slug,
    bp.title,
    1 - (bp.tag_embedding <=> query_embedding) as similarity,
    JSON_AGG(
      JSON_BUILD_OBJECT(
        'tag_id', JSON_BUILD_OBJECT(
          'id', bt.id,
          'name', bt.name
        )
      )
    )::jsonb AS blog_post_tags
  FROM
    blog_posts bp
  LEFT JOIN
    blog_post_tags bpt ON bp.id = bpt.post_id
  LEFT JOIN
    blog_tags bt ON bpt.tag_id = bt.id
  GROUP BY
    bp.id, bp.created_at, bp.img_url, bp.description, bp.author, bp.title
  ORDER BY
    similarity DESC
  LIMIT
    match_count;
END;
$$;


