CREATE OR REPLACE FUNCTION "public"."rank_market_patterns"("target" "text", "embedding_space" "text", "query_embedding" "extensions"."vector", "match_count" integer DEFAULT 20, "candidate_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("market_pattern_id" "uuid", "similarity" double precision)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $_$
DECLARE
  normalized_match_count integer := LEAST(GREATEST(COALESCE(match_count, 20), 1), 50);
BEGIN
  IF target NOT IN (
    'meta',
    'instrument_name',
    'instrument_family',
    'pattern_type',
    'bpm',
    'key',
    'scale_quality',
    'mood',
    'time_signature_numerator',
    'time_signature_denominator',
    'duration_seconds',
    'search_tokens',
    'sample_id',
    'pitch_shift',
    'is_reverse',
    'pattern',
    'envelope',
    'swell',
    'humanize',
    'delay',
    'chords'
  ) THEN
    RAISE EXCEPTION 'Unsupported embedding target: %', target
      USING ERRCODE = '22023';
  END IF;
  IF query_embedding IS NULL OR extensions.vector_dims(query_embedding) <> 256 THEN
    RAISE EXCEPTION 'query_embedding must have exactly 256 dimensions'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT
      embeddings.market_pattern_id,
      CASE target
        WHEN 'meta' THEN embeddings.meta
        WHEN 'instrument_name' THEN embeddings.instrument_name
        WHEN 'instrument_family' THEN embeddings.instrument_family
        WHEN 'pattern_type' THEN embeddings.pattern_type
        WHEN 'bpm' THEN embeddings.bpm
        WHEN 'key' THEN embeddings.key
        WHEN 'scale_quality' THEN embeddings.scale_quality
        WHEN 'mood' THEN embeddings.mood
        WHEN 'time_signature_numerator' THEN embeddings.time_signature_numerator
        WHEN 'time_signature_denominator' THEN embeddings.time_signature_denominator
        WHEN 'duration_seconds' THEN embeddings.duration_seconds
        WHEN 'search_tokens' THEN embeddings.search_tokens
        WHEN 'sample_id' THEN embeddings.sample_id
        WHEN 'pitch_shift' THEN embeddings.pitch_shift
        WHEN 'is_reverse' THEN embeddings.is_reverse
        WHEN 'pattern' THEN embeddings.pattern
        WHEN 'envelope' THEN embeddings.envelope
        WHEN 'swell' THEN embeddings.swell
        WHEN 'humanize' THEN embeddings.humanize
        WHEN 'delay' THEN embeddings.delay
        WHEN 'chords' THEN embeddings.chords
      END AS target_embedding
    FROM public.market_pattern_embeddings AS embeddings
    WHERE embeddings.embedding_space = $2
      AND ($5 IS NULL OR embeddings.market_pattern_id = ANY($5))
      AND EXISTS (
        SELECT 1
        FROM public.market_patterns_loops_unique_feed_v1 AS feed
        WHERE feed.id = embeddings.market_pattern_id
      )
  )
  SELECT
    candidates.market_pattern_id,
    1 - (candidates.target_embedding <=> query_embedding) AS similarity
  FROM candidates
  WHERE candidates.target_embedding IS NOT NULL
  ORDER BY
    candidates.target_embedding <=> query_embedding,
    candidates.market_pattern_id
  LIMIT normalized_match_count;
END;
$_$;


ALTER FUNCTION "public"."rank_market_patterns"("target" "text", "embedding_space" "text", "query_embedding" "extensions"."vector", "match_count" integer, "candidate_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rank_market_songs_by_embedding"("target" "text", "embedding_space" "text", "query_embedding" "extensions"."vector", "match_count" integer DEFAULT 20) RETURNS TABLE("market_song_id" "uuid", "similarity" double precision)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  normalized_match_count integer :=
    LEAST(GREATEST(COALESCE(match_count, 20), 1), 50);
BEGIN
  IF target NOT IN ('meta', 'genre', 'instrumentation', 'characteristics') THEN
    RAISE EXCEPTION 'Unsupported embedding target: %', target
      USING ERRCODE = '22023';
  END IF;

  IF query_embedding IS NULL
    OR extensions.vector_dims(query_embedding) <> 256
  THEN
    RAISE EXCEPTION 'query_embedding must have exactly 256 dimensions'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT
      embeddings.market_song_id,
      CASE target
        WHEN 'meta' THEN embeddings.meta
        WHEN 'genre' THEN embeddings.genre
        WHEN 'instrumentation' THEN embeddings.instrumentation
        WHEN 'characteristics' THEN embeddings.characteristics
      END AS target_embedding
    FROM public.market_song_embeddings AS embeddings
    INNER JOIN public.market_songs AS songs
      ON songs.id = embeddings.market_song_id
    WHERE embeddings.embedding_space =
      rank_market_songs_by_embedding.embedding_space
      AND songs.is_published
  )
  SELECT
    candidates.market_song_id,
    1 - (
      candidates.target_embedding
        OPERATOR(extensions.<=>)
      query_embedding
    ) AS similarity
  FROM candidates
  ORDER BY
    candidates.target_embedding OPERATOR(extensions.<=>) query_embedding,
    candidates.market_song_id
  LIMIT normalized_match_count;
END;
$$;


ALTER FUNCTION "public"."rank_market_songs_by_embedding"("target" "text", "embedding_space" "text", "query_embedding" "extensions"."vector", "match_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rank_market_songs_by_embedding"("target" "text", "embedding_space" "text", "query_embedding" "extensions"."vector", "match_count" integer) IS 'Service-role-only exact cosine ranking of canonical published Market song embeddings.';



CREATE OR REPLACE FUNCTION "public"."rank_market_style_songs_by_column"("target_column_name" "text", "query_embedding" "extensions"."vector", "match_count" integer DEFAULT NULL::integer) RETURNS TABLE("market_style_song_id" "uuid", "similarity" double precision)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  normalized_match_count integer := LEAST(GREATEST(COALESCE(match_count, 20), 1), 50);
BEGIN
  IF target_column_name NOT IN ('meta', 'genre', 'instrumentation', 'characteristics') THEN
    RAISE EXCEPTION 'Unsupported embedding target: %', target_column_name
      USING ERRCODE = '22023';
  END IF;

  IF query_embedding IS NULL OR extensions.vector_dims(query_embedding) <> 256 THEN
    RAISE EXCEPTION 'query_embedding must have exactly 256 dimensions'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT
      legacy.market_style_song_id,
      CASE target_column_name
        WHEN 'meta' THEN legacy.meta
        WHEN 'genre' THEN legacy.genre
        WHEN 'instrumentation' THEN legacy.instrumentation
        WHEN 'characteristics' THEN legacy.characteristics
      END AS target_embedding
    FROM public.market_style_song_embeddings AS legacy
    WHERE EXISTS (
      SELECT 1
      FROM public.market_songs AS songs
      WHERE songs.is_published = true
        AND (
          songs.id = legacy.market_style_song_id
          OR songs.legacy_market_style_song_id = legacy.market_style_song_id
        )
    )
  )
  SELECT
    candidates.market_style_song_id,
    1 - (candidates.target_embedding <=> query_embedding) AS similarity
  FROM candidates
  WHERE candidates.target_embedding IS NOT NULL
  ORDER BY candidates.target_embedding <=> query_embedding
  LIMIT normalized_match_count;
END;
$$;


ALTER FUNCTION "public"."rank_market_style_songs_by_column"("target_column_name" "text", "query_embedding" "extensions"."vector", "match_count" integer) OWNER TO "postgres";


