    projection.resource_id,
    projection.instrument,
    projection.aliases,
    projection.legacy_instruments,
    projection.tags,
    projection.profile_metadata,
    projection.profile_embedding
  FROM browser_catalog.instrument_projection_rows AS projection
  WHERE projection.server_generation = p_server_generation
    AND (
      p_resource_ids IS NULL
