CREATE OR REPLACE FUNCTION "public"."read_current_sample_psychoacoustic_results_v1"("p_requests" "jsonb") RETURNS TABLE("ordinal" integer, "currentness" "text", "result_payload" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF jsonb_typeof(p_requests) <> 'array' THEN
    RAISE EXCEPTION 'p_requests must be a JSON array' USING ERRCODE = '22023';
  END IF;
  v_count := jsonb_array_length(p_requests);
  IF v_count < 1 OR v_count > 100 THEN
    RAISE EXCEPTION 'p_requests must contain 1 to 100 identities'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_requests) AS item
    GROUP BY item
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'p_requests contains duplicate identities'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH requested AS (
    SELECT
      item.ordinality::integer AS ordinal,
      (item.value->>'publishedAssetId')::uuid AS published_asset_id,
      item.value->>'assetSourceSignature' AS asset_source_signature,
      item.value->>'characteristicKey' AS characteristic_key,
      item.value->>'evidenceContractVersion' AS evidence_contract_version,
      item.value->>'algorithmVersion' AS algorithm_version,
      item.value->>'projectionVersion' AS projection_version
    FROM jsonb_array_elements(p_requests) WITH ORDINALITY AS item(value, ordinality)
  )
  SELECT
    requested.ordinal,
    CASE
      WHEN asset.id IS NULL THEN 'missing'
      WHEN asset.source_signature <> requested.asset_source_signature
        THEN 'source_signature_mismatch'
      WHEN NOT asset.is_current
        OR asset.quality IS DISTINCT FROM 1
        OR asset.format IS DISTINCT FROM 'mp3'
        THEN 'asset_not_current'
      WHEN asset.excluded_at IS NOT NULL THEN 'asset_excluded'
      WHEN result.id IS NULL THEN 'missing'
      ELSE 'current'
    END,
    CASE
      WHEN asset.id IS NOT NULL
        AND asset.source_signature = requested.asset_source_signature
        AND asset.is_current
        AND asset.excluded_at IS NULL
        AND asset.quality = 1
        AND asset.format = 'mp3'
        AND result.id IS NOT NULL
      THEN result.result_payload
      ELSE NULL
    END
  FROM requested
  LEFT JOIN public.sample_s3_path AS asset
    ON asset.id = requested.published_asset_id
  LEFT JOIN public.sample_psychoacoustic_characteristic_results AS result
    ON result.published_asset_id = requested.published_asset_id
    AND result.asset_source_signature = requested.asset_source_signature
    AND result.characteristic_key = requested.characteristic_key
    AND result.evidence_contract_version = requested.evidence_contract_version
    AND result.algorithm_version = requested.algorithm_version
    AND result.projection_version IS NOT DISTINCT FROM requested.projection_version
  ORDER BY requested.ordinal;
END;
$$;


ALTER FUNCTION "public"."read_current_sample_psychoacoustic_results_v1"("p_requests" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_instrument_discovery_candidate_page"("p_resource" "text", "p_generation" "uuid", "p_page_index" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT jsonb_build_object(
    'schemaVersion', generation.schema_version,
    'resource', generation.resource_key,
    'generation', generation.generation::text,
    'sourceRevision', generation.source_revision,
    'pageIndex', page.page_index,
    'rowCount', page.row_count,
    'items', page.items
  )
  FROM browser_catalog.instrument_discovery_resource_generations AS generation
  INNER JOIN browser_catalog.instrument_discovery_resource_pages AS page
    ON page.resource_key = generation.resource_key
   AND page.generation = generation.generation
  WHERE generation.resource_key = p_resource
    AND generation.generation = p_generation
    AND page.page_index = p_page_index
    AND p_resource IN ('instruments', 'tags', 'cues', 'characteristics')
    AND p_page_index >= 0
    AND (
      (
        generation.publication_status = 'staging'
        AND generation.retained_until > pg_catalog.now()
      )
      OR (
        generation.publication_status = 'sealed'
        AND EXISTS (
          SELECT 1
          FROM browser_catalog.instrument_discovery_state AS state
          WHERE state.singleton
            AND generation.generation = CASE generation.resource_key
              WHEN 'instruments' THEN state.instrument_generation
              WHEN 'tags' THEN state.tag_generation
              WHEN 'cues' THEN state.cue_generation
              WHEN 'characteristics' THEN state.characteristic_generation
            END
        )
      )
    );
$$;


ALTER FUNCTION "public"."read_instrument_discovery_candidate_page"("p_resource" "text", "p_generation" "uuid", "p_page_index" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."read_instrument_discovery_candidate_page"("p_resource" "text", "p_generation" "uuid", "p_page_index" integer) IS 'Service-role-only bounded read of an exact staged or active page for shared-contract hashing and idempotent retries.';



CREATE OR REPLACE FUNCTION "public"."read_instrument_discovery_cues_v1"("p_instrument_id" "uuid", "p_cue_kind" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  WITH active AS MATERIALIZED (
    SELECT
      state.instrument_generation,
      state.tag_generation,
      state.cue_generation,
      state.characteristic_generation
    FROM browser_catalog.instrument_discovery_state AS state
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS instruments
      ON instruments.resource_key = 'instruments'
     AND instruments.generation = state.instrument_generation
     AND instruments.publication_status = 'sealed'
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS tags
      ON tags.resource_key = 'tags'
     AND tags.generation = state.tag_generation
     AND tags.publication_status = 'sealed'
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS cues
      ON cues.resource_key = 'cues'
     AND cues.generation = state.cue_generation
     AND cues.publication_status = 'sealed'
     AND cues.instrument_revision = instruments.source_revision
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS characteristics
      ON characteristics.resource_key = 'characteristics'
     AND characteristics.generation = state.characteristic_generation
     AND characteristics.publication_status = 'sealed'
    WHERE state.singleton
  )
  SELECT pg_catalog.jsonb_build_object(
    'items', COALESCE((
      SELECT pg_catalog.jsonb_agg(
        cue.item
        ORDER BY cue.construct_id ASC
      )
      FROM browser_catalog.instrument_discovery_cue_rows AS cue
      WHERE cue.generation = active.cue_generation
        AND cue.instrument_id = p_instrument_id
        AND CASE p_cue_kind
          WHEN 'swell' THEN (cue.item ->> 'swellEligible')::boolean
          WHEN 'crash' THEN (cue.item ->> 'crashEligible')::boolean
          ELSE p_cue_kind IS NULL
        END
    ), '[]'::jsonb)
  )
  FROM active;
$$;


ALTER FUNCTION "public"."read_instrument_discovery_cues_v1"("p_instrument_id" "uuid", "p_cue_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_instrument_discovery_filter_options_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  WITH active AS MATERIALIZED (
    SELECT
      state.instrument_generation,
      state.tag_generation,
      state.cue_generation,
      state.characteristic_generation
    FROM browser_catalog.instrument_discovery_state AS state
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS instruments
      ON instruments.resource_key = 'instruments'
     AND instruments.generation = state.instrument_generation
     AND instruments.publication_status = 'sealed'
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS tags
      ON tags.resource_key = 'tags'
     AND tags.generation = state.tag_generation
     AND tags.publication_status = 'sealed'
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS cues
      ON cues.resource_key = 'cues'
     AND cues.generation = state.cue_generation
     AND cues.publication_status = 'sealed'
     AND cues.instrument_revision = instruments.source_revision
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS characteristics
      ON characteristics.resource_key = 'characteristics'
     AND characteristics.generation = state.characteristic_generation
     AND characteristics.publication_status = 'sealed'
    WHERE state.singleton
  )
  SELECT pg_catalog.jsonb_build_object(
    'families', COALESCE((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('value', value, 'label', value)
        ORDER BY value COLLATE "C"
      )
      FROM (
        SELECT DISTINCT row.item ->> 'family' AS value
        FROM browser_catalog.instrument_discovery_instrument_rows AS row
        WHERE row.generation = active.instrument_generation
          AND row.item ->> 'assetRole' = 'playable_sample'
          AND row.item ->> 'visibilityRole' IN ('normal', 'normal_and_cue')
          AND NULLIF(row.item ->> 'family', '') IS NOT NULL
      ) AS values
    ), '[]'::jsonb),
    'types', COALESCE((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('value', value, 'label', value)
        ORDER BY value COLLATE "C"
      )
      FROM (
        SELECT DISTINCT row.item ->> 'instrumentType' AS value
        FROM browser_catalog.instrument_discovery_instrument_rows AS row
        WHERE row.generation = active.instrument_generation
          AND row.item ->> 'assetRole' = 'playable_sample'
          AND row.item ->> 'visibilityRole' IN ('normal', 'normal_and_cue')
          AND NULLIF(row.item ->> 'instrumentType', '') IS NOT NULL
      ) AS values
    ), '[]'::jsonb),
    'providers', COALESCE((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('value', value, 'label', label)
        ORDER BY label COLLATE "C", value COLLATE "C"
      )
      FROM (
        SELECT
          row.item ->> 'providerId' AS value,
          pg_catalog.min((
            COALESCE(
              NULLIF(row.item ->> 'providerName', ''),
              row.item ->> 'providerId'
            )
          ) COLLATE "C") AS label
        FROM browser_catalog.instrument_discovery_instrument_rows AS row
        WHERE row.generation = active.instrument_generation
          AND row.item ->> 'assetRole' = 'playable_sample'
          AND row.item ->> 'visibilityRole' IN ('normal', 'normal_and_cue')
          AND NULLIF(row.item ->> 'providerId', '') IS NOT NULL
        GROUP BY row.item ->> 'providerId'
      ) AS values
    ), '[]'::jsonb),
    'collections', COALESCE((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('value', value, 'label', value)
        ORDER BY value COLLATE "C"
      )
      FROM (
        SELECT DISTINCT row.item ->> 'collection' AS value
        FROM browser_catalog.instrument_discovery_instrument_rows AS row
        WHERE row.generation = active.instrument_generation
          AND row.item ->> 'assetRole' = 'playable_sample'
          AND row.item ->> 'visibilityRole' IN ('normal', 'normal_and_cue')
          AND NULLIF(row.item ->> 'collection', '') IS NOT NULL
      ) AS values
    ), '[]'::jsonb),
    'tags', COALESCE((
      SELECT pg_catalog.jsonb_agg(
        row.item
        ORDER BY
          (row.item ->> 'name') COLLATE "C",
          (row.item ->> 'id') COLLATE "C"
      )
      FROM browser_catalog.instrument_discovery_tag_rows AS row
      WHERE row.generation = active.tag_generation
        AND row.item ->> 'kind' = 'tag'
        AND EXISTS (
          SELECT 1
          FROM browser_catalog.instrument_discovery_tag_rows AS link
          INNER JOIN browser_catalog.instrument_discovery_instrument_rows
            AS instrument
            ON instrument.generation = active.instrument_generation
           AND instrument.instrument_id =
             (link.item ->> 'instrumentId')::uuid
           AND instrument.item ->> 'assetRole' = 'playable_sample'
           AND instrument.item ->> 'visibilityRole'
             IN ('normal', 'normal_and_cue')
          WHERE link.generation = active.tag_generation
            AND link.item ->> 'kind' = 'instrument_tag'
            AND link.item ->> 'tagId' = row.item ->> 'id'
        )
    ), '[]'::jsonb)
  )
  FROM active;
$$;


ALTER FUNCTION "public"."read_instrument_discovery_filter_options_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_instrument_discovery_manifest"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  WITH active AS (
    SELECT *
    FROM browser_catalog.instrument_discovery_state
    WHERE singleton AND instrument_generation IS NOT NULL
  ), descriptors AS (
    SELECT generation.*,
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'index', page.page_index,
              'rowCount', page.row_count,
              'decodedBytes', page.decoded_bytes,
              'checksum', page.checksum
            )
            ORDER BY page.page_index
          )
          FROM browser_catalog.instrument_discovery_resource_pages AS page
          WHERE page.resource_key = generation.resource_key
            AND page.generation = generation.generation
        ),
        '[]'::jsonb
      ) AS pages
    FROM browser_catalog.instrument_discovery_resource_generations AS generation
    INNER JOIN active ON generation.generation IN (
      active.instrument_generation,
      active.tag_generation,
      active.cue_generation,
      active.characteristic_generation
    )
  )
  SELECT jsonb_build_object(
    'schemaVersion', 2,
    'manifestRevision', active.manifest_revision,
    'generatedAt', pg_catalog.to_char(
      active.generated_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    ),
    'resources', jsonb_build_object(
      'instruments', jsonb_build_object(
        'key', 'instruments',
        'generation', instrument.generation::text,
        'schemaVersion', instrument.schema_version,
        'sourceRevision', instrument.source_revision,
        'etag', instrument.etag,
        'checksum', instrument.checksum,
        'rowCount', instrument.row_count,
        'pageCount', instrument.page_count,
        'pages', instrument.pages
      ),
      'tags', jsonb_build_object(
        'key', 'tags',
        'generation', tags.generation::text,
        'schemaVersion', tags.schema_version,
        'sourceRevision', tags.source_revision,
        'instrumentRevision', tags.instrument_revision,
        'etag', tags.etag,
        'checksum', tags.checksum,
        'rowCount', tags.row_count,
        'pageCount', tags.page_count,
        'pages', tags.pages
      ),
      'cues', jsonb_build_object(
        'key', 'cues',
        'generation', cues.generation::text,
        'schemaVersion', cues.schema_version,
        'sourceRevision', cues.source_revision,
        'instrumentRevision', cues.instrument_revision,
        'etag', cues.etag,
        'checksum', cues.checksum,
        'rowCount', cues.row_count,
        'pageCount', cues.page_count,
        'pages', cues.pages
      ),
      'characteristics', jsonb_build_object(
        'key', 'characteristics',
        'generation', characteristics.generation::text,
        'schemaVersion', characteristics.schema_version,
        'sourceRevision', characteristics.source_revision,
        'instrumentRevision', characteristics.instrument_revision,
        'registryVersion', characteristics.registry_version,
        'adoptionRevision', characteristics.adoption_revision,
        'adopted', characteristics.adopted,
        'etag', characteristics.etag,
        'checksum', characteristics.checksum,
        'rowCount', characteristics.row_count,
        'pageCount', characteristics.page_count,
        'pages', characteristics.pages
      )
    )
  )
  FROM active
  INNER JOIN descriptors AS instrument
    ON instrument.resource_key = 'instruments'
   AND instrument.generation = active.instrument_generation
  INNER JOIN descriptors AS tags
    ON tags.resource_key = 'tags'
   AND tags.generation = active.tag_generation
  INNER JOIN descriptors AS cues
    ON cues.resource_key = 'cues'
   AND cues.generation = active.cue_generation
  INNER JOIN descriptors AS characteristics
    ON characteristics.resource_key = 'characteristics'
   AND characteristics.generation = active.characteristic_generation;
$$;


ALTER FUNCTION "public"."read_instrument_discovery_manifest"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."read_instrument_discovery_manifest"() IS 'Service-role-only read of the active four-resource Instrument Discovery manifest.';



CREATE OR REPLACE FUNCTION "public"."read_instrument_discovery_resource_descriptor"("p_resource" "text", "p_generation" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT jsonb_build_object(
      'generation', generation.generation::text,
      'schemaVersion', generation.schema_version,
      'sourceRevision', generation.source_revision,
      'etag', generation.etag,
      'checksum', generation.checksum,
      'rowCount', generation.row_count,
      'pageCount', generation.page_count,
      'pages', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'index', page.page_index,
              'rowCount', page.row_count,
              'decodedBytes', page.decoded_bytes,
              'checksum', page.checksum
            )
            ORDER BY page.page_index
          )
          FROM browser_catalog.instrument_discovery_resource_pages AS page
          WHERE page.resource_key = generation.resource_key
            AND page.generation = generation.generation
        ),
        '[]'::jsonb
      )
    ) || CASE
      WHEN generation.resource_key IN ('tags', 'cues') THEN
        jsonb_build_object(
          'instrumentRevision', generation.instrument_revision
        )
      WHEN generation.resource_key = 'characteristics' THEN
        jsonb_build_object(
          'instrumentRevision', generation.instrument_revision,
          'registryVersion', generation.registry_version,
          'adoptionRevision', generation.adoption_revision,
          'adopted', generation.adopted
        )
      ELSE '{}'::jsonb
    END
  FROM browser_catalog.instrument_discovery_resource_generations AS generation
  WHERE p_resource IN ('instruments', 'tags', 'cues', 'characteristics')
    AND generation.resource_key = p_resource
    AND generation.generation = p_generation
    AND generation.publication_status = 'sealed'
    AND (
      generation.retained_until > pg_catalog.now()
      OR EXISTS (
        SELECT 1
        FROM browser_catalog.instrument_discovery_state AS state
        WHERE state.singleton
          AND (
            (p_resource = 'instruments'
              AND state.instrument_generation = generation.generation)
            OR (p_resource = 'tags'
              AND state.tag_generation = generation.generation)
            OR (p_resource = 'cues'
              AND state.cue_generation = generation.generation)
            OR (p_resource = 'characteristics'
              AND state.characteristic_generation = generation.generation)
          )
      )
    );
$$;


ALTER FUNCTION "public"."read_instrument_discovery_resource_descriptor"("p_resource" "text", "p_generation" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."read_instrument_discovery_resource_descriptor"("p_resource" "text", "p_generation" "uuid") IS 'Service-role-only descriptor lookup for one active or unexpired retained immutable Instrument Discovery generation.';



CREATE OR REPLACE FUNCTION "public"."read_instrument_discovery_resource_page"("p_resource" "text", "p_generation" "uuid", "p_page_index" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT jsonb_build_object(
    'schemaVersion', generation.schema_version,
    'resource', generation.resource_key,
    'generation', generation.generation::text,
    'sourceRevision', generation.source_revision,
    'pageIndex', page.page_index,
    'rowCount', page.row_count,
    'decodedBytes', page.decoded_bytes,
    'checksum', page.checksum,
    'items', page.items
  )
  FROM browser_catalog.instrument_discovery_resource_generations AS generation
  INNER JOIN browser_catalog.instrument_discovery_resource_pages AS page
    ON page.resource_key = generation.resource_key
   AND page.generation = generation.generation
  WHERE p_resource IN ('instruments', 'tags', 'cues', 'characteristics')
    AND generation.resource_key = p_resource
    AND generation.generation = p_generation
    AND generation.publication_status = 'sealed'
    AND page.page_index = p_page_index
    AND p_page_index >= 0
    AND (
      generation.retained_until > pg_catalog.now()
      OR EXISTS (
        SELECT 1
        FROM browser_catalog.instrument_discovery_state AS state
        WHERE state.singleton
          AND (
            (p_resource = 'instruments'
              AND state.instrument_generation = generation.generation)
            OR (p_resource = 'tags'
              AND state.tag_generation = generation.generation)
            OR (p_resource = 'cues'
              AND state.cue_generation = generation.generation)
            OR (p_resource = 'characteristics'
              AND state.characteristic_generation = generation.generation)
          )
      )
    );
$$;


ALTER FUNCTION "public"."read_instrument_discovery_resource_page"("p_resource" "text", "p_generation" "uuid", "p_page_index" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."read_instrument_discovery_resource_page"("p_resource" "text", "p_generation" "uuid", "p_page_index" integer) IS 'Service-role-only read of one active or unexpired retained immutable Instrument Discovery page.';



CREATE TABLE IF NOT EXISTS "public"."sip_pipeline_run_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "run_id" "uuid" NOT NULL,
    "run_item_id" "uuid",
    "staging_instrument_id" "uuid",
    "stage" "text",
    "event_type" "text" NOT NULL,
    "message" "text",
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sip_pipeline_run_events_payload_object" CHECK (("jsonb_typeof"("payload") = 'object'::"text"))
);


ALTER TABLE "public"."sip_pipeline_run_events" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_sip_pipeline_run_event"("p_run_id" "uuid", "p_run_item_id" "uuid" DEFAULT NULL::"uuid", "p_staging_instrument_id" "uuid" DEFAULT NULL::"uuid", "p_stage" "text" DEFAULT NULL::"text", "p_event_type" "text" DEFAULT 'event'::"text", "p_message" "text" DEFAULT NULL::"text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."sip_pipeline_run_events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_event public.sip_pipeline_run_events%ROWTYPE;
BEGIN
  INSERT INTO public.sip_pipeline_run_events (
    run_id,
    run_item_id,
    staging_instrument_id,
    stage,
    event_type,
    message,
    payload
  )
  VALUES (
    p_run_id,
    p_run_item_id,
    p_staging_instrument_id,
    p_stage,
    COALESCE(NULLIF(p_event_type, ''), 'event'),
    p_message,
    COALESCE(p_payload, '{}'::jsonb)
  )
  RETURNING * INTO v_event;

  UPDATE public.sip_pipeline_runs
  SET
    last_event_at = now(),
    updated_at = now()
  WHERE id = p_run_id;

  RETURN v_event;
END;
$$;


ALTER FUNCTION "public"."record_sip_pipeline_run_event"("p_run_id" "uuid", "p_run_item_id" "uuid", "p_staging_instrument_id" "uuid", "p_stage" "text", "p_event_type" "text", "p_message" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_instrument_runtime_sample_manifest_v1"("p_instrument_v2_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_candidate jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'instrument-runtime-sample-manifest:' || p_instrument_v2_id::text,
      0
    )
  );

  v_candidate := public.build_instrument_runtime_sample_manifest_v1(
    p_instrument_v2_id
  );

  INSERT INTO public.instrument_runtime_sample_manifests (
    instrument_v2_id,
    schema_version,
    variants,
    variant_count,
    manifest_sha256,
    is_complete,
    blocking_reasons,
    generated_at
  ) VALUES (
    p_instrument_v2_id,
    (v_candidate ->> 'schemaVersion')::smallint,
    v_candidate -> 'variants',
    (v_candidate ->> 'variantCount')::integer,
    v_candidate ->> 'manifestSha256',
    (v_candidate ->> 'isComplete')::boolean,
    v_candidate -> 'blockingReasons',
    now()
  )
  ON CONFLICT (instrument_v2_id) DO UPDATE SET
    schema_version = EXCLUDED.schema_version,
    variants = EXCLUDED.variants,
    variant_count = EXCLUDED.variant_count,
    manifest_sha256 = EXCLUDED.manifest_sha256,
    is_complete = EXCLUDED.is_complete,
    blocking_reasons = EXCLUDED.blocking_reasons,
    generated_at = EXCLUDED.generated_at;

  RETURN v_candidate;
END;
$$;


ALTER FUNCTION "public"."refresh_instrument_runtime_sample_manifest_v1"("p_instrument_v2_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_instrument_runtime_sample_manifest_v1"("p_instrument_v2_id" "uuid") IS 'Materializes one candidate under an instrument-scoped advisory lock. This migration intentionally adds no promotion/backfill callsite.';



CREATE OR REPLACE FUNCTION "public"."refresh_instrument_v2_axis_summaries_v1"("p_instrument_v2_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_updated_count integer;
BEGIN
  WITH requested AS (
    SELECT DISTINCT unnest(p_instrument_v2_ids) AS instrument_id
  ), normalized_constructs AS (
    SELECT
      requested.instrument_id,
      coalesce(nullif(btrim(construct.pitch_content), ''), '0') AS pitch_content,
      greatest(coalesce(construct.velocity, 0), 0) AS velocity,
      greatest(coalesce(construct.round_robin, 0), 0) AS round_robin,
      coalesce(nullif(btrim(construct.mic_position), ''), 'main') AS mic_position,
      btrim(construct.midi_note) AS midi_note,
      btrim(construct.filename) AS filename,
      CASE
        WHEN btrim(construct.midi_note) ~ '^(0|[1-9][0-9]{0,2})$'
          AND btrim(construct.midi_note)::integer BETWEEN 0 AND 127
        THEN btrim(construct.midi_note)::smallint
        ELSE NULL
      END AS numeric_midi_note,
      CASE
        WHEN btrim(construct.midi_note) ~ '^(0|[1-9][0-9]{0,2})$'
          AND btrim(construct.filename) ~ '^(0|[1-9][0-9]{0,2})$'
        THEN btrim(construct.midi_note)::integer BETWEEN 0 AND 127
          AND btrim(construct.filename)::integer BETWEEN 0 AND 127
          AND btrim(construct.midi_note)::integer = btrim(construct.filename)::integer
        ELSE false
      END AS canonical_numeric_address
    FROM requested
    JOIN public.sample_path_constructs construct
      ON construct.instrument_v2_id = requested.instrument_id
  ), construct_axes AS (
    SELECT
      normalized.instrument_id,
      to_jsonb(array_agg(
        DISTINCT normalized.pitch_content
        ORDER BY normalized.pitch_content
      )) AS pitch_contents
    FROM normalized_constructs normalized
    GROUP BY normalized.instrument_id
  ), tonal_anchor_groups AS (
    SELECT
      normalized.instrument_id,
      normalized.pitch_content,
      normalized.velocity,
      normalized.round_robin,
      normalized.mic_position,
      bool_and(normalized.canonical_numeric_address) AS canonical_addresses,
      count(*) = count(DISTINCT normalized.numeric_midi_note) AS one_construct_per_anchor,
      array_agg(
        normalized.numeric_midi_note
        ORDER BY normalized.numeric_midi_note
      ) FILTER (WHERE normalized.numeric_midi_note IS NOT NULL) AS anchors
    FROM normalized_constructs normalized
    GROUP BY
      normalized.instrument_id,
      normalized.pitch_content,
      normalized.velocity,
      normalized.round_robin,
      normalized.mic_position
  ), anchor_summaries AS (
    SELECT
      instrument.id AS instrument_id,
      CASE
        WHEN instrument.engine_type = 'tonal'
          AND (
            instrument.single_pitch IS NULL
            OR (
              instrument.range_lower IS NOT NULL
              AND instrument.range_upper IS NOT NULL
              AND instrument.single_pitch NOT BETWEEN
                least(instrument.range_lower, instrument.range_upper)
                AND greatest(instrument.range_lower, instrument.range_upper)
            )
          )
          AND count(anchor_group.instrument_id) > 0
          AND bool_and(
            anchor_group.canonical_addresses
            AND anchor_group.one_construct_per_anchor
            AND cardinality(anchor_group.anchors) > 0
          )
          AND count(DISTINCT anchor_group.anchors) = 1
        THEN (
          SELECT candidate.anchors
          FROM tonal_anchor_groups candidate
          WHERE candidate.instrument_id = instrument.id
          ORDER BY candidate.anchors::text
          LIMIT 1
        )
        ELSE NULL
      END AS sampled_midi_notes
    FROM requested
    JOIN public.instruments_v2 instrument
      ON instrument.id = requested.instrument_id
    LEFT JOIN tonal_anchor_groups anchor_group
      ON anchor_group.instrument_id = requested.instrument_id
    GROUP BY
      instrument.id,
      instrument.engine_type,
      instrument.single_pitch,
      instrument.range_lower,
      instrument.range_upper
  ), summaries AS (
    SELECT
      axes.instrument_id,
      axes.pitch_contents,
      anchor_summaries.sampled_midi_notes,
      (
        SELECT jsonb_object_agg(pc, velocities)
        FROM (
          SELECT c.pitch_content AS pc,
            to_jsonb(array_agg(DISTINCT c.velocity ORDER BY c.velocity)) AS velocities
          FROM normalized_constructs c
          WHERE c.instrument_id = axes.instrument_id
          GROUP BY c.pitch_content
        ) velocity_summary
      ) AS velocity_layers,
      (
        SELECT jsonb_object_agg(key, values)
        FROM (
          SELECT c.pitch_content || '/' || c.velocity AS key,
            to_jsonb(array_agg(DISTINCT c.round_robin ORDER BY c.round_robin)) AS values
          FROM normalized_constructs c
          WHERE c.instrument_id = axes.instrument_id
          GROUP BY c.pitch_content, c.velocity
        ) round_robin_summary
      ) AS round_robins,
      (
        SELECT jsonb_object_agg(key, values)
        FROM (
          SELECT
            c.pitch_content || '/' || c.velocity || '/' || c.round_robin AS key,
            to_jsonb(array_agg(DISTINCT c.mic_position ORDER BY c.mic_position)) AS values
          FROM normalized_constructs c
          WHERE c.instrument_id = axes.instrument_id
          GROUP BY c.pitch_content, c.velocity, c.round_robin
        ) mic_summary
      ) AS mic_positions
    FROM construct_axes axes
    JOIN anchor_summaries
      ON anchor_summaries.instrument_id = axes.instrument_id
  )
  UPDATE public.instruments_v2 instrument
  SET
    pitch_contents = summaries.pitch_contents,
    velocity_layers = summaries.velocity_layers,
    round_robins = summaries.round_robins,
    mic_positions = summaries.mic_positions,
    sampled_midi_notes = summaries.sampled_midi_notes
  FROM summaries
  WHERE instrument.id = summaries.instrument_id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  RETURN v_updated_count;
END;
$_$;


ALTER FUNCTION "public"."refresh_instrument_v2_axis_summaries_v1"("p_instrument_v2_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_instrument_v2_axis_summaries_v1"("p_instrument_v2_ids" "uuid"[]) IS 'Atomically refreshes Instruments V2 axes and a fail-closed shared tonal MIDI anchor set, ignoring only single-pitch metadata outside the playable range.';



CREATE OR REPLACE FUNCTION "public"."refresh_instrument_v2_runtime_readiness_v1"("p_instrument_v2_id" "uuid", "p_address_pending" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_candidate jsonb;
  v_readiness jsonb;
BEGIN
  v_candidate := public.refresh_instrument_runtime_sample_manifest_v1(
    p_instrument_v2_id
  );
  v_readiness := public.build_instrument_v2_runtime_readiness_v1(
    p_instrument_v2_id,
    v_candidate,
    p_address_pending
  );

  INSERT INTO public.instrument_v2_runtime_readiness (
    instrument_v2_id,
    manifest_sha256,
    variant_count,
    address_ready,
    address_status,
    behavior_ready,
    fallback_eligibility,
    fallback_state,
    blockers,
    evaluated_at
  ) VALUES (
    p_instrument_v2_id,
    v_readiness->>'manifestSha256',
    (v_readiness->>'variantCount')::integer,
    (v_readiness->>'addressReady')::boolean,
    v_readiness->>'addressStatus',
    (v_readiness->>'behaviorReady')::boolean,
    v_readiness->>'fallbackEligibility',
    v_readiness->>'fallbackState',
    v_readiness->'blockers',
    now()
  )
  ON CONFLICT (instrument_v2_id) DO UPDATE SET
    manifest_sha256 = EXCLUDED.manifest_sha256,
    variant_count = EXCLUDED.variant_count,
    address_ready = EXCLUDED.address_ready,
    address_status = EXCLUDED.address_status,
    behavior_ready = EXCLUDED.behavior_ready,
    fallback_eligibility = EXCLUDED.fallback_eligibility,
    fallback_state = EXCLUDED.fallback_state,
    blockers = EXCLUDED.blockers,
    evaluated_at = EXCLUDED.evaluated_at;

  RETURN v_readiness;
END;
$$;


ALTER FUNCTION "public"."refresh_instrument_v2_runtime_readiness_v1"("p_instrument_v2_id" "uuid", "p_address_pending" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_instrument_v2_runtime_readiness_v1"("p_instrument_v2_id" "uuid", "p_address_pending" boolean) IS 'Atomically refreshes the behavior manifest and records separate address/behavior readiness plus the explicit compatibility fallback.';



CREATE OR REPLACE FUNCTION "public"."register_sample_s3_path_v1"("p_instrument_v2_id" "uuid", "p_assets" "jsonb", "p_processing_version" "text", "p_analysis_version" "text" DEFAULT 'post-publish-mp3-v1'::"text", "p_force" boolean DEFAULT false) RETURNS TABLE("asset_id" "uuid", "source_signature" "text", "enqueued_jobs" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_duplicate_construct_id text;
  v_wrong_construct_id text;
BEGIN
  IF jsonb_typeof(p_assets) <> 'array' THEN
    RAISE EXCEPTION 'p_assets must be a JSON array';
  END IF;

  -- Parse and type every row before any data-changing statement. Invalid UUIDs
  -- retain PostgreSQL's prior cast failure behavior.
  SELECT coalesce(parsed."samplePathConstructId"::text, '<null>')
  INTO v_duplicate_construct_id
  FROM jsonb_to_recordset(p_assets) AS parsed(
    "samplePathConstructId" uuid,
    "s3Bucket" text,
    "s3Key" text,
    "objectEtag" text,
    "objectVersion" text
  )
  GROUP BY parsed."samplePathConstructId"
  HAVING count(*) > 1
  LIMIT 1;

  IF v_duplicate_construct_id IS NOT NULL THEN
    RAISE EXCEPTION 'Duplicate construct % in p_assets', v_duplicate_construct_id;
  END IF;

  SELECT coalesce(parsed."samplePathConstructId"::text, '<null>')
  INTO v_wrong_construct_id
  FROM jsonb_to_recordset(p_assets) AS parsed(
    "samplePathConstructId" uuid,
    "s3Bucket" text,
    "s3Key" text,
    "objectEtag" text,
    "objectVersion" text
  )
  LEFT JOIN public.sample_path_constructs construct
    ON construct.id = parsed."samplePathConstructId"
   AND construct.instrument_v2_id = p_instrument_v2_id
  WHERE construct.id IS NULL
  LIMIT 1;

  IF v_wrong_construct_id IS NOT NULL THEN
    RAISE EXCEPTION 'Construct % does not belong to instrument %',
      v_wrong_construct_id, p_instrument_v2_id;
  END IF;

  RETURN QUERY
  WITH input_assets AS MATERIALIZED (
    SELECT
      parsed."samplePathConstructId" AS construct_id,
      raw.ordinality AS input_ordinal,
      construct.sample_original_path_id,
      parsed."s3Bucket" AS s3_bucket,
      parsed."s3Key" AS s3_key,
      nullif(parsed."objectEtag", '') AS object_etag,
      nullif(parsed."objectVersion", '') AS object_version,
      public.audio_profile_v1_hash(jsonb_build_object(
        'bucket', parsed."s3Bucket",
        'key', parsed."s3Key",
        'etag', parsed."objectEtag",
        'objectVersion', parsed."objectVersion",
        'processingVersion', p_processing_version,
        'analysisVersion', p_analysis_version
      )) AS signature
    FROM jsonb_array_elements(p_assets) WITH ORDINALITY AS raw(item, ordinality)
    CROSS JOIN LATERAL jsonb_to_record(raw.item) AS parsed(
      "samplePathConstructId" uuid,
      "s3Bucket" text,
      "s3Key" text,
      "objectEtag" text,
      "objectVersion" text
    )
    JOIN public.sample_path_constructs construct
      ON construct.id = parsed."samplePathConstructId"
     AND construct.instrument_v2_id = p_instrument_v2_id
  ), retired AS (
    UPDATE public.sample_s3_path asset
    SET is_current = false
    FROM input_assets input
    WHERE asset.sample_path_construct_id = input.construct_id
      AND asset.is_current
      AND asset.source_signature <> input.signature
    RETURNING asset.id
  ), upserted AS (
    INSERT INTO public.sample_s3_path(
      sample_path_construct_id,
      sample_original_path_id,
      instrument_v2_id,
      s3_bucket,
      s3_key,
      object_etag,
      object_version,
      processing_version,
      analysis_version,
      source_signature,
      is_current
    )
    SELECT
      input.construct_id,
      input.sample_original_path_id,
      p_instrument_v2_id,
      input.s3_bucket,
      input.s3_key,
      input.object_etag,
      input.object_version,
      p_processing_version,
      p_analysis_version,
      input.signature,
      true
    FROM input_assets input
    CROSS JOIN (SELECT count(*) FROM retired) AS retired_barrier
    ON CONFLICT ON CONSTRAINT sample_s3_path_identity_key DO UPDATE SET
      s3_bucket = EXCLUDED.s3_bucket,
      s3_key = EXCLUDED.s3_key,
      object_etag = EXCLUDED.object_etag,
      object_version = EXCLUDED.object_version,
      is_current = true,
      excluded_at = NULL,
      exclusion_reason = NULL
    RETURNING
      sample_s3_path.id,
      sample_s3_path.sample_path_construct_id,
      sample_s3_path.source_signature,
      sample_s3_path.analysis_version
  ), obsolete_assets AS MATERIALIZED (
    SELECT retired.id FROM retired
    UNION
    SELECT obsolete.id
    FROM public.sample_s3_path obsolete
    JOIN input_assets input
      ON input.construct_id = obsolete.sample_path_construct_id
    WHERE NOT obsolete.is_current
  ), superseded AS (
    UPDATE public.sample_analysis_jobs job
    SET
      status = 'superseded',
      lease_owner = NULL,
      lease_token = NULL,
      lease_expires_at = NULL
    WHERE job.published_asset_id IN (SELECT obsolete.id FROM obsolete_assets obsolete)
      AND job.status IN ('queued', 'running', 'failed')
    RETURNING job.id
  ), desired_jobs AS MATERIALIZED (
    SELECT
      current_asset.id AS published_asset_id,
      stage.name AS stage,
      current_asset.analysis_version,
      current_asset.source_signature
    FROM upserted current_asset
    CROSS JOIN (VALUES ('analysis'::text), ('librosa'::text)) AS stage(name)
  ), enqueued AS (
    INSERT INTO public.sample_analysis_jobs(
      published_asset_id,
      stage,
      analysis_version,
      source_signature,
      priority
    )
    SELECT
      desired.published_asset_id,
      desired.stage,
      desired.analysis_version,
      desired.source_signature,
      0
    FROM desired_jobs desired
    ON CONFLICT ON CONSTRAINT sample_analysis_jobs_dedupe DO UPDATE SET
      status = CASE WHEN p_force THEN 'queued' ELSE public.sample_analysis_jobs.status END,
      priority = greatest(public.sample_analysis_jobs.priority, EXCLUDED.priority),
      attempts = CASE WHEN p_force THEN 0 ELSE public.sample_analysis_jobs.attempts END,
      available_at = CASE WHEN p_force THEN now() ELSE public.sample_analysis_jobs.available_at END,
      lease_owner = CASE WHEN p_force THEN NULL ELSE public.sample_analysis_jobs.lease_owner END,
      lease_token = CASE WHEN p_force THEN NULL ELSE public.sample_analysis_jobs.lease_token END,
      lease_expires_at = CASE WHEN p_force THEN NULL ELSE public.sample_analysis_jobs.lease_expires_at END,
      completed_at = CASE WHEN p_force THEN NULL ELSE public.sample_analysis_jobs.completed_at END,
      last_error = CASE WHEN p_force THEN NULL ELSE public.sample_analysis_jobs.last_error END
    RETURNING published_asset_id
  )
  SELECT
    current_asset.id,
    current_asset.source_signature,
    count(enqueued.published_asset_id)::integer
  FROM upserted current_asset
  JOIN input_assets input
    ON input.construct_id = current_asset.sample_path_construct_id
  JOIN enqueued ON enqueued.published_asset_id = current_asset.id
  GROUP BY current_asset.id, current_asset.source_signature, input.input_ordinal
  ORDER BY input.input_ordinal;
END $$;


ALTER FUNCTION "public"."register_sample_s3_path_v1"("p_instrument_v2_id" "uuid", "p_assets" "jsonb", "p_processing_version" "text", "p_analysis_version" "text", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_sample_psychoacoustic_result_mutation_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION USING
    ERRCODE = '55000',
    MESSAGE = 'sample_psychoacoustic_results_append_only';
END;
$$;


ALTER FUNCTION "public"."reject_sample_psychoacoustic_result_mutation_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_monthly_allowance"("p_claim_id" "uuid") RETURNS boolean
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  WITH released AS (
    UPDATE public.monthly_allowance_claims
    SET consumption_status = 'released', released_at = clock_timestamp()
    WHERE id = p_claim_id AND consumption_status = 'consumed'
    RETURNING id
  ) SELECT EXISTS (SELECT 1 FROM released);
$$;


ALTER FUNCTION "public"."release_monthly_allowance"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."saved_loops" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "config_id" "uuid" NOT NULL,
    "origin_source" "text" DEFAULT 'market'::"text" NOT NULL,
    "name" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "owner_display_name" "text",
    "owner_display_slug" "text" NOT NULL,
    "description" "text",
    "share_visibility" "text" DEFAULT 'private'::"text" NOT NULL,
    "published_at" timestamp with time zone,
    "show_in_loops_library" boolean DEFAULT false NOT NULL,
    "show_in_community_review_queue" boolean DEFAULT false NOT NULL,
    "team_review_status" "text" DEFAULT 'not_submitted'::"text" NOT NULL,
    "team_reviewed_at" timestamp with time zone,
    "team_review_notes" "text",
    "duration_seconds" real,
    "bpm" smallint,
    "key" smallint,
    "scale_quality" "text",
    "mood" "text",
    "loop_count" integer DEFAULT 0 NOT NULL,
    "has_drum_machine" boolean DEFAULT false NOT NULL,
    "source_pattern_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "source_market_song_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "instrument_names" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "instrument_family_buckets" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "view_state" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "is_archived" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "saved_loops_duration_positive" CHECK ((("duration_seconds" IS NULL) OR ("duration_seconds" > (0)::double precision))),
    CONSTRAINT "saved_loops_loop_count_nonnegative" CHECK (("loop_count" >= 0)),
    CONSTRAINT "saved_loops_name_not_blank" CHECK (("length"(TRIM(BOTH FROM "name")) > 0)),
    CONSTRAINT "saved_loops_origin_source_valid" CHECK (("origin_source" = ANY (ARRAY['market'::"text", 'producer'::"text"]))),
    CONSTRAINT "saved_loops_owner_display_slug_not_blank" CHECK (("length"(TRIM(BOTH FROM "owner_display_slug")) > 0)),
    CONSTRAINT "saved_loops_slug_not_blank" CHECK (("length"(TRIM(BOTH FROM "slug")) > 0)),
    CONSTRAINT "saved_loops_team_review_state_valid" CHECK (((("team_review_status" = ANY (ARRAY['approved'::"text", 'rejected'::"text"])) AND ("team_reviewed_at" IS NOT NULL)) OR ("team_review_status" = ANY (ARRAY['not_submitted'::"text", 'pending'::"text"])))),
    CONSTRAINT "saved_loops_team_review_status_valid" CHECK (("team_review_status" = ANY (ARRAY['not_submitted'::"text", 'pending'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "saved_loops_view_state_object" CHECK (("jsonb_typeof"("view_state") = 'object'::"text")),
    CONSTRAINT "saved_loops_visibility_valid" CHECK (("share_visibility" = ANY (ARRAY['private'::"text", 'unlisted'::"text", 'public'::"text"])))
);


ALTER TABLE "public"."saved_loops" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rename_saved_loop"("p_saved_loop_id" "uuid", "p_name" "text") RETURNS "public"."saved_loops"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  normalized_name text;
  updated_saved_loop public.saved_loops;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication is required to rename a saved loop'
      USING ERRCODE = '42501';
  END IF;

  IF p_saved_loop_id IS NULL THEN
    RAISE EXCEPTION 'p_saved_loop_id is required'
      USING ERRCODE = '22023';
  END IF;

  normalized_name := pg_catalog.btrim(p_name);
  IF normalized_name IS NULL
    OR pg_catalog.char_length(normalized_name) < 1
    OR pg_catalog.char_length(normalized_name) > 120 THEN
    RAISE EXCEPTION 'p_name must contain between 1 and 120 characters after trimming'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.set_config('app.saved_loop_rename_write', 'on', true);

  UPDATE public.saved_loops
  SET name = normalized_name
  WHERE id = p_saved_loop_id
    AND user_id = auth.uid()
  RETURNING * INTO updated_saved_loop;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saved loop not found or not owned by the current user'
      USING ERRCODE = 'P0002';
  END IF;

  RETURN updated_saved_loop;
END;
$$;


ALTER FUNCTION "public"."rename_saved_loop"("p_saved_loop_id" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_sip_review_legacy_map_links"("p_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_actor" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  applied_json jsonb := '[]'::jsonb;
  skipped_json jsonb := '[]'::jsonb;
  alias_rows_json jsonb := '[]'::jsonb;
  promote_result jsonb := '{}'::jsonb;
  applied_count integer := 0;
  alias_count integer := 0;
  alias_deleted_count integer := 0;
  skipped_count integer := 0;
  now_value timestamptz := now();
BEGIN
  p_rows := COALESCE(p_rows, '[]'::jsonb);

  IF jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'replace_sip_review_legacy_map_links p_rows must be a JSON array' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_rows) AS item(row_json)
    WHERE NOT (item.row_json ? 'sip_review_instrument_id')
      OR NOT (item.row_json ? 'legacy_instrument_id')
      OR NOT (item.row_json ? 'contributor_slug')
  ) THEN
    RAISE EXCEPTION 'legacy map rows require sip_review_instrument_id, legacy_instrument_id, and contributor_slug' USING ERRCODE = '22023';
  END IF;

  WITH raw AS (
    SELECT row_json, ord
    FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS item(row_json, ord)
  ),
  typed AS (
    SELECT
      ord,
      (row_json->>'sip_review_instrument_id')::uuid AS sip_review_instrument_id,
      (row_json->>'legacy_instrument_id')::uuid AS legacy_instrument_id,
      NULLIF(btrim(row_json->>'contributor_slug'), '') AS contributor_slug,
      NULLIF(btrim(row_json->>'notes'), '') AS notes
    FROM raw
  ),
  dedup AS (
    SELECT DISTINCT ON (legacy_instrument_id)
      ord,
      sip_review_instrument_id,
      legacy_instrument_id,
      contributor_slug,
      notes
    FROM typed
    ORDER BY legacy_instrument_id, ord DESC
  ),
  deleted AS (
    DELETE FROM "public"."sip_review_legacy_map"
    WHERE legacy_instrument_id IN (
      SELECT legacy_instrument_id
      FROM dedup
    )
  ),
  inserted AS (
    INSERT INTO "public"."sip_review_legacy_map" (
      "sip_review_instrument_id",
      "legacy_instrument_id",
      "contributor_slug",
      "notes"
    )
    SELECT
      "sip_review_instrument_id",
      "legacy_instrument_id",
      "contributor_slug",
      "notes"
    FROM dedup
    ORDER BY ord
    ON CONFLICT ("sip_review_instrument_id", "legacy_instrument_id") DO UPDATE SET
      "contributor_slug" = EXCLUDED."contributor_slug",
      "notes" = EXCLUDED."notes",
      "updated_at" = now()
    RETURNING
      "id",
      "sip_review_instrument_id",
      "legacy_instrument_id"
  ),
  applied AS (
    SELECT
      inserted."id",
      inserted."sip_review_instrument_id",
      inserted."legacy_instrument_id",
      dedup.ord
    FROM inserted
    JOIN dedup
      ON dedup.sip_review_instrument_id = inserted."sip_review_instrument_id"
     AND dedup.legacy_instrument_id = inserted."legacy_instrument_id"
  )
  SELECT
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', "id",
          'stagingInstrumentId', "sip_review_instrument_id",
          'legacyInstrumentId', "legacy_instrument_id"
        )
        ORDER BY ord
      ),
      '[]'::jsonb
    ),
    COUNT(*)::integer
  INTO applied_json, applied_count
  FROM applied;

  WITH applied_rows AS (
    SELECT *
    FROM jsonb_to_recordset(applied_json) AS row_data(
      "id" bigint,
      "stagingInstrumentId" uuid,
      "legacyInstrumentId" uuid
    )
  ),
  promoted_legacy AS (
    SELECT
      applied_rows."legacyInstrumentId" AS legacy_instrument_id
    FROM applied_rows
    JOIN "public"."sip_review_promotion_map" promotion_map
      ON promotion_map.sip_review_instrument_id = applied_rows."stagingInstrumentId"
  ),
  deleted_aliases AS (
    DELETE FROM "public"."instrument_v2_legacy_map"
    WHERE legacy_instrument_id IN (
      SELECT legacy_instrument_id
      FROM promoted_legacy
    )
    RETURNING "id"
  )
  SELECT COUNT(*)::integer
  INTO alias_deleted_count
  FROM deleted_aliases;

  WITH applied_rows AS (
    SELECT *
    FROM jsonb_to_recordset(applied_json) AS row_data(
      "id" bigint,
      "stagingInstrumentId" uuid,
      "legacyInstrumentId" uuid
    )
  ),
  applied_staging AS (
    SELECT DISTINCT "stagingInstrumentId" AS sip_review_instrument_id
    FROM applied_rows
  ),
  base AS (
    SELECT
      review_map.sip_review_instrument_id,
      review_map.legacy_instrument_id,
      review_map.contributor_slug,
      review_map.notes,
      promotion_map.instrument_v2_id,
      instruments.name AS legacy_name,
      instruments.firebase_id AS legacy_lookup_key,
      instruments.file_path_reference AS legacy_file_path_reference,
      instruments.velocity_layers AS legacy_velocity_layers
    FROM applied_staging
    JOIN "public"."sip_review_legacy_map" review_map
      ON review_map.sip_review_instrument_id = applied_staging.sip_review_instrument_id
    JOIN "public"."sip_review_promotion_map" promotion_map
      ON promotion_map.sip_review_instrument_id = review_map.sip_review_instrument_id
    JOIN "public"."instruments" instruments
      ON instruments.id = review_map.legacy_instrument_id
  ),
  skipped AS (
    SELECT DISTINCT
      sip_review_instrument_id,
      legacy_instrument_id
    FROM base
    WHERE NULLIF(btrim(COALESCE(legacy_lookup_key, '')), '') IS NULL
  ),
  valid_base AS (
    SELECT *
    FROM base
    WHERE NULLIF(btrim(COALESCE(legacy_lookup_key, '')), '') IS NOT NULL
  ),
  parsed AS (
    SELECT
      valid_base.*,
      regexp_match(btrim(COALESCE(valid_base.legacy_name, '')), '^(.*?)(?:\s+([1-9][0-9]*))?$') AS name_parts
    FROM valid_base
  ),
  indexed AS (
    SELECT
      parsed.*,
      lower(btrim(COALESCE((parsed.name_parts)[1], ''))) AS parsed_base_name,
      COALESCE(((parsed.name_parts)[2])::integer, 0) AS parsed_index,
      GREATEST(1, COALESCE(parsed.legacy_velocity_layers, 1))::integer AS fallback_legacy_velocity
    FROM parsed
  ),
  group_stats AS (
    SELECT
      sip_review_instrument_id,
      COUNT(*)::integer AS row_count,
      COUNT(DISTINCT parsed_base_name)::integer AS base_count,
      COUNT(DISTINCT parsed_index)::integer AS index_count,
      MIN(parsed_index) AS min_index,
      MAX(parsed_index) AS max_index,
      bool_and(parsed_base_name <> '') AS has_names
    FROM indexed
    GROUP BY sip_review_instrument_id
  ),
  candidate AS (
    SELECT
      indexed.*,
      CASE
        WHEN group_stats.has_names
          AND group_stats.base_count = 1
          AND group_stats.index_count = group_stats.row_count
          AND group_stats.min_index = 0
          AND group_stats.max_index = group_stats.row_count - 1
          THEN indexed.parsed_index + 1
        ELSE indexed.fallback_legacy_velocity
      END AS legacy_velocity
    FROM indexed
    JOIN group_stats
      ON group_stats.sip_review_instrument_id = indexed.sip_review_instrument_id
  ),
  dedup_candidate AS (
    SELECT DISTINCT ON (legacy_instrument_id, instrument_v2_id)
      candidate.*
    FROM candidate
    ORDER BY legacy_instrument_id, instrument_v2_id, legacy_instrument_id
  ),
  ranked AS (
    SELECT
      dedup_candidate.*,
      row_number() OVER (
        PARTITION BY legacy_instrument_id
        ORDER BY instrument_v2_id, sip_review_instrument_id
      ) AS legacy_rank,
      row_number() OVER (
        PARTITION BY instrument_v2_id
        ORDER BY legacy_instrument_id, sip_review_instrument_id
      ) AS v2_rank
    FROM dedup_candidate
  )
  SELECT
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'instrument_v2_id', instrument_v2_id,
          'legacy_instrument_id', legacy_instrument_id,
          'sip_review_instrument_id', sip_review_instrument_id,
          'contributor_slug', contributor_slug,
          'legacy_lookup_key', btrim(legacy_lookup_key),
          'legacy_file_path_reference', NULLIF(btrim(COALESCE(legacy_file_path_reference, '')), ''),
          'legacy_velocity', legacy_velocity,
          'is_primary_for_legacy', NOT EXISTS (
            SELECT 1
            FROM "public"."instrument_v2_legacy_map" existing
            WHERE existing.legacy_instrument_id = ranked.legacy_instrument_id
              AND existing.is_primary_for_legacy
          ) AND legacy_rank = 1,
          'is_primary_for_v2', NOT EXISTS (
            SELECT 1
            FROM "public"."instrument_v2_legacy_map" existing
            WHERE existing.instrument_v2_id = ranked.instrument_v2_id
              AND existing.is_primary_for_v2
          ) AND v2_rank = 1,
          'notes', notes,
          'created_by', p_actor,
          'updated_by', p_actor,
          'primary_for_legacy_set_by', CASE
            WHEN NOT EXISTS (
              SELECT 1
              FROM "public"."instrument_v2_legacy_map" existing
              WHERE existing.legacy_instrument_id = ranked.legacy_instrument_id
                AND existing.is_primary_for_legacy
            ) AND legacy_rank = 1 THEN p_actor
            ELSE NULL
          END,
          'primary_for_legacy_set_at', CASE
            WHEN NOT EXISTS (
              SELECT 1
              FROM "public"."instrument_v2_legacy_map" existing
              WHERE existing.legacy_instrument_id = ranked.legacy_instrument_id
                AND existing.is_primary_for_legacy
            ) AND legacy_rank = 1 THEN now_value
            ELSE NULL
          END,
          'primary_for_v2_set_by', CASE
            WHEN NOT EXISTS (
              SELECT 1
              FROM "public"."instrument_v2_legacy_map" existing
              WHERE existing.instrument_v2_id = ranked.instrument_v2_id
                AND existing.is_primary_for_v2
            ) AND v2_rank = 1 THEN p_actor
            ELSE NULL
          END,
          'primary_for_v2_set_at', CASE
            WHEN NOT EXISTS (
              SELECT 1
              FROM "public"."instrument_v2_legacy_map" existing
              WHERE existing.instrument_v2_id = ranked.instrument_v2_id
                AND existing.is_primary_for_v2
            ) AND v2_rank = 1 THEN now_value
            ELSE NULL
          END
        )
        ORDER BY instrument_v2_id, legacy_instrument_id
      ),
      '[]'::jsonb
    )
  INTO alias_rows_json
  FROM ranked;

  IF jsonb_array_length(alias_rows_json) > 0 THEN
    promote_result := "public"."promote_sip_instruments_v2"(
      '[]'::jsonb,
      '[]'::jsonb,
      '[]'::jsonb,
      alias_rows_json,
      '[]'::jsonb,
      '[]'::jsonb,
      '[]'::jsonb,
      '[]'::jsonb
    );
    alias_count := COALESCE((promote_result->>'legacyAliasesUpserted')::integer, jsonb_array_length(alias_rows_json));
  END IF;

  WITH applied_rows AS (
    SELECT *
    FROM jsonb_to_recordset(applied_json) AS row_data(
      "id" bigint,
      "stagingInstrumentId" uuid,
      "legacyInstrumentId" uuid
    )
  ),
  applied_staging AS (
    SELECT DISTINCT "stagingInstrumentId" AS sip_review_instrument_id
    FROM applied_rows
  ),
  skipped_source AS (
    SELECT DISTINCT
      review_map.sip_review_instrument_id,
      review_map.legacy_instrument_id
    FROM applied_staging
    JOIN "public"."sip_review_legacy_map" review_map
      ON review_map.sip_review_instrument_id = applied_staging.sip_review_instrument_id
    JOIN "public"."sip_review_promotion_map" promotion_map
      ON promotion_map.sip_review_instrument_id = review_map.sip_review_instrument_id
    JOIN "public"."instruments" instruments
      ON instruments.id = review_map.legacy_instrument_id
    WHERE NULLIF(btrim(COALESCE(instruments.firebase_id, '')), '') IS NULL
  )
  SELECT
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'stagingInstrumentId', sip_review_instrument_id,
          'legacyInstrumentId', legacy_instrument_id,
          'code', 'missing_firebase_id',
          'reason', 'Legacy instrument has no firebase_id; alias cannot be created.'
        )
        ORDER BY sip_review_instrument_id, legacy_instrument_id
      ),
      '[]'::jsonb
    ),
    COUNT(*)::integer
  INTO skipped_json, skipped_count
  FROM skipped_source;

  RETURN jsonb_build_object(
    'applied', applied_json,
    'skippedLegacyAliases', skipped_json,
    'summary', jsonb_build_object(
      'applied', applied_count,
      'productionAliasesSubmitted', alias_count,
      'productionAliasesRemoved', alias_deleted_count,
      'skippedLegacyAliases', skipped_count
    )
  );
END;
$_$;


ALTER FUNCTION "public"."replace_sip_review_legacy_map_links"("p_rows" "jsonb", "p_actor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_current_sampled_midi_publish_evidence_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT NEW.published THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sample_path_constructs construct
    WHERE construct.instrument_v2_id = NEW.id
  ) OR NOT (
    NOT EXISTS (
      SELECT 1
      FROM public.sample_path_constructs construct
      JOIN public.samples_original_paths source
        ON source.id = construct.sample_original_path_id
      WHERE construct.instrument_v2_id = NEW.id
        AND (
          SELECT count(*) = 9
            AND count(DISTINCT (output.format, output.quality)) = 9
            AND count(*) FILTER (
              WHERE output.format = 'mp3' AND output.quality BETWEEN 1 AND 5
            ) = 5
            AND count(*) FILTER (
              WHERE output.format = 'ogg' AND output.quality BETWEEN 2 AND 5
            ) = 4
          FROM public.instrument_v2_publish_output_manifest output
          WHERE output.instrument_v2_id = NEW.id
            AND output.sample_path_construct_id = construct.id
            AND output.original_sample_id = construct.sample_original_path_id
            AND output.status = 'completed'
            AND output.fingerprint_schema = 'sip-v2-output-v2'
            AND output.processed_at >= construct.updated_at
            AND jsonb_typeof(output.output_object_identity) = 'object'
            AND nullif(
              btrim(output.output_object_identity->>'eTag'),
              ''
            ) IS NOT NULL
            AND jsonb_typeof(
              output.output_object_identity->'contentLength'
            ) = 'number'
            AND (
              output.output_object_identity->>'contentLength'
            )::numeric >= 0
            AND output.processing_input->>'fingerprintSchema' =
              'sip-v2-output-v2'
            AND jsonb_typeof(
              output.processing_input->'sourceObjectIdentity'
            ) = 'object'
            AND nullif(
              btrim(
                output.processing_input
                  ->'sourceObjectIdentity'
                  ->>'eTag'
              ),
              ''
            ) IS NOT NULL
            AND output.processing_input->>'instrumentV2Id' = NEW.id::text
            AND output.processing_input->>'samplePathConstructId' =
              construct.id::text
            AND output.processing_input->>'originalSampleId' =
              construct.sample_original_path_id::text
            AND output.processing_input->>'sourceS3Key' = source.s3_path
            AND output.processing_input->>'pitchContent' =
              coalesce(nullif(btrim(construct.pitch_content), ''), '0')
            AND output.processing_input->>'midiNote' =
              btrim(construct.midi_note)
            AND output.processing_input->>'velocity' =
              greatest(coalesce(construct.velocity, 0), 0)::text
            AND output.processing_input->>'roundRobin' =
              greatest(coalesce(construct.round_robin, 0), 0)::text
            AND output.processing_input->>'micPosition' =
              coalesce(nullif(btrim(construct.mic_position), ''), 'main')
            AND output.processing_input->>'filename' =
              btrim(construct.filename)
            AND output.processing_input->'target'->>'s3Key' =
              output.destination_s3_key
            AND output.processing_input->'target'->>'format' = output.format
            AND output.processing_input->'target'->>'quality' =
              output.quality::text
        ) IS DISTINCT FROM true
    )
    OR EXISTS (
      SELECT 1
      FROM public.sip_anchor_object_verification_evidence evidence
      JOIN public.sip_anchor_object_verification_rehearsals rehearsal
        ON rehearsal.id = evidence.rehearsal_id
       AND rehearsal.artifact_id = evidence.artifact_id
       AND rehearsal.status = 'passed'
      JOIN public.sip_fleet_plan_artifacts artifact
        ON artifact.id = evidence.artifact_id
       AND artifact.content_hash = rehearsal.content_hash
      JOIN public.sip_fleet_plan_artifact_approvals approval
        ON approval.artifact_id = artifact.id
       AND approval.content_hash = artifact.content_hash
      WHERE evidence.instrument_v2_id = NEW.id
        AND evidence.authorizing_xid = txid_current()
        AND evidence.recorded_at >=
          clock_timestamp() - interval '15 minutes'
        AND evidence.projection_hash = rehearsal.projection_hash
        AND evidence.object_identity_hash = rehearsal.object_identity_hash
        AND evidence.construct_count = rehearsal.construct_count
        AND evidence.source_count = rehearsal.source_count
        AND evidence.target_count = rehearsal.target_count
        AND evidence.target_count = evidence.construct_count * 9
        AND public.is_current_instrument_v2_readiness_snapshot_v2(
          NEW.id,
          evidence.readiness_snapshot_sha256
        )
        AND evidence.construct_count = (
          SELECT count(*)
          FROM jsonb_array_elements_text(
            artifact.content->'instrumentV2Ids'
          ) requested(value)
          JOIN public.sample_path_constructs construct
            ON construct.instrument_v2_id = requested.value::uuid
        )
        AND evidence.source_count = (
          SELECT count(DISTINCT source.s3_path)
          FROM jsonb_array_elements_text(
            artifact.content->'instrumentV2Ids'
          ) requested(value)
          JOIN public.sample_path_constructs construct
            ON construct.instrument_v2_id = requested.value::uuid
          JOIN public.samples_original_paths source
            ON source.id = construct.sample_original_path_id
        )
    )
  ) THEN
    RAISE EXCEPTION 'current_publish_output_evidence_required'
      USING ERRCODE = '55000';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."require_current_sampled_midi_publish_evidence_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_market_pattern_embedding_job"("p_job_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  UPDATE public.market_pattern_embedding_jobs
  SET
    status = 'queued',
    attempt_count = 0,
    available_at = now(),
    lease_token = NULL,
    leased_by = NULL,
    lease_expires_at = NULL,
    last_heartbeat_at = NULL,
    last_error = NULL,
    started_at = NULL,
    completed_at = NULL
  WHERE id = p_job_id
    AND status = 'failed';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job % is not retryable', p_job_id USING ERRCODE = '55000';
  END IF;
  RETURN p_job_id;
END;
$$;


ALTER FUNCTION "public"."retry_market_pattern_embedding_job"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_sample_analysis_jobs"("p_instrument_v2_id" "uuid" DEFAULT NULL::"uuid", "p_published_asset_id" "uuid" DEFAULT NULL::"uuid", "p_stage" "text" DEFAULT NULL::"text", "p_priority" integer DEFAULT 0) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_count integer;
BEGIN
  UPDATE public.sample_analysis_jobs job SET status='queued', attempts=0,
    priority=greatest(job.priority,p_priority), available_at=now(), last_error=NULL,
    completed_at=NULL, lease_owner=NULL, lease_token=NULL, lease_expires_at=NULL
  FROM public.sample_s3_path asset
  WHERE asset.id=job.published_asset_id AND asset.is_current AND asset.excluded_at IS NULL
    AND job.status IN ('failed','completed')
    AND (p_instrument_v2_id IS NULL OR asset.instrument_v2_id=p_instrument_v2_id)
    AND (p_published_asset_id IS NULL OR asset.id=p_published_asset_id)
    AND (p_stage IS NULL OR job.stage=p_stage);
  GET DIAGNOSTICS v_count = ROW_COUNT; RETURN v_count;
END $$;


ALTER FUNCTION "public"."retry_sample_analysis_jobs"("p_instrument_v2_id" "uuid", "p_published_asset_id" "uuid", "p_stage" "text", "p_priority" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_sip_pipeline_run"("p_run_id" "uuid", "p_requested_by" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."sip_pipeline_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old public.sip_pipeline_runs%ROWTYPE;
  v_new_run_id uuid;
BEGIN
  SELECT * INTO v_old
  FROM public.sip_pipeline_runs
  WHERE id = p_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sip_pipeline_run_not_found: %', p_run_id;
  END IF;

  SELECT id INTO v_new_run_id
  FROM public.sip_pipeline_runs
  WHERE contributor_slug = v_old.contributor_slug
    AND mode = v_old.mode
    AND status IN ('queued', 'running', 'paused')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_new_run_id IS NOT NULL THEN
    RETURN QUERY SELECT * FROM public.sip_pipeline_runs WHERE id = v_new_run_id;
    RETURN;
  END IF;

  INSERT INTO public.sip_pipeline_runs (
    contributor_slug,
    mode,
    requested_by,
    batch_settings,
    scope,
    last_event_at,
    heartbeat_at
  )
  VALUES (
    v_old.contributor_slug,
    v_old.mode,
    COALESCE(p_requested_by, v_old.requested_by),
    v_old.batch_settings,
    v_old.scope || jsonb_build_object('retryOfRunId', v_old.id),
    now(),
    now()
  )
  RETURNING id INTO v_new_run_id;

  INSERT INTO public.sip_pipeline_run_items (
    run_id,
    staging_instrument_id,
    source_sip_instrument_id,
    instrument_v2_id,
    contributor_slug,
    instrument_name,
    current_stage,
    max_attempts
  )
  SELECT
    v_new_run_id,
    item.staging_instrument_id,
    item.source_sip_instrument_id,
    item.instrument_v2_id,
    item.contributor_slug,
    item.instrument_name,
    public.sip_pipeline_stage_from_upload_status(
      item.source_sip_instrument_id,
      item.current_stage
    ),
    item.max_attempts
  FROM public.sip_pipeline_run_items item
  LEFT JOIN public.instruments_v2 iv2
    ON iv2.id = item.instrument_v2_id
  WHERE item.run_id = p_run_id
    AND item.status IN ('blocked', 'stalled', 'failed', 'cancelled')
    AND COALESCE(iv2.published, false) = false
  ORDER BY item.created_at, item.id;

  INSERT INTO public.sip_pipeline_run_events (
    run_id,
    event_type,
    message,
    payload
  )
  VALUES (
    v_new_run_id,
    'run_retry_enqueued',
    'Queued SIP contributor retry run',
    jsonb_build_object('retryOfRunId', v_old.id)
  );

  PERFORM public.sip_pipeline_refresh_run_counts(v_new_run_id);

  RETURN QUERY SELECT * FROM public.sip_pipeline_runs WHERE id = v_new_run_id;
END;
$$;


ALTER FUNCTION "public"."retry_sip_pipeline_run"("p_run_id" "uuid", "p_requested_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sample_psychoacoustic_result_shape_is_valid_v1"("p_published_asset_id" "uuid", "p_asset_source_signature" "text", "p_source_digest" "text", "p_characteristic_key" "text", "p_evidence_contract_version" "text", "p_algorithm_version" "text", "p_projection_version" "text", "p_state" "text", "p_policy" "jsonb", "p_native_measurements" "jsonb", "p_projection" "jsonb", "p_applicability" "jsonb", "p_unavailable_reason" "text", "p_explanation" "jsonb", "p_result_id" "text", "p_result_digest" "text", "p_result_payload" "jsonb", "p_canonical_result_body" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_body jsonb;
  v_policy_kind text;
  v_projection_value numeric;
  v_confidence numeric;
BEGIN
  IF p_asset_source_signature !~ '^apv1:sha256-v1:[0-9a-f]{64}$'
     OR p_source_digest <> 'sha256:' || substring(p_asset_source_signature from 16)
     OR p_result_digest !~ '^sha256:[0-9a-f]{64}$'
     OR p_result_id <> 'psychoacoustic-result-v1:' || substring(p_result_digest from 8)
     OR NOT public.sample_psychoacoustic_token_is_valid_v1(p_characteristic_key)
     OR NOT public.sample_psychoacoustic_token_is_valid_v1(p_evidence_contract_version)
     OR NOT public.sample_psychoacoustic_token_is_valid_v1(p_algorithm_version)
     OR (p_projection_version IS NOT NULL
         AND NOT public.sample_psychoacoustic_token_is_valid_v1(p_projection_version))
     OR jsonb_typeof(p_result_payload) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_policy) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_applicability) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_explanation) IS DISTINCT FROM 'object'
     OR p_result_payload #>> '{identity,resultId}' IS DISTINCT FROM p_result_id
     OR p_result_payload #>> '{identity,resultDigest}' IS DISTINCT FROM p_result_digest
     OR p_result_payload->>'schemaVersion' IS DISTINCT FROM 'psychoacoustic-result-v1'
     OR p_result_payload->>'publishedAssetId' IS DISTINCT FROM p_published_asset_id::text
     OR p_result_payload->>'sourceSignature' IS DISTINCT FROM p_source_digest
     OR p_result_payload->>'characteristicKey' IS DISTINCT FROM p_characteristic_key
     OR p_result_payload->>'evidenceContractVersion' IS DISTINCT FROM p_evidence_contract_version
     OR p_result_payload->>'algorithmVersion' IS DISTINCT FROM p_algorithm_version
     OR p_result_payload->>'state' IS DISTINCT FROM p_state
     OR p_result_payload->'policy' IS DISTINCT FROM p_policy
     OR p_result_payload->'nativeMeasurements' IS DISTINCT FROM p_native_measurements
     OR p_result_payload->'projection' IS DISTINCT FROM p_projection
     OR p_result_payload->'applicability' IS DISTINCT FROM p_applicability
     OR p_result_payload->>'unavailableReason' IS DISTINCT FROM p_unavailable_reason
     OR p_result_payload->'explanation' IS DISTINCT FROM p_explanation
  THEN
    RETURN false;
  END IF;

  BEGIN
    v_body := p_canonical_result_body::jsonb;
  EXCEPTION WHEN others THEN
    RETURN false;
  END;
  IF v_body IS DISTINCT FROM (p_result_payload - 'identity')
     OR p_result_digest <> 'sha256:' || encode(
       extensions.digest(convert_to(p_canonical_result_body, 'UTF8'), 'sha256'),
       'hex'
     )
  THEN
    RETURN false;
  END IF;

  v_policy_kind := p_policy->>'kind';
  IF v_policy_kind IS NULL OR v_policy_kind NOT IN (
    'direct-bounded',
    'fixed-transfer',
    'content-addressed-model'
  ) THEN
    RETURN false;
  END IF;

  IF v_policy_kind = 'direct-bounded' THEN
    IF (SELECT count(*) FROM jsonb_object_keys(p_policy)) <> 5
       OR public.sample_psychoacoustic_token_is_valid_v1(
         p_policy->>'measurementKey'
       ) IS NOT TRUE
       OR public.sample_psychoacoustic_token_is_valid_v1(
         p_policy->>'unit'
       ) IS NOT TRUE
       OR jsonb_typeof(p_policy->'lowerBound') IS DISTINCT FROM 'number'
       OR jsonb_typeof(p_policy->'upperBound') IS DISTINCT FROM 'number'
       OR (p_policy->>'upperBound')::numeric
          <= (p_policy->>'lowerBound')::numeric
    THEN
      RETURN false;
    END IF;
  ELSIF v_policy_kind = 'fixed-transfer' THEN
    IF (SELECT count(*) FROM jsonb_object_keys(p_policy)) <> 4
       OR public.sample_psychoacoustic_token_is_valid_v1(
         p_policy->>'transferVersion'
       ) IS NOT TRUE
       OR public.sample_psychoacoustic_token_is_valid_v1(
         p_policy->>'anchorSetId'
       ) IS NOT TRUE
       OR (p_policy->>'anchorSetDigest' ~ '^sha256:[0-9a-f]{64}$') IS NOT TRUE
    THEN
      RETURN false;
    END IF;
  ELSE
    IF (SELECT count(*) FROM jsonb_object_keys(p_policy)) <> 3
       OR public.sample_psychoacoustic_token_is_valid_v1(
         p_policy->>'modelVersion'
       ) IS NOT TRUE
       OR (p_policy->>'modelDigest' ~ '^sha256:[0-9a-f]{64}$') IS NOT TRUE
    THEN
      RETURN false;
    END IF;
  END IF;

  IF p_state = 'available' THEN
    IF jsonb_typeof(p_native_measurements) IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_native_measurements) = 0
       OR p_unavailable_reason IS NOT NULL
       OR p_applicability->>'state' IS DISTINCT FROM 'applicable'
       OR jsonb_typeof(p_applicability->'confidence') IS DISTINCT FROM 'number'
    THEN
      RETURN false;
    END IF;
    v_confidence := (p_applicability->>'confidence')::numeric;
    IF v_confidence < 0 OR v_confidence > 1 THEN RETURN false; END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_native_measurements) AS measurement
      WHERE jsonb_typeof(measurement) IS DISTINCT FROM 'object'
        OR NOT (measurement ?& ARRAY['key', 'value', 'unit'])
        OR (SELECT count(*) FROM jsonb_object_keys(measurement)) <> 3
        OR NOT public.sample_psychoacoustic_token_is_valid_v1(measurement->>'key')
        OR NOT public.sample_psychoacoustic_token_is_valid_v1(measurement->>'unit')
        OR jsonb_typeof(measurement->'value') IS DISTINCT FROM 'number'
    ) OR (
      SELECT count(*) <> count(DISTINCT measurement->>'key')
      FROM jsonb_array_elements(p_native_measurements) AS measurement
    ) THEN
      RETURN false;
    END IF;

    IF v_policy_kind = 'direct-bounded' AND NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_native_measurements) AS measurement
      WHERE measurement->>'key' = p_policy->>'measurementKey'
        AND measurement->>'unit' = p_policy->>'unit'
    ) THEN
      RETURN false;
    END IF;

    IF p_projection IS NULL THEN
      IF p_projection_version IS NOT NULL THEN RETURN false; END IF;
    ELSE
      IF p_projection_version IS NULL
         OR jsonb_typeof(p_projection) IS DISTINCT FROM 'object'
         OR p_projection->>'kind' IS DISTINCT FROM 'fixed-0-100'
         OR jsonb_typeof(p_projection->'value') IS DISTINCT FROM 'number'
         OR (SELECT count(*) FROM jsonb_object_keys(p_projection)) <> 2
      THEN
        RETURN false;
      END IF;
      v_projection_value := (p_projection->>'value')::numeric;
      IF v_projection_value < 0 OR v_projection_value > 100 THEN
        RETURN false;
      END IF;
      IF (v_policy_kind = 'direct-bounded'
            AND p_projection_version IS DISTINCT FROM p_algorithm_version)
         OR (v_policy_kind = 'fixed-transfer'
            AND p_projection_version IS DISTINCT FROM p_policy->>'transferVersion')
         OR (v_policy_kind = 'content-addressed-model'
            AND p_projection_version IS DISTINCT FROM p_policy->>'modelVersion')
      THEN
        RETURN false;
      END IF;
    END IF;
  ELSIF p_state = 'not_applicable' THEN
    IF p_native_measurements IS NOT NULL
       OR p_projection IS NOT NULL
       OR p_projection_version IS NOT NULL
       OR p_unavailable_reason IS NOT NULL
       OR p_applicability->>'state' IS DISTINCT FROM 'not_applicable'
       OR jsonb_typeof(p_applicability->'confidence') IS DISTINCT FROM 'number'
       OR public.sample_psychoacoustic_token_is_valid_v1(
         p_applicability->>'reason'
       ) IS NOT TRUE
    THEN
      RETURN false;
    END IF;
    v_confidence := (p_applicability->>'confidence')::numeric;
    IF v_confidence < 0 OR v_confidence > 1 THEN RETURN false; END IF;
  ELSIF p_state = 'unavailable' THEN
    IF p_native_measurements IS NOT NULL
       OR p_projection IS NOT NULL
       OR p_projection_version IS NOT NULL
       OR public.sample_psychoacoustic_token_is_valid_v1(
         p_unavailable_reason
       ) IS NOT TRUE
       OR p_applicability <> '{"state":"undetermined"}'::jsonb
    THEN
      RETURN false;
    END IF;
  ELSE
    RETURN false;
  END IF;

  RETURN true;
EXCEPTION WHEN others THEN
  RETURN false;
END;
$_$;


ALTER FUNCTION "public"."sample_psychoacoustic_result_shape_is_valid_v1"("p_published_asset_id" "uuid", "p_asset_source_signature" "text", "p_source_digest" "text", "p_characteristic_key" "text", "p_evidence_contract_version" "text", "p_algorithm_version" "text", "p_projection_version" "text", "p_state" "text", "p_policy" "jsonb", "p_native_measurements" "jsonb", "p_projection" "jsonb", "p_applicability" "jsonb", "p_unavailable_reason" "text", "p_explanation" "jsonb", "p_result_id" "text", "p_result_digest" "text", "p_result_payload" "jsonb", "p_canonical_result_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sample_psychoacoustic_token_is_valid_v1"("p_value" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT p_value ~ '^[a-z0-9][a-z0-9._-]{0,127}$'
    AND p_value !~ '(^|[._-])(catalog|catalogue|cdf|family|instrument|peer|percentile|population|provider|rank|taxonomy)([._-]|$)';
$_$;


ALTER FUNCTION "public"."sample_psychoacoustic_token_is_valid_v1"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."score_market_loop_profile_compatibility_v1"("anchor_temporal_values" double precision[], "candidate_temporal_values" double precision[], "anchor_spectral_values" double precision[], "candidate_spectral_values" double precision[], "anchor_character_values" double precision[], "candidate_character_values" double precision[], "p_rank" integer, "p_match_count" integer) RETURNS double precision
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  WITH temporal_score AS (
    SELECT
      COALESCE(
        AVG(
          GREATEST(
            0::double precision,
            1::double precision - LEAST(
              1::double precision,
              ABS(
                LN(1 + GREATEST(0::double precision, pair_values.anchor_value)) -
                LN(1 + GREATEST(0::double precision, pair_values.candidate_value))
              ) /
              GREATEST(
                1::double precision,
                ABS(LN(1 + GREATEST(0::double precision, pair_values.anchor_value))),
                ABS(LN(1 + GREATEST(0::double precision, pair_values.candidate_value)))
              )
            )
          )
        ),
        0.5::double precision
      )::double precision AS score,
      COUNT(*) > 0 AS observed
    FROM unnest(anchor_temporal_values, candidate_temporal_values)
      AS pair_values(anchor_value, candidate_value)
    WHERE pair_values.anchor_value IS NOT NULL
      AND pair_values.candidate_value IS NOT NULL
  ),
  spectral_score AS (
    SELECT
      COALESCE(
        AVG(
          GREATEST(
            0::double precision,
            1::double precision - LEAST(
              1::double precision,
              ABS(
                LN(1 + GREATEST(0::double precision, pair_values.anchor_value)) -
                LN(1 + GREATEST(0::double precision, pair_values.candidate_value))
              ) /
              GREATEST(
                1::double precision,
                ABS(LN(1 + GREATEST(0::double precision, pair_values.anchor_value))),
                ABS(LN(1 + GREATEST(0::double precision, pair_values.candidate_value)))
              )
            )
          )
        ),
        0.5::double precision
      )::double precision AS score,
      COUNT(*) > 0 AS observed
    FROM unnest(anchor_spectral_values, candidate_spectral_values)
      AS pair_values(anchor_value, candidate_value)
    WHERE pair_values.anchor_value IS NOT NULL
      AND pair_values.candidate_value IS NOT NULL
  ),
  character_score AS (
    SELECT
      COALESCE(
        AVG(
          GREATEST(
            0::double precision,
            1::double precision - LEAST(
              1::double precision,
              ABS(pair_values.anchor_value - pair_values.candidate_value) /
              GREATEST(
                1::double precision,
                ABS(pair_values.anchor_value),
                ABS(pair_values.candidate_value)
              )
            )
          )
        ),
        0.5::double precision
      )::double precision AS score,
      COUNT(*) > 0 AS observed
    FROM unnest(anchor_character_values, candidate_character_values)
      AS pair_values(anchor_value, candidate_value)
    WHERE pair_values.anchor_value IS NOT NULL
      AND pair_values.candidate_value IS NOT NULL
  )
  SELECT
    GREATEST(
      0::double precision,
      LEAST(
        1::double precision,
        0.5 * GREATEST(
          0::double precision,
          1::double precision - (p_rank - 1)::double precision /
            GREATEST(p_match_count, 1)
        ) +
        0.25 * temporal_score.score +
        0.15 * spectral_score.score +
        0.1 * character_score.score -
        (
          3 -
          (CASE WHEN temporal_score.observed THEN 1 ELSE 0 END) -
          (CASE WHEN spectral_score.observed THEN 1 ELSE 0 END) -
          (CASE WHEN character_score.observed THEN 1 ELSE 0 END)
        ) * 0.035
      )
    )::double precision
  FROM temporal_score
  CROSS JOIN spectral_score
  CROSS JOIN character_score;
$$;


ALTER FUNCTION "public"."score_market_loop_profile_compatibility_v1"("anchor_temporal_values" double precision[], "candidate_temporal_values" double precision[], "anchor_spectral_values" double precision[], "candidate_spectral_values" double precision[], "anchor_character_values" double precision[], "candidate_character_values" double precision[], "p_rank" integer, "p_match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seal_instrument_discovery_candidate_page"("p_resource" "text", "p_generation" "uuid", "p_page_index" integer, "p_decoded_bytes" integer, "p_checksum" "text", "p_characteristic_row_checksums" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  candidate_page browser_catalog.instrument_discovery_resource_pages%ROWTYPE;
BEGIN
  IF p_resource IS NULL
    OR p_resource NOT IN ('instruments', 'tags', 'cues', 'characteristics')
    OR p_generation IS NULL
    OR p_page_index IS NULL
    OR p_page_index < 0
    OR p_decoded_bytes IS NULL
    OR p_decoded_bytes < 1
    OR p_decoded_bytes > 1048576
    OR p_checksum IS NULL
    OR p_checksum !~ '^[0-9a-f]{64}$'
    OR jsonb_typeof(p_characteristic_row_checksums) IS DISTINCT FROM 'array'
  THEN
    RAISE EXCEPTION 'Instrument Discovery candidate page seal is invalid';
  END IF;

  SELECT page.*
  INTO candidate_page
  FROM browser_catalog.instrument_discovery_resource_pages AS page
  INNER JOIN browser_catalog.instrument_discovery_resource_generations AS generation
    ON generation.resource_key = page.resource_key
   AND generation.generation = page.generation
  WHERE page.resource_key = p_resource
    AND page.generation = p_generation
    AND page.page_index = p_page_index
    AND (
      (
        generation.publication_status = 'staging'
        AND generation.retained_until > pg_catalog.now()
      )
      OR (
        generation.publication_status = 'sealed'
        AND EXISTS (
          SELECT 1
          FROM browser_catalog.instrument_discovery_state AS state
          WHERE state.singleton
            AND generation.generation = CASE generation.resource_key
              WHEN 'instruments' THEN state.instrument_generation
              WHEN 'tags' THEN state.tag_generation
              WHEN 'cues' THEN state.cue_generation
              WHEN 'characteristics' THEN state.characteristic_generation
            END
        )
      )
    )
  FOR UPDATE OF page;

  IF candidate_page.generation IS NULL THEN
    RAISE EXCEPTION 'Instrument Discovery candidate page is unavailable';
  END IF;
  IF candidate_page.checksum IS NOT NULL AND (
    candidate_page.checksum IS DISTINCT FROM p_checksum
    OR candidate_page.decoded_bytes IS DISTINCT FROM p_decoded_bytes
  ) THEN
    RAISE EXCEPTION 'Instrument Discovery candidate page seal conflicts with its immutable hash';
  END IF;

  IF p_resource = 'characteristics' THEN
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_characteristic_row_checksums) AS input(item)
      WHERE jsonb_typeof(item) IS DISTINCT FROM 'object'
        OR NOT item ?& ARRAY['instrumentId', 'characteristicKey', 'checksum']
        OR item - ARRAY['instrumentId', 'characteristicKey', 'checksum'] <>
          '{}'::jsonb
        OR jsonb_typeof(item -> 'instrumentId') IS DISTINCT FROM 'string'
        OR item ->> 'instrumentId' !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        OR jsonb_typeof(item -> 'characteristicKey') IS DISTINCT FROM 'string'
        OR NULLIF(pg_catalog.btrim(item ->> 'characteristicKey'), '') IS NULL
        OR jsonb_typeof(item -> 'checksum') IS DISTINCT FROM 'string'
        OR item ->> 'checksum' !~ '^[0-9a-f]{64}$'
    ) OR jsonb_array_length(p_characteristic_row_checksums) <>
        candidate_page.row_count
      OR EXISTS (
        SELECT 1
        FROM (
          SELECT item ->> 'instrumentId' AS instrument_id,
            item ->> 'characteristicKey' AS characteristic_key,
            count(*)
          FROM jsonb_array_elements(p_characteristic_row_checksums) AS input(item)
          GROUP BY item ->> 'instrumentId', item ->> 'characteristicKey'
          HAVING count(*) > 1
        ) AS duplicate
      ) OR EXISTS (
        SELECT 1
        FROM jsonb_array_elements(candidate_page.items) AS page_item(item)
        LEFT JOIN jsonb_array_elements(p_characteristic_row_checksums)
          AS checksum_item(item)
          ON checksum_item.item ->> 'instrumentId' =
              page_item.item ->> 'instrumentId'
         AND checksum_item.item ->> 'characteristicKey' =
              page_item.item ->> 'characteristicKey'
        WHERE checksum_item.item IS NULL
      )
    THEN
      RAISE EXCEPTION 'Instrument Discovery Characteristic row seals do not match the candidate page';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_characteristic_row_checksums)
        AS checksum_item(item)
      INNER JOIN browser_catalog.instrument_discovery_characteristic_rows AS row
        ON row.generation = p_generation
       AND row.instrument_id =
          (checksum_item.item ->> 'instrumentId')::uuid
       AND row.characteristic_key =
          checksum_item.item ->> 'characteristicKey'
      WHERE row.row_checksum IS NOT NULL
        AND row.row_checksum IS DISTINCT FROM checksum_item.item ->> 'checksum'
    ) THEN
      RAISE EXCEPTION 'Instrument Discovery Characteristic row seal conflicts with its immutable hash';
    END IF;

    UPDATE browser_catalog.instrument_discovery_characteristic_rows AS row
    SET row_checksum = checksum_item.item ->> 'checksum'
    FROM jsonb_array_elements(p_characteristic_row_checksums)
      AS checksum_item(item)
    WHERE row.generation = p_generation
      AND row.instrument_id =
        (checksum_item.item ->> 'instrumentId')::uuid
      AND row.characteristic_key =
        checksum_item.item ->> 'characteristicKey'
      AND (
        row.row_checksum IS NULL
        OR row.row_checksum = checksum_item.item ->> 'checksum'
      );
  ELSIF p_characteristic_row_checksums <> '[]'::jsonb THEN
    RAISE EXCEPTION 'Non-Characteristic candidate pages cannot carry row seals';
  END IF;

  UPDATE browser_catalog.instrument_discovery_resource_pages
  SET decoded_bytes = p_decoded_bytes,
      checksum = p_checksum
  WHERE resource_key = p_resource
    AND generation = p_generation
    AND page_index = p_page_index
    AND (checksum IS NULL OR checksum = p_checksum)
    AND (decoded_bytes IS NULL OR decoded_bytes = p_decoded_bytes);

  RETURN jsonb_build_object(
    'resource', p_resource,
    'generation', p_generation,
    'pageIndex', p_page_index,
    'checksum', p_checksum
  );
END;
$_$;


ALTER FUNCTION "public"."seal_instrument_discovery_candidate_page"("p_resource" "text", "p_generation" "uuid", "p_page_index" integer, "p_decoded_bytes" integer, "p_checksum" "text", "p_characteristic_row_checksums" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."seal_instrument_discovery_candidate_page"("p_resource" "text", "p_generation" "uuid", "p_page_index" integer, "p_decoded_bytes" integer, "p_checksum" "text", "p_characteristic_row_checksums" "jsonb") IS 'Service-role-only idempotent seal for one exact staged or active page and optional Characteristic row hashes.';



CREATE OR REPLACE FUNCTION "public"."search_instrument_discovery_v1"("p_query" "jsonb", "p_cursor" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  WITH active AS MATERIALIZED (
    SELECT
      state.instrument_generation,
      state.tag_generation,
      state.cue_generation,
      state.characteristic_generation
    FROM browser_catalog.instrument_discovery_state AS state
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS instruments
      ON instruments.resource_key = 'instruments'
     AND instruments.generation = state.instrument_generation
     AND instruments.publication_status = 'sealed'
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS tags
      ON tags.resource_key = 'tags'
     AND tags.generation = state.tag_generation
     AND tags.publication_status = 'sealed'
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS cues
      ON cues.resource_key = 'cues'
     AND cues.generation = state.cue_generation
     AND cues.publication_status = 'sealed'
     AND cues.instrument_revision = instruments.source_revision
    INNER JOIN browser_catalog.instrument_discovery_resource_generations
      AS characteristics
      ON characteristics.resource_key = 'characteristics'
     AND characteristics.generation = state.characteristic_generation
     AND characteristics.publication_status = 'sealed'
    WHERE state.singleton
  ),
  filtered AS MATERIALIZED (
    SELECT
      row.instrument_id,
      row.item ->> 'normalizedName' AS normalized_name,
      CASE
        WHEN p_query #>> '{sort,kind}' = 'characteristic' THEN (
          SELECT characteristic.item ->> 'normalizedValue'
          FROM browser_catalog.instrument_discovery_characteristic_rows
            AS characteristic
          WHERE characteristic.generation = active.characteristic_generation
            AND characteristic.instrument_id = row.instrument_id
            AND characteristic.characteristic_key = p_query #>> '{sort,key}'
            AND characteristic.item ->> 'state' = 'available'
            AND characteristic.item ->> 'normalizedValue' IS NOT NULL
          LIMIT 1
        )::double precision
        WHEN p_query #>> '{sort,kind}' = 'cue_duration'
          AND p_query #>> '{sort,cueKind}' = 'swell' THEN (
          SELECT pg_catalog.min(
            (cue.item ->> 'durationSeconds')::double precision
          )
          FROM browser_catalog.instrument_discovery_cue_rows AS cue
          WHERE cue.generation = active.cue_generation
            AND cue.instrument_id = row.instrument_id
            AND (cue.item ->> 'swellEligible')::boolean
            AND cue.item ->> 'durationSeconds' IS NOT NULL
        )
        WHEN p_query #>> '{sort,kind}' = 'cue_duration'
          AND p_query #>> '{sort,cueKind}' = 'crash' THEN (
          SELECT pg_catalog.min(
            (cue.item ->> 'durationSeconds')::double precision
          )
          FROM browser_catalog.instrument_discovery_cue_rows AS cue
          WHERE cue.generation = active.cue_generation
            AND cue.instrument_id = row.instrument_id
            AND (cue.item ->> 'crashEligible')::boolean
            AND cue.item ->> 'durationSeconds' IS NOT NULL
        )
        ELSE NULL
      END AS sort_value,
      row.item AS base_item
    FROM active
    INNER JOIN browser_catalog.instrument_discovery_instrument_rows AS row
      ON row.generation = active.instrument_generation
    WHERE row.item ->> 'assetRole' = 'playable_sample'
      AND (
        (
          p_query -> 'cueKind' = 'null'::jsonb
          AND row.item ->> 'visibilityRole' IN ('normal', 'normal_and_cue')
        )
        OR (
          p_query -> 'cueKind' <> 'null'::jsonb
          AND row.item ->> 'visibilityRole'
            IN ('cue_only', 'normal_and_cue', 'drum_and_cue')
        )
      )
      AND (
        p_query -> 'normalizedName' = 'null'::jsonb
        OR (row.item ->> 'normalizedName') COLLATE "C" LIKE (
          pg_catalog.replace(
            pg_catalog.replace(
              pg_catalog.replace(p_query ->> 'normalizedName', E'\\', E'\\\\'),
              '%',
              E'\\%'
            ),
            '_',
            E'\\_'
          ) || '%'
        ) COLLATE "C" ESCAPE E'\\'
      )
      AND (
        pg_catalog.jsonb_array_length(p_query -> 'families') = 0
        OR row.item ->> 'family' IN (
          SELECT pg_catalog.jsonb_array_elements_text(p_query -> 'families')
        )
      )
      AND (
        pg_catalog.jsonb_array_length(p_query -> 'types') = 0
        OR row.item ->> 'instrumentType' IN (
          SELECT pg_catalog.jsonb_array_elements_text(p_query -> 'types')
        )
      )
      AND (
        pg_catalog.jsonb_array_length(p_query -> 'providerIds') = 0
        OR row.item ->> 'providerId' IN (
          SELECT pg_catalog.jsonb_array_elements_text(p_query -> 'providerIds')
        )
      )
      AND (
        pg_catalog.jsonb_array_length(p_query -> 'collections') = 0
        OR row.item ->> 'collection' IN (
          SELECT pg_catalog.jsonb_array_elements_text(p_query -> 'collections')
        )
      )
      AND (
        pg_catalog.jsonb_array_length(p_query -> 'engineTypes') = 0
        OR row.item ->> 'engineType' IN (
          SELECT pg_catalog.jsonb_array_elements_text(p_query -> 'engineTypes')
        )
      )
      AND (
        pg_catalog.jsonb_array_length(p_query -> 'playbackTypes') = 0
        OR row.item ->> 'playbackType' IN (
          SELECT pg_catalog.jsonb_array_elements_text(p_query -> 'playbackTypes')
        )
      )
      AND (
        pg_catalog.jsonb_array_length(p_query -> 'polyphonyTypes') = 0
        OR row.item ->> 'polyphonyType' IN (
          SELECT pg_catalog.jsonb_array_elements_text(p_query -> 'polyphonyTypes')
        )
      )
      AND (
        p_query -> 'playableAtMidiNote' = 'null'::jsonb
        OR (
          ((row.item -> 'range') ->> 0)::integer
            <= (p_query ->> 'playableAtMidiNote')::integer
          AND ((row.item -> 'range') ->> 1)::integer
            >= (p_query ->> 'playableAtMidiNote')::integer
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements_text(
          p_query -> 'tagIds'
        ) AS selected(tag_id)
        WHERE NOT EXISTS (
          SELECT 1
          FROM browser_catalog.instrument_discovery_tag_rows AS tag_link
          WHERE tag_link.generation = active.tag_generation
            AND tag_link.item ->> 'kind' = 'instrument_tag'
            AND tag_link.item ->> 'tagId' = selected.tag_id
            AND tag_link.item ->> 'instrumentId' = row.instrument_id::text
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(
          p_query -> 'characteristicRanges'
        ) AS selected(range_filter)
        WHERE NOT EXISTS (
          SELECT 1
          FROM browser_catalog.instrument_discovery_characteristic_rows
            AS characteristic
          WHERE characteristic.generation = active.characteristic_generation
            AND characteristic.instrument_id = row.instrument_id
            AND characteristic.characteristic_key =
              selected.range_filter ->> 'key'
            AND characteristic.item ->> 'state' = 'available'
            AND (characteristic.item ->> 'normalizedValue')::double precision
              >= (selected.range_filter ->> 'minimum')::double precision
            AND (characteristic.item ->> 'normalizedValue')::double precision
              <= (selected.range_filter ->> 'maximum')::double precision
        )
      )
      AND (
        p_query -> 'cueKind' = 'null'::jsonb
        OR EXISTS (
          SELECT 1
          FROM browser_catalog.instrument_discovery_cue_rows AS cue
          WHERE cue.generation = active.cue_generation
            AND cue.instrument_id = row.instrument_id
            AND CASE p_query ->> 'cueKind'
              WHEN 'swell' THEN (cue.item ->> 'swellEligible')::boolean
              WHEN 'crash' THEN (cue.item ->> 'crashEligible')::boolean
              ELSE false
            END
        )
      )
  ),
  after_cursor AS MATERIALIZED (
    SELECT filtered.*
    FROM filtered
    WHERE p_cursor IS NULL
      OR CASE
        WHEN p_query #>> '{sort,kind}' = 'name' THEN
          filtered.normalized_name COLLATE "C"
            > (p_cursor ->> 'normalizedName') COLLATE "C"
          OR (
            filtered.normalized_name COLLATE "C"
              = (p_cursor ->> 'normalizedName') COLLATE "C"
            AND filtered.instrument_id > (p_cursor ->> 'instrumentId')::uuid
          )
        WHEN p_cursor -> 'value' = 'null'::jsonb THEN
          filtered.sort_value IS NULL
          AND (
            filtered.normalized_name COLLATE "C"
              > (p_cursor ->> 'normalizedName') COLLATE "C"
            OR (
              filtered.normalized_name COLLATE "C"
                = (p_cursor ->> 'normalizedName') COLLATE "C"
              AND filtered.instrument_id > (p_cursor ->> 'instrumentId')::uuid
            )
          )
        ELSE
          filtered.sort_value IS NULL
          OR (
            p_query #>> '{sort,direction}' = 'asc'
            AND filtered.sort_value > (p_cursor ->> 'value')::double precision
          )
          OR (
            p_query #>> '{sort,direction}' = 'desc'
            AND filtered.sort_value < (p_cursor ->> 'value')::double precision
          )
          OR (
            filtered.sort_value = (p_cursor ->> 'value')::double precision
            AND (
              filtered.normalized_name COLLATE "C"
                > (p_cursor ->> 'normalizedName') COLLATE "C"
              OR (
                filtered.normalized_name COLLATE "C"
                  = (p_cursor ->> 'normalizedName') COLLATE "C"
                AND filtered.instrument_id > (p_cursor ->> 'instrumentId')::uuid
              )
            )
          )
      END
  ),
  limited AS MATERIALIZED (
    SELECT
      after_cursor.*,
      pg_catalog.row_number() OVER (
        ORDER BY
          CASE
            WHEN p_query #>> '{sort,kind}' <> 'name'
              THEN after_cursor.sort_value IS NULL
          END ASC,
          CASE
            WHEN p_query #>> '{sort,kind}' <> 'name'
              AND p_query #>> '{sort,direction}' = 'asc'
              THEN after_cursor.sort_value
          END ASC,
          CASE
            WHEN p_query #>> '{sort,kind}' <> 'name'
              AND p_query #>> '{sort,direction}' = 'desc'
              THEN after_cursor.sort_value
          END DESC,
          after_cursor.normalized_name COLLATE "C" ASC,
          after_cursor.instrument_id ASC
      ) AS ordinal
    FROM after_cursor
    ORDER BY
      CASE
        WHEN p_query #>> '{sort,kind}' <> 'name'
          THEN after_cursor.sort_value IS NULL
      END ASC,
      CASE
        WHEN p_query #>> '{sort,kind}' <> 'name'
          AND p_query #>> '{sort,direction}' = 'asc'
          THEN after_cursor.sort_value
      END ASC,
      CASE
        WHEN p_query #>> '{sort,kind}' <> 'name'
          AND p_query #>> '{sort,direction}' = 'desc'
          THEN after_cursor.sort_value
      END DESC,
      after_cursor.normalized_name COLLATE "C" ASC,
      after_cursor.instrument_id ASC
    LIMIT (p_query ->> 'pageSize')::integer + 1
  ),
  visible AS MATERIALIZED (
    SELECT limited.*
    FROM limited
    WHERE limited.ordinal <= (p_query ->> 'pageSize')::integer
  ),
  enriched AS (
    SELECT
      visible.ordinal,
      visible.base_item || pg_catalog.jsonb_build_object(
        'cueAvailability', pg_catalog.jsonb_build_object(
          'swell', EXISTS (
            SELECT 1
            FROM browser_catalog.instrument_discovery_cue_rows AS cue
            WHERE cue.generation = active.cue_generation
              AND cue.instrument_id = visible.instrument_id
              AND (cue.item ->> 'swellEligible')::boolean
          ),
          'crash', EXISTS (
            SELECT 1
            FROM browser_catalog.instrument_discovery_cue_rows AS cue
            WHERE cue.generation = active.cue_generation
              AND cue.instrument_id = visible.instrument_id
              AND (cue.item ->> 'crashEligible')::boolean
          )
        ),
        'characteristics', COALESCE((
          SELECT pg_catalog.jsonb_agg(
            characteristic.item
            ORDER BY characteristic.characteristic_key COLLATE "C"
          )
          FROM browser_catalog.instrument_discovery_characteristic_rows
            AS characteristic
          WHERE characteristic.generation = active.characteristic_generation
            AND characteristic.instrument_id = visible.instrument_id
            AND EXISTS (
              SELECT 1
              FROM pg_catalog.jsonb_array_elements_text(
                p_query -> 'requestedCharacteristics'
              ) AS requested(key)
              WHERE requested.key = characteristic.characteristic_key
            )
        ), '[]'::jsonb)
      ) AS item
    FROM visible
    CROSS JOIN active
  )
  SELECT pg_catalog.jsonb_build_object(
    'items', COALESCE((
      SELECT pg_catalog.jsonb_agg(enriched.item ORDER BY enriched.ordinal)
      FROM enriched
    ), '[]'::jsonb),
    'hasMore', EXISTS (
      SELECT 1
      FROM limited
      WHERE limited.ordinal > (p_query ->> 'pageSize')::integer
    ),
    'terminal', (
      SELECT pg_catalog.jsonb_build_object(
        'sortValue', limited.sort_value,
        'normalizedName', limited.normalized_name,
        'instrumentId', limited.instrument_id
      )
      FROM limited
      WHERE limited.ordinal <= (p_query ->> 'pageSize')::integer
      ORDER BY limited.ordinal DESC
      LIMIT 1
    )
  )
  FROM active;
$$;


ALTER FUNCTION "public"."search_instrument_discovery_v1"("p_query" "jsonb", "p_cursor" "jsonb") OWNER TO "postgres";


