CREATE TABLE IF NOT EXISTS "public"."instrument_v2_legacy_map" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "instrument_v2_id" "uuid" NOT NULL,
    "legacy_instrument_id" "uuid" NOT NULL,
    "sip_review_instrument_id" "uuid",
    "contributor_slug" "text",
    "legacy_lookup_key" "text" NOT NULL,
    "legacy_file_path_reference" "text",
    "legacy_velocity" smallint NOT NULL,
    "is_primary_for_legacy" boolean DEFAULT false NOT NULL,
    "is_primary_for_v2" boolean DEFAULT false NOT NULL,
    "notes" "text",
    "created_by" "text",
    "updated_by" "text",
    "primary_for_legacy_set_by" "text",
    "primary_for_legacy_set_at" timestamp with time zone,
    "primary_for_v2_set_by" "text",
    "primary_for_v2_set_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "instrument_v2_legacy_map_legacy_lookup_nonempty" CHECK ((NULLIF("btrim"("legacy_lookup_key"), ''::"text") IS NOT NULL)),
    CONSTRAINT "instrument_v2_legacy_map_legacy_velocity_min" CHECK (("legacy_velocity" >= 1))
);


ALTER TABLE "public"."instrument_v2_legacy_map" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_instrument_v2_legacy_map_primary"("p_alias_id" "uuid", "p_direction" "text", "p_updated_by" "text" DEFAULT NULL::"text") RETURNS "public"."instrument_v2_legacy_map"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target_alias "public"."instrument_v2_legacy_map"%ROWTYPE;
  now_ts timestamp with time zone := "now"();
BEGIN
  IF p_alias_id IS NULL THEN
    RAISE EXCEPTION 'p_alias_id is required' USING ERRCODE = '22023';
  END IF;

  IF p_direction NOT IN ('legacy', 'v2') THEN
    RAISE EXCEPTION 'p_direction must be legacy or v2' USING ERRCODE = '22023';
  END IF;

  -- Read the target alias's partition keys WITHOUT a row lock first so we
  -- can lock the partition before locking individual rows. Locking
  -- target_alias FOR UPDATE before the partition lock would deadlock when
  -- two concurrent callers each hold a target row and then try to lock the
  -- partition that contains the other's target.
  --
  -- Edge case: if the target row is DELETE'd between this read and the
  -- partition lock below, the partition lock acquisition uses the stale
  -- partition keys captured here. That lock is benign — it locks rows in
  -- a partition we'll never touch — and the re-read at the end of the
  -- partition-lock block will raise P0002 cleanly.
  SELECT *
  INTO target_alias
  FROM "public"."instrument_v2_legacy_map"
  WHERE "id" = p_alias_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'instrument_v2_legacy_map row not found' USING ERRCODE = 'P0002';
  END IF;

  -- Lock the entire partition (legacy_instrument_id or instrument_v2_id) in
  -- deterministic id-asc order BEFORE the target SELECT FOR UPDATE so
  -- concurrent set-primary calls on different rows of the same partition
  -- serialize. Without this, two callers can each clear the other's
  -- siblings and then both set their own row to is_primary=true, tripping
  -- the partial unique index with a 23505 instead of orderly last-write-
  -- wins. The id-asc lock order is what prevents deadlock.
  --
  -- Note: the lock covers ONE axis at a time — a 'legacy' direction call
  -- and a 'v2' direction call that share an instrument_v2_id but target
  -- different legacy_instrument_id partitions can still run concurrently.
  -- That's fine: the OTHER axis's partial unique index still protects
  -- (instrument_v2_legacy_map_primary_v2_key vs
  -- instrument_v2_legacy_map_primary_legacy_key are independent), and we
  -- never mutate both flags in one call.
  IF p_direction = 'legacy' THEN
    PERFORM 1
    FROM "public"."instrument_v2_legacy_map"
    WHERE "legacy_instrument_id" = target_alias."legacy_instrument_id"
    ORDER BY "id"
    FOR UPDATE;
  ELSE
    PERFORM 1
    FROM "public"."instrument_v2_legacy_map"
    WHERE "instrument_v2_id" = target_alias."instrument_v2_id"
    ORDER BY "id"
    FOR UPDATE;
  END IF;

  -- Re-read the target row under the partition lock to refresh state in
  -- case another transaction modified it between our initial read and the
  -- partition lock acquisition.
  SELECT *
  INTO target_alias
  FROM "public"."instrument_v2_legacy_map"
  WHERE "id" = p_alias_id;

  IF NOT FOUND THEN
    -- The row was deleted between the initial read and now (rare).
    RAISE EXCEPTION 'instrument_v2_legacy_map row not found' USING ERRCODE = 'P0002';
  END IF;

  IF p_direction = 'legacy' THEN
    UPDATE "public"."instrument_v2_legacy_map"
    SET
      "is_primary_for_legacy" = false,
      "updated_by" = p_updated_by
    WHERE "legacy_instrument_id" = target_alias."legacy_instrument_id"
      AND "id" <> p_alias_id
      AND "is_primary_for_legacy" = true;

    UPDATE "public"."instrument_v2_legacy_map"
    SET
      "is_primary_for_legacy" = true,
      "primary_for_legacy_set_by" = p_updated_by,
      "primary_for_legacy_set_at" = now_ts,
      "updated_by" = p_updated_by
    WHERE "id" = p_alias_id
    RETURNING * INTO target_alias;
  ELSE
    UPDATE "public"."instrument_v2_legacy_map"
    SET
      "is_primary_for_v2" = false,
      "updated_by" = p_updated_by
    WHERE "instrument_v2_id" = target_alias."instrument_v2_id"
      AND "id" <> p_alias_id
      AND "is_primary_for_v2" = true;

    UPDATE "public"."instrument_v2_legacy_map"
    SET
      "is_primary_for_v2" = true,
      "primary_for_v2_set_by" = p_updated_by,
      "primary_for_v2_set_at" = now_ts,
      "updated_by" = p_updated_by
    WHERE "id" = p_alias_id
    RETURNING * INTO target_alias;
  END IF;

  RETURN target_alias;
END;
$$;


ALTER FUNCTION "public"."set_instrument_v2_legacy_map_primary"("p_alias_id" "uuid", "p_direction" "text", "p_updated_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_instrument_v2_legacy_map_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW."updated_at" = "now"();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_instrument_v2_legacy_map_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_instrument_v2_published_manifest_aware_v1"("p_instrument_v2_id" "uuid", "p_published" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_readiness jsonb;
  v_candidate jsonb;
  v_manifest public.instrument_runtime_sample_manifests%ROWTYPE;
  v_persisted_readiness public.instrument_v2_runtime_readiness%ROWTYPE;
  v_changed boolean := false;
  v_current_published boolean;
  v_diagnostic_fallback_state text;
  v_blockers jsonb;
  v_deterministic_ready boolean := false;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'instrument-runtime-sample-manifest:' || p_instrument_v2_id::text,
      0
    )
  );
  SELECT instrument.published INTO v_current_published
  FROM public.instruments_v2 instrument
  WHERE instrument.id = p_instrument_v2_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'instrument_v2_not_found' USING ERRCODE = '22023';
  END IF;

  IF NOT p_published THEN
    SELECT jsonb_build_object(
      'instrumentV2Id', readiness.instrument_v2_id,
      'manifestSha256', readiness.manifest_sha256,
      'variantCount', readiness.variant_count,
      'addressReady', readiness.address_ready,
      'addressStatus', readiness.address_status,
      'behaviorReady', readiness.behavior_ready,
      'fallbackEligibility', readiness.fallback_eligibility,
      'fallbackState', readiness.fallback_state,
      'blockers', readiness.blockers
    ) INTO v_readiness
    FROM public.instrument_v2_runtime_readiness readiness
    WHERE readiness.instrument_v2_id = p_instrument_v2_id;

    PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);
    UPDATE public.instruments_v2
    SET published = false
    WHERE id = p_instrument_v2_id
      AND published;
    v_changed := FOUND;
    DELETE FROM public.instrument_v2_deterministic_publication_admissions
    WHERE instrument_v2_id = p_instrument_v2_id;

    RETURN COALESCE(v_readiness, jsonb_build_object(
      'instrumentV2Id', p_instrument_v2_id,
      'addressReady', false,
      'behaviorReady', false,
      'fallbackState', 'blocked',
      'blockers', '[]'::jsonb
    )) || jsonb_build_object('published', false, 'changed', v_changed);
  END IF;

  v_readiness := public.refresh_instrument_v2_runtime_readiness_v1(
    p_instrument_v2_id,
    false
  );
  v_candidate := public.build_instrument_runtime_sample_manifest_v1(
    p_instrument_v2_id
  );

  SELECT * INTO v_manifest
  FROM public.instrument_runtime_sample_manifests manifest
  WHERE manifest.instrument_v2_id = p_instrument_v2_id;

  SELECT * INTO v_persisted_readiness
  FROM public.instrument_v2_runtime_readiness readiness
  WHERE readiness.instrument_v2_id = p_instrument_v2_id;

  v_deterministic_ready :=
    v_manifest.instrument_v2_id IS NOT NULL
    AND v_persisted_readiness.instrument_v2_id IS NOT NULL
    AND v_manifest.schema_version = 1
    AND v_manifest.is_complete
    AND jsonb_array_length(v_manifest.blocking_reasons) = 0
    AND v_persisted_readiness.address_ready
    AND v_persisted_readiness.behavior_ready
    AND v_persisted_readiness.fallback_state = 'runtime_manifest'
    AND jsonb_array_length(v_persisted_readiness.blockers) = 0
    AND v_manifest.manifest_sha256 = v_persisted_readiness.manifest_sha256
    AND v_manifest.manifest_sha256 = v_candidate->>'manifestSha256'
    AND v_manifest.variant_count = (v_candidate->>'variantCount')::integer
    AND v_manifest.variants = v_candidate->'variants'
    AND v_manifest.blocking_reasons = v_candidate->'blockingReasons'
    AND COALESCE((v_candidate->>'isComplete')::boolean, false);

  IF NOT COALESCE(v_deterministic_ready, false) THEN
    v_diagnostic_fallback_state := v_readiness->>'fallbackState';
    v_blockers := COALESCE(v_readiness->'blockers', '[]'::jsonb);
    IF v_manifest.instrument_v2_id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'runtime_manifest_missing',
        'readinessClass', 'behavior',
        'remediationClass', 'runtime_manifest_review'
      ));
    ELSIF NOT v_manifest.is_complete THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'runtime_manifest_incomplete',
        'readinessClass', 'behavior',
        'remediationClass', 'runtime_manifest_review'
      ));
    END IF;
    IF v_persisted_readiness.instrument_v2_id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'runtime_readiness_missing',
        'readinessClass', 'behavior',
        'remediationClass', 'runtime_manifest_review'
      ));
    ELSIF v_manifest.manifest_sha256
        IS DISTINCT FROM v_persisted_readiness.manifest_sha256
      OR v_manifest.manifest_sha256
        IS DISTINCT FROM v_candidate->>'manifestSha256'
    THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'runtime_manifest_hash_mismatch',
        'readinessClass', 'behavior',
        'remediationClass', 'runtime_manifest_review'
      ));
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_blockers) blocker
      WHERE blocker->>'code' = 'deterministic_runtime_required'
    ) THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'deterministic_runtime_required',
        'readinessClass', 'behavior',
        'remediationClass', 'runtime_manifest_review'
      ));
    END IF;

    UPDATE public.instrument_v2_runtime_readiness readiness
    SET blockers = v_blockers,
        evaluated_at = now()
    WHERE readiness.instrument_v2_id = p_instrument_v2_id;

    -- Grandfathered rows have no admission receipt and remain published for
    -- compatibility. A row admitted by this gate loses publication as soon as
    -- reevaluation disproves its receipt-bound invariant.
    IF v_current_published AND EXISTS (
      SELECT 1
      FROM public.instrument_v2_deterministic_publication_admissions admission
      WHERE admission.instrument_v2_id = p_instrument_v2_id
    ) THEN
      PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);
      UPDATE public.instruments_v2
      SET published = false
      WHERE id = p_instrument_v2_id
        AND published;
      DELETE FROM public.instrument_v2_deterministic_publication_admissions
      WHERE instrument_v2_id = p_instrument_v2_id;
      v_current_published := false;
    END IF;

    -- The effective publication decision is blocked. Preserve the underlying
    -- persisted classification separately for construct-hydration diagnosis.
    RETURN v_readiness || jsonb_build_object(
      'fallbackState', 'blocked',
      'diagnosticFallbackState', v_diagnostic_fallback_state,
      'blockers', v_blockers,
      'candidateManifestSha256', v_candidate->>'manifestSha256',
      'published', v_current_published,
      'changed', false
    );
  END IF;

  PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);
  PERFORM set_config(
    'app.sip_deterministic_publication_authorized',
    'on',
    true
  );
  UPDATE public.instruments_v2
  SET published = true
  WHERE id = p_instrument_v2_id
    AND NOT published;
  v_changed := FOUND;
  PERFORM set_config(
    'app.sip_deterministic_publication_authorized',
    'off',
    true
  );

  RETURN v_readiness || jsonb_build_object(
    'candidateManifestSha256', v_candidate->>'manifestSha256',
    'published', true,
    'changed', v_changed
  );
END;
$$;


ALTER FUNCTION "public"."set_instrument_v2_published_manifest_aware_v1"("p_instrument_v2_id" "uuid", "p_published" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_instrument_v2_published_manifest_aware_v1"("p_instrument_v2_id" "uuid", "p_published" boolean) IS 'The sole Instrument V2 publication primitive. Refusals persist diagnostic evidence and return deterministic_runtime_required without unpublishing historical rows.';



