CREATE OR REPLACE FUNCTION "public"."set_my_feature_flag"("p_flag_key" "text", "p_enabled" boolean) RETURNS TABLE("key" "text", "enabled" boolean, "assigned_enabled" boolean, "evaluation_reason" "text", "is_active" boolean, "requires_reload" boolean, "dev_logging_enabled" boolean, "product_insights_enabled" boolean, "assignment_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := (SELECT private.feature_flag_request_user_id());
  v_feature_flag_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF p_flag_key IS NULL OR p_flag_key = '' OR p_enabled IS NULL THEN
    RAISE EXCEPTION 'flag key and enabled state are required'
      USING ERRCODE = '22004';
  END IF;

  IF NOT private.is_current_soundsculpt_staff() THEN
    RAISE EXCEPTION 'internal feature self-service is not permitted'
      USING ERRCODE = '42501';
  END IF;

  SELECT flags.id
  INTO v_feature_flag_id
  FROM public.feature_flags AS flags
  WHERE flags.key = p_flag_key
    AND flags.self_service_enabled
    AND flags.archived_at IS NULL;

  IF v_feature_flag_id IS NULL THEN
    RAISE EXCEPTION 'feature flag is unavailable for self-service'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.feature_user_enablements (
    user_id,
    feature_flag_id,
    enabled,
    change_reason,
    updated_via,
    created_by_user_id,
    updated_by_user_id
  ) VALUES (
    v_user_id,
    v_feature_flag_id,
    p_enabled,
    'Internal self-service toggle',
    'self_service',
    v_user_id,
    v_user_id
  )
  ON CONFLICT ON CONSTRAINT feature_user_enablements_pkey DO UPDATE
    SET enabled = EXCLUDED.enabled,
        change_reason = EXCLUDED.change_reason,
        updated_via = EXCLUDED.updated_via,
        updated_by_user_id = EXCLUDED.updated_by_user_id
  WHERE public.feature_user_enablements.enabled IS DISTINCT FROM EXCLUDED.enabled;

  RETURN QUERY
  SELECT
    snapshot.key,
    snapshot.enabled,
    snapshot.assigned_enabled,
    snapshot.evaluation_reason,
    snapshot.is_active,
    snapshot.requires_reload,
    snapshot.dev_logging_enabled,
    snapshot.product_insights_enabled,
    snapshot.assignment_updated_at
  FROM public.get_my_feature_flags() AS snapshot
  WHERE snapshot.key = p_flag_key;
END;
$$;


