CREATE OR REPLACE FUNCTION "public"."set_saved_loop_discoverability"("p_saved_loop_id" "uuid", "p_is_discoverable" boolean) RETURNS "public"."saved_loops"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  updated_saved_loop public.saved_loops;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication is required to set loop discoverability'
      USING ERRCODE = '42501';
  END IF;

  IF p_is_discoverable IS NULL THEN
    RAISE EXCEPTION 'p_is_discoverable must be true or false'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.set_config(
    'app.saved_loop_discoverability_write',
    'on',
    true
  );

  IF p_is_discoverable THEN
    UPDATE public.saved_loops
    SET
      show_in_loops_library = true,
      share_visibility = 'public',
      published_at = COALESCE(published_at, pg_catalog.now())
    WHERE id = p_saved_loop_id
      AND user_id = auth.uid()
      AND is_archived = false
    RETURNING * INTO updated_saved_loop;
  ELSE
    UPDATE public.saved_loops
    SET show_in_loops_library = false
    WHERE id = p_saved_loop_id
      AND user_id = auth.uid()
      AND is_archived = false
    RETURNING * INTO updated_saved_loop;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saved loop not found or not owned by the current user'
      USING ERRCODE = 'P0002';
  END IF;

  RETURN updated_saved_loop;
END;
$$;


ALTER FUNCTION "public"."set_saved_loop_discoverability"("p_saved_loop_id" "uuid", "p_is_discoverable" boolean) OWNER TO "postgres";


