CREATE OR REPLACE FUNCTION "public"."set_sip_review_warning_review_status"("p_rows" "jsonb", "p_next_status" "text", "p_actor" "text" DEFAULT 'internal'::"text", "p_note" "text" DEFAULT ''::"text", "p_scope" "text" DEFAULT 'row'::"text") RETURNS TABLE("affected_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_next_status text := lower(trim(coalesce(p_next_status, '')));
  v_actor text := coalesce(nullif(trim(p_actor), ''), 'internal');
  v_note text;
  v_scope text := lower(trim(coalesce(p_scope, 'row')));
  v_provider_slug text;
BEGIN
  IF coalesce(auth.role(), '') = 'authenticated'
     AND NOT public.is_soundsculpt_staff() THEN
    RAISE EXCEPTION 'insufficient_privilege' USING ERRCODE = '42501';
  END IF;
  IF v_next_status NOT IN ('open', 'confirmed', 'accepted', 'addressed') THEN
    RAISE EXCEPTION 'invalid_warning_review_status' USING ERRCODE = '22023';
  END IF;
  v_note := CASE WHEN v_next_status = 'open' THEN ''
                 ELSE trim(coalesce(p_note, '')) END;
  IF v_scope NOT IN ('row', 'instrument_type', 'contributor_type') THEN
    RAISE EXCEPTION 'invalid_warning_review_scope' USING ERRCODE = '22023';
  END IF;

  FOR v_provider_slug IN
    SELECT DISTINCT lower(btrim(x.contributor_slug)) AS provider_slug
    FROM jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb)) AS x(
      sip_review_instrument_id uuid,
      contributor_slug text,
      category text,
      warning_key text,
      type text
    )
    WHERE btrim(coalesce(x.contributor_slug, '')) <> ''
    ORDER BY lower(btrim(x.contributor_slug))
  LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(
      hashtextextended(v_provider_slug, 0)
    );
  END LOOP;

  RETURN QUERY
  WITH input_rows AS (
    SELECT DISTINCT
      x.sip_review_instrument_id,
      x.contributor_slug,
      x.category,
      x.warning_key,
      x.type
    FROM jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb)) AS x(
      sip_review_instrument_id uuid,
      contributor_slug text,
      category text,
      warning_key text,
      type text
    )
    WHERE x.sip_review_instrument_id IS NOT NULL
      AND btrim(coalesce(x.contributor_slug, '')) <> ''
      AND btrim(coalesce(x.category, '')) <> ''
      AND btrim(coalesce(x.warning_key, '')) <> ''
      AND btrim(coalesce(x.type, '')) <> ''
  ), changed AS (
    SELECT i.sip_review_instrument_id, i.contributor_slug, i.category,
           i.warning_key, i.type, coalesce(s.status, 'open') AS previous_status
    FROM input_rows i
    LEFT JOIN public.sip_review_warning_review_state s
      ON s.sip_review_instrument_id = i.sip_review_instrument_id
     AND s.category = i.category
     AND s.warning_key = i.warning_key
    WHERE coalesce(s.status, 'open') <> v_next_status
       OR (v_next_status <> 'open' AND coalesce(s.note, '') <> v_note)
  ), deleted_state AS (
    DELETE FROM public.sip_review_warning_review_state s
    USING changed c
    WHERE v_next_status = 'open'
      AND s.sip_review_instrument_id = c.sip_review_instrument_id
      AND s.category = c.category
      AND s.warning_key = c.warning_key
    RETURNING 1
  ), upserted_state AS (
    INSERT INTO public.sip_review_warning_review_state(
      sip_review_instrument_id, contributor_slug, category, warning_key, type,
      status, note, updated_by
    )
    SELECT sip_review_instrument_id, contributor_slug, category, warning_key,
           type, v_next_status, v_note, v_actor
    FROM changed
    WHERE v_next_status <> 'open'
    ON CONFLICT (sip_review_instrument_id, category, warning_key) DO UPDATE SET
      contributor_slug = EXCLUDED.contributor_slug,
      type = EXCLUDED.type,
      status = EXCLUDED.status,
      note = EXCLUDED.note,
      updated_by = EXCLUDED.updated_by,
      updated_at = now()
    RETURNING 1
  ), inserted_events AS (
    INSERT INTO public.sip_review_warning_review_event(
      sip_review_instrument_id, contributor_slug, category, warning_key, type,
      previous_status, next_status, scope, note, actor
    )
    SELECT sip_review_instrument_id, contributor_slug, category, warning_key,
           type, previous_status, v_next_status, v_scope, v_note, v_actor
    FROM changed
    RETURNING 1
  )
  SELECT count(*)::integer FROM changed;
END;
$$;


ALTER FUNCTION "public"."set_sip_review_warning_review_status"("p_rows" "jsonb", "p_next_status" "text", "p_actor" "text", "p_note" "text", "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_apply_completion_materialization_v1"("p_rehearsal_id" "uuid", "p_expected_origin_main_sha" "text", "p_expected_manifest_sha256" "text", "p_expected_snapshot_sha256" "text", "p_expected_plan_sha256" "text", "p_expected_batch_root_sha256" "text", "p_authorization_ref" "text", "p_inventory_location" "text", "p_inventory_version" "text", "p_normalization_version" "text", "p_inventory_identity_sha256" "text", "p_database_identity_sha256" "text", "p_provider_manifest_raw_lf_sha256" "text", "p_provider_manifest_normalized_lf_sha256" "text", "p_inventory_items" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_rehearsal public.sip_completion_materialization_rehearsal%ROWTYPE;
  v_basis public.sip_completion_materialization_rehearsal_basis%ROWTYPE;
  v_receipt_id uuid := gen_random_uuid();
  v_application_id uuid;
  v_item_count bigint;
  v_provider_count bigint;
  v_generated_count bigint;
  v_exception_count bigint;
  v_open_source_count bigint;
  v_open_projection_count bigint;
  v_open_membership_count bigint;
  v_missing_registry_count bigint;
  v_uncovered_source_count bigint;
  v_source_count_before bigint;
  v_source_count_after bigint;
BEGIN
  IF current_setting('transaction_isolation') <> 'repeatable read' THEN
    RAISE EXCEPTION 'completion materialization apply requires repeatable read'
      USING ERRCODE = '25001';
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('sip-completion-materialization-global-v1', 0)
  );

  SELECT * INTO v_rehearsal
  FROM public.sip_completion_materialization_rehearsal
  WHERE id = p_rehearsal_id
  FOR UPDATE;
  IF NOT FOUND OR v_rehearsal.lifecycle_status <> 'rehearsed' THEN
    RAISE EXCEPTION 'exact unconsumed rehearsal receipt is required';
  END IF;
  IF v_rehearsal.conflict_count <> 0
    OR v_rehearsal.origin_main_sha <> p_expected_origin_main_sha
    OR v_rehearsal.manifest_sha256 <> p_expected_manifest_sha256
    OR v_rehearsal.snapshot_sha256 <> p_expected_snapshot_sha256
    OR v_rehearsal.plan_sha256 <> p_expected_plan_sha256
    OR v_rehearsal.batch_root_sha256 <> p_expected_batch_root_sha256
  THEN
    RAISE EXCEPTION 'completion materialization rehearsal proof drifted';
  END IF;
  SELECT * INTO v_basis
  FROM public.sip_completion_materialization_rehearsal_basis
  WHERE rehearsal_id = v_rehearsal.id;
  IF NOT FOUND
    OR v_basis.provider_manifest_raw_lf_sha256
      <> p_provider_manifest_raw_lf_sha256
    OR v_basis.provider_manifest_normalized_lf_sha256
      <> p_provider_manifest_normalized_lf_sha256
  THEN
    RAISE EXCEPTION 'repository LF inventory basis drifted';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs
    WHERE status IN ('queued', 'running')
  ) OR EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases
    WHERE released_at IS NULL AND lease_expires_at > now()
  ) OR EXISTS (
    SELECT 1 FROM public.sip_fleet_executor_leases
    WHERE lease_expires_at > now()
  ) OR EXISTS (
    SELECT 1 FROM public.sip_pipeline_runs
    WHERE status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'active completion-ledger work blocks apply';
  END IF;
  IF jsonb_typeof(p_inventory_items) <> 'array' THEN
    RAISE EXCEPTION 'server-derived inventory items must be an array';
  END IF;

  CREATE TEMP TABLE completion_materialization_inventory_input
  ON COMMIT DROP AS
  SELECT
    item."normalizedPath"::text AS normalized_path,
    item."sampleOriginalPathId"::uuid AS sample_original_path_id,
    item."denominatorCohort"::text AS denominator_cohort
  FROM jsonb_to_recordset(p_inventory_items) AS item(
    "normalizedPath" text,
    "sampleOriginalPathId" uuid,
    "denominatorCohort" text
  );
  IF EXISTS (
    SELECT 1 FROM completion_materialization_inventory_input
    WHERE normalized_path IS NULL OR normalized_path = ''
      OR sample_original_path_id IS NULL
      OR denominator_cohort NOT IN (
        'provider_manifest', 'generated_lineage', 'reviewed_exception'
      )
  ) OR EXISTS (
    SELECT 1 FROM completion_materialization_inventory_input
    GROUP BY normalized_path HAVING count(*) <> 1
  ) OR EXISTS (
    SELECT 1 FROM completion_materialization_inventory_input
    GROUP BY sample_original_path_id HAVING count(*) <> 1
  ) THEN
    RAISE EXCEPTION 'inventory union contains invalid or duplicate identities';
  END IF;

  SELECT
    count(*),
    count(*) FILTER (WHERE denominator_cohort = 'provider_manifest'),
    count(*) FILTER (WHERE denominator_cohort = 'generated_lineage'),
    count(*) FILTER (WHERE denominator_cohort = 'reviewed_exception')
  INTO v_item_count, v_provider_count, v_generated_count, v_exception_count
  FROM completion_materialization_inventory_input;
  IF v_item_count <> v_rehearsal.inventory_count
    OR v_item_count <> v_rehearsal.database_count
    OR v_provider_count <> v_rehearsal.provider_manifest_count
    OR v_generated_count <> v_rehearsal.generated_lineage_count
    OR v_exception_count <> v_rehearsal.exception_count
    OR EXISTS (
      SELECT 1 FROM completion_materialization_inventory_input input
      LEFT JOIN public.samples_original_paths source
        ON source.id = input.sample_original_path_id
      WHERE source.id IS NULL
    )
  THEN
    RAISE EXCEPTION 'inventory denominator union drifted';
  END IF;

  SELECT count(*) INTO v_source_count_before
  FROM public.sip_completion_source source
  JOIN completion_materialization_inventory_input input
    ON input.sample_original_path_id = source.sample_original_path_id;
  INSERT INTO public.sip_completion_source (
    sample_original_path_id,
    rights_status,
    rights_resolution_version,
    rights_evidence
  )
  SELECT
    source.id,
    CASE WHEN source.licensing_secured
      THEN 'legacy_allowed_unverified'
      ELSE 'legacy_blocked_unverified'
    END,
    'legacy-licensing-flag-v1',
    jsonb_build_object(
      'source', 'samples_original_paths.licensing_secured',
      'legacyValue', source.licensing_secured
    )
  FROM public.samples_original_paths source
  JOIN completion_materialization_inventory_input input
    ON input.sample_original_path_id = source.id
  ON CONFLICT (sample_original_path_id) DO NOTHING;
  SELECT count(*) INTO v_source_count_after
  FROM public.sip_completion_source source
  JOIN completion_materialization_inventory_input input
    ON input.sample_original_path_id = source.sample_original_path_id;

  SELECT count(*) INTO v_open_source_count
  FROM public.sip_completion_source source
  JOIN completion_materialization_inventory_input input
    ON input.sample_original_path_id = source.sample_original_path_id
  WHERE source.ownership_status <> 'resolved'
    OR (
      source.rights_status NOT IN ('verified_allowed', 'verified_restricted')
      AND source.global_disposition NOT IN ('rights_held', 'out_of_scope')
    )
    OR source.admission_status IN ('unknown', 'conflicting')
    OR source.global_disposition = 'conflicting';
  SELECT count(*) INTO v_open_projection_count
  FROM public.sip_completion_projection projection
  WHERE projection.is_intended
    AND projection.projection_decision IN ('undecided', 'conflicting');
  SELECT count(*) INTO v_open_membership_count
  FROM public.sip_completion_projection_membership membership
  WHERE membership.is_intended
    AND membership.membership_decision IN ('undecided', 'conflicting');
  SELECT count(*) INTO v_missing_registry_count
  FROM (
    SELECT DISTINCT source.canonical_provider_key
    FROM public.sip_completion_source source
    JOIN completion_materialization_inventory_input input
      ON input.sample_original_path_id = source.sample_original_path_id
  ) provider
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.sip_completion_projection_registry registry
    WHERE registry.provider_scope_key = provider.canonical_provider_key
      AND registry.status = 'frozen'
      AND registry.source_count = (
        SELECT count(*)
        FROM public.sip_completion_source source
        WHERE source.canonical_provider_key = registry.provider_scope_key
      )
      AND registry.intended_projection_count = (
        SELECT count(*)
        FROM public.sip_completion_projection projection
        WHERE projection.provider_scope_key = registry.provider_scope_key
          AND projection.is_intended
      )
      AND registry.intended_membership_count = (
        SELECT count(*)
        FROM public.sip_completion_projection_membership membership
        JOIN public.sip_completion_projection projection
          ON projection.id = membership.completion_projection_id
        WHERE projection.provider_scope_key = registry.provider_scope_key
          AND membership.is_intended
      )
      AND registry.source_identity_sha256 =
        public.sip_completion_identity_digest_v1(ARRAY(
          SELECT source.sample_original_path_id::text
          FROM public.sip_completion_source source
          WHERE source.canonical_provider_key = registry.provider_scope_key
          ORDER BY source.sample_original_path_id::text
        ))
      AND registry.projection_identity_sha256 =
        public.sip_completion_identity_digest_v1(ARRAY(
          SELECT projection.projection_key
          FROM public.sip_completion_projection projection
          WHERE projection.provider_scope_key = registry.provider_scope_key
            AND projection.is_intended
          ORDER BY projection.projection_key COLLATE "C"
        ))
      AND registry.membership_identity_sha256 =
        public.sip_completion_identity_digest_v1(ARRAY(
          SELECT
            projection.projection_key || '/' ||
              membership.sample_original_path_id
          FROM public.sip_completion_projection_membership membership
          JOIN public.sip_completion_projection projection
            ON projection.id = membership.completion_projection_id
          WHERE projection.provider_scope_key = registry.provider_scope_key
            AND membership.is_intended
          ORDER BY
            projection.projection_key COLLATE "C",
            membership.sample_original_path_id
        ))
  );
  SELECT count(*) INTO v_uncovered_source_count
  FROM completion_materialization_inventory_input input
  JOIN public.sip_completion_source source
    ON source.sample_original_path_id = input.sample_original_path_id
  WHERE source.global_disposition IN ('open', 'conflicting')
    AND NOT EXISTS (
    SELECT 1
    FROM public.sip_completion_projection_membership membership
    JOIN public.sip_completion_projection projection
      ON projection.id = membership.completion_projection_id
    WHERE membership.sample_original_path_id = input.sample_original_path_id
      AND membership.is_intended
      AND projection.is_intended
  );
  IF v_open_source_count <> 0 OR v_open_projection_count <> 0
    OR v_open_membership_count <> 0 OR v_missing_registry_count <> 0
    OR v_uncovered_source_count <> 0
  THEN
    RAISE EXCEPTION
      'completion closure decisions missing: source %, projection %, membership %, registry %, uncovered %',
      v_open_source_count, v_open_projection_count, v_open_membership_count,
      v_missing_registry_count, v_uncovered_source_count;
  END IF;

  UPDATE public.sip_completion_materialization_rehearsal
  SET lifecycle_status = 'applying'
  WHERE id = v_rehearsal.id;

  INSERT INTO public.sip_completion_inventory_receipt (
    id, inventory_location, inventory_version, normalization_version,
    origin_main_sha, production_observed_at,
    inventory_count, database_count, matched_count,
    inventory_only_count, database_only_count,
    inventory_sorted_path_sha256, database_sorted_path_sha256,
    result, evidence, created_by,
    provider_manifest_count, generated_lineage_count,
    reviewed_exception_count, provider_manifest_raw_lf_sha256,
    provider_manifest_normalized_lf_sha256,
    inventory_identity_digest_version
  ) VALUES (
    v_receipt_id, p_inventory_location, p_inventory_version,
    p_normalization_version, v_rehearsal.origin_main_sha, now(),
    v_item_count, v_item_count, v_item_count, 0, 0,
    p_inventory_identity_sha256, p_database_identity_sha256,
    'matched',
    jsonb_build_object(
      'rehearsalId', v_rehearsal.id,
      'manifestSha256', v_rehearsal.manifest_sha256,
      'snapshotSha256', v_rehearsal.snapshot_sha256,
      'planSha256', v_rehearsal.plan_sha256,
      'globalTonalityReady', false
    ),
    btrim(p_applied_by),
    v_provider_count, v_generated_count, v_exception_count,
    p_provider_manifest_raw_lf_sha256,
    p_provider_manifest_normalized_lf_sha256,
    'sip_completion_identity_digest_v1'
  );
  INSERT INTO public.sip_completion_inventory_item (
    receipt_id, normalized_path, sample_original_path_id,
    parity_status, denominator_cohort
  )
  SELECT v_receipt_id, normalized_path, sample_original_path_id,
    'matched', denominator_cohort
  FROM completion_materialization_inventory_input
  ORDER BY normalized_path COLLATE "C";

  INSERT INTO public.sip_completion_materialization_application (
    rehearsal_id, inventory_receipt_id, authorization_ref, origin_main_sha,
    manifest_sha256, rehearsal_snapshot_sha256, rehearsal_plan_sha256,
    rehearsal_batch_root_sha256, applied_source_count,
    idempotent_source_count, inventory_item_count, applied_by
  ) VALUES (
    v_rehearsal.id, v_receipt_id, btrim(p_authorization_ref),
    v_rehearsal.origin_main_sha, v_rehearsal.manifest_sha256,
    v_rehearsal.snapshot_sha256, v_rehearsal.plan_sha256,
    v_rehearsal.batch_root_sha256,
    v_source_count_after - v_source_count_before,
    v_source_count_before, v_item_count, btrim(p_applied_by)
  ) RETURNING id INTO v_application_id;
  UPDATE public.sip_completion_materialization_rehearsal
  SET lifecycle_status = 'completed'
  WHERE id = v_rehearsal.id;

  RETURN jsonb_build_object(
    'applicationId', v_application_id,
    'rehearsalId', v_rehearsal.id,
    'inventoryReceiptId', v_receipt_id,
    'status', 'HOLD',
    'lifecycleStatus', 'completed',
    'appliedSources', v_source_count_after - v_source_count_before,
    'idempotentSources', v_source_count_before,
    'inventoryItems', v_item_count,
    'readinessEvaluated', false,
    'globalTonalityReady', false
  );
END;
$$;


ALTER FUNCTION "public"."sip_apply_completion_materialization_v1"("p_rehearsal_id" "uuid", "p_expected_origin_main_sha" "text", "p_expected_manifest_sha256" "text", "p_expected_snapshot_sha256" "text", "p_expected_plan_sha256" "text", "p_expected_batch_root_sha256" "text", "p_authorization_ref" "text", "p_inventory_location" "text", "p_inventory_version" "text", "p_normalization_version" "text", "p_inventory_identity_sha256" "text", "p_database_identity_sha256" "text", "p_provider_manifest_raw_lf_sha256" "text", "p_provider_manifest_normalized_lf_sha256" "text", "p_inventory_items" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_apply_completion_materialization_v2"("p_rehearsal_id" "uuid", "p_expected_origin_main_sha" "text", "p_expected_manifest_sha256" "text", "p_expected_snapshot_sha256" "text", "p_expected_plan_sha256" "text", "p_expected_batch_root_sha256" "text", "p_authorization_ref" "text", "p_inventory_location" "text", "p_inventory_version" "text", "p_normalization_version" "text", "p_inventory_identity_sha256" "text", "p_database_identity_sha256" "text", "p_provider_manifest_raw_lf_sha256" "text", "p_provider_manifest_normalized_lf_sha256" "text", "p_inventory_items" "jsonb", "p_closure_evidence" "jsonb", "p_projection_package" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_rehearsal public.sip_completion_materialization_rehearsal%ROWTYPE;
  v_basis public.sip_completion_materialization_rehearsal_basis%ROWTYPE;
  v_receipt_id uuid := gen_random_uuid();
  v_application_id uuid;
  v_item_count bigint;
  v_provider_count bigint;
  v_generated_count bigint;
  v_exception_count bigint;
  v_source_count_before bigint;
  v_source_count_after bigint;
  v_registry_id uuid;
  v_provider record;
  v_open_source_count bigint;
  v_open_projection_count bigint;
  v_open_membership_count bigint;
  v_missing_registry_count bigint;
  v_uncovered_source_count bigint;
  v_current_association_sha256 text;
BEGIN
  IF current_setting('transaction_isolation') <> 'repeatable read' THEN
    RAISE EXCEPTION 'completion materialization apply requires repeatable read'
      USING ERRCODE = '25001';
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('sip-completion-materialization-global-v2', 0)
  );

  SELECT * INTO v_rehearsal
  FROM public.sip_completion_materialization_rehearsal
  WHERE id = p_rehearsal_id
  FOR UPDATE;
  IF NOT FOUND OR v_rehearsal.lifecycle_status <> 'rehearsed' THEN
    RAISE EXCEPTION 'exact unconsumed rehearsal receipt is required';
  END IF;
  IF v_rehearsal.conflict_count <> 0
    OR v_rehearsal.origin_main_sha <> p_expected_origin_main_sha
    OR v_rehearsal.manifest_sha256 <> p_expected_manifest_sha256
    OR v_rehearsal.snapshot_sha256 <> p_expected_snapshot_sha256
    OR v_rehearsal.plan_sha256 <> p_expected_plan_sha256
    OR v_rehearsal.batch_root_sha256 <> p_expected_batch_root_sha256
  THEN
    RAISE EXCEPTION 'completion materialization rehearsal proof drifted';
  END IF;
  SELECT * INTO v_basis
  FROM public.sip_completion_materialization_rehearsal_basis
  WHERE rehearsal_id = v_rehearsal.id;
  IF NOT FOUND
    OR v_basis.closure_file_sha256 IS NULL
    OR v_basis.projection_package_file_sha256 IS NULL
    OR v_basis.provider_manifest_raw_lf_sha256
      <> p_provider_manifest_raw_lf_sha256
    OR v_basis.provider_manifest_normalized_lf_sha256
      <> p_provider_manifest_normalized_lf_sha256
    OR p_closure_evidence->>'manifestSha256'
      <> v_basis.closure_manifest_sha256
    OR p_projection_package->>'manifestSha256'
      <> v_basis.projection_package_manifest_sha256
    OR p_projection_package#>>'{closure,fileSha256}'
      <> v_basis.closure_file_sha256
    OR p_projection_package#>>'{closure,manifestSha256}'
      <> v_basis.closure_manifest_sha256
    OR p_projection_package#>>'{closure,inputSha256}'
      <> v_basis.closure_input_sha256
    OR p_projection_package#>>'{observation,associationIdentitySha256}'
      <> v_basis.projection_association_identity_sha256
    OR encode(extensions.digest(
      convert_to(p_closure_evidence::text, 'UTF8'), 'sha256'
    ), 'hex') <> v_basis.closure_payload_sha256
    OR encode(extensions.digest(
      convert_to(p_projection_package::text, 'UTF8'), 'sha256'
    ), 'hex') <> v_basis.projection_package_payload_sha256
  THEN
    RAISE EXCEPTION 'immutable successor package basis drifted';
  END IF;
  IF p_closure_evidence->>'schemaVersion'
      <> 'sip-completion-ledger-closure-evidence-v1'
    OR p_projection_package->>'schemaVersion'
      <> 'sip-completion-ledger-successor-projection-package-v1'
    OR p_projection_package->>'status' <> 'HOLD'
  THEN
    RAISE EXCEPTION 'unsupported successor package schema';
  END IF;
  SELECT encode(extensions.digest(convert_to(
    '[' || coalesce(string_agg(
      to_jsonb(
        construct.sample_original_path_id::text || '/' ||
        construct.instrument_v2_id::text
      )::text,
      ',' ORDER BY
        construct.sample_original_path_id::text COLLATE "C",
        construct.instrument_v2_id::text COLLATE "C"
    ), '') || ']',
    'UTF8'
  ), 'sha256'), 'hex')
  INTO v_current_association_sha256
  FROM (
    SELECT DISTINCT sample_original_path_id, instrument_v2_id
    FROM public.sample_path_constructs
    WHERE sample_original_path_id IS NOT NULL
      AND instrument_v2_id IS NOT NULL
  ) construct;
  IF v_current_association_sha256
    <> v_basis.projection_association_identity_sha256
  THEN
    RAISE EXCEPTION 'current source-to-Instrument-V2 associations drifted';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs
    WHERE status IN ('queued', 'running')
  ) OR EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases
    WHERE released_at IS NULL AND lease_expires_at > now()
  ) OR EXISTS (
    SELECT 1 FROM public.sip_fleet_executor_leases
    WHERE lease_expires_at > now()
  ) OR EXISTS (
    SELECT 1 FROM public.sip_pipeline_runs
    WHERE status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'active completion-ledger work blocks apply';
  END IF;

  CREATE TEMP TABLE completion_materialization_inventory_input
  ON COMMIT DROP AS
  SELECT
    item."normalizedPath"::text AS normalized_path,
    item."sampleOriginalPathId"::uuid AS sample_original_path_id,
    item."denominatorCohort"::text AS denominator_cohort
  FROM jsonb_to_recordset(p_inventory_items) AS item(
    "normalizedPath" text,
    "sampleOriginalPathId" uuid,
    "denominatorCohort" text
  );
  IF EXISTS (
    SELECT 1 FROM completion_materialization_inventory_input
    WHERE normalized_path IS NULL OR normalized_path = ''
      OR sample_original_path_id IS NULL
      OR denominator_cohort NOT IN (
        'provider_manifest', 'generated_lineage', 'reviewed_exception'
      )
  ) OR EXISTS (
    SELECT 1 FROM completion_materialization_inventory_input
    GROUP BY normalized_path HAVING count(*) <> 1
  ) OR EXISTS (
    SELECT 1 FROM completion_materialization_inventory_input
    GROUP BY sample_original_path_id HAVING count(*) <> 1
  ) THEN
    RAISE EXCEPTION 'inventory union contains invalid or duplicate identities';
  END IF;
  SELECT
    count(*),
    count(*) FILTER (WHERE denominator_cohort = 'provider_manifest'),
    count(*) FILTER (WHERE denominator_cohort = 'generated_lineage'),
    count(*) FILTER (WHERE denominator_cohort = 'reviewed_exception')
  INTO v_item_count, v_provider_count, v_generated_count, v_exception_count
  FROM completion_materialization_inventory_input;
  IF v_item_count <> v_rehearsal.inventory_count
    OR v_item_count <> v_rehearsal.database_count
    OR v_provider_count <> v_rehearsal.provider_manifest_count
    OR v_generated_count <> v_rehearsal.generated_lineage_count
    OR v_exception_count <> v_rehearsal.exception_count
    OR EXISTS (
      SELECT 1 FROM completion_materialization_inventory_input input
      LEFT JOIN public.samples_original_paths source
        ON source.id = input.sample_original_path_id
      WHERE source.id IS NULL
    )
  THEN
    RAISE EXCEPTION 'inventory denominator union drifted';
  END IF;

  CREATE TEMP TABLE completion_closure_policy ON COMMIT DROP AS
  SELECT
    value->>'policyKey' AS policy_key,
    value AS decision
  FROM jsonb_array_elements(p_closure_evidence->'policies') value;

  CREATE TEMP TABLE completion_closure_source ON COMMIT DROP AS
  SELECT
    (source.value->>'sampleOriginalPathId')::uuid AS sample_original_path_id,
    nullif(source.value->>'providerScopeKey', '') AS provider_scope_key,
    coalesce(source.value->'override', policy.decision) AS decision
  FROM jsonb_array_elements(p_closure_evidence->'sources') source(value)
  JOIN completion_closure_policy policy
    ON policy.policy_key = source.value->>'policyKey';
  IF (SELECT count(*) FROM completion_closure_source) <> v_item_count
    OR EXISTS (
      SELECT 1 FROM completion_closure_source
      GROUP BY sample_original_path_id HAVING count(*) <> 1
    )
    OR EXISTS (
      SELECT 1 FROM completion_materialization_inventory_input input
      FULL JOIN completion_closure_source closure USING (sample_original_path_id)
      WHERE input.sample_original_path_id IS NULL
        OR closure.sample_original_path_id IS NULL
    )
  THEN
    RAISE EXCEPTION 'closure package source universe drifted';
  END IF;

  CREATE TEMP TABLE completion_projection_membership_input
  ON COMMIT DROP AS
  SELECT
    projection.value->>'providerScopeKey' AS provider_scope_key,
    projection.value->>'projectionKey' AS projection_key,
    (projection.value->>'currentInstrumentV2Id')::uuid
      AS current_instrument_v2_id,
    source_id::uuid AS sample_original_path_id
  FROM jsonb_array_elements(p_projection_package->'projections')
    projection(value)
  CROSS JOIN LATERAL jsonb_array_elements_text(
    projection.value->'sourceIds'
  ) source_id;

  CREATE TEMP TABLE completion_projection_deferred_input
  ON COMMIT DROP AS
  SELECT value::uuid AS sample_original_path_id
  FROM jsonb_array_elements_text(
    p_projection_package->'projectionDeferredSourceIds'
  ) value;

  CREATE TEMP TABLE completion_projection_terminal_input
  ON COMMIT DROP AS
  SELECT value::uuid AS sample_original_path_id
  FROM jsonb_array_elements_text(
    p_projection_package->'terminalSourceIds'
  ) value;

  CREATE TEMP TABLE completion_terminal_association_input
  ON COMMIT DROP AS
  SELECT
    value->>'providerScopeKey' AS provider_scope_key,
    (value->>'sampleOriginalPathId')::uuid AS sample_original_path_id,
    (value->>'instrumentV2Id')::uuid AS current_instrument_v2_id
  FROM jsonb_array_elements(
    p_projection_package->'terminalAssociations'
  ) value;

  IF EXISTS (
    SELECT 1 FROM completion_projection_membership_input
    GROUP BY sample_original_path_id, current_instrument_v2_id
    HAVING count(*) <> 1
  ) OR EXISTS (
    SELECT 1 FROM completion_projection_deferred_input
    GROUP BY sample_original_path_id HAVING count(*) <> 1
  ) OR EXISTS (
    SELECT 1 FROM completion_projection_terminal_input
    GROUP BY sample_original_path_id HAVING count(*) <> 1
  ) OR EXISTS (
    SELECT 1 FROM completion_terminal_association_input
    GROUP BY sample_original_path_id, current_instrument_v2_id
    HAVING count(*) <> 1
  ) OR EXISTS (
    SELECT 1 FROM completion_projection_membership_input member
    JOIN completion_projection_deferred_input deferred USING (sample_original_path_id)
  ) OR EXISTS (
    SELECT 1 FROM completion_projection_membership_input member
    JOIN completion_projection_terminal_input terminal USING (sample_original_path_id)
  ) OR EXISTS (
    SELECT 1 FROM completion_projection_deferred_input deferred
    JOIN completion_projection_terminal_input terminal USING (sample_original_path_id)
  ) OR (
    SELECT count(DISTINCT sample_original_path_id)
    FROM completion_projection_membership_input
  ) + (SELECT count(*) FROM completion_projection_deferred_input)
    + (SELECT count(*) FROM completion_projection_terminal_input)
      <> v_item_count
  OR (p_projection_package#>>'{counts,sourceCount}')::bigint <> v_item_count
  OR (p_projection_package#>>'{counts,associatedSourceCount}')::bigint <> (
    SELECT count(DISTINCT sample_original_path_id)
    FROM completion_projection_membership_input
  )
  OR (p_projection_package#>>'{counts,intendedProjectionCount}')::bigint <> (
    SELECT count(DISTINCT (provider_scope_key, projection_key))
    FROM completion_projection_membership_input
  )
  OR (p_projection_package#>>'{counts,intendedMembershipCount}')::bigint <> (
    SELECT count(*) FROM completion_projection_membership_input
  )
  OR (p_projection_package#>>'{counts,terminalAssociationCount}')::bigint <> (
    SELECT count(*) FROM completion_terminal_association_input
  )
  OR (p_projection_package#>>'{counts,projectionDeferredSourceCount}')::bigint
    <> (SELECT count(*) FROM completion_projection_deferred_input)
  OR (p_projection_package#>>'{counts,terminalSourceCount}')::bigint
    <> (SELECT count(*) FROM completion_projection_terminal_input)
  OR v_basis.projection_deferred_source_count
    <> (SELECT count(*) FROM completion_projection_deferred_input)
  THEN
    RAISE EXCEPTION 'projection assignment partition drifted';
  END IF;
  IF EXISTS (
    SELECT 1 FROM completion_projection_membership_input member
    JOIN completion_closure_source source USING (sample_original_path_id)
    WHERE member.provider_scope_key <> source.provider_scope_key
      OR source.decision#>>'{admission,status}' <> 'in_scope'
      OR source.decision#>>'{admission,disposition}' <> 'open'
      OR source.decision->'intendedProjectionKeys' <> '["instruments_v2"]'::jsonb
  ) OR EXISTS (
    SELECT 1 FROM completion_projection_deferred_input deferred
    JOIN completion_closure_source source USING (sample_original_path_id)
    WHERE source.decision#>>'{admission,status}' <> 'in_scope'
      OR source.decision#>>'{admission,disposition}' <> 'open'
      OR source.decision->'intendedProjectionKeys' <> '["instruments_v2"]'::jsonb
  ) OR EXISTS (
    SELECT 1 FROM completion_projection_terminal_input terminal
    JOIN completion_closure_source source USING (sample_original_path_id)
    WHERE source.decision#>>'{admission,status}' = 'in_scope'
      AND source.decision#>>'{admission,disposition}' = 'open'
  ) OR EXISTS (
    SELECT 1 FROM completion_terminal_association_input association
    JOIN completion_closure_source source USING (sample_original_path_id)
    LEFT JOIN completion_projection_terminal_input terminal
      USING (sample_original_path_id)
    WHERE terminal.sample_original_path_id IS NULL
      OR association.provider_scope_key IS DISTINCT FROM source.provider_scope_key
  ) THEN
    RAISE EXCEPTION 'projection package changes closure decisions';
  END IF;

  -- The package is the complete intended projection/membership set for this
  -- global closure universe. Check the reverse direction before writing any
  -- source decision or freezing any registry so stale extras cannot be
  -- silently preserved, terminalized, or hidden in the frozen denominator.
  IF EXISTS (
    SELECT 1
    FROM public.sip_completion_projection actual
    WHERE actual.is_intended
      AND NOT EXISTS (
        SELECT 1
        FROM completion_projection_membership_input expected
        WHERE expected.provider_scope_key = actual.provider_scope_key
          AND expected.projection_key = actual.projection_key
      )
  ) THEN
    RAISE EXCEPTION
      'existing intended projection is absent from successor package';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM completion_projection_terminal_input terminal
    JOIN public.sip_completion_projection_membership actual
      USING (sample_original_path_id)
    WHERE actual.is_intended
      OR actual.membership_decision = 'active'
  ) THEN
    RAISE EXCEPTION
      'terminal source conflicts with existing intended or active membership';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.sip_completion_projection_membership actual
    JOIN public.sip_completion_projection projection
      ON projection.id = actual.completion_projection_id
    WHERE actual.membership_decision = 'active'
      AND NOT EXISTS (
        SELECT 1
        FROM completion_projection_membership_input expected
        WHERE expected.provider_scope_key = projection.provider_scope_key
          AND expected.projection_key = projection.projection_key
          AND expected.sample_original_path_id =
            actual.sample_original_path_id
      )
  ) THEN
    RAISE EXCEPTION
      'existing active membership is absent from successor package';
  END IF;

  SELECT count(*) INTO v_source_count_before
  FROM public.sip_completion_source source
  JOIN completion_closure_source input USING (sample_original_path_id);
  INSERT INTO public.sip_completion_source (
    sample_original_path_id,
    canonical_provider_key,
    ownership_status,
    ownership_resolution_version,
    ownership_evidence,
    rights_status,
    rights_resolution_version,
    rights_provenance_ref,
    rights_evidence,
    admission_status,
    global_disposition,
    decision_reason,
    decision_evidence,
    decided_by,
    decided_at,
    projection_assignment_status,
    projection_assignment_evidence,
    projection_assignment_decided_by,
    projection_assignment_decided_at
  )
  SELECT
    source.sample_original_path_id,
    source.provider_scope_key,
    CASE WHEN source.provider_scope_key IS NULL
      THEN 'unresolved' ELSE 'resolved' END,
    source.decision#>>'{ownership,resolutionVersion}',
    source.decision#>'{ownership,evidence}',
    source.decision#>>'{rights,status}',
    source.decision#>>'{rights,resolutionVersion}',
    source.decision#>>'{rights,provenanceRef}',
    source.decision#>'{rights,evidence}',
    source.decision#>>'{admission,status}',
    source.decision#>>'{admission,disposition}',
    'issue #2430 immutable successor closure decision',
    source.decision#>'{admission,evidence}',
    source.decision#>>'{decision,decidedBy}',
    (source.decision#>>'{decision,decidedAt}')::timestamptz,
    CASE
      WHEN member.sample_original_path_id IS NOT NULL THEN 'assigned'
      WHEN deferred.sample_original_path_id IS NOT NULL THEN 'deferred'
      ELSE 'not_applicable'
    END,
    jsonb_build_object(
      'closureFileSha256', v_basis.closure_file_sha256,
      'projectionPackageFileSha256', v_basis.projection_package_file_sha256,
      'authorizationRef', p_authorization_ref
    ),
    btrim(p_applied_by),
    now()
  FROM completion_closure_source source
  LEFT JOIN (
    SELECT DISTINCT sample_original_path_id
    FROM completion_projection_membership_input
  ) member USING (sample_original_path_id)
  LEFT JOIN completion_projection_deferred_input deferred
    USING (sample_original_path_id)
  ON CONFLICT (sample_original_path_id) DO UPDATE SET
    canonical_provider_key = EXCLUDED.canonical_provider_key,
    ownership_status = EXCLUDED.ownership_status,
    ownership_resolution_version = EXCLUDED.ownership_resolution_version,
    ownership_evidence = EXCLUDED.ownership_evidence,
    rights_status = EXCLUDED.rights_status,
    rights_resolution_version = EXCLUDED.rights_resolution_version,
    rights_provenance_ref = EXCLUDED.rights_provenance_ref,
    rights_evidence = EXCLUDED.rights_evidence,
    admission_status = EXCLUDED.admission_status,
    global_disposition = EXCLUDED.global_disposition,
    decision_reason = EXCLUDED.decision_reason,
    decision_evidence = EXCLUDED.decision_evidence,
    decided_by = EXCLUDED.decided_by,
    decided_at = EXCLUDED.decided_at,
    projection_assignment_status = EXCLUDED.projection_assignment_status,
    projection_assignment_evidence = EXCLUDED.projection_assignment_evidence,
    projection_assignment_decided_by =
      EXCLUDED.projection_assignment_decided_by,
    projection_assignment_decided_at =
      EXCLUDED.projection_assignment_decided_at
  WHERE public.sip_completion_source.projection_assignment_status =
      'unresolved'
    AND (
      (
        public.sip_completion_source.ownership_status = 'unresolved'
        AND public.sip_completion_source.canonical_provider_key IS NULL
        AND public.sip_completion_source.canonical_contributor_id IS NULL
        AND public.sip_completion_source.ownership_resolution_version IS NULL
        AND public.sip_completion_source.ownership_evidence = '{}'::jsonb
        AND public.sip_completion_source.rights_status IN (
          'legacy_allowed_unverified', 'legacy_blocked_unverified'
        )
        AND public.sip_completion_source.rights_resolution_version =
          'legacy-licensing-flag-v1'
        AND public.sip_completion_source.rights_provenance_ref IS NULL
        AND public.sip_completion_source.rights_evidence = jsonb_build_object(
          'source', 'samples_original_paths.licensing_secured',
          'legacyValue', public.sip_completion_source.rights_status =
            'legacy_allowed_unverified'
        )
        AND public.sip_completion_source.admission_status = 'unknown'
        AND public.sip_completion_source.global_disposition = 'open'
        AND public.sip_completion_source.canonical_sample_original_path_id
          IS NULL
        AND public.sip_completion_source.decision_reason IS NULL
        AND public.sip_completion_source.decision_evidence = '{}'::jsonb
        AND public.sip_completion_source.decided_by IS NULL
        AND public.sip_completion_source.decided_at IS NULL
      )
      OR (
        public.sip_completion_source.canonical_provider_key
          IS NOT DISTINCT FROM EXCLUDED.canonical_provider_key
        AND public.sip_completion_source.ownership_status =
          EXCLUDED.ownership_status
        AND public.sip_completion_source.ownership_resolution_version
          IS NOT DISTINCT FROM EXCLUDED.ownership_resolution_version
        AND public.sip_completion_source.ownership_evidence =
          EXCLUDED.ownership_evidence
        AND public.sip_completion_source.rights_status = EXCLUDED.rights_status
        AND public.sip_completion_source.rights_resolution_version
          IS NOT DISTINCT FROM EXCLUDED.rights_resolution_version
        AND public.sip_completion_source.rights_provenance_ref
          IS NOT DISTINCT FROM EXCLUDED.rights_provenance_ref
        AND public.sip_completion_source.rights_evidence =
          EXCLUDED.rights_evidence
        AND public.sip_completion_source.admission_status =
          EXCLUDED.admission_status
        AND public.sip_completion_source.global_disposition =
          EXCLUDED.global_disposition
        AND public.sip_completion_source.decision_reason
          IS NOT DISTINCT FROM EXCLUDED.decision_reason
        AND public.sip_completion_source.decision_evidence =
          EXCLUDED.decision_evidence
        AND public.sip_completion_source.decided_by
          IS NOT DISTINCT FROM EXCLUDED.decided_by
        AND public.sip_completion_source.decided_at
          IS NOT DISTINCT FROM EXCLUDED.decided_at
      )
    );

  IF EXISTS (
    SELECT 1
    FROM completion_closure_source expected
    JOIN public.sip_completion_source actual USING (sample_original_path_id)
    LEFT JOIN (
      SELECT DISTINCT sample_original_path_id
      FROM completion_projection_membership_input
    ) member USING (sample_original_path_id)
    LEFT JOIN completion_projection_deferred_input deferred
      USING (sample_original_path_id)
    WHERE actual.canonical_provider_key IS DISTINCT FROM expected.provider_scope_key
      OR actual.ownership_status <> CASE
        WHEN expected.provider_scope_key IS NULL
          THEN 'unresolved' ELSE 'resolved' END
      OR actual.ownership_resolution_version
        IS DISTINCT FROM expected.decision#>>'{ownership,resolutionVersion}'
      OR actual.ownership_evidence
        IS DISTINCT FROM expected.decision#>'{ownership,evidence}'
      OR actual.rights_status <> expected.decision#>>'{rights,status}'
      OR actual.rights_resolution_version
        IS DISTINCT FROM expected.decision#>>'{rights,resolutionVersion}'
      OR actual.rights_provenance_ref
        IS DISTINCT FROM expected.decision#>>'{rights,provenanceRef}'
      OR actual.rights_evidence
        IS DISTINCT FROM expected.decision#>'{rights,evidence}'
      OR actual.admission_status <> expected.decision#>>'{admission,status}'
      OR actual.global_disposition
        <> expected.decision#>>'{admission,disposition}'
      OR actual.projection_assignment_status <> CASE
        WHEN member.sample_original_path_id IS NOT NULL THEN 'assigned'
        WHEN deferred.sample_original_path_id IS NOT NULL THEN 'deferred'
        ELSE 'not_applicable'
      END
  ) THEN
    RAISE EXCEPTION 'existing completion source conflicts with successor package';
  END IF;
  SELECT count(*) INTO v_source_count_after
  FROM public.sip_completion_source source
  JOIN completion_closure_source input USING (sample_original_path_id);

  INSERT INTO public.sip_completion_projection (
    provider_scope_key,
    projection_key,
    is_intended,
    projection_decision,
    current_instrument_v2_id,
    identity_evidence,
    decision_reason,
    decision_evidence,
    decided_by,
    decided_at
  )
  SELECT DISTINCT
    provider_scope_key,
    projection_key,
    true,
    'active',
    current_instrument_v2_id,
    jsonb_build_object(
      'source', 'current sample_path_constructs association',
      'associationIdentitySha256',
        v_basis.projection_association_identity_sha256
    ),
    'issue #2430 option A preserves exact current Instrument V2 association',
    jsonb_build_object('issueComment', 5227746981),
    btrim(p_applied_by),
    now()
  FROM completion_projection_membership_input
  ON CONFLICT (provider_scope_key, projection_key) DO NOTHING;
  IF EXISTS (
    SELECT 1
    FROM (
      SELECT DISTINCT provider_scope_key, projection_key, current_instrument_v2_id
      FROM completion_projection_membership_input
    ) expected
    JOIN public.sip_completion_projection actual USING (
      provider_scope_key, projection_key
    )
    WHERE NOT actual.is_intended
      OR actual.projection_decision <> 'active'
      OR actual.current_instrument_v2_id
        IS DISTINCT FROM expected.current_instrument_v2_id
  ) THEN
    RAISE EXCEPTION 'existing completion projection conflicts with successor package';
  END IF;

  INSERT INTO public.sip_completion_projection_membership (
    completion_projection_id,
    sample_original_path_id,
    is_intended,
    membership_decision,
    decision_reason,
    decision_evidence,
    decided_by,
    decided_at
  )
  SELECT
    projection.id,
    member.sample_original_path_id,
    true,
    'active',
    'issue #2430 option A preserves exact current Instrument V2 association',
    jsonb_build_object('issueComment', 5227746981),
    btrim(p_applied_by),
    now()
  FROM completion_projection_membership_input member
  JOIN public.sip_completion_projection projection USING (
    provider_scope_key, projection_key
  )
  ON CONFLICT (completion_projection_id, sample_original_path_id) DO NOTHING;
  IF EXISTS (
    SELECT 1
    FROM completion_projection_membership_input expected
    JOIN public.sip_completion_projection projection USING (
      provider_scope_key, projection_key
    )
    JOIN public.sip_completion_projection_membership actual
      ON actual.completion_projection_id = projection.id
      AND actual.sample_original_path_id = expected.sample_original_path_id
    WHERE NOT actual.is_intended
      OR actual.membership_decision <> 'active'
  ) THEN
    RAISE EXCEPTION 'existing projection membership conflicts with successor package';
  END IF;

  FOR v_provider IN
    SELECT DISTINCT
      canonical_provider_key COLLATE "C" AS provider_scope_key
    FROM public.sip_completion_source source
    JOIN completion_closure_source input USING (sample_original_path_id)
    WHERE canonical_provider_key IS NOT NULL
    ORDER BY provider_scope_key
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.sip_completion_projection_registry registry
      WHERE registry.provider_scope_key = v_provider.provider_scope_key
        AND registry.status = 'frozen'
        AND registry.source_count = (
          SELECT count(*) FROM public.sip_completion_source source
          WHERE source.canonical_provider_key = v_provider.provider_scope_key
        )
        AND registry.intended_projection_count = (
          SELECT count(*) FROM public.sip_completion_projection projection
          WHERE projection.provider_scope_key = v_provider.provider_scope_key
            AND projection.is_intended
        )
        AND registry.intended_membership_count = (
          SELECT count(*)
          FROM public.sip_completion_projection_membership membership
          JOIN public.sip_completion_projection projection
            ON projection.id = membership.completion_projection_id
          WHERE projection.provider_scope_key = v_provider.provider_scope_key
            AND membership.is_intended
        )
    ) THEN
      SELECT id INTO v_registry_id
      FROM public.sip_completion_projection_registry
      WHERE provider_scope_key = v_provider.provider_scope_key
        AND status = 'frozen'
      FOR UPDATE;
      IF FOUND THEN
        PERFORM public.sip_supersede_completion_projection_registry_v1(
          v_registry_id
        );
      END IF;
      INSERT INTO public.sip_completion_projection_registry (
        provider_scope_key,
        version,
        origin_main_sha,
        production_observed_at,
        normalization_version,
        evidence,
        created_by
      ) VALUES (
        v_provider.provider_scope_key,
        coalesce((
          SELECT max(version) + 1
          FROM public.sip_completion_projection_registry
          WHERE provider_scope_key = v_provider.provider_scope_key
        ), 1),
        v_rehearsal.origin_main_sha,
        v_rehearsal.production_observed_at,
        'sip-completion-successor-projection-package-v1',
        jsonb_build_object(
          'denominatorSource', 'reviewed-successor-projection-package',
          'closureFileSha256', v_basis.closure_file_sha256,
          'projectionPackageFileSha256',
            v_basis.projection_package_file_sha256
        ),
        btrim(p_applied_by)
      ) RETURNING id INTO v_registry_id;
      PERFORM public.sip_freeze_completion_projection_registry_v1(
        v_registry_id,
        (SELECT count(*) FROM public.sip_completion_source source
          WHERE source.canonical_provider_key = v_provider.provider_scope_key),
        (SELECT count(*) FROM public.sip_completion_projection projection
          WHERE projection.provider_scope_key = v_provider.provider_scope_key
            AND projection.is_intended),
        (SELECT count(*)
          FROM public.sip_completion_projection_membership membership
          JOIN public.sip_completion_projection projection
            ON projection.id = membership.completion_projection_id
          WHERE projection.provider_scope_key = v_provider.provider_scope_key
            AND membership.is_intended),
        public.sip_completion_identity_digest_v1(ARRAY(
          SELECT source.sample_original_path_id::text
          FROM public.sip_completion_source source
          WHERE source.canonical_provider_key = v_provider.provider_scope_key
          ORDER BY source.sample_original_path_id::text
        )),
        public.sip_completion_identity_digest_v1(ARRAY(
          SELECT projection.projection_key
          FROM public.sip_completion_projection projection
          WHERE projection.provider_scope_key = v_provider.provider_scope_key
            AND projection.is_intended
          ORDER BY projection.projection_key COLLATE "C"
        )),
        public.sip_completion_identity_digest_v1(ARRAY(
          SELECT projection.projection_key || '/' ||
            membership.sample_original_path_id
          FROM public.sip_completion_projection_membership membership
          JOIN public.sip_completion_projection projection
            ON projection.id = membership.completion_projection_id
          WHERE projection.provider_scope_key = v_provider.provider_scope_key
            AND membership.is_intended
          ORDER BY projection.projection_key COLLATE "C",
            membership.sample_original_path_id
        )),
        btrim(p_applied_by)
      );
    END IF;
  END LOOP;

  SELECT count(*) INTO v_open_source_count
  FROM public.sip_completion_source source
  JOIN completion_closure_source input USING (sample_original_path_id)
  WHERE (
      source.ownership_status <> 'resolved'
      AND NOT (
        source.canonical_provider_key IS NULL
        AND source.global_disposition IN (
          'retired', 'deferred', 'ignored', 'rights_held', 'out_of_scope'
        )
      )
    )
    OR (
      source.rights_status NOT IN ('verified_allowed', 'verified_restricted')
      AND source.global_disposition NOT IN ('rights_held', 'out_of_scope')
    )
    OR source.admission_status IN ('unknown', 'conflicting')
    OR source.global_disposition = 'conflicting'
    OR source.projection_assignment_status = 'unresolved';
  SELECT count(*) INTO v_open_projection_count
  FROM public.sip_completion_projection projection
  WHERE projection.is_intended
    AND projection.projection_decision IN ('undecided', 'conflicting');
  SELECT count(*) INTO v_open_membership_count
  FROM public.sip_completion_projection_membership membership
  WHERE membership.is_intended
    AND membership.membership_decision IN ('undecided', 'conflicting');
  SELECT count(*) INTO v_missing_registry_count
  FROM (
    SELECT DISTINCT source.canonical_provider_key
    FROM public.sip_completion_source source
    JOIN completion_closure_source input USING (sample_original_path_id)
    WHERE source.canonical_provider_key IS NOT NULL
  ) provider
  WHERE NOT EXISTS (
    SELECT 1 FROM public.sip_completion_projection_registry registry
    WHERE registry.provider_scope_key = provider.canonical_provider_key
      AND registry.status = 'frozen'
  );
  SELECT count(*) INTO v_uncovered_source_count
  FROM public.sip_completion_source source
  JOIN completion_closure_source input USING (sample_original_path_id)
  WHERE source.global_disposition = 'open'
    AND source.projection_assignment_status <> 'deferred'
    AND NOT EXISTS (
      SELECT 1
      FROM public.sip_completion_projection_membership membership
      JOIN public.sip_completion_projection projection
        ON projection.id = membership.completion_projection_id
      WHERE membership.sample_original_path_id = source.sample_original_path_id
        AND membership.is_intended
        AND projection.is_intended
    );
  IF v_open_source_count <> 0 OR v_open_projection_count <> 0
    OR v_open_membership_count <> 0 OR v_missing_registry_count <> 0
    OR v_uncovered_source_count <> 0
  THEN
    RAISE EXCEPTION
      'completion closure decisions missing: source %, projection %, membership %, registry %, uncovered %',
      v_open_source_count, v_open_projection_count, v_open_membership_count,
      v_missing_registry_count, v_uncovered_source_count;
  END IF;

  UPDATE public.sip_completion_materialization_rehearsal
  SET lifecycle_status = 'applying'
  WHERE id = v_rehearsal.id;

  INSERT INTO public.sip_completion_inventory_receipt (
    id, inventory_location, inventory_version, normalization_version,
    origin_main_sha, production_observed_at,
    inventory_count, database_count, matched_count,
    inventory_only_count, database_only_count,
    inventory_sorted_path_sha256, database_sorted_path_sha256,
    result, evidence, created_by,
    provider_manifest_count, generated_lineage_count,
    reviewed_exception_count, provider_manifest_raw_lf_sha256,
    provider_manifest_normalized_lf_sha256,
    inventory_identity_digest_version
  ) VALUES (
    v_receipt_id, p_inventory_location, p_inventory_version,
    p_normalization_version, v_rehearsal.origin_main_sha, now(),
    v_item_count, v_item_count, v_item_count, 0, 0,
    p_inventory_identity_sha256, p_database_identity_sha256,
    'matched',
    jsonb_build_object(
      'rehearsalId', v_rehearsal.id,
      'manifestSha256', v_rehearsal.manifest_sha256,
      'closureFileSha256', v_basis.closure_file_sha256,
      'projectionPackageFileSha256',
        v_basis.projection_package_file_sha256,
      'globalTonalityReady', false
    ),
    btrim(p_applied_by),
    v_provider_count, v_generated_count, v_exception_count,
    p_provider_manifest_raw_lf_sha256,
    p_provider_manifest_normalized_lf_sha256,
    'sip_completion_identity_digest_v1'
  );
  INSERT INTO public.sip_completion_inventory_item (
    receipt_id, normalized_path, sample_original_path_id,
    parity_status, denominator_cohort
  )
  SELECT v_receipt_id, normalized_path, sample_original_path_id,
    'matched', denominator_cohort
  FROM completion_materialization_inventory_input
  ORDER BY normalized_path COLLATE "C";

  INSERT INTO public.sip_completion_materialization_application (
    rehearsal_id, inventory_receipt_id, authorization_ref, origin_main_sha,
    manifest_sha256, rehearsal_snapshot_sha256, rehearsal_plan_sha256,
    rehearsal_batch_root_sha256, applied_source_count,
    idempotent_source_count, inventory_item_count, applied_by
  ) VALUES (
    v_rehearsal.id, v_receipt_id, btrim(p_authorization_ref),
    v_rehearsal.origin_main_sha, v_rehearsal.manifest_sha256,
    v_rehearsal.snapshot_sha256, v_rehearsal.plan_sha256,
    v_rehearsal.batch_root_sha256,
    v_source_count_after - v_source_count_before,
    v_source_count_before, v_item_count, btrim(p_applied_by)
  ) RETURNING id INTO v_application_id;
  UPDATE public.sip_completion_materialization_rehearsal
  SET lifecycle_status = 'completed'
  WHERE id = v_rehearsal.id;

  RETURN jsonb_build_object(
    'applicationId', v_application_id,
    'rehearsalId', v_rehearsal.id,
    'lifecycleStatus', 'completed',
    'inventoryReceiptId', v_receipt_id,
    'status', 'HOLD',
    'readinessEvaluated', false,
    'globalTonalityReady', false,
    'appliedSourceCount', v_source_count_after - v_source_count_before,
    'idempotentSourceCount', v_source_count_before,
    'inventoryItemCount', v_item_count,
    'projectionDeferredSourceCount',
      v_basis.projection_deferred_source_count
  );
END;
$$;


ALTER FUNCTION "public"."sip_apply_completion_materialization_v2"("p_rehearsal_id" "uuid", "p_expected_origin_main_sha" "text", "p_expected_manifest_sha256" "text", "p_expected_snapshot_sha256" "text", "p_expected_plan_sha256" "text", "p_expected_batch_root_sha256" "text", "p_authorization_ref" "text", "p_inventory_location" "text", "p_inventory_version" "text", "p_normalization_version" "text", "p_inventory_identity_sha256" "text", "p_database_identity_sha256" "text", "p_provider_manifest_raw_lf_sha256" "text", "p_provider_manifest_normalized_lf_sha256" "text", "p_inventory_items" "jsonb", "p_closure_evidence" "jsonb", "p_projection_package" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_apply_construct_address_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_expected_count integer;
  v_matching_count integer;
  v_updated_count integer;
  v_refreshed_count integer;
  v_instrument_ids uuid[];
  v_existing_manifest jsonb;
  v_existing_result jsonb;
  v_result jsonb;
  v_locked_lease_id uuid;
BEGIN
  IF btrim(coalesce(p_contributor_slug, '')) = ''
     OR p_lease_id IS NULL
     OR p_lease_token IS NULL
     OR p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR btrim(coalesce(p_applied_by, '')) = '' THEN
    RAISE EXCEPTION 'construct_address_reconciliation_identity_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_manifest) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest) < 1
     OR jsonb_array_length(p_manifest) > 250 THEN
    RAISE EXCEPTION 'construct_address_reconciliation_manifest_invalid'
      USING ERRCODE = '22023';
  END IF;

  v_expected_count := jsonb_array_length(p_manifest);
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest) entry
    WHERE jsonb_typeof(entry) <> 'object'
       OR btrim(coalesce(entry->>'instrumentV2Id', '')) = ''
       OR btrim(coalesce(entry->>'constructId', '')) = ''
       OR btrim(coalesce(entry->>'sampleOriginalPathId', '')) = ''
       OR btrim(coalesce(entry->>'sourceS3Path', '')) = ''
       OR btrim(coalesce(entry->>'sourceFileName', '')) = ''
       OR coalesce(entry->>'rootMidi', '') !~ '^(?:[1-9]|[1-9][0-9]|1[01][0-9]|12[0-7])$'
       OR coalesce(entry->>'expectedPitchContent', '') !~ '^0(?:_[pm][1-9][0-9]*)*$'
       OR btrim(coalesce(entry->>'expectedMicPosition', '')) = ''
       OR coalesce(entry->>'expectedPlaybackType', '') NOT IN ('oneShot','looped','legato_transition')
       OR (
         NOT (entry ? 'expectedVelocity')
         OR jsonb_typeof(entry->'expectedVelocity') <> 'number'
         OR (entry->>'expectedVelocity')::numeric < 0
         OR (entry->>'expectedVelocity')::numeric > 2147483647
         OR (entry->>'expectedVelocity')::numeric
            <> trunc((entry->>'expectedVelocity')::numeric)
       )
       OR (
         NOT (entry ? 'expectedRoundRobin')
         OR jsonb_typeof(entry->'expectedRoundRobin') <> 'number'
         OR (entry->>'expectedRoundRobin')::numeric < 0
         OR (entry->>'expectedRoundRobin')::numeric > 2147483647
         OR (entry->>'expectedRoundRobin')::numeric
            <> trunc((entry->>'expectedRoundRobin')::numeric)
       )
       OR (
         entry ? 'targetVelocity'
         AND (
           NOT (entry ? 'expectedVelocity')
           OR jsonb_typeof(entry->'targetVelocity') <> 'number'
           OR (entry->>'targetVelocity')::numeric < 0
           OR (entry->>'targetVelocity')::numeric > 2147483647
           OR (entry->>'targetVelocity')::numeric
              <> trunc((entry->>'targetVelocity')::numeric)
         )
       )
  ) THEN
    RAISE EXCEPTION 'construct_address_reconciliation_manifest_entry_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest) entry
    GROUP BY entry->>'constructId'
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'construct_address_reconciliation_duplicate_construct'
      USING ERRCODE = '22023';
  END IF;
  SELECT array_agg(
           DISTINCT (entry->>'instrumentV2Id')::uuid
           ORDER BY (entry->>'instrumentV2Id')::uuid
         )
    INTO v_instrument_ids
  FROM jsonb_array_elements(p_manifest) entry;

  -- This is the same provider-scoped serialization key used by fleet admission.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  SELECT lease.id INTO v_locked_lease_id
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
    AND lease.provider_slug = btrim(p_contributor_slug)
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF v_locked_lease_id IS NULL THEN
    RAISE EXCEPTION 'construct_address_reconciliation_lease_invalid'
      USING ERRCODE = '55000';
  END IF;

  SELECT receipt.manifest, receipt.result
    INTO v_existing_manifest, v_existing_result
  FROM public.sip_construct_address_reconciliation_receipts receipt
  WHERE receipt.provider_slug = btrim(p_contributor_slug)
    AND receipt.manifest_hash = p_manifest_hash;
  IF v_existing_result IS NOT NULL THEN
    IF v_existing_manifest IS DISTINCT FROM p_manifest THEN
      RAISE EXCEPTION 'construct_address_reconciliation_manifest_hash_collision'
        USING ERRCODE = '55000';
    END IF;
    RETURN v_existing_result || jsonb_build_object('idempotent', true);
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.sip_fleet_runs run
    WHERE run.provider_slug = btrim(p_contributor_slug)
      AND run.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'construct_address_reconciliation_active_run'
      USING ERRCODE = '55000';
  END IF;

  -- Resolve and lock every exact row before checking any mutable projection.
  PERFORM construct.id
  FROM public.sample_path_constructs construct
  WHERE construct.instrument_v2_id = ANY(v_instrument_ids)
     OR construct.id IN (
       SELECT (entry->>'constructId')::uuid
       FROM jsonb_array_elements(p_manifest) entry
     )
  FOR UPDATE;
  PERFORM instrument.id
  FROM public.instruments_v2 instrument
  WHERE instrument.id IN (
    SELECT (entry->>'instrumentV2Id')::uuid
    FROM jsonb_array_elements(p_manifest) entry
  )
  FOR UPDATE;
  PERFORM source.id
  FROM public.samples_original_paths source
  WHERE source.id IN (
    SELECT (entry->>'sampleOriginalPathId')::uuid
    FROM jsonb_array_elements(p_manifest) entry
  )
  FOR SHARE;

  SELECT count(*)
    INTO v_matching_count
  FROM jsonb_array_elements(p_manifest) entry
  JOIN public.sample_path_constructs construct
    ON construct.id = (entry->>'constructId')::uuid
   AND construct.instrument_v2_id = (entry->>'instrumentV2Id')::uuid
   AND construct.sample_original_path_id =
       (entry->>'sampleOriginalPathId')::uuid
   AND construct.midi_note = '0'
   AND construct.filename = '0'
   AND btrim(construct.pitch_content) = entry->>'expectedPitchContent'
   AND construct.velocity = (entry->>'expectedVelocity')::integer
   AND construct.round_robin = (entry->>'expectedRoundRobin')::integer
   AND coalesce(nullif(btrim(construct.mic_position), ''), 'main') =
       entry->>'expectedMicPosition'
   AND construct.playback_type::text = entry->>'expectedPlaybackType'
  JOIN public.samples_original_paths source
    ON source.id = construct.sample_original_path_id
   AND source.s3_path = entry->>'sourceS3Path'
   AND source.file_name = entry->>'sourceFileName'
  JOIN public.instruments_v2 instrument
    ON instrument.id = construct.instrument_v2_id
   AND instrument.published = true
  JOIN public.contributors contributor
    ON contributor.id = instrument.contributor_id
   AND contributor.slug = btrim(p_contributor_slug);
  IF v_matching_count <> v_expected_count THEN
    RAISE EXCEPTION 'construct_address_reconciliation_snapshot_changed'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest) entry
    JOIN public.sample_path_constructs source
      ON source.id = (entry->>'constructId')::uuid
    JOIN public.sample_path_constructs collision
      ON collision.instrument_v2_id = source.instrument_v2_id
     AND collision.id <> source.id
     AND btrim(collision.pitch_content) = entry->>'expectedPitchContent'
     AND btrim(collision.filename) = btrim(entry->>'rootMidi')
     AND collision.velocity = CASE
       WHEN entry ? 'targetVelocity'
         THEN (entry->>'targetVelocity')::integer
       ELSE (entry->>'expectedVelocity')::integer
     END
     AND collision.round_robin = (entry->>'expectedRoundRobin')::integer
     AND coalesce(nullif(btrim(collision.mic_position), ''), 'main') =
         entry->>'expectedMicPosition'
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest) entry
    JOIN public.sample_path_constructs source
      ON source.id = (entry->>'constructId')::uuid
    GROUP BY
      source.instrument_v2_id,
      entry->>'expectedPitchContent',
      btrim(entry->>'rootMidi'),
      CASE WHEN entry ? 'targetVelocity'
        THEN (entry->>'targetVelocity')::integer
        ELSE (entry->>'expectedVelocity')::integer END,
      (entry->>'expectedRoundRobin')::integer,
      entry->>'expectedMicPosition'
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'construct_address_reconciliation_destination_collision'
      USING ERRCODE = '55000';
  END IF;

  -- Row and advisory locks can wait long enough for a once-valid lease to
  -- expire. Fence the first mutation with a wall-clock check, not now().
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = v_locked_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'construct_address_reconciliation_lease_expired_before_apply'
      USING ERRCODE = '55000';
  END IF;

  WITH entries AS (
    SELECT entry
    FROM jsonb_array_elements(p_manifest) entry
  )
  UPDATE public.sample_path_constructs construct
  SET midi_note = entries.entry->>'rootMidi',
      filename = entries.entry->>'rootMidi',
      velocity = CASE
        WHEN entries.entry ? 'targetVelocity'
          THEN (entries.entry->>'targetVelocity')::integer
        ELSE construct.velocity
      END,
      updated_at = now()
  FROM entries
  WHERE construct.id = (entries.entry->>'constructId')::uuid;
  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> v_expected_count THEN
    RAISE EXCEPTION 'construct_address_reconciliation_update_count_mismatch'
      USING ERRCODE = '55000';
  END IF;

  SELECT public.refresh_instrument_v2_axis_summaries_v1(v_instrument_ids)
    INTO v_refreshed_count;
  IF v_refreshed_count IS DISTINCT FROM cardinality(v_instrument_ids) THEN
    RAISE EXCEPTION 'construct_address_reconciliation_summary_refresh_failed'
      USING ERRCODE = '55000';
  END IF;

  v_result := jsonb_build_object(
    'providerSlug', btrim(p_contributor_slug),
    'manifestHash', p_manifest_hash,
    'appliedCount', v_updated_count,
    'instrumentV2Ids', to_jsonb(v_instrument_ids),
    'idempotent', false
  );
  INSERT INTO public.sip_construct_address_reconciliation_receipts(
    provider_slug,
    manifest_hash,
    manifest,
    result,
    applied_by
  ) VALUES (
    btrim(p_contributor_slug),
    p_manifest_hash,
    p_manifest,
    v_result,
    btrim(p_applied_by)
  );
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_apply_construct_address_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_apply_construct_address_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") IS 'Atomically applies an exact reviewed construct-address manifest under the provider lease and returns a durable idempotency receipt.';



CREATE OR REPLACE FUNCTION "public"."sip_apply_gospel_talkbox_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r public.sip_gospel_talkbox_grid_rehearsals%ROWTYPE; rc public.sip_gospel_talkbox_grid_receipts%ROWTYPE; before_s jsonb; expected_after_s jsonb; after_s jsonb; after_h text; n int; override_n int; result jsonb; locked_lease_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('gospel-musicians',0));
  IF btrim(p_provider_slug)<>'gospel-musicians' OR NOT public.sip_validate_gospel_talkbox_grid_manifest_v1(p_manifest) OR btrim(coalesce(p_applied_by,''))='' THEN RAISE EXCEPTION 'gospel_talkbox_grid_apply_invalid' USING ERRCODE='22023'; END IF;
  SELECT l.id INTO locked_lease_id FROM public.sip_fleet_provider_leases l WHERE l.id=p_lease_id AND l.lease_token=p_lease_token AND l.provider_slug='gospel-musicians' AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp() FOR UPDATE;
  IF locked_lease_id IS NULL THEN RAISE EXCEPTION 'gospel_talkbox_grid_lease_invalid' USING ERRCODE='55000'; END IF;
  IF EXISTS(SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gospel-musicians' AND status IN('queued','running')) THEN RAISE EXCEPTION 'gospel_talkbox_grid_active_run' USING ERRCODE='55000'; END IF;
  LOCK TABLE public.sip_sample_construct IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.sip_review_instrument IN SHARE MODE; LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE MODE; LOCK TABLE public.sip_gospel_talkbox_grid_rehearsals IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.sip_gospel_talkbox_grid_receipts IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO r FROM public.sip_gospel_talkbox_grid_rehearsals WHERE id=p_rehearsal_id FOR UPDATE;
  SELECT * INTO rc FROM public.sip_gospel_talkbox_grid_receipts WHERE provider_slug='gospel-musicians' AND manifest_hash=p_manifest_hash FOR UPDATE;
  IF rc.result IS NOT NULL THEN
    after_s:=public.sip_build_gospel_talkbox_grid_snapshot_v1(p_manifest); after_h:=encode(extensions.digest(convert_to(after_s::text,'UTF8'),'sha256'),'hex');
    IF rc.rehearsal_id<>p_rehearsal_id OR rc.rolled_back_at IS NOT NULL OR after_h<>rc.after_snapshot_hash OR after_s IS DISTINCT FROM rc.after_snapshot THEN RAISE EXCEPTION 'gospel_talkbox_grid_apply_replay_drift' USING ERRCODE='40001'; END IF;
    RETURN rc.result||jsonb_build_object('idempotent',true);
  END IF;
  IF r.id IS NULL OR r.provider_lease_id<>p_lease_id OR r.provider_lease_token<>p_lease_token OR r.manifest_hash<>p_manifest_hash OR r.snapshot_hash<>p_snapshot_hash OR r.manifest IS DISTINCT FROM p_manifest OR r.consumed_at IS NOT NULL THEN RAISE EXCEPTION 'gospel_talkbox_grid_current_rehearsal_required' USING ERRCODE='55000'; END IF;
  PERFORM c.id FROM public.sip_sample_construct c JOIN jsonb_array_elements(p_manifest) e ON c.original_sample_id=(e->>'originalSampleId')::uuid FOR UPDATE;
  before_s:=public.sip_build_gospel_talkbox_grid_snapshot_v1(p_manifest);
  IF encode(extensions.digest(convert_to(before_s::text,'UTF8'),'sha256'),'hex')<>p_snapshot_hash OR before_s IS DISTINCT FROM r.snapshot THEN RAISE EXCEPTION 'gospel_talkbox_grid_late_drift' USING ERRCODE='40001'; END IF;
  IF NOT public.sip_gospel_talkbox_grid_override_identity_valid_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_review_override_identity_mismatch' USING ERRCODE='55000'; END IF;
  expected_after_s:=public.sip_build_gospel_talkbox_grid_expected_after_v1(before_s,p_manifest);
  IF NOT EXISTS(SELECT 1 FROM public.sip_fleet_provider_leases l WHERE l.id=locked_lease_id AND l.lease_token=p_lease_token AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'gospel_talkbox_grid_lease_expired_before_write' USING ERRCODE='55000'; END IF;
  UPDATE public.sip_sample_construct c SET midi_note=e->>'targetMidiNote',updated_at=now() FROM jsonb_array_elements(p_manifest) e WHERE c.original_sample_id=(e->>'originalSampleId')::uuid AND c.contributor_slug='gospel-musicians' AND c.file_path=e->>'filePath' AND c.midi_note=e->>'expectedMidiNote'; GET DIAGNOSTICS n=ROW_COUNT;
  IF n<>396 THEN RAISE EXCEPTION 'gospel_talkbox_grid_atomic_count_mismatch' USING ERRCODE='40001'; END IF;
  UPDATE public.sip_review_sample_override o SET midi_note=e->>'targetMidiNote',updated_at=now() FROM jsonb_array_elements(p_manifest) e WHERE o.original_sample_id=(e->>'originalSampleId')::uuid AND o.contributor_slug='gospel-musicians' AND o.file_path=e->>'filePath' AND o.midi_note=e->>'expectedMidiNote'; GET DIAGNOSTICS override_n=ROW_COUNT;
  after_s:=public.sip_build_gospel_talkbox_grid_snapshot_v1(p_manifest); after_h:=encode(extensions.digest(convert_to(after_s::text,'UTF8'),'sha256'),'hex');
  IF after_s IS DISTINCT FROM expected_after_s THEN RAISE EXCEPTION 'gospel_talkbox_grid_unexpected_after_state' USING ERRCODE='40001'; END IF;
  result:=jsonb_build_object('providerSlug','gospel-musicians','manifestHash',p_manifest_hash,'rehearsalRunId',p_rehearsal_id,'appliedCount',396,'overrideAppliedCount',override_n,'afterSnapshotHash',after_h);
  INSERT INTO public.sip_gospel_talkbox_grid_receipts VALUES('gospel-musicians',p_manifest_hash,p_rehearsal_id,before_s,after_h,after_s,result,btrim(p_applied_by),now(),NULL,NULL);
  UPDATE public.sip_gospel_talkbox_grid_rehearsals SET consumed_at=now() WHERE id=p_rehearsal_id;
  RETURN result;
END $$;


ALTER FUNCTION "public"."sip_apply_gospel_talkbox_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_apply_gospel_talkbox_incomplete_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_membership_hash" "text", "p_snapshot_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r public.sip_gospel_talkbox_grid_rehearsals%ROWTYPE; rc public.sip_gospel_talkbox_grid_receipts%ROWTYPE; before_s jsonb; expected_after_s jsonb; after_s jsonb; after_h text; n int; override_n int; result jsonb; locked_lease_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('gospel-musicians',0));
  IF btrim(p_provider_slug)<>'gospel-musicians' OR NOT public.sip_validate_gospel_talkbox_incomplete_grid_manifest_v1(p_manifest) OR btrim(coalesce(p_applied_by,''))='' THEN RAISE EXCEPTION 'gospel_talkbox_grid_apply_invalid' USING ERRCODE='22023'; END IF;
  IF p_manifest_hash<>'3abf4f6a45e2091c197088f78dbd723804ff8f24840644b051681f24ee93c795' OR p_manifest_hash<>public.sip_gospel_talkbox_incomplete_plan_hash_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_manifest_hash_mismatch' USING ERRCODE='22023'; END IF;
  IF p_membership_hash<>'34a8ab7c8db169c4de2ec2894c323bacfd379e04250844289d331d4c894737b8' OR p_membership_hash<>public.sip_gospel_talkbox_incomplete_membership_hash_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_membership_hash_mismatch' USING ERRCODE='22023'; END IF;
  SELECT l.id INTO locked_lease_id FROM public.sip_fleet_provider_leases l WHERE l.id=p_lease_id AND l.lease_token=p_lease_token AND l.provider_slug='gospel-musicians' AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp() FOR UPDATE;
  IF locked_lease_id IS NULL THEN RAISE EXCEPTION 'gospel_talkbox_grid_lease_invalid' USING ERRCODE='55000'; END IF;
  IF EXISTS(SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gospel-musicians' AND status IN('queued','running')) THEN RAISE EXCEPTION 'gospel_talkbox_grid_active_run' USING ERRCODE='55000'; END IF;
  LOCK TABLE public.sip_sample_construct IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.sip_review_instrument IN SHARE MODE; LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE MODE; LOCK TABLE public.sip_gospel_talkbox_grid_rehearsals IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.sip_gospel_talkbox_grid_receipts IN SHARE ROW EXCLUSIVE MODE;
  IF NOT public.sip_gospel_talkbox_incomplete_membership_current_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_membership_drift' USING ERRCODE='40001'; END IF;
  SELECT * INTO r FROM public.sip_gospel_talkbox_grid_rehearsals WHERE id=p_rehearsal_id FOR UPDATE;
  SELECT * INTO rc FROM public.sip_gospel_talkbox_grid_receipts WHERE provider_slug='gospel-musicians' AND manifest_hash=p_manifest_hash FOR UPDATE;
  IF rc.result IS NOT NULL THEN
    after_s:=public.sip_build_gospel_talkbox_grid_snapshot_v1(p_manifest); after_h:=encode(extensions.digest(convert_to(after_s::text,'UTF8'),'sha256'),'hex');
    IF rc.rehearsal_id<>p_rehearsal_id OR rc.rolled_back_at IS NOT NULL OR after_h<>rc.after_snapshot_hash OR after_s IS DISTINCT FROM rc.after_snapshot THEN RAISE EXCEPTION 'gospel_talkbox_grid_apply_replay_drift' USING ERRCODE='40001'; END IF;
    RETURN rc.result||jsonb_build_object('idempotent',true);
  END IF;
  IF r.id IS NULL OR r.provider_lease_id<>p_lease_id OR r.provider_lease_token<>p_lease_token OR r.manifest_hash<>p_manifest_hash OR r.snapshot_hash<>p_snapshot_hash OR r.manifest IS DISTINCT FROM p_manifest OR r.consumed_at IS NOT NULL THEN RAISE EXCEPTION 'gospel_talkbox_grid_current_rehearsal_required' USING ERRCODE='55000'; END IF;
  PERFORM c.id FROM public.sip_sample_construct c JOIN jsonb_array_elements(p_manifest) e ON c.original_sample_id=(e->>'originalSampleId')::uuid FOR UPDATE;
  before_s:=public.sip_build_gospel_talkbox_grid_snapshot_v1(p_manifest);
  IF encode(extensions.digest(convert_to(before_s::text,'UTF8'),'sha256'),'hex')<>p_snapshot_hash OR before_s IS DISTINCT FROM r.snapshot THEN RAISE EXCEPTION 'gospel_talkbox_grid_late_drift' USING ERRCODE='40001'; END IF;
  IF NOT public.sip_gospel_talkbox_grid_override_identity_valid_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_review_override_identity_mismatch' USING ERRCODE='55000'; END IF;
  expected_after_s:=public.sip_build_gospel_talkbox_grid_expected_after_v1(before_s,p_manifest);
  IF NOT EXISTS(SELECT 1 FROM public.sip_fleet_provider_leases l WHERE l.id=locked_lease_id AND l.lease_token=p_lease_token AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'gospel_talkbox_grid_lease_expired_before_write' USING ERRCODE='55000'; END IF;
  UPDATE public.sip_sample_construct c SET midi_note=e->>'targetMidiNote',updated_at=now() FROM jsonb_array_elements(p_manifest) e WHERE c.original_sample_id=(e->>'originalSampleId')::uuid AND c.contributor_slug='gospel-musicians' AND c.file_path=e->>'filePath' AND c.midi_note=e->>'expectedMidiNote'; GET DIAGNOSTICS n=ROW_COUNT;
  IF n<>69 THEN RAISE EXCEPTION 'gospel_talkbox_grid_atomic_count_mismatch' USING ERRCODE='40001'; END IF;
  UPDATE public.sip_review_sample_override o SET midi_note=e->>'targetMidiNote',updated_at=now() FROM jsonb_array_elements(p_manifest) e WHERE o.original_sample_id=(e->>'originalSampleId')::uuid AND o.contributor_slug='gospel-musicians' AND o.file_path=e->>'filePath' AND o.midi_note=e->>'expectedMidiNote'; GET DIAGNOSTICS override_n=ROW_COUNT;
  after_s:=public.sip_build_gospel_talkbox_grid_snapshot_v1(p_manifest); after_h:=encode(extensions.digest(convert_to(after_s::text,'UTF8'),'sha256'),'hex');
  IF after_s IS DISTINCT FROM expected_after_s THEN RAISE EXCEPTION 'gospel_talkbox_grid_unexpected_after_state' USING ERRCODE='40001'; END IF;
  result:=jsonb_build_object('providerSlug','gospel-musicians','manifestHash',p_manifest_hash,'rehearsalRunId',p_rehearsal_id,'appliedCount',69,'overrideAppliedCount',override_n,'afterSnapshotHash',after_h);
  INSERT INTO public.sip_gospel_talkbox_grid_receipts VALUES('gospel-musicians',p_manifest_hash,p_rehearsal_id,before_s,after_h,after_s,result,btrim(p_applied_by),now(),NULL,NULL);
  UPDATE public.sip_gospel_talkbox_grid_rehearsals SET consumed_at=now() WHERE id=p_rehearsal_id;
  RETURN result;
END $$;


ALTER FUNCTION "public"."sip_apply_gospel_talkbox_incomplete_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_membership_hash" "text", "p_snapshot_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_apply_gospel_talkbox_warning_refresh_v1"("p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_context_hash" "text", "p_snapshot_hash" "text", "p_warnings_hash" "text", "p_generator_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r public.sip_gospel_talkbox_warning_refresh_rehearsals%ROWTYPE; s jsonb; h text; n int; v_result jsonb; v_lease uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('gospel-musicians',0));
  SELECT id INTO v_lease FROM public.sip_fleet_provider_leases WHERE id=p_lease_id AND lease_token=p_lease_token AND provider_slug='gospel-musicians' AND released_at IS NULL AND lease_expires_at>clock_timestamp() FOR UPDATE;
  IF v_lease IS NULL THEN RAISE EXCEPTION 'gospel_warning_refresh_lease_invalid' USING ERRCODE='55000'; END IF;
  SELECT * INTO r FROM public.sip_gospel_talkbox_warning_refresh_rehearsals WHERE id=p_rehearsal_id FOR UPDATE;
  IF r.id IS NULL OR r.provider_lease_id<>p_lease_id OR r.provider_lease_token<>p_lease_token OR r.manifest_hash<>p_manifest_hash OR r.context_hash<>p_context_hash OR r.snapshot_hash<>p_snapshot_hash OR r.warnings_hash<>p_warnings_hash OR r.generator_version<>p_generator_version THEN RAISE EXCEPTION 'gospel_warning_refresh_rehearsal_mismatch' USING ERRCODE='55000'; END IF;
  IF r.status='applied' THEN RETURN r.result||jsonb_build_object('idempotent',true); END IF;
  IF EXISTS(SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gospel-musicians' AND status IN('queued','running')) THEN RAISE EXCEPTION 'gospel_warning_refresh_active_run' USING ERRCODE='55000'; END IF;
  PERFORM st.sip_review_instrument_id FROM public.sip_review_warning_index_state st JOIN jsonb_array_elements(r.manifest)e ON st.sip_review_instrument_id=(e->>'stagingInstrumentId')::uuid ORDER BY st.sip_review_instrument_id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM public.sip_review_warning_index_state st JOIN jsonb_array_elements(r.manifest)e ON st.sip_review_instrument_id=(e->>'stagingInstrumentId')::uuid WHERE st.refresh_lease_token IS NOT NULL) THEN RAISE EXCEPTION 'gospel_warning_refresh_background_refresh_active' USING ERRCODE='55000'; END IF;
  PERFORM rs.id FROM public.sip_review_warning_review_state rs JOIN jsonb_array_elements(r.manifest)e ON rs.sip_review_instrument_id=(e->>'stagingInstrumentId')::uuid ORDER BY rs.sip_review_instrument_id,rs.category,rs.warning_key FOR UPDATE;
  s:=public.sip_gospel_talkbox_warning_refresh_snapshot_v1(r.manifest); h:=encode(extensions.digest(convert_to(s::text,'UTF8'),'sha256'),'hex');
  IF h<>p_snapshot_hash OR s IS DISTINCT FROM r.snapshot THEN RAISE EXCEPTION 'gospel_warning_refresh_late_drift' USING ERRCODE='40001'; END IF;
  v_lease:=NULL;
  SELECT id INTO v_lease FROM public.sip_fleet_provider_leases WHERE id=p_lease_id AND lease_token=p_lease_token AND provider_slug='gospel-musicians' AND released_at IS NULL AND lease_expires_at>clock_timestamp() FOR UPDATE;
  IF v_lease IS NULL THEN RAISE EXCEPTION 'gospel_warning_refresh_lease_expired_before_write' USING ERRCODE='55000'; END IF;
  DELETE FROM public.sip_review_warning_index w USING jsonb_array_elements(r.manifest)e WHERE w.sip_review_instrument_id=(e->>'stagingInstrumentId')::uuid;
  INSERT INTO public.sip_review_warning_index(sip_review_instrument_id,contributor_slug,category,warning_key,type,severity,field,file_path,original_sample_id,message)
  SELECT (w->>'stagingInstrumentId')::uuid,'gospel-musicians',w->>'category',w->>'warningKey',w->>'type',w->>'severity',w->>'field',NULLIF(w->>'filePath',''),NULLIF(w->>'originalSampleId','')::uuid,w->>'message' FROM jsonb_array_elements(r.warnings)w;
  GET DIAGNOSTICS n=ROW_COUNT;
  INSERT INTO public.sip_review_warning_index_state(sip_review_instrument_id,contributor_slug,is_stale,refreshed_at,refresh_error,refresh_lease_token,failure_count,diagnostics_json,updated_at)
  SELECT (e->>'stagingInstrumentId')::uuid,'gospel-musicians',false,now(),NULL,NULL,0,jsonb_build_object('mode','synchronous-provider-refresh','contextHash',p_context_hash),now() FROM jsonb_array_elements(r.manifest)e
  ON CONFLICT(sip_review_instrument_id) DO UPDATE SET is_stale=false,refreshed_at=EXCLUDED.refreshed_at,refresh_error=NULL,refresh_lease_token=NULL,failure_count=0,diagnostics_json=EXCLUDED.diagnostics_json,updated_at=now();
  v_result:=jsonb_build_object('rehearsalId',r.id,'manifestHash',r.manifest_hash,'contextHash',r.context_hash,'warningsHash',r.warnings_hash,'generatorVersion',r.generator_version,'snapshotHash',r.snapshot_hash,'instrumentCount',jsonb_array_length(r.manifest),'warningCount',n,'queueRowsCreated',0,'jobRowsCreated',0,'runRowsCreated',0,'idempotent',false);
  UPDATE public.sip_gospel_talkbox_warning_refresh_rehearsals SET status='applied',result=v_result,applied_at=now() WHERE id=r.id;
  RETURN v_result;
END $$;


ALTER FUNCTION "public"."sip_apply_gospel_talkbox_warning_refresh_v1"("p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_context_hash" "text", "p_snapshot_hash" "text", "p_warnings_hash" "text", "p_generator_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_apply_gotchanoddin_tonal_kit_pitchless_v1"("p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_mutation_plan_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_authorization_proof" "text", "p_operator_identity" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE r public.sip_gotchanoddin_tonal_kit_pitchless_rehearsals%ROWTYPE; prior public.sip_gotchanoddin_tonal_kit_pitchless_receipts%ROWTYPE; v_after jsonb; v_result jsonb; v_instruments integer; v_constructs integer;
BEGIN
  IF current_setting('app.sip_publish_coordinator_authorized',true) IS DISTINCT FROM 'on' OR btrim(coalesce(p_authorization_proof,'')) !~ '^[a-f0-9]{64}$' OR btrim(coalesce(p_operator_identity,''))='' THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_apply_authorization_invalid' USING ERRCODE='42501'; END IF;
  SELECT * INTO r FROM public.sip_gotchanoddin_tonal_kit_pitchless_rehearsals WHERE id=p_rehearsal_id FOR UPDATE;
  IF r.id IS NULL OR r.manifest_hash<>p_manifest_hash OR r.snapshot_hash<>p_snapshot_hash OR r.mutation_plan_hash<>p_mutation_plan_hash THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_rehearsal_required' USING ERRCODE='40001'; END IF;
  SELECT * INTO prior FROM public.sip_gotchanoddin_tonal_kit_pitchless_receipts WHERE rehearsal_id=r.id;
  IF prior.id IS NOT NULL THEN
    IF prior.operator_identity <> p_operator_identity
       OR public.sip_gotchanoddin_tonal_kit_pitchless_snapshot_v1(r.manifest) IS DISTINCT FROM prior.after_snapshot THEN
      RAISE EXCEPTION 'gotchanoddin_tonal_kit_idempotency_drift' USING ERRCODE='40001';
    END IF;
    RETURN prior.post_write_audit || jsonb_build_object('idempotent',true);
  END IF;
  IF r.status <> 'passed' THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_rehearsal_required' USING ERRCODE='40001'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.sip_fleet_provider_leases l WHERE l.id=p_lease_id AND l.provider_slug='gotchanoddin' AND l.lease_token=p_lease_token AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_apply_lease_invalid' USING ERRCODE='55000'; END IF;
  IF EXISTS (SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gotchanoddin' AND status IN ('queued','running')) THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_active_run' USING ERRCODE='55000'; END IF;
  IF public.sip_gotchanoddin_tonal_kit_pitchless_snapshot_v1(r.manifest) IS DISTINCT FROM r.before_snapshot THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_snapshot_drift' USING ERRCODE='40001'; END IF;
  UPDATE public.instruments_v2 i SET engine_type='non_tonal', single_pitch=NULL, sampled_midi_notes=NULL, file_name_references=ARRAY['pitchless'], updated_at=now() FROM jsonb_array_elements_text(r.manifest->'instrumentV2Ids') t WHERE i.id=t.value::uuid AND i.engine_type::text='tonal'; GET DIAGNOSTICS v_instruments=ROW_COUNT;
  UPDATE public.sample_path_constructs c SET midi_note='pitchless', filename='pitchless', pitch_content='0', updated_at=now() FROM jsonb_array_elements_text(r.manifest->'instrumentV2Ids') t WHERE c.instrument_v2_id=t.value::uuid; GET DIAGNOSTICS v_constructs=ROW_COUNT;
  IF v_instruments <> 2397 OR v_constructs <> 2397 THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_expected_write_count_mismatch' USING ERRCODE='40001'; END IF;
  v_after:=public.sip_gotchanoddin_tonal_kit_pitchless_snapshot_v1(r.manifest); v_result:=jsonb_build_object('rehearsalId',r.id,'manifestHash',p_manifest_hash,'appliedCount',2397,'constructCount',2397,'idempotent',false);
  INSERT INTO public.sip_gotchanoddin_tonal_kit_pitchless_receipts(rehearsal_id,manifest_hash,snapshot_hash,mutation_plan_hash,provider_lease_id,operator_identity,before_snapshot,after_snapshot,rollback_payload,post_write_audit,expected_write_counts) VALUES (r.id,p_manifest_hash,p_snapshot_hash,p_mutation_plan_hash,p_lease_id,p_operator_identity,r.before_snapshot,v_after,r.before_snapshot,v_result,jsonb_build_object('instruments',2397,'constructs',2397));
  UPDATE public.sip_gotchanoddin_tonal_kit_pitchless_rehearsals SET status='consumed',consumed_at=now() WHERE id=r.id; RETURN v_result;
END; $_$;


ALTER FUNCTION "public"."sip_apply_gotchanoddin_tonal_kit_pitchless_v1"("p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_mutation_plan_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_authorization_proof" "text", "p_operator_identity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_apply_provider_warning_review_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_expected_decision" "text", "p_expected_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_lease_id uuid;
  v_actor text;
  v_rehearsal public.sip_provider_warning_review_rehearsals%ROWTYPE;
  v_snapshot jsonb;
  v_current_hash text;
  v_next_status text;
  v_changed_count integer;
  v_event_count integer;
  v_result jsonb;
BEGIN
  IF p_rehearsal_id IS NULL OR p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR p_snapshot_hash !~ '^[0-9a-f]{64}$'
     OR p_expected_decision NOT IN ('accepted', 'rejected')
     OR (p_expected_decision = 'accepted' AND p_expected_reason NOT IN
       ('explicit_path_authority', 'verified_false_positive'))
     OR (p_expected_decision = 'rejected' AND p_expected_reason NOT IN
       ('requires_correction', 'insufficient_evidence')) THEN
    RAISE EXCEPTION 'provider_warning_review_apply_identity_invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(lower(btrim(p_provider_slug)), 0)
  );
  SELECT lease.id, btrim(lease.lease_owner) INTO v_lease_id, v_actor
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id AND lease.provider_slug = btrim(p_provider_slug)
    AND lease.lease_token = p_lease_token AND lease.released_at IS NULL
    AND btrim(coalesce(lease.lease_owner, '')) <> ''
    AND lease.lease_expires_at > clock_timestamp() FOR UPDATE;
  IF v_lease_id IS NULL THEN
    RAISE EXCEPTION 'provider_warning_review_lease_invalid' USING ERRCODE = '55000';
  END IF;
  SELECT * INTO v_rehearsal
  FROM public.sip_provider_warning_review_rehearsals rehearsal
  WHERE rehearsal.id = p_rehearsal_id FOR UPDATE;
  IF NOT FOUND OR v_rehearsal.provider_slug <> btrim(p_provider_slug)
     OR v_rehearsal.provider_lease_id <> p_lease_id
     OR v_rehearsal.provider_lease_token <> p_lease_token
     OR v_rehearsal.manifest_hash <> p_manifest_hash
     OR v_rehearsal.snapshot_hash <> p_snapshot_hash
     OR v_rehearsal.decision <> p_expected_decision
     OR v_rehearsal.reason <> p_expected_reason THEN
    RAISE EXCEPTION 'provider_warning_review_rehearsal_mismatch' USING ERRCODE = '55000';
  END IF;
  IF v_rehearsal.status = 'applied' THEN
    RETURN v_rehearsal.result || jsonb_build_object('idempotent', true);
  END IF;
  IF EXISTS (SELECT 1 FROM public.sip_fleet_runs run
             WHERE run.provider_slug = btrim(p_provider_slug)
               AND run.status IN ('queued', 'running')) THEN
    RAISE EXCEPTION 'provider_warning_review_active_run' USING ERRCODE = '55000';
  END IF;

  PERFORM warning.id FROM public.sip_review_warning_index warning
  WHERE warning.id IN (SELECT (entry->>'warningId')::bigint
                       FROM jsonb_array_elements(v_rehearsal.manifest) entry)
  FOR UPDATE;
  PERFORM instrument.id FROM public.sip_review_instrument instrument
  WHERE instrument.id IN (
    SELECT (entry->>'stagingInstrumentId')::uuid
    FROM jsonb_array_elements(v_rehearsal.manifest) entry
  ) FOR SHARE;
  PERFORM source.id FROM public.samples_original_paths source
  WHERE source.id IN (
    SELECT (entry->>'sampleOriginalPathId')::uuid
    FROM jsonb_array_elements(v_rehearsal.manifest) entry
  ) FOR SHARE;
  PERFORM warning_state.sip_review_instrument_id
  FROM public.sip_review_warning_index_state warning_state
  WHERE warning_state.sip_review_instrument_id IN (
    SELECT (entry->>'stagingInstrumentId')::uuid
    FROM jsonb_array_elements(v_rehearsal.manifest) entry
  ) FOR UPDATE;
  PERFORM review_state.id
  FROM public.sip_review_warning_review_state review_state
  WHERE (review_state.sip_review_instrument_id, review_state.category, review_state.warning_key) IN (
    SELECT (entry->>'stagingInstrumentId')::uuid, entry->>'category', entry->>'warningKey'
    FROM jsonb_array_elements(v_rehearsal.manifest) entry
  ) FOR UPDATE;
  v_snapshot := public.sip_provider_warning_review_snapshot_v1(
    p_provider_slug, v_rehearsal.manifest
  );
  v_current_hash := encode(extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'), 'hex');
  IF v_current_hash <> p_snapshot_hash THEN
    RAISE EXCEPTION 'provider_warning_review_snapshot_changed' USING ERRCODE = '55000';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.sip_fleet_provider_leases lease
                 WHERE lease.id = v_lease_id AND lease.lease_token = p_lease_token
                   AND lease.released_at IS NULL
                   AND lease.lease_expires_at > clock_timestamp()) THEN
    RAISE EXCEPTION 'provider_warning_review_lease_expired_before_apply' USING ERRCODE = '55000';
  END IF;

  v_next_status := CASE WHEN v_rehearsal.decision = 'accepted'
                        THEN 'accepted' ELSE 'confirmed' END;
  WITH target AS (
    SELECT warning.sip_review_instrument_id, warning.contributor_slug,
           warning.category, warning.warning_key, warning.type,
           coalesce(state.status, 'open') AS previous_status
    FROM jsonb_array_elements(v_rehearsal.manifest) entry
    JOIN public.sip_review_warning_index warning
      ON warning.id = (entry->>'warningId')::bigint
    LEFT JOIN public.sip_review_warning_review_state state
      ON state.sip_review_instrument_id = warning.sip_review_instrument_id
     AND state.category = warning.category AND state.warning_key = warning.warning_key
  ), changed AS (
    INSERT INTO public.sip_review_warning_review_state(
      sip_review_instrument_id, contributor_slug, category, warning_key, type,
      status, note, updated_by
    ) SELECT sip_review_instrument_id, contributor_slug, category, warning_key,
             type, v_next_status, v_rehearsal.reason, v_actor
      FROM target
    ON CONFLICT (sip_review_instrument_id, category, warning_key) DO UPDATE SET
      contributor_slug = EXCLUDED.contributor_slug, type = EXCLUDED.type,
      status = EXCLUDED.status, note = EXCLUDED.note,
      updated_by = EXCLUDED.updated_by, updated_at = now()
    RETURNING 1
  ) SELECT count(*)::integer INTO v_changed_count FROM changed;
  IF v_changed_count <> jsonb_array_length(v_rehearsal.manifest) THEN
    RAISE EXCEPTION 'provider_warning_review_apply_count_mismatch' USING ERRCODE = '55000';
  END IF;

  WITH target AS (
    SELECT warning.sip_review_instrument_id, warning.contributor_slug,
           warning.category, warning.warning_key, warning.type,
           entry->>'expectedReviewStatus' AS previous_status
    FROM jsonb_array_elements(v_rehearsal.manifest) entry
    JOIN public.sip_review_warning_index warning ON warning.id = (entry->>'warningId')::bigint
  ), events AS (
    INSERT INTO public.sip_review_warning_review_event(
      sip_review_instrument_id, contributor_slug, category, warning_key, type,
      previous_status, next_status, scope, note, actor
    ) SELECT sip_review_instrument_id, contributor_slug, category, warning_key,
             type, previous_status, v_next_status, 'row', v_rehearsal.reason,
             v_actor FROM target RETURNING 1
  ) SELECT count(*)::integer INTO v_event_count FROM events;
  IF v_event_count <> v_changed_count THEN
    RAISE EXCEPTION 'provider_warning_review_event_count_mismatch' USING ERRCODE = '55000';
  END IF;

  v_result := jsonb_build_object(
    'rehearsalId', p_rehearsal_id, 'providerSlug', v_rehearsal.provider_slug,
    'manifestHash', p_manifest_hash, 'snapshotHash', p_snapshot_hash,
    'decision', v_rehearsal.decision, 'reason', v_rehearsal.reason,
    'appliedCount', v_changed_count, 'idempotent', false
  );
  UPDATE public.sip_provider_warning_review_rehearsals
  SET status = 'applied', result = v_result, applied_at = now()
  WHERE id = p_rehearsal_id;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_apply_provider_warning_review_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_expected_decision" "text", "p_expected_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_apply_provider_warning_review_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_expected_decision" "text", "p_expected_reason" "text") IS 'Atomically resolves only an exact fresh warning manifest under its provider lease and consumes one durable rehearsal receipt.';



CREATE OR REPLACE FUNCTION "public"."sip_apply_retired_provenance_disposition_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_mutation_plan_hash" "text", "p_operator_identity" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_lease_id uuid;
  v_lease_owner text;
  v_rehearsal public.sip_retired_provenance_disposition_rehearsals%ROWTYPE;
  v_snapshot jsonb;
  v_current_hash text;
  v_post_snapshot jsonb;
  v_post_hash text;
  v_inserted_count integer;
  v_post_count integer;
  v_result jsonb;
BEGIN
  IF p_rehearsal_id IS NULL
     OR p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR p_snapshot_hash !~ '^[0-9a-f]{64}$'
     OR p_mutation_plan_hash !~ '^[0-9a-f]{64}$'
     OR btrim(coalesce(p_operator_identity, '')) = '' THEN
    RAISE EXCEPTION 'retired_provenance_disposition_apply_identity_invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended('sip-retired-provenance-disposition-global', 0)
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(lower(btrim(p_provider_slug)), 0)
  );
  SELECT lease.id, btrim(lease.lease_owner)
  INTO v_lease_id, v_lease_owner
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
    AND lease.provider_slug = btrim(p_provider_slug)
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF v_lease_id IS NULL THEN
    RAISE EXCEPTION 'retired_provenance_disposition_lease_invalid'
      USING ERRCODE = '55000';
  END IF;
  IF v_lease_owner IS DISTINCT FROM btrim(p_operator_identity) THEN
    RAISE EXCEPTION 'retired_provenance_disposition_operator_mismatch'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_rehearsal
  FROM public.sip_retired_provenance_disposition_rehearsals rehearsal
  WHERE rehearsal.id = p_rehearsal_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_rehearsal.provider_slug <> btrim(p_provider_slug)
     OR v_rehearsal.provider_lease_id <> p_lease_id
     OR v_rehearsal.provider_lease_token <> p_lease_token
     OR v_rehearsal.operator_identity <> btrim(p_operator_identity)
     OR v_rehearsal.manifest_hash <> p_manifest_hash
     OR v_rehearsal.snapshot_hash <> p_snapshot_hash
     OR v_rehearsal.mutation_plan_hash <> p_mutation_plan_hash THEN
    RAISE EXCEPTION 'retired_provenance_disposition_rehearsal_mismatch'
      USING ERRCODE = '55000';
  END IF;
  IF v_rehearsal.status = 'applied' THEN
    RETURN v_rehearsal.result || jsonb_build_object('idempotent', true);
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = btrim(p_provider_slug)
      AND run.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'retired_provenance_disposition_active_run'
      USING ERRCODE = '55000';
  END IF;

  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope
    IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_promotion_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.samples_original_paths IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_disposition
    IN SHARE ROW EXCLUSIVE MODE;

  v_snapshot := public.sip_retired_provenance_disposition_snapshot_v1(
    p_provider_slug, v_rehearsal.manifest, false
  );
  v_current_hash := encode(
    extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'), 'hex'
  );
  IF v_current_hash <> p_snapshot_hash THEN
    RAISE EXCEPTION 'retired_provenance_disposition_snapshot_changed'
      USING ERRCODE = '55000';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = v_lease_id
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION
      'retired_provenance_disposition_lease_expired_before_apply'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.sip_review_sample_disposition(
    sip_review_instrument_id, contributor_slug, original_sample_id,
    disposition, reason, evidence, reviewed_by
  )
  SELECT
    (entry->>'stagingInstrumentId')::uuid,
    btrim(p_provider_slug),
    (entry->>'sampleOriginalPathId')::uuid,
    entry->>'disposition',
    entry->>'reason',
    jsonb_build_object(
      'schemaVersion', 1,
      'operation', 'retired-provenance-disposition-backfill-v1',
      'rehearsalId', p_rehearsal_id,
      'manifestHash', p_manifest_hash,
      'snapshotHash', p_snapshot_hash,
      'mutationPlanHash', p_mutation_plan_hash,
      'instrumentV2Id', entry->>'instrumentV2Id',
      'samplePathConstructId', entry->>'samplePathConstructId',
      'retirementReason', entry->>'retirementReason',
      'retiredBy', entry->>'retiredBy',
      'retiredAt', entry->>'retiredAt'
    ),
    btrim(p_operator_identity)
  FROM jsonb_array_elements(v_rehearsal.manifest->'entries') entry;
  GET DIAGNOSTICS v_inserted_count = ROW_COUNT;
  IF v_inserted_count <>
     (v_rehearsal.expected_counts->>'postWriteDispositions')::integer THEN
    RAISE EXCEPTION 'retired_provenance_disposition_apply_count_mismatch'
      USING ERRCODE = '55000';
  END IF;

  v_post_snapshot := public.sip_retired_provenance_disposition_snapshot_v1(
    p_provider_slug, v_rehearsal.manifest, true
  );
  v_post_hash := encode(
    extensions.digest(convert_to(v_post_snapshot::text, 'UTF8'), 'sha256'),
    'hex'
  );
  IF v_post_hash <> p_snapshot_hash THEN
    RAISE EXCEPTION
      'retired_provenance_disposition_source_construct_review_changed'
      USING ERRCODE = '55000';
  END IF;
  SELECT count(*) INTO v_post_count
  FROM public.sip_review_sample_disposition disposition
  WHERE disposition.sip_review_instrument_id IN (
    SELECT DISTINCT (entry->>'stagingInstrumentId')::uuid
    FROM jsonb_array_elements(v_rehearsal.manifest->'entries') entry
  );
  IF v_post_count <>
     (v_rehearsal.expected_counts->>'postWriteDispositions')::integer THEN
    RAISE EXCEPTION 'retired_provenance_disposition_post_write_count_mismatch'
      USING ERRCODE = '55000';
  END IF;

  v_result := jsonb_build_object(
    'rehearsalId', p_rehearsal_id,
    'providerSlug', btrim(p_provider_slug),
    'manifestHash', p_manifest_hash,
    'snapshotHash', p_snapshot_hash,
    'mutationPlanHash', p_mutation_plan_hash,
    'sourceCount', (v_rehearsal.expected_counts->>'sources')::integer,
    'reviewCount', (v_rehearsal.expected_counts->>'reviewRows')::integer,
    'deferredProvenanceCount',
      (v_rehearsal.expected_counts->>'deferredProvenance')::integer,
    'ignoredProvenanceCount',
      (v_rehearsal.expected_counts->>'ignoredProvenance')::integer,
    'expectedPostWriteCount',
      (v_rehearsal.expected_counts->>'postWriteDispositions')::integer,
    'appliedCount', v_inserted_count,
    'sourceMutationDelta', 0,
    'constructMutationDelta', 0,
    'reviewMutationDelta', 0,
    'samplesDeleted', 0,
    'constructsDeleted', 0,
    'idempotent', false,
    'status', 'applied'
  );
  UPDATE public.sip_retired_provenance_disposition_rehearsals
  SET status = 'applied', result = v_result, applied_at = now()
  WHERE id = p_rehearsal_id;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_apply_retired_provenance_disposition_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_mutation_plan_hash" "text", "p_operator_identity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_apply_retired_provenance_disposition_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_mutation_plan_hash" "text", "p_operator_identity" "text") IS 'Consumes one lease-, operator-, manifest-, snapshot-, and mutation-plan-bound rehearsal receipt and inserts only exact retired-source provenance dispositions.';



CREATE OR REPLACE FUNCTION "public"."sip_apply_source_pitchless_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_run_id" "uuid", "p_manifest_hash" "text", "p_source_snapshot_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_rehearsal public.sip_source_pitchless_reconciliation_rehearsals%ROWTYPE;
  v_receipt public.sip_source_pitchless_reconciliation_receipts%ROWTYPE;
  v_before_snapshot jsonb;
  v_before_hash text;
  v_after_snapshot jsonb;
  v_after_hash text;
  v_expected_after_snapshot jsonb;
  v_instrument_id uuid;
  v_updated_count integer;
  v_refreshed_count integer;
  v_result jsonb;
BEGIN
  IF btrim(coalesce(p_contributor_slug, '')) <> 'fallout-music-group'
     OR p_rehearsal_run_id IS NULL OR p_lease_id IS NULL OR p_lease_token IS NULL
     OR p_manifest_hash <> '1e9ef13ed4e83d9da2245bbafcdb2b83b47c87df7f118148cd4a133855412310'
     OR coalesce(p_source_snapshot_hash, '') !~ '^[0-9a-f]{64}$'
     OR btrim(coalesce(p_applied_by, '')) = ''
     OR jsonb_typeof(p_manifest) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest) <> 1 THEN
    RAISE EXCEPTION 'source_pitchless_apply_identity_invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'source_pitchless_apply_lease_invalid'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = btrim(p_contributor_slug)
      AND run.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'source_pitchless_apply_active_run'
      USING ERRCODE = '55000';
  END IF;

  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_promotion_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.samples_original_paths IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_source_pitchless_reconciliation_rehearsals
    IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_source_pitchless_reconciliation_receipts
    IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE ROW EXCLUSIVE MODE;

  SELECT (entry->>'instrumentV2Id')::uuid INTO v_instrument_id
  FROM jsonb_array_elements(p_manifest) entry;
  SELECT * INTO v_receipt
  FROM public.sip_source_pitchless_reconciliation_receipts receipt
  WHERE receipt.provider_slug = btrim(p_contributor_slug)
    AND receipt.manifest_hash = p_manifest_hash
  FOR UPDATE;
  SELECT * INTO v_rehearsal
  FROM public.sip_source_pitchless_reconciliation_rehearsals rehearsal
  WHERE rehearsal.id = p_rehearsal_run_id
  FOR UPDATE;
  IF v_receipt.result IS NULL AND (v_rehearsal.id IS NULL
     OR v_rehearsal.provider_slug <> btrim(p_contributor_slug)
     OR v_rehearsal.provider_lease_id <> p_lease_id
     OR v_rehearsal.provider_lease_token <> p_lease_token
     OR v_rehearsal.manifest_hash <> p_manifest_hash
     OR v_rehearsal.source_snapshot_hash <> p_source_snapshot_hash
     OR v_rehearsal.manifest IS DISTINCT FROM p_manifest
     OR v_rehearsal.status <> 'passed'
     OR v_rehearsal.consumed_at IS NOT NULL) THEN
    RAISE EXCEPTION 'source_pitchless_current_rehearsal_required'
      USING ERRCODE = '55000';
  END IF;
  PERFORM construct.id FROM public.sample_path_constructs construct
  WHERE construct.instrument_v2_id = v_instrument_id FOR UPDATE;
  PERFORM instrument.id FROM public.instruments_v2 instrument
  WHERE instrument.id = v_instrument_id
     OR v_instrument_id = ANY(COALESCE(instrument.articulations, ARRAY[]::uuid[]))
     OR v_instrument_id = ANY(COALESCE(instrument.effects_instruments, ARRAY[]::uuid[]))
     OR instrument.legato_transition = v_instrument_id
  FOR UPDATE;
  -- Lock every existing row represented in the snapshot. The target instrument
  -- row serializes FK-backed construct, alias, and promotion inserts; the exact
  -- final snapshot check below rejects non-FK relationship phantoms.
  PERFORM source.id FROM public.samples_original_paths source
  WHERE source.id IN (
    SELECT (entry->>'sampleOriginalPathId')::uuid
    FROM jsonb_array_elements(p_manifest) entry
  ) FOR UPDATE;
  PERFORM alias_row.id FROM public.instrument_v2_legacy_map alias_row
  WHERE alias_row.instrument_v2_id = v_instrument_id FOR SHARE;
  PERFORM promotion.id FROM public.sip_review_promotion_map promotion
  WHERE promotion.instrument_v2_id = v_instrument_id FOR SHARE;
  PERFORM review.id FROM public.sip_review_instrument review
  WHERE review.id IN (
    SELECT promotion.sip_review_instrument_id
    FROM public.sip_review_promotion_map promotion
    WHERE promotion.instrument_v2_id = v_instrument_id
  ) FOR UPDATE;
  PERFORM override_row.id FROM public.sip_review_sample_override override_row
  WHERE override_row.sip_review_instrument_id IN (
    SELECT promotion.sip_review_instrument_id
    FROM public.sip_review_promotion_map promotion
    WHERE promotion.instrument_v2_id = v_instrument_id
  ) FOR SHARE;

  v_before_snapshot := public.sip_build_source_pitchless_snapshot_v1(
    p_contributor_slug, p_manifest
  );
  v_before_hash := encode(
    extensions.digest(convert_to(v_before_snapshot::text, 'UTF8'), 'sha256'), 'hex'
  );
  IF v_receipt.result IS NOT NULL THEN
    IF v_receipt.manifest IS DISTINCT FROM p_manifest
       OR v_receipt.rehearsal_id <> p_rehearsal_run_id
       OR v_receipt.source_snapshot_hash <> p_source_snapshot_hash THEN
      RAISE EXCEPTION 'source_pitchless_receipt_identity_mismatch'
        USING ERRCODE = '55000';
    END IF;
    IF v_receipt.rolled_back_at IS NOT NULL THEN
      RAISE EXCEPTION 'source_pitchless_apply_after_rollback_forbidden'
        USING ERRCODE = '55000';
    END IF;
    IF v_before_hash <> v_receipt.after_snapshot_hash
       OR v_before_snapshot IS DISTINCT FROM v_receipt.after_snapshot THEN
      RAISE EXCEPTION 'source_pitchless_apply_replay_snapshot_changed'
        USING ERRCODE = '40001';
    END IF;
    RETURN v_receipt.result || jsonb_build_object('idempotent', true);
  END IF;
  IF v_before_hash <> p_source_snapshot_hash
     OR v_before_snapshot IS DISTINCT FROM v_rehearsal.source_snapshot THEN
    RAISE EXCEPTION 'source_pitchless_rehearsal_snapshot_changed'
      USING ERRCODE = '40001';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest) entry
    JOIN public.sample_path_constructs collision
      ON collision.instrument_v2_id = (entry->>'instrumentV2Id')::uuid
     AND collision.id <> (entry->>'constructId')::uuid
     AND btrim(collision.pitch_content) = entry->>'expectedPitchContent'
     AND collision.velocity = (entry->>'expectedVelocity')::integer
     AND collision.round_robin = (entry->>'expectedRoundRobin')::integer
     AND coalesce(nullif(btrim(collision.mic_position), ''), 'main') =
         entry->>'expectedMicPosition'
     AND btrim(collision.filename) = 'pitchless'
  ) THEN
    RAISE EXCEPTION 'source_pitchless_destination_collision'
      USING ERRCODE = '55000';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'source_pitchless_lease_expired_before_apply'
      USING ERRCODE = '55000';
  END IF;

  WITH manifest_entry AS (
    SELECT entry FROM jsonb_array_elements(p_manifest) entry
  )
  UPDATE public.sample_path_constructs construct
  SET midi_note = 'pitchless',
      filename = 'pitchless',
      updated_at = now()
  FROM manifest_entry entry
  WHERE construct.id = (entry->>'constructId')::uuid
    AND construct.instrument_v2_id = (entry->>'instrumentV2Id')::uuid
    AND construct.sample_original_path_id =
        (entry->>'sampleOriginalPathId')::uuid
    AND construct.midi_note = entry->>'expectedMidiNote'
    AND construct.filename = entry->>'expectedFilename';
  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> 1 THEN
    RAISE EXCEPTION 'source_pitchless_update_count_mismatch'
      USING ERRCODE = '55000';
  END IF;
  SELECT public.refresh_instrument_v2_axis_summaries_v1(ARRAY[v_instrument_id])
    INTO v_refreshed_count;
  IF v_refreshed_count <> 1 THEN
    RAISE EXCEPTION 'source_pitchless_summary_refresh_failed'
      USING ERRCODE = '55000';
  END IF;
  v_after_snapshot := public.sip_build_source_pitchless_snapshot_v1(
    p_contributor_slug, p_manifest
  );
  v_expected_after_snapshot := jsonb_set(
    jsonb_set(
      jsonb_set(
        jsonb_set(
          v_before_snapshot,
          '{targets,0,construct,midiNote}',
          to_jsonb('pitchless'::text)
        ),
        '{targets,0,construct,filename}',
        to_jsonb('pitchless'::text)
      ),
      '{instrumentConstructs,0,midiNote}',
      to_jsonb('pitchless'::text)
    ),
    '{instrumentConstructs,0,filename}',
    to_jsonb('pitchless'::text)
  );
  IF v_after_snapshot IS DISTINCT FROM v_expected_after_snapshot THEN
    RAISE EXCEPTION 'source_pitchless_unexpected_atomic_delta'
      USING ERRCODE = '40001';
  END IF;
  v_after_hash := encode(
    extensions.digest(convert_to(v_after_snapshot::text, 'UTF8'), 'sha256'), 'hex'
  );
  v_result := jsonb_build_object(
    'providerSlug', btrim(p_contributor_slug),
    'manifestHash', p_manifest_hash,
    'sourceSnapshotHash', p_source_snapshot_hash,
    'afterSnapshotHash', v_after_hash,
    'rehearsalRunId', p_rehearsal_run_id,
    'instrumentV2Ids', jsonb_build_array(v_instrument_id),
    'appliedCount', 1,
    'idempotent', false
  );
  INSERT INTO public.sip_source_pitchless_reconciliation_receipts(
    provider_slug, manifest_hash, rehearsal_id, source_snapshot_hash,
    manifest, before_snapshot, after_snapshot_hash, after_snapshot,
    result, applied_by
  ) VALUES (
    btrim(p_contributor_slug), p_manifest_hash, p_rehearsal_run_id,
    p_source_snapshot_hash, p_manifest, v_before_snapshot, v_after_hash,
    v_after_snapshot, v_result, btrim(p_applied_by)
  );
  UPDATE public.sip_source_pitchless_reconciliation_rehearsals
  SET status = 'consumed', consumed_at = now()
  WHERE id = p_rehearsal_run_id;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_apply_source_pitchless_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_run_id" "uuid", "p_manifest_hash" "text", "p_source_snapshot_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_apply_source_pitchless_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_run_id" "uuid", "p_manifest_hash" "text", "p_source_snapshot_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") IS 'Consumes one exact rehearsal and atomically sets one construct midi_note and filename to pitchless.';



CREATE OR REPLACE FUNCTION "public"."sip_build_gospel_talkbox_grid_expected_after_v1"("p_before_snapshot" "jsonb", "p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  WITH requested AS (SELECT e->>'originalSampleId' id,e->>'targetMidiNote' target_midi FROM jsonb_array_elements(p_manifest)e)
  SELECT jsonb_build_object(
    'constructs',COALESCE((SELECT jsonb_agg(c||jsonb_build_object('midiNote',r.target_midi) ORDER BY c->>'originalSampleId') FROM jsonb_array_elements(p_before_snapshot->'constructs')c JOIN requested r ON r.id=c->>'originalSampleId'),'[]'::jsonb),
    'overrides',COALESCE((SELECT jsonb_agg(CASE WHEN o->>'midiNote'='0' THEN o||jsonb_build_object('midiNote',r.target_midi) ELSE o END ORDER BY o->>'reviewInstrumentId',o->>'originalSampleId') FROM jsonb_array_elements(p_before_snapshot->'overrides')o JOIN requested r ON r.id=o->>'originalSampleId'),'[]'::jsonb)
  )
$$;


ALTER FUNCTION "public"."sip_build_gospel_talkbox_grid_expected_after_v1"("p_before_snapshot" "jsonb", "p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_build_gospel_talkbox_grid_snapshot_v1"("p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH requested AS (
    SELECT (e->>'originalSampleId')::uuid id FROM jsonb_array_elements(p_manifest) e
  )
  SELECT jsonb_build_object(
    'constructs', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',c.id,'originalSampleId',c.original_sample_id,'contributorSlug',c.contributor_slug,'filePath',c.file_path,'midiNote',c.midi_note,'filename',c.filename,'pitchContent',c.pitch_content,'velocity',c.velocity,'roundRobin',c.round_robin,'micPosition',c.mic_position,'playbackType',c.playback_type) ORDER BY c.original_sample_id)
      FROM public.sip_sample_construct c JOIN requested r ON r.id=c.original_sample_id), '[]'::jsonb),
    'overrides', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',o.id,'reviewInstrumentId',o.sip_review_instrument_id,'reviewSourceInstrumentId',i.source_sip_instrument_id,'reviewSourceContributorSlug',i.source_contributor_slug,'reviewSplitParentId',i.split_parent_sip_review_instrument_id,'reviewIsRetired',i.is_retired,'membershipMode',CASE WHEN EXISTS(SELECT 1 FROM public.sip_review_instrument_sample_scope any_scope WHERE any_scope.sip_review_instrument_id=o.sip_review_instrument_id) THEN 'sample-scope' ELSE 'instrument-original-sample-ids' END,'originalSampleId',o.original_sample_id,'contributorSlug',o.contributor_slug,'filePath',o.file_path,'midiNote',o.midi_note,'filename',o.filename,'pitchContent',o.pitch_content,'velocity',o.velocity,'roundRobin',o.round_robin,'micPosition',o.mic_position) ORDER BY o.sip_review_instrument_id,o.original_sample_id)
      FROM public.sip_review_sample_override o JOIN requested r ON r.id=o.original_sample_id LEFT JOIN public.sip_review_instrument i ON i.id=o.sip_review_instrument_id), '[]'::jsonb)
  )
$$;


ALTER FUNCTION "public"."sip_build_gospel_talkbox_grid_snapshot_v1"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_build_source_pitchless_snapshot_v1"("p_contributor_slug" "text", "p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH manifest AS (
    SELECT entry
    FROM jsonb_array_elements(p_manifest) entry
  ), target_ids AS (
    SELECT
      (entry->>'instrumentV2Id')::uuid AS instrument_v2_id,
      (entry->>'constructId')::uuid AS construct_id,
      (entry->>'sampleOriginalPathId')::uuid AS sample_original_path_id
    FROM manifest
  ), staging_ids AS (
    SELECT DISTINCT promotion.sip_review_instrument_id
    FROM public.sip_review_promotion_map promotion
    JOIN target_ids target
      ON target.instrument_v2_id = promotion.instrument_v2_id
  )
  SELECT jsonb_build_object(
    'providerSlug', btrim(p_contributor_slug),
    'targets', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'instrumentV2Id', instrument.id,
        'constructId', construct.id,
        'sampleOriginalPathId', source.id,
        'construct', jsonb_build_object(
          'midiNote', construct.midi_note,
          'filename', construct.filename,
          'pitchContent', construct.pitch_content,
          'velocity', construct.velocity,
          'roundRobin', construct.round_robin,
          'micPosition', coalesce(nullif(btrim(construct.mic_position), ''), 'main'),
          'playbackType', construct.playback_type
        ),
        'source', jsonb_build_object(
          's3Path', source.s3_path,
          'fileName', source.file_name
        ),
        'instrument', jsonb_build_object(
          'engineType', instrument.engine_type,
          'singlePitch', instrument.single_pitch,
          'rangeLower', instrument.range_lower,
          'rangeUpper', instrument.range_upper,
          'filePathReference', instrument.file_path_reference,
          'fileNameReferences', instrument.file_name_references,
          'pitchContents', instrument.pitch_contents,
          'velocityLayers', instrument.velocity_layers,
          'roundRobins', instrument.round_robins,
          'micPositions', instrument.mic_positions,
          'published', instrument.published,
          'articulations', instrument.articulations,
          'effectsInstruments', instrument.effects_instruments,
          'legatoTransition', instrument.legato_transition
        )
      ) ORDER BY construct.id)
      FROM target_ids target
      JOIN public.sample_path_constructs construct ON construct.id = target.construct_id
      JOIN public.samples_original_paths source ON source.id = construct.sample_original_path_id
      JOIN public.instruments_v2 instrument ON instrument.id = construct.instrument_v2_id
      JOIN public.contributors contributor ON contributor.id = instrument.contributor_id
      WHERE contributor.slug = btrim(p_contributor_slug)
        AND instrument.id = target.instrument_v2_id
        AND source.id = target.sample_original_path_id
    ), '[]'::jsonb),
    'instrumentConstructs', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', construct.id,
        'instrumentV2Id', construct.instrument_v2_id,
        'sampleOriginalPathId', construct.sample_original_path_id,
        'midiNote', construct.midi_note,
        'filename', construct.filename,
        'pitchContent', construct.pitch_content,
        'velocity', construct.velocity,
        'roundRobin', construct.round_robin,
        'micPosition', coalesce(nullif(btrim(construct.mic_position), ''), 'main'),
        'playbackType', construct.playback_type
      ) ORDER BY construct.id)
      FROM public.sample_path_constructs construct
      WHERE construct.instrument_v2_id IN (
        SELECT instrument_v2_id FROM target_ids
      )
    ), '[]'::jsonb),
    'sourceConstructs', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', construct.id,
        'instrumentV2Id', construct.instrument_v2_id,
        'sampleOriginalPathId', construct.sample_original_path_id
      ) ORDER BY construct.id)
      FROM public.sample_path_constructs construct
      WHERE construct.sample_original_path_id IN (
        SELECT sample_original_path_id FROM target_ids
      )
    ), '[]'::jsonb),
    'inboundRelationships', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', consumer.id,
        'articulations', consumer.articulations,
        'effectsInstruments', consumer.effects_instruments,
        'legatoTransition', consumer.legato_transition
      ) ORDER BY consumer.id)
      FROM public.instruments_v2 consumer
      WHERE EXISTS (
        SELECT 1 FROM target_ids target
        WHERE target.instrument_v2_id = ANY(COALESCE(consumer.articulations, ARRAY[]::uuid[]))
           OR target.instrument_v2_id = ANY(COALESCE(consumer.effects_instruments, ARRAY[]::uuid[]))
           OR consumer.legato_transition = target.instrument_v2_id
      )
    ), '[]'::jsonb),
    'legacyAliases', COALESCE((
      SELECT jsonb_agg(to_jsonb(alias_row) ORDER BY alias_row.id)
      FROM public.instrument_v2_legacy_map alias_row
      WHERE alias_row.instrument_v2_id IN (
        SELECT instrument_v2_id FROM target_ids
      )
    ), '[]'::jsonb),
    'promotionMap', COALESCE((
      SELECT jsonb_agg(to_jsonb(promotion) ORDER BY promotion.id)
      FROM public.sip_review_promotion_map promotion
      WHERE promotion.instrument_v2_id IN (
        SELECT instrument_v2_id FROM target_ids
      )
    ), '[]'::jsonb),
    'reviewInstruments', COALESCE((
      SELECT jsonb_agg(to_jsonb(review) ORDER BY review.id)
      FROM public.sip_review_instrument review
      WHERE review.id IN (SELECT sip_review_instrument_id FROM staging_ids)
    ), '[]'::jsonb),
    'reviewOverrides', COALESCE((
      SELECT jsonb_agg(to_jsonb(override_row) ORDER BY override_row.id)
      FROM public.sip_review_sample_override override_row
      WHERE override_row.sip_review_instrument_id IN (
        SELECT sip_review_instrument_id FROM staging_ids
      )
    ), '[]'::jsonb)
  )
$$;


ALTER FUNCTION "public"."sip_build_source_pitchless_snapshot_v1"("p_contributor_slug" "text", "p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_completion_identity_digest_v1"("p_identities" "text"[]) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT encode(
    extensions.digest(
      convert_to(
        to_jsonb(coalesce(p_identities, ARRAY[]::text[]))::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;


ALTER FUNCTION "public"."sip_completion_identity_digest_v1"("p_identities" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_completion_inventory_item_insert_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_completion_inventory_receipt receipt
    WHERE receipt.id = NEW.receipt_id
      AND receipt.created_at = now()
  ) THEN
    RAISE EXCEPTION 'inventory items must be inserted with their receipt'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sip_completion_inventory_item_insert_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_completion_materialization_rehearsal_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'completion materialization rehearsal is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF OLD.lifecycle_status = 'rehearsed'
    AND NEW.lifecycle_status IN ('applying', 'failed', 'superseded')
    AND to_jsonb(NEW) - 'lifecycle_status' - 'updated_at'
      = to_jsonb(OLD) - 'lifecycle_status' - 'updated_at'
  THEN
    NEW.updated_at := now();
    RETURN NEW;
  END IF;
  IF OLD.lifecycle_status = 'applying'
    AND NEW.lifecycle_status IN ('completed', 'failed')
    AND to_jsonb(NEW) - 'lifecycle_status' - 'updated_at'
      = to_jsonb(OLD) - 'lifecycle_status' - 'updated_at'
  THEN
    NEW.updated_at := now();
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'completion materialization rehearsal transition is not allowed'
    USING ERRCODE = '55000';
END;
$$;


ALTER FUNCTION "public"."sip_completion_materialization_rehearsal_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_completion_projection_delivery_status_v1"("p_provider_scope_key" "text", "p_projection_ids" "uuid"[], "p_limit" integer) RETURNS TABLE("completion_projection_id" "uuid", "projection_key" "text", "target_instrument_v2_id" "uuid", "publish_current" boolean, "upload_current" boolean, "readiness_current" boolean, "analysis_current" boolean, "audio_profile_current" boolean, "runtime_current" boolean, "object_receipts_present" boolean, "anchor_current" boolean, "delivery_complete" boolean, "delivery_blockers" "text"[])
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  v_candidate_ids uuid[];
BEGIN
  IF nullif(btrim(p_provider_scope_key), '') IS NULL THEN
    RAISE EXCEPTION 'provider scope is required';
  END IF;
  IF p_projection_ids IS NULL OR cardinality(p_projection_ids) = 0 THEN
    RAISE EXCEPTION 'an explicit projection selector is required';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'limit must be between 1 and 100';
  END IF;

  SELECT array_agg(page.id ORDER BY page.projection_key, page.id)
  INTO v_candidate_ids
  FROM (
    SELECT projection.id, projection.projection_key
    FROM public.sip_completion_projection projection
    WHERE projection.provider_scope_key = p_provider_scope_key
      AND projection.id = ANY(p_projection_ids)
    ORDER BY projection.projection_key, projection.id
    LIMIT p_limit
  ) page;

  IF coalesce(cardinality(v_candidate_ids), 0) > p_limit THEN
    RAISE EXCEPTION 'candidate bound violated';
  END IF;
  IF coalesce(cardinality(v_candidate_ids), 0) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH candidates AS MATERIALIZED (
    SELECT
      projection.id,
      projection.provider_scope_key,
      projection.projection_key,
      projection.current_instrument_v2_id,
      projection.runtime_exception_artifact_id,
      selected.ordinality
    FROM unnest(v_candidate_ids) WITH ORDINALITY AS selected(id, ordinality)
    JOIN public.sip_completion_projection projection
      ON projection.id = selected.id
  ),
  exact_base AS MATERIALIZED (
    SELECT
      candidate.*,
      coalesce(
        public.is_current_instrument_v2_readiness_snapshot_v2(
          candidate.current_instrument_v2_id,
          readiness.snapshot_sha256
        ),
        false
      ) AS exact_readiness_current,
      coalesce(analysis.ready, false)
        AND public.published_sample_temporal_ready_for_profile_v1(
          candidate.current_instrument_v2_id
        ) AS exact_analysis_current,
      (
        profile.source_signature IS NOT NULL
        AND profile.source_signature =
          public.compute_instrument_audio_profile_signature_v1(
            candidate.current_instrument_v2_id,
            'audio-profile-v1'
          )
      ) AS exact_audio_profile_current,
      readiness.snapshot_sha256 AS exact_readiness_snapshot_sha256,
      coalesce(
        upload.publish_actions_applied
        AND upload.publish_status = 'completed'
        AND upload.samples_total > 0
        AND upload.samples_processed = upload.samples_total
        AND upload.samples_total = (
          SELECT count(*)
          FROM public.sample_path_constructs construct
          WHERE construct.instrument_v2_id =
            candidate.current_instrument_v2_id
        ),
        false
      ) AS exact_upload_current,
      coalesce(upload.runtime_verification_status = 'passed', false)
        AS exact_direct_runtime_current,
      (
        EXISTS (
          SELECT 1
          FROM public.sample_path_constructs construct
          WHERE construct.instrument_v2_id =
            candidate.current_instrument_v2_id
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.sample_path_constructs construct
          WHERE construct.instrument_v2_id =
            candidate.current_instrument_v2_id
            AND NOT EXISTS (
              SELECT 1
              FROM public.instrument_v2_publish_output_manifest manifest
              WHERE manifest.sample_path_construct_id = construct.id
                AND manifest.instrument_v2_id =
                  candidate.current_instrument_v2_id
                AND manifest.original_sample_id =
                  construct.sample_original_path_id
                AND manifest.fingerprint_schema = 'sip-v2-output-v2'
                AND jsonb_typeof(manifest.output_object_identity) = 'object'
                AND nullif(
                  btrim(manifest.output_object_identity->>'eTag'),
                  ''
                ) IS NOT NULL
                AND jsonb_typeof(
                  manifest.output_object_identity->'contentLength'
                ) = 'number'
                AND (
                  manifest.output_object_identity->>'contentLength'
                )::numeric >= 0
                AND manifest.processed_at >= construct.updated_at
                AND manifest.processing_input->>'fingerprintSchema' =
                  'sip-v2-output-v2'
                AND manifest.processing_input->>'instrumentV2Id' =
                  candidate.current_instrument_v2_id::text
                AND manifest.processing_input->>'samplePathConstructId' =
                  construct.id::text
                AND manifest.processing_input->>'originalSampleId' =
                  construct.sample_original_path_id::text
                AND manifest.processing_input->'target'->>'s3Key' =
                  manifest.destination_s3_key
                AND manifest.processing_input->'target'->>'format' =
                  manifest.format
                AND manifest.processing_input->'target'->>'quality' =
                  manifest.quality::text
              GROUP BY manifest.sample_path_construct_id
              HAVING count(DISTINCT (manifest.format, manifest.quality)) = 9
                AND count(*) FILTER (
                  WHERE manifest.format = 'mp3'
                    AND manifest.quality BETWEEN 1 AND 5
                ) = 5
                AND count(*) FILTER (
                  WHERE manifest.format = 'ogg'
                    AND manifest.quality BETWEEN 2 AND 5
                ) = 4
            )
          )
      ) AS exact_object_receipts_present,
      coalesce(instrument.published, false) AS exact_published,
      coalesce((
        NOT (
          instrument.engine_type = 'tonal'
          AND instrument.single_pitch IS NULL
        )
        OR public.is_canonical_sampled_midi_notes_v1(
          instrument.sampled_midi_notes
        )
      ), false) AS exact_anchor_current,
      coalesce(delivery.missing_construct_count, 0)
        AS exact_missing_construct_count,
      coalesce(delivery.foreign_construct_count, 0)
        AS exact_foreign_construct_count
    FROM candidates candidate
    LEFT JOIN LATERAL (
      SELECT receipt.snapshot_sha256
      FROM public.instrument_v2_deterministic_readiness receipt
      WHERE receipt.instrument_v2_id = candidate.current_instrument_v2_id
        AND receipt.status IN (
          'full_grid_deterministic',
          'exception_approved'
        )
      ORDER BY receipt.updated_at DESC, receipt.id DESC
      LIMIT 1
    ) readiness ON true
    LEFT JOIN LATERAL
      public.published_sample_analysis_ready_for_profile_v1(
        candidate.current_instrument_v2_id
      ) analysis ON true
    LEFT JOIN public.instrument_audio_profile_v1 profile
      ON profile.instrument_v2_id = candidate.current_instrument_v2_id
     AND profile.profile_version = 'audio-profile-v1'
    LEFT JOIN public.instrument_v2_upload_status upload
      ON upload.instrument_v2_id = candidate.current_instrument_v2_id
    LEFT JOIN public.instruments_v2 instrument
      ON instrument.id = candidate.current_instrument_v2_id
    LEFT JOIN public.sip_completion_projection_delivery_v1 delivery
      ON delivery.completion_projection_id = candidate.id
  ),
  exact AS MATERIALIZED (
    SELECT
      exact_base.*,
      (
        exact_base.exact_direct_runtime_current
        OR coalesce((
          artifact.id IS NOT NULL
          AND artifact.artifact_kind =
            'sip-completion-runtime-exception-v1'
          AND artifact.provider_slug = exact_base.provider_scope_key
          AND approval.artifact_id = artifact.id
          AND approval.content_hash = artifact.content_hash
          AND artifact.content->>'completionProjectionId' =
            exact_base.id::text
          AND artifact.content->>'currentInstrumentV2Id' =
            exact_base.current_instrument_v2_id::text
          AND artifact.content->>'deliverySnapshotSha256' = encode(
            extensions.digest(
              convert_to(
                jsonb_build_object(
                  'projectionId', exact_base.id,
                  'currentInstrumentV2Id',
                    exact_base.current_instrument_v2_id,
                  'readinessSnapshotSha256',
                    exact_base.exact_readiness_snapshot_sha256,
                  'readinessCurrent',
                    exact_base.exact_readiness_current,
                  'uploadCurrent', exact_base.exact_upload_current,
                  'analysisCurrent',
                    exact_base.exact_analysis_current,
                  'audioProfileCurrent',
                    exact_base.exact_audio_profile_current,
                  'objectReceiptsPresent',
                    exact_base.exact_object_receipts_present,
                  'anchorCurrent', exact_base.exact_anchor_current,
                  'published', exact_base.exact_published,
                  'missingConstructCount',
                    exact_base.exact_missing_construct_count,
                  'foreignConstructCount',
                    exact_base.exact_foreign_construct_count
                )::text,
                'UTF8'
              ),
              'sha256'
            ),
            'hex'
          )
        ), false)
      ) AS exact_runtime_current
    FROM exact_base
    LEFT JOIN public.sip_fleet_plan_artifacts artifact
      ON artifact.id = exact_base.runtime_exception_artifact_id
    LEFT JOIN public.sip_fleet_plan_artifact_approvals approval
      ON approval.artifact_id = artifact.id
  )
  SELECT
    exact.id,
    exact.projection_key,
    exact.current_instrument_v2_id,
    exact.exact_published,
    exact.exact_upload_current,
    exact.exact_readiness_current,
    exact.exact_analysis_current,
    exact.exact_audio_profile_current,
    exact.exact_runtime_current,
    exact.exact_object_receipts_present,
    exact.exact_anchor_current,
    (
      exact.exact_readiness_current
      AND exact.exact_upload_current
      AND exact.exact_analysis_current
      AND exact.exact_audio_profile_current
      AND exact.exact_runtime_current
      AND exact.exact_object_receipts_present
      AND exact.exact_anchor_current
      AND exact.exact_published
      AND exact.exact_missing_construct_count = 0
      AND exact.exact_foreign_construct_count = 0
    ),
    array_remove(ARRAY[
      CASE
        WHEN NOT exact.exact_upload_current THEN 'upload_not_current'
      END,
      CASE
        WHEN NOT exact.exact_readiness_current THEN 'readiness_not_current'
      END,
      CASE
        WHEN NOT exact.exact_analysis_current THEN 'analysis_not_current'
      END,
      CASE
        WHEN NOT exact.exact_audio_profile_current
          THEN 'audio_profile_not_current'
      END,
      CASE
        WHEN NOT exact.exact_runtime_current THEN 'runtime_not_current'
      END,
      CASE
        WHEN NOT exact.exact_object_receipts_present
          THEN 'object_receipts_missing'
      END,
      CASE
        WHEN NOT exact.exact_anchor_current THEN 'anchor_not_current'
      END,
      CASE WHEN NOT exact.exact_published THEN 'not_published' END,
      CASE
        WHEN exact.exact_missing_construct_count > 0
          THEN 'missing_construct'
      END,
      CASE
        WHEN exact.exact_foreign_construct_count > 0
          THEN 'foreign_construct'
      END
    ]::text[], NULL)
  FROM exact
  ORDER BY exact.ordinality;
END;
$$;


ALTER FUNCTION "public"."sip_completion_projection_delivery_status_v1"("p_provider_scope_key" "text", "p_projection_ids" "uuid"[], "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_completion_projection_identity_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF OLD.provider_scope_key IS DISTINCT FROM NEW.provider_scope_key
    OR OLD.projection_key IS DISTINCT FROM NEW.projection_key
  THEN
    RAISE EXCEPTION 'completion projection identity is immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sip_completion_projection_identity_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_completion_registry_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft'
      OR NEW.source_count IS NOT NULL
      OR NEW.intended_projection_count IS NOT NULL
      OR NEW.intended_membership_count IS NOT NULL
      OR NEW.source_identity_sha256 IS NOT NULL
      OR NEW.projection_identity_sha256 IS NOT NULL
      OR NEW.membership_identity_sha256 IS NOT NULL
      OR NEW.frozen_by IS NOT NULL
      OR NEW.frozen_at IS NOT NULL
      OR NEW.superseded_at IS NOT NULL
    THEN
      RAISE EXCEPTION 'completion registry must be inserted as a clean draft'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'completion registry is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF OLD.status = 'draft' AND NEW.status IN ('draft', 'frozen') THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'frozen'
    AND NEW.status = 'superseded'
    AND NEW.superseded_at IS NOT NULL
    AND to_jsonb(NEW) - 'status' - 'superseded_at'
      = to_jsonb(OLD) - 'status' - 'superseded_at'
  THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'completion registry transition is not allowed'
    USING ERRCODE = '55000';
END;
$$;


ALTER FUNCTION "public"."sip_completion_registry_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_completion_reject_mutation_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  RAISE EXCEPTION '% is immutable', TG_TABLE_NAME
    USING ERRCODE = '55000';
END;
$$;


ALTER FUNCTION "public"."sip_completion_reject_mutation_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_completion_seed_source_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  INSERT INTO public.sip_completion_source (
    sample_original_path_id,
    rights_status,
    rights_resolution_version,
    rights_evidence
  ) VALUES (
    NEW.id,
    CASE
      WHEN NEW.licensing_secured THEN 'legacy_allowed_unverified'
      ELSE 'legacy_blocked_unverified'
    END,
    'legacy-licensing-flag-v1',
    jsonb_build_object(
      'source', 'samples_original_paths.licensing_secured',
      'legacyValue', NEW.licensing_secured
    )
  )
  ON CONFLICT (sample_original_path_id) DO NOTHING;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sip_completion_seed_source_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_completion_validate_inventory_receipt_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_matched bigint;
  v_inventory_only bigint;
  v_database_only bigint;
  v_inventory_hash text;
  v_database_hash text;
BEGIN
  SELECT
    count(*) FILTER (WHERE parity_status = 'matched'),
    count(*) FILTER (WHERE parity_status = 'inventory_only'),
    count(*) FILTER (WHERE parity_status = 'database_only'),
    public.sip_completion_identity_digest_v1(
      array_agg(normalized_path ORDER BY normalized_path COLLATE "C")
        FILTER (WHERE parity_status IN ('matched', 'inventory_only'))
    ),
    public.sip_completion_identity_digest_v1(
      array_agg(normalized_path ORDER BY normalized_path COLLATE "C")
        FILTER (WHERE parity_status IN ('matched', 'database_only'))
    )
  INTO
    v_matched,
    v_inventory_only,
    v_database_only,
    v_inventory_hash,
    v_database_hash
  FROM public.sip_completion_inventory_item
  WHERE receipt_id = NEW.id;

  IF coalesce(v_matched, 0) <> NEW.matched_count
    OR coalesce(v_inventory_only, 0) <> NEW.inventory_only_count
    OR coalesce(v_database_only, 0) <> NEW.database_only_count
    OR v_inventory_hash <> NEW.inventory_sorted_path_sha256
    OR v_database_hash <> NEW.database_sorted_path_sha256
  THEN
    RAISE EXCEPTION 'inventory receipt counts or digests do not match items'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sip_completion_validate_inventory_receipt_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_fence_fleet_admission_during_versioned_prefix_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(NEW.provider_slug),0));
  IF EXISTS (
    SELECT 1 FROM public.sip_versioned_output_prefix_staging_operations operation
    WHERE operation.provider_slug=btrim(NEW.provider_slug)
      AND (operation.status='running' OR (operation.status='ambiguous' AND NOT EXISTS (
        SELECT 1 FROM public.sip_versioned_output_prefix_premutation_reconciliation_receipts clearance
        WHERE clearance.staging_operation_id=operation.id
      )))
  ) THEN RAISE EXCEPTION 'versioned_output_prefix_staging_active'; END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."sip_fence_fleet_admission_during_versioned_prefix_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_fence_legacy_pipeline_admission_during_versioned_prefix_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(NEW.contributor_slug),0));
  IF EXISTS (
    SELECT 1 FROM public.sip_versioned_output_prefix_staging_operations operation
    WHERE operation.provider_slug=btrim(NEW.contributor_slug)
      AND (operation.status='running' OR (operation.status='ambiguous' AND NOT EXISTS (
        SELECT 1 FROM public.sip_versioned_output_prefix_premutation_reconciliation_receipts clearance
        WHERE clearance.staging_operation_id=operation.id
      )))
  ) THEN RAISE EXCEPTION 'versioned_output_prefix_staging_active'; END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."sip_fence_legacy_pipeline_admission_during_versioned_prefix_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_fleet_active_run_count_v1"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT count(DISTINCT run_id)::integer
  FROM public.sip_fleet_run_items
  WHERE status IN ('queued', 'running');
$$;


ALTER FUNCTION "public"."sip_fleet_active_run_count_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_fleet_reject_immutable_change_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  IF TG_OP = 'DELETE' AND OLD.artifact_kind = 'durable-canary' THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'immutable_coordinator_artifact';
END $$;


ALTER FUNCTION "public"."sip_fleet_reject_immutable_change_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_fmg_terminal_profile_wait_repair_manifest_hash_v1"("p_manifest" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT encode(extensions.digest(convert_to(
    '{"version":' || to_json(p_manifest->>'version')::text
    || ',"instrumentV2Ids":' || (
      SELECT '[' || coalesce(string_agg(to_json(value)::text, ',' ORDER BY ordinal), '') || ']'
      FROM jsonb_array_elements_text(p_manifest->'instrumentV2Ids')
        WITH ORDINALITY AS entry(value, ordinal)
    )
    || ',"samplePathConstructIds":' || (
      SELECT '[' || coalesce(string_agg(to_json(value)::text, ',' ORDER BY ordinal), '') || ']'
      FROM jsonb_array_elements_text(p_manifest->'samplePathConstructIds')
        WITH ORDINALITY AS entry(value, ordinal)
    )
    || ',"sampleOriginalPathIds":' || (
      SELECT '[' || coalesce(string_agg(to_json(value)::text, ',' ORDER BY ordinal), '') || ']'
      FROM jsonb_array_elements_text(p_manifest->'sampleOriginalPathIds')
        WITH ORDINALITY AS entry(value, ordinal)
    )
    || ',"publishedAssetIds":' || (
      SELECT '[' || coalesce(string_agg(to_json(value)::text, ',' ORDER BY ordinal), '') || ']'
      FROM jsonb_array_elements_text(p_manifest->'publishedAssetIds')
        WITH ORDINALITY AS entry(value, ordinal)
    )
    || ',"publishedAssetSignatures":' || (
      SELECT '[' || coalesce(string_agg(to_json(value)::text, ',' ORDER BY ordinal), '') || ']'
      FROM jsonb_array_elements_text(p_manifest->'publishedAssetSignatures')
        WITH ORDINALITY AS entry(value, ordinal)
    )
    || '}', 'UTF8'
  ), 'sha256'), 'hex');
$$;


ALTER FUNCTION "public"."sip_fmg_terminal_profile_wait_repair_manifest_hash_v1"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_fmg_terminal_profile_wait_snapshot_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH expected(
    ordinal,
    predecessor_run_id,
    predecessor_item_id,
    predecessor_run_status,
    predecessor_cancel_requested,
    successor_run_id,
    successor_item_id,
    instrument_v2_id,
    plan_mode,
    repair_manifest_hash,
    predecessor_pipeline_run_id,
    successor_pipeline_run_id,
    expected_readiness_snapshot_hash,
    expected_asset_count,
    expected_historical_output_count,
    expected_output_count,
    expected_legacy_v2_output_count,
    expected_legacy_identity_output_count,
    canonical_instrument_v2_id,
    canonical_pipeline_run_id,
    canonical_profile_signature,
    successor_profile_signature,
    sibling_receipt_id,
    source_instrument_published,
    reconciled_item_status
  ) AS (
    VALUES
      (
        1,
        'f5216bfa-19e7-424d-b382-d7166913ffb1'::uuid,
        '29bce41a-f448-4478-bf97-01edac4d34d1'::uuid,
        'canceled'::text,
        true,
        'd017893c-c6e7-45e6-927a-d01ee1bffc10'::uuid,
        '221423ed-1268-488f-abd6-90c4f55182cf'::uuid,
        'd822b904-ab46-4ed6-87d3-f414798606be'::uuid,
        'sibling-consolidation'::text,
        '845b887bba0e1cfc71f544ffc9b4ee44db642e4759b1dbfdc171c4903769d772'::text,
        'run-1784871607562-g4zoko'::text,
        'run-1784875180655-tseoxq'::text,
        'f55d2dbec62620f9b63c250ab24af84ad9ead863172990710eb4280ec068b138'::text,
        2,
        18,
        18,
        0,
        2,
        'd822b904-ab46-4ed6-87d3-f414798606be'::uuid,
        'run-1784875180655-tseoxq'::text,
        'apv1:sha256-v1:bd24d0f395017ae14107e3640f839e5ad000d86ee3132879fef91c00ba275909'::text,
        'apv1:sha256-v1:bd24d0f395017ae14107e3640f839e5ad000d86ee3132879fef91c00ba275909'::text,
        NULL::uuid,
        true,
        'canceled'::text
      ),
      (
        2,
        '7d5d825d-c648-4af8-9a46-b00c51285cb1'::uuid,
        '854e9736-5f7d-46b0-86c6-e5f0a7903929'::uuid,
        'failed'::text,
        false,
        '92aa0c66-0a4f-4b9b-b0b5-afef1f6e696b'::uuid,
        '0e2de10f-df83-4f6c-b189-88f7ec9e8d85'::uuid,
        '88821d01-71d6-438d-a0d1-8595789c9f85'::uuid,
        'semantic-staged-promotion'::text,
        '8ae37668f1cbb1acaa57366b15f491f4c3db803b3dc0b052a0800046f2c3893d'::text,
        'run-1784918283344-2ywaua'::text,
        'run-1784918411703-lv3uge'::text,
        'fc70aaca884216030490b524fcbc6c15ff18af285ec4220817b382226fd50b12'::text,
        1,
        9,
        36,
        0,
        4,
        'b8385e49-99ff-493b-947b-ab750af97c94'::uuid,
        'run-1784921324673-rhmx3u'::text,
        'apv1:sha256-v1:253ce39af290b0161e4d9fbca172f88bda2078364d90311ab99994e91220bee3'::text,
        'apv1:sha256-v1:5d35faa7757bb21a0b7d228f0a2b8ef4565a87c68161e65baaac1331c9bc60b0'::text,
        '8d805a71-b926-466e-8858-eb71e648da16'::uuid,
        false,
        'failed'::text
      )
  ), observed AS (
    SELECT
      expected.*,
      predecessor_run.provider_slug AS predecessor_provider_slug,
      predecessor_run.status AS observed_predecessor_run_status,
      predecessor_run.cancel_requested AS observed_predecessor_cancel_requested,
      predecessor_run.created_at AS predecessor_created_at,
      predecessor_run.finished_at AS predecessor_finished_at,
      predecessor_run.idempotency_key AS predecessor_idempotency_key,
      predecessor_run.admission_fingerprint AS predecessor_admission_fingerprint,
      predecessor_artifact.id AS predecessor_artifact_id,
      predecessor_artifact.content_hash AS predecessor_artifact_hash,
      predecessor_artifact.content->>'mode' AS predecessor_plan_mode,
      predecessor_artifact.content->>'forceRerun' AS predecessor_force_rerun,
      predecessor_item.run_id AS observed_predecessor_item_run_id,
      predecessor_item.instrument_v2_id AS predecessor_instrument_v2_id,
      predecessor_item.status AS observed_predecessor_item_status,
      predecessor_item.created_at AS predecessor_item_created_at,
      predecessor_item.finished_at AS predecessor_item_finished_at,
      predecessor_item.result_payload AS predecessor_result_payload,
      predecessor_item.payload AS predecessor_item_payload,
      successor_run.provider_slug AS successor_provider_slug,
      successor_run.status AS observed_successor_run_status,
      successor_run.cancel_requested AS observed_successor_cancel_requested,
      successor_run.created_at AS successor_created_at,
      successor_run.finished_at AS successor_finished_at,
      successor_run.idempotency_key AS successor_idempotency_key,
      successor_run.admission_fingerprint AS successor_admission_fingerprint,
      successor_artifact.id AS successor_artifact_id,
      successor_artifact.content_hash AS successor_artifact_hash,
      successor_artifact.content->>'mode' AS successor_plan_mode,
      successor_artifact.content->>'forceRerun' AS successor_force_rerun,
      successor_item.run_id AS observed_successor_item_run_id,
      successor_item.instrument_v2_id AS successor_instrument_v2_id,
      successor_item.status AS observed_successor_item_status,
      successor_item.created_at AS successor_item_created_at,
      successor_item.finished_at AS successor_item_finished_at,
      successor_item.result_payload AS successor_result_payload,
      successor_item.payload AS successor_item_payload,
      source_instrument.published AS observed_source_instrument_published,
      canonical.published AS canonical_published,
      canonical_contributor.slug AS canonical_provider_slug,
      canonical_constructs.construct_count AS canonical_construct_count,
      profile.current_source_signature AS current_profile_signature,
      profile.profile_source_signature AS persisted_profile_signature,
      profile.profile_state AS current_profile_state,
      profile.latest_job_status AS current_profile_job_status,
      sibling.id AS observed_sibling_receipt_id,
      sibling.provider_slug AS sibling_provider_slug,
      sibling.canonical_instrument_v2_id AS sibling_canonical_instrument_v2_id,
      sibling.source_instrument_v2_ids AS sibling_source_instrument_v2_ids,
      sibling.publish_run_id AS sibling_publish_run_id,
      sibling.status AS sibling_status,
      sibling.closeout_status AS sibling_closeout_status,
      sibling.closeout_completed_at AS sibling_closeout_completed_at,
      sibling.manifest_hash AS sibling_manifest_hash,
      sibling.projection_hash AS sibling_projection_hash,
      sibling.manifest AS sibling_manifest,
      sibling_projection.projection_row_count AS sibling_projection_row_count,
      sibling_projection.source_instrument_v2_id AS sibling_projection_source_instrument_v2_id,
      sibling_projection.source_construct_id AS sibling_projection_source_construct_id,
      sibling_projection.sample_original_path_id AS sibling_projection_sample_original_path_id,
      sibling_projection.target_instrument_v2_id AS sibling_projection_target_instrument_v2_id,
      sibling_projection.disposition AS sibling_projection_disposition,
      sibling_projection.status AS sibling_projection_status,
      historical_upload.publish_status AS historical_publish_status,
      historical_upload.runtime_verification_status AS historical_runtime_verification_status,
      historical_upload.runtime_verification_report_path AS historical_runtime_verification_report_path,
      historical_upload.runtime_verification_completed_at AS historical_runtime_verification_completed_at,
      canonical_upload.publish_status AS canonical_publish_status,
      canonical_upload.runtime_verification_status AS canonical_runtime_verification_status,
      canonical_upload.runtime_verification_report_path AS canonical_runtime_verification_report_path,
      canonical_upload.runtime_verification_completed_at AS canonical_runtime_verification_completed_at,
      historical_outputs.output_count AS historical_output_count,
      historical_outputs.completed_output_count AS historical_completed_output_count,
      historical_outputs.distinct_destination_count AS historical_distinct_destination_count,
      historical_outputs.output_snapshot_hash AS historical_output_snapshot_hash,
      outputs.output_count,
      outputs.completed_output_count,
      outputs.identity_output_count,
      outputs.v2_output_count,
      outputs.distinct_destination_count,
      outputs.output_snapshot_hash
    FROM expected
    LEFT JOIN public.sip_fleet_runs predecessor_run
      ON predecessor_run.id = expected.predecessor_run_id
    LEFT JOIN public.sip_fleet_plan_artifacts predecessor_artifact
      ON predecessor_artifact.id = predecessor_run.plan_artifact_id
    LEFT JOIN public.sip_fleet_run_items predecessor_item
      ON predecessor_item.id = expected.predecessor_item_id
    LEFT JOIN public.sip_fleet_runs successor_run
      ON successor_run.id = expected.successor_run_id
    LEFT JOIN public.sip_fleet_plan_artifacts successor_artifact
      ON successor_artifact.id = successor_run.plan_artifact_id
    LEFT JOIN public.sip_fleet_run_items successor_item
      ON successor_item.id = expected.successor_item_id
    LEFT JOIN public.instruments_v2 source_instrument
      ON source_instrument.id = expected.instrument_v2_id
    LEFT JOIN public.instruments_v2 canonical
      ON canonical.id = expected.canonical_instrument_v2_id
    LEFT JOIN public.contributors canonical_contributor
      ON canonical_contributor.id = canonical.contributor_id
    LEFT JOIN LATERAL (
      SELECT count(*)::integer AS construct_count
      FROM public.sample_path_constructs construct
      WHERE construct.instrument_v2_id = expected.canonical_instrument_v2_id
    ) canonical_constructs ON true
    LEFT JOIN LATERAL public.instrument_audio_profile_status_v1(
      ARRAY[expected.canonical_instrument_v2_id],
      'fallout-music-group', 'audio-profile-v1', 1, true
    ) profile ON true
    LEFT JOIN public.sip_sibling_consolidation_receipts_v2 sibling
      ON sibling.id = expected.sibling_receipt_id
    LEFT JOIN LATERAL (
      SELECT
        count(*) OVER ()::integer AS projection_row_count,
        projection.source_instrument_v2_id,
        projection.source_construct_id,
        projection.sample_original_path_id,
        projection.target_instrument_v2_id,
        projection.disposition,
        projection.status
      FROM public.sip_sibling_consolidation_projection_v2 projection
      WHERE projection.receipt_id = expected.sibling_receipt_id
        AND projection.source_instrument_v2_id = expected.instrument_v2_id
    ) sibling_projection ON true
    LEFT JOIN public.instrument_v2_upload_status historical_upload
      ON historical_upload.instrument_v2_id = expected.instrument_v2_id
    LEFT JOIN public.instrument_v2_upload_status canonical_upload
      ON canonical_upload.instrument_v2_id = expected.canonical_instrument_v2_id
    LEFT JOIN LATERAL (
      SELECT
        count(*)::integer AS output_count,
        count(*) FILTER (WHERE manifest.status = 'completed')::integer
          AS completed_output_count,
        count(DISTINCT manifest.destination_s3_key)::integer
          AS distinct_destination_count,
        encode(extensions.digest(convert_to(
          coalesce(
            jsonb_agg(to_jsonb(manifest) ORDER BY manifest.destination_s3_key),
            '[]'::jsonb
          )::text,
          'UTF8'
        ), 'sha256'), 'hex') AS output_snapshot_hash
      FROM public.instrument_v2_publish_output_manifest manifest
      WHERE manifest.instrument_v2_id = expected.instrument_v2_id
        AND manifest.run_id = expected.successor_pipeline_run_id
    ) historical_outputs ON true
    LEFT JOIN LATERAL (
      SELECT
        count(*)::integer AS output_count,
        count(*) FILTER (WHERE manifest.status = 'completed')::integer
          AS completed_output_count,
        count(*) FILTER (
          WHERE jsonb_typeof(manifest.output_object_identity) = 'object'
            AND btrim(coalesce(manifest.output_object_identity->>'eTag', '')) <> ''
            AND coalesce((manifest.output_object_identity->>'contentLength')::bigint, 0) > 0
            AND (
              btrim(coalesce(manifest.output_object_identity->>'versionId', '')) <> ''
              OR btrim(coalesce(manifest.output_object_identity->>'lastModified', '')) <> ''
            )
        )::integer AS identity_output_count,
        count(*) FILTER (
          WHERE manifest.fingerprint_schema = 'sip-v2-output-v2'
            AND manifest.processing_input->>'fingerprintSchema' = 'sip-v2-output-v2'
        )::integer AS v2_output_count,
        count(DISTINCT manifest.destination_s3_key)::integer
          AS distinct_destination_count,
        encode(extensions.digest(convert_to(
          coalesce(
            jsonb_agg(to_jsonb(manifest) ORDER BY manifest.destination_s3_key),
            '[]'::jsonb
          )::text,
          'UTF8'
        ), 'sha256'), 'hex') AS output_snapshot_hash
      FROM public.instrument_v2_publish_output_manifest manifest
      WHERE manifest.instrument_v2_id = expected.canonical_instrument_v2_id
        AND manifest.run_id = expected.canonical_pipeline_run_id
    ) outputs ON true
  ), targets AS (
    SELECT
      observed.*,
      (
        observed.predecessor_provider_slug = 'fallout-music-group'
        AND observed.successor_provider_slug = 'fallout-music-group'
        AND observed.observed_predecessor_run_status = observed.predecessor_run_status
        AND observed.observed_predecessor_cancel_requested
          IS NOT DISTINCT FROM observed.predecessor_cancel_requested
        AND observed.observed_predecessor_item_run_id = observed.predecessor_run_id
        AND observed.predecessor_instrument_v2_id = observed.instrument_v2_id
        AND observed.observed_predecessor_item_status = 'waiting_for_audio_profile'
        AND observed.predecessor_item_finished_at IS NULL
        AND observed.predecessor_finished_at IS NOT NULL
        AND observed.predecessor_plan_mode = observed.plan_mode
        AND observed.predecessor_force_rerun = 'true'
        AND observed.predecessor_result_payload->>'pipelineRunId'
          = observed.predecessor_pipeline_run_id
        AND observed.predecessor_result_payload->>'repairManifestHash'
          = observed.repair_manifest_hash
        AND observed.predecessor_result_payload->'repairManifest'->>'manifestHash'
          = observed.repair_manifest_hash
        AND observed.predecessor_result_payload->'repairManifest'->>'version'
          = 'deterministic-repair-audio-profile-v1'
        AND public.sip_fmg_terminal_profile_wait_repair_manifest_hash_v1(
          observed.predecessor_result_payload->'repairManifest'
        ) = observed.repair_manifest_hash
        AND observed.observed_successor_run_status = 'completed'
        AND observed.observed_successor_cancel_requested = false
        AND observed.successor_finished_at IS NOT NULL
        AND observed.successor_created_at > observed.predecessor_finished_at
        AND observed.successor_run_id <> observed.predecessor_run_id
        AND observed.successor_idempotency_key
          = observed.predecessor_idempotency_key || ':terminal-retry:1'
        AND observed.successor_artifact_id = observed.predecessor_artifact_id
        AND observed.successor_admission_fingerprint
          = observed.predecessor_admission_fingerprint
        AND observed.observed_successor_item_run_id = observed.successor_run_id
        AND observed.successor_instrument_v2_id = observed.instrument_v2_id
        AND observed.observed_successor_item_status = 'completed'
        AND observed.successor_item_finished_at IS NOT NULL
        AND observed.successor_item_created_at > observed.predecessor_finished_at
        AND observed.successor_item_finished_at >= observed.successor_item_created_at
        AND observed.successor_item_finished_at <= observed.successor_finished_at
        AND observed.successor_plan_mode = observed.plan_mode
        AND observed.successor_force_rerun = 'true'
        AND observed.successor_result_payload->>'pipelineRunId'
          = observed.successor_pipeline_run_id
        AND observed.successor_result_payload->>'repairManifestHash'
          = observed.repair_manifest_hash
        AND observed.successor_result_payload->'repairManifest'->>'manifestHash'
          = observed.repair_manifest_hash
        AND observed.successor_result_payload->'repairManifest'->>'version'
          = 'deterministic-repair-audio-profile-v1'
        AND public.sip_fmg_terminal_profile_wait_repair_manifest_hash_v1(
          observed.successor_result_payload->'repairManifest'
        ) = observed.repair_manifest_hash
        AND observed.predecessor_result_payload->'repairManifest'
          = observed.successor_result_payload->'repairManifest'
        AND observed.predecessor_item_payload = observed.successor_item_payload
        AND observed.predecessor_result_payload->>'deterministicReadinessSnapshotHash'
          = observed.successor_result_payload->>'deterministicReadinessSnapshotHash'
        AND observed.predecessor_result_payload->>'deterministicReadinessSnapshotHash'
          = observed.expected_readiness_snapshot_hash
        AND observed.successor_result_payload->'repairManifest'->'instrumentV2Ids'
          = jsonb_build_array(observed.instrument_v2_id)
        AND observed.observed_source_instrument_published
          IS NOT DISTINCT FROM observed.source_instrument_published
        AND jsonb_array_length(
          observed.successor_result_payload->'repairManifest'->'publishedAssetIds'
        ) = observed.expected_asset_count
        AND observed.successor_result_payload->'audioProfileFinalization'->>'state'
          = 'completed'
        AND observed.successor_result_payload->'audioProfileFinalization'->>'profileState'
          IN ('current', 'current_with_warnings')
        AND observed.successor_result_payload->'audioProfileFinalization'->>'profileJobStatus'
          IN ('completed', 'completed_with_warnings')
        AND observed.successor_result_payload->'audioProfileFinalization'->>'expectedSourceSignature'
          = observed.successor_profile_signature
        AND observed.canonical_published = true
        AND observed.canonical_provider_slug = 'fallout-music-group'
        AND observed.canonical_construct_count * 9 = observed.expected_output_count
        AND observed.current_profile_signature = observed.canonical_profile_signature
        AND observed.persisted_profile_signature = observed.canonical_profile_signature
        AND observed.current_profile_state IN ('current', 'current_with_warnings')
        AND observed.current_profile_job_status IN ('completed', 'completed_with_warnings')
        AND (
          observed.sibling_receipt_id IS NULL
          OR (
            observed.observed_sibling_receipt_id = observed.sibling_receipt_id
            AND observed.sibling_provider_slug = 'fallout-music-group'
            AND observed.sibling_canonical_instrument_v2_id
              = observed.canonical_instrument_v2_id
            AND observed.instrument_v2_id = ANY(observed.sibling_source_instrument_v2_ids)
            AND observed.sibling_publish_run_id
              = 'a675a000-acf0-4fe8-a239-714075c73ebf'::uuid
            AND observed.sibling_status = 'cutover'
            AND observed.sibling_closeout_status = 'completed'
            AND observed.sibling_closeout_completed_at IS NOT NULL
            AND observed.sibling_manifest_hash
              = '7386dacea143bf75fa7791254ec9caa097804fdeb8c189d36d06a650df7b9d7e'
            AND observed.sibling_projection_hash
              = 'b550a5232663a145ff983e40cf60d652ce56f5b844a1d8220fec53c21c011bb9'
            AND public.sip_sibling_consolidation_projection_hash_v2(
              observed.sibling_receipt_id
            ) = observed.sibling_projection_hash
            AND observed.sibling_projection_row_count = 1
            AND observed.sibling_projection_source_instrument_v2_id
              = observed.instrument_v2_id
            AND observed.sibling_projection_source_construct_id
              = '58ef2be7-6858-46e6-9160-b90294d7456c'::uuid
            AND observed.sibling_projection_sample_original_path_id
              = 'e6c25b89-482f-410b-ad41-c88a2c2ab803'::uuid
            AND observed.sibling_projection_target_instrument_v2_id
              = observed.canonical_instrument_v2_id
            AND observed.sibling_projection_disposition = 'active'
            AND observed.sibling_projection_status = 'cutover'
            AND observed.sibling_manifest->'activeSamples' @> jsonb_build_array(
              jsonb_build_object(
                'sourceInstrumentV2Id', observed.instrument_v2_id,
                'sourceConstructId', '58ef2be7-6858-46e6-9160-b90294d7456c',
                'targetConstructId', '58ef2be7-6858-46e6-9160-b90294d7456c',
                'sampleOriginalPathId', 'e6c25b89-482f-410b-ad41-c88a2c2ab803'
              )
            )
            AND NOT EXISTS (
              SELECT 1 FROM public.sample_path_constructs retired_construct
              WHERE retired_construct.instrument_v2_id = observed.instrument_v2_id
            )
            AND EXISTS (
              SELECT 1 FROM public.sample_path_constructs transferred_construct
              WHERE transferred_construct.id = '58ef2be7-6858-46e6-9160-b90294d7456c'::uuid
                AND transferred_construct.instrument_v2_id
                  = observed.canonical_instrument_v2_id
                AND transferred_construct.sample_original_path_id
                  = 'e6c25b89-482f-410b-ad41-c88a2c2ab803'::uuid
            )
          )
        )
        AND observed.historical_publish_status = 'completed'
        AND observed.historical_runtime_verification_status = 'passed'
        AND observed.historical_runtime_verification_report_path LIKE
          '%publish-runtime-verification-' || observed.successor_pipeline_run_id || '-%'
        AND observed.historical_runtime_verification_completed_at IS NOT NULL
        AND observed.historical_output_count = observed.expected_historical_output_count
        AND observed.historical_completed_output_count = observed.expected_historical_output_count
        AND observed.historical_distinct_destination_count = observed.expected_historical_output_count
        AND observed.canonical_publish_status = 'completed'
        AND observed.canonical_runtime_verification_status = 'passed'
        AND observed.canonical_runtime_verification_report_path LIKE
          '%publish-runtime-verification-' || observed.canonical_pipeline_run_id || '-%'
        AND observed.canonical_runtime_verification_completed_at IS NOT NULL
        AND observed.output_count = observed.expected_output_count
        AND observed.completed_output_count = observed.expected_output_count
        AND observed.identity_output_count = observed.expected_legacy_identity_output_count
        AND observed.v2_output_count = observed.expected_legacy_v2_output_count
        AND observed.distinct_destination_count = observed.expected_output_count
      ) AS evidence_complete
    FROM observed
  )
  SELECT jsonb_build_object(
    'version', 'sip-fmg-terminal-profile-wait-reconciliation-v1',
    'scopeKey', 'issue-2437-fmg-terminal-profile-waits-v1',
    'providerSlug', 'fallout-music-group',
    'operationClass', 'terminal-history-status-only',
    'readinessAuthorized', false,
    'legacyReceiptBlocker', 'address_output_receipts_incomplete',
    'targetCount', count(*),
    'targets', coalesce(jsonb_agg(jsonb_build_object(
      'predecessorRunId', predecessor_run_id,
      'predecessorItemId', predecessor_item_id,
      'predecessorRunStatus', observed_predecessor_run_status,
      'predecessorCancelRequested', observed_predecessor_cancel_requested,
      'predecessorArtifactId', predecessor_artifact_id,
      'predecessorArtifactHash', predecessor_artifact_hash,
      'predecessorPipelineRunId', predecessor_result_payload->>'pipelineRunId',
      'successorRunId', successor_run_id,
      'successorItemId', successor_item_id,
      'successorRunStatus', observed_successor_run_status,
      'successorArtifactId', successor_artifact_id,
      'successorArtifactHash', successor_artifact_hash,
      'successorPipelineRunId', successor_result_payload->>'pipelineRunId',
      'instrumentV2Id', instrument_v2_id,
      'canonicalInstrumentV2Id', canonical_instrument_v2_id,
      'canonicalPipelineRunId', canonical_pipeline_run_id,
      'canonicalProfileSignature', canonical_profile_signature,
      'siblingReceiptId', sibling_receipt_id,
      'planMode', plan_mode,
      'repairManifestHash', repair_manifest_hash,
      'profileState', successor_result_payload->'audioProfileFinalization'->>'profileState',
      'profileJobStatus', successor_result_payload->'audioProfileFinalization'->>'profileJobStatus',
      'expectedSourceSignature', successor_result_payload->'audioProfileFinalization'->>'expectedSourceSignature',
      'historicalRuntimeVerificationStatus', historical_runtime_verification_status,
      'historicalRuntimeVerificationReportPath', historical_runtime_verification_report_path,
      'historicalRuntimeVerificationCompletedAt', historical_runtime_verification_completed_at,
      'historicalOutputCount', historical_output_count,
      'historicalOutputSnapshotHash', historical_output_snapshot_hash,
      'canonicalRuntimeVerificationStatus', canonical_runtime_verification_status,
      'canonicalRuntimeVerificationReportPath', canonical_runtime_verification_report_path,
      'canonicalRuntimeVerificationCompletedAt', canonical_runtime_verification_completed_at,
      'outputCount', output_count,
      'v2OutputCount', v2_output_count,
      'identityCompleteOutputCount', identity_output_count,
      'outputSnapshotHash', output_snapshot_hash,
      'predecessorFinishedAt', predecessor_finished_at,
      'predecessorItemFinishedAt', predecessor_item_finished_at,
      'successorFinishedAt', successor_finished_at,
      'successorItemFinishedAt', successor_item_finished_at,
      'reconciledItemStatus', reconciled_item_status,
      'evidenceComplete', evidence_complete
    ) ORDER BY ordinal), '[]'::jsonb)
  )
  FROM targets;
$$;


