CREATE TABLE IF NOT EXISTS "public"."sip_completion_projection_registry" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_scope_key" "text" NOT NULL,
    "version" integer NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "inventory_receipt_id" "uuid",
    "origin_main_sha" "text" NOT NULL,
    "production_observed_at" timestamp with time zone NOT NULL,
    "normalization_version" "text" NOT NULL,
    "source_count" bigint,
    "intended_projection_count" bigint,
    "intended_membership_count" bigint,
    "source_identity_sha256" "text",
    "projection_identity_sha256" "text",
    "membership_identity_sha256" "text",
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "frozen_by" "text",
    "frozen_at" timestamp with time zone,
    "superseded_at" timestamp with time zone,
    CONSTRAINT "sip_completion_projection_registry_created_by_check" CHECK (("btrim"("created_by") <> ''::"text")),
    CONSTRAINT "sip_completion_projection_registry_frozen_fields_check" CHECK ((("status" = 'draft'::"text") OR (("source_count" IS NOT NULL) AND ("intended_projection_count" IS NOT NULL) AND ("intended_membership_count" IS NOT NULL) AND ("source_identity_sha256" ~ '^[0-9a-f]{64}$'::"text") AND ("projection_identity_sha256" ~ '^[0-9a-f]{64}$'::"text") AND ("membership_identity_sha256" ~ '^[0-9a-f]{64}$'::"text") AND (NULLIF("btrim"("frozen_by"), ''::"text") IS NOT NULL) AND ("frozen_at" IS NOT NULL)))),
    CONSTRAINT "sip_completion_projection_registry_normalization_version_check" CHECK (("btrim"("normalization_version") <> ''::"text")),
    CONSTRAINT "sip_completion_projection_registry_origin_main_sha_check" CHECK (("origin_main_sha" ~ '^[0-9a-f]{40}$'::"text")),
    CONSTRAINT "sip_completion_projection_registry_provider_scope_key_check" CHECK (("btrim"("provider_scope_key") <> ''::"text")),
    CONSTRAINT "sip_completion_projection_registry_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'frozen'::"text", 'superseded'::"text"]))),
    CONSTRAINT "sip_completion_projection_registry_version_check" CHECK (("version" > 0))
);


ALTER TABLE "public"."sip_completion_projection_registry" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_freeze_completion_projection_registry_v1"("p_registry_id" "uuid", "p_expected_source_count" bigint, "p_expected_projection_count" bigint, "p_expected_membership_count" bigint, "p_expected_source_sha256" "text", "p_expected_projection_sha256" "text", "p_expected_membership_sha256" "text", "p_frozen_by" "text") RETURNS "public"."sip_completion_projection_registry"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_registry public.sip_completion_projection_registry%ROWTYPE;
  v_source_count bigint;
  v_projection_count bigint;
  v_membership_count bigint;
  v_source_hash text;
  v_projection_hash text;
  v_membership_hash text;
BEGIN
  IF nullif(btrim(p_frozen_by), '') IS NULL THEN
    RAISE EXCEPTION 'frozen_by is required';
  END IF;

  SELECT *
  INTO STRICT v_registry
  FROM public.sip_completion_projection_registry
  WHERE id = p_registry_id
  FOR UPDATE;

  IF v_registry.status <> 'draft' THEN
    RAISE EXCEPTION 'registry must be draft';
  END IF;
  IF coalesce(v_registry.evidence->>'denominatorSource', '') = 'observed-only'
    OR nullif(v_registry.evidence->>'denominatorSource', '') IS NULL
  THEN
    RAISE EXCEPTION 'reviewed intended denominator evidence is required';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(v_registry.provider_scope_key, 0)
  );
  LOCK TABLE
    public.sip_completion_source,
    public.sip_completion_projection,
    public.sip_completion_projection_membership
  IN SHARE MODE;
  PERFORM 1
  FROM public.sip_completion_source
  WHERE canonical_provider_key = v_registry.provider_scope_key
  ORDER BY sample_original_path_id
  FOR SHARE;
  PERFORM 1
  FROM public.sip_completion_projection
  WHERE provider_scope_key = v_registry.provider_scope_key
  ORDER BY id
  FOR SHARE;
  PERFORM 1
  FROM public.sip_completion_projection_membership membership
  JOIN public.sip_completion_projection projection
    ON projection.id = membership.completion_projection_id
  WHERE projection.provider_scope_key = v_registry.provider_scope_key
  ORDER BY membership.completion_projection_id, membership.sample_original_path_id
  FOR SHARE OF membership;

  SELECT
    count(*),
    public.sip_completion_identity_digest_v1(
      array_agg(sample_original_path_id::text ORDER BY sample_original_path_id::text)
    )
  INTO v_source_count, v_source_hash
  FROM public.sip_completion_source
  WHERE canonical_provider_key = v_registry.provider_scope_key;

  SELECT
    count(*),
    public.sip_completion_identity_digest_v1(
      array_agg(projection_key ORDER BY projection_key COLLATE "C")
    )
  INTO v_projection_count, v_projection_hash
  FROM public.sip_completion_projection
  WHERE provider_scope_key = v_registry.provider_scope_key
    AND is_intended;

  SELECT
    count(*),
    public.sip_completion_identity_digest_v1(
      array_agg(
        projection.projection_key || '/' || membership.sample_original_path_id
        ORDER BY
          projection.projection_key COLLATE "C",
          membership.sample_original_path_id
      )
    )
  INTO v_membership_count, v_membership_hash
  FROM public.sip_completion_projection_membership membership
  JOIN public.sip_completion_projection projection
    ON projection.id = membership.completion_projection_id
  WHERE projection.provider_scope_key = v_registry.provider_scope_key
    AND membership.is_intended;

  IF v_source_count <> p_expected_source_count
    OR v_projection_count <> p_expected_projection_count
    OR v_membership_count <> p_expected_membership_count
    OR v_source_hash <> p_expected_source_sha256
    OR v_projection_hash <> p_expected_projection_sha256
    OR v_membership_hash <> p_expected_membership_sha256
  THEN
    RAISE EXCEPTION 'registry denominator drift';
  END IF;

  UPDATE public.sip_completion_projection_registry
  SET
    status = 'frozen',
    source_count = v_source_count,
    intended_projection_count = v_projection_count,
    intended_membership_count = v_membership_count,
    source_identity_sha256 = v_source_hash,
    projection_identity_sha256 = v_projection_hash,
    membership_identity_sha256 = v_membership_hash,
    frozen_by = btrim(p_frozen_by),
    frozen_at = now()
  WHERE id = p_registry_id
  RETURNING * INTO v_registry;

  RETURN v_registry;
END;
$$;


ALTER FUNCTION "public"."sip_freeze_completion_projection_registry_v1"("p_registry_id" "uuid", "p_expected_source_count" bigint, "p_expected_projection_count" bigint, "p_expected_membership_count" bigint, "p_expected_source_sha256" "text", "p_expected_projection_sha256" "text", "p_expected_membership_sha256" "text", "p_frozen_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_gospel_talkbox_grid_override_identity_valid_v1"("p_manifest" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT NOT EXISTS(
    SELECT 1
    FROM public.sip_review_sample_override o
    JOIN jsonb_array_elements(p_manifest)e ON o.original_sample_id=(e->>'originalSampleId')::uuid
    LEFT JOIN public.sip_review_instrument i ON i.id=o.sip_review_instrument_id
    WHERE o.contributor_slug IS DISTINCT FROM 'gospel-musicians'
      OR o.file_path IS DISTINCT FROM e->>'filePath'
      OR i.id IS NULL
      OR i.source_contributor_slug IS DISTINCT FROM 'gospel-musicians'
      OR i.is_retired
      OR CASE WHEN EXISTS(SELECT 1 FROM public.sip_review_instrument_sample_scope any_scope WHERE any_scope.sip_review_instrument_id=o.sip_review_instrument_id)
        THEN NOT EXISTS(SELECT 1 FROM public.sip_review_instrument_sample_scope scope WHERE scope.sip_review_instrument_id=o.sip_review_instrument_id AND scope.original_sample_id=o.original_sample_id AND scope.contributor_slug='gospel-musicians' AND scope.file_path=e->>'filePath')
        ELSE NOT (o.original_sample_id=ANY(COALESCE(i.original_sample_ids,'{}'::uuid[])))
      END
  )
$$;


ALTER FUNCTION "public"."sip_gospel_talkbox_grid_override_identity_valid_v1"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_gospel_talkbox_incomplete_membership_current_v1"("p_manifest" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH entries AS (SELECT e FROM jsonb_array_elements(p_manifest)e), frozen_roots AS (
    SELECT (e->>'stagingRootId')::uuid staging_root_id,
      array_agg((e->>'originalSampleId')::uuid ORDER BY (e->>'originalSampleId')::uuid) frozen_member_ids
    FROM entries GROUP BY e->>'stagingRootId'
  ), exact_roots AS (
    SELECT frozen_roots.staging_root_id
    FROM frozen_roots
    JOIN public.sip_review_instrument i ON i.id=frozen_roots.staging_root_id
    WHERE NOT EXISTS(SELECT 1 FROM public.sip_review_instrument_sample_scope scope WHERE scope.sip_review_instrument_id=i.id)
      AND (SELECT array_agg(DISTINCT member_id ORDER BY member_id) FROM unnest(COALESCE(i.original_sample_ids,'{}'::uuid[])) member_id)
        IS NOT DISTINCT FROM (SELECT array_agg(DISTINCT member_id ORDER BY member_id) FROM unnest(frozen_roots.frozen_member_ids) member_id)
  ), matched AS (
    SELECT e
    FROM entries
    JOIN public.sip_sample_construct c ON c.id=(e->>'sourceConstructRowId')::bigint
      AND c.original_sample_id=(e->>'originalSampleId')::uuid
      AND c.contributor_slug=e->>'contributorSlug' AND c.file_path=e->>'filePath' AND c.midi_note IN(e->>'expectedMidiNote',e->>'targetMidiNote')
    JOIN public.sip_review_instrument i ON i.id=(e->>'stagingRootId')::uuid
      AND i.source_sip_instrument_id=(e->>'sourceRootId')::uuid
      AND i.source_contributor_slug=e->>'contributorSlug' AND NOT i.is_retired
    WHERE (e->>'originalSampleId')::uuid=ANY(COALESCE(i.original_sample_ids,'{}'::uuid[]))
  )
  SELECT (SELECT count(*) FROM matched)=69 AND (SELECT count(*) FROM exact_roots)=2
$$;


ALTER FUNCTION "public"."sip_gospel_talkbox_incomplete_membership_current_v1"("p_manifest" "jsonb") OWNER TO "postgres";


