    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object('snapshotHash',encode(extensions.digest(convert_to(public.sip_gospel_talkbox_warning_refresh_snapshot_v1(p_manifest)::text,'UTF8'),'sha256'),'hex'))
$$;


ALTER FUNCTION "public"."sip_gospel_talkbox_warning_refresh_snapshot_hash_v1"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_gospel_talkbox_warning_refresh_snapshot_v1"("p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH requested AS (
    SELECT (e->>'stagingInstrumentId')::uuid staging_id,
           (e->>'sourceInstrumentId')::uuid source_id,
           e->>'rootName' root_name,
           (e->>'expectedSampleCount')::int expected_count
    FROM jsonb_array_elements(p_manifest)e
  ), membership AS (
    SELECT r.*,m.sample_id
    FROM requested r
    CROSS JOIN LATERAL (
      SELECT s.original_sample_id sample_id FROM public.sip_review_instrument_sample_scope s WHERE s.sip_review_instrument_id=r.staging_id
      UNION
      SELECT unnest(i.original_sample_ids) FROM public.sip_review_instrument i
      WHERE i.id=r.staging_id AND NOT EXISTS(SELECT 1 FROM public.sip_review_instrument_sample_scope s WHERE s.sip_review_instrument_id=r.staging_id)
    )m
  )
  SELECT jsonb_build_object(
    'instruments',COALESCE((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) FROM public.sip_review_instrument i JOIN requested r ON r.staging_id=i.id),'[]'::jsonb),
    'sourceInstruments',COALESCE((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) FROM public.sip_instrument i JOIN requested r ON r.source_id=i.id),'[]'::jsonb),
    'sourceInstrumentMeta',COALESCE((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.sip_instrument_id,m.source_group_key) FROM public.sip_instrument_meta m JOIN requested r ON r.source_id=m.sip_instrument_id),'[]'::jsonb),
    'sourceInstrumentRows',COALESCE((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM public.sip_sample_instrument_source s JOIN public.sip_instrument_meta m ON m.source_sip_sample_instrument_id=s.id JOIN requested r ON r.source_id=m.sip_instrument_id),'[]'::jsonb),
    'taxonomyCache',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.cache_key) FROM public.sip_instrument_taxonomy_cache t JOIN requested r ON r.source_id=t.sip_instrument_id),'[]'::jsonb),
    'scopes',COALESCE((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.sip_review_instrument_id,s.original_sample_id) FROM public.sip_review_instrument_sample_scope s JOIN requested r ON r.staging_id=s.sip_review_instrument_id),'[]'::jsonb),
    'constructs',COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.original_sample_id) FROM public.sip_sample_construct c JOIN (SELECT DISTINCT sample_id FROM membership)m ON m.sample_id=c.original_sample_id),'[]'::jsonb),
    'analysis',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.original_sample_id) FROM public.sip_sample_analysis a JOIN (SELECT DISTINCT sample_id FROM membership)m ON m.sample_id=a.original_sample_id),'[]'::jsonb),
    'publishActions',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.original_sample_id,a.id) FROM public.sip_sample_publish_actions a JOIN (SELECT DISTINCT sample_id FROM membership)m ON m.sample_id=a.original_sample_id),'[]'::jsonb),
    'overrides',COALESCE((SELECT jsonb_agg(to_jsonb(o) ORDER BY o.sip_review_instrument_id,o.original_sample_id) FROM public.sip_review_sample_override o JOIN requested r ON r.staging_id=o.sip_review_instrument_id),'[]'::jsonb),
    'playbackCues',COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.sip_review_instrument_id,c.original_sample_id) FROM public.sip_review_sample_playback_cues c JOIN requested r ON r.staging_id=c.sip_review_instrument_id),'[]'::jsonb),
    'sources',COALESCE((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM public.samples_original_paths s JOIN (SELECT DISTINCT sample_id FROM membership)m ON m.sample_id=s.id),'[]'::jsonb),
    'promotion',COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.sip_review_instrument_id) FROM public.sip_review_promotion_map p JOIN requested r ON r.staging_id=p.sip_review_instrument_id),'[]'::jsonb),
    'reviewState',COALESCE((SELECT jsonb_agg(to_jsonb(rs) ORDER BY rs.sip_review_instrument_id,rs.category,rs.warning_key) FROM public.sip_review_warning_review_state rs JOIN requested r ON r.staging_id=rs.sip_review_instrument_id),'[]'::jsonb),
    'membership',COALESCE((SELECT jsonb_agg(jsonb_build_object('stagingId',staging_id,'sampleId',sample_id) ORDER BY staging_id,sample_id) FROM membership),'[]'::jsonb)
  )
$$;


