CREATE OR REPLACE FUNCTION "public"."sip_gotchanoddin_tonal_kit_manifest_valid_v1"("p_manifest" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  SELECT jsonb_typeof(p_manifest) = 'object'
    AND p_manifest->>'schemaVersion' = '1'
    AND p_manifest->>'operation' = 'gotchanoddin-tonal-kit-pitchless-trigger-v1'
    AND p_manifest->>'contributor' = 'gotchanoddin'
    AND jsonb_array_length(p_manifest->'instrumentV2Ids') = 2397
    AND jsonb_array_length(p_manifest->'nonTonalExclusion'->'instrumentV2Ids') = 1167
    AND (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(p_manifest->'instrumentV2Ids')) = 2397
    AND (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(p_manifest->'nonTonalExclusion'->'instrumentV2Ids')) = 1167
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_manifest->'instrumentV2Ids') value WHERE value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_manifest->'nonTonalExclusion'->'instrumentV2Ids') value WHERE value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
    AND p_manifest#>>'{nonTonalExclusion,idMembershipHash}' = public.sip_gotchanoddin_tonal_kit_membership_hash_v1(p_manifest->'nonTonalExclusion'->'instrumentV2Ids')
    AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(p_manifest->'instrumentV2Ids') tonal
      JOIN jsonb_array_elements_text(p_manifest->'nonTonalExclusion'->'instrumentV2Ids') safe
        ON safe.value = tonal.value
    )
    AND p_manifest->'policy' = '{"nonTransposingPitchlessTriggers":true,"preserveDetectedPitchAsAnalysisMetadata":true,"prohibitKitSequenceInference":true}'::jsonb;
$_$;


