CREATE OR REPLACE FUNCTION "public"."sip_gotchanoddin_tonal_kit_membership_hash_v1"("p_ids" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT encode(
    extensions.digest(
      convert_to(
        coalesce((SELECT string_agg(value, E'\n' ORDER BY value)
          FROM jsonb_array_elements_text(p_ids)), ''),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  )
$$;


