CREATE OR REPLACE FUNCTION "public"."sip_gotchanoddin_tonal_kit_pitchless_rehearsal_immutable_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
     OR OLD.status <> 'passed'
     OR NEW.status <> 'consumed'
     OR NEW.consumed_at IS NULL
     OR NEW.id IS DISTINCT FROM OLD.id
     OR NEW.manifest_hash IS DISTINCT FROM OLD.manifest_hash
     OR NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash
     OR NEW.mutation_plan_hash IS DISTINCT FROM OLD.mutation_plan_hash
     OR NEW.manifest IS DISTINCT FROM OLD.manifest
     OR NEW.before_snapshot IS DISTINCT FROM OLD.before_snapshot
     OR NEW.operator_identity IS DISTINCT FROM OLD.operator_identity
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'sip_gotchanoddin_tonal_kit_rehearsal_immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sip_gotchanoddin_tonal_kit_pitchless_rehearsal_immutable_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_gotchanoddin_tonal_kit_pitchless_snapshot_v1"("p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH targets AS (SELECT value::uuid id FROM jsonb_array_elements_text(p_manifest->'instrumentV2Ids'))
  SELECT jsonb_build_object(
    'instruments', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id', i.id, 'engineType', i.engine_type, 'singlePitch', i.single_pitch,
      'sampledMidiNotes', i.sampled_midi_notes, 'rangeLower', i.range_lower,
      'rangeUpper', i.range_upper, 'fileNameReferences', i.file_name_references,
      'published', i.published, 'taxonomy', jsonb_build_object('family', i.instrument_family, 'type', i.instrument_type),
      'reviewId', promotion.sip_review_instrument_id, 'review', to_jsonb(review),
      'uploadReceipt', to_jsonb(upload_status), 'readiness', to_jsonb(readiness)
    ) ORDER BY i.id) FROM targets t JOIN public.instruments_v2 i ON i.id=t.id
      LEFT JOIN public.sip_review_promotion_map promotion ON promotion.instrument_v2_id=i.id
      LEFT JOIN public.sip_review_instrument review ON review.id=promotion.sip_review_instrument_id
      LEFT JOIN public.instrument_v2_upload_status upload_status ON upload_status.instrument_v2_id=i.id
      LEFT JOIN public.instrument_v2_deterministic_readiness readiness ON readiness.instrument_v2_id=i.id), '[]'::jsonb),
    'constructs', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id', c.id, 'instrumentV2Id', c.instrument_v2_id, 'sourceId', c.sample_original_path_id,
      'midiNote', c.midi_note, 'filename', c.filename, 'pitchContent', c.pitch_content,
      'velocity', c.velocity, 'roundRobin', c.round_robin, 'micPosition', c.mic_position,
      'playbackType', c.playback_type, 'source', jsonb_build_object('path', s.s3_path, 'leaf', s.file_name)
    ) ORDER BY c.id) FROM public.sample_path_constructs c JOIN targets t ON t.id=c.instrument_v2_id
      JOIN public.samples_original_paths s ON s.id=c.sample_original_path_id), '[]'::jsonb),
    'fleet', jsonb_build_object('activeRuns', (SELECT count(*) FROM public.sip_fleet_runs WHERE provider_slug='gotchanoddin' AND status IN ('queued','running')),
      'activeLease', (SELECT id FROM public.sip_fleet_provider_leases WHERE provider_slug='gotchanoddin' AND released_at IS NULL AND lease_expires_at>clock_timestamp() LIMIT 1))
  );
$$;


ALTER FUNCTION "public"."sip_gotchanoddin_tonal_kit_pitchless_snapshot_v1"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_instrument_v2_legacy_map_sync_lookup_key"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    PERFORM "public"."sip_sync_instruments_v2_lookup_key_for_alias"(NEW."instrument_v2_id");
  END IF;

  IF TG_OP IN ('UPDATE', 'DELETE')
     AND (TG_OP = 'DELETE' OR OLD."instrument_v2_id" IS DISTINCT FROM NEW."instrument_v2_id") THEN
    PERFORM "public"."sip_sync_instruments_v2_lookup_key_for_alias"(OLD."instrument_v2_id");
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sip_instrument_v2_legacy_map_sync_lookup_key"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_jsonb_expected_subset_matches_v1"("p_actual" "jsonb", "p_expected" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT p_actual IS NOT NULL
    AND p_expected IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM jsonb_each(p_expected) expected(key, value)
      WHERE p_actual -> expected.key IS DISTINCT FROM expected.value
    )
$$;


ALTER FUNCTION "public"."sip_jsonb_expected_subset_matches_v1"("p_actual" "jsonb", "p_expected" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_jsonb_row_sets_match_v1"("p_expected" "jsonb", "p_actual" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    jsonb_typeof(COALESCE(p_expected, 'null'::jsonb)) = 'array'
    AND jsonb_typeof(COALESCE(p_actual, 'null'::jsonb)) = 'array'
    AND COALESCE(
      (SELECT jsonb_agg(value ORDER BY value::text)
       FROM jsonb_array_elements(p_expected)),
      '[]'::jsonb
    ) IS NOT DISTINCT FROM COALESCE(
      (SELECT jsonb_agg(value ORDER BY value::text)
       FROM jsonb_array_elements(p_actual)),
      '[]'::jsonb
    )
$$;


ALTER FUNCTION "public"."sip_jsonb_row_sets_match_v1"("p_expected" "jsonb", "p_actual" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_mark_singleton_anchor_integrity_failure_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_content jsonb;
  v_instrument_id_text text;
  v_instrument_id uuid;
  v_snapshot jsonb;
  v_snapshot_sha256 text;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status
    OR NEW.status <> 'failed'
    OR NEW.result_payload->>'error'
      <> 'Current targets HEAD results did not match the exact request'
  THEN
    RETURN NEW;
  END IF;

  SELECT artifact.content
  INTO v_content
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = NEW.artifact_id
    AND artifact.provider_slug = NEW.provider_slug
    AND artifact.artifact_kind = 'instrument-summary-materialization'
    AND artifact.content_hash = NEW.content_hash;
  IF v_content IS NULL
    OR jsonb_typeof(v_content->'instrumentV2Ids') <> 'array'
    OR jsonb_array_length(v_content->'instrumentV2Ids') <> 1
    OR jsonb_typeof(v_content->'readinessSnapshots') <> 'array'
    OR jsonb_array_length(v_content->'readinessSnapshots') <> 1
    OR v_content->'anchorObjectVerification'->>'required'
      IS DISTINCT FROM 'true'
    OR v_content->'approval'->>'rehearsalRunId' <> NEW.id::text
  THEN
    RETURN NEW;
  END IF;

  v_instrument_id_text := v_content->'instrumentV2Ids'->>0;
  v_snapshot := v_content->'readinessSnapshots'->0;
  v_snapshot_sha256 := v_snapshot->>'snapshotSha256';
  IF coalesce(v_instrument_id_text, '')
      !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    OR v_snapshot->>'instrumentV2Id' <> v_instrument_id_text
    OR coalesce(v_snapshot_sha256, '') !~ '^[0-9a-f]{64}$'
  THEN
    RETURN NEW;
  END IF;
  v_instrument_id := v_instrument_id_text::uuid;

  IF NOT public.is_current_instrument_v2_readiness_snapshot_v2(
    v_instrument_id,
    v_snapshot_sha256
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.instrument_v2_upload_status (
    instrument_v2_id,
    runtime_verification_status,
    runtime_verification_started_at,
    runtime_verification_completed_at,
    runtime_verification_error_summary,
    runtime_verification_report_path
  )
  SELECT
    instrument.id,
    'failed',
    NEW.created_at,
    coalesce(NEW.completed_at, clock_timestamp()),
    jsonb_build_object(
      'code', 'anchor_object_verification_failed',
      'reason', 'current_targets_head_mismatch',
      'artifactId', NEW.artifact_id,
      'rehearsalRunId', NEW.id
    ),
    NULL
  FROM public.instruments_v2 instrument
  JOIN public.contributors contributor
    ON contributor.id = instrument.contributor_id
  WHERE instrument.id = v_instrument_id
    AND instrument.published IS TRUE
    AND instrument.sampled_midi_notes IS NULL
    AND contributor.slug = NEW.provider_slug
  ON CONFLICT (instrument_v2_id) DO UPDATE
  SET
    runtime_verification_status = EXCLUDED.runtime_verification_status,
    runtime_verification_started_at = coalesce(
      instrument_v2_upload_status.runtime_verification_started_at,
      EXCLUDED.runtime_verification_started_at
    ),
    runtime_verification_completed_at =
      EXCLUDED.runtime_verification_completed_at,
    runtime_verification_error_summary =
      EXCLUDED.runtime_verification_error_summary,
    runtime_verification_report_path = NULL
  WHERE instrument_v2_upload_status.runtime_verification_status = 'passed';

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."sip_mark_singleton_anchor_integrity_failure_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_mark_singleton_anchor_integrity_failure_v1"() IS 'Atomically records exact current singleton target-HEAD mismatches as runtime-verification debt, including for older published instruments without an upload-status row.';



CREATE OR REPLACE FUNCTION "public"."sip_normalize_instrument_tag_group"("p_tag_group" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN lower(trim(coalesce(p_tag_group, ''))) IN ('general', 'general tags') THEN 'General Tags'
    WHEN lower(trim(coalesce(p_tag_group, ''))) IN ('sourcetype', 'source type') THEN 'Source Type'
    WHEN lower(trim(coalesce(p_tag_group, ''))) IN ('harmtype', 'harm type') THEN 'harmType'
    WHEN lower(trim(coalesce(p_tag_group, ''))) IN ('sampletype', 'sample type') THEN 'sampleType'
    WHEN lower(trim(coalesce(p_tag_group, ''))) IN ('drivetype', 'drive type') THEN 'Drive Type'
    WHEN lower(trim(coalesce(p_tag_group, ''))) IN ('playstyle', 'play style') THEN 'Play Style'
    WHEN lower(trim(coalesce(p_tag_group, ''))) IN ('instrumentsize', 'instrument size') THEN 'Instrument Size'
    WHEN lower(trim(coalesce(p_tag_group, ''))) IN ('worldregion', 'world region') THEN 'World Region'
    WHEN lower(trim(coalesce(p_tag_group, ''))) IN ('vocaltype', 'vocal type') THEN 'Vocal Type'
    ELSE trim(coalesce(p_tag_group, ''))
  END
$$;


ALTER FUNCTION "public"."sip_normalize_instrument_tag_group"("p_tag_group" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_normalize_instrument_tag_name"("p_tag_group" "text", "p_tag_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN trim(coalesce(p_tag_name, '')) = '' THEN trim(coalesce(p_tag_name, ''))
    WHEN p_tag_group = 'sampleType' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) IN ('oneshot', 'oneshots') THEN 'oneShot'
    WHEN p_tag_group = 'sampleType' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) IN ('sustain', 'sustained', 'loop', 'loops') THEN 'looped'
    WHEN p_tag_group = 'Articulations' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) IN ('sus', 'sustain') THEN 'Sustained'
    WHEN p_tag_group = 'Articulations' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'vib' THEN 'Vibrato'
    WHEN p_tag_group = 'Articulations' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) IN ('trem', 'roll') THEN 'Tremolo'
    WHEN p_tag_group = 'Articulations' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'fluttertongue' THEN 'Flutter'
    WHEN p_tag_group = 'Articulations' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'flutter' THEN 'Flutter'
    WHEN p_tag_group = 'Articulations' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'pizzicato' THEN 'Pizzicato'
    WHEN p_tag_group = 'Articulations' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'spiccato' THEN 'Spiccato'
    WHEN p_tag_group = 'Articulations' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'staccato' THEN 'Staccato'
    WHEN p_tag_group = 'Source Type' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'electronic' THEN 'Electronic'
    WHEN p_tag_group = 'Timbre' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'airy' THEN 'Airy'
    WHEN p_tag_group = 'Timbre' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'mellow' THEN 'Mellow'
    WHEN p_tag_group = 'Material' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'metal' THEN 'Metal'
    WHEN p_tag_group = 'Play Style' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'hammered' THEN 'Hammered'
    WHEN p_tag_group = 'Play Style' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'plucked' THEN 'Plucked'
    WHEN p_tag_group = 'World Region' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'chinese' THEN 'Chinese'
    WHEN p_tag_group = 'General Tags' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'slide' THEN 'Slide'
    WHEN p_tag_group = 'General Tags' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'crash' THEN 'Crash'
    WHEN p_tag_group = 'Vocal Type' AND public.sip_normalize_instrument_tag_name_key(p_tag_name) = 'mixed' THEN 'Mixed'
    ELSE trim(p_tag_name)
  END
$$;


ALTER FUNCTION "public"."sip_normalize_instrument_tag_name"("p_tag_group" "text", "p_tag_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_normalize_instrument_tag_name_key"("p_tag_name" "text") RETURNS "text"
