CREATE OR REPLACE FUNCTION "public"."sip_pipeline_refresh_run_counts"("p_run_id" "uuid") RETURNS "public"."sip_pipeline_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run public.sip_pipeline_runs%ROWTYPE;
  v_selected_count integer := 0;
  v_queued_count integer := 0;
  v_running_count integer := 0;
  v_published_count integer := 0;
  v_blocked_count integer := 0;
  v_stalled_count integer := 0;
  v_failed_count integer := 0;
  v_cancelled_count integer := 0;
  v_next_status text;
  v_current_stage text;
BEGIN
  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE status = 'queued')::integer,
    count(*) FILTER (WHERE status = 'running')::integer,
    count(*) FILTER (WHERE status = 'published')::integer,
    count(*) FILTER (WHERE status = 'blocked')::integer,
    count(*) FILTER (WHERE status = 'stalled')::integer,
    count(*) FILTER (WHERE status = 'failed')::integer,
    count(*) FILTER (WHERE status = 'cancelled')::integer,
    (
      array_agg(
        current_stage
        ORDER BY CASE current_stage
          WHEN 'publish-actions' THEN 1
          WHEN 'normalize' THEN 2
          WHEN 'compress' THEN 3
          WHEN 'upload-s3' THEN 4
          WHEN 'publish' THEN 5
          ELSE 99
        END
      ) FILTER (WHERE status IN ('queued', 'running'))
    )[1]
  INTO
    v_selected_count,
    v_queued_count,
    v_running_count,
    v_published_count,
    v_blocked_count,
    v_stalled_count,
    v_failed_count,
    v_cancelled_count,
    v_current_stage
  FROM public.sip_pipeline_run_items
  WHERE run_id = p_run_id;

  SELECT * INTO v_run
  FROM public.sip_pipeline_runs
  WHERE id = p_run_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sip_pipeline_run_not_found: %', p_run_id;
  END IF;

  IF v_run.cancel_requested AND (v_queued_count + v_running_count) = 0 THEN
    v_next_status := 'cancelled';
  ELSIF v_selected_count = 0 THEN
    v_next_status := 'complete';
  ELSIF (v_queued_count + v_running_count) > 0 THEN
    IF v_run.cancel_requested THEN
      v_next_status := 'cancelled';
    ELSE
      v_next_status := 'running';
    END IF;
  ELSIF v_published_count = v_selected_count THEN
    v_next_status := 'complete';
  ELSIF v_failed_count > 0 THEN
    v_next_status := 'failed';
  ELSIF v_stalled_count > 0 THEN
    v_next_status := 'paused';
  ELSE
    v_next_status := 'blocked';
  END IF;

  UPDATE public.sip_pipeline_runs
  SET
    status = v_next_status,
    selected_count = v_selected_count,
    queued_count = v_queued_count,
    running_count = v_running_count,
    published_count = v_published_count,
    blocked_count = v_blocked_count,
    stalled_count = v_stalled_count,
    failed_count = v_failed_count,
    cancelled_count = v_cancelled_count,
    current_stage = v_current_stage,
    started_at = COALESCE(started_at, CASE WHEN v_next_status IN ('running', 'complete', 'blocked', 'failed', 'cancelled') THEN now() ELSE NULL END),
    finished_at = CASE WHEN v_next_status IN ('complete', 'blocked', 'failed', 'cancelled') THEN COALESCE(finished_at, now()) ELSE NULL END,
    updated_at = now()
  WHERE id = p_run_id
  RETURNING * INTO v_run;

  RETURN v_run;
END;
$$;


ALTER FUNCTION "public"."sip_pipeline_refresh_run_counts"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_pipeline_stage_from_upload_status"("p_source_sip_instrument_id" "uuid", "p_fallback_stage" "text" DEFAULT 'publish-actions'::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_fallback_stage "text";
  v_floor_stage "text";
BEGIN
  v_fallback_stage := CASE
    WHEN p_fallback_stage IN ('publish-actions', 'normalize', 'compress', 'upload-s3', 'publish')
      THEN p_fallback_stage
    ELSE 'publish-actions'
  END;
  v_floor_stage := public.sip_pipeline_upload_status_floor(
    p_source_sip_instrument_id,
    'publish-actions'
  );

  IF public.sip_pipeline_stage_rank(v_floor_stage) > public.sip_pipeline_stage_rank(v_fallback_stage) THEN
    RETURN v_floor_stage;
  END IF;

  RETURN v_fallback_stage;
END;
$$;


ALTER FUNCTION "public"."sip_pipeline_stage_from_upload_status"("p_source_sip_instrument_id" "uuid", "p_fallback_stage" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_pipeline_stage_rank"("p_stage" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE p_stage
    WHEN 'publish-actions' THEN 0
    WHEN 'normalize' THEN 1
    WHEN 'compress' THEN 2
    WHEN 'upload-s3' THEN 3
    WHEN 'publish' THEN 4
    ELSE -1
  END
$$;


ALTER FUNCTION "public"."sip_pipeline_stage_rank"("p_stage" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_pipeline_upload_status_floor"("p_source_sip_instrument_id" "uuid", "p_fallback_stage" "text" DEFAULT 'publish-actions'::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status "jsonb";
  v_publish_status "text";
  v_samples_total integer;
  v_fallback_stage "text";
BEGIN
  v_fallback_stage := CASE
    WHEN p_fallback_stage IN ('publish-actions', 'normalize', 'compress', 'upload-s3', 'publish')
      THEN p_fallback_stage
    ELSE 'publish-actions'
  END;

  IF p_source_sip_instrument_id IS NULL THEN
    RETURN v_fallback_stage;
  END IF;

  SELECT to_jsonb(status_row)
  INTO v_status
  FROM public.sip_instrument_upload_status status_row
  WHERE status_row.sip_instrument_id = p_source_sip_instrument_id;

  IF NOT FOUND THEN
    RETURN v_fallback_stage;
  END IF;

  v_publish_status := lower(btrim(COALESCE(v_status->>'publish_status', '')));
  v_samples_total := GREATEST(COALESCE((v_status->>'samples_total')::integer, 0), 0);

  IF COALESCE((v_status->>'uploaded_to_s3')::boolean, false)
    OR v_publish_status = 'completed'
    OR (v_publish_status IN ('processing', 'failed') AND v_samples_total > 0)
  THEN
    RETURN 'publish';
  END IF;

  IF COALESCE((v_status->>'compressed')::boolean, false)
    OR v_publish_status = 'compressed'
  THEN
    RETURN 'upload-s3';
  END IF;

  IF COALESCE((v_status->>'normalized')::boolean, false)
    OR v_publish_status = 'normalized'
  THEN
    RETURN 'compress';
  END IF;

  IF COALESCE((v_status->>'publish_actions_applied')::boolean, false) THEN
    RETURN 'normalize';
  END IF;

  RETURN v_fallback_stage;
END;
$$;


ALTER FUNCTION "public"."sip_pipeline_upload_status_floor"("p_source_sip_instrument_id" "uuid", "p_fallback_stage" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_plan_fmg_retired_by_normalization_v1"("p_manifest_hash" "text", "p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_authority_expires_at timestamptz;
  v_authority_expires_at_text text :=
    p_manifest #>> '{authority,expiresAt}';
  v_snapshot jsonb;
  v_snapshot_hash text;
  v_plan_hash text;
BEGIN
  IF jsonb_typeof(p_manifest) IS DISTINCT FROM 'object'
     OR p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR nullif(btrim(p_manifest #>> '{authority,actor}'), '') IS NULL
     OR nullif(btrim(p_manifest #>> '{authority,authority}'), '') IS NULL
     OR nullif(btrim(v_authority_expires_at_text), '') IS NULL
     OR p_manifest IS DISTINCT FROM jsonb_build_object(
       'schemaVersion', 1,
       'operation', 'fmg-receipt-backed-retired-by-normalization',
       'providerSlug', 'fallout-music-group',
       'authority', jsonb_build_object(
         'actor', p_manifest #>> '{authority,actor}',
         'authority', p_manifest #>> '{authority,authority}',
         'expiresAt', v_authority_expires_at_text
       ),
       'expectedCounts', jsonb_build_object(
         'completedReceipts', 143,
         'rows', 1489
       ),
       'frozenEvidence', jsonb_build_object(
         'receiptSetHash',
         '6cfa00ad938425e16b350f2d6da2cd92e166feb626ea43ef76e7bd6667f01d6c',
         'membershipSetHash',
         'ee9d61403c038a10945cd8177d223ce94b044fdda314558da9f78651e18777d1',
         'semanticReceiptSetHash',
         '5bc8f058d4013747d3fb060fc78b7d9fb69a2eae7110a22fd7448d2fc33086e6',
         'semanticLineageHash',
         'e8d215cd6b29e2fd37ccf844454237ec2ac070d17817df70f972e25ab35e8775'
       )
     )
  THEN
    RAISE EXCEPTION
      'fmg_retired_by_normalization_manifest_invalid'
      USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_authority_expires_at := v_authority_expires_at_text::timestamptz;
  EXCEPTION
    WHEN invalid_datetime_format OR datetime_field_overflow THEN
      RAISE EXCEPTION
        'fmg_retired_by_normalization_manifest_invalid'
        USING ERRCODE = '22023';
  END;

  IF v_authority_expires_at <= statement_timestamp() THEN
    RAISE EXCEPTION
      'fmg_retired_by_normalization_authority_expired'
      USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_build_object(
    'completedReceipts', count(DISTINCT receipt.id),
    'membershipRows', count(*),
    'rows', count(DISTINCT review.id),
    'sources', count(DISTINCT source.id),
    'alreadyCorrect',
      count(*) FILTER (WHERE review.retired_by = receipt.cutover_by),
    'mutationCount',
      count(*) FILTER (WHERE review.retired_by IS NULL),
    'records',
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'receiptId', receipt.id,
            'reviewId', review.id,
            'sourceInstrumentV2Id', source.id,
            'retiredBy', receipt.cutover_by
          )
          ORDER BY receipt.id, review.id, source.id
        ),
        '[]'::jsonb
      )
  )
  INTO v_snapshot
  FROM public.sip_sibling_consolidation_receipts_v2 receipt
  CROSS JOIN LATERAL generate_subscripts(
    receipt.source_sip_review_instrument_ids,
    1
  ) member(index)
  JOIN public.sip_review_instrument review
    ON review.id =
      receipt.source_sip_review_instrument_ids[member.index]
  JOIN public.instruments_v2 source
    ON source.id = receipt.source_instrument_v2_ids[member.index]
  WHERE receipt.provider_slug = 'fallout-music-group'
    AND receipt.status = 'cutover'
    AND receipt.closeout_status = 'completed'
    AND receipt.cutover_by IS NOT NULL
    AND btrim(receipt.cutover_by) <> ''
    AND cardinality(receipt.source_sip_review_instrument_ids) =
      cardinality(receipt.source_instrument_v2_ids)
    AND review.is_retired = true
    AND review.retired_at IS NOT NULL
    AND (
      review.retired_by IS NULL
      OR review.retired_by = receipt.cutover_by
    )
    AND source.published = false
    AND NOT EXISTS (
      SELECT 1
      FROM public.sample_path_constructs construct
      WHERE construct.instrument_v2_id = source.id
    );

  IF (v_snapshot ->> 'completedReceipts')::integer <> 143
     OR (v_snapshot ->> 'membershipRows')::integer <> 1489
     OR (v_snapshot ->> 'rows')::integer <> 1489
     OR (v_snapshot ->> 'sources')::integer <> 1489
     OR (
       (v_snapshot ->> 'mutationCount')::integer
       + (v_snapshot ->> 'alreadyCorrect')::integer
     ) <> 1489
  THEN
    RAISE EXCEPTION
      'fmg_retired_by_normalization_scope_drift'
      USING ERRCODE = '40001';
  END IF;

  v_snapshot_hash := encode(
    extensions.digest(
      convert_to(v_snapshot::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  v_plan_hash := encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'manifestHash', p_manifest_hash,
          'mutation', 'retired_by:=cutover_by',
          'snapshotHash', v_snapshot_hash
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  RETURN jsonb_build_object(
    'manifestHash', p_manifest_hash,
    'snapshotHash', v_snapshot_hash,
    'mutationPlanHash', v_plan_hash,
    'receiptCount', 143,
    'rowCount', 1489,
    'mutationCount', (v_snapshot ->> 'mutationCount')::integer,
    'alreadyCorrectCount', (v_snapshot ->> 'alreadyCorrect')::integer,
    'semanticSequencingGuard', jsonb_build_object(
      'semanticReceipts', 49,
      'overlapRows', 50,
      'normalizationMustFinishFirst', true
    )
  );
END;
$_$;


ALTER FUNCTION "public"."sip_plan_fmg_retired_by_normalization_v1"("p_manifest_hash" "text", "p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_provider_warning_review_snapshot_v1"("p_provider_slug" "text", "p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_expected_count integer;
  v_matching_count integer;
  v_snapshot jsonb;
BEGIN
  IF btrim(coalesce(p_provider_slug, '')) = ''
     OR jsonb_typeof(p_manifest) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest) < 1
     OR jsonb_array_length(p_manifest) > 100 THEN
    RAISE EXCEPTION 'provider_warning_review_manifest_invalid' USING ERRCODE = '22023';
  END IF;
  v_expected_count := jsonb_array_length(p_manifest);

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_manifest) entry
    WHERE jsonb_typeof(entry) <> 'object'
       OR coalesce(entry->>'warningId', '') !~ '^[1-9][0-9]*$'
       OR coalesce(entry->>'stagingInstrumentId', '') !~
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR coalesce(entry->>'sampleOriginalPathId', '') !~
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR btrim(coalesce(entry->>'category', '')) = ''
       OR btrim(coalesce(entry->>'warningKey', '')) = ''
       OR btrim(coalesce(entry->>'type', '')) = ''
       OR coalesce(entry->>'expectedReviewStatus', '') NOT IN ('open', 'confirmed')
  ) THEN
    RAISE EXCEPTION 'provider_warning_review_manifest_entry_invalid' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_manifest) entry
    GROUP BY (entry->>'warningId')::bigint HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'provider_warning_review_duplicate_warning' USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_matching_count
  FROM jsonb_array_elements(p_manifest) entry
  JOIN public.sip_review_warning_index warning
    ON warning.id = (entry->>'warningId')::bigint
   AND warning.sip_review_instrument_id = (entry->>'stagingInstrumentId')::uuid
   AND warning.original_sample_id = (entry->>'sampleOriginalPathId')::uuid
   AND warning.contributor_slug = btrim(p_provider_slug)
   AND warning.category = entry->>'category'
   AND warning.warning_key = entry->>'warningKey'
   AND warning.type = entry->>'type'
  JOIN public.sip_review_instrument instrument
    ON instrument.id = warning.sip_review_instrument_id
   AND instrument.source_contributor_slug = btrim(p_provider_slug)
   AND instrument.is_retired = false
   AND warning.original_sample_id = ANY(
     coalesce(instrument.original_sample_ids, '{}'::uuid[])
   )
  JOIN public.samples_original_paths source
    ON source.id = warning.original_sample_id
  JOIN public.sip_review_warning_index_state warning_state
    ON warning_state.sip_review_instrument_id = warning.sip_review_instrument_id
   AND warning_state.contributor_slug = btrim(p_provider_slug)
   AND warning_state.is_stale = false
   AND warning_state.refresh_error IS NULL
  LEFT JOIN public.sip_review_warning_review_state review_state
    ON review_state.sip_review_instrument_id = warning.sip_review_instrument_id
   AND review_state.category = warning.category
   AND review_state.warning_key = warning.warning_key
  WHERE coalesce(review_state.status, 'open') = entry->>'expectedReviewStatus';
  IF v_matching_count <> v_expected_count THEN
    RAISE EXCEPTION 'provider_warning_review_warning_set_changed' USING ERRCODE = '55000';
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
      'warningId', warning.id,
      'stagingInstrumentId', warning.sip_review_instrument_id,
      'sampleOriginalPathId', warning.original_sample_id,
      'category', warning.category,
      'warningKey', warning.warning_key,
      'type', warning.type,
      'severity', warning.severity,
      'field', warning.field,
      'filePath', warning.file_path,
      'message', warning.message,
      'warningUpdatedAt', warning.updated_at,
      'reviewStatus', coalesce(review_state.status, 'open'),
      'warningRefreshedAt', warning_state.refreshed_at,
      'warningDiagnostics', warning_state.diagnostics_json,
      'instrumentUpdatedAt', instrument.updated_at,
      'instrumentSampleIds', instrument.original_sample_ids,
      'sourcePath', source.s3_path,
      'sourceFileName', source.file_name,
      'sourceUpdatedAt', source.updated_at
    ) ORDER BY warning.id)
    INTO v_snapshot
  FROM jsonb_array_elements(p_manifest) entry
  JOIN public.sip_review_warning_index warning
    ON warning.id = (entry->>'warningId')::bigint
  JOIN public.sip_review_instrument instrument
    ON instrument.id = warning.sip_review_instrument_id
  JOIN public.samples_original_paths source ON source.id = warning.original_sample_id
  JOIN public.sip_review_warning_index_state warning_state
    ON warning_state.sip_review_instrument_id = warning.sip_review_instrument_id
  LEFT JOIN public.sip_review_warning_review_state review_state
    ON review_state.sip_review_instrument_id = warning.sip_review_instrument_id
   AND review_state.category = warning.category
   AND review_state.warning_key = warning.warning_key;
  RETURN coalesce(v_snapshot, '[]'::jsonb);
END;
$_$;


ALTER FUNCTION "public"."sip_provider_warning_review_snapshot_v1"("p_provider_slug" "text", "p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_public_output_recovery_retry_receipt_immutable_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'immutable_public_output_recovery_retry_receipt';
END;
$$;


ALTER FUNCTION "public"."sip_public_output_recovery_retry_receipt_immutable_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_anchor_object_verification_rehearsal_begin_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_rehearsal public.sip_anchor_object_verification_rehearsals%ROWTYPE;
  v_instrument_count integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;

  SELECT artifact.*
  INTO v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = p_artifact_id
    AND artifact.provider_slug = btrim(p_contributor_slug)
    AND artifact.artifact_kind = 'instrument-summary-materialization';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'summary_artifact_not_found';
  END IF;
  IF jsonb_typeof(v_artifact.content->'instrumentV2Ids') <> 'array'
    OR jsonb_array_length(v_artifact.content->'instrumentV2Ids') = 0
    OR jsonb_typeof(v_artifact.content->'readinessSnapshots') <> 'array'
    OR jsonb_typeof(v_artifact.content->'anchorObjectVerification') <> 'object'
  THEN
    RAISE EXCEPTION 'anchor_object_verification_artifact_invalid';
  END IF;
  IF coalesce(
      v_artifact.content->'approval'->>'rehearsalRunId',
      ''
    ) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  THEN
    RAISE EXCEPTION 'anchor_object_verification_rehearsal_id_required';
  END IF;
  IF coalesce((
      v_artifact.content->'anchorObjectVerification'->>'required'
    )::boolean, false) IS NOT TRUE
  THEN
    RAISE EXCEPTION 'anchor_object_verification_required';
  END IF;
  IF (
      v_artifact.content->'anchorObjectVerification' ? 'constructCount'
      AND coalesce(
        v_artifact.content->'anchorObjectVerification'->>'constructCount',
        ''
      ) !~ '^[1-9][0-9]*$'
    ) OR (
      v_artifact.content->'anchorObjectVerification' ? 'sourceCount'
      AND coalesce(
        v_artifact.content->'anchorObjectVerification'->>'sourceCount',
        ''
      ) !~ '^[1-9][0-9]*$'
    ) OR (
      v_artifact.content->'anchorObjectVerification' ? 'targetCount'
      AND coalesce(
        v_artifact.content->'anchorObjectVerification'->>'targetCount',
        ''
      ) !~ '^[1-9][0-9]*$'
    )
  THEN
    RAISE EXCEPTION 'anchor_object_verification_declared_counts_invalid';
  END IF;

  SELECT count(*)
  INTO v_instrument_count
  FROM jsonb_array_elements_text(v_artifact.content->'instrumentV2Ids');
  IF v_instrument_count <> (
      SELECT count(DISTINCT value)
      FROM jsonb_array_elements_text(v_artifact.content->'instrumentV2Ids')
    )
    OR jsonb_array_length(v_artifact.content->'readinessSnapshots')
      <> v_instrument_count
  THEN
    RAISE EXCEPTION 'anchor_object_verification_scope_invalid';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(
      v_artifact.content->'instrumentV2Ids'
    ) requested(value)
    LEFT JOIN public.instruments_v2 instrument
      ON instrument.id = requested.value::uuid
    LEFT JOIN public.contributors contributor
      ON contributor.id = instrument.contributor_id
    LEFT JOIN jsonb_array_elements(
      v_artifact.content->'readinessSnapshots'
    ) snapshot(value)
      ON snapshot.value->>'instrumentV2Id' = requested.value
    WHERE instrument.id IS NULL
      OR instrument.published IS NOT TRUE
      OR contributor.slug <> btrim(p_contributor_slug)
      OR snapshot.value IS NULL
      OR coalesce(snapshot.value->>'snapshotSha256', '')
        !~ '^[0-9a-f]{64}$'
      OR NOT public.is_current_instrument_v2_readiness_snapshot_v2(
        instrument.id,
        snapshot.value->>'snapshotSha256'
      )
  ) THEN
    RAISE EXCEPTION 'current_published_summary_readiness_required';
  END IF;

  INSERT INTO public.sip_anchor_object_verification_rehearsals (
    id,
    artifact_id,
    content_hash,
    provider_slug,
    provider_lease_id,
    provider_lease_token
  ) VALUES (
    (v_artifact.content->'approval'->>'rehearsalRunId')::uuid,
    v_artifact.id,
    v_artifact.content_hash,
    btrim(p_contributor_slug),
    p_lease_id,
    p_lease_token
  )
  ON CONFLICT (
    artifact_id,
    content_hash,
    provider_lease_id,
    provider_lease_token
  ) DO NOTHING
  RETURNING * INTO v_rehearsal;

  IF v_rehearsal.id IS NULL THEN
    SELECT rehearsal.*
    INTO STRICT v_rehearsal
    FROM public.sip_anchor_object_verification_rehearsals rehearsal
    WHERE rehearsal.artifact_id = v_artifact.id
      AND rehearsal.content_hash = v_artifact.content_hash
      AND rehearsal.provider_lease_id = p_lease_id
      AND rehearsal.provider_lease_token = p_lease_token;
  END IF;
  IF v_rehearsal.id::text
      <> v_artifact.content->'approval'->>'rehearsalRunId'
  THEN
    RAISE EXCEPTION 'anchor_object_verification_rehearsal_id_conflict';
  END IF;
  IF v_rehearsal.status = 'failed' THEN
    RAISE EXCEPTION 'failed_rehearsal_is_immutable';
  END IF;

  RETURN jsonb_build_object(
    'rehearsalRunId', v_rehearsal.id,
    'artifactId', v_artifact.id,
    'contentHash', v_artifact.content_hash,
    'content', v_artifact.content,
    'status', v_rehearsal.status
  );
END;
$_$;


ALTER FUNCTION "public"."sip_publish_anchor_object_verification_rehearsal_begin_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_anchor_object_verification_rehearsal_complete_v1"("p_rehearsal_run_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_passed" boolean, "p_projection_hash" "text", "p_object_identity_hash" "text", "p_expected_construct_count" integer, "p_expected_source_count" integer, "p_expected_target_count" integer, "p_result_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_rehearsal public.sip_anchor_object_verification_rehearsals%ROWTYPE;
  v_artifact_content jsonb;
BEGIN
  IF jsonb_typeof(p_result_payload) <> 'object' THEN
    RAISE EXCEPTION 'anchor_object_verification_result_required';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    JOIN public.sip_anchor_object_verification_rehearsals rehearsal
      ON rehearsal.provider_slug = lease.provider_slug
    WHERE rehearsal.id = p_rehearsal_run_id
      AND lease.id = p_lease_id
      AND lease.lease_token = p_lease_token
      AND rehearsal.provider_lease_id = lease.id
      AND rehearsal.provider_lease_token = lease.lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;

  SELECT artifact.content
  INTO v_artifact_content
  FROM public.sip_anchor_object_verification_rehearsals rehearsal
  JOIN public.sip_fleet_plan_artifacts artifact
    ON artifact.id = rehearsal.artifact_id
   AND artifact.content_hash = rehearsal.content_hash
  WHERE rehearsal.id = p_rehearsal_run_id
    AND rehearsal.provider_lease_id = p_lease_id
    AND rehearsal.provider_lease_token = p_lease_token;
  IF v_artifact_content IS NULL THEN
    RAISE EXCEPTION 'anchor_object_verification_rehearsal_not_found';
  END IF;

  IF p_passed AND (
    coalesce(p_projection_hash, '') !~ '^[0-9a-f]{64}$'
    OR coalesce(p_object_identity_hash, '') !~ '^[0-9a-f]{64}$'
    OR p_expected_construct_count IS NULL
    OR p_expected_construct_count < 1
    OR p_expected_source_count IS NULL
    OR p_expected_source_count < 1
    OR p_expected_target_count IS NULL
    OR p_expected_target_count < 1
    OR p_expected_target_count <> p_expected_construct_count * 9
    OR (
      v_artifact_content->'anchorObjectVerification' ? 'constructCount'
      AND (
        v_artifact_content->'anchorObjectVerification'->>'constructCount'
      )::integer <> p_expected_construct_count
    )
    OR (
      v_artifact_content->'anchorObjectVerification' ? 'sourceCount'
      AND (
        v_artifact_content->'anchorObjectVerification'->>'sourceCount'
      )::integer <> p_expected_source_count
    )
    OR (
      v_artifact_content->'anchorObjectVerification' ? 'targetCount'
      AND (
        v_artifact_content->'anchorObjectVerification'->>'targetCount'
      )::integer <> p_expected_target_count
    )
  ) THEN
    RAISE EXCEPTION 'anchor_object_verification_second_pass_mismatch';
  END IF;

  UPDATE public.sip_anchor_object_verification_rehearsals rehearsal
  SET
    status = CASE WHEN p_passed THEN 'passed' ELSE 'failed' END,
    projection_hash = CASE WHEN p_passed THEN p_projection_hash ELSE NULL END,
    object_identity_hash =
      CASE WHEN p_passed THEN p_object_identity_hash ELSE NULL END,
    construct_count =
      CASE WHEN p_passed THEN p_expected_construct_count ELSE NULL END,
    source_count =
      CASE WHEN p_passed THEN p_expected_source_count ELSE NULL END,
    target_count =
      CASE WHEN p_passed THEN p_expected_target_count ELSE NULL END,
    result_payload = p_result_payload,
    completed_at = clock_timestamp()
  WHERE rehearsal.id = p_rehearsal_run_id
    AND rehearsal.provider_lease_id = p_lease_id
    AND rehearsal.provider_lease_token = p_lease_token
    AND rehearsal.status = 'pending'
  RETURNING * INTO v_rehearsal;

  IF v_rehearsal.id IS NULL THEN
    SELECT rehearsal.*
    INTO STRICT v_rehearsal
    FROM public.sip_anchor_object_verification_rehearsals rehearsal
    WHERE rehearsal.id = p_rehearsal_run_id
      AND rehearsal.provider_lease_id = p_lease_id
      AND rehearsal.provider_lease_token = p_lease_token;
    IF v_rehearsal.status
        <> (CASE WHEN p_passed THEN 'passed' ELSE 'failed' END)
      OR v_rehearsal.result_payload <> p_result_payload
      OR (
        p_passed
        AND (
          v_rehearsal.projection_hash <> p_projection_hash
          OR v_rehearsal.object_identity_hash <> p_object_identity_hash
          OR v_rehearsal.construct_count <> p_expected_construct_count
          OR v_rehearsal.source_count <> p_expected_source_count
          OR v_rehearsal.target_count <> p_expected_target_count
        )
      )
    THEN
      RAISE EXCEPTION 'anchor_object_verification_completion_mismatch';
    END IF;
  END IF;

  RETURN to_jsonb(v_rehearsal);
END;
$_$;


ALTER FUNCTION "public"."sip_publish_anchor_object_verification_rehearsal_complete_v1"("p_rehearsal_run_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_passed" boolean, "p_projection_hash" "text", "p_object_identity_hash" "text", "p_expected_construct_count" integer, "p_expected_source_count" integer, "p_expected_target_count" integer, "p_result_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_apply_deterministic_repair_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_coordinator_run_id" "uuid", "p_provider_lease_token" "uuid", "p_instrument_v2_id" "uuid", "p_expected_snapshot_hash" "text", "p_operations" "jsonb", "p_materialization_receipts" "jsonb", "p_source_rows" "jsonb", "p_construct_inserts" "jsonb", "p_construct_updates" "jsonb", "p_detach_construct_ids" "jsonb", "p_derivation_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_artifact_content jsonb;
  v_artifact_hash text;
  v_artifact_kind text;
  v_provider_slug text;
  v_approved_operations jsonb;
  v_current_snapshot_hash text;
  v_existing jsonb;
  v_expected_materialized integer;
  v_expected_updates integer;
  v_expected_detaches integer;
  v_expected_inserts integer;
  v_updated integer;
  v_result jsonb;
BEGIN
  IF btrim(coalesce(p_contributor_slug, '')) = ''
    OR p_artifact_id IS NULL OR btrim(coalesce(p_expected_content_hash, '')) = ''
    OR p_coordinator_run_id IS NULL OR p_provider_lease_token IS NULL
    OR p_instrument_v2_id IS NULL
  THEN RAISE EXCEPTION 'deterministic_repair_identity_required'; END IF;
  IF p_expected_snapshot_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'deterministic_repair_snapshot_hash_invalid';
  END IF;
  IF jsonb_typeof(p_operations) <> 'array' OR jsonb_array_length(p_operations) = 0
    OR jsonb_typeof(p_materialization_receipts) <> 'array'
    OR jsonb_typeof(p_source_rows) <> 'array'
    OR jsonb_typeof(p_construct_inserts) <> 'array'
    OR jsonb_typeof(p_construct_updates) <> 'array'
    OR jsonb_typeof(p_detach_construct_ids) <> 'array'
    OR jsonb_typeof(p_derivation_rows) <> 'array'
  THEN RAISE EXCEPTION 'deterministic_repair_payload_invalid'; END IF;

  SELECT artifact.content, artifact.content_hash, artifact.provider_slug, artifact.artifact_kind
    INTO v_artifact_content, v_artifact_hash, v_provider_slug, v_artifact_kind
  FROM public.sip_fleet_plan_artifacts artifact
  JOIN public.sip_fleet_plan_artifact_approvals approval
    ON approval.artifact_id = artifact.id
   AND approval.content_hash = artifact.content_hash
  WHERE artifact.id = p_artifact_id
    AND artifact.provider_slug = btrim(p_contributor_slug)
    AND artifact.artifact_kind IN ('grid-topology-normalization-v1', 'derived-grid-fill-v1');
  IF v_artifact_content IS NULL OR v_artifact_hash <> p_expected_content_hash THEN
    RAISE EXCEPTION 'approved_deterministic_repair_artifact_required';
  END IF;

  SELECT coalesce(jsonb_agg(operation ORDER BY operation->>'operationId'), '[]'::jsonb)
    INTO v_approved_operations
  FROM jsonb_array_elements(v_artifact_content->'operations') operation
  WHERE operation->>'instrumentV2Id' = p_instrument_v2_id::text;
  IF jsonb_array_length(v_approved_operations) = 0
    OR NOT (p_operations @> v_approved_operations)
    OR NOT (v_approved_operations @> p_operations)
  THEN RAISE EXCEPTION 'deterministic_repair_operations_not_exact_artifact_scope'; END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_runs run
    JOIN public.sip_fleet_provider_leases lease ON lease.id = run.provider_lease_id
    JOIN public.instruments_v2 instrument ON instrument.id = p_instrument_v2_id
    JOIN public.contributors contributor ON contributor.id = instrument.contributor_id
    WHERE run.id = p_coordinator_run_id
      AND run.provider_slug = v_provider_slug
      AND run.provider_lease_token = p_provider_lease_token
      AND lease.provider_slug = v_provider_slug
      AND lease.lease_token = p_provider_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > now()
      AND contributor.slug = v_provider_slug
  ) THEN RAISE EXCEPTION 'invalid_deterministic_repair_provider_lease'; END IF;

  -- The durable item payload is the idempotency receipt. It is updated inside
  -- this transaction, so a failed transaction cannot falsely claim completion.
  SELECT item.result_payload INTO v_existing
  FROM public.sip_fleet_run_items item
  WHERE item.run_id = p_coordinator_run_id
    AND item.instrument_v2_id = p_instrument_v2_id
  FOR UPDATE;
  IF v_existing IS NULL THEN RAISE EXCEPTION 'deterministic_repair_run_item_missing'; END IF;
  IF v_existing->>'deterministicRepairArtifactId' = p_artifact_id::text
    AND v_existing->>'deterministicRepairContentHash' = v_artifact_hash
  THEN
    RETURN v_existing || jsonb_build_object('idempotent', true);
  END IF;

  -- Mirrors buildDeterministicRepairSnapshotHash() in the runner. Base64
  -- eliminates delimiter ambiguity and makes a stale axes/source mapping
  -- reject before any generated metadata becomes visible.
  SELECT encode(extensions.digest(convert_to(coalesce(string_agg(
    concat_ws('|',
      encode(convert_to(coalesce(c.id::text, '<null>'), 'UTF8'), 'base64'),
      encode(convert_to(coalesce(c.sample_original_path_id::text, '<null>'), 'UTF8'), 'base64'),
      encode(convert_to(coalesce(c.pitch_content, '<null>'), 'UTF8'), 'base64'),
      encode(convert_to(coalesce(c.velocity::text, '<null>'), 'UTF8'), 'base64'),
      encode(convert_to(coalesce(c.round_robin::text, '<null>'), 'UTF8'), 'base64'),
      encode(convert_to(coalesce(c.mic_position, '<null>'), 'UTF8'), 'base64'),
      encode(convert_to(coalesce(c.midi_note, '<null>'), 'UTF8'), 'base64'),
      encode(convert_to(coalesce(c.filename, '<null>'), 'UTF8'), 'base64')
    ), E'\n' ORDER BY c.id), ''), 'UTF8'), 'sha256'), 'hex')
    INTO v_current_snapshot_hash
  FROM public.sample_path_constructs c
  WHERE c.instrument_v2_id = p_instrument_v2_id;
  IF v_current_snapshot_hash <> p_expected_snapshot_hash THEN
    RAISE EXCEPTION 'deterministic_repair_snapshot_mismatch';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_operations) operation
    WHERE operation->>'instrumentV2Id' <> p_instrument_v2_id::text
  ) THEN RAISE EXCEPTION 'deterministic_repair_operation_instrument_mismatch'; END IF;

  SELECT count(*) INTO v_expected_materialized
  FROM jsonb_array_elements(p_operations) operation
  WHERE coalesce((operation->>'audioMaterializationRequired')::boolean, true);
  IF (SELECT count(*) FROM jsonb_array_elements(p_materialization_receipts)) <> v_expected_materialized
    OR (SELECT count(*) FROM jsonb_array_elements(p_source_rows)) <> v_expected_materialized
    OR (SELECT count(*) FROM jsonb_array_elements(p_derivation_rows)) <> v_expected_materialized
  THEN RAISE EXCEPTION 'deterministic_repair_receipt_count_mismatch'; END IF;

  -- Receipts prove that the exact approved donor/output pair was materialized.
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_operations) operation
    LEFT JOIN LATERAL (
      SELECT receipt
      FROM jsonb_array_elements(p_materialization_receipts) receipt
      WHERE receipt->>'operationId' = operation->>'operationId'
      LIMIT 1
    ) receipt_match ON true
    WHERE coalesce((operation->>'audioMaterializationRequired')::boolean, true)
      AND (receipt_match.receipt IS NULL
        OR receipt_match.receipt->>'processed' <> 'true'
        OR receipt_match.receipt->>'sourceS3Key' <> operation->'donor'->>'sourceS3Key'
        OR receipt_match.receipt->>'outputS3Key' <> operation->'generated'->>'privateSourceS3Key'
        OR btrim(coalesce(receipt_match.receipt->>'sourceHash','')) = ''
        OR btrim(coalesce(receipt_match.receipt->>'generatedHash','')) = '')
  ) THEN RAISE EXCEPTION 'deterministic_repair_receipt_mismatch'; END IF;

  IF v_artifact_kind = 'grid-topology-normalization-v1' THEN
    SELECT count(*) INTO v_expected_detaches
    FROM jsonb_array_elements(p_operations) operation
    WHERE operation->>'operationKind' = 'surplus_axis_discard';
    SELECT count(*) INTO v_expected_updates
    FROM jsonb_array_elements(p_operations) operation
    WHERE operation->>'operationKind' <> 'surplus_axis_discard';
    v_expected_inserts := 0;
  ELSE
    v_expected_detaches := 0;
    v_expected_updates := 0;
    SELECT count(*) INTO v_expected_inserts FROM jsonb_array_elements(p_operations);
  END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_detach_construct_ids)) <> v_expected_detaches
    OR (SELECT count(*) FROM jsonb_array_elements(p_construct_updates)) <> v_expected_updates
    OR (SELECT count(*) FROM jsonb_array_elements(p_construct_inserts)) <> v_expected_inserts
  THEN RAISE EXCEPTION 'deterministic_repair_construct_count_mismatch'; END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_operations) operation
    LEFT JOIN LATERAL (
      SELECT source_candidate
      FROM jsonb_array_elements(p_source_rows) source_candidate
      WHERE source_candidate->>'id' = operation->'generated'->>'sampleOriginalPathId'
      LIMIT 1
    ) source_row ON true
    LEFT JOIN LATERAL (
      SELECT derivation_candidate
      FROM jsonb_array_elements(p_derivation_rows) derivation_candidate
      WHERE derivation_candidate->>'generated_sample_original_path_id' = operation->'generated'->>'sampleOriginalPathId'
      LIMIT 1
    ) derivation_row ON true
    WHERE coalesce((operation->>'audioMaterializationRequired')::boolean, true)
      AND (source_row.source_candidate IS NULL OR derivation_row.derivation_candidate IS NULL
        OR source_row.source_candidate->>'s3_path' <> operation->'generated'->>'privateSourceS3Key'
        OR derivation_row.derivation_candidate->>'source_sample_original_path_id' <> operation->'donor'->>'sampleOriginalPathId')
  ) THEN RAISE EXCEPTION 'deterministic_repair_generated_lineage_mismatch'; END IF;

  IF v_artifact_kind = 'grid-topology-normalization-v1' AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_operations) operation
    LEFT JOIN LATERAL (
      SELECT row FROM jsonb_array_elements(p_construct_updates) row
      WHERE row->>'id' = operation->>'retargetSamplePathConstructId' LIMIT 1
    ) update_row ON true
    WHERE operation->>'operationKind' <> 'surplus_axis_discard'
      AND (update_row.row IS NULL
        OR update_row.row->>'pitch_content' <> operation->'target'->'slot'->>'pitchContent'
        OR update_row.row->>'velocity' <> operation->'target'->'slot'->>'velocity'
        OR update_row.row->>'round_robin' <> operation->'target'->'slot'->>'roundRobin'
        OR update_row.row->>'midi_note' <> operation->'target'->'slot'->>'midiNote')
  ) THEN RAISE EXCEPTION 'deterministic_repair_retarget_mismatch'; END IF;

  IF v_artifact_kind = 'derived-grid-fill-v1' AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_operations) operation
    LEFT JOIN LATERAL (
      SELECT row FROM jsonb_array_elements(p_construct_inserts) row
      WHERE row->>'id' = operation->'generated'->>'samplePathConstructId' LIMIT 1
    ) insert_row ON true
    WHERE insert_row.row IS NULL
      OR insert_row.row->>'sample_original_path_id' <> operation->'generated'->>'sampleOriginalPathId'
      OR insert_row.row->>'pitch_content' <> operation->'target'->>'pitchContent'
      OR insert_row.row->>'velocity' <> operation->'target'->>'velocity'
      OR insert_row.row->>'round_robin' <> operation->'target'->>'roundRobin'
      OR insert_row.row->>'midi_note' <> operation->'target'->>'midiNote'
  ) THEN RAISE EXCEPTION 'deterministic_repair_insert_mismatch'; END IF;

  -- A destination must be unique in the resulting active grid. Update and
  -- detach rows are excluded from the current grid because they are replaced
  -- by the submitted target set in this same transaction.
  IF EXISTS (
    SELECT 1
    FROM (
      SELECT row->>'pitch_content' AS pitch_content, row->>'velocity' AS velocity,
        row->>'round_robin' AS round_robin, row->>'mic_position' AS mic_position,
        row->>'midi_note' AS midi_note, row->>'filename' AS filename
      FROM jsonb_array_elements(p_construct_inserts) row
      UNION ALL
      SELECT row->>'pitch_content', row->>'velocity', row->>'round_robin',
        row->>'mic_position', row->>'midi_note', row->>'filename'
      FROM jsonb_array_elements(p_construct_updates) row
    ) targets
    GROUP BY pitch_content, velocity, round_robin, mic_position, midi_note, filename
    HAVING count(*) > 1
  ) OR EXISTS (
    SELECT 1
    FROM public.sample_path_constructs current
    JOIN (
      SELECT row->>'pitch_content' AS pitch_content, row->>'velocity' AS velocity,
        row->>'round_robin' AS round_robin, row->>'mic_position' AS mic_position,
        row->>'midi_note' AS midi_note, row->>'filename' AS filename
      FROM jsonb_array_elements(p_construct_inserts) row
      UNION ALL
      SELECT row->>'pitch_content', row->>'velocity', row->>'round_robin',
        row->>'mic_position', row->>'midi_note', row->>'filename'
      FROM jsonb_array_elements(p_construct_updates) row
    ) targets ON current.pitch_content = targets.pitch_content
      AND current.velocity::text = targets.velocity
      AND current.round_robin::text = targets.round_robin
      AND coalesce(current.mic_position, '') = coalesce(targets.mic_position, '')
      AND current.midi_note = targets.midi_note
      AND current.filename = targets.filename
    WHERE current.instrument_v2_id = p_instrument_v2_id
      AND current.id <> ALL(ARRAY(
        SELECT value::uuid FROM jsonb_array_elements_text(p_detach_construct_ids)
        UNION ALL SELECT (row->>'id')::uuid FROM jsonb_array_elements(p_construct_updates) row
      ))
  ) THEN RAISE EXCEPTION 'deterministic_repair_duplicate_destination'; END IF;

  INSERT INTO public.samples_original_paths(id, s3_path, file_name, licensing_secured)
  SELECT (row->>'id')::uuid, row->>'s3_path', row->>'file_name', true
  FROM jsonb_array_elements(p_source_rows) row;

  UPDATE public.sample_path_constructs c
  SET instrument_v2_id = NULL
  WHERE c.id IN (SELECT value::uuid FROM jsonb_array_elements_text(p_detach_construct_ids))
    AND c.instrument_v2_id = p_instrument_v2_id;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> v_expected_detaches THEN RAISE EXCEPTION 'deterministic_repair_detach_mismatch'; END IF;

  UPDATE public.sample_path_constructs c
  SET sample_original_path_id = (row->>'sample_original_path_id')::uuid,
      instrument_name = row->>'instrument_name',
      pitch_content = row->>'pitch_content', velocity = (row->>'velocity')::integer,
      round_robin = (row->>'round_robin')::integer, mic_position = row->>'mic_position',
      midi_note = row->>'midi_note', filename = row->>'filename'
  FROM jsonb_array_elements(p_construct_updates) row
  WHERE c.id = (row->>'id')::uuid
    AND c.instrument_v2_id = p_instrument_v2_id;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> v_expected_updates THEN RAISE EXCEPTION 'deterministic_repair_update_mismatch'; END IF;

  INSERT INTO public.sample_path_constructs(
    id, sample_original_path_id, instrument_name, instrument_v2_id, pitch_content,
    velocity, round_robin, mic_position, midi_note, filename, playback_type
  )
  SELECT (row->>'id')::uuid, (row->>'sample_original_path_id')::uuid,
    row->>'instrument_name', p_instrument_v2_id, row->>'pitch_content',
    (row->>'velocity')::integer, (row->>'round_robin')::integer,
    row->>'mic_position', row->>'midi_note', row->>'filename',
    (row->>'playback_type')::public.instrument_playback_type
  FROM jsonb_array_elements(p_construct_inserts) row;

  INSERT INTO public.sample_generated_derivations(
    generated_sample_original_path_id, source_sample_original_path_id, instrument_v2_id,
    generated_sample_path_construct_id, source_sample_path_construct_id, derivation_kind,
    derivation_params, tool_version, source_hash, generated_hash, run_id,
    rehearsal_run_id, created_by
  )
  SELECT (row->>'generated_sample_original_path_id')::uuid,
    (row->>'source_sample_original_path_id')::uuid, p_instrument_v2_id,
    (row->>'generated_sample_path_construct_id')::uuid,
    nullif(row->>'source_sample_path_construct_id','')::uuid,
    'pitch_shift_cents', coalesce(row->'derivation_params','{}'::jsonb),
    row->>'tool_version', nullif(row->>'source_hash',''), nullif(row->>'generated_hash',''),
    row->>'run_id', nullif(row->>'rehearsal_run_id',''), nullif(row->>'created_by','')
  FROM jsonb_array_elements(p_derivation_rows) row;

  SELECT public.refresh_instrument_v2_axis_summaries_v1(ARRAY[p_instrument_v2_id])
    INTO v_updated;
  IF v_updated <> 1 THEN RAISE EXCEPTION 'deterministic_repair_summary_refresh_failed'; END IF;

  v_result := jsonb_build_object(
    'deterministicRepairArtifactId', p_artifact_id,
    'deterministicRepairContentHash', v_artifact_hash,
    'deterministicRepairSnapshotHash', p_expected_snapshot_hash,
    'instrumentV2Id', p_instrument_v2_id,
    'operationCount', jsonb_array_length(p_operations),
    'materializedCount', v_expected_materialized,
    'idempotent', false
  );
  UPDATE public.sip_fleet_run_items
  SET result_payload = result_payload || v_result
  WHERE run_id = p_coordinator_run_id AND instrument_v2_id = p_instrument_v2_id;
  RETURN v_result;
END $_$;


ALTER FUNCTION "public"."sip_publish_apply_deterministic_repair_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_coordinator_run_id" "uuid", "p_provider_lease_token" "uuid", "p_instrument_v2_id" "uuid", "p_expected_snapshot_hash" "text", "p_operations" "jsonb", "p_materialization_receipts" "jsonb", "p_source_rows" "jsonb", "p_construct_inserts" "jsonb", "p_construct_updates" "jsonb", "p_detach_construct_ids" "jsonb", "p_derivation_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_publish_apply_deterministic_repair_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_coordinator_run_id" "uuid", "p_provider_lease_token" "uuid", "p_instrument_v2_id" "uuid", "p_expected_snapshot_hash" "text", "p_operations" "jsonb", "p_materialization_receipts" "jsonb", "p_source_rows" "jsonb", "p_construct_inserts" "jsonb", "p_construct_updates" "jsonb", "p_detach_construct_ids" "jsonb", "p_derivation_rows" "jsonb") IS 'Atomically commits approved deterministic repair metadata after private audio materialization under the active coordinator provider lease.';



CREATE OR REPLACE FUNCTION "public"."sip_publish_apply_fmg_terminal_waits_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_existing record;
  v_preview jsonb;
  v_current_manifest jsonb;
  v_receipt_id uuid := gen_random_uuid();
  v_lease_owner text;
  v_updated integer;
  v_result jsonb;
BEGIN
  IF btrim(coalesce(p_contributor_slug, '')) <> 'fallout-music-group'
     OR p_lease_id IS NULL OR p_lease_token IS NULL
     OR coalesce(p_manifest_hash, '') !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_manifest) IS DISTINCT FROM 'object'
     OR btrim(coalesce(p_applied_by, '')) = '' THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_apply_identity_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF p_manifest->>'version'
       IS DISTINCT FROM 'sip-fmg-terminal-profile-wait-reconciliation-v1'
     OR p_manifest->>'scopeKey'
       IS DISTINCT FROM 'issue-2437-fmg-terminal-profile-waits-v1'
     OR p_manifest->>'providerSlug' IS DISTINCT FROM 'fallout-music-group'
     OR p_manifest->>'operationClass'
       IS DISTINCT FROM 'terminal-history-status-only'
     OR coalesce((p_manifest->>'readinessAuthorized')::boolean, true) IS NOT FALSE
     OR p_manifest->>'legacyReceiptBlocker'
       IS DISTINCT FROM 'address_output_receipts_incomplete'
     OR (p_manifest->>'targetCount')::integer IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_manifest_scope_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF encode(extensions.digest(convert_to(p_manifest::text, 'UTF8'), 'sha256'), 'hex')
       IS DISTINCT FROM p_manifest_hash THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_manifest_hash_mismatch'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended('fallout-music-group', 0)
  );

  SELECT lease.lease_owner INTO v_lease_owner
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
    AND lease.provider_slug = 'fallout-music-group'
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_invalid_provider_lease'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.sip_fmg_terminal_profile_wait_reconciliation_receipts receipt
    WHERE receipt.scope_key = 'issue-2437-fmg-terminal-profile-waits-v1'
      AND receipt.receipt_kind = 'rollback'
  ) THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_already_rolled_back'
      USING ERRCODE = '55000';
  END IF;

  SELECT receipt.* INTO v_existing
  FROM public.sip_fmg_terminal_profile_wait_reconciliation_receipts receipt
  WHERE receipt.scope_key = 'issue-2437-fmg-terminal-profile-waits-v1'
    AND receipt.receipt_kind = 'apply'
  FOR SHARE;
  IF FOUND THEN
    IF v_existing.provider_slug IS DISTINCT FROM 'fallout-music-group'
       OR v_existing.manifest_hash IS DISTINCT FROM p_manifest_hash
       OR v_existing.manifest IS DISTINCT FROM p_manifest THEN
      RAISE EXCEPTION 'fmg_terminal_profile_wait_receipt_conflict'
        USING ERRCODE = '55000';
    END IF;
    IF (
      SELECT count(*)
      FROM public.sip_fleet_run_items item
      WHERE (
        item.id = '29bce41a-f448-4478-bf97-01edac4d34d1'::uuid
        AND item.run_id = 'f5216bfa-19e7-424d-b382-d7166913ffb1'::uuid
        AND item.instrument_v2_id = 'd822b904-ab46-4ed6-87d3-f414798606be'::uuid
        AND item.status = 'canceled'
        AND item.finished_at = '2026-07-24 06:32:57.437962+00'::timestamptz
      ) OR (
        item.id = '854e9736-5f7d-46b0-86c6-e5f0a7903929'::uuid
        AND item.run_id = '7d5d825d-c648-4af8-9a46-b00c51285cb1'::uuid
        AND item.instrument_v2_id = '88821d01-71d6-438d-a0d1-8595789c9f85'::uuid
        AND item.status = 'failed'
        AND item.finished_at = '2026-07-24 18:38:17.532446+00'::timestamptz
      )
    ) IS DISTINCT FROM 2 THEN
      RAISE EXCEPTION 'fmg_terminal_profile_wait_idempotent_state_changed'
        USING ERRCODE = '55000';
    END IF;
    RETURN v_existing.result || jsonb_build_object('idempotent', true);
  END IF;

  PERFORM run.id
  FROM public.sip_fleet_runs run
  WHERE run.provider_slug = 'fallout-music-group'
  ORDER BY run.id
  FOR UPDATE;
  PERFORM item.id
  FROM public.sip_fleet_run_items item
  JOIN public.sip_fleet_runs run ON run.id = item.run_id
  WHERE run.provider_slug = 'fallout-music-group'
  ORDER BY item.id
  FOR UPDATE OF item;
  PERFORM artifact.id
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id IN (
    SELECT run.plan_artifact_id
    FROM public.sip_fleet_runs run
    WHERE run.id IN (
      'f5216bfa-19e7-424d-b382-d7166913ffb1'::uuid,
      'd017893c-c6e7-45e6-927a-d01ee1bffc10'::uuid,
      '7d5d825d-c648-4af8-9a46-b00c51285cb1'::uuid,
      '92aa0c66-0a4f-4b9b-b0b5-afef1f6e696b'::uuid
    )
  )
  ORDER BY artifact.id
  FOR SHARE;
  PERFORM instrument.id
  FROM public.instruments_v2 instrument
  WHERE instrument.id IN (
    'd822b904-ab46-4ed6-87d3-f414798606be'::uuid,
    '88821d01-71d6-438d-a0d1-8595789c9f85'::uuid,
    'b8385e49-99ff-493b-947b-ab750af97c94'::uuid
  )
  ORDER BY instrument.id
  FOR SHARE;
  PERFORM construct.id
  FROM public.sample_path_constructs construct
  WHERE construct.instrument_v2_id IN (
    'd822b904-ab46-4ed6-87d3-f414798606be'::uuid,
    '88821d01-71d6-438d-a0d1-8595789c9f85'::uuid,
    'b8385e49-99ff-493b-947b-ab750af97c94'::uuid
  )
  ORDER BY construct.id
  FOR SHARE;
  PERFORM receipt.id
  FROM public.sip_sibling_consolidation_receipts_v2 receipt
  WHERE receipt.id = '8d805a71-b926-466e-8858-eb71e648da16'::uuid
  FOR SHARE;
  PERFORM projection.id
  FROM public.sip_sibling_consolidation_projection_v2 projection
  WHERE projection.receipt_id = '8d805a71-b926-466e-8858-eb71e648da16'::uuid
  ORDER BY projection.id
  FOR SHARE;
  PERFORM profile.instrument_v2_id
  FROM public.instrument_audio_profile_v1 profile
  WHERE profile.instrument_v2_id IN (
    'd822b904-ab46-4ed6-87d3-f414798606be'::uuid,
    'b8385e49-99ff-493b-947b-ab750af97c94'::uuid
  )
  ORDER BY profile.instrument_v2_id
  FOR SHARE;
  PERFORM job.id
  FROM public.instrument_audio_profile_jobs_v1 job
  WHERE job.instrument_v2_id IN (
    'd822b904-ab46-4ed6-87d3-f414798606be'::uuid,
    'b8385e49-99ff-493b-947b-ab750af97c94'::uuid
  )
  ORDER BY job.id
  FOR SHARE;
  PERFORM upload.instrument_v2_id
  FROM public.instrument_v2_upload_status upload
  WHERE upload.instrument_v2_id IN (
    'd822b904-ab46-4ed6-87d3-f414798606be'::uuid,
    '88821d01-71d6-438d-a0d1-8595789c9f85'::uuid,
    'b8385e49-99ff-493b-947b-ab750af97c94'::uuid
  )
  ORDER BY upload.instrument_v2_id
  FOR SHARE;
  PERFORM output.id
  FROM public.instrument_v2_publish_output_manifest output
  WHERE (
    output.instrument_v2_id = 'd822b904-ab46-4ed6-87d3-f414798606be'::uuid
    AND output.run_id = 'run-1784875180655-tseoxq'
  ) OR (
    output.instrument_v2_id = '88821d01-71d6-438d-a0d1-8595789c9f85'::uuid
    AND output.run_id = 'run-1784918411703-lv3uge'
  ) OR (
    output.instrument_v2_id = 'b8385e49-99ff-493b-947b-ab750af97c94'::uuid
    AND output.run_id = 'run-1784921324673-rhmx3u'
  )
  ORDER BY output.id
  FOR SHARE;

  v_preview := public.sip_publish_preview_fmg_terminal_waits_v1(
    p_contributor_slug, p_lease_id, p_lease_token
  );
  v_current_manifest := v_preview->'manifest';
  IF coalesce((v_preview->>'eligible')::boolean, false) IS NOT TRUE
     OR v_preview->>'manifestHash' IS DISTINCT FROM p_manifest_hash
     OR v_current_manifest IS DISTINCT FROM p_manifest THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_snapshot_changed'
      USING ERRCODE = '55000';
  END IF;

  IF NOT public.validate_sip_publish_operator_lease_v1(
    p_contributor_slug, p_lease_id, p_lease_token
  ) THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_lease_expired_before_write'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.sip_fleet_run_items item
      SET status = CASE item.id
        WHEN '29bce41a-f448-4478-bf97-01edac4d34d1'::uuid THEN 'canceled'
        WHEN '854e9736-5f7d-46b0-86c6-e5f0a7903929'::uuid THEN 'failed'
      END,
      finished_at = (
        SELECT run.finished_at
        FROM public.sip_fleet_runs run
        WHERE run.id = item.run_id
      )
  WHERE (
    item.id = '29bce41a-f448-4478-bf97-01edac4d34d1'::uuid
    AND item.run_id = 'f5216bfa-19e7-424d-b382-d7166913ffb1'::uuid
    AND item.instrument_v2_id = 'd822b904-ab46-4ed6-87d3-f414798606be'::uuid
    AND item.status = 'waiting_for_audio_profile'
  ) OR (
    item.id = '854e9736-5f7d-46b0-86c6-e5f0a7903929'::uuid
    AND item.run_id = '7d5d825d-c648-4af8-9a46-b00c51285cb1'::uuid
    AND item.instrument_v2_id = '88821d01-71d6-438d-a0d1-8595789c9f85'::uuid
    AND item.status = 'waiting_for_audio_profile'
  );
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_update_count_mismatch'
      USING ERRCODE = '55000';
  END IF;

  v_result := jsonb_build_object(
    'scopeKey', 'issue-2437-fmg-terminal-profile-waits-v1',
    'providerSlug', 'fallout-music-group',
    'operationClass', 'terminal-history-status-only',
    'readinessAuthorized', false,
    'legacyReceiptBlocker', 'address_output_receipts_incomplete',
    'providerLeaseId', p_lease_id,
    'receiptId', v_receipt_id,
    'manifestHash', p_manifest_hash,
    'reconciledCount', 2,
    'canceledCount', 1,
    'failedCount', 1,
    'idempotent', false
  );
  INSERT INTO public.sip_fmg_terminal_profile_wait_reconciliation_receipts(
    scope_key, receipt_kind, receipt_id, provider_slug, provider_lease_id,
    provider_lease_owner, manifest_hash, manifest, result, applied_by
  ) VALUES (
    'issue-2437-fmg-terminal-profile-waits-v1', 'apply', v_receipt_id,
    'fallout-music-group', p_lease_id, v_lease_owner, p_manifest_hash,
    p_manifest, v_result, btrim(p_applied_by)
  );
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_apply_fmg_terminal_waits_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_apply_orphan_upload_status_reconciliation_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_current_manifest jsonb;
  v_current_hash text;
  v_control jsonb;
  v_existing_manifest jsonb;
  v_existing_result jsonb;
  v_after_control jsonb;
  v_result jsonb;
BEGIN
  IF btrim(coalesce(p_contributor_slug, '')) = ''
     OR p_instrument_v2_id IS NULL
     OR coalesce(p_manifest_hash, '') !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_manifest) IS DISTINCT FROM 'object'
     OR btrim(coalesce(p_applied_by, '')) = '' THEN
    RAISE EXCEPTION 'orphan_upload_status_apply_identity_invalid' USING ERRCODE = '22023';
  END IF;
  IF p_manifest->>'providerSlug' IS DISTINCT FROM btrim(p_contributor_slug)
     OR p_manifest->>'instrumentV2Id' IS DISTINCT FROM p_instrument_v2_id::text THEN
    RAISE EXCEPTION 'orphan_upload_status_manifest_scope_invalid' USING ERRCODE = '22023';
  END IF;
  v_current_hash := encode(digest(convert_to(p_manifest::text, 'UTF8'), 'sha256'), 'hex');
  IF v_current_hash IS DISTINCT FROM p_manifest_hash THEN
    RAISE EXCEPTION 'orphan_upload_status_manifest_hash_mismatch' USING ERRCODE = '22023';
  END IF;

  -- This provider lock is shared with publish admission and operator begin.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );

  SELECT receipt.manifest, receipt.result
    INTO v_existing_manifest, v_existing_result
  FROM public.sip_orphan_upload_status_reconciliation_receipts receipt
  WHERE receipt.provider_slug = btrim(p_contributor_slug)
    AND receipt.instrument_v2_id = p_instrument_v2_id
    AND receipt.manifest_hash = p_manifest_hash
  FOR SHARE;
  IF v_existing_result IS NOT NULL THEN
    IF v_existing_manifest IS DISTINCT FROM p_manifest THEN
      RAISE EXCEPTION 'orphan_upload_status_manifest_hash_collision' USING ERRCODE = '55000';
    END IF;
    RETURN v_existing_result || jsonb_build_object('idempotent', true);
  END IF;

  -- Lock every ownership/control row before re-reading the exact snapshot.
  PERFORM lease.id
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.provider_slug = btrim(p_contributor_slug)
  ORDER BY lease.id
  FOR UPDATE;
  PERFORM run.id
  FROM public.sip_fleet_runs run
  WHERE run.provider_slug = btrim(p_contributor_slug)
  ORDER BY run.id
  FOR UPDATE;
  PERFORM item.id
  FROM public.sip_fleet_run_items item
  JOIN public.sip_fleet_runs run ON run.id = item.run_id
  WHERE item.instrument_v2_id = p_instrument_v2_id
     OR run.provider_slug = btrim(p_contributor_slug)
  ORDER BY item.id
  FOR UPDATE OF item;
  PERFORM instrument.id
  FROM public.instruments_v2 instrument
  WHERE instrument.id = p_instrument_v2_id
  FOR UPDATE;
  PERFORM upload_status.instrument_v2_id
  FROM public.instrument_v2_upload_status upload_status
  WHERE upload_status.instrument_v2_id = p_instrument_v2_id
  FOR UPDATE;
  PERFORM construct.id
  FROM public.sample_path_constructs construct
  WHERE construct.instrument_v2_id = p_instrument_v2_id
  ORDER BY construct.id
  FOR SHARE;
  PERFORM source.id
  FROM public.samples_original_paths source
  WHERE source.id IN (
    SELECT construct.sample_original_path_id
    FROM public.sample_path_constructs construct
    WHERE construct.instrument_v2_id = p_instrument_v2_id
      AND construct.sample_original_path_id IS NOT NULL
  )
  ORDER BY source.id
  FOR SHARE;

  v_current_manifest := public.sip_publish_orphan_upload_status_snapshot_v1(
    p_contributor_slug, p_instrument_v2_id
  );
  IF v_current_manifest IS NULL OR v_current_manifest IS DISTINCT FROM p_manifest THEN
    RAISE EXCEPTION 'orphan_upload_status_snapshot_changed' USING ERRCODE = '55000';
  END IF;
  v_control := v_current_manifest->'control';

  IF (v_current_manifest->>'instrumentPublished')::boolean IS DISTINCT FROM false
     OR coalesce(v_control->>'publish_status', '') <> 'running'
     OR coalesce((v_control->>'publish_actions_applied')::boolean, false) IS NOT TRUE
     OR coalesce((v_control->>'samples_processed')::integer, -1) <> 0
     OR coalesce((v_control->>'samples_total')::integer, -1)
          <> (v_current_manifest->>'constructCount')::integer
     OR (v_current_manifest->>'constructCount')::integer < 1
     OR v_control->>'published_at' IS NOT NULL THEN
    RAISE EXCEPTION 'orphan_upload_status_control_ineligible' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.provider_slug = btrim(p_contributor_slug)
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'orphan_upload_status_active_provider_lease' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.sip_fleet_runs run
    WHERE run.provider_slug = btrim(p_contributor_slug)
      AND run.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'orphan_upload_status_active_provider_run' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.sip_fleet_run_items item
    JOIN public.sip_fleet_runs run ON run.id = item.run_id
    WHERE item.status IN ('queued', 'running', 'waiting_for_audio_profile')
      AND (
        item.instrument_v2_id = p_instrument_v2_id
        OR run.provider_slug = btrim(p_contributor_slug)
      )
  ) THEN
    RAISE EXCEPTION 'orphan_upload_status_active_provider_item' USING ERRCODE = '55000';
  END IF;

  UPDATE public.instrument_v2_upload_status upload_status
  SET
    publish_status = 'failed',
    error_summary = jsonb_build_object(
      'code', 'orphaned_upload_status_no_active_coordinator_item',
      'recoveredAt', clock_timestamp(),
      'manifestHash', p_manifest_hash,
      'previousControl', v_control
    )
  WHERE upload_status.instrument_v2_id = p_instrument_v2_id
    AND upload_status.publish_status = 'running'
    AND upload_status.samples_processed = 0
    AND upload_status.samples_total = (v_current_manifest->>'constructCount')::integer
  RETURNING to_jsonb(upload_status) INTO v_after_control;
  IF v_after_control IS NULL THEN
    RAISE EXCEPTION 'orphan_upload_status_clear_failed' USING ERRCODE = '55000';
  END IF;

  v_result := jsonb_build_object(
    'providerSlug', btrim(p_contributor_slug),
    'instrumentV2Id', p_instrument_v2_id,
    'manifestHash', p_manifest_hash,
    'clearedCount', 1,
    'previousPublishStatus', 'running',
    'currentPublishStatus', 'failed',
    'samplesProcessed', (v_after_control->>'samples_processed')::integer,
    'samplesTotal', (v_after_control->>'samples_total')::integer,
    'idempotent', false
  );
  INSERT INTO public.sip_orphan_upload_status_reconciliation_receipts(
    provider_slug, instrument_v2_id, manifest_hash, manifest, result, applied_by
  ) VALUES (
    btrim(p_contributor_slug), p_instrument_v2_id, p_manifest_hash,
    p_manifest, v_result, btrim(p_applied_by)
  );
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_apply_orphan_upload_status_reconciliation_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_publish_apply_orphan_upload_status_reconciliation_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_applied_by" "text") IS 'Atomically terminalizes only an exact orphan running upload status when the unpublished instrument snapshot is unchanged and no active provider owner or publish work remains.';



CREATE OR REPLACE FUNCTION "public"."sip_publish_apply_parent_pitchless_projection_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_content jsonb;
  v_hash text;
  v_expected_count integer;
  v_seen_count integer;
  v_updated_count integer;
  v_run_id uuid;
BEGIN
  SELECT artifact.content, artifact.content_hash INTO v_content, v_hash
  FROM public.sip_fleet_plan_artifacts artifact
  JOIN public.sip_fleet_plan_artifact_approvals approval
    ON approval.artifact_id=artifact.id AND approval.content_hash=artifact.content_hash
  WHERE artifact.id=p_artifact_id
    AND artifact.provider_slug=btrim(p_contributor_slug)
    AND artifact.artifact_kind='parent-pitchless-projection-v1';
  IF v_content IS NULL THEN RAISE EXCEPTION 'approved_parent_pitchless_artifact_required'; END IF;
  IF jsonb_typeof(v_content->'instruments') <> 'array'
    OR jsonb_array_length(v_content->'instruments')=0
  THEN RAISE EXCEPTION 'parent_pitchless_instruments_required'; END IF;

  SELECT count(DISTINCT instrument->>'instrumentV2Id'), count(*)
    INTO v_expected_count, v_seen_count
  FROM jsonb_array_elements(v_content->'instruments') instrument;
  IF v_expected_count <> v_seen_count THEN RAISE EXCEPTION 'duplicate_instrument_id'; END IF;
  IF p_expected_count IS NULL OR p_expected_count<1 OR p_expected_count<>v_expected_count
  THEN RAISE EXCEPTION 'parent_pitchless_expected_count_mismatch'; END IF;

  SELECT id INTO v_run_id FROM public.sip_fleet_runs
  WHERE provider_slug=btrim(p_contributor_slug)
    AND idempotency_key='parent-pitchless:'||v_hash
    AND status='completed';
  IF v_run_id IS NOT NULL THEN
    RETURN jsonb_build_object('artifactId',p_artifact_id,'runId',v_run_id,
      'contentHash',v_hash,'instrumentCount',v_expected_count,'idempotent',true);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug=btrim(p_contributor_slug)
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>now()
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_content->'instruments') requested(instrument)
    LEFT JOIN public.instruments_v2 instrument ON instrument.id=(requested.instrument->>'instrumentV2Id')::uuid
    LEFT JOIN public.contributors contributor ON contributor.id=instrument.contributor_id
    WHERE instrument.id IS NULL OR contributor.slug<>btrim(p_contributor_slug)
      OR requested.instrument->'target'->>'engineType' <> 'non_tonal'
      OR requested.instrument->'target'->>'singlePitch' IS NOT NULL
      OR requested.instrument->'target'->>'fileNameReference' <> 'pitchless'
      OR coalesce((requested.instrument->'target'->>'rangeLower')::integer, 0) <> 21
      OR coalesce((requested.instrument->'target'->>'rangeUpper')::integer, 0) <> 108
      OR coalesce(requested.instrument->'current'->>'engineType','') <> instrument.engine_type::text
      OR (requested.instrument->'current' ? 'singlePitch'
        AND coalesce(requested.instrument->'current'->>'singlePitch','') <> coalesce(instrument.single_pitch::text,''))
  ) THEN RAISE EXCEPTION 'parent_pitchless_manifest_invalid_or_stale'; END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_content->'instruments') requested(instrument)
    JOIN public.sample_path_constructs c
      ON c.instrument_v2_id=(requested.instrument->>'instrumentV2Id')::uuid
    GROUP BY requested.instrument->>'instrumentV2Id'
    HAVING count(*)=0
      OR count(*) FILTER (WHERE c.midi_note='pitchless' AND c.filename='pitchless') <> count(*)
      OR count(DISTINCT coalesce(nullif(btrim(c.pitch_content),''),'0')) <> 1
      OR min(coalesce(nullif(btrim(c.pitch_content),''),'0')) <> '0'
  ) THEN RAISE EXCEPTION 'parent_pitchless_construct_evidence_required'; END IF;

  PERFORM public.refresh_instrument_v2_axis_summaries_v1(
    ARRAY(
      SELECT (instrument->>'instrumentV2Id')::uuid
      FROM jsonb_array_elements(v_content->'instruments') instrument
    )
  );

  UPDATE public.instruments_v2 instrument SET
    engine_type='non_tonal'::public.instrument_engine_type,
    single_pitch=NULL,
    range_lower=21,
    range_upper=108,
    file_name_references=ARRAY['pitchless']::text[],
    updated_at=now()
  FROM jsonb_array_elements(v_content->'instruments') requested(manifest)
  WHERE instrument.id=(requested.manifest->>'instrumentV2Id')::uuid;
  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count<>v_expected_count THEN RAISE EXCEPTION 'parent_pitchless_update_count_mismatch'; END IF;

  INSERT INTO public.sip_fleet_runs(provider_slug,idempotency_key,plan_artifact_id,
    submitted_by,provider_lease_id,provider_lease_token,status,started_at,finished_at,result_payload)
  VALUES (btrim(p_contributor_slug),'parent-pitchless:'||v_hash,p_artifact_id,
    (SELECT lease_owner FROM public.sip_fleet_provider_leases WHERE id=p_lease_id),
    p_lease_id,p_lease_token,'completed',now(),now(),
    jsonb_build_object('operation','parent-pitchless-projection','instrumentCount',v_updated_count))
  ON CONFLICT (provider_slug,idempotency_key) DO UPDATE SET
    plan_artifact_id=EXCLUDED.plan_artifact_id,
    submitted_by=EXCLUDED.submitted_by,
    provider_lease_id=EXCLUDED.provider_lease_id,
    provider_lease_token=EXCLUDED.provider_lease_token,
    status=EXCLUDED.status,
    started_at=EXCLUDED.started_at,
    finished_at=EXCLUDED.finished_at,
    result_payload=EXCLUDED.result_payload,
    updated_at=now()
  RETURNING id INTO v_run_id;

  INSERT INTO public.sip_fleet_run_items(run_id,item_key,instrument_v2_id,status,
    started_at,finished_at,result_payload)
  SELECT v_run_id,'parent-pitchless:'||(manifest->>'instrumentV2Id'),
    (manifest->>'instrumentV2Id')::uuid,'completed',now(),now(),
    jsonb_build_object('operation','parent-pitchless-projection')
  FROM jsonb_array_elements(v_content->'instruments') manifest
  ON CONFLICT (run_id,item_key) DO NOTHING;

  RETURN jsonb_build_object('artifactId',p_artifact_id,'runId',v_run_id,
    'contentHash',v_hash,'instrumentCount',v_updated_count,'projectedAt',now());
END $$;


ALTER FUNCTION "public"."sip_publish_apply_parent_pitchless_projection_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_publish_apply_parent_pitchless_projection_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer) IS 'Projects reviewed parent pitchless metadata from existing pitchless sample_path_construct evidence under an approved artifact and active provider lease.';



CREATE OR REPLACE FUNCTION "public"."sip_publish_apply_runtime_manifest_materialization_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer, "p_rehearsal_run_id" "uuid", "p_projection_hash" "text", "p_object_identity_hash" "text", "p_expected_construct_count" integer, "p_expected_source_count" integer, "p_expected_target_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '2min'
    SET "lock_timeout" TO '5s'
    AS $$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_rehearsal_id uuid;
  v_validation jsonb;
  v_run_id uuid;
  v_requested jsonb;
  v_instrument_v2_id uuid;
  v_expected jsonb;
  v_readiness jsonb;
  v_existing_count integer;
  v_manifest_generated_at timestamptz;
  v_readiness_evaluated_at timestamptz;
BEGIN
  IF NOT public.validate_sip_publish_operator_lease_v1(
    p_contributor_slug,
    p_lease_id,
    p_lease_token
  ) THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;
  SELECT artifact.* INTO v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  JOIN public.sip_fleet_plan_artifact_approvals approval
    ON approval.artifact_id = artifact.id
   AND approval.content_hash = artifact.content_hash
  WHERE artifact.id = p_artifact_id
    AND artifact.provider_slug = btrim(p_contributor_slug)
    AND artifact.artifact_kind = 'runtime-manifest-materialization-v1';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'approved_runtime_manifest_artifact_required';
  END IF;

  IF p_expected_count IS NULL OR p_expected_count < 1
    OR jsonb_array_length(v_artifact.content->'instrumentV2Ids')
      <> p_expected_count
  THEN
    RAISE EXCEPTION 'runtime_manifest_materialization_expected_count_mismatch';
  END IF;

  SELECT count(*) INTO v_existing_count
  FROM public.sip_runtime_manifest_materialization_receipts receipt
  WHERE receipt.artifact_id = v_artifact.id;
  IF v_existing_count = p_expected_count AND v_existing_count > 0 THEN
    IF EXISTS (
      SELECT 1
      FROM public.sip_runtime_manifest_rollback_receipts rollback
      WHERE rollback.artifact_id = v_artifact.id
    ) THEN
      RAISE EXCEPTION 'runtime_manifest_materialization_already_rolled_back';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM public.sip_runtime_manifest_materialization_receipts receipt
      LEFT JOIN jsonb_array_elements(v_artifact.content->'runtimeManifests') expected(value)
        ON expected.value->>'instrumentV2Id' = receipt.instrument_v2_id::text
      LEFT JOIN public.instrument_runtime_sample_manifests manifest
        ON manifest.instrument_v2_id = receipt.instrument_v2_id
      LEFT JOIN public.instrument_v2_runtime_readiness readiness
        ON readiness.instrument_v2_id = receipt.instrument_v2_id
      WHERE receipt.artifact_id = v_artifact.id
        AND (
          receipt.content_hash IS DISTINCT FROM v_artifact.content_hash
          OR expected.value IS NULL
          OR expected.value->>'manifestSha256'
            IS DISTINCT FROM receipt.manifest_sha256
          OR (expected.value->>'variantCount')::integer
            IS DISTINCT FROM receipt.variant_count
          OR manifest.manifest_sha256 IS DISTINCT FROM receipt.manifest_sha256
          OR manifest.variant_count IS DISTINCT FROM receipt.variant_count
          OR manifest.generated_at IS DISTINCT FROM
            receipt.manifest_generated_at
          OR readiness.manifest_sha256 IS DISTINCT FROM receipt.manifest_sha256
          OR readiness.variant_count IS DISTINCT FROM receipt.variant_count
          OR readiness.evaluated_at IS DISTINCT FROM
            receipt.readiness_evaluated_at
          OR readiness.address_ready IS DISTINCT FROM
            (receipt.runtime_readiness->>'addressReady')::boolean
          OR readiness.behavior_ready IS DISTINCT FROM
            (receipt.runtime_readiness->>'behaviorReady')::boolean
          OR readiness.fallback_state IS DISTINCT FROM
            receipt.runtime_readiness->>'fallbackState'
        )
    ) THEN
      RAISE EXCEPTION 'runtime_manifest_materialization_idempotency_drift';
    END IF;
    SELECT receipt.run_id INTO STRICT v_run_id
    FROM public.sip_runtime_manifest_materialization_receipts receipt
    WHERE receipt.artifact_id = v_artifact.id
    LIMIT 1;
    RETURN jsonb_build_object(
      'artifactId', v_artifact.id,
      'runId', v_run_id,
      'contentHash', v_artifact.content_hash,
      'instrumentCount', v_existing_count,
      'idempotent', true
    );
  ELSIF v_existing_count <> 0 THEN
    RAISE EXCEPTION 'runtime_manifest_materialization_receipts_partial';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    btrim(p_contributor_slug),
    0
  ));
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = btrim(p_contributor_slug)
      AND run.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'active_provider_run';
  END IF;

  SELECT rehearsal.id INTO v_rehearsal_id
  FROM public.sip_anchor_object_verification_rehearsals rehearsal
  JOIN public.sip_fleet_plan_artifact_approvals approval
    ON approval.artifact_id = rehearsal.artifact_id
   AND approval.content_hash = rehearsal.content_hash
  WHERE rehearsal.id = p_rehearsal_run_id
    AND rehearsal.artifact_id = v_artifact.id
    AND rehearsal.content_hash = v_artifact.content_hash
    AND rehearsal.provider_slug = btrim(p_contributor_slug)
    AND rehearsal.provider_lease_id = p_lease_id
    AND rehearsal.provider_lease_token = p_lease_token
    AND rehearsal.status = 'passed'
    AND rehearsal.projection_hash = p_projection_hash
    AND rehearsal.object_identity_hash = p_object_identity_hash
    AND rehearsal.construct_count = p_expected_construct_count
    AND rehearsal.source_count = p_expected_source_count
    AND rehearsal.target_count = p_expected_target_count
    AND rehearsal.completed_at >= clock_timestamp() - interval '15 minutes'
    AND approval.approval_metadata->>'rehearsalRunId' =
      p_rehearsal_run_id::text
  FOR UPDATE OF rehearsal;
  IF v_rehearsal_id IS NULL OR p_expected_target_count <>
      p_expected_construct_count * 9
  THEN
    RAISE EXCEPTION 'matching_passed_anchor_object_verification_required';
  END IF;

  v_validation := public.validate_runtime_manifest_materialization_plan_v1(
    p_contributor_slug,
    v_artifact.content,
    true
  );
  IF p_expected_count IS NULL OR p_expected_count < 1
    OR (v_validation->>'instrumentCount')::integer <> p_expected_count
  THEN
    RAISE EXCEPTION 'runtime_manifest_materialization_expected_count_mismatch';
  END IF;

  INSERT INTO public.sip_fleet_runs(
    provider_slug,
    idempotency_key,
    plan_artifact_id,
    submitted_by,
    provider_lease_id,
    provider_lease_token,
    status,
    started_at,
    finished_at,
    result_payload
  ) VALUES (
    btrim(p_contributor_slug),
    'runtime-manifest-materialization:' || v_artifact.content_hash,
    v_artifact.id,
    (SELECT lease_owner FROM public.sip_fleet_provider_leases
      WHERE id = p_lease_id),
    p_lease_id,
    p_lease_token,
    'completed',
    clock_timestamp(),
    clock_timestamp(),
    jsonb_build_object(
      'operation', 'runtime-manifest-materialization',
      'contentHash', v_artifact.content_hash,
      'instrumentCount', p_expected_count,
      'projectionHash', p_projection_hash,
      'objectIdentityHash', p_object_identity_hash
    )
  ) RETURNING id INTO v_run_id;

  FOR v_requested IN
    SELECT jsonb_build_object('instrumentV2Id', requested.value)
    FROM jsonb_array_elements_text(v_artifact.content->'instrumentV2Ids') requested(value)
    ORDER BY requested.value
  LOOP
    v_instrument_v2_id := (v_requested->>'instrumentV2Id')::uuid;
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'instrument-runtime-sample-manifest:' || v_instrument_v2_id::text,
      0
    ));
    SELECT expected.value INTO STRICT v_expected
    FROM jsonb_array_elements(v_artifact.content->'runtimeManifests') expected(value)
    WHERE expected.value->>'instrumentV2Id' = v_instrument_v2_id::text;
    v_readiness := public.refresh_instrument_v2_runtime_readiness_v1(
      v_instrument_v2_id,
      false
    );
    IF v_readiness->>'manifestSha256'
        IS DISTINCT FROM v_expected->>'manifestSha256'
      OR (v_readiness->>'variantCount')::integer <>
        (v_expected->>'variantCount')::integer
      OR v_readiness->>'fallbackState' IS DISTINCT FROM 'runtime_manifest'
      OR coalesce((v_readiness->>'addressReady')::boolean, false) IS NOT TRUE
      OR coalesce((v_readiness->>'behaviorReady')::boolean, false) IS NOT TRUE
    THEN
      RAISE EXCEPTION 'runtime_manifest_materialization_result_drift';
    END IF;
    SELECT manifest.generated_at, readiness.evaluated_at
    INTO STRICT v_manifest_generated_at, v_readiness_evaluated_at
    FROM public.instrument_runtime_sample_manifests manifest
    JOIN public.instrument_v2_runtime_readiness readiness
      ON readiness.instrument_v2_id = manifest.instrument_v2_id
     AND readiness.manifest_sha256 = manifest.manifest_sha256
    WHERE manifest.instrument_v2_id = v_instrument_v2_id
      AND manifest.manifest_sha256 = v_readiness->>'manifestSha256';
    INSERT INTO public.sip_runtime_manifest_materialization_receipts(
      artifact_id,
      run_id,
      instrument_v2_id,
      content_hash,
      manifest_sha256,
      variant_count,
      runtime_readiness,
      manifest_generated_at,
      readiness_evaluated_at,
      projection_hash,
      object_identity_hash,
      authorizing_xid
    ) VALUES (
      v_artifact.id,
      v_run_id,
      v_instrument_v2_id,
      v_artifact.content_hash,
      v_readiness->>'manifestSha256',
      (v_readiness->>'variantCount')::integer,
      v_readiness,
      v_manifest_generated_at,
      v_readiness_evaluated_at,
      p_projection_hash,
      p_object_identity_hash,
      txid_current()
    );
    INSERT INTO public.sip_fleet_run_items(
      run_id,
      item_key,
      instrument_v2_id,
      status,
      started_at,
      finished_at,
      result_payload
    ) VALUES (
      v_run_id,
      'runtime-manifest:' || v_instrument_v2_id::text,
      v_instrument_v2_id,
      'completed',
      clock_timestamp(),
      clock_timestamp(),
      jsonb_build_object('runtimeManifestReadiness', v_readiness)
    );
  END LOOP;

  RETURN jsonb_build_object(
    'artifactId', v_artifact.id,
    'runId', v_run_id,
    'contentHash', v_artifact.content_hash,
    'instrumentCount', p_expected_count,
    'projectionHash', p_projection_hash,
    'objectIdentityHash', p_object_identity_hash,
    'idempotent', false
  );
END;
$$;


ALTER FUNCTION "public"."sip_publish_apply_runtime_manifest_materialization_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer, "p_rehearsal_run_id" "uuid", "p_projection_hash" "text", "p_object_identity_hash" "text", "p_expected_construct_count" integer, "p_expected_source_count" integer, "p_expected_target_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_apply_staged_promotion_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_staging_snapshot_hash" "text", "p_mutation_plan_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_lease public.sip_fleet_provider_leases%ROWTYPE;
  v_rehearsal public.sip_staged_promotion_rehearsals%ROWTYPE;
  v_plan jsonb;
  v_expected jsonb;
  v_canonical_contributor_id uuid;
  v_source_contributor_slug text;
  v_expected_row jsonb;
  v_actual_row jsonb;
  v_expected_id text;
  v_expected_v2_id text;
  v_current_v2_id text;
  v_expected_ids jsonb;
  v_actual_ids jsonb;
  v_actual_rows jsonb;
  v_source_legato_refs_cleared integer := 0;
  v_staging_synced integer := 0;
  v_v2_legato_refs_cleared integer := 0;
  v_upload_status_rows_upserted integer := 0;
  v_deterministic_readiness_rows_upserted integer := 0;
  v_base_result jsonb;
BEGIN
  SELECT * INTO v_lease
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_lease.provider_slug IS DISTINCT FROM p_contributor_slug
     OR v_lease.lease_token IS DISTINCT FROM p_lease_token
     OR v_lease.lease_expires_at <= now()
     OR v_lease.released_at IS NOT NULL THEN
    RAISE EXCEPTION 'invalid_coordinator_publish_authorization';
  END IF;

  SELECT * INTO v_rehearsal
  FROM public.sip_staged_promotion_rehearsals rehearsal
  WHERE rehearsal.id = p_rehearsal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_not_found';
  END IF;
  IF v_rehearsal.status = 'applied' THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_already_applied';
  END IF;
  IF v_rehearsal.provider_slug IS DISTINCT FROM p_contributor_slug
     OR v_rehearsal.provider_lease_id IS DISTINCT FROM p_lease_id
     OR v_rehearsal.provider_lease_token IS DISTINCT FROM p_lease_token THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_lease_mismatch';
  END IF;
  IF v_rehearsal.staging_snapshot_hash IS DISTINCT FROM p_staging_snapshot_hash
     OR v_rehearsal.mutation_plan_hash IS DISTINCT FROM p_mutation_plan_hash THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_hash_mismatch';
  END IF;

  v_plan := v_rehearsal.mutation_plan;
  IF encode(extensions.digest(v_plan::text, 'sha256'), 'hex')
       IS DISTINCT FROM v_rehearsal.mutation_plan_content_hash
     OR encode(extensions.digest(v_rehearsal.mutation_plan_canonical_json, 'sha256'), 'hex')
          IS DISTINCT FROM v_rehearsal.mutation_plan_hash
     OR v_rehearsal.mutation_plan_canonical_json::jsonb IS DISTINCT FROM v_plan
     OR NOT public.sip_staged_promotion_plan_is_structurally_valid_v1(
       v_plan,
       p_contributor_slug,
       p_lease_id
     ) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_plan_integrity_failed';
  END IF;
  v_expected := COALESCE(v_plan->'expectedState', '{}'::jsonb);
  v_canonical_contributor_id :=
    (v_plan->>'canonicalContributorId')::uuid;
  v_source_contributor_slug := v_plan->>'sourceContributorSlug';

  -- Freeze the live legal destination owner for the rest of the transaction,
  -- then re-resolve the provider slug under that lock. This rejects a receipt
  -- whose hash-valid canonical identity no longer matches the provider.
  PERFORM 1
  FROM public.contributors contributor
  WHERE contributor.id = v_canonical_contributor_id
  FOR SHARE;
  IF NOT FOUND
     OR public.sip_publish_coordinator_contributor_id_v1(p_contributor_slug)
          IS DISTINCT FROM v_canonical_contributor_id THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_provider_identity_mismatch';
  END IF;

  -- Lock and compare the exact reviewed staging projection. Expected JSON is a
  -- deliberately selected field subset; every field present in the receipt
  -- must still match when the transaction begins.
  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(COALESCE(v_expected->'stagingRows', '[]'::jsonb))
  LOOP
    v_expected_id := v_expected_row->>'id';
    SELECT to_jsonb(live) INTO v_actual_row
    FROM public.sip_review_instrument live
    WHERE live.id = v_expected_id::uuid
    FOR UPDATE;
    IF NOT public.sip_jsonb_expected_subset_matches_v1(v_actual_row, v_expected_row) THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:staging:%', v_expected_id
        USING ERRCODE = '40001';
    END IF;
  END LOOP;

  PERFORM 1 FROM public.sip_instrument live
  WHERE live.id IN (
    SELECT value::uuid
    FROM jsonb_array_elements_text(v_expected->'relationshipResolutionSourceIds') item(value)
  ) FOR UPDATE;
  PERFORM 1 FROM public.sip_review_instrument live
  WHERE live.source_contributor_slug = v_source_contributor_slug
    AND live.split_parent_sip_review_instrument_id IS NULL
    AND live.is_retired = false
    AND live.source_sip_instrument_id IN (
      SELECT value::uuid
      FROM jsonb_array_elements_text(v_expected->'relationshipResolutionSourceIds') item(value)
    ) FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(projected) ORDER BY to_jsonb(projected)::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT live.id, live.source_sip_instrument_id
    FROM public.sip_review_instrument live
    WHERE live.source_contributor_slug = v_source_contributor_slug
      AND live.split_parent_sip_review_instrument_id IS NULL
      AND live.is_retired = false
      AND live.source_sip_instrument_id IN (
        SELECT value::uuid
        FROM jsonb_array_elements_text(v_expected->'relationshipResolutionSourceIds') item(value)
      )
  ) projected;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'relationshipResolutionStagingRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:relationship-resolution-staging-set' USING ERRCODE = '40001';
  END IF;

  PERFORM 1 FROM public.sip_review_promotion_map live
  WHERE live.sip_review_instrument_id IN (
    SELECT (row_json->>'id')::uuid
    FROM jsonb_array_elements(v_expected->'relationshipResolutionStagingRows') item(row_json)
  ) FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(projected) ORDER BY to_jsonb(projected)::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT live.sip_review_instrument_id, live.instrument_v2_id
    FROM public.sip_review_promotion_map live
    WHERE live.sip_review_instrument_id IN (
      SELECT (row_json->>'id')::uuid
      FROM jsonb_array_elements(v_expected->'relationshipResolutionStagingRows') item(row_json)
    )
  ) projected;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'relationshipResolutionPromotionMapRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:relationship-resolution-map-set' USING ERRCODE = '40001';
  END IF;

  PERFORM 1 FROM public.sip_review_instrument live
  WHERE live.source_contributor_slug = v_source_contributor_slug
    AND live.is_retired = false
    AND live.source_sip_instrument_id IN (
      SELECT value::uuid
      FROM jsonb_array_elements_text(v_expected->'relationshipValidationSourceIds') item(value)
    ) FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(projected) ORDER BY to_jsonb(projected)::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT live.id, live.source_sip_instrument_id, live.playback_type,
      live.is_retired
    FROM public.sip_review_instrument live
    WHERE live.source_contributor_slug = v_source_contributor_slug
      AND live.is_retired = false
      AND live.source_sip_instrument_id IN (
        SELECT value::uuid
        FROM jsonb_array_elements_text(v_expected->'relationshipValidationSourceIds') item(value)
      )
  ) projected;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'relationshipValidationRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:relationship-validation-set' USING ERRCODE = '40001';
  END IF;

  -- Bind every mutable row that fed the normalized plan. The selected staging
  -- rows are already locked above, which also prevents new FK children from
  -- appearing while these exact-set checks and the promotion execute.
  PERFORM 1 FROM public.sip_review_instrument_sample_scope live
  WHERE live.sip_review_instrument_id IN (
    SELECT (row_json->>'id')::uuid
    FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
  ) FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(projected) ORDER BY to_jsonb(projected)::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT live.sip_review_instrument_id, live.original_sample_id
    FROM public.sip_review_instrument_sample_scope live
    WHERE live.sip_review_instrument_id IN (
      SELECT (row_json->>'id')::uuid
      FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
    )
  ) projected;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'sampleScopeRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:sample-scope-set' USING ERRCODE = '40001';
  END IF;

  PERFORM 1 FROM public.sip_review_sample_disposition live
  WHERE live.sip_review_instrument_id IN (
    SELECT (row_json->>'id')::uuid
    FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
  ) AND live.disposition = 'deferred_provenance' FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(projected) ORDER BY to_jsonb(projected)::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT live.sip_review_instrument_id, live.original_sample_id
    FROM public.sip_review_sample_disposition live
    WHERE live.sip_review_instrument_id IN (
      SELECT (row_json->>'id')::uuid
      FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
    ) AND live.disposition = 'deferred_provenance'
  ) projected;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'sampleDispositionRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:sample-disposition-set' USING ERRCODE = '40001';
  END IF;

  -- Lock source sample identities before checking construct/override inputs;
  -- their FK locks prevent a late row from entering either reviewed set.
  PERFORM 1 FROM public.samples_original_paths live
  WHERE live.id IN (
    SELECT (row_json->>'sample_original_path_id')::uuid
    FROM jsonb_array_elements(v_plan->'sampleConstructRows') item(row_json)
  ) FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(projected) ORDER BY to_jsonb(projected)::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT live.id, live.s3_path
    FROM public.samples_original_paths live
    WHERE live.id IN (
      SELECT (row_json->>'sample_original_path_id')::uuid
      FROM jsonb_array_elements(v_plan->'sampleConstructRows') item(row_json)
    )
  ) projected;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'sampleOriginalPathRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:sample-original-path-set' USING ERRCODE = '40001';
  END IF;

  PERFORM 1 FROM public.sip_sample_construct live
  WHERE live.original_sample_id IN (
    SELECT (row_json->>'sample_original_path_id')::uuid
    FROM jsonb_array_elements(v_plan->'sampleConstructRows') item(row_json)
  ) AND live.contributor_slug = v_source_contributor_slug FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(projected) ORDER BY to_jsonb(projected)::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT live.original_sample_id, live.collection, live.file_path,
      live.instrument_name, live.articulation, live.effect, live.mic_position,
      live.velocity, live.round_robin, live.midi_note, live.pitch_content,
      live.filename, live.confidence, live.source, live.name, live.playback_type
    FROM public.sip_sample_construct live
    WHERE live.original_sample_id IN (
      SELECT (row_json->>'sample_original_path_id')::uuid
      FROM jsonb_array_elements(v_plan->'sampleConstructRows') item(row_json)
    ) AND live.contributor_slug = v_source_contributor_slug
  ) projected;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'baseSampleConstructRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:base-sample-construct-set' USING ERRCODE = '40001';
  END IF;

  PERFORM 1 FROM public.sip_review_sample_override live
  WHERE live.sip_review_instrument_id IN (
    SELECT (row_json->>'id')::uuid
    FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
  ) FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(live) ORDER BY to_jsonb(live)::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM public.sip_review_sample_override live
  WHERE live.sip_review_instrument_id IN (
    SELECT (row_json->>'id')::uuid
    FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
  );
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'sampleOverrideRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:sample-override-set' USING ERRCODE = '40001';
  END IF;

  PERFORM 1
  FROM public.sip_review_instrument_tag link
  JOIN public.instrument_tags tag ON tag.id = link.tag_id
  WHERE link.sip_review_instrument_id IN (
    SELECT (row_json->>'id')::uuid
    FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
  ) FOR UPDATE OF link, tag;
  SELECT COALESCE(jsonb_agg(row_json ORDER BY row_json::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT jsonb_build_object(
      'sip_review_instrument_id', link.sip_review_instrument_id,
      'tag_id', link.tag_id,
      'source', link.source,
      'instrument_tags', jsonb_build_object(
        'id', tag.id, 'tag_group', tag.tag_group, 'tag_name', tag.tag_name
      )
    ) AS row_json
    FROM public.sip_review_instrument_tag link
    JOIN public.instrument_tags tag ON tag.id = link.tag_id
    WHERE link.sip_review_instrument_id IN (
      SELECT (row_json->>'id')::uuid
      FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
    )
  ) rows;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'reviewTagRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:review-tag-set' USING ERRCODE = '40001';
  END IF;

  PERFORM 1
  FROM public.sip_review_legacy_map link
  JOIN public.instruments legacy ON legacy.id = link.legacy_instrument_id
  WHERE link.sip_review_instrument_id IN (
    SELECT (row_json->>'id')::uuid
    FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
  ) FOR UPDATE OF link, legacy;
  SELECT COALESCE(jsonb_agg(row_json ORDER BY row_json::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT jsonb_build_object(
      'sip_review_instrument_id', link.sip_review_instrument_id,
      'legacy_instrument_id', link.legacy_instrument_id,
      'contributor_slug', link.contributor_slug,
      'notes', link.notes,
      'instruments', jsonb_build_object(
        'id', legacy.id, 'name', legacy.name, 'firebase_id', legacy.firebase_id,
        'file_path_reference', legacy.file_path_reference,
        'velocity_layers', legacy.velocity_layers
      )
    ) AS row_json
    FROM public.sip_review_legacy_map link
    JOIN public.instruments legacy ON legacy.id = link.legacy_instrument_id
    WHERE link.sip_review_instrument_id IN (
      SELECT (row_json->>'id')::uuid
      FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
    )
  ) rows;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'legacyMapRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:legacy-map-set' USING ERRCODE = '40001';
  END IF;

  PERFORM 1 FROM public.instrument_v2_legacy_map live
  WHERE live.legacy_instrument_id IN (
    SELECT (row_json->>'legacy_instrument_id')::uuid
    FROM jsonb_array_elements(v_plan->'legacyAliasRows') item(row_json)
  ) OR live.instrument_v2_id IN (
    SELECT (row_json->>'id')::uuid
    FROM jsonb_array_elements(v_plan->'instrumentRows') item(row_json)
  ) FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(projected) ORDER BY to_jsonb(projected)::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT live.legacy_instrument_id, live.instrument_v2_id,
      live.is_primary_for_legacy, live.is_primary_for_v2
    FROM public.instrument_v2_legacy_map live
    WHERE live.legacy_instrument_id IN (
      SELECT (row_json->>'legacy_instrument_id')::uuid
      FROM jsonb_array_elements(v_plan->'legacyAliasRows') item(row_json)
    ) OR live.instrument_v2_id IN (
      SELECT (row_json->>'id')::uuid
      FROM jsonb_array_elements(v_plan->'instrumentRows') item(row_json)
    )
  ) projected;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'existingLegacyAliasRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:existing-legacy-alias-set' USING ERRCODE = '40001';
  END IF;

  PERFORM 1 FROM public.sip_review_sample_playback_cues live
  WHERE live.sip_review_instrument_id IN (
    SELECT (row_json->>'id')::uuid
    FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
  ) FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(projected) ORDER BY to_jsonb(projected)::text), '[]'::jsonb)
  INTO v_actual_rows
  FROM (
    SELECT live.sip_review_instrument_id, live.original_sample_id,
      live.sync_point_ms, live.loop_start_offset_ms, live.loop_end_offset_ms,
      live.sync_point_status, live.loop_start_status, live.loop_end_status,
      live.analysis_payload
    FROM public.sip_review_sample_playback_cues live
    WHERE live.sip_review_instrument_id IN (
      SELECT (row_json->>'id')::uuid
      FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
    )
  ) projected;
  IF NOT public.sip_jsonb_row_sets_match_v1(v_expected->'reviewPlaybackCueRows', v_actual_rows) THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:review-playback-cue-set' USING ERRCODE = '40001';
  END IF;

  -- The clear operation selects source relationship consumers by their child
  -- reference. Lock and compare the complete set so a late-added consumer is
  -- not silently omitted from the rehearsed mutation.
  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(COALESCE(v_expected->'sourceRelationshipRows', '[]'::jsonb))
  LOOP
    v_expected_id := v_expected_row->>'id';
    SELECT to_jsonb(live) INTO v_actual_row
    FROM public.sip_instrument live
    WHERE live.id = v_expected_id::uuid
    FOR UPDATE;
    IF NOT public.sip_jsonb_expected_subset_matches_v1(v_actual_row, v_expected_row) THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:source-relationship:%', v_expected_id
        USING ERRCODE = '40001';
    END IF;
  END LOOP;
  SELECT COALESCE(jsonb_agg(row_json->>'id' ORDER BY row_json->>'id'), '[]'::jsonb)
  INTO v_expected_ids
  FROM jsonb_array_elements(COALESCE(v_expected->'sourceRelationshipRows', '[]'::jsonb)) item(row_json);
  SELECT COALESCE(jsonb_agg(live.id::text ORDER BY live.id::text), '[]'::jsonb)
  INTO v_actual_ids
  FROM public.sip_instrument live
  WHERE live.legato_transition IN (
    SELECT value::uuid
    FROM jsonb_array_elements_text(v_plan->'sourceLegatoTransitionParentIdsToClear') item(value)
  );
  IF v_actual_ids IS DISTINCT FROM v_expected_ids THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:source-relationship-set'
      USING ERRCODE = '40001';
  END IF;

  -- Source rows are updated below, so bind and lock their complete recorded
  -- state before applying the reviewed staging projection.
  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(COALESCE(v_expected->'sourceInstrumentRows', '[]'::jsonb))
  LOOP
    v_expected_id := v_expected_row->>'id';
    SELECT to_jsonb(live) INTO v_actual_row
    FROM public.sip_instrument live
    WHERE live.id = v_expected_id::uuid
    FOR UPDATE;
    IF NOT public.sip_jsonb_expected_subset_matches_v1(v_actual_row, v_expected_row) THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:source:%', v_expected_id
        USING ERRCODE = '40001';
    END IF;
  END LOOP;

  -- A promotion-map row appearing or changing after rehearsal changes the
  -- stable V2 identity and must fail closed.
  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(COALESCE(v_expected->'promotionMap', '[]'::jsonb))
  LOOP
    v_expected_id := v_expected_row->>'stagingId';
    v_expected_v2_id := NULLIF(v_expected_row->>'instrumentV2Id', '');
    SELECT map.instrument_v2_id::text INTO v_current_v2_id
    FROM public.sip_review_promotion_map map
    WHERE map.sip_review_instrument_id = v_expected_id::uuid
    FOR UPDATE;
    IF v_current_v2_id IS DISTINCT FROM v_expected_v2_id THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:promotion-map:%', v_expected_id
        USING ERRCODE = '40001';
    END IF;
  END LOOP;

  -- Existing target constructs and upload rows participate in idempotency and
  -- replace-in-place decisions. Lock them before any source/relationship write.
  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(COALESCE(v_expected->'constructRows', '[]'::jsonb))
  LOOP
    v_expected_id := v_expected_row->>'id';
    SELECT to_jsonb(live) INTO v_actual_row
    FROM public.sample_path_constructs live
    WHERE live.id = v_expected_id::uuid
    FOR UPDATE;
    IF NOT public.sip_jsonb_expected_subset_matches_v1(v_actual_row, v_expected_row) THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:construct:%', v_expected_id
        USING ERRCODE = '40001';
    END IF;
  END LOOP;
  SELECT COALESCE(jsonb_agg(row_json->>'id' ORDER BY row_json->>'id'), '[]'::jsonb)
  INTO v_expected_ids
  FROM jsonb_array_elements(COALESCE(v_expected->'constructRows', '[]'::jsonb)) item(row_json);
  SELECT COALESCE(jsonb_agg(live.id::text ORDER BY live.id::text), '[]'::jsonb)
  INTO v_actual_ids
  FROM public.sample_path_constructs live
  WHERE live.instrument_v2_id IN (
    SELECT value::uuid
    FROM jsonb_array_elements_text(v_expected->'constructInstrumentV2Ids') item(value)
  );
  IF v_actual_ids IS DISTINCT FROM v_expected_ids THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:construct-set'
      USING ERRCODE = '40001';
  END IF;

  -- A target V2 row may legitimately be absent during rehearsal. Bind both
  -- absence and complete existing-row state before the promotion upsert.
  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(COALESCE(v_expected->'targetInstrumentV2Rows', '[]'::jsonb))
  LOOP
    v_expected_v2_id := v_expected_row->>'instrumentV2Id';
    SELECT to_jsonb(live) INTO v_actual_row
    FROM public.instruments_v2 live
    WHERE live.id = v_expected_v2_id::uuid
    FOR UPDATE;
    IF (v_expected_row->>'exists')::boolean IS DISTINCT FROM (v_actual_row IS NOT NULL)
       OR (
         (v_expected_row->>'exists')::boolean
         AND NOT public.sip_jsonb_expected_subset_matches_v1(
           v_actual_row,
           COALESCE(v_expected_row->'row', '{}'::jsonb)
         )
       ) THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:target-v2:%', v_expected_v2_id
        USING ERRCODE = '40001';
    END IF;
  END LOOP;

  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(COALESCE(v_expected->'uploadStatus', '[]'::jsonb))
  LOOP
    v_expected_v2_id := v_expected_row->>'instrumentV2Id';
    SELECT to_jsonb(live) INTO v_actual_row
    FROM public.instrument_v2_upload_status live
    WHERE live.instrument_v2_id = v_expected_v2_id::uuid
    FOR UPDATE;
    IF (v_expected_row->>'exists')::boolean IS DISTINCT FROM (v_actual_row IS NOT NULL)
       OR (
         (v_expected_row->>'exists')::boolean
         AND NOT public.sip_jsonb_expected_subset_matches_v1(
           v_actual_row,
           COALESCE(v_expected_row->'row', '{}'::jsonb)
         )
       ) THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:upload-status:%', v_expected_v2_id
        USING ERRCODE = '40001';
    END IF;
  END LOOP;
  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(COALESCE(v_expected->'externalV2Relationships', '[]'::jsonb))
  LOOP
    v_expected_id := v_expected_row->>'id';
    SELECT to_jsonb(live) INTO v_actual_row
    FROM public.instruments_v2 live
    WHERE live.id = v_expected_id::uuid
    FOR UPDATE;
    IF NOT public.sip_jsonb_expected_subset_matches_v1(v_actual_row, v_expected_row) THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:v2-relationship:%', v_expected_id
      USING ERRCODE = '40001';
    END IF;
  END LOOP;
  SELECT COALESCE(jsonb_agg(row_json->>'id' ORDER BY row_json->>'id'), '[]'::jsonb)
  INTO v_expected_ids
  FROM jsonb_array_elements(COALESCE(v_expected->'externalV2Relationships', '[]'::jsonb)) item(row_json);
  SELECT COALESCE(jsonb_agg(live.id::text ORDER BY live.id::text), '[]'::jsonb)
  INTO v_actual_ids
  FROM public.instruments_v2 live
  WHERE live.legato_transition IN (
    SELECT value::uuid
    FROM jsonb_array_elements_text(v_plan->'externalV2LegatoChildIdsLeavingTransition') item(value)
  )
    AND live.id NOT IN (
      SELECT (row_json->>'id')::uuid
      FROM jsonb_array_elements(v_plan->'instrumentRows') item(row_json)
    );
  IF v_actual_ids IS DISTINCT FROM v_expected_ids THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:v2-relationship-set'
      USING ERRCODE = '40001';
  END IF;

  -- Replace-in-place can delete a retiring V2 row, detach its constructs, and
  -- rewrite every relationship consumer. Bind and lock all three complete
  -- sets before the nested coordinator RPC performs any of those writes.
  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(v_expected->'replaceInPlaceTargetRows')
  LOOP
    v_expected_id := v_expected_row->>'id';
    SELECT to_jsonb(live) INTO v_actual_row
    FROM public.instruments_v2 live
    WHERE live.id = v_expected_id::uuid
    FOR UPDATE;
    IF NOT public.sip_jsonb_expected_subset_matches_v1(v_actual_row, v_expected_row) THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:replace-target:%', v_expected_id
        USING ERRCODE = '40001';
    END IF;
  END LOOP;

  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(v_expected->'replaceInPlaceRelationshipRows')
  LOOP
    v_expected_id := v_expected_row->>'id';
    SELECT to_jsonb(live) INTO v_actual_row
    FROM public.instruments_v2 live
    WHERE live.id = v_expected_id::uuid
    FOR UPDATE;
    IF NOT public.sip_jsonb_expected_subset_matches_v1(v_actual_row, v_expected_row) THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:replace-relationship:%', v_expected_id
        USING ERRCODE = '40001';
    END IF;
  END LOOP;
  SELECT COALESCE(jsonb_agg(row_json->>'id' ORDER BY row_json->>'id'), '[]'::jsonb)
  INTO v_expected_ids
  FROM jsonb_array_elements(v_expected->'replaceInPlaceRelationshipRows') item(row_json);
  SELECT COALESCE(jsonb_agg(live.id::text ORDER BY live.id::text), '[]'::jsonb)
  INTO v_actual_ids
  FROM public.instruments_v2 live
  WHERE live.articulations && ARRAY(
          SELECT (row_json->>'retiring_instrument_v2_id')::uuid
          FROM jsonb_array_elements(v_plan->'replaceInPlaceRows') item(row_json)
        )
     OR live.effects_instruments && ARRAY(
          SELECT (row_json->>'retiring_instrument_v2_id')::uuid
          FROM jsonb_array_elements(v_plan->'replaceInPlaceRows') item(row_json)
        )
     OR live.legato_transition IN (
          SELECT (row_json->>'retiring_instrument_v2_id')::uuid
          FROM jsonb_array_elements(v_plan->'replaceInPlaceRows') item(row_json)
        );
  IF v_actual_ids IS DISTINCT FROM v_expected_ids THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:replace-relationship-set'
      USING ERRCODE = '40001';
  END IF;

  FOR v_expected_row IN
    SELECT value FROM jsonb_array_elements(v_expected->'replaceInPlaceConstructRows')
  LOOP
    v_expected_id := v_expected_row->>'id';
    SELECT to_jsonb(live) INTO v_actual_row
    FROM public.sample_path_constructs live
    WHERE live.id = v_expected_id::uuid
    FOR UPDATE;
    IF NOT public.sip_jsonb_expected_subset_matches_v1(v_actual_row, v_expected_row) THEN
      RAISE EXCEPTION 'staged_promotion_rehearsal_drift:replace-construct:%', v_expected_id
        USING ERRCODE = '40001';
    END IF;
  END LOOP;
  SELECT COALESCE(jsonb_agg(row_json->>'id' ORDER BY row_json->>'id'), '[]'::jsonb)
  INTO v_expected_ids
  FROM jsonb_array_elements(v_expected->'replaceInPlaceConstructRows') item(row_json);
  SELECT COALESCE(jsonb_agg(live.id::text ORDER BY live.id::text), '[]'::jsonb)
  INTO v_actual_ids
  FROM public.sample_path_constructs live
  WHERE live.instrument_v2_id IN (
    SELECT (row_json->>'retiring_instrument_v2_id')::uuid
    FROM jsonb_array_elements(v_plan->'replaceInPlaceRows') item(row_json)
  );
  IF v_actual_ids IS DISTINCT FROM v_expected_ids THEN
    RAISE EXCEPTION 'staged_promotion_rehearsal_drift:replace-construct-set'
      USING ERRCODE = '40001';
  END IF;

  -- The transaction may have waited on any of the locked receipt/state rows
  -- above. Re-read the already-locked lease and use wall-clock time at the last
  -- safe point before the first provider mutation or receipt consumption.
  SELECT * INTO v_lease
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_lease.provider_slug IS DISTINCT FROM p_contributor_slug
     OR v_lease.lease_token IS DISTINCT FROM p_lease_token
     OR v_lease.lease_expires_at <= clock_timestamp()
     OR v_lease.released_at IS NOT NULL THEN
    RAISE EXCEPTION 'invalid_coordinator_publish_authorization';
  END IF;

  PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);

  WITH cleared AS (
    UPDATE public.sip_instrument parent
    SET legato_transition = NULL
    WHERE parent.legato_transition IN (
      SELECT value::uuid
      FROM jsonb_array_elements_text(
        COALESCE(v_plan->'sourceLegatoTransitionParentIdsToClear', '[]'::jsonb)
      ) item(value)
    )
    RETURNING 1
  ) SELECT count(*) INTO v_source_legato_refs_cleared FROM cleared;

  WITH patches AS (
    SELECT
      (item.value->>'sourceInstrumentId')::uuid AS id,
      jsonb_populate_record(NULL::public.sip_instrument, item.value->'patch') AS row_data
    FROM jsonb_array_elements(COALESCE(v_plan->'sourceInstrumentPatches', '[]'::jsonb)) item(value)
  ), updated AS (
    UPDATE public.sip_instrument target SET
      name = (patches.row_data).name,
      engine_type = (patches.row_data).engine_type,
      playback_type = (patches.row_data).playback_type,
      polyphony_type = (patches.row_data).polyphony_type,
      instrument_family = (patches.row_data).instrument_family,
      instrument_type = (patches.row_data).instrument_type,
      contributor_id = (patches.row_data).contributor_id,
      collection = (patches.row_data).collection,
      pitch_contents = (patches.row_data).pitch_contents,
      velocity_layers = (patches.row_data).velocity_layers,
      pitch_content_config = (patches.row_data).pitch_content_config,
      round_robins = (patches.row_data).round_robins,
      mic_positions = (patches.row_data).mic_positions,
      articulation = (patches.row_data).articulation,
      effect = (patches.row_data).effect,
      range_lower = (patches.row_data).range_lower,
      range_upper = (patches.row_data).range_upper,
      single_pitch = (patches.row_data).single_pitch,
      gain = (patches.row_data).gain,
      sustain_crop_time = (patches.row_data).sustain_crop_time,
      original_file_path_reference = (patches.row_data).original_file_path_reference,
      original_file_name_references = (patches.row_data).original_file_name_references,
      articulations = (patches.row_data).articulations,
      effects_instruments = (patches.row_data).effects_instruments,
      legato_transition = (patches.row_data).legato_transition,
      published = (patches.row_data).published,
      updated_at = now()
    FROM patches
    WHERE target.id = patches.id
    RETURNING 1
  ) SELECT count(*) INTO v_staging_synced FROM updated;

  WITH cleared AS (
    UPDATE public.instruments_v2 parent
    SET legato_transition = NULL
    WHERE parent.id IN (
      SELECT value::uuid
      FROM jsonb_array_elements_text(
        COALESCE(v_plan->'externalV2LegatoParentIdsToClear', '[]'::jsonb)
      ) item(value)
    )
    RETURNING 1
  ) SELECT count(*) INTO v_v2_legato_refs_cleared FROM cleared;

  v_base_result := public.promote_sip_instruments_v2_coordinated(
    p_contributor_slug,
    p_lease_id,
    p_lease_token,
    COALESCE(v_plan->'instrumentRows', '[]'::jsonb),
    COALESCE(v_plan->'promotionLinks', '[]'::jsonb),
    COALESCE(v_plan->'sampleConstructRows', '[]'::jsonb),
    COALESCE(v_plan->'legacyAliasRows', '[]'::jsonb),
    COALESCE(v_plan->'sipTagRows', '[]'::jsonb),
    COALESCE(v_plan->'v2TagRows', '[]'::jsonb),
    COALESCE(v_plan->'uploadRows', '[]'::jsonb),
    COALESCE(v_plan->'metadataRows', '[]'::jsonb),
    COALESCE(v_plan->'samplePlaybackCueRows', '[]'::jsonb),
    COALESCE(v_plan->'replaceInstrumentV2Ids', '[]'::jsonb),
    COALESCE(v_plan->'replaceInPlaceRows', '[]'::jsonb)
  );

  IF jsonb_array_length(COALESCE(v_plan->'uploadStatusRows', '[]'::jsonb)) > 0 THEN
    WITH rows AS (
      SELECT jsonb_populate_record(NULL::public.instrument_v2_upload_status, value) AS row_data
      FROM jsonb_array_elements(v_plan->'uploadStatusRows') item(value)
    ), upserted AS (
      INSERT INTO public.instrument_v2_upload_status (
        instrument_v2_id, publish_actions_applied, publish_status,
        samples_processed, samples_total, needs, duration_policy,
        error_summary, published_at
      )
      SELECT
        (rows.row_data).instrument_v2_id,
        COALESCE((rows.row_data).publish_actions_applied, false),
        (rows.row_data).publish_status,
        COALESCE((rows.row_data).samples_processed, 0),
        COALESCE((rows.row_data).samples_total, 0),
        COALESCE((rows.row_data).needs, ARRAY[]::text[]),
        (rows.row_data).duration_policy,
        (rows.row_data).error_summary,
        (rows.row_data).published_at
      FROM rows
      ON CONFLICT (instrument_v2_id) DO UPDATE SET
        publish_actions_applied = EXCLUDED.publish_actions_applied,
        publish_status = EXCLUDED.publish_status,
        samples_processed = EXCLUDED.samples_processed,
        samples_total = EXCLUDED.samples_total,
        needs = EXCLUDED.needs,
        duration_policy = EXCLUDED.duration_policy,
        error_summary = EXCLUDED.error_summary,
        published_at = EXCLUDED.published_at,
        updated_at = now()
      RETURNING 1
    ) SELECT count(*) INTO v_upload_status_rows_upserted FROM upserted;
  END IF;

  IF jsonb_array_length(v_plan->'deterministicReadinessRows') > 0 THEN
    WITH rows AS (
      SELECT *
      FROM jsonb_to_recordset(v_plan->'deterministicReadinessRows') AS row_data(
        instrument_v2_id uuid,
        snapshot_sha256 text,
        snapshot jsonb,
        status text,
        workflow_kind text,
        run_id text,
        final_audit jsonb,
        approved_exception jsonb,
        created_by text
      )
    ), upserted AS (
      INSERT INTO public.instrument_v2_deterministic_readiness (
        instrument_v2_id, snapshot_sha256, snapshot, status, workflow_kind,
        run_id, final_audit, approved_exception, created_by
      )
      SELECT
        instrument_v2_id, snapshot_sha256, snapshot, status, workflow_kind,
        run_id, final_audit, approved_exception, created_by
      FROM rows
      ON CONFLICT (instrument_v2_id, snapshot_sha256) DO UPDATE SET
        snapshot = EXCLUDED.snapshot,
        status = EXCLUDED.status,
        workflow_kind = EXCLUDED.workflow_kind,
        run_id = EXCLUDED.run_id,
        final_audit = EXCLUDED.final_audit,
        approved_exception = EXCLUDED.approved_exception,
        created_by = EXCLUDED.created_by,
        updated_at = now()
      RETURNING 1
    ) SELECT count(*) INTO v_deterministic_readiness_rows_upserted FROM upserted;
  END IF;

  v_base_result := v_base_result || jsonb_build_object(
    'rehearsalId', v_rehearsal.id,
    'sourceLegatoRefsCleared', v_source_legato_refs_cleared,
    'stagingSynced', v_staging_synced,
    'v2LegatoRefsCleared', v_v2_legato_refs_cleared,
    'uploadStatusRowsUpserted', v_upload_status_rows_upserted,
    'deterministicReadinessRowsUpserted', v_deterministic_readiness_rows_upserted
  );

  UPDATE public.sip_staged_promotion_rehearsals
  SET status = 'applied', applied_at = now(), applied_result = v_base_result
  WHERE id = v_rehearsal.id;

  RETURN v_base_result;
END
$$;


ALTER FUNCTION "public"."sip_publish_apply_staged_promotion_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsal_id" "uuid", "p_staging_snapshot_hash" "text", "p_mutation_plan_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_apply_versioned_output_prefix_v1"("p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_expected_object_identity_hash" "text", "p_expected_approval_receipt_id" "uuid", "p_expected_approval_receipt_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_existing public.sip_versioned_output_prefix_application_receipts%ROWTYPE;
  v_rehearsal public.sip_versioned_output_prefix_rehearsal_receipts%ROWTYPE;
  v_approval public.sip_versioned_output_prefix_approval_receipts%ROWTYPE;
  v_instrument_id uuid;
  v_old_pointer text;
  v_new_pointer text;
  v_old_state jsonb;
  v_new_state jsonb;
  v_readiness jsonb;
  v_projection_hash text;
  v_receipt_hash text;
  v_old_state_hash text;
  v_target_count integer;
  v_lease public.sip_fleet_provider_leases%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_artifact FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id=p_artifact_id AND artifact.artifact_kind='versioned-output-prefix-v1'
    AND artifact.content_hash=btrim(p_expected_content_hash);
  IF nullif(btrim(p_applied_by), '') IS NULL
    OR btrim(p_expected_object_identity_hash) !~ '^[0-9a-f]{64}$'
    OR btrim(p_expected_approval_receipt_hash) !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'versioned_output_prefix_application_actor_invalid'; END IF;
  v_instrument_id := (v_artifact.content->>'instrumentV2Id')::uuid;
  v_old_pointer := v_artifact.content->>'oldFilePathReference';
  v_new_pointer := v_artifact.content->>'newFilePathReference';
  -- Share the provider admission lock with submit_sip_fleet_run so the
  -- quiescence observation and cutover commit cannot race a new writer.
  PERFORM pg_advisory_xact_lock(hashtextextended(v_artifact.provider_slug,0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:' || v_instrument_id::text,0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-fleet-executor-admission',0));
  SELECT * INTO STRICT v_lease FROM public.sip_fleet_provider_leases lease
  WHERE lease.id=p_lease_id AND lease.provider_slug=v_artifact.provider_slug
    AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp() FOR UPDATE;
  IF EXISTS (
      SELECT 1 FROM public.sip_fleet_runs run
      WHERE run.provider_slug=v_artifact.provider_slug
        AND run.status IN ('queued','running')
    ) OR EXISTS (
      SELECT 1 FROM public.sip_fleet_run_items item
      JOIN public.sip_fleet_runs run ON run.id=item.run_id
      WHERE run.provider_slug=v_artifact.provider_slug
        AND item.status IN ('queued','running','waiting_for_audio_profile')
    ) OR EXISTS (
      SELECT 1 FROM public.sip_fleet_executor_leases executor
      WHERE executor.lease_expires_at>clock_timestamp()
    ) OR EXISTS (
      SELECT 1 FROM public.sip_pipeline_runs pipeline
      WHERE pipeline.contributor_slug=v_artifact.provider_slug
        AND pipeline.status IN ('queued','running')
    ) OR EXISTS (
      SELECT 1 FROM public.sip_versioned_output_prefix_staging_operations operation
      WHERE operation.provider_slug=v_artifact.provider_slug
        AND (operation.status='running' OR (operation.status='ambiguous' AND NOT EXISTS (
          SELECT 1 FROM public.sip_versioned_output_prefix_premutation_reconciliation_receipts clearance
          WHERE clearance.staging_operation_id=operation.id
        )))
    )
  THEN RAISE EXCEPTION 'versioned_output_prefix_provider_not_quiescent'; END IF;
  SELECT * INTO STRICT v_approval
  FROM public.sip_versioned_output_prefix_approval_receipts approval
  WHERE approval.id = p_expected_approval_receipt_id
    AND approval.approval_receipt_hash = btrim(p_expected_approval_receipt_hash)
    AND approval.artifact_id = v_artifact.id
    AND approval.artifact_content_hash = v_artifact.content_hash;
  IF v_approval.provider_lease_id IS DISTINCT FROM p_lease_id
    OR v_approval.provider_lease_token_hash IS DISTINCT FROM encode(digest(
      convert_to(p_lease_token::text,'UTF8'),'sha256'
    ),'hex')
  THEN RAISE EXCEPTION 'versioned_output_prefix_provider_lease_drift'; END IF;
  SELECT * INTO STRICT v_rehearsal
  FROM public.sip_versioned_output_prefix_rehearsal_receipts rehearsal
  WHERE rehearsal.id = v_approval.rehearsal_receipt_id
    AND rehearsal.artifact_id = v_artifact.id
    AND rehearsal.old_state_hash = v_approval.old_state_hash
    AND rehearsal.staging_projection_hash = v_approval.staging_projection_hash;
  IF v_rehearsal.provider_lease_id IS DISTINCT FROM p_lease_id
    OR v_rehearsal.provider_lease_token_hash IS DISTINCT FROM encode(digest(
      convert_to(p_lease_token::text,'UTF8'),'sha256'
    ),'hex')
  THEN RAISE EXCEPTION 'versioned_output_prefix_provider_lease_drift'; END IF;
  IF btrim(p_expected_object_identity_hash)
      IS DISTINCT FROM v_rehearsal.object_identity_hash
    OR btrim(p_expected_object_identity_hash)
      IS DISTINCT FROM v_approval.object_identity_hash
  THEN RAISE EXCEPTION 'versioned_output_prefix_object_identity_drift'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_artifact.content->'targets') target
    WHERE NOT EXISTS (
      SELECT 1 FROM public.samples_original_paths source
      WHERE source.id=(target->>'originalSampleId')::uuid
        AND source.s3_path=target->>'sourceS3Key'
        AND target->'sourceTerminalEvidence'=jsonb_build_object(
          'status',CASE WHEN source.completed_at IS NULL THEN 'legacy_quiescent' ELSE 'completed' END,
          'completedAt',CASE WHEN source.completed_at IS NULL THEN NULL ELSE to_char(
            source.completed_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
          'updatedAt',to_char(source.updated_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
          'claimedBy',source.claimed_by,
          'claimedAt',source.claimed_at,
          'errorMessage',source.error_message,
          'licensingSecured',source.licensing_secured
        )
        AND source.claimed_by IS NULL AND source.claimed_at IS NULL
        AND source.error_message IS NULL AND source.licensing_secured
    )
  ) THEN RAISE EXCEPTION 'versioned_output_prefix_source_terminal_drift'; END IF;
  SELECT * INTO v_existing
  FROM public.sip_versioned_output_prefix_application_receipts receipt
  WHERE receipt.artifact_id = v_artifact.id;
  IF v_existing.id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.sip_versioned_output_prefix_rollback_receipts rollback
      WHERE rollback.application_receipt_id = v_existing.id
    ) THEN RAISE EXCEPTION 'versioned_output_prefix_already_rolled_back'; END IF;
    IF v_existing.artifact_content_hash IS DISTINCT FROM v_artifact.content_hash
      OR v_existing.provider_slug IS DISTINCT FROM v_artifact.provider_slug
      OR v_existing.provider_lease_id IS DISTINCT FROM p_lease_id
      OR v_existing.provider_lease_token_hash IS DISTINCT FROM encode(digest(
        convert_to(p_lease_token::text,'UTF8'),'sha256'
      ),'hex')
      OR v_existing.instrument_v2_id IS DISTINCT FROM v_instrument_id
      OR v_existing.old_file_path_reference IS DISTINCT FROM v_old_pointer
      OR v_existing.new_file_path_reference IS DISTINCT FROM v_new_pointer
      OR v_existing.applied_by IS DISTINCT FROM btrim(p_applied_by)
      OR public.sip_versioned_output_prefix_state_v1(v_instrument_id)
        IS DISTINCT FROM v_existing.new_state
    THEN RAISE EXCEPTION 'versioned_output_prefix_application_replay_drift'; END IF;
    RETURN to_jsonb(v_existing) || jsonb_build_object('idempotent',true);
  END IF;
  SELECT count(*)::integer INTO v_target_count
  FROM public.sip_versioned_output_prefix_staging_receipts receipt
  WHERE receipt.artifact_id = v_artifact.id
    AND receipt.artifact_content_hash = v_artifact.content_hash
    AND receipt.provider_slug = v_artifact.provider_slug
    AND receipt.instrument_v2_id = v_instrument_id
    AND receipt.provider_lease_id = p_lease_id
    AND receipt.provider_lease_token_hash = encode(digest(
      convert_to(p_lease_token::text,'UTF8'),'sha256'
    ),'hex');
  IF v_target_count IS DISTINCT FROM v_rehearsal.staged_target_count
  THEN RAISE EXCEPTION 'versioned_output_prefix_staging_scope_drift'; END IF;
  IF (v_artifact.content->>'stagingProjectionCanonicalJson')::jsonb
      IS DISTINCT FROM public.sip_versioned_output_prefix_staging_projection_v1(
        v_artifact.id
      )
  THEN RAISE EXCEPTION 'versioned_output_prefix_staging_projection_drift'; END IF;
  SELECT encode(digest(convert_to(
    v_artifact.content->>'stagingProjectionCanonicalJson', 'UTF8'
  ),'sha256'),'hex') INTO v_projection_hash;
  IF v_projection_hash IS DISTINCT FROM v_artifact.content->>'stagingProjectionHash'
    OR v_projection_hash IS DISTINCT FROM v_rehearsal.staging_projection_hash
    OR v_projection_hash IS DISTINCT FROM v_approval.staging_projection_hash
  THEN RAISE EXCEPTION 'versioned_output_prefix_staging_projection_drift'; END IF;
  SELECT public.sip_versioned_output_prefix_state_v1(instrument.id)
  INTO STRICT v_old_state FROM public.instruments_v2 instrument
  WHERE instrument.id=v_instrument_id AND instrument.file_path_reference=v_old_pointer
  FOR UPDATE;
  v_old_state_hash := encode(digest(convert_to(v_old_state::text,'UTF8'),'sha256'),'hex');
  IF v_old_state_hash IS DISTINCT FROM v_rehearsal.old_state_hash
    OR v_old_state_hash IS DISTINCT FROM v_approval.old_state_hash
  THEN RAISE EXCEPTION 'versioned_output_prefix_application_state_drift'; END IF;
  DELETE FROM public.instrument_v2_publish_output_manifest WHERE instrument_v2_id=v_instrument_id;
  PERFORM set_config('app.sip_publish_coordinator_authorized','on',true);
  UPDATE public.instruments_v2 SET file_path_reference=v_new_pointer WHERE id=v_instrument_id;
  INSERT INTO public.instrument_v2_publish_output_manifest(
    instrument_v2_id,sample_path_construct_id,original_sample_id,destination_s3_key,
    format,quality,processing_fingerprint_sha256,fingerprint_schema,
    processing_input,status,run_id,processed_at,output_object_identity
  ) SELECT instrument_v2_id,sample_path_construct_id,original_sample_id,
    destination_s3_key,format,quality,processing_fingerprint_sha256,
    'sip-v2-output-v2',processing_input,'completed',staging_run_id,verified_at,
    output_object_identity || jsonb_build_object(
      'receiptOrigin','versioned_prefix_cutover',
      'outputContentSha256',output_content_sha256
    )
  FROM public.sip_versioned_output_prefix_staging_receipts
  WHERE artifact_id=v_artifact.id ORDER BY destination_s3_key;
  v_readiness := public.refresh_instrument_v2_runtime_readiness_v1(v_instrument_id,false);
  IF v_readiness->>'fallbackState' IS DISTINCT FROM 'runtime_manifest'
    OR (v_readiness->>'addressReady')::boolean IS NOT TRUE
    OR (v_readiness->>'behaviorReady')::boolean IS NOT TRUE
  THEN RAISE EXCEPTION 'versioned_output_prefix_readiness_drift'; END IF;
  -- Force the false->true deterministic publication transition inside this
  -- transaction so a grandfathered published row also receives a current
  -- admission bound to the newly materialized manifest.
  PERFORM public.set_instrument_v2_published_manifest_aware_v1(v_instrument_id,false);
  PERFORM public.set_instrument_v2_published_manifest_aware_v1(v_instrument_id,true);
  SELECT public.sip_versioned_output_prefix_state_v1(v_instrument_id)
  INTO STRICT v_new_state;
  v_receipt_hash := encode(digest(convert_to(jsonb_build_object(
    'artifactId',v_artifact.id,'contentHash',v_artifact.content_hash,
    'providerLeaseId',p_lease_id,
    'providerLeaseTokenHash',encode(digest(
      convert_to(p_lease_token::text,'UTF8'),'sha256'
    ),'hex'),
    'objectIdentityHash',btrim(p_expected_object_identity_hash),
    'approvalReceiptId',v_approval.id,
    'approvalReceiptHash',v_approval.approval_receipt_hash,
    'oldState',v_old_state,'newState',v_new_state,'stagingProjectionHash',v_projection_hash
  )::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.sip_versioned_output_prefix_application_receipts(
    artifact_id,rehearsal_receipt_id,approval_receipt_id,
    artifact_content_hash,provider_slug,provider_lease_id,
    provider_lease_token_hash,
    instrument_v2_id,old_file_path_reference,new_file_path_reference,
    approval_receipt_hash,object_identity_hash,old_state,new_state,
    staging_projection_hash,application_receipt_hash,
    authorizing_xid,applied_by
  ) VALUES (v_artifact.id,v_rehearsal.id,v_approval.id,
    v_artifact.content_hash,v_artifact.provider_slug,p_lease_id,
    encode(digest(convert_to(p_lease_token::text,'UTF8'),'sha256'),'hex'),
    v_instrument_id,v_old_pointer,v_new_pointer,v_approval.approval_receipt_hash,
    btrim(p_expected_object_identity_hash),
    v_old_state,v_new_state,
    v_projection_hash,v_receipt_hash,txid_current(),btrim(p_applied_by))
  RETURNING * INTO v_existing;
  RETURN to_jsonb(v_existing) || jsonb_build_object('idempotent',false);
END $_$;


ALTER FUNCTION "public"."sip_publish_apply_versioned_output_prefix_v1"("p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_expected_object_identity_hash" "text", "p_expected_approval_receipt_id" "uuid", "p_expected_approval_receipt_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_approve_public_output_recovery_retry_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_prior_run_id" "uuid", "p_fresh_rehearsal_id" "uuid", "p_expected_content_hash" "text", "p_approved_by" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_provider_slug text := btrim(p_contributor_slug);
  v_git_sha text := btrim(p_git_sha);
  v_processor_config_id text := btrim(p_processor_config_id);
  v_content_hash text := btrim(p_expected_content_hash);
  v_approved_by text := btrim(p_approved_by);
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_prior_run public.sip_fleet_runs%ROWTYPE;
  v_rehearsal public.sip_public_output_recovery_rehearsals%ROWTYPE;
  v_approval public.sip_public_output_recovery_retry_approvals%ROWTYPE;
  v_payload jsonb;
  v_hash text;
  v_instrument_count integer;
  v_target_count integer;
BEGIN
  IF nullif(v_provider_slug, '') IS NULL
    OR p_artifact_id IS NULL
    OR p_prior_run_id IS NULL
    OR p_fresh_rehearsal_id IS NULL
    OR v_content_hash !~ '^[0-9a-f]{64}$'
    OR nullif(v_approved_by, '') IS NULL
    OR nullif(v_git_sha, '') IS NULL
    OR v_git_sha = 'unknown'
    OR nullif(v_processor_config_id, '') IS NULL
    OR v_processor_config_id = 'unconfigured'
  THEN
    RAISE EXCEPTION 'public_output_recovery_retry_approval_identity_required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_provider_slug, 0));

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = v_provider_slug
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;

  SELECT * INTO v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = p_artifact_id
    AND artifact.provider_slug = v_provider_slug
    AND artifact.artifact_kind = 'public-output-recovery-v1'
    AND artifact.content_hash = v_content_hash;
  IF NOT FOUND
    OR v_artifact.content->>'recoveryKind'
      IS DISTINCT FROM 'public-output-recovery-v1'
    OR v_artifact.content->>'contributor' IS DISTINCT FROM v_provider_slug
    OR v_artifact.content->>'gitSha' IS DISTINCT FROM v_git_sha
    OR v_artifact.content->>'processorConfigId'
      IS DISTINCT FROM v_processor_config_id
  THEN
    RAISE EXCEPTION 'public_output_recovery_retry_approval_artifact_invalid';
  END IF;

  v_instrument_count := jsonb_array_length(v_artifact.content->'instruments');
  SELECT count(*)::integer INTO v_target_count
  FROM jsonb_array_elements(v_artifact.content->'instruments') instrument(value)
  CROSS JOIN LATERAL jsonb_array_elements(instrument.value->'targets') target(value);
  IF v_instrument_count <= 0 OR v_target_count <= 0 THEN
    RAISE EXCEPTION 'public_output_recovery_retry_approval_scope_invalid';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_plan_artifact_approvals approval
    WHERE approval.artifact_id = v_artifact.id
      AND approval.content_hash = v_artifact.content_hash
      AND approval.approved_by = v_approved_by
  ) THEN
    RAISE EXCEPTION 'approved_public_output_recovery_artifact_required';
  END IF;

  SELECT * INTO v_prior_run
  FROM public.sip_fleet_runs run
  WHERE run.id = p_prior_run_id
    AND run.provider_slug = v_provider_slug
  FOR SHARE;
  IF NOT FOUND
    OR v_prior_run.status NOT IN ('failed', 'canceled')
    OR v_prior_run.finished_at IS NULL
    OR v_prior_run.idempotency_key
      IS DISTINCT FROM 'public-output-recovery:' || v_artifact.content_hash
  THEN
    RAISE EXCEPTION 'original_terminal_public_output_recovery_run_required';
  END IF;

  SELECT * INTO v_rehearsal
  FROM public.sip_public_output_recovery_rehearsals rehearsal
  WHERE rehearsal.id = p_fresh_rehearsal_id
    AND rehearsal.artifact_id = v_artifact.id
    AND rehearsal.content_hash = v_artifact.content_hash
    AND rehearsal.provider_slug = v_provider_slug
    AND rehearsal.provider_lease_id = p_lease_id
    AND rehearsal.git_sha = v_git_sha
    AND rehearsal.processor_config_id = v_processor_config_id
    AND rehearsal.status = 'passed'
    AND rehearsal.completed_at IS NOT NULL
    AND rehearsal.created_at > v_prior_run.finished_at
    AND rehearsal.completed_at >= clock_timestamp() - interval '15 minutes';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'fresh_passed_public_output_recovery_rehearsal_required';
  END IF;
  IF v_rehearsal.result_payload->>'instrumentCount'
      IS DISTINCT FROM v_instrument_count::text
    OR v_rehearsal.result_payload->>'targetCount'
      IS DISTINCT FROM v_target_count::text
  THEN
    RAISE EXCEPTION 'fresh_public_output_recovery_rehearsal_count_mismatch';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = v_provider_slug
      AND run.status IN ('queued', 'running')
  ) OR EXISTS (
    SELECT 1
    FROM public.sip_fleet_runs run
    JOIN public.sip_fleet_run_items item ON item.run_id = run.id
    WHERE run.provider_slug = v_provider_slug
      AND item.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'provider_publish_run_active';
  END IF;

  v_payload := jsonb_build_object(
    'schemaVersion', 'sip-public-output-recovery-retry-approval-v1',
    'artifactId', v_artifact.id,
    'contentHash', v_artifact.content_hash,
    'providerSlug', v_provider_slug,
    'providerLeaseId', p_lease_id,
    'priorRunId', v_prior_run.id,
    'freshRehearsalId', v_rehearsal.id,
    'freshRehearsalResultHash', encode(digest(
      convert_to(v_rehearsal.result_payload::text, 'UTF8'), 'sha256'
    ), 'hex'),
    'gitSha', v_git_sha,
    'processorConfigId', v_processor_config_id,
    'approvedBy', v_approved_by
  );
  v_hash := encode(digest(convert_to(v_payload::text, 'UTF8'), 'sha256'), 'hex');

  INSERT INTO public.sip_public_output_recovery_retry_approvals (
    id, artifact_id, content_hash, provider_slug, provider_lease_id,
    prior_run_id, fresh_rehearsal_id, git_sha, processor_config_id,
    approved_by, approval_payload, approval_hash
  ) VALUES (
    gen_random_uuid(), v_artifact.id, v_artifact.content_hash,
    v_provider_slug, p_lease_id, v_prior_run.id, v_rehearsal.id,
    v_git_sha, v_processor_config_id, v_approved_by, v_payload, v_hash
  )
  ON CONFLICT (prior_run_id) DO NOTHING
  RETURNING * INTO v_approval;

  IF v_approval.id IS NULL THEN
    SELECT * INTO STRICT v_approval
    FROM public.sip_public_output_recovery_retry_approvals approval
    WHERE approval.prior_run_id = v_prior_run.id;
    IF v_approval.artifact_id <> v_artifact.id
      OR v_approval.content_hash <> v_artifact.content_hash
      OR v_approval.provider_lease_id <> p_lease_id
      OR v_approval.fresh_rehearsal_id <> v_rehearsal.id
      OR v_approval.approved_by <> v_approved_by
      OR v_approval.approval_hash <> v_hash
    THEN
      RAISE EXCEPTION 'public_output_recovery_retry_approval_mismatch';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'retryApprovalId', v_approval.id,
    'retryApprovalHash', v_approval.approval_hash,
    'priorRunId', v_approval.prior_run_id,
    'freshRehearsalRunId', v_approval.fresh_rehearsal_id
  );
END;
$_$;


ALTER FUNCTION "public"."sip_publish_approve_public_output_recovery_retry_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_prior_run_id" "uuid", "p_fresh_rehearsal_id" "uuid", "p_expected_content_hash" "text", "p_approved_by" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_approve_versioned_output_prefix_v1"("p_artifact_id" "uuid", "p_rehearsal_receipt_id" "uuid", "p_expected_content_hash" "text", "p_expected_old_state_hash" "text", "p_expected_staging_projection_hash" "text", "p_approved_by" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_rehearsal public.sip_versioned_output_prefix_rehearsal_receipts%ROWTYPE;
  v_existing public.sip_versioned_output_prefix_approval_receipts%ROWTYPE;
  v_approval_hash text;
BEGIN
  SELECT * INTO STRICT v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = p_artifact_id
    AND artifact.artifact_kind = 'versioned-output-prefix-v1'
    AND artifact.content_hash = btrim(p_expected_content_hash);
  IF NOT public.validate_sip_publish_operator_lease_v1(
    v_artifact.provider_slug, p_lease_id, p_lease_token
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  SELECT * INTO STRICT v_rehearsal
  FROM public.sip_versioned_output_prefix_rehearsal_receipts receipt
  WHERE receipt.id = p_rehearsal_receipt_id
    AND receipt.artifact_id = v_artifact.id
    AND receipt.artifact_content_hash = v_artifact.content_hash
    AND receipt.old_state_hash = btrim(p_expected_old_state_hash)
    AND receipt.staging_projection_hash = btrim(p_expected_staging_projection_hash)
    AND receipt.provider_lease_id = p_lease_id
    AND receipt.provider_lease_token_hash = encode(digest(
      convert_to(p_lease_token::text,'UTF8'),'sha256'
    ),'hex')
    AND receipt.result->>'passed' = 'true';
  IF nullif(btrim(p_approved_by), '') IS NULL
  THEN RAISE EXCEPTION 'versioned_output_prefix_approval_actor_invalid'; END IF;
  v_approval_hash := encode(digest(convert_to(jsonb_build_object(
    'artifactId', v_artifact.id,
    'contentHash', v_artifact.content_hash,
    'rehearsalReceiptId', v_rehearsal.id,
    'providerLeaseId', p_lease_id,
    'providerLeaseTokenHash', encode(digest(
      convert_to(p_lease_token::text,'UTF8'),'sha256'
    ),'hex'),
    'oldStateHash', v_rehearsal.old_state_hash,
    'stagingProjectionHash', v_rehearsal.staging_projection_hash,
    'objectIdentityHash', v_rehearsal.object_identity_hash,
    'approvedBy', btrim(p_approved_by)
  )::text, 'UTF8'), 'sha256'), 'hex');
  INSERT INTO public.sip_versioned_output_prefix_approval_receipts(
    artifact_id, rehearsal_receipt_id, provider_lease_id,
    provider_lease_token_hash,
    artifact_content_hash, old_state_hash,
    staging_projection_hash, object_identity_hash,
    approval_receipt_hash, approved_by
  ) VALUES (
    v_artifact.id, v_rehearsal.id, p_lease_id,
    encode(digest(convert_to(p_lease_token::text,'UTF8'),'sha256'),'hex'),
    v_artifact.content_hash,
    v_rehearsal.old_state_hash, v_rehearsal.staging_projection_hash,
    v_rehearsal.object_identity_hash, v_approval_hash, btrim(p_approved_by)
  ) ON CONFLICT (artifact_id) DO NOTHING
  RETURNING * INTO v_existing;
  IF v_existing.id IS NULL THEN
    SELECT * INTO STRICT v_existing
    FROM public.sip_versioned_output_prefix_approval_receipts receipt
    WHERE receipt.artifact_id = v_artifact.id;
    IF v_existing.rehearsal_receipt_id IS DISTINCT FROM v_rehearsal.id
      OR v_existing.provider_lease_id IS DISTINCT FROM p_lease_id
      OR v_existing.provider_lease_token_hash IS DISTINCT FROM encode(digest(
        convert_to(p_lease_token::text,'UTF8'),'sha256'
      ),'hex')
      OR v_existing.artifact_content_hash IS DISTINCT FROM v_artifact.content_hash
      OR v_existing.old_state_hash IS DISTINCT FROM v_rehearsal.old_state_hash
      OR v_existing.staging_projection_hash IS DISTINCT FROM v_rehearsal.staging_projection_hash
      OR v_existing.object_identity_hash IS DISTINCT FROM v_rehearsal.object_identity_hash
      OR v_existing.approval_receipt_hash IS DISTINCT FROM v_approval_hash
      OR v_existing.approved_by IS DISTINCT FROM btrim(p_approved_by)
    THEN RAISE EXCEPTION 'versioned_output_prefix_approval_replay_drift'; END IF;
  END IF;
  RETURN to_jsonb(v_existing);
END $$;


ALTER FUNCTION "public"."sip_publish_approve_versioned_output_prefix_v1"("p_artifact_id" "uuid", "p_rehearsal_receipt_id" "uuid", "p_expected_content_hash" "text", "p_expected_old_state_hash" "text", "p_expected_staging_projection_hash" "text", "p_approved_by" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_begin_versioned_output_prefix_staging_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_request_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_lease public.sip_fleet_provider_leases%ROWTYPE;
  v_existing public.sip_versioned_output_prefix_staging_operations%ROWTYPE;
BEGIN
  IF btrim(p_request_hash) !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'versioned_output_prefix_staging_request_invalid'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug),0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:' || p_instrument_v2_id::text,0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-fleet-executor-admission',0));
  SELECT * INTO STRICT v_lease
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id=p_lease_id
    AND lease.provider_slug=btrim(p_contributor_slug)
    AND lease.lease_token=p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at>clock_timestamp()
  FOR UPDATE;
  SELECT * INTO v_existing
  FROM public.sip_versioned_output_prefix_staging_operations operation
  WHERE operation.provider_slug=btrim(p_contributor_slug)
    AND operation.request_hash=btrim(p_request_hash);
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.instrument_v2_id IS DISTINCT FROM p_instrument_v2_id
      OR v_existing.provider_lease_id IS DISTINCT FROM p_lease_id
      OR v_existing.provider_lease_token_hash IS DISTINCT FROM encode(digest(
        convert_to(p_lease_token::text,'UTF8'),'sha256'
      ),'hex')
    THEN RAISE EXCEPTION 'versioned_output_prefix_staging_operation_drift'; END IF;
    IF v_existing.status='completed' THEN
      RETURN to_jsonb(v_existing) || jsonb_build_object('idempotent',true);
    ELSIF v_existing.status='running' THEN
      RETURN to_jsonb(v_existing) || jsonb_build_object(
        'idempotent',true,'requiresReconciliation',true
      );
    END IF;
    RAISE EXCEPTION 'versioned_output_prefix_staging_operation_unresolved';
  END IF;
  IF EXISTS (
      SELECT 1 FROM public.sip_fleet_runs run
      WHERE run.provider_slug=btrim(p_contributor_slug)
        AND run.status IN ('queued','running')
    ) OR EXISTS (
      SELECT 1 FROM public.sip_fleet_run_items item
      JOIN public.sip_fleet_runs run ON run.id=item.run_id
      WHERE run.provider_slug=btrim(p_contributor_slug)
        AND item.status IN ('queued','running','waiting_for_audio_profile')
    ) OR EXISTS (
      SELECT 1 FROM public.sip_fleet_executor_leases executor
      WHERE executor.lease_expires_at>clock_timestamp()
    ) OR EXISTS (
      SELECT 1 FROM public.sip_pipeline_runs pipeline
      WHERE pipeline.contributor_slug=btrim(p_contributor_slug)
        AND pipeline.status IN ('queued','running')
    ) OR EXISTS (
      SELECT 1 FROM public.sip_versioned_output_prefix_staging_operations operation
      WHERE operation.provider_slug=btrim(p_contributor_slug)
        AND operation.status IN ('running','ambiguous')
    )
  THEN RAISE EXCEPTION 'versioned_output_prefix_provider_not_quiescent'; END IF;
  INSERT INTO public.sip_versioned_output_prefix_staging_operations(
    provider_slug,instrument_v2_id,provider_lease_id,provider_lease_token_hash,
    request_hash,status
  ) VALUES (
    btrim(p_contributor_slug),p_instrument_v2_id,p_lease_id,
    encode(digest(convert_to(p_lease_token::text,'UTF8'),'sha256'),'hex'),
    btrim(p_request_hash),'running'
  ) RETURNING * INTO v_existing;
  RETURN to_jsonb(v_existing) || jsonb_build_object('idempotent',false);
END $_$;


ALTER FUNCTION "public"."sip_publish_begin_versioned_output_prefix_staging_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_request_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_begin_versioned_output_prefix_staging_v2"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_request_hash" "text", "p_preflight_receipt_id" "uuid", "p_expected_preflight_receipt_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_lease public.sip_fleet_provider_leases%ROWTYPE;
  v_preflight public.sip_versioned_output_prefix_preflight_receipts%ROWTYPE;
  v_existing public.sip_versioned_output_prefix_staging_operations%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug),0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:' || p_instrument_v2_id::text,0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-fleet-executor-admission',0));
  SELECT * INTO STRICT v_lease FROM public.sip_fleet_provider_leases lease
  WHERE lease.id=p_lease_id AND lease.provider_slug=btrim(p_contributor_slug)
    AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
    AND lease.lease_expires_at>clock_timestamp() FOR UPDATE;
  SELECT * INTO STRICT v_preflight
  FROM public.sip_versioned_output_prefix_preflight_receipts receipt
  WHERE receipt.id=p_preflight_receipt_id
    AND receipt.preflight_receipt_hash=btrim(p_expected_preflight_receipt_hash)
    AND receipt.provider_slug=btrim(p_contributor_slug)
    AND receipt.instrument_v2_id=p_instrument_v2_id
    AND receipt.provider_lease_id=p_lease_id
    AND receipt.provider_lease_token_hash=encode(digest(
      convert_to(p_lease_token::text,'UTF8'),'sha256'
    ),'hex');
  IF public.sip_versioned_output_prefix_source_terminal_snapshot_v1(
      p_instrument_v2_id
    ) IS DISTINCT FROM v_preflight.source_terminal_snapshot
  THEN RAISE EXCEPTION 'versioned_output_prefix_source_terminal_drift'; END IF;
  IF btrim(p_request_hash) IS DISTINCT FROM v_preflight.admission_request_hash
  THEN RAISE EXCEPTION 'versioned_output_prefix_staging_request_invalid'; END IF;
  IF EXISTS (SELECT 1 FROM public.sip_fleet_runs run
      WHERE run.provider_slug=v_preflight.provider_slug AND run.status IN ('queued','running'))
    OR EXISTS (SELECT 1 FROM public.sip_fleet_run_items item
      JOIN public.sip_fleet_runs run ON run.id=item.run_id
      WHERE run.provider_slug=v_preflight.provider_slug
        AND item.status IN ('queued','running','waiting_for_audio_profile'))
    OR EXISTS (SELECT 1 FROM public.sip_fleet_executor_leases executor
      WHERE executor.lease_expires_at>clock_timestamp())
    OR EXISTS (SELECT 1 FROM public.sip_pipeline_runs pipeline
      WHERE pipeline.contributor_slug=v_preflight.provider_slug
        AND pipeline.status IN ('queued','running'))
    OR EXISTS (SELECT 1 FROM public.sip_versioned_output_prefix_staging_operations operation
      WHERE operation.provider_slug=v_preflight.provider_slug
        AND (operation.status='running' OR (operation.status='ambiguous' AND NOT EXISTS (
          SELECT 1 FROM public.sip_versioned_output_prefix_premutation_reconciliation_receipts clearance
          WHERE clearance.staging_operation_id=operation.id
        ))))
  THEN RAISE EXCEPTION 'versioned_output_prefix_provider_not_quiescent'; END IF;
  INSERT INTO public.sip_versioned_output_prefix_staging_operations(
    provider_slug,instrument_v2_id,provider_lease_id,provider_lease_token_hash,
    request_hash,status,preflight_receipt_id
  ) VALUES (v_preflight.provider_slug,p_instrument_v2_id,p_lease_id,
    v_preflight.provider_lease_token_hash,btrim(p_request_hash),'running',v_preflight.id)
  ON CONFLICT (provider_slug,request_hash) DO NOTHING RETURNING * INTO v_existing;
  IF v_existing.id IS NULL THEN
    SELECT * INTO STRICT v_existing FROM public.sip_versioned_output_prefix_staging_operations
    WHERE provider_slug=v_preflight.provider_slug AND request_hash=btrim(p_request_hash);
    IF v_existing.preflight_receipt_id IS DISTINCT FROM v_preflight.id
    THEN RAISE EXCEPTION 'versioned_output_prefix_staging_operation_drift'; END IF;
    RETURN to_jsonb(v_existing)||jsonb_build_object(
      'idempotent',true,'requiresReconciliation',v_existing.status='running'
    );
  END IF;
  RETURN to_jsonb(v_existing)||jsonb_build_object('idempotent',false);
END $$;


ALTER FUNCTION "public"."sip_publish_begin_versioned_output_prefix_staging_v2"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_request_hash" "text", "p_preflight_receipt_id" "uuid", "p_expected_preflight_receipt_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_apply_semantic_regroup_plain_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_expected_snapshot" "jsonb", "p_expected_parent_source_snapshot" "jsonb", "p_expected_target_snapshot" "jsonb", "p_expected_target_metadata_snapshot" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_parent_staging public.sip_review_instrument%ROWTYPE;
  v_parent public.instruments_v2%ROWTYPE;
  v_child_staging public.sip_review_instrument%ROWTYPE;
  v_child jsonb;
  v_expected_target_metadata jsonb;
  v_source jsonb;
  v_child_staging_id uuid;
  v_child_v2_id uuid;
  v_target_mode text;
  v_parent_staging_already_retired boolean;
  v_expected_constructs uuid[];
  v_assigned_constructs uuid[];
  v_snapshot_constructs uuid[];
  v_expected_target_constructs uuid[];
  v_live_target_constructs uuid[];
  v_manifest_child_ids uuid[];
  v_manifest_child_staging_ids uuid[];
  v_child_ids uuid[] := ARRAY[]::uuid[];
  v_created integer := 0;
  v_existing integer := 0;
  v_moved integer := 0;
  v_inactive integer := 0;
  v_restored integer := 0;
  v_result jsonb;
  v_receipt public.sip_semantic_regroup_receipts%ROWTYPE;
  v_locked_lease_id uuid;
BEGIN
  IF NULLIF(btrim(p_contributor_slug), '') IS NULL THEN
    RAISE EXCEPTION 'invalid semantic regroup contributor identity'
      USING ERRCODE = '22023';
  END IF;
  -- Serialize with provider-fleet admission before making any lease, receipt,
  -- or active-run decision. The same provider can never enter two mutation
  -- commit points concurrently.
  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug), 0));
  SELECT lease.id INTO v_locked_lease_id
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
    AND lease.provider_slug = btrim(p_contributor_slug)
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF v_locked_lease_id IS NULL THEN
    RAISE EXCEPTION 'semantic regroup requires an active provider lease'
      USING ERRCODE = '42501';
  END IF;
  IF p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR NULLIF(btrim(p_applied_by), '') IS NULL
     OR p_manifest->>'providerSlug' IS DISTINCT FROM p_contributor_slug
     OR NOT (CASE
       WHEN jsonb_typeof(p_manifest->'schemaVersion') = 'number'
       THEN (p_manifest->>'schemaVersion')::numeric = 1
         AND mod((p_manifest->>'schemaVersion')::numeric, 1) = 0
       ELSE false
     END) THEN
    RAISE EXCEPTION 'invalid semantic regroup manifest identity'
      USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_manifest->'children') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest->'children') < 1
     OR jsonb_array_length(p_manifest->'children') > 250
     OR jsonb_typeof(p_manifest->'inactiveSources') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'semantic regroup scope is outside bounded limits'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_receipt
  FROM public.sip_semantic_regroup_receipts
  WHERE provider_slug = p_contributor_slug AND manifest_hash = p_manifest_hash
  FOR SHARE;
  IF v_receipt.id IS NOT NULL THEN
    IF v_receipt.manifest IS DISTINCT FROM p_manifest
       OR v_receipt.execution_context IS DISTINCT FROM jsonb_build_object(
         'expectedParentSourceSnapshot',p_expected_parent_source_snapshot,
         'expectedRecoverySnapshot',p_expected_snapshot,
         'expectedTargetSnapshot',p_expected_target_snapshot,
         'expectedTargetMetadataSnapshot',p_expected_target_metadata_snapshot
       ) THEN
      RAISE EXCEPTION 'semantic regroup execution hash replay mismatch'
        USING ERRCODE = '22023';
    END IF;
    RETURN v_receipt.result || jsonb_build_object('idempotent', true);
  END IF;
  IF jsonb_typeof(p_expected_snapshot) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_expected_snapshot) < 1
     OR jsonb_array_length(p_expected_snapshot) > 2000 THEN
    RAISE EXCEPTION 'semantic regroup expected snapshot is outside bounded limits'
      USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_expected_parent_source_snapshot) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_expected_parent_source_snapshot->'production') IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_expected_parent_source_snapshot->'staging') IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_expected_parent_source_snapshot->'playbackCues') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_expected_parent_source_snapshot->'playbackCues') > 2000 THEN
    RAISE EXCEPTION 'semantic regroup expected parent source snapshot is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_expected_target_snapshot) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_expected_target_snapshot) > 2000 THEN
    RAISE EXCEPTION 'semantic regroup expected target snapshot is outside bounded limits'
      USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_expected_target_metadata_snapshot) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_expected_target_metadata_snapshot) > 250 THEN
    RAISE EXCEPTION 'semantic regroup expected target metadata snapshot is outside bounded limits'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_expected_target_metadata_snapshot) metadata
       WHERE jsonb_typeof(metadata) IS DISTINCT FROM 'object'
          OR COALESCE(metadata->>'instrumentV2Id','') !~
             '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
          OR COALESCE(metadata->>'stagingInstrumentId','') !~
             '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     ) OR jsonb_array_length(p_expected_target_metadata_snapshot) IS DISTINCT FROM (
       SELECT count(DISTINCT metadata->>'instrumentV2Id')
       FROM jsonb_array_elements(p_expected_target_metadata_snapshot) metadata
     ) THEN
    RAISE EXCEPTION 'semantic regroup expected target metadata identity is invalid or duplicated'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs
    WHERE provider_slug = p_contributor_slug AND status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'semantic regroup blocked by active provider run'
      USING ERRCODE = '55000';
  END IF;
  IF ARRAY(
       SELECT (metadata->>'instrumentV2Id')::uuid
       FROM jsonb_array_elements(p_expected_target_metadata_snapshot) metadata
       ORDER BY metadata->>'instrumentV2Id'
     ) IS DISTINCT FROM ARRAY(
       SELECT (child->>'instrumentV2Id')::uuid
       FROM jsonb_array_elements(p_manifest->'children') child
       WHERE COALESCE(child->>'targetMode','create')='existing'
       ORDER BY child->>'instrumentV2Id'
     ) THEN
    RAISE EXCEPTION 'semantic regroup existing-target metadata partition changed'
      USING ERRCODE='55000';
  END IF;

  -- Semantic cutovers are rare and mutate a wide projection. Acquire every
  -- table-level mutation/phantom fence in one global order before any parent
  -- or child row lock. SHARE ROW EXCLUSIVE is self-exclusive yet compatible
  -- with this transaction's later INSERT/UPDATE/DELETE statements, avoiding
  -- cross-provider lock upgrades and deadlocks.
  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_promotion_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_playback_cues IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_instrument_tags IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_tag IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_upload_status IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_disposition IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_semantic_regroup_receipts IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE MODE;
  LOCK TABLE public.sip_review_legacy_map IN SHARE MODE;

  SELECT i.* INTO v_parent
  FROM public.instruments_v2 i
  JOIN public.contributors c ON c.id = i.contributor_id
  WHERE i.id = (p_manifest#>>'{parent,instrumentV2Id}')::uuid
    AND c.slug = p_contributor_slug
  FOR UPDATE OF i;
  -- A concurrent exact replay can miss the receipt before the first transaction
  -- commits, then wait here on the parent row. Re-read after the lock so it
  -- returns the durable result instead of failing on the now-retired parent.
  SELECT * INTO v_receipt
  FROM public.sip_semantic_regroup_receipts
  WHERE provider_slug = p_contributor_slug AND manifest_hash = p_manifest_hash
  FOR SHARE;
  IF v_receipt.id IS NOT NULL THEN
    IF v_receipt.manifest IS DISTINCT FROM p_manifest
       OR v_receipt.execution_context IS DISTINCT FROM jsonb_build_object(
         'expectedParentSourceSnapshot',p_expected_parent_source_snapshot,
         'expectedRecoverySnapshot',p_expected_snapshot,
         'expectedTargetSnapshot',p_expected_target_snapshot,
         'expectedTargetMetadataSnapshot',p_expected_target_metadata_snapshot
       ) THEN
      RAISE EXCEPTION 'semantic regroup execution hash replay mismatch'
        USING ERRCODE = '22023';
    END IF;
    RETURN v_receipt.result || jsonb_build_object('idempotent', true);
  END IF;
  SELECT * INTO v_parent_staging
  FROM public.sip_review_instrument
  WHERE id = (p_manifest#>>'{parent,stagingInstrumentId}')::uuid
    AND source_contributor_slug = p_contributor_slug
  FOR UPDATE;
  IF v_parent.id IS NULL OR NOT v_parent.published
     OR v_parent.name IS DISTINCT FROM p_manifest#>>'{parent,name}'
     OR v_parent_staging.id IS NULL
     OR v_parent_staging.name IS DISTINCT FROM p_manifest#>>'{parent,name}'
     OR v_parent_staging.source_sip_instrument_id IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM public.sip_review_promotion_map
       WHERE sip_review_instrument_id = v_parent_staging.id
         AND instrument_v2_id = v_parent.id
     ) THEN
    RAISE EXCEPTION 'semantic regroup parent identity changed'
      USING ERRCODE = '55000';
  END IF;
  v_parent_staging_already_retired := v_parent_staging.is_retired;

  IF p_expected_parent_source_snapshot->'production' IS DISTINCT FROM
       jsonb_build_object(
         'contributorId',v_parent.contributor_id,
         'assetRole',v_parent.asset_role,
         'pitchContents',v_parent.pitch_contents,
         'pitchContentConfig',v_parent.pitch_content_config,
         'gain',v_parent.gain,
         'sustainCropTime',v_parent.sustain_crop_time,
         'fileNameReferences',v_parent.file_name_references,
         'velocityLayers',v_parent.velocity_layers,
         'roundRobins',v_parent.round_robins,
         'micPositions',v_parent.mic_positions,
         'lookupKey',v_parent.lookup_key
       )
     OR p_expected_parent_source_snapshot->'staging' IS DISTINCT FROM
       jsonb_build_object(
         'sourceSipInstrumentId',v_parent_staging.source_sip_instrument_id,
         'sourceContributorSlug',v_parent_staging.source_contributor_slug,
         'sourceGroupKey',v_parent_staging.source_group_key,
         'contributorId',v_parent_staging.contributor_id,
         'assetRole',v_parent_staging.asset_role,
         'isRetired',v_parent_staging.is_retired,
         'pitchContents',v_parent_staging.pitch_contents,
         'pitchContentConfig',v_parent_staging.pitch_content_config,
         'gain',v_parent_staging.gain,
         'sustainCropTime',v_parent_staging.sustain_crop_time,
         'originalFileNameReferences',v_parent_staging.original_file_name_references,
         'velocityLayers',v_parent_staging.velocity_layers,
         'velocityLayerMap',v_parent_staging.velocity_layer_map,
         'roundRobins',v_parent_staging.round_robins,
         'micPositions',v_parent_staging.mic_positions
       ) THEN
    RAISE EXCEPTION 'semantic regroup inherited parent source state changed'
      USING ERRCODE = '55000';
  END IF;
  IF v_parent.asset_role::text IS DISTINCT FROM 'playable_sample'
     OR v_parent_staging.asset_role::text IS DISTINCT FROM 'playable_sample' THEN
    RAISE EXCEPTION 'semantic regroup accepts only playable sample parents'
      USING ERRCODE = '55000';
  END IF;

  SELECT array_agg((value->>'instrumentV2Id')::uuid ORDER BY value->>'instrumentV2Id'),
         array_agg((value->>'stagingInstrumentId')::uuid ORDER BY value->>'stagingInstrumentId')
  INTO v_manifest_child_ids, v_manifest_child_staging_ids
  FROM jsonb_array_elements(p_manifest->'children') value;
  IF cardinality(v_manifest_child_ids) IS DISTINCT FROM (
       SELECT count(DISTINCT value->>'instrumentV2Id') FROM jsonb_array_elements(p_manifest->'children') value
     ) OR cardinality(v_manifest_child_staging_ids) IS DISTINCT FROM (
       SELECT count(DISTINCT value->>'stagingInstrumentId') FROM jsonb_array_elements(p_manifest->'children') value
     ) OR jsonb_array_length(p_manifest->'children') IS DISTINCT FROM (
       SELECT count(DISTINCT value->>'name') FROM jsonb_array_elements(p_manifest->'children') value
     ) OR jsonb_array_length(p_manifest->'children') IS DISTINCT FROM (
       SELECT count(DISTINCT value->>'filePathReference') FROM jsonb_array_elements(p_manifest->'children') value
     ) THEN
    RAISE EXCEPTION 'semantic regroup child identities, names, and paths must be unique'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_manifest->'children') child
    WHERE NULLIF(btrim(child->>'name'), '') IS NULL
      OR NULLIF(btrim(child->>'filePathReference'), '') IS NULL
      OR child->>'addressMode' NOT IN ('pitchless','tonal')
      OR child->>'playbackType' NOT IN ('oneShot','looped','legato_transition')
      OR NOT CASE WHEN jsonb_typeof(child->'rangeLower')='number'
        THEN (child->>'rangeLower')::numeric BETWEEN 0 AND 127
          AND mod((child->>'rangeLower')::numeric,1)=0 ELSE false END
      OR NOT CASE WHEN jsonb_typeof(child->'rangeUpper')='number'
        THEN (child->>'rangeUpper')::numeric BETWEEN 0 AND 127
          AND mod((child->>'rangeUpper')::numeric,1)=0 ELSE false END
      OR CASE WHEN jsonb_typeof(child->'rangeLower')='number'
                   AND jsonb_typeof(child->'rangeUpper')='number'
        THEN (child->>'rangeLower')::numeric > (child->>'rangeUpper')::numeric
        ELSE true END
      OR CASE child->>'addressMode'
        WHEN 'pitchless' THEN (child->>'rangeLower')::numeric <> 21
          OR (child->>'rangeUpper')::numeric <> 108
          OR jsonb_typeof(child->'singlePitch') IS DISTINCT FROM 'null'
        WHEN 'tonal' THEN NOT CASE
          WHEN jsonb_typeof(child->'singlePitch')='null' THEN true
          WHEN jsonb_typeof(child->'singlePitch')='number' THEN
            mod((child->>'singlePitch')::numeric,1)=0
            AND (child->>'singlePitch')::numeric BETWEEN
                (child->>'rangeLower')::numeric AND (child->>'rangeUpper')::numeric
          ELSE false END
        ELSE true
      END
      OR CASE COALESCE(child->>'targetMode', 'create')
      WHEN 'create' THEN
        child#>>'{metadataPolicy,mode}' IS DISTINCT FROM 'exact_reviewed'
        OR child#>>'{metadataPolicy,reviewStatus}' IS DISTINCT FROM 'reviewed'
        OR NULLIF(btrim(child#>>'{metadataPolicy,evidence}'), '') IS NULL
        OR NULLIF(btrim(child#>>'{metadataPolicy,instrumentFamily}'), '') IS NULL
        OR NULLIF(btrim(child#>>'{metadataPolicy,instrumentType}'), '') IS NULL
        OR NULLIF(btrim(child#>>'{metadataPolicy,polyphonyType}'), '') IS NULL
        OR jsonb_typeof(child#>'{metadataPolicy,tagIds}') IS DISTINCT FROM 'array'
        OR child ? 'expectedTargetConstructIds'
        OR child ? 'expectedTargetSnapshotHash'
      WHEN 'existing' THEN
        child#>>'{metadataPolicy,mode}' IS DISTINCT FROM 'preserve_existing'
        OR child#>>'{metadataPolicy,reviewStatus}' IS DISTINCT FROM 'reviewed'
        OR NULLIF(btrim(child#>>'{metadataPolicy,evidence}'), '') IS NULL
        OR NULLIF(btrim(child#>>'{metadataPolicy,instrumentFamily}'), '') IS NULL
        OR NULLIF(btrim(child#>>'{metadataPolicy,instrumentType}'), '') IS NULL
        OR NULLIF(btrim(child#>>'{metadataPolicy,polyphonyType}'), '') IS NULL
        OR jsonb_typeof(child#>'{metadataPolicy,tagIds}') IS DISTINCT FROM 'array'
        OR jsonb_typeof(child->'expectedTargetConstructIds') IS DISTINCT FROM 'array'
        OR COALESCE(child->>'expectedTargetSnapshotHash', '') !~ '^[0-9a-f]{64}$'
      ELSE true
    END
  ) THEN
    RAISE EXCEPTION 'semantic regroup child metadata or target snapshot policy is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF cardinality(COALESCE(v_parent.articulations, ARRAY[]::uuid[])) > 0
     OR cardinality(COALESCE(v_parent.effects_instruments, ARRAY[]::uuid[])) > 0
     OR v_parent.legato_transition IS NOT NULL
     OR cardinality(COALESCE(v_parent_staging.articulations, ARRAY[]::uuid[])) > 0
     OR cardinality(COALESCE(v_parent_staging.effects_instruments, ARRAY[]::uuid[])) > 0
     OR v_parent_staging.legato_transition IS NOT NULL
     OR EXISTS (
       SELECT 1 FROM public.instruments_v2 i
       WHERE v_parent.id = ANY(COALESCE(i.articulations, ARRAY[]::uuid[]))
          OR v_parent.id = ANY(COALESCE(i.effects_instruments, ARRAY[]::uuid[]))
          OR i.legato_transition = v_parent.id
     )
     OR EXISTS (
       SELECT 1 FROM public.sip_review_instrument i
       WHERE v_parent_staging.source_sip_instrument_id = ANY(COALESCE(i.articulations, ARRAY[]::uuid[]))
          OR v_parent_staging.source_sip_instrument_id = ANY(COALESCE(i.effects_instruments, ARRAY[]::uuid[]))
          OR i.legato_transition = v_parent_staging.id
     )
     OR EXISTS (SELECT 1 FROM public.instrument_v2_legacy_map WHERE instrument_v2_id = v_parent.id)
     OR EXISTS (SELECT 1 FROM public.sip_review_legacy_map WHERE sip_review_instrument_id = v_parent_staging.id) THEN
    RAISE EXCEPTION 'semantic regroup parent has relationships or legacy aliases'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
       SELECT 1 FROM public.instruments_v2 i
       WHERE COALESCE(i.articulations, ARRAY[]::uuid[]) && v_manifest_child_ids
          OR COALESCE(i.effects_instruments, ARRAY[]::uuid[]) && v_manifest_child_ids
          OR i.legato_transition = ANY(v_manifest_child_ids)
     ) OR EXISTS (
       SELECT 1 FROM public.sip_review_instrument i
       WHERE COALESCE(i.articulations, ARRAY[]::uuid[]) && COALESCE(ARRAY(
               SELECT child.source_sip_instrument_id FROM public.sip_review_instrument child
               WHERE child.id = ANY(v_manifest_child_staging_ids)
                 AND child.source_sip_instrument_id IS NOT NULL
             ), ARRAY[]::uuid[])
          OR COALESCE(i.effects_instruments, ARRAY[]::uuid[]) && COALESCE(ARRAY(
               SELECT child.source_sip_instrument_id FROM public.sip_review_instrument child
               WHERE child.id = ANY(v_manifest_child_staging_ids)
                 AND child.source_sip_instrument_id IS NOT NULL
             ), ARRAY[]::uuid[])
          OR i.legato_transition = ANY(v_manifest_child_staging_ids)
     ) THEN
    RAISE EXCEPTION 'semantic regroup child target has inbound relationships'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(array_agg((value#>>'{}')::uuid ORDER BY value#>>'{}'), ARRAY[]::uuid[])
  INTO v_expected_constructs
  FROM jsonb_array_elements(p_manifest#>'{parent,expectedConstructIds}') value;
  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::uuid[])
  INTO v_assigned_constructs
  FROM (
    SELECT (s->>'constructId')::uuid id
    FROM jsonb_array_elements(p_manifest->'children') c,
         jsonb_array_elements(c->'sources') s
    UNION ALL
    SELECT (s->>'constructId')::uuid
    FROM jsonb_array_elements(p_manifest->'inactiveSources') s
  ) assigned;
  IF cardinality(v_assigned_constructs) < 1
     OR cardinality(v_assigned_constructs) > 2000
     OR cardinality(v_assigned_constructs) IS DISTINCT FROM (
       SELECT count(DISTINCT id) FROM unnest(v_assigned_constructs) id
     ) THEN
    RAISE EXCEPTION 'semantic regroup manifest construct assignment is duplicated or outside bounded limits'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg((value->>'constructId')::uuid ORDER BY value->>'constructId'), ARRAY[]::uuid[])
  INTO v_snapshot_constructs
  FROM jsonb_array_elements(p_expected_snapshot) value;
  IF cardinality(v_snapshot_constructs) IS DISTINCT FROM (
       SELECT count(DISTINCT id) FROM unnest(v_snapshot_constructs) id
     ) OR v_snapshot_constructs IS DISTINCT FROM v_assigned_constructs THEN
    RAISE EXCEPTION 'semantic regroup expected snapshot is not the exact assignment partition'
      USING ERRCODE = '22023';
  END IF;

  -- Lock every row that can influence the cutover before validating the API's
  -- hash-bound preflight snapshot. This includes exact restored rows whose
  -- ownership is NULL and all rows still attached to the parent.
  PERFORM 1 FROM public.sample_path_constructs
  WHERE instrument_v2_id = v_parent.id OR id = ANY(v_assigned_constructs)
  ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.samples_original_paths
  WHERE id IN (
    SELECT (expected->>'sampleOriginalPathId')::uuid
    FROM jsonb_array_elements(p_expected_snapshot) expected
    UNION
    SELECT (expected->>'sampleOriginalPathId')::uuid
    FROM jsonb_array_elements(p_expected_target_snapshot) expected
  )
  ORDER BY id FOR UPDATE;
  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::uuid[])
  INTO v_snapshot_constructs
  FROM public.sample_path_constructs
  WHERE instrument_v2_id = v_parent.id;
  IF v_snapshot_constructs IS DISTINCT FROM v_expected_constructs THEN
    RAISE EXCEPTION 'semantic regroup live parent construct partition changed'
      USING ERRCODE = '55000';
  END IF;
  IF NOT v_snapshot_constructs <@ v_assigned_constructs THEN
    RAISE EXCEPTION 'semantic regroup assignment omits a live parent construct'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_expected_snapshot) expected
    LEFT JOIN public.sample_path_constructs spc
      ON spc.id = (expected->>'constructId')::uuid
    LEFT JOIN public.samples_original_paths sop
      ON sop.id = spc.sample_original_path_id
    WHERE spc.id IS NULL
       OR spc.contributor_id IS DISTINCT FROM v_parent.contributor_id
       OR spc.contributor_id IS DISTINCT FROM (expected->>'contributorId')::uuid
       OR spc.sample_original_path_id IS DISTINCT FROM (expected->>'sampleOriginalPathId')::uuid
       OR spc.instrument_v2_id IS DISTINCT FROM NULLIF(expected->>'instrumentV2Id','')::uuid
       OR COALESCE(sop.s3_path,sop.file_name) IS DISTINCT FROM expected->>'sourcePath'
       OR (expected ? 'sourceS3Path' AND sop.s3_path IS DISTINCT FROM expected->>'sourceS3Path')
       OR spc.collection IS DISTINCT FROM expected->>'collection'
       OR spc.instrument_name IS DISTINCT FROM expected->>'instrumentName'
       OR spc.articulation IS DISTINCT FROM expected->>'articulation'
       OR spc.effect IS DISTINCT FROM expected->>'effect'
       OR spc.pitch_content IS DISTINCT FROM expected->>'pitchContent'
       OR spc.midi_note IS DISTINCT FROM expected->>'midiNote'
       OR spc.filename IS DISTINCT FROM expected->>'filename'
       OR spc.velocity IS DISTINCT FROM (expected->>'velocity')::integer
       OR spc.round_robin IS DISTINCT FROM (expected->>'roundRobin')::integer
       OR spc.mic_position IS DISTINCT FROM expected->>'micPosition'
       OR spc.playback_type::text IS DISTINCT FROM expected->>'playbackType'
  ) THEN
    RAISE EXCEPTION 'semantic regroup expected snapshot changed under lock'
      USING ERRCODE = '55000';
  END IF;

  -- Playback cues copied from the parent into create targets are part of the
  -- dry-run execution hash. Lock the table to exclude cue phantoms and compare
  -- both row presence and every copied value before any child is created.
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_expected_parent_source_snapshot->'playbackCues') cue
    GROUP BY cue->>'originalSampleId'
    HAVING count(*) > 1
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_expected_parent_source_snapshot->'playbackCues') cue
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_manifest->'children') child,
           jsonb_array_elements(child->'sources') source
      WHERE source->>'sampleOriginalPathId' = cue->>'originalSampleId'
    )
  ) THEN
    RAISE EXCEPTION 'semantic regroup expected parent playback cue scope is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF ARRAY(
       SELECT cue.original_sample_id
       FROM public.sip_review_sample_playback_cues cue
       WHERE cue.sip_review_instrument_id=v_parent_staging.id
         AND EXISTS (
           SELECT 1
           FROM jsonb_array_elements(p_manifest->'children') child,
                jsonb_array_elements(child->'sources') source
           WHERE (source->>'sampleOriginalPathId')::uuid=cue.original_sample_id
         )
       ORDER BY cue.original_sample_id
     ) IS DISTINCT FROM ARRAY(
       SELECT (cue->>'originalSampleId')::uuid
       FROM jsonb_array_elements(p_expected_parent_source_snapshot->'playbackCues') cue
       ORDER BY cue->>'originalSampleId'
     ) THEN
    RAISE EXCEPTION 'semantic regroup parent playback cue partition changed'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_expected_parent_source_snapshot->'playbackCues') expected
    LEFT JOIN public.sip_review_sample_playback_cues cue
      ON cue.sip_review_instrument_id=v_parent_staging.id
     AND cue.original_sample_id=(expected->>'originalSampleId')::uuid
    WHERE cue.id IS NULL
       OR cue.file_path IS DISTINCT FROM expected->>'filePath'
       OR cue.sync_point_ms IS DISTINCT FROM NULLIF(expected->>'syncPointMs','')::integer
       OR cue.loop_start_offset_ms IS DISTINCT FROM NULLIF(expected->>'loopStartOffsetMs','')::integer
       OR cue.loop_end_offset_ms IS DISTINCT FROM NULLIF(expected->>'loopEndOffsetMs','')::integer
       OR cue.sync_point_status IS DISTINCT FROM expected->>'syncPointStatus'
       OR cue.loop_start_status IS DISTINCT FROM expected->>'loopStartStatus'
       OR cue.loop_end_status IS DISTINCT FROM expected->>'loopEndStatus'
       OR cue.analysis_payload IS DISTINCT FROM expected->'analysisPayload'
       OR cue.analysis_run_id IS DISTINCT FROM NULLIF(expected->>'analysisRunId','')
       OR cue.analyzed_at IS DISTINCT FROM NULLIF(expected->>'analyzedAt','')::timestamptz
  ) THEN
    RAISE EXCEPTION 'semantic regroup parent playback cue snapshot changed'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM (
      SELECT s FROM jsonb_array_elements(p_manifest->'children') c,
                    jsonb_array_elements(c->'sources') s
      UNION ALL
      SELECT s FROM jsonb_array_elements(p_manifest->'inactiveSources') s
    ) a
    LEFT JOIN public.sample_path_constructs spc ON spc.id = (a.s->>'constructId')::uuid
    LEFT JOIN public.samples_original_paths sop ON sop.id = spc.sample_original_path_id
    WHERE spc.id IS NULL
       OR spc.contributor_id IS DISTINCT FROM v_parent.contributor_id
       OR spc.sample_original_path_id IS DISTINCT FROM (a.s->>'sampleOriginalPathId')::uuid
       OR (spc.instrument_v2_id IS DISTINCT FROM v_parent.id AND spc.instrument_v2_id IS NOT NULL)
       OR COALESCE(sop.s3_path,sop.file_name) IS DISTINCT FROM a.s->>'sourcePath'
       OR (a.s ? 'sourceS3Path' AND sop.s3_path IS DISTINCT FROM a.s->>'sourceS3Path')
  ) THEN
    RAISE EXCEPTION 'semantic regroup source identity changed'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_manifest->'inactiveSources') s
    JOIN public.sample_path_constructs spc ON spc.id=(s->>'constructId')::uuid
    WHERE spc.instrument_v2_id IS DISTINCT FROM v_parent.id
  ) THEN
    RAISE EXCEPTION 'semantic regroup cannot classify a detached restored construct as inactive'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(
    array_agg((value->>'constructId')::uuid ORDER BY value->>'constructId'),
    ARRAY[]::uuid[]
  ) INTO v_expected_target_constructs
  FROM jsonb_array_elements(p_expected_target_snapshot) value;
  IF cardinality(v_expected_target_constructs) IS DISTINCT FROM (
       SELECT count(DISTINCT id) FROM unnest(v_expected_target_constructs) id
     ) THEN
    RAISE EXCEPTION 'semantic regroup expected target snapshot contains duplicate constructs'
      USING ERRCODE = '22023';
  END IF;
  -- Lock both the caller-selected rows and every live construct currently
  -- owned by a declared child. This prevents a stale or incomplete existing
  -- target snapshot from being merged.
  PERFORM 1 FROM public.sample_path_constructs
  WHERE instrument_v2_id = ANY(v_manifest_child_ids)
     OR id = ANY(v_expected_target_constructs)
  ORDER BY id FOR UPDATE;
  SELECT COALESCE(array_agg(spc.id ORDER BY spc.id), ARRAY[]::uuid[])
  INTO v_live_target_constructs
  FROM public.sample_path_constructs spc
  WHERE spc.instrument_v2_id IN (
    SELECT (child->>'instrumentV2Id')::uuid
    FROM jsonb_array_elements(p_manifest->'children') child
    WHERE COALESCE(child->>'targetMode', 'create') = 'existing'
  );
  IF v_live_target_constructs IS DISTINCT FROM v_expected_target_constructs THEN
    RAISE EXCEPTION 'semantic regroup live existing-target construct partition changed'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_expected_target_snapshot) expected
    LEFT JOIN public.sample_path_constructs spc
      ON spc.id = (expected->>'constructId')::uuid
    LEFT JOIN public.samples_original_paths sop
      ON sop.id = spc.sample_original_path_id
    WHERE spc.id IS NULL
       OR spc.instrument_v2_id IS DISTINCT FROM (expected->>'instrumentV2Id')::uuid
       OR NOT (spc.instrument_v2_id = ANY(v_manifest_child_ids))
       OR spc.contributor_id IS DISTINCT FROM v_parent.contributor_id
       OR spc.contributor_id IS DISTINCT FROM (expected->>'contributorId')::uuid
       OR spc.sample_original_path_id IS DISTINCT FROM (expected->>'sampleOriginalPathId')::uuid
       OR COALESCE(sop.s3_path,sop.file_name) IS DISTINCT FROM expected->>'sourcePath'
       OR (expected ? 'sourceS3Path' AND sop.s3_path IS DISTINCT FROM expected->>'sourceS3Path')
       OR spc.collection IS DISTINCT FROM expected->>'collection'
       OR spc.instrument_name IS DISTINCT FROM expected->>'instrumentName'
       OR spc.articulation IS DISTINCT FROM expected->>'articulation'
       OR spc.effect IS DISTINCT FROM expected->>'effect'
       OR spc.pitch_content IS DISTINCT FROM expected->>'pitchContent'
       OR spc.midi_note IS DISTINCT FROM expected->>'midiNote'
       OR spc.filename IS DISTINCT FROM expected->>'filename'
       OR spc.velocity IS DISTINCT FROM (expected->>'velocity')::integer
       OR spc.round_robin IS DISTINCT FROM (expected->>'roundRobin')::integer
       OR spc.mic_position IS DISTINCT FROM expected->>'micPosition'
       OR spc.playback_type::text IS DISTINCT FROM expected->>'playbackType'
  ) THEN
    RAISE EXCEPTION 'semantic regroup expected target snapshot changed under lock'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_manifest->'children') child
    WHERE COALESCE(child->>'targetMode', 'create') = 'existing'
      AND ARRAY(
        SELECT (value#>>'{}')::uuid
        FROM jsonb_array_elements(child->'expectedTargetConstructIds') value
        ORDER BY value#>>'{}'
      ) IS DISTINCT FROM ARRAY(
        SELECT (expected->>'constructId')::uuid
        FROM jsonb_array_elements(p_expected_target_snapshot) expected
        WHERE expected->>'instrumentV2Id' = child->>'instrumentV2Id'
        ORDER BY expected->>'constructId'
      )
  ) THEN
    RAISE EXCEPTION 'semantic regroup manifest existing-target construct IDs changed'
      USING ERRCODE = '55000';
  END IF;

  -- Existing-target projection state is part of the exact cutover snapshot.
  -- Lock and compare review overrides and playback cues so a force-rerun cannot
  -- reapply stale reviewed state after the canonical construct merge.
  PERFORM override_row.id
  FROM public.sip_review_sample_override override_row
  WHERE EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_expected_target_snapshot) expected
    JOIN jsonb_array_elements(p_manifest->'children') child
      ON child->>'instrumentV2Id' = expected->>'instrumentV2Id'
     AND COALESCE(child->>'targetMode', 'create') = 'existing'
    WHERE override_row.sip_review_instrument_id =
          (child->>'stagingInstrumentId')::uuid
      AND override_row.original_sample_id =
          (expected->>'sampleOriginalPathId')::uuid
  )
  ORDER BY override_row.id
  FOR UPDATE;
  PERFORM cue_row.id
  FROM public.sip_review_sample_playback_cues cue_row
  WHERE EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_expected_target_snapshot) expected
    JOIN jsonb_array_elements(p_manifest->'children') child
      ON child->>'instrumentV2Id' = expected->>'instrumentV2Id'
     AND COALESCE(child->>'targetMode', 'create') = 'existing'
    WHERE cue_row.sip_review_instrument_id =
          (child->>'stagingInstrumentId')::uuid
      AND cue_row.original_sample_id =
          (expected->>'sampleOriginalPathId')::uuid
  )
  ORDER BY cue_row.id
  FOR UPDATE;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_expected_target_snapshot) expected
    JOIN jsonb_array_elements(p_manifest->'children') child
      ON child->>'instrumentV2Id' = expected->>'instrumentV2Id'
     AND COALESCE(child->>'targetMode', 'create') = 'existing'
    LEFT JOIN public.sip_review_sample_override override_row
      ON override_row.sip_review_instrument_id =
           (child->>'stagingInstrumentId')::uuid
     AND override_row.original_sample_id =
           (expected->>'sampleOriginalPathId')::uuid
    WHERE NOT (expected ? 'reviewOverride')
       OR jsonb_typeof(expected->'reviewOverride') NOT IN ('null', 'object')
       OR (jsonb_typeof(expected->'reviewOverride') = 'null'
         AND override_row.id IS NOT NULL)
       OR (jsonb_typeof(expected->'reviewOverride') = 'object' AND (
         override_row.id IS NULL
         OR override_row.contributor_slug IS DISTINCT FROM
              expected#>>'{reviewOverride,contributorSlug}'
         OR override_row.file_path IS DISTINCT FROM
              expected#>>'{reviewOverride,filePath}'
         OR override_row.collection IS DISTINCT FROM
              expected#>>'{reviewOverride,collection}'
         OR override_row.instrument_name IS DISTINCT FROM
              expected#>>'{reviewOverride,instrumentName}'
         OR override_row.articulation IS DISTINCT FROM
              expected#>>'{reviewOverride,articulation}'
         OR override_row.effect IS DISTINCT FROM
              expected#>>'{reviewOverride,effect}'
         OR override_row.mic_position IS DISTINCT FROM
              expected#>>'{reviewOverride,micPosition}'
         OR override_row.velocity IS DISTINCT FROM
              expected#>>'{reviewOverride,velocity}'
         OR override_row.round_robin IS DISTINCT FROM
              expected#>>'{reviewOverride,roundRobin}'
         OR override_row.midi_note IS DISTINCT FROM
              expected#>>'{reviewOverride,midiNote}'
         OR override_row.pitch_content IS DISTINCT FROM
              expected#>>'{reviewOverride,pitchContent}'
         OR override_row.filename IS DISTINCT FROM
              expected#>>'{reviewOverride,filename}'
         OR override_row.playback_type::text IS DISTINCT FROM
              expected#>>'{reviewOverride,playbackType}'
       ))
  ) THEN
    RAISE EXCEPTION 'semantic regroup existing-target review override snapshot changed'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_expected_target_snapshot) expected
    JOIN jsonb_array_elements(p_manifest->'children') child
      ON child->>'instrumentV2Id' = expected->>'instrumentV2Id'
     AND COALESCE(child->>'targetMode', 'create') = 'existing'
    LEFT JOIN public.sip_review_sample_playback_cues cue_row
      ON cue_row.sip_review_instrument_id =
           (child->>'stagingInstrumentId')::uuid
     AND cue_row.original_sample_id =
           (expected->>'sampleOriginalPathId')::uuid
    WHERE NOT (expected ? 'playbackCue')
       OR jsonb_typeof(expected->'playbackCue') NOT IN ('null', 'object')
       OR (jsonb_typeof(expected->'playbackCue') = 'null'
         AND cue_row.id IS NOT NULL)
       OR (jsonb_typeof(expected->'playbackCue') = 'object' AND (
         cue_row.id IS NULL
         OR cue_row.file_path IS DISTINCT FROM
              expected#>>'{playbackCue,filePath}'
         OR cue_row.sync_point_ms IS DISTINCT FROM
              NULLIF(expected#>>'{playbackCue,syncPointMs}', '')::integer
         OR cue_row.loop_start_offset_ms IS DISTINCT FROM
              NULLIF(expected#>>'{playbackCue,loopStartOffsetMs}', '')::integer
         OR cue_row.loop_end_offset_ms IS DISTINCT FROM
              NULLIF(expected#>>'{playbackCue,loopEndOffsetMs}', '')::integer
         OR cue_row.sync_point_status IS DISTINCT FROM
              expected#>>'{playbackCue,syncPointStatus}'
         OR cue_row.loop_start_status IS DISTINCT FROM
              expected#>>'{playbackCue,loopStartStatus}'
         OR cue_row.loop_end_status IS DISTINCT FROM
              expected#>>'{playbackCue,loopEndStatus}'
         OR cue_row.analysis_payload IS DISTINCT FROM
              expected#>'{playbackCue,analysisPayload}'
         OR cue_row.analysis_run_id IS DISTINCT FROM
              expected#>>'{playbackCue,analysisRunId}'
         OR cue_row.analyzed_at IS DISTINCT FROM
              NULLIF(expected#>>'{playbackCue,analyzedAt}', '')::timestamptz
       ))
  ) THEN
    RAISE EXCEPTION 'semantic regroup existing-target playback cue snapshot changed'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'children') child,
         jsonb_array_elements(child->'sources') source
    WHERE source#>>'{canonical,pitchContent}' !~ '^0(?:_[pm][1-9][0-9]*)*$'
       OR NULLIF(btrim(source#>>'{canonical,micPosition}'), '') IS NULL
       OR source#>>'{canonical,playbackType}' IS DISTINCT FROM child->>'playbackType'
       OR source#>>'{canonical,filename}' IS DISTINCT FROM source#>>'{canonical,midiNote}'
       OR NOT CASE
         WHEN jsonb_typeof(source#>'{canonical,velocity}') = 'number'
         THEN (source#>>'{canonical,velocity}')::numeric BETWEEN 0 AND 2147483647
           AND mod((source#>>'{canonical,velocity}')::numeric, 1) = 0
         ELSE false
       END
       OR NOT CASE
         WHEN jsonb_typeof(source#>'{canonical,roundRobin}') = 'number'
         THEN (source#>>'{canonical,roundRobin}')::numeric BETWEEN 0 AND 2147483647
           AND mod((source#>>'{canonical,roundRobin}')::numeric, 1) = 0
         ELSE false
       END
       OR CASE child->>'addressMode'
         WHEN 'pitchless' THEN
           source#>>'{canonical,pitchContent}' IS DISTINCT FROM '0'
           OR source#>>'{canonical,midiNote}' IS DISTINCT FROM 'pitchless'
           OR source#>>'{canonical,filename}' IS DISTINCT FROM 'pitchless'
         WHEN 'tonal' THEN NOT CASE
           WHEN source#>>'{canonical,midiNote}' ~
                '^(0|[1-9]|[1-9][0-9]|1[01][0-9]|12[0-7])$'
           THEN (source#>>'{canonical,midiNote}')::integer BETWEEN
                  (child->>'rangeLower')::integer AND (child->>'rangeUpper')::integer
             AND (jsonb_typeof(child->'singlePitch')='null'
               OR (source#>>'{canonical,midiNote}')::integer =
                  (child->>'singlePitch')::integer)
           ELSE false END
         ELSE true
       END
  ) THEN
    RAISE EXCEPTION 'semantic regroup canonical destination axes are invalid'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_expected_target_snapshot) expected
    JOIN jsonb_array_elements(p_manifest->'children') child
      ON child->>'instrumentV2Id'=expected->>'instrumentV2Id'
    WHERE expected->>'filename' IS DISTINCT FROM expected->>'midiNote'
       OR expected->>'playbackType' IS DISTINCT FROM child->>'playbackType'
       OR expected->>'instrumentName' IS DISTINCT FROM child->>'name'
       OR expected->>'collection' IS DISTINCT FROM child#>>'{metadataPolicy,collection}'
       OR expected->>'articulation' IS DISTINCT FROM child#>>'{metadataPolicy,articulation}'
       OR expected->>'effect' IS DISTINCT FROM child#>>'{metadataPolicy,effect}'
       OR CASE child->>'addressMode'
         WHEN 'pitchless' THEN expected->>'filename' IS DISTINCT FROM 'pitchless'
           OR expected->>'pitchContent' IS DISTINCT FROM '0'
         WHEN 'tonal' THEN NOT CASE
           WHEN expected->>'filename' ~ '^(0|[1-9]|[1-9][0-9]|1[01][0-9]|12[0-7])$'
           THEN (expected->>'filename')::integer BETWEEN
                  (child->>'rangeLower')::integer AND (child->>'rangeUpper')::integer
             AND (jsonb_typeof(child->'singlePitch')='null'
               OR (expected->>'filename')::integer=(child->>'singlePitch')::integer)
           ELSE false END
         ELSE true
       END
  ) THEN
    RAISE EXCEPTION 'semantic regroup existing target address is not canonical'
      USING ERRCODE='55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'children') child,
         jsonb_array_elements(child->'sources') source
    GROUP BY child->>'instrumentV2Id',
      btrim(source#>>'{canonical,pitchContent}'),
      btrim(source#>>'{canonical,filename}'),
      source#>>'{canonical,velocity}', source#>>'{canonical,roundRobin}',
      COALESCE(NULLIF(btrim(source#>>'{canonical,micPosition}'),''),'main')
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'semantic regroup duplicate canonical destination cell'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'children') child,
         jsonb_array_elements(child->'sources') source
    GROUP BY child->>'instrumentV2Id', source->>'sampleOriginalPathId'
    HAVING count(*) > 1
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'children') child,
         jsonb_array_elements(child->'sources') source
    GROUP BY child->>'instrumentV2Id', source->>'sourcePath'
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'semantic regroup duplicate child sample or source path'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'children') child
    CROSS JOIN LATERAL jsonb_array_elements(child->'sources') source
    JOIN public.sample_path_constructs target
      ON target.instrument_v2_id = (child->>'instrumentV2Id')::uuid
     AND target.sample_original_path_id = (source->>'sampleOriginalPathId')::uuid
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'children') child
    CROSS JOIN LATERAL jsonb_array_elements(child->'sources') source
    JOIN public.sample_path_constructs target
      ON target.instrument_v2_id = (child->>'instrumentV2Id')::uuid
    JOIN public.samples_original_paths target_path
      ON target_path.id=target.sample_original_path_id
     AND COALESCE(target_path.s3_path,target_path.file_name)=source->>'sourcePath'
  ) THEN
    RAISE EXCEPTION 'semantic regroup existing target sample or source path collision'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'children') child
    CROSS JOIN LATERAL jsonb_array_elements(child->'sources') source
    JOIN public.sample_path_constructs target
     ON target.instrument_v2_id = (child->>'instrumentV2Id')::uuid
     AND btrim(target.pitch_content) = btrim(source#>>'{canonical,pitchContent}')
     AND btrim(target.filename) = btrim(source#>>'{canonical,filename}')
     AND target.velocity = (source#>>'{canonical,velocity}')::integer
     AND target.round_robin = (source#>>'{canonical,roundRobin}')::integer
     AND COALESCE(NULLIF(btrim(target.mic_position),''),'main') =
         COALESCE(NULLIF(btrim(source#>>'{canonical,micPosition}'),''),'main')
  ) THEN
    RAISE EXCEPTION 'semantic regroup existing-target destination cell collision'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'children') child
    CROSS JOIN LATERAL (
      SELECT DISTINCT source#>>'{canonical,midiNote}' midi_note
      FROM jsonb_array_elements(child->'sources') source
    ) address
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(child->'sources') source
      WHERE source#>>'{canonical,midiNote}' = address.midi_note
        AND source#>>'{canonical,pitchContent}' = '0'
        AND (source#>>'{canonical,velocity}')::integer = 0
        AND (source#>>'{canonical,roundRobin}')::integer = 0
        AND source#>>'{canonical,micPosition}' = 'main'
    ) AND NOT EXISTS (
      SELECT 1
      FROM public.sample_path_constructs target
      WHERE target.instrument_v2_id = (child->>'instrumentV2Id')::uuid
        AND target.midi_note = address.midi_note
        AND target.pitch_content = '0' AND target.velocity = 0
        AND target.round_robin = 0 AND target.mic_position = 'main'
    )
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'children') child
    CROSS JOIN LATERAL (
      SELECT DISTINCT target.midi_note
      FROM public.sample_path_constructs target
      WHERE target.instrument_v2_id = (child->>'instrumentV2Id')::uuid
    ) address
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(child->'sources') source
      WHERE source#>>'{canonical,midiNote}' = address.midi_note
        AND source#>>'{canonical,pitchContent}' = '0'
        AND (source#>>'{canonical,velocity}')::integer = 0
        AND (source#>>'{canonical,roundRobin}')::integer = 0
        AND source#>>'{canonical,micPosition}' = 'main'
    ) AND NOT EXISTS (
      SELECT 1
      FROM public.sample_path_constructs target
      WHERE target.instrument_v2_id = (child->>'instrumentV2Id')::uuid
        AND target.midi_note = address.midi_note
        AND target.pitch_content = '0' AND target.velocity = 0
        AND target.round_robin = 0 AND target.mic_position = 'main'
    )
  ) THEN
    RAISE EXCEPTION 'semantic regroup child is missing a startup destination cell'
      USING ERRCODE = '22023';
  END IF;

  -- Preflight can wait on parent/target locks. Recheck real wall time while the
  -- exact lease row is still locked immediately before the first mutation.
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = v_locked_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'semantic regroup provider lease expired before cutover'
      USING ERRCODE = '42501';
  END IF;

  PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);
  FOR v_child IN SELECT value FROM jsonb_array_elements(p_manifest->'children') LOOP
    v_child_staging_id := (v_child->>'stagingInstrumentId')::uuid;
    v_child_v2_id := (v_child->>'instrumentV2Id')::uuid;
    v_target_mode := COALESCE(v_child->>'targetMode', 'create');
    v_child_ids := array_append(v_child_ids, v_child_v2_id);

    PERFORM 1 FROM public.instruments_v2
    WHERE file_path_reference = v_child->>'filePathReference'
    ORDER BY id FOR UPDATE;
    PERFORM 1 FROM public.sip_review_instrument
    WHERE original_file_path_reference = v_child->>'filePathReference'
    ORDER BY id FOR UPDATE;
    IF EXISTS (
         SELECT 1 FROM public.instruments_v2
         WHERE file_path_reference = v_child->>'filePathReference'
           AND id <> v_child_v2_id
       ) OR EXISTS (
         SELECT 1 FROM public.sip_review_instrument
         WHERE original_file_path_reference = v_child->>'filePathReference'
           AND id <> v_child_staging_id
       ) THEN
      RAISE EXCEPTION 'semantic regroup child file path is already occupied'
        USING ERRCODE = '55000';
    END IF;

    IF v_target_mode = 'existing' THEN
      SELECT metadata INTO v_expected_target_metadata
      FROM jsonb_array_elements(p_expected_target_metadata_snapshot) metadata
      WHERE metadata->>'instrumentV2Id'=v_child_v2_id::text;
      PERFORM 1 FROM public.instruments_v2
      WHERE id = v_child_v2_id AND contributor_id = v_parent.contributor_id
        AND name = v_child->>'name' AND published
        AND asset_role::text = 'playable_sample'
        AND playback_type = (v_child->>'playbackType')::public.instrument_playback_type
        AND range_lower = (v_child->>'rangeLower')::integer
        AND range_upper = (v_child->>'rangeUpper')::integer
        AND single_pitch IS NOT DISTINCT FROM NULLIF(v_child->>'singlePitch','')::integer
        AND engine_type = CASE WHEN v_child->>'addressMode'='pitchless'
          THEN 'non_tonal'::public.instrument_engine_type
          ELSE 'tonal'::public.instrument_engine_type END
        AND file_path_reference = v_child->>'filePathReference'
        AND instrument_family = v_child#>>'{metadataPolicy,instrumentFamily}'
        AND instrument_type = v_child#>>'{metadataPolicy,instrumentType}'
        AND collection IS NOT DISTINCT FROM NULLIF(v_child#>>'{metadataPolicy,collection}','')
        AND polyphony_type = (v_child#>>'{metadataPolicy,polyphonyType}')::public.instrument_polyphony_type
        AND articulation IS NOT DISTINCT FROM NULLIF(v_child#>>'{metadataPolicy,articulation}','')
        AND effect IS NOT DISTINCT FROM NULLIF(v_child#>>'{metadataPolicy,effect}','')
        AND cardinality(COALESCE(articulations,ARRAY[]::uuid[])) = 0
        AND cardinality(COALESCE(effects_instruments,ARRAY[]::uuid[])) = 0
        AND legato_transition IS NULL
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'semantic regroup existing target changed' USING ERRCODE = '55000';
      END IF;
      SELECT * INTO v_child_staging
      FROM public.sip_review_instrument
      WHERE id = v_child_staging_id
      FOR UPDATE;
      IF v_child_staging.id IS NULL OR v_child_staging.is_retired
         OR v_child_staging.source_contributor_slug IS DISTINCT FROM p_contributor_slug
         OR v_child_staging.contributor_id IS DISTINCT FROM v_parent.contributor_id
         OR v_child_staging.name IS DISTINCT FROM v_child->>'name'
         OR v_child_staging.source_sip_instrument_id IS NULL
         OR v_child_staging.asset_role::text IS DISTINCT FROM 'playable_sample'
         OR v_child_staging.playback_type IS DISTINCT FROM (v_child->>'playbackType')::public.instrument_playback_type
         OR v_child_staging.range_lower IS DISTINCT FROM (v_child->>'rangeLower')::integer
         OR v_child_staging.range_upper IS DISTINCT FROM (v_child->>'rangeUpper')::integer
         OR v_child_staging.single_pitch IS DISTINCT FROM NULLIF(v_child->>'singlePitch','')::integer
         OR v_child_staging.engine_type IS DISTINCT FROM (CASE WHEN v_child->>'addressMode'='pitchless'
           THEN 'non_tonal'::public.instrument_engine_type
           ELSE 'tonal'::public.instrument_engine_type END)
         OR v_child_staging.original_file_path_reference IS DISTINCT FROM v_child->>'filePathReference'
         OR v_child_staging.instrument_family IS DISTINCT FROM v_child#>>'{metadataPolicy,instrumentFamily}'
         OR v_child_staging.instrument_type IS DISTINCT FROM v_child#>>'{metadataPolicy,instrumentType}'
         OR v_child_staging.collection IS DISTINCT FROM NULLIF(v_child#>>'{metadataPolicy,collection}','')
         OR v_child_staging.polyphony_type IS DISTINCT FROM (v_child#>>'{metadataPolicy,polyphonyType}')::public.instrument_polyphony_type
         OR v_child_staging.articulation IS DISTINCT FROM NULLIF(v_child#>>'{metadataPolicy,articulation}','')
         OR v_child_staging.effect IS DISTINCT FROM NULLIF(v_child#>>'{metadataPolicy,effect}','')
         OR cardinality(COALESCE(v_child_staging.articulations,ARRAY[]::uuid[])) <> 0
         OR cardinality(COALESCE(v_child_staging.effects_instruments,ARRAY[]::uuid[])) <> 0
         OR v_child_staging.legato_transition IS NOT NULL THEN
        RAISE EXCEPTION 'semantic regroup existing target changed' USING ERRCODE = '55000';
      END IF;
      IF v_expected_target_metadata IS NULL
         OR v_expected_target_metadata->>'stagingInstrumentId' IS DISTINCT FROM v_child_staging_id::text
         OR v_expected_target_metadata->>'contributorId' IS DISTINCT FROM v_parent.contributor_id::text
         OR v_parent.contributor_id IS DISTINCT FROM (v_expected_target_metadata->>'contributorId')::uuid
         OR v_expected_target_metadata->>'pitchContentConfig' IS DISTINCT FROM
              (SELECT pitch_content_config::text FROM public.instruments_v2 WHERE id=v_child_v2_id)
         OR (v_expected_target_metadata->>'gain')::real IS DISTINCT FROM
              (SELECT gain FROM public.instruments_v2 WHERE id=v_child_v2_id)
         OR (v_expected_target_metadata->>'sustainCropTime')::real IS DISTINCT FROM
              (SELECT sustain_crop_time FROM public.instruments_v2 WHERE id=v_child_v2_id)
         OR v_expected_target_metadata->>'lookupKey' IS DISTINCT FROM
              (SELECT lookup_key FROM public.instruments_v2 WHERE id=v_child_v2_id)
         OR v_expected_target_metadata->>'filenameVariantMap' IS DISTINCT FROM
              (SELECT filename_variant_map::text FROM public.instruments_v2 WHERE id=v_child_v2_id)
         OR v_expected_target_metadata->>'sourceSipInstrumentId' IS DISTINCT FROM
              v_child_staging.source_sip_instrument_id::text
         OR v_expected_target_metadata->>'sourceGroupKey' IS DISTINCT FROM
              v_child_staging.source_group_key
         OR v_expected_target_metadata->>'stagingPitchContentConfig' IS DISTINCT FROM
              v_child_staging.pitch_content_config::text
         OR (v_expected_target_metadata->>'stagingGain')::real IS DISTINCT FROM
              v_child_staging.gain
         OR (v_expected_target_metadata->>'stagingSustainCropTime')::real IS DISTINCT FROM
              v_child_staging.sustain_crop_time
         OR (v_expected_target_metadata->>'stagingPublished')::boolean IS DISTINCT FROM
              v_child_staging.published
         OR v_expected_target_metadata->>'assetRole' IS DISTINCT FROM
              (SELECT asset_role::text FROM public.instruments_v2 WHERE id=v_child_v2_id)
         OR v_expected_target_metadata->>'stagingAssetRole' IS DISTINCT FROM
              v_child_staging.asset_role::text
         OR v_expected_target_metadata->'stagingVelocityLayerMap' IS DISTINCT FROM
              v_child_staging.velocity_layer_map
         OR v_expected_target_metadata->>'stagingIdentityHash' IS DISTINCT FROM
              v_child_staging.identity_hash THEN
        RAISE EXCEPTION 'semantic regroup existing target runtime state changed'
          USING ERRCODE='55000';
      END IF;
      PERFORM 1 FROM public.sip_review_promotion_map
      WHERE sip_review_instrument_id = v_child_staging_id
        AND instrument_v2_id = v_child_v2_id
      FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'semantic regroup existing target promotion map changed' USING ERRCODE = '55000';
      END IF;
      IF EXISTS (SELECT 1 FROM public.instrument_v2_legacy_map WHERE instrument_v2_id=v_child_v2_id)
         OR EXISTS (SELECT 1 FROM public.sip_review_legacy_map WHERE sip_review_instrument_id=v_child_staging_id)
         OR EXISTS (
           SELECT 1 FROM public.instruments_v2
           WHERE id=v_child_v2_id AND (
             cardinality(COALESCE(articulations,ARRAY[]::uuid[]))>0 OR
             cardinality(COALESCE(effects_instruments,ARRAY[]::uuid[]))>0 OR
             legato_transition IS NOT NULL)
         ) THEN
        RAISE EXCEPTION 'semantic regroup existing target has relationships or legacy aliases' USING ERRCODE='55000';
      END IF;
      IF ARRAY(
           SELECT tag_id FROM public.instrument_v2_instrument_tags
           WHERE instrument_v2_id=v_child_v2_id ORDER BY tag_id
         ) IS DISTINCT FROM ARRAY(
           SELECT tag_id::uuid FROM jsonb_array_elements_text(v_child#>'{metadataPolicy,tagIds}') tag_id
           ORDER BY tag_id::uuid
         ) OR ARRAY(
           SELECT tag_id FROM public.sip_review_instrument_tag
           WHERE sip_review_instrument_id=v_child_staging_id ORDER BY tag_id
         ) IS DISTINCT FROM ARRAY(
           SELECT tag_id::uuid FROM jsonb_array_elements_text(v_child#>'{metadataPolicy,tagIds}') tag_id
           ORDER BY tag_id::uuid
         ) THEN
        RAISE EXCEPTION 'semantic regroup existing target metadata tags changed'
          USING ERRCODE='55000';
      END IF;
      UPDATE public.instruments_v2 SET published = false, updated_at = now()
      WHERE id = v_child_v2_id;
      v_existing := v_existing + 1;
    ELSIF v_target_mode = 'create' THEN
      IF EXISTS (SELECT 1 FROM public.instruments_v2 WHERE id = v_child_v2_id)
         OR EXISTS (SELECT 1 FROM public.sip_review_instrument WHERE id = v_child_staging_id) THEN
        RAISE EXCEPTION 'semantic regroup create target identity is occupied' USING ERRCODE = '55000';
      END IF;
      INSERT INTO public.instruments_v2 (
        id,name,engine_type,playback_type,polyphony_type,instrument_family,instrument_type,
        contributor_id,collection,pitch_contents,pitch_content_config,range_lower,range_upper,
        single_pitch,gain,sustain_crop_time,file_path_reference,file_name_references,
        velocity_layers,round_robins,articulations,effects_instruments,mic_positions,
        articulation,effect,published,lookup_key,asset_role
      ) VALUES (
        v_child_v2_id,v_child->>'name',CASE WHEN v_child->>'addressMode'='pitchless'
          THEN 'non_tonal'::public.instrument_engine_type ELSE 'tonal'::public.instrument_engine_type END,
        (v_child->>'playbackType')::public.instrument_playback_type,
        (v_child#>>'{metadataPolicy,polyphonyType}')::public.instrument_polyphony_type,
        v_child#>>'{metadataPolicy,instrumentFamily}',v_child#>>'{metadataPolicy,instrumentType}',
        v_parent.contributor_id,NULLIF(v_child#>>'{metadataPolicy,collection}',''),
        v_parent.pitch_contents,v_parent.pitch_content_config,(v_child->>'rangeLower')::integer,
        (v_child->>'rangeUpper')::integer,NULLIF(v_child->>'singlePitch','')::integer,v_parent.gain,
        v_parent.sustain_crop_time,v_child->>'filePathReference',
        v_parent.file_name_references,v_parent.velocity_layers,v_parent.round_robins,ARRAY[]::uuid[],ARRAY[]::uuid[],
        v_parent.mic_positions,NULLIF(v_child#>>'{metadataPolicy,articulation}',''),
        NULLIF(v_child#>>'{metadataPolicy,effect}',''),false,
        v_parent.lookup_key||':semantic-regroup:'||v_child_v2_id,v_parent.asset_role
      );
      INSERT INTO public.sip_review_instrument (
        id,source_sip_instrument_id,source_contributor_slug,source_group_key,name,engine_type,
        playback_type,polyphony_type,instrument_family,instrument_type,contributor_id,collection,
        pitch_contents,velocity_layers,pitch_content_config,range_lower,range_upper,single_pitch,
        gain,sustain_crop_time,original_file_path_reference,original_file_name_references,
        articulations,effects_instruments,mic_positions,original_sample_ids,published,is_retired,
        split_parent_sip_review_instrument_id,staged_by,round_robins,velocity_layer_map,articulation,effect,asset_role
      ) SELECT
        v_child_staging_id,source_sip_instrument_id,source_contributor_slug,
        COALESCE(source_group_key,id::text)||'::semantic-regroup::'||v_child_staging_id,
        v_child->>'name',CASE WHEN v_child->>'addressMode'='pitchless'
          THEN 'non_tonal'::public.instrument_engine_type ELSE 'tonal'::public.instrument_engine_type END,
        (v_child->>'playbackType')::public.instrument_playback_type,
        (v_child#>>'{metadataPolicy,polyphonyType}')::public.instrument_polyphony_type,
        v_child#>>'{metadataPolicy,instrumentFamily}',v_child#>>'{metadataPolicy,instrumentType}',
        contributor_id,NULLIF(v_child#>>'{metadataPolicy,collection}',''),pitch_contents,
        velocity_layers,pitch_content_config,(v_child->>'rangeLower')::integer,(v_child->>'rangeUpper')::integer,
        NULLIF(v_child->>'singlePitch','')::integer,gain,sustain_crop_time,v_child->>'filePathReference',
        original_file_name_references,ARRAY[]::uuid[],ARRAY[]::uuid[],mic_positions,
        ARRAY(SELECT (s->>'sampleOriginalPathId')::uuid FROM jsonb_array_elements(v_child->'sources') s),
        false,false,v_parent_staging.id,p_applied_by,round_robins,
        COALESCE(velocity_layer_map,'{}'::jsonb),
        NULLIF(v_child#>>'{metadataPolicy,articulation}',''),NULLIF(v_child#>>'{metadataPolicy,effect}',''),
        asset_role
      FROM public.sip_review_instrument WHERE id = v_parent_staging.id;
      INSERT INTO public.sip_review_promotion_map(sip_review_instrument_id,instrument_v2_id,promoted_by,notes)
      VALUES(v_child_staging_id,v_child_v2_id,p_applied_by,'semantic-regroup:'||p_manifest_hash);
      IF EXISTS (
        SELECT 1 FROM jsonb_array_elements_text(v_child#>'{metadataPolicy,tagIds}') tag_id
        LEFT JOIN public.instrument_tags tag ON tag.id=tag_id::uuid
        WHERE tag.id IS NULL
      ) THEN
        RAISE EXCEPTION 'semantic regroup reviewed child metadata references an unknown tag'
          USING ERRCODE='55000';
      END IF;
      INSERT INTO public.sip_review_instrument_tag(sip_review_instrument_id,tag_id,source)
      SELECT v_child_staging_id,tag_id::uuid,'semantic-regroup-reviewed:'||p_manifest_hash
      FROM jsonb_array_elements_text(v_child#>'{metadataPolicy,tagIds}') tag_id;
      INSERT INTO public.instrument_v2_instrument_tags(instrument_v2_id,tag_id,source)
      SELECT v_child_v2_id,tag_id::uuid,'semantic-regroup-reviewed:'||p_manifest_hash
      FROM jsonb_array_elements_text(v_child#>'{metadataPolicy,tagIds}') tag_id;
      v_created := v_created + 1;
    ELSE
      RAISE EXCEPTION 'semantic regroup targetMode must be create or existing' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.sip_review_sample_override(
      sip_review_instrument_id,contributor_slug,file_path,collection,instrument_name,
      articulation,effect,mic_position,velocity,round_robin,midi_note,
      original_sample_id,pitch_content,filename,playback_type,run_id
    ) SELECT v_child_staging_id,p_contributor_slug,s->>'sourcePath',
      NULLIF(v_child#>>'{metadataPolicy,collection}',''),v_child->>'name',
      NULLIF(v_child#>>'{metadataPolicy,articulation}',''),
      NULLIF(v_child#>>'{metadataPolicy,effect}',''),
      NULLIF(s#>>'{canonical,micPosition}',''),s#>>'{canonical,velocity}',s#>>'{canonical,roundRobin}',
      s#>>'{canonical,midiNote}',(s->>'sampleOriginalPathId')::uuid,s#>>'{canonical,pitchContent}',
      s#>>'{canonical,filename}',(s#>>'{canonical,playbackType}')::public.instrument_playback_type,
      'semantic-regroup:'||p_manifest_hash
    FROM jsonb_array_elements(v_child->'sources') s
    ON CONFLICT(sip_review_instrument_id,original_sample_id) DO UPDATE SET
      contributor_slug=EXCLUDED.contributor_slug,
      file_path=EXCLUDED.file_path,
      collection=EXCLUDED.collection,
      instrument_name=EXCLUDED.instrument_name,
      articulation=EXCLUDED.articulation,
      effect=EXCLUDED.effect,
      mic_position=EXCLUDED.mic_position,
      velocity=EXCLUDED.velocity,
      round_robin=EXCLUDED.round_robin,
      midi_note=EXCLUDED.midi_note,
      pitch_content=EXCLUDED.pitch_content,
      filename=EXCLUDED.filename,
      playback_type=EXCLUDED.playback_type,
      run_id=EXCLUDED.run_id,
      updated_at=now();
    IF EXISTS (
      SELECT 1
      FROM public.sip_review_sample_playback_cues child_cue
      LEFT JOIN public.sip_review_sample_playback_cues parent_cue
        ON parent_cue.sip_review_instrument_id=v_parent_staging.id
       AND parent_cue.original_sample_id=child_cue.original_sample_id
      WHERE child_cue.sip_review_instrument_id=v_child_staging_id
        AND child_cue.original_sample_id IN (
          SELECT (s->>'sampleOriginalPathId')::uuid
          FROM jsonb_array_elements(v_child->'sources') s
        )
        AND (parent_cue.id IS NULL
          OR child_cue.file_path IS DISTINCT FROM parent_cue.file_path
          OR child_cue.sync_point_ms IS DISTINCT FROM parent_cue.sync_point_ms
          OR child_cue.loop_start_offset_ms IS DISTINCT FROM parent_cue.loop_start_offset_ms
          OR child_cue.loop_end_offset_ms IS DISTINCT FROM parent_cue.loop_end_offset_ms
          OR child_cue.sync_point_status IS DISTINCT FROM parent_cue.sync_point_status
          OR child_cue.loop_start_status IS DISTINCT FROM parent_cue.loop_start_status
          OR child_cue.loop_end_status IS DISTINCT FROM parent_cue.loop_end_status
          OR child_cue.analysis_payload IS DISTINCT FROM parent_cue.analysis_payload
          OR child_cue.analysis_run_id IS DISTINCT FROM parent_cue.analysis_run_id
          OR child_cue.analyzed_at IS DISTINCT FROM parent_cue.analyzed_at
        )
    ) THEN
      RAISE EXCEPTION 'semantic regroup child playback cue conflicts with reviewed parent cue'
        USING ERRCODE='55000';
    END IF;
    INSERT INTO public.sip_review_sample_playback_cues(
      sip_review_instrument_id,original_sample_id,file_path,sync_point_ms,loop_start_offset_ms,
      loop_end_offset_ms,sync_point_status,loop_start_status,loop_end_status,analysis_payload,
      analysis_run_id,analyzed_at
    ) SELECT v_child_staging_id,c.original_sample_id,c.file_path,c.sync_point_ms,c.loop_start_offset_ms,
      c.loop_end_offset_ms,c.sync_point_status,c.loop_start_status,c.loop_end_status,c.analysis_payload,
      c.analysis_run_id,c.analyzed_at FROM public.sip_review_sample_playback_cues c
    WHERE c.sip_review_instrument_id = v_parent_staging.id
      AND c.original_sample_id IN (SELECT (s->>'sampleOriginalPathId')::uuid FROM jsonb_array_elements(v_child->'sources') s)
    ON CONFLICT DO NOTHING;

    FOR v_source IN SELECT value FROM jsonb_array_elements(v_child->'sources') LOOP
      IF EXISTS (
        SELECT 1 FROM public.sample_path_constructs
        WHERE id=(v_source->>'constructId')::uuid AND instrument_v2_id IS NULL
      ) THEN
        v_restored := v_restored + 1;
      END IF;
      UPDATE public.sample_path_constructs SET
        instrument_v2_id=v_child_v2_id,instrument_name=v_child->>'name',
        collection=NULLIF(v_child#>>'{metadataPolicy,collection}',''),
        articulation=NULLIF(v_child#>>'{metadataPolicy,articulation}',''),
        effect=NULLIF(v_child#>>'{metadataPolicy,effect}',''),
        pitch_content=v_source#>>'{canonical,pitchContent}',midi_note=v_source#>>'{canonical,midiNote}',
        filename=v_source#>>'{canonical,filename}',velocity=(v_source#>>'{canonical,velocity}')::integer,
        round_robin=(v_source#>>'{canonical,roundRobin}')::integer,
        playback_type=(v_source#>>'{canonical,playbackType}')::public.instrument_playback_type,
        mic_position=v_source#>>'{canonical,micPosition}',updated_at=now()
      WHERE id=(v_source->>'constructId')::uuid
        AND contributor_id=v_parent.contributor_id
        AND (instrument_v2_id=v_parent.id OR instrument_v2_id IS NULL);
      IF NOT FOUND THEN RAISE EXCEPTION 'semantic regroup construct changed during cutover' USING ERRCODE='55000'; END IF;
      v_moved := v_moved + 1;
    END LOOP;
    UPDATE public.instruments_v2 SET
      original_sample_ids=ARRAY(
        SELECT spc.sample_original_path_id
        FROM public.sample_path_constructs spc
        WHERE spc.instrument_v2_id=v_child_v2_id
        ORDER BY spc.sample_original_path_id
      ),
      file_path_reference=v_child->>'filePathReference',
      file_name_references=CASE
        WHEN v_child->>'addressMode'='pitchless' THEN ARRAY['pitchless']::text[]
        ELSE NULL::text[]
      END,
      filename_variant_map=CASE
        WHEN v_child->>'addressMode'='pitchless' THEN NULL::jsonb
        ELSE filename_variant_map
      END,
      updated_at=now()
    WHERE id=v_child_v2_id;
    IF public.refresh_instrument_v2_axis_summaries_v1(ARRAY[v_child_v2_id]) IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'semantic regroup child axis summary refresh failed' USING ERRCODE='55000';
    END IF;
    UPDATE public.sip_review_instrument staging SET
      pitch_contents=instrument.pitch_contents,
      velocity_layers=instrument.velocity_layers,
      round_robins=instrument.round_robins,
      mic_positions=instrument.mic_positions,
      original_file_path_reference=instrument.file_path_reference,
      original_file_name_references=instrument.file_name_references,
      original_sample_ids=instrument.original_sample_ids,
      velocity_layer_map=COALESCE(staging.velocity_layer_map,'{}'::jsonb) || COALESCE((
        SELECT jsonb_object_agg(velocity::text,velocity)
        FROM (
          SELECT DISTINCT greatest(COALESCE(spc.velocity,0),0) velocity
          FROM public.sample_path_constructs spc
          WHERE spc.instrument_v2_id=v_child_v2_id
        ) velocities
      ),'{}'::jsonb),
      updated_at=now()
    FROM public.instruments_v2 instrument
    WHERE staging.id=v_child_staging_id AND instrument.id=v_child_v2_id;
    DELETE FROM public.sip_review_instrument_sample_scope scope
    WHERE scope.sip_review_instrument_id=v_child_staging_id
      AND NOT EXISTS (
        SELECT 1 FROM public.sample_path_constructs spc
        JOIN public.samples_original_paths sop ON sop.id=spc.sample_original_path_id
        WHERE spc.instrument_v2_id=v_child_v2_id
          AND spc.sample_original_path_id=scope.original_sample_id
          AND COALESCE(sop.s3_path,sop.file_name)=scope.file_path
      );
    INSERT INTO public.sip_review_instrument_sample_scope(
      sip_review_instrument_id,contributor_slug,file_path,original_sample_id
    )
    SELECT v_child_staging_id,p_contributor_slug,
      COALESCE(sop.s3_path,sop.file_name),spc.sample_original_path_id
    FROM public.sample_path_constructs spc
    JOIN public.samples_original_paths sop ON sop.id=spc.sample_original_path_id
    WHERE spc.instrument_v2_id=v_child_v2_id
    ON CONFLICT(sip_review_instrument_id,file_path) DO UPDATE SET
      contributor_slug=EXCLUDED.contributor_slug,
      original_sample_id=EXCLUDED.original_sample_id,
      updated_at=now();
    INSERT INTO public.instrument_v2_upload_status(instrument_v2_id,publish_actions_applied,publish_status,samples_processed,samples_total,needs,error_summary)
    VALUES(v_child_v2_id,false,'pending',0,(
      SELECT count(*) FROM public.sample_path_constructs spc
      WHERE spc.instrument_v2_id=v_child_v2_id
    ),ARRAY['publish_actions'],jsonb_build_object('semantic_regroup_manifest_hash',p_manifest_hash))
    ON CONFLICT(instrument_v2_id) DO UPDATE SET publish_actions_applied=false,publish_status='pending',samples_processed=0,
      samples_total=EXCLUDED.samples_total,needs=EXCLUDED.needs,error_summary=EXCLUDED.error_summary,published_at=NULL,updated_at=now();
    UPDATE public.instrument_v2_upload_status SET
      runtime_verification_status='pending',runtime_verification_started_at=NULL,
      runtime_verification_completed_at=NULL,runtime_verification_error_summary=NULL,
      runtime_verification_report_path=NULL
    WHERE instrument_v2_id=v_child_v2_id;
  END LOOP;

  FOR v_source IN SELECT value FROM jsonb_array_elements(p_manifest->'inactiveSources') LOOP
    UPDATE public.sample_path_constructs SET instrument_v2_id=NULL,updated_at=now()
    WHERE id=(v_source->>'constructId')::uuid
      AND contributor_id=v_parent.contributor_id
      AND instrument_v2_id=v_parent.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'semantic regroup inactive construct changed during cutover' USING ERRCODE='55000'; END IF;
    INSERT INTO public.sip_review_sample_disposition(
      sip_review_instrument_id,contributor_slug,original_sample_id,disposition,reason,evidence,reviewed_by
    ) VALUES(v_parent_staging.id,p_contributor_slug,(v_source->>'sampleOriginalPathId')::uuid,
      CASE v_source->>'disposition' WHEN 'deferred' THEN 'deferred_provenance' ELSE 'ignored_provenance' END,
      'semantic regroup inactive source',jsonb_build_object('manifest_hash',p_manifest_hash,'source_path',v_source->>'sourcePath'),p_applied_by)
    ON CONFLICT(sip_review_instrument_id,original_sample_id) DO UPDATE SET disposition=EXCLUDED.disposition,
      reason=EXCLUDED.reason,evidence=EXCLUDED.evidence,reviewed_by=EXCLUDED.reviewed_by,updated_at=now();
    v_inactive := v_inactive + 1;
  END LOOP;

  UPDATE public.instruments_v2 SET published=false,updated_at=now() WHERE id=v_parent.id;
  UPDATE public.sip_review_instrument SET is_retired=true,retired_at=COALESCE(retired_at,now()),
    retired_reason=COALESCE(retired_reason,'semantic-regroup'),retired_by=COALESCE(retired_by,p_applied_by),updated_at=now()
  WHERE id=v_parent_staging.id;
  v_result := jsonb_build_object(
    'manifest_hash',p_manifest_hash,'parent_instrument_v2_id',v_parent.id,
    'parent_staging_already_retired',v_parent_staging_already_retired,
    'child_instrument_v2_ids',v_child_ids,'created_targets',v_created,'existing_targets',v_existing,
    'moved_constructs',v_moved,'restored_constructs',v_restored,
    'inactive_constructs',v_inactive,'idempotent',false,
    'terminal_accounting_complete',false,
    'post_cutover_requirements',jsonb_build_array(
      'force_rerun_each_child',
      'runtime_verify_each_child',
      'current_audio_profile_each_child',
      'fresh_parent_public_object_orphan_audit',
      'guarded_orphan_cleanup_if_needed'
    )
  );
  INSERT INTO public.sip_semantic_regroup_receipts(
    provider_slug,manifest_hash,parent_instrument_v2_id,parent_sip_review_instrument_id,
    manifest,execution_context,result,applied_by
  ) VALUES (
    p_contributor_slug,p_manifest_hash,v_parent.id,v_parent_staging.id,
    p_manifest,jsonb_build_object(
      'expectedParentSourceSnapshot',p_expected_parent_source_snapshot,
      'expectedRecoverySnapshot',p_expected_snapshot,
      'expectedTargetSnapshot',p_expected_target_snapshot,
      'expectedTargetMetadataSnapshot',p_expected_target_metadata_snapshot
    ),v_result,p_applied_by
  );
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_coordinator_apply_semantic_regroup_plain_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_expected_snapshot" "jsonb", "p_expected_parent_source_snapshot" "jsonb", "p_expected_target_snapshot" "jsonb", "p_expected_target_metadata_snapshot" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_apply_semantic_regroup_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_expected_snapshot" "jsonb", "p_expected_parent_source_snapshot" "jsonb", "p_expected_target_snapshot" "jsonb", "p_expected_target_metadata_snapshot" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_policy jsonb := p_manifest->'legacyAliasPolicy';
  v_parent_v2_id uuid := (p_manifest#>>'{parent,instrumentV2Id}')::uuid;
  v_parent_staging_id uuid := (p_manifest#>>'{parent,stagingInstrumentId}')::uuid;
  v_expected_production jsonb;
  v_expected_staging jsonb;
  v_actual_production jsonb;
  v_actual_staging jsonb;
  v_locked_lease_id uuid;
  v_deleted integer;
BEGIN
  -- Receipt replay remains owned by the established primitive. The exact
  -- aliases are absent after a successful first apply, so replay must bypass
  -- first-apply snapshot validation.
  IF EXISTS (
    SELECT 1
    FROM public.sip_semantic_regroup_receipts receipt
    WHERE receipt.provider_slug = btrim(p_contributor_slug)
      AND receipt.manifest_hash = p_manifest_hash
  ) THEN
    RETURN private.sip_apply_semantic_regroup_pre_alias_detach_v1(
      p_contributor_slug, p_lease_id, p_lease_token, p_manifest_hash,
      p_manifest, p_expected_snapshot, p_expected_parent_source_snapshot,
      p_expected_target_snapshot, p_expected_target_metadata_snapshot,
      p_applied_by
    );
  END IF;

  -- Historical manifests retain their original behavior and hash.
  IF v_policy IS NULL THEN
    RETURN private.sip_apply_semantic_regroup_pre_alias_detach_v1(
      p_contributor_slug, p_lease_id, p_lease_token, p_manifest_hash,
      p_manifest, p_expected_snapshot, p_expected_parent_source_snapshot,
      p_expected_target_snapshot, p_expected_target_metadata_snapshot,
      p_applied_by
    );
  END IF;

  IF jsonb_typeof(v_policy) IS DISTINCT FROM 'object'
     OR v_policy->>'mode' IS DISTINCT FROM 'detach_parent_legacy_aliases'
     OR jsonb_typeof(v_policy->'productionAliases') IS DISTINCT FROM 'array'
     OR jsonb_typeof(v_policy->'stagingAliases') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'semantic regroup legacy alias policy is invalid'
      USING ERRCODE = '22023';
  END IF;
  v_expected_production := v_policy->'productionAliases';
  v_expected_staging := v_policy->'stagingAliases';
  IF jsonb_array_length(v_expected_production) = 0
     OR jsonb_array_length(v_expected_staging) = 0 THEN
    RAISE EXCEPTION 'semantic regroup legacy alias snapshot is incomplete'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  SELECT lease.id INTO v_locked_lease_id
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
    AND lease.provider_slug = btrim(p_contributor_slug)
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF v_locked_lease_id IS NULL THEN
    RAISE EXCEPTION 'semantic regroup requires an active provider lease'
      USING ERRCODE = '42501';
  END IF;

  -- Preserve the established lock order and strengthen only the two alias
  -- tables that this wrapper deletes from.
  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_promotion_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_playback_cues IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_instrument_tags IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_tag IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_upload_status IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_disposition IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_semantic_regroup_receipts IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_legacy_map IN SHARE ROW EXCLUSIVE MODE;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', alias.id::text,
      'instrumentV2Id', alias.instrument_v2_id::text,
      'legacyInstrumentId', alias.legacy_instrument_id::text,
      'sipReviewInstrumentId', alias.sip_review_instrument_id::text,
      'contributorSlug', alias.contributor_slug,
      'legacyLookupKey', alias.legacy_lookup_key,
      'legacyFilePathReference', alias.legacy_file_path_reference,
      'legacyVelocity', alias.legacy_velocity,
      'isPrimaryForLegacy', alias.is_primary_for_legacy,
      'isPrimaryForV2', alias.is_primary_for_v2,
      'notes', alias.notes,
      'createdBy', alias.created_by,
      'updatedBy', alias.updated_by,
      'primaryForLegacySetBy', alias.primary_for_legacy_set_by,
      'primaryForV2SetBy', alias.primary_for_v2_set_by
    ) ORDER BY alias.id::text
  ), '[]'::jsonb)
  INTO v_actual_production
  FROM public.instrument_v2_legacy_map alias
  WHERE alias.instrument_v2_id = v_parent_v2_id;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', alias.id,
      'sipReviewInstrumentId', alias.sip_review_instrument_id::text,
      'legacyInstrumentId', alias.legacy_instrument_id::text,
      'contributorSlug', alias.contributor_slug,
      'notes', alias.notes
    ) ORDER BY alias.id
  ), '[]'::jsonb)
  INTO v_actual_staging
  FROM public.sip_review_legacy_map alias
  WHERE alias.sip_review_instrument_id = v_parent_staging_id;

  IF v_actual_production IS DISTINCT FROM v_expected_production
     OR v_actual_staging IS DISTINCT FROM v_expected_staging THEN
    RAISE EXCEPTION 'semantic regroup legacy alias snapshot changed under lock'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_expected_production) production_alias
    WHERE production_alias->>'instrumentV2Id' IS DISTINCT FROM v_parent_v2_id::text
       OR production_alias->>'sipReviewInstrumentId' IS DISTINCT FROM v_parent_staging_id::text
       OR production_alias->>'contributorSlug' IS DISTINCT FROM btrim(p_contributor_slug)
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_expected_staging) staging_alias
    WHERE staging_alias->>'sipReviewInstrumentId' IS DISTINCT FROM v_parent_staging_id::text
       OR staging_alias->>'contributorSlug' IS DISTINCT FROM btrim(p_contributor_slug)
  ) OR ARRAY(
    SELECT production_alias->>'legacyInstrumentId'
    FROM jsonb_array_elements(v_expected_production) production_alias
    ORDER BY production_alias->>'legacyInstrumentId'
  ) IS DISTINCT FROM ARRAY(
    SELECT staging_alias->>'legacyInstrumentId'
    FROM jsonb_array_elements(v_expected_staging) staging_alias
    ORDER BY staging_alias->>'legacyInstrumentId'
  ) THEN
    RAISE EXCEPTION 'semantic regroup legacy alias snapshot does not belong to the exact parent'
      USING ERRCODE = '55000';
  END IF;

  DELETE FROM public.instrument_v2_legacy_map alias
  WHERE alias.instrument_v2_id = v_parent_v2_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  IF v_deleted <> jsonb_array_length(v_expected_production) THEN
    RAISE EXCEPTION 'semantic regroup production legacy alias detachment was incomplete'
      USING ERRCODE = '55000';
  END IF;
  DELETE FROM public.sip_review_legacy_map alias
  WHERE alias.sip_review_instrument_id = v_parent_staging_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  IF v_deleted <> jsonb_array_length(v_expected_staging) THEN
    RAISE EXCEPTION 'semantic regroup staging legacy alias detachment was incomplete'
      USING ERRCODE = '55000';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = v_locked_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'semantic regroup provider lease expired before alias cutover'
      USING ERRCODE = '42501';
  END IF;

  RETURN private.sip_apply_semantic_regroup_pre_alias_detach_v1(
    p_contributor_slug, p_lease_id, p_lease_token, p_manifest_hash,
    p_manifest, p_expected_snapshot, p_expected_parent_source_snapshot,
    p_expected_target_snapshot, p_expected_target_metadata_snapshot,
    p_applied_by
  );
END;
$$;


ALTER FUNCTION "public"."sip_publish_coordinator_apply_semantic_regroup_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_expected_snapshot" "jsonb", "p_expected_parent_source_snapshot" "jsonb", "p_expected_target_snapshot" "jsonb", "p_expected_target_metadata_snapshot" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_cancel_v1"("p_run_id" "uuid", "p_provider_lease_id" "uuid", "p_provider_lease_token" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.sip_fleet_provider_leases lease
    JOIN public.sip_fleet_runs run ON run.provider_slug=lease.provider_slug
    WHERE run.id=p_run_id AND lease.id=p_provider_lease_id AND lease.lease_token=p_provider_lease_token
      AND lease.lease_expires_at>now()) THEN RETURN false; END IF;
  RETURN public.cancel_sip_fleet_run(p_run_id,p_provider_lease_token,'operator_cancel');
END $$;


ALTER FUNCTION "public"."sip_publish_coordinator_cancel_v1"("p_run_id" "uuid", "p_provider_lease_id" "uuid", "p_provider_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_claim_item_v1"("p_run_id" "uuid", "p_instrument_v2_id" "uuid", "p_executor_id" "text", "p_lane_id" "text", "p_lease_seconds" integer DEFAULT 900) RETURNS "public"."sip_fleet_run_items"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT public.claim_sip_fleet_run_item(
    p_run_id,p_instrument_v2_id,p_executor_id,p_lane_id,p_lease_seconds)
$$;


ALTER FUNCTION "public"."sip_publish_coordinator_claim_item_v1"("p_run_id" "uuid", "p_instrument_v2_id" "uuid", "p_executor_id" "text", "p_lane_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_claim_v1"("p_executor_id" "text", "p_lane_id" "text", "p_lease_seconds" integer DEFAULT 900) RETURNS SETOF "public"."sip_fleet_run_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_executor public.sip_fleet_executor_leases%ROWTYPE;
BEGIN
  SELECT * INTO v_executor FROM public.acquire_sip_fleet_executor_lease(
    p_executor_id,least(p_lease_seconds,3600),ARRAY[p_lane_id],jsonb_build_object('laneId',p_lane_id));
  RETURN QUERY SELECT * FROM public.claim_sip_fleet_run_items(
    p_executor_id,v_executor.lease_token,1,p_lease_seconds);
END $$;


ALTER FUNCTION "public"."sip_publish_coordinator_claim_v1"("p_executor_id" "text", "p_lane_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_closeout_sibling_consolidation_v2"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_closeout_proof" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '120s'
    AS $_$
DECLARE
  v_receipt public.sip_sibling_consolidation_receipts_v2%ROWTYPE;
  v_target public.instruments_v2%ROWTYPE;
  v_upload public.instrument_v2_upload_status%ROWTYPE;
  v_profile jsonb;
  v_profile_job public.instrument_audio_profile_jobs_v1%ROWTYPE;
  v_current_signature text;
  v_publish_run_id uuid;
  v_pipeline_run_id text;
  v_repair_manifest_hash text;
  v_result_payload jsonb;
  v_projection_hash text;
  v_current_snapshot jsonb;
  v_current_structural_hash text;
  v_expected_closeout_structural_hash text;
  v_active_construct_ids uuid[];
  v_registered_construct_ids uuid[];
  v_result jsonb;
BEGIN
  IF NULLIF(btrim(p_contributor_slug), '') IS NULL
     OR NULLIF(btrim(p_applied_by), '') IS NULL
     OR p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_closeout_proof) IS DISTINCT FROM 'object'
     OR p_closeout_proof->>'manifestHash'
          IS DISTINCT FROM p_manifest_hash
     OR NULLIF(p_closeout_proof->>'projectionHash', '') IS NULL
     OR NULLIF(p_closeout_proof->>'publishRunId', '') IS NULL
     OR NULLIF(p_closeout_proof->>'pipelineRunId', '') IS NULL
     OR NULLIF(p_closeout_proof->>'repairManifestHash', '') IS NULL
     OR NULLIF(
          p_closeout_proof->>'runtimeVerificationReportPath',
          ''
        ) IS NULL
     OR NULLIF(
          p_closeout_proof->>'audioProfileSourceSignature',
          ''
        ) IS NULL THEN
    RAISE EXCEPTION 'invalid sibling consolidation v2 closeout request'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
    FOR UPDATE
  ) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 closeout requires active provider lease'
      USING ERRCODE = '42501';
  END IF;

  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_disposition IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_playback_cues IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_playback_cues IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_generated_derivations IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_publish_output_manifest IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_s3_path IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_upload_status IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE MODE;
  LOCK TABLE public.sip_review_legacy_map IN SHARE MODE;
  LOCK TABLE public.sip_fleet_runs IN SHARE MODE;
  LOCK TABLE public.sip_fleet_run_items IN SHARE MODE;
  LOCK TABLE public.sip_sibling_consolidation_receipts_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_sibling_consolidation_projection_v2 IN SHARE ROW EXCLUSIVE MODE;

  SELECT * INTO v_receipt
  FROM public.sip_sibling_consolidation_receipts_v2 receipt
  WHERE receipt.provider_slug = p_contributor_slug
    AND receipt.manifest_hash = p_manifest_hash
  FOR UPDATE;

  IF v_receipt.id IS NULL
     OR v_receipt.status <> 'cutover' THEN
    RAISE EXCEPTION
      'sibling consolidation v2 closeout receipt mismatch'
      USING ERRCODE = '42501';
  END IF;
  IF v_receipt.closeout_status = 'completed' THEN
    IF NOT (v_receipt.closeout_proof @> p_closeout_proof) THEN
      RAISE EXCEPTION 'sibling consolidation v2 closeout replay mismatch'
        USING ERRCODE = '40001';
    END IF;
    RETURN v_receipt.closeout_proof || jsonb_build_object('idempotent', true);
  END IF;
  IF v_receipt.closeout_status IS DISTINCT FROM 'pending' THEN
    RAISE EXCEPTION
      'sibling consolidation v2 closeout requires pending hidden target'
      USING ERRCODE = '55000';
  END IF;

  v_projection_hash :=
    public.sip_sibling_consolidation_projection_hash_v2(v_receipt.id);
  IF v_projection_hash IS DISTINCT FROM v_receipt.projection_hash
     OR p_closeout_proof->>'projectionHash'
          IS DISTINCT FROM v_receipt.projection_hash THEN
    RAISE EXCEPTION
      'sibling consolidation v2 closeout projection drifted'
      USING ERRCODE = '40001';
  END IF;
  v_current_snapshot :=
    public.sip_sibling_consolidation_snapshot_v2(v_receipt.manifest);
  v_current_structural_hash := encode(
    extensions.digest(
      convert_to(
        public.sip_sibling_consolidation_closeout_structural_snapshot_v2(
          v_current_snapshot
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
  v_expected_closeout_structural_hash := encode(
    extensions.digest(
      convert_to(
        public.sip_sibling_consolidation_closeout_structural_snapshot_v2(
          v_receipt.post_prepare_snapshot
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
  IF v_current_structural_hash
       IS DISTINCT FROM v_expected_closeout_structural_hash THEN
    RAISE EXCEPTION
      'sibling consolidation v2 hidden target structural state drifted'
      USING ERRCODE = '40001';
  END IF;

  SELECT target.* INTO v_target
  FROM public.instruments_v2 target
  WHERE target.id = v_receipt.canonical_instrument_v2_id
  FOR UPDATE;

  SELECT COALESCE(
    array_agg(projection.source_construct_id ORDER BY projection.source_construct_id),
    ARRAY[]::uuid[]
  )
  INTO v_active_construct_ids
  FROM public.sip_sibling_consolidation_projection_v2 projection
  WHERE projection.receipt_id = v_receipt.id
    AND projection.disposition = 'active';

  IF v_target.id IS NULL
     OR v_target.published
     OR EXISTS (
       SELECT 1
       FROM public.sip_sibling_consolidation_projection_v2 projection
       JOIN public.sample_path_constructs construct
         ON construct.id = projection.source_construct_id
        AND construct.sample_original_path_id =
            projection.sample_original_path_id
       WHERE projection.receipt_id = v_receipt.id
         AND (
           projection.status <> 'cutover'
           OR (
             projection.disposition = 'active'
             AND (
               construct.instrument_v2_id
                 IS DISTINCT FROM projection.target_instrument_v2_id
               OR construct.pitch_content
                 IS DISTINCT FROM projection.target_pitch_content
               OR construct.midi_note
                 IS DISTINCT FROM projection.target_midi_note
               OR construct.filename
                 IS DISTINCT FROM projection.target_filename
               OR construct.velocity
                 IS DISTINCT FROM projection.target_velocity
               OR construct.round_robin
                 IS DISTINCT FROM projection.target_round_robin
               OR construct.mic_position
                 IS DISTINCT FROM projection.target_mic_position
               OR construct.playback_type
                 IS DISTINCT FROM projection.target_playback_type
             )
           )
           OR (
             projection.disposition = 'deferred'
             AND construct.instrument_v2_id IS NOT NULL
           )
         )
     )
     OR ARRAY(
       SELECT construct.id
       FROM public.sample_path_constructs construct
       WHERE construct.instrument_v2_id = v_target.id
       ORDER BY construct.id
     ) IS DISTINCT FROM v_active_construct_ids
     OR EXISTS (
       SELECT 1
       FROM public.instruments_v2 source
       WHERE source.id = ANY(v_receipt.source_instrument_v2_ids)
         AND source.published
     )
     OR EXISTS (
       SELECT 1
       FROM public.sip_review_instrument source
       WHERE source.id = ANY(v_receipt.source_sip_review_instrument_ids)
         AND NOT source.is_retired
     ) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 closeout topology or lifecycle drifted'
      USING ERRCODE = '40001';
  END IF;

  SELECT
    run.id,
    COALESCE(
      NULLIF(item.result_payload->>'pipelineRunId', ''),
      NULLIF(item.payload->>'pipelineRunId', '')
    ),
    COALESCE(
      NULLIF(item.result_payload->>'repairManifestHash', ''),
      NULLIF(item.result_payload#>>'{repairManifest,manifestHash}', '')
    ),
    item.result_payload
  INTO
    v_publish_run_id,
    v_pipeline_run_id,
    v_repair_manifest_hash,
    v_result_payload
  FROM public.sip_fleet_runs run
  JOIN public.sip_fleet_run_items item ON item.run_id = run.id
  WHERE run.provider_slug = p_contributor_slug
    AND run.provider_lease_id = v_receipt.provider_lease_id
    AND run.status = 'completed'
    AND item.instrument_v2_id = v_target.id
    AND item.status = 'completed'
    AND item.finished_at >= v_receipt.cutover_at
    AND item.payload->>'mode' = 'sibling-consolidation'
    AND item.payload->>'forceRerun' = 'true'
    AND item.result_payload#>>'{repairManifest,version}' IS NOT NULL
  ORDER BY
    item.finished_at DESC,
    run.finished_at DESC NULLS LAST,
    run.id DESC
  LIMIT 1;

  IF v_publish_run_id IS NULL
     OR NULLIF(v_pipeline_run_id, '') IS NULL
     OR NULLIF(v_repair_manifest_hash, '') IS NULL
     OR p_closeout_proof->>'publishRunId'
          IS DISTINCT FROM v_publish_run_id::text
     OR p_closeout_proof->>'pipelineRunId'
          IS DISTINCT FROM v_pipeline_run_id
     OR p_closeout_proof->>'repairManifestHash'
          IS DISTINCT FROM v_repair_manifest_hash
     OR ARRAY(
       SELECT value::uuid
       FROM jsonb_array_elements_text(
         v_result_payload#>'{repairManifest,samplePathConstructIds}'
       ) value
       ORDER BY value::uuid
     ) IS DISTINCT FROM v_active_construct_ids THEN
    RAISE EXCEPTION
      'sibling consolidation v2 post-cutover publish proof is incomplete'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(
    array_agg(
      DISTINCT output.sample_path_construct_id
      ORDER BY output.sample_path_construct_id
    ),
    ARRAY[]::uuid[]
  )
  INTO v_registered_construct_ids
  FROM public.instrument_v2_publish_output_manifest output
  WHERE output.instrument_v2_id = v_target.id
    AND output.status = 'completed'
    AND output.processed_at >= v_receipt.cutover_at
    AND output.output_object_identity IS NOT NULL
    AND output.format = 'mp3'
    AND output.quality = 1;

  SELECT * INTO v_upload
  FROM public.instrument_v2_upload_status upload
  WHERE upload.instrument_v2_id = v_target.id
  FOR UPDATE;

  v_current_signature :=
    public.compute_instrument_audio_profile_signature_v1(v_target.id);
  SELECT to_jsonb(profile) INTO v_profile
  FROM public.instrument_audio_profile_v1 profile
  WHERE profile.instrument_v2_id = v_target.id
    AND profile.source_signature = v_current_signature;
  SELECT job.* INTO v_profile_job
  FROM public.instrument_audio_profile_jobs_v1 job
  WHERE job.instrument_v2_id = v_target.id
    AND job.source_signature = v_current_signature
    AND job.status IN ('completed', 'completed_with_warnings')
    AND job.completed_at >= v_receipt.cutover_at
  ORDER BY job.completed_at DESC
  LIMIT 1;

  IF v_upload.instrument_v2_id IS NULL
     OR NOT v_upload.publish_actions_applied
     OR v_upload.published_at IS NULL
     OR v_upload.published_at < v_receipt.cutover_at
     OR v_upload.runtime_verification_status <> 'passed'
     OR v_upload.runtime_verification_completed_at IS NULL
     OR v_upload.runtime_verification_completed_at < v_receipt.cutover_at
     OR NULLIF(v_upload.runtime_verification_report_path, '') IS NULL
     OR v_registered_construct_ids IS DISTINCT FROM v_active_construct_ids
     OR v_profile IS NULL
     OR v_profile_job.id IS NULL
     OR p_closeout_proof->>'runtimeVerificationReportPath'
          IS DISTINCT FROM v_upload.runtime_verification_report_path
     OR p_closeout_proof->>'audioProfileSourceSignature'
          IS DISTINCT FROM v_current_signature THEN
    RAISE EXCEPTION
      'sibling consolidation v2 post-cutover publish closeout failed'
      USING ERRCODE = '55000';
  END IF;

  v_result := public.set_instrument_v2_published_manifest_aware_v1(
    v_target.id,
    true
  );
  IF v_result->>'fallbackState' = 'blocked' THEN
    RETURN p_closeout_proof || jsonb_build_object(
      'manifestHash', p_manifest_hash,
      'canonicalInstrumentV2Id', v_target.id,
      'targetPublished', false,
      'closeoutStatus', 'blocked',
      'runtimeManifestReadiness', v_result,
      'idempotent', false
    );
  END IF;
  IF NOT COALESCE((v_result->>'published')::boolean, false) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 hidden target publication raced'
      USING ERRCODE = '40001';
  END IF;

  v_result := p_closeout_proof || jsonb_build_object(
    'manifestHash', p_manifest_hash,
    'canonicalInstrumentV2Id', v_target.id,
    'publishRunId', v_publish_run_id,
    'pipelineRunId', v_pipeline_run_id,
    'repairManifestHash', v_repair_manifest_hash,
    'runtimeVerificationStatus', v_upload.runtime_verification_status,
    'audioProfileSourceSignature', v_current_signature,
    'targetPublished', true,
    'completedAt', now(),
    'idempotent', false
  );
  UPDATE public.sip_sibling_consolidation_receipts_v2
  SET publish_run_id = v_publish_run_id,
      closeout_status = 'completed',
      closeout_proof = v_result,
      closeout_completed_at = now()
  WHERE id = v_receipt.id;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_coordinator_closeout_sibling_consolidation_v2"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_closeout_proof" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_complete_v1"("p_run_id" "uuid", "p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_status" "text", "p_result" "jsonb" DEFAULT '{}'::"jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_status NOT IN ('completed','failed','canceled') THEN RAISE EXCEPTION 'invalid_completion_status'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.sip_fleet_run_items WHERE id=p_item_id AND run_id=p_run_id)
    THEN RETURN false; END IF;
  IF p_status='canceled' THEN
    UPDATE public.sip_fleet_run_items SET status='canceled',result_payload=coalesce(p_result,'{}'::jsonb),
      last_error=p_error,finished_at=now(),executor_id=NULL,lease_token=NULL,lease_expires_at=NULL
    WHERE id=p_item_id AND run_id=p_run_id AND status='running' AND executor_id=p_executor_id
      AND lease_token=p_lease_token AND lease_expires_at>now();
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE public.sip_fleet_runs SET status='canceled',finished_at=now()
      WHERE id=p_run_id AND cancel_requested
        AND NOT EXISTS(SELECT 1 FROM public.sip_fleet_run_items WHERE run_id=p_run_id AND status='running');
    RETURN true;
  END IF;
  RETURN public.complete_sip_fleet_run_item(p_item_id,p_executor_id,p_lease_token,p_status='completed',p_result,p_error);
END $$;


ALTER FUNCTION "public"."sip_publish_coordinator_complete_v1"("p_run_id" "uuid", "p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_status" "text", "p_result" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_contributor_id_v1"("p_provider_slug" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT contributor.id
  FROM public.contributors contributor
  WHERE contributor.slug = btrim(p_provider_slug)
     OR (
       btrim(p_provider_slug) = 'versilian-studios'
       AND regexp_replace(lower(coalesce(contributor.company_name, '')), '[^a-z0-9]+', '', 'g') = 'versilianstudiosllc'
     )
     OR (
       btrim(p_provider_slug) = 'gospel-musicians'
       AND regexp_replace(lower(coalesce(contributor.company_name, '')), '[^a-z0-9]+', '', 'g') = 'gospelmusiciansllc'
     )
  ORDER BY CASE
    WHEN btrim(p_provider_slug) = 'versilian-studios'
      AND regexp_replace(lower(coalesce(contributor.company_name, '')), '[^a-z0-9]+', '', 'g') = 'versilianstudiosllc'
      THEN 0
    WHEN btrim(p_provider_slug) = 'gospel-musicians'
      AND regexp_replace(lower(coalesce(contributor.company_name, '')), '[^a-z0-9]+', '', 'g') = 'gospelmusiciansllc'
      THEN 0
    WHEN contributor.slug = btrim(p_provider_slug) THEN 1
    ELSE 2
  END
  LIMIT 1
$$;


ALTER FUNCTION "public"."sip_publish_coordinator_contributor_id_v1"("p_provider_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_cutover_sibling_consolidation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_readiness_proof" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_receipt public.sip_sibling_consolidation_receipts%ROWTYPE;
  v_target public.instruments_v2%ROWTYPE;
  v_target_staging public.sip_review_instrument%ROWTYPE;
  v_target_source_sip_id uuid;
  v_source_sip_ids uuid[];
  v_current_snapshot jsonb;
  v_current_snapshot_hash text;
  v_result jsonb;
  v_relationship_rows integer := 0;
  v_alias_rows integer := 0;
  v_retired_v2 integer := 0;
  v_retired_staging integer := 0;
BEGIN
  IF NULLIF(btrim(p_contributor_slug), '') IS NULL
     OR NULLIF(btrim(p_applied_by), '') IS NULL
     OR p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_readiness_proof) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid sibling consolidation cutover identity'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug), 0));
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
    FOR UPDATE
  ) THEN
    RAISE EXCEPTION 'sibling consolidation provider lease expired before cutover'
      USING ERRCODE = '42501';
  END IF;
  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_legacy_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_upload_status IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_sibling_consolidation_receipts IN SHARE ROW EXCLUSIVE MODE;

  SELECT * INTO v_receipt
  FROM public.sip_sibling_consolidation_receipts receipt
  WHERE receipt.provider_slug = p_contributor_slug
    AND receipt.manifest_hash = p_manifest_hash
  FOR UPDATE;
  IF v_receipt.id IS NULL THEN
    RAISE EXCEPTION 'sibling consolidation must be prepared before cutover'
      USING ERRCODE = '55000';
  END IF;
  IF v_receipt.status = 'cutover' THEN
    IF v_receipt.readiness_proof IS DISTINCT FROM p_readiness_proof THEN
      RAISE EXCEPTION 'sibling consolidation cutover replay mismatch'
        USING ERRCODE = '22023';
    END IF;
    RETURN v_receipt.cutover_result || jsonb_build_object('idempotent', true);
  END IF;

  SELECT * INTO v_target
  FROM public.instruments_v2
  WHERE id = v_receipt.canonical_instrument_v2_id
  FOR UPDATE;
  SELECT * INTO v_target_staging
  FROM public.sip_review_instrument
  WHERE id = v_receipt.canonical_sip_review_instrument_id
  FOR UPDATE;
  v_target_source_sip_id := v_target_staging.source_sip_instrument_id;
  SELECT COALESCE(array_agg(source.source_sip_instrument_id ORDER BY source.source_sip_instrument_id), ARRAY[]::uuid[])
  INTO v_source_sip_ids
  FROM public.sip_review_instrument source
  WHERE source.id = ANY(v_receipt.source_sip_review_instrument_ids);

  v_current_snapshot := public.sip_sibling_consolidation_snapshot_v1(v_receipt.manifest);
  v_current_snapshot_hash := encode(
    extensions.digest(convert_to(v_current_snapshot::text, 'UTF8'), 'sha256'),
    'hex'
  );
  IF v_current_snapshot IS DISTINCT FROM v_receipt.post_prepare_snapshot
     OR v_current_snapshot_hash IS DISTINCT FROM v_receipt.post_prepare_snapshot_hash THEN
    RAISE EXCEPTION 'sibling consolidation prepared state changed before cutover'
      USING ERRCODE = '40001';
  END IF;

  IF p_readiness_proof->>'manifestHash' IS DISTINCT FROM p_manifest_hash
     OR p_readiness_proof->>'instrumentV2Id' IS DISTINCT FROM v_target.id::text
     OR p_readiness_proof->>'runtimeVerificationStatus' IS DISTINCT FROM 'passed'
     OR p_readiness_proof->>'audioProfileStatus'
        NOT IN ('completed', 'completed_with_warnings')
     OR NULLIF(btrim(p_readiness_proof->>'publishRunId'), '') IS NULL
     OR NULLIF(btrim(p_readiness_proof->>'audioProfileSourceSignature'), '') IS NULL
     OR NULLIF(btrim(p_readiness_proof->>'verifiedAt'), '') IS NULL THEN
    RAISE EXCEPTION 'sibling consolidation target readiness proof is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT v_target.published OR v_target_staging.is_retired
     OR NOT EXISTS (
       SELECT 1
       FROM public.instrument_v2_upload_status upload
       WHERE upload.instrument_v2_id = v_target.id
         AND upload.publish_actions_applied
         AND upload.runtime_verification_status = 'passed'
         AND upload.runtime_verification_completed_at IS NOT NULL
     )
     OR NOT EXISTS (
       SELECT 1
       FROM public.instrument_audio_profile_v1 profile
       JOIN public.instrument_audio_profile_jobs_v1 job
         ON job.instrument_v2_id = profile.instrument_v2_id
        AND job.profile_version = profile.profile_version
        AND job.source_signature = profile.source_signature
       WHERE profile.instrument_v2_id = v_target.id
         AND profile.source_signature = p_readiness_proof->>'audioProfileSourceSignature'
         AND profile.source_signature = public.compute_instrument_audio_profile_signature_v1(
           v_target.id, profile.profile_version
         )
         AND job.status = p_readiness_proof->>'audioProfileStatus'
         AND job.completed_at IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'sibling consolidation target is not currently publish and profile ready'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.instrument_v2_legacy_map source_alias
    JOIN public.instrument_v2_legacy_map other_alias
      ON other_alias.legacy_instrument_id = source_alias.legacy_instrument_id
     AND other_alias.id <> source_alias.id
     AND other_alias.instrument_v2_id <> ALL(v_receipt.source_instrument_v2_ids)
     AND other_alias.instrument_v2_id <> v_target.id
    WHERE source_alias.instrument_v2_id = ANY(v_receipt.source_instrument_v2_ids)
  ) OR EXISTS (
    SELECT 1
    FROM public.instrument_v2_legacy_map source_alias
    JOIN public.instrument_v2_legacy_map target_alias
      ON target_alias.legacy_instrument_id = source_alias.legacy_instrument_id
     AND target_alias.instrument_v2_id = v_target.id
    WHERE source_alias.instrument_v2_id = ANY(v_receipt.source_instrument_v2_ids)
  ) THEN
    RAISE EXCEPTION 'sibling consolidation legacy alias remap is ambiguous'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.instruments_v2 relation
    WHERE relation.id = ANY(v_receipt.source_instrument_v2_ids)
      AND (
        cardinality(COALESCE(relation.articulations, ARRAY[]::uuid[])) > 0
        OR cardinality(COALESCE(relation.effects_instruments, ARRAY[]::uuid[])) > 0
        OR relation.legato_transition IS NOT NULL
      )
  ) THEN
    RAISE EXCEPTION 'sibling consolidation source relationships changed before cutover'
      USING ERRCODE = '40001';
  END IF;

  PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);

  UPDATE public.instruments_v2 relation
  SET articulations = ARRAY(
        SELECT DISTINCT CASE
          WHEN member = ANY(v_receipt.source_instrument_v2_ids) THEN v_target.id
          ELSE member
        END
        FROM unnest(COALESCE(relation.articulations, ARRAY[]::uuid[])) member
        ORDER BY 1
      ),
      effects_instruments = ARRAY(
        SELECT DISTINCT CASE
          WHEN member = ANY(v_receipt.source_instrument_v2_ids) THEN v_target.id
          ELSE member
        END
        FROM unnest(COALESCE(relation.effects_instruments, ARRAY[]::uuid[])) member
        ORDER BY 1
      ),
      legato_transition = CASE
        WHEN relation.legato_transition = ANY(v_receipt.source_instrument_v2_ids)
        THEN v_target.id
        ELSE relation.legato_transition
      END,
      updated_at = now()
  WHERE COALESCE(relation.articulations, ARRAY[]::uuid[]) && v_receipt.source_instrument_v2_ids
     OR COALESCE(relation.effects_instruments, ARRAY[]::uuid[]) && v_receipt.source_instrument_v2_ids
     OR relation.legato_transition = ANY(v_receipt.source_instrument_v2_ids);
  GET DIAGNOSTICS v_relationship_rows = ROW_COUNT;

  UPDATE public.sip_review_instrument relation
  SET articulations = ARRAY(
        SELECT DISTINCT CASE WHEN member = ANY(v_source_sip_ids)
          THEN v_target_source_sip_id ELSE member END
        FROM unnest(COALESCE(relation.articulations, ARRAY[]::uuid[])) member
        ORDER BY 1
      ),
      effects_instruments = ARRAY(
        SELECT DISTINCT CASE WHEN member = ANY(v_source_sip_ids)
          THEN v_target_source_sip_id ELSE member END
        FROM unnest(COALESCE(relation.effects_instruments, ARRAY[]::uuid[])) member
        ORDER BY 1
      ),
      legato_transition = CASE
        WHEN relation.legato_transition = ANY(v_receipt.source_sip_review_instrument_ids)
        THEN v_target_staging.id
        ELSE relation.legato_transition
      END,
      updated_at = now()
  WHERE COALESCE(relation.articulations, ARRAY[]::uuid[]) && v_source_sip_ids
     OR COALESCE(relation.effects_instruments, ARRAY[]::uuid[]) && v_source_sip_ids
     OR relation.legato_transition = ANY(v_receipt.source_sip_review_instrument_ids);

  UPDATE public.instrument_v2_legacy_map alias
  SET instrument_v2_id = v_target.id,
      sip_review_instrument_id = v_target_staging.id,
      contributor_slug = p_contributor_slug,
      updated_by = p_applied_by,
      updated_at = now()
  WHERE alias.instrument_v2_id = ANY(v_receipt.source_instrument_v2_ids);
  GET DIAGNOSTICS v_alias_rows = ROW_COUNT;

  UPDATE public.sip_review_legacy_map alias
  SET sip_review_instrument_id = v_target_staging.id,
      contributor_slug = p_contributor_slug,
      updated_at = now()
  WHERE alias.sip_review_instrument_id = ANY(v_receipt.source_sip_review_instrument_ids);

  UPDATE public.instruments_v2 source
  SET published = false, updated_at = now()
  WHERE source.id = ANY(v_receipt.source_instrument_v2_ids)
    AND source.published;
  GET DIAGNOSTICS v_retired_v2 = ROW_COUNT;
  IF v_retired_v2 IS DISTINCT FROM cardinality(v_receipt.source_instrument_v2_ids) THEN
    RAISE EXCEPTION 'sibling consolidation source publication state changed during cutover'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.sip_review_instrument source
  SET is_retired = true,
      retired_at = now(),
      retired_reason = 'sibling-consolidation:' || p_manifest_hash,
      retired_by = p_applied_by,
      updated_at = now()
  WHERE source.id = ANY(v_receipt.source_sip_review_instrument_ids)
    AND NOT source.is_retired;
  GET DIAGNOSTICS v_retired_staging = ROW_COUNT;
  IF v_retired_staging IS DISTINCT FROM cardinality(v_receipt.source_sip_review_instrument_ids) THEN
    RAISE EXCEPTION 'sibling consolidation source staging state changed during cutover'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.instrument_v2_upload_status upload
  SET runtime_verification_status = 'skipped',
      runtime_verification_error_summary = jsonb_build_object(
        'kind', 'terminal_disposition',
        'reason', 'sibling_consolidated',
        'manifest_hash', p_manifest_hash,
        'canonical_instrument_v2_id', v_target.id
      ),
      updated_at = now()
  WHERE upload.instrument_v2_id = ANY(v_receipt.source_instrument_v2_ids);

  v_result := jsonb_build_object(
    'manifestHash', p_manifest_hash,
    'canonicalInstrumentV2Id', v_target.id,
    'sourceInstrumentV2Ids', to_jsonb(v_receipt.source_instrument_v2_ids),
    'relationshipsRemapped', v_relationship_rows,
    'legacyAliasesRemapped', v_alias_rows,
    'sourceInstrumentsUnpublished', v_retired_v2,
    'sourceStagingRowsRetired', v_retired_staging,
    'samplesDeleted', 0,
    'constructsDeleted', 0,
    'idempotent', false
  );
  UPDATE public.sip_sibling_consolidation_receipts
  SET status = 'cutover',
      readiness_proof = p_readiness_proof,
      cutover_result = v_result,
      cutover_by = p_applied_by,
      cutover_at = now()
  WHERE id = v_receipt.id;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_coordinator_cutover_sibling_consolidation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_readiness_proof" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_cutover_sibling_consolidation_v2"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_readiness_proof" "jsonb", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_receipt public.sip_sibling_consolidation_receipts_v2%ROWTYPE;
  v_target public.instruments_v2%ROWTYPE;
  v_target_staging public.sip_review_instrument%ROWTYPE;
  v_projection_hash text;
  v_current_snapshot jsonb;
  v_current_snapshot_hash text;
  v_current_structural_hash text;
  v_active_construct_ids uuid[];
  v_source_sip_ids uuid[];
  v_target_source_sip_id uuid;
  v_result jsonb;
BEGIN
  IF NULLIF(btrim(p_contributor_slug), '') IS NULL
     OR NULLIF(btrim(p_applied_by), '') IS NULL
     OR p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_readiness_proof) IS DISTINCT FROM 'object'
     OR p_readiness_proof->>'authorization' IS DISTINCT FROM 'cutover'
     OR p_readiness_proof->>'approved' IS DISTINCT FROM 'true'
     OR p_readiness_proof->>'manifestHash'
          IS DISTINCT FROM p_manifest_hash THEN
    RAISE EXCEPTION 'invalid sibling consolidation v2 cutover request'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
    FOR UPDATE
  ) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 cutover requires active provider lease'
      USING ERRCODE = '42501';
  END IF;

  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_disposition IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_playback_cues IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_playback_cues IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_generated_derivations IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_publish_output_manifest IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_s3_path IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_upload_status IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE MODE;
  LOCK TABLE public.sip_review_legacy_map IN SHARE MODE;
  LOCK TABLE public.sip_fleet_runs IN SHARE MODE;
  LOCK TABLE public.sip_fleet_run_items IN SHARE MODE;
  LOCK TABLE public.sip_sibling_consolidation_receipts_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_sibling_consolidation_projection_v2 IN SHARE ROW EXCLUSIVE MODE;

  SELECT * INTO v_receipt
  FROM public.sip_sibling_consolidation_receipts_v2 receipt
  WHERE receipt.provider_slug = p_contributor_slug
    AND receipt.manifest_hash = p_manifest_hash
  FOR UPDATE;

  IF v_receipt.id IS NULL THEN
    RAISE EXCEPTION 'sibling consolidation v2 prepare receipt not found'
      USING ERRCODE = '55000';
  END IF;
  IF v_receipt.provider_lease_id IS DISTINCT FROM p_lease_id
     OR v_receipt.provider_lease_token IS DISTINCT FROM p_lease_token THEN
    RAISE EXCEPTION 'sibling consolidation v2 cutover lease differs from prepare receipt'
      USING ERRCODE = '42501';
  END IF;
  IF v_receipt.status = 'cutover' THEN
    IF v_receipt.readiness_proof IS DISTINCT FROM p_readiness_proof THEN
      RAISE EXCEPTION 'sibling consolidation v2 cutover replay mismatch'
        USING ERRCODE = '40001';
    END IF;
    RETURN v_receipt.cutover_result || jsonb_build_object(
      'idempotent', true,
      'closeoutStatus', v_receipt.closeout_status
    );
  END IF;
  IF v_receipt.status <> 'prepared' THEN
    RAISE EXCEPTION 'sibling consolidation v2 cutover requires prepared receipt'
      USING ERRCODE = '55000';
  END IF;

  v_projection_hash :=
    public.sip_sibling_consolidation_projection_hash_v2(v_receipt.id);
  IF v_projection_hash IS DISTINCT FROM v_receipt.projection_hash THEN
    RAISE EXCEPTION 'sibling consolidation v2 projection drifted before cutover'
      USING ERRCODE = '40001';
  END IF;

  v_current_snapshot :=
    public.sip_sibling_consolidation_snapshot_v2(v_receipt.manifest);
  v_current_structural_hash := encode(
    extensions.digest(
      convert_to(
        public.sip_sibling_consolidation_structural_snapshot_v2(
          v_current_snapshot
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
  IF v_current_structural_hash
       IS DISTINCT FROM v_receipt.post_prepare_structural_hash THEN
    RAISE EXCEPTION
      'sibling consolidation v2 prepared state drifted before cutover'
      USING ERRCODE = '40001';
  END IF;
  IF p_readiness_proof->>'preparedSnapshotHash'
       IS DISTINCT FROM v_receipt.prepared_snapshot_hash
     OR p_readiness_proof->>'projectionHash'
       IS DISTINCT FROM v_receipt.projection_hash THEN
    RAISE EXCEPTION
      'sibling consolidation v2 cutover proof does not bind prepared state'
      USING ERRCODE = '40001';
  END IF;

  SELECT target.* INTO v_target
  FROM public.instruments_v2 target
  WHERE target.id = v_receipt.canonical_instrument_v2_id
  FOR UPDATE;
  SELECT target.* INTO v_target_staging
  FROM public.sip_review_instrument target
  WHERE target.id = v_receipt.canonical_sip_review_instrument_id
  FOR UPDATE;

  SELECT COALESCE(
    array_agg(projection.source_construct_id ORDER BY projection.source_construct_id),
    ARRAY[]::uuid[]
  )
  INTO v_active_construct_ids
  FROM public.sip_sibling_consolidation_projection_v2 projection
  WHERE projection.receipt_id = v_receipt.id
    AND projection.disposition = 'active';

  PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);

  UPDATE public.sample_path_constructs construct
  SET instrument_v2_id = NULL
  FROM public.sip_sibling_consolidation_projection_v2 projection
  WHERE projection.receipt_id = v_receipt.id
    AND construct.id = projection.source_construct_id
    AND construct.sample_original_path_id =
        projection.sample_original_path_id
    AND construct.instrument_v2_id =
        projection.source_instrument_v2_id;

  IF EXISTS (
    SELECT 1
    FROM public.sip_sibling_consolidation_projection_v2 projection
    JOIN public.sample_path_constructs construct
      ON construct.id = projection.source_construct_id
    WHERE projection.receipt_id = v_receipt.id
      AND construct.instrument_v2_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 partition detach was incomplete'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.sample_path_constructs construct
  SET instrument_v2_id = projection.target_instrument_v2_id,
      instrument_name =
        v_receipt.manifest#>>'{canonicalTarget,metadata,name}',
      mic_position = projection.target_mic_position,
      velocity = projection.target_velocity,
      round_robin = projection.target_round_robin,
      midi_note = projection.target_midi_note,
      pitch_content = projection.target_pitch_content,
      filename = projection.target_filename,
      playback_type = projection.target_playback_type
  FROM public.sip_sibling_consolidation_projection_v2 projection
  WHERE projection.receipt_id = v_receipt.id
    AND projection.disposition = 'active'
    AND construct.id = projection.source_construct_id
    AND construct.sample_original_path_id =
        projection.sample_original_path_id
    AND construct.instrument_v2_id IS NULL;

  IF NOT FOUND OR (
    SELECT count(*)
    FROM public.sample_path_constructs construct
    WHERE construct.id = ANY(v_active_construct_ids)
      AND construct.instrument_v2_id = v_target.id
  ) IS DISTINCT FROM cardinality(v_active_construct_ids) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 active construct transfer was incomplete'
      USING ERRCODE = '40001';
  END IF;

  IF ARRAY(
       SELECT construct.id
       FROM public.sample_path_constructs construct
       WHERE construct.instrument_v2_id = v_target.id
       ORDER BY construct.id
     ) IS DISTINCT FROM v_active_construct_ids THEN
    RAISE EXCEPTION
      'sibling consolidation v2 cutover target grid is not exact'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.instruments_v2 target
  SET name = v_receipt.manifest#>>'{canonicalTarget,metadata,name}',
      engine_type =
        (v_receipt.manifest#>>'{canonicalTarget,metadata,engineType}')
          ::public.instrument_engine_type,
      playback_type =
        (v_receipt.manifest#>>'{canonicalTarget,metadata,playbackType}')
          ::public.instrument_playback_type,
      polyphony_type =
        (v_receipt.manifest#>>'{canonicalTarget,metadata,polyphonyType}')
          ::public.instrument_polyphony_type,
      instrument_family =
        v_receipt.manifest#>>'{canonicalTarget,metadata,instrumentFamily}',
      instrument_type =
        v_receipt.manifest#>>'{canonicalTarget,metadata,instrumentType}',
      range_lower =
        (v_receipt.manifest#>>'{canonicalTarget,metadata,rangeLower}')::integer,
      range_upper =
        (v_receipt.manifest#>>'{canonicalTarget,metadata,rangeUpper}')::integer,
      single_pitch = CASE
        WHEN v_receipt.manifest#>'{canonicalTarget,metadata,singlePitch}'
               = 'null'::jsonb
        THEN NULL
        ELSE (
          v_receipt.manifest#>>'{canonicalTarget,metadata,singlePitch}'
        )::integer
      END,
      file_path_reference =
        v_receipt.manifest#>>'{canonicalTarget,metadata,filePathReference}',
      original_sample_ids = ARRAY(
        SELECT construct.sample_original_path_id
        FROM public.sample_path_constructs construct
        WHERE construct.instrument_v2_id = target.id
        ORDER BY construct.sample_original_path_id
      ),
      published = false,
      updated_at = now()
  WHERE target.id = v_target.id;

  UPDATE public.sip_review_instrument target
  SET name = v_receipt.manifest#>>'{canonicalTarget,metadata,name}',
      engine_type =
        (v_receipt.manifest#>>'{canonicalTarget,metadata,engineType}')
          ::public.instrument_engine_type,
      playback_type =
        (v_receipt.manifest#>>'{canonicalTarget,metadata,playbackType}')
          ::public.instrument_playback_type,
      polyphony_type =
        (v_receipt.manifest#>>'{canonicalTarget,metadata,polyphonyType}')
          ::public.instrument_polyphony_type,
      instrument_family =
        v_receipt.manifest#>>'{canonicalTarget,metadata,instrumentFamily}',
      instrument_type =
        v_receipt.manifest#>>'{canonicalTarget,metadata,instrumentType}',
      range_lower =
        (v_receipt.manifest#>>'{canonicalTarget,metadata,rangeLower}')::integer,
      range_upper =
        (v_receipt.manifest#>>'{canonicalTarget,metadata,rangeUpper}')::integer,
      single_pitch = CASE
        WHEN v_receipt.manifest#>'{canonicalTarget,metadata,singlePitch}'
               = 'null'::jsonb
        THEN NULL
        ELSE (
          v_receipt.manifest#>>'{canonicalTarget,metadata,singlePitch}'
        )::integer
      END,
      updated_at = now()
  WHERE target.id = v_target_staging.id;

  INSERT INTO public.sip_review_instrument_sample_scope(
    sip_review_instrument_id,
    contributor_slug,
    file_path,
    original_sample_id
  )
  SELECT
    v_target_staging.id,
    p_contributor_slug,
    source_sample.sample->>'sourcePath',
    projection.sample_original_path_id
  FROM public.sip_sibling_consolidation_projection_v2 projection
  JOIN LATERAL (
    SELECT sample
    FROM jsonb_array_elements(v_receipt.manifest->'activeSamples') sample
    WHERE (sample->>'sourceConstructId')::uuid =
          projection.source_construct_id
  ) source_sample ON true
  WHERE projection.receipt_id = v_receipt.id
    AND projection.disposition = 'active'
  ON CONFLICT (sip_review_instrument_id, file_path) DO UPDATE SET
    contributor_slug = EXCLUDED.contributor_slug,
    original_sample_id = EXCLUDED.original_sample_id,
    updated_at = now();

  INSERT INTO public.sip_review_sample_override(
    sip_review_instrument_id,
    contributor_slug,
    file_path,
    collection,
    instrument_name,
    articulation,
    effect,
    mic_position,
    velocity,
    round_robin,
    midi_note,
    original_sample_id,
    pitch_content,
    filename,
    playback_type,
    run_id
  )
  SELECT
    v_target_staging.id,
    p_contributor_slug,
    source_sample.sample->>'sourcePath',
    projection.source_construct_snapshot->>'collection',
    v_receipt.manifest#>>'{canonicalTarget,metadata,name}',
    projection.source_construct_snapshot->>'articulation',
    projection.source_construct_snapshot->>'effect',
    projection.target_mic_position,
    projection.target_velocity::text,
    projection.target_round_robin::text,
    projection.target_midi_note,
    projection.sample_original_path_id,
    projection.target_pitch_content,
    projection.target_filename,
    projection.target_playback_type,
    'sibling-consolidation-v2:' || p_manifest_hash
  FROM public.sip_sibling_consolidation_projection_v2 projection
  JOIN LATERAL (
    SELECT sample
    FROM jsonb_array_elements(v_receipt.manifest->'activeSamples') sample
    WHERE (sample->>'sourceConstructId')::uuid =
          projection.source_construct_id
  ) source_sample ON true
  WHERE projection.receipt_id = v_receipt.id
    AND projection.disposition = 'active'
  ON CONFLICT (sip_review_instrument_id, original_sample_id) DO UPDATE SET
    contributor_slug = EXCLUDED.contributor_slug,
    file_path = EXCLUDED.file_path,
    collection = public.sip_review_sample_override.collection,
    instrument_name = EXCLUDED.instrument_name,
    articulation = public.sip_review_sample_override.articulation,
    effect = public.sip_review_sample_override.effect,
    mic_position = EXCLUDED.mic_position,
    velocity = EXCLUDED.velocity,
    round_robin = EXCLUDED.round_robin,
    midi_note = EXCLUDED.midi_note,
    pitch_content = EXCLUDED.pitch_content,
    filename = EXCLUDED.filename,
    playback_type = EXCLUDED.playback_type,
    run_id = EXCLUDED.run_id,
    updated_at = now();

  INSERT INTO public.sip_review_sample_playback_cues(
    sip_review_instrument_id,
    original_sample_id,
    file_path,
    sync_point_ms,
    loop_start_offset_ms,
    loop_end_offset_ms,
    sync_point_status,
    loop_start_status,
    loop_end_status,
    analysis_payload,
    analysis_run_id,
    analyzed_at
  )
  SELECT
    v_target_staging.id,
    projection.sample_original_path_id,
    cue.file_path,
    cue.sync_point_ms,
    cue.loop_start_offset_ms,
    cue.loop_end_offset_ms,
    cue.sync_point_status,
    cue.loop_start_status,
    cue.loop_end_status,
    cue.analysis_payload,
    cue.analysis_run_id,
    cue.analyzed_at
  FROM public.sip_sibling_consolidation_projection_v2 projection
  JOIN public.sip_review_sample_playback_cues cue
    ON cue.sip_review_instrument_id =
       projection.source_sip_review_instrument_id
   AND cue.original_sample_id = projection.sample_original_path_id
  WHERE projection.receipt_id = v_receipt.id
    AND projection.disposition = 'active'
  ON CONFLICT (sip_review_instrument_id, original_sample_id) DO UPDATE SET
    file_path = EXCLUDED.file_path,
    sync_point_ms = EXCLUDED.sync_point_ms,
    loop_start_offset_ms = EXCLUDED.loop_start_offset_ms,
    loop_end_offset_ms = EXCLUDED.loop_end_offset_ms,
    sync_point_status = EXCLUDED.sync_point_status,
    loop_start_status = EXCLUDED.loop_start_status,
    loop_end_status = EXCLUDED.loop_end_status,
    analysis_payload = EXCLUDED.analysis_payload,
    analysis_run_id = EXCLUDED.analysis_run_id,
    analyzed_at = EXCLUDED.analyzed_at,
    updated_at = now();

  INSERT INTO public.sip_review_sample_disposition(
    sip_review_instrument_id,
    contributor_slug,
    original_sample_id,
    disposition,
    reason,
    evidence,
    reviewed_by
  )
  SELECT
    v_target_staging.id,
    p_contributor_slug,
    projection.sample_original_path_id,
    'deferred_provenance',
    projection.defer_reason,
    jsonb_build_object(
      'manifestHash', p_manifest_hash,
      'sourceConstructId', projection.source_construct_id,
      'sourceInstrumentV2Id', projection.source_instrument_v2_id
    ),
    p_applied_by
  FROM public.sip_sibling_consolidation_projection_v2 projection
  WHERE projection.receipt_id = v_receipt.id
    AND projection.disposition = 'deferred'
  ON CONFLICT (sip_review_instrument_id, original_sample_id) DO UPDATE SET
    contributor_slug = EXCLUDED.contributor_slug,
    disposition = EXCLUDED.disposition,
    reason = EXCLUDED.reason,
    evidence = EXCLUDED.evidence,
    reviewed_by = EXCLUDED.reviewed_by,
    updated_at = now();

  SELECT COALESCE(
    array_agg(source.source_sip_instrument_id ORDER BY source.id),
    ARRAY[]::uuid[]
  )
  INTO v_source_sip_ids
  FROM public.sip_review_instrument source
  WHERE source.id = ANY(v_receipt.source_sip_review_instrument_ids);

  SELECT target.source_sip_instrument_id
  INTO v_target_source_sip_id
  FROM public.sip_review_instrument target
  WHERE target.id = v_target_staging.id;

  UPDATE public.instruments_v2 relation
  SET articulations = ARRAY(
        SELECT DISTINCT CASE
          WHEN member = ANY(v_receipt.source_instrument_v2_ids)
          THEN v_target.id
          ELSE member
        END
        FROM unnest(COALESCE(relation.articulations, ARRAY[]::uuid[])) member
        ORDER BY 1
      ),
      effects_instruments = ARRAY(
        SELECT DISTINCT CASE
          WHEN member = ANY(v_receipt.source_instrument_v2_ids)
          THEN v_target.id
          ELSE member
        END
        FROM unnest(
          COALESCE(relation.effects_instruments, ARRAY[]::uuid[])
        ) member
        ORDER BY 1
      ),
      legato_transition = CASE
        WHEN relation.legato_transition =
             ANY(v_receipt.source_instrument_v2_ids)
        THEN v_target.id
        ELSE relation.legato_transition
      END,
      updated_at = now()
  WHERE COALESCE(relation.articulations, ARRAY[]::uuid[])
          && v_receipt.source_instrument_v2_ids
     OR COALESCE(relation.effects_instruments, ARRAY[]::uuid[])
          && v_receipt.source_instrument_v2_ids
     OR relation.legato_transition =
          ANY(v_receipt.source_instrument_v2_ids);

  UPDATE public.sip_review_instrument relation
  SET articulations = ARRAY(
        SELECT DISTINCT CASE
          WHEN member = ANY(v_source_sip_ids)
          THEN v_target_source_sip_id
          ELSE member
        END
        FROM unnest(COALESCE(relation.articulations, ARRAY[]::uuid[])) member
        ORDER BY 1
      ),
      effects_instruments = ARRAY(
        SELECT DISTINCT CASE
          WHEN member = ANY(v_source_sip_ids)
          THEN v_target_source_sip_id
          ELSE member
        END
        FROM unnest(
          COALESCE(relation.effects_instruments, ARRAY[]::uuid[])
        ) member
        ORDER BY 1
      ),
      legato_transition = CASE
        WHEN relation.legato_transition =
             ANY(v_source_sip_ids)
        THEN v_target_source_sip_id
        ELSE relation.legato_transition
      END,
      updated_at = now()
  WHERE COALESCE(relation.articulations, ARRAY[]::uuid[]) && v_source_sip_ids
     OR COALESCE(relation.effects_instruments, ARRAY[]::uuid[])
          && v_source_sip_ids
     OR relation.legato_transition =
          ANY(v_source_sip_ids);

  UPDATE public.instrument_v2_legacy_map alias
  SET instrument_v2_id = v_target.id,
      sip_review_instrument_id = v_target_staging.id,
      contributor_slug = p_contributor_slug,
      updated_by = p_applied_by,
      updated_at = now()
  WHERE alias.instrument_v2_id =
        ANY(v_receipt.source_instrument_v2_ids);

  UPDATE public.sip_review_legacy_map alias
  SET sip_review_instrument_id = v_target_staging.id,
      contributor_slug = p_contributor_slug,
      updated_at = now()
  WHERE alias.sip_review_instrument_id =
        ANY(v_receipt.source_sip_review_instrument_ids);

  UPDATE public.instruments_v2 source
  SET published = false,
      updated_at = now()
  WHERE source.id = ANY(v_receipt.source_instrument_v2_ids);

  UPDATE public.sip_review_instrument source
  SET is_retired = true,
      retired_at = COALESCE(source.retired_at, now()),
      retired_reason =
        'sibling-consolidation-v2:' || p_manifest_hash,
      updated_at = now()
  WHERE source.id = ANY(v_receipt.source_sip_review_instrument_ids);

  PERFORM public.refresh_instrument_v2_axis_summaries_v1(ARRAY[v_target.id]);

  v_current_snapshot :=
    public.sip_sibling_consolidation_snapshot_v2(v_receipt.manifest);
  v_current_snapshot_hash := encode(
    extensions.digest(
      convert_to(v_current_snapshot::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  v_current_structural_hash := encode(
    extensions.digest(
      convert_to(
        public.sip_sibling_consolidation_structural_snapshot_v2(
          v_current_snapshot
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  UPDATE public.sip_sibling_consolidation_projection_v2 projection
  SET status = 'cutover',
      updated_at = now()
  WHERE projection.receipt_id = v_receipt.id;

  v_result := jsonb_build_object(
    'manifestHash', p_manifest_hash,
    'canonicalInstrumentV2Id', v_target.id,
    'projectionHash', v_projection_hash,
    'preparedSnapshotHash', v_receipt.prepared_snapshot_hash,
    'constructsTransferredInPlace', cardinality(v_active_construct_ids),
    'targetPublished', false,
    'samplesDeleted', 0,
    'constructsDeleted', 0,
    'publicObjectsDeleted', 0,
    'closeoutStatus', 'pending',
    'idempotent', false
  );

  UPDATE public.sip_sibling_consolidation_receipts_v2
  SET publish_run_id = NULL,
      post_prepare_snapshot = v_current_snapshot,
      post_prepare_snapshot_hash = v_current_snapshot_hash,
      post_prepare_structural_hash = v_current_structural_hash,
      status = 'cutover',
      readiness_proof = p_readiness_proof,
      cutover_result = v_result,
      cutover_by = p_applied_by,
      cutover_at = now(),
      closeout_status = 'pending',
      closeout_proof = NULL,
      closeout_completed_at = NULL
  WHERE id = v_receipt.id;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_coordinator_cutover_sibling_consolidation_v2"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_readiness_proof" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_heartbeat_v1"("p_run_id" "uuid", "p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_lease_seconds" integer DEFAULT 900) RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN EXISTS(
    SELECT 1 FROM public.sip_fleet_run_items WHERE id=p_item_id AND run_id=p_run_id
  ) THEN public.heartbeat_sip_fleet_run_item(
    p_item_id,p_executor_id,p_lease_token,p_lease_seconds
  ) ELSE false END
$$;


ALTER FUNCTION "public"."sip_publish_coordinator_heartbeat_v1"("p_run_id" "uuid", "p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_heartbeat_v1"("p_run_id" "uuid", "p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_lease_seconds" integer DEFAULT 900, "p_progress" "jsonb" DEFAULT NULL::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_accepted boolean := false;
BEGIN
  IF p_lease_seconds < 1 OR p_lease_seconds > 3600 THEN
    RAISE EXCEPTION 'invalid_lease_seconds';
  END IF;

  UPDATE public.sip_fleet_run_items item
  SET
    heartbeat_at = now(),
    lease_expires_at = now() + make_interval(secs => p_lease_seconds),
    progress_payload = CASE
      WHEN p_progress IS NULL OR p_progress = item.progress_payload THEN item.progress_payload
      ELSE p_progress
    END,
    last_progress_at = CASE
      WHEN p_progress IS NULL OR p_progress = item.progress_payload THEN item.last_progress_at
      ELSE now()
    END
  WHERE item.id = p_item_id
    AND item.run_id = p_run_id
    AND item.status = 'running'
    AND item.executor_id = p_executor_id
    AND item.lease_token = p_lease_token
    AND item.lease_expires_at > now()
  RETURNING true INTO v_accepted;

  RETURN coalesce(v_accepted, false);
END;
$$;


ALTER FUNCTION "public"."sip_publish_coordinator_heartbeat_v1"("p_run_id" "uuid", "p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_lease_seconds" integer, "p_progress" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_prepare_sibling_consolidation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_manifest_canonical_json" "text", "p_expected_snapshot" "jsonb", "p_expected_snapshot_hash" "text", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_target public.instruments_v2%ROWTYPE;
  v_target_staging public.sip_review_instrument%ROWTYPE;
  v_receipt public.sip_sibling_consolidation_receipts%ROWTYPE;
  v_source_v2_ids uuid[];
  v_source_staging_ids uuid[];
  v_expected_source_construct_ids uuid[];
  v_partition_construct_ids uuid[];
  v_actual_source_construct_ids uuid[];
  v_target_expected_construct_ids uuid[];
  v_target_actual_construct_ids uuid[];
  v_source jsonb;
  v_active jsonb;
  v_deferred jsonb;
  v_current_snapshot jsonb;
  v_current_snapshot_hash text;
  v_post_snapshot jsonb;
  v_post_snapshot_hash text;
  v_inserted_constructs integer := 0;
  v_result jsonb;
BEGIN
  IF NULLIF(btrim(p_contributor_slug), '') IS NULL
     OR NULLIF(btrim(p_applied_by), '') IS NULL
     OR p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR p_expected_snapshot_hash !~ '^[0-9a-f]{64}$'
     OR p_manifest->>'providerSlug' IS DISTINCT FROM p_contributor_slug
     OR p_manifest->>'schemaVersion' IS DISTINCT FROM '1'
     OR jsonb_typeof(p_manifest->'canonicalTarget') IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_manifest#>'{canonicalTarget,metadata}') IS DISTINCT FROM 'object'
     OR NULLIF(btrim(p_manifest#>>'{canonicalTarget,metadata,name}'), '') IS NULL
     OR p_manifest#>>'{canonicalTarget,metadata,engineType}' NOT IN ('tonal', 'non_tonal')
     OR p_manifest#>>'{canonicalTarget,metadata,playbackType}' NOT IN ('oneShot', 'looped', 'legato_transition')
     OR p_manifest#>>'{canonicalTarget,metadata,polyphonyType}' NOT IN ('Single', 'Melodic', 'Harmonic')
     OR NULLIF(btrim(p_manifest#>>'{canonicalTarget,metadata,instrumentFamily}'), '') IS NULL
     OR NULLIF(btrim(p_manifest#>>'{canonicalTarget,metadata,instrumentType}'), '') IS NULL
     OR NULLIF(btrim(p_manifest#>>'{canonicalTarget,metadata,filePathReference}'), '') IS NULL
     OR jsonb_typeof(p_manifest->'sourceInstruments') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest->'sourceInstruments') NOT BETWEEN 1 AND 250
     OR jsonb_typeof(p_manifest->'activeSamples') IS DISTINCT FROM 'array'
     OR jsonb_typeof(p_manifest->'deferredSamples') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest->'activeSamples') < 1
     OR jsonb_array_length(p_manifest->'activeSamples')
        + jsonb_array_length(p_manifest->'deferredSamples') > 2000 THEN
    RAISE EXCEPTION 'invalid sibling consolidation manifest identity or bounds'
      USING ERRCODE = '22023';
  END IF;
  IF p_manifest_canonical_json::jsonb IS DISTINCT FROM p_manifest
     OR encode(extensions.digest(convert_to(p_manifest_canonical_json, 'UTF8'), 'sha256'), 'hex')
        IS DISTINCT FROM p_manifest_hash THEN
    RAISE EXCEPTION 'sibling consolidation manifest hash mismatch'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug), 0));
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
    FOR UPDATE
  ) THEN
    RAISE EXCEPTION 'sibling consolidation requires an active provider lease'
      USING ERRCODE = '42501';
  END IF;
  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_disposition IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_upload_status IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE MODE;
  LOCK TABLE public.sip_sibling_consolidation_receipts IN SHARE ROW EXCLUSIVE MODE;

  SELECT * INTO v_receipt
  FROM public.sip_sibling_consolidation_receipts
  WHERE provider_slug = p_contributor_slug AND manifest_hash = p_manifest_hash
  FOR UPDATE;
  IF v_receipt.id IS NOT NULL THEN
    IF v_receipt.manifest IS DISTINCT FROM p_manifest
       OR v_receipt.manifest_canonical_json IS DISTINCT FROM p_manifest_canonical_json
       OR v_receipt.prepared_snapshot IS DISTINCT FROM p_expected_snapshot
       OR v_receipt.prepared_snapshot_hash IS DISTINCT FROM p_expected_snapshot_hash THEN
      RAISE EXCEPTION 'sibling consolidation prepare replay mismatch'
        USING ERRCODE = '22023';
    END IF;
    RETURN v_receipt.prepare_result || jsonb_build_object(
      'idempotent', true,
      'status', v_receipt.status
    );
  END IF;

  SELECT COALESCE(array_agg((source->>'instrumentV2Id')::uuid ORDER BY source->>'instrumentV2Id'), ARRAY[]::uuid[]),
         COALESCE(array_agg((source->>'stagingInstrumentId')::uuid ORDER BY source->>'stagingInstrumentId'), ARRAY[]::uuid[])
  INTO v_source_v2_ids, v_source_staging_ids
  FROM jsonb_array_elements(p_manifest->'sourceInstruments') source;

  IF cardinality(v_source_v2_ids) IS DISTINCT FROM (
       SELECT count(DISTINCT source->>'instrumentV2Id')
       FROM jsonb_array_elements(p_manifest->'sourceInstruments') source
     )
     OR cardinality(v_source_staging_ids) IS DISTINCT FROM (
       SELECT count(DISTINCT source->>'stagingInstrumentId')
       FROM jsonb_array_elements(p_manifest->'sourceInstruments') source
     )
     OR (p_manifest#>>'{canonicalTarget,instrumentV2Id}')::uuid = ANY(v_source_v2_ids)
     OR (p_manifest#>>'{canonicalTarget,stagingInstrumentId}')::uuid = ANY(v_source_staging_ids) THEN
    RAISE EXCEPTION 'sibling consolidation source identities must be unique and exclude target'
      USING ERRCODE = '22023';
  END IF;

  SELECT i.* INTO v_target
  FROM public.instruments_v2 i
  JOIN public.contributors contributor ON contributor.id = i.contributor_id
  WHERE i.id = (p_manifest#>>'{canonicalTarget,instrumentV2Id}')::uuid
    AND contributor.slug = p_contributor_slug
  FOR UPDATE OF i;
  SELECT staging.* INTO v_target_staging
  FROM public.sip_review_instrument staging
  WHERE staging.id = (p_manifest#>>'{canonicalTarget,stagingInstrumentId}')::uuid
    AND staging.source_contributor_slug = p_contributor_slug
  FOR UPDATE;
  IF v_target.id IS NULL OR NOT v_target.published
     OR v_target_staging.id IS NULL OR v_target_staging.is_retired
     OR NOT EXISTS (
       SELECT 1 FROM public.sip_review_promotion_map promotion
       WHERE promotion.instrument_v2_id = v_target.id
         AND promotion.sip_review_instrument_id = v_target_staging.id
     ) THEN
    RAISE EXCEPTION 'sibling consolidation canonical target identity changed'
      USING ERRCODE = '55000';
  END IF;

  IF (SELECT count(*)
      FROM public.instruments_v2 source
      JOIN public.contributors contributor ON contributor.id = source.contributor_id
      JOIN public.sip_review_promotion_map promotion ON promotion.instrument_v2_id = source.id
      JOIN public.sip_review_instrument staging ON staging.id = promotion.sip_review_instrument_id
      WHERE source.id = ANY(v_source_v2_ids)
        AND staging.id = ANY(v_source_staging_ids)
        AND contributor.slug = p_contributor_slug
        AND staging.source_contributor_slug = p_contributor_slug
        AND source.published
        AND NOT staging.is_retired) IS DISTINCT FROM cardinality(v_source_v2_ids) THEN
    RAISE EXCEPTION 'sibling consolidation source identity or publication state changed'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.instruments_v2 source
    WHERE source.id = ANY(v_source_v2_ids)
      AND (
        cardinality(COALESCE(source.articulations, ARRAY[]::uuid[])) > 0
        OR cardinality(COALESCE(source.effects_instruments, ARRAY[]::uuid[])) > 0
        OR source.legato_transition IS NOT NULL
      )
  ) OR EXISTS (
    SELECT 1
    FROM public.sip_review_instrument source
    WHERE source.id = ANY(v_source_staging_ids)
      AND (
        cardinality(COALESCE(source.articulations, ARRAY[]::uuid[])) > 0
        OR cardinality(COALESCE(source.effects_instruments, ARRAY[]::uuid[])) > 0
        OR source.legato_transition IS NOT NULL
      )
  ) THEN
    RAISE EXCEPTION 'sibling consolidation cannot retire a relationship-owning source'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(array_agg((id#>>'{}')::uuid ORDER BY id#>>'{}'), ARRAY[]::uuid[])
  INTO v_target_expected_construct_ids
  FROM jsonb_array_elements(p_manifest#>'{canonicalTarget,expectedConstructIds}') id;
  SELECT COALESCE(array_agg(c.id ORDER BY c.id), ARRAY[]::uuid[])
  INTO v_target_actual_construct_ids
  FROM public.sample_path_constructs c
  WHERE c.instrument_v2_id = v_target.id;
  IF v_target_expected_construct_ids IS DISTINCT FROM v_target_actual_construct_ids THEN
    RAISE EXCEPTION 'sibling consolidation canonical target construct snapshot changed'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(array_agg((id#>>'{}')::uuid ORDER BY id#>>'{}'), ARRAY[]::uuid[])
  INTO v_expected_source_construct_ids
  FROM jsonb_array_elements(p_manifest->'sourceInstruments') source,
       jsonb_array_elements(source->'expectedConstructIds') id;
  SELECT COALESCE(array_agg(c.id ORDER BY c.id), ARRAY[]::uuid[])
  INTO v_actual_source_construct_ids
  FROM public.sample_path_constructs c
  WHERE c.instrument_v2_id = ANY(v_source_v2_ids);
  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::uuid[])
  INTO v_partition_construct_ids
  FROM (
    SELECT (sample->>'sourceConstructId')::uuid id
    FROM jsonb_array_elements(p_manifest->'activeSamples') sample
    UNION ALL
    SELECT (sample->>'sourceConstructId')::uuid id
    FROM jsonb_array_elements(p_manifest->'deferredSamples') sample
  ) partitioned;
  IF v_expected_source_construct_ids IS DISTINCT FROM v_actual_source_construct_ids
     OR v_partition_construct_ids IS DISTINCT FROM v_actual_source_construct_ids
     OR cardinality(v_partition_construct_ids) IS DISTINCT FROM (
       SELECT count(DISTINCT id)
       FROM (
         SELECT sample->>'sourceConstructId' id
         FROM jsonb_array_elements(p_manifest->'activeSamples') sample
         UNION ALL
         SELECT sample->>'sourceConstructId' id
         FROM jsonb_array_elements(p_manifest->'deferredSamples') sample
       ) identities
     ) THEN
    RAISE EXCEPTION 'sibling consolidation samples are not the exact source construct partition'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'activeSamples') sample
    LEFT JOIN public.sample_path_constructs construct
      ON construct.id = (sample->>'sourceConstructId')::uuid
     AND construct.instrument_v2_id = (sample->>'sourceInstrumentV2Id')::uuid
     AND construct.sample_original_path_id = (sample->>'sampleOriginalPathId')::uuid
    LEFT JOIN public.samples_original_paths original
      ON original.id = construct.sample_original_path_id
    WHERE construct.id IS NULL
       OR construct.instrument_v2_id <> ALL(v_source_v2_ids)
       OR COALESCE(original.s3_path, original.file_name) IS DISTINCT FROM sample->>'sourcePath'
       OR COALESCE(sample->>'targetConstructId', '') !~ '^[0-9a-f-]{36}$'
       OR sample#>>'{canonical,midiNote}' IS NULL
       OR sample#>>'{canonical,filename}' IS NULL
       OR sample#>>'{canonical,pitchContent}' IS NULL
       OR sample#>>'{canonical,playbackType}' NOT IN ('oneShot', 'looped', 'legato_transition')
       OR NOT CASE WHEN jsonb_typeof(sample#>'{canonical,velocity}') = 'number'
         THEN (sample#>>'{canonical,velocity}')::numeric >= 0
          AND mod((sample#>>'{canonical,velocity}')::numeric, 1) = 0 ELSE false END
       OR NOT CASE WHEN jsonb_typeof(sample#>'{canonical,roundRobin}') = 'number'
         THEN (sample#>>'{canonical,roundRobin}')::numeric >= 0
          AND mod((sample#>>'{canonical,roundRobin}')::numeric, 1) = 0 ELSE false END
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'deferredSamples') sample
    LEFT JOIN public.sample_path_constructs construct
      ON construct.id = (sample->>'sourceConstructId')::uuid
     AND construct.instrument_v2_id = (sample->>'sourceInstrumentV2Id')::uuid
     AND construct.sample_original_path_id = (sample->>'sampleOriginalPathId')::uuid
    LEFT JOIN public.samples_original_paths original
      ON original.id = construct.sample_original_path_id
    WHERE construct.id IS NULL
       OR construct.instrument_v2_id <> ALL(v_source_v2_ids)
       OR COALESCE(original.s3_path, original.file_name) IS DISTINCT FROM sample->>'sourcePath'
       OR NULLIF(btrim(sample->>'reason'), '') IS NULL
  ) OR (
    SELECT count(DISTINCT sample->>'targetConstructId')
    FROM jsonb_array_elements(p_manifest->'activeSamples') sample
  ) IS DISTINCT FROM jsonb_array_length(p_manifest->'activeSamples') THEN
    RAISE EXCEPTION 'sibling consolidation sample identity or canonical projection is invalid'
      USING ERRCODE = '22023';
  END IF;

  v_current_snapshot := public.sip_sibling_consolidation_snapshot_v1(p_manifest);
  v_current_snapshot_hash := encode(
    extensions.digest(convert_to(v_current_snapshot::text, 'UTF8'), 'sha256'),
    'hex'
  );
  IF v_current_snapshot IS DISTINCT FROM p_expected_snapshot
     OR v_current_snapshot_hash IS DISTINCT FROM p_expected_snapshot_hash THEN
    RAISE EXCEPTION 'sibling consolidation expected snapshot changed before prepare'
      USING ERRCODE = '40001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'activeSamples') sample
    JOIN public.sample_path_constructs existing
      ON existing.id = (sample->>'targetConstructId')::uuid
  ) THEN
    RAISE EXCEPTION 'sibling consolidation target construct identity already exists'
      USING ERRCODE = '55000';
  END IF;

  PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);

  UPDATE public.instruments_v2 target
  SET name = p_manifest#>>'{canonicalTarget,metadata,name}',
      engine_type = (p_manifest#>>'{canonicalTarget,metadata,engineType}')::public.instrument_engine_type,
      playback_type = (p_manifest#>>'{canonicalTarget,metadata,playbackType}')::public.instrument_playback_type,
      polyphony_type = (p_manifest#>>'{canonicalTarget,metadata,polyphonyType}')::public.instrument_polyphony_type,
      instrument_family = p_manifest#>>'{canonicalTarget,metadata,instrumentFamily}',
      instrument_type = p_manifest#>>'{canonicalTarget,metadata,instrumentType}',
      range_lower = (p_manifest#>>'{canonicalTarget,metadata,rangeLower}')::integer,
      range_upper = (p_manifest#>>'{canonicalTarget,metadata,rangeUpper}')::integer,
      single_pitch = CASE
        WHEN p_manifest#>'{canonicalTarget,metadata,singlePitch}' = 'null'::jsonb
        THEN NULL
        ELSE (p_manifest#>>'{canonicalTarget,metadata,singlePitch}')::integer
      END,
      file_path_reference = p_manifest#>>'{canonicalTarget,metadata,filePathReference}',
      updated_at = now()
  WHERE target.id = v_target.id;

  UPDATE public.sip_review_instrument staging
  SET name = p_manifest#>>'{canonicalTarget,metadata,name}',
      engine_type = (p_manifest#>>'{canonicalTarget,metadata,engineType}')::public.instrument_engine_type,
      playback_type = (p_manifest#>>'{canonicalTarget,metadata,playbackType}')::public.instrument_playback_type,
      polyphony_type = (p_manifest#>>'{canonicalTarget,metadata,polyphonyType}')::public.instrument_polyphony_type,
      instrument_family = p_manifest#>>'{canonicalTarget,metadata,instrumentFamily}',
      instrument_type = p_manifest#>>'{canonicalTarget,metadata,instrumentType}',
      range_lower = (p_manifest#>>'{canonicalTarget,metadata,rangeLower}')::integer,
      range_upper = (p_manifest#>>'{canonicalTarget,metadata,rangeUpper}')::integer,
      single_pitch = CASE
        WHEN p_manifest#>'{canonicalTarget,metadata,singlePitch}' = 'null'::jsonb
        THEN NULL
        ELSE (p_manifest#>>'{canonicalTarget,metadata,singlePitch}')::integer
      END,
      updated_at = now()
  WHERE staging.id = v_target_staging.id;

  SELECT * INTO v_target
  FROM public.instruments_v2
  WHERE id = v_target.id;
  SELECT * INTO v_target_staging
  FROM public.sip_review_instrument
  WHERE id = v_target_staging.id;

  FOR v_active IN SELECT value FROM jsonb_array_elements(p_manifest->'activeSamples') LOOP
    INSERT INTO public.sample_path_constructs(
      id, sample_original_path_id, collection, instrument_name, articulation,
      effect, mic_position, velocity, round_robin, midi_note, instrument_v2_id,
      contributor_id, pitch_content, filename, playback_type
    ) VALUES (
      (v_active->>'targetConstructId')::uuid,
      (v_active->>'sampleOriginalPathId')::uuid,
      NULLIF(v_active#>>'{canonical,collection}', ''),
      v_target.name,
      NULLIF(v_active#>>'{canonical,articulation}', ''),
      NULLIF(v_active#>>'{canonical,effect}', ''),
      COALESCE(NULLIF(v_active#>>'{canonical,micPosition}', ''), 'main'),
      (v_active#>>'{canonical,velocity}')::integer,
      (v_active#>>'{canonical,roundRobin}')::integer,
      v_active#>>'{canonical,midiNote}',
      v_target.id,
      v_target.contributor_id,
      v_active#>>'{canonical,pitchContent}',
      v_active#>>'{canonical,filename}',
      (v_active#>>'{canonical,playbackType}')::public.instrument_playback_type
    );
    v_inserted_constructs := v_inserted_constructs + 1;

    INSERT INTO public.sip_review_instrument_sample_scope(
      sip_review_instrument_id, contributor_slug, file_path, original_sample_id
    ) VALUES (
      v_target_staging.id, p_contributor_slug, v_active->>'sourcePath',
      (v_active->>'sampleOriginalPathId')::uuid
    )
    ON CONFLICT (sip_review_instrument_id, file_path) DO UPDATE SET
      contributor_slug = EXCLUDED.contributor_slug,
      original_sample_id = EXCLUDED.original_sample_id,
      updated_at = now();

    INSERT INTO public.sip_review_sample_override(
      sip_review_instrument_id, contributor_slug, file_path, collection,
      instrument_name, articulation, effect, mic_position, velocity,
      round_robin, midi_note, original_sample_id, pitch_content, filename,
      playback_type, run_id
    ) VALUES (
      v_target_staging.id, p_contributor_slug, v_active->>'sourcePath',
      NULLIF(v_active#>>'{canonical,collection}', ''), v_target.name,
      NULLIF(v_active#>>'{canonical,articulation}', ''),
      NULLIF(v_active#>>'{canonical,effect}', ''),
      COALESCE(NULLIF(v_active#>>'{canonical,micPosition}', ''), 'main'),
      v_active#>>'{canonical,velocity}', v_active#>>'{canonical,roundRobin}',
      v_active#>>'{canonical,midiNote}', (v_active->>'sampleOriginalPathId')::uuid,
      v_active#>>'{canonical,pitchContent}', v_active#>>'{canonical,filename}',
      (v_active#>>'{canonical,playbackType}')::public.instrument_playback_type,
      'sibling-consolidation:' || p_manifest_hash
    )
    ON CONFLICT (sip_review_instrument_id, original_sample_id) DO UPDATE SET
      contributor_slug = EXCLUDED.contributor_slug,
      file_path = EXCLUDED.file_path,
      collection = EXCLUDED.collection,
      instrument_name = EXCLUDED.instrument_name,
      articulation = EXCLUDED.articulation,
      effect = EXCLUDED.effect,
      mic_position = EXCLUDED.mic_position,
      velocity = EXCLUDED.velocity,
      round_robin = EXCLUDED.round_robin,
      midi_note = EXCLUDED.midi_note,
      pitch_content = EXCLUDED.pitch_content,
      filename = EXCLUDED.filename,
      playback_type = EXCLUDED.playback_type,
      run_id = EXCLUDED.run_id,
      updated_at = now();

    DELETE FROM public.sip_review_sample_disposition disposition
    WHERE disposition.sip_review_instrument_id = v_target_staging.id
      AND disposition.original_sample_id = (v_active->>'sampleOriginalPathId')::uuid;
  END LOOP;

  FOR v_deferred IN SELECT value FROM jsonb_array_elements(p_manifest->'deferredSamples') LOOP
    INSERT INTO public.sip_review_sample_disposition(
      sip_review_instrument_id, contributor_slug, original_sample_id,
      disposition, reason, evidence, reviewed_by
    ) VALUES (
      v_target_staging.id, p_contributor_slug,
      (v_deferred->>'sampleOriginalPathId')::uuid,
      'deferred_provenance', v_deferred->>'reason',
      jsonb_build_object(
        'manifest_hash', p_manifest_hash,
        'source_construct_id', v_deferred->>'sourceConstructId',
        'source_instrument_v2_id', v_deferred->>'sourceInstrumentV2Id',
        'source_path', v_deferred->>'sourcePath'
      ),
      p_applied_by
    )
    ON CONFLICT (sip_review_instrument_id, original_sample_id) DO UPDATE SET
      contributor_slug = EXCLUDED.contributor_slug,
      disposition = EXCLUDED.disposition,
      reason = EXCLUDED.reason,
      evidence = EXCLUDED.evidence,
      reviewed_by = EXCLUDED.reviewed_by,
      updated_at = now();
  END LOOP;

  UPDATE public.instruments_v2 target
  SET original_sample_ids = ARRAY(
        SELECT construct.sample_original_path_id
        FROM public.sample_path_constructs construct
        WHERE construct.instrument_v2_id = target.id
        ORDER BY construct.sample_original_path_id
      ),
      updated_at = now()
  WHERE target.id = v_target.id;
  IF public.refresh_instrument_v2_axis_summaries_v1(ARRAY[v_target.id]) IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'sibling consolidation target axis summary refresh failed'
      USING ERRCODE = '55000';
  END IF;
  UPDATE public.sip_review_instrument staging
  SET original_sample_ids = target.original_sample_ids,
      pitch_contents = target.pitch_contents,
      velocity_layers = target.velocity_layers,
      round_robins = target.round_robins,
      mic_positions = target.mic_positions,
      updated_at = now()
  FROM public.instruments_v2 target
  WHERE staging.id = v_target_staging.id AND target.id = v_target.id;

  INSERT INTO public.instrument_v2_upload_status(
    instrument_v2_id, publish_actions_applied, publish_status,
    samples_processed, samples_total, needs, error_summary
  ) VALUES (
    v_target.id, false, 'pending', 0,
    (SELECT count(*) FROM public.sample_path_constructs WHERE instrument_v2_id = v_target.id),
    ARRAY['publish_actions'],
    jsonb_build_object('sibling_consolidation_manifest_hash', p_manifest_hash)
  )
  ON CONFLICT (instrument_v2_id) DO UPDATE SET
    publish_actions_applied = false,
    publish_status = 'pending',
    samples_processed = 0,
    samples_total = EXCLUDED.samples_total,
    needs = EXCLUDED.needs,
    error_summary = EXCLUDED.error_summary,
    published_at = NULL,
    runtime_verification_status = 'pending',
    runtime_verification_started_at = NULL,
    runtime_verification_completed_at = NULL,
    runtime_verification_error_summary = NULL,
    runtime_verification_report_path = NULL,
    updated_at = now();

  v_post_snapshot := public.sip_sibling_consolidation_snapshot_v1(p_manifest);
  v_post_snapshot_hash := encode(
    extensions.digest(convert_to(v_post_snapshot::text, 'UTF8'), 'sha256'),
    'hex'
  );
  v_result := jsonb_build_object(
    'manifestHash', p_manifest_hash,
    'canonicalInstrumentV2Id', v_target.id,
    'sourceInstrumentV2Ids', to_jsonb(v_source_v2_ids),
    'activeConstructsCreated', v_inserted_constructs,
    'deferredSamplesRecorded', jsonb_array_length(p_manifest->'deferredSamples'),
    'sourcesRemainPublished', true,
    'requiresTargetRepublish', true,
    'idempotent', false
  );

  INSERT INTO public.sip_sibling_consolidation_receipts(
    provider_slug, manifest_hash, manifest, manifest_canonical_json,
    prepared_snapshot, prepared_snapshot_hash, post_prepare_snapshot,
    post_prepare_snapshot_hash, canonical_instrument_v2_id,
    canonical_sip_review_instrument_id, source_instrument_v2_ids,
    source_sip_review_instrument_ids, status, prepare_result, prepared_by
  ) VALUES (
    p_contributor_slug, p_manifest_hash, p_manifest, p_manifest_canonical_json,
    p_expected_snapshot, p_expected_snapshot_hash, v_post_snapshot,
    v_post_snapshot_hash, v_target.id, v_target_staging.id, v_source_v2_ids,
    v_source_staging_ids, 'prepared', v_result, p_applied_by
  );
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_coordinator_prepare_sibling_consolidation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_manifest_canonical_json" "text", "p_expected_snapshot" "jsonb", "p_expected_snapshot_hash" "text", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_prepare_sibling_consolidation_v2"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_manifest_canonical_json" "text", "p_expected_snapshot" "jsonb", "p_expected_snapshot_hash" "text", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '120s'
    AS $_$
DECLARE
  v_target public.instruments_v2%ROWTYPE;
  v_target_staging public.sip_review_instrument%ROWTYPE;
  v_receipt public.sip_sibling_consolidation_receipts_v2%ROWTYPE;
  v_source_v2_ids uuid[];
  v_source_staging_ids uuid[];
  v_expected_construct_ids uuid[];
  v_actual_construct_ids uuid[];
  v_partition_construct_ids uuid[];
  v_ordered_candidate_ids uuid[];
  v_selected_indexes integer[];
  v_expected_selected_indexes integer[];
  v_selected_construct_ids uuid[];
  v_mapping_construct_ids uuid[];
  v_mapping_round_robins integer[];
  v_current_snapshot jsonb;
  v_current_snapshot_hash text;
  v_current_structural_hash text;
  v_projection_hash text;
  v_total integer;
  v_cap integer;
  v_selected integer;
  v_result jsonb;
  v_reprepare boolean := false;
BEGIN
  IF NULLIF(btrim(p_contributor_slug), '') IS NULL
     OR NULLIF(btrim(p_applied_by), '') IS NULL
     OR p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR p_expected_snapshot_hash !~ '^[0-9a-f]{64}$'
     OR p_manifest->>'providerSlug' IS DISTINCT FROM p_contributor_slug
     OR p_manifest->>'schemaVersion' IS DISTINCT FROM '2'
     OR jsonb_typeof(p_manifest->'canonicalTarget') IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_manifest#>'{canonicalTarget,metadata}')
          IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_manifest->'sourceInstruments')
          IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest->'sourceInstruments')
          NOT BETWEEN 1 AND 250
     OR jsonb_typeof(p_manifest->'activeSamples') IS DISTINCT FROM 'array'
     OR jsonb_typeof(p_manifest->'deferredSamples') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest->'activeSamples') < 1
     OR p_manifest#>>'{selectionProof,algorithmVersion}'
          IS DISTINCT FROM 'stable_stratified_indexes_v1'
     OR jsonb_typeof(
          p_manifest#>'{selectionProof,orderedCandidateConstructIds}'
        ) IS DISTINCT FROM 'array'
     OR jsonb_typeof(p_manifest#>'{selectionProof,selectedIndexes}')
          IS DISTINCT FROM 'array'
     OR jsonb_typeof(p_manifest#>'{selectionProof,finalRoundRobinMapping}')
          IS DISTINCT FROM 'array'
     OR NOT (
       CASE
         WHEN jsonb_typeof(p_manifest#>'{selectionProof,activeCap}') = 'number'
         THEN (p_manifest#>>'{selectionProof,activeCap}')::integer IN (8, 16)
         ELSE false
       END
     ) THEN
    RAISE EXCEPTION 'invalid sibling consolidation v2 projected manifest'
      USING ERRCODE = '22023';
  END IF;

  IF p_manifest_canonical_json::jsonb IS DISTINCT FROM p_manifest
     OR encode(
       extensions.digest(
         convert_to(p_manifest_canonical_json, 'UTF8'),
         'sha256'
       ),
       'hex'
     ) IS DISTINCT FROM p_manifest_hash THEN
    RAISE EXCEPTION 'sibling consolidation v2 manifest hash mismatch'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
    FOR UPDATE
  ) THEN
    RAISE EXCEPTION 'sibling consolidation v2 requires an active provider lease'
      USING ERRCODE = '42501';
  END IF;

  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_disposition IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_playback_cues IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_playback_cues IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_generated_derivations IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_publish_output_manifest IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_s3_path IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_upload_status IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE MODE;
  LOCK TABLE public.sip_review_legacy_map IN SHARE MODE;
  LOCK TABLE public.sip_fleet_runs IN SHARE MODE;
  LOCK TABLE public.sip_fleet_run_items IN SHARE MODE;
  LOCK TABLE public.sip_sibling_consolidation_receipts_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_sibling_consolidation_projection_v2 IN SHARE ROW EXCLUSIVE MODE;

  SELECT
    COALESCE(
      array_agg(
        (source->>'instrumentV2Id')::uuid
        ORDER BY source->>'instrumentV2Id'
      ),
      ARRAY[]::uuid[]
    ),
    COALESCE(
      array_agg(
        (source->>'stagingInstrumentId')::uuid
        ORDER BY source->>'stagingInstrumentId'
      ),
      ARRAY[]::uuid[]
    )
  INTO v_source_v2_ids, v_source_staging_ids
  FROM jsonb_array_elements(p_manifest->'sourceInstruments') source;

  IF cardinality(v_source_v2_ids) IS DISTINCT FROM (
       SELECT count(DISTINCT source->>'instrumentV2Id')
       FROM jsonb_array_elements(p_manifest->'sourceInstruments') source
     )
     OR cardinality(v_source_staging_ids) IS DISTINCT FROM (
       SELECT count(DISTINCT source->>'stagingInstrumentId')
       FROM jsonb_array_elements(p_manifest->'sourceInstruments') source
     )
     OR (p_manifest#>>'{canonicalTarget,instrumentV2Id}')::uuid
          = ANY(v_source_v2_ids)
     OR (p_manifest#>>'{canonicalTarget,stagingInstrumentId}')::uuid
          = ANY(v_source_staging_ids) THEN
    RAISE EXCEPTION 'sibling consolidation v2 source identities are invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT instrument.* INTO v_target
  FROM public.instruments_v2 instrument
  JOIN public.contributors contributor
    ON contributor.id = instrument.contributor_id
  WHERE instrument.id =
        (p_manifest#>>'{canonicalTarget,instrumentV2Id}')::uuid
    AND contributor.slug = p_contributor_slug
  FOR UPDATE OF instrument;

  SELECT review.* INTO v_target_staging
  FROM public.sip_review_instrument review
  WHERE review.id =
        (p_manifest#>>'{canonicalTarget,stagingInstrumentId}')::uuid
    AND review.source_contributor_slug = p_contributor_slug
  FOR UPDATE;

  IF v_target.id IS NULL
     OR NOT v_target.published
     OR v_target_staging.id IS NULL
     OR v_target_staging.is_retired
     OR (
       SELECT count(*)
       FROM public.instruments_v2 source
       JOIN public.contributors contributor
         ON contributor.id = source.contributor_id
       JOIN public.sip_review_promotion_map promotion
         ON promotion.instrument_v2_id = source.id
       JOIN public.sip_review_instrument review
         ON review.id = promotion.sip_review_instrument_id
       WHERE source.id = ANY(v_source_v2_ids)
         AND review.id = ANY(v_source_staging_ids)
         AND contributor.slug = p_contributor_slug
         AND review.source_contributor_slug = p_contributor_slug
         AND source.published
         AND NOT review.is_retired
     ) IS DISTINCT FROM cardinality(v_source_v2_ids) THEN
    RAISE EXCEPTION 'sibling consolidation v2 instrument identity changed'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::uuid[])
  INTO v_expected_construct_ids
  FROM (
    SELECT (id#>>'{}')::uuid AS id
    FROM jsonb_array_elements(
      p_manifest#>'{canonicalTarget,expectedConstructIds}'
    ) id
    UNION ALL
    SELECT (id#>>'{}')::uuid AS id
    FROM jsonb_array_elements(p_manifest->'sourceInstruments') source,
         jsonb_array_elements(source->'expectedConstructIds') id
  ) expected;

  SELECT COALESCE(array_agg(construct.id ORDER BY construct.id), ARRAY[]::uuid[])
  INTO v_actual_construct_ids
  FROM public.sample_path_constructs construct
  WHERE construct.instrument_v2_id = v_target.id
     OR construct.instrument_v2_id = ANY(v_source_v2_ids);

  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::uuid[])
  INTO v_partition_construct_ids
  FROM (
    SELECT (sample->>'sourceConstructId')::uuid AS id
    FROM jsonb_array_elements(p_manifest->'activeSamples') sample
    UNION ALL
    SELECT (sample->>'sourceConstructId')::uuid AS id
    FROM jsonb_array_elements(p_manifest->'deferredSamples') sample
  ) partitioned;

  IF v_expected_construct_ids IS DISTINCT FROM v_actual_construct_ids
     OR v_partition_construct_ids IS DISTINCT FROM v_actual_construct_ids
     OR cardinality(v_partition_construct_ids) IS DISTINCT FROM (
       SELECT count(DISTINCT id)
       FROM (
         SELECT sample->>'sourceConstructId' AS id
         FROM jsonb_array_elements(p_manifest->'activeSamples') sample
         UNION ALL
         SELECT sample->>'sourceConstructId' AS id
         FROM jsonb_array_elements(p_manifest->'deferredSamples') sample
       ) partitioned
     ) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 requires exact source and target construct accounting'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM (
      SELECT value AS sample
      FROM jsonb_array_elements(p_manifest->'activeSamples')
      UNION ALL
      SELECT value AS sample
      FROM jsonb_array_elements(p_manifest->'deferredSamples')
    ) partitioned
    LEFT JOIN public.sample_path_constructs construct
      ON construct.id = (sample->>'sourceConstructId')::uuid
     AND construct.instrument_v2_id =
         (sample->>'sourceInstrumentV2Id')::uuid
     AND construct.sample_original_path_id =
         (sample->>'sampleOriginalPathId')::uuid
    LEFT JOIN public.samples_original_paths original
      ON original.id = construct.sample_original_path_id
    WHERE construct.id IS NULL
       OR construct.instrument_v2_id
            <> ALL(array_prepend(v_target.id, v_source_v2_ids))
       OR COALESCE(original.s3_path, original.file_name)
            IS DISTINCT FROM sample->>'sourcePath'
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'activeSamples') sample
    WHERE sample->>'targetConstructId'
            IS DISTINCT FROM sample->>'sourceConstructId'
       OR sample#>>'{canonical,midiNote}' IS NULL
       OR sample#>>'{canonical,filename}' IS NULL
       OR sample#>>'{canonical,pitchContent}' IS NULL
       OR sample#>>'{canonical,playbackType}'
            NOT IN ('oneShot', 'looped', 'legato_transition')
       OR NOT (
         CASE
           WHEN jsonb_typeof(sample#>'{canonical,velocity}') = 'number'
           THEN (sample#>>'{canonical,velocity}')::numeric >= 0
             AND mod((sample#>>'{canonical,velocity}')::numeric, 1) = 0
           ELSE false
         END
       )
       OR NOT (
         CASE
           WHEN jsonb_typeof(sample#>'{canonical,roundRobin}') = 'number'
           THEN (sample#>>'{canonical,roundRobin}')::numeric >= 0
             AND mod((sample#>>'{canonical,roundRobin}')::numeric, 1) = 0
           ELSE false
         END
       )
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'deferredSamples') sample
    WHERE NULLIF(btrim(sample->>'reason'), '') IS NULL
  ) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 requires stable construct identity projection'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(value::uuid ORDER BY ordinal), ARRAY[]::uuid[])
  INTO v_ordered_candidate_ids
  FROM jsonb_array_elements_text(
    p_manifest#>'{selectionProof,orderedCandidateConstructIds}'
  ) WITH ORDINALITY ordered(value, ordinal);

  SELECT COALESCE(array_agg(value::integer ORDER BY ordinal), ARRAY[]::integer[])
  INTO v_selected_indexes
  FROM jsonb_array_elements_text(
    p_manifest#>'{selectionProof,selectedIndexes}'
  ) WITH ORDINALITY selected(value, ordinal);

  SELECT
    COALESCE(
      array_agg(
        (mapping->>'constructId')::uuid
        ORDER BY (mapping->>'roundRobin')::integer
      ),
      ARRAY[]::uuid[]
    ),
    COALESCE(
      array_agg(
        (mapping->>'roundRobin')::integer
        ORDER BY (mapping->>'roundRobin')::integer
      ),
      ARRAY[]::integer[]
    )
  INTO v_mapping_construct_ids, v_mapping_round_robins
  FROM jsonb_array_elements(
    p_manifest#>'{selectionProof,finalRoundRobinMapping}'
  ) mapping;

  v_total := cardinality(v_ordered_candidate_ids);
  v_cap := (p_manifest#>>'{selectionProof,activeCap}')::integer;
  v_selected := LEAST(v_cap, v_total);

  SELECT COALESCE(
    array_agg(
      CASE
        WHEN v_total <= v_cap THEN generated_index
        WHEN v_selected = 1 THEN 0
        ELSE round(
          generated_index * (v_total - 1)::numeric / (v_selected - 1)
        )::integer
      END
      ORDER BY generated_index
    ),
    ARRAY[]::integer[]
  )
  INTO v_expected_selected_indexes
  FROM generate_series(0, v_selected - 1) generated_index;

  SELECT COALESCE(
    array_agg(v_ordered_candidate_ids[selected_index + 1] ORDER BY ordinal),
    ARRAY[]::uuid[]
  )
  INTO v_selected_construct_ids
  FROM unnest(v_selected_indexes)
    WITH ORDINALITY selected(selected_index, ordinal);

  IF v_total IS DISTINCT FROM cardinality(v_actual_construct_ids)
     OR ARRAY(SELECT unnest(v_ordered_candidate_ids) ORDER BY 1)
          IS DISTINCT FROM v_actual_construct_ids
     OR v_selected_indexes IS DISTINCT FROM v_expected_selected_indexes
     OR jsonb_array_length(p_manifest->'activeSamples')
          IS DISTINCT FROM v_selected
     OR v_mapping_construct_ids IS DISTINCT FROM v_selected_construct_ids
     OR v_mapping_round_robins IS DISTINCT FROM ARRAY(
       SELECT generate_series(0, v_selected - 1)
     )
     OR ARRAY(
       SELECT (sample->>'sourceConstructId')::uuid
       FROM jsonb_array_elements(p_manifest->'activeSamples') sample
       ORDER BY sample->>'sourceConstructId'
     ) IS DISTINCT FROM ARRAY(
       SELECT unnest(v_selected_construct_ids) ORDER BY 1
     ) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 globally stratified cap proof failed'
      USING ERRCODE = '22023';
  END IF;

  v_current_snapshot :=
    public.sip_sibling_consolidation_snapshot_v2(p_manifest);
  v_current_snapshot_hash := encode(
    extensions.digest(
      convert_to(v_current_snapshot::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  v_current_structural_hash := encode(
    extensions.digest(
      convert_to(
        public.sip_sibling_consolidation_structural_snapshot_v2(
          v_current_snapshot
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  IF v_current_snapshot_hash IS DISTINCT FROM p_expected_snapshot_hash
     OR (
       p_expected_snapshot IS NOT NULL
       AND p_expected_snapshot IS DISTINCT FROM v_current_snapshot
     ) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 expected snapshot changed before prepare'
      USING ERRCODE = '40001';
  END IF;

  SELECT * INTO v_receipt
  FROM public.sip_sibling_consolidation_receipts_v2 receipt
  WHERE receipt.provider_slug = p_contributor_slug
    AND receipt.manifest_hash = p_manifest_hash
  FOR UPDATE;

  IF v_receipt.id IS NOT NULL AND v_receipt.status <> 'rolled_back' THEN
    IF v_receipt.manifest IS DISTINCT FROM p_manifest
       OR v_receipt.manifest_canonical_json
            IS DISTINCT FROM p_manifest_canonical_json
       OR v_receipt.provider_lease_id IS DISTINCT FROM p_lease_id
       OR v_receipt.provider_lease_token IS DISTINCT FROM p_lease_token
       OR v_receipt.prepared_snapshot_hash
            IS DISTINCT FROM p_expected_snapshot_hash
       OR v_receipt.projection_hash IS DISTINCT FROM
          public.sip_sibling_consolidation_projection_hash_v2(v_receipt.id)
       OR v_current_structural_hash IS DISTINCT FROM
          encode(
            extensions.digest(
              convert_to(
                public.sip_sibling_consolidation_structural_snapshot_v2(
                  v_receipt.prepared_snapshot
                )::text,
                'UTF8'
              ),
              'sha256'
            ),
            'hex'
          ) THEN
      RAISE EXCEPTION
        'sibling consolidation v2 prepare replay mismatch or drift'
        USING ERRCODE = '40001';
    END IF;
    RETURN v_receipt.prepare_result || jsonb_build_object(
      'idempotent', true,
      'status', v_receipt.status
    );
  END IF;

  IF v_receipt.id IS NOT NULL THEN
    IF v_receipt.manifest IS DISTINCT FROM p_manifest
       OR v_receipt.manifest_canonical_json
            IS DISTINCT FROM p_manifest_canonical_json
       OR v_receipt.provider_lease_id IS DISTINCT FROM p_lease_id THEN
      RAISE EXCEPTION
        'sibling_consolidation_v2_reprepare_snapshot_or_lease_mismatch'
        USING ERRCODE = '40001';
    END IF;
    v_reprepare := true;
    DELETE FROM public.sip_sibling_consolidation_projection_v2 projection
    WHERE projection.receipt_id = v_receipt.id;
  ELSE
    INSERT INTO public.sip_sibling_consolidation_receipts_v2(
      provider_slug,
      provider_lease_id,
      provider_lease_token,
      manifest_hash,
      manifest,
      manifest_canonical_json,
      canonical_instrument_v2_id,
      canonical_sip_review_instrument_id,
      source_instrument_v2_ids,
      source_sip_review_instrument_ids,
      publish_run_id,
      prepared_snapshot,
      prepared_snapshot_hash,
      post_prepare_snapshot,
      post_prepare_snapshot_hash,
      post_prepare_structural_hash,
      status,
      prepare_result,
      prepared_by,
      projection_summary
    ) VALUES (
      p_contributor_slug,
      p_lease_id,
      p_lease_token,
      p_manifest_hash,
      p_manifest,
      p_manifest_canonical_json,
      v_target.id,
      v_target_staging.id,
      v_source_v2_ids,
      v_source_staging_ids,
      NULL,
      v_current_snapshot,
      v_current_snapshot_hash,
      v_current_snapshot,
      v_current_snapshot_hash,
      v_current_structural_hash,
      'prepared',
      '{}'::jsonb,
      p_applied_by,
      '{}'::jsonb
    )
    RETURNING * INTO v_receipt;
  END IF;

  INSERT INTO public.sip_sibling_consolidation_projection_v2(
    receipt_id,
    provider_slug,
    manifest_hash,
    target_instrument_v2_id,
    target_sip_review_instrument_id,
    source_instrument_v2_id,
    source_sip_review_instrument_id,
    source_construct_id,
    sample_original_path_id,
    disposition,
    defer_reason,
    target_pitch_content,
    target_midi_note,
    target_filename,
    target_velocity,
    target_round_robin,
    target_mic_position,
    target_playback_type,
    source_construct_snapshot
  )
  SELECT
    v_receipt.id,
    p_contributor_slug,
    p_manifest_hash,
    v_target.id,
    v_target_staging.id,
    (sample->>'sourceInstrumentV2Id')::uuid,
    (sample->>'stagingInstrumentId')::uuid,
    construct.id,
    construct.sample_original_path_id,
    'active',
    NULL,
    sample#>>'{canonical,pitchContent}',
    sample#>>'{canonical,midiNote}',
    sample#>>'{canonical,filename}',
    (sample#>>'{canonical,velocity}')::integer,
    (sample#>>'{canonical,roundRobin}')::integer,
    COALESCE(NULLIF(sample#>>'{canonical,micPosition}', ''), 'main'),
    (sample#>>'{canonical,playbackType}')::public.instrument_playback_type,
    to_jsonb(construct)
  FROM jsonb_array_elements(p_manifest->'activeSamples') sample
  JOIN public.sample_path_constructs construct
    ON construct.id = (sample->>'sourceConstructId')::uuid
   AND construct.instrument_v2_id =
       (sample->>'sourceInstrumentV2Id')::uuid
   AND construct.sample_original_path_id =
       (sample->>'sampleOriginalPathId')::uuid;

  INSERT INTO public.sip_sibling_consolidation_projection_v2(
    receipt_id,
    provider_slug,
    manifest_hash,
    target_instrument_v2_id,
    target_sip_review_instrument_id,
    source_instrument_v2_id,
    source_sip_review_instrument_id,
    source_construct_id,
    sample_original_path_id,
    disposition,
    defer_reason,
    source_construct_snapshot
  )
  SELECT
    v_receipt.id,
    p_contributor_slug,
    p_manifest_hash,
    v_target.id,
    v_target_staging.id,
    (sample->>'sourceInstrumentV2Id')::uuid,
    (sample->>'stagingInstrumentId')::uuid,
    construct.id,
    construct.sample_original_path_id,
    'deferred',
    sample->>'reason',
    to_jsonb(construct)
  FROM jsonb_array_elements(p_manifest->'deferredSamples') sample
  JOIN public.sample_path_constructs construct
    ON construct.id = (sample->>'sourceConstructId')::uuid
   AND construct.instrument_v2_id =
       (sample->>'sourceInstrumentV2Id')::uuid
   AND construct.sample_original_path_id =
       (sample->>'sampleOriginalPathId')::uuid;

  IF (
    SELECT count(*)
    FROM public.sip_sibling_consolidation_projection_v2 projection
    WHERE projection.receipt_id = v_receipt.id
  ) IS DISTINCT FROM cardinality(v_actual_construct_ids)
     OR (
       SELECT count(*)
       FROM public.sip_sibling_consolidation_projection_v2 projection
       WHERE projection.receipt_id = v_receipt.id
         AND projection.disposition = 'active'
     ) IS DISTINCT FROM v_selected THEN
    RAISE EXCEPTION
      'sibling consolidation v2 projected construct partition is incomplete'
      USING ERRCODE = '40001';
  END IF;

  v_projection_hash :=
    public.sip_sibling_consolidation_projection_hash_v2(v_receipt.id);
  v_result := jsonb_build_object(
    'manifestHash', p_manifest_hash,
    'canonicalInstrumentV2Id', v_target.id,
    'projectionHash', v_projection_hash,
    'projectedActiveConstructs', v_selected,
    'projectedDeferredConstructs', v_total - v_selected,
    'productionConstructsMutated', 0,
    'samplesDeleted', 0,
    'constructsDeleted', 0,
    'publicObjectsDeleted', 0,
    'closeoutStatus', NULL,
    'idempotent', false
  );

  UPDATE public.sip_sibling_consolidation_receipts_v2
  SET provider_lease_token = p_lease_token,
      publish_run_id = NULL,
      prepared_snapshot = v_current_snapshot,
      prepared_snapshot_hash = v_current_snapshot_hash,
      post_prepare_snapshot = v_current_snapshot,
      post_prepare_snapshot_hash = v_current_snapshot_hash,
      post_prepare_structural_hash = v_current_structural_hash,
      projection_hash = v_projection_hash,
      projection_summary = jsonb_build_object(
        'activeConstructs', v_selected,
        'deferredConstructs', v_total - v_selected,
        'constructIds', to_jsonb(v_actual_construct_ids)
      ),
      closeout_status = NULL,
      closeout_proof = NULL,
      closeout_completed_at = NULL,
      status = 'prepared',
      prepare_result = v_result,
      readiness_proof = NULL,
      cutover_result = NULL,
      rollback_result = NULL,
      prepared_by = p_applied_by,
      prepared_at = now(),
      cutover_by = NULL,
      cutover_at = NULL,
      rolled_back_by = NULL,
      rolled_back_at = NULL,
      reprepare_count =
        CASE WHEN v_reprepare THEN reprepare_count + 1 ELSE reprepare_count END
  WHERE id = v_receipt.id;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_coordinator_prepare_sibling_consolidation_v2"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb", "p_manifest_canonical_json" "text", "p_expected_snapshot" "jsonb", "p_expected_snapshot_hash" "text", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_reconcile_audio_profiles_v1"("p_limit" integer DEFAULT 100) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item record;
  v_ready record;
  v_profile record;
  v_profile_job_status text;
  v_sample_error text;
  v_runtime_ready boolean;
  v_count integer := 0;
BEGIN
  FOR v_item IN
    SELECT item.id, item.run_id, item.instrument_v2_id, item.result_payload
    FROM public.sip_fleet_run_items item
    JOIN public.sip_fleet_runs run ON run.id = item.run_id
    WHERE item.status = 'waiting_for_audio_profile'
      AND run.status IN ('queued', 'running')
      AND NOT run.cancel_requested
    ORDER BY item.updated_at ASC
    LIMIT greatest(1, least(coalesce(p_limit, 100), 1000))
    FOR UPDATE OF item, run SKIP LOCKED
  LOOP
    SELECT * INTO v_ready
    FROM public.published_sample_analysis_ready_for_profile_v1(v_item.instrument_v2_id);

    IF NOT coalesce(v_ready.ready, false) THEN
      SELECT left(
        string_agg(nullif(job.last_error, ''), '; ' ORDER BY job.updated_at DESC),
        8000
      ) INTO v_sample_error
      FROM public.sample_analysis_jobs job
      JOIN public.sample_s3_path asset ON asset.id = job.published_asset_id
      WHERE asset.instrument_v2_id = v_item.instrument_v2_id
        AND asset.is_current
        AND job.status = 'failed';
      UPDATE public.sip_fleet_run_items
      SET result_payload = coalesce(result_payload, '{}'::jsonb) || jsonb_build_object(
            'audioProfileFinalization', coalesce(result_payload->'audioProfileFinalization', '{}'::jsonb)
              || jsonb_build_object(
                'state', 'waiting_for_sample_analysis',
                'analysisReady', false,
                'failedSampleAnalysisCount', coalesce(v_ready.failed_asset_count, 0),
                'pendingSampleAnalysisCount', coalesce(v_ready.pending_asset_count, 0),
                'sampleAnalysisError', v_sample_error,
                'updatedAt', now()
              )
          )
      WHERE id = v_item.id;
      CONTINUE;
    END IF;

    SELECT * INTO v_profile
    FROM public.instrument_audio_profile_status_v1(
      ARRAY[v_item.instrument_v2_id], NULL, 'audio-profile-v1', 1, NOT EXISTS (
        SELECT 1
        FROM public.sip_sibling_consolidation_receipts_v2 receipt
        WHERE receipt.canonical_instrument_v2_id = v_item.instrument_v2_id
          AND receipt.status = 'cutover'
          AND receipt.closeout_status = 'pending'
      )
    )
    LIMIT 1;

    SELECT coalesce(
      (
        SELECT CASE
          WHEN job.status = 'skipped_fresh' THEN 'completed'
          ELSE job.status
        END
        FROM public.instrument_audio_profile_jobs_v1 job
        JOIN public.sip_sibling_consolidation_receipts_v2 receipt
          ON receipt.canonical_instrument_v2_id = job.instrument_v2_id
        WHERE job.instrument_v2_id = v_item.instrument_v2_id
          AND job.profile_version = 'audio-profile-v1'
          AND job.reason = 'deterministic_repair_finalization'
          AND job.status IN ('completed', 'completed_with_warnings', 'skipped_fresh')
          AND job.source_signature IS NOT DISTINCT FROM
            v_profile.current_source_signature
          AND job.completed_at >= receipt.cutover_at
          AND receipt.status = 'cutover'
          AND receipt.closeout_status = 'pending'
        ORDER BY job.completed_at DESC, job.id DESC
        LIMIT 1
      ),
      v_profile.latest_job_status
    )
    INTO v_profile_job_status;

    SELECT EXISTS (
      SELECT 1
      FROM public.instrument_v2_upload_status upload
      WHERE upload.instrument_v2_id = v_item.instrument_v2_id
        AND upload.runtime_verification_status = 'passed'
        AND upload.runtime_verification_report_path LIKE
          '%publish-runtime-verification-' || (v_item.result_payload->>'pipelineRunId') || '-%'
        AND EXISTS (
          SELECT 1
          FROM public.instrument_v2_publish_output_manifest manifest
          WHERE manifest.instrument_v2_id = v_item.instrument_v2_id
            AND manifest.run_id = v_item.result_payload->>'pipelineRunId'
        )
    ) INTO v_runtime_ready;

    IF v_profile.profile_state IN ('current', 'current_with_warnings')
      AND v_profile.profile_source_signature IS NOT DISTINCT FROM v_profile.current_source_signature
      AND v_profile_job_status IN ('completed', 'completed_with_warnings')
      AND v_runtime_ready
    THEN
      UPDATE public.sip_fleet_run_items
      SET status = 'completed',
          finished_at = now(),
          result_payload = coalesce(result_payload, '{}'::jsonb) || jsonb_build_object(
            'audioProfileFinalization', coalesce(result_payload->'audioProfileFinalization', '{}'::jsonb)
              || jsonb_build_object(
                'state', 'completed',
                'expectedSourceSignature', v_profile.current_source_signature,
                'profileState', v_profile.profile_state,
                'profileJobStatus', v_profile_job_status,
                'updatedAt', now()
              )
          )
      WHERE id = v_item.id;
      UPDATE public.sip_fleet_runs run
      SET status = CASE
            WHEN EXISTS (
              SELECT 1 FROM public.sip_fleet_run_items failed
              WHERE failed.run_id = run.id AND failed.status = 'failed'
            ) THEN 'failed'
            ELSE 'completed'
          END,
          finished_at = now()
      WHERE run.id = v_item.run_id
        AND NOT EXISTS (
          SELECT 1 FROM public.sip_fleet_run_items pending
          WHERE pending.run_id = run.id
            AND pending.status IN ('queued', 'running', 'waiting_for_audio_profile')
        );
      v_count := v_count + 1;
    ELSIF NOT (
      v_profile.profile_state IN ('current', 'current_with_warnings')
      AND v_profile.profile_source_signature IS NOT DISTINCT FROM v_profile.current_source_signature
      AND v_profile_job_status IN ('completed', 'completed_with_warnings')
    ) THEN
      PERFORM public.enqueue_instrument_audio_profile_jobs_v1(
        ARRAY[v_item.instrument_v2_id],
        'deterministic_repair_finalization',
        'audio-profile-v1',
        coalesce(
          v_profile_job_status NOT IN ('completed', 'completed_with_warnings'),
          true
        ),
        1000
      );
      UPDATE public.sip_fleet_run_items
      SET result_payload = coalesce(result_payload, '{}'::jsonb) || jsonb_build_object(
            'audioProfileFinalization', coalesce(result_payload->'audioProfileFinalization', '{}'::jsonb)
              || jsonb_build_object(
                'state', 'waiting_for_instrument_profile',
                'expectedSourceSignature', v_profile.current_source_signature,
                'profileState', v_profile.profile_state,
                'profileJobStatus', v_profile_job_status,
                'profileJobError', v_profile.latest_job_error,
                'updatedAt', now()
              )
          )
      WHERE id = v_item.id;
    ELSE
      UPDATE public.sip_fleet_run_items
      SET result_payload = coalesce(result_payload, '{}'::jsonb) || jsonb_build_object(
            'audioProfileFinalization', coalesce(result_payload->'audioProfileFinalization', '{}'::jsonb)
              || jsonb_build_object(
                'state', 'waiting_for_runtime_verification',
                'expectedSourceSignature', v_profile.current_source_signature,
                'profileState', v_profile.profile_state,
                'profileJobStatus', v_profile_job_status,
                'updatedAt', now()
              )
          )
      WHERE id = v_item.id;
    END IF;
  END LOOP;
  RETURN v_count;
END $$;


ALTER FUNCTION "public"."sip_publish_coordinator_reconcile_audio_profiles_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_reconcile_stalled_progress_v1"("p_max_idle_seconds" integer DEFAULT 1800) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_stalled integer := 0;
BEGIN
  IF p_max_idle_seconds < 300 OR p_max_idle_seconds > 86400 THEN
    RAISE EXCEPTION 'invalid_max_idle_seconds';
  END IF;

  WITH stalled AS (
    UPDATE public.sip_fleet_run_items item
    SET
      status = 'failed',
      last_error = 'Publish watchdog: no stage progress before bounded idle deadline',
      result_payload = coalesce(item.result_payload, '{}'::jsonb) || jsonb_build_object(
        'watchdog', jsonb_build_object(
          'reason', 'no_progress',
          'detectedAt', now(),
          'lastProgressAt', item.last_progress_at,
          'progress', item.progress_payload
        )
      ),
      executor_id = NULL,
      lease_token = NULL,
      lease_expires_at = NULL,
      finished_at = now()
    WHERE item.status = 'running'
      AND coalesce(item.last_progress_at, item.started_at, item.created_at)
        < now() - make_interval(secs => p_max_idle_seconds)
    RETURNING item.run_id
  )
  SELECT count(*) INTO v_stalled FROM stalled;

  UPDATE public.sip_fleet_runs run
  SET status = 'failed', finished_at = now()
  WHERE run.status = 'running'
    AND NOT EXISTS (
      SELECT 1 FROM public.sip_fleet_run_items item
      WHERE item.run_id = run.id AND item.status IN ('queued', 'running', 'waiting_for_audio_profile')
    )
    AND EXISTS (
      SELECT 1 FROM public.sip_fleet_run_items item
      WHERE item.run_id = run.id AND item.status = 'failed'
    );

  RETURN v_stalled;
END;
$$;


ALTER FUNCTION "public"."sip_publish_coordinator_reconcile_stalled_progress_v1"("p_max_idle_seconds" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_fleet_canary_results" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "git_sha" "text" NOT NULL,
    "processor_config_id" "text" NOT NULL,
    "contributor_slug" "text" NOT NULL,
    "instrument_v2_id" "uuid" NOT NULL,
    "run_id" "uuid" NOT NULL,
    "durable_check_id" "uuid" NOT NULL,
    "classification_parity_ok" boolean NOT NULL,
    "durable_queue_ok" boolean NOT NULL,
    "runtime_verification_ok" boolean NOT NULL,
    "audio_profile_ok" boolean NOT NULL,
    "passed" boolean NOT NULL,
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sip_fleet_canary_results_contributor_slug_check" CHECK (("btrim"("contributor_slug") <> ''::"text")),
    CONSTRAINT "sip_fleet_canary_results_evidence_check" CHECK (("jsonb_typeof"("evidence") = 'object'::"text")),
    CONSTRAINT "sip_fleet_canary_results_git_sha_check" CHECK (("btrim"("git_sha") <> ''::"text")),
    CONSTRAINT "sip_fleet_canary_results_processor_config_id_check" CHECK (("btrim"("processor_config_id") <> ''::"text")),
    CONSTRAINT "sip_fleet_canary_results_required_evidence_check" CHECK (("passed" = ("classification_parity_ok" AND "durable_queue_ok" AND "runtime_verification_ok")))
);


ALTER TABLE "public"."sip_fleet_canary_results" OWNER TO "postgres";


COMMENT ON TABLE "public"."sip_fleet_canary_results" IS 'Immutable production canary evidence used to gate SIP coordinator enforcement activation.';



CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_record_canary_v1"("p_git_sha" "text", "p_processor_config_id" "text", "p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_run_id" "uuid", "p_durable_check_id" "uuid", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."sip_fleet_canary_results"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result public.sip_fleet_canary_results%ROWTYPE;
  v_run_started_at timestamptz;
  v_classification_parity_ok boolean;
  v_durable_queue_ok boolean;
  v_runtime_verification_ok boolean;
  v_audio_profile_ok boolean;
  v_passed boolean;
  v_contributor_id uuid;
BEGIN
  IF nullif(btrim(p_git_sha), '') IS NULL
    OR nullif(btrim(p_processor_config_id), '') IS NULL
    OR nullif(btrim(p_contributor_slug), '') IS NULL
  THEN
    RAISE EXCEPTION 'canary_identity_required';
  END IF;
  IF jsonb_typeof(coalesce(p_evidence, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'canary_evidence_must_be_object';
  END IF;

  v_contributor_id := public.sip_publish_coordinator_contributor_id_v1(
    p_contributor_slug
  );
  SELECT run.started_at INTO v_run_started_at
  FROM public.sip_fleet_runs run
  JOIN public.sip_fleet_plan_artifacts artifact
    ON artifact.id = run.plan_artifact_id
  JOIN public.instruments_v2 instrument
    ON instrument.id = p_instrument_v2_id
   AND instrument.contributor_id = v_contributor_id
  WHERE run.id = p_run_id
    AND run.provider_slug = btrim(p_contributor_slug)
    AND run.status = 'completed'
    AND run.started_at IS NOT NULL
    AND artifact.provider_slug = run.provider_slug
    AND artifact.content->>'mode' = 'canary'
    AND artifact.content->>'gitSha' = btrim(p_git_sha)
    AND artifact.content->>'processorConfigId' = btrim(p_processor_config_id)
    AND (
      SELECT count(*)
      FROM public.sip_fleet_run_items item
      WHERE item.run_id = run.id
    ) = 1
    AND EXISTS (
      SELECT 1
      FROM public.sip_fleet_run_items item
      WHERE item.run_id = run.id
        AND item.instrument_v2_id = p_instrument_v2_id
        AND item.status = 'completed'
    );
  IF v_run_started_at IS NULL THEN
    RAISE EXCEPTION 'exact_completed_canary_run_required';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.instrument_v2_deterministic_readiness readiness
    JOIN public.sip_fleet_run_items item
      ON item.run_id = p_run_id
     AND item.instrument_v2_id = readiness.instrument_v2_id
    JOIN public.sip_fleet_runs run ON run.id = item.run_id
    JOIN public.sip_fleet_plan_artifacts artifact
      ON artifact.id = run.plan_artifact_id
    WHERE readiness.instrument_v2_id = p_instrument_v2_id
      AND readiness.status IN (
        'full_grid_deterministic',
        'exception_approved'
      )
      AND readiness.updated_at >= v_run_started_at
      AND readiness.snapshot_sha256 =
        item.result_payload->>'deterministicReadinessSnapshotHash'
      AND readiness.status::text =
        artifact.content->>'baselineReadinessStatus'
      AND readiness.snapshot_sha256 =
        artifact.content->>'baselineReadinessSnapshotSha256'
  ) INTO v_classification_parity_ok;

  SELECT EXISTS (
    SELECT 1
    FROM public.sip_fleet_durable_canary_checks durable
    WHERE durable.id = p_durable_check_id
      AND durable.instrument_v2_id = p_instrument_v2_id
      AND durable.passed
      AND durable.created_at >= v_run_started_at
  ) INTO v_durable_queue_ok;

  SELECT EXISTS (
    SELECT 1
    FROM public.instrument_v2_upload_status runtime
    JOIN public.sip_fleet_run_items item
      ON item.run_id = p_run_id
     AND item.instrument_v2_id = runtime.instrument_v2_id
    WHERE runtime.instrument_v2_id = p_instrument_v2_id
      AND runtime.runtime_verification_status = 'passed'
      AND runtime.runtime_verification_completed_at >= v_run_started_at
      AND runtime.runtime_verification_report_path LIKE
        '%publish-runtime-verification-' ||
        (item.result_payload->>'pipelineRunId') || '-%'
      AND EXISTS (
        SELECT 1
        FROM public.instrument_v2_publish_output_manifest manifest
        WHERE manifest.instrument_v2_id = p_instrument_v2_id
          AND manifest.run_id = item.result_payload->>'pipelineRunId'
          AND manifest.processed_at >= v_run_started_at
      )
  ) INTO v_runtime_verification_ok;

  SELECT EXISTS (
    SELECT 1
    FROM public.instrument_audio_profile_v1 profile
    JOIN public.instrument_audio_profile_jobs_v1 job
      ON job.instrument_v2_id = profile.instrument_v2_id
     AND job.profile_version = profile.profile_version
    WHERE profile.instrument_v2_id = p_instrument_v2_id
      AND profile.updated_at >= v_run_started_at
      AND job.status IN (
        'completed',
        'completed_with_warnings',
        'skipped_fresh'
      )
      AND job.completed_at >= v_run_started_at
      AND profile.source_signature IS NOT DISTINCT FROM
        public.compute_instrument_audio_profile_signature_v1(
          p_instrument_v2_id,
          profile.profile_version
        )
      AND profile.embedding IS NOT NULL
      AND profile.spectral_centroid_median IS NOT NULL
      AND profile.spectral_contrast_median IS NOT NULL
  ) INTO v_audio_profile_ok;

  v_passed := v_classification_parity_ok
    AND v_durable_queue_ok
    AND v_runtime_verification_ok;
  IF NOT v_passed THEN
    RAISE EXCEPTION 'canary_evidence_not_ready';
  END IF;

  INSERT INTO public.sip_fleet_canary_results(
    git_sha,
    processor_config_id,
    contributor_slug,
    instrument_v2_id,
    run_id,
    durable_check_id,
    classification_parity_ok,
    durable_queue_ok,
    runtime_verification_ok,
    audio_profile_ok,
    passed,
    evidence
  ) VALUES (
    btrim(p_git_sha),
    btrim(p_processor_config_id),
    btrim(p_contributor_slug),
    p_instrument_v2_id,
    p_run_id,
    p_durable_check_id,
    v_classification_parity_ok,
    v_durable_queue_ok,
    v_runtime_verification_ok,
    v_audio_profile_ok,
    v_passed,
    coalesce(p_evidence, '{}'::jsonb)
  ) RETURNING * INTO v_result;

  RETURN v_result;
END $$;


ALTER FUNCTION "public"."sip_publish_coordinator_record_canary_v1"("p_git_sha" "text", "p_processor_config_id" "text", "p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_run_id" "uuid", "p_durable_check_id" "uuid", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_retire_duplicate_orphans_v1"("p_contributor_slug" "text", "p_instrument_v2_ids" "uuid"[], "p_canonical_instrument_v2_ids" "uuid"[], "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_requested integer := cardinality(p_instrument_v2_ids);
  v_canonical_requested integer := cardinality(p_canonical_instrument_v2_ids);
  v_retired integer := 0;
  v_dispositioned integer := 0;
BEGIN
  IF coalesce(btrim(p_contributor_slug), '') = ''
    OR v_requested IS NULL OR v_requested < 1 OR v_requested > 250
    OR v_canonical_requested IS NULL OR v_canonical_requested < 1 OR v_canonical_requested > 250
    OR (SELECT count(DISTINCT id) FROM unnest(p_instrument_v2_ids) AS id) <> v_requested
    OR (SELECT count(DISTINCT id) FROM unnest(p_canonical_instrument_v2_ids) AS id) <> v_canonical_requested
    OR p_instrument_v2_ids && p_canonical_instrument_v2_ids
  THEN
    RAISE EXCEPTION 'invalid_duplicate_orphan_retirement_scope';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = p_contributor_slug
      AND lease.lease_token = p_lease_token
      AND lease.lease_expires_at > now()
  ) THEN
    RAISE EXCEPTION 'invalid_coordinator_publish_authorization';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = p_contributor_slug
      AND run.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'duplicate_orphan_retirement_active_run';
  END IF;

  IF (SELECT count(*) FROM public.instruments_v2 i
      JOIN public.contributors c ON c.id = i.contributor_id
      WHERE i.id = ANY(p_instrument_v2_ids)
        AND c.slug = p_contributor_slug
        AND i.published) <> v_requested
    OR (SELECT count(*) FROM public.instruments_v2 i
        JOIN public.contributors c ON c.id = i.contributor_id
        JOIN public.instrument_v2_upload_status s ON s.instrument_v2_id = i.id
        WHERE i.id = ANY(p_canonical_instrument_v2_ids)
          AND c.slug = p_contributor_slug
          AND i.published
          AND s.runtime_verification_status = 'passed') <> v_canonical_requested
    OR EXISTS (SELECT 1 FROM public.sip_review_promotion_map WHERE instrument_v2_id = ANY(p_instrument_v2_ids))
    OR EXISTS (SELECT 1 FROM public.instrument_v2_legacy_map WHERE instrument_v2_id = ANY(p_instrument_v2_ids))
    OR EXISTS (SELECT 1 FROM public.sample_path_constructs WHERE instrument_v2_id = ANY(p_instrument_v2_ids))
    OR EXISTS (
      SELECT 1
      FROM public.instruments_v2 orphan
      CROSS JOIN LATERAL unnest(orphan.original_sample_ids) AS source(sample_original_path_id)
      WHERE orphan.id = ANY(p_instrument_v2_ids)
        AND NOT EXISTS (
          SELECT 1 FROM public.sample_path_constructs construct
          WHERE construct.instrument_v2_id = ANY(p_canonical_instrument_v2_ids)
            AND construct.sample_original_path_id = source.sample_original_path_id
        )
    )
  THEN
    RAISE EXCEPTION 'duplicate_orphan_retirement_not_duplicate';
  END IF;

  PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);

  UPDATE public.instruments_v2
  SET published = false
  WHERE id = ANY(p_instrument_v2_ids) AND published;
  GET DIAGNOSTICS v_retired = ROW_COUNT;

  UPDATE public.instrument_v2_upload_status
  SET runtime_verification_status = 'skipped',
      runtime_verification_error_summary = jsonb_build_object(
        'kind', 'terminal_disposition',
        'reason', 'duplicate_orphan_v2_source_already_published',
        'canonical_instrument_v2_ids', to_jsonb(p_canonical_instrument_v2_ids)
      )
  WHERE instrument_v2_id = ANY(p_instrument_v2_ids);
  GET DIAGNOSTICS v_dispositioned = ROW_COUNT;

  IF v_retired <> v_requested OR v_dispositioned <> v_requested THEN
    RAISE EXCEPTION 'duplicate_orphan_retirement_incomplete';
  END IF;

  RETURN jsonb_build_object('retired', v_retired);
END;
$$;


ALTER FUNCTION "public"."sip_publish_coordinator_retire_duplicate_orphans_v1"("p_contributor_slug" "text", "p_instrument_v2_ids" "uuid"[], "p_canonical_instrument_v2_ids" "uuid"[], "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_retry_public_output_recovery_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_prior_run_id" "uuid", "p_fresh_rehearsal_id" "uuid", "p_expected_content_hash" "text", "p_approved_by" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_provider_slug text := btrim(p_contributor_slug);
  v_git_sha text := btrim(p_git_sha);
  v_processor_config_id text := btrim(p_processor_config_id);
  v_content_hash text := btrim(p_expected_content_hash);
  v_approved_by text := btrim(p_approved_by);
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_prior_run public.sip_fleet_runs%ROWTYPE;
  v_rehearsal public.sip_public_output_recovery_rehearsals%ROWTYPE;
  v_retry_approval public.sip_public_output_recovery_retry_approvals%ROWTYPE;
  v_receipt public.sip_public_output_recovery_retry_receipts%ROWTYPE;
  v_lease_owner text;
  v_instrument_ids uuid[];
  v_target_keys text[];
  v_instrument_count integer;
  v_target_count integer;
  v_retry_receipt_id uuid := gen_random_uuid();
  v_retry_run_id uuid;
  v_retry_key text;
  v_retry_proof jsonb;
  v_retry_proof_hash text;
  v_prior_items jsonb;
  v_recovery jsonb;
  v_plan jsonb;
  v_items jsonb;
BEGIN
  IF nullif(v_provider_slug, '') IS NULL
    OR p_artifact_id IS NULL
    OR p_prior_run_id IS NULL
    OR p_fresh_rehearsal_id IS NULL
    OR v_content_hash !~ '^[0-9a-f]{64}$'
    OR nullif(v_approved_by, '') IS NULL
    OR nullif(v_git_sha, '') IS NULL
    OR v_git_sha = 'unknown'
    OR nullif(v_processor_config_id, '') IS NULL
    OR v_processor_config_id = 'unconfigured'
  THEN
    RAISE EXCEPTION 'public_output_recovery_retry_identity_required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_provider_slug, 0));

  SELECT lease.lease_owner
  INTO v_lease_owner
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
    AND lease.provider_slug = v_provider_slug
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;

  SELECT *
  INTO v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = p_artifact_id
    AND artifact.provider_slug = v_provider_slug
    AND artifact.artifact_kind = 'public-output-recovery-v1'
    AND artifact.content_hash = v_content_hash;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'public_output_recovery_retry_artifact_required';
  END IF;

  IF v_artifact.content->>'recoveryKind'
      IS DISTINCT FROM 'public-output-recovery-v1'
    OR v_artifact.content->>'contributor' IS DISTINCT FROM v_provider_slug
    OR v_artifact.content->>'gitSha' IS DISTINCT FROM v_git_sha
    OR v_artifact.content->>'processorConfigId'
      IS DISTINCT FROM v_processor_config_id
    OR jsonb_typeof(v_artifact.content->'instruments') <> 'array'
    OR jsonb_array_length(v_artifact.content->'instruments') = 0
  THEN
    RAISE EXCEPTION 'public_output_recovery_retry_artifact_identity_mismatch';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_plan_artifact_approvals approval
    WHERE approval.artifact_id = v_artifact.id
      AND approval.content_hash = v_artifact.content_hash
      AND approval.approved_by = v_approved_by
  ) THEN
    RAISE EXCEPTION 'approved_public_output_recovery_artifact_required';
  END IF;

  SELECT * INTO v_retry_approval
  FROM public.sip_public_output_recovery_retry_approvals approval
  WHERE approval.artifact_id = v_artifact.id
    AND approval.content_hash = v_artifact.content_hash
    AND approval.provider_slug = v_provider_slug
    AND approval.provider_lease_id = p_lease_id
    AND approval.prior_run_id = p_prior_run_id
    AND approval.fresh_rehearsal_id = p_fresh_rehearsal_id
    AND approval.git_sha = v_git_sha
    AND approval.processor_config_id = v_processor_config_id
    AND approval.approved_by = v_approved_by
    AND approval.approval_hash = encode(digest(
      convert_to(approval.approval_payload::text, 'UTF8'), 'sha256'
    ), 'hex')
    AND approval.approval_payload->>'artifactId' = v_artifact.id::text
    AND approval.approval_payload->>'priorRunId' = p_prior_run_id::text
    AND approval.approval_payload->>'freshRehearsalId'
      = p_fresh_rehearsal_id::text;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'fresh_public_output_recovery_retry_approval_required';
  END IF;

  SELECT array_agg(
    (instrument.value->>'instrumentV2Id')::uuid
    ORDER BY instrument.value->>'instrumentV2Id'
  )
  INTO v_instrument_ids
  FROM jsonb_array_elements(v_artifact.content->'instruments') instrument(value);

  SELECT array_agg(target.value->>'s3Key' ORDER BY target.value->>'s3Key')
  INTO v_target_keys
  FROM jsonb_array_elements(v_artifact.content->'instruments') instrument(value)
  CROSS JOIN LATERAL jsonb_array_elements(instrument.value->'targets') target(value);

  v_instrument_count := cardinality(v_instrument_ids);
  v_target_count := cardinality(v_target_keys);

  IF v_instrument_count IS NULL
    OR v_target_count IS NULL
    OR v_target_count = 0
    OR v_instrument_count <> (
      SELECT count(DISTINCT id) FROM unnest(v_instrument_ids) requested(id)
    )
    OR v_target_count <> (
      SELECT count(DISTINCT key) FROM unnest(v_target_keys) requested(key)
    )
  THEN
    RAISE EXCEPTION 'public_output_recovery_retry_scope_invalid';
  END IF;

  SELECT *
  INTO v_receipt
  FROM public.sip_public_output_recovery_retry_receipts receipt
  WHERE receipt.prior_run_id = p_prior_run_id;

  IF FOUND THEN
    IF v_receipt.artifact_id <> p_artifact_id
      OR v_receipt.content_hash <> v_content_hash
      OR v_receipt.provider_slug <> v_provider_slug
      OR v_receipt.provider_lease_id <> p_lease_id
      OR v_receipt.fresh_rehearsal_id <> p_fresh_rehearsal_id
      OR v_receipt.retry_approval_id <> v_retry_approval.id
      OR v_receipt.approval_hash <> v_retry_approval.approval_hash
      OR v_receipt.git_sha <> v_git_sha
      OR v_receipt.processor_config_id <> v_processor_config_id
      OR v_receipt.approved_by <> v_approved_by
    THEN
      RAISE EXCEPTION 'public_output_recovery_retry_receipt_mismatch';
    END IF;

    RETURN jsonb_build_object(
      'runId', v_receipt.retry_run_id,
      'created', false,
      'priorRunId', v_receipt.prior_run_id,
      'retryReceiptId', v_receipt.id,
      'retryProofHash', v_receipt.proof_hash
    );
  END IF;

  SELECT *
  INTO v_prior_run
  FROM public.sip_fleet_runs run
  WHERE run.id = p_prior_run_id
    AND run.provider_slug = v_provider_slug
  FOR UPDATE;

  IF NOT FOUND
    OR v_prior_run.status NOT IN ('failed', 'canceled')
    OR v_prior_run.finished_at IS NULL
  THEN
    RAISE EXCEPTION 'terminal_public_output_recovery_run_required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_plan_artifacts run_artifact
    WHERE run_artifact.id = v_prior_run.plan_artifact_id
      AND run_artifact.artifact_kind = 'publish-plan'
      AND run_artifact.content->>'mode' = 'public_output_recovery'
      AND run_artifact.content#>>'{publicOutputRecovery,artifactId}'
        = v_artifact.id::text
      AND run_artifact.content#>>'{publicOutputRecovery,contentHash}'
        = v_artifact.content_hash
      AND run_artifact.content->>'gitSha' = v_git_sha
      AND run_artifact.content->>'processorConfigId' = v_processor_config_id
  ) THEN
    RAISE EXCEPTION 'prior_public_output_recovery_run_identity_mismatch';
  END IF;

  IF v_prior_run.idempotency_key
      <> 'public-output-recovery:' || v_artifact.content_hash
  THEN
    RAISE EXCEPTION 'prior_public_output_recovery_run_lineage_mismatch';
  END IF;

  PERFORM 1
  FROM public.sip_fleet_run_items item
  WHERE item.run_id = v_prior_run.id
  ORDER BY item.id
  FOR UPDATE;

  IF (
    SELECT count(*)
    FROM public.sip_fleet_run_items item
    WHERE item.run_id = v_prior_run.id
  ) <> v_instrument_count
    OR EXISTS (
      SELECT 1
      FROM unnest(v_instrument_ids) requested(id)
      FULL JOIN (
        SELECT prior_item.*
        FROM public.sip_fleet_run_items prior_item
        WHERE prior_item.run_id = v_prior_run.id
      ) item ON item.instrument_v2_id = requested.id
      WHERE requested.id IS NULL OR item.id IS NULL
    )
  THEN
    RAISE EXCEPTION 'prior_public_output_recovery_run_scope_mismatch';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.sip_fleet_run_items item
    WHERE item.run_id = v_prior_run.id
      AND (
        item.status NOT IN ('failed', 'canceled')
        OR item.attempts <> 0
        OR item.executor_id IS NOT NULL
        OR item.lease_token IS NOT NULL
        OR item.lease_expires_at IS NOT NULL
        OR item.heartbeat_at IS NOT NULL
        OR item.started_at IS NOT NULL
        OR item.result_payload <> '{}'::jsonb
        OR coalesce(item.last_error, '') NOT IN (
          'Could not reconcile current targets object evidence',
          'public_output_recovery_object_evidence_unreadable',
          'sip_v2_reconcile_objects_ambiguous',
          'coordinator_cancelled_before_claim'
        )
      )
  ) THEN
    RAISE EXCEPTION 'prior_public_output_recovery_precontent_proof_invalid';
  END IF;

  IF (
    SELECT count(DISTINCT coalesce(item.last_error, ''))
    FROM public.sip_fleet_run_items item
    WHERE item.run_id = v_prior_run.id
  ) <> 1 THEN
    RAISE EXCEPTION 'prior_public_output_recovery_item_error_ambiguous';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'itemId', item.id,
      'instrumentV2Id', item.instrument_v2_id,
      'status', item.status,
      'attempts', item.attempts,
      'startedAt', item.started_at,
      'finishedAt', item.finished_at,
      'executorId', item.executor_id,
      'leaseTokenPresent', item.lease_token IS NOT NULL,
      'leaseExpiresAt', item.lease_expires_at,
      'heartbeatAt', item.heartbeat_at,
      'resultPayload', item.result_payload,
      'lastError', item.last_error
    ) ORDER BY item.id
  )
  INTO v_prior_items
  FROM public.sip_fleet_run_items item
  WHERE item.run_id = v_prior_run.id;

  IF v_prior_run.status = 'failed'
    AND v_prior_run.result_payload NOT IN (
      jsonb_build_object(
        'recoveryError',
        'Could not reconcile current targets object evidence'
      ),
      jsonb_build_object(
        'recoveryError',
        'public_output_recovery_object_evidence_unreadable'
      ),
      jsonb_build_object(
        'recoveryError',
        'sip_v2_reconcile_objects_ambiguous'
      )
    )
  THEN
    RAISE EXCEPTION 'prior_public_output_recovery_failure_payload_invalid';
  END IF;

  IF v_prior_run.status = 'canceled'
    AND (
      v_prior_run.cancel_requested IS NOT TRUE
      OR nullif(btrim(v_prior_run.cancel_reason), '') IS NULL
      OR v_prior_run.result_payload <> '{}'::jsonb
    )
  THEN
    RAISE EXCEPTION 'prior_public_output_recovery_cancellation_proof_invalid';
  END IF;

  SELECT *
  INTO v_rehearsal
  FROM public.sip_public_output_recovery_rehearsals rehearsal
  WHERE rehearsal.id = p_fresh_rehearsal_id
    AND rehearsal.artifact_id = v_artifact.id
    AND rehearsal.content_hash = v_artifact.content_hash
    AND rehearsal.provider_slug = v_provider_slug
    AND rehearsal.provider_lease_id = p_lease_id
    AND rehearsal.git_sha = v_git_sha
    AND rehearsal.processor_config_id = v_processor_config_id
    AND rehearsal.status = 'passed'
    AND rehearsal.completed_at IS NOT NULL
    AND rehearsal.created_at > v_prior_run.finished_at
    AND rehearsal.completed_at >= clock_timestamp() - interval '15 minutes';

  IF NOT FOUND
    OR v_rehearsal.result_payload->>'instrumentCount'
      IS DISTINCT FROM v_instrument_count::text
    OR v_rehearsal.result_payload->>'targetCount'
      IS DISTINCT FROM v_target_count::text
  THEN
    RAISE EXCEPTION 'fresh_passed_public_output_recovery_rehearsal_required';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.sip_fleet_runs run
    WHERE run.provider_slug = v_provider_slug
      AND run.status IN ('queued', 'running')
  ) OR EXISTS (
    SELECT 1
    FROM public.sip_fleet_runs run
    JOIN public.sip_fleet_run_items item ON item.run_id = run.id
    WHERE run.provider_slug = v_provider_slug
      AND item.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'provider_publish_run_active';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.instrument_v2_publish_output_manifest output
    WHERE output.destination_s3_key = ANY(v_target_keys)
      AND output.processed_at >= v_prior_run.created_at
  ) OR EXISTS (
    SELECT 1
    FROM public.instrument_runtime_sample_manifests manifest
    WHERE manifest.instrument_v2_id = ANY(v_instrument_ids)
      AND manifest.generated_at >= v_prior_run.created_at
  ) OR EXISTS (
    SELECT 1
    FROM public.instrument_v2_deterministic_readiness readiness
    WHERE readiness.instrument_v2_id = ANY(v_instrument_ids)
      AND readiness.updated_at >= v_prior_run.created_at
  ) OR EXISTS (
    SELECT 1
    FROM public.instrument_v2_runtime_readiness readiness
    WHERE readiness.instrument_v2_id = ANY(v_instrument_ids)
      AND readiness.evaluated_at >= v_prior_run.created_at
  ) OR EXISTS (
    SELECT 1
    FROM public.sip_runtime_manifest_materialization_receipts receipt
    WHERE receipt.instrument_v2_id = ANY(v_instrument_ids)
      AND receipt.applied_at >= v_prior_run.created_at
  ) OR EXISTS (
    SELECT 1
    FROM public.sample_generated_derivations derivation
    WHERE derivation.instrument_v2_id = ANY(v_instrument_ids)
      AND derivation.created_at >= v_prior_run.created_at
  ) THEN
    RAISE EXCEPTION 'prior_public_output_recovery_mutation_detected';
  END IF;

  v_retry_proof := jsonb_build_object(
    'schemaVersion', 'sip-public-output-recovery-precontent-retry-v1',
    'artifactId', v_artifact.id,
    'contentHash', v_artifact.content_hash,
    'providerSlug', v_provider_slug,
    'providerLeaseId', p_lease_id,
    'priorRunId', v_prior_run.id,
    'priorRunIdempotencyKey', v_prior_run.idempotency_key,
    'priorRunPlanArtifactId', v_prior_run.plan_artifact_id,
    'priorRunStatus', v_prior_run.status,
    'priorRunCancelRequested', v_prior_run.cancel_requested,
    'priorRunCancelReason', v_prior_run.cancel_reason,
    'priorRunResultPayload', v_prior_run.result_payload,
    'priorRunFinishedAt', v_prior_run.finished_at,
    'priorItems', v_prior_items,
    'freshRehearsalId', v_rehearsal.id,
    'freshRehearsalCompletedAt', v_rehearsal.completed_at,
    'retryApprovalId', v_retry_approval.id,
    'retryApprovalHash', v_retry_approval.approval_hash,
    'gitSha', v_git_sha,
    'processorConfigId', v_processor_config_id,
    'approvedBy', v_approved_by,
    'instrumentV2Ids', to_jsonb(v_instrument_ids),
    'targetS3Keys', to_jsonb(v_target_keys),
    'precontentProof', jsonb_build_object(
      'instrumentCount', v_instrument_count,
      'targetCount', v_target_count,
      'allItemsTerminal', true,
      'allItemsAttemptsZero', true,
      'allItemsUnclaimed', true,
      'allItemResultsEmpty', true,
      'runBoundOrTimeBoundMutationsAbsent', true
    )
  );
  v_retry_proof_hash := encode(
    digest(convert_to(v_retry_proof::text, 'UTF8'), 'sha256'),
    'hex'
  );

  v_recovery := jsonb_build_object(
    'artifactId', v_artifact.id,
    'contentHash', v_artifact.content_hash,
    'rehearsalRunId', v_rehearsal.id,
    'approved', true,
    'manifest', v_artifact.content,
    'precontentRetry', jsonb_build_object(
      'receiptId', v_retry_receipt_id,
      'priorRunId', v_prior_run.id,
      'proofHash', v_retry_proof_hash,
      'freshRehearsalRunId', v_rehearsal.id,
      'retryApprovalId', v_retry_approval.id,
      'retryApprovalHash', v_retry_approval.approval_hash,
      'approvedBy', v_approved_by
    )
  );
  v_plan := jsonb_build_object(
    'mode', 'public_output_recovery',
    'forceRerun', false,
    'durationPolicy', null,
    'topology', '{}'::jsonb,
    'derivedFill', '{}'::jsonb,
    'publicOutputRecovery', v_recovery,
    'gitSha', v_git_sha,
    'processorConfigId', v_processor_config_id,
    'instrumentV2Ids', to_jsonb(v_instrument_ids)
  );
  v_retry_key := 'public-output-recovery:' || v_artifact.content_hash
    || ':precontent-retry:' || v_prior_run.id::text;

  SELECT jsonb_agg(
    jsonb_build_object(
      'itemKey', 'public-output-recovery:' || id::text,
      'instrumentV2Id', id,
      'payload', jsonb_build_object(
        'mode', 'public_output_recovery',
        'publicOutputRecovery', v_recovery
      )
    ) ORDER BY id
  )
  INTO v_items
  FROM unnest(v_instrument_ids) id;

  v_retry_run_id := public.submit_sip_fleet_run(
    v_provider_slug,
    p_lease_token,
    v_retry_key,
    v_lease_owner,
    v_plan,
    v_items
  );

  INSERT INTO public.sip_public_output_recovery_retry_receipts (
    id,
    artifact_id,
    content_hash,
    provider_slug,
    provider_lease_id,
    prior_run_id,
    retry_run_id,
    fresh_rehearsal_id,
    retry_approval_id,
    approval_hash,
    git_sha,
    processor_config_id,
    approved_by,
    retry_proof,
    proof_hash
  ) VALUES (
    v_retry_receipt_id,
    v_artifact.id,
    v_artifact.content_hash,
    v_provider_slug,
    p_lease_id,
    v_prior_run.id,
    v_retry_run_id,
    v_rehearsal.id,
    v_retry_approval.id,
    v_retry_approval.approval_hash,
    v_git_sha,
    v_processor_config_id,
    v_approved_by,
    v_retry_proof,
    v_retry_proof_hash
  )
  RETURNING * INTO v_receipt;

  RETURN jsonb_build_object(
    'runId', v_receipt.retry_run_id,
    'created', true,
    'priorRunId', v_receipt.prior_run_id,
    'retryReceiptId', v_receipt.id,
    'retryProofHash', v_receipt.proof_hash
  );
END;
$_$;


ALTER FUNCTION "public"."sip_publish_coordinator_retry_public_output_recovery_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_prior_run_id" "uuid", "p_fresh_rehearsal_id" "uuid", "p_expected_content_hash" "text", "p_approved_by" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_rollback_sibling_consolidation_v2"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_applied_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_receipt public.sip_sibling_consolidation_receipts_v2%ROWTYPE;
  v_projection_hash text;
  v_result jsonb;
BEGIN
  IF NULLIF(btrim(p_contributor_slug), '') IS NULL
     OR NULLIF(btrim(p_applied_by), '') IS NULL
     OR p_manifest_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'invalid sibling consolidation v2 rollback request'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
    FOR UPDATE
  ) THEN
    RAISE EXCEPTION
      'sibling consolidation v2 rollback requires active provider lease'
      USING ERRCODE = '42501';
  END IF;

  LOCK TABLE public.sip_sibling_consolidation_receipts_v2
    IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_sibling_consolidation_projection_v2
    IN SHARE ROW EXCLUSIVE MODE;

  SELECT * INTO v_receipt
  FROM public.sip_sibling_consolidation_receipts_v2 receipt
  WHERE receipt.provider_slug = p_contributor_slug
    AND receipt.manifest_hash = p_manifest_hash
  FOR UPDATE;

  IF v_receipt.id IS NULL THEN
    RAISE EXCEPTION 'sibling consolidation v2 rollback receipt not found'
      USING ERRCODE = '55000';
  END IF;
  IF v_receipt.provider_lease_id IS DISTINCT FROM p_lease_id THEN
    RAISE EXCEPTION
      'sibling consolidation v2 rollback lease differs from prepare receipt'
      USING ERRCODE = '42501';
  END IF;
  IF v_receipt.status = 'rolled_back' THEN
    RETURN v_receipt.rollback_result
      || jsonb_build_object('idempotent', true);
  END IF;
  IF v_receipt.status = 'cutover' THEN
    RAISE EXCEPTION
      'sibling consolidation v2 cutover requires forward recovery; generic rollback is forbidden'
      USING ERRCODE = '55000';
  END IF;
  IF v_receipt.status <> 'prepared' THEN
    RAISE EXCEPTION
      'sibling consolidation v2 rollback requires prepared receipt'
      USING ERRCODE = '55000';
  END IF;

  v_projection_hash :=
    public.sip_sibling_consolidation_projection_hash_v2(v_receipt.id);
  IF v_projection_hash IS DISTINCT FROM v_receipt.projection_hash
     OR EXISTS (
       SELECT 1
       FROM public.sip_sibling_consolidation_projection_v2 projection
       WHERE projection.receipt_id = v_receipt.id
         AND projection.status <> 'prepared'
     )
     OR NOT EXISTS (
       SELECT 1
       FROM public.sip_sibling_consolidation_projection_v2 projection
       WHERE projection.receipt_id = v_receipt.id
     )
     OR v_receipt.publish_run_id IS NOT NULL
     OR v_receipt.readiness_proof IS NOT NULL
     OR v_receipt.cutover_result IS NOT NULL
     OR v_receipt.closeout_status IS NOT NULL
     OR v_receipt.closeout_proof IS NOT NULL
     OR v_receipt.closeout_completed_at IS NOT NULL THEN
    RAISE EXCEPTION
      'sibling consolidation v2 prepared control-plane state drifted before rollback'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.sip_sibling_consolidation_projection_v2 projection
  SET status = 'rolled_back',
      updated_at = now()
  WHERE projection.receipt_id = v_receipt.id
    AND projection.status = 'prepared';

  v_result := jsonb_build_object(
    'manifestHash', p_manifest_hash,
    'canonicalInstrumentV2Id',
      v_receipt.canonical_instrument_v2_id,
    'controlPlaneOnly', true,
    'productionRowsMutated', 0,
    'samplesDeleted', 0,
    'constructsDeleted', 0,
    'publicObjectsDeleted', 0,
    'idempotent', false
  );

  UPDATE public.sip_sibling_consolidation_receipts_v2
  SET status = 'rolled_back',
      publish_run_id = NULL,
      readiness_proof = NULL,
      cutover_result = NULL,
      rollback_result = v_result,
      rolled_back_by = p_applied_by,
      rolled_back_at = now(),
      closeout_status = NULL,
      closeout_proof = NULL,
      closeout_completed_at = NULL
  WHERE id = v_receipt.id
    AND status = 'prepared';
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'sibling consolidation v2 prepared rollback raced'
      USING ERRCODE = '40001';
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_coordinator_rollback_sibling_consolidation_v2"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_set_published_v1"("p_run_id" "uuid", "p_instrument_v2_id" "uuid", "p_provider_lease_token" "uuid", "p_item_id" "uuid", "p_executor_id" "text", "p_item_lease_token" "uuid", "p_published" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT EXISTS(
    SELECT 1
    FROM public.sip_fleet_runs run
    JOIN public.sip_fleet_provider_leases lease
      ON lease.id = run.provider_lease_id
     AND lease.provider_slug = run.provider_slug
    JOIN public.sip_fleet_run_items item ON item.run_id = run.id
    WHERE run.id = p_run_id
      AND run.status IN ('queued', 'running')
      AND NOT run.cancel_requested
      AND lease.lease_token = p_provider_lease_token
      AND lease.lease_expires_at > now()
      AND run.provider_lease_token = p_provider_lease_token
      AND item.id = p_item_id
      AND item.instrument_v2_id = p_instrument_v2_id
      AND item.status = 'running'
      AND item.executor_id = p_executor_id
      AND item.lease_token = p_item_lease_token
      AND item.lease_expires_at > now()
  ) THEN
    RAISE EXCEPTION 'invalid_coordinator_publish_authorization';
  END IF;

  v_result := public.set_instrument_v2_published_manifest_aware_v1(
    p_instrument_v2_id,
    p_published
  );
  RETURN (v_result->>'changed')::boolean;
END;
$$;


ALTER FUNCTION "public"."sip_publish_coordinator_set_published_v1"("p_run_id" "uuid", "p_instrument_v2_id" "uuid", "p_provider_lease_token" "uuid", "p_item_id" "uuid", "p_executor_id" "text", "p_item_lease_token" "uuid", "p_published" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_status_v1"("p_contributor_slug" "text", "p_run_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'runId', run.id,
    'contributorSlug', run.provider_slug,
    'status', run.status,
    'cancelRequested', run.cancel_requested,
    'createdAt', run.created_at,
    'startedAt', run.started_at,
    'finishedAt', run.finished_at,
    'counts', (SELECT jsonb_object_agg(item_counts.status, item_counts.count)
      FROM (SELECT item.status, count(*) AS count FROM public.sip_fleet_run_items item
            WHERE item.run_id = run.id GROUP BY item.status) item_counts),
    'oldestQueuedAt', queue_age.oldest_queued_at,
    'oldestQueuedAgeSeconds', CASE
      WHEN queue_age.oldest_queued_at IS NULL THEN NULL
      ELSE greatest(0, floor(extract(epoch FROM (now() - queue_age.oldest_queued_at)))::bigint)
    END,
    'audioProfileFinalizations', coalesce(finalizations.items, '[]'::jsonb),
    'recentItemErrors', coalesce(recent_errors.items, '[]'::jsonb)
  ) ORDER BY run.created_at DESC), '[]'::jsonb)
  FROM public.sip_fleet_runs run
  LEFT JOIN LATERAL (
    SELECT min(item.created_at) AS oldest_queued_at
    FROM public.sip_fleet_run_items item
    WHERE item.run_id = run.id AND item.status = 'queued'
  ) queue_age ON true
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(jsonb_build_object(
      'itemId', item.id,
      'instrumentV2Id', item.instrument_v2_id,
      'status', item.status,
      'manifest', item.result_payload->'repairManifest',
      'finalization', item.result_payload->'audioProfileFinalization',
      'updatedAt', item.updated_at
    ) ORDER BY item.updated_at ASC) AS items
    FROM public.sip_fleet_run_items item
    WHERE item.run_id = run.id
      AND (item.status = 'waiting_for_audio_profile'
        OR item.result_payload ? 'audioProfileFinalization')
  ) finalizations ON true
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(jsonb_build_object(
      'itemId', errors.id, 'instrumentV2Id', errors.instrument_v2_id,
      'status', errors.status, 'lastError', errors.last_error,
      'attempts', errors.attempts, 'maxAttempts', errors.max_attempts,
      'updatedAt', errors.updated_at
    ) ORDER BY errors.updated_at DESC) AS items
    FROM (SELECT item.id, item.instrument_v2_id, item.status, item.last_error,
                 item.attempts, item.max_attempts, item.updated_at
          FROM public.sip_fleet_run_items item
          WHERE item.run_id = run.id AND nullif(btrim(item.last_error), '') IS NOT NULL
          ORDER BY item.updated_at DESC LIMIT 5) errors
  ) recent_errors ON true
  WHERE run.provider_slug = p_contributor_slug
    AND (p_run_id IS NULL OR run.id = p_run_id)
$$;


ALTER FUNCTION "public"."sip_publish_coordinator_status_v1"("p_contributor_slug" "text", "p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_submit_canary_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_readiness public.instrument_v2_deterministic_readiness%ROWTYPE; v_plan jsonb; v_items jsonb; v_key text; v_existing uuid; v_run_id uuid; v_contributor_id uuid;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.sip_fleet_provider_leases lease WHERE lease.id=p_lease_id AND lease.provider_slug=p_contributor_slug AND lease.lease_token=p_lease_token AND lease.lease_expires_at>now()) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  v_contributor_id := public.sip_publish_coordinator_contributor_id_v1(p_contributor_slug);
  IF v_contributor_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.instruments_v2 instrument WHERE instrument.id=p_instrument_v2_id AND instrument.contributor_id=v_contributor_id AND NOT instrument.published) THEN RAISE EXCEPTION 'canary_instrument_ineligible'; END IF;
  SELECT * INTO v_readiness FROM public.instrument_v2_deterministic_readiness readiness WHERE readiness.instrument_v2_id=p_instrument_v2_id AND readiness.status IN ('full_grid_deterministic','exception_approved') ORDER BY readiness.updated_at DESC LIMIT 1;
  IF v_readiness.id IS NULL THEN RAISE EXCEPTION 'canary_readiness_required'; END IF;
  v_plan:=jsonb_build_object('mode','canary','forceRerun',false,'durationPolicy',null,'topology','{}'::jsonb,'derivedFill','{}'::jsonb,'gitSha',p_git_sha,'processorConfigId',p_processor_config_id,'instrumentV2Ids',jsonb_build_array(p_instrument_v2_id),'baselineReadinessStatus',v_readiness.status,'baselineReadinessSnapshotSha256',v_readiness.snapshot_sha256,'baselineReadinessUpdatedAt',v_readiness.updated_at);
  v_items:=jsonb_build_array(jsonb_build_object('itemKey',p_instrument_v2_id::text,'instrumentV2Id',p_instrument_v2_id,'payload',jsonb_build_object('mode','canary')));
  v_key:=encode(digest(convert_to(v_plan::text,'UTF8'),'sha256'),'hex');
  SELECT id INTO v_existing FROM public.sip_fleet_runs WHERE provider_slug=p_contributor_slug AND idempotency_key=v_key;
  v_run_id:=public.submit_sip_fleet_run(p_contributor_slug,p_lease_token,v_key,(SELECT lease_owner FROM public.sip_fleet_provider_leases WHERE id=p_lease_id),v_plan,v_items);
  RETURN jsonb_build_object('runId',v_run_id,'created',v_existing IS NULL);
END $$;


ALTER FUNCTION "public"."sip_publish_coordinator_submit_canary_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_submit_public_output_recovery_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_rehearsal_id uuid;
  v_lease_owner text;
  v_instrument_ids uuid[];
  v_recovery jsonb;
  v_plan jsonb;
  v_items jsonb;
  v_key text;
  v_existing uuid;
  v_run_id uuid;
BEGIN
  SELECT lease.lease_owner INTO v_lease_owner
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id=p_lease_id AND lease.provider_slug=btrim(p_contributor_slug)
    AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
    AND lease.lease_expires_at>clock_timestamp();
  IF NOT FOUND THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;

  SELECT artifact.* INTO v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  JOIN public.sip_fleet_plan_artifact_approvals approval
    ON approval.artifact_id=artifact.id AND approval.content_hash=artifact.content_hash
  WHERE artifact.id=p_artifact_id
    AND artifact.provider_slug=btrim(p_contributor_slug)
    AND artifact.artifact_kind='public-output-recovery-v1';
  IF v_artifact.id IS NULL THEN RAISE EXCEPTION 'approved_public_output_recovery_artifact_required'; END IF;
  SELECT (approval.approval_metadata->>'rehearsalRunId')::uuid
  INTO v_rehearsal_id
  FROM public.sip_fleet_plan_artifact_approvals approval
  WHERE approval.artifact_id=v_artifact.id
    AND approval.content_hash=v_artifact.content_hash;
  IF v_artifact.content->>'gitSha'<>btrim(p_git_sha)
    OR v_artifact.content->>'processorConfigId'<>btrim(p_processor_config_id)
  THEN RAISE EXCEPTION 'public_output_recovery_identity_mismatch'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_public_output_recovery_rehearsals rehearsal
    WHERE rehearsal.id=v_rehearsal_id AND rehearsal.artifact_id=v_artifact.id
      AND rehearsal.content_hash=v_artifact.content_hash
      AND rehearsal.provider_lease_id=p_lease_id AND rehearsal.status='passed'
      AND rehearsal.git_sha=btrim(p_git_sha)
      AND rehearsal.processor_config_id=btrim(p_processor_config_id)
  ) THEN RAISE EXCEPTION 'current_passed_rehearsal_required'; END IF;

  IF jsonb_typeof(v_artifact.content->'instruments')<>'array'
    OR jsonb_array_length(v_artifact.content->'instruments')=0
  THEN RAISE EXCEPTION 'public_output_recovery_instruments_required'; END IF;
  SELECT array_agg((item->>'instrumentV2Id')::uuid ORDER BY item->>'instrumentV2Id')
  INTO v_instrument_ids FROM jsonb_array_elements(v_artifact.content->'instruments') item;
  IF cardinality(v_instrument_ids)<>(SELECT count(DISTINCT id) FROM unnest(v_instrument_ids) id)
  THEN RAISE EXCEPTION 'duplicate_instrument_id'; END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(v_instrument_ids) requested(id)
    LEFT JOIN public.instruments_v2 instrument ON instrument.id=requested.id
    LEFT JOIN public.contributors contributor ON contributor.id=instrument.contributor_id
    WHERE instrument.id IS NULL OR instrument.published IS NOT TRUE
      OR contributor.slug<>btrim(p_contributor_slug)
  ) THEN RAISE EXCEPTION 'published_provider_instruments_required'; END IF;

  v_recovery := jsonb_build_object(
    'artifactId',v_artifact.id,'contentHash',v_artifact.content_hash,
    'rehearsalRunId',v_rehearsal_id,'approved',true,'manifest',v_artifact.content
  );
  v_plan := jsonb_build_object(
    'mode','public_output_recovery','forceRerun',false,'durationPolicy',null,
    'topology','{}'::jsonb,'derivedFill','{}'::jsonb,
    'publicOutputRecovery',v_recovery,'gitSha',btrim(p_git_sha),
    'processorConfigId',btrim(p_processor_config_id),'instrumentV2Ids',to_jsonb(v_instrument_ids)
  );
  v_key := 'public-output-recovery:' || v_artifact.content_hash;
  SELECT id INTO v_existing FROM public.sip_fleet_runs
    WHERE provider_slug=btrim(p_contributor_slug) AND idempotency_key=v_key;
  SELECT jsonb_agg(jsonb_build_object(
    'itemKey','public-output-recovery:'||id::text,'instrumentV2Id',id,
    'payload',jsonb_build_object('mode','public_output_recovery','publicOutputRecovery',v_recovery)
  )) INTO v_items FROM unnest(v_instrument_ids) id;
  v_run_id := public.submit_sip_fleet_run(
    btrim(p_contributor_slug),p_lease_token,v_key,v_lease_owner,v_plan,v_items
  );
  RETURN jsonb_build_object('runId',v_run_id,'created',v_existing IS NULL);
END $$;


ALTER FUNCTION "public"."sip_publish_coordinator_submit_public_output_recovery_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_submit_v1"("p_contributor_slug" "text", "p_instrument_v2_ids" "uuid"[], "p_mode" "text", "p_force_rerun" boolean, "p_duration_policy" "text", "p_topology" "jsonb", "p_derived_fill" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_plan jsonb; v_items jsonb; v_run_id uuid;
BEGIN
  IF coalesce(array_length(p_instrument_v2_ids,1),0)=0 THEN RAISE EXCEPTION 'instrument_ids_required'; END IF;
  IF EXISTS(SELECT 1 FROM unnest(p_instrument_v2_ids) id GROUP BY id HAVING count(*)>1)
    THEN RAISE EXCEPTION 'duplicate_instrument_id'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.sip_fleet_provider_leases WHERE id=p_lease_id
    AND provider_slug=p_contributor_slug AND lease_token=p_lease_token AND lease_expires_at>now())
    THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  v_plan := jsonb_build_object('mode',p_mode,'forceRerun',p_force_rerun,
    'durationPolicy',p_duration_policy,'topology',coalesce(p_topology,'{}'::jsonb),
    'derivedFill',coalesce(p_derived_fill,'{}'::jsonb),'gitSha',p_git_sha,
    'processorConfigId',p_processor_config_id,'instrumentV2Ids',to_jsonb(p_instrument_v2_ids));
  SELECT jsonb_agg(jsonb_build_object('itemKey',id::text,'instrumentV2Id',id,'payload',jsonb_build_object(
    'mode',p_mode,'forceRerun',p_force_rerun,'durationPolicy',p_duration_policy,
    'topology',coalesce(p_topology,'{}'::jsonb),'derivedFill',coalesce(p_derived_fill,'{}'::jsonb))))
  INTO v_items FROM unnest(p_instrument_v2_ids) id;
  v_run_id := public.submit_sip_fleet_run(p_contributor_slug,p_lease_token,
    encode(digest(convert_to(v_plan::text,'UTF8'),'sha256'),'hex'),
    (SELECT lease_owner FROM public.sip_fleet_provider_leases WHERE id=p_lease_id),v_plan,v_items);
  RETURN v_run_id;
END $$;


ALTER FUNCTION "public"."sip_publish_coordinator_submit_v1"("p_contributor_slug" "text", "p_instrument_v2_ids" "uuid"[], "p_mode" "text", "p_force_rerun" boolean, "p_duration_policy" "text", "p_topology" "jsonb", "p_derived_fill" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_submit_v2"("p_contributor_slug" "text", "p_instrument_v2_ids" "uuid"[], "p_mode" "text", "p_force_rerun" boolean, "p_duration_policy" "text", "p_topology" "jsonb", "p_derived_fill" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_plan jsonb;
  v_items jsonb;
  v_base_key text;
  v_selected_key text;
  v_existing_key text;
  v_existing_status text;
  v_existing_is_config_failure boolean := false;
  v_successor_count integer := 0;
  v_lease_owner text;
  v_run_id uuid;
  v_created boolean := false;
BEGIN
  IF coalesce(array_length(p_instrument_v2_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION 'instrument_ids_required';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM unnest(p_instrument_v2_ids) id
    GROUP BY id
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'duplicate_instrument_id';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug), 0));

  SELECT lease.lease_owner
  INTO v_lease_owner
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
    AND lease.provider_slug = p_contributor_slug
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;

  v_plan := jsonb_build_object(
    'mode', p_mode,
    'forceRerun', p_force_rerun,
    'durationPolicy', p_duration_policy,
    'topology', coalesce(p_topology, '{}'::jsonb),
    'derivedFill', coalesce(p_derived_fill, '{}'::jsonb),
    'gitSha', p_git_sha,
    'processorConfigId', p_processor_config_id,
    'instrumentV2Ids', to_jsonb(p_instrument_v2_ids)
  );
  v_base_key := encode(digest(convert_to(v_plan::text, 'UTF8'), 'sha256'), 'hex');

  SELECT run.idempotency_key, run.status,
    EXISTS (
      SELECT 1
      FROM public.sip_fleet_run_items item
      WHERE item.run_id = run.id
        AND (
          item.last_error ILIKE '%This Samples mutation endpoint requires the Studio coordinator%'
          OR item.last_error ILIKE '%Production Samples mutations require the Studio coordinator token%'
          OR item.last_error ILIKE '%sip_publish_coordinator_required%'
          OR item.last_error ILIKE '%sip_publish_coordinator_unconfigured%'
          OR item.last_error ILIKE '%invalid_coordinator_publish_authorization%'
        )
    )
  INTO v_existing_key, v_existing_status, v_existing_is_config_failure
  FROM public.sip_fleet_runs run
  WHERE run.provider_slug = p_contributor_slug
    AND (
      run.idempotency_key = v_base_key
      OR run.idempotency_key LIKE v_base_key || ':config-retry:%'
      OR run.idempotency_key LIKE v_base_key || ':terminal-retry:%'
    )
  ORDER BY run.created_at DESC, run.id DESC
  LIMIT 1;

  IF FOUND THEN
    IF
      v_existing_status = 'canceled'
      OR (v_existing_status = 'failed' AND v_existing_is_config_failure)
    THEN
      SELECT count(*)
      INTO v_successor_count
      FROM public.sip_fleet_runs run
      WHERE run.provider_slug = p_contributor_slug
        AND (
          run.idempotency_key = v_base_key
          OR run.idempotency_key LIKE v_base_key || ':config-retry:%'
          OR run.idempotency_key LIKE v_base_key || ':terminal-retry:%'
        );
      v_selected_key := v_base_key || ':terminal-retry:' || v_successor_count::text;
      v_created := true;
    ELSE
      v_selected_key := v_existing_key;
    END IF;
  ELSE
    v_selected_key := v_base_key;
    v_created := true;
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'itemKey', id::text,
    'instrumentV2Id', id,
    'payload', jsonb_build_object(
      'mode', p_mode,
      'forceRerun', p_force_rerun,
      'durationPolicy', p_duration_policy,
      'topology', coalesce(p_topology, '{}'::jsonb),
      'derivedFill', coalesce(p_derived_fill, '{}'::jsonb)
    )
  ))
  INTO v_items
  FROM unnest(p_instrument_v2_ids) id;

  v_run_id := public.submit_sip_fleet_run(
    p_contributor_slug,
    p_lease_token,
    v_selected_key,
    v_lease_owner,
    v_plan,
    v_items
  );

  RETURN jsonb_build_object('runId', v_run_id, 'created', v_created);
END;
$$;


ALTER FUNCTION "public"."sip_publish_coordinator_submit_v2"("p_contributor_slug" "text", "p_instrument_v2_ids" "uuid"[], "p_mode" "text", "p_force_rerun" boolean, "p_duration_policy" "text", "p_topology" "jsonb", "p_derived_fill" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_validate_durable_canary_v1"("p_instrument_v2_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_suffix text := replace(gen_random_uuid()::text, '-', '');
  v_provider_slug text := '__sip_canary_' || v_suffix;
  v_executor_one text := 'sip-canary-executor-1-' || v_suffix;
  v_executor_two text := 'sip-canary-executor-2-' || v_suffix;
  v_provider_lease_id uuid;
  v_provider_lease_token uuid := gen_random_uuid();
  v_artifact_id uuid;
  v_run_id uuid;
  v_item_id uuid;
  v_first_claim public.sip_fleet_run_items%ROWTYPE;
  v_second_claim public.sip_fleet_run_items%ROWTYPE;
  v_initial_claim_ok boolean := false;
  v_heartbeat_ok boolean := false;
  v_reclaim_ok boolean := false;
  v_stale_heartbeat_rejected boolean := false;
  v_stale_completion_rejected boolean := false;
  v_completion_ok boolean := false;
  v_terminal_state_ok boolean := false;
  v_passed boolean := false;
  v_durable_check_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.instruments_v2 WHERE id = p_instrument_v2_id
  ) THEN
    RAISE EXCEPTION 'canary_instrument_not_found';
  END IF;

  INSERT INTO public.sip_fleet_provider_leases(
    provider_slug, lease_owner, lease_token, lease_expires_at, metadata
  ) VALUES (
    v_provider_slug, 'sip-durable-canary', v_provider_lease_token,
    now() + interval '10 minutes', jsonb_build_object('canary', true)
  ) RETURNING id INTO v_provider_lease_id;

  INSERT INTO public.sip_fleet_plan_artifacts(
    provider_slug, artifact_kind, content_hash, content, created_by
  ) VALUES (
    v_provider_slug, 'durable-canary', v_suffix,
    jsonb_build_object('canary', true, 'instrumentV2Id', p_instrument_v2_id),
    'sip-durable-canary'
  ) RETURNING id INTO v_artifact_id;

  INSERT INTO public.sip_fleet_runs(
    provider_slug, idempotency_key, plan_artifact_id, submitted_by,
    provider_lease_id, provider_lease_token
  ) VALUES (
    v_provider_slug, v_suffix, v_artifact_id, 'sip-durable-canary',
    v_provider_lease_id, v_provider_lease_token
  ) RETURNING id INTO v_run_id;

  INSERT INTO public.sip_fleet_run_items(
    run_id, item_key, instrument_v2_id, payload, max_attempts
  ) VALUES (
    v_run_id, p_instrument_v2_id::text, p_instrument_v2_id,
    jsonb_build_object('canary', true), 2
  ) RETURNING id INTO v_item_id;

  SELECT * INTO v_first_claim
  FROM public.claim_sip_fleet_run_item(
    v_run_id, p_instrument_v2_id, v_executor_one, 'durable-canary-lane-1', 30
  );
  v_initial_claim_ok := v_first_claim.id = v_item_id
    AND v_first_claim.status = 'running'
    AND v_first_claim.attempts = 1
    AND v_first_claim.lease_token IS NOT NULL;

  v_heartbeat_ok := public.heartbeat_sip_fleet_run_item(
    v_item_id, v_executor_one, v_first_claim.lease_token, 30
  );

  -- Exercise expiry deterministically without waiting or changing production
  -- coordinator rows. This update is scoped to the synthetic item above.
  UPDATE public.sip_fleet_run_items
  SET lease_expires_at = now() - interval '1 second'
  WHERE id = v_item_id;

  SELECT * INTO v_second_claim
  FROM public.claim_sip_fleet_run_item(
    v_run_id, p_instrument_v2_id, v_executor_two, 'durable-canary-lane-2', 30
  );
  v_reclaim_ok := v_second_claim.id = v_item_id
    AND v_second_claim.status = 'running'
    AND v_second_claim.attempts = 2
    AND v_second_claim.executor_id = v_executor_two
    AND v_second_claim.lease_token IS NOT NULL
    AND v_second_claim.lease_token IS DISTINCT FROM v_first_claim.lease_token;

  v_stale_heartbeat_rejected := NOT public.heartbeat_sip_fleet_run_item(
    v_item_id, v_executor_one, v_first_claim.lease_token, 30
  );
  v_stale_completion_rejected := NOT public.complete_sip_fleet_run_item(
    v_item_id, v_executor_one, v_first_claim.lease_token, true,
    jsonb_build_object('canary', true, 'stale', true), NULL
  );
  v_completion_ok := public.complete_sip_fleet_run_item(
    v_item_id, v_executor_two, v_second_claim.lease_token, true,
    jsonb_build_object('canary', true), NULL
  );

  SELECT EXISTS (
    SELECT 1
    FROM public.sip_fleet_runs run
    JOIN public.sip_fleet_run_items item ON item.run_id = run.id
    WHERE run.id = v_run_id
      AND run.status = 'completed'
      AND item.id = v_item_id
      AND item.status = 'completed'
      AND item.attempts = 2
      AND item.executor_id IS NULL
      AND item.lease_token IS NULL
      AND item.lease_expires_at IS NULL
  ) INTO v_terminal_state_ok;

  v_passed := v_initial_claim_ok
    AND v_heartbeat_ok
    AND v_reclaim_ok
    AND v_stale_heartbeat_rejected
    AND v_stale_completion_rejected
    AND v_completion_ok
    AND v_terminal_state_ok;

  INSERT INTO public.sip_fleet_durable_canary_checks(
    instrument_v2_id, passed, evidence
  ) VALUES (
    p_instrument_v2_id,
    v_passed,
    jsonb_build_object(
      'initialClaimOk', v_initial_claim_ok,
      'heartbeatOk', v_heartbeat_ok,
      'reclaimOk', v_reclaim_ok,
      'staleHeartbeatRejected', v_stale_heartbeat_rejected,
      'staleCompletionRejected', v_stale_completion_rejected,
      'completionOk', v_completion_ok,
      'terminalStateOk', v_terminal_state_ok
    )
  ) RETURNING id INTO v_durable_check_id;

  DELETE FROM public.sip_fleet_runs WHERE id = v_run_id;
  DELETE FROM public.sip_fleet_plan_artifacts WHERE id = v_artifact_id;
  DELETE FROM public.sip_fleet_executor_leases
    WHERE executor_id IN (v_executor_one, v_executor_two);
  DELETE FROM public.sip_fleet_provider_leases WHERE id = v_provider_lease_id;

  RETURN jsonb_build_object(
    'durableCheckId', v_durable_check_id,
    'passed', v_passed,
    'initialClaimOk', v_initial_claim_ok,
    'heartbeatOk', v_heartbeat_ok,
    'reclaimOk', v_reclaim_ok,
    'staleHeartbeatRejected', v_stale_heartbeat_rejected,
    'staleCompletionRejected', v_stale_completion_rejected,
    'completionOk', v_completion_ok,
    'terminalStateOk', v_terminal_state_ok
  );
EXCEPTION WHEN OTHERS THEN
  DELETE FROM public.sip_fleet_runs WHERE id = v_run_id;
  DELETE FROM public.sip_fleet_plan_artifacts WHERE id = v_artifact_id;
  DELETE FROM public.sip_fleet_executor_leases
    WHERE executor_id IN (v_executor_one, v_executor_two);
  DELETE FROM public.sip_fleet_provider_leases WHERE id = v_provider_lease_id;
  RAISE;
END $$;


ALTER FUNCTION "public"."sip_publish_coordinator_validate_durable_canary_v1"("p_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_coordinator_wait_for_audio_profile_v1"("p_run_id" "uuid", "p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF jsonb_typeof(coalesce(p_result, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'audio_profile_finalization_result_required';
  END IF;
  UPDATE public.sip_fleet_run_items
  SET status = 'waiting_for_audio_profile',
      result_payload = coalesce(p_result, '{}'::jsonb),
      last_error = NULL,
      executor_id = NULL,
      lease_token = NULL,
      lease_expires_at = NULL,
      heartbeat_at = now()
  WHERE id = p_item_id
    AND run_id = p_run_id
    AND status = 'running'
    AND executor_id = p_executor_id
    AND lease_token = p_lease_token
    AND lease_expires_at > now();
  RETURN FOUND;
END $$;


ALTER FUNCTION "public"."sip_publish_coordinator_wait_for_audio_profile_v1"("p_run_id" "uuid", "p_item_id" "uuid", "p_executor_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_fail_unclaimed_run_v1"("p_run_id" "uuid", "p_provider_lease_token" "uuid", "p_error" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_error text := nullif(btrim(p_error), '');
BEGIN
  IF v_error IS NULL THEN RAISE EXCEPTION 'run_failure_error_required'; END IF;

  -- The current, unexpired provider lease fences startup-failure recovery.
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_runs run
    JOIN public.sip_fleet_provider_leases lease
      ON lease.id = run.provider_lease_id
     AND lease.provider_slug = run.provider_slug
    WHERE run.id = p_run_id
      AND run.status IN ('queued', 'running')
      AND run.provider_lease_token = p_provider_lease_token
      AND lease.lease_token = p_provider_lease_token
      AND lease.lease_expires_at > now()
      AND lease.released_at IS NULL
  ) THEN
    RETURN false;
  END IF;

  -- Never terminate work that an executor currently owns.
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_run_items
    WHERE run_id = p_run_id AND status = 'running'
  ) THEN
    RETURN false;
  END IF;

  UPDATE public.sip_fleet_run_items
  SET status = 'failed',
      finished_at = now(),
      last_error = v_error,
      executor_id = NULL,
      lease_token = NULL,
      lease_expires_at = NULL
  WHERE run_id = p_run_id AND status = 'queued';

  UPDATE public.sip_fleet_runs
  SET status = 'failed',
      finished_at = now(),
      result_payload = coalesce(result_payload, '{}'::jsonb)
        || jsonb_build_object('recoveryError', v_error)
  WHERE id = p_run_id
    AND status IN ('queued', 'running')
    AND NOT EXISTS (
      SELECT 1 FROM public.sip_fleet_run_items item
      WHERE item.run_id = p_run_id AND item.status IN ('queued', 'running')
    );

  RETURN FOUND;
END $$;


ALTER FUNCTION "public"."sip_publish_fail_unclaimed_run_v1"("p_run_id" "uuid", "p_provider_lease_token" "uuid", "p_error" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_publish_fail_unclaimed_run_v1"("p_run_id" "uuid", "p_provider_lease_token" "uuid", "p_error" "text") IS 'Fenced terminalization for a coordinator run that failed before any item was claimed.';



CREATE OR REPLACE FUNCTION "public"."sip_publish_fail_versioned_output_prefix_staging_v1"("p_staging_operation_id" "uuid", "p_staging_operation_token" "uuid", "p_failure_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_operation public.sip_versioned_output_prefix_staging_operations%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_operation
  FROM public.sip_versioned_output_prefix_staging_operations operation
  WHERE operation.id=p_staging_operation_id
    AND operation.operation_token=p_staging_operation_token
  FOR UPDATE;
  IF v_operation.status <> 'running'
  THEN RETURN to_jsonb(v_operation) || jsonb_build_object('idempotent',true); END IF;
  PERFORM set_config('app.sip_versioned_output_prefix_operation_authorized','on',true);
  UPDATE public.sip_versioned_output_prefix_staging_operations
  SET status='ambiguous',failure_code=coalesce(nullif(btrim(p_failure_code),''),
    'versioned_output_prefix_staging_response_ambiguous'),finished_at=clock_timestamp()
  WHERE id=v_operation.id RETURNING * INTO v_operation;
  RETURN to_jsonb(v_operation) || jsonb_build_object('idempotent',false);
END $$;


ALTER FUNCTION "public"."sip_publish_fail_versioned_output_prefix_staging_v1"("p_staging_operation_id" "uuid", "p_staging_operation_token" "uuid", "p_failure_code" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_fleet_lane_heartbeats" (
    "lane_id" "text" NOT NULL,
    "url" "text" NOT NULL,
    "healthy" boolean DEFAULT false NOT NULL,
    "git_sha" "text",
    "processor_config_id" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "heartbeat_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sip_fleet_lane_heartbeats_lane_id_check" CHECK (("btrim"("lane_id") <> ''::"text")),
    CONSTRAINT "sip_fleet_lane_heartbeats_metadata_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "sip_fleet_lane_heartbeats_url_check" CHECK (("btrim"("url") <> ''::"text"))
);


ALTER TABLE "public"."sip_fleet_lane_heartbeats" OWNER TO "postgres";


COMMENT ON TABLE "public"."sip_fleet_lane_heartbeats" IS 'Durable Samples publish-lane readiness heartbeats; callers determine staleness from heartbeat_at.';



CREATE OR REPLACE FUNCTION "public"."sip_publish_lane_heartbeat_v1"("p_lane_id" "text", "p_url" "text", "p_healthy" boolean, "p_git_sha" "text", "p_processor_config_id" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."sip_fleet_lane_heartbeats"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_lane public.sip_fleet_lane_heartbeats%ROWTYPE;
BEGIN
  IF nullif(btrim(p_lane_id), '') IS NULL OR nullif(btrim(p_url), '') IS NULL THEN
    RAISE EXCEPTION 'lane_id_and_url_required';
  END IF;
  IF jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'lane_metadata_must_be_object';
  END IF;

  INSERT INTO public.sip_fleet_lane_heartbeats(
    lane_id, url, healthy, git_sha, processor_config_id, metadata, heartbeat_at
  ) VALUES (
    btrim(p_lane_id), btrim(p_url), coalesce(p_healthy, false),
    nullif(btrim(p_git_sha), ''), nullif(btrim(p_processor_config_id), ''),
    coalesce(p_metadata, '{}'::jsonb), now()
  )
  ON CONFLICT (lane_id) DO UPDATE SET
    url = EXCLUDED.url,
    healthy = EXCLUDED.healthy,
    git_sha = EXCLUDED.git_sha,
    processor_config_id = EXCLUDED.processor_config_id,
    metadata = EXCLUDED.metadata,
    heartbeat_at = now()
  RETURNING * INTO v_lane;

  RETURN v_lane;
END $$;


ALTER FUNCTION "public"."sip_publish_lane_heartbeat_v1"("p_lane_id" "text", "p_url" "text", "p_healthy" boolean, "p_git_sha" "text", "p_processor_config_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_mark_versioned_prefix_remote_write_v1"("p_staging_operation_id" "uuid", "p_staging_operation_token" "uuid", "p_preflight_receipt_id" "uuid", "p_expected_preflight_receipt_hash" "text", "p_write_request_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_operation public.sip_versioned_output_prefix_staging_operations%ROWTYPE;
  v_preflight public.sip_versioned_output_prefix_preflight_receipts%ROWTYPE;
  v_existing public.sip_versioned_output_prefix_remote_write_phase_receipts%ROWTYPE;
  v_hash text;
BEGIN
  SELECT * INTO STRICT v_operation FROM public.sip_versioned_output_prefix_staging_operations
  WHERE id=p_staging_operation_id AND operation_token=p_staging_operation_token
    AND status='running' AND preflight_receipt_id=p_preflight_receipt_id;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_operation.provider_slug,0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:'||v_operation.instrument_v2_id::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-fleet-executor-admission',0));
  SELECT * INTO STRICT v_operation FROM public.sip_versioned_output_prefix_staging_operations
  WHERE id=p_staging_operation_id AND operation_token=p_staging_operation_token
    AND status='running' AND preflight_receipt_id=p_preflight_receipt_id FOR UPDATE;
  PERFORM 1 FROM public.sip_fleet_provider_leases lease
  WHERE lease.id=p_lease_id AND lease.provider_slug=v_operation.provider_slug
    AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
    AND lease.lease_expires_at>clock_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'versioned_output_prefix_provider_lease_drift'; END IF;
  SELECT * INTO STRICT v_preflight FROM public.sip_versioned_output_prefix_preflight_receipts
  WHERE id=p_preflight_receipt_id
    AND preflight_receipt_hash=btrim(p_expected_preflight_receipt_hash)
    AND provider_lease_id=p_lease_id;
  v_hash:=encode(digest(convert_to(jsonb_build_object(
    'stagingOperationId',v_operation.id,'preflightReceiptId',v_preflight.id,
    'preflightReceiptHash',v_preflight.preflight_receipt_hash,
    'providerLeaseId',p_lease_id,'writeRequestHash',btrim(p_write_request_hash)
  )::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.sip_versioned_output_prefix_remote_write_phase_receipts(
    staging_operation_id,preflight_receipt_id,provider_lease_id,
    write_request_hash,phase_receipt_hash
  ) VALUES (v_operation.id,v_preflight.id,p_lease_id,btrim(p_write_request_hash),v_hash)
  ON CONFLICT (staging_operation_id) DO NOTHING RETURNING * INTO v_existing;
  IF v_existing.id IS NULL THEN
    SELECT * INTO STRICT v_existing FROM public.sip_versioned_output_prefix_remote_write_phase_receipts
    WHERE staging_operation_id=v_operation.id;
    IF v_existing.phase_receipt_hash IS DISTINCT FROM v_hash
    THEN RAISE EXCEPTION 'versioned_output_prefix_remote_write_phase_drift'; END IF;
    RETURN to_jsonb(v_existing)||jsonb_build_object('idempotent',true);
  END IF;
  RETURN to_jsonb(v_existing)||jsonb_build_object('idempotent',false);
END $$;


ALTER FUNCTION "public"."sip_publish_mark_versioned_prefix_remote_write_v1"("p_staging_operation_id" "uuid", "p_staging_operation_token" "uuid", "p_preflight_receipt_id" "uuid", "p_expected_preflight_receipt_hash" "text", "p_write_request_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_materialize_instrument_summaries_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer, "p_rehearsal_run_id" "uuid" DEFAULT NULL::"uuid", "p_projection_hash" "text" DEFAULT NULL::"text", "p_object_identity_hash" "text" DEFAULT NULL::"text", "p_expected_construct_count" integer DEFAULT NULL::integer, "p_expected_source_count" integer DEFAULT NULL::integer, "p_expected_target_count" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_content jsonb;
  v_expected_count integer;
  v_updated_count integer;
  v_live_construct_count integer;
  v_live_source_count integer;
  v_run_id uuid;
  v_hash text;
  v_rehearsal public.sip_anchor_object_verification_rehearsals%ROWTYPE;
  v_requires_anchor_verification boolean;
  v_existing_result jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;

  SELECT artifact.content, artifact.content_hash
  INTO v_content, v_hash
  FROM public.sip_fleet_plan_artifacts artifact
  JOIN public.sip_fleet_plan_artifact_approvals approval
    ON approval.artifact_id = artifact.id
   AND approval.content_hash = artifact.content_hash
  WHERE artifact.id = p_artifact_id
    AND artifact.provider_slug = btrim(p_contributor_slug)
    AND artifact.artifact_kind = 'instrument-summary-materialization';
  IF v_content IS NULL THEN
    RAISE EXCEPTION 'approved_summary_artifact_required';
  END IF;
  IF jsonb_typeof(v_content->'instrumentV2Ids') <> 'array'
    OR jsonb_array_length(v_content->'instrumentV2Ids') = 0
  THEN
    RAISE EXCEPTION 'summary_instrument_ids_required';
  END IF;

  SELECT count(DISTINCT value), count(*)
  INTO v_expected_count, v_updated_count
  FROM jsonb_array_elements_text(v_content->'instrumentV2Ids');
  IF v_expected_count <> v_updated_count THEN
    RAISE EXCEPTION 'duplicate_instrument_id';
  END IF;
  IF p_expected_count IS NULL
    OR p_expected_count < 1
    OR p_expected_count <> v_expected_count
  THEN
    RAISE EXCEPTION 'summary_expected_count_mismatch';
  END IF;

  SELECT coalesce((
      v_content->'anchorObjectVerification'->>'required'
    )::boolean, false)
    AND EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(
        v_content->'instrumentV2Ids'
      ) requested(value)
      JOIN public.instruments_v2 instrument
        ON instrument.id = requested.value::uuid
      WHERE instrument.published IS TRUE
        AND instrument.sampled_midi_notes IS NULL
  )
  INTO v_requires_anchor_verification;

  SELECT run.id, run.result_payload
  INTO v_run_id, v_existing_result
  FROM public.sip_fleet_runs run
  WHERE run.provider_slug = btrim(p_contributor_slug)
    AND run.idempotency_key = 'instrument-summary:' || v_hash
    AND run.plan_artifact_id = p_artifact_id
    AND run.status = 'completed';
  IF v_run_id IS NOT NULL THEN
    IF coalesce(
        (v_existing_result->>'anchorObjectVerification')::boolean,
        false
      ) AND (
        p_rehearsal_run_id IS NULL
        OR v_existing_result->>'anchorObjectVerificationRehearsalId'
          <> p_rehearsal_run_id::text
        OR v_existing_result->>'projectionHash' <> p_projection_hash
        OR v_existing_result->>'objectIdentityHash' <> p_object_identity_hash
        OR (v_existing_result->>'constructCount')::integer
          <> p_expected_construct_count
        OR (v_existing_result->>'sourceCount')::integer
          <> p_expected_source_count
        OR (v_existing_result->>'targetCount')::integer
          <> p_expected_target_count
      )
    THEN
      RAISE EXCEPTION 'anchor_object_verification_replay_mismatch';
    END IF;
    RETURN jsonb_build_object(
      'artifactId', p_artifact_id,
      'runId', v_run_id,
      'contentHash', v_hash,
      'instrumentCount', v_expected_count,
      'constructCount', (v_existing_result->>'constructCount')::integer,
      'sourceCount', (v_existing_result->>'sourceCount')::integer,
      'targetCount', v_existing_result->'targetCount',
      'anchorObjectVerification',
        coalesce(
          (v_existing_result->>'anchorObjectVerification')::boolean,
          false
        ),
      'projectionHash', v_existing_result->'projectionHash',
      'objectIdentityHash', v_existing_result->'objectIdentityHash',
      'rehearsalRunId',
        v_existing_result->'anchorObjectVerificationRehearsalId',
      'idempotent', true
    );
  END IF;

  -- Serialize every instrument in a stable order before rechecking mutable
  -- readiness, constructs, and sources.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('instrument-summary:' || requested.value, 0)
  )
  FROM jsonb_array_elements_text(v_content->'instrumentV2Ids') requested(value)
  ORDER BY requested.value;

  PERFORM instrument.id
  FROM jsonb_array_elements_text(v_content->'instrumentV2Ids') requested(value)
  JOIN public.instruments_v2 instrument
    ON instrument.id = requested.value::uuid
  ORDER BY instrument.id
  FOR UPDATE OF instrument;

  PERFORM construct.id
  FROM jsonb_array_elements_text(v_content->'instrumentV2Ids') requested(value)
  JOIN public.sample_path_constructs construct
    ON construct.instrument_v2_id = requested.value::uuid
  ORDER BY construct.id
  FOR UPDATE OF construct;

  PERFORM source.id
  FROM jsonb_array_elements_text(v_content->'instrumentV2Ids') requested(value)
  JOIN public.sample_path_constructs construct
    ON construct.instrument_v2_id = requested.value::uuid
  JOIN public.samples_original_paths source
    ON source.id = construct.sample_original_path_id
  ORDER BY source.id
  FOR UPDATE OF source;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(v_content->'instrumentV2Ids') requested(value)
    LEFT JOIN public.instruments_v2 instrument
      ON instrument.id = requested.value::uuid
    LEFT JOIN public.contributors contributor
      ON contributor.id = instrument.contributor_id
    WHERE instrument.id IS NULL
      OR contributor.slug <> btrim(p_contributor_slug)
  ) THEN
    RAISE EXCEPTION 'summary_instrument_not_owned_by_provider';
  END IF;
  IF jsonb_typeof(v_content->'readinessSnapshots') <> 'array'
    OR jsonb_array_length(v_content->'readinessSnapshots') <> v_expected_count
  THEN
    RAISE EXCEPTION 'summary_readiness_snapshots_required';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(v_content->'instrumentV2Ids') requested(value)
    LEFT JOIN jsonb_array_elements(
      v_content->'readinessSnapshots'
    ) snapshot(value)
      ON snapshot.value->>'instrumentV2Id' = requested.value
    WHERE snapshot.value IS NULL
      OR coalesce(snapshot.value->>'snapshotSha256', '')
        !~ '^[0-9a-f]{64}$'
      OR NOT public.is_current_instrument_v2_readiness_snapshot_v2(
        requested.value::uuid,
        snapshot.value->>'snapshotSha256'
      )
  ) THEN
    RAISE EXCEPTION 'summary_readiness_snapshot_stale';
  END IF;

  SELECT count(*), count(DISTINCT source.s3_path)
  INTO v_live_construct_count, v_live_source_count
  FROM jsonb_array_elements_text(v_content->'instrumentV2Ids') requested(value)
  JOIN public.sample_path_constructs construct
    ON construct.instrument_v2_id = requested.value::uuid
  JOIN public.samples_original_paths source
    ON source.id = construct.sample_original_path_id;

  IF v_requires_anchor_verification THEN
    IF p_rehearsal_run_id IS NULL
      OR NOT EXISTS (
        SELECT 1
        FROM public.sip_fleet_plan_artifact_approvals approval
        WHERE approval.artifact_id = p_artifact_id
          AND approval.content_hash = v_hash
          AND approval.approval_metadata->>'rehearsalRunId' =
            p_rehearsal_run_id::text
      )
    THEN
      RAISE EXCEPTION 'approved_anchor_object_verification_required';
    END IF;

    SELECT rehearsal.*
    INTO v_rehearsal
    FROM public.sip_anchor_object_verification_rehearsals rehearsal
    WHERE rehearsal.id = p_rehearsal_run_id
      AND rehearsal.artifact_id = p_artifact_id
      AND rehearsal.content_hash = v_hash
      AND rehearsal.provider_slug = btrim(p_contributor_slug)
      AND rehearsal.provider_lease_id = p_lease_id
      AND rehearsal.provider_lease_token = p_lease_token
      AND rehearsal.status = 'passed'
      AND rehearsal.completed_at >=
        clock_timestamp() - interval '15 minutes'
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'current_passed_anchor_object_verification_required';
    END IF;

    IF coalesce(p_projection_hash, '') !~ '^[0-9a-f]{64}$'
      OR coalesce(p_object_identity_hash, '') !~ '^[0-9a-f]{64}$'
      OR p_projection_hash <> v_rehearsal.projection_hash
      OR p_object_identity_hash <> v_rehearsal.object_identity_hash
      OR p_expected_construct_count <> v_rehearsal.construct_count
      OR p_expected_source_count <> v_rehearsal.source_count
      OR p_expected_target_count <> v_rehearsal.target_count
      OR p_expected_target_count <> p_expected_construct_count * 9
    THEN
      RAISE EXCEPTION 'anchor_object_verification_apply_mismatch';
    END IF;
    IF v_live_construct_count <> p_expected_construct_count
      OR v_live_source_count <> p_expected_source_count
    THEN
      RAISE EXCEPTION 'anchor_object_verification_scope_drift';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(v_content->'instrumentV2Ids') requested(value)
    JOIN public.instruments_v2 instrument
      ON instrument.id = requested.value::uuid
    JOIN LATERAL (
      SELECT array_agg(grouped.filename ORDER BY grouped.pitch_content) AS refs
      FROM (
        SELECT
          coalesce(nullif(btrim(c.pitch_content), ''), '0') AS pitch_content,
          min(nullif(btrim(c.filename), '')) AS filename
        FROM public.sample_path_constructs c
        WHERE c.instrument_v2_id = requested.value::uuid
        GROUP BY coalesce(nullif(btrim(c.pitch_content), ''), '0')
        HAVING count(DISTINCT nullif(btrim(c.filename), '')) = 1
      ) grouped
    ) summary ON true
    WHERE CASE
        WHEN jsonb_typeof(instrument.pitch_contents) = 'array'
        THEN jsonb_array_length(instrument.pitch_contents) > 0
        ELSE false
      END
      AND CASE
        WHEN jsonb_typeof(instrument.velocity_layers) = 'object'
        THEN instrument.velocity_layers <> '{}'::jsonb
        ELSE false
      END
      AND CASE
        WHEN jsonb_typeof(instrument.round_robins) = 'object'
        THEN instrument.round_robins <> '{}'::jsonb
        ELSE false
      END
      AND CASE
        WHEN jsonb_typeof(instrument.mic_positions) = 'object'
        THEN instrument.mic_positions <> '{}'::jsonb
        ELSE false
      END
      AND coalesce(array_length(instrument.file_name_references, 1), 0) > 0
      AND (
        summary.refs IS NULL
        OR instrument.file_name_references IS NOT DISTINCT FROM summary.refs
      )
      AND instrument.sampled_midi_notes IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'summary_instrument_no_longer_requires_materialization';
  END IF;

  IF v_requires_anchor_verification THEN
    INSERT INTO public.sip_anchor_object_verification_evidence (
    artifact_id,
    rehearsal_id,
    instrument_v2_id,
    readiness_snapshot_sha256,
    projection_hash,
    object_identity_hash,
    construct_count,
    source_count,
    target_count,
    authorizing_xid
  )
    SELECT
    p_artifact_id,
    p_rehearsal_run_id,
    requested.value::uuid,
    snapshot.value->>'snapshotSha256',
    p_projection_hash,
    p_object_identity_hash,
    p_expected_construct_count,
    p_expected_source_count,
    p_expected_target_count,
    txid_current()
    FROM jsonb_array_elements_text(
      v_content->'instrumentV2Ids'
    ) requested(value)
    JOIN jsonb_array_elements(v_content->'readinessSnapshots') snapshot(value)
      ON snapshot.value->>'instrumentV2Id' = requested.value;
  END IF;

  SELECT public.refresh_instrument_v2_axis_summaries_v1(
    ARRAY(
      SELECT value::uuid
      FROM jsonb_array_elements_text(v_content->'instrumentV2Ids')
    )
  ) INTO v_updated_count;
  IF v_updated_count <> v_expected_count THEN
    RAISE EXCEPTION 'summary_construct_rows_required';
  END IF;

  INSERT INTO public.sip_fleet_runs (
    provider_slug,
    idempotency_key,
    plan_artifact_id,
    submitted_by,
    provider_lease_id,
    provider_lease_token,
    status,
    started_at,
    finished_at,
    result_payload
  ) VALUES (
    btrim(p_contributor_slug),
    'instrument-summary:' || v_hash,
    p_artifact_id,
    (
      SELECT lease_owner
      FROM public.sip_fleet_provider_leases
      WHERE id = p_lease_id
    ),
    p_lease_id,
    p_lease_token,
    'completed',
    now(),
    now(),
    jsonb_build_object(
      'operation', 'instrument-summary-materialization',
      'instrumentCount', v_updated_count,
      'constructCount', v_live_construct_count,
      'sourceCount', v_live_source_count,
      'targetCount', CASE
        WHEN v_requires_anchor_verification THEN p_expected_target_count
        ELSE NULL
      END,
      'anchorObjectVerification', v_requires_anchor_verification,
      'projectionHash', CASE
        WHEN v_requires_anchor_verification THEN p_projection_hash
        ELSE NULL
      END,
      'objectIdentityHash', CASE
        WHEN v_requires_anchor_verification THEN p_object_identity_hash
        ELSE NULL
      END,
      'anchorObjectVerificationRehearsalId', CASE
        WHEN v_requires_anchor_verification THEN p_rehearsal_run_id
        ELSE NULL
      END
    )
  )
  ON CONFLICT (provider_slug, idempotency_key) DO UPDATE SET
    plan_artifact_id = EXCLUDED.plan_artifact_id,
    submitted_by = EXCLUDED.submitted_by,
    provider_lease_id = EXCLUDED.provider_lease_id,
    provider_lease_token = EXCLUDED.provider_lease_token,
    status = EXCLUDED.status,
    started_at = EXCLUDED.started_at,
    finished_at = EXCLUDED.finished_at,
    result_payload = EXCLUDED.result_payload,
    updated_at = now()
  RETURNING id INTO v_run_id;

  INSERT INTO public.sip_fleet_run_items (
    run_id,
    item_key,
    instrument_v2_id,
    status,
    started_at,
    finished_at,
    result_payload
  )
  SELECT
    v_run_id,
    'instrument-summary:' || value,
    value::uuid,
    'completed',
    now(),
    now(),
    jsonb_build_object(
      'operation', 'instrument-summary-materialization',
      'anchorObjectVerification', v_requires_anchor_verification,
      'anchorObjectVerificationRehearsalId', CASE
        WHEN v_requires_anchor_verification THEN p_rehearsal_run_id
        ELSE NULL
      END
    )
  FROM jsonb_array_elements_text(v_content->'instrumentV2Ids')
  ON CONFLICT (run_id, item_key) DO NOTHING;

  RETURN jsonb_build_object(
    'artifactId', p_artifact_id,
    'runId', v_run_id,
    'contentHash', v_hash,
    'instrumentCount', v_updated_count,
    'constructCount', v_live_construct_count,
    'sourceCount', v_live_source_count,
    'targetCount', CASE
      WHEN v_requires_anchor_verification THEN p_expected_target_count
      ELSE NULL
    END,
    'anchorObjectVerification', v_requires_anchor_verification,
    'projectionHash', CASE
      WHEN v_requires_anchor_verification THEN p_projection_hash
      ELSE NULL
    END,
    'objectIdentityHash', CASE
      WHEN v_requires_anchor_verification THEN p_object_identity_hash
      ELSE NULL
    END,
    'rehearsalRunId', CASE
      WHEN v_requires_anchor_verification THEN p_rehearsal_run_id
      ELSE NULL
    END,
    'materializedAt', now()
  );
END;
$_$;


ALTER FUNCTION "public"."sip_publish_materialize_instrument_summaries_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer, "p_rehearsal_run_id" "uuid", "p_projection_hash" "text", "p_object_identity_hash" "text", "p_expected_construct_count" integer, "p_expected_source_count" integer, "p_expected_target_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_operator_begin_v1"("p_contributor_slug" "text", "p_owner_id" "text", "p_lease_seconds" integer DEFAULT 900) RETURNS TABLE("lease_id" "uuid", "lease_token" "uuid", "lease_expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  RETURN QUERY
  SELECT lease.id, lease.lease_token, lease.lease_expires_at
  FROM public.acquire_sip_fleet_provider_lease(
    p_contributor_slug, p_owner_id, p_lease_seconds, '{}'::jsonb
  ) lease;
END;
$$;


ALTER FUNCTION "public"."sip_publish_operator_begin_v1"("p_contributor_slug" "text", "p_owner_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_operator_finish_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug),0));
  UPDATE public.sip_fleet_provider_leases lease SET released_at=now(),lease_expires_at=now()
  WHERE lease.provider_slug=p_contributor_slug AND lease.id=p_lease_id AND lease.lease_token=p_lease_token
    AND NOT EXISTS(SELECT 1 FROM public.sip_fleet_runs run JOIN public.sip_fleet_run_items item ON item.run_id=run.id WHERE run.provider_slug=p_contributor_slug AND run.status IN('queued','running') AND item.status IN('queued','running'));
  RETURN FOUND;
END $$;


ALTER FUNCTION "public"."sip_publish_operator_finish_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_orphan_upload_status_snapshot_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH target AS (
    SELECT instrument.*
    FROM public.instruments_v2 instrument
    JOIN public.contributors contributor
      ON contributor.id = instrument.contributor_id
     AND contributor.slug = btrim(p_contributor_slug)
    WHERE instrument.id = p_instrument_v2_id
  ), construct_snapshot AS (
    SELECT
      count(*)::integer AS construct_count,
      encode(digest(convert_to(
        coalesce(jsonb_agg(to_jsonb(construct) ORDER BY construct.id), '[]'::jsonb)::text,
        'UTF8'
      ), 'sha256'), 'hex') AS construct_snapshot_hash
    FROM public.sample_path_constructs construct
    WHERE construct.instrument_v2_id = p_instrument_v2_id
  ), source_snapshot AS (
    SELECT encode(digest(convert_to(
      coalesce(jsonb_agg(to_jsonb(source) ORDER BY source.id), '[]'::jsonb)::text,
      'UTF8'
    ), 'sha256'), 'hex') AS source_snapshot_hash
    FROM public.samples_original_paths source
    WHERE source.id IN (
      SELECT construct.sample_original_path_id
      FROM public.sample_path_constructs construct
      WHERE construct.instrument_v2_id = p_instrument_v2_id
        AND construct.sample_original_path_id IS NOT NULL
    )
  )
  SELECT jsonb_build_object(
    'schemaVersion', 1,
    'providerSlug', btrim(p_contributor_slug),
    'instrumentV2Id', p_instrument_v2_id,
    'instrumentPublished', instrument.published,
    'instrumentSnapshotHash', encode(digest(convert_to(to_jsonb(instrument)::text, 'UTF8'), 'sha256'), 'hex'),
    'constructCount', construct_snapshot.construct_count,
    'constructSnapshotHash', construct_snapshot.construct_snapshot_hash,
    'sourceSnapshotHash', source_snapshot.source_snapshot_hash,
    'control', to_jsonb(upload_status)
  )
  FROM target instrument
  JOIN public.instrument_v2_upload_status upload_status
    ON upload_status.instrument_v2_id = instrument.id
  CROSS JOIN construct_snapshot
  CROSS JOIN source_snapshot;
$$;


ALTER FUNCTION "public"."sip_publish_orphan_upload_status_snapshot_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_fleet_plan_artifact_approvals" (
    "artifact_id" "uuid" NOT NULL,
    "content_hash" "text" NOT NULL,
    "approved_by" "text" NOT NULL,
    "approval_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "approved_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sip_fleet_plan_artifact_approvals_approval_metadata_check" CHECK (("jsonb_typeof"("approval_metadata") = 'object'::"text")),
    CONSTRAINT "sip_fleet_plan_artifact_approvals_approved_by_check" CHECK (("btrim"("approved_by") <> ''::"text")),
    CONSTRAINT "sip_fleet_plan_artifact_approvals_content_hash_check" CHECK (("btrim"("content_hash") <> ''::"text"))
);


ALTER TABLE "public"."sip_fleet_plan_artifact_approvals" OWNER TO "postgres";


COMMENT ON TABLE "public"."sip_fleet_plan_artifact_approvals" IS 'Immutable approval binding for the exact hash of a coordinator plan artifact.';



CREATE OR REPLACE FUNCTION "public"."sip_publish_plan_artifact_approve_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_approved_by" "text", "p_rehearsal_run_id" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "public"."sip_fleet_plan_artifact_approvals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_approval public.sip_fleet_plan_artifact_approvals%ROWTYPE;
  v_artifact_kind text;
  v_rehearsal_uuid uuid;
  v_operation_count integer;
  v_instrument_count integer;
  v_has_published_summary boolean;
BEGIN
  IF nullif(btrim(p_expected_content_hash), '') IS NULL
    OR nullif(btrim(p_approved_by), '') IS NULL
    OR nullif(btrim(p_rehearsal_run_id), '') IS NULL
  THEN
    RAISE EXCEPTION 'approval_identity_required';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;

  SELECT artifact.artifact_kind
  INTO v_artifact_kind
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = p_artifact_id
    AND artifact.provider_slug = btrim(p_contributor_slug)
    AND artifact.content_hash = btrim(p_expected_content_hash);
  IF v_artifact_kind IS NULL THEN
    RAISE EXCEPTION 'artifact_not_found';
  END IF;

  IF v_artifact_kind = 'public-output-recovery-v1' THEN
    v_rehearsal_uuid := p_rehearsal_run_id::uuid;
    IF NOT EXISTS (
      SELECT 1
      FROM public.sip_public_output_recovery_rehearsals rehearsal
      WHERE rehearsal.id = v_rehearsal_uuid
        AND rehearsal.artifact_id = p_artifact_id
        AND rehearsal.content_hash = btrim(p_expected_content_hash)
        AND rehearsal.provider_slug = btrim(p_contributor_slug)
        AND rehearsal.provider_lease_id = p_lease_id
        AND rehearsal.status = 'passed'
    ) THEN
      RAISE EXCEPTION 'passed_public_output_recovery_rehearsal_required';
    END IF;
  END IF;

  IF coalesce(
    (
      SELECT content->'approval'->>'rehearsalRunId'
      FROM public.sip_fleet_plan_artifacts
      WHERE id = p_artifact_id
    ),
    btrim(p_rehearsal_run_id)
  ) <> btrim(p_rehearsal_run_id)
  THEN
    RAISE EXCEPTION 'artifact_rehearsal_mismatch';
  END IF;

  IF v_artifact_kind = 'derived-grid-fill-v1' THEN
    IF btrim(p_rehearsal_run_id)
      !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    THEN
      RAISE EXCEPTION 'derived_grid_fill_rehearsal_required';
    END IF;
    SELECT
      count(*),
      count(DISTINCT lower(operation->>'instrumentV2Id'))
    INTO v_operation_count, v_instrument_count
    FROM jsonb_array_elements(coalesce(
      (
        SELECT content->'operations'
        FROM public.sip_fleet_plan_artifacts
        WHERE id = p_artifact_id
      ),
      '[]'::jsonb
    )) operation;
    IF NOT EXISTS (
      SELECT 1
      FROM public.sip_fleet_runs rehearsal
      WHERE rehearsal.id = btrim(p_rehearsal_run_id)::uuid
        AND rehearsal.provider_slug = btrim(p_contributor_slug)
        AND rehearsal.plan_artifact_id = p_artifact_id
        AND rehearsal.provider_lease_id = p_lease_id
        AND rehearsal.provider_lease_token = p_lease_token
        AND rehearsal.status = 'completed'
        AND rehearsal.result_payload->>'operation' =
          'derived-grid-fill-rehearsal'
        AND rehearsal.result_payload->>'contentHash' =
          btrim(p_expected_content_hash)
        AND rehearsal.result_payload->>'operationCount' =
          v_operation_count::text
        AND rehearsal.result_payload->>'instrumentCount' =
          v_instrument_count::text
    ) THEN
      RAISE EXCEPTION 'derived_grid_fill_rehearsal_required';
    END IF;
  END IF;

  IF v_artifact_kind = 'instrument-summary-materialization' THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.sip_fleet_plan_artifacts artifact
      CROSS JOIN LATERAL jsonb_array_elements_text(
        coalesce(artifact.content->'instrumentV2Ids', '[]'::jsonb)
      ) requested(value)
      JOIN public.instruments_v2 instrument
        ON instrument.id = requested.value::uuid
      WHERE artifact.id = p_artifact_id
        AND coalesce((
          artifact.content->'anchorObjectVerification'->>'required'
        )::boolean, false) IS TRUE
        AND instrument.published IS TRUE
        AND instrument.sampled_midi_notes IS NULL
    ) INTO v_has_published_summary;
    IF v_has_published_summary THEN
      IF btrim(p_rehearsal_run_id)
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR NOT EXISTS (
          SELECT 1
          FROM public.sip_anchor_object_verification_rehearsals rehearsal
          WHERE rehearsal.id = btrim(p_rehearsal_run_id)::uuid
            AND rehearsal.artifact_id = p_artifact_id
            AND rehearsal.content_hash = btrim(p_expected_content_hash)
            AND rehearsal.provider_slug = btrim(p_contributor_slug)
            AND rehearsal.provider_lease_id = p_lease_id
            AND rehearsal.provider_lease_token = p_lease_token
            AND rehearsal.status = 'passed'
            AND rehearsal.completed_at >=
              clock_timestamp() - interval '15 minutes'
        )
      THEN
        RAISE EXCEPTION 'passed_anchor_object_verification_required';
      END IF;
    END IF;
  END IF;

  INSERT INTO public.sip_fleet_plan_artifact_approvals (
    artifact_id,
    content_hash,
    approved_by,
    approval_metadata
  ) VALUES (
    p_artifact_id,
    btrim(p_expected_content_hash),
    btrim(p_approved_by),
    jsonb_build_object('rehearsalRunId', btrim(p_rehearsal_run_id))
  )
  ON CONFLICT (artifact_id) DO NOTHING
  RETURNING * INTO v_approval;

  IF v_approval.artifact_id IS NULL THEN
    SELECT approval.*
    INTO STRICT v_approval
    FROM public.sip_fleet_plan_artifact_approvals approval
    WHERE approval.artifact_id = p_artifact_id;
    IF v_approval.content_hash <> btrim(p_expected_content_hash)
      OR v_approval.approved_by <> btrim(p_approved_by)
      OR v_approval.approval_metadata <>
        jsonb_build_object('rehearsalRunId', btrim(p_rehearsal_run_id))
    THEN
      RAISE EXCEPTION 'artifact_approval_payload_mismatch';
    END IF;
  END IF;

  RETURN v_approval;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_plan_artifact_approve_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_approved_by" "text", "p_rehearsal_run_id" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_fleet_plan_artifacts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_slug" "text" NOT NULL,
    "artifact_kind" "text" DEFAULT 'publish-plan'::"text" NOT NULL,
    "content_hash" "text" NOT NULL,
    "content" "jsonb" NOT NULL,
    "created_by" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sip_fleet_plan_artifacts_artifact_kind_check" CHECK (("btrim"("artifact_kind") <> ''::"text")),
    CONSTRAINT "sip_fleet_plan_artifacts_content_check" CHECK (("jsonb_typeof"("content") = ANY (ARRAY['object'::"text", 'array'::"text"]))),
    CONSTRAINT "sip_fleet_plan_artifacts_content_hash_check" CHECK (("btrim"("content_hash") <> ''::"text")),
    CONSTRAINT "sip_fleet_plan_artifacts_created_by_check" CHECK (("btrim"("created_by") <> ''::"text")),
    CONSTRAINT "sip_fleet_plan_artifacts_provider_slug_check" CHECK (("btrim"("provider_slug") <> ''::"text"))
);


ALTER TABLE "public"."sip_fleet_plan_artifacts" OWNER TO "postgres";


COMMENT ON TABLE "public"."sip_fleet_plan_artifacts" IS 'Immutable-by-hash submitted fleet plans retained for audit and replay.';



CREATE OR REPLACE FUNCTION "public"."sip_publish_plan_artifact_upload_v1"("p_contributor_slug" "text", "p_artifact_kind" "text", "p_content" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "public"."sip_fleet_plan_artifacts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_hash text;
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
BEGIN
  IF nullif(btrim(p_contributor_slug), '') IS NULL
    OR nullif(btrim(p_artifact_kind), '') IS NULL
    OR jsonb_typeof(p_content) NOT IN ('object', 'array')
  THEN RAISE EXCEPTION 'plan_identity_and_content_required'; END IF;

  IF btrim(p_artifact_kind) NOT IN (
    'grid-topology-normalization-v1',
    'derived-grid-fill-v1',
    'instrument-summary-materialization',
    'parent-pitchless-projection-v1',
    'public-output-recovery-v1'
  ) THEN RAISE EXCEPTION 'unsupported_plan_artifact_kind'; END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;

  v_hash := encode(
    extensions.digest(convert_to(p_content::text, 'UTF8'), 'sha256'),
    'hex'
  );

  INSERT INTO public.sip_fleet_plan_artifacts(
    provider_slug,
    artifact_kind,
    content_hash,
    content,
    created_by
  ) VALUES (
    btrim(p_contributor_slug),
    btrim(p_artifact_kind),
    v_hash,
    p_content,
    (
      SELECT lease_owner
      FROM public.sip_fleet_provider_leases
      WHERE id = p_lease_id
    )
  )
  ON CONFLICT (provider_slug, artifact_kind, content_hash) DO NOTHING
  RETURNING * INTO v_artifact;

  IF v_artifact.id IS NULL THEN
    SELECT * INTO STRICT v_artifact
    FROM public.sip_fleet_plan_artifacts artifact
    WHERE artifact.provider_slug = btrim(p_contributor_slug)
      AND artifact.artifact_kind = btrim(p_artifact_kind)
      AND artifact.content_hash = v_hash;
  END IF;

  RETURN v_artifact;
END $$;


ALTER FUNCTION "public"."sip_publish_plan_artifact_upload_v1"("p_contributor_slug" "text", "p_artifact_kind" "text", "p_content" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_preview_fmg_terminal_waits_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_manifest jsonb;
  v_manifest_hash text;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF btrim(coalesce(p_contributor_slug, '')) <> 'fallout-music-group'
     OR p_lease_id IS NULL OR p_lease_token IS NULL THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_scope_invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended('fallout-music-group', 0)
  );

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = 'fallout-music-group'
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_invalid_provider_lease'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.provider_slug = 'fallout-music-group'
      AND lease.id <> p_lease_id
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    v_blockers := v_blockers || jsonb_build_array('other_active_provider_lease');
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = 'fallout-music-group'
      AND run.status IN ('queued', 'running')
  ) THEN
    v_blockers := v_blockers || jsonb_build_array('active_provider_run');
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.sip_fleet_run_items item
    JOIN public.sip_fleet_runs run ON run.id = item.run_id
    WHERE run.provider_slug = 'fallout-music-group'
      AND (
        item.status IN ('queued', 'running')
        OR (
          item.status = 'waiting_for_audio_profile'
          AND item.id NOT IN (
            '29bce41a-f448-4478-bf97-01edac4d34d1'::uuid,
            '854e9736-5f7d-46b0-86c6-e5f0a7903929'::uuid
          )
        )
      )
  ) THEN
    v_blockers := v_blockers || jsonb_build_array('active_provider_item');
  END IF;

  v_manifest := public.sip_fmg_terminal_profile_wait_snapshot_v1();
  v_manifest_hash := encode(
    extensions.digest(convert_to(v_manifest::text, 'UTF8'), 'sha256'), 'hex'
  );

  IF (v_manifest->>'targetCount')::integer IS DISTINCT FROM 2
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(v_manifest->'targets') target
       WHERE coalesce((target->>'evidenceComplete')::boolean, false) IS NOT TRUE
     ) THEN
    v_blockers := v_blockers || jsonb_build_array('terminal_successor_evidence_mismatch');
  END IF;

  RETURN jsonb_build_object(
    'manifest', v_manifest,
    'manifestHash', v_manifest_hash,
    'eligible', jsonb_array_length(v_blockers) = 0,
    'blockers', v_blockers
  );
END;
$$;


ALTER FUNCTION "public"."sip_publish_preview_fmg_terminal_waits_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_preview_orphan_upload_status_reconciliation_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_manifest jsonb;
  v_manifest_hash text;
  v_control jsonb;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF btrim(coalesce(p_contributor_slug, '')) = '' OR p_instrument_v2_id IS NULL THEN
    RAISE EXCEPTION 'orphan_upload_status_identity_invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  v_manifest := public.sip_publish_orphan_upload_status_snapshot_v1(
    p_contributor_slug, p_instrument_v2_id
  );
  IF v_manifest IS NULL THEN
    RAISE EXCEPTION 'orphan_upload_status_snapshot_missing' USING ERRCODE = '55000';
  END IF;
  v_control := v_manifest->'control';
  v_manifest_hash := encode(digest(convert_to(v_manifest::text, 'UTF8'), 'sha256'), 'hex');

  IF (v_manifest->>'instrumentPublished')::boolean IS DISTINCT FROM false THEN
    v_blockers := v_blockers || jsonb_build_array('instrument_published');
  END IF;
  IF coalesce(v_control->>'publish_status', '') <> 'running' THEN
    v_blockers := v_blockers || jsonb_build_array('publish_status_not_running');
  END IF;
  IF coalesce((v_control->>'publish_actions_applied')::boolean, false) IS NOT TRUE THEN
    v_blockers := v_blockers || jsonb_build_array('publish_actions_not_applied');
  END IF;
  IF coalesce((v_control->>'samples_processed')::integer, -1) <> 0 THEN
    v_blockers := v_blockers || jsonb_build_array('samples_already_processed');
  END IF;
  IF coalesce((v_control->>'samples_total')::integer, -1)
       <> (v_manifest->>'constructCount')::integer
     OR (v_manifest->>'constructCount')::integer < 1 THEN
    v_blockers := v_blockers || jsonb_build_array('sample_total_mismatch');
  END IF;
  IF v_control->>'published_at' IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array('upload_status_already_published');
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.provider_slug = btrim(p_contributor_slug)
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    v_blockers := v_blockers || jsonb_build_array('active_provider_lease');
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.sip_fleet_runs run
    WHERE run.provider_slug = btrim(p_contributor_slug)
      AND run.status IN ('queued', 'running')
  ) THEN
    v_blockers := v_blockers || jsonb_build_array('active_provider_run');
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.sip_fleet_run_items item
    JOIN public.sip_fleet_runs run ON run.id = item.run_id
    WHERE item.status IN ('queued', 'running', 'waiting_for_audio_profile')
      AND (
        item.instrument_v2_id = p_instrument_v2_id
        OR run.provider_slug = btrim(p_contributor_slug)
      )
  ) THEN
    v_blockers := v_blockers || jsonb_build_array('active_provider_item');
  END IF;

  RETURN jsonb_build_object(
    'manifest', v_manifest,
    'manifestHash', v_manifest_hash,
    'eligible', jsonb_array_length(v_blockers) = 0,
    'blockers', v_blockers
  );
END;
$$;


ALTER FUNCTION "public"."sip_publish_preview_orphan_upload_status_reconciliation_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_public_output_recovery_rehearsal_begin_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_rehearsal public.sip_public_output_recovery_rehearsals%ROWTYPE;
BEGIN
  IF nullif(btrim(p_git_sha), '') IS NULL
    OR btrim(p_git_sha) = 'unknown'
    OR nullif(btrim(p_processor_config_id), '') IS NULL
    OR btrim(p_processor_config_id) = 'unconfigured'
  THEN
    RAISE EXCEPTION 'configured_coordinator_identity_required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;

  SELECT *
  INTO v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = p_artifact_id
    AND artifact.provider_slug = btrim(p_contributor_slug)
    AND artifact.artifact_kind = 'public-output-recovery-v1';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'public_output_recovery_artifact_required';
  END IF;

  IF v_artifact.content->>'recoveryKind'
      IS DISTINCT FROM 'public-output-recovery-v1'
    OR v_artifact.content->>'contributor'
      IS DISTINCT FROM btrim(p_contributor_slug)
    OR v_artifact.content->>'gitSha' IS DISTINCT FROM btrim(p_git_sha)
    OR v_artifact.content->>'processorConfigId'
      IS DISTINCT FROM btrim(p_processor_config_id)
  THEN
    RAISE EXCEPTION 'public_output_recovery_identity_mismatch';
  END IF;

  INSERT INTO public.sip_public_output_recovery_rehearsals (
    artifact_id,
    content_hash,
    provider_slug,
    provider_lease_id,
    git_sha,
    processor_config_id
  ) VALUES (
    v_artifact.id,
    v_artifact.content_hash,
    btrim(p_contributor_slug),
    p_lease_id,
    btrim(p_git_sha),
    btrim(p_processor_config_id)
  )
  ON CONFLICT (
    artifact_id,
    content_hash,
    provider_lease_id,
    git_sha,
    processor_config_id
  ) WHERE status = 'pending'
  DO NOTHING
  RETURNING * INTO v_rehearsal;

  IF v_rehearsal.id IS NULL THEN
    SELECT *
    INTO STRICT v_rehearsal
    FROM public.sip_public_output_recovery_rehearsals rehearsal
    WHERE rehearsal.artifact_id = v_artifact.id
      AND rehearsal.content_hash = v_artifact.content_hash
      AND rehearsal.provider_lease_id = p_lease_id
      AND rehearsal.git_sha = btrim(p_git_sha)
      AND rehearsal.processor_config_id = btrim(p_processor_config_id)
      AND rehearsal.status = 'pending';
  END IF;

  RETURN jsonb_build_object(
    'rehearsalRunId', v_rehearsal.id,
    'artifactId', v_artifact.id,
    'contentHash', v_artifact.content_hash,
    'content', v_artifact.content,
    'status', v_rehearsal.status
  );
END;
$$;


ALTER FUNCTION "public"."sip_publish_public_output_recovery_rehearsal_begin_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_git_sha" "text", "p_processor_config_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_public_output_recovery_rehearsal_complete_v1"("p_rehearsal_run_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_passed" boolean, "p_result_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_rehearsal public.sip_public_output_recovery_rehearsals%ROWTYPE;
BEGIN
  IF jsonb_typeof(p_result_payload)<>'object' THEN RAISE EXCEPTION 'rehearsal_result_required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.lease_token=p_lease_token
      AND lease.released_at IS NULL AND lease.lease_expires_at>clock_timestamp()
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  UPDATE public.sip_public_output_recovery_rehearsals rehearsal SET
    status=CASE WHEN p_passed THEN 'passed' ELSE 'failed' END,
    result_payload=p_result_payload,
    completed_at=clock_timestamp()
  WHERE rehearsal.id=p_rehearsal_run_id
    AND rehearsal.provider_lease_id=p_lease_id
    AND rehearsal.status='pending'
  RETURNING * INTO v_rehearsal;
  IF v_rehearsal.id IS NULL THEN
    SELECT * INTO STRICT v_rehearsal FROM public.sip_public_output_recovery_rehearsals
    WHERE id=p_rehearsal_run_id AND provider_lease_id=p_lease_id;
    IF v_rehearsal.status<>(CASE WHEN p_passed THEN 'passed' ELSE 'failed' END)
      OR v_rehearsal.result_payload<>p_result_payload
    THEN RAISE EXCEPTION 'rehearsal_completion_mismatch'; END IF;
  END IF;
  RETURN to_jsonb(v_rehearsal);
END $$;


ALTER FUNCTION "public"."sip_publish_public_output_recovery_rehearsal_complete_v1"("p_rehearsal_run_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_passed" boolean, "p_result_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_reconcile_terminal_leases_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_lease record;
  v_active_lease_token uuid;
  v_latest_operation text;
  v_latest_requires_anchor_verification boolean;
  v_released integer := 0;
BEGIN
  FOR v_lease IN
    SELECT lease.id, lease.provider_slug
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.released_at IS NULL
    ORDER BY btrim(lease.provider_slug), lease.id
  LOOP
    PERFORM pg_advisory_xact_lock(
      hashtextextended(btrim(v_lease.provider_slug), 0)
    );

    SELECT lease.lease_token INTO v_active_lease_token
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = v_lease.id
      AND lease.provider_slug = v_lease.provider_slug
      AND lease.released_at IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN CONTINUE; END IF;

    SELECT
      terminal_run.result_payload->>'operation',
      coalesce(
        (artifact.content->'anchorObjectVerification'->>'required')::boolean,
        false
      )
    INTO v_latest_operation, v_latest_requires_anchor_verification
    FROM public.sip_fleet_runs terminal_run
    LEFT JOIN public.sip_fleet_plan_artifacts artifact
      ON artifact.id = terminal_run.plan_artifact_id
    WHERE terminal_run.provider_slug = v_lease.provider_slug
      AND terminal_run.provider_lease_id = v_lease.id
      AND terminal_run.provider_lease_token = v_active_lease_token
      AND terminal_run.status IN ('completed', 'failed', 'canceled')
    ORDER BY terminal_run.finished_at DESC NULLS LAST,
      terminal_run.updated_at DESC,
      terminal_run.created_at DESC,
      terminal_run.id DESC
    LIMIT 1;
    IF NOT FOUND
      OR v_latest_operation IN (
        'derived-grid-fill-rehearsal',
        'instrument-summary-materialization-rehearsal'
      )
      OR (
        v_latest_operation = 'instrument-summary-materialization'
        AND v_latest_requires_anchor_verification
      )
    THEN CONTINUE; END IF;

    IF EXISTS (
      SELECT 1 FROM public.sip_fleet_runs run
      WHERE run.provider_slug = v_lease.provider_slug
        AND run.status IN ('queued', 'running')
    ) THEN CONTINUE; END IF;

    UPDATE public.sip_fleet_provider_leases lease
    SET released_at = coalesce(lease.released_at, now()),
        lease_expires_at = least(lease.lease_expires_at, now())
    WHERE lease.id = v_lease.id
      AND lease.provider_slug = v_lease.provider_slug
      AND lease.lease_token = v_active_lease_token
      AND lease.released_at IS NULL;
    IF FOUND THEN v_released := v_released + 1; END IF;
  END LOOP;
  RETURN v_released;
END $$;


ALTER FUNCTION "public"."sip_publish_reconcile_terminal_leases_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_publish_reconcile_terminal_leases_v1"() IS 'Preserves active provider leases across guarded rehearsals and verified anchor summary materialization; releases other idle terminal leases.';



CREATE OR REPLACE FUNCTION "public"."sip_publish_reconcile_versioned_output_prefix_premutation_v1"("p_staging_operation_id" "uuid", "p_expected_request_hash" "text", "p_execution_sha" "text", "p_evidence" "jsonb", "p_reconciled_by" "text", "p_expected_active_state" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_operation public.sip_versioned_output_prefix_staging_operations%ROWTYPE;
  v_historical_lease public.sip_fleet_provider_leases%ROWTYPE;
  v_existing public.sip_versioned_output_prefix_premutation_reconciliation_receipts%ROWTYPE;
  v_hash text;
BEGIN
  IF p_staging_operation_id IS DISTINCT FROM '366f1326-a483-41e9-91be-ec74382b7555'::uuid
    OR btrim(p_execution_sha) IS DISTINCT FROM
      '6bf8db77647c62b37df623f253136446950e8022'
  THEN RAISE EXCEPTION 'versioned_output_prefix_premutation_scope_invalid'; END IF;
  SELECT * INTO STRICT v_operation FROM public.sip_versioned_output_prefix_staging_operations
  WHERE id=p_staging_operation_id AND status='ambiguous'
    AND request_hash=btrim(p_expected_request_hash)
    AND failure_code='Every versioned output-prefix source must have exact terminal evidence.'
    AND artifact_id IS NULL AND result IS NULL;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_operation.provider_slug,0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:'||v_operation.instrument_v2_id::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-fleet-executor-admission',0));
  SELECT * INTO STRICT v_operation FROM public.sip_versioned_output_prefix_staging_operations
  WHERE id=p_staging_operation_id AND status='ambiguous'
    AND request_hash=btrim(p_expected_request_hash)
    AND failure_code='Every versioned output-prefix source must have exact terminal evidence.'
    AND artifact_id IS NULL AND result IS NULL FOR UPDATE;
  SELECT * INTO STRICT v_historical_lease
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id=v_operation.provider_lease_id
    AND lease.provider_slug=v_operation.provider_slug
    AND lease.released_at IS NOT NULL
  FOR UPDATE;
  IF nullif(btrim(p_reconciled_by),'') IS NULL OR btrim(p_execution_sha)!~'^[0-9a-f]{40}$'
    OR jsonb_typeof(p_expected_active_state) IS DISTINCT FROM 'object'
    OR public.sip_versioned_output_prefix_state_v1(v_operation.instrument_v2_id)
      IS DISTINCT FROM p_expected_active_state
    OR jsonb_typeof(p_evidence) IS DISTINCT FROM 'object'
    OR p_evidence IS DISTINCT FROM jsonb_build_object(
      'schemaVersion',p_evidence->'schemaVersion',
      'stagingOperationId',p_evidence->'stagingOperationId',
      'expectedRequestHash',p_evidence->'expectedRequestHash',
      'executionSha',p_evidence->'executionSha',
      'observedAt',p_evidence->'observedAt',
      'operationStatus',p_evidence->'operationStatus',
      'failureCode',p_evidence->'failureCode',
      'artifactCount',p_evidence->'artifactCount',
      'stagingReceiptCount',p_evidence->'stagingReceiptCount',
      'remoteWritePhaseReceiptCount',p_evidence->'remoteWritePhaseReceiptCount',
      'activeState',p_evidence->'activeState',
      'activeStateHash',p_evidence->'activeStateHash',
      'destinationObjectSetHash',p_evidence->'destinationObjectSetHash',
      'destinationTargetCount',p_evidence->'destinationTargetCount',
      'destinationObjectCount',p_evidence->'destinationObjectCount',
      'destinationObjects',p_evidence->'destinationObjects')
    OR p_evidence->>'schemaVersion' IS DISTINCT FROM
      'sip-versioned-output-prefix-premutation-reconciliation-v1'
    OR p_evidence->>'stagingOperationId' IS DISTINCT FROM v_operation.id::text
    OR p_evidence->>'expectedRequestHash' IS DISTINCT FROM v_operation.request_hash
    OR p_evidence->>'executionSha' IS DISTINCT FROM btrim(p_execution_sha)
    OR p_evidence->>'operationStatus' IS DISTINCT FROM 'ambiguous'
    OR p_evidence->>'failureCode' IS DISTINCT FROM v_operation.failure_code
    OR p_evidence->>'observedAt' !~
      '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
    OR p_evidence->'activeState' IS DISTINCT FROM p_expected_active_state
    OR p_evidence->>'activeStateHash' IS DISTINCT FROM encode(digest(
      convert_to(p_expected_active_state::text,'UTF8'),'sha256'
    ),'hex')
    OR p_evidence->>'destinationObjectSetHash' !~ '^[0-9a-f]{64}$'
    OR p_evidence->'artifactCount' IS DISTINCT FROM '0'::jsonb
    OR p_evidence->'stagingReceiptCount' IS DISTINCT FROM '0'::jsonb
    OR p_evidence->'remoteWritePhaseReceiptCount' IS DISTINCT FROM '0'::jsonb
    OR p_evidence->'destinationObjectCount' IS DISTINCT FROM '0'::jsonb
    OR p_evidence->'destinationObjects' IS DISTINCT FROM '[]'::jsonb
    OR jsonb_typeof(p_evidence->'destinationTargetCount') IS DISTINCT FROM 'number'
    OR (p_evidence->>'destinationTargetCount')::numeric <= 0
    OR (p_evidence->>'destinationTargetCount')::numeric <> trunc(
      (p_evidence->>'destinationTargetCount')::numeric)
    OR (p_evidence->>'destinationTargetCount')::numeric > 9007199254740991
    OR EXISTS (SELECT 1 FROM public.sip_fleet_provider_leases lease
      WHERE lease.released_at IS NULL
        AND lease.lease_expires_at>clock_timestamp())
    OR EXISTS (SELECT 1 FROM public.sip_fleet_runs run
      WHERE run.status IN ('queued','running'))
    OR EXISTS (SELECT 1 FROM public.sip_fleet_run_items item
      JOIN public.sip_fleet_runs run ON run.id=item.run_id
      WHERE item.status IN ('queued','running','waiting_for_audio_profile'))
    OR EXISTS (SELECT 1 FROM public.sip_fleet_executor_leases executor
      WHERE executor.lease_expires_at>clock_timestamp())
    OR EXISTS (SELECT 1 FROM public.sip_pipeline_runs pipeline
      WHERE pipeline.status IN ('queued','running'))
    OR EXISTS (SELECT 1
      FROM public.sip_versioned_output_prefix_staging_operations replacement
      WHERE replacement.id<>v_operation.id
        AND replacement.status IN ('running','ambiguous'))
    OR EXISTS (SELECT 1 FROM public.sip_versioned_output_prefix_remote_write_phase_receipts
      WHERE staging_operation_id=v_operation.id)
    OR EXISTS (SELECT 1 FROM public.sip_versioned_output_prefix_staging_receipts
      WHERE provider_slug=v_operation.provider_slug
        AND instrument_v2_id=v_operation.instrument_v2_id
        AND created_at>=v_operation.started_at)
  THEN RAISE EXCEPTION 'versioned_output_prefix_premutation_evidence_invalid'; END IF;
  v_hash:=encode(digest(convert_to(jsonb_build_object(
    'stagingOperationId',v_operation.id,'requestHash',v_operation.request_hash,
    'failureCode',v_operation.failure_code,'executionSha',btrim(p_execution_sha),
    'evidence',p_evidence,'providerLeaseId',v_operation.provider_lease_id,
    'reconciledBy',btrim(p_reconciled_by)
  )::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.sip_versioned_output_prefix_premutation_reconciliation_receipts(
    staging_operation_id,provider_lease_id,expected_request_hash,execution_sha,
    evidence,reconciliation_receipt_hash,reconciled_by
  ) VALUES (v_operation.id,v_operation.provider_lease_id,v_operation.request_hash,btrim(p_execution_sha),
    p_evidence,v_hash,btrim(p_reconciled_by))
  ON CONFLICT (staging_operation_id) DO NOTHING RETURNING * INTO v_existing;
  IF v_existing.id IS NULL THEN
    SELECT * INTO STRICT v_existing
    FROM public.sip_versioned_output_prefix_premutation_reconciliation_receipts
    WHERE staging_operation_id=v_operation.id;
    IF (v_existing.evidence - 'observedAt') IS DISTINCT FROM
        (p_evidence - 'observedAt')
      OR v_existing.provider_lease_id IS DISTINCT FROM v_operation.provider_lease_id
      OR v_existing.expected_request_hash IS DISTINCT FROM v_operation.request_hash
      OR v_existing.execution_sha IS DISTINCT FROM btrim(p_execution_sha)
      OR v_existing.reconciled_by IS DISTINCT FROM btrim(p_reconciled_by)
    THEN RAISE EXCEPTION 'versioned_output_prefix_premutation_replay_drift'; END IF;
    RETURN to_jsonb(v_existing)||jsonb_build_object('idempotent',true);
  END IF;
  RETURN to_jsonb(v_existing)||jsonb_build_object('idempotent',false);
END $_$;


ALTER FUNCTION "public"."sip_publish_reconcile_versioned_output_prefix_premutation_v1"("p_staging_operation_id" "uuid", "p_expected_request_hash" "text", "p_execution_sha" "text", "p_evidence" "jsonb", "p_reconciled_by" "text", "p_expected_active_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_record_staged_promotion_rehearsal_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_staging_snapshot_hash" "text", "p_mutation_plan_hash" "text", "p_mutation_plan_canonical_json" "text", "p_mutation_plan" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_rehearsal public.sip_staged_promotion_rehearsals%ROWTYPE;
  v_canonical_contributor_id uuid;
BEGIN
  IF NOT public.validate_sip_publish_operator_lease_v1(
    p_contributor_slug,
    p_lease_id,
    p_lease_token
  ) THEN
    RAISE EXCEPTION 'invalid_coordinator_publish_authorization';
  END IF;

  IF COALESCE(p_staging_snapshot_hash, '') !~ '^[0-9a-f]{64}$'
     OR COALESCE(p_mutation_plan_hash, '') !~ '^[0-9a-f]{64}$'
     OR encode(extensions.digest(COALESCE(p_mutation_plan_canonical_json, ''), 'sha256'), 'hex')
          IS DISTINCT FROM p_mutation_plan_hash
     OR (CASE
          WHEN COALESCE(p_mutation_plan_canonical_json, '') = '' THEN true
          ELSE (p_mutation_plan_canonical_json::jsonb IS DISTINCT FROM p_mutation_plan)
        END)
     OR jsonb_typeof(COALESCE(p_mutation_plan, 'null'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'invalid_staged_promotion_rehearsal_payload'
      USING ERRCODE = '22023';
  END IF;
  IF NOT public.sip_staged_promotion_plan_is_structurally_valid_v1(
    p_mutation_plan,
    p_contributor_slug,
    p_lease_id
  ) THEN
    RAISE EXCEPTION 'invalid_staged_promotion_mutation_plan'
      USING ERRCODE = '22023';
  END IF;
  v_canonical_contributor_id :=
    public.sip_publish_coordinator_contributor_id_v1(p_contributor_slug);
  IF v_canonical_contributor_id IS NULL
     OR p_mutation_plan->>'canonicalContributorId'
          IS DISTINCT FROM v_canonical_contributor_id::text THEN
    RAISE EXCEPTION 'invalid_staged_promotion_provider_identity'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.sip_staged_promotion_rehearsals (
    provider_slug,
    provider_lease_id,
    provider_lease_token,
    staging_snapshot_hash,
    mutation_plan_hash,
    mutation_plan_content_hash,
    mutation_plan_canonical_json,
    mutation_plan
  ) VALUES (
    p_contributor_slug,
    p_lease_id,
    p_lease_token,
    p_staging_snapshot_hash,
    p_mutation_plan_hash,
    encode(extensions.digest(p_mutation_plan::text, 'sha256'), 'hex'),
    p_mutation_plan_canonical_json,
    p_mutation_plan
  )
  ON CONFLICT ON CONSTRAINT sip_staged_promotion_rehearsal_identity_unique
  DO NOTHING
  RETURNING * INTO v_rehearsal;

  IF v_rehearsal.id IS NULL THEN
    SELECT * INTO STRICT v_rehearsal
    FROM public.sip_staged_promotion_rehearsals rehearsal
    WHERE rehearsal.provider_slug = p_contributor_slug
      AND rehearsal.provider_lease_id = p_lease_id
      AND rehearsal.provider_lease_token = p_lease_token
      AND rehearsal.staging_snapshot_hash = p_staging_snapshot_hash
      AND rehearsal.mutation_plan_hash = p_mutation_plan_hash;
  END IF;

  RETURN jsonb_build_object(
    'rehearsalId', v_rehearsal.id,
    'status', v_rehearsal.status,
    'stagingSnapshotHash', v_rehearsal.staging_snapshot_hash,
    'mutationPlanHash', v_rehearsal.mutation_plan_hash,
    'createdAt', v_rehearsal.created_at
  );
END
$_$;


ALTER FUNCTION "public"."sip_publish_record_staged_promotion_rehearsal_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_staging_snapshot_hash" "text", "p_mutation_plan_hash" "text", "p_mutation_plan_canonical_json" "text", "p_mutation_plan" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_record_versioned_output_prefix_preflight_failure_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_request_hash" "text", "p_execution_sha" "text", "p_failure_code" "text", "p_evidence" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_recorded_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_existing public.sip_versioned_output_prefix_preflight_failure_receipts%ROWTYPE;
  v_hash text;
  v_token_hash text:=encode(digest(convert_to(p_lease_token::text,'UTF8'),'sha256'),'hex');
BEGIN
  IF btrim(p_request_hash)!~'^[0-9a-f]{64}$'
    OR btrim(p_execution_sha)!~'^[0-9a-f]{40}$'
    OR btrim(p_failure_code) NOT IN (
      'versioned_output_prefix_processor_config_drift',
      'versioned_output_prefix_instrument_drift',
      'versioned_output_prefix_canonical_plan_invalid',
      'versioned_output_prefix_source_not_terminal')
    OR nullif(btrim(p_recorded_by),'') IS NULL
    OR p_evidence IS DISTINCT FROM jsonb_build_object(
      'schemaVersion',p_evidence->'schemaVersion','requestHash',p_evidence->'requestHash',
      'executionSha',p_evidence->'executionSha','failureCode',p_evidence->'failureCode',
      'failureMessage',p_evidence->'failureMessage','observedAt',p_evidence->'observedAt',
      'stagingOperationCount',p_evidence->'stagingOperationCount',
      'remoteWritePhaseReceiptCount',p_evidence->'remoteWritePhaseReceiptCount')
    OR p_evidence->>'schemaVersion' IS DISTINCT FROM
      'sip-versioned-output-prefix-preflight-failure-v1'
    OR p_evidence->>'requestHash' IS DISTINCT FROM btrim(p_request_hash)
    OR p_evidence->>'executionSha' IS DISTINCT FROM btrim(p_execution_sha)
    OR p_evidence->>'failureCode' IS DISTINCT FROM btrim(p_failure_code)
    OR nullif(btrim(p_evidence->>'failureMessage'),'') IS NULL
    OR p_evidence->>'observedAt' !~
      '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
    OR p_evidence->'stagingOperationCount' IS DISTINCT FROM '0'::jsonb
    OR p_evidence->'remoteWritePhaseReceiptCount' IS DISTINCT FROM '0'::jsonb
  THEN RAISE EXCEPTION 'versioned_output_prefix_preflight_failure_invalid'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug),0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:'||p_instrument_v2_id::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-fleet-executor-admission',0));
  PERFORM 1 FROM public.sip_fleet_provider_leases lease
  WHERE lease.id=p_lease_id AND lease.provider_slug=btrim(p_contributor_slug)
    AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
    AND lease.lease_expires_at>clock_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'versioned_output_prefix_provider_lease_drift'; END IF;
  IF EXISTS (SELECT 1 FROM public.sip_versioned_output_prefix_staging_operations operation
      LEFT JOIN public.sip_versioned_output_prefix_preflight_receipts preflight
        ON preflight.id=operation.preflight_receipt_id
      WHERE operation.provider_lease_id=p_lease_id
        AND operation.instrument_v2_id=p_instrument_v2_id
        AND (operation.request_hash=btrim(p_request_hash)
          OR preflight.request_hash=btrim(p_request_hash)))
    OR EXISTS (SELECT 1 FROM public.sip_versioned_output_prefix_remote_write_phase_receipts phase
      JOIN public.sip_versioned_output_prefix_staging_operations operation
        ON operation.id=phase.staging_operation_id
      JOIN public.sip_versioned_output_prefix_preflight_receipts preflight
        ON preflight.id=phase.preflight_receipt_id
      WHERE phase.provider_lease_id=p_lease_id
        AND operation.instrument_v2_id=p_instrument_v2_id
        AND preflight.request_hash=btrim(p_request_hash))
  THEN RAISE EXCEPTION 'versioned_output_prefix_preflight_failure_after_mutation'; END IF;
  v_hash:=encode(digest(convert_to(jsonb_build_object(
    'providerSlug',btrim(p_contributor_slug),'instrumentV2Id',p_instrument_v2_id,
    'requestHash',btrim(p_request_hash),'executionSha',btrim(p_execution_sha),
    'providerLeaseId',p_lease_id,'providerLeaseTokenHash',v_token_hash,
    'failureCode',btrim(p_failure_code),'evidence',p_evidence,
    'recordedBy',btrim(p_recorded_by))::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.sip_versioned_output_prefix_preflight_failure_receipts(
    provider_slug,instrument_v2_id,request_hash,execution_sha,provider_lease_id,
    provider_lease_token_hash,failure_code,evidence,failure_receipt_hash,recorded_by
  ) VALUES (btrim(p_contributor_slug),p_instrument_v2_id,btrim(p_request_hash),
    btrim(p_execution_sha),p_lease_id,v_token_hash,btrim(p_failure_code),p_evidence,
    v_hash,btrim(p_recorded_by))
  ON CONFLICT (provider_slug,request_hash,provider_lease_id,provider_lease_token_hash,failure_code)
  DO NOTHING RETURNING * INTO v_existing;
  IF v_existing.id IS NULL THEN
    SELECT * INTO STRICT v_existing
    FROM public.sip_versioned_output_prefix_preflight_failure_receipts receipt
    WHERE receipt.provider_slug=btrim(p_contributor_slug)
      AND receipt.request_hash=btrim(p_request_hash)
      AND receipt.provider_lease_id=p_lease_id
      AND receipt.provider_lease_token_hash=v_token_hash
      AND receipt.failure_code=btrim(p_failure_code);
    IF (v_existing.evidence-'observedAt') IS DISTINCT FROM (p_evidence-'observedAt')
      OR v_existing.recorded_by IS DISTINCT FROM btrim(p_recorded_by)
    THEN RAISE EXCEPTION 'versioned_output_prefix_preflight_failure_replay_drift'; END IF;
    RETURN to_jsonb(v_existing)||jsonb_build_object('idempotent',true);
  END IF;
  RETURN to_jsonb(v_existing)||jsonb_build_object('idempotent',false);
END $_$;


ALTER FUNCTION "public"."sip_publish_record_versioned_output_prefix_preflight_failure_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_request_hash" "text", "p_execution_sha" "text", "p_failure_code" "text", "p_evidence" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_recorded_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_record_versioned_output_prefix_preflight_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_request_hash" "text", "p_canonical_plan_hash" "text", "p_source_terminal_snapshot" "jsonb", "p_processor_config_sha256" "text", "p_execution_sha" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_preflight_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_lease public.sip_fleet_provider_leases%ROWTYPE;
  v_snapshot jsonb;
  v_snapshot_hash text;
  v_receipt_hash text;
  v_existing public.sip_versioned_output_prefix_preflight_receipts%ROWTYPE;
BEGIN
  IF btrim(p_request_hash) !~ '^[0-9a-f]{64}$'
    OR btrim(p_canonical_plan_hash) !~ '^[0-9a-f]{64}$'
    OR btrim(p_processor_config_sha256) !~ '^[0-9a-f]{64}$'
    OR btrim(p_execution_sha) !~ '^[0-9a-f]{40}$'
    OR nullif(btrim(p_preflight_by),'') IS NULL
    OR jsonb_typeof(p_source_terminal_snapshot) IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_source_terminal_snapshot) = 0
  THEN RAISE EXCEPTION 'versioned_output_prefix_preflight_invalid'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug),0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:' || p_instrument_v2_id::text,0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-fleet-executor-admission',0));
  SELECT * INTO STRICT v_lease FROM public.sip_fleet_provider_leases lease
  WHERE lease.id=p_lease_id AND lease.provider_slug=btrim(p_contributor_slug)
    AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
    AND lease.lease_expires_at>clock_timestamp() FOR UPDATE;

  v_snapshot := public.sip_versioned_output_prefix_source_terminal_snapshot_v1(
    p_instrument_v2_id
  );
  IF v_snapshot IS DISTINCT FROM p_source_terminal_snapshot
    OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(p_source_terminal_snapshot) entry
      WHERE entry IS DISTINCT FROM jsonb_build_object(
        'id',entry->'id','terminalEvidence',entry->'terminalEvidence'
      )
    ) OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(p_source_terminal_snapshot) entry
      WHERE entry->'terminalEvidence' IS DISTINCT FROM jsonb_build_object(
          'status',entry->'terminalEvidence'->'status',
          'completedAt',entry->'terminalEvidence'->'completedAt',
          'updatedAt',entry->'terminalEvidence'->'updatedAt',
          'claimedBy',entry->'terminalEvidence'->'claimedBy',
          'claimedAt',entry->'terminalEvidence'->'claimedAt',
          'errorMessage',entry->'terminalEvidence'->'errorMessage',
          'licensingSecured',entry->'terminalEvidence'->'licensingSecured'
        )
        OR entry->'terminalEvidence'->>'status' NOT IN ('completed','legacy_quiescent')
        OR entry->'terminalEvidence'->'claimedBy' <> 'null'::jsonb
        OR entry->'terminalEvidence'->'claimedAt' <> 'null'::jsonb
        OR entry->'terminalEvidence'->'errorMessage' <> 'null'::jsonb
        OR entry->'terminalEvidence'->'licensingSecured' <> 'true'::jsonb
        OR nullif(entry->'terminalEvidence'->>'updatedAt','') IS NULL
        OR (entry->'terminalEvidence'->>'status'='completed'
          AND nullif(entry->'terminalEvidence'->>'completedAt','') IS NULL)
        OR (entry->'terminalEvidence'->>'status'='legacy_quiescent'
          AND entry->'terminalEvidence'->'completedAt' <> 'null'::jsonb)
    )
  THEN RAISE EXCEPTION 'versioned_output_prefix_source_terminal_drift'; END IF;
  v_snapshot_hash := encode(digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex');
  v_receipt_hash := encode(digest(convert_to(jsonb_build_object(
    'providerSlug',btrim(p_contributor_slug),'instrumentV2Id',p_instrument_v2_id,
    'requestHash',btrim(p_request_hash),'canonicalPlanHash',btrim(p_canonical_plan_hash),
    'sourceTerminalSnapshotHash',v_snapshot_hash,
    'processorConfigSha256',btrim(p_processor_config_sha256),
    'executionSha',btrim(p_execution_sha),'providerLeaseId',p_lease_id,
    'providerLeaseTokenHash',encode(digest(convert_to(p_lease_token::text,'UTF8'),'sha256'),'hex'),
    'preflightBy',btrim(p_preflight_by)
  )::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.sip_versioned_output_prefix_preflight_receipts(
    provider_slug,instrument_v2_id,request_hash,canonical_plan_hash,
    source_terminal_snapshot,source_terminal_snapshot_hash,
    processor_config_sha256,execution_sha,provider_lease_id,
    provider_lease_token_hash,preflight_receipt_hash,admission_request_hash,preflight_by
  ) VALUES (
    btrim(p_contributor_slug),p_instrument_v2_id,btrim(p_request_hash),
    btrim(p_canonical_plan_hash),v_snapshot,v_snapshot_hash,
    btrim(p_processor_config_sha256),btrim(p_execution_sha),p_lease_id,
    encode(digest(convert_to(p_lease_token::text,'UTF8'),'sha256'),'hex'),
    v_receipt_hash,encode(digest(convert_to(jsonb_build_object(
      'preflightReceiptHash',v_receipt_hash,
      'clearanceReceiptHashes',COALESCE((SELECT jsonb_agg(
        clearance.reconciliation_receipt_hash ORDER BY clearance.reconciliation_receipt_hash
      ) FROM public.sip_versioned_output_prefix_premutation_reconciliation_receipts clearance
      JOIN public.sip_versioned_output_prefix_staging_operations operation
        ON operation.id=clearance.staging_operation_id
      WHERE operation.provider_slug=btrim(p_contributor_slug)),'[]'::jsonb)
    )::text,'UTF8'),'sha256'),'hex'),btrim(p_preflight_by)
  ) ON CONFLICT (
    provider_slug,request_hash,source_terminal_snapshot_hash,provider_lease_id,
    provider_lease_token_hash
  ) DO NOTHING
  RETURNING * INTO v_existing;
  IF v_existing.id IS NULL THEN
    SELECT * INTO STRICT v_existing
    FROM public.sip_versioned_output_prefix_preflight_receipts receipt
    WHERE receipt.provider_slug=btrim(p_contributor_slug)
      AND receipt.request_hash=btrim(p_request_hash)
      AND receipt.source_terminal_snapshot_hash=v_snapshot_hash
      AND receipt.provider_lease_id=p_lease_id
      AND receipt.provider_lease_token_hash=encode(digest(
        convert_to(p_lease_token::text,'UTF8'),'sha256'
      ),'hex');
    IF v_existing.preflight_receipt_hash IS DISTINCT FROM v_receipt_hash
    THEN RAISE EXCEPTION 'versioned_output_prefix_preflight_replay_drift'; END IF;
    RETURN to_jsonb(v_existing)||jsonb_build_object('idempotent',true);
  END IF;
  RETURN to_jsonb(v_existing)||jsonb_build_object('idempotent',false);
END $_$;


ALTER FUNCTION "public"."sip_publish_record_versioned_output_prefix_preflight_v1"("p_contributor_slug" "text", "p_instrument_v2_id" "uuid", "p_request_hash" "text", "p_canonical_plan_hash" "text", "p_source_terminal_snapshot" "jsonb", "p_processor_config_sha256" "text", "p_execution_sha" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_preflight_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_refresh_anchor_verification_and_materialize_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer, "p_rehearsal_run_id" "uuid", "p_projection_hash" "text", "p_object_identity_hash" "text", "p_expected_construct_count" integer, "p_expected_source_count" integer, "p_expected_target_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '5min'
    SET "lock_timeout" TO '5s'
    AS $$
DECLARE
  v_rehearsal_id uuid;
BEGIN
  UPDATE public.sip_anchor_object_verification_rehearsals rehearsal
  SET completed_at = clock_timestamp()
  FROM public.sip_fleet_provider_leases lease
  WHERE rehearsal.id = p_rehearsal_run_id
    AND rehearsal.artifact_id = p_artifact_id
    AND rehearsal.provider_slug = btrim(p_contributor_slug)
    AND rehearsal.provider_lease_id = p_lease_id
    AND rehearsal.provider_lease_token = p_lease_token
    AND rehearsal.status = 'passed'
    AND rehearsal.projection_hash = p_projection_hash
    AND rehearsal.object_identity_hash = p_object_identity_hash
    AND rehearsal.construct_count = p_expected_construct_count
    AND rehearsal.source_count = p_expected_source_count
    AND rehearsal.target_count = p_expected_target_count
    AND lease.id = p_lease_id
    AND lease.provider_slug = btrim(p_contributor_slug)
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp()
  RETURNING rehearsal.id INTO v_rehearsal_id;

  IF v_rehearsal_id IS NULL THEN
    RAISE EXCEPTION 'matching_passed_anchor_object_verification_required';
  END IF;

  RETURN public.sip_publish_materialize_instrument_summaries_v1(
    p_contributor_slug,
    p_artifact_id,
    p_lease_id,
    p_lease_token,
    p_expected_count,
    p_rehearsal_run_id,
    p_projection_hash,
    p_object_identity_hash,
    p_expected_construct_count,
    p_expected_source_count,
    p_expected_target_count
  );
END;
$$;


ALTER FUNCTION "public"."sip_publish_refresh_anchor_verification_and_materialize_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer, "p_rehearsal_run_id" "uuid", "p_projection_hash" "text", "p_object_identity_hash" "text", "p_expected_construct_count" integer, "p_expected_source_count" integer, "p_expected_target_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_publish_refresh_anchor_verification_and_materialize_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer, "p_rehearsal_run_id" "uuid", "p_projection_hash" "text", "p_object_identity_hash" "text", "p_expected_construct_count" integer, "p_expected_source_count" integer, "p_expected_target_count" integer) IS 'Atomically refreshes an exact passed anchor-object receipt after a current second verification and materializes guarded instrument summaries.';



CREATE OR REPLACE FUNCTION "public"."sip_publish_rehearse_derived_grid_fill_unlocked_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_operation_count" integer, "p_expected_instrument_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_content jsonb;
  v_hash text;
  v_operation_count integer;
  v_instrument_count integer;
  v_rehearsal_id text;
  v_run_id uuid;
  v_inserted_run_id uuid;
  v_existing_run public.sip_fleet_runs%ROWTYPE;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug=btrim(p_contributor_slug)
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>clock_timestamp()
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;

  SELECT artifact.content, artifact.content_hash INTO v_content, v_hash
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id=p_artifact_id
    AND artifact.provider_slug=btrim(p_contributor_slug)
    AND artifact.artifact_kind='derived-grid-fill-v1';
  IF v_content IS NULL THEN RAISE EXCEPTION 'derived_grid_fill_artifact_not_found'; END IF;
  IF v_content->>'planKind'<>'v2-derived-grid-fill'
    OR coalesce((v_content->>'planVersion')::integer,-1)<>1
    OR coalesce((v_content->>'dryRun')::boolean,false) IS NOT TRUE
  THEN RAISE EXCEPTION 'derived_grid_fill_plan_contract_invalid'; END IF;
  IF jsonb_typeof(v_content->'operations') <> 'array'
    OR jsonb_array_length(v_content->'operations')=0
  THEN RAISE EXCEPTION 'derived_grid_fill_operations_required'; END IF;
  IF v_content->'approval'->>'rehearsalRunId' IS NULL THEN
    RAISE EXCEPTION 'derived_grid_fill_rehearsal_id_required_in_artifact';
  END IF;
  v_rehearsal_id := v_content->'approval'->>'rehearsalRunId';
  IF v_rehearsal_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'derived_grid_fill_rehearsal_id_invalid';
  END IF;
  v_run_id := v_rehearsal_id::uuid;

  SELECT count(*), count(DISTINCT lower(operation->>'instrumentV2Id'))
    INTO v_operation_count, v_instrument_count
  FROM jsonb_array_elements(v_content->'operations') operation;
  IF p_expected_operation_count IS NULL OR p_expected_operation_count<1
    OR p_expected_operation_count<>v_operation_count
  THEN RAISE EXCEPTION 'derived_grid_fill_expected_operation_count_mismatch'; END IF;
  IF p_expected_instrument_count IS NULL OR p_expected_instrument_count<1
    OR p_expected_instrument_count<>v_instrument_count
  THEN RAISE EXCEPTION 'derived_grid_fill_expected_instrument_count_mismatch'; END IF;
  IF coalesce((v_content->'summary'->>'missingSlots')::integer,-1)<>v_operation_count
    OR coalesce((v_content->'summary'->>'autoFillable')::integer,-1)<>v_operation_count
    OR coalesce((v_content->'summary'->>'instrumentsEvaluated')::integer,-1)<>v_instrument_count
    OR coalesce((v_content->'summary'->>'reviewRequired')::integer,-1)<>0
    OR coalesce((v_content->'summary'->>'blocked')::integer,-1)<>0
    OR coalesce((v_content->'summary'->>'lineageBlocked')::integer,-1)<>0
    OR coalesce((v_content->'summary'->>'needsFullDetail')::integer,-1)<>0
  THEN RAISE EXCEPTION 'derived_grid_fill_summary_not_exact_auto_scope'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_content->'operations') operation
    WHERE operation->>'status'<>'auto-fillable'
      OR nullif(btrim(operation->>'operationId'),'') IS NULL
      OR nullif(btrim(operation->>'instrumentV2Id'),'') IS NULL
      OR jsonb_typeof(operation->'target')<>'object'
      OR jsonb_typeof(operation->'donor')<>'object'
      OR nullif(btrim(operation->'target'->>'pitchContent'),'') IS NULL
      OR nullif(btrim(operation->'target'->>'midiNote'),'') IS NULL
      OR nullif(btrim(operation->'donor'->>'pitchContent'),'') IS NULL
      OR nullif(btrim(operation->'donor'->>'midiNote'),'') IS NULL
      OR nullif(btrim(operation->'donor'->>'samplePathConstructId'),'') IS NULL
      OR nullif(btrim(operation->'donor'->>'sampleOriginalPathId'),'') IS NULL
      OR nullif(btrim(operation->'donor'->>'sourceS3Key'),'') IS NULL
      OR jsonb_typeof(operation->'generated')<>'object'
      OR nullif(btrim(operation->'generated'->>'sampleOriginalPathId'),'') IS NULL
      OR nullif(btrim(operation->'generated'->>'samplePathConstructId'),'') IS NULL
      OR nullif(btrim(operation->'generated'->>'privateSourceS3Key'),'') IS NULL
  ) THEN RAISE EXCEPTION 'derived_grid_fill_non_auto_operation'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_content->'operations') operation
    WHERE operation->>'instrumentV2Id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR operation->'donor'->>'samplePathConstructId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR operation->'donor'->>'sampleOriginalPathId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR operation->'generated'->>'sampleOriginalPathId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR operation->'generated'->>'samplePathConstructId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) THEN RAISE EXCEPTION 'derived_grid_fill_operation_id_invalid'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_content->'operations') operation
    GROUP BY operation->>'operationId' HAVING count(*)>1
  ) OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_content->'operations') operation
    GROUP BY operation->'generated'->>'sampleOriginalPathId' HAVING count(*)>1
  ) THEN RAISE EXCEPTION 'derived_grid_fill_duplicate_operation'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_content->'operations') operation
    LEFT JOIN public.samples_original_paths generated_source
      ON generated_source.id=(operation->'generated'->>'sampleOriginalPathId')::uuid
    LEFT JOIN public.sample_path_constructs generated_construct
      ON generated_construct.id=(operation->'generated'->>'samplePathConstructId')::uuid
    WHERE generated_source.id IS NOT NULL OR generated_construct.id IS NOT NULL
  ) THEN RAISE EXCEPTION 'derived_grid_fill_generated_identity_already_exists'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_content->'operations') operation
    LEFT JOIN public.instruments_v2 instrument ON instrument.id=(operation->>'instrumentV2Id')::uuid
    LEFT JOIN public.contributors contributor ON contributor.id=instrument.contributor_id
    WHERE instrument.id IS NULL OR contributor.slug<>btrim(p_contributor_slug)
  ) THEN RAISE EXCEPTION 'derived_grid_fill_instrument_not_owned_by_provider'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_content->'operations') operation
    JOIN public.sample_path_constructs target
      ON target.instrument_v2_id=(operation->>'instrumentV2Id')::uuid
     AND coalesce(nullif(btrim(target.pitch_content),''),'0')=operation->'target'->>'pitchContent'
     AND target.midi_note::text=operation->'target'->>'midiNote'
     AND greatest(coalesce(target.velocity,0),0)=coalesce((operation->'target'->>'velocity')::integer,0)
     AND greatest(coalesce(target.round_robin,0),0)=coalesce((operation->'target'->>'roundRobin')::integer,0)
     AND coalesce(nullif(btrim(target.mic_position),''),'main')=coalesce(nullif(btrim(operation->'target'->>'micPosition'),''),'main')
  ) THEN RAISE EXCEPTION 'derived_grid_fill_target_already_exists'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_content->'operations') operation
    LEFT JOIN public.sample_path_constructs donor
      ON donor.id=(operation->'donor'->>'samplePathConstructId')::uuid
     AND donor.instrument_v2_id=(operation->>'instrumentV2Id')::uuid
    LEFT JOIN public.samples_original_paths source ON source.id=donor.sample_original_path_id
    WHERE donor.id IS NULL
      OR source.id IS DISTINCT FROM (operation->'donor'->>'sampleOriginalPathId')::uuid
      OR source.s3_path IS DISTINCT FROM operation->'donor'->>'sourceS3Key'
      OR coalesce(nullif(btrim(donor.pitch_content),''),'0')<>operation->'donor'->>'pitchContent'
      OR donor.midi_note::text<>operation->'donor'->>'midiNote'
      OR greatest(coalesce(donor.velocity,0),0)<>coalesce((operation->'donor'->>'velocity')::integer,0)
      OR greatest(coalesce(donor.round_robin,0),0)<>coalesce((operation->'donor'->>'roundRobin')::integer,0)
      OR coalesce(nullif(btrim(donor.mic_position),''),'main')<>coalesce(operation->'donor'->>'micPosition','main')
  ) THEN RAISE EXCEPTION 'derived_grid_fill_donor_no_longer_current'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_content->'operations') operation
    GROUP BY (operation->>'instrumentV2Id')::uuid, btrim(operation->'target'->>'pitchContent'),
      operation->'target'->>'midiNote', coalesce((operation->'target'->>'velocity')::integer,0),
      coalesce((operation->'target'->>'roundRobin')::integer,0),
      coalesce(nullif(btrim(operation->'target'->>'micPosition'),''),'main')
    HAVING count(*)>1
  ) THEN RAISE EXCEPTION 'derived_grid_fill_duplicate_target'; END IF;

  SELECT * INTO v_existing_run FROM public.sip_fleet_runs run
  WHERE run.provider_slug=btrim(p_contributor_slug)
    AND run.idempotency_key='derived-grid-fill-rehearsal:'||v_hash;
  IF v_existing_run.id IS NOT NULL THEN
    IF v_existing_run.status<>'completed' OR v_existing_run.plan_artifact_id<>p_artifact_id
      OR v_existing_run.id<>v_run_id OR v_existing_run.result_payload->>'contentHash'<>v_hash
      OR v_existing_run.result_payload->>'operation'<>'derived-grid-fill-rehearsal'
      OR v_existing_run.result_payload->>'operationCount'<>v_operation_count::text
      OR v_existing_run.result_payload->>'instrumentCount'<>v_instrument_count::text
    THEN RAISE EXCEPTION 'derived_grid_fill_rehearsal_incomplete_existing_run'; END IF;
    RETURN jsonb_build_object('rehearsalRunId',v_rehearsal_id,'runId',v_existing_run.id,
      'contentHash',v_hash,'operationCount',v_operation_count,'instrumentCount',v_instrument_count,'idempotent',true);
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.id=v_run_id AND run.idempotency_key<>'derived-grid-fill-rehearsal:'||v_hash
  ) THEN RAISE EXCEPTION 'derived_grid_fill_rehearsal_id_conflict'; END IF;
  INSERT INTO public.sip_fleet_runs(id,provider_slug,idempotency_key,plan_artifact_id,
    submitted_by,provider_lease_id,provider_lease_token,status,started_at,finished_at,result_payload)
  VALUES (v_run_id,btrim(p_contributor_slug),'derived-grid-fill-rehearsal:'||v_hash,p_artifact_id,
    (SELECT lease_owner FROM public.sip_fleet_provider_leases WHERE id=p_lease_id),
    p_lease_id,p_lease_token,'completed',now(),now(),jsonb_build_object(
      'operation','derived-grid-fill-rehearsal','rehearsalRunId',v_rehearsal_id,'contentHash',v_hash,
      'operationCount',v_operation_count,'instrumentCount',v_instrument_count))
  ON CONFLICT (provider_slug,idempotency_key) DO NOTHING RETURNING id INTO v_inserted_run_id;
  IF v_inserted_run_id IS NULL THEN
    SELECT * INTO v_existing_run FROM public.sip_fleet_runs run
    WHERE run.provider_slug=btrim(p_contributor_slug)
      AND run.idempotency_key='derived-grid-fill-rehearsal:'||v_hash;
    IF v_existing_run.id IS NULL OR v_existing_run.status<>'completed'
      OR v_existing_run.plan_artifact_id<>p_artifact_id OR v_existing_run.id<>v_run_id
      OR v_existing_run.result_payload->>'contentHash'<>v_hash
      OR v_existing_run.result_payload->>'operation'<>'derived-grid-fill-rehearsal'
      OR v_existing_run.result_payload->>'operationCount'<>v_operation_count::text
      OR v_existing_run.result_payload->>'instrumentCount'<>v_instrument_count::text
    THEN RAISE EXCEPTION 'derived_grid_fill_rehearsal_incomplete_existing_run'; END IF;
    RETURN jsonb_build_object('rehearsalRunId',v_rehearsal_id,'runId',v_existing_run.id,
      'contentHash',v_hash,'operationCount',v_operation_count,'instrumentCount',v_instrument_count,'idempotent',true);
  END IF;
  v_run_id := v_inserted_run_id;
  INSERT INTO public.sip_fleet_run_items(run_id,item_key,instrument_v2_id,status,
    started_at,finished_at,result_payload)
  SELECT v_run_id,'derived-grid-fill-rehearsal:instrument:'||operation.instrument_v2_id::text,
    operation.instrument_v2_id,'completed',now(),now(),jsonb_build_object(
      'operation','derived-grid-fill-rehearsal','instrumentV2Id',operation.instrument_v2_id::text,
      'operationCount',count(*)::integer,
      'operationIds',jsonb_agg(operation.operation_id ORDER BY operation.operation_id))
  FROM (
    SELECT (entry->>'instrumentV2Id')::uuid AS instrument_v2_id,
      entry->>'operationId' AS operation_id
    FROM jsonb_array_elements(v_content->'operations') entry
  ) operation
  GROUP BY operation.instrument_v2_id;
  RETURN jsonb_build_object('rehearsalRunId',v_rehearsal_id,'runId',v_run_id,
    'contentHash',v_hash,'operationCount',v_operation_count,
    'instrumentCount',v_instrument_count,'idempotent',false);
END $_$;


ALTER FUNCTION "public"."sip_publish_rehearse_derived_grid_fill_unlocked_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_operation_count" integer, "p_expected_instrument_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_rehearse_derived_grid_fill_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_operation_count" integer, "p_expected_instrument_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Exact key/order shared by submission and terminal reconciliation.
  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug), 0));
  RETURN public.sip_publish_rehearse_derived_grid_fill_unlocked_v1(
    p_contributor_slug,
    p_artifact_id,
    p_lease_id,
    p_lease_token,
    p_expected_operation_count,
    p_expected_instrument_count
  );
END $$;


ALTER FUNCTION "public"."sip_publish_rehearse_derived_grid_fill_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_operation_count" integer, "p_expected_instrument_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_rehearse_instrument_summaries_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '2min'
    SET "lock_timeout" TO '5s'
    AS $_$
DECLARE
  v_content jsonb;
  v_hash text;
  v_count integer;
  v_run_id uuid;
  v_existing_run_id uuid;
  v_existing_status text;
  v_rehearsal_id text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug=btrim(p_contributor_slug)
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>now()
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;

  SELECT artifact.content, artifact.content_hash INTO v_content, v_hash
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id=p_artifact_id
    AND artifact.provider_slug=btrim(p_contributor_slug)
    AND artifact.artifact_kind='instrument-summary-materialization';
  IF v_content IS NULL THEN RAISE EXCEPTION 'summary_artifact_not_found'; END IF;
  IF jsonb_typeof(v_content->'instrumentV2Ids') <> 'array'
    OR jsonb_array_length(v_content->'instrumentV2Ids')=0
  THEN RAISE EXCEPTION 'summary_instrument_ids_required'; END IF;

  SELECT count(*) INTO v_count FROM jsonb_array_elements_text(v_content->'instrumentV2Ids');
  IF p_expected_count IS NULL OR p_expected_count<1 OR p_expected_count<>v_count
  THEN RAISE EXCEPTION 'summary_expected_count_mismatch'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(v_content->'instrumentV2Ids') requested(value)
    LEFT JOIN public.instruments_v2 instrument ON instrument.id=requested.value::uuid
    LEFT JOIN public.contributors contributor ON contributor.id=instrument.contributor_id
    WHERE instrument.id IS NULL OR contributor.slug<>btrim(p_contributor_slug)
  ) THEN RAISE EXCEPTION 'summary_instrument_not_owned_by_provider'; END IF;
  IF v_content->'approval'->>'rehearsalRunId' IS NULL THEN
    RAISE EXCEPTION 'summary_rehearsal_id_required_in_artifact';
  END IF;

  v_rehearsal_id := v_content->'approval'->>'rehearsalRunId';
  IF v_rehearsal_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'summary_rehearsal_id_invalid';
  END IF;
  v_run_id := v_rehearsal_id::uuid;

  INSERT INTO public.sip_fleet_runs(id,provider_slug,idempotency_key,plan_artifact_id,
    submitted_by,provider_lease_id,provider_lease_token,status,started_at,finished_at,result_payload)
  VALUES (v_run_id,btrim(p_contributor_slug),'summary-rehearsal:'||v_hash,p_artifact_id,
    (SELECT lease_owner FROM public.sip_fleet_provider_leases WHERE id=p_lease_id),
    p_lease_id,p_lease_token,'completed',now(),now(),
    jsonb_build_object('operation','instrument-summary-materialization-rehearsal',
      'rehearsalRunId',v_rehearsal_id,'contentHash',v_hash,'instrumentCount',v_count))
  ON CONFLICT (provider_slug,idempotency_key) DO NOTHING
  RETURNING id INTO v_existing_run_id;

  IF v_existing_run_id IS NULL THEN
    SELECT id, status INTO v_existing_run_id, v_existing_status
    FROM public.sip_fleet_runs
    WHERE provider_slug=btrim(p_contributor_slug)
      AND idempotency_key='summary-rehearsal:'||v_hash;
    IF v_existing_status <> 'completed' THEN
      RAISE EXCEPTION 'summary_rehearsal_incomplete_existing_run';
    END IF;
    RETURN jsonb_build_object('rehearsalRunId',v_rehearsal_id,'runId',v_existing_run_id,
      'contentHash',v_hash,'instrumentCount',v_count,'idempotent',true);
  END IF;
  v_run_id := v_existing_run_id;

  INSERT INTO public.sip_fleet_run_items(run_id,item_key,instrument_v2_id,status,
    started_at,finished_at,result_payload)
  SELECT v_run_id,'summary-rehearsal:'||value,value::uuid,'completed',now(),now(),
    jsonb_build_object('operation','instrument-summary-materialization-rehearsal')
  FROM jsonb_array_elements_text(v_content->'instrumentV2Ids');

  RETURN jsonb_build_object('rehearsalRunId',v_rehearsal_id,'runId',v_run_id,
    'contentHash',v_hash,'instrumentCount',v_count,'idempotent',false);
END $_$;


ALTER FUNCTION "public"."sip_publish_rehearse_instrument_summaries_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_rehearse_parent_pitchless_projection_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_content jsonb;
  v_hash text;
  v_count integer;
  v_seen_count integer;
  v_run_id uuid;
  v_existing_run_id uuid;
  v_existing_status text;
  v_rehearsal_id text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug=btrim(p_contributor_slug)
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>now()
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;

  SELECT artifact.content, artifact.content_hash INTO v_content, v_hash
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id=p_artifact_id
    AND artifact.provider_slug=btrim(p_contributor_slug)
    AND artifact.artifact_kind='parent-pitchless-projection-v1';
  IF v_content IS NULL THEN RAISE EXCEPTION 'parent_pitchless_artifact_not_found'; END IF;
  IF jsonb_typeof(v_content->'instruments') <> 'array'
    OR jsonb_array_length(v_content->'instruments')=0
  THEN RAISE EXCEPTION 'parent_pitchless_instruments_required'; END IF;

  SELECT count(DISTINCT instrument->>'instrumentV2Id'), count(*)
    INTO v_count, v_seen_count
  FROM jsonb_array_elements(v_content->'instruments') instrument;
  IF v_count <> v_seen_count THEN RAISE EXCEPTION 'duplicate_instrument_id'; END IF;
  IF p_expected_count IS NULL OR p_expected_count<1 OR p_expected_count<>v_count
  THEN RAISE EXCEPTION 'parent_pitchless_expected_count_mismatch'; END IF;

  IF v_content->'approval'->>'rehearsalRunId' IS NULL THEN
    RAISE EXCEPTION 'parent_pitchless_rehearsal_id_required_in_artifact';
  END IF;
  v_rehearsal_id := v_content->'approval'->>'rehearsalRunId';
  IF v_rehearsal_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'parent_pitchless_rehearsal_id_invalid';
  END IF;
  v_run_id := v_rehearsal_id::uuid;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_content->'instruments') requested(instrument)
    LEFT JOIN public.instruments_v2 instrument ON instrument.id=(requested.instrument->>'instrumentV2Id')::uuid
    LEFT JOIN public.contributors contributor ON contributor.id=instrument.contributor_id
    WHERE instrument.id IS NULL OR contributor.slug<>btrim(p_contributor_slug)
      OR requested.instrument->'target'->>'engineType' <> 'non_tonal'
      OR requested.instrument->'target'->>'singlePitch' IS NOT NULL
      OR requested.instrument->'target'->>'fileNameReference' <> 'pitchless'
      OR coalesce((requested.instrument->'target'->>'rangeLower')::integer, 0) <> 21
      OR coalesce((requested.instrument->'target'->>'rangeUpper')::integer, 0) <> 108
  ) THEN RAISE EXCEPTION 'parent_pitchless_manifest_invalid'; END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_content->'instruments') requested(instrument)
    JOIN public.sample_path_constructs c
      ON c.instrument_v2_id=(requested.instrument->>'instrumentV2Id')::uuid
    GROUP BY requested.instrument->>'instrumentV2Id'
    HAVING count(*)=0
      OR count(*) FILTER (WHERE c.midi_note='pitchless' AND c.filename='pitchless') <> count(*)
      OR count(DISTINCT coalesce(nullif(btrim(c.pitch_content),''),'0')) <> 1
      OR min(coalesce(nullif(btrim(c.pitch_content),''),'0')) <> '0'
  ) THEN RAISE EXCEPTION 'parent_pitchless_construct_evidence_required'; END IF;

  INSERT INTO public.sip_fleet_runs(id,provider_slug,idempotency_key,plan_artifact_id,
    submitted_by,provider_lease_id,provider_lease_token,status,started_at,finished_at,result_payload)
  VALUES (v_run_id,btrim(p_contributor_slug),'parent-pitchless-rehearsal:'||v_hash,p_artifact_id,
    (SELECT lease_owner FROM public.sip_fleet_provider_leases WHERE id=p_lease_id),
    p_lease_id,p_lease_token,'completed',now(),now(),
    jsonb_build_object('operation','parent-pitchless-projection-rehearsal',
      'rehearsalRunId',v_rehearsal_id,'contentHash',v_hash,'instrumentCount',v_count))
  ON CONFLICT (provider_slug,idempotency_key) DO NOTHING
  RETURNING id INTO v_existing_run_id;

  IF v_existing_run_id IS NULL THEN
    SELECT id, status INTO v_existing_run_id, v_existing_status
    FROM public.sip_fleet_runs
    WHERE provider_slug=btrim(p_contributor_slug)
      AND idempotency_key='parent-pitchless-rehearsal:'||v_hash;
    IF v_existing_status <> 'completed' THEN
      RAISE EXCEPTION 'parent_pitchless_rehearsal_incomplete_existing_run';
    END IF;
    RETURN jsonb_build_object('rehearsalRunId',v_rehearsal_id,'runId',v_existing_run_id,
      'contentHash',v_hash,'instrumentCount',v_count,'idempotent',true);
  END IF;
  v_run_id := v_existing_run_id;

  INSERT INTO public.sip_fleet_run_items(run_id,item_key,instrument_v2_id,status,
    started_at,finished_at,result_payload)
  SELECT v_run_id,'parent-pitchless-rehearsal:'||(instrument->>'instrumentV2Id'),
    (instrument->>'instrumentV2Id')::uuid,'completed',now(),now(),
    jsonb_build_object('operation','parent-pitchless-projection-rehearsal')
  FROM jsonb_array_elements(v_content->'instruments') instrument;

  RETURN jsonb_build_object('rehearsalRunId',v_rehearsal_id,'runId',v_run_id,
    'contentHash',v_hash,'instrumentCount',v_count,'idempotent',false);
END $_$;


ALTER FUNCTION "public"."sip_publish_rehearse_parent_pitchless_projection_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_rehearse_versioned_output_prefix_v1"("p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_expected_object_identity_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsed_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_existing public.sip_versioned_output_prefix_rehearsal_receipts%ROWTYPE;
  v_instrument_id uuid;
  v_state jsonb;
  v_state_hash text;
  v_projection jsonb;
  v_projection_hash text;
  v_target_count integer;
BEGIN
  SELECT * INTO STRICT v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = p_artifact_id
    AND artifact.artifact_kind = 'versioned-output-prefix-v1'
    AND artifact.content_hash = btrim(p_expected_content_hash);
  IF NOT public.validate_sip_publish_operator_lease_v1(
    v_artifact.provider_slug, p_lease_id, p_lease_token
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  IF nullif(btrim(p_rehearsed_by), '') IS NULL
    OR btrim(p_expected_object_identity_hash) !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'versioned_output_prefix_rehearsal_actor_invalid'; END IF;
  v_instrument_id := (v_artifact.content->>'instrumentV2Id')::uuid;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:' || v_instrument_id::text, 0
  ));
  SELECT public.sip_versioned_output_prefix_state_v1(v_instrument_id)
  INTO STRICT v_state;
  IF v_state->'instrument'->>'file_path_reference'
      IS DISTINCT FROM v_artifact.content->>'oldFilePathReference'
    OR COALESCE((v_state->'instrument'->>'published')::boolean, false) IS NOT TRUE
  THEN RAISE EXCEPTION 'versioned_output_prefix_rehearsal_state_drift'; END IF;
  v_state_hash := encode(digest(convert_to(v_state::text, 'UTF8'), 'sha256'), 'hex');
  v_projection := public.sip_versioned_output_prefix_staging_projection_v1(v_artifact.id);
  IF (v_artifact.content->>'stagingProjectionCanonicalJson')::jsonb
      IS DISTINCT FROM v_projection
  THEN RAISE EXCEPTION 'versioned_output_prefix_staging_projection_drift'; END IF;
  v_projection_hash := encode(digest(convert_to(
    v_artifact.content->>'stagingProjectionCanonicalJson', 'UTF8'
  ), 'sha256'), 'hex');
  IF v_projection_hash IS DISTINCT FROM v_artifact.content->>'stagingProjectionHash'
  THEN RAISE EXCEPTION 'versioned_output_prefix_staging_projection_drift'; END IF;
  SELECT count(*)::integer INTO v_target_count
  FROM public.sip_versioned_output_prefix_staging_receipts receipt
  WHERE receipt.artifact_id = v_artifact.id;
  IF v_target_count IS DISTINCT FROM jsonb_array_length(v_artifact.content->'targets')
  THEN RAISE EXCEPTION 'versioned_output_prefix_full_keyset_required'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_versioned_output_prefix_staging_receipts receipt
    WHERE receipt.artifact_id=v_artifact.id
      AND (receipt.provider_lease_id IS DISTINCT FROM p_lease_id
        OR receipt.provider_lease_token_hash IS DISTINCT FROM encode(digest(
          convert_to(p_lease_token::text,'UTF8'),'sha256'
        ),'hex'))
  ) THEN RAISE EXCEPTION 'versioned_output_prefix_provider_lease_drift'; END IF;
  INSERT INTO public.sip_versioned_output_prefix_rehearsal_receipts(
    artifact_id, artifact_content_hash, provider_slug, provider_lease_id,
    provider_lease_token_hash,
    instrument_v2_id, old_state_hash, staging_projection_hash,
    object_identity_hash,
    staged_target_count, result, rehearsed_by
  ) VALUES (
    v_artifact.id, v_artifact.content_hash, v_artifact.provider_slug, p_lease_id,
    encode(digest(convert_to(p_lease_token::text,'UTF8'),'sha256'),'hex'),
    v_instrument_id, v_state_hash, v_projection_hash,
    btrim(p_expected_object_identity_hash), v_target_count,
    jsonb_build_object(
      'passed', true,
      'oldStateHash', v_state_hash,
      'stagingProjectionHash', v_projection_hash,
      'stagedTargetCount', v_target_count
    ), btrim(p_rehearsed_by)
  ) ON CONFLICT (artifact_id) DO NOTHING
  RETURNING * INTO v_existing;
  IF v_existing.id IS NULL THEN
    SELECT * INTO STRICT v_existing
    FROM public.sip_versioned_output_prefix_rehearsal_receipts receipt
    WHERE receipt.artifact_id = v_artifact.id;
    IF v_existing.artifact_content_hash IS DISTINCT FROM v_artifact.content_hash
      OR v_existing.provider_slug IS DISTINCT FROM v_artifact.provider_slug
      OR v_existing.provider_lease_id IS DISTINCT FROM p_lease_id
      OR v_existing.provider_lease_token_hash IS DISTINCT FROM encode(digest(
        convert_to(p_lease_token::text,'UTF8'),'sha256'
      ),'hex')
      OR v_existing.instrument_v2_id IS DISTINCT FROM v_instrument_id
      OR v_existing.old_state_hash IS DISTINCT FROM v_state_hash
      OR v_existing.staging_projection_hash IS DISTINCT FROM v_projection_hash
      OR v_existing.object_identity_hash IS DISTINCT FROM
        btrim(p_expected_object_identity_hash)
      OR v_existing.staged_target_count IS DISTINCT FROM v_target_count
      OR v_existing.rehearsed_by IS DISTINCT FROM btrim(p_rehearsed_by)
    THEN RAISE EXCEPTION 'versioned_output_prefix_rehearsal_replay_drift'; END IF;
  END IF;
  RETURN to_jsonb(v_existing);
END $_$;


ALTER FUNCTION "public"."sip_publish_rehearse_versioned_output_prefix_v1"("p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_expected_object_identity_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rehearsed_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_rollback_fmg_terminal_waits_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_manifest_hash" "text", "p_rolled_back_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_apply record;
  v_existing record;
  v_lease_owner text;
  v_receipt_id uuid := gen_random_uuid();
  v_updated integer;
  v_result jsonb;
BEGIN
  IF btrim(coalesce(p_contributor_slug, '')) <> 'fallout-music-group'
     OR p_lease_id IS NULL OR p_lease_token IS NULL
     OR coalesce(p_expected_manifest_hash, '') !~ '^[0-9a-f]{64}$'
     OR btrim(coalesce(p_rolled_back_by, '')) = '' THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_rollback_identity_invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended('fallout-music-group', 0)
  );
  SELECT lease.lease_owner INTO v_lease_owner
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
    AND lease.provider_slug = 'fallout-music-group'
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_invalid_provider_lease'
      USING ERRCODE = '55000';
  END IF;

  SELECT receipt.* INTO v_apply
  FROM public.sip_fmg_terminal_profile_wait_reconciliation_receipts receipt
  WHERE receipt.scope_key = 'issue-2437-fmg-terminal-profile-waits-v1'
    AND receipt.receipt_kind = 'apply'
  FOR SHARE;
  IF NOT FOUND OR v_apply.manifest_hash IS DISTINCT FROM p_expected_manifest_hash THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_apply_receipt_missing'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = 'fallout-music-group'
      AND run.status IN ('queued', 'running')
  ) OR EXISTS (
    SELECT 1
    FROM public.sip_fleet_run_items item
    JOIN public.sip_fleet_runs run ON run.id = item.run_id
    WHERE run.provider_slug = 'fallout-music-group'
      AND (
        item.status IN ('queued', 'running')
        OR (
          item.status = 'waiting_for_audio_profile'
          AND item.id NOT IN (
            '29bce41a-f448-4478-bf97-01edac4d34d1'::uuid,
            '854e9736-5f7d-46b0-86c6-e5f0a7903929'::uuid
          )
        )
      )
  ) THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_rollback_active_work'
      USING ERRCODE = '55000';
  END IF;

  SELECT receipt.* INTO v_existing
  FROM public.sip_fmg_terminal_profile_wait_reconciliation_receipts receipt
  WHERE receipt.scope_key = 'issue-2437-fmg-terminal-profile-waits-v1'
    AND receipt.receipt_kind = 'rollback'
  FOR SHARE;
  IF FOUND THEN
    IF v_existing.manifest_hash IS DISTINCT FROM p_expected_manifest_hash THEN
      RAISE EXCEPTION 'fmg_terminal_profile_wait_rollback_receipt_conflict'
        USING ERRCODE = '55000';
    END IF;
    IF (
      SELECT count(*)
      FROM public.sip_fleet_run_items item
      WHERE (
        item.id = '29bce41a-f448-4478-bf97-01edac4d34d1'::uuid
        AND item.run_id = 'f5216bfa-19e7-424d-b382-d7166913ffb1'::uuid
        AND item.instrument_v2_id = 'd822b904-ab46-4ed6-87d3-f414798606be'::uuid
        AND item.status = 'waiting_for_audio_profile'
        AND item.finished_at IS NULL
      ) OR (
        item.id = '854e9736-5f7d-46b0-86c6-e5f0a7903929'::uuid
        AND item.run_id = '7d5d825d-c648-4af8-9a46-b00c51285cb1'::uuid
        AND item.instrument_v2_id = '88821d01-71d6-438d-a0d1-8595789c9f85'::uuid
        AND item.status = 'waiting_for_audio_profile'
        AND item.finished_at IS NULL
      )
    ) IS DISTINCT FROM 2 THEN
      RAISE EXCEPTION 'fmg_terminal_profile_wait_rollback_idempotent_state_changed'
        USING ERRCODE = '55000';
    END IF;
    RETURN v_existing.result || jsonb_build_object('idempotent', true);
  END IF;

  PERFORM item.id
  FROM public.sip_fleet_run_items item
  WHERE item.id IN (
    '29bce41a-f448-4478-bf97-01edac4d34d1'::uuid,
    '854e9736-5f7d-46b0-86c6-e5f0a7903929'::uuid
  )
  ORDER BY item.id
  FOR UPDATE;

  IF NOT public.validate_sip_publish_operator_lease_v1(
    p_contributor_slug, p_lease_id, p_lease_token
  ) THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_rollback_lease_expired_before_write'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.sip_fleet_run_items item
  SET status = 'waiting_for_audio_profile',
      finished_at = NULL
  WHERE (
    item.id = '29bce41a-f448-4478-bf97-01edac4d34d1'::uuid
    AND item.run_id = 'f5216bfa-19e7-424d-b382-d7166913ffb1'::uuid
    AND item.instrument_v2_id = 'd822b904-ab46-4ed6-87d3-f414798606be'::uuid
    AND item.status = 'canceled'
    AND item.finished_at = '2026-07-24 06:32:57.437962+00'::timestamptz
  ) OR (
    item.id = '854e9736-5f7d-46b0-86c6-e5f0a7903929'::uuid
    AND item.run_id = '7d5d825d-c648-4af8-9a46-b00c51285cb1'::uuid
    AND item.instrument_v2_id = '88821d01-71d6-438d-a0d1-8595789c9f85'::uuid
    AND item.status = 'failed'
    AND item.finished_at = '2026-07-24 18:38:17.532446+00'::timestamptz
  );
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION 'fmg_terminal_profile_wait_rollback_state_changed'
      USING ERRCODE = '55000';
  END IF;

  v_result := jsonb_build_object(
    'scopeKey', 'issue-2437-fmg-terminal-profile-waits-v1',
    'providerSlug', 'fallout-music-group',
    'operationClass', 'terminal-history-status-only-rollback',
    'readinessAuthorized', false,
    'legacyReceiptBlocker', 'address_output_receipts_incomplete',
    'providerLeaseId', p_lease_id,
    'receiptId', v_receipt_id,
    'manifestHash', p_expected_manifest_hash,
    'rolledBackCount', 2,
    'restoredStatus', 'waiting_for_audio_profile',
    'idempotent', false
  );
  INSERT INTO public.sip_fmg_terminal_profile_wait_reconciliation_receipts(
    scope_key, receipt_kind, receipt_id, provider_slug, provider_lease_id,
    provider_lease_owner, manifest_hash, manifest, result, applied_by
  ) VALUES (
    'issue-2437-fmg-terminal-profile-waits-v1', 'rollback', v_receipt_id,
    'fallout-music-group', p_lease_id, v_lease_owner,
    p_expected_manifest_hash, v_apply.manifest, v_result,
    btrim(p_rolled_back_by)
  );
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_rollback_fmg_terminal_waits_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_manifest_hash" "text", "p_rolled_back_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_rollback_runtime_manifest_materialization_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_apply_run_id" "uuid", "p_expected_count" integer, "p_rolled_back_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "lock_timeout" TO '5s'
    AS $$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_rollback_run_id uuid;
  v_receipt public.sip_runtime_manifest_materialization_receipts%ROWTYPE;
  v_count integer;
  v_rollback_count integer;
BEGIN
  IF nullif(btrim(p_rolled_back_by), '') IS NULL
    OR NOT public.validate_sip_publish_operator_lease_v1(
      p_contributor_slug,
      p_lease_id,
      p_lease_token
    )
  THEN
    RAISE EXCEPTION 'runtime_manifest_rollback_authorization_invalid';
  END IF;
  SELECT artifact.* INTO v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = p_artifact_id
    AND artifact.provider_slug = btrim(p_contributor_slug)
    AND artifact.artifact_kind = 'runtime-manifest-materialization-v1';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'runtime_manifest_materialization_artifact_not_found';
  END IF;
  SELECT count(*) INTO v_count
  FROM public.sip_runtime_manifest_materialization_receipts receipt
  WHERE receipt.artifact_id = v_artifact.id
    AND receipt.run_id = p_expected_apply_run_id;
  IF p_expected_count IS NULL OR p_expected_count < 1
    OR jsonb_array_length(v_artifact.content->'instrumentV2Ids')
      <> p_expected_count
    OR v_count <> p_expected_count
    OR EXISTS (
      SELECT 1
      FROM public.sip_runtime_manifest_materialization_receipts receipt
      LEFT JOIN jsonb_array_elements_text(
        v_artifact.content->'instrumentV2Ids'
      ) requested(value)
        ON requested.value = receipt.instrument_v2_id::text
      WHERE receipt.artifact_id = v_artifact.id
        AND (
          receipt.run_id IS DISTINCT FROM p_expected_apply_run_id
          OR receipt.content_hash IS DISTINCT FROM v_artifact.content_hash
          OR requested.value IS NULL
        )
    )
  THEN
    RAISE EXCEPTION 'runtime_manifest_rollback_scope_mismatch';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    btrim(p_contributor_slug),
    0
  ));
  IF EXISTS (
    SELECT 1 FROM public.sip_runtime_manifest_rollback_receipts rollback
    WHERE rollback.artifact_id = v_artifact.id
  ) THEN
    SELECT count(*) INTO v_rollback_count
    FROM public.sip_runtime_manifest_rollback_receipts rollback
    WHERE rollback.artifact_id = v_artifact.id
      AND rollback.apply_run_id = p_expected_apply_run_id;
    IF v_rollback_count <> p_expected_count THEN
      RAISE EXCEPTION 'runtime_manifest_rollback_receipts_partial';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM public.sip_runtime_manifest_materialization_receipts receipt
      JOIN public.sip_runtime_manifest_rollback_receipts rollback
        ON rollback.artifact_id = receipt.artifact_id
       AND rollback.instrument_v2_id = receipt.instrument_v2_id
      LEFT JOIN public.instrument_runtime_sample_manifests manifest
        ON manifest.instrument_v2_id = receipt.instrument_v2_id
      LEFT JOIN public.instrument_v2_runtime_readiness readiness
        ON readiness.instrument_v2_id = receipt.instrument_v2_id
      WHERE receipt.artifact_id = v_artifact.id
        AND (
          manifest.instrument_v2_id IS NOT NULL
          OR readiness.instrument_v2_id IS NOT NULL
        )
    ) THEN
      RAISE EXCEPTION 'runtime_manifest_rollback_idempotency_drift';
    END IF;
    SELECT rollback.rollback_run_id INTO STRICT v_rollback_run_id
    FROM public.sip_runtime_manifest_rollback_receipts rollback
    WHERE rollback.artifact_id = v_artifact.id
    LIMIT 1;
    RETURN jsonb_build_object(
      'artifactId', v_artifact.id,
      'rollbackRunId', v_rollback_run_id,
      'instrumentCount', v_count,
      'idempotent', true
    );
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = btrim(p_contributor_slug)
      AND run.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'active_provider_run';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'instrument-runtime-sample-manifest:' || receipt.instrument_v2_id::text,
    0
  ))
  FROM public.sip_runtime_manifest_materialization_receipts receipt
  WHERE receipt.artifact_id = v_artifact.id
    AND receipt.run_id = p_expected_apply_run_id
  ORDER BY receipt.instrument_v2_id;
  PERFORM public.validate_runtime_manifest_materialization_plan_v1(
    p_contributor_slug,
    v_artifact.content,
    false
  );
  IF EXISTS (
    SELECT 1
    FROM public.sip_runtime_manifest_materialization_receipts receipt
    LEFT JOIN public.instrument_runtime_sample_manifests manifest
      ON manifest.instrument_v2_id = receipt.instrument_v2_id
     AND manifest.manifest_sha256 = receipt.manifest_sha256
    LEFT JOIN public.instrument_v2_runtime_readiness readiness
      ON readiness.instrument_v2_id = receipt.instrument_v2_id
     AND readiness.manifest_sha256 = receipt.manifest_sha256
    WHERE receipt.artifact_id = v_artifact.id
      AND receipt.run_id = p_expected_apply_run_id
      AND (
        manifest.instrument_v2_id IS NULL
        OR readiness.instrument_v2_id IS NULL
        OR manifest.generated_at IS DISTINCT FROM
          receipt.manifest_generated_at
        OR readiness.evaluated_at IS DISTINCT FROM
          receipt.readiness_evaluated_at
        OR readiness.address_ready IS DISTINCT FROM
          (receipt.runtime_readiness->>'addressReady')::boolean
        OR readiness.behavior_ready IS DISTINCT FROM
          (receipt.runtime_readiness->>'behaviorReady')::boolean
        OR readiness.fallback_state IS DISTINCT FROM
          receipt.runtime_readiness->>'fallbackState'
      )
  ) THEN
    RAISE EXCEPTION 'runtime_manifest_rollback_state_drift';
  END IF;

  INSERT INTO public.sip_fleet_runs(
    provider_slug,
    idempotency_key,
    plan_artifact_id,
    submitted_by,
    provider_lease_id,
    provider_lease_token,
    status,
    started_at,
    finished_at,
    result_payload
  ) VALUES (
    btrim(p_contributor_slug),
    'runtime-manifest-rollback:' || v_artifact.content_hash,
    v_artifact.id,
    btrim(p_rolled_back_by),
    p_lease_id,
    p_lease_token,
    'completed',
    clock_timestamp(),
    clock_timestamp(),
    jsonb_build_object(
      'operation', 'runtime-manifest-rollback',
      'applyRunId', p_expected_apply_run_id,
      'instrumentCount', p_expected_count
    )
  ) RETURNING id INTO v_rollback_run_id;

  FOR v_receipt IN
    SELECT *
    FROM public.sip_runtime_manifest_materialization_receipts receipt
    WHERE receipt.artifact_id = v_artifact.id
      AND receipt.run_id = p_expected_apply_run_id
    ORDER BY receipt.instrument_v2_id
  LOOP
    DELETE FROM public.instrument_v2_runtime_readiness readiness
    WHERE readiness.instrument_v2_id = v_receipt.instrument_v2_id
      AND readiness.manifest_sha256 = v_receipt.manifest_sha256;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'runtime_manifest_rollback_readiness_drift';
    END IF;
    DELETE FROM public.instrument_runtime_sample_manifests manifest
    WHERE manifest.instrument_v2_id = v_receipt.instrument_v2_id
      AND manifest.manifest_sha256 = v_receipt.manifest_sha256;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'runtime_manifest_rollback_manifest_drift';
    END IF;
    INSERT INTO public.sip_runtime_manifest_rollback_receipts(
      artifact_id,
      instrument_v2_id,
      apply_run_id,
      rollback_run_id,
      manifest_sha256,
      rolled_back_by,
      authorizing_xid
    ) VALUES (
      v_artifact.id,
      v_receipt.instrument_v2_id,
      p_expected_apply_run_id,
      v_rollback_run_id,
      v_receipt.manifest_sha256,
      btrim(p_rolled_back_by),
      txid_current()
    );
    INSERT INTO public.sip_fleet_run_items(
      run_id,
      item_key,
      instrument_v2_id,
      status,
      started_at,
      finished_at,
      result_payload
    ) VALUES (
      v_rollback_run_id,
      'runtime-manifest-rollback:' || v_receipt.instrument_v2_id::text,
      v_receipt.instrument_v2_id,
      'completed',
      clock_timestamp(),
      clock_timestamp(),
      jsonb_build_object(
        'fallbackState', 'construct_hydration',
        'manifestSha256', v_receipt.manifest_sha256
      )
    );
  END LOOP;

  RETURN jsonb_build_object(
    'artifactId', v_artifact.id,
    'applyRunId', p_expected_apply_run_id,
    'rollbackRunId', v_rollback_run_id,
    'instrumentCount', p_expected_count,
    'fallbackState', 'construct_hydration',
    'idempotent', false
  );
END;
$$;


ALTER FUNCTION "public"."sip_publish_rollback_runtime_manifest_materialization_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_expected_apply_run_id" "uuid", "p_expected_count" integer, "p_rolled_back_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_rollback_versioned_output_prefix_v1"("p_application_receipt_id" "uuid", "p_expected_application_receipt_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rolled_back_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_application public.sip_versioned_output_prefix_application_receipts%ROWTYPE;
  v_existing public.sip_versioned_output_prefix_rollback_receipts%ROWTYPE;
  v_current_state jsonb;
  v_restored_state jsonb;
  v_output jsonb;
  v_restored_hash text;
  v_lease public.sip_fleet_provider_leases%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_application FROM public.sip_versioned_output_prefix_application_receipts
  WHERE id=p_application_receipt_id AND application_receipt_hash=btrim(p_expected_application_receipt_hash);
  IF nullif(btrim(p_rolled_back_by), '') IS NULL
  THEN RAISE EXCEPTION 'versioned_output_prefix_rollback_actor_invalid'; END IF;
  -- Use the same lock order as application and provider-run admission. This
  -- makes the quiescence observation, exact rollback, and replay receipt one
  -- serial transaction for this provider and instrument.
  PERFORM pg_advisory_xact_lock(hashtextextended(v_application.provider_slug,0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:' || v_application.instrument_v2_id::text,0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-fleet-executor-admission',0));
  SELECT * INTO STRICT v_lease FROM public.sip_fleet_provider_leases lease
  WHERE lease.id=p_lease_id AND lease.provider_slug=v_application.provider_slug
    AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp() FOR UPDATE;
  IF EXISTS (
      SELECT 1 FROM public.sip_fleet_runs run
      WHERE run.provider_slug=v_application.provider_slug
        AND run.status IN ('queued','running')
    ) OR EXISTS (
      SELECT 1 FROM public.sip_fleet_run_items item
      JOIN public.sip_fleet_runs run ON run.id=item.run_id
      WHERE run.provider_slug=v_application.provider_slug
        AND item.status IN ('queued','running','waiting_for_audio_profile')
    ) OR EXISTS (
      SELECT 1 FROM public.sip_fleet_executor_leases executor
      WHERE executor.lease_expires_at>clock_timestamp()
    ) OR EXISTS (
      SELECT 1 FROM public.sip_pipeline_runs pipeline
      WHERE pipeline.contributor_slug=v_application.provider_slug
        AND pipeline.status IN ('queued','running')
    ) OR EXISTS (
      SELECT 1 FROM public.sip_versioned_output_prefix_staging_operations operation
      WHERE operation.provider_slug=v_application.provider_slug
        AND (operation.status='running' OR (operation.status='ambiguous' AND NOT EXISTS (
          SELECT 1 FROM public.sip_versioned_output_prefix_premutation_reconciliation_receipts clearance
          WHERE clearance.staging_operation_id=operation.id
        )))
    )
  THEN RAISE EXCEPTION 'versioned_output_prefix_provider_not_quiescent'; END IF;
  SELECT * INTO v_existing FROM public.sip_versioned_output_prefix_rollback_receipts
  WHERE application_receipt_id=v_application.id;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.rolled_back_by IS DISTINCT FROM btrim(p_rolled_back_by)
      OR public.sip_versioned_output_prefix_state_v1(
        v_application.instrument_v2_id
      ) IS DISTINCT FROM v_application.old_state
      OR v_existing.restored_state_hash IS DISTINCT FROM encode(digest(
        convert_to(v_application.old_state::text, 'UTF8'), 'sha256'
      ), 'hex')
    THEN RAISE EXCEPTION 'versioned_output_prefix_rollback_replay_drift'; END IF;
    RETURN to_jsonb(v_existing) || jsonb_build_object('idempotent',true);
  END IF;
  SELECT public.sip_versioned_output_prefix_state_v1(instrument.id)
  INTO STRICT v_current_state FROM public.instruments_v2 instrument
  WHERE instrument.id=v_application.instrument_v2_id FOR UPDATE;
  IF v_current_state IS DISTINCT FROM v_application.new_state
  THEN RAISE EXCEPTION 'versioned_output_prefix_rollback_state_drift'; END IF;
  DELETE FROM public.instrument_v2_publish_output_manifest WHERE instrument_v2_id=v_application.instrument_v2_id;
  PERFORM set_config('app.sip_publish_coordinator_authorized','on',true);
  UPDATE public.instruments_v2 SET file_path_reference=v_application.old_file_path_reference
  WHERE id=v_application.instrument_v2_id;
  FOR v_output IN SELECT value FROM jsonb_array_elements(v_application.old_state->'outputs') LOOP
    INSERT INTO public.instrument_v2_publish_output_manifest
    SELECT * FROM jsonb_populate_record(NULL::public.instrument_v2_publish_output_manifest,v_output);
  END LOOP;
  DELETE FROM public.instrument_v2_runtime_readiness
  WHERE instrument_v2_id = v_application.instrument_v2_id;
  DELETE FROM public.instrument_runtime_sample_manifests
  WHERE instrument_v2_id = v_application.instrument_v2_id;
  DELETE FROM public.instrument_v2_deterministic_publication_admissions
  WHERE instrument_v2_id = v_application.instrument_v2_id;
  IF jsonb_typeof(v_application.old_state->'manifest') = 'object' THEN
    INSERT INTO public.instrument_runtime_sample_manifests
    SELECT * FROM jsonb_populate_record(
      NULL::public.instrument_runtime_sample_manifests,
      v_application.old_state->'manifest'
    );
  END IF;
  IF jsonb_typeof(v_application.old_state->'readiness') = 'object' THEN
    INSERT INTO public.instrument_v2_runtime_readiness
    SELECT * FROM jsonb_populate_record(
      NULL::public.instrument_v2_runtime_readiness,
      v_application.old_state->'readiness'
    );
  END IF;
  -- Restore publication without rematerializing the exact manifest/readiness
  -- rows above. The ordinary publication primitive refreshes their timestamps,
  -- which would make receipt-exact rollback impossible.
  PERFORM set_config('app.sip_deterministic_publication_authorized','on',true);
  UPDATE public.instruments_v2
  SET published = COALESCE(
    (v_application.old_state->'instrument'->>'published')::boolean,
    false
  )
  WHERE id = v_application.instrument_v2_id;
  PERFORM set_config('app.sip_deterministic_publication_authorized','off',true);
  DELETE FROM public.instrument_v2_deterministic_publication_admissions
  WHERE instrument_v2_id = v_application.instrument_v2_id;
  IF jsonb_typeof(v_application.old_state->'admission') = 'object' THEN
    INSERT INTO public.instrument_v2_deterministic_publication_admissions
    SELECT * FROM jsonb_populate_record(
      NULL::public.instrument_v2_deterministic_publication_admissions,
      v_application.old_state->'admission'
    );
  END IF;
  v_restored_state := public.sip_versioned_output_prefix_state_v1(
    v_application.instrument_v2_id
  );
  IF v_restored_state IS DISTINCT FROM v_application.old_state
  THEN RAISE EXCEPTION 'versioned_output_prefix_rollback_restore_drift'; END IF;
  v_restored_hash := encode(digest(convert_to(v_restored_state::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.sip_versioned_output_prefix_rollback_receipts(
    application_receipt_id,provider_lease_id,restored_state_hash,
    authorizing_xid,rolled_back_by
  ) VALUES (
    v_application.id,p_lease_id,v_restored_hash,txid_current(),
    btrim(p_rolled_back_by)
  )
  RETURNING * INTO v_existing;
  RETURN to_jsonb(v_existing) || jsonb_build_object('idempotent',false);
END $$;


ALTER FUNCTION "public"."sip_publish_rollback_versioned_output_prefix_v1"("p_application_receipt_id" "uuid", "p_expected_application_receipt_hash" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rolled_back_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_runtime_manifest_plan_approve_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_approved_by" "text", "p_rehearsal_run_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "public"."sip_fleet_plan_artifact_approvals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_approval public.sip_fleet_plan_artifact_approvals%ROWTYPE;
BEGIN
  IF nullif(btrim(p_approved_by), '') IS NULL
    OR coalesce(p_expected_content_hash, '') !~ '^[0-9a-f]{64}$'
    OR NOT public.validate_sip_publish_operator_lease_v1(
      p_contributor_slug,
      p_lease_id,
      p_lease_token
    )
  THEN
    RAISE EXCEPTION 'runtime_manifest_materialization_approval_invalid';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_plan_artifacts artifact
    JOIN public.sip_anchor_object_verification_rehearsals rehearsal
      ON rehearsal.artifact_id = artifact.id
     AND rehearsal.content_hash = artifact.content_hash
    WHERE artifact.id = p_artifact_id
      AND artifact.provider_slug = btrim(p_contributor_slug)
      AND artifact.artifact_kind = 'runtime-manifest-materialization-v1'
      AND artifact.content_hash = p_expected_content_hash
      AND rehearsal.id = p_rehearsal_run_id
      AND rehearsal.provider_lease_id = p_lease_id
      AND rehearsal.provider_lease_token = p_lease_token
      AND rehearsal.status = 'passed'
      AND rehearsal.completed_at >= clock_timestamp() - interval '15 minutes'
      AND artifact.content->'approval'->>'rehearsalRunId' =
        p_rehearsal_run_id::text
  ) THEN
    RAISE EXCEPTION 'passed_runtime_manifest_rehearsal_required';
  END IF;
  INSERT INTO public.sip_fleet_plan_artifact_approvals(
    artifact_id,
    content_hash,
    approved_by,
    approval_metadata
  ) VALUES (
    p_artifact_id,
    p_expected_content_hash,
    btrim(p_approved_by),
    jsonb_build_object('rehearsalRunId', p_rehearsal_run_id)
  )
  ON CONFLICT (artifact_id) DO NOTHING
  RETURNING * INTO v_approval;
  IF v_approval.artifact_id IS NULL THEN
    SELECT * INTO STRICT v_approval
    FROM public.sip_fleet_plan_artifact_approvals approval
    WHERE approval.artifact_id = p_artifact_id;
    IF v_approval.content_hash <> p_expected_content_hash
      OR v_approval.approved_by <> btrim(p_approved_by)
      OR v_approval.approval_metadata <>
        jsonb_build_object('rehearsalRunId', p_rehearsal_run_id)
    THEN
      RAISE EXCEPTION 'artifact_approval_payload_mismatch';
    END IF;
  END IF;
  RETURN v_approval;
END;
$_$;


ALTER FUNCTION "public"."sip_publish_runtime_manifest_plan_approve_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_approved_by" "text", "p_rehearsal_run_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_runtime_manifest_plan_upload_v1"("p_contributor_slug" "text", "p_content" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "public"."sip_fleet_plan_artifacts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_hash text;
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
BEGIN
  IF NOT public.validate_sip_publish_operator_lease_v1(
    p_contributor_slug,
    p_lease_id,
    p_lease_token
  ) THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;
  PERFORM public.validate_runtime_manifest_materialization_plan_v1(
    p_contributor_slug,
    p_content,
    true
  );
  v_hash := encode(digest(convert_to(p_content::text, 'UTF8'), 'sha256'), 'hex');
  INSERT INTO public.sip_fleet_plan_artifacts(
    provider_slug,
    artifact_kind,
    content_hash,
    content,
    created_by
  ) VALUES (
    btrim(p_contributor_slug),
    'runtime-manifest-materialization-v1',
    v_hash,
    p_content,
    (SELECT lease_owner FROM public.sip_fleet_provider_leases
      WHERE id = p_lease_id)
  )
  ON CONFLICT (provider_slug, artifact_kind, content_hash) DO NOTHING
  RETURNING * INTO v_artifact;
  IF v_artifact.id IS NULL THEN
    SELECT * INTO STRICT v_artifact
    FROM public.sip_fleet_plan_artifacts artifact
    WHERE artifact.provider_slug = btrim(p_contributor_slug)
      AND artifact.artifact_kind = 'runtime-manifest-materialization-v1'
      AND artifact.content_hash = v_hash;
  END IF;
  RETURN v_artifact;
END;
$$;


ALTER FUNCTION "public"."sip_publish_runtime_manifest_plan_upload_v1"("p_contributor_slug" "text", "p_content" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_runtime_manifest_rehearsal_begin_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_rehearsal public.sip_anchor_object_verification_rehearsals%ROWTYPE;
BEGIN
  IF NOT public.validate_sip_publish_operator_lease_v1(
    p_contributor_slug,
    p_lease_id,
    p_lease_token
  ) THEN
    RAISE EXCEPTION 'invalid_provider_lease';
  END IF;
  SELECT artifact.* INTO v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = p_artifact_id
    AND artifact.provider_slug = btrim(p_contributor_slug)
    AND artifact.artifact_kind = 'runtime-manifest-materialization-v1';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'runtime_manifest_materialization_artifact_not_found';
  END IF;
  PERFORM public.validate_runtime_manifest_materialization_plan_v1(
    p_contributor_slug,
    v_artifact.content,
    true
  );
  INSERT INTO public.sip_anchor_object_verification_rehearsals(
    id,
    artifact_id,
    content_hash,
    provider_slug,
    provider_lease_id,
    provider_lease_token
  ) VALUES (
    (v_artifact.content->'approval'->>'rehearsalRunId')::uuid,
    v_artifact.id,
    v_artifact.content_hash,
    btrim(p_contributor_slug),
    p_lease_id,
    p_lease_token
  )
  ON CONFLICT (
    artifact_id,
    content_hash,
    provider_lease_id,
    provider_lease_token
  ) DO NOTHING
  RETURNING * INTO v_rehearsal;
  IF v_rehearsal.id IS NULL THEN
    SELECT rehearsal.* INTO STRICT v_rehearsal
    FROM public.sip_anchor_object_verification_rehearsals rehearsal
    WHERE rehearsal.artifact_id = v_artifact.id
      AND rehearsal.content_hash = v_artifact.content_hash
      AND rehearsal.provider_lease_id = p_lease_id
      AND rehearsal.provider_lease_token = p_lease_token;
  END IF;
  IF v_rehearsal.id::text <>
      v_artifact.content->'approval'->>'rehearsalRunId'
    OR v_rehearsal.status = 'failed'
  THEN
    RAISE EXCEPTION 'runtime_manifest_materialization_rehearsal_conflict';
  END IF;
  RETURN jsonb_build_object(
    'rehearsalRunId', v_rehearsal.id,
    'artifactId', v_artifact.id,
    'contentHash', v_artifact.content_hash,
    'content', v_artifact.content,
    'status', v_rehearsal.status
  );
END;
$$;


ALTER FUNCTION "public"."sip_publish_runtime_manifest_rehearsal_begin_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_publish_stage_versioned_output_prefix_v1"("p_contributor_slug" "text", "p_content" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_staging_operation_id" "uuid", "p_staging_operation_token" "uuid", "p_expected_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_content_hash text;
  v_instrument_id uuid;
  v_old_pointer text;
  v_new_pointer text;
  v_target jsonb;
  v_construct_count integer;
  v_projection jsonb;
  v_projection_hash text;
  v_expected_projection_hash text;
  v_format text;
  v_quality smallint;
  v_lease public.sip_fleet_provider_leases%ROWTYPE;
  v_operation public.sip_versioned_output_prefix_staging_operations%ROWTYPE;
BEGIN
  v_instrument_id := (p_content->>'instrumentV2Id')::uuid;
  v_content_hash := encode(digest(convert_to(p_content::text, 'UTF8'), 'sha256'), 'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_contributor_slug),0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:' || v_instrument_id::text,0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-fleet-executor-admission',0));
  SELECT * INTO STRICT v_lease FROM public.sip_fleet_provider_leases lease
  WHERE lease.id=p_lease_id AND lease.provider_slug=btrim(p_contributor_slug)
    AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
    AND lease.lease_expires_at>clock_timestamp() FOR UPDATE;
  SELECT * INTO STRICT v_operation
  FROM public.sip_versioned_output_prefix_staging_operations operation
  WHERE operation.id=p_staging_operation_id
    AND operation.operation_token=p_staging_operation_token
    AND operation.provider_slug=btrim(p_contributor_slug)
    AND operation.instrument_v2_id=v_instrument_id
    AND operation.provider_lease_id=p_lease_id
    AND operation.request_hash=btrim(p_expected_request_hash)
    AND operation.provider_lease_token_hash=encode(digest(
      convert_to(p_lease_token::text,'UTF8'),'sha256'
    ),'hex') FOR UPDATE;
  IF v_operation.status='completed' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.sip_fleet_plan_artifacts artifact
      WHERE artifact.id=v_operation.artifact_id
        AND artifact.content_hash=v_content_hash
    ) THEN RAISE EXCEPTION 'versioned_output_prefix_staging_replay_drift'; END IF;
    RETURN v_operation.result || jsonb_build_object('idempotent',true);
  ELSIF v_operation.status<>'running' THEN
    RAISE EXCEPTION 'versioned_output_prefix_staging_operation_unresolved';
  END IF;
  IF jsonb_typeof(p_content) IS DISTINCT FROM 'object'
    OR p_content->>'schemaVersion' IS DISTINCT FROM 'sip-versioned-output-prefix-v1'
    OR p_content->>'providerSlug' IS DISTINCT FROM btrim(p_contributor_slug)
    OR jsonb_typeof(p_content->'targets') IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_content->'targets') = 0
    OR p_content->>'processorConfigSha256' !~ '^[0-9a-f]{64}$'
    OR p_content->>'contentSetHash' !~ '^[0-9a-f]{64}$'
    OR jsonb_typeof((p_content->>'contentSetCanonicalJson')::jsonb)
      IS DISTINCT FROM 'object'
    OR encode(digest(convert_to(
      p_content->>'contentSetCanonicalJson', 'UTF8'
    ), 'sha256'), 'hex') IS DISTINCT FROM p_content->>'contentSetHash'
    OR p_content->>'stagingProjectionHash' !~ '^[0-9a-f]{64}$'
    OR jsonb_typeof((p_content->>'stagingProjectionCanonicalJson')::jsonb)
      IS DISTINCT FROM 'array'
    OR encode(digest(convert_to(
      p_content->>'stagingProjectionCanonicalJson', 'UTF8'
    ), 'sha256'), 'hex') IS DISTINCT FROM p_content->>'stagingProjectionHash'
    OR nullif(btrim(p_content->>'stagingRunId'), '') IS NULL
  THEN RAISE EXCEPTION 'versioned_output_prefix_artifact_invalid'; END IF;
  IF (p_content->>'contentSetCanonicalJson')::jsonb IS DISTINCT FROM
    jsonb_build_object(
      'processorConfigSha256', p_content->>'processorConfigSha256',
      'targets', (
        SELECT jsonb_agg(identity_value ORDER BY
          sample_path_construct_id, format, quality
        )
        FROM (
      SELECT jsonb_build_object(
        'samplePathConstructId', target->>'samplePathConstructId',
        'originalSampleId', target->>'originalSampleId',
        'relativePath', target->>'relativePath',
        'format', target->>'format',
        'quality', (target->>'quality')::integer,
        'sourceS3Key', target->>'sourceS3Key',
        'sourceObjectIdentity', target->'sourceObjectIdentity',
        'sourceTerminalEvidence', target->'sourceTerminalEvidence',
        'processingInput',
          ((target->'processingInput') - 'filePathReference'::text) ||
          jsonb_build_object(
            'target', ((target->'processingInput')->'target') - 's3Key'::text
          )
      ) AS identity_value,
        target->>'samplePathConstructId' AS sample_path_construct_id,
        target->>'format' AS format,
        (target->>'quality')::integer AS quality
      FROM jsonb_array_elements(p_content->'targets') target
        ) identities
      )
    )
  THEN RAISE EXCEPTION 'versioned_output_prefix_content_set_drift'; END IF;
  v_old_pointer := btrim(p_content->>'oldFilePathReference');
  v_new_pointer := btrim(p_content->>'newFilePathReference');
  IF v_old_pointer !~ '^[A-Za-z0-9._/-]+$'
    OR v_new_pointer IS DISTINCT FROM
      v_old_pointer || '_revision-' || left(p_content->>'contentSetHash', 12)
  THEN RAISE EXCEPTION 'versioned_output_prefix_noncanonical'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'versioned-output-prefix:' || v_instrument_id::text, 0
  ));
  IF NOT EXISTS (
    SELECT 1 FROM public.instruments_v2 instrument
    WHERE instrument.id=v_instrument_id
      AND instrument.file_path_reference=v_old_pointer
      AND instrument.published
  ) THEN RAISE EXCEPTION 'versioned_output_prefix_instrument_drift'; END IF;
  INSERT INTO public.sip_fleet_plan_artifacts(
    provider_slug, artifact_kind, content_hash, content, created_by
  ) VALUES (
    btrim(p_contributor_slug), 'versioned-output-prefix-v1', v_content_hash,
    p_content, (SELECT lease_owner FROM public.sip_fleet_provider_leases WHERE id=p_lease_id)
  ) ON CONFLICT (provider_slug, artifact_kind, content_hash) DO NOTHING
  RETURNING * INTO v_artifact;
  IF v_artifact.id IS NULL THEN
    SELECT * INTO STRICT v_artifact FROM public.sip_fleet_plan_artifacts artifact
    WHERE artifact.provider_slug=btrim(p_contributor_slug)
      AND artifact.artifact_kind='versioned-output-prefix-v1'
      AND artifact.content_hash=v_content_hash;
  END IF;
  SELECT count(DISTINCT construct.id) INTO v_construct_count
  FROM public.sample_path_constructs construct
  WHERE construct.instrument_v2_id=v_instrument_id;
  IF jsonb_array_length(p_content->'targets') <> v_construct_count * 9
  THEN RAISE EXCEPTION 'versioned_output_prefix_full_keyset_required'; END IF;
  FOR v_target IN SELECT value FROM jsonb_array_elements(p_content->'targets') LOOP
    v_format := v_target->>'format';
    v_quality := CASE
      WHEN COALESCE(v_target->>'quality', '') ~ '^[0-9]+$'
      THEN (v_target->>'quality')::smallint
      ELSE NULL
    END;
    IF nullif(btrim(v_target->>'relativePath'), '') IS NULL
      OR v_target->>'relativePath' LIKE '/%'
      OR v_target->>'relativePath' LIKE '%..%'
      OR v_target->>'s3Key' IS DISTINCT FROM
        'instrument_samples/v2/' || v_new_pointer || '/' ||
          (v_target->>'relativePath')
      OR NOT (
        (v_format = 'mp3' AND v_quality BETWEEN 1 AND 5)
        OR (v_format = 'ogg' AND v_quality BETWEEN 2 AND 5)
      )
      OR v_target->>'processingFingerprintSha256' !~ '^[0-9a-f]{64}$'
      OR v_target->>'contentIntentToken' !~ '^[0-9a-f]{64}$'
      OR jsonb_typeof(v_target->'sourceObjectIdentity') IS DISTINCT FROM 'object'
      OR jsonb_typeof(v_target->'outputObjectIdentity') IS DISTINCT FROM 'object'
      OR v_target->'sourceObjectIdentity' IS DISTINCT FROM jsonb_build_object(
        'eTag', v_target->'sourceObjectIdentity'->'eTag',
        'versionId', v_target->'sourceObjectIdentity'->'versionId',
        'contentLength', v_target->'sourceObjectIdentity'->'contentLength',
        'lastModified', v_target->'sourceObjectIdentity'->'lastModified'
      )
      OR v_target->'outputObjectIdentity' IS DISTINCT FROM jsonb_build_object(
        'eTag', v_target->'outputObjectIdentity'->'eTag',
        'versionId', v_target->'outputObjectIdentity'->'versionId',
        'contentLength', v_target->'outputObjectIdentity'->'contentLength',
        'lastModified', v_target->'outputObjectIdentity'->'lastModified'
      )
      OR jsonb_typeof(v_target->'sourceObjectIdentity'->'eTag') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_target->'sourceObjectIdentity'->'contentLength') IS DISTINCT FROM 'number'
      OR jsonb_typeof(v_target->'sourceObjectIdentity'->'versionId') NOT IN ('string', 'null')
      OR jsonb_typeof(v_target->'sourceObjectIdentity'->'lastModified') NOT IN ('string', 'null')
      OR nullif(btrim(v_target->'sourceObjectIdentity'->>'eTag'), '') IS NULL
      OR v_target->'sourceObjectIdentity'->>'eTag' ~ '^[[:space:]]|[[:space:]]$'
      OR (v_target->'sourceObjectIdentity'->>'contentLength') !~ '^[0-9]+$'
      OR (CASE
        WHEN (v_target->'sourceObjectIdentity'->>'contentLength') ~ '^[0-9]+$'
        THEN (v_target->'sourceObjectIdentity'->>'contentLength')::numeric > 9007199254740991
        ELSE false
      END)
      OR (jsonb_typeof(v_target->'sourceObjectIdentity'->'versionId') = 'string'
        AND (nullif(btrim(v_target->'sourceObjectIdentity'->>'versionId'), '') IS NULL
          OR v_target->'sourceObjectIdentity'->>'versionId' ~ '^[[:space:]]|[[:space:]]$'))
      OR (jsonb_typeof(v_target->'sourceObjectIdentity'->'lastModified') = 'string'
        AND (nullif(btrim(v_target->'sourceObjectIdentity'->>'lastModified'), '') IS NULL
          OR v_target->'sourceObjectIdentity'->>'lastModified' ~ '^[[:space:]]|[[:space:]]$'))
      OR (nullif(btrim(v_target->'sourceObjectIdentity'->>'versionId'), '') IS NULL
        AND nullif(btrim(v_target->'sourceObjectIdentity'->>'lastModified'), '') IS NULL)
      OR v_target->>'outputContentSha256' !~ '^[0-9a-f]{64}$'
      OR jsonb_typeof(v_target->'outputObjectIdentity'->'eTag') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_target->'outputObjectIdentity'->'contentLength') IS DISTINCT FROM 'number'
      OR jsonb_typeof(v_target->'outputObjectIdentity'->'versionId') NOT IN ('string', 'null')
      OR jsonb_typeof(v_target->'outputObjectIdentity'->'lastModified') NOT IN ('string', 'null')
      OR nullif(btrim(v_target->'outputObjectIdentity'->>'eTag'), '') IS NULL
      OR v_target->'outputObjectIdentity'->>'eTag' ~ '^[[:space:]]|[[:space:]]$'
      OR (v_target->'outputObjectIdentity'->>'contentLength') !~ '^[0-9]+$'
      OR (CASE
        WHEN (v_target->'outputObjectIdentity'->>'contentLength') ~ '^[0-9]+$'
        THEN (v_target->'outputObjectIdentity'->>'contentLength')::numeric > 9007199254740991
        ELSE false
      END)
      OR (jsonb_typeof(v_target->'outputObjectIdentity'->'versionId') = 'string'
        AND (nullif(btrim(v_target->'outputObjectIdentity'->>'versionId'), '') IS NULL
          OR v_target->'outputObjectIdentity'->>'versionId' ~ '^[[:space:]]|[[:space:]]$'))
      OR (jsonb_typeof(v_target->'outputObjectIdentity'->'lastModified') = 'string'
        AND (nullif(btrim(v_target->'outputObjectIdentity'->>'lastModified'), '') IS NULL
          OR v_target->'outputObjectIdentity'->>'lastModified' ~ '^[[:space:]]|[[:space:]]$'))
      OR (nullif(btrim(v_target->'outputObjectIdentity'->>'versionId'), '') IS NULL
        AND nullif(btrim(v_target->'outputObjectIdentity'->>'lastModified'), '') IS NULL)
      OR jsonb_typeof(v_target->'sourceTerminalEvidence') IS DISTINCT FROM 'object'
      OR jsonb_typeof(v_target->'processingInput') IS DISTINCT FROM 'object'
      OR v_target->'processingInput'->>'fingerprintSchema' IS DISTINCT FROM 'sip-v2-output-v2'
      OR v_target->'processingInput'->>'instrumentV2Id' IS DISTINCT FROM v_instrument_id::text
      OR v_target->'processingInput'->>'filePathReference' IS DISTINCT FROM v_new_pointer
      OR v_target->'processingInput'->>'samplePathConstructId'
        IS DISTINCT FROM v_target->>'samplePathConstructId'
      OR v_target->'processingInput'->>'originalSampleId'
        IS DISTINCT FROM v_target->>'originalSampleId'
      OR v_target->'processingInput'->>'sourceS3Key' IS DISTINCT FROM v_target->>'sourceS3Key'
      OR v_target->'processingInput'->'sourceObjectIdentity'
        IS DISTINCT FROM v_target->'sourceObjectIdentity'
      OR v_target->'processingInput'->'target'->>'s3Key' IS DISTINCT FROM v_target->>'s3Key'
      OR v_target->'processingInput'->'target'->>'format' IS DISTINCT FROM v_format
      OR v_target->'processingInput'->'target'->>'quality' IS DISTINCT FROM v_quality::text
      OR NOT EXISTS (
        SELECT 1
        FROM public.sample_path_constructs construct
        JOIN public.samples_original_paths source
          ON source.id = construct.sample_original_path_id
        WHERE construct.id = (v_target->>'samplePathConstructId')::uuid
          AND construct.instrument_v2_id = v_instrument_id
          AND construct.sample_original_path_id = (v_target->>'originalSampleId')::uuid
          AND source.s3_path = v_target->>'sourceS3Key'
          AND v_target->'sourceTerminalEvidence' = jsonb_build_object(
            'status',CASE WHEN source.completed_at IS NULL THEN 'legacy_quiescent' ELSE 'completed' END,
            'completedAt',CASE WHEN source.completed_at IS NULL THEN NULL ELSE to_char(
              source.completed_at AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
            'updatedAt',to_char(source.updated_at AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
            'claimedBy',source.claimed_by,
            'claimedAt',source.claimed_at,
            'errorMessage',source.error_message,
            'licensingSecured',source.licensing_secured
          )
          AND source.claimed_by IS NULL AND source.claimed_at IS NULL
          AND source.error_message IS NULL AND source.licensing_secured
      )
    THEN RAISE EXCEPTION 'versioned_output_prefix_target_invalid'; END IF;
    INSERT INTO public.sip_versioned_output_prefix_staging_receipts(
      artifact_id,artifact_content_hash,provider_slug,provider_lease_id,
      provider_lease_token_hash,
      instrument_v2_id,sample_path_construct_id,original_sample_id,
      old_file_path_reference,new_file_path_reference,relative_path,destination_s3_key,
      format,quality,source_s3_key,source_object_identity,source_terminal_evidence,output_object_identity,
      output_content_sha256,
      processor_config_sha256,processing_fingerprint_sha256,processing_input,
      content_intent_token,staging_run_id,verified_at
    ) VALUES (
      v_artifact.id,v_content_hash,btrim(p_contributor_slug),p_lease_id,
      encode(digest(convert_to(p_lease_token::text,'UTF8'),'sha256'),'hex'),
      v_instrument_id,(v_target->>'samplePathConstructId')::uuid,
      (v_target->>'originalSampleId')::uuid,v_old_pointer,v_new_pointer,
      v_target->>'relativePath',v_target->>'s3Key',v_target->>'format',(v_target->>'quality')::smallint,
      v_target->>'sourceS3Key',v_target->'sourceObjectIdentity',
      v_target->'sourceTerminalEvidence',v_target->'outputObjectIdentity',v_target->>'outputContentSha256',
      p_content->>'processorConfigSha256',
      v_target->>'processingFingerprintSha256',v_target->'processingInput',
      v_target->>'contentIntentToken',p_content->>'stagingRunId',
      (v_target->>'verifiedAt')::timestamptz
    ) ON CONFLICT (artifact_id,sample_path_construct_id,format,quality) DO NOTHING;
    IF NOT EXISTS (
      SELECT 1
      FROM public.sip_versioned_output_prefix_staging_receipts receipt
      WHERE receipt.artifact_id = v_artifact.id
        AND receipt.sample_path_construct_id = (v_target->>'samplePathConstructId')::uuid
        AND receipt.format = v_format
        AND receipt.quality = v_quality
        AND receipt.instrument_v2_id = v_instrument_id
        AND receipt.provider_lease_id = p_lease_id
        AND receipt.provider_lease_token_hash = encode(digest(
          convert_to(p_lease_token::text,'UTF8'),'sha256'
        ),'hex')
        AND receipt.original_sample_id = (v_target->>'originalSampleId')::uuid
        AND receipt.old_file_path_reference = v_old_pointer
        AND receipt.new_file_path_reference = v_new_pointer
        AND receipt.relative_path = v_target->>'relativePath'
        AND receipt.destination_s3_key = v_target->>'s3Key'
        AND receipt.source_s3_key = v_target->>'sourceS3Key'
        AND receipt.source_object_identity = v_target->'sourceObjectIdentity'
        AND receipt.source_terminal_evidence = v_target->'sourceTerminalEvidence'
        AND receipt.output_object_identity = v_target->'outputObjectIdentity'
        AND receipt.output_content_sha256 = v_target->>'outputContentSha256'
        AND receipt.processor_config_sha256 = p_content->>'processorConfigSha256'
        AND receipt.processing_fingerprint_sha256 = v_target->>'processingFingerprintSha256'
        AND receipt.processing_input = v_target->'processingInput'
        AND receipt.content_intent_token = v_target->>'contentIntentToken'
        AND receipt.staging_run_id = p_content->>'stagingRunId'
        AND receipt.verified_at = (v_target->>'verifiedAt')::timestamptz
    ) THEN RAISE EXCEPTION 'versioned_output_prefix_staging_replay_drift'; END IF;
  END LOOP;
  IF EXISTS (
    SELECT 1 FROM public.sample_path_constructs construct
    WHERE construct.instrument_v2_id=v_instrument_id
      AND NOT EXISTS (
        SELECT 1 FROM public.sip_versioned_output_prefix_staging_receipts receipt
        WHERE receipt.artifact_id=v_artifact.id
          AND receipt.sample_path_construct_id=construct.id
        GROUP BY receipt.sample_path_construct_id
        HAVING count(*)=9
          AND count(*) FILTER (WHERE format='mp3' AND quality BETWEEN 1 AND 5)=5
          AND count(*) FILTER (WHERE format='ogg' AND quality BETWEEN 2 AND 5)=4
      )
  ) THEN RAISE EXCEPTION 'versioned_output_prefix_full_keyset_required'; END IF;
  SELECT public.sip_versioned_output_prefix_staging_projection_v1(v_artifact.id)
  INTO v_projection;
  IF (p_content->>'stagingProjectionCanonicalJson')::jsonb
      IS DISTINCT FROM v_projection
  THEN RAISE EXCEPTION 'versioned_output_prefix_staging_projection_drift'; END IF;
  v_projection_hash := encode(digest(convert_to(
    p_content->>'stagingProjectionCanonicalJson', 'UTF8'
  ), 'sha256'), 'hex');
  v_expected_projection_hash := p_content->>'stagingProjectionHash';
  IF v_projection_hash IS DISTINCT FROM v_expected_projection_hash
  THEN RAISE EXCEPTION 'versioned_output_prefix_staging_projection_drift'; END IF;
  v_projection := jsonb_build_object('artifactId',v_artifact.id,'contentHash',v_content_hash,
    'instrumentV2Id',v_instrument_id,'targetCount',v_construct_count*9,
    'stagingProjectionHash',v_projection_hash,
    'activePointerChanged',false);
  PERFORM set_config('app.sip_versioned_output_prefix_operation_authorized','on',true);
  UPDATE public.sip_versioned_output_prefix_staging_operations
  SET status='completed',artifact_id=v_artifact.id,result=v_projection,
    finished_at=clock_timestamp()
  WHERE id=v_operation.id;
  RETURN v_projection || jsonb_build_object('idempotent',false);
END $_$;


ALTER FUNCTION "public"."sip_publish_stage_versioned_output_prefix_v1"("p_contributor_slug" "text", "p_content" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_staging_operation_id" "uuid", "p_staging_operation_token" "uuid", "p_expected_request_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_record_completion_materialization_rehearsal_v1"("p_origin_main_sha" "text", "p_authorization_ref" "text", "p_production_observed_at" timestamp with time zone, "p_transaction_snapshot" "text", "p_manifest_sha256" "text", "p_snapshot_sha256" "text", "p_plan_sha256" "text", "p_expected_batch_root_sha256" "text", "p_inventory_count" bigint, "p_database_count" bigint, "p_provider_manifest_count" bigint, "p_generated_lineage_count" bigint, "p_exception_count" bigint, "p_conflicts" "jsonb", "p_batches" "jsonb", "p_created_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_rehearsal public.sip_completion_materialization_rehearsal%ROWTYPE;
  v_batch_count bigint;
  v_batch_root text;
BEGIN
  IF current_setting('transaction_isolation') <> 'repeatable read' THEN
    RAISE EXCEPTION 'completion materialization rehearsal requires repeatable read'
      USING ERRCODE = '25001';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('sip-completion-materialization-global-v1', 0));
  IF jsonb_typeof(p_batches) <> 'array'
    OR jsonb_array_length(p_batches) = 0
  THEN
    RAISE EXCEPTION 'nonempty batch descriptors are required';
  END IF;
  IF jsonb_typeof(coalesce(p_conflicts, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'conflicts must be an array';
  END IF;
  IF p_inventory_count < 0 OR p_database_count < 0
    OR p_inventory_count < p_provider_manifest_count
    OR p_inventory_count < p_generated_lineage_count
    OR p_inventory_count < p_exception_count
    OR p_inventory_count <>
      p_provider_manifest_count + p_generated_lineage_count + p_exception_count
  THEN
    RAISE EXCEPTION 'completion denominator counts are invalid';
  END IF;

  SELECT
    count(*),
    public.sip_completion_identity_digest_v1(
      array_agg(value::text ORDER BY (value->>'batchIndex')::integer)
    )
  INTO v_batch_count, v_batch_root
  FROM jsonb_array_elements(p_batches) value;

  IF v_batch_root <> p_expected_batch_root_sha256 THEN
    RAISE EXCEPTION 'batch descriptor root drift';
  END IF;

  INSERT INTO public.sip_completion_materialization_rehearsal (
    origin_main_sha,
    authorization_ref,
    production_observed_at,
    transaction_snapshot,
    manifest_sha256,
    snapshot_sha256,
    plan_sha256,
    batch_root_sha256,
    inventory_count,
    database_count,
    provider_manifest_count,
    generated_lineage_count,
    exception_count,
    batch_count,
    conflict_count,
    conflicts,
    created_by
  ) VALUES (
    p_origin_main_sha,
    btrim(p_authorization_ref),
    p_production_observed_at,
    p_transaction_snapshot,
    p_manifest_sha256,
    p_snapshot_sha256,
    p_plan_sha256,
    p_expected_batch_root_sha256,
    p_inventory_count,
    p_database_count,
    p_provider_manifest_count,
    p_generated_lineage_count,
    p_exception_count,
    v_batch_count,
    jsonb_array_length(coalesce(p_conflicts, '[]'::jsonb)),
    coalesce(p_conflicts, '[]'::jsonb),
    btrim(p_created_by)
  )
  RETURNING * INTO v_rehearsal;

  INSERT INTO public.sip_completion_materialization_rehearsal_batch (
    rehearsal_id,
    batch_index,
    first_source_id,
    last_source_id,
    row_count,
    row_sha256,
    insert_count,
    update_count,
    idempotent_count
  )
  SELECT
    v_rehearsal.id,
    descriptor."batchIndex",
    descriptor."firstSourceId",
    descriptor."lastSourceId",
    descriptor."rowCount",
    descriptor."rowSha256",
    descriptor."insertCount",
    descriptor."updateCount",
    descriptor."idempotentCount"
  FROM jsonb_to_recordset(p_batches) AS descriptor(
    "batchIndex" integer,
    "firstSourceId" uuid,
    "lastSourceId" uuid,
    "rowCount" bigint,
    "rowSha256" text,
    "insertCount" bigint,
    "updateCount" bigint,
    "idempotentCount" bigint
  );

  IF (SELECT count(*) FROM public.sip_completion_materialization_rehearsal_batch
      WHERE rehearsal_id = v_rehearsal.id) <> v_batch_count
  THEN
    RAISE EXCEPTION 'batch descriptor count drift';
  END IF;

  RETURN jsonb_build_object(
    'rehearsalId', v_rehearsal.id,
    'status', 'HOLD',
    'lifecycleStatus', v_rehearsal.lifecycle_status,
    'manifestHash', v_rehearsal.manifest_sha256,
    'snapshotHash', v_rehearsal.snapshot_sha256,
    'planHash', v_rehearsal.plan_sha256,
    'batchRootHash', v_rehearsal.batch_root_sha256,
    'batchCount', v_rehearsal.batch_count,
    'conflictCount', v_rehearsal.conflict_count,
    'readinessEvaluated', false,
    'applyReady', false,
    'applied', 0
  );
END;
$$;


ALTER FUNCTION "public"."sip_record_completion_materialization_rehearsal_v1"("p_origin_main_sha" "text", "p_authorization_ref" "text", "p_production_observed_at" timestamp with time zone, "p_transaction_snapshot" "text", "p_manifest_sha256" "text", "p_snapshot_sha256" "text", "p_plan_sha256" "text", "p_expected_batch_root_sha256" "text", "p_inventory_count" bigint, "p_database_count" bigint, "p_provider_manifest_count" bigint, "p_generated_lineage_count" bigint, "p_exception_count" bigint, "p_conflicts" "jsonb", "p_batches" "jsonb", "p_created_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rehearse_gospel_talkbox_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE s jsonb; h text; rid uuid; locked_lease_id uuid;
BEGIN
  IF btrim(p_provider_slug)<>'gospel-musicians' OR p_manifest_hash !~ '^[0-9a-f]{64}$' OR NOT public.sip_validate_gospel_talkbox_grid_manifest_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_manifest_invalid' USING ERRCODE='22023'; END IF;
  IF p_manifest_hash<>(SELECT encode(extensions.digest(convert_to(string_agg(concat_ws('|',e->>'rootName',e->>'sequenceIndex',e->>'originalSampleId',e->>'filePath',e->>'expectedMidiNote',e->>'targetMidiNote'),E'\n' ORDER BY e->>'rootName',(e->>'sequenceIndex')::int,e->>'originalSampleId'),'UTF8'),'sha256'),'hex') FROM jsonb_array_elements(p_manifest)e) THEN RAISE EXCEPTION 'gospel_talkbox_grid_manifest_hash_mismatch' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('gospel-musicians',0));
  SELECT l.id INTO locked_lease_id FROM public.sip_fleet_provider_leases l WHERE l.id=p_lease_id AND l.lease_token=p_lease_token AND l.provider_slug='gospel-musicians' AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp() FOR UPDATE;
  IF locked_lease_id IS NULL THEN RAISE EXCEPTION 'gospel_talkbox_grid_lease_invalid' USING ERRCODE='55000'; END IF;
  IF EXISTS(SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gospel-musicians' AND status IN('queued','running')) THEN RAISE EXCEPTION 'gospel_talkbox_grid_active_run' USING ERRCODE='55000'; END IF;
  LOCK TABLE public.sip_sample_construct IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE MODE;
  PERFORM c.id FROM public.sip_sample_construct c JOIN jsonb_array_elements(p_manifest) e ON c.original_sample_id=(e->>'originalSampleId')::uuid FOR UPDATE;
  IF (SELECT count(*) FROM public.sip_sample_construct c JOIN jsonb_array_elements(p_manifest) e ON c.original_sample_id=(e->>'originalSampleId')::uuid AND c.contributor_slug='gospel-musicians' AND c.file_path=e->>'filePath' AND c.midi_note=e->>'expectedMidiNote')<>396 THEN RAISE EXCEPTION 'gospel_talkbox_grid_current_rows_changed' USING ERRCODE='40001'; END IF;
  IF EXISTS(SELECT 1 FROM public.sip_review_sample_override o JOIN jsonb_array_elements(p_manifest) e ON o.original_sample_id=(e->>'originalSampleId')::uuid WHERE o.midi_note IS NOT NULL AND btrim(o.midi_note)<>e->>'expectedMidiNote') THEN RAISE EXCEPTION 'gospel_talkbox_grid_review_override_conflict' USING ERRCODE='55000'; END IF;
  IF NOT public.sip_gospel_talkbox_grid_override_identity_valid_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_review_override_identity_mismatch' USING ERRCODE='55000'; END IF;
  s:=public.sip_build_gospel_talkbox_grid_snapshot_v1(p_manifest); h:=encode(extensions.digest(convert_to(s::text,'UTF8'),'sha256'),'hex');
  IF NOT EXISTS(SELECT 1 FROM public.sip_fleet_provider_leases l WHERE l.id=locked_lease_id AND l.lease_token=p_lease_token AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'gospel_talkbox_grid_lease_expired_before_write' USING ERRCODE='55000'; END IF;
  INSERT INTO public.sip_gospel_talkbox_grid_rehearsals(provider_slug,provider_lease_id,provider_lease_token,manifest_hash,manifest,snapshot_hash,snapshot)
  VALUES('gospel-musicians',p_lease_id,p_lease_token,p_manifest_hash,p_manifest,h,s)
  ON CONFLICT(provider_slug,manifest_hash) DO UPDATE SET provider_lease_id=EXCLUDED.provider_lease_id,provider_lease_token=EXCLUDED.provider_lease_token,snapshot_hash=EXCLUDED.snapshot_hash,snapshot=EXCLUDED.snapshot,consumed_at=NULL,created_at=now()
  WHERE sip_gospel_talkbox_grid_rehearsals.consumed_at IS NULL RETURNING id INTO rid;
  IF rid IS NULL THEN RAISE EXCEPTION 'gospel_talkbox_grid_rehearsal_already_consumed' USING ERRCODE='55000'; END IF;
  RETURN jsonb_build_object('rehearsalRunId',rid,'manifestHash',p_manifest_hash,'snapshotHash',h,'repairableCount',396);
END $_$;


ALTER FUNCTION "public"."sip_rehearse_gospel_talkbox_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rehearse_gospel_talkbox_incomplete_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_membership_hash" "text", "p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE s jsonb; h text; rid uuid; locked_lease_id uuid;
BEGIN
  IF btrim(p_provider_slug)<>'gospel-musicians' OR NOT public.sip_validate_gospel_talkbox_incomplete_grid_manifest_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_manifest_invalid' USING ERRCODE='22023'; END IF;
  IF p_manifest_hash<>'3abf4f6a45e2091c197088f78dbd723804ff8f24840644b051681f24ee93c795' OR p_manifest_hash<>public.sip_gospel_talkbox_incomplete_plan_hash_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_manifest_hash_mismatch' USING ERRCODE='22023'; END IF;
  IF p_membership_hash<>'34a8ab7c8db169c4de2ec2894c323bacfd379e04250844289d331d4c894737b8' OR p_membership_hash<>public.sip_gospel_talkbox_incomplete_membership_hash_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_membership_hash_mismatch' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('gospel-musicians',0));
  SELECT l.id INTO locked_lease_id FROM public.sip_fleet_provider_leases l WHERE l.id=p_lease_id AND l.lease_token=p_lease_token AND l.provider_slug='gospel-musicians' AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp() FOR UPDATE;
  IF locked_lease_id IS NULL THEN RAISE EXCEPTION 'gospel_talkbox_grid_lease_invalid' USING ERRCODE='55000'; END IF;
  IF EXISTS(SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gospel-musicians' AND status IN('queued','running')) THEN RAISE EXCEPTION 'gospel_talkbox_grid_active_run' USING ERRCODE='55000'; END IF;
  LOCK TABLE public.sip_sample_construct IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE MODE;
  IF NOT public.sip_gospel_talkbox_incomplete_membership_current_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_membership_drift' USING ERRCODE='40001'; END IF;
  PERFORM c.id FROM public.sip_sample_construct c JOIN jsonb_array_elements(p_manifest) e ON c.original_sample_id=(e->>'originalSampleId')::uuid FOR UPDATE;
  IF (SELECT count(*) FROM public.sip_sample_construct c JOIN jsonb_array_elements(p_manifest) e ON c.original_sample_id=(e->>'originalSampleId')::uuid AND c.contributor_slug='gospel-musicians' AND c.file_path=e->>'filePath' AND c.midi_note=e->>'expectedMidiNote')<>69 THEN RAISE EXCEPTION 'gospel_talkbox_grid_current_rows_changed' USING ERRCODE='40001'; END IF;
  IF EXISTS(SELECT 1 FROM public.sip_review_sample_override o JOIN jsonb_array_elements(p_manifest) e ON o.original_sample_id=(e->>'originalSampleId')::uuid WHERE o.midi_note IS NOT NULL AND btrim(o.midi_note)<>e->>'expectedMidiNote') THEN RAISE EXCEPTION 'gospel_talkbox_grid_review_override_conflict' USING ERRCODE='55000'; END IF;
  IF NOT public.sip_gospel_talkbox_grid_override_identity_valid_v1(p_manifest) THEN RAISE EXCEPTION 'gospel_talkbox_grid_review_override_identity_mismatch' USING ERRCODE='55000'; END IF;
  s:=public.sip_build_gospel_talkbox_grid_snapshot_v1(p_manifest); h:=encode(extensions.digest(convert_to(s::text,'UTF8'),'sha256'),'hex');
  IF NOT EXISTS(SELECT 1 FROM public.sip_fleet_provider_leases l WHERE l.id=locked_lease_id AND l.lease_token=p_lease_token AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'gospel_talkbox_grid_lease_expired_before_write' USING ERRCODE='55000'; END IF;
  INSERT INTO public.sip_gospel_talkbox_grid_rehearsals(provider_slug,provider_lease_id,provider_lease_token,manifest_hash,manifest,snapshot_hash,snapshot)
  VALUES('gospel-musicians',p_lease_id,p_lease_token,p_manifest_hash,p_manifest,h,s)
  ON CONFLICT(provider_slug,manifest_hash) DO UPDATE SET provider_lease_id=EXCLUDED.provider_lease_id,provider_lease_token=EXCLUDED.provider_lease_token,snapshot_hash=EXCLUDED.snapshot_hash,snapshot=EXCLUDED.snapshot,consumed_at=NULL,created_at=now()
  WHERE sip_gospel_talkbox_grid_rehearsals.consumed_at IS NULL RETURNING id INTO rid;
  IF rid IS NULL THEN RAISE EXCEPTION 'gospel_talkbox_grid_rehearsal_already_consumed' USING ERRCODE='55000'; END IF;
  RETURN jsonb_build_object('rehearsalRunId',rid,'manifestHash',p_manifest_hash,'snapshotHash',h,'repairableCount',69);
END $$;


ALTER FUNCTION "public"."sip_rehearse_gospel_talkbox_incomplete_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_membership_hash" "text", "p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rehearse_gospel_talkbox_warning_refresh_v1"("p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest_canonical_json" "text", "p_context_hash" "text", "p_warnings_hash" "text", "p_warnings_canonical_json" "text", "p_generator_version" "text", "p_expected_snapshot_hash" "text", "p_manifest" "jsonb", "p_warnings" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE v_snapshot jsonb; v_hash text; v_id uuid; v_count int; v_lease uuid;
BEGIN
  IF jsonb_typeof(p_manifest)<>'array' OR jsonb_array_length(p_manifest)<1 OR jsonb_array_length(p_manifest)>13
    OR jsonb_typeof(p_warnings)<>'array' OR p_manifest_hash!~'^[0-9a-f]{64}$' OR p_context_hash!~'^[0-9a-f]{64}$' OR p_expected_snapshot_hash!~'^[0-9a-f]{64}$' OR p_warnings_hash!~'^[0-9a-f]{64}$' OR p_generator_version<>'gospel-talkbox-warning-generator-v1'
    OR p_manifest_canonical_json::jsonb IS DISTINCT FROM p_manifest
    OR encode(extensions.digest(convert_to(p_manifest_canonical_json,'UTF8'),'sha256'),'hex')<>p_manifest_hash
    OR p_warnings_canonical_json::jsonb IS DISTINCT FROM p_warnings
    OR encode(extensions.digest(convert_to(p_warnings_canonical_json,'UTF8'),'sha256'),'hex')<>p_warnings_hash
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_manifest)e WHERE e->>'rootName' NOT IN('Aaaah','Baaah','Beee','Booo','Laaah','O Long','Raw Buzz','Raw Tube','Shooo','Weee','Whaap','Whoa','Wooo'))
  THEN RAISE EXCEPTION 'gospel_warning_refresh_manifest_invalid' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_warnings)w WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_manifest)e WHERE e->>'stagingInstrumentId'=w->>'stagingInstrumentId') OR btrim(coalesce(w->>'category',''))='' OR btrim(coalesce(w->>'warningKey',''))='' OR btrim(coalesce(w->>'type',''))='' OR w->>'severity' NOT IN('high','med','low') OR w->>'warningKey' IS DISTINCT FROM concat_ws('|',w->>'type',w->>'field',coalesce(w->>'filePath',''),coalesce(w->>'originalSampleId','')) OR (NULLIF(w->>'originalSampleId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.sip_gospel_talkbox_warning_refresh_snapshot_v1(p_manifest)->'membership')m WHERE m->>'stagingId'=w->>'stagingInstrumentId' AND m->>'sampleId'=w->>'originalSampleId')) OR (NULLIF(w->>'originalSampleId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sip_sample_construct c WHERE c.original_sample_id=(w->>'originalSampleId')::uuid AND c.file_path=w->>'filePath')))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_warnings)w GROUP BY w->>'stagingInstrumentId',w->>'category',w->>'warningKey' HAVING count(*)>1)
  THEN RAISE EXCEPTION 'gospel_warning_refresh_warning_payload_invalid' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('gospel-musicians',0));
  SELECT id INTO v_lease FROM public.sip_fleet_provider_leases WHERE id=p_lease_id AND lease_token=p_lease_token AND provider_slug='gospel-musicians' AND released_at IS NULL AND lease_expires_at>clock_timestamp() FOR UPDATE;
  IF v_lease IS NULL THEN RAISE EXCEPTION 'gospel_warning_refresh_lease_invalid' USING ERRCODE='55000'; END IF;
  IF EXISTS(SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gospel-musicians' AND status IN('queued','running')) THEN RAISE EXCEPTION 'gospel_warning_refresh_active_run' USING ERRCODE='55000'; END IF;
  PERFORM s.sip_review_instrument_id FROM public.sip_review_warning_index_state s JOIN jsonb_array_elements(p_manifest)e ON s.sip_review_instrument_id=(e->>'stagingInstrumentId')::uuid ORDER BY s.sip_review_instrument_id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM public.sip_review_warning_index_state s JOIN jsonb_array_elements(p_manifest)e ON s.sip_review_instrument_id=(e->>'stagingInstrumentId')::uuid WHERE s.refresh_lease_token IS NOT NULL) THEN RAISE EXCEPTION 'gospel_warning_refresh_background_refresh_active' USING ERRCODE='55000'; END IF;
  PERFORM i.id FROM public.sip_review_instrument i JOIN jsonb_array_elements(p_manifest)e ON i.id=(e->>'stagingInstrumentId')::uuid WHERE i.source_contributor_slug='gospel-musicians' AND i.source_sip_instrument_id=(e->>'sourceInstrumentId')::uuid AND i.name=e->>'rootName' AND NOT i.is_retired FOR SHARE;
  GET DIAGNOSTICS v_count=ROW_COUNT;
  IF v_count<>jsonb_array_length(p_manifest) THEN RAISE EXCEPTION 'gospel_warning_refresh_identity_drift' USING ERRCODE='40001'; END IF;
  IF EXISTS(SELECT 1 FROM public.sip_review_promotion_map p JOIN jsonb_array_elements(p_manifest)e ON p.sip_review_instrument_id=(e->>'stagingInstrumentId')::uuid) THEN RAISE EXCEPTION 'gospel_warning_refresh_promoted' USING ERRCODE='55000'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_manifest)e WHERE (e->>'expectedSampleCount')::int<>(SELECT count(*) FROM jsonb_array_elements(public.sip_gospel_talkbox_warning_refresh_snapshot_v1(jsonb_build_array(e))->'membership'))) THEN RAISE EXCEPTION 'gospel_warning_refresh_sample_count_drift' USING ERRCODE='40001'; END IF;
  v_snapshot:=public.sip_gospel_talkbox_warning_refresh_snapshot_v1(p_manifest);
  v_hash:=encode(extensions.digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex');
  IF v_hash<>p_expected_snapshot_hash THEN RAISE EXCEPTION 'gospel_warning_refresh_snapshot_drift' USING ERRCODE='40001'; END IF;
  INSERT INTO public.sip_gospel_talkbox_warning_refresh_rehearsals(provider_lease_id,provider_lease_token,manifest_hash,context_hash,warnings_hash,generator_version,snapshot_hash,manifest,warnings,snapshot)
  VALUES(p_lease_id,p_lease_token,p_manifest_hash,p_context_hash,p_warnings_hash,p_generator_version,v_hash,p_manifest,p_warnings,v_snapshot)
  ON CONFLICT(provider_lease_id,manifest_hash,context_hash,snapshot_hash,warnings_hash,generator_version) DO NOTHING;
  SELECT id INTO STRICT v_id FROM public.sip_gospel_talkbox_warning_refresh_rehearsals WHERE provider_lease_id=p_lease_id AND manifest_hash=p_manifest_hash AND context_hash=p_context_hash AND snapshot_hash=v_hash AND warnings_hash=p_warnings_hash AND generator_version=p_generator_version;
  RETURN jsonb_build_object('rehearsalId',v_id,'manifestHash',p_manifest_hash,'contextHash',p_context_hash,'warningsHash',p_warnings_hash,'generatorVersion',p_generator_version,'snapshotHash',v_hash,'instrumentCount',jsonb_array_length(p_manifest),'warningCount',jsonb_array_length(p_warnings));
END $_$;


ALTER FUNCTION "public"."sip_rehearse_gospel_talkbox_warning_refresh_v1"("p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest_canonical_json" "text", "p_context_hash" "text", "p_warnings_hash" "text", "p_warnings_canonical_json" "text", "p_generator_version" "text", "p_expected_snapshot_hash" "text", "p_manifest" "jsonb", "p_warnings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rehearse_gotchanoddin_tonal_kit_pitchless_v1"("p_manifest" "jsonb", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_mutation_plan_hash" "text", "p_authorization_proof" "text", "p_operator_identity" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE v_snapshot jsonb; v_current_hash text; v_rehearsal uuid;
BEGIN
  IF current_setting('app.sip_publish_coordinator_authorized', true) IS DISTINCT FROM 'on'
     OR btrim(coalesce(p_authorization_proof,'')) !~ '^[a-f0-9]{64}$'
     OR btrim(coalesce(p_operator_identity,'')) = ''
     OR NOT public.sip_gotchanoddin_tonal_kit_manifest_valid_v1(p_manifest)
     OR p_manifest_hash <> p_manifest->'rehearsal'->>'manifestHash'
     OR p_snapshot_hash <> p_manifest->'rehearsal'->>'snapshotHash'
     OR p_mutation_plan_hash <> p_manifest->'rehearsal'->>'mutationPlanHash' THEN
    RAISE EXCEPTION 'gotchanoddin_tonal_kit_rehearsal_identity_invalid' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('gotchanoddin',0));
  IF EXISTS (SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gotchanoddin' AND status IN ('queued','running')) THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_active_run' USING ERRCODE='55000'; END IF;
  IF (SELECT count(*) FROM public.instruments_v2 i JOIN public.contributors c ON c.id=i.contributor_id JOIN jsonb_array_elements_text(p_manifest->'instrumentV2Ids') t ON t.value::uuid=i.id WHERE c.slug='gotchanoddin' AND i.published AND i.engine_type::text='tonal' AND i.range_lower=(p_manifest->'expectedTriggerRange'->>'lower')::integer AND i.range_upper=(p_manifest->'expectedTriggerRange'->>'upper')::integer) <> 2397 THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_membership_or_range_drift' USING ERRCODE='40001'; END IF;
  IF (SELECT count(*) FROM public.sample_path_constructs c JOIN jsonb_array_elements_text(p_manifest->'instrumentV2Ids') t ON t.value::uuid=c.instrument_v2_id) <> 2397 THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_construct_count_drift' USING ERRCODE='40001'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_manifest->'nonTonalExclusion'->'instrumentV2Ids') t JOIN public.instruments_v2 i ON i.id=t.value::uuid WHERE i.engine_type::text <> 'non_tonal') THEN RAISE EXCEPTION 'gotchanoddin_non_tonal_exclusion_drift' USING ERRCODE='40001'; END IF;
  v_snapshot := public.sip_gotchanoddin_tonal_kit_pitchless_snapshot_v1(p_manifest);
  v_current_hash := encode(digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex');
  IF v_current_hash <> p_snapshot_hash THEN
    RAISE EXCEPTION 'gotchanoddin_tonal_kit_snapshot_hash_drift' USING ERRCODE='40001';
  END IF;
  INSERT INTO public.sip_gotchanoddin_tonal_kit_pitchless_rehearsals(manifest_hash,snapshot_hash,mutation_plan_hash,manifest,before_snapshot,operator_identity)
  VALUES (p_manifest_hash,p_snapshot_hash,p_mutation_plan_hash,p_manifest,v_snapshot,p_operator_identity)
  ON CONFLICT (manifest_hash,snapshot_hash,mutation_plan_hash) DO NOTHING RETURNING id INTO v_rehearsal;
  IF v_rehearsal IS NULL THEN SELECT id INTO v_rehearsal FROM public.sip_gotchanoddin_tonal_kit_pitchless_rehearsals WHERE manifest_hash=p_manifest_hash AND snapshot_hash=p_snapshot_hash AND mutation_plan_hash=p_mutation_plan_hash AND before_snapshot=v_snapshot AND status='passed'; IF v_rehearsal IS NULL THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_stale_rehearsal' USING ERRCODE='40001'; END IF; END IF;
  RETURN jsonb_build_object('rehearsalId',v_rehearsal,'manifestHash',p_manifest_hash,'snapshotHash',p_snapshot_hash,'mutationPlanHash',p_mutation_plan_hash,'currentSnapshotHash',v_current_hash,'repairableCount',2397);
END; $_$;


ALTER FUNCTION "public"."sip_rehearse_gotchanoddin_tonal_kit_pitchless_v1"("p_manifest" "jsonb", "p_manifest_hash" "text", "p_snapshot_hash" "text", "p_mutation_plan_hash" "text", "p_authorization_proof" "text", "p_operator_identity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rehearse_provider_warning_review_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest_canonical_json" "text", "p_manifest" "jsonb", "p_decision" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_lease_id uuid;
  v_snapshot jsonb;
  v_snapshot_hash text;
  v_rehearsal public.sip_provider_warning_review_rehearsals%ROWTYPE;
BEGIN
  IF p_decision NOT IN ('accepted', 'rejected')
     OR (p_decision = 'accepted' AND p_reason NOT IN
       ('explicit_path_authority', 'verified_false_positive'))
     OR (p_decision = 'rejected' AND p_reason NOT IN
       ('requires_correction', 'insufficient_evidence')) THEN
    RAISE EXCEPTION 'provider_warning_review_resolution_invalid' USING ERRCODE = '22023';
  END IF;
  IF p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR p_manifest_canonical_json::jsonb IS DISTINCT FROM p_manifest
     OR encode(extensions.digest(convert_to(p_manifest_canonical_json, 'UTF8'), 'sha256'), 'hex')
        <> p_manifest_hash THEN
    RAISE EXCEPTION 'provider_warning_review_manifest_hash_mismatch' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(lower(btrim(p_provider_slug)), 0)
  );
  SELECT lease.id INTO v_lease_id
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
    AND lease.provider_slug = btrim(p_provider_slug)
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND lease.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF v_lease_id IS NULL THEN
    RAISE EXCEPTION 'provider_warning_review_lease_invalid' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (SELECT 1 FROM public.sip_fleet_runs run
             WHERE run.provider_slug = btrim(p_provider_slug)
               AND run.status IN ('queued', 'running')) THEN
    RAISE EXCEPTION 'provider_warning_review_active_run' USING ERRCODE = '55000';
  END IF;

  PERFORM warning.id
  FROM public.sip_review_warning_index warning
  WHERE warning.id IN (
    SELECT (entry->>'warningId')::bigint FROM jsonb_array_elements(p_manifest) entry
  ) FOR UPDATE;
  PERFORM instrument.id
  FROM public.sip_review_instrument instrument
  WHERE instrument.id IN (
    SELECT (entry->>'stagingInstrumentId')::uuid
    FROM jsonb_array_elements(p_manifest) entry
  ) FOR SHARE;
  PERFORM source.id
  FROM public.samples_original_paths source
  WHERE source.id IN (
    SELECT (entry->>'sampleOriginalPathId')::uuid
    FROM jsonb_array_elements(p_manifest) entry
  ) FOR SHARE;
  PERFORM warning_state.sip_review_instrument_id
  FROM public.sip_review_warning_index_state warning_state
  WHERE warning_state.sip_review_instrument_id IN (
    SELECT (entry->>'stagingInstrumentId')::uuid
    FROM jsonb_array_elements(p_manifest) entry
  ) FOR UPDATE;
  v_snapshot := public.sip_provider_warning_review_snapshot_v1(p_provider_slug, p_manifest);
  v_snapshot_hash := encode(extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'), 'hex');

  INSERT INTO public.sip_provider_warning_review_rehearsals(
    provider_slug, provider_lease_id, provider_lease_token, manifest_hash,
    snapshot_hash, manifest, decision, reason
  ) VALUES (
    btrim(p_provider_slug), p_lease_id, p_lease_token, p_manifest_hash,
    v_snapshot_hash, p_manifest, p_decision, p_reason
  ) ON CONFLICT (provider_slug, provider_lease_id, manifest_hash, snapshot_hash, decision, reason)
    DO NOTHING;
  SELECT * INTO STRICT v_rehearsal
  FROM public.sip_provider_warning_review_rehearsals rehearsal
  WHERE rehearsal.provider_slug = btrim(p_provider_slug)
    AND rehearsal.provider_lease_id = p_lease_id
    AND rehearsal.manifest_hash = p_manifest_hash
    AND rehearsal.snapshot_hash = v_snapshot_hash
    AND rehearsal.decision = p_decision
    AND rehearsal.reason = p_reason;
  RETURN jsonb_build_object(
    'rehearsalId', v_rehearsal.id,
    'manifestHash', p_manifest_hash,
    'snapshotHash', v_snapshot_hash,
    'warningCount', jsonb_array_length(p_manifest),
    'decision', p_decision,
    'reason', p_reason,
    'status', v_rehearsal.status
  );
END;
$_$;


ALTER FUNCTION "public"."sip_rehearse_provider_warning_review_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest_canonical_json" "text", "p_manifest" "jsonb", "p_decision" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rehearse_retired_provenance_disposition_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest_canonical_json" "text", "p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_lease_id uuid;
  v_operator_identity text;
  v_snapshot jsonb;
  v_snapshot_hash text;
  v_mutation_plan jsonb;
  v_mutation_plan_hash text;
  v_rehearsal public.sip_retired_provenance_disposition_rehearsals%ROWTYPE;
BEGIN
  IF p_manifest_hash !~ '^[0-9a-f]{64}$'
     OR p_manifest_canonical_json::jsonb IS DISTINCT FROM p_manifest
     OR encode(
       extensions.digest(
         convert_to(p_manifest_canonical_json, 'UTF8'), 'sha256'
       ), 'hex'
     ) <> p_manifest_hash THEN
    RAISE EXCEPTION 'retired_provenance_disposition_manifest_hash_mismatch'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended('sip-retired-provenance-disposition-global', 0)
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(lower(btrim(p_provider_slug)), 0)
  );
  SELECT lease.id, btrim(lease.lease_owner)
  INTO v_lease_id, v_operator_identity
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.id = p_lease_id
    AND lease.provider_slug = btrim(p_provider_slug)
    AND lease.lease_token = p_lease_token
    AND lease.released_at IS NULL
    AND btrim(coalesce(lease.lease_owner, '')) <> ''
    AND lease.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF v_lease_id IS NULL THEN
    RAISE EXCEPTION 'retired_provenance_disposition_lease_invalid'
      USING ERRCODE = '55000';
  END IF;
  IF p_manifest->>'operatorIdentity' IS DISTINCT FROM v_operator_identity THEN
    RAISE EXCEPTION 'retired_provenance_disposition_operator_mismatch'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = btrim(p_provider_slug)
      AND run.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'retired_provenance_disposition_active_run'
      USING ERRCODE = '55000';
  END IF;

  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument_sample_scope
    IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_promotion_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.samples_original_paths IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_disposition
    IN SHARE ROW EXCLUSIVE MODE;

  v_snapshot := public.sip_retired_provenance_disposition_snapshot_v1(
    p_provider_slug, p_manifest, false
  );
  v_snapshot_hash := encode(
    extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'), 'hex'
  );
  SELECT jsonb_build_object(
    'operation', 'insert_sip_review_sample_disposition',
    'providerSlug', btrim(p_provider_slug),
    'operatorIdentity', v_operator_identity,
    'manifestHash', p_manifest_hash,
    'snapshotHash', v_snapshot_hash,
    'rows', jsonb_agg(
      jsonb_build_object(
        'stagingInstrumentId', entry->>'stagingInstrumentId',
        'sampleOriginalPathId', entry->>'sampleOriginalPathId',
        'disposition', entry->>'disposition',
        'reason', entry->>'reason',
        'reviewedBy', v_operator_identity
      ) ORDER BY entry->>'sampleOriginalPathId'
    )
  ) INTO v_mutation_plan
  FROM jsonb_array_elements(p_manifest->'entries') entry;
  v_mutation_plan_hash := encode(
    extensions.digest(convert_to(v_mutation_plan::text, 'UTF8'), 'sha256'),
    'hex'
  );

  INSERT INTO public.sip_retired_provenance_disposition_rehearsals(
    provider_slug, provider_lease_id, provider_lease_token, operator_identity,
    manifest_hash, snapshot_hash, mutation_plan_hash, manifest, expected_counts
  ) VALUES (
    btrim(p_provider_slug), p_lease_id, p_lease_token, v_operator_identity,
    p_manifest_hash, v_snapshot_hash, v_mutation_plan_hash, p_manifest,
    p_manifest->'expectedCounts'
  )
  ON CONFLICT (
    provider_slug, provider_lease_id, operator_identity, manifest_hash,
    snapshot_hash, mutation_plan_hash
  ) DO NOTHING;

  SELECT * INTO STRICT v_rehearsal
  FROM public.sip_retired_provenance_disposition_rehearsals rehearsal
  WHERE rehearsal.provider_slug = btrim(p_provider_slug)
    AND rehearsal.provider_lease_id = p_lease_id
    AND rehearsal.operator_identity = v_operator_identity
    AND rehearsal.manifest_hash = p_manifest_hash
    AND rehearsal.snapshot_hash = v_snapshot_hash
    AND rehearsal.mutation_plan_hash = v_mutation_plan_hash;

  RETURN jsonb_build_object(
    'rehearsalId', v_rehearsal.id,
    'manifestHash', p_manifest_hash,
    'snapshotHash', v_snapshot_hash,
    'mutationPlanHash', v_mutation_plan_hash,
    'sourceCount', (p_manifest#>>'{expectedCounts,sources}')::integer,
    'reviewCount', (p_manifest#>>'{expectedCounts,reviewRows}')::integer,
    'deferredProvenanceCount',
      (p_manifest#>>'{expectedCounts,deferredProvenance}')::integer,
    'ignoredProvenanceCount',
      (p_manifest#>>'{expectedCounts,ignoredProvenance}')::integer,
    'expectedPostWriteCount',
      (p_manifest#>>'{expectedCounts,postWriteDispositions}')::integer,
    'dispositionRowsInserted', 0,
    'sourceMutationDelta', 0,
    'constructMutationDelta', 0,
    'reviewMutationDelta', 0,
    'status', v_rehearsal.status
  );
END;
$_$;


ALTER FUNCTION "public"."sip_rehearse_retired_provenance_disposition_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest_canonical_json" "text", "p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rehearse_source_pitchless_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_snapshot jsonb;
  v_snapshot_hash text;
  v_existing public.sip_source_pitchless_reconciliation_rehearsals%ROWTYPE;
  v_rehearsal_id uuid;
  v_instrument_id uuid;
BEGIN
  IF btrim(coalesce(p_contributor_slug, '')) <> 'fallout-music-group'
     OR p_lease_id IS NULL OR p_lease_token IS NULL
     OR p_manifest_hash <> '1e9ef13ed4e83d9da2245bbafcdb2b83b47c87df7f118148cd4a133855412310'
     OR jsonb_typeof(p_manifest) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest) <> 1 THEN
    RAISE EXCEPTION 'source_pitchless_rehearsal_identity_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF p_manifest IS DISTINCT FROM '[{
    "evidenceDigest":"0f78ea702aacb08c267e995f7c877a1ec34e33f9e8cc8476d58252dbc5255a43",
    "instrumentV2Id":"e74e4cc0-7df1-480e-a370-1514f5630ca0",
    "constructId":"4a4b4f5c-d3ed-4845-bf60-ed8896730119",
    "sampleOriginalPathId":"8219df25-c19c-4577-8502-6f9cef472b91",
    "sourceS3Path":"s3://ss-market-private-resources/samples/original/Fallout Music Group/FMG Unstrung 2/Raw Sounds/Riser Layers/Banjo Spectral Scrapes 2.wav",
    "sourceFileName":"Banjo Spectral Scrapes 2.wav",
    "expectedMidiNote":"0","expectedFilename":"0","expectedPitchContent":"0",
    "expectedVelocity":0,"expectedRoundRobin":0,"expectedMicPosition":"main",
    "expectedPlaybackType":"oneShot","expectedEngineType":"non_tonal",
    "expectedSinglePitch":0,"expectedRangeLower":21,"expectedRangeUpper":108,
    "expectedFilePathReference":"fallout-music-group_FMG-Unstrung-2_Banjo-Spectral-Scrapes-2_spectral-scrapes-2",
    "expectedFileNameReferences":["Banjo Spectral Scrapes 2.wav"]
  }]'::jsonb THEN
    RAISE EXCEPTION 'source_pitchless_rehearsal_manifest_invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'source_pitchless_rehearsal_lease_invalid'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = btrim(p_contributor_slug)
      AND run.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'source_pitchless_rehearsal_active_run'
      USING ERRCODE = '55000';
  END IF;

  -- Fence every table represented in the immutable snapshot before reading it.
  -- SHARE ROW EXCLUSIVE prevents concurrent updates and phantom inserts while
  -- remaining compatible with this transaction's own writes.
  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_promotion_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.samples_original_paths IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_source_pitchless_reconciliation_rehearsals
    IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_source_pitchless_reconciliation_receipts
    IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE ROW EXCLUSIVE MODE;

  SELECT (entry->>'instrumentV2Id')::uuid INTO v_instrument_id
  FROM jsonb_array_elements(p_manifest) entry;
  PERFORM construct.id FROM public.sample_path_constructs construct
  WHERE construct.instrument_v2_id = v_instrument_id FOR UPDATE;
  PERFORM instrument.id FROM public.instruments_v2 instrument
  WHERE instrument.id = v_instrument_id
     OR v_instrument_id = ANY(COALESCE(instrument.articulations, ARRAY[]::uuid[]))
     OR v_instrument_id = ANY(COALESCE(instrument.effects_instruments, ARRAY[]::uuid[]))
     OR instrument.legato_transition = v_instrument_id
  FOR UPDATE;
  PERFORM source.id FROM public.samples_original_paths source
  WHERE source.id = (p_manifest->0->>'sampleOriginalPathId')::uuid FOR SHARE;
  PERFORM alias_row.id FROM public.instrument_v2_legacy_map alias_row
  WHERE alias_row.instrument_v2_id = v_instrument_id FOR SHARE;
  PERFORM promotion.id FROM public.sip_review_promotion_map promotion
  WHERE promotion.instrument_v2_id = v_instrument_id FOR SHARE;
  PERFORM review.id FROM public.sip_review_instrument review
  WHERE review.id IN (
    SELECT promotion.sip_review_instrument_id
    FROM public.sip_review_promotion_map promotion
    WHERE promotion.instrument_v2_id = v_instrument_id
  ) FOR UPDATE;
  PERFORM override_row.id FROM public.sip_review_sample_override override_row
  WHERE override_row.sip_review_instrument_id IN (
    SELECT promotion.sip_review_instrument_id
    FROM public.sip_review_promotion_map promotion
    WHERE promotion.instrument_v2_id = v_instrument_id
  ) FOR SHARE;

  IF (
    SELECT count(*)
    FROM public.sample_path_constructs construct
    WHERE construct.instrument_v2_id =
      (p_manifest->0->>'instrumentV2Id')::uuid
  ) <> 1 OR (
    SELECT count(*)
    FROM public.sample_path_constructs construct
    WHERE construct.sample_original_path_id =
      (p_manifest->0->>'sampleOriginalPathId')::uuid
  ) <> 1 THEN
    RAISE EXCEPTION 'source_pitchless_one_source_one_construct_required'
      USING ERRCODE = '55000';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest) entry
    JOIN public.sample_path_constructs construct
      ON construct.id = (entry->>'constructId')::uuid
     AND construct.instrument_v2_id = (entry->>'instrumentV2Id')::uuid
     AND construct.sample_original_path_id =
         (entry->>'sampleOriginalPathId')::uuid
     AND construct.midi_note = '0'
     AND construct.filename = '0'
     AND btrim(construct.pitch_content) = entry->>'expectedPitchContent'
     AND construct.velocity = (entry->>'expectedVelocity')::integer
     AND construct.round_robin = (entry->>'expectedRoundRobin')::integer
     AND coalesce(nullif(btrim(construct.mic_position), ''), 'main') =
         entry->>'expectedMicPosition'
     AND construct.playback_type::text = entry->>'expectedPlaybackType'
    JOIN public.samples_original_paths source
      ON source.id = construct.sample_original_path_id
     AND source.s3_path = entry->>'sourceS3Path'
     AND source.file_name = entry->>'sourceFileName'
    JOIN public.instruments_v2 instrument
     ON instrument.id = construct.instrument_v2_id
     AND instrument.published = true
     AND instrument.engine_type::text = entry->>'expectedEngineType'
     AND instrument.single_pitch = (entry->>'expectedSinglePitch')::integer
     AND instrument.range_lower = (entry->>'expectedRangeLower')::integer
     AND instrument.range_upper = (entry->>'expectedRangeUpper')::integer
     AND instrument.file_path_reference = entry->>'expectedFilePathReference'
     AND to_jsonb(instrument.file_name_references) =
         entry->'expectedFileNameReferences'
    JOIN public.contributors contributor
      ON contributor.id = instrument.contributor_id
     AND contributor.slug = btrim(p_contributor_slug)
  ) THEN
    RAISE EXCEPTION 'source_pitchless_rehearsal_snapshot_changed'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest) entry
    JOIN public.sample_path_constructs collision
      ON collision.instrument_v2_id = (entry->>'instrumentV2Id')::uuid
     AND collision.id <> (entry->>'constructId')::uuid
     AND btrim(collision.pitch_content) = entry->>'expectedPitchContent'
     AND collision.velocity = (entry->>'expectedVelocity')::integer
     AND collision.round_robin = (entry->>'expectedRoundRobin')::integer
     AND coalesce(nullif(btrim(collision.mic_position), ''), 'main') =
         entry->>'expectedMicPosition'
     AND btrim(collision.filename) = 'pitchless'
  ) THEN
    RAISE EXCEPTION 'source_pitchless_destination_collision'
      USING ERRCODE = '55000';
  END IF;

  v_snapshot := public.sip_build_source_pitchless_snapshot_v1(
    p_contributor_slug, p_manifest
  );
  v_snapshot_hash := encode(
    extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'), 'hex'
  );
  -- The table fences above can wait behind an unrelated provider's atomic
  -- cutover. Revalidate immediately before returning or persisting rehearsal
  -- proof so an expired/released lease can never mint a usable receipt.
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'source_pitchless_rehearsal_lease_expired_before_persist'
      USING ERRCODE = '55000';
  END IF;
  SELECT * INTO v_existing
  FROM public.sip_source_pitchless_reconciliation_rehearsals rehearsal
  WHERE rehearsal.provider_slug = btrim(p_contributor_slug)
    AND rehearsal.manifest_hash = p_manifest_hash;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.manifest IS DISTINCT FROM p_manifest
       OR v_existing.source_snapshot_hash <> v_snapshot_hash
       OR v_existing.source_snapshot IS DISTINCT FROM v_snapshot
       OR v_existing.provider_lease_id <> p_lease_id
       OR v_existing.provider_lease_token <> p_lease_token
       OR v_existing.status <> 'passed'
       OR v_existing.consumed_at IS NOT NULL THEN
      RAISE EXCEPTION 'source_pitchless_rehearsal_snapshot_changed'
        USING ERRCODE = '40001';
    END IF;
    RETURN jsonb_build_object(
      'rehearsalRunId', v_existing.id,
      'manifestHash', p_manifest_hash,
      'sourceSnapshotHash', v_snapshot_hash,
      'repairableCount', 1,
      'idempotent', true
    );
  END IF;
  INSERT INTO public.sip_source_pitchless_reconciliation_rehearsals(
    provider_slug, provider_lease_id, provider_lease_token, manifest_hash,
    manifest, source_snapshot_hash, source_snapshot
  ) VALUES (
    btrim(p_contributor_slug), p_lease_id, p_lease_token, p_manifest_hash,
    p_manifest, v_snapshot_hash, v_snapshot
  ) RETURNING id INTO v_rehearsal_id;
  RETURN jsonb_build_object(
    'rehearsalRunId', v_rehearsal_id,
    'manifestHash', p_manifest_hash,
    'sourceSnapshotHash', v_snapshot_hash,
    'repairableCount', 1,
    'idempotent', false
  );
END;
$$;


ALTER FUNCTION "public"."sip_rehearse_source_pitchless_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_rehearse_source_pitchless_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_manifest" "jsonb") IS 'Persists one exact lease-bound source-pitchless rehearsal without changing provider rows.';



CREATE OR REPLACE FUNCTION "public"."sip_reject_fmg_retired_by_normalization_receipt_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN RAISE EXCEPTION 'fmg_retired_by_normalization_receipts_are_immutable'; END;
$$;


ALTER FUNCTION "public"."sip_reject_fmg_retired_by_normalization_receipt_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_reject_fmg_terminal_profile_wait_receipt_mutation_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
