BEGIN
  RAISE EXCEPTION 'fmg_terminal_profile_wait_receipt_immutable'
    USING ERRCODE = '55000';
END;
$$;


ALTER FUNCTION "public"."sip_reject_fmg_terminal_profile_wait_receipt_mutation_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_retired_provenance_disposition_snapshot_v1"("p_provider_slug" "text", "p_manifest" "jsonb", "p_expect_dispositions" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_entry_count integer;
  v_review_count integer;
  v_deferred_count integer;
  v_ignored_count integer;
  v_matching_count integer;
  v_disposition_count integer;
  v_snapshot jsonb;
BEGIN
  IF btrim(coalesce(p_provider_slug, '')) = ''
     OR jsonb_typeof(p_manifest) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_manifest->'schemaVersion') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_manifest->'entries') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_manifest->'entries') < 1
     OR jsonb_array_length(p_manifest->'entries') > 500
     OR p_manifest->>'providerSlug' IS DISTINCT FROM btrim(p_provider_slug)
     OR p_manifest->>'schemaVersion' IS DISTINCT FROM '1'
     OR btrim(coalesce(p_manifest->>'operatorIdentity', '')) = ''
     OR length(p_manifest->>'operatorIdentity') > 500
     OR jsonb_typeof(p_manifest->'expectedCounts') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'retired_provenance_disposition_manifest_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_object_keys(p_manifest) manifest_key
    WHERE manifest_key NOT IN (
      'schemaVersion', 'providerSlug', 'operatorIdentity',
      'expectedCounts', 'entries'
    )
  ) OR (SELECT count(*) FROM jsonb_object_keys(p_manifest)) <> 5 THEN
    RAISE EXCEPTION 'retired_provenance_disposition_manifest_shape_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'entries') entry
    WHERE jsonb_typeof(entry) IS DISTINCT FROM 'object'
       OR coalesce(entry->>'stagingInstrumentId', '') !~
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR coalesce(entry->>'instrumentV2Id', '') !~
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR coalesce(entry->>'samplePathConstructId', '') !~
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR coalesce(entry->>'sampleOriginalPathId', '') !~
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR btrim(coalesce(entry->>'retirementReason', '')) = ''
       OR length(entry->>'retirementReason') > 2000
       OR btrim(coalesce(entry->>'retiredBy', '')) = ''
       OR length(entry->>'retiredBy') > 500
       OR coalesce(entry->>'retiredAt', '') !~
          '^[0-9]{4}-[0-9]{2}-[0-9]{2}T'
       OR entry->>'disposition' NOT IN (
          'deferred_provenance', 'ignored_provenance'
       )
       OR btrim(coalesce(entry->>'reason', '')) = ''
       OR length(entry->>'reason') > 2000
  ) THEN
    RAISE EXCEPTION 'retired_provenance_disposition_manifest_entry_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'entries') entry
    CROSS JOIN LATERAL jsonb_object_keys(entry) entry_key
    WHERE entry_key NOT IN (
      'stagingInstrumentId', 'instrumentV2Id', 'samplePathConstructId',
      'sampleOriginalPathId', 'retirementReason', 'retiredBy', 'retiredAt',
      'disposition', 'reason'
    )
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'entries') entry
    WHERE (SELECT count(*) FROM jsonb_object_keys(entry)) <> 9
  ) THEN
    RAISE EXCEPTION 'retired_provenance_disposition_manifest_entry_shape_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_manifest->'entries') entry
    GROUP BY (entry->>'sampleOriginalPathId')::uuid HAVING count(*) > 1
  ) OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_manifest->'entries') entry
    GROUP BY (entry->>'samplePathConstructId')::uuid HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'retired_provenance_disposition_manifest_duplicate_source'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_each(p_manifest->'expectedCounts') expected(key, value)
    WHERE expected.key NOT IN (
      'reviewRows', 'sources', 'deferredProvenance',
      'ignoredProvenance', 'postWriteDispositions'
    )
       OR jsonb_typeof(expected.value) IS DISTINCT FROM 'number'
       OR expected.value::text !~ '^[0-9]+$'
       OR (expected.value::text)::numeric > 500
  ) OR (
    SELECT count(*) FROM jsonb_object_keys(p_manifest->'expectedCounts')
  ) <> 5 THEN
    RAISE EXCEPTION 'retired_provenance_disposition_expected_counts_invalid'
      USING ERRCODE = '22023';
  END IF;

  v_entry_count := jsonb_array_length(p_manifest->'entries');
  SELECT count(DISTINCT (entry->>'stagingInstrumentId')::uuid),
         count(*) FILTER (
           WHERE entry->>'disposition' = 'deferred_provenance'
         ),
         count(*) FILTER (
           WHERE entry->>'disposition' = 'ignored_provenance'
         )
  INTO v_review_count, v_deferred_count, v_ignored_count
  FROM jsonb_array_elements(p_manifest->'entries') entry;

  IF (p_manifest#>>'{expectedCounts,reviewRows}')::integer <> v_review_count
     OR (p_manifest#>>'{expectedCounts,sources}')::integer <> v_entry_count
     OR (p_manifest#>>'{expectedCounts,deferredProvenance}')::integer
        <> v_deferred_count
     OR (p_manifest#>>'{expectedCounts,ignoredProvenance}')::integer
        <> v_ignored_count
     OR (p_manifest#>>'{expectedCounts,postWriteDispositions}')::integer
        <> v_entry_count THEN
    RAISE EXCEPTION 'retired_provenance_disposition_expected_counts_mismatch'
      USING ERRCODE = '22023';
  END IF;

  -- Retired array/scope membership is historical evidence captured in the
  -- snapshot, not cohort authority: some correctly retired sources no longer
  -- remain there. The exact promotion -> unpublished V2 -> construct -> source
  -- chain is authoritative. No target source may simultaneously belong to an
  -- active review row through either membership representation.
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'entries') entry
    JOIN public.sip_review_instrument active
      ON active.is_retired = false
     AND (
       (entry->>'sampleOriginalPathId')::uuid = ANY(
         coalesce(active.original_sample_ids, '{}'::uuid[])
       )
       OR EXISTS (
         SELECT 1
         FROM public.sip_review_instrument_sample_scope active_scope
         WHERE active_scope.sip_review_instrument_id = active.id
           AND active_scope.original_sample_id =
               (entry->>'sampleOriginalPathId')::uuid
       )
     )
  ) THEN
    RAISE EXCEPTION 'retired_provenance_disposition_active_membership'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_manifest->'entries') entry
    JOIN public.sample_path_constructs conflict_construct
      ON conflict_construct.sample_original_path_id =
         (entry->>'sampleOriginalPathId')::uuid
    JOIN public.instruments_v2 published_instrument
      ON published_instrument.id = conflict_construct.instrument_v2_id
     AND published_instrument.published = true
  ) THEN
    RAISE EXCEPTION 'retired_provenance_disposition_published_source_conflict'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*) INTO v_matching_count
  FROM jsonb_array_elements(p_manifest->'entries') entry
  JOIN public.sip_review_instrument review
    ON review.id = (entry->>'stagingInstrumentId')::uuid
   AND review.source_contributor_slug = btrim(p_provider_slug)
   AND review.is_retired = true
   AND review.retired_reason = entry->>'retirementReason'
   AND review.retired_by = entry->>'retiredBy'
   AND review.retired_at = (entry->>'retiredAt')::timestamptz
  JOIN public.sip_review_promotion_map promotion
    ON promotion.sip_review_instrument_id = review.id
   AND promotion.instrument_v2_id = (entry->>'instrumentV2Id')::uuid
  JOIN public.instruments_v2 instrument
    ON instrument.id = promotion.instrument_v2_id
   AND instrument.published = false
  JOIN public.sample_path_constructs construct
    ON construct.id = (entry->>'samplePathConstructId')::uuid
   AND construct.sample_original_path_id =
       (entry->>'sampleOriginalPathId')::uuid
   AND construct.instrument_v2_id = instrument.id
  JOIN public.samples_original_paths source
    ON source.id = construct.sample_original_path_id;
  IF v_matching_count <> v_entry_count THEN
    RAISE EXCEPTION 'retired_provenance_disposition_identity_changed'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*) INTO v_disposition_count
  FROM public.sip_review_sample_disposition disposition
  WHERE disposition.sip_review_instrument_id IN (
      SELECT DISTINCT (entry->>'stagingInstrumentId')::uuid
      FROM jsonb_array_elements(p_manifest->'entries') entry
    )
     OR disposition.original_sample_id IN (
      SELECT (entry->>'sampleOriginalPathId')::uuid
      FROM jsonb_array_elements(p_manifest->'entries') entry
    );
  IF NOT p_expect_dispositions AND v_disposition_count <> 0 THEN
    RAISE EXCEPTION 'retired_provenance_disposition_already_dispositioned'
      USING ERRCODE = '55000';
  END IF;
  IF p_expect_dispositions THEN
    SELECT count(*) INTO v_matching_count
    FROM jsonb_array_elements(p_manifest->'entries') entry
    JOIN public.sip_review_sample_disposition disposition
      ON disposition.sip_review_instrument_id =
         (entry->>'stagingInstrumentId')::uuid
     AND disposition.original_sample_id =
         (entry->>'sampleOriginalPathId')::uuid
     AND disposition.contributor_slug = btrim(p_provider_slug)
     AND disposition.disposition = entry->>'disposition'
     AND disposition.reason = entry->>'reason'
     AND disposition.reviewed_by = p_manifest->>'operatorIdentity';
    IF v_disposition_count <> v_entry_count
       OR v_matching_count <> v_entry_count THEN
      RAISE EXCEPTION 'retired_provenance_disposition_post_write_mismatch'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'entry', entry,
      'review', to_jsonb(review),
      'promotion', to_jsonb(promotion),
      'instrumentV2', to_jsonb(instrument),
      'construct', to_jsonb(construct),
      'source', to_jsonb(source),
      'reviewScopeRows', (
        SELECT coalesce(
          jsonb_agg(to_jsonb(scope) ORDER BY scope.id), '[]'::jsonb
        )
        FROM public.sip_review_instrument_sample_scope scope
        WHERE scope.sip_review_instrument_id = review.id
      ),
      'sourceConstructRows', (
        SELECT coalesce(
          jsonb_agg(to_jsonb(source_construct) ORDER BY source_construct.id),
          '[]'::jsonb
        )
        FROM public.sample_path_constructs source_construct
        WHERE source_construct.sample_original_path_id = source.id
      )
    )
    ORDER BY entry->>'sampleOriginalPathId'
  ) INTO v_snapshot
  FROM jsonb_array_elements(p_manifest->'entries') entry
  JOIN public.sip_review_instrument review
    ON review.id = (entry->>'stagingInstrumentId')::uuid
  JOIN public.sip_review_promotion_map promotion
    ON promotion.sip_review_instrument_id = review.id
   AND promotion.instrument_v2_id = (entry->>'instrumentV2Id')::uuid
  JOIN public.instruments_v2 instrument
    ON instrument.id = promotion.instrument_v2_id
  JOIN public.sample_path_constructs construct
    ON construct.id = (entry->>'samplePathConstructId')::uuid
  JOIN public.samples_original_paths source
    ON source.id = (entry->>'sampleOriginalPathId')::uuid;
  RETURN coalesce(v_snapshot, '[]'::jsonb);
END;
$_$;


ALTER FUNCTION "public"."sip_retired_provenance_disposition_snapshot_v1"("p_provider_slug" "text", "p_manifest" "jsonb", "p_expect_dispositions" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rollback_gospel_talkbox_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_expected_after_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE rc public.sip_gospel_talkbox_grid_receipts%ROWTYPE; cur jsonb; rb jsonb; h text; n int; override_n int; locked_lease_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('gospel-musicians',0));
  IF btrim(p_provider_slug)<>'gospel-musicians' THEN RAISE EXCEPTION 'gospel_talkbox_grid_rollback_lease_invalid' USING ERRCODE='55000'; END IF;
  SELECT l.id INTO locked_lease_id FROM public.sip_fleet_provider_leases l WHERE l.id=p_lease_id AND l.lease_token=p_lease_token AND l.provider_slug='gospel-musicians' AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp() FOR UPDATE;
  IF locked_lease_id IS NULL THEN RAISE EXCEPTION 'gospel_talkbox_grid_rollback_lease_invalid' USING ERRCODE='55000'; END IF;
  IF EXISTS(SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gospel-musicians' AND status IN('queued','running')) THEN RAISE EXCEPTION 'gospel_talkbox_grid_active_run' USING ERRCODE='55000'; END IF;
  LOCK TABLE public.sip_sample_construct IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.sip_review_instrument IN SHARE MODE; LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE MODE; LOCK TABLE public.sip_gospel_talkbox_grid_receipts IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO rc FROM public.sip_gospel_talkbox_grid_receipts WHERE provider_slug='gospel-musicians' AND manifest_hash=p_manifest_hash FOR UPDATE;
  cur:=public.sip_build_gospel_talkbox_grid_snapshot_v1((SELECT manifest FROM public.sip_gospel_talkbox_grid_rehearsals WHERE id=rc.rehearsal_id)); h:=encode(extensions.digest(convert_to(cur::text,'UTF8'),'sha256'),'hex');
  IF rc.result IS NULL OR rc.rolled_back_at IS NOT NULL OR h<>p_expected_after_hash OR cur IS DISTINCT FROM rc.after_snapshot THEN RAISE EXCEPTION 'gospel_talkbox_grid_rollback_drift' USING ERRCODE='40001'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.sip_fleet_provider_leases l WHERE l.id=locked_lease_id AND l.lease_token=p_lease_token AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'gospel_talkbox_grid_lease_expired_before_write' USING ERRCODE='55000'; END IF;
  UPDATE public.sip_sample_construct c SET midi_note=e->>'expectedMidiNote',updated_at=now() FROM public.sip_gospel_talkbox_grid_rehearsals rr, jsonb_array_elements(rr.manifest) e WHERE rr.id=rc.rehearsal_id AND c.original_sample_id=(e->>'originalSampleId')::uuid AND c.midi_note=e->>'targetMidiNote'; GET DIAGNOSTICS n=ROW_COUNT;
  IF n<>396 THEN RAISE EXCEPTION 'gospel_talkbox_grid_rollback_count_mismatch' USING ERRCODE='40001'; END IF;
  UPDATE public.sip_review_sample_override o SET midi_note=e->>'expectedMidiNote',updated_at=now() FROM public.sip_gospel_talkbox_grid_rehearsals rr, jsonb_array_elements(rr.manifest) e WHERE rr.id=rc.rehearsal_id AND o.original_sample_id=(e->>'originalSampleId')::uuid AND o.midi_note=e->>'targetMidiNote'; GET DIAGNOSTICS override_n=ROW_COUNT;
  rb:=public.sip_build_gospel_talkbox_grid_snapshot_v1((SELECT manifest FROM public.sip_gospel_talkbox_grid_rehearsals WHERE id=rc.rehearsal_id));
  IF rb IS DISTINCT FROM rc.before_snapshot THEN RAISE EXCEPTION 'gospel_talkbox_grid_rollback_not_exact' USING ERRCODE='40001'; END IF;
  h:=encode(extensions.digest(convert_to(rb::text,'UTF8'),'sha256'),'hex'); UPDATE public.sip_gospel_talkbox_grid_receipts SET rolled_back_at=now(),rollback_snapshot_hash=h WHERE provider_slug='gospel-musicians' AND manifest_hash=p_manifest_hash;
  RETURN jsonb_build_object('manifestHash',p_manifest_hash,'rolledBackCount',396,'rollbackSnapshotHash',h);
END $$;


ALTER FUNCTION "public"."sip_rollback_gospel_talkbox_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_expected_after_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rollback_gospel_talkbox_incomplete_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_expected_after_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE rc public.sip_gospel_talkbox_grid_receipts%ROWTYPE; cur jsonb; rb jsonb; h text; n int; override_n int; locked_lease_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('gospel-musicians',0));
  IF btrim(p_provider_slug)<>'gospel-musicians' THEN RAISE EXCEPTION 'gospel_talkbox_grid_rollback_lease_invalid' USING ERRCODE='55000'; END IF;
  SELECT l.id INTO locked_lease_id FROM public.sip_fleet_provider_leases l WHERE l.id=p_lease_id AND l.lease_token=p_lease_token AND l.provider_slug='gospel-musicians' AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp() FOR UPDATE;
  IF locked_lease_id IS NULL THEN RAISE EXCEPTION 'gospel_talkbox_grid_rollback_lease_invalid' USING ERRCODE='55000'; END IF;
  IF EXISTS(SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gospel-musicians' AND status IN('queued','running')) THEN RAISE EXCEPTION 'gospel_talkbox_grid_active_run' USING ERRCODE='55000'; END IF;
  LOCK TABLE public.sip_sample_construct IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.sip_review_instrument IN SHARE MODE; LOCK TABLE public.sip_review_instrument_sample_scope IN SHARE MODE; LOCK TABLE public.sip_gospel_talkbox_grid_receipts IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO rc FROM public.sip_gospel_talkbox_grid_receipts WHERE provider_slug='gospel-musicians' AND manifest_hash=p_manifest_hash FOR UPDATE;
  cur:=public.sip_build_gospel_talkbox_grid_snapshot_v1((SELECT manifest FROM public.sip_gospel_talkbox_grid_rehearsals WHERE id=rc.rehearsal_id)); h:=encode(extensions.digest(convert_to(cur::text,'UTF8'),'sha256'),'hex');
  IF rc.result IS NULL OR rc.rolled_back_at IS NOT NULL OR h<>p_expected_after_hash OR cur IS DISTINCT FROM rc.after_snapshot THEN RAISE EXCEPTION 'gospel_talkbox_grid_rollback_drift' USING ERRCODE='40001'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.sip_fleet_provider_leases l WHERE l.id=locked_lease_id AND l.lease_token=p_lease_token AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'gospel_talkbox_grid_lease_expired_before_write' USING ERRCODE='55000'; END IF;
  UPDATE public.sip_sample_construct c SET midi_note=e->>'expectedMidiNote',updated_at=now() FROM public.sip_gospel_talkbox_grid_rehearsals rr, jsonb_array_elements(rr.manifest) e WHERE rr.id=rc.rehearsal_id AND c.original_sample_id=(e->>'originalSampleId')::uuid AND c.midi_note=e->>'targetMidiNote'; GET DIAGNOSTICS n=ROW_COUNT;
  IF n<>69 THEN RAISE EXCEPTION 'gospel_talkbox_grid_rollback_count_mismatch' USING ERRCODE='40001'; END IF;
  UPDATE public.sip_review_sample_override o SET midi_note=e->>'expectedMidiNote',updated_at=now() FROM public.sip_gospel_talkbox_grid_rehearsals rr, jsonb_array_elements(rr.manifest) e WHERE rr.id=rc.rehearsal_id AND o.original_sample_id=(e->>'originalSampleId')::uuid AND o.midi_note=e->>'targetMidiNote'; GET DIAGNOSTICS override_n=ROW_COUNT;
  rb:=public.sip_build_gospel_talkbox_grid_snapshot_v1((SELECT manifest FROM public.sip_gospel_talkbox_grid_rehearsals WHERE id=rc.rehearsal_id));
  IF rb IS DISTINCT FROM rc.before_snapshot THEN RAISE EXCEPTION 'gospel_talkbox_grid_rollback_not_exact' USING ERRCODE='40001'; END IF;
  h:=encode(extensions.digest(convert_to(rb::text,'UTF8'),'sha256'),'hex'); UPDATE public.sip_gospel_talkbox_grid_receipts SET rolled_back_at=now(),rollback_snapshot_hash=h WHERE provider_slug='gospel-musicians' AND manifest_hash=p_manifest_hash;
  RETURN jsonb_build_object('manifestHash',p_manifest_hash,'rolledBackCount',69,'rollbackSnapshotHash',h);
END $$;


ALTER FUNCTION "public"."sip_rollback_gospel_talkbox_incomplete_grid_v1"("p_provider_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_expected_after_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rollback_gotchanoddin_tonal_kit_pitchless_v1"("p_receipt_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_authorization_proof" "text", "p_rolled_back_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE receipt public.sip_gotchanoddin_tonal_kit_pitchless_receipts%ROWTYPE; manifest jsonb; row jsonb; restored_instruments integer:=0; restored_constructs integer:=0; changed_rows integer; restored jsonb;
BEGIN
  IF current_setting('app.sip_publish_coordinator_authorized',true) IS DISTINCT FROM 'on' OR btrim(coalesce(p_authorization_proof,'')) !~ '^[a-f0-9]{64}$' OR btrim(coalesce(p_rolled_back_by,''))='' THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_rollback_authorization_invalid' USING ERRCODE='42501'; END IF;
  SELECT receipt_row INTO receipt
    FROM public.sip_gotchanoddin_tonal_kit_pitchless_receipts receipt_row
    WHERE receipt_row.id=p_receipt_id FOR UPDATE;
  IF receipt.id IS NULL OR EXISTS (SELECT 1 FROM public.sip_gotchanoddin_tonal_kit_pitchless_rollbacks WHERE receipt_id=receipt.id) THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_rollback_receipt_invalid' USING ERRCODE='40001'; END IF;
  SELECT rehearsal.manifest INTO manifest
    FROM public.sip_gotchanoddin_tonal_kit_pitchless_rehearsals rehearsal
    WHERE rehearsal.id=receipt.rehearsal_id;
  IF NOT EXISTS (SELECT 1 FROM public.sip_fleet_provider_leases l WHERE l.id=p_lease_id AND l.provider_slug='gotchanoddin' AND l.lease_token=p_lease_token AND l.released_at IS NULL AND l.lease_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_rollback_lease_invalid' USING ERRCODE='55000'; END IF;
  IF EXISTS (SELECT 1 FROM public.sip_fleet_runs WHERE provider_slug='gotchanoddin' AND status IN ('queued','running')) THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_active_run' USING ERRCODE='55000'; END IF;
  IF public.sip_gotchanoddin_tonal_kit_pitchless_snapshot_v1(manifest) IS DISTINCT FROM receipt.after_snapshot THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_rollback_drift' USING ERRCODE='40001'; END IF;
  FOR row IN SELECT value FROM jsonb_array_elements(receipt.rollback_payload->'instruments') LOOP
    UPDATE public.instruments_v2 SET engine_type=row->>'engineType', single_pitch=(row->>'singlePitch')::integer, sampled_midi_notes=CASE WHEN row->'sampledMidiNotes' IS NULL OR row->'sampledMidiNotes'='null'::jsonb THEN NULL ELSE ARRAY(SELECT jsonb_array_elements_text(row->'sampledMidiNotes')::integer) END, file_name_references=ARRAY(SELECT jsonb_array_elements_text(row->'fileNameReferences')), updated_at=now() WHERE id=(row->>'id')::uuid; GET DIAGNOSTICS changed_rows=ROW_COUNT; restored_instruments:=restored_instruments+changed_rows;
  END LOOP;
  FOR row IN SELECT value FROM jsonb_array_elements(receipt.rollback_payload->'constructs') LOOP
    UPDATE public.sample_path_constructs SET midi_note=row->>'midiNote', filename=row->>'filename', pitch_content=row->>'pitchContent', updated_at=now() WHERE id=(row->>'id')::uuid; GET DIAGNOSTICS changed_rows=ROW_COUNT; restored_constructs:=restored_constructs+changed_rows;
  END LOOP;
  IF restored_instruments<>2397 OR restored_constructs<>2397 THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_rollback_count_mismatch' USING ERRCODE='40001'; END IF;
  IF public.sip_gotchanoddin_tonal_kit_pitchless_snapshot_v1(manifest) IS DISTINCT FROM receipt.before_snapshot THEN RAISE EXCEPTION 'gotchanoddin_tonal_kit_rollback_restore_mismatch' USING ERRCODE='40001'; END IF;
  restored:=jsonb_build_object('receiptId',receipt.id,'rolledBack',2397,'restoredConstructs',2397);
  INSERT INTO public.sip_gotchanoddin_tonal_kit_pitchless_rollbacks(receipt_id,rollback_by,rollback_snapshot) VALUES(receipt.id,p_rolled_back_by,public.sip_gotchanoddin_tonal_kit_pitchless_snapshot_v1(manifest));
  RETURN restored;
END; $_$;


ALTER FUNCTION "public"."sip_rollback_gotchanoddin_tonal_kit_pitchless_v1"("p_receipt_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_authorization_proof" "text", "p_rolled_back_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_rollback_source_pitchless_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_expected_after_snapshot_hash" "text", "p_rolled_back_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_receipt public.sip_source_pitchless_reconciliation_receipts%ROWTYPE;
  v_current_snapshot jsonb;
  v_current_hash text;
  v_rollback_snapshot jsonb;
  v_rollback_hash text;
  v_instrument_id uuid;
  v_updated_count integer;
  v_refreshed_count integer;
BEGIN
  IF btrim(coalesce(p_contributor_slug, '')) <> 'fallout-music-group'
     OR p_lease_id IS NULL OR p_lease_token IS NULL
     OR p_manifest_hash <> '1e9ef13ed4e83d9da2245bbafcdb2b83b47c87df7f118148cd4a133855412310'
     OR coalesce(p_expected_after_snapshot_hash, '') !~ '^[0-9a-f]{64}$'
     OR btrim(coalesce(p_rolled_back_by, '')) = '' THEN
    RAISE EXCEPTION 'source_pitchless_rollback_identity_invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    hashtextextended(btrim(p_contributor_slug), 0)
  );
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'source_pitchless_rollback_lease_invalid'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug = btrim(p_contributor_slug)
      AND run.status IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'source_pitchless_rollback_active_run'
      USING ERRCODE = '55000';
  END IF;
  LOCK TABLE public.instruments_v2 IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_instrument IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_promotion_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sample_path_constructs IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.samples_original_paths IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_review_sample_override IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_source_pitchless_reconciliation_rehearsals
    IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.sip_source_pitchless_reconciliation_receipts
    IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.instrument_v2_legacy_map IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO v_receipt
  FROM public.sip_source_pitchless_reconciliation_receipts receipt
  WHERE receipt.provider_slug = btrim(p_contributor_slug)
    AND receipt.manifest_hash = p_manifest_hash
  FOR UPDATE;
  IF v_receipt.result IS NULL
     OR v_receipt.after_snapshot_hash <> p_expected_after_snapshot_hash THEN
    RAISE EXCEPTION 'source_pitchless_rollback_receipt_required'
      USING ERRCODE = '55000';
  END IF;
  SELECT (entry->>'instrumentV2Id')::uuid INTO v_instrument_id
  FROM jsonb_array_elements(v_receipt.manifest) entry;
  PERFORM construct.id FROM public.sample_path_constructs construct
  WHERE construct.instrument_v2_id = v_instrument_id FOR UPDATE;
  PERFORM instrument.id FROM public.instruments_v2 instrument
  WHERE instrument.id = v_instrument_id
     OR v_instrument_id = ANY(COALESCE(instrument.articulations, ARRAY[]::uuid[]))
     OR v_instrument_id = ANY(COALESCE(instrument.effects_instruments, ARRAY[]::uuid[]))
     OR instrument.legato_transition = v_instrument_id
  FOR UPDATE;
  PERFORM source.id FROM public.samples_original_paths source
  WHERE source.id IN (
    SELECT (entry->>'sampleOriginalPathId')::uuid
    FROM jsonb_array_elements(v_receipt.manifest) entry
  ) FOR SHARE;
  PERFORM alias_row.id FROM public.instrument_v2_legacy_map alias_row
  WHERE alias_row.instrument_v2_id = v_instrument_id FOR SHARE;
  PERFORM promotion.id FROM public.sip_review_promotion_map promotion
  WHERE promotion.instrument_v2_id = v_instrument_id FOR SHARE;
  PERFORM review.id FROM public.sip_review_instrument review
  WHERE review.id IN (
    SELECT promotion.sip_review_instrument_id
    FROM public.sip_review_promotion_map promotion
    WHERE promotion.instrument_v2_id = v_instrument_id
  ) FOR UPDATE;
  PERFORM override_row.id FROM public.sip_review_sample_override override_row
  WHERE override_row.sip_review_instrument_id IN (
    SELECT promotion.sip_review_instrument_id
    FROM public.sip_review_promotion_map promotion
    WHERE promotion.instrument_v2_id = v_instrument_id
  ) FOR SHARE;
  v_current_snapshot := public.sip_build_source_pitchless_snapshot_v1(
    p_contributor_slug, v_receipt.manifest
  );
  v_current_hash := encode(
    extensions.digest(convert_to(v_current_snapshot::text, 'UTF8'), 'sha256'), 'hex'
  );
  IF v_receipt.rolled_back_at IS NOT NULL THEN
    IF v_current_hash <> v_receipt.rollback_snapshot_hash
       OR v_current_snapshot IS DISTINCT FROM v_receipt.before_snapshot THEN
      RAISE EXCEPTION 'source_pitchless_rollback_replay_snapshot_changed'
        USING ERRCODE = '40001';
    END IF;
    RETURN jsonb_build_object(
      'providerSlug', btrim(p_contributor_slug),
      'manifestHash', p_manifest_hash,
      'expectedAfterSnapshotHash', p_expected_after_snapshot_hash,
      'rollbackSnapshotHash', v_receipt.rollback_snapshot_hash,
      'rolledBackCount', 1,
      'idempotent', true
    );
  END IF;
  IF v_current_hash <> p_expected_after_snapshot_hash
     OR v_current_snapshot IS DISTINCT FROM v_receipt.after_snapshot THEN
    RAISE EXCEPTION 'source_pitchless_rollback_snapshot_changed'
      USING ERRCODE = '40001';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = btrim(p_contributor_slug)
      AND lease.lease_token = p_lease_token
      AND lease.released_at IS NULL
      AND lease.lease_expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'source_pitchless_lease_expired_before_rollback'
      USING ERRCODE = '55000';
  END IF;
  WITH manifest_entry AS (
    SELECT entry FROM jsonb_array_elements(v_receipt.manifest) entry
  )
  UPDATE public.sample_path_constructs construct
  SET midi_note = entry->>'expectedMidiNote',
      filename = entry->>'expectedFilename',
      updated_at = now()
  FROM manifest_entry entry
  WHERE construct.id = (entry->>'constructId')::uuid
    AND construct.midi_note = 'pitchless'
    AND construct.filename = 'pitchless';
  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> 1 THEN
    RAISE EXCEPTION 'source_pitchless_rollback_count_mismatch'
      USING ERRCODE = '55000';
  END IF;
  SELECT public.refresh_instrument_v2_axis_summaries_v1(ARRAY[v_instrument_id])
    INTO v_refreshed_count;
  IF v_refreshed_count <> 1 THEN
    RAISE EXCEPTION 'source_pitchless_rollback_summary_refresh_failed'
      USING ERRCODE = '55000';
  END IF;
  v_rollback_snapshot := public.sip_build_source_pitchless_snapshot_v1(
    p_contributor_slug, v_receipt.manifest
  );
  v_rollback_hash := encode(
    extensions.digest(convert_to(v_rollback_snapshot::text, 'UTF8'), 'sha256'), 'hex'
  );
  IF v_rollback_snapshot IS DISTINCT FROM v_receipt.before_snapshot THEN
    RAISE EXCEPTION 'source_pitchless_rollback_before_snapshot_mismatch'
      USING ERRCODE = '40001';
  END IF;
  UPDATE public.sip_source_pitchless_reconciliation_receipts
  SET rolled_back_at = now(), rolled_back_by = btrim(p_rolled_back_by),
      rollback_snapshot_hash = v_rollback_hash
  WHERE provider_slug = btrim(p_contributor_slug)
    AND manifest_hash = p_manifest_hash;
  RETURN jsonb_build_object(
    'providerSlug', btrim(p_contributor_slug),
    'manifestHash', p_manifest_hash,
    'expectedAfterSnapshotHash', p_expected_after_snapshot_hash,
    'rollbackSnapshotHash', v_rollback_hash,
    'rolledBackCount', 1,
    'idempotent', false
  );
END;
$_$;


ALTER FUNCTION "public"."sip_rollback_source_pitchless_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_expected_after_snapshot_hash" "text", "p_rolled_back_by" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sip_rollback_source_pitchless_reconciliation_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_manifest_hash" "text", "p_expected_after_snapshot_hash" "text", "p_rolled_back_by" "text") IS 'Rolls back only the exact unchanged post-apply snapshot recorded by a source-pitchless receipt.';



CREATE OR REPLACE FUNCTION "public"."sip_runtime_duration_approve_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_approved_by" "text", "p_rehearsal_run_id" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "public"."sip_fleet_plan_artifact_approvals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_approval public.sip_fleet_plan_artifact_approvals%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('sonuscore',0));
  IF btrim(coalesce(p_contributor_slug,'')) <> 'sonuscore'
    OR nullif(btrim(p_approved_by),'') IS NULL
    OR coalesce(p_rehearsal_run_id,'') !~ '^[0-9a-f-]{36}$'
  THEN RAISE EXCEPTION 'runtime_duration_approval_identity_invalid'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug='sonuscore'
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>clock_timestamp() FOR UPDATE
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.sip_fleet_plan_artifacts artifact
    JOIN public.sip_runtime_duration_recovery_rehearsals rehearsal
      ON rehearsal.artifact_id=artifact.id
     AND rehearsal.id=p_rehearsal_run_id::uuid
     AND rehearsal.passed IS TRUE
     AND rehearsal.content_hash=artifact.content_hash
    WHERE artifact.id=p_artifact_id
      AND artifact.artifact_kind='runtime-duration-recovery-v1'
      AND artifact.content_hash=p_expected_content_hash
      AND artifact.content->'approval'->>'rehearsalRunId'=p_rehearsal_run_id
  ) THEN RAISE EXCEPTION 'runtime_duration_rehearsal_not_passed'; END IF;
  INSERT INTO public.sip_fleet_plan_artifact_approvals(
    artifact_id,content_hash,approved_by,approval_metadata
  ) VALUES (
    p_artifact_id,p_expected_content_hash,btrim(p_approved_by),
    jsonb_build_object('rehearsalRunId',p_rehearsal_run_id)
  ) ON CONFLICT (artifact_id) DO NOTHING RETURNING * INTO v_approval;
  IF v_approval.artifact_id IS NULL THEN
    SELECT * INTO STRICT v_approval FROM public.sip_fleet_plan_artifact_approvals approval
    WHERE approval.artifact_id=p_artifact_id;
    IF v_approval.content_hash<>p_expected_content_hash
      OR v_approval.approved_by<>btrim(p_approved_by)
      OR v_approval.approval_metadata<>jsonb_build_object('rehearsalRunId',p_rehearsal_run_id)
    THEN RAISE EXCEPTION 'artifact_approval_payload_mismatch'; END IF;
  END IF;
  RETURN v_approval;
END $_$;


ALTER FUNCTION "public"."sip_runtime_duration_approve_v1"("p_contributor_slug" "text", "p_artifact_id" "uuid", "p_expected_content_hash" "text", "p_approved_by" "text", "p_rehearsal_run_id" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_runtime_duration_artifact_upload_v1"("p_contributor_slug" "text", "p_content" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "public"."sip_fleet_plan_artifacts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_hash text;
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('sonuscore',0));
  IF btrim(coalesce(p_contributor_slug,'')) <> 'sonuscore'
    OR jsonb_typeof(p_content) IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'runtime_duration_identity_required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug='sonuscore'
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>clock_timestamp()
    FOR UPDATE
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  v_hash := encode(digest(convert_to(p_content::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.sip_fleet_plan_artifacts(
    provider_slug,artifact_kind,content_hash,content,created_by
  ) SELECT 'sonuscore','runtime-duration-recovery-v1',v_hash,p_content,lease.lease_owner
    FROM public.sip_fleet_provider_leases lease WHERE lease.id=p_lease_id
  ON CONFLICT (provider_slug,artifact_kind,content_hash) DO NOTHING
  RETURNING * INTO v_artifact;
  IF v_artifact.id IS NULL THEN
    SELECT * INTO STRICT v_artifact FROM public.sip_fleet_plan_artifacts artifact
    WHERE artifact.provider_slug='sonuscore'
      AND artifact.artifact_kind='runtime-duration-recovery-v1'
      AND artifact.content_hash=v_hash;
  END IF;
  PERFORM public.sip_runtime_duration_assert_scope_v1(v_artifact.id,true);
  RETURN v_artifact;
END $$;


ALTER FUNCTION "public"."sip_runtime_duration_artifact_upload_v1"("p_contributor_slug" "text", "p_content" "jsonb", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_runtime_duration_assert_scope_v1"("p_artifact_id" "uuid", "p_require_unapplied" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_content jsonb;
  v_count integer;
  v_projection jsonb;
  v_projection_hash text;
BEGIN
  SELECT * INTO STRICT v_artifact
  FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id = p_artifact_id
  FOR SHARE;
  v_content := v_artifact.content;

  IF v_artifact.provider_slug <> 'sonuscore'
    OR v_artifact.artifact_kind <> 'runtime-duration-recovery-v1'
    OR v_content->>'schemaVersion' <> 'runtime-duration-recovery-v1'
    OR v_content->>'contributor' <> 'sonuscore'
    OR coalesce(v_content->>'processorRevision','') !~ '^[0-9a-f]{40}$'
    OR jsonb_typeof(v_content->'samples') IS DISTINCT FROM 'array'
    OR coalesce((v_content->>'expectedCount')::integer, 0) <= 0
    OR (v_content->>'expectedCount')::integer > 250
  THEN RAISE EXCEPTION 'runtime_duration_artifact_invalid'; END IF;

  SELECT count(*)::integer INTO v_count
  FROM jsonb_array_elements(v_content->'samples');
  IF v_count <> (v_content->>'expectedCount')::integer
    OR v_count <> (
      SELECT count(DISTINCT (sample->>'sampleOriginalPathId')::uuid)
      FROM jsonb_array_elements(v_content->'samples') sample
    )
  THEN RAISE EXCEPTION 'runtime_duration_scope_count_mismatch'; END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_content->'samples') sample
    WHERE coalesce(sample->>'instrumentV2Id','') !~ '^[0-9a-f-]{36}$'
      OR coalesce(sample->>'samplePathConstructId','') !~ '^[0-9a-f-]{36}$'
      OR coalesce(sample->>'sampleOriginalPathId','') !~ '^[0-9a-f-]{36}$'
      OR nullif(btrim(sample->>'sourceS3Uri'),'') IS NULL
      OR jsonb_typeof(sample->'expectedSourceObjectIdentity') IS DISTINCT FROM 'object'
      OR coalesce(sample->>'sourceIdentitySha256','') !~ '^[0-9a-f]{64}$'
  ) THEN RAISE EXCEPTION 'runtime_duration_sample_identity_invalid'; END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_content->'samples') sample
    LEFT JOIN public.sample_path_constructs construct
      ON construct.id=(sample->>'samplePathConstructId')::uuid
     AND construct.instrument_v2_id=(sample->>'instrumentV2Id')::uuid
     AND construct.sample_original_path_id=(sample->>'sampleOriginalPathId')::uuid
    LEFT JOIN public.samples_original_paths source
      ON source.id=(sample->>'sampleOriginalPathId')::uuid
     AND source.s3_path=sample->>'sourceS3Uri'
    LEFT JOIN public.instruments_v2 instrument
      ON instrument.id=(sample->>'instrumentV2Id')::uuid
    LEFT JOIN public.contributors contributor
      ON contributor.id=instrument.contributor_id
    LEFT JOIN public.analysis_librosa analysis
      ON analysis.sample_id=source.id
    WHERE construct.id IS NULL OR source.id IS NULL OR instrument.id IS NULL
      OR instrument.published IS NOT TRUE OR contributor.slug <> 'sonuscore'
      OR analysis.id IS NOT NULL OR source.librosa_analyzed IS NOT FALSE
      OR source.claimed_by IS NOT NULL OR source.claimed_at IS NOT NULL
  ) THEN RAISE EXCEPTION 'runtime_duration_scope_drift'; END IF;

  IF EXISTS (
    SELECT source.id
    FROM public.instruments_v2 instrument
    JOIN public.contributors contributor ON contributor.id=instrument.contributor_id
    JOIN public.sample_path_constructs construct ON construct.instrument_v2_id=instrument.id
    JOIN public.samples_original_paths source ON source.id=construct.sample_original_path_id
    LEFT JOIN public.analysis_librosa analysis ON analysis.sample_id=source.id
    WHERE instrument.published IS TRUE AND contributor.slug='sonuscore'
      AND analysis.id IS NULL
      AND instrument.id IN (
        SELECT DISTINCT (sample->>'instrumentV2Id')::uuid
        FROM jsonb_array_elements(v_content->'samples') sample
      )
    EXCEPT
    SELECT (sample->>'sampleOriginalPathId')::uuid
    FROM jsonb_array_elements(v_content->'samples') sample
  ) OR EXISTS (
    SELECT (sample->>'sampleOriginalPathId')::uuid
    FROM jsonb_array_elements(v_content->'samples') sample
    EXCEPT
    SELECT source.id
    FROM public.instruments_v2 instrument
    JOIN public.contributors contributor ON contributor.id=instrument.contributor_id
    JOIN public.sample_path_constructs construct ON construct.instrument_v2_id=instrument.id
    JOIN public.samples_original_paths source ON source.id=construct.sample_original_path_id
    LEFT JOIN public.analysis_librosa analysis ON analysis.sample_id=source.id
    WHERE instrument.published IS TRUE AND contributor.slug='sonuscore'
      AND analysis.id IS NULL
      AND instrument.id IN (
        SELECT DISTINCT (sample->>'instrumentV2Id')::uuid
        FROM jsonb_array_elements(v_content->'samples') sample
      )
  ) THEN RAISE EXCEPTION 'runtime_duration_fresh_audit_scope_mismatch'; END IF;

  IF p_require_unapplied AND EXISTS (
    SELECT 1 FROM public.sip_runtime_duration_recovery_receipts receipt
    WHERE receipt.artifact_id=p_artifact_id
  ) THEN RAISE EXCEPTION 'runtime_duration_already_applied'; END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'instrumentV2Id',instrument.id,
    'samplePathConstructId',construct.id,
    'sampleOriginalPathId',source.id,
    'sourceS3Uri',source.s3_path,
    'librosaAnalyzed',source.librosa_analyzed,
    'analysisPresent',analysis.id IS NOT NULL
  ) ORDER BY instrument.id,construct.id,source.id)
  INTO v_projection
  FROM jsonb_array_elements(v_content->'samples') sample
  JOIN public.instruments_v2 instrument ON instrument.id=(sample->>'instrumentV2Id')::uuid
  JOIN public.sample_path_constructs construct ON construct.id=(sample->>'samplePathConstructId')::uuid
  JOIN public.samples_original_paths source ON source.id=(sample->>'sampleOriginalPathId')::uuid
  LEFT JOIN public.analysis_librosa analysis ON analysis.sample_id=source.id;
  v_projection_hash := encode(digest(convert_to(v_projection::text,'UTF8'),'sha256'),'hex');
  RETURN jsonb_build_object(
    'artifactId',p_artifact_id,
    'contentHash',v_artifact.content_hash,
    'expectedCount',v_count,
    'projectionHash',v_projection_hash,
    'projection',v_projection
  );
END $_$;


ALTER FUNCTION "public"."sip_runtime_duration_assert_scope_v1"("p_artifact_id" "uuid", "p_require_unapplied" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_runtime_duration_claim_v1"("p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_worker_id" "text", "p_claim_seconds" integer DEFAULT 1800) RETURNS TABLE("sample_original_path_id" "uuid", "instrument_v2_id" "uuid", "sample_path_construct_id" "uuid", "s3_path" "text", "file_name" "text", "expected_source_object_identity" "jsonb", "source_identity_sha256" "text", "processor_revision" "text", "claim_token" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_scope jsonb; v_expected_count integer; v_existing_count integer; v_updated integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('sonuscore',0));
  IF nullif(btrim(p_worker_id),'') IS NULL OR p_claim_seconds<60 OR p_claim_seconds>3600
  THEN RAISE EXCEPTION 'runtime_duration_claim_invalid'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug='sonuscore'
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>clock_timestamp() FOR UPDATE
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_fleet_runs run
    WHERE run.provider_slug='sonuscore' AND run.status IN ('queued','running')
  ) THEN RAISE EXCEPTION 'active_provider_run'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_runtime_duration_recovery_rollbacks rollback
    WHERE rollback.artifact_id=p_artifact_id
  ) THEN RAISE EXCEPTION 'runtime_duration_artifact_rolled_back'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_plan_artifacts artifact
    JOIN public.sip_fleet_plan_artifact_approvals approval
      ON approval.artifact_id=artifact.id AND approval.content_hash=artifact.content_hash
    JOIN public.sip_runtime_duration_recovery_rehearsals rehearsal
      ON rehearsal.artifact_id=artifact.id AND rehearsal.passed IS TRUE
     AND rehearsal.id=(approval.approval_metadata->>'rehearsalRunId')::uuid
    WHERE artifact.id=p_artifact_id AND artifact.artifact_kind='runtime-duration-recovery-v1'
  ) THEN RAISE EXCEPTION 'runtime_duration_artifact_not_approved'; END IF;
  SELECT (artifact.content->>'expectedCount')::integer INTO v_expected_count
  FROM public.sip_fleet_plan_artifacts artifact WHERE artifact.id=p_artifact_id;
  SELECT count(*)::integer INTO v_existing_count
  FROM public.sip_runtime_duration_recovery_claims claim
  WHERE claim.artifact_id=p_artifact_id;
  IF v_existing_count=v_expected_count THEN
    IF EXISTS (
      SELECT 1
      FROM public.sip_runtime_duration_recovery_claims claim
      JOIN public.samples_original_paths source ON source.id=claim.sample_original_path_id
      WHERE claim.artifact_id=p_artifact_id AND (
        claim.worker_id<>btrim(p_worker_id)
        OR claim.status IN ('failed','rolled_back')
        OR (
          claim.status='claimed'
          AND source.claimed_by<>'runtime-duration:'||p_artifact_id::text||':'||btrim(p_worker_id)
        )
        OR (
          claim.status='completed' AND (
            source.librosa_analyzed IS NOT TRUE OR source.claimed_by IS NOT NULL
            OR NOT EXISTS (
              SELECT 1
              FROM public.sip_runtime_duration_recovery_receipts receipt
              JOIN public.analysis_librosa analysis ON analysis.id=receipt.analysis_librosa_id
              WHERE receipt.artifact_id=claim.artifact_id
                AND receipt.sample_original_path_id=claim.sample_original_path_id
                AND analysis.sample_id=claim.sample_original_path_id
                AND analysis.duration=receipt.duration_seconds
            )
          )
        )
      )
    ) THEN RAISE EXCEPTION 'runtime_duration_claim_replay_drift'; END IF;
    UPDATE public.sip_runtime_duration_recovery_claims
    SET lease_id=p_lease_id,
        claim_expires_at=clock_timestamp()+make_interval(secs=>p_claim_seconds)
    WHERE artifact_id=p_artifact_id AND status='claimed';
  ELSIF v_existing_count<>0 THEN
    RAISE EXCEPTION 'runtime_duration_partial_claim_state';
  ELSE
    v_scope := public.sip_runtime_duration_assert_scope_v1(p_artifact_id,true);

    INSERT INTO public.sip_runtime_duration_recovery_claims(
      artifact_id,sample_original_path_id,instrument_v2_id,sample_path_construct_id,
      lease_id,worker_id,claim_expires_at,before_sample_state
    )
    SELECT p_artifact_id,(sample->>'sampleOriginalPathId')::uuid,
      (sample->>'instrumentV2Id')::uuid,(sample->>'samplePathConstructId')::uuid,
      p_lease_id,btrim(p_worker_id),clock_timestamp()+make_interval(secs=>p_claim_seconds),
      jsonb_build_object(
        'librosaAnalyzed',source.librosa_analyzed,
        'claimedBy',source.claimed_by,
        'claimedAt',source.claimed_at,
        'errorMessage',source.error_message,
        'retryCount',source.retry_count
      )
    FROM public.sip_fleet_plan_artifacts artifact,
         jsonb_array_elements(artifact.content->'samples') sample
    JOIN public.samples_original_paths source
      ON source.id=(sample->>'sampleOriginalPathId')::uuid
    WHERE artifact.id=p_artifact_id;

    UPDATE public.samples_original_paths source
    SET claimed_by='runtime-duration:'||p_artifact_id::text||':'||btrim(p_worker_id),
        claimed_at=clock_timestamp()
    FROM public.sip_runtime_duration_recovery_claims claim
    WHERE claim.artifact_id=p_artifact_id
      AND claim.sample_original_path_id=source.id
      AND claim.status='claimed'
      AND source.claimed_by IS NULL AND source.claimed_at IS NULL;
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    IF v_updated<>v_expected_count THEN RAISE EXCEPTION 'runtime_duration_claim_state_drift'; END IF;
  END IF;

  RETURN QUERY
  SELECT claim.sample_original_path_id,claim.instrument_v2_id,
    claim.sample_path_construct_id,source.s3_path,source.file_name,
    sample->'expectedSourceObjectIdentity',sample->>'sourceIdentitySha256',
    artifact.content->>'processorRevision',claim.claim_token
  FROM public.sip_runtime_duration_recovery_claims claim
  JOIN public.samples_original_paths source ON source.id=claim.sample_original_path_id
  JOIN public.sip_fleet_plan_artifacts artifact ON artifact.id=claim.artifact_id
  JOIN LATERAL jsonb_array_elements(artifact.content->'samples') sample
    ON (sample->>'sampleOriginalPathId')::uuid=claim.sample_original_path_id
  WHERE claim.artifact_id=p_artifact_id AND claim.status='claimed'
  ORDER BY claim.sample_original_path_id;
END $$;


ALTER FUNCTION "public"."sip_runtime_duration_claim_v1"("p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_worker_id" "text", "p_claim_seconds" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_runtime_duration_recovery_receipts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "schema_version" "text" DEFAULT 'runtime-duration-recovery-receipt-v1'::"text" NOT NULL,
    "artifact_id" "uuid" NOT NULL,
    "rehearsal_id" "uuid" NOT NULL,
    "provider_slug" "text" NOT NULL,
    "sample_original_path_id" "uuid" NOT NULL,
    "instrument_v2_id" "uuid" NOT NULL,
    "sample_path_construct_id" "uuid" NOT NULL,
    "analysis_librosa_id" "uuid" NOT NULL,
    "source_s3_uri" "text" NOT NULL,
    "source_object_identity" "jsonb" NOT NULL,
    "source_identity_sha256" "text" NOT NULL,
    "processor_revision" "text" NOT NULL,
    "result_payload" "jsonb" NOT NULL,
    "result_sha256" "text" NOT NULL,
    "duration_seconds" double precision NOT NULL,
    "before_sample_state" "jsonb" NOT NULL,
    "lease_id" "uuid" NOT NULL,
    "applied_by" "text" NOT NULL,
    "authorizing_xid" "xid8" DEFAULT "pg_current_xact_id"() NOT NULL,
    "applied_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "sip_runtime_duration_recovery_rece_source_identity_sha256_check" CHECK (("source_identity_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_rece_source_object_identity_check" CHECK (("jsonb_typeof"("source_object_identity") = 'object'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_receipt_before_sample_state_check" CHECK (("jsonb_typeof"("before_sample_state") = 'object'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_receipts_applied_by_check" CHECK (("btrim"("applied_by") <> ''::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_receipts_duration_seconds_check" CHECK ((("duration_seconds" > (0)::double precision) AND ("duration_seconds" <= (2147483.647)::double precision))),
    CONSTRAINT "sip_runtime_duration_recovery_receipts_processor_revision_check" CHECK (("processor_revision" ~ '^[0-9a-f]{40}$'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_receipts_provider_slug_check" CHECK (("provider_slug" = 'sonuscore'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_receipts_result_payload_check" CHECK (("jsonb_typeof"("result_payload") = 'object'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_receipts_result_sha256_check" CHECK (("result_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_receipts_schema_version_check" CHECK (("schema_version" = 'runtime-duration-recovery-receipt-v1'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_receipts_source_s3_uri_check" CHECK (("btrim"("source_s3_uri") <> ''::"text"))
);


ALTER TABLE "public"."sip_runtime_duration_recovery_receipts" OWNER TO "postgres";


COMMENT ON TABLE "public"."sip_runtime_duration_recovery_receipts" IS 'Immutable, non-publication receipts for exact artifact-bound Librosa duration recovery.';



CREATE OR REPLACE FUNCTION "public"."sip_runtime_duration_complete_v1"("p_artifact_id" "uuid", "p_sample_original_path_id" "uuid", "p_claim_token" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_source_object_identity" "jsonb", "p_result_payload" "jsonb", "p_applied_by" "text") RETURNS "public"."sip_runtime_duration_recovery_receipts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_claim public.sip_runtime_duration_recovery_claims%ROWTYPE;
  v_artifact public.sip_fleet_plan_artifacts%ROWTYPE;
  v_sample jsonb;
  v_source public.samples_original_paths%ROWTYPE;
  v_analysis public.analysis_librosa%ROWTYPE;
  v_receipt public.sip_runtime_duration_recovery_receipts%ROWTYPE;
  v_result_hash text;
  v_duration double precision;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('sonuscore',0));
  IF jsonb_typeof(p_source_object_identity) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_result_payload) IS DISTINCT FROM 'object'
    OR nullif(btrim(p_applied_by),'') IS NULL
  THEN RAISE EXCEPTION 'runtime_duration_result_invalid'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug='sonuscore'
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>clock_timestamp() FOR UPDATE
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  SELECT * INTO STRICT v_claim FROM public.sip_runtime_duration_recovery_claims claim
  WHERE claim.artifact_id=p_artifact_id
    AND claim.sample_original_path_id=p_sample_original_path_id
    AND claim.claim_token=p_claim_token FOR UPDATE;
  SELECT * INTO STRICT v_artifact FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id=p_artifact_id FOR SHARE;
  SELECT sample INTO STRICT v_sample
  FROM jsonb_array_elements(v_artifact.content->'samples') sample
  WHERE (sample->>'sampleOriginalPathId')::uuid=p_sample_original_path_id;
  IF v_claim.status='completed' THEN
    SELECT * INTO STRICT v_receipt FROM public.sip_runtime_duration_recovery_receipts receipt
    WHERE receipt.artifact_id=p_artifact_id AND receipt.sample_original_path_id=p_sample_original_path_id;
    IF v_receipt.result_sha256<>encode(digest(convert_to(p_result_payload::text,'UTF8'),'sha256'),'hex')
      OR v_receipt.source_object_identity<>p_source_object_identity
    THEN RAISE EXCEPTION 'runtime_duration_result_replay_mismatch'; END IF;
    RETURN v_receipt;
  END IF;
  IF v_claim.status<>'claimed' OR v_claim.lease_id<>p_lease_id
    OR v_claim.claim_expires_at<=clock_timestamp()
    OR v_sample->'expectedSourceObjectIdentity'<>p_source_object_identity
  THEN RAISE EXCEPTION 'runtime_duration_claim_drift'; END IF;
  SELECT * INTO STRICT v_source FROM public.samples_original_paths source
  WHERE source.id=p_sample_original_path_id FOR UPDATE;
  IF v_source.s3_path<>v_sample->>'sourceS3Uri'
    OR v_source.librosa_analyzed IS NOT FALSE
    OR v_source.claimed_by<>'runtime-duration:'||p_artifact_id::text||':'||v_claim.worker_id
    OR EXISTS (SELECT 1 FROM public.analysis_librosa WHERE sample_id=p_sample_original_path_id)
  THEN RAISE EXCEPTION 'runtime_duration_source_drift'; END IF;
  v_duration := (p_result_payload->>'duration')::double precision;
  IF v_duration IS NULL OR v_duration::text IN ('NaN','Infinity','-Infinity')
    OR v_duration<=0 OR v_duration>2147483.647
    OR coalesce((p_result_payload->>'sampleRate')::integer,0)<=0
  THEN RAISE EXCEPTION 'runtime_duration_result_duration_invalid'; END IF;
  v_result_hash := encode(digest(convert_to(p_result_payload::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.analysis_librosa(
    sample_id,sample_rate,duration,spectral_contrast,hpss,tempo,raw_result,
    attack_time_ms,decay_time_ms,temporal_centroid_s,onset_sharpness,
    spectral_flux_mean,spectral_flux_std
  ) VALUES (
    p_sample_original_path_id,(p_result_payload->>'sampleRate')::integer,v_duration,
    p_result_payload->'spectralContrast',p_result_payload->'hpss',p_result_payload->'tempo',p_result_payload,
    (p_result_payload#>>'{envelope,attackTimeMs}')::real,
    (p_result_payload#>>'{envelope,decayTimeMs}')::real,
    (p_result_payload#>>'{envelope,temporalCentroidS}')::real,
    (p_result_payload#>>'{envelope,onsetSharpness}')::real,
    (p_result_payload#>>'{envelope,spectralFluxMean}')::real,
    (p_result_payload#>>'{envelope,spectralFluxStd}')::real
  ) RETURNING * INTO v_analysis;
  UPDATE public.samples_original_paths
  SET librosa_analyzed=true,claimed_by=NULL,claimed_at=NULL,error_message=NULL
  WHERE id=p_sample_original_path_id;
  INSERT INTO public.sip_runtime_duration_recovery_receipts(
    artifact_id,rehearsal_id,provider_slug,sample_original_path_id,
    instrument_v2_id,sample_path_construct_id,analysis_librosa_id,
    source_s3_uri,source_object_identity,source_identity_sha256,
    processor_revision,result_payload,result_sha256,duration_seconds,
    before_sample_state,lease_id,applied_by
  ) VALUES (
    p_artifact_id,(v_artifact.content->'approval'->>'rehearsalRunId')::uuid,'sonuscore',
    p_sample_original_path_id,v_claim.instrument_v2_id,v_claim.sample_path_construct_id,v_analysis.id,
    v_source.s3_path,p_source_object_identity,v_sample->>'sourceIdentitySha256',
    v_artifact.content->>'processorRevision',p_result_payload,v_result_hash,v_duration,
    v_claim.before_sample_state,
    p_lease_id,btrim(p_applied_by)
  ) RETURNING * INTO v_receipt;
  UPDATE public.sip_runtime_duration_recovery_claims
  SET status='completed',completed_at=clock_timestamp(),last_error=NULL
  WHERE artifact_id=p_artifact_id AND sample_original_path_id=p_sample_original_path_id;
  RETURN v_receipt;
END $$;


ALTER FUNCTION "public"."sip_runtime_duration_complete_v1"("p_artifact_id" "uuid", "p_sample_original_path_id" "uuid", "p_claim_token" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_source_object_identity" "jsonb", "p_result_payload" "jsonb", "p_applied_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_runtime_duration_fail_v1"("p_artifact_id" "uuid", "p_sample_original_path_id" "uuid", "p_claim_token" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_error" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_claim public.sip_runtime_duration_recovery_claims%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('sonuscore',0));
  IF nullif(btrim(p_error),'') IS NULL THEN RAISE EXCEPTION 'runtime_duration_error_required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug='sonuscore'
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>clock_timestamp() FOR UPDATE
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  SELECT * INTO STRICT v_claim FROM public.sip_runtime_duration_recovery_claims claim
  WHERE claim.artifact_id=p_artifact_id AND claim.sample_original_path_id=p_sample_original_path_id
    AND claim.claim_token=p_claim_token AND claim.status='claimed' FOR UPDATE;
  UPDATE public.samples_original_paths
  SET claimed_by=NULL,claimed_at=NULL,error_message=left(btrim(p_error),1000),retry_count=retry_count+1
  WHERE id=p_sample_original_path_id
    AND claimed_by='runtime-duration:'||p_artifact_id::text||':'||v_claim.worker_id;
  UPDATE public.sip_runtime_duration_recovery_claims
  SET status='failed',completed_at=clock_timestamp(),last_error=left(btrim(p_error),1000)
  WHERE artifact_id=p_artifact_id AND sample_original_path_id=p_sample_original_path_id;
  RETURN true;
END $$;


ALTER FUNCTION "public"."sip_runtime_duration_fail_v1"("p_artifact_id" "uuid", "p_sample_original_path_id" "uuid", "p_claim_token" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_error" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_runtime_duration_recovery_rehearsals" (
    "id" "uuid" NOT NULL,
    "artifact_id" "uuid" NOT NULL,
    "provider_slug" "text" NOT NULL,
    "content_hash" "text" NOT NULL,
    "expected_count" integer NOT NULL,
    "projection_hash" "text" NOT NULL,
    "object_identity_hash" "text",
    "passed" boolean,
    "result_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "lease_id" "uuid" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "completed_at" timestamp with time zone,
    CONSTRAINT "sip_runtime_duration_recovery_rehear_object_identity_hash_check" CHECK (("object_identity_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_rehearsals_check" CHECK (((("passed" IS NULL) AND ("completed_at" IS NULL) AND ("object_identity_hash" IS NULL)) OR (("passed" IS NOT NULL) AND ("completed_at" IS NOT NULL)))),
    CONSTRAINT "sip_runtime_duration_recovery_rehearsals_content_hash_check" CHECK (("content_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_rehearsals_expected_count_check" CHECK ((("expected_count" > 0) AND ("expected_count" <= 250))),
    CONSTRAINT "sip_runtime_duration_recovery_rehearsals_projection_hash_check" CHECK (("projection_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_rehearsals_provider_slug_check" CHECK (("provider_slug" = 'sonuscore'::"text")),
    CONSTRAINT "sip_runtime_duration_recovery_rehearsals_result_payload_check" CHECK (("jsonb_typeof"("result_payload") = 'object'::"text"))
);


ALTER TABLE "public"."sip_runtime_duration_recovery_rehearsals" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_runtime_duration_rehearsal_begin_v1"("p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS "public"."sip_runtime_duration_recovery_rehearsals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_scope jsonb;
  v_rehearsal public.sip_runtime_duration_recovery_rehearsals%ROWTYPE;
  v_rehearsal_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('sonuscore',0));
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug='sonuscore'
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>clock_timestamp() FOR UPDATE
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  v_scope := public.sip_runtime_duration_assert_scope_v1(p_artifact_id,true);
  SELECT (artifact.content->'approval'->>'rehearsalRunId')::uuid
  INTO v_rehearsal_id FROM public.sip_fleet_plan_artifacts artifact
  WHERE artifact.id=p_artifact_id;
  IF v_rehearsal_id IS NULL THEN RAISE EXCEPTION 'rehearsal_identity_missing'; END IF;
  INSERT INTO public.sip_runtime_duration_recovery_rehearsals(
    id,artifact_id,provider_slug,content_hash,expected_count,projection_hash,lease_id
  ) VALUES (
    v_rehearsal_id,p_artifact_id,'sonuscore',v_scope->>'contentHash',
    (v_scope->>'expectedCount')::integer,v_scope->>'projectionHash',p_lease_id
  ) ON CONFLICT (artifact_id) DO NOTHING RETURNING * INTO v_rehearsal;
  IF v_rehearsal.id IS NULL THEN
    SELECT * INTO STRICT v_rehearsal
    FROM public.sip_runtime_duration_recovery_rehearsals rehearsal
    WHERE rehearsal.artifact_id=p_artifact_id;
    IF v_rehearsal.passed IS NOT NULL THEN RAISE EXCEPTION 'rehearsal_already_completed'; END IF;
  END IF;
  RETURN v_rehearsal;
END $$;


ALTER FUNCTION "public"."sip_runtime_duration_rehearsal_begin_v1"("p_artifact_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_runtime_duration_rehearsal_complete_v1"("p_rehearsal_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_passed" boolean, "p_object_identity_hash" "text", "p_result_payload" "jsonb") RETURNS "public"."sip_runtime_duration_recovery_rehearsals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_existing public.sip_runtime_duration_recovery_rehearsals%ROWTYPE;
  v_scope jsonb;
  v_result public.sip_runtime_duration_recovery_rehearsals%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('sonuscore',0));
  SELECT * INTO STRICT v_existing
  FROM public.sip_runtime_duration_recovery_rehearsals rehearsal
  WHERE rehearsal.id=p_rehearsal_id FOR SHARE;
  IF v_existing.lease_id<>p_lease_id
    OR NOT EXISTS (
      SELECT 1 FROM public.sip_fleet_provider_leases lease
      WHERE lease.id=p_lease_id AND lease.provider_slug='sonuscore'
        AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
        AND lease.lease_expires_at>clock_timestamp() FOR UPDATE
    )
  THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  IF p_object_identity_hash !~ '^[0-9a-f]{64}$'
    OR jsonb_typeof(p_result_payload) IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'runtime_duration_rehearsal_result_invalid'; END IF;
  v_scope := public.sip_runtime_duration_assert_scope_v1(v_existing.artifact_id,true);
  IF v_scope->>'projectionHash' <> v_existing.projection_hash
  THEN RAISE EXCEPTION 'runtime_duration_rehearsal_projection_drift'; END IF;

  UPDATE public.sip_runtime_duration_recovery_rehearsals
  SET object_identity_hash=p_object_identity_hash,passed=p_passed,
      result_payload=p_result_payload,completed_at=clock_timestamp()
  WHERE id=p_rehearsal_id AND passed IS NULL
  RETURNING * INTO v_result;
  IF v_result.id IS NULL THEN RAISE EXCEPTION 'rehearsal_already_completed'; END IF;
  RETURN v_result;
END $_$;


ALTER FUNCTION "public"."sip_runtime_duration_rehearsal_complete_v1"("p_rehearsal_id" "uuid", "p_lease_id" "uuid", "p_lease_token" "uuid", "p_passed" boolean, "p_object_identity_hash" "text", "p_result_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_runtime_duration_rehearsal_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable_runtime_duration_rehearsal'; END IF;
  IF OLD.passed IS NULL AND NEW.id=OLD.id AND NEW.artifact_id=OLD.artifact_id
    AND NEW.provider_slug=OLD.provider_slug AND NEW.content_hash=OLD.content_hash
    AND NEW.expected_count=OLD.expected_count AND NEW.projection_hash=OLD.projection_hash
    AND NEW.lease_id=OLD.lease_id AND NEW.started_at=OLD.started_at
    AND NEW.passed IS NOT NULL AND NEW.completed_at IS NOT NULL
    AND NEW.object_identity_hash IS NOT NULL
  THEN RETURN NEW; END IF;
  IF NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'immutable_runtime_duration_rehearsal';
END $$;


ALTER FUNCTION "public"."sip_runtime_duration_rehearsal_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_runtime_duration_rollback_v1"("p_artifact_id" "uuid", "p_expected_count" integer, "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rolled_back_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_count integer; v_existing integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('sonuscore',0));
  IF p_expected_count<=0 OR nullif(btrim(p_rolled_back_by),'') IS NULL
  THEN RAISE EXCEPTION 'runtime_duration_rollback_identity_invalid'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sip_fleet_provider_leases lease
    WHERE lease.id=p_lease_id AND lease.provider_slug='sonuscore'
      AND lease.lease_token=p_lease_token AND lease.released_at IS NULL
      AND lease.lease_expires_at>clock_timestamp() FOR UPDATE
  ) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  SELECT count(*)::integer INTO v_count
  FROM public.sip_runtime_duration_recovery_receipts receipt
  WHERE receipt.artifact_id=p_artifact_id;
  SELECT count(*)::integer INTO v_existing
  FROM public.sip_runtime_duration_recovery_rollbacks rollback
  WHERE rollback.artifact_id=p_artifact_id;
  IF v_existing=p_expected_count THEN
    IF EXISTS (
      SELECT 1 FROM public.sip_runtime_duration_recovery_receipts receipt
      LEFT JOIN public.sip_runtime_duration_recovery_rollbacks rollback
        ON rollback.application_receipt_id=receipt.id
      JOIN public.samples_original_paths source ON source.id=receipt.sample_original_path_id
      LEFT JOIN public.analysis_librosa analysis ON analysis.id=receipt.analysis_librosa_id
      WHERE receipt.artifact_id=p_artifact_id
        AND (rollback.id IS NULL OR analysis.id IS NOT NULL OR source.librosa_analyzed IS NOT FALSE)
    ) THEN RAISE EXCEPTION 'runtime_duration_rollback_replay_drift'; END IF;
    RETURN jsonb_build_object('artifactId',p_artifact_id,'count',v_existing,'idempotent',true);
  END IF;
  IF v_existing<>0 OR v_count<>p_expected_count
  THEN RAISE EXCEPTION 'runtime_duration_rollback_receipt_count_mismatch'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.sip_runtime_duration_recovery_receipts receipt
    JOIN public.analysis_librosa analysis ON analysis.id=receipt.analysis_librosa_id
    JOIN public.samples_original_paths source ON source.id=receipt.sample_original_path_id
    WHERE receipt.artifact_id=p_artifact_id AND (
      encode(digest(convert_to(analysis.raw_result::text,'UTF8'),'sha256'),'hex')<>receipt.result_sha256
      OR source.librosa_analyzed IS NOT TRUE OR source.claimed_by IS NOT NULL OR source.claimed_at IS NOT NULL
    )
  ) THEN RAISE EXCEPTION 'runtime_duration_rollback_state_drift'; END IF;
  DELETE FROM public.analysis_librosa analysis
  USING public.sip_runtime_duration_recovery_receipts receipt
  WHERE receipt.artifact_id=p_artifact_id AND analysis.id=receipt.analysis_librosa_id;
  UPDATE public.samples_original_paths source
  SET librosa_analyzed=(receipt.before_sample_state->>'librosaAnalyzed')::boolean,
      claimed_by=receipt.before_sample_state->>'claimedBy',
      claimed_at=(receipt.before_sample_state->>'claimedAt')::timestamptz,
      error_message=receipt.before_sample_state->>'errorMessage',
      retry_count=(receipt.before_sample_state->>'retryCount')::integer
  FROM public.sip_runtime_duration_recovery_receipts receipt
  WHERE receipt.artifact_id=p_artifact_id AND source.id=receipt.sample_original_path_id;
  INSERT INTO public.sip_runtime_duration_recovery_rollbacks(
    application_receipt_id,artifact_id,sample_original_path_id,lease_id,
    rolled_back_by,rollback_state_sha256
  ) SELECT receipt.id,p_artifact_id,receipt.sample_original_path_id,p_lease_id,
    btrim(p_rolled_back_by),encode(digest(convert_to(jsonb_build_object(
      'sampleOriginalPathId',receipt.sample_original_path_id,
      'librosaAnalyzed',receipt.before_sample_state->'librosaAnalyzed',
      'analysisPresent',false
    )::text,'UTF8'),'sha256'),'hex')
  FROM public.sip_runtime_duration_recovery_receipts receipt
  WHERE receipt.artifact_id=p_artifact_id;
  UPDATE public.sip_runtime_duration_recovery_claims
  SET status='rolled_back'
  WHERE artifact_id=p_artifact_id AND status='completed';
  RETURN jsonb_build_object('artifactId',p_artifact_id,'count',p_expected_count,'idempotent',false);
END $$;


ALTER FUNCTION "public"."sip_runtime_duration_rollback_v1"("p_artifact_id" "uuid", "p_expected_count" integer, "p_lease_id" "uuid", "p_lease_token" "uuid", "p_rolled_back_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_sibling_consolidation_closeout_structural_snapshot_v2"("p_snapshot" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    public.sip_sibling_consolidation_structural_snapshot_v2(p_snapshot)
    || jsonb_build_object(
      'reviewPlaybackCues', COALESCE((
        SELECT jsonb_agg(
          value
            - 'analysis_payload'
            - 'analysis_run_id'
            - 'analyzed_at'
          ORDER BY value->>'id'
        )
        FROM jsonb_array_elements(
          public.sip_sibling_consolidation_structural_snapshot_v2(
            p_snapshot
          )->'reviewPlaybackCues'
        ) value
      ), '[]'::jsonb)
    );
$$;


ALTER FUNCTION "public"."sip_sibling_consolidation_closeout_structural_snapshot_v2"("p_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_sibling_consolidation_projection_hash_v2"("p_receipt_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT encode(
    extensions.digest(
      convert_to(
        COALESCE(
          jsonb_agg(
            jsonb_build_object(
              'sourceConstructId', projection.source_construct_id,
              'sampleOriginalPathId', projection.sample_original_path_id,
              'sourceInstrumentV2Id', projection.source_instrument_v2_id,
              'sourceSipReviewInstrumentId',
                projection.source_sip_review_instrument_id,
              'targetInstrumentV2Id', projection.target_instrument_v2_id,
              'targetSipReviewInstrumentId',
                projection.target_sip_review_instrument_id,
              'disposition', projection.disposition,
              'deferReason', projection.defer_reason,
              'pitchContent', projection.target_pitch_content,
              'midiNote', projection.target_midi_note,
              'filename', projection.target_filename,
              'velocity', projection.target_velocity,
              'roundRobin', projection.target_round_robin,
              'micPosition', projection.target_mic_position,
              'playbackType', projection.target_playback_type
            )
            ORDER BY projection.source_construct_id
          ),
          '[]'::jsonb
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  )
  FROM public.sip_sibling_consolidation_projection_v2 projection
  WHERE projection.receipt_id = p_receipt_id;
$$;


ALTER FUNCTION "public"."sip_sibling_consolidation_projection_hash_v2"("p_receipt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_sibling_consolidation_snapshot_receipt_v1"("p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH snapshot AS (
    SELECT public.sip_sibling_consolidation_snapshot_v1(p_manifest) AS value
  )
  SELECT jsonb_build_object(
    'snapshot', value,
    'snapshotHash', encode(
      extensions.digest(convert_to(value::text, 'UTF8'), 'sha256'),
      'hex'
    )
  )
  FROM snapshot;
$$;


ALTER FUNCTION "public"."sip_sibling_consolidation_snapshot_receipt_v1"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_sibling_consolidation_snapshot_receipt_v2"("p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH snapshot AS (
    SELECT public.sip_sibling_consolidation_snapshot_v2(p_manifest) AS value
  )
  SELECT jsonb_build_object(
    'snapshot', value,
