$$;


ALTER FUNCTION "public"."sip_sibling_consolidation_snapshot_receipt_v2"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_sibling_consolidation_snapshot_v1"("p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH identity AS (
    SELECT
      (p_manifest#>>'{canonicalTarget,instrumentV2Id}')::uuid AS target_v2_id,
      (p_manifest#>>'{canonicalTarget,stagingInstrumentId}')::uuid AS target_staging_id,
      COALESCE(ARRAY(
        SELECT (source->>'instrumentV2Id')::uuid
        FROM jsonb_array_elements(p_manifest->'sourceInstruments') source
        ORDER BY source->>'instrumentV2Id'
      ), ARRAY[]::uuid[]) AS source_v2_ids,
      COALESCE(ARRAY(
        SELECT (source->>'stagingInstrumentId')::uuid
        FROM jsonb_array_elements(p_manifest->'sourceInstruments') source
        ORDER BY source->>'stagingInstrumentId'
      ), ARRAY[]::uuid[]) AS source_staging_ids
  )
  SELECT jsonb_build_object(
    'target', jsonb_build_object(
      'production', (
        SELECT to_jsonb(row_data)
        FROM (
          SELECT i.id, i.name, i.contributor_id, i.engine_type, i.playback_type,
            i.polyphony_type, i.instrument_family, i.instrument_type, i.collection,
            i.range_lower, i.range_upper, i.single_pitch, i.file_path_reference,
            i.lookup_key, i.articulations, i.effects_instruments,
            i.legato_transition
          FROM public.instruments_v2 i, identity x
          WHERE i.id = x.target_v2_id
        ) row_data
      ),
      'staging', (
        SELECT to_jsonb(row_data)
        FROM (
          SELECT i.id, i.source_sip_instrument_id, i.source_contributor_slug,
            i.source_group_key, i.name, i.contributor_id, i.is_retired,
            i.articulations, i.effects_instruments, i.legato_transition, i.updated_at
          FROM public.sip_review_instrument i, identity x
          WHERE i.id = x.target_staging_id
        ) row_data
      ),
      'constructs', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', c.id,
          'sampleOriginalPathId', c.sample_original_path_id,
          'instrumentV2Id', c.instrument_v2_id,
          'contributorId', c.contributor_id,
          'collection', c.collection,
          'instrumentName', c.instrument_name,
          'articulation', c.articulation,
          'effect', c.effect,
          'pitchContent', c.pitch_content,
          'midiNote', c.midi_note,
          'filename', c.filename,
          'velocity', c.velocity,
          'roundRobin', c.round_robin,
          'micPosition', c.mic_position,
          'playbackType', c.playback_type
        ) ORDER BY c.id)
        FROM public.sample_path_constructs c, identity x
        WHERE c.instrument_v2_id = x.target_v2_id
      ), '[]'::jsonb)
    ),
    'sources', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'production', jsonb_build_object(
          'id', v2.id,
          'name', v2.name,
          'contributorId', v2.contributor_id,
          'published', v2.published,
          'articulations', v2.articulations,
          'effectsInstruments', v2.effects_instruments,
          'legatoTransition', v2.legato_transition,
          'updatedAt', v2.updated_at
        ),
        'staging', jsonb_build_object(
          'id', staging.id,
          'sourceSipInstrumentId', staging.source_sip_instrument_id,
          'sourceContributorSlug', staging.source_contributor_slug,
          'sourceGroupKey', staging.source_group_key,
          'name', staging.name,
          'contributorId', staging.contributor_id,
          'isRetired', staging.is_retired,
          'articulations', staging.articulations,
          'effectsInstruments', staging.effects_instruments,
          'legatoTransition', staging.legato_transition,
          'updatedAt', staging.updated_at
        ),
        'constructs', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', c.id,
            'sampleOriginalPathId', c.sample_original_path_id,
            'instrumentV2Id', c.instrument_v2_id,
            'contributorId', c.contributor_id,
            'collection', c.collection,
            'instrumentName', c.instrument_name,
            'articulation', c.articulation,
            'effect', c.effect,
            'pitchContent', c.pitch_content,
            'midiNote', c.midi_note,
            'filename', c.filename,
            'velocity', c.velocity,
            'roundRobin', c.round_robin,
            'micPosition', c.mic_position,
            'playbackType', c.playback_type
          ) ORDER BY c.id)
          FROM public.sample_path_constructs c
          WHERE c.instrument_v2_id = v2.id
        ), '[]'::jsonb)
      ) ORDER BY v2.id)
      FROM identity x
      JOIN public.instruments_v2 v2 ON v2.id = ANY(x.source_v2_ids)
      JOIN public.sip_review_promotion_map promotion ON promotion.instrument_v2_id = v2.id
      JOIN public.sip_review_instrument staging
        ON staging.id = promotion.sip_review_instrument_id
       AND staging.id = ANY(x.source_staging_ids)
    ), '[]'::jsonb),
    'inboundProductionRelationships', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', i.id,
        'articulations', i.articulations,
        'effectsInstruments', i.effects_instruments,
        'legatoTransition', i.legato_transition
      ) ORDER BY i.id)
      FROM public.instruments_v2 i, identity x
      WHERE COALESCE(i.articulations, ARRAY[]::uuid[]) && x.source_v2_ids
         OR COALESCE(i.effects_instruments, ARRAY[]::uuid[]) && x.source_v2_ids
         OR i.legato_transition = ANY(x.source_v2_ids)
    ), '[]'::jsonb),
    'inboundStagingRelationships', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', i.id,
        'articulations', i.articulations,
        'effectsInstruments', i.effects_instruments,
        'legatoTransition', i.legato_transition
      ) ORDER BY i.id)
      FROM public.sip_review_instrument i, identity x
      WHERE COALESCE(i.articulations, ARRAY[]::uuid[]) && ARRAY(
              SELECT source.source_sip_instrument_id
              FROM public.sip_review_instrument source
              WHERE source.id = ANY(x.source_staging_ids)
            )
         OR COALESCE(i.effects_instruments, ARRAY[]::uuid[]) && ARRAY(
              SELECT source.source_sip_instrument_id
              FROM public.sip_review_instrument source
              WHERE source.id = ANY(x.source_staging_ids)
            )
         OR i.legato_transition = ANY(x.source_staging_ids)
    ), '[]'::jsonb),
    'legacyAliases', COALESCE((
      SELECT jsonb_agg(to_jsonb(alias_row) ORDER BY alias_row.id)
      FROM (
        SELECT alias.id, alias.instrument_v2_id, alias.legacy_instrument_id,
          alias.sip_review_instrument_id, alias.contributor_slug,
          alias.legacy_lookup_key, alias.legacy_velocity,
          alias.is_primary_for_legacy, alias.is_primary_for_v2
        FROM public.instrument_v2_legacy_map alias, identity x
        WHERE alias.instrument_v2_id = ANY(x.source_v2_ids)
           OR alias.instrument_v2_id = x.target_v2_id
      ) alias_row
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."sip_sibling_consolidation_snapshot_v1"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_sibling_consolidation_snapshot_v2"("p_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH identity AS (
    SELECT
      (p_manifest#>>'{canonicalTarget,instrumentV2Id}')::uuid AS target_v2_id,
      (p_manifest#>>'{canonicalTarget,stagingInstrumentId}')::uuid AS target_staging_id,
      COALESCE(ARRAY(
        SELECT (source->>'instrumentV2Id')::uuid
        FROM jsonb_array_elements(p_manifest->'sourceInstruments') source
        ORDER BY source->>'instrumentV2Id'
      ), ARRAY[]::uuid[]) AS source_v2_ids,
      COALESCE(ARRAY(
        SELECT (source->>'stagingInstrumentId')::uuid
        FROM jsonb_array_elements(p_manifest->'sourceInstruments') source
        ORDER BY source->>'stagingInstrumentId'
      ), ARRAY[]::uuid[]) AS source_staging_ids,
      COALESCE(ARRAY(
        SELECT construct_id
        FROM (
          SELECT (sample->>'sourceConstructId')::uuid AS construct_id
          FROM jsonb_array_elements(p_manifest->'activeSamples') sample
          UNION ALL
          SELECT (sample->>'targetConstructId')::uuid AS construct_id
          FROM jsonb_array_elements(p_manifest->'activeSamples') sample
          WHERE NULLIF(sample->>'targetConstructId', '') IS NOT NULL
          UNION ALL
          SELECT (sample->>'sourceConstructId')::uuid AS construct_id
          FROM jsonb_array_elements(p_manifest->'deferredSamples') sample
        ) partition_rows
        ORDER BY construct_id
      ), ARRAY[]::uuid[]) AS partition_construct_ids
      ,
      COALESCE(ARRAY(
        SELECT (sample->>'sourceConstructId')::uuid
        FROM (
          SELECT value AS sample FROM jsonb_array_elements(p_manifest->'activeSamples')
          UNION ALL
          SELECT value AS sample FROM jsonb_array_elements(p_manifest->'deferredSamples')
        ) source_rows
        ORDER BY sample->>'sourceConstructId'
      ), ARRAY[]::uuid[]) AS source_construct_ids
  ),
  all_staging_ids AS (
    SELECT target_staging_id AS id FROM identity
    UNION
    SELECT unnest(source_staging_ids) FROM identity
  ),
  all_v2_ids AS (
    SELECT target_v2_id AS id FROM identity
    UNION
    SELECT unnest(source_v2_ids) FROM identity
  )
  SELECT jsonb_build_object(
    'instruments', COALESCE((
      SELECT jsonb_agg(to_jsonb(instrument_row) ORDER BY instrument_row.id)
      FROM (
        SELECT instrument.*
        FROM public.instruments_v2 instrument
        JOIN all_v2_ids requested ON requested.id = instrument.id
      ) instrument_row
    ), '[]'::jsonb),
    'reviewInstruments', COALESCE((
      SELECT jsonb_agg(to_jsonb(review_row) ORDER BY review_row.id)
      FROM (
        SELECT review.*
        FROM public.sip_review_instrument review
        JOIN all_staging_ids requested ON requested.id = review.id
      ) review_row
    ), '[]'::jsonb),
    'constructs', COALESCE((
      SELECT jsonb_agg(to_jsonb(construct_row) ORDER BY construct_row.id)
      FROM (
        SELECT construct.*
        FROM public.sample_path_constructs construct, identity requested
        WHERE construct.id = ANY(requested.partition_construct_ids)
          AND (
            construct.id = ANY(requested.source_construct_ids)
            OR construct.instrument_v2_id = requested.target_v2_id
          )
      ) construct_row
    ), '[]'::jsonb),
    'reviewScopes', COALESCE((
      SELECT jsonb_agg(to_jsonb(scope_row) ORDER BY scope_row.sip_review_instrument_id, scope_row.original_sample_id, scope_row.id)
      FROM (
        SELECT scope.*
        FROM public.sip_review_instrument_sample_scope scope
        JOIN all_staging_ids requested ON requested.id = scope.sip_review_instrument_id
      ) scope_row
    ), '[]'::jsonb),
    'reviewOverrides', COALESCE((
      SELECT jsonb_agg(to_jsonb(override_row) ORDER BY override_row.sip_review_instrument_id, override_row.original_sample_id, override_row.id)
      FROM (
        SELECT override_value.*
        FROM public.sip_review_sample_override override_value
        JOIN all_staging_ids requested ON requested.id = override_value.sip_review_instrument_id
      ) override_row
    ), '[]'::jsonb),
    'reviewDispositions', COALESCE((
      SELECT jsonb_agg(to_jsonb(disposition_row) ORDER BY disposition_row.sip_review_instrument_id, disposition_row.original_sample_id, disposition_row.id)
      FROM (
        SELECT disposition.*
        FROM public.sip_review_sample_disposition disposition
        JOIN all_staging_ids requested ON requested.id = disposition.sip_review_instrument_id
      ) disposition_row
    ), '[]'::jsonb),
    'reviewPlaybackCues', COALESCE((
      SELECT jsonb_agg(to_jsonb(cue_row) ORDER BY cue_row.sip_review_instrument_id, cue_row.original_sample_id, cue_row.id)
      FROM (
        SELECT cue.*
        FROM public.sip_review_sample_playback_cues cue
        JOIN all_staging_ids requested ON requested.id = cue.sip_review_instrument_id
      ) cue_row
    ), '[]'::jsonb),
    'productionPlaybackCues', COALESCE((
      SELECT jsonb_agg(to_jsonb(cue_row) ORDER BY cue_row.sample_path_construct_id)
      FROM (
        SELECT cue.*
        FROM public.sample_playback_cues cue
        JOIN public.sample_path_constructs construct
          ON construct.id = cue.sample_path_construct_id
        CROSS JOIN identity requested
        WHERE cue.sample_path_construct_id = ANY(requested.partition_construct_ids)
          AND (
            construct.id = ANY(requested.source_construct_ids)
            OR construct.instrument_v2_id = requested.target_v2_id
          )
      ) cue_row
    ), '[]'::jsonb),
    'inboundProductionRelationships', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', relation.id,
        'articulations', relation.articulations,
        'effectsInstruments', relation.effects_instruments,
        'legatoTransition', relation.legato_transition
      ) ORDER BY relation.id)
      FROM public.instruments_v2 relation, identity requested
      WHERE COALESCE(relation.articulations, ARRAY[]::uuid[]) && requested.source_v2_ids
         OR COALESCE(relation.effects_instruments, ARRAY[]::uuid[]) && requested.source_v2_ids
         OR relation.legato_transition = ANY(requested.source_v2_ids)
    ), '[]'::jsonb),
    'inboundReviewRelationships', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', relation.id,
        'articulations', relation.articulations,
        'effectsInstruments', relation.effects_instruments,
        'legatoTransition', relation.legato_transition
      ) ORDER BY relation.id)
      FROM public.sip_review_instrument relation, identity requested
      WHERE COALESCE(relation.articulations, ARRAY[]::uuid[]) && ARRAY(
              SELECT source.source_sip_instrument_id
              FROM public.sip_review_instrument source
              WHERE source.id = ANY(requested.source_staging_ids)
            )
         OR COALESCE(relation.effects_instruments, ARRAY[]::uuid[]) && ARRAY(
              SELECT source.source_sip_instrument_id
              FROM public.sip_review_instrument source
              WHERE source.id = ANY(requested.source_staging_ids)
            )
         OR relation.legato_transition = ANY(requested.source_staging_ids)
    ), '[]'::jsonb),
    'legacyAliases', COALESCE((
      SELECT jsonb_agg(to_jsonb(alias_row) ORDER BY alias_row.id)
      FROM (
        SELECT alias.*
        FROM public.instrument_v2_legacy_map alias, identity requested
        WHERE alias.instrument_v2_id = requested.target_v2_id
           OR alias.instrument_v2_id = ANY(requested.source_v2_ids)
      ) alias_row
    ), '[]'::jsonb),
    'reviewAliases', COALESCE((
      SELECT jsonb_agg(to_jsonb(alias_row) ORDER BY alias_row.id)
      FROM (
        SELECT alias.*
        FROM public.sip_review_legacy_map alias, identity requested
        WHERE alias.sip_review_instrument_id = requested.target_staging_id
           OR alias.sip_review_instrument_id = ANY(requested.source_staging_ids)
      ) alias_row
    ), '[]'::jsonb),
    'publishRunEvidence', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'run', to_jsonb(run),
        'items', (
          SELECT jsonb_agg(to_jsonb(item) ORDER BY item.id)
          FROM public.sip_fleet_run_items item
          WHERE item.run_id = run.id
        )
      ) ORDER BY run.created_at, run.id)
      FROM public.sip_fleet_runs run, identity requested
      WHERE EXISTS (
        SELECT 1
        FROM public.sip_fleet_run_items item
        WHERE item.run_id = run.id
          AND item.instrument_v2_id = requested.target_v2_id
      )
    ), '[]'::jsonb),
    'runtimeEvidence', (
      SELECT to_jsonb(upload)
      FROM public.instrument_v2_upload_status upload, identity requested
      WHERE upload.instrument_v2_id = requested.target_v2_id
    ),
    'audioProfileEvidence', jsonb_build_object(
      'profiles', COALESCE((
        SELECT jsonb_agg(to_jsonb(profile) ORDER BY profile.profile_version)
        FROM public.instrument_audio_profile_v1 profile, identity requested
        WHERE profile.instrument_v2_id = requested.target_v2_id
      ), '[]'::jsonb),
      'jobs', COALESCE((
        SELECT jsonb_agg(to_jsonb(job) ORDER BY job.created_at, job.id)
        FROM public.instrument_audio_profile_jobs_v1 job, identity requested
        WHERE job.instrument_v2_id = requested.target_v2_id
      ), '[]'::jsonb)
    )
  );
$$;


ALTER FUNCTION "public"."sip_sibling_consolidation_snapshot_v2"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_sibling_consolidation_structural_snapshot_v2"("p_snapshot" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    (p_snapshot - 'publishRunEvidence' - 'runtimeEvidence' - 'audioProfileEvidence')
    || jsonb_build_object(
      'instruments', COALESCE((
        SELECT jsonb_agg(value - 'created_at' - 'updated_at' ORDER BY value->>'id')
        FROM jsonb_array_elements(p_snapshot->'instruments') value
      ), '[]'::jsonb),
      'reviewInstruments', COALESCE((
        SELECT jsonb_agg(value - 'created_at' - 'updated_at' ORDER BY value->>'id')
        FROM jsonb_array_elements(p_snapshot->'reviewInstruments') value
      ), '[]'::jsonb),
      'reviewScopes', COALESCE((
        SELECT jsonb_agg(value - 'created_at' - 'updated_at' ORDER BY value->>'id')
        FROM jsonb_array_elements(p_snapshot->'reviewScopes') value
      ), '[]'::jsonb),
      'reviewOverrides', COALESCE((
        SELECT jsonb_agg(value - 'created_at' - 'updated_at' ORDER BY value->>'id')
        FROM jsonb_array_elements(p_snapshot->'reviewOverrides') value
      ), '[]'::jsonb),
      'reviewDispositions', COALESCE((
        SELECT jsonb_agg(value - 'created_at' - 'updated_at' ORDER BY value->>'id')
        FROM jsonb_array_elements(p_snapshot->'reviewDispositions') value
      ), '[]'::jsonb),
      'reviewPlaybackCues', COALESCE((
        SELECT jsonb_agg(value - 'created_at' - 'updated_at' ORDER BY value->>'id')
        FROM jsonb_array_elements(p_snapshot->'reviewPlaybackCues') value
      ), '[]'::jsonb),
      'productionPlaybackCues', COALESCE((
        SELECT jsonb_agg(
          value - 'created_at' - 'updated_at'
          ORDER BY value->>'sample_path_construct_id'
        )
        FROM jsonb_array_elements(p_snapshot->'productionPlaybackCues') value
      ), '[]'::jsonb),
      'legacyAliases', COALESCE((
        SELECT jsonb_agg(value - 'created_at' - 'updated_at' ORDER BY value->>'id')
        FROM jsonb_array_elements(p_snapshot->'legacyAliases') value
      ), '[]'::jsonb),
      'reviewAliases', COALESCE((
        SELECT jsonb_agg(value - 'created_at' - 'updated_at' ORDER BY value->>'id')
        FROM jsonb_array_elements(p_snapshot->'reviewAliases') value
      ), '[]'::jsonb)
    );
$$;


ALTER FUNCTION "public"."sip_sibling_consolidation_structural_snapshot_v2"("p_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_staged_promotion_plan_is_structurally_valid_v1"("p_plan" "jsonb", "p_contributor_slug" "text", "p_lease_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_expected jsonb;
BEGIN
  IF jsonb_typeof(COALESCE(p_plan, 'null'::jsonb)) <> 'object'
     OR p_plan->>'schemaVersion' IS DISTINCT FROM '1'
     OR p_plan->>'contributorSlug' IS DISTINCT FROM p_contributor_slug
     OR COALESCE(p_plan->>'canonicalContributorId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR COALESCE(p_plan->>'sourceContributorSlug', '') !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
     OR p_plan->>'coordinatorLeaseId' IS DISTINCT FROM p_lease_id::text
     OR jsonb_typeof(COALESCE(p_plan->'expectedState', 'null'::jsonb)) <> 'object'
     OR EXISTS (
       SELECT 1
       FROM unnest(ARRAY[
         'sourceLegatoTransitionParentIdsToClear', 'sourceInstrumentPatches',
         'externalV2LegatoParentIdsToClear',
         'externalV2LegatoChildIdsLeavingTransition', 'instrumentRows', 'promotionLinks',
         'sampleConstructRows', 'legacyAliasRows', 'sipTagRows', 'v2TagRows',
         'uploadRows', 'metadataRows', 'samplePlaybackCueRows',
         'uploadStatusRows', 'deterministicReadinessRows',
         'replaceInstrumentV2Ids', 'replaceInPlaceRows'
       ]) required_key
       WHERE jsonb_typeof(COALESCE(p_plan->required_key, 'null'::jsonb)) <> 'array'
     ) THEN
    RETURN false;
  END IF;

  v_expected := p_plan->'expectedState';

  -- The lease/provider identity owns every selected staging and destination
  -- row. Historical source identity is a separate, exact, nonempty value that
  -- must agree across the complete selected staging cohort.
  IF jsonb_array_length(v_expected->'stagingRows') = 0
     OR jsonb_array_length(p_plan->'instrumentRows') = 0
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
       WHERE COALESCE(row_json->>'id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          OR COALESCE(row_json->>'source_sip_instrument_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          OR row_json->>'contributor_id' IS DISTINCT FROM p_plan->>'canonicalContributorId'
          OR row_json->>'source_contributor_slug' IS DISTINCT FROM p_plan->>'sourceContributorSlug'
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_plan->'instrumentRows') item(row_json)
       WHERE row_json->>'contributor_id' IS DISTINCT FROM p_plan->>'canonicalContributorId'
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_plan->'sourceInstrumentPatches') item(row_json)
       WHERE row_json->'patch'->>'contributor_id' IS DISTINCT FROM p_plan->>'canonicalContributorId'
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_plan->'metadataRows') item(row_json)
       WHERE row_json->>'source_contributor_slug' IS DISTINCT FROM p_plan->>'sourceContributorSlug'
     )
     OR EXISTS (
       (SELECT DISTINCT row_json->>'source_sip_instrument_id' AS id
        FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
        EXCEPT
        SELECT DISTINCT row_json->>'id'
        FROM jsonb_array_elements(v_expected->'sourceInstrumentRows') item(row_json))
       UNION ALL
       (SELECT DISTINCT row_json->>'id'
        FROM jsonb_array_elements(v_expected->'sourceInstrumentRows') item(row_json)
        EXCEPT
        SELECT DISTINCT row_json->>'source_sip_instrument_id'
        FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json))
     ) THEN
    RETURN false;
  END IF;

  IF EXISTS (
       SELECT 1
       FROM unnest(ARRAY[
         'stagingRows', 'sourceInstrumentRows', 'sourceRelationshipRows',
         'promotionMap', 'relationshipResolutionSourceIds',
         'relationshipResolutionStagingRows',
         'relationshipResolutionPromotionMapRows',
         'relationshipValidationSourceIds', 'relationshipValidationRows',
         'constructInstrumentV2Ids', 'constructRows',
         'targetInstrumentV2Rows', 'uploadStatus', 'externalV2Relationships',
         'sampleScopeRows', 'sampleDispositionRows',
         'baseSampleConstructRows', 'sampleOverrideRows', 'reviewTagRows',
         'legacyMapRows', 'existingLegacyAliasRows',
         'reviewPlaybackCueRows', 'sampleOriginalPathRows'
         , 'replaceInPlaceTargetRows', 'replaceInPlaceRelationshipRows',
         'replaceInPlaceConstructRows'
       ]) required_key
       WHERE jsonb_typeof(COALESCE(v_expected->required_key, 'null'::jsonb)) <> 'array'
     )
     OR EXISTS (
       SELECT 1
       FROM unnest(ARRAY[
         'sourceInstrumentPatches', 'instrumentRows', 'promotionLinks',
         'sampleConstructRows', 'legacyAliasRows', 'sipTagRows', 'v2TagRows',
         'uploadRows', 'metadataRows', 'samplePlaybackCueRows',
         'uploadStatusRows', 'deterministicReadinessRows', 'replaceInPlaceRows'
       ]) object_array_key,
       LATERAL jsonb_array_elements(p_plan->object_array_key) item(value)
       WHERE jsonb_typeof(item.value) <> 'object'
     )
     OR EXISTS (
       SELECT 1
       FROM unnest(ARRAY[
         'stagingRows', 'sourceInstrumentRows', 'sourceRelationshipRows',
         'promotionMap', 'relationshipResolutionStagingRows',
         'relationshipResolutionPromotionMapRows',
         'relationshipValidationRows',
         'constructRows', 'targetInstrumentV2Rows',
         'uploadStatus', 'externalV2Relationships', 'replaceInPlaceTargetRows',
         'replaceInPlaceRelationshipRows', 'replaceInPlaceConstructRows',
         'sampleScopeRows', 'sampleDispositionRows',
         'baseSampleConstructRows', 'sampleOverrideRows', 'reviewTagRows',
         'legacyMapRows', 'existingLegacyAliasRows',
         'reviewPlaybackCueRows', 'sampleOriginalPathRows'
       ]) object_array_key,
       LATERAL jsonb_array_elements(v_expected->object_array_key) item(value)
       WHERE jsonb_typeof(item.value) <> 'object'
     ) THEN
    RETURN false;
  END IF;

  -- Every identifier that is cast or used as a mutation target must be a UUID.
  IF EXISTS (
       SELECT value
       FROM jsonb_array_elements_text(p_plan->'sourceLegatoTransitionParentIdsToClear') item(value)
       WHERE value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     )
     OR EXISTS (
       SELECT value
       FROM jsonb_array_elements_text(p_plan->'externalV2LegatoParentIdsToClear') item(value)
       WHERE value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-58][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     )
     OR EXISTS (
       SELECT value
       FROM jsonb_array_elements_text(p_plan->'externalV2LegatoChildIdsLeavingTransition') item(value)
       WHERE value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-58][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     )
     OR EXISTS (
       SELECT value
       FROM jsonb_array_elements_text(p_plan->'replaceInstrumentV2Ids') item(value)
       WHERE value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-58][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     )
     OR EXISTS (
       SELECT row_json
       FROM jsonb_array_elements(p_plan->'sourceInstrumentPatches') item(row_json)
       WHERE COALESCE(row_json->>'sourceInstrumentId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          OR jsonb_typeof(COALESCE(row_json->'patch', 'null'::jsonb)) <> 'object'
     )
     OR EXISTS (
       SELECT row_json
       FROM jsonb_array_elements(p_plan->'instrumentRows') item(row_json)
       WHERE COALESCE(row_json->>'id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-58][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     )
     OR EXISTS (
       SELECT row_json
       FROM jsonb_array_elements(p_plan->'promotionLinks') item(row_json)
       WHERE COALESCE(row_json->>'sip_review_instrument_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          OR COALESCE(row_json->>'instrument_v2_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-58][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     ) THEN
    RETURN false;
  END IF;

  -- Mutation targets must be exactly the rows represented by the locked
  -- expected-state sets. This prevents a valid hash from authorizing unrelated
  -- IDs hidden in a different mutation-plan field.
  IF EXISTS (
       (SELECT DISTINCT row_json->>'sourceInstrumentId' AS id FROM jsonb_array_elements(p_plan->'sourceInstrumentPatches') item(row_json)
        EXCEPT SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(v_expected->'sourceInstrumentRows') item(row_json))
       UNION ALL
       (SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(v_expected->'sourceInstrumentRows') item(row_json)
        EXCEPT SELECT DISTINCT row_json->>'sourceInstrumentId' FROM jsonb_array_elements(p_plan->'sourceInstrumentPatches') item(row_json))
     )
     OR EXISTS (
       (SELECT DISTINCT row_json->>'sip_review_instrument_id' AS id FROM jsonb_array_elements(p_plan->'promotionLinks') item(row_json)
        EXCEPT SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json))
       UNION ALL
       (SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(v_expected->'stagingRows') item(row_json)
        EXCEPT SELECT DISTINCT row_json->>'sip_review_instrument_id' FROM jsonb_array_elements(p_plan->'promotionLinks') item(row_json))
     )
     OR EXISTS (
       (SELECT DISTINCT row_json->>'instrument_v2_id' AS id FROM jsonb_array_elements(p_plan->'promotionLinks') item(row_json)
        EXCEPT SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(p_plan->'instrumentRows') item(row_json))
       UNION ALL
       (SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(p_plan->'instrumentRows') item(row_json)
        EXCEPT SELECT DISTINCT row_json->>'instrument_v2_id' FROM jsonb_array_elements(p_plan->'promotionLinks') item(row_json))
     )
     OR EXISTS (
       (SELECT DISTINCT value AS id FROM jsonb_array_elements_text(v_expected->'constructInstrumentV2Ids') item(value)
        EXCEPT SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(p_plan->'instrumentRows') item(row_json))
       UNION ALL
       (SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(p_plan->'instrumentRows') item(row_json)
        EXCEPT SELECT DISTINCT value FROM jsonb_array_elements_text(v_expected->'constructInstrumentV2Ids') item(value))
     )
     OR EXISTS (
       (SELECT DISTINCT row_json->>'instrumentV2Id' AS id FROM jsonb_array_elements(v_expected->'targetInstrumentV2Rows') item(row_json)
        EXCEPT SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(p_plan->'instrumentRows') item(row_json))
       UNION ALL
       (SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(p_plan->'instrumentRows') item(row_json)
        EXCEPT SELECT DISTINCT row_json->>'instrumentV2Id' FROM jsonb_array_elements(v_expected->'targetInstrumentV2Rows') item(row_json))
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_plan->'promotionLinks') link(row_json)
       LEFT JOIN jsonb_array_elements(v_expected->'promotionMap') expected(row_json)
         ON expected.row_json->>'stagingId' = link.row_json->>'sip_review_instrument_id'
       WHERE expected.row_json IS NULL
          OR (
            expected.row_json->>'instrumentV2Id' IS NOT NULL
            AND expected.row_json->>'instrumentV2Id' IS DISTINCT FROM link.row_json->>'instrument_v2_id'
          )
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_plan->'uploadStatusRows') item(row_json)
       WHERE NOT EXISTS (
         SELECT 1 FROM jsonb_array_elements(p_plan->'instrumentRows') instrument(row_json)
         WHERE instrument.row_json->>'id' = item.row_json->>'instrument_v2_id'
       )
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_plan->'deterministicReadinessRows') item(row_json)
       WHERE COALESCE(row_json->>'instrument_v2_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-58][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          OR COALESCE(row_json->>'snapshot_sha256', '') !~ '^[0-9a-f]{64}$'
          OR row_json->'snapshot'->>'instrumentV2Id' IS DISTINCT FROM row_json->>'instrument_v2_id'
          OR NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(p_plan->'instrumentRows') instrument(row_json)
            WHERE instrument.row_json->>'id' = item.row_json->>'instrument_v2_id'
          )
     )
     OR EXISTS (
       (SELECT DISTINCT value AS id FROM jsonb_array_elements_text(p_plan->'externalV2LegatoParentIdsToClear') item(value)
        EXCEPT SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(v_expected->'externalV2Relationships') item(row_json))
       UNION ALL
       (SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(v_expected->'externalV2Relationships') item(row_json)
        EXCEPT SELECT DISTINCT value FROM jsonb_array_elements_text(p_plan->'externalV2LegatoParentIdsToClear') item(value))
     )
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(p_plan->'replaceInPlaceRows') item(row_json)
       WHERE COALESCE(row_json->>'retiring_instrument_v2_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          OR COALESCE(row_json->>'canonical_instrument_v2_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-58][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          OR NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(p_plan->'instrumentRows') instrument(row_json)
            WHERE instrument.row_json->>'id' = item.row_json->>'canonical_instrument_v2_id'
          )
     )
     OR EXISTS (
       (SELECT DISTINCT row_json->>'retiring_instrument_v2_id' AS id FROM jsonb_array_elements(p_plan->'replaceInPlaceRows') item(row_json)
        EXCEPT SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(v_expected->'replaceInPlaceTargetRows') item(row_json))
       UNION ALL
       (SELECT DISTINCT row_json->>'id' FROM jsonb_array_elements(v_expected->'replaceInPlaceTargetRows') item(row_json)
        EXCEPT SELECT DISTINCT row_json->>'retiring_instrument_v2_id' FROM jsonb_array_elements(p_plan->'replaceInPlaceRows') item(row_json))
     ) THEN
    RETURN false;
  END IF;

  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END
$_$;


ALTER FUNCTION "public"."sip_staged_promotion_plan_is_structurally_valid_v1"("p_plan" "jsonb", "p_contributor_slug" "text", "p_lease_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_supersede_completion_projection_registry_v1"("p_registry_id" "uuid") RETURNS "public"."sip_completion_projection_registry"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_registry public.sip_completion_projection_registry%ROWTYPE;
BEGIN
  UPDATE public.sip_completion_projection_registry
  SET
    status = 'superseded',
    superseded_at = now()
  WHERE id = p_registry_id
    AND status = 'frozen'
  RETURNING * INTO STRICT v_registry;

  RETURN v_registry;
END;
$$;


ALTER FUNCTION "public"."sip_supersede_completion_projection_registry_v1"("p_registry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_sync_instruments_v2_lookup_key_for_alias"("target_instrument_v2_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  resolved_lookup_key text;
  has_any_alias boolean;
BEGIN
  IF target_instrument_v2_id IS NULL THEN
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM "public"."instrument_v2_legacy_map"
    WHERE "instrument_v2_id" = target_instrument_v2_id
  ) INTO has_any_alias;

  -- If no alias rows exist for this v2 (pure-v2 row), leave lookup_key alone.
  -- Clobbering it to id::text would silently destroy any meaningful
  -- pre-existing key that callers (e.g. convertInstrumentV2Row) read.
  IF NOT has_any_alias THEN
    RETURN;
  END IF;

  SELECT "legacy_lookup_key"
  INTO resolved_lookup_key
  FROM "public"."instrument_v2_legacy_map"
  WHERE "instrument_v2_id" = target_instrument_v2_id
    AND "is_primary_for_v2" = true
  ORDER BY "updated_at" DESC, "created_at" DESC, "id" ASC
  LIMIT 1;

  UPDATE "public"."instruments_v2"
  SET "lookup_key" = COALESCE(resolved_lookup_key, target_instrument_v2_id::text)
  WHERE "id" = target_instrument_v2_id;
END;
$$;


ALTER FUNCTION "public"."sip_sync_instruments_v2_lookup_key_for_alias"("target_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_validate_gospel_talkbox_grid_manifest_v1"("p_manifest" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  WITH vector AS (
    SELECT * FROM unnest(ARRAY[24,26,28,29,31,33,35,36,38,40,41,43,45,47,48,50,52,53,55,57,59,60,62,64,65,67,69,71,72,74,76,77,79,81,83,84]) WITH ORDINALITY v(midi,idx)
  ), roots(root_name) AS (VALUES ('Baaah'),('Beee'),('Booo'),('Laaah'),('O Long'),('Raw Tube'),('Shooo'),('Weee'),('Whaap'),('Whoa'),('Wooo')),
  entries AS (SELECT e FROM jsonb_array_elements(p_manifest) e)
  SELECT jsonb_typeof(p_manifest)='array' AND jsonb_array_length(p_manifest)=396
    AND (SELECT count(DISTINCT e->>'originalSampleId') FROM entries)=396
    AND (SELECT count(*) FROM entries JOIN roots ON root_name=e->>'rootName' JOIN vector ON idx=(e->>'sequenceIndex')::int
      WHERE e->>'expectedMidiNote'='0' AND e->>'targetMidiNote'=midi::text
        AND e->>'filePath' LIKE 'Gospel Musicians LLC/Exhibit 1/Talkbox Sounds/10 Talkbox Vocal Phrases/'||root_name||'/% Sample '||lpad(idx::text,4,'0')||'.wav')=396
    AND NOT EXISTS (SELECT 1 FROM roots LEFT JOIN entries ON e->>'rootName'=root_name GROUP BY root_name HAVING count(e)<>36)
$$;


ALTER FUNCTION "public"."sip_validate_gospel_talkbox_grid_manifest_v1"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_validate_gospel_talkbox_incomplete_grid_manifest_v1"("p_manifest" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  WITH expected(root_name,midi,idx) AS (
    SELECT 'Aaaah'::text,midi,idx::int
    FROM unnest(ARRAY[24,26,28,29,31,33,35,36,38,40,41,43,45,47,50,52,53,55,57,59,60,62,64,65,67,69,71,72,74,76,77,79,81,83,84]) WITH ORDINALITY v(midi,idx)
    UNION ALL
    SELECT 'Raw Buzz'::text,midi,idx::int
    FROM unnest(ARRAY[24,26,28,29,31,33,35,36,38,40,41,43,45,47,48,52,53,55,57,59,60,62,64,65,67,69,71,72,74,76,77,79,83,84]) WITH ORDINALITY v(midi,idx)
  ), entries AS (
    SELECT e,e->>'rootName' root_name,
      CASE WHEN e->>'sequenceIndex' ~ '^[1-9][0-9]*$' THEN (e->>'sequenceIndex')::int END sequence_index
    FROM jsonb_array_elements(p_manifest) e
  )
  SELECT jsonb_typeof(p_manifest)='array' AND jsonb_array_length(p_manifest)=69
    AND (SELECT count(DISTINCT e->>'originalSampleId') FROM entries)=69
    AND NOT EXISTS(SELECT 1 FROM entries WHERE sequence_index IS NULL OR e->'sequenceIndex' IS DISTINCT FROM to_jsonb(sequence_index))
    AND NOT EXISTS(SELECT 1 FROM entries WHERE e->>'contributorSlug'<>'gospel-musicians'
      OR e->>'stagingRootId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      OR e->>'sourceRootId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      OR CASE WHEN jsonb_typeof(e->'sourceConstructRowId')='number' AND e->>'sourceConstructRowId' ~ '^[1-9][0-9]*$'
        THEN e->'sourceConstructRowId' IS DISTINCT FROM to_jsonb((e->>'sourceConstructRowId')::bigint) ELSE true END)
    AND (SELECT count(DISTINCT (root_name,sequence_index)) FROM entries)=69
    AND (SELECT count(*) FROM entries JOIN expected x ON x.root_name=entries.root_name AND x.idx=entries.sequence_index
      WHERE e->>'expectedMidiNote'='0' AND e->>'targetMidiNote'=x.midi::text
        AND (e->>'filePath') ~ ('^Gospel Musicians LLC/Exhibit 1/Talkbox Sounds/10 Talkbox Vocal Phrases/'||x.root_name||'/[^/]+ Sample '||lpad(x.idx::text,4,'0')||E'\\.wav$'))=69
    AND NOT EXISTS(SELECT 1 FROM entries WHERE e->>'rootName'='Yeahh')
$_$;


ALTER FUNCTION "public"."sip_validate_gospel_talkbox_incomplete_grid_manifest_v1"("p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_versioned_output_prefix_guard_operation_change_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' OR current_setting(
    'app.sip_versioned_output_prefix_operation_authorized', true
  ) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'immutable_versioned_output_prefix_staging_operation';
  END IF;
  IF OLD.status <> 'running' OR NEW.id IS DISTINCT FROM OLD.id
    OR NEW.operation_token IS DISTINCT FROM OLD.operation_token
    OR NEW.provider_slug IS DISTINCT FROM OLD.provider_slug
    OR NEW.instrument_v2_id IS DISTINCT FROM OLD.instrument_v2_id
    OR NEW.provider_lease_id IS DISTINCT FROM OLD.provider_lease_id
    OR NEW.provider_lease_token_hash IS DISTINCT FROM OLD.provider_lease_token_hash
    OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
    OR NEW.preflight_receipt_id IS DISTINCT FROM OLD.preflight_receipt_id
    OR NEW.started_at IS DISTINCT FROM OLD.started_at
    OR NEW.status NOT IN ('completed','ambiguous')
  THEN RAISE EXCEPTION 'immutable_versioned_output_prefix_staging_operation'; END IF;
  IF NEW.status = 'completed' AND NEW.preflight_receipt_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.sip_versioned_output_prefix_remote_write_phase_receipts phase
    WHERE phase.staging_operation_id = NEW.id
      AND phase.preflight_receipt_id = NEW.preflight_receipt_id
      AND phase.provider_lease_id = NEW.provider_lease_id
  ) THEN
    RAISE EXCEPTION 'versioned_output_prefix_remote_write_phase_missing';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."sip_versioned_output_prefix_guard_operation_change_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_versioned_output_prefix_reject_immutable_change_v1"() RETURNS "trigger"
