CREATE OR REPLACE FUNCTION "public"."sip_versioned_output_prefix_source_terminal_snapshot_v1"("p_instrument_v2_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', source.id,
    'terminalEvidence', jsonb_build_object(
      'status', CASE WHEN source.completed_at IS NULL
        THEN 'legacy_quiescent' ELSE 'completed' END,
      'completedAt', CASE WHEN source.completed_at IS NULL THEN NULL ELSE to_char(
        source.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
      ) END,
      'updatedAt', to_char(source.updated_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
      'claimedBy', source.claimed_by,
      'claimedAt', source.claimed_at,
      'errorMessage', source.error_message,
      'licensingSecured', source.licensing_secured
    )
  ) ORDER BY source.id),'[]'::jsonb)
  FROM (
    SELECT DISTINCT ON (source.id)
      source.id,source.completed_at,source.updated_at,source.claimed_by,
      source.claimed_at,source.error_message,source.licensing_secured
    FROM public.sample_path_constructs construct
    JOIN public.samples_original_paths source
      ON source.id=construct.sample_original_path_id
    WHERE construct.instrument_v2_id=p_instrument_v2_id
    ORDER BY source.id
  ) source;
$$;


ALTER FUNCTION "public"."sip_versioned_output_prefix_source_terminal_snapshot_v1"("p_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_versioned_output_prefix_staging_projection_v1"("p_artifact_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'samplePathConstructId', receipt.sample_path_construct_id,
    'originalSampleId', receipt.original_sample_id,
    'relativePath', receipt.relative_path,
    'format', receipt.format,
    'quality', receipt.quality,
    'sourceS3Key', receipt.source_s3_key,
    'sourceObjectIdentity', receipt.source_object_identity,
    'sourceTerminalEvidence', receipt.source_terminal_evidence,
    'outputObjectIdentity', receipt.output_object_identity,
    'outputContentSha256', receipt.output_content_sha256,
    'processingFingerprintSha256', receipt.processing_fingerprint_sha256,
    'processingInput', receipt.processing_input,
    'contentIntentToken', receipt.content_intent_token,
    's3Key', receipt.destination_s3_key,
    'verifiedAt', to_char(
      receipt.verified_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    )
  ) ORDER BY receipt.sample_path_construct_id, receipt.format, receipt.quality), '[]'::jsonb)
  FROM public.sip_versioned_output_prefix_staging_receipts receipt
  WHERE receipt.artifact_id = p_artifact_id;
$$;


ALTER FUNCTION "public"."sip_versioned_output_prefix_staging_projection_v1"("p_artifact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sip_versioned_output_prefix_state_evidence_v1"("p_instrument_v2_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH state AS (
    SELECT public.sip_versioned_output_prefix_state_v1(p_instrument_v2_id) AS value
  )
  SELECT jsonb_build_object(
    'activeState',state.value,
    'activeStateHash',encode(digest(convert_to(state.value::text,'UTF8'),'sha256'),'hex')
  )
  FROM state
  WHERE state.value IS NOT NULL;
$$;


