CREATE OR REPLACE FUNCTION "public"."sip_versioned_output_prefix_state_v1"("p_instrument_v2_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'instrument', jsonb_build_object(
      'id', instrument.id,
      'file_path_reference', instrument.file_path_reference,
      'published', instrument.published
    ),
    'outputs', COALESCE((
      SELECT jsonb_agg(to_jsonb(output) ORDER BY output.destination_s3_key)
      FROM public.instrument_v2_publish_output_manifest output
      WHERE output.instrument_v2_id = instrument.id
    ), '[]'::jsonb),
    'manifest', (
      SELECT to_jsonb(manifest)
      FROM public.instrument_runtime_sample_manifests manifest
      WHERE manifest.instrument_v2_id = instrument.id
    ),
    'readiness', (
      SELECT to_jsonb(readiness)
      FROM public.instrument_v2_runtime_readiness readiness
      WHERE readiness.instrument_v2_id = instrument.id
    ),
    'admission', (
      SELECT to_jsonb(admission)
      FROM public.instrument_v2_deterministic_publication_admissions admission
      WHERE admission.instrument_v2_id = instrument.id
    )
  )
  FROM public.instruments_v2 instrument
  WHERE instrument.id = p_instrument_v2_id;
$$;


