CREATE OR REPLACE FUNCTION "public"."submit_sip_fleet_run"("p_provider_slug" "text", "p_provider_lease_token" "uuid", "p_idempotency_key" "text", "p_submitted_by" "text", "p_plan" "jsonb", "p_items" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_run_id uuid; v_artifact_id uuid; v_hash text; v_artifact_hash text; v_existing_hash text;
BEGIN
  IF p_plan IS NULL OR p_items IS NULL OR jsonb_typeof(p_plan) NOT IN ('object','array') OR jsonb_typeof(p_items)<>'array'
    OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'plan_and_items_required'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_to_recordset(p_items) x("itemKey" text)
    GROUP BY x."itemKey" HAVING x."itemKey" IS NULL OR count(*)>1) THEN RAISE EXCEPTION 'invalid_or_duplicate_item_key'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(btrim(p_provider_slug), 0));
  IF NOT EXISTS (SELECT 1 FROM public.sip_fleet_provider_leases WHERE provider_slug=p_provider_slug
    AND lease_token=p_provider_lease_token AND released_at IS NULL
    AND lease_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;

  v_hash := encode(digest(convert_to(jsonb_build_object('plan',p_plan,'items',p_items)::text,'UTF8'),'sha256'),'hex');
  v_artifact_hash := encode(digest(convert_to(p_plan::text,'UTF8'),'sha256'),'hex');
  SELECT run.id, run.admission_fingerprint INTO v_run_id, v_existing_hash
  FROM public.sip_fleet_runs run
  JOIN public.sip_fleet_plan_artifacts artifact ON artifact.id=run.plan_artifact_id
  WHERE run.provider_slug=p_provider_slug AND run.idempotency_key=p_idempotency_key;
  IF FOUND THEN
    IF v_existing_hash<>v_hash THEN RAISE EXCEPTION 'idempotency_key_payload_mismatch'; END IF;
    RETURN v_run_id;
  END IF;
  IF EXISTS (SELECT 1 FROM public.sip_fleet_runs run JOIN public.sip_fleet_run_items item ON item.run_id = run.id
    WHERE run.provider_slug = p_provider_slug AND run.status IN ('queued', 'running')
      AND item.status IN ('queued', 'running')) THEN RAISE EXCEPTION 'provider_publish_run_active'; END IF;

  INSERT INTO public.sip_fleet_plan_artifacts(provider_slug,content_hash,content,created_by)
  VALUES(p_provider_slug,v_artifact_hash,p_plan,p_submitted_by)
  ON CONFLICT(provider_slug,artifact_kind,content_hash) DO NOTHING RETURNING id INTO v_artifact_id;
  IF v_artifact_id IS NULL THEN SELECT id INTO STRICT v_artifact_id FROM public.sip_fleet_plan_artifacts
    WHERE provider_slug=p_provider_slug AND artifact_kind='publish-plan' AND content_hash=v_artifact_hash; END IF;
  INSERT INTO public.sip_fleet_runs(provider_slug,idempotency_key,plan_artifact_id,submitted_by,provider_lease_id,provider_lease_token,admission_fingerprint)
  SELECT p_provider_slug,p_idempotency_key,v_artifact_id,p_submitted_by,lease.id,p_provider_lease_token,v_hash
  FROM public.sip_fleet_provider_leases lease
  WHERE lease.provider_slug=p_provider_slug AND lease.lease_token=p_provider_lease_token
    AND lease.released_at IS NULL AND lease.lease_expires_at>clock_timestamp()
  RETURNING id INTO v_run_id;
  IF v_run_id IS NULL THEN RAISE EXCEPTION 'invalid_provider_lease'; END IF;
  INSERT INTO public.sip_fleet_run_items(run_id,item_key,instrument_v2_id,payload,priority,max_attempts)
  SELECT v_run_id,x."itemKey",x."instrumentV2Id",coalesce(x.payload,'{}'::jsonb),coalesce(x.priority,0),coalesce(x."maxAttempts",3)
  FROM jsonb_to_recordset(p_items) x("itemKey" text,"instrumentV2Id" uuid,payload jsonb,priority integer,"maxAttempts" integer);
  RETURN v_run_id;
END $$;


ALTER FUNCTION "public"."submit_sip_fleet_run"("p_provider_slug" "text", "p_provider_lease_token" "uuid", "p_idempotency_key" "text", "p_submitted_by" "text", "p_plan" "jsonb", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_composer_public_song_configs_from_legacy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  insert into public.composer_public_song_configs (
    composer_song_id,
    song_v2,
    audio_samples,
    created_at,
    updated_at
  ) values (
    new.composer_song_id,
    new.song_config,
    new.audio_samples,
    coalesce(new.published_at, now()),
    now()
  )
  on conflict (composer_song_id) do update
  set
    song_v2 = excluded.song_v2,
    audio_samples = excluded.audio_samples,
    updated_at = now();

  return new;
end;
$$;


