CREATE OR REPLACE FUNCTION "public"."trg_fn_sip_review_instrument_sample_scope_stale_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_ids uuid[];
BEGIN
    IF current_setting('sip.trigger_depth', true)::int > 0 THEN RETURN NULL; END IF;

    SELECT array_agg(DISTINCT sip_review_instrument_id) INTO v_ids FROM old_rows;

    IF v_ids IS NOT NULL AND array_length(v_ids, 1) > 0 THEN
        PERFORM public.mark_sip_review_warning_stale(v_ids, 'sample_scope_deleted');
    END IF;

    RETURN NULL;
END;
$$;


