CREATE OR REPLACE FUNCTION "public"."trg_fn_sip_review_instrument_stale_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_ids uuid[];
    v_contributor_ids uuid[];
    v_old_contrib text;
    v_new_contrib text;
BEGIN
    IF current_setting('sip.trigger_depth', true)::int > 0 THEN RETURN NULL; END IF;

    -- Collect directly affected IDs (union old + new)
    SELECT array_agg(DISTINCT id) INTO v_ids
    FROM (
        SELECT id FROM old_rows
        UNION
        SELECT id FROM new_rows
    ) combined;

    IF v_ids IS NOT NULL AND array_length(v_ids, 1) > 0 THEN
        PERFORM public.mark_sip_review_warning_stale(v_ids, 'instrument_updated');
    END IF;

    -- Special case: original_sample_ids changed => mark ALL contributor instruments stale
    IF EXISTS (
        SELECT 1 FROM old_rows o
        JOIN new_rows n ON o.id = n.id
        WHERE o.original_sample_ids IS DISTINCT FROM n.original_sample_ids
    ) THEN
        SELECT array_agg(DISTINCT i.id) INTO v_contributor_ids
        FROM public.sip_review_instrument i
        WHERE i.is_retired = false
          AND i.source_contributor_slug IN (
              SELECT DISTINCT source_contributor_slug FROM new_rows
          );

        IF v_contributor_ids IS NOT NULL AND array_length(v_contributor_ids, 1) > 0 THEN
            PERFORM public.mark_sip_review_warning_stale(v_contributor_ids, 'sample_ids_changed');
        END IF;
    END IF;

    -- Special case: contributor slug changed => mark all for BOTH old and new contributor
    IF EXISTS (
        SELECT 1 FROM old_rows o
        JOIN new_rows n ON o.id = n.id
        WHERE o.source_contributor_slug IS DISTINCT FROM n.source_contributor_slug
    ) THEN
        SELECT array_agg(DISTINCT i.id) INTO v_contributor_ids
        FROM public.sip_review_instrument i
        WHERE i.is_retired = false
          AND i.source_contributor_slug IN (
              SELECT source_contributor_slug FROM old_rows
              UNION
              SELECT source_contributor_slug FROM new_rows
          );

        IF v_contributor_ids IS NOT NULL AND array_length(v_contributor_ids, 1) > 0 THEN
            PERFORM public.mark_sip_review_warning_stale(v_contributor_ids, 'contributor_slug_changed');
        END IF;
    END IF;

    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."trg_fn_sip_review_instrument_stale_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_fn_sip_review_sample_disposition_stale"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF current_setting('sip.trigger_depth', true)::int > 0 THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_id := OLD.sip_review_instrument_id;
  ELSE
    v_id := NEW.sip_review_instrument_id;
  END IF;
  IF v_id IS NOT NULL THEN
    PERFORM public.mark_sip_review_warning_stale(
      ARRAY[v_id],
      'sample_provenance_disposition_changed'
    );
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


