CREATE OR REPLACE FUNCTION "public"."trg_fn_sip_sample_analysis_stale_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_ids uuid[];
    v_fallback_count integer;
BEGIN
    IF current_setting('sip.trigger_depth', true)::int > 0 THEN RETURN NULL; END IF;

    WITH changed_pairs AS (
        SELECT DISTINCT contributor_slug, original_sample_id
        FROM old_rows
        WHERE original_sample_id IS NOT NULL
    ),
    resolved AS (
        SELECT DISTINCT scope.sip_review_instrument_id
        FROM changed_pairs cp
        JOIN public.sip_review_instrument_sample_scope scope
            ON scope.contributor_slug = cp.contributor_slug
            AND scope.original_sample_id = cp.original_sample_id
        UNION
        SELECT DISTINCT i.id
        FROM changed_pairs cp
        JOIN public.sip_review_instrument i
            ON i.source_contributor_slug = cp.contributor_slug
            AND i.original_sample_ids @> ARRAY[cp.original_sample_id]
    )
    SELECT array_agg(sip_review_instrument_id) INTO v_ids FROM resolved;

    IF v_ids IS NOT NULL AND array_length(v_ids, 1) > 0 THEN
        PERFORM public.mark_sip_review_warning_stale(v_ids, 'sample_analysis_deleted');
    ELSE
        SELECT count(DISTINCT original_sample_id) INTO v_fallback_count
        FROM old_rows WHERE original_sample_id IS NOT NULL;

        IF v_fallback_count > 0 THEN
            INSERT INTO public.sip_review_warning_fallback_log (
                contributor_slug, sample_id_count, resolved_staging_count, reason
            )
            SELECT
                COALESCE((SELECT contributor_slug FROM old_rows LIMIT 1), 'unknown'),
                v_fallback_count, 0, 'sample_analysis_deleted_no_resolution';
        END IF;
    END IF;

    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."trg_fn_sip_sample_analysis_stale_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_fn_sip_sample_analysis_stale_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
