CREATE OR REPLACE FUNCTION "public"."unpublish_invalidated_deterministic_instrument_v2_v1"("p_instrument_v2_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_instrument_v2_id IS NULL THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.instruments_v2 instrument
    JOIN public.instrument_v2_deterministic_publication_admissions admission
      ON admission.instrument_v2_id = instrument.id
    WHERE instrument.id = p_instrument_v2_id
      AND instrument.published
  ) THEN
    PERFORM set_config('app.sip_publish_coordinator_authorized', 'on', true);
    UPDATE public.instruments_v2
    SET published = false
    WHERE id = p_instrument_v2_id
      AND published;
  END IF;

  DELETE FROM public.instrument_v2_deterministic_publication_admissions
  WHERE instrument_v2_id = p_instrument_v2_id;
END;
$$;


ALTER FUNCTION "public"."unpublish_invalidated_deterministic_instrument_v2_v1"("p_instrument_v2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unpublish_retired_sip_review_instrument_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.is_retired IS TRUE AND OLD.is_retired IS DISTINCT FROM TRUE THEN
    UPDATE public.instruments_v2 AS instrument
    SET published = false
    FROM public.sip_review_promotion_map AS mapping
    WHERE mapping.sip_review_instrument_id = NEW.id
      AND instrument.id = mapping.instrument_v2_id
      AND instrument.published = true
      AND NOT EXISTS (
        SELECT 1
        FROM public.sip_review_promotion_map AS sibling_mapping
        JOIN public.sip_review_instrument AS sibling_review
          ON sibling_review.id = sibling_mapping.sip_review_instrument_id
        WHERE sibling_mapping.instrument_v2_id = instrument.id
          AND sibling_review.is_retired = false
      );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."unpublish_retired_sip_review_instrument_v2"() OWNER TO "postgres";


