CREATE OR REPLACE FUNCTION "public"."update_instrument_v2_metadata"("p_instrument_id" "uuid", "p_name" "text", "p_published" boolean, "p_instrument_family" "text", "p_instrument_type" "text", "p_tag_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  updated_row public.instruments_v2%ROWTYPE;
  v_publish_result jsonb;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'name is required' USING ERRCODE = '22023';
  END IF;

  IF p_published AND (
    p_instrument_family IS NULL
    OR btrim(p_instrument_family) = ''
    OR p_instrument_type IS NULL
    OR btrim(p_instrument_type) = ''
  ) THEN
    RAISE EXCEPTION 'published instruments require family and type'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_tag_ids, ARRAY[]::uuid[])) AS requested(tag_id)
    LEFT JOIN public.instrument_tags tag ON tag.id = requested.tag_id
    WHERE tag.id IS NULL
  ) THEN
    RAISE EXCEPTION 'unknown instrument tag id' USING ERRCODE = '22023';
  END IF;

  -- Match the evidence invalidation lock order: advisory lock first, then the
  -- Instrument V2 row lock acquired by this update and the strict primitive.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'instrument-runtime-sample-manifest:' || p_instrument_id::text,
      0
    )
  );

  -- Metadata is committed independently of the requested publication state.
  -- The strict primitive below is the only operation allowed to change that
  -- state and returns persisted refusal diagnostics without rolling them back.
  UPDATE public.instruments_v2
  SET name = btrim(p_name),
      instrument_family = btrim(COALESCE(p_instrument_family, '')),
      instrument_type = NULLIF(btrim(COALESCE(p_instrument_type, '')), ''),
      updated_at = now()
  WHERE id = p_instrument_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'instrument not found' USING ERRCODE = 'P0002';
  END IF;

  DELETE FROM public.instrument_v2_instrument_tags
  WHERE instrument_v2_id = p_instrument_id;

  INSERT INTO public.instrument_v2_instrument_tags (
    instrument_v2_id,
    tag_id,
    source
  )
  SELECT p_instrument_id, tag_id, 'producer_metadata'
  FROM unnest(COALESCE(p_tag_ids, ARRAY[]::uuid[])) AS requested(tag_id)
  ON CONFLICT (instrument_v2_id, tag_id) DO UPDATE
  SET source = EXCLUDED.source;

  v_publish_result := public.set_instrument_v2_published_manifest_aware_v1(
    p_instrument_id,
    p_published
  );

  SELECT * INTO STRICT updated_row
  FROM public.instruments_v2
  WHERE id = p_instrument_id;

  RETURN jsonb_build_object(
    'id', updated_row.id,
    'name', updated_row.name,
    'published', updated_row.published,
    'instrument_family', updated_row.instrument_family,
    'instrument_type', updated_row.instrument_type,
    'runtimeManifestReadiness', v_publish_result
  );
END;
$$;


