CREATE OR REPLACE FUNCTION "public"."validate_instruments_v2_legato_transition_rows"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM new_rows changed
    JOIN public.instruments_v2 parent
      ON parent.id = changed.id
    LEFT JOIN public.instruments_v2 child
      ON child.id = parent.legato_transition
    WHERE parent.legato_transition IS NOT NULL
      AND (
        child.id IS NULL
        OR parent.playback_type::text = 'legato_transition'
        OR child.playback_type::text <> 'legato_transition'
        OR parent.contributor_id IS DISTINCT FROM child.contributor_id
      )
  ) THEN
    RAISE EXCEPTION 'invalid instruments_v2 legato_transition relationship'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM new_rows changed
    JOIN public.instruments_v2 child
      ON child.id = changed.id
    JOIN public.instruments_v2 parent
      ON parent.legato_transition = child.id
    WHERE child.playback_type::text <> 'legato_transition'
       OR parent.playback_type::text = 'legato_transition'
       OR parent.contributor_id IS DISTINCT FROM child.contributor_id
  ) THEN
    RAISE EXCEPTION 'invalid inbound instruments_v2 legato_transition relationship'
      USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$$;


