CREATE OR REPLACE FUNCTION "public"."validate_runtime_manifest_materialization_plan_v1"("p_contributor_slug" "text", "p_content" "jsonb", "p_require_unmaterialized" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_instrument_count integer;
BEGIN
  IF nullif(btrim(p_contributor_slug), '') IS NULL
    OR jsonb_typeof(p_content) <> 'object'
    OR p_content->>'schemaVersion' IS DISTINCT FROM
      'sip-runtime-manifest-materialization-v1'
    OR p_content->>'contributor' IS DISTINCT FROM btrim(p_contributor_slug)
    OR jsonb_typeof(p_content->'instrumentV2Ids') <> 'array'
    OR jsonb_typeof(p_content->'readinessSnapshots') <> 'array'
    OR jsonb_typeof(p_content->'runtimeManifests') <> 'array'
    OR jsonb_typeof(p_content->'anchorObjectVerification') <> 'object'
    OR coalesce((p_content->'anchorObjectVerification'->>'required')::boolean,
      false) IS NOT TRUE
    OR coalesce(p_content->'approval'->>'rehearsalRunId', '')
      !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  THEN
    RAISE EXCEPTION 'runtime_manifest_materialization_plan_invalid';
  END IF;

  SELECT count(*) INTO v_instrument_count
  FROM jsonb_array_elements_text(p_content->'instrumentV2Ids');

  IF v_instrument_count < 1 OR v_instrument_count > 250
    OR v_instrument_count <> (
      SELECT count(DISTINCT value)
      FROM jsonb_array_elements_text(p_content->'instrumentV2Ids')
    )
    OR v_instrument_count <>
      jsonb_array_length(p_content->'readinessSnapshots')
    OR v_instrument_count <>
      jsonb_array_length(p_content->'runtimeManifests')
  THEN
    RAISE EXCEPTION 'runtime_manifest_materialization_scope_invalid';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(p_content->'instrumentV2Ids') requested(value)
    LEFT JOIN public.instruments_v2 instrument
      ON instrument.id = requested.value::uuid
    LEFT JOIN public.contributors contributor
      ON contributor.id = instrument.contributor_id
    LEFT JOIN jsonb_array_elements(p_content->'readinessSnapshots') snapshot(value)
      ON snapshot.value->>'instrumentV2Id' = requested.value
    LEFT JOIN jsonb_array_elements(p_content->'runtimeManifests') expected(value)
      ON expected.value->>'instrumentV2Id' = requested.value
    LEFT JOIN public.instrument_runtime_sample_manifests persisted
      ON persisted.instrument_v2_id = instrument.id
    LEFT JOIN public.instrument_v2_runtime_readiness readiness
      ON readiness.instrument_v2_id = instrument.id
    CROSS JOIN LATERAL public.build_instrument_runtime_sample_manifest_v1(
      instrument.id
    ) candidate
    CROSS JOIN LATERAL public.build_instrument_v2_runtime_readiness_v1(
      instrument.id,
      candidate,
      false
    ) runtime_readiness
    WHERE instrument.id IS NULL
      OR instrument.published IS NOT TRUE
      OR contributor.slug IS DISTINCT FROM btrim(p_contributor_slug)
      OR snapshot.value IS NULL
      OR coalesce(snapshot.value->>'snapshotSha256', '') !~ '^[0-9a-f]{64}$'
      OR NOT public.is_current_instrument_v2_readiness_snapshot_v2(
        instrument.id,
        snapshot.value->>'snapshotSha256'
      )
      OR expected.value IS NULL
      OR coalesce(expected.value->>'manifestSha256', '') !~ '^[0-9a-f]{64}$'
      OR expected.value->>'manifestSha256'
        IS DISTINCT FROM candidate->>'manifestSha256'
      OR coalesce(expected.value->>'variantCount', '') !~ '^[1-9][0-9]*$'
      OR (expected.value->>'variantCount')::integer <>
        (candidate->>'variantCount')::integer
      OR coalesce((candidate->>'isComplete')::boolean, false) IS NOT TRUE
      OR runtime_readiness->>'manifestSha256' IS DISTINCT FROM
        expected.value->>'manifestSha256'
      OR coalesce((runtime_readiness->>'addressReady')::boolean, false)
        IS NOT TRUE
      OR coalesce((runtime_readiness->>'behaviorReady')::boolean, false)
        IS NOT TRUE
      OR runtime_readiness->>'fallbackState'
        IS DISTINCT FROM 'runtime_manifest'
      OR (
        p_require_unmaterialized
        AND (persisted.instrument_v2_id IS NOT NULL
          OR readiness.instrument_v2_id IS NOT NULL)
      )
  ) THEN
    RAISE EXCEPTION 'runtime_manifest_materialization_plan_drift';
  END IF;

  RETURN jsonb_build_object('instrumentCount', v_instrument_count);
END;
$_$;


ALTER FUNCTION "public"."validate_runtime_manifest_materialization_plan_v1"("p_contributor_slug" "text", "p_content" "jsonb", "p_require_unmaterialized" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_sip_instrument_legato_transition_rows"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM new_rows changed
    JOIN public.sip_instrument parent
      ON parent.id = changed.id
    LEFT JOIN public.sip_instrument child
      ON child.id = parent.legato_transition
    WHERE parent.legato_transition IS NOT NULL
      AND (
        child.id IS NULL
        OR parent.playback_type::text = 'legato_transition'
        OR COALESCE(child.playback_type::text, '') <> 'legato_transition'
        OR (
          parent.contributor_id IS NOT NULL
          AND child.contributor_id IS NOT NULL
          AND parent.contributor_id <> child.contributor_id
        )
      )
  ) THEN
    RAISE EXCEPTION 'invalid sip_instrument legato_transition relationship'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM new_rows changed
    JOIN public.sip_instrument child
      ON child.id = changed.id
    JOIN public.sip_instrument parent
      ON parent.legato_transition = child.id
    WHERE COALESCE(child.playback_type::text, '') <> 'legato_transition'
       OR parent.playback_type::text = 'legato_transition'
       OR (
         parent.contributor_id IS NOT NULL
         AND child.contributor_id IS NOT NULL
         AND parent.contributor_id <> child.contributor_id
       )
  ) THEN
    RAISE EXCEPTION 'invalid inbound sip_instrument legato_transition relationship'
      USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."validate_sip_instrument_legato_transition_rows"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_sip_publish_operator_lease_v1"("p_contributor_slug" "text", "p_lease_id" "uuid", "p_lease_token" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.sip_fleet_provider_leases lease
    WHERE lease.id = p_lease_id
      AND lease.provider_slug = p_contributor_slug
      AND lease.lease_token = p_lease_token
      AND lease.lease_expires_at > now()
      AND lease.released_at IS NULL
  )
$$;


