CREATE OR REPLACE FUNCTION "public"."validate_sip_review_instrument_legato_transition_rows"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM new_rows changed
    JOIN public.sip_review_instrument parent
      ON parent.id = changed.id
    LEFT JOIN public.sip_review_instrument child
      ON child.id = parent.legato_transition
    WHERE parent.legato_transition IS NOT NULL
      AND (
        child.id IS NULL
        OR parent.playback_type::text = 'legato_transition'
        OR COALESCE(child.playback_type::text, '') <> 'legato_transition'
        OR parent.source_contributor_slug <> child.source_contributor_slug
      )
  ) THEN
    RAISE EXCEPTION 'invalid sip_review_instrument legato_transition relationship'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM new_rows changed
    JOIN public.sip_review_instrument child
      ON child.id = changed.id
    JOIN public.sip_review_instrument parent
      ON parent.legato_transition = child.id
    WHERE COALESCE(child.playback_type::text, '') <> 'legato_transition'
       OR parent.playback_type::text = 'legato_transition'
       OR parent.source_contributor_slug <> child.source_contributor_slug
  ) THEN
    RAISE EXCEPTION 'invalid inbound sip_review_instrument legato_transition relationship'
      USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$$;


