    CONSTRAINT "song_projection_rows_check2" CHECK ((("meta_embedding" IS NULL) OR ((("meta_embedding")::"text" !~* '(nan|infinity)'::"text") AND (("genre_embedding")::"text" !~* '(nan|infinity)'::"text") AND (("instrumentation_embedding")::"text" !~* '(nan|infinity)'::"text") AND (("characteristics_embedding")::"text" !~* '(nan|infinity)'::"text")))),
    CONSTRAINT "song_projection_rows_core_check" CHECK (("jsonb_typeof"("core") = 'object'::"text")),
