CREATE TABLE IF NOT EXISTS "public"."instruments_v2" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "engine_type" "public"."instrument_engine_type" DEFAULT 'tonal'::"public"."instrument_engine_type" NOT NULL,
    "playback_type" "public"."instrument_playback_type" DEFAULT 'oneShot'::"public"."instrument_playback_type" NOT NULL,
    "polyphony_type" "public"."instrument_polyphony_type" DEFAULT 'Single'::"public"."instrument_polyphony_type" NOT NULL,
    "instrument_family" "text" DEFAULT ''::"text" NOT NULL,
    "instrument_type" "text",
    "contributor_id" "uuid" NOT NULL,
    "collection" "text",
    "pitch_contents" "jsonb" DEFAULT '["0"]'::"jsonb" NOT NULL,
    "pitch_content_config" "jsonb",
    "range_lower" integer DEFAULT 21 NOT NULL,
    "range_upper" integer DEFAULT 108 NOT NULL,
    "single_pitch" integer,
    "gain" real DEFAULT 0.1 NOT NULL,
    "sustain_crop_time" real DEFAULT 0.1 NOT NULL,
    "file_path_reference" "text",
    "file_name_references" "text"[],
    "velocity_layers" "jsonb" DEFAULT '{"0": [0]}'::"jsonb" NOT NULL,
    "articulations" "uuid"[] DEFAULT ARRAY[]::"uuid"[],
    "effects_instruments" "uuid"[] DEFAULT ARRAY[]::"uuid"[],
    "mic_positions" "jsonb" DEFAULT '{"0/0/0": ["main"]}'::"jsonb" NOT NULL,
    "published" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lookup_key" "text" NOT NULL,
    "round_robins" "jsonb" DEFAULT '{"0/0": [0]}'::"jsonb" NOT NULL,
    "articulation" "text",
    "effect" "text",
    "original_sample_ids" "uuid"[],
    "legato_transition" "uuid",
    "filename_variant_map" "jsonb",
    "asset_role" "public"."instrument_asset_role" DEFAULT 'playable_sample'::"public"."instrument_asset_role" NOT NULL,
    "sampled_midi_notes" smallint[],
    CONSTRAINT "instruments_v2_legato_not_effect_relationship" CHECK ((("legato_transition" IS NULL) OR (NULLIF("btrim"("effect"), ''::"text") IS NULL))),
    CONSTRAINT "instruments_v2_legato_transition_child_leaf" CHECK (((("playback_type")::"text" <> 'legato_transition'::"text") OR (("legato_transition" IS NULL) AND (NULLIF("btrim"("effect"), ''::"text") IS NULL) AND ("cardinality"(COALESCE("articulations", ARRAY[]::"uuid"[])) = 0) AND ("cardinality"(COALESCE("effects_instruments", ARRAY[]::"uuid"[])) = 0)))),
    CONSTRAINT "instruments_v2_legato_transition_not_self" CHECK ((("legato_transition" IS NULL) OR ("legato_transition" <> "id"))),
    CONSTRAINT "instruments_v2_publish_requires_taxonomy" CHECK (((NOT "published") OR ((NULLIF("btrim"("instrument_family"), ''::"text") IS NOT NULL) AND (NULLIF("btrim"("instrument_type"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "instruments_v2_sampled_midi_notes_canonical" CHECK ((("sampled_midi_notes" IS NULL) OR "public"."is_canonical_sampled_midi_notes_v1"("sampled_midi_notes"))),
    CONSTRAINT "valid_range" CHECK (("range_lower" <= "range_upper")),
    CONSTRAINT "valid_range_midi" CHECK ((("range_lower" >= 0) AND ("range_upper" <= 127)))
);


ALTER TABLE "public"."instruments_v2" OWNER TO "postgres";


COMMENT ON COLUMN "public"."instruments_v2"."legato_transition" IS 'Optional production Instruments V2 row that supplies legato transition samples for this parent instrument.';



COMMENT ON COLUMN "public"."instruments_v2"."filename_variant_map" IS 'Optional deterministic filename map keyed by pitch_content/velocity/round_robin/mic_position for non-tonal V2 sample URL synthesis.';



COMMENT ON COLUMN "public"."instruments_v2"."sampled_midi_notes" IS 'Canonical authored numeric MIDI filename anchors shared by every active tonal variant group; NULL requires construct-backed runtime addressing.';



