CREATE TABLE IF NOT EXISTS "public"."feedback" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text" NOT NULL,
    "urgency" "text" DEFAULT 'medium'::"text" NOT NULL,
    "page_url" "text",
    "ui_context" "jsonb" DEFAULT '{}'::"jsonb",
    "screenshot_url" "text",
    "contact_ok" boolean DEFAULT false,
    "status" "text" DEFAULT 'new'::"text" NOT NULL,
    "admin_notes" "text",
    "cluster_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "store_context" "jsonb",
    "log_info_context" "jsonb",
    "log_warning_context" "jsonb",
    "log_error_context" "jsonb",
    CONSTRAINT "feedback_status_check" CHECK (("status" = ANY (ARRAY['new'::"text", 'reviewed'::"text", 'planned'::"text", 'in_progress'::"text", 'completed'::"text", 'declined'::"text"]))),
    CONSTRAINT "feedback_title_check" CHECK (("char_length"("title") <= 200)),
    CONSTRAINT "feedback_type_check" CHECK (("type" = ANY (ARRAY['bug'::"text", 'feature_request'::"text", 'improvement'::"text", 'other'::"text"]))),
    CONSTRAINT "feedback_urgency_check" CHECK (("urgency" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text"])))
);


ALTER TABLE "public"."feedback" OWNER TO "postgres";


COMMENT ON TABLE "public"."feedback" IS 'User-submitted feedback items (bugs, feature requests, improvements)';



COMMENT ON COLUMN "public"."feedback"."store_context" IS 'Snapshot of all registered Zustand store state at time of feedback submission';



COMMENT ON COLUMN "public"."feedback"."log_info_context" IS 'Contents of the info log buffer (last N entries) at submission time';



COMMENT ON COLUMN "public"."feedback"."log_warning_context" IS 'Contents of the warning log buffer at submission time';



COMMENT ON COLUMN "public"."feedback"."log_error_context" IS 'Contents of the error log buffer at submission time';



