    "feedback"."urgency",
    "regexp_replace"("feedback"."page_url", '([?#]).*$'::"text", ''::"text") AS "page_path",
    "feedback"."contact_ok",
    "feedback"."status",
    "feedback"."created_at",
    "feedback"."updated_at"
   FROM "public"."feedback";


