CREATE OR REPLACE VIEW "public"."creator_ranked_creators" WITH ("security_invoker"='true') AS
 SELECT "profile"."id",
    "profile"."platform",
    "profile"."handle",
    "profile"."display_name",
    "profile"."bio",
    "profile"."follower_count",
    "profile"."avg_views",
    "profile"."engagement_rate",
    "profile"."external_links",
    "profile"."recent_content",
    "profile"."status",
    "profile"."discovery_source",
    "profile"."discovered_at",
    "profile"."updated_at",
    "latest_score"."overall_score" AS "latest_overall_score",
    "to_jsonb"("latest_score".*) AS "latest_score"
   FROM ("public"."creator_profiles" "profile"
     LEFT JOIN LATERAL ( SELECT "score"."id",
            "score"."creator_id",
            "score"."loop_affinity",
            "score"."educational_influence",
            "score"."audience_fit",
            "score"."engagement_quality",
            "score"."collaboration_likelihood",
            "score"."overall_score",
            "score"."confidence",
            "score"."rationale",
            "score"."evidence_urls",
            "score"."prompt_version",
            "score"."content_hash",
            "score"."provider",
            "score"."model",
            "score"."scored_at",
            "score"."research_payload"
           FROM "public"."creator_scores" "score"
          WHERE ("score"."creator_id" = "profile"."id")
          ORDER BY "score"."scored_at" DESC
         LIMIT 1) "latest_score" ON (true));


