CREATE TABLE IF NOT EXISTS "public"."derived_sample_analysis" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "sample_id" "uuid" NOT NULL,
    "pitch_mean" real,
    "pitch_median" real,
    "pitch_std" real,
    "pitch_range" real,
    "pitch_stability" real,
    "effective_duration" real,
    "vibrato_rate_hz" real,
    "vibrato_depth_hz" real,
    "inharmonicity" real,
    "tristimulus_t1" real,
    "tristimulus_t2" real,
    "tristimulus_t3" real,
    "odd_even_ratio" real,
    "spectral_entropy" real,
    "fundamental_hz" real,
    "spectral_flux_mean" real,
    "spectral_flux_std" real,
    "attack_time_ms" real,
    "decay_time_ms" real,
    "temporal_centroid" real,
    "sustain_stability" real,
    "onset_sharpness" real,
    "derived_at" timestamp with time zone DEFAULT "now"(),
    "pitch_confidence" real,
    "hp_ratio" real,
    "hnr_db" real,
    "spectral_contrast_overall_mean" real
);


ALTER TABLE "public"."derived_sample_analysis" OWNER TO "postgres";


COMMENT ON TABLE "public"."derived_sample_analysis" IS 'Derived audio features computed from stored Meyda and Aubio analysis results';



COMMENT ON COLUMN "public"."derived_sample_analysis"."sample_id" IS 'Reference to original_sample_paths';



COMMENT ON COLUMN "public"."derived_sample_analysis"."pitch_mean" IS 'Mean pitch frequency (Hz) from cleaned Aubio pitch track';



COMMENT ON COLUMN "public"."derived_sample_analysis"."pitch_median" IS 'Median pitch frequency (Hz) from cleaned Aubio pitch track';



COMMENT ON COLUMN "public"."derived_sample_analysis"."pitch_std" IS 'Standard deviation of pitch frequency (Hz)';



COMMENT ON COLUMN "public"."derived_sample_analysis"."pitch_range" IS 'Range of pitch (max - min) in Hz';



COMMENT ON COLUMN "public"."derived_sample_analysis"."pitch_stability" IS 'Pitch stability metric (std/mean, lower = more stable)';



COMMENT ON COLUMN "public"."derived_sample_analysis"."effective_duration" IS 'Duration of stable/voiced pitch region (seconds)';



COMMENT ON COLUMN "public"."derived_sample_analysis"."vibrato_rate_hz" IS 'Detected vibrato rate (Hz), typically 4-7 Hz';



COMMENT ON COLUMN "public"."derived_sample_analysis"."vibrato_depth_hz" IS 'Detected vibrato depth (Hz), typically ±2-10 Hz';



COMMENT ON COLUMN "public"."derived_sample_analysis"."inharmonicity" IS 'Mean deviation of harmonic peaks from ideal positions';



COMMENT ON COLUMN "public"."derived_sample_analysis"."tristimulus_t1" IS 'Fundamental magnitude / total harmonic magnitude';



COMMENT ON COLUMN "public"."derived_sample_analysis"."tristimulus_t2" IS '(2nd + 3rd + 4th harmonic) / total harmonic magnitude';



COMMENT ON COLUMN "public"."derived_sample_analysis"."tristimulus_t3" IS 'Remaining harmonics / total harmonic magnitude';



COMMENT ON COLUMN "public"."derived_sample_analysis"."odd_even_ratio" IS 'Sum of odd harmonic energy / sum of even harmonic energy';



COMMENT ON COLUMN "public"."derived_sample_analysis"."spectral_entropy" IS 'Spectral entropy measuring spectral complexity/noise-likeness';



COMMENT ON COLUMN "public"."derived_sample_analysis"."fundamental_hz" IS 'Detected fundamental frequency (Hz)';



COMMENT ON COLUMN "public"."derived_sample_analysis"."spectral_flux_mean" IS 'Mean spectral flux across frames';



COMMENT ON COLUMN "public"."derived_sample_analysis"."spectral_flux_std" IS 'Standard deviation of spectral flux';



COMMENT ON COLUMN "public"."derived_sample_analysis"."attack_time_ms" IS 'Time from noise floor to peak RMS (ms)';



COMMENT ON COLUMN "public"."derived_sample_analysis"."decay_time_ms" IS 'Time from peak RMS to 40% threshold (ms)';



COMMENT ON COLUMN "public"."derived_sample_analysis"."temporal_centroid" IS 'Temporal centroid (center of energy over time)';



COMMENT ON COLUMN "public"."derived_sample_analysis"."sustain_stability" IS 'RMS stability during sustain region';



COMMENT ON COLUMN "public"."derived_sample_analysis"."onset_sharpness" IS 'RMS slope at attack onset (higher = sharper transient)';



COMMENT ON COLUMN "public"."derived_sample_analysis"."derived_at" IS 'Timestamp when derived analysis was computed';



COMMENT ON COLUMN "public"."derived_sample_analysis"."hp_ratio" IS 'Harmonic/percussive energy ratio from librosa HPSS';



COMMENT ON COLUMN "public"."derived_sample_analysis"."hnr_db" IS 'Harmonic-to-noise ratio in dB from librosa HPSS';



COMMENT ON COLUMN "public"."derived_sample_analysis"."spectral_contrast_overall_mean" IS 'Mean of 7-band spectral contrast means from librosa';



