CREATE TABLE IF NOT EXISTS "public"."feature_flag_change_events" (
    "id" bigint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "feature_flag_id" "uuid" NOT NULL,
    "target_user_id" "uuid",
    "actor_user_id" "uuid",
    "entity_type" "text" NOT NULL,
    "action" "text" NOT NULL,
    "before_state" "jsonb",
    "after_state" "jsonb",
    "mutation_source" "text" NOT NULL,
    "change_reason" "text",
    CONSTRAINT "feature_flag_change_events_action_check" CHECK (("action" = ANY (ARRAY['insert'::"text", 'update'::"text", 'archive'::"text", 'delete'::"text"]))),
    CONSTRAINT "feature_flag_change_events_after_state_check" CHECK ((("after_state" IS NULL) OR ("jsonb_typeof"("after_state") = 'object'::"text"))),
    CONSTRAINT "feature_flag_change_events_before_state_check" CHECK ((("before_state" IS NULL) OR ("jsonb_typeof"("before_state") = 'object'::"text"))),
    CONSTRAINT "feature_flag_change_events_change_reason_check" CHECK ((("change_reason" IS NULL) OR ("char_length"("change_reason") <= 500))),
    CONSTRAINT "feature_flag_change_events_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['feature_flag'::"text", 'user_enablement'::"text"]))),
    CONSTRAINT "feature_flag_change_events_source_check" CHECK (("mutation_source" = ANY (ARRAY['admin'::"text", 'self_service'::"text", 'migration'::"text"]))),
    CONSTRAINT "feature_flag_change_events_target_check" CHECK (((("entity_type" = 'feature_flag'::"text") AND ("target_user_id" IS NULL)) OR (("entity_type" = 'user_enablement'::"text") AND ("target_user_id" IS NOT NULL))))
);


ALTER TABLE "public"."feature_flag_change_events" OWNER TO "feature_flag_owner";


ALTER TABLE "public"."feature_flag_change_events" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."feature_flag_change_events_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "public"."feature_flags" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "key" "text" NOT NULL,
    "label" "text" NOT NULL,
    "description" "text" NOT NULL,
    "category" "text" NOT NULL,
    "surfaces" "text"[] NOT NULL,
    "is_active" boolean DEFAULT false NOT NULL,
    "requires_reload" boolean DEFAULT false NOT NULL,
    "dev_logging_enabled" boolean DEFAULT false NOT NULL,
    "product_insights_enabled" boolean DEFAULT false NOT NULL,
    "self_service_enabled" boolean DEFAULT false NOT NULL,
    "owner" "text" NOT NULL,
    "review_after" timestamp with time zone NOT NULL,
    "archived_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by_user_id" "uuid",
    "updated_by_user_id" "uuid",
    CONSTRAINT "feature_flags_archived_at_check" CHECK ((("archived_at" IS NULL) OR ("archived_at" >= "created_at"))),
    CONSTRAINT "feature_flags_category_check" CHECK (("category" = ANY (ARRAY['release'::"text", 'runtime'::"text", 'diagnostic'::"text"]))),
    CONSTRAINT "feature_flags_description_check" CHECK ((("char_length"("btrim"("description")) >= 1) AND ("char_length"("btrim"("description")) <= 2000))),
    CONSTRAINT "feature_flags_key_format_check" CHECK (("key" ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'::"text")),
    CONSTRAINT "feature_flags_label_check" CHECK ((("char_length"("btrim"("label")) >= 1) AND ("char_length"("btrim"("label")) <= 120))),
    CONSTRAINT "feature_flags_owner_check" CHECK ((("char_length"("btrim"("owner")) >= 1) AND ("char_length"("btrim"("owner")) <= 120))),
    CONSTRAINT "feature_flags_review_after_check" CHECK (("review_after" > "created_at")),
    CONSTRAINT "feature_flags_surfaces_check" CHECK ((("cardinality"("surfaces") > 0) AND ("array_position"("surfaces", NULL::"text") IS NULL) AND ("surfaces" <@ ARRAY['producer'::"text", 'market'::"text", 'admin'::"text", 'shared'::"text"]))),
    CONSTRAINT "feature_flags_updated_at_check" CHECK (("updated_at" >= "created_at"))
);


ALTER TABLE "public"."feature_flags" OWNER TO "feature_flag_owner";


CREATE TABLE IF NOT EXISTS "public"."feature_user_enablements" (
