CREATE OR REPLACE VIEW "public"."feedback_with_votes" WITH ("security_invoker"='true') AS
 SELECT "uf"."id",
    "uf"."user_id",
    "uf"."type",
    "uf"."title",
    "uf"."description",
    "uf"."urgency",
    "uf"."page_url",
    "uf"."ui_context",
    "uf"."screenshot_url",
    "uf"."contact_ok",
    "uf"."status",
    "uf"."admin_notes",
    "uf"."cluster_id",
    "uf"."created_at",
    "uf"."updated_at",
    COALESCE("v"."vote_count", (0)::bigint) AS "vote_count"
   FROM ("public"."feedback" "uf"
     LEFT JOIN ( SELECT "feedback_votes"."feedback_id",
            "count"(*) AS "vote_count"
           FROM "public"."feedback_votes"
          GROUP BY "feedback_votes"."feedback_id") "v" ON (("v"."feedback_id" = "uf"."id")));


ALTER TABLE "public"."feedback_with_votes" OWNER TO "postgres";


