CREATE TABLE IF NOT EXISTS "public"."instrument_runtime_sample_manifests" (
    "instrument_v2_id" "uuid" NOT NULL,
    "schema_version" smallint DEFAULT 1 NOT NULL,
    "variants" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "variant_count" integer NOT NULL,
    "manifest_sha256" "text" NOT NULL,
    "is_complete" boolean NOT NULL,
    "blocking_reasons" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "generated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "instrument_runtime_sample_manifests_schema_version_check" CHECK (("schema_version" = 1)),
    CONSTRAINT "instrument_runtime_sample_manifests_sha256_check" CHECK (("manifest_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "instrument_runtime_sample_manifests_variant_count_check" CHECK ((("variant_count" >= 0) AND ("variant_count" = "jsonb_array_length"("variants")))),
    CONSTRAINT "instrument_runtime_sample_manifests_variants_array_check" CHECK (("jsonb_typeof"("variants") = 'array'::"text")),
    CONSTRAINT "runtime_sample_manifests_blocking_reasons_array_check" CHECK (("jsonb_typeof"("blocking_reasons") = 'array'::"text"))
);


ALTER TABLE "public"."instrument_runtime_sample_manifests" OWNER TO "postgres";


COMMENT ON TABLE "public"."instrument_runtime_sample_manifests" IS 'One derived deterministic runtime sample manifest per Instrument V2. Runtime readers see complete rows only; service-role audit tooling may inspect incomplete rows.';



COMMENT ON COLUMN "public"."instrument_runtime_sample_manifests"."variants" IS 'Ordered InstrumentRuntimeSampleVariantV1 array. Missing timing is explicit JSON null and effective eligibility is a concrete boolean.';



COMMENT ON COLUMN "public"."instrument_runtime_sample_manifests"."manifest_sha256" IS 'SHA-256 of schema version plus deterministically ordered stable playback fields. sampleOriginalPathId is excluded because it is provenance-only.';



