COMMENT ON TABLE "public"."instrument_v2_publish_output_manifest" IS 'Current, fingerprinted provenance for SIP V2 public sample outputs. A row is written only after the samples executor reports the complete source plan successful; it is not itself publish authorization.';



COMMENT ON COLUMN "public"."instrument_v2_publish_output_manifest"."output_object_identity" IS 'S3 object receipt returned after the guarded public output write. V1 rows without a receipt are never eligible for incremental reuse.';



CREATE TABLE IF NOT EXISTS "public"."instrument_v2_runtime_readiness" (
    "instrument_v2_id" "uuid" NOT NULL,
    "manifest_sha256" "text" NOT NULL,
    "variant_count" integer NOT NULL,
    "address_ready" boolean NOT NULL,
    "address_status" "text" NOT NULL,
    "behavior_ready" boolean NOT NULL,
    "fallback_eligibility" "text" NOT NULL,
    "fallback_state" "text" NOT NULL,
    "blockers" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "evaluated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "instrument_v2_runtime_readiness_address_status_check" CHECK (("address_status" = ANY (ARRAY['pending'::"text", 'ready'::"text", 'blocked'::"text"]))),
    CONSTRAINT "instrument_v2_runtime_readiness_blockers_check" CHECK (("jsonb_typeof"("blockers") = 'array'::"text")),
    CONSTRAINT "instrument_v2_runtime_readiness_check" CHECK (((("fallback_state" = 'runtime_manifest'::"text") AND "address_ready" AND "behavior_ready") OR (("fallback_state" = 'construct_hydration'::"text") AND "address_ready" AND (NOT "behavior_ready")) OR (("fallback_state" = 'blocked'::"text") AND (NOT "address_ready")))),
    CONSTRAINT "instrument_v2_runtime_readiness_check1" CHECK (((("address_status" = 'ready'::"text") AND "address_ready") OR (("address_status" = ANY (ARRAY['pending'::"text", 'blocked'::"text"])) AND (NOT "address_ready")))),
    CONSTRAINT "instrument_v2_runtime_readiness_check2" CHECK ((("behavior_ready" AND ("fallback_eligibility" = 'runtime_manifest'::"text")) OR ((NOT "behavior_ready") AND ("fallback_eligibility" = 'construct_hydration'::"text")))),
    CONSTRAINT "instrument_v2_runtime_readiness_fallback_eligibility_check" CHECK (("fallback_eligibility" = ANY (ARRAY['runtime_manifest'::"text", 'construct_hydration'::"text"]))),
    CONSTRAINT "instrument_v2_runtime_readiness_fallback_state_check" CHECK (("fallback_state" = ANY (ARRAY['runtime_manifest'::"text", 'construct_hydration'::"text", 'blocked'::"text"]))),
    CONSTRAINT "instrument_v2_runtime_readiness_manifest_sha256_check" CHECK (("manifest_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "instrument_v2_runtime_readiness_variant_count_check" CHECK (("variant_count" >= 0))
);


ALTER TABLE "public"."instrument_v2_runtime_readiness" OWNER TO "postgres";


COMMENT ON TABLE "public"."instrument_v2_runtime_readiness" IS 'Separate address/behavior readiness classification for the current runtime manifest. Incomplete but addressable instruments retain explicit construct hydration; address-invalid instruments cannot publish.';



