CREATE OR REPLACE VIEW "public"."instruments_v2_with_audio_profile_v1" WITH ("security_invoker"='true') AS
 SELECT "i"."id",
    "i"."name",
    "i"."engine_type",
    "i"."playback_type",
    "i"."polyphony_type",
    "i"."instrument_family",
    "i"."instrument_type",
    "i"."contributor_id",
    "c"."slug" AS "contributor_slug",
    "i"."collection",
    "i"."pitch_contents",
    "i"."pitch_content_config",
    "i"."range_lower",
    "i"."range_upper",
    "i"."single_pitch",
    "i"."gain",
    "i"."sustain_crop_time",
    "i"."file_path_reference",
    "i"."file_name_references",
    "i"."velocity_layers",
    "i"."articulations",
    "i"."effects_instruments",
    "i"."mic_positions",
    "i"."published",
    "i"."lookup_key",
    "i"."round_robins",
    "i"."articulation",
    "i"."effect",
    "p"."profile_version" AS "audio_profile_version",
    "p"."source_signature" AS "audio_profile_source_signature",
    "p"."sample_count" AS "audio_profile_sample_count",
    "p"."analyzed_sample_count" AS "audio_profile_analyzed_sample_count",
    "p"."flagged_sample_count" AS "audio_profile_flagged_sample_count",
    "p"."quality_report" AS "audio_profile_quality_report",
    "p"."warning_payload" AS "audio_profile_warning_payload",
    "p"."temporal_summary" AS "audio_profile_temporal_summary",
    "p"."spectral_centroid_median",
    "p"."spectral_flatness_median",
    "p"."spectral_contrast_median",
    "p"."hp_ratio_median",
    "p"."attack_time_ms_median",
    "p"."decay_time_ms_median",
    "p"."inharmonicity_median",
    "p"."spectral_rolloff_median",
    "p"."spectral_entropy_median",
    "p"."hnr_db_median",
    "p"."onset_sharpness_median",
    "p"."sustain_stability_median",
    "p"."temporal_centroid_median",
    "p"."spectral_flux_mean_median",
    "p"."pitch_mean",
    "p"."pitch_median_median",
    "p"."pitch_std_median",
    "p"."pitch_range_median",
    "p"."pitch_stability_median",
    "p"."pitch_confidence_median",
    "p"."effective_duration_median",
    "p"."vibrato_rate_hz_median",
    "p"."vibrato_depth_hz_median",
    "p"."odd_even_ratio_median",
    "p"."pitched_sample_ratio",
    "p"."long_sample_ratio",
    "p"."short_sample_ratio",
    "p"."sharp_onset_sample_ratio",
    "p"."tremolo_candidate_sample_ratio",
    "p"."vibrato_candidate_sample_ratio",
    "p"."noisy_candidate_sample_ratio",
    "p"."harmonic_candidate_sample_ratio",
    "p"."percussive_candidate_sample_ratio",
    "p"."bright_sample_ratio",
    "p"."dark_sample_ratio",
    "p"."low_register",
    "p"."mid_register",
    "p"."high_register",
    "p"."embedding",
    "p"."computed_at" AS "audio_profile_computed_at",
    "i"."legato_transition",
    "i"."asset_role"
   FROM (("public"."instruments_v2" "i"
     JOIN "public"."instrument_audio_profile_v1" "p" ON (("p"."instrument_v2_id" = "i"."id")))
     LEFT JOIN "public"."contributors" "c" ON (("c"."id" = "i"."contributor_id")))
  WHERE (("i"."published" = true) AND (NOT ("p"."source_signature" IS DISTINCT FROM "public"."compute_instrument_audio_profile_signature_v1"("i"."id", "p"."profile_version"))) AND ("p"."embedding" IS NOT NULL) AND ("p"."spectral_centroid_median" IS NOT NULL) AND ("p"."spectral_contrast_median" IS NOT NULL));


