CREATE OR REPLACE VIEW "public"."market_patterns_loops_unique_feed_v1" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "mp"."id",
            "mp"."market_song_id",
            COALESCE(NULLIF("mp"."song_title", ''::"text"), NULLIF("ms"."song_title", ''::"text"), 'Untitled'::"text") AS "song_title",
            COALESCE(NULLIF("mp"."song_slug", ''::"text"), NULLIF("ms"."slug", ''::"text")) AS "song_slug",
            "mp"."display_name",
            "mp"."audio_url",
            "mp"."waveform",
            "mp"."duration_seconds",
            "mp"."bpm",
            "mp"."key",
            "mp"."scale_quality",
            "mp"."mood",
            "mp"."instrument_name",
            "mp"."instrument_family",
            "mp"."pattern_type",
            "mp"."bus_type",
            "mp"."bus_index",
            "mp"."track_index",
            "mp"."song_config_coordinates",
            COALESCE(NULLIF("mp"."contributor_name", ''::"text"), NULLIF("mp"."artist_name", ''::"text"), NULLIF("ms"."composer", ''::"text")) AS "creator_name",
            "lower"(((((((((((((((COALESCE("mp"."display_name", ''::"text") || ' '::"text") || COALESCE("mp"."instrument_name", ''::"text")) || ' '::"text") || COALESCE("mp"."instrument_family", ''::"text")) || ' '::"text") || COALESCE("mp"."mood", ''::"text")) || ' '::"text") || COALESCE("mp"."pattern_type", ''::"text")) || ' '::"text") || COALESCE("mp"."song_title", ''::"text")) || ' '::"text") || COALESCE("mp"."contributor_name", ''::"text")) || ' '::"text") || COALESCE("mp"."artist_name", ''::"text"))) AS "primary_match_text",
            "lower"(((((((((((((((((COALESCE("mp"."display_name", ''::"text") || ' '::"text") || COALESCE("mp"."instrument_name", ''::"text")) || ' '::"text") || COALESCE("mp"."instrument_family", ''::"text")) || ' '::"text") || COALESCE("mp"."mood", ''::"text")) || ' '::"text") || COALESCE("mp"."pattern_type", ''::"text")) || ' '::"text") || COALESCE("mp"."song_title", ''::"text")) || ' '::"text") || COALESCE("mp"."contributor_name", ''::"text")) || ' '::"text") || COALESCE("mp"."artist_name", ''::"text")) || ' '::"text") || COALESCE("array_to_string"("mp"."search_tokens", ' '::"text"), ''::"text"))) AS "match_text",
            COALESCE((("mp"."meta" ->> 'layer_count'::"text"))::integer, 0) AS "layer_count",
            ARRAY( SELECT "jsonb_array_elements_text"(
                        CASE
                            WHEN ("jsonb_typeof"(("mp"."meta" -> 'layer_instrument_names'::"text")) = 'array'::"text") THEN ("mp"."meta" -> 'layer_instrument_names'::"text")
                            ELSE '[]'::"jsonb"
                        END) AS "jsonb_array_elements_text") AS "layer_instrument_names",
            ARRAY( SELECT "jsonb_array_elements_text"(
                        CASE
                            WHEN ("jsonb_typeof"(("mp"."meta" -> 'layer_family_buckets'::"text")) = 'array'::"text") THEN ("mp"."meta" -> 'layer_family_buckets'::"text")
                            ELSE '[]'::"jsonb"
                        END) AS "jsonb_array_elements_text") AS "layer_family_buckets",
            "mp"."updated_at"
           FROM (("public"."market_patterns" "mp"
             JOIN "public"."market_songs" "ms" ON (("ms"."id" = "mp"."market_song_id")))
             JOIN "public"."market_song_configs" "msc" ON (("msc"."market_song_id" = "mp"."market_song_id")))
          WHERE (("mp"."bus_type" = 'loops'::"text") AND ("mp"."is_unique" = true) AND ("mp"."is_published" = true) AND ("ms"."is_published" = true) AND ((NULLIF("btrim"("mp"."track_index"), ''::"text") IS NULL) OR (EXISTS ( SELECT 1
                   FROM "jsonb_array_elements"(
                        CASE
                            WHEN ("jsonb_typeof"(("msc"."song_v2" -> 'phraseSequence'::"text")) = 'array'::"text") THEN ("msc"."song_v2" -> 'phraseSequence'::"text")
                            ELSE '[]'::"jsonb"
                        END) "phrase"("value")
                  WHERE ((COALESCE((("phrase"."value" -> 'section'::"text") ->> 'label'::"text"), ''::"text") <> 'End'::"text") AND (("phrase"."value" #> ARRAY['buses'::"text", 'loops'::"text", "mp"."bus_index", 'tracks'::"text"]) ? "mp"."track_index"))))))
        )
 SELECT "b"."id",
    "b"."market_song_id",
    "b"."song_title",
    "b"."song_slug",
    "b"."display_name",
    "b"."audio_url",
    "b"."waveform",
    "b"."duration_seconds",
    "b"."bpm",
    "b"."key",
    "b"."scale_quality",
    "b"."mood",
    "b"."instrument_name",
    "b"."instrument_family",
        CASE
            WHEN ("b"."primary_match_text" ~* '\m(voice|voices|vox|choir|shout|vocal|female voice)\M'::"text") THEN 'voices-choirs'::"text"
            WHEN ("b"."primary_match_text" ~* '\m(flute|woodwind|woodwinds|wind|winds)\M'::"text") THEN 'woodwinds'::"text"
            WHEN ("b"."primary_match_text" ~* '\m(bass|sub bass|upright bass|throb)\M'::"text") THEN 'bass'::"text"
            WHEN ("b"."primary_match_text" ~* '\m(violin|cello|string|strings|pizz|stacc|staccato|tremolo|quartet)\M'::"text") THEN 'strings'::"text"
            WHEN ("b"."primary_match_text" ~* '\m(guitar|e guitar|twang|strum|pluck|pick)\M'::"text") THEN 'guitar'::"text"
            WHEN ("b"."primary_match_text" ~* '\m(piano|rhodes|keys?)\M'::"text") THEN 'piano-keys'::"text"
            WHEN ("b"."primary_match_text" ~* '\m(mandolin|banjo|ukulele|plucky)\M'::"text") THEN 'plucked-folk'::"text"
            WHEN ("b"."primary_match_text" ~* '\m(celeste|bells?)\M'::"text") THEN 'bells-mallets'::"text"
            WHEN ("b"."primary_match_text" ~* '\m(pad|synth|osc)\M'::"text") THEN 'pads-synths'::"text"
            WHEN ("b"."primary_match_text" ~* '\m(ambience|ambient|lofi|sparkle|sparkles|swell|fx)\M'::"text") THEN 'textures-fx'::"text"
            ELSE 'other'::"text"
        END AS "instrument_family_bucket",
    "b"."pattern_type",
    "b"."creator_name",
    "b"."bus_type",
    "b"."bus_index",
    "b"."track_index",
    "b"."song_config_coordinates",
    "b"."match_text" AS "search_text",
    "b"."updated_at",
    "b"."layer_count",
    "b"."layer_instrument_names",
    "b"."layer_family_buckets"
   FROM "base" "b";


