CREATE TABLE IF NOT EXISTS "public"."sample_playback_cues" (
    "sample_path_construct_id" "uuid" NOT NULL,
    "sync_point_ms" integer,
    "loop_start_offset_ms" integer,
    "loop_end_offset_ms" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "swell_eligible" boolean,
    "crash_eligible" boolean,
    CONSTRAINT "sample_playback_cues_loop_end_offset_ms_check" CHECK ((("loop_end_offset_ms" IS NULL) OR ("loop_end_offset_ms" >= 0))),
    CONSTRAINT "sample_playback_cues_loop_offsets_order_check" CHECK ((("loop_start_offset_ms" IS NULL) OR ("loop_end_offset_ms" IS NULL) OR ("loop_end_offset_ms" > "loop_start_offset_ms"))),
    CONSTRAINT "sample_playback_cues_loop_start_offset_ms_check" CHECK ((("loop_start_offset_ms" IS NULL) OR ("loop_start_offset_ms" >= 0))),
    CONSTRAINT "sample_playback_cues_sync_point_ms_check" CHECK ((("sync_point_ms" IS NULL) OR ("sync_point_ms" >= 0)))
);


ALTER TABLE "public"."sample_playback_cues" OWNER TO "postgres";


COMMENT ON TABLE "public"."sample_playback_cues" IS 'Optional playback cue offsets for production sample_path_constructs rows.';



COMMENT ON COLUMN "public"."sample_playback_cues"."sample_path_construct_id" IS 'Primary key and foreign key to sample_path_constructs.id; one cue profile per production sample construct.';



COMMENT ON COLUMN "public"."sample_playback_cues"."sync_point_ms" IS 'Optional sync point offset in milliseconds from the beginning of the loaded, already-trimmed sample. NULL means no sync cue is configured; 0 is a valid cue at sample start.';



COMMENT ON COLUMN "public"."sample_playback_cues"."loop_start_offset_ms" IS 'Optional loop start offset in milliseconds from the beginning of the loaded, already-trimmed sample.';



COMMENT ON COLUMN "public"."sample_playback_cues"."loop_end_offset_ms" IS 'Optional loop end offset in milliseconds from the beginning of the loaded, already-trimmed sample. Must be greater than loop_start_offset_ms when both are present.';



COMMENT ON COLUMN "public"."sample_playback_cues"."swell_eligible" IS 'Whether this sample is eligible for swell playback behavior. Derived from cue analysis during promotion.';



COMMENT ON COLUMN "public"."sample_playback_cues"."crash_eligible" IS 'Whether this sample is eligible for crash playback behavior. Derived from cue analysis during promotion.';



CREATE OR REPLACE VIEW "public"."producer_instrument_catalog_v1" AS
 WITH "construct_membership" AS (
         SELECT "construct"."instrument_v2_id",
            "count"(*) AS "construct_count",
            "count"(*) FILTER (WHERE (COALESCE("cue"."swell_eligible", false) OR COALESCE("cue"."crash_eligible", false))) AS "cue_eligible_count",
            "bool_and"(("construct"."filename" = 'pitchless'::"text")) AS "all_pitchless"
           FROM ("public"."sample_path_constructs" "construct"
             LEFT JOIN "public"."sample_playback_cues" "cue" ON (("cue"."sample_path_construct_id" = "construct"."id")))
          WHERE ("construct"."instrument_v2_id" IS NOT NULL)
          GROUP BY "construct"."instrument_v2_id"
        )
 SELECT "instrument"."id",
    "instrument"."name",
    "instrument"."engine_type",
    "instrument"."playback_type",
    "instrument"."polyphony_type",
    "instrument"."instrument_family",
    "instrument"."instrument_type",
    "instrument"."contributor_id",
    "instrument"."collection",
    "instrument"."pitch_contents",
    "instrument"."pitch_content_config",
    "instrument"."range_lower",
    "instrument"."range_upper",
    "instrument"."single_pitch",
    "instrument"."gain",
    "instrument"."sustain_crop_time",
    "instrument"."file_path_reference",
    "instrument"."file_name_references",
    "instrument"."velocity_layers",
    "instrument"."articulations",
    "instrument"."effects_instruments",
    "instrument"."mic_positions",
    "instrument"."published",
    "instrument"."created_at",
    "instrument"."updated_at",
    "instrument"."lookup_key",
    "instrument"."round_robins",
    "instrument"."articulation",
    "instrument"."effect",
    "instrument"."original_sample_ids",
    "instrument"."legato_transition",
    "instrument"."filename_variant_map",
    "instrument"."asset_role",
    "instrument"."sampled_midi_notes",
        CASE
            WHEN ((COALESCE(("instrument"."asset_role")::"text", 'playable_sample'::"text") <> 'playable_sample'::"text") OR ("instrument"."playback_type" = 'legato_transition'::"public"."instrument_playback_type")) THEN 'hidden'::"text"
            WHEN (("instrument"."instrument_family" ~~* 'Drum Kit Piece'::"text") AND (COALESCE("membership"."cue_eligible_count", (0)::bigint) > 0)) THEN 'drum_and_cue'::"text"
            WHEN ("instrument"."instrument_family" ~~* 'Drum Kit Piece'::"text") THEN 'drum'::"text"
            WHEN ((COALESCE("membership"."construct_count", (0)::bigint) > 0) AND ("membership"."cue_eligible_count" = "membership"."construct_count") AND "membership"."all_pitchless" AND ("instrument"."engine_type" = 'non_tonal'::"public"."instrument_engine_type") AND ("instrument"."playback_type" = 'oneShot'::"public"."instrument_playback_type")) THEN 'cue_only'::"text"
            WHEN (COALESCE("membership"."cue_eligible_count", (0)::bigint) > 0) THEN 'normal_and_cue'::"text"
            ELSE 'normal'::"text"
        END AS "visibility_role"
   FROM ("public"."instruments_v2" "instrument"
     LEFT JOIN "construct_membership" "membership" ON (("membership"."instrument_v2_id" = "instrument"."id")))
  WHERE ("instrument"."published" = true);


ALTER TABLE "public"."producer_instrument_catalog_v1" OWNER TO "postgres";


COMMENT ON VIEW "public"."producer_instrument_catalog_v1" IS 'Published Instrument V2 catalog with derived normal, cue, drum, and hidden Producer visibility roles.';



CREATE OR REPLACE VIEW "public"."producer_instrument_ordinary_browse_options_v1" AS
 WITH "ordinary" AS (
         SELECT "producer_instrument_catalog_v1"."id",
            "producer_instrument_catalog_v1"."polyphony_type",
            "producer_instrument_catalog_v1"."playback_type"
           FROM "public"."producer_instrument_catalog_v1"
          WHERE ("producer_instrument_catalog_v1"."visibility_role" = ANY (ARRAY['normal'::"text", 'normal_and_cue'::"text"]))
        ), "generic_options" AS (
         SELECT "normalized"."option_group",
            "normalized"."option_key",
            "normalized"."option_label",
            ("count"(DISTINCT "ordinary"."id"))::integer AS "instrument_count"
           FROM ((("ordinary"
             JOIN "public"."instrument_v2_instrument_tags" "link" ON (("link"."instrument_v2_id" = "ordinary"."id")))
             JOIN "public"."instrument_tags" "tag" ON (("tag"."id" = "link"."tag_id")))
             CROSS JOIN LATERAL ( SELECT "public"."sip_normalize_instrument_tag_group"("tag"."tag_group") AS "option_group",
                    "public"."sip_normalize_instrument_tag_name_key"("public"."sip_normalize_instrument_tag_name"("public"."sip_normalize_instrument_tag_group"("tag"."tag_group"), "tag"."tag_name")) AS "option_key",
                    "public"."sip_normalize_instrument_tag_name"("public"."sip_normalize_instrument_tag_group"("tag"."tag_group"), "tag"."tag_name") AS "option_label") "normalized")
          WHERE (("normalized"."option_group" <> ALL (ARRAY['harmType'::"text", 'sampleType'::"text"])) AND ("normalized"."option_key" <> ALL (ARRAY['legacy'::"text", 'potentiallysustainedsampletype'::"text"])) AND (NULLIF("btrim"("normalized"."option_group"), ''::"text") IS NOT NULL) AND (NULLIF("btrim"("normalized"."option_key"), ''::"text") IS NOT NULL) AND (NULLIF("btrim"("normalized"."option_label"), ''::"text") IS NOT NULL))
          GROUP BY "normalized"."option_group", "normalized"."option_key", "normalized"."option_label"
        )
 SELECT 'harmType'::"text" AS "option_group",
    "lower"(("ordinary"."polyphony_type")::"text") AS "option_key",
    ("ordinary"."polyphony_type")::"text" AS "option_label",
    ("count"(*))::integer AS "instrument_count"
   FROM "ordinary"
  WHERE (("ordinary"."polyphony_type" IS NOT NULL) AND (NULLIF("btrim"(("ordinary"."polyphony_type")::"text"), ''::"text") IS NOT NULL))
  GROUP BY "ordinary"."polyphony_type"
UNION ALL
 SELECT 'sampleType'::"text" AS "option_group",
    ("ordinary"."playback_type")::"text" AS "option_key",
        CASE "ordinary"."playback_type"
            WHEN 'oneShot'::"public"."instrument_playback_type" THEN 'One Shot'::"text"
            WHEN 'looped'::"public"."instrument_playback_type" THEN 'Looped'::"text"
            ELSE NULL::"text"
        END AS "option_label",
    ("count"(*))::integer AS "instrument_count"
   FROM "ordinary"
  WHERE (("ordinary"."playback_type" IS NOT NULL) AND (NULLIF("btrim"(("ordinary"."playback_type")::"text"), ''::"text") IS NOT NULL) AND ("ordinary"."playback_type" = ANY (ARRAY['oneShot'::"public"."instrument_playback_type", 'looped'::"public"."instrument_playback_type"])))
  GROUP BY "ordinary"."playback_type"
UNION ALL
 SELECT "generic_options"."option_group",
    "generic_options"."option_key",
    "generic_options"."option_label",
    "generic_options"."instrument_count"
   FROM "generic_options"
  WHERE ("generic_options"."instrument_count" > 0);


