COMMENT ON VIEW "public"."producer_instrument_ordinary_browse_options_v1" IS 'Positive-count ordinary-browse options. Harmony and Playback are column-derived; generic tags exclude derived and internal values.';



CREATE OR REPLACE VIEW "public"."producer_sample_selector_options_v1" AS
 WITH "swell_options" AS (
         SELECT DISTINCT ON ("i"."id") 'swell'::"text" AS "selector_kind",
            "i"."id" AS "instrument_v2_id",
            "i"."name",
            "i"."instrument_family",
            "i"."instrument_type",
            "i"."engine_type",
            "i"."playback_type",
            "i"."collection",
            "i"."contributor_id",
            "c"."slug" AS "contributor_slug",
            "spc"."id" AS "sample_path_construct_id",
            "spc"."sample_original_path_id",
            "spc"."filename",
            "cue"."sync_point_ms",
            "cue"."swell_eligible",
            "cue"."crash_eligible",
            "lib"."duration" AS "duration_seconds",
            "concat_ws"(' '::"text", "i"."name", "i"."instrument_family", "i"."instrument_type", "i"."collection", "c"."slug", "spc"."filename") AS "search_text"
           FROM (((("public"."sample_playback_cues" "cue"
             JOIN "public"."sample_path_constructs" "spc" ON (("spc"."id" = "cue"."sample_path_construct_id")))
             JOIN "public"."instruments_v2" "i" ON (("i"."id" = "spc"."instrument_v2_id")))
             LEFT JOIN "public"."contributors" "c" ON (("c"."id" = "i"."contributor_id")))
             LEFT JOIN "public"."analysis_librosa" "lib" ON (("lib"."sample_id" = "spc"."sample_original_path_id")))
          WHERE (("i"."published" = true) AND ("cue"."swell_eligible" = true))
          ORDER BY "i"."id", "spc"."id"
        ), "crash_options" AS (
         SELECT DISTINCT ON ("i"."id") 'crash'::"text" AS "selector_kind",
            "i"."id" AS "instrument_v2_id",
            "i"."name",
            "i"."instrument_family",
            "i"."instrument_type",
            "i"."engine_type",
            "i"."playback_type",
            "i"."collection",
            "i"."contributor_id",
            "c"."slug" AS "contributor_slug",
            "spc"."id" AS "sample_path_construct_id",
            "spc"."sample_original_path_id",
            "spc"."filename",
            "cue"."sync_point_ms",
            "cue"."swell_eligible",
            "cue"."crash_eligible",
            "lib"."duration" AS "duration_seconds",
            "concat_ws"(' '::"text", "i"."name", "i"."instrument_family", "i"."instrument_type", "i"."collection", "c"."slug", "spc"."filename") AS "search_text"
           FROM (((("public"."sample_playback_cues" "cue"
             JOIN "public"."sample_path_constructs" "spc" ON (("spc"."id" = "cue"."sample_path_construct_id")))
             JOIN "public"."instruments_v2" "i" ON (("i"."id" = "spc"."instrument_v2_id")))
             LEFT JOIN "public"."contributors" "c" ON (("c"."id" = "i"."contributor_id")))
             LEFT JOIN "public"."analysis_librosa" "lib" ON (("lib"."sample_id" = "spc"."sample_original_path_id")))
          WHERE (("i"."published" = true) AND ("cue"."crash_eligible" = true))
          ORDER BY "i"."id", "spc"."id"
        ), "drum_options" AS (
         SELECT DISTINCT ON ("i"."id") 'drum'::"text" AS "selector_kind",
            "i"."id" AS "instrument_v2_id",
            "i"."name",
            "i"."instrument_family",
            "i"."instrument_type",
            "i"."engine_type",
            "i"."playback_type",
            "i"."collection",
            "i"."contributor_id",
            "c"."slug" AS "contributor_slug",
            "spc"."id" AS "sample_path_construct_id",
            "spc"."sample_original_path_id",
            "spc"."filename",
            NULL::integer AS "sync_point_ms",
            NULL::boolean AS "swell_eligible",
            NULL::boolean AS "crash_eligible",
            "lib"."duration" AS "duration_seconds",
            "concat_ws"(' '::"text", "i"."name", "i"."instrument_family", "i"."instrument_type", "i"."collection", "c"."slug", "spc"."filename") AS "search_text"
           FROM ((("public"."instruments_v2" "i"
             LEFT JOIN "public"."contributors" "c" ON (("c"."id" = "i"."contributor_id")))
             JOIN "public"."sample_path_constructs" "spc" ON (("spc"."instrument_v2_id" = "i"."id")))
             LEFT JOIN "public"."analysis_librosa" "lib" ON (("lib"."sample_id" = "spc"."sample_original_path_id")))
          WHERE (("i"."published" = true) AND ("i"."instrument_family" ~~* 'Drum Kit Piece'::"text"))
          ORDER BY "i"."id", "spc"."id"
        )
 SELECT "swell_options"."selector_kind",
    "swell_options"."instrument_v2_id",
    "swell_options"."name",
    "swell_options"."instrument_family",
    "swell_options"."instrument_type",
    "swell_options"."engine_type",
    "swell_options"."playback_type",
    "swell_options"."collection",
    "swell_options"."contributor_id",
    "swell_options"."contributor_slug",
    "swell_options"."sample_path_construct_id",
    "swell_options"."sample_original_path_id",
    "swell_options"."filename",
    "swell_options"."sync_point_ms",
    "swell_options"."swell_eligible",
    "swell_options"."crash_eligible",
    "swell_options"."duration_seconds",
    "swell_options"."search_text"
   FROM "swell_options"
UNION ALL
 SELECT "crash_options"."selector_kind",
    "crash_options"."instrument_v2_id",
    "crash_options"."name",
    "crash_options"."instrument_family",
    "crash_options"."instrument_type",
    "crash_options"."engine_type",
    "crash_options"."playback_type",
    "crash_options"."collection",
    "crash_options"."contributor_id",
    "crash_options"."contributor_slug",
    "crash_options"."sample_path_construct_id",
    "crash_options"."sample_original_path_id",
    "crash_options"."filename",
    "crash_options"."sync_point_ms",
    "crash_options"."swell_eligible",
    "crash_options"."crash_eligible",
    "crash_options"."duration_seconds",
    "crash_options"."search_text"
   FROM "crash_options"
UNION ALL
 SELECT "drum_options"."selector_kind",
    "drum_options"."instrument_v2_id",
    "drum_options"."name",
    "drum_options"."instrument_family",
    "drum_options"."instrument_type",
    "drum_options"."engine_type",
    "drum_options"."playback_type",
    "drum_options"."collection",
    "drum_options"."contributor_id",
    "drum_options"."contributor_slug",
    "drum_options"."sample_path_construct_id",
    "drum_options"."sample_original_path_id",
    "drum_options"."filename",
    "drum_options"."sync_point_ms",
    "drum_options"."swell_eligible",
    "drum_options"."crash_eligible",
    "drum_options"."duration_seconds",
    "drum_options"."search_text"
   FROM "drum_options";


