CREATE OR REPLACE VIEW "public"."round_robin_cue_eligibility_violations_v1" WITH ("security_invoker"='true') AS
 SELECT "construct"."instrument_v2_id",
    "instrument"."name" AS "instrument_name",
    "instrument"."published",
    "construct"."pitch_content",
    "construct"."velocity",
    "construct"."mic_position",
    "construct"."filename",
    "array_agg"("construct"."id" ORDER BY "construct"."round_robin", "construct"."id") AS "sample_path_construct_ids",
    "array_agg"(DISTINCT "construct"."round_robin" ORDER BY "construct"."round_robin") AS "round_robins",
    ("bool_or"(COALESCE("cue"."swell_eligible", false)) <> "bool_and"(COALESCE("cue"."swell_eligible", false))) AS "swell_eligibility_mixed",
    ("bool_or"(COALESCE("cue"."crash_eligible", false)) <> "bool_and"(COALESCE("cue"."crash_eligible", false))) AS "crash_eligibility_mixed",
    "jsonb_agg"("jsonb_build_object"('samplePathConstructId', "construct"."id", 'roundRobin', "construct"."round_robin", 'swellEligible', COALESCE("cue"."swell_eligible", false), 'crashEligible', COALESCE("cue"."crash_eligible", false), 'cueRowPresent', ("cue"."sample_path_construct_id" IS NOT NULL)) ORDER BY "construct"."round_robin", "construct"."id") AS "construct_evidence"
   FROM (("public"."sample_path_constructs" "construct"
     JOIN "public"."instruments_v2" "instrument" ON (("instrument"."id" = "construct"."instrument_v2_id")))
     LEFT JOIN "public"."sample_playback_cues" "cue" ON (("cue"."sample_path_construct_id" = "construct"."id")))
  GROUP BY "construct"."instrument_v2_id", "instrument"."name", "instrument"."published", "construct"."pitch_content", "construct"."velocity", "construct"."mic_position", "construct"."filename"
 HAVING (("count"(DISTINCT "construct"."round_robin") > 1) AND (("bool_or"(COALESCE("cue"."swell_eligible", false)) <> "bool_and"(COALESCE("cue"."swell_eligible", false))) OR ("bool_or"(COALESCE("cue"."crash_eligible", false)) <> "bool_and"(COALESCE("cue"."crash_eligible", false)))));


ALTER TABLE "public"."round_robin_cue_eligibility_violations_v1" OWNER TO "postgres";


