    "split_parent_sip_review_instrument_id" "uuid",
    "staged_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "staged_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "round_robins" "jsonb" DEFAULT '{"0/0": [0]}'::"jsonb" NOT NULL,
    "velocity_layer_map" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "articulation" "text",
    "effect" "text",
    "identity_hash" "text",
    "legato_transition" "uuid",
    "asset_role" "public"."instrument_asset_role" DEFAULT 'playable_sample'::"public"."instrument_asset_role" NOT NULL,
    "completion_projection_id" "uuid",
    CONSTRAINT "sip_review_instrument_legato_not_effect_relationship" CHECK ((("legato_transition" IS NULL) OR (NULLIF("btrim"("effect"), ''::"text") IS NULL))),
    CONSTRAINT "sip_review_instrument_legato_transition_child_leaf" CHECK ((("playback_type" IS NULL) OR (("playback_type")::"text" <> 'legato_transition'::"text") OR (("legato_transition" IS NULL) AND (NULLIF("btrim"("effect"), ''::"text") IS NULL) AND ("split_parent_sip_review_instrument_id" IS NULL)))),
    CONSTRAINT "sip_review_instrument_legato_transition_not_self" CHECK ((("legato_transition" IS NULL) OR ("legato_transition" <> "id"))),
    CONSTRAINT "sip_review_instrument_publish_requires_taxonomy" CHECK (((NOT "published") OR ((NULLIF("btrim"("instrument_family"), ''::"text") IS NOT NULL) AND (NULLIF("btrim"("instrument_type"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "sip_review_instrument_valid_range" CHECK (("range_lower" <= "range_upper")),
    CONSTRAINT "sip_review_instrument_valid_range_midi" CHECK ((("range_lower" >= 0) AND ("range_upper" <= 127)))
);


