);


ALTER TABLE "public"."sip_review_sample_disposition" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sip_completion_observed_membership_v1" WITH ("security_invoker"='true') AS
 WITH "review_array" AS (
         SELECT "review"."completion_projection_id",
            "source_id"."source_id" AS "sample_original_path_id",
            "bool_or"((NOT "review"."is_retired")) AS "observed_active_review",
            "bool_or"("review"."is_retired") AS "observed_retired_review",
            "count"(*) FILTER (WHERE (NOT "review"."is_retired")) AS "active_review_count",
            "count"(*) FILTER (WHERE "review"."is_retired") AS "retired_review_count"
           FROM ("public"."sip_review_instrument" "review"
             CROSS JOIN LATERAL "unnest"(COALESCE("review"."original_sample_ids", '{}'::"uuid"[])) "source_id"("source_id"))
          WHERE ("review"."completion_projection_id" IS NOT NULL)
          GROUP BY "review"."completion_projection_id", "source_id"."source_id"
        ), "scope_rows" AS (
         SELECT "review"."completion_projection_id",
            "scope"."original_sample_id" AS "sample_original_path_id",
            true AS "observed_in_scope_projection"
           FROM ("public"."sip_review_instrument_sample_scope" "scope"
             JOIN "public"."sip_review_instrument" "review" ON (("review"."id" = "scope"."sip_review_instrument_id")))
          WHERE (("review"."completion_projection_id" IS NOT NULL) AND ("scope"."original_sample_id" IS NOT NULL))
          GROUP BY "review"."completion_projection_id", "scope"."original_sample_id"
        ), "legacy_disposition" AS (
         SELECT "review"."completion_projection_id",
            "disposition"."original_sample_id" AS "sample_original_path_id",
                CASE
                    WHEN ("count"(DISTINCT "disposition"."disposition") > 1) THEN 'conflicting'::"text"
                    WHEN ("min"("disposition"."disposition") = 'deferred_provenance'::"text") THEN 'deferred'::"text"
                    WHEN ("min"("disposition"."disposition") = 'ignored_provenance'::"text") THEN 'ignored'::"text"
                    ELSE NULL::"text"
                END AS "legacy_disposition_decision"
           FROM ("public"."sip_review_sample_disposition" "disposition"
             JOIN "public"."sip_review_instrument" "review" ON (("review"."id" = "disposition"."sip_review_instrument_id")))
          WHERE ("review"."completion_projection_id" IS NOT NULL)
          GROUP BY "review"."completion_projection_id", "disposition"."original_sample_id"
        ), "production" AS (
         SELECT "projection"."id" AS "completion_projection_id",
            "construct"."sample_original_path_id",
            true AS "observed_in_production"
           FROM ("public"."sip_completion_projection" "projection"
             JOIN "public"."sample_path_constructs" "construct" ON (("construct"."instrument_v2_id" = "projection"."current_instrument_v2_id")))
          GROUP BY "projection"."id", "construct"."sample_original_path_id"
        ), "keys" AS (
         SELECT "review_array_1"."completion_projection_id",
            "review_array_1"."sample_original_path_id"
           FROM "review_array" "review_array_1"
        UNION
         SELECT "scope_rows_1"."completion_projection_id",
            "scope_rows_1"."sample_original_path_id"
           FROM "scope_rows" "scope_rows_1"
        UNION
         SELECT "legacy_disposition_1"."completion_projection_id",
            "legacy_disposition_1"."sample_original_path_id"
           FROM "legacy_disposition" "legacy_disposition_1"
        UNION
         SELECT "production_1"."completion_projection_id",
            "production_1"."sample_original_path_id"
           FROM "production" "production_1"
        )
 SELECT "keys"."completion_projection_id",
    "keys"."sample_original_path_id",
    ("review_array"."completion_projection_id" IS NOT NULL) AS "observed_in_review_array",
    ("scope_rows"."completion_projection_id" IS NOT NULL) AS "observed_in_scope_projection",
    ("legacy_disposition"."completion_projection_id" IS NOT NULL) AS "observed_in_legacy_disposition",
    ("production"."completion_projection_id" IS NOT NULL) AS "observed_in_production",
    COALESCE("review_array"."active_review_count", (0)::bigint) AS "active_review_count",
    COALESCE("review_array"."retired_review_count", (0)::bigint) AS "retired_review_count",
    COALESCE("review_array"."observed_active_review", false) AS "observed_active_review",
    COALESCE("review_array"."observed_retired_review", false) AS "observed_retired_review",
    "legacy_disposition"."legacy_disposition_decision",
    (("review_array"."completion_projection_id" IS NOT NULL) AND ("scope_rows"."completion_projection_id" IS NULL)) AS "scope_projection_missing",
    (("review_array"."completion_projection_id" IS NULL) AND ("scope_rows"."completion_projection_id" IS NOT NULL)) AS "scope_projection_extra",
    (EXISTS ( SELECT 1
           FROM ("public"."sample_path_constructs" "other_construct"
             JOIN "public"."sip_completion_projection" "other_projection" ON (("other_projection"."current_instrument_v2_id" = "other_construct"."instrument_v2_id")))
          WHERE (("other_construct"."sample_original_path_id" = "keys"."sample_original_path_id") AND ("other_projection"."id" <> "keys"."completion_projection_id")))) AS "production_projection_conflict",
    (("legacy_disposition"."legacy_disposition_decision" IS NOT NULL) AND (COALESCE("review_array"."observed_active_review", false) OR ("production"."completion_projection_id" IS NOT NULL))) AS "legacy_disposition_conflict"
   FROM (((("keys"
     LEFT JOIN "review_array" USING ("completion_projection_id", "sample_original_path_id"))
     LEFT JOIN "scope_rows" USING ("completion_projection_id", "sample_original_path_id"))
     LEFT JOIN "legacy_disposition" USING ("completion_projection_id", "sample_original_path_id"))
     LEFT JOIN "production" USING ("completion_projection_id", "sample_original_path_id"));


ALTER TABLE "public"."sip_completion_observed_membership_v1" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_completion_projection_membership" (
    "completion_projection_id" "uuid" NOT NULL,
    "sample_original_path_id" "uuid" NOT NULL,
    "is_intended" boolean DEFAULT false NOT NULL,
    "membership_decision" "text" DEFAULT 'undecided'::"text" NOT NULL,
    "canonical_sample_original_path_id" "uuid",
    "decision_reason" "text",
    "decision_evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "decided_by" "text",
    "decided_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sip_completion_projection_membership_canonical_check" CHECK (((("membership_decision" = ANY (ARRAY['duplicate'::"text", 'superseded'::"text"])) AND ("canonical_sample_original_path_id" IS NOT NULL) AND ("canonical_sample_original_path_id" <> "sample_original_path_id")) OR (("membership_decision" <> ALL (ARRAY['duplicate'::"text", 'superseded'::"text"])) AND ("canonical_sample_original_path_id" IS NULL)))),
    CONSTRAINT "sip_completion_projection_membership_membership_decision_check" CHECK (("membership_decision" = ANY (ARRAY['undecided'::"text", 'active'::"text", 'retired'::"text", 'deferred'::"text", 'ignored'::"text", 'duplicate'::"text", 'superseded'::"text", 'rights_held'::"text", 'out_of_scope'::"text", 'conflicting'::"text"]))),
    CONSTRAINT "sip_completion_projection_membership_nonempty_check" CHECK (("is_intended" OR ("membership_decision" <> 'undecided'::"text"))),
    CONSTRAINT "sip_completion_projection_membership_terminal_evidence_check" CHECK ((("membership_decision" = ANY (ARRAY['undecided'::"text", 'active'::"text", 'conflicting'::"text"])) OR ((NULLIF("btrim"("decision_reason"), ''::"text") IS NOT NULL) AND ("decision_evidence" <> '{}'::"jsonb") AND (NULLIF("btrim"("decided_by"), ''::"text") IS NOT NULL) AND ("decided_at" IS NOT NULL))))
);


ALTER TABLE "public"."sip_completion_projection_membership" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sip_completion_projection_membership_v1" WITH ("security_invoker"='true') AS
 WITH "keys" AS (
         SELECT "sip_completion_projection_membership"."completion_projection_id",
            "sip_completion_projection_membership"."sample_original_path_id"
           FROM "public"."sip_completion_projection_membership"
        UNION
         SELECT "sip_completion_observed_membership_v1"."completion_projection_id",
            "sip_completion_observed_membership_v1"."sample_original_path_id"
           FROM "public"."sip_completion_observed_membership_v1"
        ), "combined" AS (
         SELECT "keys"."completion_projection_id",
            "keys"."sample_original_path_id",
            COALESCE("explicit"."is_intended", false) AS "is_intended",
            ("observed"."completion_projection_id" IS NOT NULL) AS "is_observed",
            COALESCE("explicit"."membership_decision", 'undecided'::"text") AS "declared_decision",
                CASE
                    WHEN ("observed"."legacy_disposition_decision" IS NOT NULL) THEN "observed"."legacy_disposition_decision"
                    WHEN (COALESCE("observed"."observed_active_review", false) OR COALESCE("observed"."observed_in_production", false)) THEN 'active'::"text"
                    WHEN COALESCE("observed"."observed_retired_review", false) THEN 'retired'::"text"
                    ELSE 'undecided'::"text"
                END AS "observed_decision",
            "explicit"."canonical_sample_original_path_id",
            COALESCE("observed"."scope_projection_missing", false) AS "scope_projection_missing",
            COALESCE("observed"."scope_projection_extra", false) AS "scope_projection_extra",
            COALESCE("observed"."production_projection_conflict", false) AS "production_projection_conflict",
            (COALESCE("observed"."legacy_disposition_conflict", false) OR (("explicit"."membership_decision" = ANY (ARRAY['retired'::"text", 'deferred'::"text", 'ignored'::"text", 'duplicate'::"text", 'superseded'::"text", 'rights_held'::"text", 'out_of_scope'::"text"])) AND (COALESCE("observed"."observed_active_review", false) OR COALESCE("observed"."observed_in_production", false))) OR (("explicit"."membership_decision" = 'active'::"text") AND ("observed"."legacy_disposition_decision" = ANY (ARRAY['retired'::"text", 'deferred'::"text", 'ignored'::"text"])))) AS "evidence_conflict"
           FROM (("keys"
             LEFT JOIN "public"."sip_completion_projection_membership" "explicit" USING ("completion_projection_id", "sample_original_path_id"))
             LEFT JOIN "public"."sip_completion_observed_membership_v1" "observed" USING ("completion_projection_id", "sample_original_path_id"))
        )
 SELECT "combined"."completion_projection_id",
    "combined"."sample_original_path_id",
    "combined"."is_intended",
    "combined"."is_observed",
    "combined"."declared_decision",
    "combined"."observed_decision",
    "combined"."canonical_sample_original_path_id",
    "combined"."scope_projection_missing",
    "combined"."scope_projection_extra",
    "combined"."production_projection_conflict",
    "combined"."evidence_conflict",
        CASE
            WHEN ("combined"."evidence_conflict" OR "combined"."production_projection_conflict") THEN 'conflicting'::"text"
            WHEN ("combined"."declared_decision" <> 'undecided'::"text") THEN "combined"."declared_decision"
            ELSE "combined"."observed_decision"
        END AS "effective_decision",
    (
        CASE
            WHEN ("combined"."evidence_conflict" OR "combined"."production_projection_conflict") THEN 'conflicting'::"text"
            WHEN ("combined"."declared_decision" <> 'undecided'::"text") THEN "combined"."declared_decision"
            ELSE "combined"."observed_decision"
        END <> ALL (ARRAY['undecided'::"text", 'conflicting'::"text"])) AS "decision_final",
    (
        CASE
            WHEN ("combined"."evidence_conflict" OR "combined"."production_projection_conflict") THEN 'conflicting'::"text"
            WHEN ("combined"."declared_decision" <> 'undecided'::"text") THEN "combined"."declared_decision"
            ELSE "combined"."observed_decision"
        END = ANY (ARRAY['retired'::"text", 'deferred'::"text", 'ignored'::"text", 'duplicate'::"text", 'superseded'::"text", 'rights_held'::"text", 'out_of_scope'::"text"])) AS "membership_terminal",
    (
        CASE
            WHEN ("combined"."evidence_conflict" OR "combined"."production_projection_conflict") THEN 'conflicting'::"text"
            WHEN ("combined"."declared_decision" <> 'undecided'::"text") THEN "combined"."declared_decision"
            ELSE "combined"."observed_decision"
        END = 'active'::"text") AS "delivery_required"
   FROM "combined";


ALTER TABLE "public"."sip_completion_projection_membership_v1" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sip_completion_projection_delivery_v1" WITH ("security_invoker"='true') AS
 WITH "membership" AS (
         SELECT "sip_completion_projection_membership_v1"."completion_projection_id",
            "count"(*) FILTER (WHERE "sip_completion_projection_membership_v1"."delivery_required") AS "active_membership_count",
            "count"(*) FILTER (WHERE ("sip_completion_projection_membership_v1"."is_intended" AND "sip_completion_projection_membership_v1"."delivery_required")) AS "active_intended_membership_count"
           FROM "public"."sip_completion_projection_membership_v1"
          GROUP BY "sip_completion_projection_membership_v1"."completion_projection_id"
        ), "coverage" AS (
         SELECT "member"."completion_projection_id",
            "count"(*) FILTER (WHERE ("construct"."instrument_v2_id" = "projection_1"."current_instrument_v2_id")) AS "covered_construct_count",
            "count"(*) FILTER (WHERE ("construct"."id" IS NULL)) AS "missing_construct_count",
            "count"(*) FILTER (WHERE (("construct"."id" IS NOT NULL) AND ("construct"."instrument_v2_id" IS DISTINCT FROM "projection_1"."current_instrument_v2_id"))) AS "foreign_construct_count"
           FROM (("public"."sip_completion_projection_membership_v1" "member"
             JOIN "public"."sip_completion_projection" "projection_1" ON (("projection_1"."id" = "member"."completion_projection_id")))
             LEFT JOIN "public"."sample_path_constructs" "construct" ON (("construct"."sample_original_path_id" = "member"."sample_original_path_id")))
          WHERE "member"."delivery_required"
          GROUP BY "member"."completion_projection_id"
        ), "latest_readiness" AS (
         SELECT DISTINCT ON ("instrument_v2_deterministic_readiness"."instrument_v2_id") "instrument_v2_deterministic_readiness"."instrument_v2_id",
            "instrument_v2_deterministic_readiness"."status",
            "instrument_v2_deterministic_readiness"."snapshot_sha256"
           FROM "public"."instrument_v2_deterministic_readiness"
          ORDER BY "instrument_v2_deterministic_readiness"."instrument_v2_id", "instrument_v2_deterministic_readiness"."updated_at" DESC, "instrument_v2_deterministic_readiness"."id" DESC
        ), "manifest" AS (
         SELECT "instrument_v2_publish_output_manifest"."instrument_v2_id",
            "count"(*) AS "manifest_output_count",
            "count"(*) FILTER (WHERE (("instrument_v2_publish_output_manifest"."fingerprint_schema" = 'sip-v2-output-v2'::"text") AND ("instrument_v2_publish_output_manifest"."output_object_identity" IS NOT NULL))) AS "manifest_v2_receipt_count"
           FROM "public"."instrument_v2_publish_output_manifest"
          GROUP BY "instrument_v2_publish_output_manifest"."instrument_v2_id"
        )
 SELECT "projection"."id" AS "completion_projection_id",
    "projection"."provider_scope_key",
    "projection"."projection_key",
    "projection"."projection_decision",
    "projection"."current_instrument_v2_id" AS "target_instrument_v2_id",
    COALESCE("membership"."active_membership_count", (0)::bigint) AS "active_membership_count",
    COALESCE("coverage"."covered_construct_count", (0)::bigint) AS "covered_construct_count",
    COALESCE("coverage"."missing_construct_count", (0)::bigint) AS "missing_construct_count",
    COALESCE("coverage"."foreign_construct_count", (0)::bigint) AS "foreign_construct_count",
        CASE
            WHEN ("instrument"."id" IS NULL) THEN 'missing'::"text"
            WHEN "instrument"."published" THEN 'published'::"text"
            ELSE 'unpublished'::"text"
        END AS "publish_status",
    COALESCE("upload"."publish_status", 'missing'::"text") AS "upload_status",
    "latest_readiness"."status" AS "readiness_status",
    "latest_readiness"."snapshot_sha256" AS "readiness_snapshot_sha256",
    false AS "readiness_current",
    COALESCE("manifest"."manifest_output_count", (0)::bigint) AS "manifest_output_count",
    COALESCE("manifest"."manifest_v2_receipt_count", (0)::bigint) AS "manifest_v2_receipt_count",
        CASE
            WHEN ((COALESCE("manifest"."manifest_output_count", (0)::bigint) > 0) AND ("manifest"."manifest_output_count" = "manifest"."manifest_v2_receipt_count")) THEN 'receipt_present_not_object_reverified'::"text"
            ELSE 'incomplete'::"text"
        END AS "object_receipt_status",
    COALESCE("upload"."runtime_verification_status", 'missing'::"text") AS "runtime_status",
    false AS "runtime_exception_current",
    'not_evaluated'::"text" AS "analysis_status",
    'not_evaluated'::"text" AS "audio_profile_status",
    'not_evaluated'::"text" AS "anchor_status",
    false AS "delivery_complete",
    "array_remove"(ARRAY[
        CASE
            WHEN ("projection"."projection_decision" <> 'active'::"text") THEN 'projection_not_active'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("membership"."active_membership_count", (0)::bigint) = 0) THEN 'no_active_membership'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("coverage"."missing_construct_count", (0)::bigint) > 0) THEN 'missing_construct'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("coverage"."foreign_construct_count", (0)::bigint) > 0) THEN 'foreign_construct'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (NOT COALESCE("instrument"."published", false)) THEN 'not_published'::"text"
            ELSE NULL::"text"
        END, 'exact_currentness_not_evaluated'::"text"], NULL::"text") AS "delivery_blockers"
   FROM (((((("public"."sip_completion_projection" "projection"
     LEFT JOIN "membership" ON (("membership"."completion_projection_id" = "projection"."id")))
     LEFT JOIN "coverage" ON (("coverage"."completion_projection_id" = "projection"."id")))
     LEFT JOIN "public"."instruments_v2" "instrument" ON (("instrument"."id" = "projection"."current_instrument_v2_id")))
     LEFT JOIN "public"."instrument_v2_upload_status" "upload" ON (("upload"."instrument_v2_id" = "projection"."current_instrument_v2_id")))
     LEFT JOIN "latest_readiness" ON (("latest_readiness"."instrument_v2_id" = "projection"."current_instrument_v2_id")))
     LEFT JOIN "manifest" ON (("manifest"."instrument_v2_id" = "projection"."current_instrument_v2_id")));


ALTER TABLE "public"."sip_completion_projection_delivery_v1" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_completion_source" (
    "sample_original_path_id" "uuid" NOT NULL,
    "canonical_provider_key" "text",
    "canonical_contributor_id" "uuid",
    "ownership_status" "text" DEFAULT 'unresolved'::"text" NOT NULL,
    "ownership_resolution_version" "text",
    "ownership_evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "rights_status" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "rights_resolution_version" "text",
    "rights_provenance_ref" "text",
    "rights_evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "admission_status" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "global_disposition" "text" DEFAULT 'open'::"text" NOT NULL,
    "canonical_sample_original_path_id" "uuid",
    "decision_reason" "text",
    "decision_evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "decided_by" "text",
    "decided_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "origin_exception_classification" "text",
    "origin_exception_evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "projection_assignment_status" "text" DEFAULT 'unresolved'::"text" NOT NULL,
    "projection_assignment_evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "projection_assignment_decided_by" "text",
    "projection_assignment_decided_at" timestamp with time zone,
    CONSTRAINT "sip_completion_source_admission_status_check" CHECK (("admission_status" = ANY (ARRAY['unknown'::"text", 'in_scope'::"text", 'held'::"text", 'out_of_scope'::"text", 'conflicting'::"text"]))),
    CONSTRAINT "sip_completion_source_canonical_target_check" CHECK (((("global_disposition" = ANY (ARRAY['duplicate'::"text", 'superseded'::"text"])) AND ("canonical_sample_original_path_id" IS NOT NULL) AND ("canonical_sample_original_path_id" <> "sample_original_path_id")) OR (("global_disposition" <> ALL (ARRAY['duplicate'::"text", 'superseded'::"text"])) AND ("canonical_sample_original_path_id" IS NULL)))),
    CONSTRAINT "sip_completion_source_global_disposition_check" CHECK (("global_disposition" = ANY (ARRAY['open'::"text", 'retired'::"text", 'deferred'::"text", 'ignored'::"text", 'duplicate'::"text", 'superseded'::"text", 'rights_held'::"text", 'out_of_scope'::"text", 'conflicting'::"text"]))),
    CONSTRAINT "sip_completion_source_origin_exception_classification_check" CHECK (("origin_exception_classification" = ANY (ARRAY['stale_generated_output'::"text", 'lineage_missing_live'::"text", 'generated_origin_owner_and_donor_unresolved'::"text"]))),
    CONSTRAINT "sip_completion_source_origin_exception_evidence_check" CHECK ((("jsonb_typeof"("origin_exception_evidence") = 'object'::"text") AND (("origin_exception_classification" IS NULL) OR ("origin_exception_evidence" <> '{}'::"jsonb")))),
    CONSTRAINT "sip_completion_source_ownership_check" CHECK (((("ownership_status" = 'resolved'::"text") AND (NULLIF("btrim"("canonical_provider_key"), ''::"text") IS NOT NULL)) OR (("ownership_status" = ANY (ARRAY['unresolved'::"text", 'conflicting'::"text"])) AND ("canonical_provider_key" IS NULL) AND ("canonical_contributor_id" IS NULL)))),
    CONSTRAINT "sip_completion_source_ownership_status_check" CHECK (("ownership_status" = ANY (ARRAY['unresolved'::"text", 'resolved'::"text", 'conflicting'::"text"]))),
    CONSTRAINT "sip_completion_source_projection_assignment_evidence_check" CHECK ((("projection_assignment_status" = 'unresolved'::"text") OR (("projection_assignment_evidence" <> '{}'::"jsonb") AND (NULLIF("btrim"("projection_assignment_decided_by"), ''::"text") IS NOT NULL) AND ("projection_assignment_decided_at" IS NOT NULL)))),
    CONSTRAINT "sip_completion_source_projection_assignment_status_check" CHECK (("projection_assignment_status" = ANY (ARRAY['unresolved'::"text", 'assigned'::"text", 'deferred'::"text", 'not_applicable'::"text"]))),
    CONSTRAINT "sip_completion_source_rights_status_check" CHECK (("rights_status" = ANY (ARRAY['unknown'::"text", 'legacy_allowed_unverified'::"text", 'legacy_blocked_unverified'::"text", 'verified_allowed'::"text", 'verified_restricted'::"text", 'conflicting'::"text"]))),
    CONSTRAINT "sip_completion_source_terminal_evidence_check" CHECK ((("global_disposition" = ANY (ARRAY['open'::"text", 'conflicting'::"text"])) OR ((NULLIF("btrim"("decision_reason"), ''::"text") IS NOT NULL) AND ("decision_evidence" <> '{}'::"jsonb") AND (NULLIF("btrim"("decided_by"), ''::"text") IS NOT NULL) AND ("decided_at" IS NOT NULL)))),
    CONSTRAINT "sip_completion_source_verified_rights_check" CHECK ((("rights_status" <> ALL (ARRAY['verified_allowed'::"text", 'verified_restricted'::"text"])) OR ((NULLIF("btrim"("rights_provenance_ref"), ''::"text") IS NOT NULL) AND ("rights_evidence" <> '{}'::"jsonb") AND (NULLIF("btrim"("decided_by"), ''::"text") IS NOT NULL) AND ("decided_at" IS NOT NULL))))
);


ALTER TABLE "public"."sip_completion_source" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sip_fleet_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_slug" "text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "plan_artifact_id" "uuid" NOT NULL,
    "submitted_by" "text" NOT NULL,
    "provider_lease_id" "uuid" NOT NULL,
    "provider_lease_token" "uuid" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "cancel_requested" boolean DEFAULT false NOT NULL,
    "cancel_reason" "text",
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "result_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "admission_fingerprint" "text",
    CONSTRAINT "sip_fleet_runs_idempotency_key_check" CHECK (("btrim"("idempotency_key") <> ''::"text")),
    CONSTRAINT "sip_fleet_runs_provider_slug_check" CHECK (("btrim"("provider_slug") <> ''::"text")),
    CONSTRAINT "sip_fleet_runs_result_payload_check" CHECK (("jsonb_typeof"("result_payload") = 'object'::"text")),
    CONSTRAINT "sip_fleet_runs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'completed'::"text", 'failed'::"text", 'canceled'::"text"]))),
    CONSTRAINT "sip_fleet_runs_submitted_by_check" CHECK (("btrim"("submitted_by") <> ''::"text"))
);


ALTER TABLE "public"."sip_fleet_runs" OWNER TO "postgres";


COMMENT ON TABLE "public"."sip_fleet_runs" IS 'Durable provider-scoped publish coordination runs.';



CREATE OR REPLACE VIEW "public"."sip_completion_provider_status_v1" WITH ("security_invoker"='true') AS
 WITH "scopes" AS (
         SELECT "sip_completion_source"."canonical_provider_key" AS "provider_scope_key"
           FROM "public"."sip_completion_source"
          WHERE ("sip_completion_source"."canonical_provider_key" IS NOT NULL)
        UNION
         SELECT "sip_completion_projection"."provider_scope_key"
           FROM "public"."sip_completion_projection"
        UNION
         SELECT "sip_completion_projection_registry"."provider_scope_key"
           FROM "public"."sip_completion_projection_registry"
        ), "latest_receipt" AS (
         SELECT "receipt"."id",
            "receipt"."inventory_location",
            "receipt"."inventory_version",
            "receipt"."normalization_version",
            "receipt"."origin_main_sha",
            "receipt"."production_observed_at",
            "receipt"."inventory_count",
            "receipt"."database_count",
            "receipt"."matched_count",
            "receipt"."inventory_only_count",
            "receipt"."database_only_count",
            "receipt"."inventory_sorted_path_sha256",
            "receipt"."database_sorted_path_sha256",
            "receipt"."result",
            "receipt"."evidence",
            "receipt"."created_by",
            "receipt"."created_at",
            (("receipt"."result" = 'matched'::"text") AND ("receipt"."database_count" = ( SELECT "count"(*) AS "count"
                   FROM "public"."samples_original_paths")) AND (NOT (EXISTS ( SELECT 1
                   FROM ("public"."samples_original_paths" "current_source"
                     LEFT JOIN "public"."sip_completion_inventory_item" "current_item" ON ((("current_item"."receipt_id" = "receipt"."id") AND ("current_item"."sample_original_path_id" = "current_source"."id"))))
                  WHERE (("current_item"."parity_status" IS DISTINCT FROM 'matched'::"text") OR ("current_item"."normalized_path" IS DISTINCT FROM "current_source"."s3_path")))))) AS "inventory_receipt_current"
           FROM "public"."sip_completion_inventory_receipt" "receipt"
          ORDER BY "receipt"."production_observed_at" DESC, "receipt"."created_at" DESC, "receipt"."id" DESC
         LIMIT 1
        ), "registry_state" AS (
         SELECT "registry"."id",
            "registry"."provider_scope_key",
            "registry"."version",
            "registry"."status",
            "registry"."inventory_receipt_id",
            "registry"."origin_main_sha",
            "registry"."production_observed_at",
            "registry"."normalization_version",
            "registry"."source_count",
            "registry"."intended_projection_count",
            "registry"."intended_membership_count",
            "registry"."source_identity_sha256",
            "registry"."projection_identity_sha256",
            "registry"."membership_identity_sha256",
            "registry"."evidence",
            "registry"."created_by",
            "registry"."created_at",
            "registry"."frozen_by",
            "registry"."frozen_at",
            "registry"."superseded_at",
            (("registry"."source_count" = ( SELECT "count"(*) AS "count"
                   FROM "public"."sip_completion_source" "source"
                  WHERE ("source"."canonical_provider_key" = "registry"."provider_scope_key"))) AND ("registry"."intended_projection_count" = ( SELECT "count"(*) AS "count"
                   FROM "public"."sip_completion_projection" "projection"
                  WHERE (("projection"."provider_scope_key" = "registry"."provider_scope_key") AND "projection"."is_intended"))) AND ("registry"."intended_membership_count" = ( SELECT "count"(*) AS "count"
                   FROM ("public"."sip_completion_projection_membership" "membership"
                     JOIN "public"."sip_completion_projection" "projection" ON (("projection"."id" = "membership"."completion_projection_id")))
                  WHERE (("projection"."provider_scope_key" = "registry"."provider_scope_key") AND "membership"."is_intended"))) AND ("registry"."source_identity_sha256" = "public"."sip_completion_identity_digest_v1"(ARRAY( SELECT ("source"."sample_original_path_id")::"text" AS "sample_original_path_id"
                   FROM "public"."sip_completion_source" "source"
                  WHERE ("source"."canonical_provider_key" = "registry"."provider_scope_key")
                  ORDER BY ("source"."sample_original_path_id")::"text"))) AND ("registry"."projection_identity_sha256" = "public"."sip_completion_identity_digest_v1"(ARRAY( SELECT "projection"."projection_key"
                   FROM "public"."sip_completion_projection" "projection"
                  WHERE (("projection"."provider_scope_key" = "registry"."provider_scope_key") AND "projection"."is_intended")
                  ORDER BY ("projection"."projection_key" COLLATE "C")))) AND ("registry"."membership_identity_sha256" = "public"."sip_completion_identity_digest_v1"(ARRAY( SELECT (("projection"."projection_key" || '/'::"text") || "membership"."sample_original_path_id")
                   FROM ("public"."sip_completion_projection_membership" "membership"
                     JOIN "public"."sip_completion_projection" "projection" ON (("projection"."id" = "membership"."completion_projection_id")))
                  WHERE (("projection"."provider_scope_key" = "registry"."provider_scope_key") AND "membership"."is_intended")
                  ORDER BY ("projection"."projection_key" COLLATE "C"), "membership"."sample_original_path_id")))) AS "current_by_count"
           FROM "public"."sip_completion_projection_registry" "registry"
          WHERE ("registry"."status" = 'frozen'::"text")
        ), "membership_rows" AS MATERIALIZED (
         SELECT "sip_completion_projection_membership_v1"."completion_projection_id",
            "sip_completion_projection_membership_v1"."sample_original_path_id",
            "sip_completion_projection_membership_v1"."is_intended",
            "sip_completion_projection_membership_v1"."is_observed",
            "sip_completion_projection_membership_v1"."declared_decision",
            "sip_completion_projection_membership_v1"."observed_decision",
            "sip_completion_projection_membership_v1"."canonical_sample_original_path_id",
            "sip_completion_projection_membership_v1"."scope_projection_missing",
            "sip_completion_projection_membership_v1"."scope_projection_extra",
            "sip_completion_projection_membership_v1"."production_projection_conflict",
            "sip_completion_projection_membership_v1"."evidence_conflict",
            "sip_completion_projection_membership_v1"."effective_decision",
            "sip_completion_projection_membership_v1"."decision_final",
            "sip_completion_projection_membership_v1"."membership_terminal",
            "sip_completion_projection_membership_v1"."delivery_required"
           FROM "public"."sip_completion_projection_membership_v1"
        ), "accounted_sources" AS MATERIALIZED (
         SELECT DISTINCT "projection"."provider_scope_key",
            "membership"."sample_original_path_id"
           FROM ("membership_rows" "membership"
             JOIN "public"."sip_completion_projection" "projection" ON (("projection"."id" = "membership"."completion_projection_id")))
          WHERE "membership"."decision_final"
        ), "delivery_rows" AS MATERIALIZED (
         SELECT "sip_completion_projection_delivery_v1"."completion_projection_id",
            "sip_completion_projection_delivery_v1"."provider_scope_key",
            "sip_completion_projection_delivery_v1"."projection_key",
            "sip_completion_projection_delivery_v1"."projection_decision",
            "sip_completion_projection_delivery_v1"."target_instrument_v2_id",
            "sip_completion_projection_delivery_v1"."active_membership_count",
            "sip_completion_projection_delivery_v1"."covered_construct_count",
            "sip_completion_projection_delivery_v1"."missing_construct_count",
            "sip_completion_projection_delivery_v1"."foreign_construct_count",
            "sip_completion_projection_delivery_v1"."publish_status",
            "sip_completion_projection_delivery_v1"."upload_status",
            "sip_completion_projection_delivery_v1"."readiness_status",
            "sip_completion_projection_delivery_v1"."readiness_snapshot_sha256",
            "sip_completion_projection_delivery_v1"."readiness_current",
            "sip_completion_projection_delivery_v1"."manifest_output_count",
            "sip_completion_projection_delivery_v1"."manifest_v2_receipt_count",
            "sip_completion_projection_delivery_v1"."object_receipt_status",
            "sip_completion_projection_delivery_v1"."runtime_status",
            "sip_completion_projection_delivery_v1"."runtime_exception_current",
            "sip_completion_projection_delivery_v1"."analysis_status",
            "sip_completion_projection_delivery_v1"."audio_profile_status",
            "sip_completion_projection_delivery_v1"."anchor_status",
            "sip_completion_projection_delivery_v1"."delivery_complete",
            "sip_completion_projection_delivery_v1"."delivery_blockers"
           FROM "public"."sip_completion_projection_delivery_v1"
        ), "source_stats" AS MATERIALIZED (
         SELECT "source"."canonical_provider_key" AS "provider_scope_key",
            "count"(*) AS "source_count",
            "count"(*) FILTER (WHERE (("source"."ownership_status" = 'unresolved'::"text") OR ("inventory"."parity_status" IS DISTINCT FROM 'matched'::"text") OR ("inventory"."normalized_path" IS DISTINCT FROM "source_path"."s3_path") OR (("source"."rights_status" <> ALL (ARRAY['verified_allowed'::"text", 'verified_restricted'::"text"])) AND ("source"."global_disposition" <> ALL (ARRAY['rights_held'::"text", 'out_of_scope'::"text"]))) OR ("source"."admission_status" = 'unknown'::"text") OR (("source"."global_disposition" = 'open'::"text") AND ("accounting"."sample_original_path_id" IS NULL)))) AS "unresolved_source_count",
            "count"(*) FILTER (WHERE (("source"."ownership_status" = 'conflicting'::"text") OR ("source"."rights_status" = 'conflicting'::"text") OR ("source"."admission_status" = 'conflicting'::"text") OR ("source"."global_disposition" = 'conflicting'::"text"))) AS "conflicting_source_count",
            "count"(*) FILTER (WHERE ("source"."rights_status" = ANY (ARRAY['legacy_allowed_unverified'::"text", 'legacy_blocked_unverified'::"text"]))) AS "legacy_unverified_rights_count",
            "count"(*) FILTER (WHERE ("source"."rights_status" = ANY (ARRAY['verified_allowed'::"text", 'verified_restricted'::"text"]))) AS "verified_rights_count"
           FROM (((("public"."sip_completion_source" "source"
             JOIN "public"."samples_original_paths" "source_path" ON (("source_path"."id" = "source"."sample_original_path_id")))
             LEFT JOIN "latest_receipt" ON (true))
             LEFT JOIN "public"."sip_completion_inventory_item" "inventory" ON ((("inventory"."receipt_id" = "latest_receipt"."id") AND ("inventory"."sample_original_path_id" = "source"."sample_original_path_id"))))
             LEFT JOIN "accounted_sources" "accounting" ON ((("accounting"."provider_scope_key" = "source"."canonical_provider_key") AND ("accounting"."sample_original_path_id" = "source"."sample_original_path_id"))))
          WHERE ("source"."canonical_provider_key" IS NOT NULL)
          GROUP BY "source"."canonical_provider_key"
        ), "projection_stats" AS MATERIALIZED (
         SELECT "projection"."provider_scope_key",
            "count"(*) FILTER (WHERE "projection"."is_intended") AS "intended_projection_count",
            "count"(*) FILTER (WHERE ("projection"."is_intended" AND ("projection"."projection_decision" = ANY (ARRAY['undecided'::"text", 'conflicting'::"text"])))) AS "open_projection_count"
           FROM "public"."sip_completion_projection" "projection"
          GROUP BY "projection"."provider_scope_key"
        ), "membership_stats" AS MATERIALIZED (
         SELECT "projection"."provider_scope_key",
            "count"(*) FILTER (WHERE "membership"."is_intended") AS "intended_membership_count",
            "count"(*) FILTER (WHERE ("membership"."is_intended" AND ("membership"."effective_decision" = 'undecided'::"text"))) AS "open_membership_count",
            "count"(*) FILTER (WHERE ("membership"."is_intended" AND ("membership"."effective_decision" = 'conflicting'::"text"))) AS "conflicting_membership_count",
            COALESCE("bool_and"("membership"."decision_final") FILTER (WHERE "membership"."is_observed"), false) AS "all_observed_memberships_closed"
           FROM ("membership_rows" "membership"
             JOIN "public"."sip_completion_projection" "projection" ON (("projection"."id" = "membership"."completion_projection_id")))
          GROUP BY "projection"."provider_scope_key"
        ), "delivery_stats" AS MATERIALIZED (
         SELECT "projection"."provider_scope_key",
            "count"(*) FILTER (WHERE ("projection"."is_intended" AND ("projection"."projection_decision" = 'active'::"text"))) AS "active_delivery_projection_count",
            "count"(*) FILTER (WHERE ("projection"."is_intended" AND ("projection"."projection_decision" = 'active'::"text") AND (NOT COALESCE("delivery"."delivery_complete", false)))) AS "open_delivery_projection_count"
           FROM ("public"."sip_completion_projection" "projection"
             LEFT JOIN "delivery_rows" "delivery" ON (("delivery"."completion_projection_id" = "projection"."id")))
          GROUP BY "projection"."provider_scope_key"
        ), "lease_stats" AS MATERIALIZED (
         SELECT "lease"."provider_slug" AS "provider_scope_key",
            "count"(*) AS "active_lease_count"
           FROM "public"."sip_fleet_provider_leases" "lease"
          WHERE (("lease"."released_at" IS NULL) AND ("lease"."lease_expires_at" > "now"()))
          GROUP BY "lease"."provider_slug"
        ), "run_stats" AS MATERIALIZED (
         SELECT "run"."provider_slug" AS "provider_scope_key",
            "count"(*) AS "active_run_count"
           FROM "public"."sip_fleet_runs" "run"
          WHERE ("run"."status" = ANY (ARRAY['queued'::"text", 'running'::"text"]))
          GROUP BY "run"."provider_slug"
        ), "provider_rows" AS (
         SELECT "scope"."provider_scope_key",
            COALESCE("latest_receipt"."inventory_receipt_current", false) AS "inventory_receipt_current",
            COALESCE("latest_receipt"."inventory_only_count", (0)::bigint) AS "inventory_only_path_count",
            COALESCE("latest_receipt"."database_only_count", (0)::bigint) AS "database_only_source_count",
            COALESCE("source"."source_count", (0)::bigint) AS "source_count",
            COALESCE("source"."unresolved_source_count", (0)::bigint) AS "unresolved_source_count",
            COALESCE("source"."conflicting_source_count", (0)::bigint) AS "conflicting_source_count",
            COALESCE("source"."legacy_unverified_rights_count", (0)::bigint) AS "legacy_unverified_rights_count",
            COALESCE("source"."verified_rights_count", (0)::bigint) AS "verified_rights_count",
            COALESCE("registry"."status", 'missing'::"text") AS "intended_registry_status",
            COALESCE("registry"."current_by_count", false) AS "intended_registry_current",
            COALESCE("projection"."intended_projection_count", (0)::bigint) AS "intended_projection_count",
            COALESCE("projection"."open_projection_count", (0)::bigint) AS "open_projection_count",
            COALESCE("membership"."intended_membership_count", (0)::bigint) AS "intended_membership_count",
            COALESCE("membership"."open_membership_count", (0)::bigint) AS "open_membership_count",
            COALESCE("membership"."conflicting_membership_count", (0)::bigint) AS "conflicting_membership_count",
            COALESCE("delivery"."active_delivery_projection_count", (0)::bigint) AS "active_delivery_projection_count",
            COALESCE("delivery"."open_delivery_projection_count", (0)::bigint) AS "open_delivery_projection_count",
            COALESCE("lease"."active_lease_count", (0)::bigint) AS "active_lease_count",
            COALESCE("run"."active_run_count", (0)::bigint) AS "active_run_count",
            COALESCE("membership"."all_observed_memberships_closed", false) AS "all_observed_memberships_closed"
           FROM (((((((("scopes" "scope"
             LEFT JOIN "latest_receipt" ON (true))
             LEFT JOIN "source_stats" "source" ON (("source"."provider_scope_key" = "scope"."provider_scope_key")))
             LEFT JOIN "projection_stats" "projection" ON (("projection"."provider_scope_key" = "scope"."provider_scope_key")))
             LEFT JOIN "membership_stats" "membership" ON (("membership"."provider_scope_key" = "scope"."provider_scope_key")))
             LEFT JOIN "delivery_stats" "delivery" ON (("delivery"."provider_scope_key" = "scope"."provider_scope_key")))
             LEFT JOIN "registry_state" "registry" ON (("registry"."provider_scope_key" = "scope"."provider_scope_key")))
             LEFT JOIN "lease_stats" "lease" ON (("lease"."provider_scope_key" = "scope"."provider_scope_key")))
             LEFT JOIN "run_stats" "run" ON (("run"."provider_scope_key" = "scope"."provider_scope_key")))
        )
 SELECT "provider_rows"."provider_scope_key",
    "provider_rows"."inventory_receipt_current",
    "provider_rows"."inventory_only_path_count",
    "provider_rows"."database_only_source_count",
    "provider_rows"."source_count",
    "provider_rows"."unresolved_source_count",
    "provider_rows"."conflicting_source_count",
    "provider_rows"."legacy_unverified_rights_count",
    "provider_rows"."verified_rights_count",
    "provider_rows"."intended_registry_status",
    "provider_rows"."intended_registry_current",
    "provider_rows"."intended_projection_count",
    "provider_rows"."open_projection_count",
    "provider_rows"."intended_membership_count",
    "provider_rows"."open_membership_count",
    "provider_rows"."conflicting_membership_count",
    "provider_rows"."active_delivery_projection_count",
    "provider_rows"."open_delivery_projection_count",
    "provider_rows"."active_lease_count",
    "provider_rows"."active_run_count",
    "provider_rows"."all_observed_memberships_closed",
        CASE
            WHEN "provider_rows"."intended_registry_current" THEN (("provider_rows"."open_projection_count" = 0) AND ("provider_rows"."open_membership_count" = 0) AND ("provider_rows"."conflicting_membership_count" = 0) AND ("provider_rows"."open_delivery_projection_count" = 0))
            ELSE NULL::boolean
        END AS "all_intended_projections_complete",
    (COALESCE(
        CASE
            WHEN "provider_rows"."intended_registry_current" THEN (("provider_rows"."open_projection_count" = 0) AND ("provider_rows"."open_membership_count" = 0) AND ("provider_rows"."conflicting_membership_count" = 0) AND ("provider_rows"."open_delivery_projection_count" = 0))
            ELSE NULL::boolean
        END, false) AND "provider_rows"."inventory_receipt_current" AND ("provider_rows"."unresolved_source_count" = 0) AND ("provider_rows"."conflicting_source_count" = 0) AND ("provider_rows"."open_delivery_projection_count" = 0) AND ("provider_rows"."active_lease_count" = 0) AND ("provider_rows"."active_run_count" = 0)) AS "provider_complete",
    "array_remove"(ARRAY[
        CASE
            WHEN (NOT "provider_rows"."inventory_receipt_current") THEN 'inventory_not_current'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (NOT "provider_rows"."intended_registry_current") THEN 'registry_missing_or_stale'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("provider_rows"."unresolved_source_count" > 0) THEN 'unresolved_sources'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("provider_rows"."conflicting_source_count" > 0) THEN 'conflicting_sources'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("provider_rows"."open_projection_count" > 0) THEN 'open_projections'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("provider_rows"."open_membership_count" > 0) THEN 'open_memberships'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("provider_rows"."conflicting_membership_count" > 0) THEN 'conflicting_memberships'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("provider_rows"."open_delivery_projection_count" > 0) THEN 'open_delivery'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("provider_rows"."active_lease_count" > 0) THEN 'active_lease'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("provider_rows"."active_run_count" > 0) THEN 'active_run'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "completion_blockers"
   FROM "provider_rows"
UNION ALL
 SELECT '__global__'::"text" AS "provider_scope_key",
    COALESCE("latest_receipt"."inventory_receipt_current", false) AS "inventory_receipt_current",
    COALESCE("latest_receipt"."inventory_only_count", (0)::bigint) AS "inventory_only_path_count",
    COALESCE("latest_receipt"."database_only_count", (0)::bigint) AS "database_only_source_count",
    "count"("source"."sample_original_path_id") AS "source_count",
    "count"("source"."sample_original_path_id") FILTER (WHERE (("source"."ownership_status" = 'unresolved'::"text") OR ("inventory"."parity_status" IS DISTINCT FROM 'matched'::"text") OR ("inventory"."normalized_path" IS DISTINCT FROM "source_path"."s3_path") OR (("source"."rights_status" <> ALL (ARRAY['verified_allowed'::"text", 'verified_restricted'::"text"])) AND ("source"."global_disposition" <> ALL (ARRAY['rights_held'::"text", 'out_of_scope'::"text"]))) OR ("source"."admission_status" = 'unknown'::"text") OR (("source"."global_disposition" = 'open'::"text") AND (NOT (EXISTS ( SELECT 1
           FROM "accounted_sources" "accounting"
          WHERE ("accounting"."sample_original_path_id" = "source"."sample_original_path_id"))))))) AS "unresolved_source_count",
    "count"("source"."sample_original_path_id") FILTER (WHERE (("source"."ownership_status" = 'conflicting'::"text") OR ("source"."rights_status" = 'conflicting'::"text") OR ("source"."admission_status" = 'conflicting'::"text") OR ("source"."global_disposition" = 'conflicting'::"text"))) AS "conflicting_source_count",
    "count"("source"."sample_original_path_id") FILTER (WHERE ("source"."rights_status" = ANY (ARRAY['legacy_allowed_unverified'::"text", 'legacy_blocked_unverified'::"text"]))) AS "legacy_unverified_rights_count",
    "count"("source"."sample_original_path_id") FILTER (WHERE ("source"."rights_status" = ANY (ARRAY['verified_allowed'::"text", 'verified_restricted'::"text"]))) AS "verified_rights_count",
    'missing'::"text" AS "intended_registry_status",
    false AS "intended_registry_current",
    (0)::bigint AS "intended_projection_count",
    (0)::bigint AS "open_projection_count",
    (0)::bigint AS "intended_membership_count",
    (0)::bigint AS "open_membership_count",
    (0)::bigint AS "conflicting_membership_count",
    (0)::bigint AS "active_delivery_projection_count",
    (0)::bigint AS "open_delivery_projection_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."sip_fleet_provider_leases" "lease"
          WHERE (("lease"."released_at" IS NULL) AND ("lease"."lease_expires_at" > "now"()))) AS "active_lease_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."sip_fleet_runs" "run"
          WHERE ("run"."status" = ANY (ARRAY['queued'::"text", 'running'::"text"]))) AS "active_run_count",
    false AS "all_observed_memberships_closed",
    NULL::boolean AS "all_intended_projections_complete",
    false AS "provider_complete",
    ARRAY['global_intended_registry_unavailable'::"text"] AS "completion_blockers"
   FROM ((((( SELECT 1 AS "?column?") "seed"
     LEFT JOIN "latest_receipt" ON (true))
     LEFT JOIN "public"."sip_completion_source" "source" ON (true))
     LEFT JOIN "public"."samples_original_paths" "source_path" ON (("source_path"."id" = "source"."sample_original_path_id")))
     LEFT JOIN "public"."sip_completion_inventory_item" "inventory" ON ((("inventory"."receipt_id" = "latest_receipt"."id") AND ("inventory"."sample_original_path_id" = "source"."sample_original_path_id"))))
  GROUP BY "latest_receipt"."result", "latest_receipt"."database_count", "latest_receipt"."inventory_receipt_current", "latest_receipt"."inventory_only_count", "latest_receipt"."database_only_count";


ALTER TABLE "public"."sip_completion_provider_status_v1" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sip_completion_source_ledger_v1" WITH ("security_invoker"='true') AS
 WITH "latest_receipt" AS (
         SELECT "receipt"."id",
            "receipt"."result",
            "receipt"."database_count",
            (("receipt"."result" = 'matched'::"text") AND ("receipt"."database_count" = ( SELECT "count"(*) AS "count"
                   FROM "public"."samples_original_paths")) AND (NOT (EXISTS ( SELECT 1
                   FROM ("public"."samples_original_paths" "current_source"
                     LEFT JOIN "public"."sip_completion_inventory_item" "current_item" ON ((("current_item"."receipt_id" = "receipt"."id") AND ("current_item"."sample_original_path_id" = "current_source"."id"))))
                  WHERE (("current_item"."parity_status" IS DISTINCT FROM 'matched'::"text") OR ("current_item"."normalized_path" IS DISTINCT FROM "current_source"."s3_path")))))) AS "inventory_receipt_current"
           FROM "public"."sip_completion_inventory_receipt" "receipt"
          ORDER BY "receipt"."production_observed_at" DESC, "receipt"."created_at" DESC, "receipt"."id" DESC
         LIMIT 1
        ), "membership" AS (
         SELECT "membership_1"."sample_original_path_id",
            "count"(*) FILTER (WHERE "membership_1"."is_observed") AS "observed_membership_count",
            "count"(*) FILTER (WHERE "membership_1"."is_intended") AS "intended_membership_count",
            "count"(*) FILTER (WHERE "membership_1"."delivery_required") AS "active_membership_count",
            "count"(*) FILTER (WHERE "membership_1"."membership_terminal") AS "terminal_membership_count",
            "count"(*) FILTER (WHERE ("membership_1"."effective_decision" = 'conflicting'::"text")) AS "conflicting_membership_count",
            "count"(*) FILTER (WHERE ("membership_1"."delivery_required" AND (NOT COALESCE("delivery"."delivery_complete", false)))) AS "open_delivery_membership_count",
            "bool_and"("membership_1"."decision_final") FILTER (WHERE "membership_1"."is_observed") AS "all_observed_membership_decisions_final",
            "bool_and"(("membership_1"."membership_terminal" OR (NOT "membership_1"."delivery_required"))) FILTER (WHERE "membership_1"."is_observed") AS "all_observed_memberships_closed",
            "bool_and"(("membership_1"."decision_final" AND ("membership_1"."membership_terminal" OR ("membership_1"."delivery_required" AND COALESCE("delivery"."delivery_complete", false))))) FILTER (WHERE "membership_1"."is_intended") AS "all_intended_memberships_closed"
           FROM ("public"."sip_completion_projection_membership_v1" "membership_1"
             LEFT JOIN "public"."sip_completion_projection_delivery_v1" "delivery" ON (("delivery"."completion_projection_id" = "membership_1"."completion_projection_id")))
          GROUP BY "membership_1"."sample_original_path_id"
        ), "current_registry" AS (
         SELECT "registry"."provider_scope_key"
           FROM "public"."sip_completion_projection_registry" "registry"
          WHERE (("registry"."status" = 'frozen'::"text") AND ("registry"."source_count" = ( SELECT "count"(*) AS "count"
                   FROM "public"."sip_completion_source" "source_1"
                  WHERE ("source_1"."canonical_provider_key" = "registry"."provider_scope_key"))) AND ("registry"."intended_projection_count" = ( SELECT "count"(*) AS "count"
                   FROM "public"."sip_completion_projection" "projection"
                  WHERE (("projection"."provider_scope_key" = "registry"."provider_scope_key") AND "projection"."is_intended"))) AND ("registry"."intended_membership_count" = ( SELECT "count"(*) AS "count"
                   FROM ("public"."sip_completion_projection_membership" "member"
                     JOIN "public"."sip_completion_projection" "projection" ON (("projection"."id" = "member"."completion_projection_id")))
                  WHERE (("projection"."provider_scope_key" = "registry"."provider_scope_key") AND "member"."is_intended"))) AND ("registry"."source_identity_sha256" = "public"."sip_completion_identity_digest_v1"(ARRAY( SELECT ("source_1"."sample_original_path_id")::"text" AS "sample_original_path_id"
                   FROM "public"."sip_completion_source" "source_1"
                  WHERE ("source_1"."canonical_provider_key" = "registry"."provider_scope_key")
                  ORDER BY ("source_1"."sample_original_path_id")::"text"))) AND ("registry"."projection_identity_sha256" = "public"."sip_completion_identity_digest_v1"(ARRAY( SELECT "projection"."projection_key"
                   FROM "public"."sip_completion_projection" "projection"
                  WHERE (("projection"."provider_scope_key" = "registry"."provider_scope_key") AND "projection"."is_intended")
                  ORDER BY ("projection"."projection_key" COLLATE "C")))) AND ("registry"."membership_identity_sha256" = "public"."sip_completion_identity_digest_v1"(ARRAY( SELECT (("projection"."projection_key" || '/'::"text") || "member"."sample_original_path_id")
                   FROM ("public"."sip_completion_projection_membership" "member"
                     JOIN "public"."sip_completion_projection" "projection" ON (("projection"."id" = "member"."completion_projection_id")))
                  WHERE (("projection"."provider_scope_key" = "registry"."provider_scope_key") AND "member"."is_intended")
                  ORDER BY ("projection"."projection_key" COLLATE "C"), "member"."sample_original_path_id"))))
        )
 SELECT "source"."id" AS "sample_original_path_id",
    "source"."s3_path",
        CASE
            WHEN ("fact"."origin_exception_classification" IS NOT NULL) THEN 'generated_exception'::"text"
            WHEN ("derivation"."generated_sample_original_path_id" IS NULL) THEN 'received_original'::"text"
            ELSE 'generated_derivation'::"text"
        END AS "origin_kind",
    "derivation"."source_sample_original_path_id" AS "generated_parent_sample_id",
    ("fact"."sample_original_path_id" IS NULL) AS "source_fact_missing",
    "fact"."canonical_provider_key",
    COALESCE("fact"."ownership_status", 'unresolved'::"text") AS "ownership_status",
    COALESCE("fact"."rights_status", 'unknown'::"text") AS "rights_status",
    COALESCE("fact"."admission_status", 'unknown'::"text") AS "admission_status",
    COALESCE("fact"."global_disposition", 'open'::"text") AS "global_disposition",
    "latest_receipt"."id" AS "inventory_receipt_id",
    "inventory"."parity_status" AS "inventory_parity_status",
    (COALESCE("latest_receipt"."inventory_receipt_current", false) AND ("inventory"."parity_status" = 'matched'::"text") AND ("inventory"."normalized_path" = "source"."s3_path")) AS "inventory_receipt_current",
    COALESCE("membership"."observed_membership_count", (0)::bigint) AS "observed_membership_count",
    COALESCE("membership"."intended_membership_count", (0)::bigint) AS "intended_membership_count",
    COALESCE("membership"."active_membership_count", (0)::bigint) AS "active_membership_count",
    COALESCE("membership"."terminal_membership_count", (0)::bigint) AS "terminal_membership_count",
    COALESCE("membership"."conflicting_membership_count", (0)::bigint) AS "conflicting_membership_count",
    COALESCE("membership"."open_delivery_membership_count", (0)::bigint) AS "open_delivery_membership_count",
    COALESCE("membership"."all_observed_membership_decisions_final", false) AS "all_observed_membership_decisions_final",
    COALESCE("membership"."all_observed_memberships_closed", false) AS "all_observed_memberships_closed",
    ("current_registry"."provider_scope_key" IS NOT NULL) AS "intended_registry_current",
        CASE
            WHEN ("current_registry"."provider_scope_key" IS NULL) THEN NULL::boolean
            ELSE COALESCE("membership"."all_intended_memberships_closed", false)
        END AS "all_intended_memberships_closed",
    (("fact"."sample_original_path_id" IS NOT NULL) AND COALESCE("latest_receipt"."inventory_receipt_current", false) AND ("inventory"."parity_status" = 'matched'::"text") AND ("inventory"."normalized_path" = "source"."s3_path") AND ("fact"."ownership_status" = 'resolved'::"text") AND (("fact"."rights_status" = ANY (ARRAY['verified_allowed'::"text", 'verified_restricted'::"text"])) OR ("fact"."global_disposition" = ANY (ARRAY['rights_held'::"text", 'out_of_scope'::"text"]))) AND ("fact"."admission_status" <> ALL (ARRAY['unknown'::"text", 'conflicting'::"text"])) AND (("fact"."global_disposition" <> ALL (ARRAY['open'::"text", 'conflicting'::"text"])) OR (COALESCE("membership"."observed_membership_count", (0)::bigint) > 0)) AND (COALESCE("membership"."conflicting_membership_count", (0)::bigint) = 0) AND ((COALESCE("membership"."observed_membership_count", (0)::bigint) = 0) OR COALESCE("membership"."all_observed_membership_decisions_final", false)) AND (COALESCE("membership"."open_delivery_membership_count", (0)::bigint) = 0)) AS "source_accounted",
    "array_remove"(ARRAY[
        CASE
            WHEN ("fact"."sample_original_path_id" IS NULL) THEN 'source_fact_missing'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (NOT COALESCE("latest_receipt"."inventory_receipt_current", false)) THEN 'inventory_receipt_stale'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("inventory"."parity_status" IS DISTINCT FROM 'matched'::"text") OR ("inventory"."normalized_path" IS DISTINCT FROM "source"."s3_path")) THEN 'inventory_parity_open'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("fact"."ownership_status", 'unresolved'::"text") = ANY (ARRAY['unresolved'::"text", 'conflicting'::"text"])) THEN 'ownership_open'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ((COALESCE("fact"."rights_status", 'unknown'::"text") <> ALL (ARRAY['verified_allowed'::"text", 'verified_restricted'::"text"])) AND (COALESCE("fact"."global_disposition", 'open'::"text") <> ALL (ARRAY['rights_held'::"text", 'out_of_scope'::"text"]))) THEN 'rights_open'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("fact"."admission_status", 'unknown'::"text") = ANY (ARRAY['unknown'::"text", 'conflicting'::"text"])) THEN 'admission_open'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("membership"."conflicting_membership_count", (0)::bigint) > 0) THEN 'membership_conflict'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ((COALESCE("membership"."observed_membership_count", (0)::bigint) > 0) AND (NOT COALESCE("membership"."all_observed_membership_decisions_final", false))) THEN 'membership_decision_open'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("membership"."open_delivery_membership_count", (0)::bigint) > 0) THEN 'delivery_open'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "source_blockers",
    "fact"."origin_exception_classification"
   FROM (((((("public"."samples_original_paths" "source"
     LEFT JOIN "public"."sip_completion_source" "fact" ON (("fact"."sample_original_path_id" = "source"."id")))
     LEFT JOIN "public"."sample_generated_derivations" "derivation" ON (("derivation"."generated_sample_original_path_id" = "source"."id")))
     LEFT JOIN "latest_receipt" ON (true))
     LEFT JOIN "public"."sip_completion_inventory_item" "inventory" ON ((("inventory"."receipt_id" = "latest_receipt"."id") AND ("inventory"."sample_original_path_id" = "source"."id"))))
     LEFT JOIN "membership" ON (("membership"."sample_original_path_id" = "source"."id")))
     LEFT JOIN "current_registry" ON (("current_registry"."provider_scope_key" = "fact"."canonical_provider_key")));


ALTER TABLE "public"."sip_completion_source_ledger_v1" OWNER TO "postgres";


