CREATE TABLE IF NOT EXISTS "public"."sip_fmg_terminal_profile_wait_reconciliation_receipts" (
    "scope_key" "text" NOT NULL,
    "receipt_kind" "text" NOT NULL,
    "receipt_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_slug" "text" NOT NULL,
    "provider_lease_id" "uuid" NOT NULL,
    "provider_lease_owner" "text" NOT NULL,
    "manifest_hash" "text" NOT NULL,
    "manifest" "jsonb" NOT NULL,
    "result" "jsonb" NOT NULL,
    "applied_by" "text" NOT NULL,
    "applied_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "sip_fmg_terminal_profile_wait_reconc_provider_lease_owner_check" CHECK (("btrim"("provider_lease_owner") <> ''::"text")),
    CONSTRAINT "sip_fmg_terminal_profile_wait_reconciliatio_manifest_hash_check" CHECK (("manifest_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "sip_fmg_terminal_profile_wait_reconciliatio_provider_slug_check" CHECK (("provider_slug" = 'fallout-music-group'::"text")),
    CONSTRAINT "sip_fmg_terminal_profile_wait_reconciliation_r_applied_by_check" CHECK (("btrim"("applied_by") <> ''::"text")),
    CONSTRAINT "sip_fmg_terminal_profile_wait_reconciliation_re_scope_key_check" CHECK (("scope_key" = 'issue-2437-fmg-terminal-profile-waits-v1'::"text")),
    CONSTRAINT "sip_fmg_terminal_profile_wait_reconciliation_rec_manifest_check" CHECK ((("jsonb_typeof"("manifest") = 'object'::"text") AND (("manifest" ->> 'operationClass'::"text") = 'terminal-history-status-only'::"text") AND (("manifest" ->> 'readinessAuthorized'::"text") = 'false'::"text") AND (("manifest" ->> 'legacyReceiptBlocker'::"text") = 'address_output_receipts_incomplete'::"text"))),
