CREATE OR REPLACE VIEW "public"."sip_instrument_with_audio_profile" AS
 SELECT "i"."id",
    "i"."name",
    "i"."engine_type",
    "i"."playback_type",
    "i"."polyphony_type",
    "i"."instrument_family",
    "i"."instrument_type",
    "i"."contributor_id",
    "i"."collection",
    "i"."pitch_contents",
    "i"."velocity_layers",
    "i"."pitch_content_config",
    "i"."range_lower",
    "i"."range_upper",
    "i"."single_pitch",
    "i"."gain",
    "i"."sustain_crop_time",
    "i"."original_file_path_reference",
    "i"."original_file_name_references",
    "i"."articulations",
    "i"."effects_instruments",
    "i"."mic_positions",
    "i"."original_sample_ids",
    "i"."published",
    "i"."created_at",
    "i"."updated_at",
    "m"."source_contributor_slug",
    "m"."source_group_key",
    "m"."source_collections",
    "m"."source_group_keys",
    "m"."approved",
    "p"."profile_version" AS "audio_profile_version",
    "p"."source_sample_ids_hash" AS "audio_profile_source_sample_ids_hash",
    "p"."sample_count" AS "audio_profile_sample_count",
    "p"."analyzed_sample_count" AS "audio_profile_analyzed_sample_count",
    "p"."flagged_sample_count" AS "audio_profile_flagged_sample_count",
    "p"."quality_report" AS "audio_profile_quality_report",
    "p"."spectral_centroid_median",
    "p"."spectral_rolloff_median",
    "p"."spectral_contrast_median",
    "p"."spectral_flatness_median",
    "p"."spectral_entropy_median",
    "p"."hp_ratio_median",
    "p"."hnr_db_median",
    "p"."attack_time_ms_median",
    "p"."decay_time_ms_median",
    "p"."effective_duration_median",
    "p"."onset_sharpness_median",
    "p"."sustain_stability_median",
    "p"."inharmonicity_median",
    "p"."pitch_median_median",
    "p"."pitch_std_median",
    "p"."pitch_range_median",
    "p"."pitch_stability_median",
    "p"."pitch_confidence_median",
    "p"."vibrato_rate_hz_median",
    "p"."vibrato_depth_hz_median",
    "p"."pitched_sample_ratio",
    "p"."long_sample_ratio",
    "p"."short_sample_ratio",
    "p"."sharp_onset_sample_ratio",
    "p"."tremolo_candidate_sample_ratio",
    "p"."vibrato_candidate_sample_ratio",
    "p"."noisy_candidate_sample_ratio",
    "p"."harmonic_candidate_sample_ratio",
    "p"."percussive_candidate_sample_ratio",
    "p"."bright_sample_ratio",
    "p"."dark_sample_ratio",
    "p"."low_register",
    "p"."mid_register",
    "p"."high_register",
    "p"."embedding" AS "audio_profile_embedding",
    "p"."computed_at" AS "audio_profile_computed_at",
    "i"."legato_transition",
    "i"."asset_role"
   FROM (("public"."sip_instrument" "i"
     JOIN "public"."sip_instrument_meta" "m" ON (("m"."sip_instrument_id" = "i"."id")))
     LEFT JOIN "public"."sip_instrument_audio_profile" "p" ON (("p"."sip_instrument_id" = "i"."id")));


ALTER TABLE "public"."sip_instrument_with_audio_profile" OWNER TO "postgres";


