    CONSTRAINT "sip_public_output_recovery_retry_receipts_git_sha_check" CHECK (("btrim"("git_sha") <> ALL (ARRAY[''::"text", 'unknown'::"text"]))),
    CONSTRAINT "sip_public_output_recovery_retry_receipts_proof_hash_check" CHECK (("proof_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "sip_public_output_recovery_retry_receipts_provider_slug_check" CHECK (("btrim"("provider_slug") <> ''::"text")),
