CREATE TABLE IF NOT EXISTS "public"."sip_review_sample_playback_cues" (
    "id" bigint NOT NULL,
    "sip_review_instrument_id" "uuid" NOT NULL,
    "original_sample_id" "uuid" NOT NULL,
    "file_path" "text",
    "sync_point_ms" integer,
    "loop_start_offset_ms" integer,
    "loop_end_offset_ms" integer,
    "sync_point_status" "text" DEFAULT 'not_requested'::"text" NOT NULL,
    "loop_start_status" "text" DEFAULT 'not_requested'::"text" NOT NULL,
    "loop_end_status" "text" DEFAULT 'not_requested'::"text" NOT NULL,
    "analysis_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "analysis_run_id" "text",
    "analyzed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sip_review_sample_playback_cues_analysis_payload_object_check" CHECK (("jsonb_typeof"("analysis_payload") = 'object'::"text")),
    CONSTRAINT "sip_review_sample_playback_cues_loop_end_offset_ms_check" CHECK ((("loop_end_offset_ms" IS NULL) OR ("loop_end_offset_ms" >= 0))),
    CONSTRAINT "sip_review_sample_playback_cues_loop_end_status_check" CHECK (("loop_end_status" = ANY (ARRAY['not_requested'::"text", 'pending'::"text", 'found'::"text", 'none'::"text", 'failed'::"text", 'needs_review'::"text"]))),
    CONSTRAINT "sip_review_sample_playback_cues_loop_offsets_order_check" CHECK ((("loop_start_offset_ms" IS NULL) OR ("loop_end_offset_ms" IS NULL) OR ("loop_end_offset_ms" > "loop_start_offset_ms"))),
    CONSTRAINT "sip_review_sample_playback_cues_loop_start_offset_ms_check" CHECK ((("loop_start_offset_ms" IS NULL) OR ("loop_start_offset_ms" >= 0))),
    CONSTRAINT "sip_review_sample_playback_cues_loop_start_status_check" CHECK (("loop_start_status" = ANY (ARRAY['not_requested'::"text", 'pending'::"text", 'found'::"text", 'none'::"text", 'failed'::"text", 'needs_review'::"text"]))),
    CONSTRAINT "sip_review_sample_playback_cues_sync_point_ms_check" CHECK ((("sync_point_ms" IS NULL) OR ("sync_point_ms" >= 0))),
    CONSTRAINT "sip_review_sample_playback_cues_sync_point_status_check" CHECK (("sync_point_status" = ANY (ARRAY['not_requested'::"text", 'pending'::"text", 'found'::"text", 'none'::"text", 'failed'::"text", 'needs_review'::"text"])))
);


ALTER TABLE "public"."sip_review_sample_playback_cues" OWNER TO "postgres";


COMMENT ON TABLE "public"."sip_review_sample_playback_cues" IS 'Review-layer playback cue analysis for samples in sip_review_instrument. Mirrors sample_playback_cues against sip_review_instrument + samples_original_paths identity.';



COMMENT ON COLUMN "public"."sip_review_sample_playback_cues"."sip_review_instrument_id" IS 'Review instrument owning this sample cue row; cascades with the review instrument.';



COMMENT ON COLUMN "public"."sip_review_sample_playback_cues"."original_sample_id" IS 'Canonical sample identity from samples_original_paths.id.';



COMMENT ON COLUMN "public"."sip_review_sample_playback_cues"."file_path" IS 'Human-readable source path captured for review display. Not part of the key.';



COMMENT ON COLUMN "public"."sip_review_sample_playback_cues"."sync_point_ms" IS 'Optional sync point offset in milliseconds from the beginning of the loaded, already-trimmed sample.';



COMMENT ON COLUMN "public"."sip_review_sample_playback_cues"."loop_start_offset_ms" IS 'Optional loop start offset in milliseconds from the beginning of the loaded, already-trimmed sample.';



COMMENT ON COLUMN "public"."sip_review_sample_playback_cues"."loop_end_offset_ms" IS 'Optional loop end offset in milliseconds from the beginning of the loaded, already-trimmed sample. Must be greater than loop_start_offset_ms when both are present.';



COMMENT ON COLUMN "public"."sip_review_sample_playback_cues"."sync_point_status" IS 'Independent analysis status for sync_point_ms.';



COMMENT ON COLUMN "public"."sip_review_sample_playback_cues"."loop_start_status" IS 'Independent analysis status for loop_start_offset_ms.';



COMMENT ON COLUMN "public"."sip_review_sample_playback_cues"."loop_end_status" IS 'Independent analysis status for loop_end_offset_ms.';



COMMENT ON COLUMN "public"."sip_review_sample_playback_cues"."analysis_payload" IS 'Raw analyzer/debug payload. Must be a JSON object.';



