    "id" bigint NOT NULL,
    "sip_review_instrument_id" "uuid" NOT NULL,
    "contributor_slug" "text" NOT NULL,
    "category" "text" NOT NULL,
    "warning_key" "text" NOT NULL,
    "type" "text" NOT NULL,
    "severity" "text" NOT NULL,
    "severity_rank" smallint GENERATED ALWAYS AS (
CASE "severity"
    WHEN 'high'::"text" THEN 3
    WHEN 'med'::"text" THEN 2
    ELSE 1
END) STORED,
    "field" "text" NOT NULL,
    "file_path" "text" NOT NULL,
