CREATE OR REPLACE VIEW "public"."sip_review_warning_index_with_review_state" WITH ("security_invoker"='true') AS
 SELECT "wi"."id",
    "wi"."sip_review_instrument_id",
    "wi"."contributor_slug",
    "wi"."category",
    "wi"."warning_key",
    "wi"."type",
    "wi"."severity",
    "wi"."severity_rank",
    "wi"."field",
    "wi"."file_path",
    "wi"."original_sample_id",
    "wi"."message",
    "wi"."created_at",
    "wi"."updated_at",
    COALESCE("rs"."status", 'open'::"text") AS "review_status",
    "rs"."note" AS "review_note",
    "rs"."updated_by" AS "reviewed_by",
    "rs"."updated_at" AS "reviewed_at"
   FROM ("public"."sip_review_warning_index" "wi"
     LEFT JOIN "public"."sip_review_warning_review_state" "rs" ON ((("rs"."sip_review_instrument_id" = "wi"."sip_review_instrument_id") AND ("rs"."category" = "wi"."category") AND ("rs"."warning_key" = "wi"."warning_key"))));


ALTER TABLE "public"."sip_review_warning_index_with_review_state" OWNER TO "postgres";


