    CONSTRAINT "sip_sample_publish_actions_target_source_check" CHECK (("target_source" = ANY (ARRAY['perceptual_midi_estimate'::"text", 'resolved_midi_note'::"text", 'path_midi_guess'::"text", 'path_midi_octave_equivalent'::"text", 'nearest_midi'::"text"])))
);


