COMMENT ON TABLE "public"."song_migrations" IS 'Tracks the status and history of song migrations from Firebase to Supabase';



COMMENT ON COLUMN "public"."song_migrations"."id" IS 'Unique identifier for the migration record';



COMMENT ON COLUMN "public"."song_migrations"."firebase_uid" IS 'Firebase user ID of the song owner';



COMMENT ON COLUMN "public"."song_migrations"."firebase_song_key" IS 'Original Firebase song document key';



COMMENT ON COLUMN "public"."song_migrations"."composer_song_id" IS 'Reference to the created composer_songs record (if successful)';



COMMENT ON COLUMN "public"."song_migrations"."status" IS 'Migration status: pending, success, failed, or skipped';



COMMENT ON COLUMN "public"."song_migrations"."error_message" IS 'Error message if migration failed';



COMMENT ON COLUMN "public"."song_migrations"."migration_version" IS 'Version identifier of the migration script used';



COMMENT ON COLUMN "public"."song_migrations"."migration_metadata" IS 'Additional metadata about the migration process';



COMMENT ON COLUMN "public"."song_migrations"."migrated_at" IS 'Timestamp of when the migration was attempted';



CREATE TABLE IF NOT EXISTS "public"."song_render_midi_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
