    CONSTRAINT "song_render_midi_assets_note_count_check" CHECK (("note_count" >= 0)),
    CONSTRAINT "song_render_midi_assets_part_identity_sha256_check" CHECK (("part_identity_sha256" ~ '^[0-9a-f]{64}$'::"text")),
