    "current_period_start" timestamp without time zone,
    "current_period_end" timestamp without time zone,
    "attrs" "jsonb",
    "customer" "text",
    "currency" "text",
    "id" "text"
)
SERVER "stripe_server"
OPTIONS (
    "object" 'subscriptions',
    "schema" 'public'
);


ALTER FOREIGN TABLE "public"."stripe_subscriptions" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."temp_purchase" (
    "id" bigint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "org_song_config" "jsonb",
    "updated_song_config" "jsonb",
    "song_configs_w_id_and_uuid" "jsonb",
    "user_id" "uuid"
);


ALTER TABLE "public"."temp_purchase" OWNER TO "postgres";


ALTER TABLE "public"."temp_purchase" ALTER COLUMN "id" ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME "public"."temp_purchase_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



