CREATE OR REPLACE VIEW "public"."published_sample_analysis_status_v1" AS
 SELECT "asset"."instrument_v2_id",
    "asset"."id" AS "published_asset_id",
    "asset"."sample_path_construct_id",
    "asset"."sample_original_path_id",
    "asset"."source_signature",
    "asset"."analysis_version",
    "asset"."is_current",
    "asset"."exclusion_reason",
    ("count"(*) FILTER (WHERE ("job"."stage" = ANY (ARRAY['analysis'::"text", 'derived'::"text", 'librosa'::"text", 'deep_derived'::"text"]))))::integer AS "job_count",
    ("count"(*) FILTER (WHERE (("job"."stage" = ANY (ARRAY['analysis'::"text", 'derived'::"text", 'librosa'::"text", 'deep_derived'::"text"])) AND ("job"."status" = 'completed'::"text"))))::integer AS "completed_job_count",
    ("count"(*) FILTER (WHERE (("job"."stage" = ANY (ARRAY['analysis'::"text", 'derived'::"text", 'librosa'::"text", 'deep_derived'::"text"])) AND ("job"."status" = ANY (ARRAY['queued'::"text", 'running'::"text"])))))::integer AS "pending_job_count",
    ("count"(*) FILTER (WHERE (("job"."stage" = ANY (ARRAY['analysis'::"text", 'derived'::"text", 'librosa'::"text", 'deep_derived'::"text"])) AND ("job"."status" = 'failed'::"text"))))::integer AS "failed_job_count",
        CASE
            WHEN ("asset"."excluded_at" IS NOT NULL) THEN 'excluded'::"text"
            WHEN (("count"(*) FILTER (WHERE ("job"."stage" = ANY (ARRAY['analysis'::"text", 'derived'::"text", 'librosa'::"text", 'deep_derived'::"text"]))) = 4) AND "bool_and"(("job"."status" = 'completed'::"text")) FILTER (WHERE ("job"."stage" = ANY (ARRAY['analysis'::"text", 'derived'::"text", 'librosa'::"text", 'deep_derived'::"text"])))) THEN 'complete'::"text"
            WHEN ("count"(*) FILTER (WHERE (("job"."stage" = ANY (ARRAY['analysis'::"text", 'derived'::"text", 'librosa'::"text", 'deep_derived'::"text"])) AND ("job"."status" = 'failed'::"text"))) > 0) THEN 'failed'::"text"
            WHEN ("count"(*) FILTER (WHERE (("job"."stage" = ANY (ARRAY['analysis'::"text", 'derived'::"text", 'librosa'::"text", 'deep_derived'::"text"])) AND ("job"."status" = 'running'::"text"))) > 0) THEN 'running'::"text"
            ELSE 'pending'::"text"
        END AS "analysis_status"
   FROM ("public"."sample_s3_path" "asset"
     LEFT JOIN "public"."sample_analysis_jobs" "job" ON ((("job"."published_asset_id" = "asset"."id") AND ("job"."source_signature" = "asset"."source_signature"))))
  GROUP BY "asset"."id";



